use std::collections::{HashMap, HashSet};

/// A* shortest path from `start` to `goal`, guided by `heuristic`. Returns the node path
/// (inclusive of both ends) or `None` if `goal` is unreachable.
pub fn a_star(
    adj: &HashMap<String, Vec<(String, u32)>>,
    start: &str,
    goal: &str,
    heuristic: impl Fn(&str) -> u32,
) -> Option<Vec<String>> {
    let mut g_score: HashMap<String, u32> = HashMap::from([(start.to_string(), 0)]);
    let mut came_from: HashMap<String, String> = HashMap::new();
    let mut open: HashSet<String> = HashSet::from([start.to_string()]);
    while !open.is_empty() {
        let current = open
            .iter()
            .min_by_key(|n| {
                g_score.get(*n).copied().unwrap_or(u32::MAX).saturating_add(heuristic(n))
            })
            .cloned()
            .unwrap();
        if current == goal {
            let mut path = vec![current.clone()];
            let mut step = current;
            while let Some(prev) = came_from.get(&step) {
                path.push(prev.clone());
                step = prev.clone();
            }
            path.reverse();
            return Some(path);
        }
        open.remove(&current);
        let g_current = g_score.get(&current).copied().unwrap_or(u32::MAX);
        if let Some(neighbors) = adj.get(&current) {
            for (next, w) in neighbors {
                let tentative = g_current.saturating_add(*w);
                if tentative < g_score.get(next).copied().unwrap_or(u32::MAX) {
                    came_from.insert(next.clone(), current.clone());
                    g_score.insert(next.clone(), tentative);
                    open.insert(next.clone());
                }
            }
        }
    }
    None
}

// Accessible-interaction helpers (#3775, epic #2725) — make a styled non-button element (a `Box`, a
// row/card `<div>`) operable by keyboard, atomically. The whole point is that keyboard operability
// ships WITH the click, never separately: `clickable(onClick)` returns role + focusability + Enter/Space
// activation bundled with the click handler, so an element can never end up clickable-but-not-keyboard.
//
// A raw `onClick` on a `<div>`/`<span>` still trips the jsx-a11y guardrail (#3773) — that's deliberate:
// new interactive containers must come through here (or use a real Button/IconButton primitive).

import { useEffect } from "react";
import type { AriaRole, KeyboardEvent, MouseEvent, RefObject } from "react";

// Typed mouse-only to match the ordinary `onClick` handlers call sites already have (`(e: MouseEvent) =>
// void` or `() => void`); the keydown path casts, which is safe because activation handlers use the
// event only for `stopPropagation`/`preventDefault`, never mouse coordinates.
type Activate<T extends Element> = (e: MouseEvent<T>) => void;

/** An `onKeyDown` that fires `activate` on Enter/Space (preventing Space-scroll). Pair with a literal
 *  `role` + `tabIndex={0}` on an ALWAYS-interactive element (where a static role reads cleanly and
 *  other handlers — pointer capture, drag — sit alongside). For a CONDITIONALLY-interactive element,
 *  reach for [`clickable`] instead so the role/tabindex disappear when it's inert. */
export function onEnterOrSpace<T extends Element = HTMLElement>(activate: Activate<T>) {
  return (e: KeyboardEvent<T>) => {
    // MODIFIED presses are not activations (#4134). Without this, Shift+Enter (and Ctrl/Alt/Meta+Enter)
    // activated any focused `clickable()` element — every rail row, card and toggle built on this bundle —
    // and `preventDefault`ed a chord the user meant for something else. A real button behaves this way:
    // Shift+Enter on one does not click it.
    if (e.shiftKey || e.ctrlKey || e.altKey || e.metaKey) return;
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      activate(e as unknown as MouseEvent<T>);
    }
  };
}

/** The interactive-attribute bundle for a conditionally-clickable styled element: spread it on, and the
 *  element is a keyboard-operable button when `onClick` is set and fully inert (no role/tabindex/handler)
 *  when it isn't. Bundling is what makes it correct — role, focusability, click, and key-activation are
 *  all present or all absent, never a click without its keyboard equivalent. `opts.role` overrides the
 *  default `"button"` (e.g. `"switch"`, `"checkbox"`); `opts.label` sets an accessible name. */
export function clickable<T extends Element = HTMLElement>(
  onClick: Activate<T> | undefined,
  opts?: { role?: AriaRole; label?: string },
) {
  if (!onClick) return {} as const;
  return {
    role: opts?.role ?? "button",
    tabIndex: 0,
    "aria-label": opts?.label,
    onClick,
    onKeyDown: onEnterOrSpace<T>(onClick),
  };
}

// ── Modal focus management (#2725 Tier 0) ────────────────────────────────────────────────────────────

/** Elements that can hold focus, in DOM order. `:not([disabled])` and the negative-tabindex filter matter:
 *  a disabled button and a `tabIndex={-1}` container are both focusable-looking and both wrong to land on. */
const FOCUSABLE = [
  "a[href]", "button", "input", "select", "textarea",
  '[tabindex]:not([tabindex="-1"])',
].map((s) => `${s}:not([disabled]):not([aria-hidden="true"])`).join(",");

function focusableWithin(root: HTMLElement): HTMLElement[] {
  // Filtered on DECLARED hiddenness only — `hidden`, `aria-hidden`, `disabled` (in the selector above) —
  // never on layout.
  //
  // The textbook check is `offsetParent !== null`, and it is untestable here: jsdom has no layout, so
  // `offsetParent` is null for EVERY element and the filter silently returns an empty list. That is not a
  // hypothetical — it made all six focus tests fail on the first run, reporting "focus never moved" for a
  // trap that was working. The e2e harness cannot cover it either; it drives the preview srcdoc, not the
  // app shell.
  //
  // Little is lost: the browser already skips hidden elements during native Tab, and the trap only
  // intervenes at the two ends. A `display:none` element sitting exactly at an end would wrap to something
  // unfocusable — at which point the browser keeps focus where it is, which is still inside the modal.
  return Array.from(root.querySelectorAll<HTMLElement>(FOCUSABLE))
    .filter((el) => !el.hidden && el.getAttribute("aria-hidden") !== "true");
}

/**
 * Trap focus inside `ref` while `enabled`, and put it back where it came from on close.
 *
 * A modal that does not do this is not "slightly less polished" — it is unusable with a screen reader.
 * Focus stays on the trigger BEHIND the overlay, so the reader never enters the dialog and never says one
 * opened; Tab then walks out into the page underneath, which is visually covered and obviously not
 * interactive to everyone except the person who cannot see it.
 *
 * Lives on `ModalScrim` rather than `Dialog` because 7 modal surfaces render through the scrim, including
 * the custom-bodied ones that supply their own card — fixing `Dialog` alone would miss them.
 *
 * Deliberately NOT tied to `onDismiss`: a non-dismissable modal (a destructive op in flight) is exactly
 * the one you must not be able to Tab out of.
 */
export function useFocusTrap(ref: RefObject<HTMLElement | null>, enabled = true) {
  useEffect(() => {
    const root = ref.current;
    if (!enabled || !root) return;

    // Captured BEFORE we move focus, so close returns the user where they were rather than at the top of
    // the document. `body` is the fallback when focus was nowhere in particular.
    const restoreTo = document.activeElement as HTMLElement | null;

    const first = focusableWithin(root)[0];
    // Falls back to the container itself (it carries `tabIndex={-1}`) so a modal with no focusable content
    // — a spinner, a message — still moves the reader inside instead of leaving it behind the scrim.
    (first ?? root).focus();

    // `globalThis.KeyboardEvent`, NOT the React one this module already imports — a native listener gets
    // the DOM event, and the React synthetic type would typecheck while describing the wrong object.
    const onKeyDown = (e: globalThis.KeyboardEvent) => {
      if (e.key !== "Tab") return;
      const items = focusableWithin(root);
      if (items.length === 0) {
        // Nothing to cycle between: hold focus on the container rather than letting Tab escape.
        e.preventDefault();
        root.focus();
        return;
      }
      const firstItem = items[0];
      const lastItem = items[items.length - 1];
      const active = document.activeElement;
      // Wrap at each end. The `!root.contains(active)` case catches focus that has already escaped (a
      // programmatic focus elsewhere) and pulls it back rather than letting Tab continue outward.
      if (e.shiftKey && (active === firstItem || !root.contains(active))) {
        e.preventDefault();
        lastItem.focus();
      } else if (!e.shiftKey && (active === lastItem || !root.contains(active))) {
        e.preventDefault();
        firstItem.focus();
      }
    };

    root.addEventListener("keydown", onKeyDown);
    return () => {
      root.removeEventListener("keydown", onKeyDown);
      // Only restore if focus is still inside the closing modal. If something else has deliberately taken
      // focus (a toast, a newly opened second modal), stealing it back would be the bug.
      if (!root.contains(document.activeElement) && document.activeElement !== document.body) return;
      restoreTo?.focus?.();
    };
  }, [ref, enabled]);
}

// The unlock chime (#3939) — SYNTHESIZED, not sampled.
//
// The toast used to play a bundled `achievement-sound.mp3` that was almost certainly the Xbox cue.
// Generating the sound removes the provenance question entirely and drops a binary from the bundle:
// two short notes on a triangle wave with a quick exponential decay, which reads as a chime without
// imitating anyone's.
//
// Fail-safe by construction: no AudioContext (an old WebView, a test env) or a blocked autoplay policy
// simply produces no sound. The toast's visual never depends on it.

/** A rising two-note figure — a perfect fifth, which is the least imitative "something good happened". */
const NOTES: Array<{ hz: number; at: number; dur: number }> = [
  { hz: 784, at: 0, dur: 0.16 },     // G5
  { hz: 1175, at: 0.13, dur: 0.34 }, // D6
];

/** Play the unlock chime. Never throws, never rejects — audio is decoration here. */
export function playAchievementChime(volume = 0.22): void {
  try {
    const Ctor: typeof AudioContext | undefined =
      window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return;
    const ctx = new Ctor();
    const now = ctx.currentTime;
    for (const n of NOTES) {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "triangle";
      osc.frequency.value = n.hz;
      // A quick attack and an exponential decay — a flat envelope would click on start and stop.
      gain.gain.setValueAtTime(0.0001, now + n.at);
      gain.gain.exponentialRampToValueAtTime(volume, now + n.at + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + n.at + n.dur);
      osc.connect(gain).connect(ctx.destination);
      osc.start(now + n.at);
      osc.stop(now + n.at + n.dur + 0.02);
    }
    // Release the hardware once the figure has finished; leaking contexts eventually stops playback.
    window.setTimeout(() => void ctx.close().catch(() => {}), 1200);
  } catch {
    // No audio is fine — the toast is visual first.
  }
}

// Per-agent execution flow (#297): how a planned stream behaves at runtime —
// whether it pauses for confirmation or runs continuously, and what/when it
// pushes to GitHub. Set in the planning phase, the flow drives three launch-time
// concerns: which git/gh writes auto-approve (permissions), how the kickoff's
// autonomy + push paragraph reads, and whether the agent emits a coordination
// wake at its pause points.
//
// Pure (no React/Tauri) so it can be unit-tested and shared by the planner UI,
// the tag/fleet.json parsers, and the launch path.

/** How the agent handles underspecified decisions. */
export type FlowAutonomy = "continuous" | "checkpoint" | "confirm";
/** What and whether the agent pushes to GitHub. */
export type FlowPush = "local" | "auto-pr" | "self-merge" | "push-confirm" | "commit-only" | "none";
/** Which event fires a push attempt. */
export type FlowTrigger = "per-issue" | "per-stage" | "on-green";
/** How a "confirm"/"push-confirm" pause is enforced. */
export type FlowGate = "soft" | "hard";

export interface AgentFlow {
  /** continuous = never pause; checkpoint = pause at stage/PR boundaries; confirm = ask before non-trivial decisions. */
  autonomy: FlowAutonomy;
  /** local = commit on the branch and STOP; nothing ever reaches a remote and the integration stream
   *  merges locally (the default); auto-pr = commit+push+open PR on green; self-merge = run full gate,
   *  rebase onto develop, re-gate, push develop directly (no PR); push-confirm = commit+test then wait;
   *  commit-only = commit, don't push — someone else pushes the branch and opens the PR; none = no git/gh. */
  push: FlowPush;
  /** When a push fires: per owned issue, per pipeline stage, or whenever the gate is green. */
  trigger: FlowTrigger;
  /** soft = kickoff instructs the agent to pause and ask; hard = the push command isn't auto-approved so the pane prompts. */
  gate: FlowGate;
}

export const FLOW_AUTONOMY: readonly FlowAutonomy[] = ["continuous", "checkpoint", "confirm"];
export const FLOW_PUSH: readonly FlowPush[] = ["local", "auto-pr", "self-merge", "push-confirm", "commit-only", "none"];

/** The push policies that never reach a remote — no `git push`, no `gh pr create`, under any gate.
 *  Exported so the "nothing escapes locally" guarantee is asserted from ONE list rather than
 *  re-enumerated at each call site (a new policy added without a decision here fails that test). */
export const LOCAL_ONLY_PUSH: readonly FlowPush[] = ["local", "commit-only", "none"];
export const FLOW_TRIGGER: readonly FlowTrigger[] = ["per-issue", "per-stage", "on-green"];
export const FLOW_GATE: readonly FlowGate[] = ["soft", "hard"];

/** The default flow a freshly-planned stream gets (confirmed with the user).
 *
 *  `push` is `local` and that is load-bearing, not a preference: this is the fallback
 *  {@link resolveFlow} applies when a stream carries NO flow at all, so it is what governs a
 *  launch that never went near the strategy layer. It was `auto-pr` — which meant a fleet
 *  launched with untouched defaults pushed branches and opened PRs regardless of intent. */
export const DEFAULT_FLOW: AgentFlow = {
  autonomy: "continuous",
  push: "local",
  trigger: "per-issue",
  gate: "hard",
};

/** Coerce one raw value to a member of `allowed`, falling back when absent/invalid. */
function coerce<T extends string>(raw: unknown, allowed: readonly T[], fallback: T): T {
  if (typeof raw !== "string") return fallback;
  const v = raw.trim().toLowerCase();
  return (allowed as readonly string[]).includes(v) ? (v as T) : fallback;
}

/**
 * Build a complete, valid {@link AgentFlow} from arbitrary/partial input (a tag's
 * attributes or a `fleet.json` object). Every field falls back to {@link DEFAULT_FLOW},
 * so the result is always launch-safe. Unknown keys are ignored.
 */
export function normalizeFlow(input: Record<string, unknown> | null | undefined): AgentFlow {
  const o = input ?? {};
  return {
    autonomy: coerce(o.autonomy, FLOW_AUTONOMY, DEFAULT_FLOW.autonomy),
    push:     coerce(o.push,     FLOW_PUSH,     DEFAULT_FLOW.push),
    trigger:  coerce(o.trigger,  FLOW_TRIGGER,  DEFAULT_FLOW.trigger),
    gate:     coerce(o.gate,     FLOW_GATE,     DEFAULT_FLOW.gate),
  };
}

/**
 * Like {@link normalizeFlow} but returns `undefined` when the input names none of
 * the four flow fields — so a stream that never specified a flow stays `flow:
 * undefined` (the launch path applies {@link DEFAULT_FLOW}) instead of being
 * silently materialized. Preserves backward-compat for pre-flow plans.
 */
export function flowOrUndefined(input: Record<string, unknown> | null | undefined): AgentFlow | undefined {
  const o = input ?? {};
  const named = ["autonomy", "push", "trigger", "gate"].some(
    (k) => typeof o[k] === "string" && (o[k] as string).trim() !== "",
  );
  return named ? normalizeFlow(o) : undefined;
}

/** The effective flow for a stream, applying {@link DEFAULT_FLOW} when unset. */
export function resolveFlow(flow: AgentFlow | undefined): AgentFlow {
  return flow ?? DEFAULT_FLOW;
}

// Agent-health watchdog (#2541) — the piece that GENERATES the Glance "warning" from live agent state,
// not from a crash. A `bsc-wait` (an EXPECTED pause for the user) is calm while it's fresh — the project
// reads activity "waiting". But once a wait OVERSTAYS its welcome (no instructions for N minutes), it's a
// stall the user should be pulled to: it escalates the project to health "warning" (orange dot) with a
// duration reason ("<note> · Nm"), which the existing dot+reason pipeline renders for free.
//
// Deliberately NOT routed through errordb / the fault-triage fix loop (#2265): a "no instructions" stall
// needs the USER to act, not a fix dispatched to the director. It's an ephemeral, derived health overlay
// (like liveness, #2263) — it clears the instant the agent resumes. Pure; `now` is injected for testing.
import type { ProjectLite } from "@/features/glance/lib/glanceData";
import type { GHealth, GActivity, GRawNode } from "@/features/glance/lib/glanceGraph";
import { fleetPaneId } from "@/app/console/lib/paneIdentity";

/** A `bsc-wait` parked longer than this escalates from the calm "waiting" activity to an orange
 *  "warning" health. 10 min — long enough that a normal think/confirm pause stays calm. Overridable per
 *  call so a Settings field can drive it later (#2541 follow-up). */
export const STALL_WARN_MS = 10 * 60_000;

/** The minimal waiting-session shape the watchdog reads — a projection of `CoordState.waiting`. */
export interface WaitLite { session: string; reason: string; at: number }

/** The project (plan) key that owns a session/pane id — everything before the first ':' (pane ids are
 *  `<key>:<stream>` / `<key>:director` / `<key>:<repo>:triage`, all prefixed by the plan key, #2409). */
export function projectKeyOfSession(session: string): string {
  const i = session.indexOf(":");
  return i < 0 ? session : session.slice(0, i);
}

/**
 * Keep only the waits whose session still EXISTS (#3429) — the liveness guard the L0 watchdog was missing.
 *
 * `CoordState.waiting` is a replay of the coord log: an entry is cleared only by a LATER event from that
 * same session, and killing a pane emits none. So a wait parked by a long-dead agent stayed outstanding
 * forever while `now - w.at` only grew, pinning its project orange permanently — a `warning` that no longer
 * described anything. A session that no longer exists cannot be waiting on the user.
 *
 * `livePaneIds` is the same pruned set the L1 overlay reads (tab membership minus ended/disabled panes), so
 * both layers decide "does this session exist?" from one signal. Pure.
 */
export function liveWaits(waiting: WaitLite[], livePaneIds: ReadonlySet<string>): WaitLite[] {
  return waiting.filter((w) => livePaneIds.has(w.session));
}

const worse = (a: GHealth, b: GHealth): boolean => a === "error" && b !== "error";

/**
 * Escalate PARKED agents onto the Glance node axes (#2541 watchdog). Per project the OLDEST outstanding
 * `bsc-wait` decides: while it's under `warnMs` the project reads a calm activity "waiting"; once it
 * exceeds `warnMs` it escalates to health "warning" with a "<note> · Nm" reason. Only ever ESCALATES
 * health (never downgrades an already-worse state). Pure.
 *
 * Apply BEFORE the errordb fault overlay (`applyFaultHealth`) so a real error still beats a stall.
 */
export function applyStallHealth(projects: ProjectLite[], waiting: WaitLite[], now: number, warnMs = STALL_WARN_MS): ProjectLite[] {
  if (waiting.length === 0) return projects;
  const oldest = new Map<string, WaitLite>();
  for (const w of waiting) {
    const key = projectKeyOfSession(w.session);
    const prev = oldest.get(key);
    if (!prev || w.at < prev.at) oldest.set(key, w);
  }
  return projects.map((p) => {
    const w = oldest.get(p.id);
    if (!w) return p;
    const elapsed = now - w.at;
    if (elapsed < warnMs) return { ...p, activity: "waiting" }; // fresh, expected pause — stays calm
    const minutes = Math.max(1, Math.floor(elapsed / 60_000));
    const note = w.reason?.trim() || "no instructions";
    const health: GHealth = worse(p.health ?? "healthy", "warning") ? (p.health as GHealth) : "warning";
    return { ...p, activity: "waiting", health, reason: `${note} · ${minutes}m` };
  });
}

/** The live signals a fleet-drill (L1) node reads to lift off its planned rest state (#3252). All keyed by
 *  the node's PANE id (`fleetPaneId` → `<project>:<stream>` / `<project>:director`). */
export interface FleetLiveSignals {
  /** Launched-tab membership — the session cell exists + is openable (`livePaneIds`). */
  livePaneIds: ReadonlySet<string>;
  /** Per-pane run status — `"run"` while the session is actively working (the console's aggregate state). */
  paneStatus: Record<string, string>;
  /** Parked `bsc-wait` sessions (from `CoordState.waiting`). */
  waiting: WaitLite[];
  /** Panes STOPPED at a permission prompt / input wait (#4005) — Claude Code's `Notification` hook,
   *  recorded as `bsc-activity attn` and read back from `bsc logs pane-activity`. Keyed by pane id.
   *  Nothing else in the app could see this state: such a pane is not `run` and has no `bsc-wait`, so
   *  it fell through to plain `idle` and looked identical to a session that had simply finished. */
  attention?: ReadonlySet<string>;
  /** Sessions PARKED IN MAINTENANCE (#4010) — `bsc-maintain` (#1957): every owned issue is done, the
   *  worker stays alive and ready for the director to dispatch into. Keyed by pane id.
   *
   *  Modelled explicitly rather than left to fall through to `idle`, because a parked session's TUI is
   *  still alive: whether it reads `run` is a timing accident, and on the wrong side of that accident a
   *  finished worker keeps the building outline forever. */
  maintaining?: ReadonlySet<string>;
  /** Panes the auto-end marked FINISHED (#4027) — `bsc-done` → `endedPanes`, valued by the verdict
   *  plan.db gave (`done` / `needs-attention` / `blocked`), not the worker's say-so. Keyed by pane id.
   *
   *  Needed here because `livePaneIds` EXCLUDES ended panes, so without this an ended worker falls
   *  through to `off` — indistinguishable from one that never launched. */
  ended?: Record<string, { state: string }>;
  /** Epoch now — injected (impure in render). */
  now: number;
  /** Stall threshold; a wait beyond it escalates to `warning`. Defaults to {@link STALL_WARN_MS}. */
  warnMs?: number;
  /** QUARANTINED panes (#3916) — the warden hard-paused these: it killed the PTY and marked why. Keyed
   *  by pane id, valued by the summary the warden recorded. Until now quarantine was invisible in Glance
   *  (grep found no handling outside `resumeProject`'s comments), so a hard-paused worker read as a plain
   *  `off` node — indistinguishable from one that was simply never launched. */
  quarantined?: Record<string, { summary?: string }>;
  /** HELD streams (#3931) — the dependency gate refused to start these because an upstream has not
   *  landed. Keyed by STREAM id (not pane id: there is no pane, that is the point). Same argument as
   *  quarantine: a held stream has no session, so it fell through to a plain `off` node and was
   *  indistinguishable from one that was never planned — the user could not tell "waiting its turn"
   *  from "broken". A `deadlocked` stream is an ERROR (it can never start on its own); an ordinary
   *  held one stays `off` but now carries the reason that explains itself. */
  held?: Record<string, { reason: string; deadlocked: boolean }>;
}

/**
 * Overlay the LIVE session state onto a project's fleet-drill (L1) agent nodes (#3252, the #2541 axes) —
 * the agent twin of the L0 {@link applyStallHealth}. Each node is keyed by its pane id
 * `fleetPaneId(projectKey, node.id)`, and its OWN health/activity is set from what its session is doing NOW:
 *
 *   - not launched (NO session exists)           → off · idle
 *   - launched + running (`paneStatus === "run"`) → healthy · building
 *   - launched + parked on a fresh `bsc-wait`    → healthy · waiting
 *   - that wait overstayed `warnMs`              → warning · waiting (reason "<note> · Nm")
 *   - launched but quiet (between prompts)       → idle · idle  (it EXISTS but is not working)
 *
 * The `preview` node (not an agent) is left untouched. The director gets the same treatment via
 * `<project>:director`, so it finally moves off idle. Pure — apply to `rawNodes` BEFORE `buildGraph` so the
 * dependency rollup + inherited-health recompute over the live values.
 */
export function applyFleetLiveStatus(nodes: GRawNode[], projectKey: string, sig: FleetLiveSignals): GRawNode[] {
  const warnMs = sig.warnMs ?? STALL_WARN_MS;
  const waitByPane = new Map(sig.waiting.map((w) => [w.session, w] as const));
  return nodes.map((n) => {
    if (n.preview) return n; // not an agent — its own healthy/live state stands
    const paneId = fleetPaneId(projectKey, n.id);
    // FINISHED BY THE PLAN (#4124) — every issue this node owns is done.
    //
    // Completion was derived ONLY from runtime session signals: an `ended` verdict of `done`, or an
    // explicit maintenance park. Both are ephemeral — they describe a session, and a session ends. The
    // issues do not: a worker that finished its lane last week still finished it, whether or not
    // anything is running now. So the two QUIET branches below (no session / live but idle) read this
    // first, and a node whose work is done stops reporting `idle`, which is what a node with nothing to
    // do also reports. Live-WORKING and blocked-on-a-person states still outrank it: what a session is
    // doing right now is the more urgent fact, and a worker parked on a question is still parked.
    // Two sources, because neither is complete alone. The PLAN says every owned issue is closed. A
    // `maintain` record says the worker itself declared it finished and stood by (#1957) — durable
    // evidence it got there, and for a fleet whose plan.db carries no issue rows it is the ONLY
    // evidence. Measured: 34 panes have emitted `maintain`.
    const finished =
      (!!n.progress && n.progress.total > 0 && n.progress.done >= n.progress.total) ||
      !!sig.maintaining?.has(paneId);
    const asFinished = (reason: string) =>
      ({ ...n, health: "complete" as GHealth, activity: "complete" as GActivity, reason });
    // QUARANTINE FIRST (#3916): the warden kills the PTY when it quarantines, so a quarantined pane is
    // never in `livePaneIds` and would otherwise fall through to `off` — reading as "never launched"
    // rather than "hard-paused, here is why". It must outrank every other state: this is the one the
    // user has to act on, and Resume deliberately refuses to relaunch it.
    const q = sig.quarantined?.[paneId];
    if (q) {
      return {
        ...n,
        health: "error" as GHealth,
        activity: "idle" as GActivity,
        reason: q.summary?.trim() || "quarantined by the warden",
      };
    }
    // HELD BY THE DEPENDENCY GATE (#3931) — checked before the plain `off` fall-through for exactly the
    // reason quarantine is: a held stream has no pane, so it would render as an anonymous dark node and
    // the user would have no way to tell "waiting on its upstream" from "never planned". A DEADLOCK is
    // an error the user must fix (the plan's `dependsOn` has a cycle, so it can never start on its own);
    // an ordinary hold is not a fault, so it keeps `off` health and just explains itself.
    const h = sig.held?.[n.id];
    if (h && !sig.livePaneIds.has(paneId)) {
      return {
        ...n,
        health: (h.deadlocked ? "error" : "off") as GHealth,
        activity: "waiting" as GActivity,
        reason: h.reason,
      };
    }
    // FINISHED (#4027) — above the `off` fall-through on purpose, and for the same reason quarantine
    // and held are: `livePaneIds` excludes ended panes, so a worker that completed every issue it owned
    // would render as `off` — exactly what a NEVER-LAUNCHED node looks like. The one state that has
    // earned a distinct reading would be the one state that loses it.
    //
    // Only a `done` verdict reads complete. `needs-attention` / `blocked` are endings too, but they are
    // endings that want a person — they keep falling through to the states that say so.
    const endState = sig.ended?.[paneId]?.state;
    if (endState === "done") {
      return { ...n, health: "complete" as GHealth, activity: "complete" as GActivity, reason: "every owned issue complete" };
    }

    // NOT LAUNCHED — there is no session behind this node. That is `off`, not `idle`: the two states
    // were indistinguishable while both rendered idle, so a node with no session read as one that was
    // merely quiet, and its empty log view looked like a broken log rather than an absent session.
    // `off` = no session exists · `idle` = a session exists but is not working · `healthy` = working.
    if (!sig.livePaneIds.has(paneId)) {
      // #4124: `off` is "never launched". A worker that finished everything and whose session has since
      // been reclaimed is not that, and rendering it identically loses the one state that was earned.
      return finished
        ? asFinished("every owned issue complete — no session running")
        : { ...n, health: "off" as GHealth, activity: "idle" as GActivity };
    }
    // BLOCKED ON A PERSON (#4005) — a `bsc-wait` park, or a session stopped at a permission prompt.
    //
    // A wait used to read `healthy` (green, calm) for ten minutes and only then flip to `warning`.
    // Both readings were wrong in the same way: green says "nothing to do" about a session that is
    // waiting on YOU, and orange says "something is degrading" about a normal hand-off. It is neither
    // — it is a request, so it gets its own health. The elapsed-time note is kept, because how long it
    // has been waiting is still worth knowing; it is just no longer the thing that makes it visible.
    const wait = waitByPane.get(paneId);
    if (wait) {
      const elapsed = sig.now - wait.at;
      const note = wait.reason?.trim() || "no instructions";
      const minutes = Math.max(1, Math.floor(elapsed / 60_000));
      const reason = elapsed >= warnMs ? `${note} · ${minutes}m` : note;
      // #4046 — `healthy` health, `waiting` activity. Nothing is WRONG with a worker parked on a
      // question; it is doing a thing called waiting. The reason string still says what it waits on.
      return { ...n, health: "healthy" as GHealth, activity: "waiting" as GActivity, reason };
    }
    if (sig.attention?.has(paneId)) {
      return {
        ...n,
        health: "healthy" as GHealth,
        activity: "waiting" as GActivity,
        reason: "stopped for you — permission prompt or awaiting input",
      };
    }
    // PARKED IN MAINTENANCE (#4010) — before the run->building branch, deliberately. A maintaining
    // worker's session is still alive, so `paneStatus` may well read "run"; checked after, it would
    // keep the building outline forever despite having finished everything it owns.
    //
    // It stays BELOW the wait/attention branches: a park needs a person, standing-by does not. The
    // RECLAIMED case (session gone) is handled at the liveness gate instead, via `finished` — putting
    // this whole branch above that gate would have let maintenance outrank a `bsc-wait`.
    //
    // It renders as the PLAIN node — no outline, no pulse — because there is nothing for anyone to do
    // about it. The explanation rides in `reason`, which the hover title and the inspector's REASON
    // tile both show, so the state is still discoverable without being loud.
    if (sig.maintaining?.has(paneId)) {
      // #4027: `complete`, not `idle`. A worker standing by having finished everything it owns and one
      // that happens to be quiet are different facts, and they used to render as the same word.
      return { ...n, health: "complete" as GHealth, activity: "complete" as GActivity, reason: "maintenance — owned issues complete, standing by for dispatch" };
    }
    if (sig.paneStatus[paneId] === "run") return { ...n, health: "healthy" as GHealth, activity: "building" as GActivity };
    // Launched, but not working: the session EXISTS and is quiet ⇒ `idle` on both axes. It used to read
    // `healthy` here ("subtly live"), which collided with a genuinely working session — and left `idle`
    // free to be misread as the no-session state. Health now tracks existence + work, not mere launch.
    // #4042 — `healthy`, not `idle`: the session EXISTS and nothing is wrong, which is what healthy
    // means. The activity word still says `idle`, so "at rest" is not lost — the two axes just stop
    // saying the same thing twice.
    // #4124: a live session with nothing left to do is COMPLETE, not merely quiet. `idle` is the word
    // for "a session exists and is not working", which is true here but is the least of what is true.
    return finished
      ? asFinished("every owned issue complete")
      : { ...n, health: "healthy" as GHealth, activity: "idle" as GActivity };
  });
}

import type { ConsoleProvider, ProviderLaunchConfig } from "@/app/console/lib/providers/types";
import type { FirstRunInstall } from "@/app/console/lib/providers/providers/claudeInstall";
import { aiderModelArg } from "@/shared/lib/core/llmConfig";

// Aider — a first-class console provider (#1172). Unlike Claude Code / bsc-agent (which bake the
// prompt and read config from the backend harness), Aider is a plain CLI launched via its own
// init command, so ALL of its configuration — model, task, fleet-safe git, worker context — is
// composed into the launch command here (the matching API-key env comes from `aiderEnv`, wired in
// sessionLaunch.buildAgentEnv).

/** Aider is a Python CLI installed from PyPI (`pip install aider-chat`) — not bundled (like `gh`) and
 *  not an npm package (like Claude Code). We DETECT it and, on first run, guide/offer the pip install
 *  rather than shipping it. The descriptor is provider-agnostic (a free-form `command`), so the pip
 *  invocation reuses the same {@link FirstRunInstall} shape the Claude CLI first-run flow consumes. */
export const aiderFirstRunInstall: FirstRunInstall = {
  pkg: "aider-chat",
  command: "python -m pip install aider-chat",
  docsUrl: "https://aider.chat/docs/install.html",
};

/** POSIX single-quote a shell argument (wrap in '…', escaping embedded quotes). Newlines survive
 *  inside single quotes, so a multi-line kickoff passes through `--message` intact. */
function shQuote(s: string): string {
  return `'${s.replace(/'/g, `'\\''`)}'`;
}

/**
 * Build Aider's launch command from the pane's resolved config (#1172) — first-class parity with the
 * sibling providers:
 *  - **LLM config** → `--model <aiderModelArg>` (the matching API-key env is injected separately by
 *    `aiderEnv`). When no `llm` is supplied, a bare `model` string is honored; with neither, Aider
 *    falls back to its own default.
 *  - **Fleet-safe git** → ALWAYS `--no-auto-commits --no-dirty-commits`. Aider auto-commits after
 *    every successful edit (and commits pre-existing dirty changes) by default, which fights the
 *    fleet's worktree/branch flow — the worker opens a PR, the director merges (#1948). Disabling
 *    both keeps commits/PRs owned by the app's per-agent flow (#297). Aider never auto-pushes, so no
 *    push flag is needed; the fleet's push policy stays the sole authority over `git push`.
 *  - **Worker context** → `--read <file>` loads the plan scope read-only (Aider does no ancestor-
 *    `CLAUDE.md` walk, so a worker's `CLAUDE.local.md` must be handed to it explicitly).
 *  - **Task delivery** → `--message <prompt>` submits the kickoff, the analogue of Claude's baked
 *    initial message. NOTE: `--message` is one-shot — Aider processes the reply then exits — the
 *    closest flag Aider offers for delivering a startup task.
 */
export function buildAiderCommand(config?: ProviderLaunchConfig): string {
  // Fleet-safe git by DEFAULT — every Aider session (manual or fleet) starts with auto-commit off so
  // it never makes a surprise commit on the pane's branch.
  const parts = ["aider", "--no-auto-commits", "--no-dirty-commits"];
  const model = config?.llm ? aiderModelArg(config.llm) : config?.model;
  if (model && model.trim()) parts.push("--model", shQuote(model));
  for (const f of config?.readFiles ?? []) parts.push("--read", shQuote(f));
  const prompt = config?.startupPrompt;
  if (prompt && prompt.trim()) parts.push("--message", shQuote(prompt));
  return parts.join(" ");
}

export const aiderProvider: ConsoleProvider = {
  id: "aider",
  displayName: "Aider",
  buildLaunchCmd: buildAiderCommand,
  prereqProbe: "which aider",
  firstRunInstall: aiderFirstRunInstall,
  // Surfaced in the pane menu (#1172): Aider has no Claude-Code-style permission gate and no MCP, so
  // the role gate / write-scope hooks and MCP assignment don't apply, and it emits none of the OSC
  // status / transcript signals the app uses for run-idle + cost accounting.
  limitations: [
    "No permission gate — the role gate & write-scope hooks don't apply.",
    "No MCP support.",
    "Limited status/cost telemetry (no run/idle or token signals).",
  ],
};

// Alert hub (#2498) — the one place alert candidates from every source (the coord pump, the
// focus queue, the planner's gate/turn transitions) converge. Folds them into the capped
// rolling inbox (pure model: alerts.ts), publishes the inbox as the `alerts` store_state
// domain, and fires one FCM push per FRESH alert via the thin `tunnel_emit_alert` command —
// so a backgrounded/quit phone is notified even while off the relay.
//
// The hub is a factory (`createAlertHub`) so the fold→publish→push flow is testable with
// injected transports; the app-wide instance below binds the real publisher + push command.

import { foldAlerts, alertPushFields, type AlertEvent } from "@/features/tunnel/lib/alerts";
import { buildAlertsPayload } from "@/features/tunnel/lib/storeProjections";
import { publishTunnelDomain } from "@/features/tunnel/lib/tunnelDomains";
import { tunnelEmitAlert } from "@/features/tunnel/lib/tunnelClient";
import { log } from "@/shared/lib/core/log";

export interface AlertHub {
  /** Fold candidates into the inbox; publish + push whatever is genuinely new. */
  record(candidates: ReadonlyArray<AlertEvent>): void;
  /** Fold + publish WITHOUT pushing — for the first coord-log read after the relay starts,
   *  so the historical log seeds the mobile inbox without firing a burst of stale FCM
   *  notifications. Everything folded here is known, so a later `record` won't push it. */
  seed(candidates: ReadonlyArray<AlertEvent>): void;
  /** The current inbox (newest last). Exposed for tests/diagnostics. */
  inbox(): ReadonlyArray<AlertEvent>;
}

export function createAlertHub(deps: {
  publish: (payload: unknown) => void;
  push: (alert: AlertEvent, title: string, body: string) => Promise<void>;
  onError?: (err: unknown) => void;
}): AlertHub {
  let inbox: ReadonlyArray<AlertEvent> = [];
  const onError = deps.onError ?? (() => {});
  const fold = (candidates: ReadonlyArray<AlertEvent>, push: boolean): void => {
    const { inbox: next, fresh } = foldAlerts(inbox, candidates);
    if (fresh.length === 0) return;
    inbox = next;
    deps.publish(buildAlertsPayload(inbox));
    if (!push) return;
    for (const a of fresh) {
      const { title, body } = alertPushFields(a);
      deps.push(a, title, body).catch(onError);
    }
  };
  return {
    record: (candidates) => fold(candidates, true),
    seed: (candidates) => fold(candidates, false),
    inbox: () => inbox,
  };
}

const hub = createAlertHub({
  publish: (payload) => publishTunnelDomain("alerts", payload),
  push: (a, title, body) => tunnelEmitAlert(a.kind, title, body, a.paneId ?? null, a.at),
  onError: (e) => log.error(`tunnel: alert push failed: ${e}`),
});

/** Record alert candidates on the app-wide hub. Callers gate on the tunnel being live —
 *  alerts are a mobile-companion feature (the desktop has its own inbox surfaces). */
export function recordTunnelAlerts(candidates: ReadonlyArray<AlertEvent>): void {
  hub.record(candidates);
}

/** Seed the app-wide hub without pushing (the first coord-log read — see {@link AlertHub.seed}). */
export function seedTunnelAlerts(candidates: ReadonlyArray<AlertEvent>): void {
  hub.seed(candidates);
}

// Alert taxonomy (#2498) — ONE event model for everything that should reach the user's phone:
// the push-worthy moments of a running fleet/planner, derived from the SAME sources the desktop
// surfaces them from (the coordination pump's CoordState, the focus queue's awaiting set, the
// planner's gate/turn transitions). Pure — no React/Tauri — so the derivation, dedup, and the
// capped rolling inbox are unit-testable. The inbox rides the `alerts` store_state domain; each
// FRESH alert additionally fires an FCM push (see alertHub.ts / tunnel_emit_alert).

import type { CoordState } from "@/shared/lib/fleet/coordination";

/** The alert vocabulary (#2498). Fixed — mobile switches its notification routing on it. */
export type AlertKind =
  | "agent-paused"     // bsc-wait: an agent parked itself for the user (#297)
  | "prompt-waiting"   // a console pane flipped to awaiting-input (the user_request moment)
  | "worker-question"  // bsc-ask: a worker asked the director a question (#369)
  | "fleet-failed"     // a dep/issue latch FAILED — a stalled chain needing attention
  | "fleet-landed"     // a dep/issue latch satisfied (landed/merged/closed)
  | "gate-ready"       // the active plan stage's gate passed — awaiting the USER's confirm
  | "planner-waiting"; // the planner finished a turn and is waiting on the user

/** One alert. `id` is the stable dedup key — derivation is idempotent per source event. */
export interface AlertEvent {
  id: string;
  kind: AlertKind;
  /** The pane/session the alert is about, when it has one. */
  paneId?: string;
  /** The owning project key, when known. */
  project?: string;
  /** Short human-facing line (also the push body). */
  text: string;
  /** Epoch ms. */
  at: number;
}

/** Rolling-inbox cap: the newest N alerts are kept. */
export const ALERT_INBOX_CAP = 100;

const truncate = (s: string, max = 140): string => {
  const collapsed = s.split(/\s+/).join(" ").trim();
  return collapsed.length > max ? `${collapsed.slice(0, max - 1)}…` : collapsed;
};

// ── Coord-log sources ────────────────────────────────────────────────────────────
// CoordState entries carry their own `at` from the log line, so the derived ids are stable
// across polls — re-deriving from the same log yields the same alerts and foldAlerts dedups.

/** Derive the coord-sourced alert candidates from a replayed {@link CoordState}. */
export function coordAlerts(state: CoordState): AlertEvent[] {
  const out: AlertEvent[] = [];
  for (const w of state.waiting) {
    out.push({
      id: `agent-paused:${w.session}:${w.at}`,
      kind: "agent-paused",
      paneId: w.session,
      text: w.reason ? truncate(w.reason) : `${w.session} paused and is waiting for you.`,
      at: w.at,
    });
  }
  for (const a of state.asking) {
    out.push({
      id: `worker-question:${a.session}:${a.at}`,
      kind: "worker-question",
      paneId: a.session,
      text: truncate(a.question || `${a.session} asked the director a question.`),
      at: a.at,
    });
  }
  for (const [ref, latch] of Object.entries(state.latches)) {
    if (latch.state === "failed") {
      out.push({
        id: `fleet-failed:${ref}:${latch.at}`,
        kind: "fleet-failed",
        text: truncate(`${ref} failed${latch.reason ? `: ${latch.reason}` : ""}`),
        at: latch.at,
      });
    } else {
      out.push({
        id: `fleet-landed:${ref}:${latch.at}`,
        kind: "fleet-landed",
        text: `${ref} ${latch.source}`,
        at: latch.at,
      });
    }
  }
  return out;
}

// ── Transition sources ───────────────────────────────────────────────────────────
// These have no durable log to key off, so a NEW alert is an entry present now but not in the
// previous snapshot; `now` stamps it. A pane that resolves and awaits again re-alerts.

/** One awaiting console pane (from the focus queue, resolved to its identity id). */
export interface AwaitingPane {
  paneId: string;
  name: string;
}

/** Derive prompt-waiting alerts for panes that JUST entered the awaiting set. */
export function promptAlerts(
  prev: ReadonlyArray<AwaitingPane>,
  next: ReadonlyArray<AwaitingPane>,
  now: number,
): AlertEvent[] {
  const seen = new Set(prev.map((p) => p.paneId));
  return next
    .filter((p) => !seen.has(p.paneId))
    .map((p) => ({
      id: `prompt-waiting:${p.paneId}:${now}`,
      kind: "prompt-waiting" as const,
      paneId: p.paneId,
      text: `${p.name} is waiting for your input.`,
      at: now,
    }));
}

/** A gate-ready alert for a stage whose gate JUST passed (false→true per stage). */
export function gateReadyAlert(
  project: string,
  stage: string,
  now: number,
): AlertEvent {
  return {
    id: `gate-ready:${project}:${stage}:${now}`,
    kind: "gate-ready",
    project,
    text: `Stage "${stage}" gate passed — awaiting your confirm.`,
    at: now,
  };
}

/** A planner-waiting alert: the planner finished a turn (its newest transcript message is an
 *  assistant turn) and is waiting on the user. Keyed by the message timestamp, so the same turn
 *  never re-alerts. */
export function plannerWaitingAlert(
  project: string,
  paneId: string,
  lastText: string,
  at: number,
): AlertEvent {
  return {
    id: `planner-waiting:${paneId}:${at}`,
    kind: "planner-waiting",
    paneId,
    project,
    text: truncate(lastText) || "The planner is waiting for you.",
    at,
  };
}

// ── The rolling inbox ────────────────────────────────────────────────────────────

/** Fold candidate alerts into the inbox: candidates whose `id` is already present are dropped,
 *  the rest append in `at` order, and the inbox keeps only the newest {@link ALERT_INBOX_CAP}.
 *  Returns the (possibly unchanged — same reference) inbox plus the FRESH alerts to push. */
export function foldAlerts(
  inbox: ReadonlyArray<AlertEvent>,
  candidates: ReadonlyArray<AlertEvent>,
): { inbox: ReadonlyArray<AlertEvent>; fresh: AlertEvent[] } {
  const known = new Set(inbox.map((a) => a.id));
  const fresh = candidates.filter((a) => !known.has(a.id));
  // Dedup WITHIN the batch too (two sources could mint the same id in one tick).
  const uniqueFresh: AlertEvent[] = [];
  const batch = new Set<string>();
  for (const a of fresh) {
    if (batch.has(a.id)) continue;
    batch.add(a.id);
    uniqueFresh.push(a);
  }
  if (uniqueFresh.length === 0) return { inbox, fresh: [] };
  uniqueFresh.sort((a, b) => a.at - b.at);
  const next = [...inbox, ...uniqueFresh];
  return { inbox: next.slice(Math.max(0, next.length - ALERT_INBOX_CAP)), fresh: uniqueFresh };
}

/** The FCM banner fields for one alert (title per kind; body = the alert text). Pure so the
 *  push contract is pinned by tests. */
export function alertPushFields(a: AlertEvent): { title: string; body: string } {
  const titles: Record<AlertKind, string> = {
    "agent-paused": "Agent paused",
    "prompt-waiting": "Agent awaiting input",
    "worker-question": "Worker question",
    "fleet-failed": "Fleet: dependency failed",
    "fleet-landed": "Fleet: landed",
    "gate-ready": "Plan stage ready",
    "planner-waiting": "Planner waiting",
  };
  const who = a.paneId ?? a.project;
  return {
    title: who ? `${titles[a.kind]} — ${who}` : titles[a.kind],
    body: a.text,
  };
}

// The `algo-viz` kit's MOTION library as DATA (#2942/#3194, epic #3171) — the compare / swap / set /
// sorted (+ the search pair probe / found, #3220) animations authored as {@link KitAnimation} data,
// compiled by the kit-motion engine
// (`compileAnimationsCss`), NOT as hand-written CSS `@keyframes`. This is the epic's core vision: motion
// is data, so it's editable in the Designer's Animations menu instead of baked into a renderer's
// stylesheet.
//
// ── WHY THIS LIVES IN shared/ui/kit (not in either feature) ──────────────────────────────────────────
// It has EXACTLY TWO consumers, in two different features, and must be ONE definition (change `swap` once
// → every array visualization AND the Design-Studio kit shelf update in lockstep):
//   1. the Algorithms ArrayView renderer (`features/algorithms/.../arrayViewMotion.ts`,
//      `ensureArrayViewMotion`) — injects the compiled CSS into the live visualization; and
//   2. the Designs seed (`features/designs/lib/algoVizKit.ts` → `seed.ts`) — registers `algo-viz` as a
//      recoverable builtin kit so the set is visible + editable in the Design Studio's AnimationsMenu.
// Importing the Algorithms barrel from the Designs seed would eagerly pull the whole algorithms feature
// (its Workspace + graph) into the store-boot module graph and risks a designs↔algorithms seed cycle. The
// data is genuinely feature-agnostic viz-motion, so it lives HERE — a leaf both features import cheaply.
//
// ── THE STATE-TRIGGER SEAM (#3058) — "verb → data-state → animation" ─────────────────────────────────
// The current engine has no `trigger: "state"`; a state trigger is a KitAnimation whose `selector` IS the
// data-state (`[data-op="swap"]`). The engine compiles it to a rule
//
//     .algo-viz-anim-swap [data-op="swap"] { animation: bsc-algo-viz-swap …; }
//
// which plays whenever a DESCENDANT of the applying-class root matches that state — i.e. exactly when
// `ArrayView` stamps `data-op="swap"` on a cell. The renderer's root carries the applying classes; its
// cells only stamp `data-op` / `data-mark`. Change an animation's data here → every array visualization
// (and the kit's Design-Studio preview) updates, no renderer change.

import type { KitAnimation } from "@/shared/ui/kit/animations";

/** The array-visualization motion kit id — `.algo-viz-anim-<name>` + `@keyframes bsc-algo-viz-<name>`. */
export const ALGO_VIZ_KIT_ID = "algo-viz";

/**
 * The `algo-viz` kit's animations as DATA (#2942), each a STATE trigger keyed on the data-state selector
 * `ArrayView` stamps — so the compiled rule fires on exactly `[data-op="compare"]` / `[data-op="swap"]`
 * / `[data-op="set"]` / `[data-mark="sorted"]`. Token-based colors + durations; the engine wraps every
 * applying rule in `@media (prefers-reduced-motion: no-preference)`, so reduced-motion is handled for
 * free. This is the single source of truth the ArrayView renderer AND the Designs `algo-viz` builtin kit
 * both consume — one definition, two consumers.
 */
export const ALGO_VIZ_ANIMATIONS: KitAnimation[] = [
  // compare — a highlight pulse on the two compared cells.
  {
    name: "compare",
    selector: '[data-op="compare"]',
    duration: "500ms",
    easing: "var(--ease-standard)",
    set: { "z-index": "1" },
    keyframes: {
      "0%": { "box-shadow": "0 0 0 0 transparent", "border-color": "var(--border)" },
      "45%": {
        "box-shadow": "0 0 0 2px color-mix(in oklch, var(--state-wait), transparent 45%)",
        "border-color": "var(--state-wait)",
      },
      "100%": { "box-shadow": "0 0 0 0 transparent", "border-color": "var(--border)" },
    },
  },
  // swap — the two cells lift, tint to the accent, and settle back as they exchange.
  {
    name: "swap",
    selector: '[data-op="swap"]',
    duration: "420ms",
    easing: "cubic-bezier(0.34, 1.4, 0.5, 1)",
    set: { "z-index": "2" },
    keyframes: {
      "0%": {
        transform: "translateY(0)",
        "border-color": "var(--accent)",
        background: "color-mix(in oklch, var(--accent), var(--bg-elev) 62%)",
      },
      "40%": { transform: "translateY(-12px) scale(1.05)" },
      "100%": { transform: "translateY(0)" },
    },
  },
  // set — a value flash (a fresh write into the cell).
  {
    name: "set",
    selector: '[data-op="set"]',
    duration: "500ms",
    easing: "var(--ease-standard)",
    keyframes: {
      "0%": { background: "color-mix(in oklch, var(--accent), transparent 20%)" },
      "100%": { background: "var(--bg-elev)" },
    },
  },
  // probe — the SEARCH verb (#3220): ONE cell examined against an external target. Deliberately unlike
  // `compare` (which pulses a PAIR): a tight accent ring that closes in on the single cell, so a search
  // reads as "inspect this one" rather than "weigh these two".
  {
    name: "probe",
    selector: '[data-op="probe"]',
    duration: "460ms",
    easing: "var(--ease-standard)",
    set: { "z-index": "1" },
    keyframes: {
      "0%": { "box-shadow": "0 0 0 6px transparent", "border-color": "var(--border)" },
      "50%": {
        "box-shadow": "0 0 0 2px color-mix(in oklch, var(--accent), transparent 35%)",
        "border-color": "var(--accent)",
      },
      "100%": { "box-shadow": "0 0 0 0 transparent", "border-color": "var(--border)" },
    },
  },
  // found — the search's terminal hit (#3220): a one-shot pop as the target is located (its DURABLE accent
  // resting look is a static element style in arrayView.css, since the mark ends the trace).
  {
    name: "found",
    selector: '[data-mark="found"]',
    duration: "420ms",
    easing: "cubic-bezier(0.34, 1.4, 0.5, 1)",
    set: { "z-index": "2" },
    keyframes: {
      "0%": { transform: "scale(1)" },
      "45%": { transform: "scale(1.12)" },
      "100%": { transform: "scale(1)" },
    },
  },
  // sorted — a one-shot settle as a cell reaches its final place (its DURABLE green resting look is a
  // static element style in arrayView.css, since a mark persists across frames — this is only the motion).
  {
    name: "sorted",
    selector: '[data-mark="sorted"]',
    duration: "300ms",
    easing: "var(--ease-standard)",
    keyframes: {
      "0%": { transform: "translateY(-3px)" },
      "100%": { transform: "translateY(0)" },
    },
  },
];

/** Wh per 1k tokens by model tier — directional coefficients, not metered readings. */
const WH_PER_1K: Record<"large" | "medium" | "small" | "local", { in: number; out: number }> = {
  large: { in: 0.05, out: 0.9 },
  medium: { in: 0.03, out: 0.4 },
  small: { in: 0.01, out: 0.15 },
  local: { in: 0, out: 0 },
};

/** Classify a model name into an energy tier by name pattern; unknown hosted models fall to medium. */
function tier(model: string): keyof typeof WH_PER_1K {
  const m = model.toLowerCase();
  if (/local|ollama|llama|mistral|qwen|deepseek|phi/.test(m)) return "local";
  if (/opus|ultra|gpt-4(?!o)|gpt4(?!o)/.test(m)) return "large";
  if (/haiku|mini|flash|nano|small|lite/.test(m)) return "small";
  return "medium";
}

/** Estimated Wh for an input/output token split at the model's tier. Directional, not metered. */
export function estimateEnergyWh(model: string, inputTokens: number, outputTokens: number): number {
  const k = WH_PER_1K[tier(model)];
  return (inputTokens / 1000) * k.in + (outputTokens / 1000) * k.out;
}

// The algorithms feature's store slice — the IMPLS the runtime resolver can reach.
//
// WHY A SLICE AND NOT `useKnowledgeGraph`. The Algorithms page already hydrates the live graph by
// polling `graph_dump` through that hook, and it stays the page's source. But `resolveGraphSource` is
// SYNCHRONOUS — `(specifier) => string | null`, reading a `getState()` snapshot — so it cannot invoke a
// Tauri command, and it lives in `shared/`, which may not import a feature. The only surface satisfying
// both is the app store, which is exactly how COMPONENTS already reach it (`hydrateComponents`, #3610).
// So this mirrors that path rather than inventing a second one.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import type { AlgoImpl } from "@/features/algorithms/lib/knowledge";
import { loadGraph } from "@/features/algorithms/lib/graphBridge";

export interface AlgorithmsSlice {
  /** Every implementation in the writable store — the set `resolveGraphSource` matches `provides` against.
   *  A CACHE, never persisted (#3610): it is re-read from the store at each boot. */
  algorithmImpls: AlgoImpl[];
  /** Read the librarian's writable store into memory. Idempotent; a no-op in a degraded environment. */
  hydrateAlgorithms: () => Promise<void>;
}

export const createAlgorithmsSlice: StateCreator<AppStore, [], [], AlgorithmsSlice> = (set) => ({
  algorithmImpls: [],
  hydrateAlgorithms: async () => {
    // `loadGraph` returns null on ANY failure — the web shell, the tests, an old `bsc` — so a degraded
    // environment simply resolves nothing rather than throwing during boot. Same contract the
    // Algorithms page already relies on.
    const graph = await loadGraph();
    if (!graph) return;
    set({ algorithmImpls: graph.implementations });
  },
});

import type { ConsoleProvider } from "@/app/console/lib/providers/types";

export const amazonQProvider: ConsoleProvider = {
  id: "amazonq",
  displayName: "Amazon Q Developer",
  buildLaunchCmd: () => "q",
  prereqProbe: "which q",
};

// The shipped analytics EMIT runtime (#3816, epic #3809 slice 3) — the fixed, audited code that turns a
// component's #3810 `analytics` manifest (DATA) into a `bsc usage record` (#3812) call when one of its
// actions fires. This is the seam that finally connects the two halves the epic left disconnected: the
// per-node CONTRACT (`ComponentRecord.analytics`) and the per-app SINK (`bsc usage record`).
//
// The load-bearing principle (inherited from #3283): CODE vs DATA. The component DECLARES what it emits;
// THIS runtime — fixed, shipped, never LLM-authored — does the emitting. There is no `track()`/`emit()`
// call in any authored component: emission is derived from the manifest at the render seam, so an app
// composed from instrumented nodes is instrumented BY CONSTRUCTION, uniformly, for free.
//
// It is host-agnostic on purpose: the SINK is injected. A generated app running in a Node/dev process
// spawns `bsc usage record` (the argv `usageRecordArgs` builds); a test collects; a browser logs. Absent
// a sink the whole path is inert — the dev-only / opt-in gate.

import type { AnalyticsEvent } from "@/features/designs/lib/model";

/** What `KitRenderer` reports when a bound handler fires (mirrors its `KitBindings.emit` argument): the
 *  node's component `type`, the action PROP that fired, and the args the underlying handler received. */
export interface ActionFire {
  type: string;
  prop: string;
  args: unknown[];
}

/** A resolved usage event, ready for the sink / the `bsc usage record` CLI. */
export interface UsageRecord {
  event: string;
  props: Record<string, unknown>;
}

/** Where resolved events go. Injected so the runtime is host-agnostic — see the file header. */
export type UsageSink = (rec: UsageRecord) => void;

/** A component-manifest lookup by a node's `type` (the host wires this to the components store; the
 *  shared renderer never reads the store itself). */
export type AnalyticsLookup = (type: string) => AnalyticsEvent[] | undefined;

/**
 * The convention that binds an action PROP to the event a component would declare for it: strip the
 * leading `on`, then PascalCase → snake_case (`onClick` → `click`, `onItemSelected` → `item_selected`,
 * `onFilterChanged` → `filter_changed`). Returns `undefined` for a non-action prop (one that is not
 * `on`-prefixed), which is the same "starts with `on`" shape the `no-analytics` doctor finding uses to
 * decide a component is interactive — so the finding and the runtime agree on what an action is.
 */
export function eventNameForProp(prop: string): string | undefined {
  if (!/^on[A-Z]/.test(prop)) return undefined;
  return prop
    .slice(2) // drop "on"
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1_$2") // acronym boundary: HTMLParser → HTML_Parser
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2") // camel boundary: ItemSelected → Item_Selected
    .toLowerCase();
}

/** A plain data object we can read a payload from — NOT an array and NOT a DOM `Event` (a click's
 *  `MouseEvent` carries no analytics payload, so it must not be mined for prop values). */
function isPlainPayload(v: unknown): v is Record<string, unknown> {
  if (typeof v !== "object" || v === null || Array.isArray(v)) return false;
  if (typeof Event !== "undefined" && v instanceof Event) return false;
  return true;
}

/**
 * Resolve a fired action to the usage event its component DECLARED — or `undefined` when the component
 * declared no matching event. It never invents an undeclared event: the manifest is the authority on
 * what an app reports.
 *
 * `props` are filled from the declared `PropSpec` NAMES, best-effort, from `args[0]` when that is a plain
 * data object (e.g. `onChange(nextValue)` where the value is an object, or a synthetic payload the host
 * passes). A DOM event or a scalar arg yields an EMPTY props map — the runtime records the event name
 * (the "what users do" signal `bsc usage summary` ranks) but does not fabricate a payload it cannot see.
 * This is the same honesty the prop validator publishes about what it can and cannot check.
 */
export function resolveAnalyticsEmit(
  manifest: AnalyticsEvent[] | undefined,
  prop: string,
  args: unknown[],
): UsageRecord | undefined {
  if (!manifest || manifest.length === 0) return undefined;
  const name = eventNameForProp(prop);
  if (!name) return undefined;
  const declared = manifest.find((e) => e.event === name);
  if (!declared) return undefined;

  const props: Record<string, unknown> = {};
  const payload = args[0];
  if (declared.props && isPlainPayload(payload)) {
    for (const p of declared.props) {
      if (Object.prototype.hasOwnProperty.call(payload, p.name)) props[p.name] = payload[p.name];
    }
  }
  return { event: declared.event, props };
}

/**
 * Build the exact argv `bsc usage record` (#3812) accepts, so the emit runtime's data-out shape IS the
 * CLI's input — a Node host can `spawn("bsc", usageRecordArgs(rec))` with no glue. `--props` is omitted
 * when the payload is empty (the CLI treats a missing `--props` as no payload).
 */
export function usageRecordArgs(rec: UsageRecord): string[] {
  const argv = ["usage", "record", "--event", rec.event];
  if (Object.keys(rec.props).length > 0) argv.push("--props", JSON.stringify(rec.props));
  return argv;
}

/**
 * Compose a manifest lookup + a sink into the hook `KitRenderer.emit` expects. A fire that resolves to no
 * declared event is a silent no-op — most action props are not instrumented, and that is fine.
 */
export function makeAnalyticsEmit(lookup: AnalyticsLookup, sink: UsageSink): (fire: ActionFire) => void {
  return (fire) => {
    const rec = resolveAnalyticsEmit(lookup(fire.type), fire.prop, fire.args);
    if (rec) sink(rec);
  };
}

/** Build an {@link AnalyticsLookup} from component records keyed by `name` — the studio host's bridge
 *  from its components store to the manifest-driven runtime. */
export function componentAnalyticsLookup(
  records: Iterable<{ name: string; analytics?: AnalyticsEvent[] }>,
): AnalyticsLookup {
  const byName = new Map<string, AnalyticsEvent[] | undefined>();
  for (const r of records) byName.set(r.name, r.analytics);
  return (type) => byName.get(type);
}

/** A sink that COLLECTS records — for tests and for a host that wants to batch/inspect before shipping. */
export function collectingSink(): UsageSink & { records: UsageRecord[] } {
  const records: UsageRecord[] = [];
  const sink = ((rec: UsageRecord) => {
    records.push(rec);
  }) as UsageSink & { records: UsageRecord[] };
  sink.records = records;
  return sink;
}

/** A sink that logs the `bsc usage record` argv — dev visibility. The real DB write is that CLI running
 *  in the app's OWN session, where `$BSC_USAGE_DB` is wired to the per-project `usage.db`. */
export const consoleUsageSink: UsageSink = (rec) => {
  // A deliberate dev-visibility sink; opt-in, never on by default.
  console.info("[usage] bsc", ...usageRecordArgs(rec));
};

// Data-defined KIT animations (#2942, epic #2865/#2553) — the RENDER path for motion an LLM authors
// as data on a KIT (`Kit.animations`), the motion sibling of themes. Each definition compiles to a
// `@keyframes bsc-<kit>-<name>` block + an applying rule on `.<kit>-anim-<name>`, injected into ONE
// managed `<style>`, so a kit's motion plays on any of its components with zero component changes.
// A component BINDS an animation by name (`ComponentRecord.animations: string[]`) — the renderer puts
// `.<kit>-anim-<name>` on the element; the kit owns the keyframes + timing + trigger.
//
// Motion is per-KIT, not global and not baked per-component: a kit is a structurally-distinct
// component set (its own DOM/CSS architecture), so a 3D / non-DOM kit carries a different motion
// representation, and two kits may reuse a name (`fade-in`) with different keyframes without colliding.
// Mirrors the variant render path (variants.ts): compiled on boot + re-applied on a `ui-touch` write.
// The applying rule is wrapped in `@media (prefers-reduced-motion: no-preference)`, so motion is
// suppressed for users who ask for less of it.
//
// DEFENSE IN DEPTH: like variants, this compiles LLM-authored data into live CSS, so a kit /
// animation name must be a safe CSS identifier, a keyframe stop must be `from`/`to`/`N%`, a property
// must be `[a-z-]+`, and no value may carry a declaration-ending / injection sequence. An optional
// child `selector` must pass `SAFE_SELECTOR` (only selector-safe characters — it cannot break out of
// the selector position). Anything failing is skipped, never emitted.

/** When an authored animation plays. `mount` (the default) plays once as the element is INSERTED — so a
 *  child `selector` + `mount` voices a STATE-TRIGGERED conditional render (e.g. a tooltip pop-in): CSS
 *  restarts a `1 both` animation each time the matched subtree (re)mounts, so no dedicated "state" trigger
 *  is needed (#3058). `exit` is DORMANT until the preview exit-runtime lands (#3057). */
export type AnimationTrigger = "mount" | "hover" | "always" | "exit";

/** One authored animation in a kit's motion library (the shape carried on a `Kit`'s `animations`).
 *  A component references it by {@link name} to play it — the kit owns the keyframes/timing/trigger. */
export interface KitAnimation {
  /** Animation name — a safe CSS identifier → `.<kit>-anim-<name>` + `@keyframes bsc-<kit>-<name>`. */
  name: string;
  /** Keyframe stops: a selector (`from`/`to`/`N%`) → CSS declarations (property → value). */
  keyframes: Record<string, Record<string, string>>;
  /** Duration — a motion-token ref (`var(--dur-base)`) or a time (`220ms`). Default `var(--dur-base)`. */
  duration?: string;
  /** Easing — a motion-token ref (`var(--ease-standard)`) or a timing-function. Default `var(--ease-standard)`. */
  easing?: string;
  /** Animation-level delay (#3056) — a time (`120ms`), slotted after easing in the shorthand. Default none. */
  delay?: string;
  /** When it plays. Default `mount`. `exit` (#3057) keys the rule on a `[data-bsc-exit]` marker so it
   *  plays as a subtree LEAVES — DORMANT until the preview exit-runtime sets that marker on the leaving
   *  element (nothing sets it today, so an exit animation compiles the keyframes + rule but plays
   *  nothing yet; a follow-up slice adds the runtime that flips the marker). */
  trigger?: AnimationTrigger;
  /** Scope the applying rule to a CHILD element (#3054) — a descendant combinator
   *  (`.<kit>-anim-<name> <selector>`). Absent ⇒ the animation applies to the root class as before. */
  selector?: string;
  /** STATIC declarations set on the applying rule (#3054) — for `transform-origin` / `transform-box`
   *  etc. that can't live in keyframes. Each `property: value` is guarded like a keyframe declaration. */
  set?: Record<string, string>;
  /** Per-matched-element delay STEP (#3055) — a time (`14ms`) added cumulatively across the elements a
   *  {@link selector} matches, so a heatmap wave / scatter cascade / per-series line ripples in. Only
   *  meaningful WITH a `selector` (a root has no siblings to step); capped at ~`STAGGER_MAX` elements
   *  (siblings past the cap gracefully fall back to the base `delay`). Absent ⇒ no per-element step. */
  stagger?: string;
  /** VARIATION SLOT (#3069) — the ORGANIZATIONAL grouping for a component's alternative animations, the
   *  motion analog of a component variant. Two or more animations a component binds that share a `group`
   *  are VARIATIONS of one another for the SAME slot (e.g. "bars entering"), and only ONE of the group
   *  PLAYS — the {@link default} (or the first in appearance order, if none is marked). Ungrouped
   *  animations are unaffected: they all play, exactly as before. Purely ORGANIZATIONAL: it is NOT
   *  emitted to CSS — {@link compileAnimationsCss} and the Rust `validate_animation` ignore it, so it
   *  never touches the keyframes / applying rule. Resolved by `resolveComponentAnimations`. Absent ⇒
   *  ungrouped (always plays). */
  group?: string;
  /** The DEFAULT variation of its {@link group} (#3069) — the one that plays. At most one variation per
   *  group is the default; if none is marked, the FIRST in appearance order plays. Meaningful only WITH a
   *  `group`. Like `group` it is ORGANIZATIONAL — never emitted to CSS. Absent ⇒ not the group's default. */
  default?: boolean;
}

/** A kit animation + its owning kit's CSS class base (the flat shape the compiler takes). */
export interface AnimationDef extends KitAnimation {
  /** The kit's CSS class base (its id, e.g. `react-ui`). */
  kit: string;
  /** The OWNING COMPONENT (#3163) — when set, the compiled `@keyframes` + applying class are namespaced
   *  `bsc-<kit>-<component>-<name>` / `.<kit>-<component>-anim-<name>` so two DIFFERENT components' same-
   *  named animations compile to DISTINCT keyframes instead of one silently clobbering the other (the
   *  invisible collision a multi-component preview hit when a chart + a composed piece both named an
   *  animation `draw-in`). Absent ⇒ the plain, un-namespaced `bsc-<kit>-<name>` / `.<kit>-anim-<name>`
   *  (a single-component preview — existing behavior). Sanitized to a safe ident segment by the compiler
   *  ({@link animClassName}), so a PascalCase component name (`Sparkline`) is accepted. */
  component?: string;
}

const STYLE_ID = "bsc-ui-animations";
/** A safe CSS identifier for a class / keyframes-name segment (mirrors the CLI's sanitize_variant_name). */
const SAFE_IDENT = /^[a-z][a-z0-9-]*$/;
/** A keyframe stop selector — `from`, `to`, or a percentage (`0%`, `50%`, `100%`). */
const SAFE_STOP = /^(from|to|\d{1,3}%)$/;
/** A CSS property name — lowercase letters + hyphens (`opacity`, `transform`, `background-color`). */
const SAFE_PROP = /^[a-z-]+$/;
/** A child selector for the applying rule (#3054) — ONLY selector-safe characters, so it structurally
 *  cannot break out of the selector position into a declaration / new rule / comment (no `{ } ; < \ /`).
 *  Allows classes, tags, `#`ids, `>`/space/`+`/`~` combinators, `[attr="v"]`, `:nth-child(2n)`, `,` lists, `*`. */
const SAFE_SELECTOR = /^[a-zA-Z0-9 ._#>[\]="'\-:(),*+~]+$/;
/** A value that could END the declaration or INJECT CSS — refused even though the CLI already guards. */
const UNSAFE_VALUE = /[;{}<>\\]|url\(|expression\(|@import|\/\*/i;
const DUR_DEFAULT = "var(--dur-base)";
const EASE_DEFAULT = "var(--ease-standard)";
/** Cap on the stagger nth-child ramp (#3055): pure-CSS stagger needs one rule per position, so it's
 *  bounded — 32 covers typical charts, and elements past it fall back to the base delay (graceful,
 *  documented). */
const STAGGER_MAX = 32;

function safeValue(v: unknown): v is string {
  return typeof v === "string" && v.length > 0 && !UNSAFE_VALUE.test(v);
}

/** Sanitize a component name/id into a safe CSS-identifier SEGMENT for keyframe/class namespacing
 *  (#3163): lowercased, every non-`[a-z0-9-]` run collapsed to `-`, leading/trailing `-` stripped. Empty
 *  (or an all-unsafe input) ⇒ "" — the caller then falls back to the un-namespaced form. So a PascalCase
 *  component name (`Sparkline` → `sparkline`, `Bar Chart` → `bar-chart`) namespaces cleanly. */
function identSegment(s: string): string {
  const slug = (s ?? "").toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, "");
  return SAFE_IDENT.test(slug) ? slug : "";
}

/** The `@keyframes` NAME for a def — namespaced by its owning {@link AnimationDef.component} when one is
 *  set (#3163), so two components' same-named animations compile to DISTINCT keyframes instead of one
 *  clobbering the other. Absent/unsafe `component` ⇒ the plain `bsc-<kit>-<name>` (existing behavior). */
function animKeyframeName(d: AnimationDef): string {
  const seg = identSegment(d.component ?? "");
  return seg ? `bsc-${d.kit}-${seg}-${d.name}` : `bsc-${d.kit}-${d.name}`;
}

/** The applying CLASS hook for a def — the component-namespaced twin of {@link animKeyframeName}
 *  (#3163): `.<kit>-<component>-anim-<name>` when a `component` is set, else `.<kit>-anim-<name>`. The
 *  renderer (ComponentPreviewFrame) stamps this EXACT class on `#root`, so it always matches the compiled
 *  rule — exported so the preview derives the class the same way the compiler names the keyframes. */
export function animClassName(d: { kit: string; name: string; component?: string }): string {
  const seg = identSegment(d.component ?? "");
  return seg ? `${d.kit}-${seg}-anim-${d.name}` : `${d.kit}-anim-${d.name}`;
}

/** Compile one animation's `@keyframes` block, or "" when no stop/declaration passes the guards. */
function keyframesCss(d: AnimationDef): string {
  const stops: string[] = [];
  for (const [stop, decls] of Object.entries(d.keyframes ?? {})) {
    if (!SAFE_STOP.test(stop)) continue;
    const lines = Object.entries(decls ?? {})
      .filter(([prop, value]) => SAFE_PROP.test(prop) && safeValue(value))
      .map(([prop, value]) => `    ${prop}: ${value};`);
    if (lines.length) stops.push(`  ${stop} {\n${lines.join("\n")}\n  }`);
  }
  return stops.length ? `@keyframes ${animKeyframeName(d)} {\n${stops.join("\n")}\n}` : "";
}

/**
 * Compile animation definitions into CSS: a `@keyframes bsc-<kit>-<name>` block + a
 * reduced-motion-guarded rule applying it on `.<kit>-anim-<name>` (`:hover` for a hover
 * trigger; `[data-bsc-exit]` for an `exit` trigger — dormant until the exit-runtime, #3057;
 * `infinite` for `always`, else played once). A valid {@link KitAnimation.selector}
 * scopes the applying rule to a CHILD (`.<kit>-anim-<name> <selector>`, #3054); {@link KitAnimation.set}
 * adds static declarations to the rule body; {@link KitAnimation.delay} slots into the shorthand after
 * easing (#3056). A {@link KitAnimation.stagger} with a valid `selector` (#3055) adds, after the base
 * rule, a bounded `:nth-child(2..STAGGER_MAX)` `animation-delay` ramp so the matched elements cascade.
 * Pure + guarded — skips any definition whose kit/name isn't a safe identifier, whose
 * duration/easing/delay looks like an injection, or with no valid keyframes; an unsafe selector falls
 * back to the root class (and drops the stagger ramp) and an unsafe `set` pair is dropped. Empty string
 * when nothing is renderable.
 */
export function compileAnimationsCss(defs: AnimationDef[]): string {
  const blocks: string[] = [];
  for (const d of defs) {
    if (!d || !SAFE_IDENT.test(d.kit ?? "") || !SAFE_IDENT.test(d.name ?? "")) continue;
    const frames = keyframesCss(d);
    if (!frames) continue;
    const dur = safeValue(d.duration) ? d.duration! : DUR_DEFAULT;
    const ease = safeValue(d.easing) ? d.easing! : EASE_DEFAULT;
    const delay = safeValue(d.delay) ? ` ${d.delay}` : "";
    // #3163: the keyframe name + applying class are namespaced by `component` (when set) so a chart and
    // its composed pieces can each carry a same-named animation without one clobbering the other.
    const anim = animKeyframeName(d);
    const cls = `.${animClassName(d)}`;
    // #3054: scope to a child when a safe selector is given (descendant combinator); else the root class.
    const scoped = SAFE_SELECTOR.test(d.selector ?? "") ? `${cls} ${d.selector!.trim()}` : cls;
    // #3057: `exit` keys the rule on a `[data-bsc-exit]` marker — DORMANT until the exit-runtime sets it
    // on a leaving element (nothing sets it today, so an exit rule compiles but never matches → inert).
    const rule =
      d.trigger === "hover" ? `${scoped}:hover`
      : d.trigger === "exit" ? `${scoped}[data-bsc-exit]`
      : scoped;
    const iter = d.trigger === "always" ? "infinite" : "1";
    // #3054: static declarations on the applying rule, guarded exactly like a keyframe declaration.
    const setCss = Object.entries(d.set ?? {})
      .filter(([prop, value]) => SAFE_PROP.test(prop) && safeValue(value))
      .map(([prop, value]) => `${prop}: ${value};`)
      .join(" ");
    const body = `${setCss ? `${setCss} ` : ""}animation: ${anim} ${dur} ${ease}${delay} ${iter} both;`;
    // #3055: with a valid child selector AND a valid stagger step, cascade the matched elements by a
    // bounded nth-child `animation-delay` ramp AFTER the base rule (same scoped(+hover) selector, so
    // specificity + trigger match — `… :hover:nth-child(k)` overrides the base delay). nth-child(1) is
    // already the base delay (the shorthand), so the ramp starts at k=2; each step is (k-1) × stagger,
    // added onto the base delay when one is present. Elements past STAGGER_MAX keep the base delay.
    let staggerRamp = "";
    if (SAFE_SELECTOR.test(d.selector ?? "") && safeValue(d.stagger)) {
      const baseTerm = safeValue(d.delay) ? `${d.delay} + ` : "";
      const steps: string[] = [];
      for (let k = 2; k <= STAGGER_MAX; k++) {
        steps.push(`  ${rule}:nth-child(${k}) { animation-delay: calc(${baseTerm}${k - 1} * ${d.stagger}); }`);
      }
      staggerRamp = `\n${steps.join("\n")}`;
    }
    blocks.push(
      `${frames}\n@media (prefers-reduced-motion: no-preference) {\n  ${rule} { ${body} }${staggerRamp}\n}`,
    );
  }
  return blocks.join("\n\n");
}

/** Flatten a kit list's authored `animations` into the flat `AnimationDef[]` the compiler takes,
 *  keying each by its kit's CSS class base (the kit id — the kit convention). */
export function kitAnimations(
  kits: { id: string; animations?: KitAnimation[] }[],
): AnimationDef[] {
  const out: AnimationDef[] = [];
  for (const k of kits) {
    const kit = k.id ?? "";
    for (const a of k.animations ?? []) out.push({ ...a, kit });
  }
  return out;
}

/**
 * Inject / update / clear the managed `<style id="bsc-ui-animations">` holding the compiled animation
 * CSS. Removing the last animation removes the element. `doc` is param'd for tests. Mirrors
 * {@link applyVariantsToRoot} — one global stylesheet the whole app follows.
 */
export function applyAnimationsToRoot(defs: AnimationDef[], doc: Document = document): void {
  const css = compileAnimationsCss(defs);
  let el = doc.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!css) {
    el?.remove();
    return;
  }
  if (!el) {
    el = doc.createElement("style");
    el.id = STYLE_ID;
    doc.head.appendChild(el);
  }
  el.textContent = css;
}

// Canonical Workspace registry — the SINGLE source of truth for each top-level Workspace's key,
// display name, and rail icon (a Workspace = a rail destination; see docs/frontend-structure.md).
// The left-nav rail AND the titlebar position crumb both read from here, so a Workspace is named in
// exactly ONE place and the two can never drift: add a Workspace here and it's labeled everywhere
// (rail tooltip + the "you are here" titlebar). Previously the rail's NAV array and App's titlebar
// switch each hardcoded the names independently. (#nav-pass; Screen → Workspace rename #1879)

import { TerminalSquare, Zap, Server, FolderKanban, ShieldCheck, Sparkles, Settings, Network } from "lucide-react";
import type { LucideIcon } from "lucide-react";
