// Appearance prefs that drive the design-token CSS variables at runtime (#486).
//
// The accent is a single hue threaded through two tokens — `--accent` (the bright
// interactive color) and `--accent-dim` (its muted partner) — which the rest of
// the palette derives from via color-mix. Offering a fixed set of hue presets (vs.
// a freeform picker) keeps the two tokens in lockstep at the lightness/chroma the
// design was tuned for, so every accent stays legible.
//
// Pure (no DOM access) so the mapping is unit-testable; the App applies the result
// to document.documentElement.

export interface AccentPreset {
  /** Stable id persisted in the store. */
  id: string;
  /** Label shown in the Appearance picker. */
  label: string;
  /** oklch hue angle for this accent. */
  hue: number;
}

/** The accent palette. `amber` (hue 70) is the historical default in tokens.css. */
export const ACCENT_PRESETS: AccentPreset[] = [
  { id: "amber",  label: "Amber",  hue: 70  },
  { id: "blue",   label: "Blue",   hue: 230 },
  { id: "green",  label: "Green",  hue: 145 },
  { id: "cyan",   label: "Cyan",   hue: 195 },
  { id: "purple", label: "Purple", hue: 300 },
  { id: "red",    label: "Red",    hue: 25  },
];

export const DEFAULT_ACCENT = "amber";

/** The two `--accent*` token values for an accent id. Lightness/chroma match the
 *  tokens.css defaults so only the hue changes; an unknown id falls back to the
 *  default so a corrupt persisted value can't blank the accent. */
export function accentVars(id: string): { accent: string; accentDim: string } {
  const p = ACCENT_PRESETS.find((x) => x.id === id)
    ?? ACCENT_PRESETS.find((x) => x.id === DEFAULT_ACCENT)!;
  return {
    accent: `oklch(0.80 0.14 ${p.hue})`,
    accentDim: `oklch(0.55 0.10 ${p.hue})`,
  };
}

// arrayMove -- pure, feature/app-agnostic array reordering helper.
//
// Lives in shared/ so both the console tab-reorder machinery (app/console) and
// the per-page tab model (shared/hooks/usePageTabs) can reuse it without shared/
// reaching into app/ (#1703).

/** Move the element at `from` to `to` in a new array (no mutation). Out-of-range
 *  or no-op moves return a shallow copy unchanged. */
export function moveInArray<T>(arr: T[], from: number, to: number): T[] {
  const out = arr.slice();
  if (from < 0 || from >= out.length || to < 0 || to >= out.length || from === to) return out;
  const [m] = out.splice(from, 1);
  out.splice(to, 0, m);
  return out;
}

// The `array` viz kit's MOTION wiring (#3178, epic #3171/#2942) — injects the compiled motion CSS
// (compare / swap / set / sorted) into the live ArrayView. The animation DATA itself now lives in a
// SHARED, feature-agnostic home (`@/shared/ui/kit/algoVizAnimations`) so BOTH consumers read ONE
// definition: this renderer AND the Designs `algo-viz` builtin kit (#3194) — see that module's doc for
// the why and the state-trigger seam. `ArrayView`'s root carries the applying classes
// ({@link ALGO_VIZ_ANIM_CLASSES}); its cells only stamp `data-op` / `data-mark`. Change an animation's
// data in the shared module → every array visualization AND the Design-Studio kit shelf update, no
// renderer change.
//
// The #3194 kit registration (RESIDUAL, now DONE): the Designs seed registers `ALGO_VIZ_ANIMATIONS` as a
// recoverable builtin kit so `AnimationsMenu` lists + edits them; this renderer keeps its own dedicated
// managed `<style>` (below) so the two paths never clobber each other.

import { animClassName, compileAnimationsCss, kitAnimations } from "@/shared/ui/kit";
import { ALGO_VIZ_KIT_ID, ALGO_VIZ_ANIMATIONS } from "@/shared/ui/kit/algoVizAnimations";

// Re-export the shared data so this renderer's public surface (and the algorithms barrel) is unchanged.
export { ALGO_VIZ_KIT_ID, ALGO_VIZ_ANIMATIONS };

/** The applying classes the renderer's root must carry so the state-scoped rules match its cells —
 *  the kit-binding convention (`the renderer puts .<kit>-anim-<name> on the element`). Derived from the
 *  animation data so it never drifts. */
export const ALGO_VIZ_ANIM_CLASSES: string = ALGO_VIZ_ANIMATIONS.map((a) =>
  animClassName({ kit: ALGO_VIZ_KIT_ID, name: a.name }),
).join(" ");

/** The compiled motion CSS for the kit — produced ONCE by the engine (`compileAnimationsCss`) from the
 *  {@link ALGO_VIZ_ANIMATIONS} data. Pure (no DOM); injected by {@link ensureArrayViewMotion}. */
export const ALGO_VIZ_MOTION_CSS: string = compileAnimationsCss(
  kitAnimations([{ id: ALGO_VIZ_KIT_ID, animations: ALGO_VIZ_ANIMATIONS }]),
);

/** The dedicated managed `<style>` id — SEPARATE from the global `bsc-ui-animations` sheet so wiring the
 *  viz kit in never clobbers the Designs feature's kit animations. */
const STYLE_ID = "bsc-algo-viz-animations";

/**
 * Inject the compiled viz-kit motion CSS into a dedicated managed `<style id="bsc-algo-viz-animations">`
 * (idempotent — one element, updated in place). Mirrors `applyAnimationsToRoot` but on its OWN style id,
 * so it coexists with the global animation sheet. `doc` is param'd for tests. No-op if nothing compiled.
 */
export function ensureArrayViewMotion(doc: Document = document): void {
  if (!ALGO_VIZ_MOTION_CSS) return;
  let el = doc.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!el) {
    el = doc.createElement("style");
    el.id = STYLE_ID;
    doc.head.appendChild(el);
  }
  if (el.textContent !== ALGO_VIZ_MOTION_CSS) el.textContent = ALGO_VIZ_MOTION_CSS;
}

// Document-assignment model — the single source of truth for *which* unified-store
// document seeds a session's kickoff message:
//
//   • startupPrompt — the ONE document that seeds a session's kickoff message.
//
// ─── Mental model: "global default + overrides" ───────────────────────────────
//
// `startupPrompt` is assigned along a four-level cascade, from broadest to most
// specific:
//
//   default  →  project  →  repo  →  session
//
// `default` is the global baseline that applies everywhere. Each narrower level
// refines it for a smaller scope (one project, one repo within a project, one
// live session/pane):
//
//   startupPrompt — OVERRIDE. Exactly one document wins. The most specific level
//                   that names a document supplies it; an absent / null entry
//                   means "inherit" and falls through to the next broader level.
//                   Nothing assigned anywhere → null (the caller uses its
//                   built-in default prompt).
//
// Resolution is PURE — no I/O, no store access. Callers (session launch in #326)
// hold the {@link DocAssignments} state and call {@link resolveStartupPrompt} at
// launch time.

/** A unified-store document, identified by its base-relative path (see documents.ts). */
export type DocRef = string;

/** The scope a session runs in. Any level may be absent (e.g. an ad-hoc console
 *  with no project). Resolution only consults the levels a scope provides. */
export interface AssignmentScope {
  /** Sanitized project key, or null/absent for an unscoped session. */
  projectId?: string | null;
  /** Full repo name (e.g. `owner/web`), or null/absent. */
  repo?: string | null;
  /** Live session / pane id, or null/absent. The narrowest level. */
  session?: string | null;
}

/** Composite key for a per-repo assignment, scoped to its project so the same
 *  repo under two projects never collides. */
export function scopeKey(projectId: string, repo: string): string {
  return `${projectId}::${repo}`;
}

// ─── Startup prompt: single-doc override cascade ──────────────────────────────

/** Per-level assignment of the kickoff document. A `null`/absent value at a
 *  level means "inherit" (fall through to the next broader level). */
export interface StartupPromptCascade {
  /** Global default kickoff document, or null for the built-in prompt. */
  default: DocRef | null;
  /** Overrides keyed by project id. */
  project: Record<string, DocRef | null>;
  /** Overrides keyed by {@link scopeKey}. */
  repo: Record<string, DocRef | null>;
  /** Overrides keyed by session/pane id. */
  session: Record<string, DocRef | null>;
}

/** The complete assignment state for a workspace. */
export interface DocAssignments {
  startupPrompt: StartupPromptCascade;
}

/** A fresh, fully-empty assignment state. */
export function emptyAssignments(): DocAssignments {
  return {
    startupPrompt: { default: null, project: {}, repo: {}, session: {} },
  };
}

/**
 * The cascade levels that apply to a scope, broadest → narrowest. Levels whose
 * scope key is absent are skipped (an unscoped console only ever sees `default`).
 */
function startupLevels(a: StartupPromptCascade, scope: AssignmentScope): (DocRef | null | undefined)[] {
  const out: (DocRef | null | undefined)[] = [a.default];
  if (scope.projectId) out.push(a.project[scope.projectId]);
  if (scope.projectId && scope.repo) out.push(a.repo[scopeKey(scope.projectId, scope.repo)]);
  if (scope.session) out.push(a.session[scope.session]);
  return out;
}

/**
 * Resolves the single kickoff document for a scope, following
 * session → repo → project → default. The most specific level that names a
 * document wins; a `null`/absent entry inherits from the next broader level.
 * Returns `null` when nothing is assigned at any applicable level, in which case
 * the caller uses its built-in default prompt.
 */
export function resolveStartupPrompt(
  assignments: DocAssignments,
  scope: AssignmentScope,
): DocRef | null {
  const levels = startupLevels(assignments.startupPrompt, scope);
  // Walk narrowest → broadest; first explicit (truthy) value wins.
  for (let i = levels.length - 1; i >= 0; i--) {
    const v = levels[i];
    if (v) return v;
  }
  return null;
}

// Agents — audit-log model + decision derivation (#257).
//
// A PreToolUse hook on gated panes appends one TAB-separated line per tool attempt to
// a per-app log (see the `bsc-audit` helper + `read_audit_log`). A flat, redacted line
// — `ts \t pane \t toolName \t target` — is used deliberately: it never writes full
// tool inputs (which could contain file contents / secrets) and is trivially safe to
// emit from shell. This module parses those lines and derives the allow/ask/block
// decision for each, per the pane's resolved policy (profile ∪ role), reusing the same
// rules the launch gate applies.
//
// The derived decision is the app's *policy view*, not a capture of Claude Code's
// internal permission outcome — they agree because the settings are generated from
// these same rules, but treat it as advisory. Pure + unit-testable.

import { checkCommand, matchGlob, type RoleCapability } from "@/shared/lib/session/sessionRoles";

export type AuditDecision = "allow" | "ask" | "block";
export type AuditKind = "cmd" | "tool" | "net";

/** One tool attempt (a parsed `bsc-audit` line). `target` is the command (Bash), file
 *  path (edit tools), or url/query (web) — redacted/short, never full input. */
export interface AuditRecord {
  ts: string; // ISO-8601
  pane: string; // paneId
  toolName: string;
  target: string;
}

export interface AuditRow extends AuditRecord {
  kind: AuditKind;
}

/** The resolved allow/deny rules for a pane (profile ∪ role) — same shape the launch
 *  gate feeds to `ensure_session_settings`. */
export interface ResolvedGate {
  allowedCommands: string[];
  allowToolRules: string[];
  denyToolRules: string[];
}

/** Parse the TSV audit log into records, skipping malformed lines. */
export function parseAuditLog(text: string): AuditRecord[] {
  const out: AuditRecord[] = [];
  for (const line of text.split("\n")) {
    if (!line.trim()) continue;
    const [ts, pane, toolName, ...rest] = line.split("\t");
    if (ts && pane && toolName) {
      out.push({ ts, pane, toolName, target: rest.join("\t") });
    }
  }
  return out;
}

const NET_TOOLS = new Set(["WebFetch", "WebSearch"]);
const FILE_TOOLS = new Set(["Edit", "Write", "MultiEdit", "NotebookEdit"]);

/** Add the display `kind` to a record. */
export function toRow(r: AuditRecord): AuditRow {
  const kind: AuditKind = r.toolName === "Bash" ? "cmd" : NET_TOOLS.has(r.toolName) ? "net" : "tool";
  return { ...r, kind };
}

/** Parse a `Tool(glob)` rule into its parts, or null for a bare tool rule. */
function parseScoped(rule: string): { tool: string; glob: string } | null {
  const m = /^([A-Za-z]+)\((.+)\)$/.exec(rule);
  return m ? { tool: m[1], glob: m[2] } : null;
}

/**
 * Derive the decision for one record against the pane's resolved gate (+ optional role
 * capability for `git`/`gh` command checks). Deny wins; an unlisted capability is `ask`
 * (Claude Code prompts); `Bash` is broadly allowed unless the role gate blocks it.
 */
export function decideAudit(r: AuditRecord, gate: ResolvedGate, roleCap?: RoleCapability): AuditDecision {
  if (r.toolName === "Bash") {
    if (roleCap && !checkCommand(roleCap, r.target).allowed) return "block";
    return "allow"; // Bash is broadly allowed; command control is the allowlist + role gate
  }

  const file = FILE_TOOLS.has(r.toolName) ? r.target : "";

  // Deny wins: a bare tool deny, or a path-scoped deny whose glob matches the file.
  if (gate.denyToolRules.includes(r.toolName)) return "block";
  if (file) {
    for (const rule of gate.denyToolRules) {
      const p = parseScoped(rule);
      if (p && p.tool === r.toolName && matchGlob(p.glob, file)) return "block";
    }
  }
  // Allow: a bare tool allow, or a path-scoped allow whose glob matches.
  if (gate.allowToolRules.includes(r.toolName)) return "allow";
  if (file) {
    for (const rule of gate.allowToolRules) {
      const p = parseScoped(rule);
      if (p && p.tool === r.toolName && matchGlob(p.glob, file)) return "allow";
    }
  }
  return "ask";
}

// Agents — Activity-tab display rows (#257 / #1643).
//
// Turns the raw `bsc-audit` log lines into the computed rows the Activity table
// renders: each row carries the resolving console name, the pane's profile, the
// display kind/target, and the derived allow/ask/block decision (per the pane's
// resolved policy — profile ∪ role, the same rules the launch gate applies). Plus
// the toolbar filter + decision counts. Pure — split out of SecurityWorkspace so the
// transforms are React-free + unit-testable.

import { roleCapability, roleWriteRules, type SessionRole } from "@/shared/lib/session/sessionRoles";
import { resolveProfileSettings } from "@/features/security/lib/profileEnforcement";
import { parseAuditLog, toRow, decideAudit, type AuditDecision, type AuditKind, type ResolvedGate } from "@/features/security/lib/auditLog";
import type { AgentProfile, ConsoleSession } from "@/features/security/lib/agentProfiles";

/** The Activity toolbar's decision filter (`all` shows everything). */
export type DecFilter = "all" | "allow" | "ask" | "block";

/** A computed audit row for the Activity table. */
export interface AuditDisplayRow {
  ts: string;
  console: string;
  pane: string;
  profileId: string;
  kind: AuditKind;
  target: string;
  decision: AuditDecision;
}

/** The state the row derivation reads to resolve each record's console + gate. */
export interface AuditRowContext {
  consoles: Pick<ConsoleSession, "id" | "name">[];
  profiles: AgentProfile[];
  paneProfiles: Record<string, string>;
  paneRoles: Record<string, SessionRole>;
}

/**
 * Build the display rows from raw audit log lines. Each record's decision is derived
 * from the pane's resolved gate (profile ∪ role) — the same rules the launch gate
 * applies — and its console name is resolved from the pane id's tab index.
 */
export function buildAuditRows(lines: string[], ctx: AuditRowContext): AuditDisplayRow[] {
  const records = parseAuditLog(lines.join("\n"));
  return records.map((rec): AuditDisplayRow => {
    const profileId = ctx.paneProfiles[rec.pane] ?? "";
    const profile = ctx.profiles.find((p) => p.id === profileId);
    const role = ctx.paneRoles[rec.pane];
    const roleCap = role ? roleCapability(role) : undefined;
    const prof = profile ? resolveProfileSettings(profile) : null;
    const roleW = roleCap ? roleWriteRules(roleCap) : { allow: [], deny: [] };
    const gate: ResolvedGate = {
      allowedCommands: prof?.allowedCommands ?? [],
      allowToolRules: [...(prof?.allowToolRules ?? []), ...roleW.allow],
      denyToolRules: [...(prof?.denyToolRules ?? []), ...roleW.deny],
    };
    const r = toRow(rec);
    const ti = Number(/^t(\d+)p/.exec(rec.pane)?.[1] ?? "-1");
    return {
      ts: rec.ts,
      console: ctx.consoles.find((c) => c.id === `t${ti}`)?.name ?? "—",
      pane: rec.pane,
      profileId: profileId || "—",
      kind: r.kind,
      target: r.target,
      decision: decideAudit(rec, gate, roleCap),
    };
  });
}

/** Filter rows by the toolbar's decision + console-name selectors (`all` = no filter). */
export function filterAuditRows(rows: AuditDisplayRow[], decision: DecFilter, console: string): AuditDisplayRow[] {
  return rows.filter((r) => {
    if (decision !== "all" && r.decision !== decision) return false;
    if (console !== "all" && r.console !== console) return false;
    return true;
  });
}

/** Tally the rows by decision for the Activity summary cards + filter chips. */
export function auditDecisionCounts(rows: AuditDisplayRow[]): { allow: number; ask: number; block: number } {
  let allow = 0, ask = 0, block = 0;
  for (const r of rows) {
    if (r.decision === "allow") allow++;
    else if (r.decision === "ask") ask++;
    else block++;
  }
  return { allow, ask, block };
}

/** Format an ISO timestamp as a local 24h time, passing through unparseable input. */
export function fmtAuditTime(iso: string): string {
  const d = new Date(iso);
  return isNaN(d.getTime()) ? iso : d.toLocaleTimeString("en-US", { hour12: false });
}

// The AUTO-SPAWN GATE (#3498) — the ONE place that may authorise starting a session without a human
// asking for it. Nothing else in the app is allowed to make that call.
//
// ── WHY THIS IS A GATE AND NOT A CONDITION ──────────────────────────────────────────────────────────
// Automatic session spawning is the highest-consequence capability in the app: a session runs a real
// LLM against a real repo with real credentials, and one that spawns itself can do so repeatedly. The
// maintainer's constraint is therefore explicit — ONLY the debug session may ever be spawned
// automatically, and only while a Settings toggle is on. This module is the enforcement point, kept
// separate from the spawning mechanism so the lock can exist (and be tested) before any door does.
//
// ── THE THREE INDEPENDENT CONDITIONS, ALL FAIL-CLOSED ───────────────────────────────────────────────
//  1. The setting is ON. Default OFF; anything that is not literally `true` reads as off, so a missing,
//     undefined, or corrupted value disables auto-spawn rather than enabling it.
//  2. The role is EXACTLY {@link AUTO_SPAWNABLE_ROLE}. This is an ALLOW-LIST of one, never a deny-list:
//     a role added to `SessionRole` later is refused by default instead of quietly inheriting the
//     capability. That is the same reasoning that makes the restricted-role command surface an
//     allow-list — the failure mode of a deny-list is silent over-permission.
//  3. The caller is the request-intake path. Enforced by this being the only exported authoriser: a
//     second spawn path is the bug to prevent, so `autoSpawnDecision` is the single funnel and its
//     refusals carry a reason rather than returning a bare `false`.
//
// A refusal is never silent — {@link autoSpawnDecision} names WHY, so a blocked spawn is diagnosable
// instead of looking like nothing happened (the failure shape that hid the request queue for a day).

import { ROLE_DEFAULTS, type SessionRole } from "@/shared/lib/session/roleModel";

/**
 * The ONLY role that may ever be auto-spawned (#3498).
 *
 * `satisfies SessionRole` is load-bearing: if the `debugger` role is renamed or removed, this stops
 * compiling rather than silently becoming a string that matches nothing (which would disable the
 * feature quietly) or, worse, matching a different role.
 */
export const AUTO_SPAWNABLE_ROLE = "debugger" satisfies SessionRole;

/** What the caller wants to auto-spawn, and whether the user has enabled auto-spawn at all. */
export interface AutoSpawnRequest {
  /** The role of the session that WOULD be started. */
  role: SessionRole | null | undefined;
  /** The Settings toggle (`autoSpawnDebugSessions`). Anything but `true` is treated as off. */
  enabled: boolean | null | undefined;
}

/** Allowed, or refused WITH the reason — a refusal must be diagnosable, never a bare `false`. */
export type AutoSpawnDecision = { allowed: true } | { allowed: false; reason: string };

/**
 * THE single authoriser for starting a session automatically (#3498). Every auto-spawn call site must
 * route through this; there is deliberately no other exported way to authorise one.
 *
 * Order matters for the reason text: the setting is checked FIRST so that with auto-spawn off, the
 * refusal says so plainly for every role rather than blaming the role.
 */
export function autoSpawnDecision(req: AutoSpawnRequest): AutoSpawnDecision {
  // Fail-closed: only a literal `true` enables. Undefined/null/missing ⇒ off.
  if (req.enabled !== true) {
    return {
      allowed: false,
      reason: "auto-spawn is disabled — turn it on in Settings → Security (it is off by default)",
    };
  }
  if (req.role !== AUTO_SPAWNABLE_ROLE) {
    return {
      allowed: false,
      reason:
        `only the '${AUTO_SPAWNABLE_ROLE}' session may be auto-spawned; ` +
        `'${req.role ?? "(none)"}' must be started explicitly`,
    };
  }
  return { allowed: true };
}

/** {@link autoSpawnDecision} as a boolean, for call sites that don't surface the reason. */
export function mayAutoSpawn(req: AutoSpawnRequest): boolean {
  return autoSpawnDecision(req).allowed;
}

/**
 * Every role the app defines, at RUNTIME — so the gate's tests enumerate the real union rather than a
 * hand-copied list that would drift the moment a role is added. `ROLE_DEFAULTS` is
 * `Record<SessionRole, …>`, so its keys ARE the union.
 */
export function allSessionRoles(): SessionRole[] {
  return Object.keys(ROLE_DEFAULTS) as SessionRole[];
}

// Pure helpers for the automations tunnel surface (#937): project a store Automation to
// the wire frame, and decide whether a phone's arm/disarm request is allowed. The desktop
// owns schedule validity — a phone can arm/disarm/run, but an invalid cron is rejected
// here rather than silently armed (and the phone never runs schedules itself).

import { isValidCron, type Automation, type AutomationWhen } from "@/features/automations";
import type { AutomationFrame } from "@/features/tunnel/lib/tunnelClient";

/** A compact, human-readable schedule string for the phone (cron expr, or "every day · 09:00"). */
export function whenExpr(when: AutomationWhen): string {
  if (when.kind === "cron") return when.expr;
  return `every ${when.every}${when.every !== "minute" ? " · " + when.at : ""}`;
}

/** Project one automation to its read-only wire frame. */
export function automationToFrame(a: Automation): AutomationFrame {
  return {
    id: a.id,
    name: a.name,
    armed: a.armed,
    whenExpr: whenExpr(a.when),
    lastRunAt: a.lastRunAt,
    nextRunAt: a.nextRunAt,
    lastStatus: a.runs[0]?.status ?? null,
  };
}

export type ArmDecision =
  | { ok: true; id: string; armed: boolean }
  | { ok: false; id: string; name: string; error: string };

/**
 * Decide a phone's arm/disarm request:
 *  - unknown id → rejected.
 *  - arming a cron automation with an invalid expression → rejected (the schedule would
 *    never fire, and the desktop is the source of truth for validity).
 *  - disarming, or arming a valid schedule → allowed.
 */
export function planArm(a: Automation | undefined, id: string, armed: boolean): ArmDecision {
  if (!a) return { ok: false, id, name: id, error: "unknown automation" };
  if (armed && a.when.kind === "cron" && !isValidCron(a.when.expr)) {
    return { ok: false, id, name: a.name, error: `invalid cron expression: ${a.when.expr}` };
  }
  return { ok: true, id, armed };
}

// Compact local-time formatting for automation timestamps.
// fmtClock moved to the shared home (@/shared/lib/core/format, #2421) — import it from there.

import { fmtClock } from "@/shared/lib/core/format";

/** "today HH:MM" / "yesterday HH:MM" / "Mon D HH:MM", or "—" for null. */
export function fmtStamp(ms: number | null): string {
  if (ms == null) return "—";
  const d = new Date(ms);
  const t = fmtClock(ms);
  const midnight = (x: Date) => { const c = new Date(x); c.setHours(0, 0, 0, 0); return c.getTime(); };
  const today = midnight(new Date());
  const day = midnight(d);
  if (day === today) return `today ${t}`;
  if (day === today - 86_400_000) return `yesterday ${t}`;
  return `${d.toLocaleDateString(undefined, { month: "short", day: "numeric" })} ${t}`;
}

/**
 * The status-bar summary of armed schedules: how many are armed and the soonest next run
 * across them (`null` when none are armed or none have a next run). Pure; drives the live
 * Automations status-bar slot (replacing the old hardcoded "4 schedules armed").
 */
export function armedSummary(
  automations: ReadonlyArray<{ armed: boolean; nextRunAt: number | null }>,
): { count: number; nextAt: number | null } {
  let count = 0;
  let nextAt: number | null = null;
  for (const a of automations) {
    if (!a.armed) continue;
    count++;
    if (a.nextRunAt != null && (nextAt == null || a.nextRunAt < nextAt)) nextAt = a.nextRunAt;
  }
  return { count, nextAt };
}

// The automations feature's PUBLIC API — re-exports only, plus the stylesheet the page needs.
//
// The Automations screen itself (#142) is the `automationspage` RECORD, mounted by
// AutomationsGraphHost — which is what `lazyWorkspaces` resolves the `AutomationsWorkspace` symbol
// to, in both App.tsx and DetachedWindow. The copy that used to live in this file was a dead
// duplicate: nothing imported it.
//
// Note for anyone pruning `@/features/mcp`: that record's Hooks tab imports the REAL `HooksView`
// from the mcp barrel and resolves it through the graph platform, so the export is load-bearing at
// runtime even though no FILE imports it any more. A file-import search will call it dead. It isn't.

// Re-exported feature surface — this index is the automations feature's public API barrel (#1309).
export { AutomationsGraphHost } from "@/features/automations/AutomationsGraphHost"; // the graph-hosted workspace (#3642)
export { AutomationsStatus } from "@/features/automations/AutomationsStatus";
export { useScheduler } from "@/features/automations/useScheduler";

// #1545: public API for cross-feature consumers (tunnel).
export { type Automation, type AutomationWhen } from "@/features/automations/lib/scheduler";
export { isValidCron } from "@/features/automations/lib/cron";
export { dispatchAutomation } from "@/features/automations/lib/dispatch";

// Automations feature store slice (#1309) — schedules, commands, and cron automations. Extracted
// from the former grab-bag `automations` slice (which kept LLM config / active-project state, now
// in store/slices/core.ts). Composed into the app store by store/index.ts.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import { type Automation, type AutomationRun, appendRun, computeNextRun } from "@/features/automations/lib/scheduler";
import type { Schedule, Command } from "@/shared/data/mock";

export interface AutomationsSlice {
  schedules: Schedule[];
  addSchedule: () => void;
  updateSchedule: (id: string, patch: Partial<Schedule>) => void;
  removeSchedule: (id: string) => void;
  commands: Command[];
  addCommand: () => void;
  updateCommand: (id: string, patch: Partial<Command>) => void;
  removeCommand: (id: string) => void;
  automations: Automation[];
  addAutomation: (input: Omit<Automation, "id" | "lastRunAt" | "nextRunAt" | "runs">) => string;
  updateAutomation: (id: string, patch: Partial<Automation>) => void;
  removeAutomation: (id: string) => void;
  setAutomationArmed: (id: string, armed: boolean) => void;
  recordAutomationRun: (id: string, run: AutomationRun) => void;
}

export const createAutomationsSlice: StateCreator<AppStore, [], [], AutomationsSlice> = (set) => ({
  schedules: [],
  addSchedule: () =>
    set((s) => {
      const id = `S-${String(s.schedules.length + 1).padStart(2, "0")}`;
      const newSched: Schedule = {
        id, name: "New schedule", on: false,
        when: "every day · 02:00", target: "",
        action: "command", detail: "",
        lastRun: "—", nextRun: "—",
      };
      return { schedules: [...s.schedules, newSched] };
    }),
  updateSchedule: (id, patch) =>
    set((s) => ({ schedules: s.schedules.map((sc) => (sc.id === id ? { ...sc, ...patch } : sc)) })),
  removeSchedule: (id) =>
    set((s) => ({ schedules: s.schedules.filter((sc) => sc.id !== id) })),

  commands: [],
  addCommand: () =>
    set((s) => {
      const id = `cmd_${Math.random().toString(36).slice(2, 8)}`;
      const newCmd: Command = { id, name: "New command", cmd: "", used: 0, tags: [] };
      return { commands: [...s.commands, newCmd] };
    }),
  updateCommand: (id, patch) =>
    set((s) => ({ commands: s.commands.map((c) => (c.id === id ? { ...c, ...patch } : c)) })),
  removeCommand: (id) =>
    set((s) => ({ commands: s.commands.filter((c) => c.id !== id) })),

  automations: [],
  addAutomation: (input) => {
    // Mint the id outside `set` so the action can return it — callers select the new row via useDraft
    // instead of the fragile "find the last item" lookup the screens used to do.
    const id = `auto_${Math.random().toString(36).slice(2, 8)}`;
    set((s) => {
      const nextRunAt = input.armed ? computeNextRun(input.when, Date.now()) : null;
      const a: Automation = { ...input, id, lastRunAt: null, nextRunAt, runs: [] };
      return { automations: [...s.automations, a] };
    });
    return id;
  },
  updateAutomation: (id, patch) =>
    set((s) => ({
      automations: s.automations.map((a) => {
        if (a.id !== id) return a;
        const next = { ...a, ...patch };
        // Editing the trigger or arming re-derives the next fire time.
        if ("when" in patch || "armed" in patch) {
          next.nextRunAt = next.armed ? computeNextRun(next.when, Date.now()) : null;
        }
        return next;
      }),
    })),
  removeAutomation: (id) =>
    set((s) => ({ automations: s.automations.filter((a) => a.id !== id) })),
  setAutomationArmed: (id, armed) =>
    set((s) => ({
      automations: s.automations.map((a) =>
        a.id === id
          ? { ...a, armed, nextRunAt: armed ? computeNextRun(a.when, Date.now()) : null }
          : a),
    })),
  recordAutomationRun: (id, run) =>
    set((s) => ({
      automations: s.automations.map((a) =>
        a.id === id
          ? { ...a, runs: appendRun(a.runs, run), lastRunAt: run.at, nextRunAt: computeNextRun(a.when, run.at) }
          : a),
    })),
});

import type { ChipTone } from "@/shared/ui/data/Chip";

/** Map a profile's base-policy mode to a Chip tone (was `.mode-badge.{deny,ask,allow}`). */
export function modeTone(mode: string): ChipTone {
  return mode === "deny" ? "danger" : mode === "ask" ? "accent" : mode === "allow" ? "success" : "neutral";
}

/** Map a profile origin class to a Chip tone (was `.origin-badge.{approle,gen}`; else neutral). */
export function originTone(cls: string): ChipTone {
  return cls === "approle" ? "info" : cls === "gen" ? "accent" : "neutral";
}

// The app's NOTICE registry (#54) — the one list the banner stack and `bsc navigate dismiss` share.
//
// Every banner in `AppBanners.tsx` hides itself through its own local `useState`, which is fine for a
// human with a mouse and unreachable for a session driving the app from a shell. A designer session hit
// this with two notices it could see in a capture and had no way to clear.
//
// The ids live HERE rather than as strings at each dismiss site so the CLI cannot drift from the UI: a
// banner renamed without updating this list fails the registry test, instead of silently becoming
// un-dismissable the next time someone reaches for it.

/** A notice the app can show, and whether clearing it would decide something on the user's behalf. */
export interface NoticeDef {
  id: string;
  /** What it tells the user — the `bsc navigate dismiss --list` line. */
  label: string;
  /**
   * Does this notice ask a QUESTION whose answer is lost if it is hidden?
   *
   * `session-recovery` asks "3 sessions found on disk that aren't open — restore or discard?". Hiding it
   * does not answer it; it removes the only place the answer could be given, and those sessions stay
   * unrestored with nothing on screen to say so. So a decision-bearing notice is never cleared by a
   * blanket dismiss and is REFUSED by name — choosing for the user is worse than leaving the banner up,
   * which is the whole reason this flag exists rather than a plain id list.
   */
  decision?: true;
}

/** Every dismissable notice, in the order `AppBanners` stacks them. */
export const NOTICES: readonly NoticeDef[] = [
  { id: "kit-changes", label: "a packaged kit changed since you last synced" },
  { id: "seed-drift", label: "rendered modules do not match their source file" },
