// ── import source (#923) ──
// The import screen pulls real blueprint gists from a source GitHub account; the mock community
// catalog (+ its preview/fork flow) was removed. Configurable sources land later (#598). For now
// the default source is the maintainer's account.
export const DEFAULT_GIST_SOURCE = "kevinthelago";

/** Whether an imported blueprint is OUT OF DATE with its upstream gist (#955): the gist's current
 *  `updated_at` is strictly newer than the one recorded locally at import/sync. Both are GitHub
 *  `updated_at` timestamps. Unknown on either side ⇒ can't tell ⇒ not stale (treat as current).
 *  Drives whether the import page renders an "Update" button instead of "✓ Imported". */
export function gistUpdateAvailable(currentUpdatedAt?: string, importedUpdatedAt?: string): boolean {
  if (!currentUpdatedAt || !importedUpdatedAt) return false;
  const cur = new Date(currentUpdatedAt).getTime();
  const imp = new Date(importedUpdatedAt).getTime();
  return isFinite(cur) && isFinite(imp) && cur > imp;
}

// Pure stage-edit helpers for the new Blueprints editor (#609). Operate on a
// BlueprintStage[] and return a new array — the editor calls these then persists via
// setBlueprintStages. Superset model (#609 option A): the runtime fields (gateRule /
// appliesWhen / enabled) are preserved untouched; these add the editor's stage ops
// (add by kind, reorder, dep toggle, pipeline trigger/gate, output disposition).

import {
  type BlueprintStage,
  STAGE_DEFS, mkStage, uid,
} from "@/features/planner/stages/blueprints";
import { stageKind, defaultDisposition } from "@/features/planner/blueprints/blueprintCatalog";

/** Build a section for ANY stage kind. Known kinds (in STAGE_DEFS) keep their runtime
 *  gate; unknown ones (users/stack/…) are synthesized as informational stages. */
export function mkStageSection(kind: string): BlueprintStage {
  if (STAGE_DEFS[kind]) {
    const s = mkStage(kind);
    return { ...s, output: s.output ?? defaultDisposition(kind) };
  }
  const k = stageKind(kind);
  return {
    uid: uid("sec"), key: kind, name: k.title, glyph: "✚", icon: k.glyph, hue: k.h,
    gate: "stage complete", deps: [], blurb: k.blurb,
    prompt: `Document the project's ${k.title.toLowerCase()}. ${k.blurb}`,
    enabled: true, expanded: false, output: defaultDisposition(kind),
  };
}

const mapSec = (sections: BlueprintStage[], u: string, fn: (s: BlueprintStage) => BlueprintStage) =>
  sections.map((s) => (s.uid === u ? fn(s) : s));

/** Move a stage from index `from` to index `to`. */
export function reorderStages(sections: BlueprintStage[], from: number, to: number): BlueprintStage[] {
  if (from === to || from < 0 || from >= sections.length || to < 0 || to >= sections.length) return sections;
  const a = [...sections];
  const [m] = a.splice(from, 1);
  a.splice(to, 0, m);
  return a;
}

/** Append a fresh stage of `kind`. */
export function addStage(sections: BlueprintStage[], kind: string): BlueprintStage[] {
  return [...sections, mkStageSection(kind)];
}

/** Delete a stage and scrub it from other stages' deps (deps are section keys). */
export function deleteStage(sections: BlueprintStage[], u: string): BlueprintStage[] {
  const victim = sections.find((s) => s.uid === u);
  const out = sections.filter((s) => s.uid !== u);
  if (!victim) return out;
  // Only scrub the victim's key if no other remaining section shares it.
  if (out.some((s) => s.key === victim.key)) return out;
  return out.map((s) => ({ ...s, deps: s.deps.filter((d) => d !== victim.key) }));
}

/** Toggle a dependency (by the depended-on stage's key) on a stage. */
export function toggleDep(sections: BlueprintStage[], secUid: string, depKey: string): BlueprintStage[] {
  return mapSec(sections, secUid, (s) => ({
    ...s,
    deps: s.deps.includes(depKey) ? s.deps.filter((d) => d !== depKey) : [...s.deps, depKey],
  }));
}

export function setOutput(sections: BlueprintStage[], secUid: string, output: string): BlueprintStage[] {
  return mapSec(sections, secUid, (s) => ({ ...s, output }));
}

/** Attach a skill/knowledge id to a section (no-op if already attached). (#636) */
export function addSkill(sections: BlueprintStage[], secUid: string, skillId: string): BlueprintStage[] {
  return mapSec(sections, secUid, (s) => ((s.skills ?? []).includes(skillId) ? s : { ...s, skills: [...(s.skills ?? []), skillId] }));
}
/** Detach a skill/knowledge id from a section. (#636) */
export function removeSkill(sections: BlueprintStage[], secUid: string, skillId: string): BlueprintStage[] {
  return mapSec(sections, secUid, (s) => ({ ...s, skills: (s.skills ?? []).filter((x) => x !== skillId) }));
}

/** Attach an MCP server (by name) to a section (no-op if already attached). (#897) */
export function addMcpServer(sections: BlueprintStage[], secUid: string, name: string): BlueprintStage[] {
  return mapSec(sections, secUid, (s) => ((s.mcp ?? []).includes(name) ? s : { ...s, mcp: [...(s.mcp ?? []), name] }));
}
/** Detach an MCP server (by name) from a section. (#897) */
export function removeMcpServer(sections: BlueprintStage[], secUid: string, name: string): BlueprintStage[] {
  return mapSec(sections, secUid, (s) => ({ ...s, mcp: (s.mcp ?? []).filter((x) => x !== name) }));
}
export function setStageField(
  sections: BlueprintStage[], secUid: string, patch: Partial<Pick<BlueprintStage, "name" | "prompt">>,
): BlueprintStage[] {
  return mapSec(sections, secUid, (s) => ({ ...s, ...patch }));
}

/** Stages that may precede `secUid` as dependency candidates (only earlier stages,
 *  preventing cycles) — what the dependency editor offers. */
export function depCandidates(sections: BlueprintStage[], secUid: string): BlueprintStage[] {
  const i = sections.findIndex((s) => s.uid === secUid);
  return i <= 0 ? [] : sections.slice(0, i);
}

// Pure style atoms for the cloud-blueprint column (`list/CloudBlueprints.tsx`, #3802) — the spinner
// rotation (keyframe `bim-spin`, `styles/blueprintImport.css`) + the shared loading shimmer (#2234).
// (The per-row preview cache type + `pill` badge lived here for the removed BlueprintImportModal; they
// went with it — the not-yet-downloaded list is download-only.)

import { type CSSProperties } from "react";
// The loading shimmer is the shared skeleton style now (#2234) — one skeleton look app-wide.
export { shimmer } from "@/shared/ui/feedback/shimmer";

export const spin: CSSProperties = { animation: "bim-spin .8s linear infinite" };

// ── Blueprint display helpers (#…): the blueprint's OWN hued icon tile, a visibility
// pill (draft / private gist / public gist), and a shortened gist link. ────────────────────────
//
// The tile used to be keyed off the lifecycle `category`, which #3785 removed from the model — and
// which had degenerated anyway: every packaged blueprint was `greenfield`, so all six cards drew the
// same glyph, the same hue, and the same meaningless "greenfield" badge. A blueprint is a
// goal/domain route now, so it carries its own `icon`/`h` (CRM → hub, HR → group, …) and the card
// renders those, exactly as the setup page already did.
import { timeAgoMs, truncate } from "@/shared/lib/core/format";
import type { Blueprint, BlueprintGist, BlueprintStage } from "@/features/planner/stages/blueprints";

/** The fallback accent hue for a blueprint that declares no `h` — matches the setup page's `?? 70`. */
export const DEFAULT_BLUEPRINT_HUE = 70;

/** A blueprint's accent colour, from its own hue. */
export function blueprintHue(h?: number): string {
  return `oklch(0.75 0.13 ${h ?? DEFAULT_BLUEPRINT_HUE})`;
}

/** The icon NAME a blueprint's tile renders (an `<Ic>` glyph). A blueprint that declares none falls
 *  back to `category` — the generic grid glyph, which is what `Ic` itself resolves an unknown name
 *  to, made explicit here so the fallback is visible at the call site rather than a surprise.
 *  (Deliberately NOT the name's initial: `Ic` renders SVG paths, never letters, so an initial would
 *  silently resolve to this same generic glyph anyway.) */
export function blueprintIcon(b: Pick<Blueprint, "icon">): string {
  return b.icon ?? "category";
}
export function prettyGist(g?: BlueprintGist): string | undefined {
  if (!g) return undefined;
  if (g.url) {
    const s = g.url.replace(/^https?:\/\//, "").replace(/^www\./, "");
    return truncate(s, 32, 30);
  }
  return g.id ? `gist · ${g.id.slice(0, 7)}` : undefined;
}

/** A blueprint surfaced in the Projects page — a saved library or built-in blueprint. */
export interface BpItem {
  id: string;          // library blueprint id
  name: string;
  pitch: string;
  icon: string;        // the blueprint's own `<Ic>` glyph name
  h?: number;          // the blueprint's own accent hue
  stages: number;
  sections: BlueprintStage[];   // the blueprint's sections — drives the gate-row preview
  builtIn?: boolean;   // a code-owned app template (can't be deleted)
  gistLabel?: string;
  updatedLabel: string;
  sort: number;        // recency key (epoch ms)
}

/** Build the blueprint list surfaced in the rail: ALL blueprints — the built-in app templates AND
 *  the user's saved library — so a blueprint can be SELECTED for the next project right here
 *  (#blueprints). */
export function buildBlueprintItems(blueprints: Blueprint[]): BpItem[] {
  const items: BpItem[] = [];
  for (const b of blueprints) {
    const hasGist = !!b.gist?.id;
    const sortMs = b.updatedAt ? new Date(b.updatedAt).getTime() : 0;
    items.push({
      id: b.id, name: b.name,
      pitch: b.pitch ?? b.desc ?? "",
      icon: blueprintIcon(b), h: b.h,
      stages: b.sections.length, sections: b.sections,
      builtIn: b.origin === "built-in",
      gistLabel: hasGist ? prettyGist(b.gist) : undefined,
      updatedLabel: timeAgoMs(sortMs), sort: sortMs,
    });
  }
  return items;
}

// Blueprint MCP-server attachment (#897). A blueprint section (and the blueprint as a whole)
// can attach reusable MCP servers — tools the planner / fleet can call (research, analysis,
// grading, validation, export). This is the tool counterpart to blueprintSkills.ts (knowledge);
// the two are kept SEPARATE on purpose. Servers are referenced by NAME — the portable ref that
// matches the catalog + `<mcp_assign name="…">` — so a blueprint shared as a gist carries its
// tool list, and the existing applyMcpAssign/{dir} machinery scopes them to the project at
// launch. Pure (no React/Tauri) so it's unit-testable and shared by the editor + launch path.

import { type McpServer } from "@/features/mcp";
import { MCP_CATALOG } from "@/shared/data/mcpCatalog";
import { catalogLink } from "@/features/mcp";
import { applyMcpAssign, type McpStoreLike } from "@/features/planner/lib/planExtensions";
import { type Blueprint } from "@/features/planner/stages/blueprints";

/** One pickable MCP server. `id` is the server NAME (the portable ref stored in a blueprint). */
export interface McpLibraryItem {
  id: string;
  name: string;
  desc?: string;
  /** A downloadable first-party server (installs from source via its catalog git link). */
  downloadable: boolean;
}

/**
 * The pickable MCP-server library for the editor: every MCP server in the catalog (first-party +
 * known) plus any installed MCP server not already in the catalog. Deduped by name
 * (case-insensitive), catalog first.
 */
export function buildMcpLibrary(servers: McpServer[], catalog = MCP_CATALOG): McpLibraryItem[] {
  const out: McpLibraryItem[] = [];
  const seen = new Set<string>();
  const add = (name: string, desc: string | undefined, downloadable: boolean) => {
    const key = name.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    out.push({ id: name, name, desc, downloadable });
  };
  for (const c of catalog) add(c.name, c.desc, !!c.link);
  for (const e of servers) add(e.name, undefined, !!catalogLink(e.name));
  return out;
}

/**
 * Every MCP server name a blueprint attaches — blueprint-wide plus every section — deduped
 * (case-insensitive) and order-preserving. The launch path feeds these to `applyMcpAssign` so the
 * project's planner/fleet sessions get them. The blueprint-wide names come first.
 */
export function collectBlueprintMcp(bp: Blueprint): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  const add = (name: string) => {
    const key = name.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    out.push(name);
  };
  for (const n of bp.mcp ?? []) add(n);
  for (const s of bp.sections) for (const n of s.mcp ?? []) add(n);
  return out;
}

/**
 * Scope a blueprint's attached MCP servers to a project (#897 Phase 2). Idempotently applies
 * each `collectBlueprintMcp` name via `applyMcpAssign` (enables + scopes an existing extension, or
 * adds a catalog-derived one), so the project's planner + fleet sessions get the tools the
 * blueprint declares. Returns the **downloadable** server names (those with a catalog git link) so
 * the caller can clone them (a Tauri side-effect kept out of this pure function). `baseDir`
 * resolves the `{dir}` placeholder for first-party servers.
 */
export function applyBlueprintMcp(
  store: McpStoreLike,
  bp: Blueprint,
  projectId: string,
  baseDir = "",
): string[] {
  const downloadable: string[] = [];
  for (const name of collectBlueprintMcp(bp)) {
    applyMcpAssign(store, name, projectId, baseDir);
    if (catalogLink(name)) downloadable.push(name);
  }
  return downloadable;
}

// Blueprint ⇄ extension-manifest bridge (#598). Wraps a blueprint in the generic
// envelope for export/share, and tolerantly reconstructs a blueprint from an imported
// manifest (fresh uids, defensive field coercion — never trusts the payload shape).
// Pure; pairs with lib/gist/manifest.ts.

import { type Blueprint, type BlueprintStage, type BlueprintTeam, type BlueprintUiKit, type BlueprintSoundKit, type BlueprintDesign, type FleetPolicy, uid, dedupeSections } from "@/features/planner/stages/blueprints";
import { flowOrUndefined } from "@/features/planner/fleet/agentFlow";
import { wrapExtension, type ExtensionManifest } from "@/features/planner/lib/gist/manifest";
import { type SkillPayload } from "@/features/planner/blueprints/blueprintSkills";
// Type-only cross-feature imports (allowed by the #1545 boundary) — the team's node/edge shapes.
import type { Position, Relationship } from "@/features/teams";

const str = (v: unknown, d = ""): string => (typeof v === "string" ? v : d);
const strArr = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : []);

const BP_MODES = ["create", "operate"] as const;

function coerceSection(v: unknown): BlueprintStage | null {
  if (!v || typeof v !== "object") return null;
  const o = v as Record<string, unknown>;
  const key = str(o.key);
  const name = str(o.name);
  if (!key || !name) return null;
  return {
    uid: uid("sec"), key, name,
    glyph: str(o.glyph, "✚"),
    icon: str(o.icon, "category"),
    hue: typeof o.hue === "number" ? o.hue : 250,
    gate: str(o.gate, "stage complete"),
    deps: strArr(o.deps),
    blurb: str(o.blurb),
    prompt: str(o.prompt),
    enabled: o.enabled !== false,
    expanded: false,
    // Attached capabilities (#897) — preserve the section's skill ids + MCP server names so a
    // shared blueprint carries its tools/knowledge instead of silently dropping them on import.
    skills: strArr(o.skills),
    mcp: strArr(o.mcp),
    // Carry the optional flag + output disposition so the stage's shape/behavior survives a share.
    ...(typeof o.optional === "boolean" ? { optional: o.optional } : {}),
    ...(str(o.output) ? { output: str(o.output) } : {}),
  };
}

// ── Embedded team (#2450) ────────────────────────────────────────────────────
const POSITION_KINDS = ["agent", "external", "resource"] as const;

function coercePosition(v: unknown): Position | null {
  if (!v || typeof v !== "object") return null;
  const o = v as Record<string, unknown>;
  const nodeId = str(o.nodeId);
  if (!nodeId) return null;
  const kind = (POSITION_KINDS as readonly string[]).includes(str(o.kind))
    ? (str(o.kind) as Position["kind"]) : "agent";
  return {
    nodeId, kind,
    ...(str(o.personaId) ? { personaId: str(o.personaId) } : {}),
    ...(str(o.label) ? { label: str(o.label) } : {}),
    ...(typeof o.x === "number" ? { x: o.x } : {}),
    ...(typeof o.y === "number" ? { y: o.y } : {}),
  };
}

function coerceRelationship(v: unknown): Relationship | null {
  if (!v || typeof v !== "object") return null;
  const o = v as Record<string, unknown>;
  const id = str(o.id);
  const archetype = str(o.archetype);
  const from = str(o.from);
  const to = str(o.to);
  if (!id || !archetype || !from || !to) return null;
  return { id, archetype, from, to, ...(typeof o.bow === "number" ? { bow: o.bow } : {}) };
}

/** Coerce a blueprint's embedded team (#2450) out of an untrusted payload: positions need a nodeId,
 *  relationships need id/archetype/from/to; malformed entries are dropped. `undefined` when the
 *  field is absent or not an object — a blueprint without a team stays without one. */
export function coerceTeam(v: unknown): BlueprintTeam | undefined {
  if (!v || typeof v !== "object" || Array.isArray(v)) return undefined;
  const o = v as Record<string, unknown>;
  const positions = (Array.isArray(o.positions) ? o.positions : [])
    .map(coercePosition).filter((p): p is Position => !!p);
  const relationships = (Array.isArray(o.relationships) ? o.relationships : [])
    .map(coerceRelationship).filter((r): r is Relationship => !!r);
  return { positions, relationships };
}

/** Coerce a blueprint's UI-kit pin (#2465) out of an untrusted payload — the lockfile entry
 *  referencing an immutable `id@version` artifact in the global kit store. A pin is only as good
 *  as its integrity data, so ALL of id/version/hash are required (a hash-less pin can't be
 *  verified on fetch); anything malformed ⇒ `undefined` — the blueprint just stays unpinned,
 *  exactly like a blueprint that never had one. `source` (the typed-gist URL) stays optional, as
 *  is the paired `themeId` (#2489 — the theme id rides the pin wherever the pin travels; absent ⇒
 *  `"default"`). */
export function coerceUiKit(v: unknown): BlueprintUiKit | undefined {
  if (!v || typeof v !== "object" || Array.isArray(v)) return undefined;
  const o = v as Record<string, unknown>;
  const id = str(o.id);
  const version = str(o.version);
  const hash = str(o.hash);
  if (!id || !version || !hash) return undefined;
  return {
    id, version, hash,
    ...(str(o.source) ? { source: str(o.source) } : {}),
    ...(str(o.themeId) ? { themeId: str(o.themeId) } : {}),
  };
}

/** Coerce a blueprint's SOUND-kit pin (#3372) out of an untrusted payload — the sounds twin of
 *  {@link coerceUiKit}, same discipline: a pin is only as good as its integrity data, so ALL of
 *  id/version/hash are required (a hash-less pin can't be verified on fetch) and anything malformed
 *  ⇒ `undefined` (the blueprint just stays unpinned). `source` (the typed-gist URL) stays optional.
 *  No `themeId` twin — a sound kit has no theme (see {@link BlueprintSoundKit}). */
export function coerceSoundKit(v: unknown): BlueprintSoundKit | undefined {
  if (!v || typeof v !== "object" || Array.isArray(v)) return undefined;
  const o = v as Record<string, unknown>;
  const id = str(o.id);
  const version = str(o.version);
  const hash = str(o.hash);
  if (!id || !version || !hash) return undefined;
  return { id, version, hash, ...(str(o.source) ? { source: str(o.source) } : {}) };
}

/** Coerce a blueprint's fleet POLICY (#1854 Phase b / #2460) out of an untrusted payload — the
 *  default per-stream profile + flow the planner instantiates for this project type's fleet.
 *  `profile` is a reference-by-id (any non-empty string; an unknown id already falls through to
 *  the role default at launch). `flow` reuses the canonical flow coercion ({@link flowOrUndefined}
 *  — the same rule the tag/fleet.json parsers apply): a flow naming at least one field normalizes
 *  to a complete launch-safe AgentFlow, so a fully-specified valid flow round-trips byte-faithfully;
 *  a non-object flow, or one naming no flow field, is dropped. A policy carrying NEITHER field —
 *  malformed, non-object, or informationless `{}` — ⇒ `undefined`: the blueprint just stays on
 *  today's launch-time defaults, exactly like one that never declared a policy. */
export function coerceFleetPolicy(v: unknown): FleetPolicy | undefined {
  if (!v || typeof v !== "object" || Array.isArray(v)) return undefined;
  const o = v as Record<string, unknown>;
  const profile = str(o.profile);
  const rawFlow = o.flow && typeof o.flow === "object" && !Array.isArray(o.flow)
    ? (o.flow as Record<string, unknown>) : undefined;
  const flow = flowOrUndefined(rawFlow);
  if (!profile && !flow) return undefined;
  return { ...(profile ? { profile } : {}), ...(flow ? { flow } : {}) };
}

/** Reconstruct a Blueprint from an untrusted payload, or null if it's not one. Requires an id, a
 *  name, and (by default) at least one valid section; assigns fresh uids.
 *
 *  `allowEmptySections` (#923) accepts a section-less blueprint — used for the IN-PROGRESS blueprint
 *  an authoring session emits via the `<blueprint>` tag, which has its identity (name) at
 *  the Purpose stage before any stages are designed. Import stays strict (≥1 section). */
export function coerceBlueprint(
  payload: unknown,
  { allowEmptySections = false }: { allowEmptySections?: boolean } = {},
): Blueprint | null {
  if (!payload || typeof payload !== "object") return null;
  const o = payload as Record<string, unknown>;
  const id = str(o.id);
  const name = str(o.name);
  if (!id || !name) return null;
  // Accept `stages` (the planner-facing name — matching the design, the UI, and the planning-process
  // concept) OR the internal `sections` field (#923): they're the same thing — the ordered planning
  // STAGES, one per project pane. (NOT the per-stage context files, which a stage like Context
  // produces itself.) The internal model keeps the field name `sections`.
  const rawStages = Array.isArray(o.stages) ? o.stages : Array.isArray(o.sections) ? o.sections : [];
  // Dedup the section keys defensively — a hand-edited/imported blueprint could carry a duplicate.
  const sections = dedupeSections(rawStages.map(coerceSection).filter(Boolean) as BlueprintStage[]);
  if (sections.length === 0 && !allowEmptySections) return null;
  const mode = (BP_MODES as readonly string[]).includes(str(o.mode))
    ? (str(o.mode) as Blueprint["mode"]) : undefined;
  const VIS = ["local", "private-gist", "catalog"] as const;
  const visibility = (VIS as readonly string[]).includes(str(o.visibility))
    ? (str(o.visibility) as Blueprint["visibility"]) : undefined;
  // Embedded team (#2450) — preserved through import/share so the blueprint keeps its own org
  // configuration instead of silently dropping it (same discipline as skills/mcp above).
  const team = coerceTeam(o.team);
  // UI-kit pin (#2465) — the whitelist below silently strips unknown fields (the #2450 lesson),
  // so the pin MUST be coerced explicitly or it would vanish on every import/poll round-trip.
  const uiKit = coerceUiKit(o.uiKit);
  // Sound-kit pin (#3372) — SAME whitelist discipline as uiKit: without explicit coercion the pin
  // would vanish on every import/share/poll round-trip and a shared blueprint would silently lose
  // the sound kit it prescribes.
  const soundKit = coerceSoundKit(o.soundKit);
  // Fleet policy (#1854 Phase b / #2460) — same whitelist discipline: without explicit coercion
  // every import/share/poll round-trip would silently strip the default per-stream profile+flow,
  // reverting the blueprint's fleet to launch defaults.
  const fleetPolicy = coerceFleetPolicy(o.fleetPolicy);
  // Design contribution (#2606) — the categories the blueprint introduces + a preferred theme ref.
  // SAME whitelist discipline (#2450): without explicit coercion `design` would be silently stripped
  // on every import/share/poll round-trip and the download-reconciliation confirm-list (#2658) would
  // never fire — a silent hole, exactly what the "fall loudly" principle forbids.
  const design = coerceDesign(o.design);
  return {
    id, name, desc: str(o.desc), sections,
    // Blueprint-wide attached capabilities (#897) + lifecycle metadata, preserved on import.
    skills: strArr(o.skills),
    mcp: strArr(o.mcp),
    // Authoring metadata (#923): catalog pitch/audience/tags/visibility + accent hue/icon.
    ...(str(o.pitch) ? { pitch: str(o.pitch) } : {}),
    ...(str(o.audience) ? { audience: str(o.audience) } : {}),
    ...(visibility ? { visibility } : {}),
    ...(strArr(o.tags).length ? { tags: strArr(o.tags) } : {}),
    ...(typeof o.h === "number" ? { h: o.h } : {}),
    ...(str(o.icon) ? { icon: str(o.icon) } : {}),
    ...(mode ? { mode } : {}),
    ...(fleetPolicy ? { fleetPolicy } : {}),
    ...(team ? { team } : {}),
    ...(uiKit ? { uiKit } : {}),
    ...(soundKit ? { soundKit } : {}),
    ...(design ? { design } : {}),
  };
}

/** Coerce a blueprint's design contribution (#2606) from an untrusted payload — the categories it
 *  introduces + a preferred theme ref. Returns undefined when neither is present, so an all-default
 *  blueprint stays `design`-less (and reconcile is a no-op). Mirrors coerceUiKit/coerceTeam. */
function coerceDesign(raw: unknown): BlueprintDesign | undefined {
  if (!raw || typeof raw !== "object") return undefined;
  const o = raw as Record<string, unknown>;
  const categories = strArr(o.categories);
  const theme = str(o.theme);
  if (!categories.length && !theme) return undefined;
  return { ...(categories.length ? { categories } : {}), ...(theme ? { theme } : {}) };
}

/** Wrap a blueprint in the extension envelope for export / share / publish. When `bundledSkills`
 *  is given (#897 Phase 5b), the attached skills' CONTENT travels in the payload so the share is
 *  self-contained for knowledge; the recipient reconstitutes them into their library on import.
 *  (MCP servers stay by reference — they download from their catalog link, not the gist.) */
export function blueprintToManifest(bp: Blueprint, bundledSkills: SkillPayload[] = []): ExtensionManifest<Blueprint> {
  const payload = bundledSkills.length ? { ...bp, bundledSkills } : bp;
  return wrapExtension("blueprint", bp.id, bp.name, "1.0.0", payload, { description: bp.desc });
}

/** Coerce embedded skill content out of a shared manifest's payload (#897 Phase 5b). Tolerant of
 *  an absent/old payload (returns []). Each item keeps its id so the blueprint's refs resolve. */
export function bundledSkillsFromManifest(m: ExtensionManifest): SkillPayload[] {
  const raw = (m?.payload as { bundledSkills?: unknown } | undefined)?.bundledSkills;
  if (!Array.isArray(raw)) return [];
  const out: SkillPayload[] = [];
  for (const v of raw) {
    if (!v || typeof v !== "object") continue;
    const o = v as Record<string, unknown>;
    const id = str(o.id);
    const name = str(o.name);
    if (!id || !name) continue;
    // KB blocks were retired (#1460); a legacy "kb" payload reconstitutes as a skill.
    out.push({
      id, name, kind: "skill", content: str(o.content), desc: str(o.desc) || undefined,
      ...(Array.isArray(o.tags) ? { tags: strArr(o.tags) } : {}),
      ...(str(o.skillKind) ? { skillKind: str(o.skillKind) as SkillPayload["skillKind"] } : {}),
      ...(Array.isArray(o.tools) ? { tools: strArr(o.tools) } : {}),
    });
  }
  return out;
}

/** Reconstruct a blueprint from a validated manifest. The store assigns a fresh
 *  blueprint id on import, so a same-id collision can never overwrite an existing one. */
export function manifestToBlueprint(
  m: ExtensionManifest,
): { ok: true; blueprint: Blueprint } | { ok: false; error: string } {
  if (m.kind !== "blueprint") return { ok: false, error: `expected a blueprint, got '${m.kind}'` };
  const blueprint = coerceBlueprint(m.payload);
  if (!blueprint) return { ok: false, error: "blueprint payload is malformed (need id, name, and ≥1 valid section)" };
  return { ok: true, blueprint };
}

// Blueprint skills attachment (#636 slice a). A blueprint section (and the blueprint as a
// whole) can reference reusable library Skills that slice b injects into the agent's context.
// This resolves attached ids (so the editor can show what's attached + warn about anything
// missing). Pure. (The Knowledge Blocks half of this library was retired in #1460 — Skills only.)

import { type SkillDef } from "@/features/skills";
import { type SkillKind } from "@/shared/data/skills";
import { writeProjectFile } from "@/shared/lib/core/projectFiles";
import { type Blueprint } from "@/features/planner/stages/blueprints";

/** One pickable library item, from the Skills library. */
export interface BlueprintSkillItem {
  id: string;
  name: string;
  kind: "skill";
  desc?: string;
}

/** Build the Skills library list for the editor's picker. */
export function buildSkillLibrary(skills: SkillDef[]): BlueprintSkillItem[] {
  return skills.map((s): BlueprintSkillItem => ({ id: s.id, name: s.name, kind: "skill", desc: s.desc }));
}

// ── injection (#636 slice b): resolve attached skills to content + write the context ──

export interface SkillContentItem { name: string; kind: "skill"; content: string }

/** Resolve ids to their content (a SkillDef's prompt). Missing ids are skipped (they surface
 *  as warnings in the editor). */
export function resolveSkillContent(ids: string[], skills: SkillDef[]): SkillContentItem[] {
  const skillById = new Map(skills.map((s) => [s.id, s]));
  const out: SkillContentItem[] = [];
  for (const id of ids) {
    const s = skillById.get(id);
    if (s) out.push({ name: s.name, kind: "skill", content: s.prompt });
  }
  return out;
}

// ── content embedding for share (#897 Phase 5b) ─────────────────────────────
// A shared blueprint references skills by id. To make it self-contained for KNOWLEDGE, the
// share bundles each attached item's full CONTENT (a SkillPayload), and the recipient
// reconstitutes them into their library so the id refs resolve. (MCP servers stay by reference
// — code, not content; they download from their catalog link on use.)

/** An attached skill item, with enough content to faithfully reconstitute it on import. */
export interface SkillPayload {
  /** The library id — kept so the blueprint's refs resolve after reconstitution. */
  id: string;
  name: string;
  kind: "skill";
  /** SkillDef.prompt. */
  content: string;
  desc?: string;
  tags?: string[];
  /** For a skill: its SkillDef.kind + tools, carried so reconstitution is faithful. */
  skillKind?: SkillKind;
  tools?: string[];
}

/** Every distinct skill id a blueprint attaches (project-wide + every stage), order-preserving. */
export function collectBlueprintSkillIds(bp: Blueprint): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  const add = (id: string) => { if (!seen.has(id)) { seen.add(id); out.push(id); } };
  for (const id of bp.skills ?? []) add(id);
  for (const s of bp.sections) for (const id of s.skills ?? []) add(id);
  return out;
}

/** Resolve a blueprint's attached skill ids to full {@link SkillPayload}s for embedding in a
 *  share. Missing ids (not in the library) are skipped. */
export function resolveBlueprintSkillPayloads(bp: Blueprint, skills: SkillDef[]): SkillPayload[] {
  const skillById = new Map(skills.map((s) => [s.id, s]));
  const out: SkillPayload[] = [];
  for (const id of collectBlueprintSkillIds(bp)) {
    const s = skillById.get(id);
    if (s) out.push({ id: s.id, name: s.name, kind: "skill", content: s.prompt, desc: s.desc, skillKind: s.kind, tools: s.tools });
  }
  return out;
}

/** Render a blueprint's attached skills (project-wide + per-stage) into a markdown doc
 *  the agents read (`skills.md`). Empty string when nothing is attached. */
export function buildSkillContext(bp: Blueprint, skills: SkillDef[]): string {
  const render = (items: SkillContentItem[]) =>
    items.map((i) => `### ${i.name} _(${i.kind})_\n\n${i.content.trim() || "_(no content)_"}`).join("\n\n");
  const blocks: string[] = [];
  const wide = resolveSkillContent(bp.skills ?? [], skills);
  if (wide.length) blocks.push(`## Project-wide\n\n${render(wide)}`);
  for (const sec of bp.sections) {
    const items = resolveSkillContent(sec.skills ?? [], skills);
    if (items.length) blocks.push(`## ${sec.name} stage\n\n${render(items)}`);
  }
  if (blocks.length === 0) return "";
  return `# Attached skills & knowledge\n\nReusable context paired with this project's blueprint — read the section relevant to the current stage.\n\n${blocks.join("\n\n")}\n`;
}

/** Resolve + write the blueprint's attached skills to the project hub's skills.md, where
 *  the planner (and downstream sessions) read them. No-op when nothing is attached. */
export async function writeBlueprintSkillContext(args: { projectKey: string; blueprint: Blueprint; skills: SkillDef[] }): Promise<void> {
  const content = buildSkillContext(args.blueprint, args.skills);
  if (!content) return;
  await writeProjectFile(args.projectKey, "skills.md", content);
}

// Blueprint model TYPES (#513/#514, split out #2148): the pure type surface behind the
// Blueprints page — the substeps, the section/stage defs, the Blueprint shape, and the
// status result types. No runtime data or logic; the built-in library lives in
// blueprintBuiltins.ts and the pure helpers in blueprintStages.ts (both re-exported by
// the ./blueprints barrel).

import { type ClassificationSignals } from "@/features/planner/stages/classification";
import { type StageGate, type Requirement } from "@/features/planner/stages/stageGate";
import { type AgentFlow } from "@/features/planner/fleet/agentFlow";
// Type-only cross-feature import (allowed by the #1545 boundary): the blueprint team (#2450)
// reuses the org feature's graph shape rather than redeclaring it.
import type { Position, Relationship } from "@/features/teams";

// ── Substeps ─────────────────────────────────────────────────────────────────
// A discrete step WITHIN a stage. The conductor injects ONE substep's prompt at a time and
// advances when its artifact is written + confirmed — incremental, instead of front-loading
// the whole stage's instructions. A `loop` substep repeats once per dynamic item discovered
// during the stage (the feature workshop), so the conductor drives "one feature at a time".
export type SubStepLoop = "features" | "repos" | "topics";
export interface SubStep {
  /** Canonical key / artifact stem (e.g. "goal" → goal.md). For a loop, the loop's id. */
  key: string;
  label: string;
  /** Injected into the session when this substep becomes active. Plan-only — never describes
   *  publishing (the user owns that). */
  prompt: string;
  /** Human "done when…"; absent ⇒ informational (no gate of its own). */
  gate?: string;
  /** Repeat once per dynamic item (a feature, a repo). Absent ⇒ a single static substep. */
  loop?: SubStepLoop;
}

// ── Dynamic-blueprint additions (#1854 Phase a) ──────────────────────────────
// The first slice of the dynamic-blueprints epic: a stage can adapt its prompt to the DRIVING
// MODEL and can carry ARCHETYPE SEED CONTENT. Both are optional and additive — a stage without
// them behaves exactly as before (its single `prompt`, no seed).

/** A model CAPABILITY tier — the axis model-variant prompts key on (#1854 Phase a). Deliberately
 *  keyed by *capability*, not by a vendor model id, because blueprints are WAN-distributable and
 *  must not couple to a specific model/provider (they run on any {@link LlmProvider} via the
 *  bsc-agent "run on any model" track, #1078):
 *   - `frontier` — top frontier models (Claude Opus/Sonnet, GPT-4-class). The default open-ended
 *     prompt (the base `prompt`) is already written for this tier, so an explicit variant is only
 *     needed to override it.
 *   - `standard` — mid-capability hosted models (Haiku-class, smaller hosted models).
 *   - `local`    — weak local models. The headline payoff: a tight, schema-shaped, more-explicit
 *     directive prompt that lets a weak model plan reliably.
 *  A tier with no variant defined falls back to the base `prompt` (see {@link resolveStagePrompt}). */
export type ModelCapabilityTier = "frontier" | "standard" | "local";

/** Archetype seed content for a stage (#1854 Phase a) — starter content the stage can offer when it
 *  opens (e.g. a "twitter clone" archetype → a starter feature set for the Features stage). Additive:
 *  a stage with no `seed` behaves as today. Seeds; the planner + user still shape the final artifact. */
export interface StageSeed {
  /** The archetype this seed represents (a descriptive slug, e.g. "twitter-clone"). */
  archetype?: string;
  /** The starter content, as markdown — offered as an injectable option when the stage is active. */
  content: string;
}

// ── Sections (the canonical planning stages) ─────────────────────────────────

/** One discovery-checklist dimension. The editor-presentation fields (`icon`/`hue`/`blurb`)
 *  are present only for the dimensions that double as add-stage palette kinds (#1603); plain
 *  checklist dimensions carry just `key` + `title`. */
export interface DimensionMeta {
  key: string;
  title: string;
  /** Material/Lucide icon name (the editor `<Ic>` glyph). */
  icon?: string;
  /** Accent hue (oklch) for the palette card. */
  hue?: number;
  blurb?: string;
}

export interface SectionDef {
  name: string;
  /** Unicode symbol rendered as text in the focused-pane stepper (`focusedPlan.ts`). */
  glyph: string;
  /** Material/Lucide icon name for the editor/bar `<Ic>` component (#1603 — the editor
   *  presentation metadata, single-sourced here from the stage's own JSON). */
  icon: string;
  /** Accent hue (oklch) for the stage's editor/palette card (#1603). */
  hue: number;
  /** Human-readable gate description, shown in the editor and the readiness feedback. */
  gate: string;
  deps: string[];
  blurb: string;
  prompt: string;
  /** Model-variant prompts (#1854 Phase a) — per {@link ModelCapabilityTier} overrides of `prompt`,
   *  so a stage adapts its instructions to the DRIVING model (a tight, schema-shaped prompt for a
   *  weak `local` model alongside the open-ended default). Absent tier ⇒ the base `prompt` is used
   *  (resolved via {@link resolveStagePrompt}); the whole field absent ⇒ today's single-prompt
   *  behavior. Reference-by-tier; unknown tiers are simply ignored. */
  promptVariants?: Partial<Record<ModelCapabilityTier, string>>;
  /** Archetype seed content (#1854 Phase a) — starter content this stage offers when active (e.g. a
   *  starter feature set for a known archetype). Absent ⇒ no seed (today's behavior). */
  seed?: StageSeed;
  /** UI stage only (#604): the self-contained instruction the file-intake "Route" action injects
   *  into the planner to read the staged design files and route each to the right repo. Carried as
   *  stage DATA (like `prompt`) so it isn't hardcoded in the frontend. Absent ⇒ no route prompt. */
  routePrompt?: string;
  /** Declarative completion gate (#…) — the DATA that decides this section's
   *  done-ness. Carried on every section instance so a section is fully serializable
   *  and distributable; the app evaluates it via {@link evalGate}. Absent ⇒ the
   *  section is informational (vacuously complete). */
  gateRule?: StageGate;
  /** Optional applicability rule (e.g. UI only when the project needs a UI). Absent ⇒
   *  the section always applies. */
  appliesWhen?: Requirement;
  /** Declarative "skippable RIGHT NOW" rule (#2854) — the same {@link Requirement} shape as
   *  {@link appliesWhen}/gateRule, evaluated against the live signal bag, that makes a section's
   *  Skip control appear. It expresses the "empty ⇒ skippable, populated ⇒ required" pattern
   *  WITHOUT the stage disappearing (unlike `appliesWhen`, which drops it entirely): e.g. Features
   *  carries `{ signal: "featuresDefined", target: 0, op: "==" }`, so an empty Features stage is
   *  skippable but one with content is required. Absent ⇒ not skippable on its own (only an
   *  {@link optional} section or gate-override offers Skip). Drives `Stage.skippable`. */
  skipWhen?: Requirement;
  /** An OPTIONAL section is shown but never required: it doesn't block plan completion or
   *  downstream dependents, and it's off the critical path (currentStage skips it) — the
   *  user can fill it or skip it (#676). Equivalent to an always-passing {@link skipWhen}. */
  optional?: boolean;
  /** Context stage only (#1019): the baseline REQUIRED topics this section seeds into the project's
   *  dynamic context manifest (plan.db) when first adopted. The planner then adjusts the set with
   *  `bsc-plan context require/unrequire`. Absent ⇒ the universal {@link DISCOVERY_BASELINE}. */
  requires?: string[];
  /** Discovery stage only (#1603): the checklist dimensions, carried as data so the editor's
   *  add-stage palette + the dimension vocabulary (`KNOWN_DIMENSIONS`) single-source from here. */
  dimensions?: DimensionMeta[];
  /** Output disposition (#609) — what happens to this stage's artifact (a key into
   *  DISPOSITIONS: plan-file / issues / milestones / skill-index / knowledge / scratch).
   *  Editor metadata; the runtime doesn't read it. Absent ⇒ defaultDisposition(key). */
  output?: string;
  /** Attached skills/knowledge (#636) — library item ids (KB blocks or Skills) injected
   *  into the agent's context for this stage. Resolved at planning + fleet launch
   *  (slice b). Reference-by-id; unresolved ids surface a warning. */
  skills?: string[];
  /** Attached MCP servers (#897) — server NAMES (the portable ref, matching the catalog +
   *  `<mcp_assign>`), scoped to the project at launch so the planner/fleet can call them.
   *  Kept SEPARATE from `skills`: MCP servers are tools (research/analysis/grading), skills are
   *  knowledge. Reference-by-name; an unresolved name surfaces a warning in the editor. */
  mcp?: string[];
  /** Ordered substeps the conductor injects one at a time (#…). Absent ⇒ the stage is driven
   *  by a single prompt (its `prompt`). Pipeline `triggerTarget`s reference these by `key`. */
  substeps?: SubStep[];
  /** The planner-facing directive prose (#1462) — the single source of truth, shared byte-for-byte
   *  with the Rust `stage_directive`, read from this stage's `prompts/stages/<id>.json`. Only the
   *  duplicated stages carry one; stages without it use the generic Rust fallback. */
  directive?: string;
  /** Reserved (populated by #1395) — the classification signals that gate this stage's applicability,
   *  and its ordering tier. Typed now so #1395 fills them without re-churning files; unset today. */
  signals?: ClassificationSignals;
  phase?: "discover" | "decide" | "generate";
}

export interface BlueprintStage extends SectionDef {
  uid: string;
  key: string;
  enabled: boolean;
  expanded: boolean;
}

/** Where a blueprint came from (#609) — drives the card's origin tag. */
export type BlueprintOrigin = "built-in" | "local" | "forked" | "imported";

/** Whether a blueprint starts from a pitch (create) or runs against existing repos
 *  (operate) — selects the planner intro at launch. */
export type BlueprintMode = "create" | "operate";

/** Gist link state for a blueprint (#609) — the publish/sync state-machine. Slice 5
 *  populates this; the Library card reads it for the sync badge. Absent ⇒ local-only. */
export interface BlueprintGist {
  state: "local" | "dirty" | "synced" | "forked";
  /** Whether an upstream update is available (forked blueprints). */
  behind?: boolean;
  rev?: string;
  author?: string;
  id?: string;
  url?: string;
  public?: boolean;
  /** The upstream gist's `updated_at` recorded at import/sync. Compared against the gist's CURRENT
   *  `updated_at` on the import-from-gist page to detect an available update (#955). */
  updatedAt?: string;
}

/** Fleet POLICY a blueprint declares (#1854 Phase b) — the default per-stream {@link AgentProfile}
 *  and {@link AgentFlow} the planner instantiates when it generates this project type's fleet. A
 *  COMPOSED typed sub-model (epic discipline #1: not N flat top-level fields), carrying only the
 *  *recipe/policy* — the DEFAULTS — while the concrete per-stream config stays planner-GENERATED
 *  per-project (discipline #2: static template vs generation policy). Resolution precedence is
 *  stream-declared → this policy → the hard launch-time default (see `resolveStreamProfile` /
 *  `resolveStreamFlow` in `../fleet/fleetPolicy`). Both fields optional ⇒ when unset, today's
 *  launch-time defaults apply, byte-for-byte.
 *
 *  Trust boundary (discipline #3): a blueprint only *seeds* the launch default here — the role
 *  gate (#219) still caps the session. The request-vs-cap permission POSTURE is Phase (c), out of
 *  scope for this sub-model. */
export interface FleetPolicy {
  /** Default {@link AgentProfile} id for a WORKER stream that doesn't pin its own `profile` (#289).
   *  A reference-by-id; an unknown id just falls through to the role default at launch. Applies to
   *  worker streams only — never the director, which keeps its role's read-only review profile. */
  profile?: string;
  /** Default {@link AgentFlow} (autonomy + push + trigger + gate) for a stream that doesn't declare
   *  its own `flow` (#297). Absent ⇒ the launch path applies {@link DEFAULT_FLOW}. */
  flow?: AgentFlow;
}

/** The TEAM a blueprint carries (#2450) — an embedded org configuration: positions (personas
 *  referenced by id — personas stay a global library) wired by relationships, with the canvas
 *  layout coords on each position. The same graph shape the `bsc org` store holds, MINUS the
 *  library identity fields (`id`/`name`/`blurb`/`builtin`) — the blueprint itself is the identity.
 *
 *  FORK-ON-ATTACH: authoring starts by DEEP-COPYING a library org (or blank) into
 *  `blueprint.team` (see `forkTeamFromOrg`); the `bsc org` store remains the archetype library.
 *  Editing a blueprint's team never mutates the library org and vice versa — reproducibility of
 *  the blueprint artifact wins. Persisted inside the blueprint's JSON (the `bsc blueprint` store
 *  is verbatim JSON), so export/import carries it automatically. Optional — a blueprint without
 *  `team` behaves exactly as before; plan-time consumption (seeding fleet streams from the team)
 *  is a deliberate follow-up, not this field's contract. */
export interface BlueprintTeam {
  positions: Position[];
  relationships: Relationship[];
}

/** The UI KIT a blueprint pins (#2465) — a LOCKFILE entry, deliberately the opposite of `team`:
 *  the kit is REFERENCED, never embedded, because kits are immutable versioned artifacts shared
 *  across blueprints (one copy in the global store, `~/.base-studio-code/kits/<id>/<version>/`,
 *  no matter how many blueprints pin it). Exact pins only — no version ranges (reproducibility).
 *
 *  `hash` is the sha256 (lowercase hex) of the kit artifact's bytes, verified BEFORE a fetched
 *  kit is accepted into the store (resolve flow, `uiKitPin.ts`); `source` is the typed-gist URL
 *  to fetch from when `id@version` isn't in the local store yet. A new blueprint default-pins the
 *  packaged `bsc/react-ui` kit ({@link Blueprint.uiKit} set in `addBlueprint`); a blueprint
 *  without a pin behaves exactly as before. */
export interface BlueprintUiKit {
  /** Publisher-scoped kit id (e.g. `"bsc/react-ui"`). */
  id: string;
  /** Exact semver of the pinned artifact (immutable once published). */
  version: string;
  /** sha256 (lowercase hex) of the artifact bytes. */
  hash: string;
  /** Typed-gist URL to fetch from when the id@version is missing locally. */
  source?: string;
  /** The kit THEME paired with the pin (#2489) — a `bsc ui theme` id. Absent ⇒ `"default"`. An ID,
   *  never the vars: the theme resolves through `bsc ui theme get` at EMISSION time
   *  (`bsc ui emit-css --theme <id>` → the generated app's tokens.css + theme.css), so
   *  designer-authored themes apply the moment they exist. This is the blueprint-level default;
   *  the planned application's actual pair is recorded per project in plan.db (`bsc plan ui`). */
  themeId?: string;
}

/** The SOUND KIT a blueprint pins (#3372, epic #3071 phase 4) — the sounds twin of
 *  {@link BlueprintUiKit}, deliberately the SAME lockfile discipline: the kit is REFERENCED, never
 *  embedded, against the global versioned sound-kit release store
 *  (`~/.base-studio-code/sound-kits/<id>/<version>/`, the Rust `bsc sound release` CLI, #3371).
 *  Exact pins only — no ranges (reproducibility). A new blueprint default-pins the packaged
 *  `bsc/signal` kit ({@link Blueprint.soundKit} set in `addBlueprint`), which resolves against the
 *  store's embedded fallback and so needs no fetch.
 *
 *  NO `themeId` twin: a theme restyles a component kit's tokens, and a sound kit has no token
 *  contract to restyle — its cues ARE the palette. Adding a dead field "for symmetry" would invent
 *  a knob nothing reads. */
export interface BlueprintSoundKit {
  /** Publisher-scoped kit id (e.g. `"bsc/signal"`). */
  id: string;
  /** Exact semver of the pinned artifact (immutable once published). */
  version: string;
  /** sha256 (lowercase hex) of the artifact bytes — the canonical SoundKit object, NOT a wrapper. */
  hash: string;
  /** Typed-gist URL to fetch from when the id@version is missing locally. */
  source?: string;
}

/** A blueprint's DESIGN contribution (#2646, epic #2606) — the categorical dimensions it introduces
 *  that need design-token backing (a `simulation` node-kind, say), plus an optional theme by reference.
 *  Downloading a blueprint RECONCILES this against the local design contract: categories the contract
 *  doesn't define are surfaced (a dedicated confirm-list, 5b) and filled by the generator (#2636), so a
 *  shared blueprint brings its look with NO holes. Deliberately the opposite of embedding: categories
 *  are KEYS (the generator derives on-brand colours), `theme` is a `bsc ui theme` id (never the vars). */
export interface BlueprintDesign {
  /** Categorical keys the blueprint introduces — reconciled against the contract's graph-category group;
   *  any the contract doesn't define is a gap the generator fills (5b). */
  categories?: string[];
  /** Optional theme by reference — a `bsc ui theme` id (mirrors the uiKit pin's `themeId`; absent ⇒ default). */
  theme?: string;
}

export interface Blueprint {
  id: string;
  name: string;
  desc: string;
  sections: BlueprintStage[];
  /** The curated FEATURE LIST this blueprint seeds (#3785) — the raw `features` section content
   *  (`features.md`) captured when a completed project is promoted (`generateBlueprint`). A blueprint
   *  is a goal/domain planning ROUTE (its `sections`/stages) PLUS the features that route builds
   *  (this). Absent ⇒ no seeded features (the blueprint is a bare route); applying one with features
   *  seeds them into the new project's Features stage. */
  features?: string;
  /** Display + provenance metadata (#609). All optional — the Library derives sensible
   *  fallbacks (icon from the name, hue from the id, origin "local", local-only gist). */
  icon?: string;
  /** Accent hue (oklch) for the card/editor icon. */
  h?: number;
  origin?: BlueprintOrigin;
  tags?: string[];
  gist?: BlueprintGist;
  /** How many projects this blueprint has seeded. */
  uses?: number;
  updatedAt?: string;
  /** Blueprint-wide attached skills/knowledge (#636) — applied across every stage,
   *  in addition to each section's own `skills`. Library item ids. */
  skills?: string[];
  /** Blueprint-wide attached MCP servers (#897) — applied across every stage, in addition to
   *  each section's own `mcp`. Server NAMES (the portable ref). */
  mcp?: string[];
  /** The component KIT (#2277) an app seeded from this blueprint is built on — a `bsc ui` kit id
   *  (e.g. `"react-ui"`). Recording it makes every project seeded here a CONSUMER of that kit, so a kit
   *  change fans out to it (the `kit_usage` consumer index self-fills at planning). Absent ⇒ the blueprint
   *  isn't tied to a shared kit (an authoring blueprint, or one that operates on a repo's own UI). */
  kit?: string;
  /** Fleet policy (#1854 Phase b) — the DEFAULT per-stream profile + flow the planner instantiates
   *  when it generates this project type's fleet. A composed sub-model; see {@link FleetPolicy}.
   *  Absent ⇒ today's launch-time defaults apply (byte-identical). */
  fleetPolicy?: FleetPolicy;
  /** The blueprint's own TEAM (#2450) — an embedded org configuration forked from the org library
   *  (or authored blank). A composed sub-model; see {@link BlueprintTeam}. Absent ⇒ no team
   *  authored (today's behavior, byte-identical everywhere). */
  team?: BlueprintTeam;
  /** The UI kit this blueprint pins (#2465) — a lockfile entry referencing an immutable
   *  `id@version` artifact in the global kit store; see {@link BlueprintUiKit}. Absent ⇒ no pin
   *  (existing blueprints are unaffected); a NEW blueprint default-pins the packaged kit. */
  uiKit?: BlueprintUiKit;
  /** The SOUND kit this blueprint pins (#3372) — the same lockfile entry one pillar over, against
   *  the versioned sound-kit release store; see {@link BlueprintSoundKit}. Absent ⇒ no pin
   *  (existing blueprints are unaffected); a NEW blueprint default-pins the packaged `bsc/signal`. */
  soundKit?: BlueprintSoundKit;
  /** The blueprint's DESIGN contribution (#2646) — the categorical keys it introduces + an optional
   *  theme ref; reconciled against the local design contract on download. Absent ⇒ nothing to reconcile
   *  (existing blueprints unaffected). See {@link BlueprintDesign}. */
  design?: BlueprintDesign;
  /** Create (from a pitch) vs operate (against existing repos). Absent ⇒ create. */
  mode?: BlueprintMode;
  /** Catalog metadata: a one-line catalog pitch, the audience it serves, and the share visibility
   *  (used by the gist share/import flow). `tags` doubles as the "best for" catalog tags. */
  pitch?: string;
  audience?: string;
  visibility?: "local" | "private-gist" | "catalog";
}

/** The JSON shape of a built-in blueprint definition (stages/blueprints/*.json): blueprint
 *  metadata + an ordered list of section KEYS (chaining to stages/sections/*.json). The keys
 *  resolve to full section instances via mkStage at load — no blueprint data lives in TS. */
export interface BlueprintDef extends Omit<Blueprint, "sections"> {
  /** Display order within the built-in library. */
  order?: number;
  /** Ordered section refs: a key into STAGE_DEFS + an optional per-blueprint `optional` flag. */
  sections: { key: string; optional?: boolean }[];
}

export interface SectionStatus { locked: boolean; unmet: string[]; satisfied: boolean }

/** Render status of a blueprint section. `na` = not applicable to this project. */
export type StageRenderStatus = "locked" | "in-progress" | "complete" | "na";

/** A blueprint section that isn't satisfied yet — what the user still has to finish. */
export interface IncompleteStage {
  key: string;
  /** The section's display name, straight from the blueprint. */
  name: string;
  /** The section's own gate description (`gate`) — the human "what's left". */
  reason: string;
  /** Locked behind an unfinished dependency vs. simply in progress. */
  status: "locked" | "in-progress";
}

// Shared inline-style constants for the planner focused-pane bodies (#1635).
//
// The bodies under bodies/ are token-styled inline (no CSS modules) and historically each
// re-declared the same handful of style objects. These are the ones that were byte-identical
// across multiple bodies — extracted here so there is a single source of truth.
//
// NOTE: only TRULY-identical style objects live here. ScanViews keeps its own `grpLabel`
// (fontSize 10 / letterSpacing .08em) because it differs from this one (fontSize 9.5 / .06em),
// and the per-body component helpers (Card/Field/Seg/Toggle/…) differ in props + markup between
// bodies and are deliberately NOT consolidated.

import type { CSSProperties } from "react";

/** The mono font token (`var(--mono)`), referenced inline across every planner body. */
export const MONO = "var(--mono)";

/**
 * Uppercase, dim, tracked group/section label — the standard field/section caption used by the
 * Deploy, Source, Integration, and Integrations bodies.
 */
export const grpLabel: CSSProperties = {
  fontFamily: MONO, fontSize: 9.5, color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".06em",
};

/** A small, dim mono caption (hints, inline meta). */
export const monoSm: CSSProperties = { fontFamily: MONO, fontSize: 10, color: "var(--fg-dim)" };

// Hub dir ↔ canonical file map + plan.json bridge.
//
// Pure — no filesystem I/O, no Tauri, no React. Takes the in-memory plan state
// (as held by the Zustand store) and produces the canonical CanonicalFile list
// the sync layer transmits. Also applies a received push back to a HubSnapshot
// so the calling code can update the store.

import type { CanonicalFile, PlanMeta, CanonicalSectionState } from "@/features/planner/lib/plannerCore/types";
import { projectId as mintProjectId } from "@/features/planner/lib/plannerCore/ids";
import { parseSkipped } from "@/features/planner/stages/planTopics";

/** In-memory representation of the plan hub's current state (from the Zustand store). */
export interface HubSnapshot {
  /** Sanitized project title — used to derive projectId on first access. */
  projectTitle: string;
  /** Stable "proj-{hex}" id if already minted; derived from title otherwise. */
  existingProjectId?: string;
  /** Section content keyed by section key (e.g. "goal", "scope"). Only drafted/confirmed. */
  sections: Record<string, string>;
  /** Section keys whose state is "confirmed" (user clicked confirm in the UI). */
  confirmedSections: string[];
  /** Raw issues.json content (undefined if not yet authored). */
  issuesJson?: string;
  /** Raw phases.json content (undefined if not yet authored). */
  phasesJson?: string;
  /** Raw fleet.json content (undefined if not yet authored). */
  fleetJson?: string;
  /** Raw repos.json content (undefined if not yet authored). */
  reposJson?: string;
  /** Raw _skipped.md content (undefined if no sections have been skipped). */
  skippedContent?: string;
}

/** Result of converting a HubSnapshot to the canonical representation. */
export interface CanonicalBuild {
  /** Sorted list of plan files ready for hashing and transmission. */
  files: CanonicalFile[];
  /** The plan metadata (written to / read from plan.json). */
  meta: PlanMeta;
}

/**
 * Convert an in-memory hub snapshot to the canonical file list + plan metadata.
 *
 * Each section becomes a `{key}.md` file. JSON plan files (phases, issues, fleet,
 * repos) are included as-is. Skipped sections are recorded in the sectionStates
 * map as "skipped". plan.json is always included and carries the stable projectId.
 *
 * Sections missing from confirmedSections are treated as "drafted" (they have
 * content but the user hasn't explicitly confirmed them). There is no "surfaced"
 * state in the current desktop model — sections aren't tracked until Claude
 * writes them.
 */
export function hubToCanonical(snap: HubSnapshot): CanonicalBuild {
  const pid = snap.existingProjectId ?? mintProjectId(snap.projectTitle);
  const sectionStates: Record<string, CanonicalSectionState> = {};
  const files: CanonicalFile[] = [];

  for (const [key, content] of Object.entries(snap.sections)) {
    if (!content?.trim()) continue;
    files.push({ relpath: `${key}.md`, content });
    sectionStates[key] = snap.confirmedSections.includes(key) ? "confirmed" : "drafted";
  }

  if (snap.skippedContent?.trim()) {
    files.push({ relpath: "_skipped.md", content: snap.skippedContent });
    for (const { topic } of parseSkipped(snap.skippedContent)) {
      if (topic) sectionStates[topic] = "skipped";
    }
  }

  const jsonEntries: Array<[string, string | undefined]> = [
    ["phases.json",  snap.phasesJson],
    ["issues.json",  snap.issuesJson],
    ["fleet.json",   snap.fleetJson],
    ["repos.json",   snap.reposJson],
  ];
  for (const [relpath, content] of jsonEntries) {
    if (content?.trim()) files.push({ relpath, content });
  }

  const meta: PlanMeta = { projectId: pid, title: snap.projectTitle, sectionStates };
  files.push({ relpath: "plan.json", content: JSON.stringify(meta, null, 2) });
  files.sort((a, b) => a.relpath.localeCompare(b.relpath));

  return { files, meta };
}

/**
 * Apply a push (incoming CanonicalFile list from mobile) onto a HubSnapshot.
 * Full-replace semantics: pushed files overwrite the corresponding local state.
 * Returns a new snapshot — the original is not mutated.
 */
export function applyPush(snap: HubSnapshot, pushed: CanonicalFile[]): HubSnapshot {
  const sections = { ...snap.sections };
  let { existingProjectId, phasesJson, issuesJson, fleetJson, reposJson, skippedContent } = snap;

  for (const { relpath, content } of pushed) {
    if (relpath === "plan.json") {
      try {
        const m = JSON.parse(content) as Partial<PlanMeta>;
        if (typeof m.projectId === "string" && m.projectId) existingProjectId = m.projectId;
      } catch { /* ignore malformed plan.json */ }
    } else if (relpath === "_skipped.md") {
      skippedContent = content;
    } else if (relpath === "phases.json")  { phasesJson  = content; }
    else if (relpath === "issues.json")    { issuesJson  = content; }
    else if (relpath === "fleet.json")     { fleetJson   = content; }
    else if (relpath === "repos.json")     { reposJson   = content; }
    else if (relpath.endsWith(".md") && !relpath.includes("/")) {
      sections[relpath.slice(0, -3)] = content;
    }
  }

  return { ...snap, existingProjectId, sections, phasesJson, issuesJson, fleetJson, reposJson, skippedContent };
}

/** True if a hub-relative path belongs to the synced plan (included in the canonical map). */
export function isPlanFile(relpath: string): boolean {
  if (relpath.includes("/")) return false;  // no subdirectory files
  if (relpath.endsWith(".md")) return true;
  return ["phases.json", "issues.json", "fleet.json", "repos.json", "plan.json"].includes(relpath);
}

// Brief routing (#brief-routes-to-its-target) — decide WHICH pane each `bsc-brief` is delivered to.
//
// The target was always on the wire. `bsc-brief <target>` writes it, `parseCoordLine` reads it back,
// `ReceivedBrief.target` documents it as "director, issuer, or a specific session id", and the fold
// carries it into `CoordState.briefs`. The one thing missing was a consumer: `useDirectorPump` looped
// over director-drive panes and injected every brief into each of them, so a director briefing a
// worker briefed itself and the worker never heard.
//
// This is the pure decision half, modelled on `studioNetworkDrive`'s `authorInjections` — the pump
// stays a thin actuator. Free of React/Tauri so the routing table is unit-testable on its own.

import type { ReceivedBrief } from "@/shared/lib/fleet/coordination.types";

export interface BriefRouteContext {
  /** Panes launched with a director drive — the `director` audience, and where an undeliverable
   *  brief is reported (the director is the actor that can do something about it). */
  directorPanes: string[];
  /** Every pane the app currently has a status for. This is the REACHABLE set: a target that
   *  resolves to nothing here has no session to receive it. */
  knownPanes: string[];
  /** `<paneId>|<key>` entries already injected. */
  surfaced: ReadonlySet<string>;
  /** A pane's session ROLE, for the tier constraint below. Optional so every existing caller and
   *  fixture keeps working unchanged — absent ⇒ no sender is treated as an architect. */
  roleOf?: (paneId: string) => string | undefined;
}

/** The broadcast audiences — every other target names one specific session. */
const DIRECTOR = "director";
const ISSUER = "issuer";

/**
 * Stable per-brief key. **Includes the target**, unlike the original `<from>@<at>`: two briefs sent
 * by one session in the same millisecond to different targets shared a key under the old scheme, so
 * the second was suppressed as already-surfaced and silently never delivered.
 */
export function briefRouteKey(b: Pick<ReceivedBrief, "from" | "at" | "target">): string {
  return `${b.from}@${b.at}@${b.target || DIRECTOR}`;
}

/**
 * Resolve a brief's `target` to the panes that should receive it.
 *
 * Order matters — most specific first, so a project that happens to name a stream "director" cannot
 * hijack the broadcast audience:
 *  1. an EXACT pane id (`studio-code:security`) — what a director reaching one worker writes;
 *  2. a bare stream id (`security`) — resolved by suffix against the known panes, since a pane id is
 *     `<projectKey>:<stream>` and a session addressing a sibling stream has no reason to know the key;
 *  3. `director` / `issuer` — the two broadcast audiences.
 * Anything else resolves to nothing, which the caller reports rather than drops.
 *
 * EVERYTHING EXCEPT THE EXACT PANE ID IS SCOPED TO THE SENDER'S PROJECT (#59). Before, the untargeted
 * default, both broadcast audiences and the bare-stream suffix all matched across EVERY project — so a
 * planner's mid-build update reached a director in an unrelated project and instructed it to open issues
 * and assign work on a board it does not own. It declined; the next one might not.
 *
 * The exact pane id stays deliberately cross-project: `bsc-brief <project>:director` from an architect
 * means THAT director, and a targeted brief must stay targeted.
 *
 * `from` is REQUIRED, not optional. This module's own note records that the architect-reaches-directors
 * rule lost its only enforcement site when the delivery function was deleted — a rule enforced by
 * nothing is how that recurred. A required parameter means a rebuilt delivery cannot route unscoped by
 * simply forgetting to opt in.
 */
export function resolveBriefTarget(target: string, ctx: BriefRouteContext, from: string): string[] {
  const t = (target || "").trim();
  const mine = inProjectOf(from);
  if (!t) return ctx.directorPanes.filter(mine);                     // untargeted ⇒ MY directors
  if (ctx.knownPanes.includes(t)) return [t];                        // 1 · exact pane id (see above)
  const bySuffix = ctx.knownPanes.filter((p) => p.endsWith(`:${t}`) && mine(p));
  if (bySuffix.length > 0) return bySuffix;                          // 2 · bare stream id, MY project
  if (t === DIRECTOR) return ctx.directorPanes.filter(mine);         // 3 · broadcast audiences, scoped
  if (t === ISSUER) return ctx.knownPanes.filter((p) => p.endsWith(`:${ISSUER}`) && mine(p));
  return [];
}

/** The project half of a pane id — everything before the FIRST `:`, since a pane id is
 *  `<projectKey>:<stream>` and a triage pane is `<projectKey>:<repo>:triage`. `""` when there is no
 *  prefix at all. */
function projectOf(paneId: string): string {
  const i = (paneId || "").indexOf(":");
  return i > 0 ? paneId.slice(0, i) : "";
}

/** A predicate for "this pane belongs to the sender's project".
 *
 *  A sender with NO project prefix matches nothing rather than everything. Broadcasting on an
 *  unparseable sender is the exact failure this exists to stop, and an audience of nobody is reported
 *  as undeliverable by the caller — loud and fixable, where a silent cross-project delivery is neither. */
function inProjectOf(from: string): (paneId: string) => boolean {
  const proj = projectOf(from);
  return (paneId) => proj !== "" && projectOf(paneId) === proj;
}

// THE PROMPT ASSEMBLY IS GONE (#coord-prefix-names-the-sender). `briefInjections` and the three
// prompt builders it fed built `[coordinator] ...` strings for a pump that no longer exists — the app
// does not write into a session's stdin at all now, so they were computed by nothing and delivered to
// nobody. `resolveBriefTarget` + `briefRouteKey` survive because they answer routing questions, not
// delivery ones.
//
// CARRY THIS FORWARD IF BRIEF DELIVERY IS EVER REBUILT — it was a rule, not an implementation detail
// (#funnel-generalize-brief-channel), and its only enforcement site went with the deleted function:
//
//   An ARCHITECT reaches DIRECTORS, and nothing else. Apply it to the resolved pane set by
//   INTERSECTING with the director panes, never by replacing them with every director: a
//   `bsc-brief <project>:director` from an architect must still reach exactly that one director, so a
//   targeted brief stays targeted. An architect naming a WORKER resolves to that worker, intersects
//   to empty, and must be reported UNDELIVERABLE — refused loudly, never silently re-routed to a
//   director, which would look like it worked while quietly crossing the tier boundary.

// Pure targeting logic for console broadcast mode.
//
// Broadcast must only ever reach the consoles in the *actively viewed* tab. Pane ids are minted
// from the tab's identity (`paneIdFor` — `man:<tabId>:p<n>` for a manual tab, the minted
// `paneIds[]` for fleet/triage), so we build them strictly from the active tab — never from
// another tab, and never from the legacy positional shape (which a manual tab's PTYs are NOT
// keyed by, so broadcasting positional ids silently hit nothing, #1176). The focused pane (if
// any) self-handles its own keystroke through xterm, so it is excluded to avoid a double-write;
// but only when its index is actually within this tab, otherwise a stale focus index from a
// previously-viewed tab would wrongly exclude (and silently skip) one of this tab's consoles.
import { paneIdFor, type PaneIdentityTab } from "@/app/console/lib/paneIdentity";
import { paneCountForLayout } from "@/app/console/lib/paneStatus";

export interface BroadcastPlan {
  /** Pane ids that should receive the keystroke via pty_broadcast. */
  paneIds: string[];
  /**
   * Whether to preventDefault/stopPropagation. True when no pane in this tab owns
   * focus — nothing else will handle the key, so we both broadcast to every pane
   * and stop the event from landing elsewhere.
   */
  suppressDefault: boolean;
}

export function computeBroadcastTargets(
  tab: PaneIdentityTab & { layout: string },
  activeTabIdx: number,
  focusedPaneIdx: number,
): BroadcastPlan {
  const paneCount = paneCountForLayout(tab.layout);
  // Treat focus as real only when it points at a pane inside this tab.
  const focusedInTab = focusedPaneIdx >= 0 && focusedPaneIdx < paneCount;
  const paneIds: string[] = [];
  for (let i = 0; i < paneCount; i++) {
    if (focusedInTab && i === focusedPaneIdx) continue; // self-handled by xterm
    paneIds.push(paneIdFor(tab, activeTabIdx, i));
  }
  return { paneIds, suppressDefault: !focusedInTab };
}

import type { ConsoleProvider } from "@/app/console/lib/providers/types";

/**
 * The model-agnostic `bsc-agent` runtime (#1078) — our own agent shell that runs on any
 * configured LLM (Anthropic/OpenAI/Gemini/local). It ships as a bundled sidecar resolved via
 * `$BSC_AGENT_BIN` (set per-session in pty_create) and is launched through the `BscAgentAdapter`
 * harness, selected by this provider's id. Not Claude — it skips the `.claude/*` setup paths and
 * instead reads its provider/model/key/permissions from `BSC_AGENT_*` env (wired in TerminalView).
 */
export const bscAgentProvider: ConsoleProvider = {
  id: "bsc-agent",
  displayName: "bsc-agent (any LLM)",
  buildLaunchCmd: () => "bsc-agent",
  isClaude: false,
};

// Coalesced `bsc` reads (#five-callers-one-spawn-for-the-same-plan-read) — many callers, one process.
//
// Every `bsc` call the app makes is a PROCESS LAUNCH. `bsc perf spawns` measured what that costs when one
// read has several independent consumers: `plan list --full` at 113 calls / 57.9s, because five hooks —
// useProjectComplete, useStreamProgress, useFleetHeld, resumeProject and AppBanners — each spawn their own
// process for the same bytes, on their own polling clocks, forever.
//
// This is a KNOWN class here. `bsc project progress` exists precisely so a caller wanting every project's
// progress makes one spawn instead of one per project, and its help records that spawning N processes "has
// repeatedly cost this app whole seconds (#3908 / #3912 / #3944 / #3954)". This is the same shape one level
// up: not N projects, but N callers of one read.
//
// TWO MECHANISMS, and they are not equally strong:
//
//   1. IN-FLIGHT JOIN — unconditionally correct and needs no TTL. Two identical reads happening at the same
//      moment should never be two processes; the second joins the first's promise.
//   2. TTL REUSE — a judgement the CALLER makes. A reading newer than `ttlMs` is served without spawning.
//
// WHAT IS SHARED IS THE RAW STDOUT, NOT A PARSED RESULT — and that is a correctness requirement, not a
// convenience. The first version cached whatever `bscJson` returned, which meant a joiner inherited the
// ORIGINATOR's fallback: `useStreamProgress` reads this list with a `null` fallback and `useProjectComplete`
// with `[]`, so a failed read started by the former handed `null` to the latter, which promptly did
// `.length` on it. The test suite caught it as an unhandled rejection. Sharing the raw bytes and letting
// each caller apply its OWN fallback removes the coupling entirely — and removes the need to guess whether
// a returned value "is" the fallback.
//
// WHY OPT-IN, NEVER BLANKET. A general cache over `bsc` would be wrong: writes must never be cached, and
// some reads must be fresh. The caller passes the TTL, so the staleness each site accepts is visible at
// that site rather than buried in a helper.
import { bsc } from "@/shared/lib/core/bsc";

interface Entry {
  /** The in-flight read, if one is running — what a second caller joins. Resolves to RAW stdout. */
  inflight?: Promise<string>;
  /** The last SUCCESSFUL stdout and when it landed. */
  out?: string;
  at?: number;
}

/** Keyed by project + the whole argument list: the same command for two projects is two different reads,
 *  and `plan list` is not `plan list --full`. */
const cache = new Map<string, Entry>();

const keyOf = (projectKey: string | null, args: string[]) => `${projectKey ?? ""} ${args.join(" ")}`;

/**
 * The shared raw read. THROWS on failure — deliberately, so each caller decides what a failure means to it
 * rather than inheriting whatever the first caller decided.
 */
async function sharedRaw(projectKey: string | null, args: string[], ttlMs: number): Promise<string> {
  const key = keyOf(projectKey, args);
  const entry = cache.get(key) ?? {};

  if (entry.at !== undefined && entry.out !== undefined && Date.now() - entry.at < ttlMs) {
    return entry.out;
  }
  if (entry.inflight) return entry.inflight;

  const inflight = bsc(projectKey, args)
    .then((raw) => {
      const out = raw.trim();
      cache.set(key, { out, at: Date.now() });
      return out;
    })
    .catch((e) => {
      // A failed read leaves NOTHING behind: a transient failure must not pin an answer for the window.
      cache.delete(key);
      throw e;
    });

  cache.set(key, { ...entry, inflight });
  return inflight;
}

/**
 * Read `bsc … --json` alongside other callers, spawning at most one process per `ttlMs` window.
 *
 * `fallback` is this CALLER's own — returned when the read fails or produces nothing, exactly as
 * {@link import("@/shared/lib/core/bsc").bscJson} does, and never shared with another caller.
 *
 * @param ttlMs How stale an answer this caller will accept. Pass a value it genuinely tolerates: a hook
 *              polling every 20s already accepts 20s-old data, so a 20s TTL costs it nothing and removes
 *              four process launches. `0` disables reuse and leaves only the in-flight join, which cannot
 *              serve stale data at all.
 */
export async function bscJsonShared<T>(
  projectKey: string | null,
  args: string[],
  fallback: T,
  ttlMs: number,
): Promise<T> {
  try {
    const out = await sharedRaw(projectKey, args, ttlMs);
    return out ? (JSON.parse(out) as T) : fallback;
  } catch {
    return fallback;
  }
}

/** Drop every cached reading — for tests, and for a caller that knows the underlying store just changed. */
export function clearBscShared(): void {
  cache.clear();
}

// The `bsc` bridge (epic #2114) — the UI drives the SAME complete `bsc` interaction set the project
// planner + agents use from a live session's shell, over ONE shared store surface, via the generic
// `bsc` Tauri command (#2115). This replaces the parallel, hand-maintained per-verb `plan_*`/`data_*`
// Tauri commands: `bsc plan …` / `bsc data …` route to the bundled binary's subcommand, and the Rust
// bridge wires the project's stores ($BSC_PLAN_DB/$BSC_DATA_DB from `projectKey`) + the global skills
// store, so the UI reaches parity with the planner — the user can make the same actions.
//
// The `bsc` subcommands emit JSON to stdout (structured reads) and return the same serde shapes the
// old per-verb commands did (both wrap the same store crates), so a migrated read parses to the exact
// same type. Kept React-free so it's unit-testable, mirroring safeInvoke.ts.

import { invoke } from "@tauri-apps/api/core";
import { startInvokeTimer, bscLabel } from "@/shared/lib/core/invokeTiming";

/**
 * Run the bundled `bsc` CLI with `args` against `projectKey`'s stores; resolves to its raw stdout.
 * `projectKey` `null` (or empty) scopes to global-only subcommands (e.g. `bsc skill …`). Rejects when
 * the bundled binary can't be resolved or `bsc` exits non-zero (its stderr becomes the rejection).
 * The one choke point for every bsc-bridge call, so timing it here (#3626, labelled by subcommand)
 * covers `bscJson`/`bscRun`/`bscWrite` — a slow `bsc <sub> <verb>` gets a `[invoke]` app-log line.
 */
export async function bsc(projectKey: string | null, args: string[], stdin?: string): Promise<string> {
  const done = startInvokeTimer(bscLabel(args), "bsc");
  try {
    // Only include `stdin` when given, so read/positional calls keep their exact 2-key payload.
    return await invoke<string>("bsc", stdin === undefined ? { projectKey, args } : { projectKey, args, stdin });
  } finally {
    done();
  }
}

/**
 * Run `bsc` and JSON-parse its stdout as `T`; returns `fallback` when the output is empty (a void
 * verb) OR the invoke rejected (bridge/binary absent, or a project's plan.db not created yet). Mirrors
 * safeInvoke's degrade-gracefully contract, so a not-yet-existing store yields the fallback rather than
 * throwing — the same behavior the per-command `invoke(...).catch(() => fallback)` sites had.
 */
export async function bscJson<T>(projectKey: string | null, args: string[], fallback: T): Promise<T> {
  try {
    const out = (await bsc(projectKey, args)).trim();
    return out ? (JSON.parse(out) as T) : fallback;
  } catch {
    return fallback;
  }
}

/** Fire a `bsc` write/void verb and swallow any error (the bridge/store may be absent). */
export async function bscRun(projectKey: string | null, args: string[]): Promise<void> {
  try {
    await bsc(projectKey, args);
  } catch {
    /* bridge/store absent — ignore, matching the old per-command catch sites */
  }
}

/**
 * Drive a `bsc … set`/`add` verb whose JSON body is read from the child's **stdin** (#2123) — the
 * write analogue of `bscRun` for the CLI verbs that take a manifest/object on stdin (e.g.
 * `bsc plan deps set`, `bsc plan issue add`). Serializes `body` to JSON and feeds it in; swallows any
 * error like the other void helpers.
 */
export async function bscWrite(projectKey: string | null, args: string[], body: unknown): Promise<void> {
  try {
    await bsc(projectKey, args, JSON.stringify(body));
  } catch {
    /* bridge/store absent — ignore */
  }
}

/// Bubble sort — repeatedly swap adjacent out-of-order pairs; stop early once a pass makes no swap.
pub fn bubble_sort<T: Ord + Clone>(xs: &[T]) -> Vec<T> {
    let mut out = xs.to_vec();
    let n = out.len();
    for end in (1..n).rev() {
        let mut swapped = false;
        for i in 0..end {
            if out[i] > out[i + 1] {
                out.swap(i, i + 1);
                swapped = true;
            }
        }
        if !swapped {
            break;
        }
    }
    out
}

// image / video-frame renderer (#581 PV-canvas).
//
// Blits the newest chunk to a persistent <canvas> element in the container. No iframe
// needed — images are safe host-side. Each update() call draws over the previous frame;
// the canvas stays mounted across updates with zero re-renders.
//
// Payload shape: { dataUrl: string; width?: number; height?: number }
//   dataUrl — a data: URI (JPEG, PNG, WebP, etc.) or an object URL.
//   width / height — optional natural dimensions hint; canvas auto-sizes to the image.

import type { PreviewRenderer, RendererHandle } from '@/features/planner/preview/registry';
import type { RenderableChunk, PreviewStatus } from '@/features/planner/preview/types';

type CanvasPayload = { dataUrl: string; width?: number; height?: number };

function createCanvasRenderer(): PreviewRenderer {
  return {
    kind: ['image', 'video-frame'],

    mount(container: HTMLElement, initial: RenderableChunk): RendererHandle {
      const canvas = document.createElement('canvas');
      canvas.style.cssText = 'display:block;width:100%;height:100%;object-fit:contain;background:#0d0d0f';
      container.style.cssText = 'display:flex;flex:1;min-height:0';
      container.appendChild(canvas);

      const ctx = canvas.getContext('2d');
      let statusCb: ((s: PreviewStatus) => void) | undefined;

      function blit(chunk: RenderableChunk) {
        const p = chunk.payload as CanvasPayload | null;
        if (!p?.dataUrl || !ctx) return;
        const img = new Image();
        img.onload = () => {
          canvas.width = p.width ?? img.naturalWidth;
          canvas.height = p.height ?? img.naturalHeight;
          ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
          statusCb?.({ status: 'ready' });
        };
        img.onerror = () => {
          statusCb?.({ status: 'error', message: `failed to load image: ${p.dataUrl.slice(0, 60)}` });
        };
        img.src = p.dataUrl;
      }

      blit(initial);

      const handle: RendererHandle = {
        update: blit,
        onStatus(cb) { statusCb = cb; },
        teardown() {
          if (container.contains(canvas)) container.removeChild(canvas);
        },
      };
      return handle;
    },
  };
}

export const canvasRenderer = createCanvasRenderer();

// captureFrame (#2623 slice 5b) — screenshot the running preview for the reviewer. The web preview is a
// cross-origin iframe (localhost:PORT ≠ the app origin), so its canvas is TAINTED — JS can't read those
// pixels with html2canvas / drawImage(iframe). `getDisplayMedia` reads the actual RENDERED pixels at the
// OS level (untainted), which also means it captures a NATIVE preview window (the user shares that
// window) — one capture path for every PreviewSource kind, and zero dependencies (WebView2 supports it).
//
// The DOM-heavy grab (getDisplayMedia + <video> + canvas) isn't exercised in jsdom; the pure guards
// (availability + track teardown) are unit-tested, and the grab itself is runtime-verified.

/** Whether screen capture is available in this webview (feature-detect before offering the action). */
export function screenCaptureAvailable(): boolean {
  return typeof navigator !== "undefined" && !!navigator.mediaDevices?.getDisplayMedia;
}

/** Start a display-capture stream — prompts the user once to pick the window/screen to review. Reused
 *  across captures (kept by the caller) so the picker isn't shown on every shot. */
export async function startPreviewCapture(): Promise<MediaStream> {
  if (!screenCaptureAvailable()) {
    throw new Error("Screen capture isn't available here — can't grab a preview shot to review.");
  }
  return navigator.mediaDevices.getDisplayMedia({ video: { frameRate: 1 }, audio: false });
}

/** Grab the stream's current frame as a `data:image/png;base64,…` URL (drawn through a `<video>` +
 *  `<canvas>`; the frame is untainted since it came from screen capture). */
export async function grabFrame(stream: MediaStream): Promise<string> {
  if (!stream.getVideoTracks()[0]) throw new Error("capture stream has no video track");
  const video = document.createElement("video");
  video.srcObject = stream;
  video.muted = true;
  await video.play();
  if (video.readyState < 2) {
    await new Promise<void>((resolve) => { video.onloadeddata = () => resolve(); });
  }
  const w = video.videoWidth, h = video.videoHeight;
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("no 2d canvas context for the capture");
  ctx.drawImage(video, 0, 0, w, h);
  video.pause();
  video.srcObject = null;
  return canvas.toDataURL("image/png");
}

/** Stop every track of a capture stream (ends the OS "sharing" indicator). Safe on null. */
export function stopCapture(stream: MediaStream | null): void {
  stream?.getTracks().forEach((t) => t.stop());
}

// Triage session continuity ("begin where we left off").
//
// A triage session writes a short "where we left off" note via the `bsc-checkpoint`
// shell helper, which overwrites a per-repo *checkpoint document* in the unified
// store (plain file — no Tauri IPC). At the next triage launch the checkpoint is
// composed onto the triage prompt so the agent resumes with that context.
//
// Pure logic only; the wiring lives in the store (assigns the per-pane checkpoint
// doc), TerminalView (composes at launch), and pty_create (env + helper injection).

/** Heading the previous session's checkpoint is appended under, in the next prompt. */
export const CHECKPOINT_HEADING = "# Where we left off (from your previous session)";

/**
 * Compose the prompt baked into a triage launch: the base triage prompt, plus —
 * when a prior session left a non-empty checkpoint — that checkpoint under a clear
 * heading so the agent resumes with it. Returns `base` unchanged when there's no
 * checkpoint (first run, or it was never written).
 *
 * @param base the triage prompt (verbatim TRIAGE_PROMPT or a resolved doc).
 * @param checkpoint the prior session's checkpoint text, or null/undefined/empty.
 */
export function composeStartupPrompt(base: string, checkpoint: string | null | undefined): string {
  const note = (checkpoint ?? "").trim();
  if (!note) return base;
  return `${base}\n\n${CHECKPOINT_HEADING}\n\n${note}`;
}

/**
 * Unified-store relpath for a repo's triage checkpoint document. `sanitizedKey` is
 * the on-disk project folder (sanitize_project_key); `repo` is the full name
 * (owner/name) — only the name segment is used, slugged to a filesystem-safe stem.
 * Mirrors {@link scriptDocRelpath}'s `projects/{key}/prompts/…` layout so it lands
 * beside the planner-authored startup scripts.
 */
export function checkpointDocRelpath(sanitizedKey: string, repo: string): string {
  const name = (repo.split("/").pop() || repo).trim();
  const slug = (name.replace(/[^A-Za-z0-9._-]/g, "-") || "repo").toLowerCase();
  return `projects/${sanitizedKey}/prompts/${slug}-checkpoint.md`;
}

/**
 * Unified-store relpath for a fleet *agent's* checkpoint document, keyed by the
 * agent/stream id rather than the repo — so two agents sharing one repo clone keep
 * separate "where we left off" notes instead of clobbering each other. `agentId` is
 * a stream id (already slug-like); it is re-slugged defensively.
 */
export function agentCheckpointDocRelpath(sanitizedKey: string, agentId: string): string {
  const slug = (agentId.replace(/[^A-Za-z0-9._-]/g, "-") || "agent").toLowerCase();
  return `projects/${sanitizedKey}/prompts/${slug}-checkpoint.md`;
}

// Discovery classification signal types (#1395).
//
// The Discovery phase characterizes a project into a small set of SIGNALS. These types describe the
// shape of that signal set; `blueprints.ts` carries a `ClassificationSignals` on a blueprint. Pure
// (no React / store / Tauri).

export type Lifecycle = "greenfield" | "transform" | "harden" | "maintain";
export type Workspace = "ui" | "cli" | "api" | "service" | "library" | "data";
export type ServiceTopology = "none" | "split" | "combine";
export type DeployKind = "none" | "static" | "serverless" | "container" | "service";

/** Discovery's classification output (#1395) — the project's lifecycle, surfaces, and a few counts.
 *  Planner-set as it learns, plus counts derived from plan state. Carried on a blueprint. */
export interface ClassificationSignals {
  lifecycle: Lifecycle;
  /** ⊆ {ui, cli, api, service, library, data} — what the project exposes. */
  surfaces: Workspace[];
  provenance: "new" | "existing";
  migration: boolean;
  dataModel: boolean;
  serviceTopology: ServiceTopology;
  deploy: DeployKind;
  compliance: boolean;
  // derived from plan state:
  featureCount: number;
  repoCount: number;
  streamCount: number;
}

// Project classification (#3783/#3784) — the planner's discovery output that shapes the plan:
// which UI surface the `ui` stage renders, and which optional stages (source / mcp / skills) the
// project actually needs. Written by the planner during discovery via `bsc plan classify set`,
// polled into the store, and read by the UI-stage body + the stage-visibility signals.
//
// Every field is OPTIONAL: an unclassified project (the planner hasn't run `classify` yet) coerces
// to `{}`, and each read site applies its own non-regressing default (uiMode → "custom", the
// needs-flags → their stage's prior default). So adding classification never hides a pane that
// showed before the planner classified.

/** The two UI-stage surfaces (#3783). "custom" = the in-app designer preview (PreviewPaneShell —
 *  the navigable shell the designer commissions); "external" = the Claude-Design drop-files intake
 *  (FileIntakePane).
 *
 *  Only meaningful when {@link UiSystem} is "studio" — it says where the DESIGNS come from, not what
 *  renders them (#4115). */
export type UiMode = "custom" | "external";

/** Where one class of a project's artifacts comes from (#4115) — `studio` = OUR data-driven stores,
 *  `own` = the project's own stack. One shared vocabulary for every `*System` axis, so the answer
 *  reads the same whichever surface is being asked about.
 *
 *  **These axes are a security boundary, not a routing preference.** `studio` means our host TAKES IN
 *  and runs the project's artifacts — LLM-authored code, the same trust class the Design Studio's
 *  opaque-origin sandbox was chosen for (#2824). Both surfaces execute it:
 *
 *  - **UI** — component/app code rendered in an iframe. `ComponentPreviewFrame` runs it at an OPAQUE
 *    origin; the Glance frame still passes `allow-same-origin`, which leaves `parent.__TAURI_INTERNALS__`
 *    (and through it the whole IPC surface) reachable from generated code — #3862, open.
 *  - **Algorithms** — stored `vizCode` compiled with `new Function` and executed, confined to a
 *    dedicated Web Worker with no DOM and no app state since #3233 (`vizWorker.ts`).
 *
 *  So the pair answers *"does our process run this project's code at all?"* — isolate-before-render is
 *  only required, and only meaningful, where the answer is `studio`. Claiming `studio` for a project we
 *  never host wastes the isolation; claiming `own` for one we DO host silently drops it. */
export type SystemSource = "studio" | "own";

/** The valid {@link SystemSource} tokens, shared by every `*System` axis. Mirrored by `SYSTEM_SOURCES`
 *  in `crates/plandb/src/validate.rs`, which rejects an unknown token at `bsc plan classify set` —
 *  keep the two in lockstep or the planner can write a value the app cannot read. */
export const SYSTEM_SOURCES: SystemSource[] = ["studio", "own"];

/** WHO RENDERS this project's UI at runtime — a separate axis from {@link UiMode}, because the two
 *  are orthogonal:
 *
 *  |  | designs generated in-app | designs brought by the user |
 *  |---|---|---|
 *  | **renders from our graph** | `studio` + `custom` | `studio` + `external` |
 *  | **project owns rendering** | `own` + `custom` | `own` + `external` |
 *
 *  - `studio` — the component graph IS the render source, so the build/publish pipeline, the host API,
 *    per-node analytics (#3809) — and the render isolation above — all apply.
 *  - `own` — the project brings or keeps its own UI stack (Material UI, shadcn, an existing React
 *    codebase). None of the above applies to it.
 *
 *  `uiMode: "external"` is NOT this: it still means OUR pipeline ingests the user's design files and
 *  produces OUR shell. Without this axis the planner designs a graph-rendered shell for a project that
 *  will never render one, and the fleet is told to build against a contract the project does not use —
 *  the common case for an existing codebase (`lifecycle: "transform"`, already the default there). */
export type UiSystem = SystemSource;

/** WHERE THIS PROJECT'S ALGORITHMS COME FROM — the twin of {@link UiSystem}, and the other half of the
 *  executed surface (#4115).
 *
 *  - `studio` — the algorithms knowledge graph is the source: the librarian curates them, workers fetch
 *    them with `bsc graph impl get`, and their stored `vizCode` is COMPILED AND RUN by our host to drive
 *    the visualizations.
 *  - `own` — the project writes its own computation. Nothing is fetched from the graph and nothing of
 *    the project's is executed here.
 *
 *  Paired with `uiSystem` because the two studios split the whole artifact surface — the planner already
 *  routes on exactly this line ("a component is UI (designer, `bsc ui`); an algorithm is computation
 *  (librarian, `bsc graph impl`)"). Asking only about the UI would leave the executed half of the surface
 *  unstated, which is the more dangerous half to be wrong about: it runs code rather than rendering it. */
export type AlgorithmSystem = SystemSource;

/** The project's APPLICATION ARCHITECTURE (#3802/#3784) — what KIND of app it is, the axis the
 *  Projects list facets by AND the axis that selects which stages run (#3784). A flat taxonomy
 *  grounded in the deploy model (cloud `workload` + local `localKind`): a general application, a
 *  desktop/mobile app, a backend API, serverless functions, a static site, a CLI tool, a published
 *  library, or an MCP server. Unset ⇒ read as "application". */
export type AppType =
  | "application" | "desktop" | "mobile" | "api" | "serverless" | "static" | "cli" | "library" | "mcp-server";

/** The valid `AppType` tokens, for the coerce below + facet iteration. */
export const APP_TYPES: AppType[] = ["application", "api", "serverless", "static", "desktop", "mobile", "cli", "library", "mcp-server"];

/** The project's LIFECYCLE INTENT (#3784) — what this planning run is FOR. Discovered by the
 *  planner (existing repos to restructure ⇒ transform; from a pitch ⇒ greenfield; …) rather than
 *  chosen up front: lifecycle left the blueprint model in #3785, so discovery is its only home.
 *  Unset ⇒ read as "greenfield", the create-a-project default — see {@link lifecycleOf}, and note
 *  that DISPLAY must not apply that default (#4062).
 *
 *  `harvest` (#4062) — the project exists to EXTRACT DATA FROM SOURCES: pulling an existing system's
 *  data out, rather than restructuring code (`transform`) or keeping something running (`maintain`).
 *  The name is the app's established one for exactly this shape — `bsc ui harvest`, algorithm harvest,
 *  both "extract from what already exists". */
export type Lifecycle = "greenfield" | "transform" | "harden" | "maintain" | "harvest";

/** The valid `Lifecycle` tokens, for the coerce below. Mirrored by `LIFECYCLES` in
 *  `crates/plandb/src/validate.rs`, which rejects an unknown token at `bsc plan classify set` —
 *  keep the two in lockstep or the planner can write a value the app cannot read. */
export const LIFECYCLES: Lifecycle[] = ["greenfield", "transform", "harden", "maintain", "harvest"];

/** The app types that carry a USER INTERFACE — the ones for which the `ui` stage is meaningful.
 *  Everything else (an API, serverless functions, a CLI, a library, an MCP server) has no screens
 *  to design, so the UI stage does not apply to it (#3784). */
const UI_BEARING: AppType[] = ["application", "desktop", "mobile", "static"];

export interface ClassifyConfig {
  /** Which surface the `ui` stage renders. Unset → the body defaults to "custom". */
  uiMode?: UiMode;
  /** Who renders this project's UI at runtime (#4115). Unset → read as "studio", today's behaviour
   *  for every existing project — so adding the axis changes nothing until a planner sets it. */
  uiSystem?: UiSystem;
  /** Where this project's algorithms come from (#4115) — the twin of `uiSystem`, covering the other
   *  half of the surface our host executes. Unset → read as "studio", same non-regressing rule. */
  algorithmSystem?: AlgorithmSystem;
  /** The project's application architecture (#3802/#3784). Unset → read as "application". */
  appType?: AppType;
  /** The project's lifecycle intent (#3784). Unset → read as "greenfield". */
  lifecycle?: Lifecycle;
  /** A desk-research market assessment is worth doing → show the `market` stage (#3806). */
  needsMarket?: boolean;
  /** The project connects to an external system → show the `source` stage. */
  needsSource?: boolean;
  /** The project uses MCP servers → show the `mcps` stage. */
  needsMcp?: boolean;
  /** The project needs attached skills → show the `skills` stage. */
  needsSkills?: boolean;
  /** The project needs cron automations → show the `automations` stage. */
  needsAutomations?: boolean;
}

/** Coerce a `bsc plan classify get` blob into a typed config — a light structural check (the CLI
 *  validates hard at write). A non-object reads as null; unknown/mistyped fields are dropped, so a
 *  partial blob (e.g. only `uiMode`) coerces cleanly. */
export function coerceClassifyConfig(raw: unknown): ClassifyConfig | null {
  if (typeof raw !== "object" || raw === null) return null;
  const r = raw as Record<string, unknown>;
  const cfg: ClassifyConfig = {};
  if (r.uiMode === "custom" || r.uiMode === "external") cfg.uiMode = r.uiMode;
  if (typeof r.uiSystem === "string" && (SYSTEM_SOURCES as string[]).includes(r.uiSystem)) cfg.uiSystem = r.uiSystem as UiSystem;
  if (typeof r.algorithmSystem === "string" && (SYSTEM_SOURCES as string[]).includes(r.algorithmSystem)) cfg.algorithmSystem = r.algorithmSystem as AlgorithmSystem;
  if (typeof r.appType === "string" && (APP_TYPES as string[]).includes(r.appType)) cfg.appType = r.appType as AppType;
  if (typeof r.lifecycle === "string" && (LIFECYCLES as string[]).includes(r.lifecycle)) cfg.lifecycle = r.lifecycle as Lifecycle;
  if (typeof r.needsMarket === "boolean") cfg.needsMarket = r.needsMarket;
  if (typeof r.needsSource === "boolean") cfg.needsSource = r.needsSource;
  if (typeof r.needsMcp === "boolean") cfg.needsMcp = r.needsMcp;
  if (typeof r.needsSkills === "boolean") cfg.needsSkills = r.needsSkills;
  if (typeof r.needsAutomations === "boolean") cfg.needsAutomations = r.needsAutomations;
  return cfg;
}

/** The project's app type, with the unclassified default applied. */
export function appTypeOf(cfg: ClassifyConfig | undefined | null): AppType {
  return cfg?.appType ?? "application";
}

/** The project's lifecycle intent, with the unclassified default applied. */
export function lifecycleOf(cfg: ClassifyConfig | undefined | null): Lifecycle {
  return cfg?.lifecycle ?? "greenfield";
}

/** Who renders this project's UI, with the unclassified default applied (#4115).
 *
 *  Unset reads as "studio" — today's behaviour for every project that exists — so the axis is
 *  non-regressing by construction and needs no migration or backfill. */
export function uiSystemOf(cfg: ClassifyConfig | undefined | null): UiSystem {
  return cfg?.uiSystem ?? "studio";
}

/** Where this project's algorithms come from, with the unclassified default applied (#4115). */
export function algorithmSystemOf(cfg: ClassifyConfig | undefined | null): AlgorithmSystem {
  return cfg?.algorithmSystem ?? "studio";
}

/** Does this project render from OUR component graph (#4115)? The gate for everything that only
 *  applies to studio-rendered projects — kit pinning, the graph vocabulary in worker context, the
 *  build/publish pipeline, per-node analytics (#3809), and the render isolation the preview frames owe
 *  LLM-authored code (#2824/#3862).
 *
 *  Deliberately a predicate rather than call sites comparing strings: the consumers land across
 *  slices 3-5, and they should all ask one question. */
export function rendersFromStudio(cfg: ClassifyConfig | undefined | null): boolean {
  return uiSystemOf(cfg) === "studio";
}

/** Does this project's computation come from OUR algorithms graph (#4115)? The twin gate — the
 *  librarian, `bsc graph impl` in worker context, and the sandboxed `vizCode` execution (#3233). */
export function computesFromStudio(cfg: ClassifyConfig | undefined | null): boolean {
  return algorithmSystemOf(cfg) === "studio";
}

/** Does our HOST take in and run any of this project's artifacts (#4115)? True when EITHER system axis
 *  is `studio` — the UI half is rendered in a frame, the algorithm half is compiled and executed.
 *
 *  This is the isolate-before-render question, and it is deliberately an OR: isolation is owed if any
 *  one surface hosts project code, and a project that owns its UI can still draw its algorithms from the
 *  graph. Reading only `uiSystem` would answer it wrongly for exactly that project — and the algorithm
 *  half is the more dangerous one to get wrong, since it runs code rather than rendering it. */
export function hostRunsProjectArtifacts(cfg: ClassifyConfig | undefined | null): boolean {
  return rendersFromStudio(cfg) || computesFromStudio(cfg);
}

/** Does this project have screens to design? Drives whether the `ui` stage applies (#3784).
 *
 *  An UNCLASSIFIED project reads as "application" ⇒ true, so turning this on never hides a UI
 *  stage that showed before the planner classified — the same non-regressing rule every other
 *  classification read site follows. */
export function appTypeHasUi(cfg: ClassifyConfig | undefined | null): boolean {
  return UI_BEARING.includes(appTypeOf(cfg));
}

/** Project the classification into the flat gate-signal bag (#3784) — one boolean per app type
 *  (`appType:api`, `appType:mcp-server`, …) and per lifecycle (`lifecycle:transform`, …), plus the
 *  derived `hasUserInterface`.
 *
 *  Exposing the taxonomy as signals rather than a single string is what the {@link
 *  import("../stages/stageGate").PlanSignals} bag supports (numbers/booleans only) — and it lets a
 *  cloud-distributed stage key its `appliesWhen` on an app type without the app shipping code for it. */
export function classifySignals(cfg: ClassifyConfig | undefined | null): Record<string, boolean> {
  const appType = appTypeOf(cfg);
  const lifecycle = lifecycleOf(cfg);
  const uiSystem = uiSystemOf(cfg);
  const algorithmSystem = algorithmSystemOf(cfg);
  const out: Record<string, boolean> = {
    hasUserInterface: appTypeHasUi(cfg),
    // #4115: exposed as signals so a stage's `appliesWhen` can key on them — a studio-only stage
    // should not run for a project that owns that half of its stack.
    rendersFromStudio: rendersFromStudio(cfg),
    computesFromStudio: computesFromStudio(cfg),
    hostRunsProjectArtifacts: hostRunsProjectArtifacts(cfg),
  };
  for (const t of APP_TYPES) out[`appType:${t}`] = t === appType;
  for (const l of LIFECYCLES) out[`lifecycle:${l}`] = l === lifecycle;
  for (const s of SYSTEM_SOURCES) out[`uiSystem:${s}`] = s === uiSystem;
  for (const s of SYSTEM_SOURCES) out[`algorithmSystem:${s}`] = s === algorithmSystem;
  return out;
}

// The algorithm-kind classifier (#3210, epic #3209) — the heuristic that infers an algorithm's
// MANIPULATION kind (`sort`/`search`/`traversal`/`accumulate`) from its name/id/tags (+ a light code
// hint). This is the SAFETY NET: the creator SHOULD type an algorithm at creation (`bsc graph impl set
// --kind`), and this fills the gap for untyped impls so they still animate. `resolveKind` (in the viz
// registry) prefers the assigned `kind` and only falls back here.
//
// A Rust twin lives in `bsc-graph` for the `bsc graph doctor` / `--fix` scan (#3212); keep the two aligned
// (the graphHealth twin pattern). Deliberately conservative: an unrecognized algorithm returns `null`
// (no false type) rather than guessing.
import type { AlgoImpl, AlgoKind } from "@/features/algorithms/lib/knowledge";

/** The signals we read — name + id (hyphenated ids tokenize the words) + tags + code. */
export type Classifiable = Pick<AlgoImpl, "name" | "id" | "code" | "tags">;

/**
 * Infer an algorithm's kind from its name/id/tags, else a light code hint, else `null`. Ordered so
 * ambiguous names disambiguate: **traversal** first (a `…-first-search` / bfs / dfs is a traversal, not a
 * search), then the exact **sort**, then **search**, then **accumulate**.
 */
export function classifyKind(impl: Classifiable): AlgoKind | null {
  const hay = `${impl.name} ${impl.id} ${(impl.tags ?? []).join(" ")}`.toLowerCase();
  const has = (...words: string[]) => words.some((w) => hay.includes(w));

  if (has("bfs", "dfs", "traverse", "traversal", "walk", "breadth-first", "depth-first")) return "traversal";
  if (has("sort")) return "sort";
  if (has("transpose", "rotate", "reflect", "transform", "flip", "mirror")) return "transform";
  if (has("search", "find", "lookup", "bisect")) return "search";
  if (has("fib", "factorial", "prefix-sum", "prefixsum", "accumulate", "cumulative", "reduce", "scan")) return "accumulate";

  // Light code-pattern fallbacks for un-obvious names (kept minimal — names carry most of the signal).
  const code = (impl.code ?? "").toLowerCase();
  if (/\bmid\b/.test(code) && /\b(lo|low|hi|high)\b/.test(code)) return "search"; // lo/hi/mid bisection
  if (/\bswap\b/.test(code) || /\[[^\]]+\],\s*[a-z0-9_[\].]+\s*=\s*\[/.test(code)) return "sort"; // element swap

  return null;
}

// One-shot LLM completion (#624; provider-agnostic since #1085) — a thin wrapper over
// the llm_complete Tauri command for features that need a single structured/short reply
// (the blueprint assistant's prose, the LLM grader, the cleanup verifier, the preview
// reviewer, …) rather than a streaming session. Routed through the active LlmConfig
// (provider + model + key), so it works on any provider. Returns the concatenated text
// blocks; throws on missing key / network (callers fall back as appropriate).

import { invoke } from "@tauri-apps/api/core";
import { type LlmConfig, hasLlmKey } from "@/shared/lib/core/llmConfig";

interface LlmReply { content: { type: string; text?: string }[] }

/** Join the text blocks of an llm_complete reply into one trimmed string. */
function replyText(res: LlmReply): string {
  return (res.content ?? []).filter((b) => b.type === "text").map((b) => b.text ?? "").join("\n").trim();
}

export async function oneShotComplete(cfg: LlmConfig, system: string, user: string): Promise<string> {
  if (!hasLlmKey(cfg)) throw new Error(`No API key configured for ${cfg.provider}. Add it in Settings → Integrations.`);
  const res = await invoke<LlmReply>("llm_complete", {
    messages: [{ role: "user", content: user }], system, tools: [],
    apiKey: cfg.apiKey, provider: cfg.provider, model: cfg.model, baseUrl: cfg.baseUrl,
  });
  return replyText(res);
}

/** A captured image to send with a vision prompt — a `data:<mime>;base64,<…>` URL. */
export type ImageDataUrl = string;

/** Providers whose Messages API accepts image content blocks in the shape we build below. Claude Code
 *  only ever speaks Anthropic; OpenAI's chat API takes `image_url`. Gemini/local use different shapes we
 *  don't build here, so vision falls back to a clear error rather than silently dropping the image. */
export function providerSupportsVision(p: LlmConfig["provider"]): boolean {
  return p === "anthropic" || p === "openai";
}

/** Split a `data:<mime>;base64,<data>` URL into its media type + base64 payload. */
function splitDataUrl(url: ImageDataUrl): { mediaType: string; data: string } {
  const m = /^data:([^;]+);base64,(.*)$/s.exec(url);
  if (!m) throw new Error("vision image must be a base64 data URL");
  return { mediaType: m[1], data: m[2] };
}

/** Build the provider-specific `content` array (a text block + one block per image) for a vision message.
 *  Anthropic → `{type:"image",source:{type:"base64",…}}`; OpenAI → `{type:"image_url",image_url:{url}}`. */
function visionContent(provider: LlmConfig["provider"], text: string, images: ImageDataUrl[]): unknown[] {
  const blocks: unknown[] = [{ type: "text", text }];
  for (const url of images) {
    if (provider === "openai") {
      blocks.push({ type: "image_url", image_url: { url } });
    } else {
      const { mediaType, data } = splitDataUrl(url);
      blocks.push({ type: "image", source: { type: "base64", media_type: mediaType, data } });
    }
  }
  return blocks;
}

/**
 * One-shot MULTIMODAL completion — `text` plus one or more screenshots, for the preview reviewer (#2623)
 * and any future see-the-screen feature. Builds provider-appropriate image content blocks and sends them
 * through the same `llm_complete` path (which forwards `messages` verbatim to the provider's API).
 * @throws when no key is configured, or the active provider can't take images (see {@link providerSupportsVision}).
 */
export async function oneShotVision(
  cfg: LlmConfig,
  system: string,
  text: string,
  images: ImageDataUrl[],
): Promise<string> {
  if (!hasLlmKey(cfg)) throw new Error(`No API key configured for ${cfg.provider}. Add it in Settings → Integrations.`);
  if (!providerSupportsVision(cfg.provider)) {
    throw new Error(`Image review needs Claude or OpenAI — ${cfg.provider} can't read screenshots. Switch provider in Settings → Integrations.`);
  }
  const res = await invoke<LlmReply>("llm_complete", {
    messages: [{ role: "user", content: visionContent(cfg.provider, text, images) }], system, tools: [],
    apiKey: cfg.apiKey, provider: cfg.provider, model: cfg.model, baseUrl: cfg.baseUrl,
  });
  return replyText(res);
}

// Pure derivation for the Claude Config editor (#2128), extracted verbatim from ClaudeConfigCard.tsx.
// Kept React-free so it can be unit-tested in isolation.

import { projectRepoCwd } from "@/shared/lib/core/projectPaths";

/** A cloned repo the editor can target, with its local clone path. */
export interface RepoTarget {
  full_name: string;
  local_path: string;
}

/**
 * All unique cloned repos across all projects, with their local clone paths.
 * Repos live under `<base>/projects/<projectKey>/<repoShort>`, so the path is
 * derived from the project key each repo was cloned under. (Every hub lives under
 * the single `projects/` root since #922, so published-ness never affects the path
 * — the old alias-based published check is gone with the alias, #2409.)
 */
export function deriveAllRepos(
  projectLocalRepos: Record<string, string[]>,
  bscBaseDir: string,
): RepoTarget[] {
  const seen = new Map<string, string>(); // full_name → local_path (first seen wins)
  for (const [projectKey, fullNames] of Object.entries(projectLocalRepos)) {
    for (const fullName of fullNames) {
      if (!seen.has(fullName)) seen.set(fullName, projectRepoCwd(bscBaseDir, projectKey, fullName));
    }
  }
  return Array.from(seen.entries()).map(([fullName, local_path]) => ({
    full_name: fullName,
    local_path,
  }));
}

// Claude Design brief (#634). Once the UI stage has defined its screens, the planner
// hands the user a kickoff prompt to paste into Claude Design: it asks for polished,
// drop-in components for each screen and tells the user to export them back into the
// file-intake stage, where the planner routes them to the UI repo. Pure + testable.

export interface DesignBriefOpts { projectName?: string; stack?: string }

/** Build the Claude Design kickoff prompt for a set of declared screens. */
export function buildClaudeDesignBrief(screens: string[], opts: DesignBriefOpts = {}): string {
  const list = screens.length
    ? screens.map((s) => `- **${s}**`).join("\n")
    : "- (no screens defined yet — define them in the UI stage first)";
  const project = opts.projectName ? ` for ${opts.projectName}` : "";
  const stackLine = opts.stack ? `\nTarget stack: **${opts.stack}** — build components that fit it.` : "";
  return `# Design brief${project}

Design these screens as polished, production-ready UI components:

${list}
${stackLine}

## Guidelines
- A clean, modern aesthetic — consistent spacing, a clear type scale, and reusable color tokens.
- Cover each screen's states: **default, empty, loading, error**.
- Build each screen as a **self-contained component (one file per screen)** so it can drop straight into the codebase.
- Note the responsive behavior and the key interactions for each screen.

## When you're done
Export each screen's code/assets and **drag them into the planner's "Drop files" stage** — the planner will route them into the UI repo for you.`;
}

// Claude CLI install-on-first-run policy (#1277).
//
// Claude Code is Anthropic's PROPRIETARY CLI (npm `@anthropic-ai/claude-code`) — unlike `gh`
// (MIT) or the GPL PortableGit userland, we CANNOT freely repackage/redistribute it in our
// installer, and it auto-updates itself + needs the user's own auth (both of which fight a pinned
// bundled copy). So the pattern is: DETECT it, and on first run OFFER a consented `npm i -g`
// install (or guide the user) — we never ship Anthropic's bits in our bundle. `bsc-agent` stays the
// bundled agent (our Claude-independence lever, #1078).
//
// This module is the PURE policy — no React/Tauri imports — so it's unit-testable and shared. The
// actual consented-install execution (a Tauri command running the npm install, wired to a first-run
// prompt) is the deferred half of #1277; this defines exactly what that flow runs and says.

/** The npm package that provides the Claude CLI. */
export const CLAUDE_CLI_PKG = "@anthropic-ai/claude-code";

/** Official install/docs URL surfaced when we guide (rather than auto-install). */
export const CLAUDE_CLI_DOCS = "https://docs.claude.com/claude-code";

/** A consented first-run install descriptor for a CLI we install (not bundle). */
export interface FirstRunInstall {
  /** npm package that provides the CLI. */
  pkg: string;
  /** The exact command a consented first-run flow runs (global npm install). */
  command: string;
  /** Docs URL for manual guidance. */
  docsUrl: string;
}

/** The Claude CLI's first-run install descriptor. */
export const claudeFirstRunInstall: FirstRunInstall = {
  pkg: CLAUDE_CLI_PKG,
  command: `npm i -g ${CLAUDE_CLI_PKG}`,
  docsUrl: CLAUDE_CLI_DOCS,
};

/** What the first-run flow should do given detection results. */
export type ClaudeFirstRunAction =
  | { kind: "ready" } //                CLI present — nothing to do.
  | { kind: "offer-install"; command: string } // absent but npm present — offer the consented install.
  | { kind: "guide"; docsUrl: string }; //        absent and no npm — we can't install; point to docs.

/**
 * Decide the first-run action for the Claude CLI. Pure. We NEVER repackage Anthropic's CLI, so the
 * best we do is offer to install it from npm (with the user's consent) when npm is available, else
 * guide them to the official docs. `claudePresent`/`npmPresent` come from the host probe.
 */
export function claudeFirstRunAction(
  claudePresent: boolean,
  npmPresent: boolean,
): ClaudeFirstRunAction {
  if (claudePresent) return { kind: "ready" };
  if (npmPresent) return { kind: "offer-install", command: claudeFirstRunInstall.command };
  return { kind: "guide", docsUrl: claudeFirstRunInstall.docsUrl };
}

