// Role gate (#219) — command classification + the role's command check. Classifies a shell command
// as a `git`/`gh` read or write, then decides whether a role's tier permits it. Pure enforcement
// core, free of React / xterm / Tauri. Re-exported from `sessionRoles.ts`.

import type { RoleCapability } from "@/shared/lib/session/roleModel";

// ── Command classification ──────────────────────────────────────────────────────

const GIT_WRITE = new Set([
  "push", "commit", "merge", "rebase", "reset", "revert", "cherry-pick", "tag", "am",
  "apply", "branch", "checkout", "switch", "restore", "stash", "mv", "rm", "add", "clean",
]);

const GH_WRITE_VERBS = new Set([
  "create", "edit", "delete", "close", "reopen", "merge", "comment", "add", "remove",
  "develop", "ready", "lock", "unlock", "transfer", "pin", "unpin", "rename", "sync",
]);

const HTTP_WRITE = new Set(["POST", "PATCH", "PUT", "DELETE"]);

export interface CommandClass {
  /** The leading binary (`git`, `gh`, `npm`, …). */
  tool: string;
  /** True when the command mutates state (a write). */
  mutating: boolean;
}

/**
 * Classify a shell command as a `git`/`gh` read or write (other tools are reported as
 * non-mutating — they're gated elsewhere). `gh api` is mutating when its method
 * (`--method` / `-X`) is a write verb.
 */
export function classifyCommand(cmd: string): CommandClass {
  const tokens = cmd.trim().split(/\s+/).filter(Boolean);
  const tool = tokens[0] ?? "";

  if (tool === "git") {
    return { tool, mutating: GIT_WRITE.has(tokens[1] ?? "") };
  }
  if (tool === "gh") {
    if (tokens[1] === "api") {
      const flag = tokens.indexOf("--method") >= 0 ? "--method" : "-X";
      const i = tokens.indexOf(flag);
      const method = (i >= 0 ? tokens[i + 1] ?? "" : "GET").toUpperCase();
      return { tool, mutating: HTTP_WRITE.has(method) };
    }
    return { tool, mutating: GH_WRITE_VERBS.has(tokens[2] ?? "") };
  }
  return { tool, mutating: false };
}

export interface CommandDecision {
  allowed: boolean;
  /** A clear, non-technical reason when denied. */
  reason?: string;
}

/**
 * Decide whether a role may run a command. Only `git`/`gh` are gated here (other
 * tools pass — they're handled by the command allowlist). Tier rules: `none` denies
 * all, `read` allows non-mutating only, `write` allows all.
 */
export function checkCommand(cap: RoleCapability, cmd: string): CommandDecision {
  const { tool, mutating } = classifyCommand(cmd);
  const tier = tool === "gh" ? cap.github : tool === "git" ? cap.git : null;
  if (tier === null) return { allowed: true };
  if (tier === "none") {
    return { allowed: false, reason: `the ${cap.role} role has no ${tool} access` };
  }
  if (mutating && tier === "read") {
    return { allowed: false, reason: `the ${cap.role} role can read but not modify via ${tool}` };
  }
  return { allowed: true };
}

// The commons + integration LANES (#851, retasked by #funnel-commons-and-integration-streams).
//
// Originally this module gated feature streams on a commons SENTINEL that the DIRECTOR satisfied:
// `commons` was not a real stream, it was a latch, and the director held a write carve-out so it
// could scaffold `.gitignore` / `package.json` / CI config itself. The three-tier funnel takes the
// director's write away, so that owner has to go somewhere — and all three of the duties it loses
// (steward the commons, merge the integration branch + revert it when red, run the cross-feature
// seam tests) are DOING work. Doing is a worker's job.
//
// So the sentinel becomes a real lane with a real worktree, and a second lane takes the integration
// branch. Four pure transforms over a FleetPlan, applied at launch (and usable in the planner/UI):
//
//   1. excludeCommonsFromStreams — strip every commons path from each FEATURE stream's `owns`, so no
//      feature stream owns `.gitignore` / `package.json` / CI config (the single-owner rule, by
//      construction). The commons lane owns them instead.
//   2. gateStreamsOnCommons — Phase 0: every feature stream `dependsOn` its repo's commons lane, so
//      the commons are scaffolded and landed BEFORE feature workers build against them.
//   3. commonsLanesFor — materialize the lanes themselves, one pair PER REPO (see the note on
//      `laneIdFor`).
//   4. applyCommonsGate — all three, in the order that matters.
//
// Pure (no store/IO) so it's exhaustively unit-testable; `fleetStartProject` calls `applyCommonsGate`
// with the project's stack-derived commons.

import type { FleetPlan, AgentStream } from "@/features/planner/fleet/planFleet";
import { excludeCommonsFromOwns } from "@/shared/lib/session/commons";
import { matchGlob } from "@/shared/lib/session/sessionRoles";

/**
 * Stream id for the commons lane — the single owner of the repo-root commons (#851). It USED to be a
 * reserved sentinel that no real stream carried (the director satisfied it); it is now a real stream
 * id, so it names a branch, a worktree and a pane like any other lane.
 */
export const COMMONS_STREAM_ID = "commons";

/**
 * Stream id for the integration lane — owner of the integration branch: the local merges, the revert
 * when the branch goes red, and the cross-feature seam tests. Under local-first there are no PRs, so
 * this lane's whole job is local: it never reaches a remote.
 */
export const INTEGRATION_STREAM_ID = "integration";

/**
 * The lane id for `base` in `repo`. The commons are a property of a REPO ROOT, not of a project — two
 * repos have two `.gitignore`s and two lockfiles, and one owner cannot hold both (it gets one
 * worktree). So a multi-repo fleet gets one pair of lanes per repo, suffixed with the repo slug.
 *
 * The single-repo case — which is nearly every fleet — keeps the bare `commons` / `integration` ids,
 * so branch names, pane ids and the `dependsOn` sentinel read exactly as they did before.
 */
export function laneIdFor(base: string, repo: string, multiRepo: boolean): string {
  if (!multiRepo) return base;
  const slug = repo.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  return slug ? `${base}--${slug}` : base;
}

/** The distinct repos the feature streams build in, in first-seen order. */
function reposOf(streams: AgentStream[]): string[] {
  const out: string[] = [];
  for (const s of streams) if (s.repo && !out.includes(s.repo)) out.push(s.repo);
  return out;
}

/** Strip every commons path from each feature stream's `owns` (the owns-exclusion). Pure; returns a
 *  new array. A stream that already excludes the commons is unchanged. */
export function excludeCommonsFromStreams(streams: AgentStream[], commons: string[]): AgentStream[] {
  return streams.map((s) => {
    const owns = excludeCommonsFromOwns(s.owns, commons, matchGlob);
    return owns.length === s.owns.length ? s : { ...s, owns };
  });
}

/**
 * Phase 0 gating (#851 step 3): make every feature stream depend on ITS OWN REPO's commons lane, so
 * the commons are landed before feature workers build against them. Adds the lane id to each stream's
 * `dependsOn` (deduped). A no-op when there are no commons. Pure; returns new stream objects only
 * where the dep was added.
 *
 * No longer conditioned on a director existing (it was, when the director was the commons owner): the
 * commons lane is a worker, so the gate holds in a director-less fleet exactly as it does with one.
 */
export function gateStreamsOnCommons(streams: AgentStream[], commons: string[]): AgentStream[] {
  if (commons.length === 0) return streams;
  const multiRepo = reposOf(streams).length > 1;
  return streams.map((s) => {
    const id = laneIdFor(COMMONS_STREAM_ID, s.repo, multiRepo);
    return s.dependsOn.includes(id) ? s : { ...s, dependsOn: [...s.dependsOn, id] };
  });
}

/**
 * Materialize the commons + integration lanes for `streams` — one pair per distinct repo.
 *
 * The commons lane OWNS the commons globs (it is the single owner the exclusion above carved out for
 * it) and depends on nothing, so it runs in the first wave. The integration lane owns no source at
 * all — its artifacts are merges, a revert, and seam-test runs — and it depends on the commons lane,
 * since there is nothing coherent to integrate until the commons have landed.
 *
 * Both are ORDINARY streams (#funnel-commons-and-integration-streams): they launch with the fleet and
 * END when their work is done, exactly like a feature worker. Nothing parks them alive and nothing but
 * the user restarts them — the maintenance parking that once would have kept them warm was removed on
 * purpose (`#session-stop-is-honoured`), because it depended on a Stop hook that refused a worker's
 * stop and so made sessions unkillable.
 */
export function commonsLanesFor(streams: AgentStream[], commons: string[]): AgentStream[] {
  if (commons.length === 0) return [];
  const repos = reposOf(streams);
  if (repos.length === 0) return [];
  const multiRepo = repos.length > 1;
  const lanes: AgentStream[] = [];
  for (const repo of repos) {
    const commonsId = laneIdFor(COMMONS_STREAM_ID, repo, multiRepo);
    lanes.push({
      id: commonsId,
      name: multiRepo ? `Commons (${repo})` : "Commons",
      repo,
      owns: [...commons],
      issues: [],
      dependsOn: [],
    });
    lanes.push({
      id: laneIdFor(INTEGRATION_STREAM_ID, repo, multiRepo),
      name: multiRepo ? `Integration (${repo})` : "Integration",
      repo,
      // Owns no source: this lane merges, reverts and runs seam tests. Giving it globs would make it
      // a second writer on someone else's lane, which is the exact collision #851 exists to prevent.
      owns: [],
      issues: [],
      dependsOn: [commonsId],
    });
  }
  return lanes;
}

/** True when `id` names one of the two lanes (either the bare id or a per-repo suffixed one). */
export function isLaneStream(id: string): boolean {
  return (
    id === COMMONS_STREAM_ID ||
    id === INTEGRATION_STREAM_ID ||
    id.startsWith(`${COMMONS_STREAM_ID}--`) ||
    id.startsWith(`${INTEGRATION_STREAM_ID}--`)
  );
}

/**
 * Apply the commons model to a fleet plan: exclude the commons from every feature stream's `owns`,
 * gate each on its repo's commons lane, then PREPEND the lanes themselves.
 *
 * Order is load-bearing. The exclusion must run on the feature streams ALONE — if the commons lane
 * were already in the list, the exclusion would strip the very globs that make it the owner and the
 * commons would end up owned by nobody. Prepending last also puts the lanes at the head of the launch
 * order, which is what Phase 0 means. Returns a new plan; the director and other fields pass through.
 */
export function applyCommonsGate(fleet: FleetPlan, commons: string[]): FleetPlan {
  const excluded = excludeCommonsFromStreams(fleet.streams, commons);
  const gated = gateStreamsOnCommons(excluded, commons);
  const lanes = commonsLanesFor(fleet.streams, commons);
  return { ...fleet, streams: [...lanes, ...gated] };
}

// Director-owned commons (#851) — the repo-root shared files that EVERY stream depends on and
// that feature-decomposition can't carve apart: the ignore file, the dependency manifest +
// lockfile, the TS/build config, CI workflows, the env template, and formatter/linter config.
//
// Worktrees isolate the working *directory*, not the *merge*: each worker that appends to one of
// these on its own branch collides at integration. The fix is a single owner + dependency-gating,
// with the **director** as that owner (it lives at the project root, sees every worktree, and is
// the integrator — and these commons are integration concerns). This module is the pure source of
// truth for the commons set: which paths they are (derived from the stack), the owns-exclusion that
// keeps every feature stream OUT of them, and the union-merge subset. Free of React / Tauri imports
// so it's unit-testable in isolation (matches sessionRoles.ts).

/** A stack tag describing the project's tech (lowercased identifiers like `react`, `rust`, `node`). */
export type StackTag = string;

/**
 * Repo-root commons present in EVERY project regardless of stack — the ignore file, CI workflows,
 * the env template, and the common formatter/linter configs. These are the director's lane and are
 * excluded from every feature stream's `owns`.
 */
const BASE_COMMONS: string[] = [
  ".gitignore",
  ".gitattributes",
  ".github/workflows/**",
  ".env.example",
  // Formatter / linter config (cross-stack — present for JS, Rust, Python projects alike).
  ".editorconfig",
  ".prettierrc",
  ".prettierrc.*",
  "prettier.config.*",
  ".eslintrc",
  ".eslintrc.*",
  "eslint.config.*",
];

/**
 * Stack-specific commons keyed by a tag substring. Each entry's globs are added when ANY of the
 * project's stack tags contains the key (case-insensitive) — so `react`/`node`/`typescript`/`vite`
 * all pull in the JS/TS manifest + tsconfig, and `rust`/`cargo` pull in the Cargo manifest.
 */
const STACK_COMMONS: Array<{ match: string[]; globs: string[] }> = [
  {
    // JS/TS ecosystems: the package manifest + every lockfile flavor, and the TS/build config.
    match: ["node", "npm", "pnpm", "yarn", "react", "vue", "svelte", "next", "vite", "typescript", "ts", "javascript", "js", "tauri"],
    globs: [
      "package.json",
      "package-lock.json",
      "pnpm-lock.yaml",
      "yarn.lock",
      "tsconfig.json",
      "tsconfig.*.json",
    ],
  },
  {
    // Rust: the Cargo manifest + lockfile (workspace root).
    match: ["rust", "cargo", "tauri"],
    globs: ["Cargo.toml", "Cargo.lock"],
  },
  {
    // Python: the project manifests + common lockfiles.
    match: ["python", "py", "poetry", "pip"],
    globs: ["pyproject.toml", "setup.py", "setup.cfg", "requirements*.txt", "poetry.lock", "Pipfile", "Pipfile.lock"],
  },
  {
    // Go: the module manifest + checksum file.
    match: ["go", "golang"],
    globs: ["go.mod", "go.sum"],
  },
];

/**
 * The line-additive commons whose merges should use git's `merge=union` driver: files that streams
 * only ever APPEND lines to (ignore entries, env keys), so concatenating both sides on merge is the
 * correct resolution and any residual race auto-resolves without a conflict. (NOT the structured
 * files — package.json/tsconfig/Cargo.toml — where a blind union would produce invalid JSON/TOML.)
 */
export const UNION_MERGE_COMMONS: string[] = [".gitignore", ".env.example"];

/**
 * Pull candidate stack tags out of the free-text `stack.md` section the planner writes (#851). The
 * stack section is prose, not a tag list, so we tokenize it into lowercase words and let {@link
 * commonsGlobsForStack}'s substring match recognize the technologies (`react`, `rust`, `node`, …).
 * Cheap and order-independent; unrecognized words simply don't match any stack entry.
 */
export function stackTagsFromSection(stackSection: string): StackTag[] {
  if (!stackSection) return [];
  const seen = new Set<string>();
  for (const tok of stackSection.toLowerCase().match(/[a-z][a-z0-9+.#-]*/g) ?? []) {
    if (tok.length >= 2) seen.add(tok);
  }
  return [...seen];
}

/**
 * Derive the repo-root commons set from the project's stack tags. Always includes {@link
 * BASE_COMMONS}; adds each stack entry whose `match` key is a substring of any tag. Deduped and
 * stable-ordered (base first, then stack additions in declaration order). With no recognized tag the
 * caller still gets the universal base commons.
 */
export function commonsGlobsForStack(stack: StackTag[]): string[] {
  const tags = stack.map((t) => t.toLowerCase().trim()).filter(Boolean);
  const out = [...BASE_COMMONS];
  for (const entry of STACK_COMMONS) {
    if (entry.match.some((m) => tags.some((t) => t.includes(m)))) {
      for (const g of entry.globs) if (!out.includes(g)) out.push(g);
    }
  }
  return out;
}

/** True when `path` is one of the commons globs in `commons` (uses the same glob matcher the role
 *  gate uses; imported lazily to avoid a cycle isn't needed — sessionRoles has no commons import). */
function pathInCommons(path: string, commons: string[], match: (glob: string, p: string) => boolean): boolean {
  return commons.some((g) => g === path || match(g, path));
}

/**
 * Strip any commons path from a feature stream's `owns` (the owns-exclusion, #851 step 1): the
 * director owns the commons, so no feature stream may list one. A stream that owned `.gitignore` or
 * `package.json` would re-introduce the parallel-append collision; this enforces the single-owner
 * rule by construction. `match` is the glob matcher (injected to avoid importing the heavier
 * sessionRoles here for a one-liner).
 */
export function excludeCommonsFromOwns(owns: string[], commons: string[], match: (glob: string, p: string) => boolean): string[] {
  return owns.filter((o) => {
    // Drop an exact commons glob the stream declared, and any concrete path that falls inside one.
    if (commons.includes(o)) return false;
    return !pathInCommons(o, commons, match);
  });
}

// Component analysis (#3667, epic #3604) — derive a graph component's CATEGORIZATION metadata from its
// source, so an extracted component lands in the right composition-graph swimlane with real dependency edges
// instead of as a metadata shell. Pure + React-free (a type-only `model` import, erased at runtime), so it's
// reusable by the app, the backfill script, and future extraction generators, and unit-testable.
//
// Derives the two categorization signals that drive the Design Studio's composition graph:
//   • `composes` — the EDGE set: the NAMES of the graph components this one imports (a `@/components/<id>`
//     sibling, or a `@/shared/ui/*` primitive a graph component PROVIDES). Name-keyed + resolved within-kit,
//     matching the store convention. Plain-code imports (an unextracted shared/ui module, a lib) are NOT
//     edges — they're not graph nodes.
//   • `role` — the TIER (`primitive | composite | layout | page | service`): the swimlane band. A page stays
//     a page; a structural container is a layout; anything that ASSEMBLES (composes a sibling, or renders
//     several imported components) is a composite; a leaf atom is a primitive.
import type { ComponentRecord, PropSpec, Role } from "@/features/designs/lib/model";

/** Resolve an import specifier → the composed graph component's NAME, or null if it's not a graph node. */
export type NameResolver = (specifier: string) => string | null;

/** Structural-container primitives — a `layout`-tier component (renders `children` as a box), by NAME. */
const LAYOUT_NAMES = new Set([
  "Box", "Stack", "Row", "Grid", "Spacer", "Screen", "MasterDetail", "SectionHeader", "SectionLabel",
  "GraphRail", "GraphCanvas", "RailRow", "RailSection", "Pane", "TabBar", "Divider",
  "ModalScrim", "ModalCard", "Dialog", "GraphLegend", "RailGroupHeader", "PaneGrid", "SessionDock", "SplitView",
  "Tree",
]);

/** Content-atom FUNDAMENTALS — always `primitive`, even if they compose a utility (a Skeleton loading
 *  shim doesn't make an atom a composite). Mirrors compositionLayout's exemplars (Button/Text/Chip …). A
 *  composes-count alone can't separate `Text` (atom, composes Skeleton) from `Card` (composite, composes
 *  Skeleton), so the well-known atoms are curated. */
const PRIMITIVE_NAMES = new Set([
  "Text", "Chip", "Button", "IconButton", "Badge", "StatusDot", "ColorSwatch", "Avatar", "IconBox",
  "FillBar", "StatTile", "Kbd", "Skeleton", "Spinner", "Dot", "Tag",
  // form controls are fundamentals (even Field, which composes a Skeleton loading state)
  "Field", "TextField", "SelectField", "TextArea", "SearchField", "SegmentedControl", "Toggle", "Checkbox",
]);

/** The graph components a source composes → their NAMES (deduped, sorted). An import of a `@/components/<id>`
 *  sibling or a `@/shared/ui/*` specifier a component provides is an edge; everything else (plain code) isn't. */
export function deriveComposes(srcText: string, resolveName: NameResolver): string[] {
  const names = new Set<string>();
  const re = /\bfrom\s+"([^"]+)"/g; // every `… from "specifier"` (named/namespace/default imports)
  let m: RegExpExecArray | null;
  while ((m = re.exec(srcText)) !== null) {
    const name = resolveName(m[1]);
    if (name) names.add(name);
  }
  return [...names].sort();
}

/** Count DISTINCT imported components used as JSX tags (`<Foo …>`) — a proxy for "assembles components". */
export function renderedComponentCount(srcText: string): number {
  const tags = new Set<string>();
  const re = /<([A-Z][A-Za-z0-9]*)[\s/>]/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(srcText)) !== null) tags.add(m[1]);
  return tags.size;
}

/** The architectural TIER, from the source's shape. A `page` record keeps its tier (a page is a page by
 *  definition); otherwise: structural container → `layout`; assembles (composes a sibling OR renders ≥3
 *  imported components) → `composite`; a leaf atom → `primitive`. */
export function deriveRole(name: string, existingRole: string | undefined, composes: string[], rendered: number): Role {
  if (existingRole === "page") return "page";
  if (LAYOUT_NAMES.has(name)) return "layout";
  if (PRIMITIVE_NAMES.has(name)) return "primitive"; // a curated content atom stays a fundamental
  if (composes.length >= 1 || rendered >= 3) return "composite";
  return "primitive";
}

/** Derive the PROP interface of a record's PRIMARY component (`interface <name>Props {…}`) → PropSpec[].
 *  Single-component records get their props; a record with no `<name>Props` interface (a page with an inline
 *  prop type, or a multi-export barrel like charts) gets `[]` — accurate, not wrong. `desc` is left empty
 *  (author/LLM fills it); `name`/`type`/`req` are the catalog signal. */
export function deriveProps(srcText: string, name: string): PropSpec[] {
  const open = srcText.search(new RegExp(`interface\\s+${name}Props\\b[^{]*\\{`));
  if (open < 0) return [];
  const braceAt = srcText.indexOf("{", open);
  let depth = 0, end = -1;
  for (let k = braceAt; k < srcText.length; k++) {
    if (srcText[k] === "{") depth++;
    else if (srcText[k] === "}" && --depth === 0) { end = k; break; }
  }
  if (end < 0) return [];
  const body = srcText.slice(braceAt + 1, end)
    .replace(/\/\*[\s\S]*?\*\//g, "") // strip block/JSDoc comments
    .replace(/\/\/[^\n]*/g, "");      // strip line comments
  const props: PropSpec[] = [];
  const re = /(?:^|[;\n{])\s*([A-Za-z_]\w*)(\?)?\s*:\s*([\s\S]*?);/g; // name(?): type;  (type may span lines)
  let m: RegExpExecArray | null;
  while ((m = re.exec(body)) !== null) {
    props.push({ name: m[1], type: m[3].replace(/\s+/g, " ").trim().slice(0, 100), req: !m[2], desc: "" });
  }
  return props;
}

/** The categorization metadata derived for one record — `composes` (edges) + `role` (tier) + `props`. */
export interface DerivedMeta {
  composes: string[];
  role: Role;
  props: PropSpec[];
}

/** Analyze a record: derive its `composes` edges + `role` tier from its `srcText`. `role` is typed loosely
 *  (string) on purpose — the whole point is to REPLACE an absent or INVALID existing role (e.g. our extracted
 *  records' non-tier `"component"`), so it must accept one. */
export function analyzeComponent(
  record: { name: string; role?: string; srcText: string },
  resolveName: NameResolver,
): DerivedMeta {
  const composes = deriveComposes(record.srcText, resolveName);
  const role = deriveRole(record.name, record.role, composes, renderedComponentCount(record.srcText));
  const props = deriveProps(record.srcText, record.name);
  return { composes, role, props };
}

/** Build a `NameResolver` from a component set: `@/components/<id>` → the record's name; a `@/shared/ui/*`
 *  specifier a record PROVIDES → that record's name. Same-kit only (composes never crosses kits). */
export function buildNameResolver(records: Pick<ComponentRecord, "id" | "name" | "provides" | "kitId">[], kitId: string): NameResolver {
  const inKit = records.filter((r) => r.kitId === kitId);
  const byId = new Map(inKit.map((r) => [r.id, r.name] as const));
  const byProvides = new Map(inKit.filter((r) => r.provides).map((r) => [r.provides as string, r.name] as const));
  return (specifier) => {
    if (specifier.startsWith("@/components/")) return byId.get(specifier.slice("@/components/".length)) ?? null;
    return byProvides.get(specifier) ?? null;
  };
}

// componentRuntimeProbe (#2908) — RUN a built component preview in a hidden sandboxed iframe and report
// whether it threw at RUNTIME. The Design Studio's on-visit scan (#2838) only esbuild-BUILT each
// component, so it was blind to components that build clean yet throw when rendered — e.g. a d3-force
// `ForceGraph` whose simulation throws on its timer tick. This runner closes that gap: it mounts the
// bundled module exactly as the live `ComponentPreviewFrame` does (`buildComponentSrcDoc`, sandboxed
// `allow-scripts`), listens for the iframe's `__preview` messages, and resolves ok / errored.
//
// Two subtleties make this actually catch the target class of bug:
//   • CORRELATION — messages are matched by `e.source === iframe.contentWindow`, so concurrent probes (or
//     a live preview frame) never cross-talk. (`buildComponentSrcDoc` carries no id.)
//   • ASYNC THROWS — the iframe posts `ready` right after the module executes, but a d3-force tick / a
//     `useEffect` throw fires LATER. So `ready` does NOT immediately pass: we keep listening for a throw
//     for a short SETTLE window, then pass. A synchronous render throw fires `error` before `ready`.
//
// Non-throwing by contract: a component that can't be PROVEN to throw resolves `{ ok: true }` (no DOM, a
// timeout, or any probe-infra failure ⇒ inconclusive), so the scan never false-badges a healthy
// component. DOM-using (creates an iframe) so it can't run under jsdom — the pure decision logic lives in
// `componentScan.ts` (`buildAndProbe`, unit-tested with a mock runner); this wires the real iframe.
import { buildComponentSrcDoc } from "@/shared/lib/preview/componentBundle";

/** A build-clean component's RUNTIME outcome: `ok` (mounted + settled without throwing) or a throw with a
 *  message. `empty` (on the ok variant, #2926) is true when the iframe reported it rendered NOTHING — no
 *  elements, no text — i.e. it mounts but produces no visible output; undefined ⇒ it rendered content or
 *  the check was inconclusive (no `rendered` report). The generic result the scan's `RunFn` consumes —
 *  canonical here (the probe produces it) so `shared/` stays feature-agnostic; `features/designs` imports
 *  this type for its scan contract. */
export type RuntimeOutcome = { ok: true; empty?: boolean } | { ok: false; message: string };

/** How long to wait for the iframe to post `ready` before giving up (inconclusive ⇒ ok). Generous so a
 *  component that fetches externals from esm.sh has time to mount over a slow link. */
const READY_TIMEOUT_MS = 6000;
/** After `ready`, keep listening this long for a LATE throw (an async tick / effect) before passing. */
const SETTLE_MS = 700;

/**
 * Does an iframe error message read as a MODULE/NETWORK load failure rather than a component throw? The
 * probe bundle keeps React (and any user library — d3, three) external, loaded from esm.sh at render
 * time. When those can't load (offline, a slow/blocked CDN), the iframe errors before the component ever
 * runs — that's an ENVIRONMENT failure, NOT a defect in the component, so the scan must treat it as
 * inconclusive (ok) rather than falsely badging every component in the kit. A genuine render throw
 * (`x is undefined`, a d3-force tick) does NOT match these, so it still badges. Pure.
 */
export function looksLikeModuleLoadFailure(message: string): boolean {
  return /failed to fetch|dynamically imported module|importing a module script failed|load failed|networkerror|failed to load resource|err_(?:internet|network|connection)/i.test(
    message,
  );
}

/**
 * Render `bundleJs` in a hidden sandboxed iframe and report whether it threw at runtime.
 *
 * @param bundleJs   the built ESM module (from `bundleComponent`) — a self-mounting preview bundle.
 * @param injectedCss app CSS injected into the iframe so the render is faithful (optional).
 * @returns `{ ok: false, message }` only if the component DEMONSTRABLY threw (a sync render error, an
 *          async tick, or an unhandled rejection); `{ ok: true }` otherwise — including no-DOM, timeouts,
 *          and any probe-infrastructure failure (inconclusive, never a false badge).
 */
export function probeComponentRuntime(bundleJs: string, injectedCss = ""): Promise<RuntimeOutcome> {
  // No DOM (jsdom / SSR) — can't run the component; treat as inconclusive rather than badging it.
  if (typeof document === "undefined" || !document.body) return Promise.resolve({ ok: true });

  return new Promise<RuntimeOutcome>((resolve) => {
    const iframe = document.createElement("iframe");
    iframe.setAttribute("sandbox", "allow-scripts"); // scripts, but NOT same-origin — same trust as the live preview
    iframe.setAttribute("aria-hidden", "true");
    iframe.tabIndex = -1;
    // Off-screen + inert, but attached (a detached iframe never loads its srcdoc, so scripts wouldn't run).
    iframe.style.cssText =
      "position:fixed;left:-99999px;top:0;width:480px;height:360px;border:0;opacity:0;pointer-events:none";

    let settled = false;
    let settleTimer: ReturnType<typeof setTimeout> | undefined;
    // Whether the iframe reported an EMPTY render (#2926). Captured from the `rendered` message, which the
    // srcdoc posts a beat after `ready` (so async/effect renders have settled) — before the settle window
    // resolves ok, so it's folded into the ok outcome. Undefined until reported ⇒ treated as not-empty.
    let empty: boolean | undefined;
    const finish = (outcome: RuntimeOutcome): void => {
      if (settled) return;
      settled = true;
      clearTimeout(hardTimer);
      if (settleTimer) clearTimeout(settleTimer);
      window.removeEventListener("message", onMsg);
      iframe.remove();
      resolve(outcome);
    };

    const onMsg = (e: MessageEvent): void => {
      // Correlate strictly by the source window so concurrent probes / a live preview frame don't leak in.
      if (e.source !== iframe.contentWindow) return;
      const data = e.data as { __preview?: unknown; message?: unknown; empty?: unknown } | null;
      if (!data || typeof data.__preview !== "string") return;
      if (data.__preview === "error") {
        const message = String(data.message ?? "runtime error");
        // A failed external/module load is an environment problem, not a component defect ⇒ inconclusive.
        finish(looksLikeModuleLoadFailure(message) ? { ok: true } : { ok: false, message });
      } else if (data.__preview === "rendered") {
        empty = data.empty === true; // the iframe's post-render measurement (#2926)
      } else if (data.__preview === "ready") {
        // Mounted without a synchronous throw — but keep listening briefly for a late (async) throw, then
        // pass, carrying whatever empty-render verdict the `rendered` message reported by then.
        settleTimer = setTimeout(() => finish({ ok: true, empty }), SETTLE_MS);
      }
    };

    // Backstop: never posted `ready` (hung / slow) ⇒ inconclusive, don't badge.
    const hardTimer = setTimeout(() => finish({ ok: true }), READY_TIMEOUT_MS);

    window.addEventListener("message", onMsg);
    try {
      document.body.appendChild(iframe);
      iframe.srcdoc = buildComponentSrcDoc(bundleJs, { injectedCss });
    } catch {
      finish({ ok: true }); // couldn't even mount the probe ⇒ inconclusive
    }
  });
}

// Component preview-error scan (#2838, #2908) — the PURE spine of the Design Studio's on-visit sweep.
// When the Studio is visited we esbuild-build EACH buildable component in the active kit AND, when the
// build is clean, RUN it in a sandboxed iframe (#2908) — throttled to a small concurrency — recording
// ok / build-error / runtime-error per component so the graph can badge the ones that fail. This module
// owns the React-free, esbuild-free, DOM-free logic (which components to scan, the throttle pool, and
// the build→run→status derivation) so it's unit-testable; the hook (`useComponentScan`) wires it to the
// real `bundleComponent` (esbuild-wasm) and `probeComponentRuntime` (a hidden iframe) — neither of which
// can run under jsdom — and the store.
//
// WHY RUN, not just build (#2908): the build-only scan caught esbuild compile/resolve failures but was
// BLIND to components that build clean yet THROW at runtime — e.g. a d3-force `ForceGraph` whose
// simulation throws on its timer tick. Those looked healthy on the graph until opened. Running each
// build-clean component closes that gap; a build-clean-but-throws component is now badged proactively.
//
// SCOPE: only components that HAVE buildable source (`componentPreviewFiles` non-null) and then FAIL are
// this scan's concern. A component with NO buildable source (`componentPreviewFiles` === null) is a
// separate, static graph-health finding (the `no-implementation` category) — never scanned here.
//
// STATE BLANKS (#3191): the same sweep also render-confirms a component's supported data-STATES. A DATA
// component (collection prop) is built in the `empty` state and a component with a `loading` prop in the
// `loading` state; a build-clean, renders-fine-LOADED component that produces a BLANK #root in one of those
// states is flagged `empty-empty-state` / `empty-loading-state` (RUNTIME-only HealthCategory values — the
// static `analyzeGraphHealth`/Rust doctor can't render, so they never emit these). This is the render angle
// on the #3135 static no-empty/no-loading advisories: it catches a component that HAS an empty/loading
// branch which itself renders nothing (e.g. `data.length ? list : null`), which the static heuristic misses.
import type { RuntimeOutcome } from "@/shared/lib/preview/componentRuntimeProbe";
import {
  componentPreviewFiles, isCollectionProp, isLoadingProp,
  type KitArtifact, type LibraryModuleResolver, type GraphProvidesResolver,
} from "@/features/designs/lib/componentPreview";
import type { HealthCategory } from "@/features/designs/lib/graphHealth";
import { libraryModuleResolver } from "@/features/designs/lib/libraryModules";
import { KNOWLEDGE } from "@/features/algorithms";
// The feature's existing hash — reused rather than adding a second one
// (#the-scan-signature-is-the-whole-source-not-a-digest).
import { fnv1a } from "@/features/designs/lib/seedRefresh";
import type { ComponentRecord } from "@/features/designs/lib/model";

/** The two RUNTIME data-state health categories the scan render-confirms (#3191) — a subset of
 *  {@link HealthCategory} (the `Extract` binds them to real members, so a typo fails to compile). */
export type RuntimeStateCategory = Extract<HealthCategory, "empty-empty-state" | "empty-loading-state">;

/** One component's preview outcome — the value the graph badges off. `ok` = built clean, ran without
 *  throwing, AND rendered something; `error` carries a readable message for the node's tooltip and a
 *  `kind` distinguishing a `build` failure (esbuild) from a `runtime` throw (an exception during the
 *  component's own render); `empty` = built + mounted clean but rendered NOTHING visible (#2926). */
export type ComponentBuildStatus =
  | { state: "ok" }
  | { state: "error"; kind: "build" | "runtime"; message: string }
  | { state: "empty"; message: string };

/** One component's complete scan outcome — the unit the sweep BATCHES into the store (#4132).
 *
 *  Both halves travel together because they are produced together and consumed together: writing them
 *  through two separate per-id setters cost two store commits per component (~496 for a 248-component
 *  kit), each one re-rendering the whole graph. */
export interface ComponentScanResult {
  id: string;
  status: ComponentBuildStatus;
  /** The render-confirmed data-state blanks (#3191). `[]` is meaningful — it CLEARS a prior badge. */
  stateBlanks: RuntimeStateCategory[];
}

/**
 * What the scan should mirror to the DURABLE preview-error log (`bsc ui preview-error`) for a component
 * whose status went `prior` → `next` (#3540) — so `bsc ui doctor` sees the COMPLETE errored set, not
 * just components a human opened. Returns:
 *  - the message to RECORD, for BOTH a `build` failure and a `runtime` throw (#3549). Doctor's STATIC
 *    checks assume a build error is always statically detectable, but it isn't (WorkspaceShellPage's
 *    extensionless `src` built clean by the analyzer yet the real esbuild loader rejected its TS), so
 *    the real preview build is the authority — its failures must reach the log too. The message is
 *    prefixed with the kind (`build:`/`render:`) so the doctor finding reads correctly for either;
 *  - `""` to CLEAR, when a component that WAS an error is now ok/empty (so a fixed one drops out);
 *  - `null` to do nothing — a first-visit `ok`/`empty` (no prior error), so a sweep of ~50 healthy
 *    components logs nothing.
 *
 * Pure — the hook calls `recordPreviewError` only when this is non-null.
 */

/**
 * The default {@link GraphProvidesResolver} (#83) — a `@/…` specifier → the ALGORITHMS record that
 * provides it, matched exactly the way the runtime's `resolveGraphSource` matches.
 *
 * The preview only ever consulted COMPONENT records for `provides`, so a module retired into the
 * algorithms store had no source in the mem file set and every named import off it failed to resolve
 * (`No matching export in mem:src/app/lazyWorkspaces`). The runtime has resolved these since
 * `resolver-reads-the-algorithms-store`; this is the preview catching up.
 *
 * Keyed at the mem path the specifier resolves to (`@/a/b` → `a/b.ts`), which is where the bundler's
 * `@/…` branch looks — the same shape `libraryModuleResolver` returns for `@bsc/…`.
 */
export const graphProvidesResolver: GraphProvidesResolver = (spec: string) => {
  const want = spec.trim();
  if (!want.startsWith("@/")) return null;
  for (const impl of KNOWLEDGE.implementations) {
    if (impl.provides?.trim() !== want || !impl.code) continue;
    return { path: `${want.slice(2)}.ts`, source: impl.code };
  }
  return null;
};

export function durableLogSync(
  prior: ComponentBuildStatus | undefined,
  next: ComponentBuildStatus,
): string | null {
  if (next.state === "error") return `${next.kind === "build" ? "build" : "render"}: ${next.message}`;
  if (prior?.state === "error") return ""; // next is now ok/empty — a prior error is resolved, so clear it
  return null;
}

/** A per-STATE preview build to render-confirm for a BLANK #root (#3191) — the empty/loading data-state a
 *  component supports. `category` is the finding it yields when that state renders nothing; `files`/`entry`
 *  build that state's preview (the same file set as loaded — only the sampled props differ). */
export interface StateProbe {
  category: RuntimeStateCategory;
  files: Record<string, string>;
  entry: string;
}

/** A component queued for the build scan: its id, a change-signature (so an edit re-queues just it), and
 *  the in-memory files + entry to hand esbuild. */
export interface ScannableComponent {
  id: string;
  /** Any change to the buildable source re-queues this component (see {@link buildSignature}). */
  sig: string;
  files: Record<string, string>;
  entry: string;
  /** Extra per-state preview builds to render-confirm for a blank (#3191) — present only for a component
   *  that HAS the relevant state (a collection prop → `empty`; a `loading` prop → `loading`). Undefined
   *  for a component with no such state (a Button), so it is never probed for a state it can't have. */
  states?: StateProbe[];
}

/** The raw material a signature is computed FROM — the fields that decide what gets bundled. Kept
 *  separate from {@link buildSignature} so the vendored/state extension below can fold its own text in
 *  BEFORE hashing, rather than hashing twice and concatenating digests. Never persisted, never held. */
function signatureSource(c: ComponentRecord): string {
  return [c.id, c.src ?? "", c.source ?? "", c.srcText ?? ""].join(" ");
}

/**
 * Reduce signature material to a short digest.
 *
 * WHY THIS EXISTS (#the-scan-signature-is-the-whole-source-not-a-digest). A signature used to BE its
 * material — the component's whole source, plus every vendored dependency's body. As a purely
 * in-memory comparison key that was fine: the only operation anyone performs on a signature is
 * equality. Then the scan cache persisted it, and a comparison key became **216,810,972 bytes** on
 * disk — 371 entries averaging 584 KB — read in full at every boot and written back on every sweep.
 *
 * Hashing happens HERE, at the source, and not at the persistence boundary: `scannedSigs` holds a
 * signature per component for the life of the page, so hashing only on the way to disk would still
 * leave ~200 MB of source text in memory being compared for equality.
 *
 * The length is folded in alongside the hash because a missed re-queue is the failure that matters —
 * it leaves a stale error badge on a component the designer just fixed. FNV-1a is 32-bit, so a
 * birthday collision across a few hundred components is already ~1e-5; requiring an edit to preserve
 * both the hash AND the exact byte length puts it out of reach in practice. Not cryptographic and
 * does not need to be: this detects a designer's edit, it is not a security boundary.
 */
function digest(material: string): string {
  return `${fnv1a(material)}-${material.length.toString(36)}`;
}

/** A component's build signature — a digest of the fields that decide what gets bundled. A change to
 *  any of them (a designer edit, a re-authored source) means a stale ok/error, so the scan re-queues
 *  it. Equality is the ONLY operation defined on this value. */
export function buildSignature(c: ComponentRecord): string {
  return digest(signatureSource(c));
}

/** The subset of `comps` that HAS buildable preview source (`componentPreviewFiles` non-null) — the scan
 *  targets. Components with no buildable source are deliberately excluded (they're the separate static
 *  `no-implementation` graph-health finding, not a build FAILURE), so this never double-reports them. */
export function scannableComponents(
  comps: ComponentRecord[],
  artifact: KitArtifact,
  // The library resolver the scan judges `@bsc/…` imports with — the ACTIVE project's pinned sound kit
  // when a caller has project context (#3412), else the packaged default. It is part of the build, so a
  // kit switch changes which components build and must reach the scan, not just the live preview.
  libResolver: LibraryModuleResolver = libraryModuleResolver,
): ScannableComponent[] {
  // The packaged artifact's own file keys — its component sources + its runtime closure. Computed ONCE
  // (not per component): it is the same set for every build in this sweep, and `comps` can be hundreds.
  const artifactKeys = new Set<string>([
    ...(artifact.components ?? []).map((a) => a.src),
    ...Object.keys(artifact.runtime ?? {}),
  ]);
  const out: ScannableComponent[] = [];
  for (const c of comps) {
    // #4072 — a LITE record (graph projection) has an empty `srcText` by construction, not because the
    // component lacks source. Scanning it would record a build failure against a component that is
    // fine, and cache that verdict under its signature. Skip until the full read replaces it; the
    // effect re-runs on that swap, so nothing is permanently unscanned.
    if (c.lite) continue;
    // Same-kit siblings so a composing user component's imported siblings vendor into its build (#3112).
    const siblings = comps.filter((s) => s.kitId === c.kitId && s.id !== c.id);
    const build = componentPreviewFiles(c, artifact, siblings, libResolver, undefined, undefined, undefined, graphProvidesResolver);
    if (!build) continue;
    // Everything in the build that is NOT part of the packaged artifact is record-derived, and a change
    // to any of it must re-queue this component — otherwise a fixed dependency leaves every consumer
    // holding a cached failure forever (#4092).
    //
    // Derived by EXCLUDING the artifact's own keys rather than by matching sibling `src`, which is what
    // this did before and what never once matched: `src` is a RECORD path
    // (`src/shared/ui/charts/Charts.tsx`) while `build.files` is keyed by RESOLVED MODULE path
    // (`shared/ui/charts.tsx`). Measured on a real `fleetpage` build, all five charts files came back
    // NOMATCH — so #3112's invalidation was inert across the entire library, and the 16 components that
    // vendor `ui-charts` kept a 2026-07-28 build failure nine minutes older than the fix for it.
    //
    // The artifact is a packaged constant (it changes only with the app build), so excluding it keeps
    // the two contracts the old filter was reaching for: a built-in's whole-artifact file set does NOT
    // fold in, and a component that vendors nothing still gets sig === buildSignature(c) exactly.
    // The component's OWN module is excluded too — `buildSignature(c)` already carries it, and folding
    // it in twice would break the no-dependency contract below.
    const ownImpl = c.source || c.srcText || "";
    const vendored = Object.keys(build.files)
      .filter((k) => k !== build.entry && !artifactKeys.has(k) && build.files[k] !== ownImpl)
      .sort();
    // Runtime data-state probes (#3191): a DATA component (collection prop) also gets an `empty`-state build
    // and a component with a LOADING prop a `loading`-state build, so the scan can render-confirm a BLANK
    // #root in that state. Same file set as loaded — only the sampled props differ (`samplePropValue` empties
    // collections / turns on the loading prop) — so each reuses `componentPreviewFiles(..., state)`.
    const states: StateProbe[] = [];
    if (c.props.some(isCollectionProp)) {
      const s = componentPreviewFiles(c, artifact, siblings, libResolver, "empty", undefined, undefined, graphProvidesResolver);
      if (s) states.push({ category: "empty-empty-state", files: s.files, entry: s.entry });
    }
    if (c.props.some(isLoadingProp)) {
      const s = componentPreviewFiles(c, artifact, siblings, libResolver, "loading", undefined, undefined, graphProvidesResolver);
      if (s) states.push({ category: "empty-loading-state", files: s.files, entry: s.entry });
    }
    // Fold the qualifying states into the sig so adding/removing a collection/loading prop re-queues the
    // component. Appends "" for a stateless component ⇒ sig === buildSignature(c) exactly (pre-#3191 contract).
    //
    // The whole concatenation is hashed ONCE, at the end
    // (#the-scan-signature-is-the-whole-source-not-a-digest) — folding the vendored bodies in and THEN
    // digesting, rather than digesting first and concatenating, which would have left every vendored
    // dependency's full text in the signature and kept the 207 MB. The no-dependency contract still
    // holds exactly: with no vendored files and no states this is `digest(signatureSource(c) + "")`,
    // which IS `buildSignature(c)`.
    const sig = digest(
      (vendored.length
        ? signatureSource(c) + vendored.map((k) => `${k} ${build.files[k]}`).join("")
        : signatureSource(c)) + states.map((s) => s.category).join(""),
    );
    out.push({ id: c.id, sig, files: build.files, entry: build.entry, states: states.length ? states : undefined });
  }
  return out;
}

/** Those whose signature changed since the last scan (or were never scanned) — the re-queue set. Lets a
 *  re-scan skip components already built at their current source, so a revisit / kit-toggle is cheap. */
export function pendingScans(scannable: ScannableComponent[], prevSigs: Map<string, string>): ScannableComponent[] {
  return scannable.filter((s) => prevSigs.get(s.id) !== s.sig);
}

/**
 * Run `worker` over `items` with at most `concurrency` in flight, queueing the rest. Resolves once every
 * item has been processed. Pure — a fixed-size pool of `pump`s each pull the next item until the queue is
 * drained, so no more than `concurrency` `worker` calls overlap. A REJECTING worker rejects the whole
 * run, so callers must make `worker` non-throwing (the scan worker catches build errors and records them).
 */
export async function runPooled<T>(
  items: T[],
  concurrency: number,
  worker: (item: T) => Promise<void>,
): Promise<void> {
  const size = Math.max(1, Math.min(Math.floor(concurrency) || 1, items.length));
  let cursor = 0;
  const pump = async (): Promise<void> => {
    while (cursor < items.length) {
      const item = items[cursor++];
      await worker(item);
    }
  };
  await Promise.all(Array.from({ length: size }, () => pump()));
}

/** Derive a BUILD ok/error status from an esbuild outcome: a `null`/`undefined` error ⇒ ok; anything
 *  else ⇒ a `build` error status with a readable message. Pure. */
export function toBuildStatus(error: unknown): ComponentBuildStatus {
  if (error == null) return { state: "ok" };
  return { state: "error", kind: "build", message: error instanceof Error ? error.message : String(error) };
}

/** Bundle one component's in-memory files → the built ESM module source. `bundleComponent` throws on a
 *  build error, which the scan catches; the resolved JS is handed to the runtime probe (#2908). */
export type BundleFn = (files: Record<string, string>, entry: string) => Promise<string>;

/** Run a built component module and report whether it threw at runtime. Non-throwing by contract: an
 *  INFRA failure (no DOM, a timeout, a probe error) resolves `{ ok: true }` so the scan never
 *  false-badges a healthy component — only a component that DEMONSTRABLY threw is reported not-ok. */
export type RunFn = (bundleJs: string) => Promise<RuntimeOutcome>;

/** The default run step: no runtime probe (build-only scan). Callers that want runtime detection pass a
 *  real `RunFn` (the hook wires `probeComponentRuntime`); tests pass a mock. */
const NO_RUNTIME_PROBE: RunFn = async () => ({ ok: true });

/**
 * Derive one component's status: BUILD it, and if it builds clean, RUN it (#2908). A build throw ⇒ a
 * `build` error; a clean build that then throws at runtime ⇒ a `runtime` error; otherwise ok. The runtime
 * probe is treated as best-effort — if `run` itself rejects (a probe-infrastructure failure, not the
 * component), we fall back to `ok` so a healthy component is never false-badged. Pure given `bundle`/`run`.
 */
export async function buildAndProbe(item: ScannableComponent, bundle: BundleFn, run: RunFn): Promise<ComponentBuildStatus> {
  let js: string;
  try {
    js = await bundle(item.files, item.entry);
  } catch (e) {
    // Preserve a thrown falsy value as a non-null marker so `toBuildStatus` still classifies it error.
    return toBuildStatus(e ?? new Error("preview build failed"));
  }
  let outcome: RuntimeOutcome;
  try {
    outcome = await run(js);
  } catch {
    return { state: "ok" }; // probe infra failure ⇒ inconclusive, never a false badge
  }
  if (!outcome.ok) return { state: "error", kind: "runtime", message: outcome.message };
  // Built + mounted clean, but rendered nothing visible (#2926) — a distinct "no output" signal.
  if (outcome.empty) return { state: "empty", message: "renders nothing — the component mounts but produces no visible output" };
  return { state: "ok" };
}

/**
 * Render-confirm each supported data-STATE of a build-clean component (#3191), returning the categories it
 * renders BLANK in. For each state build, BUILD it then RUN it; a clean mount that renders NOTHING
 * (`ok && empty`) yields that state's category. A build error, a runtime throw, or a non-blank render yields
 * nothing — conservative: only a demonstrable, render-confirmed blank flags (a real EmptyState / skeleton
 * renders content ⇒ never flagged). Called ONLY when the component rendered fine LOADED, so a finding here
 * is precisely "works normally but blanks in this state". Pure given `bundle`/`run` (the hook wires the real
 * esbuild bundle + iframe probe; tests pass mocks).
 */
export async function probeStateBlanks(states: StateProbe[], bundle: BundleFn, run: RunFn): Promise<RuntimeStateCategory[]> {
  const blanks: RuntimeStateCategory[] = [];
  for (const s of states) {
    let js: string;
    try {
      js = await bundle(s.files, s.entry);
    } catch {
      continue; // a state build that won't compile isn't a blank-render signal — skip it
    }
    let outcome: RuntimeOutcome;
    try {
      outcome = await run(js);
    } catch {
      continue; // probe-infra failure ⇒ inconclusive, never a false flag
    }
    if (outcome.ok && outcome.empty) blanks.push(s.category);
  }
  return blanks;
}

/**
 * Scan each buildable component (build + optional runtime probe), throttled to `concurrency` in flight,
 * reporting ok / build-error / runtime-error per id via `onResult`. A build failure (esbuild) OR a runtime
 * throw (`run`) is recorded as an error status — one bad component never aborts the sweep. `isCancelled`
 * short-circuits both before work starts and before its result is reported, so an unmount / re-scan
 * doesn't write stale state. `run` defaults to a no-op probe (build-only) so existing callers/tests keep
 * their behavior; the hook passes the real `probeComponentRuntime`.
 *
 * The scan's spine, kept pure (no React, no esbuild, no DOM): the hook passes the real `bundleComponent`
 * + `probeComponentRuntime` + a store setter; a test passes mocks and asserts the derived statuses.
 *
 * `onResult`'s third arg is the render-confirmed data-state blanks (#3191) — the `empty-empty-state` /
 * `empty-loading-state` categories the component blanks in, probed ONLY when it built + rendered fine LOADED
 * (a blank-loaded #2926 / errored component is already reported, so its state probes would be noise). Empty
 * for a component with no such fault or no probed states; a 2-arg `onResult` callback simply ignores it.
 */
export async function scanComponents(
  scannable: ScannableComponent[],
  bundle: BundleFn,
  concurrency: number,
  onResult: (id: string, status: ComponentBuildStatus, stateBlanks: RuntimeStateCategory[]) => void,
  isCancelled: () => boolean = () => false,
  run: RunFn = NO_RUNTIME_PROBE,
): Promise<void> {
  await runPooled(scannable, concurrency, async (item) => {
    if (isCancelled()) return;
    const status = await buildAndProbe(item, bundle, run);
    const stateBlanks = status.state === "ok" && item.states?.length
      ? await probeStateBlanks(item.states, bundle, run)
      : [];
    if (isCancelled()) return;
    onResult(item.id, status, stateBlanks);
  });
}

// Composition-graph layout (#2455, #2964, #2970) — the pure, hierarchical TOP-DOWN placement for the
// Design Studio's composition graph, banded into four SEMANTIC ROLE TIERS and labeled as swimlanes:
//
//   • PAGES (top)         — complete ideas / whole screens (`role === "page"`).
//   • LAYOUTS             — structural POSITIONERS: arrange children, render no content of their own
//                           (`role === "layout"` — Box, Stack, Grid, MasterDetail, …). The maintainer's
//                           flexbox framing — the scaffold the content sits in — so they rank just under
//                           Pages, ABOVE the composables that fill them (#2970).
//   • COMPOSABLES         — assembled widgets (`role` composite / service — Card, Dialog, StatCard, …).
//   • FUNDAMENTALS (base) — content atoms (`role === "primitive"` — Button, Text, Chip, …).
//
// Purely ROLE-DRIVEN (#2970): the tier is the component's kind, so a composition ROOT nobody uses yet
// (an unwired composite like `ItemBars`) no longer floats up into the page band — it sits in Composables
// where it belongs. Composition (`composes`) is the EDGE set + still drawn, but no longer the y-axis.
// One band per present tier, ordered within by importance (`used` desc, name tiebreak), wrapping into
// sub-rows past `maxPerRow`. The `lanes` tile the world height so the chrome can label each tier.
//
// Pure and React-free; DesignsWorkbench's graph memo is a single call to `layoutComposition`.
import type { GraphEdge } from "@/shared/lib/graph/types";
import type { ComponentRecord, Role } from "@/features/designs/lib/model";

/** Graph node box (world coords) — shared with the GraphView's node + edge rendering. */
export const NODE_W = 170;
export const NODE_H = 54;

export interface CompositionLayoutMetrics {
  nodeW: number;
  nodeH: number;
  /** Horizontal clearance between nodes in a row. */
  hGap: number;
  /** Vertical clearance between depth bands (the hierarchy gap the edges cross). */
  bandGap: number;
  /** Vertical clearance between wrapped sub-rows inside one band. */
  subRowGap: number;
  /** World padding around the whole layout. */
  pad: number;
  /** A band wraps onto a new sub-row after this many nodes. */
  maxPerRow: number;
}

export const DEFAULT_METRICS: CompositionLayoutMetrics = {
  nodeW: NODE_W, nodeH: NODE_H, hGap: 28, bandGap: 92, subRowGap: 26, pad: 60, maxPerRow: 8,
};

/** A semantic vertical tier (#2964/#2970), top → bottom: complete ideas (`page`), structural positioners
 *  (`layout`), assembled widgets (`composable`), content atoms (`fundamental`). */
export type Tier = "page" | "layout" | "composable" | "fundamental";

/** Tier order, top → bottom. */
export const TIER_ORDER: readonly Tier[] = ["page", "layout", "composable", "fundamental"];

/** The lane label shown for each tier. */
export const LANE_LABEL: Record<Tier, string> = {
  page: "Pages",
  layout: "Layouts",
  composable: "Composables",
  fundamental: "Fundamentals",
};

/** One horizontal swimlane — a tier's full-width vertical extent in world coords (tiled to fill). */
export interface CompositionLane {
  tier: Tier;
  label: string;
  y0: number;
  y1: number;
}

export interface CompositionLayout {
  pos: Map<string, { x: number; y: number }>;
  edges: GraphEdge[];
  world: { w: number; h: number };
  /** Node id → its vertical band (0 = top row). Exposed for tests + the lane chrome. */
  depth: Map<string, number>;
  /** Node id → its semantic tier (#2964/#2970). */
  tier: Map<string, Tier>;
  /** The swimlanes, top → bottom — one per PRESENT tier, tiled to fill the world height. */
  lanes: CompositionLane[];
}

/**
 * The semantic tier a component belongs to (#2970) — purely by its architectural `role`:
 * `page` → Pages, `layout` → Layouts (a structural positioner), `primitive` → Fundamentals (a content
 * atom), everything else (`composite`, `service`) → Composables (an assembled widget).
 */
export function nodeTier(role: Role): Tier {
  if (role === "page") return "page";
  if (role === "layout") return "layout";
  if (role === "primitive") return "fundamental";
  return "composable";
}

/** Sort components by graph TIER (Pages → Layouts → Composables → Fundamentals), then importance
 *  (`used` desc, name tiebreak). The rail (#2976) sorts its list with this so it reads like the graph. */
export const byTier = (a: ComponentRecord, b: ComponentRecord): number =>
  TIER_ORDER.indexOf(nodeTier(a.role)) - TIER_ORDER.indexOf(nodeTier(b.role)) ||
  b.used - a.used ||
  a.name.localeCompare(b.name);

/** The kit's `composes` names resolved to in-kit edges (composer → dependency). Names that don't
 *  resolve to a component in `comps` are dropped — no dangling graph edges. */
export function buildComposesEdges(comps: readonly ComponentRecord[]): GraphEdge[] {
  const idByName = new Map(comps.map((c) => [c.name, c.id] as const));
  const edges: GraphEdge[] = [];
  for (const c of comps) {
    for (const dep of c.composes) {
      const to = idByName.get(dep);
      if (to) edges.push({ id: `${c.id}->${to}`, from: c.id, to });
    }
  }
  return edges;
}

/** Within-row importance order: `used` descending, stable name tiebreak. */
const byImportance = (a: ComponentRecord, b: ComponentRecord): number =>
  b.used - a.used || a.name.localeCompare(b.name);

/**
 * Compute the tier-banded, top-down composition layout for one kit's components.
 *
 * One band per PRESENT tier, in `TIER_ORDER` (an absent tier leaves no gap). Each band is ordered by
 * importance and wraps into sub-rows past `maxPerRow`. The `lanes` tile the world height so the chrome
 * can label each tier.
 */
export function layoutComposition(
  comps: readonly ComponentRecord[],
  metrics: CompositionLayoutMetrics = DEFAULT_METRICS,
): CompositionLayout {
  const m = metrics;
  const edges = buildComposesEdges(comps);

  const tier = new Map<string, Tier>();
  for (const c of comps) tier.set(c.id, nodeTier(c.role));

  // One band per PRESENT tier, top → bottom in TIER_ORDER.
  const present = TIER_ORDER.filter((t) => comps.some((c) => tier.get(c.id) === t));
  const bandOfTier = new Map<Tier, number>(present.map((t, i) => [t, i]));
  const depth = new Map<string, number>();
  for (const c of comps) depth.set(c.id, bandOfTier.get(tier.get(c.id)!)!);

  // Band the nodes by depth, order each band by importance, wrap into sub-rows.
  const bands = new Map<number, ComponentRecord[]>();
  for (const c of comps) {
    const d = depth.get(c.id)!;
    const band = bands.get(d);
    if (band) band.push(c); else bands.set(d, [c]);
  }
  const bandRows: ComponentRecord[][][] = [...bands.entries()]
    .sort(([a], [b]) => a - b)
    .map(([, band]) => {
      const sorted = band.sort(byImportance);
      const rows: ComponentRecord[][] = [];
      for (let i = 0; i < sorted.length; i += m.maxPerRow) rows.push(sorted.slice(i, i + m.maxPerRow));
      return rows;
    });

  const rowWidth = (n: number) => n * m.nodeW + (n - 1) * m.hGap;
  const maxRow = Math.max(0, ...bandRows.flat().map((r) => r.length));
  const w = Math.max(400, 2 * m.pad + rowWidth(maxRow));

  const pos = new Map<string, { x: number; y: number }>();
  let y = m.pad;
  let bottom = m.pad;
  for (let bi = 0; bi < bandRows.length; bi++) {
    const rows = bandRows[bi];
    for (let ri = 0; ri < rows.length; ri++) {
      const row = rows[ri];
      const x0 = (w - rowWidth(row.length)) / 2;   // center each row — hubs sit toward the middle
      row.forEach((c, i) => pos.set(c.id, { x: x0 + i * (m.nodeW + m.hGap), y }));
      bottom = y + m.nodeH;
      y += m.nodeH + (ri < rows.length - 1 ? m.subRowGap : m.bandGap);
    }
  }
  const h = Math.max(300, bottom + m.pad);

  // Swimlanes: each present tier's vertical extent, tiled to fill the world height (a boundary falls at
  // the midpoint of the gap between adjacent tiers; the top lane starts at 0, the bottom ends at `h`).
  const tierYs = new Map<Tier, { min: number; max: number }>();
  for (const c of comps) {
    const p = pos.get(c.id)!;
    const t = tier.get(c.id)!;
    const cur = tierYs.get(t);
    if (cur) { cur.min = Math.min(cur.min, p.y); cur.max = Math.max(cur.max, p.y + m.nodeH); }
    else tierYs.set(t, { min: p.y, max: p.y + m.nodeH });
  }
  const lanes: CompositionLane[] = present.map((t, i) => ({
    tier: t,
    label: LANE_LABEL[t],
    y0: i === 0 ? 0 : (tierYs.get(present[i - 1])!.max + tierYs.get(t)!.min) / 2,
    y1: i === present.length - 1 ? h : (tierYs.get(t)!.max + tierYs.get(present[i + 1])!.min) / 2,
  }));

  return { pos, edges, world: { w, h }, depth, tier, lanes };
}

// `selectionNeighborhood` (#2523) was promoted to a shared graph util (#2719) — it's a pure,
// layout-agnostic edge/node query, not composition-specific. Re-exported here so the existing
// intra-feature importers (DesignsWorkbench, this feature's tests) don't churn.
export { selectionNeighborhood, type SelectionNeighborhood } from "@/shared/lib/graph/selectionNeighborhood";

// Confirm reconciliation (#2256) — the PURE decision behind the poll's durable-confirmation sync.
// plan.db is the durable store of which stages the user confirmed (each with a content fingerprint);
// the app-state mirrors it. Every poll tick this decides three disjoint actions from the plan.db rows,
// the live section content, and the current store set. Pure + serializable → unit-testable without
// Tauri; the poll just applies the result.

import { hashString } from "@/shared/lib/core/hashString";

/** One durable confirmation row from `bsc plan confirm list` — a stage + its confirm-time fingerprint. */
export interface ConfirmRow {
  stage: string;
  fingerprint: string;
}

export interface ConfirmReconcile {
  /** Durably-confirmed stages whose content is UNCHANGED but missing from the store — restore them
   *  (rehydrate on revisit). Applied via `markStageConfirmedLocal` (no plan.db echo). */
  rehydrate: string[];
  /** Confirmed stages whose content CHANGED since confirm — reset just these (the per-stage reset).
   *  Applied via `unconfirmPlanStage` (drops store + plan.db). */
  reset: string[];
  /** Store confirmations with no plan.db row yet — forward-migrate them into plan.db (one-time, when
   *  plan.db has none and we haven't migrated this project). */
  migrate: string[];
}

/**
 * Decide the confirm reconciliation for one poll tick.
 *
 * - When plan.db has NO rows but the store does and this project hasn't been migrated → forward-migrate
 *   the store's confirmations into plan.db (the pre-#2256 app-state-only set becomes durable).
 * - Otherwise plan.db is authoritative: a row whose live content fingerprint MATCHES is rehydrated into
 *   the store (if absent); a MISMATCH means the stage's content changed → reset just that stage.
 */
export function reconcileConfirmations(
  rows: ConfirmRow[],
  liveSections: Record<string, string>,
  storeConfirmed: Set<string>,
  migrated: boolean,
): ConfirmReconcile {
  if (rows.length === 0 && storeConfirmed.size > 0 && !migrated) {
    return { rehydrate: [], reset: [], migrate: [...storeConfirmed] };
  }
  const rehydrate: string[] = [];
  const reset: string[] = [];
  for (const { stage, fingerprint } of rows) {
    if (hashString(liveSections[stage] ?? "") === fingerprint) {
      if (!storeConfirmed.has(stage)) rehydrate.push(stage);
    } else {
      reset.push(stage);
    }
  }
  return { rehydrate, reset, migrate: [] };
}

export interface SkipReconcile {
  /** Durably-skipped stages missing from the store — restore them (rehydrate on revisit). */
  rehydrate: string[];
  /** Store skips with no plan.db row yet — forward-migrate them into plan.db (one-time). */
  migrate: string[];
}

/**
 * Decide the skipped-stage reconciliation for one poll tick (#2267). Simpler than confirmations: a
 * skip is a plain decision (no fingerprint / reset-on-change), so plan.db just needs to be the durable
 * mirror. When plan.db has NO rows but the store does and this project hasn't been migrated → forward-
 * migrate the store's skips into plan.db; otherwise restore any durable skip missing from the store.
 */
export function reconcileSkips(rows: string[], storeSkipped: Set<string>, migrated: boolean): SkipReconcile {
  if (rows.length === 0 && storeSkipped.size > 0 && !migrated) {
    return { rehydrate: [], migrate: [...storeSkipped] };
  }
  return { rehydrate: rows.filter((s) => !storeSkipped.has(s)), migrate: [] };
}

/** One section as the focused-plan derivation sees it — key + draft/confirm state. */
export interface SectionState {
  k: string;
  state: "confirmed" | "drafted" | "pending";
}

/**
 * Stages to auto-confirm when a PUBLISHED project is reopened with NO durable confirmations yet
 * (#2259 backfill for pre-#2256 projects): every **drafted** section (content present, not yet
 * confirmed). A published project's discovery sections were all confirmed to reach publish, so
 * restoring them avoids a pointless reconfirm pass on reopen. The CALLER gates this to published
 * projects with an empty confirmed set — this pure helper just picks the drafted sections. `pending`
 * (no content) sections are never backfilled (nothing was confirmed there).
 */
export function stagesToBackfill(sections: SectionState[], alreadyConfirmed: Set<string>): string[] {
  return sections.filter((s) => s.state === "drafted" && !alreadyConfirmed.has(s.k)).map((s) => s.k);
}

// Deterministic fleet conformance check (#1102) — the non-injectable, no-LLM core of the
// warden. Given a session's TRUSTED plan anchor (its stream's owned globs + role + flow, all
// authored by the planner/app and none of it attacker-rewritable at runtime) and the session's
// observed activity (committed file changes + attempted shell commands), it flags anything
// off-plan: a diff outside the stream's lane, or a command the session's effective gate forbids
// (a role-denied write, or a push the flow blocks).
//
// Trust model: the watcher must be LESS exposed than the watched. This module reads ONLY
// structured, trusted signals — the plan anchor, the git diff, the bsc-audit command log — never
// the issue/PR/web prose a worker ingests, so it can't itself be steered by an injection. The
// fuzzy LLM judge is escalated to only ON a trip (or a sampled spot-check), off this hot path.
//
// Pure + unit-tested, so the warden wiring (who runs it, how often, the auto-pause response)
// layers on top without re-deriving the rules. Mirrors the launch gate exactly (role denies
// minus flow grants #304, plus the push a commit-only/none flow blocks) so it never flags a
// command the session is actually permitted to run.

import { matchGlob, roleDeniedCommands, type RoleCapability } from "@/shared/lib/session/sessionRoles";
import type { AgentFlow } from "@/features/planner/fleet/agentFlow";
// shared/ is feature-agnostic (#1626), but the warden's conformance check MUST mirror the launch
// gate exactly, and the launch gate's push policy is derived by these two pure flow→permission
// functions. They depend transitively on the planner's `agentFlow` (AgentFlow/resolveFlow), so
// relocating them into shared would just pull the planner's flow domain along — disproportionate.
// Deliberate, scoped exception (the only feature VALUE import left in shared/, see #1626).
// eslint-disable-next-line @typescript-eslint/no-restricted-imports
import { flowGrantedPushCommands, flowPermissionRules } from "@/features/planner/fleet/flowPermissions";

/** GitHub-propagation commands the flow governs (mirrors flowPermissions' PUSH_WRITE_RULES). */
const PUSH_COMMANDS = ["git push", "gh pr create"];

/** The trusted, plan-sourced ground truth a session is checked against — its `AgentStream`
 *  fields (`id`, `owns`, role, `flow`), authored by the planner/app, not rewritable at runtime. */
export interface StreamAnchor {
  streamId: string;
  /** File globs the stream owns; writing outside them is off-lane. Empty ⇒ no lane constraint. */
  ownedGlobs: string[];
  /** The session's role gate (least privilege), with the stream's globs as its write boundary. */
  capability: RoleCapability;
  /** The session's execution flow (push policy). Unset ⇒ the default flow. */
  flow?: AgentFlow;
}

/** Observed, attributable activity for one session — collected by the warden from TRUSTED
 *  telemetry: `git diff --name-only` and the `bsc-audit` command log, never from prose. */
export interface SessionActivity {
  /** Repo-relative paths the session changed (committed or staged). */
  changedFiles: string[];
  /** Shell commands the session attempted (bsc-audit targets for the Bash tool). */
  commands: string[];
}

export type ConformanceTrip =
  | { kind: "out-of-glob"; detail: string }      // changed a file outside the stream's owned globs
  | { kind: "denied-command"; detail: string };  // attempted a command the effective gate forbids

export interface ConformanceVerdict {
  /** True when nothing tripped — the session looks on-plan by the deterministic checks. */
  onTask: boolean;
  trips: ConformanceTrip[];
}

/** The command prefixes the session's EFFECTIVE gate forbids: the role denies (minus any the
 *  flow grants, #304) plus the push commands a commit-only/none flow blocks. Mirrors the launch
 *  gate so the check never flags a command the session is actually allowed to run. */
export function effectiveDeniedCommands(cap: RoleCapability, flow?: AgentFlow): string[] {
  const granted = flowGrantedPushCommands(flow);
  const roleDenies = roleDeniedCommands(cap).filter((d) => !granted.includes(d));
  // A commit-only / none flow contributes a hard push deny (flowPermissionRules.denyToolRules);
  // auto-pr / push-confirm grant push instead, so nothing to add there.
  const flowDeniesPush = flowPermissionRules(flow).denyToolRules.length > 0;
  const pushDenies = flowDeniesPush ? PUSH_COMMANDS.filter((p) => !granted.includes(p)) : [];
  return Array.from(new Set([...roleDenies, ...pushDenies]));
}

/**
 * Files the APP authors, or explicitly instructs the agent to write (#3980). Never a worker's drift,
 * so never a lane trip.
 *
 * This is not a convenience carve-out — without it the warden punishes workers for the launch path's
 * own writes. Measured: 22 quarantined sessions, 20 of them for exactly these two files. The warden
 * KILLS the PTY when it quarantines, so each one was a dead session.
 *
 *  · `CLAUDE.local.md` — written by `ensure_worktree` → `write_worker_context`. It is the worker's own
 *    scope doc, placed in the worktree by the launcher. No stream's `owns` globs list it, because it
 *    is not the worker's file to claim — so it can never be in lane, for anyone.
 *  · `DECISIONS.md`    — `bsc-note`'s default target (`$BSC_DECISIONS_DOC`), a helper the app installs
 *    into every session via `BASH_ENV`. Using documented tooling must not be drift.
 *
 * A NAMED list, deliberately, not a pattern: a pattern like "dotfiles" or "looks like scratch" would
 * widen silently and hole the drift check. Agent-invented scratch (`.agentscratch.txt`, `.tmp-agent/…`)
 * is NOT here — that is the agent's own choice rather than the app's instruction, and it needs its own
 * decision rather than being swept in.
 */
export const APP_SANCTIONED_FILES: readonly string[] = ["CLAUDE.local.md", "DECISIONS.md"];

/** Whether the app itself owns this path (basename match — these live at the worktree root, but a
 *  nested copy is equally app-authored). Pure. */
export function isAppSanctioned(file: string): boolean {
  const base = file.replace(/[\\/]+$/, "").split(/[\\/]/).pop() ?? "";
  return APP_SANCTIONED_FILES.includes(base);
}

/** Whether a changed file falls inside the stream's lane (its owned globs). A lane-less stream
 *  (no owned globs) imposes no file constraint. App-authored files are always in lane (#3980). */
function inLane(file: string, ownedGlobs: string[]): boolean {
  if (isAppSanctioned(file)) return true;
  return ownedGlobs.length === 0 || ownedGlobs.some((g) => matchGlob(g, file));
}

/** The forbidden prefix a command hits, or null. Whole-word at the boundary so "git pushy" does
 *  not match "git push" and "gh pr createx" does not match "gh pr create". */
function deniedPrefixHit(cmd: string, denied: string[]): string | null {
  const c = cmd.trim();
  for (const d of denied) {
    if (c === d || c.startsWith(d + " ")) return d;
  }
  return null;
}

/** Deterministic conformance check: is this session on-plan? No LLM, no untrusted input —
 *  a trip is the signal to pause + escalate, never a quiet pass that hides drift. */
export function checkConformance(anchor: StreamAnchor, activity: SessionActivity): ConformanceVerdict {
  const trips: ConformanceTrip[] = [];

  // 1. Files changed outside the stream's owned lane.
  for (const f of activity.changedFiles) {
    if (!inLane(f, anchor.ownedGlobs)) {
      trips.push({ kind: "out-of-glob", detail: f });
    }
  }

  // 2. Commands the session's effective gate forbids (role-denied or flow-blocked push).
  const denied = effectiveDeniedCommands(anchor.capability, anchor.flow);
  for (const c of activity.commands) {
    if (deniedPrefixHit(c, denied)) {
      trips.push({ kind: "denied-command", detail: c.trim() });
    }
  }

  return { onTask: trips.length === 0, trips };
}

// Focus policy for console panes.

// Canonical pane-status vocabulary (#435), re-exported for this module's importers.
export type { PaneStatus } from "@/app/console/lib/paneStatus";
import type { PaneStatus } from "@/app/console/lib/paneStatus";

/**
 * Whether replying to the focused agent — it just went idle -> run — should
 * auto-advance focus to the next waiting pane (complete an interaction, move on).
 * Only the focused pane's reply triggers it; a background pane resuming on its
 * own must not move the cursor.
 */
export function shouldAdvanceOnReply(
  prevStatus: PaneStatus,
  status: PaneStatus,
  paneIdx: number,
  focusedIdx: number,
): boolean {
  return status === "run" && prevStatus === "idle" && focusedIdx >= 0 && paneIdx === focusedIdx;
}

/**
 * Resolve the next `fullscreenPaneIdx` when toggling maximize/minimize on a pane.
 * Shared by the header button (via Console's handler) and the Ctrl+Shift+F hotkey
 * so both follow identical maximize ⇄ restore semantics.
 *
 * @param targetIdx the pane to act on (e.g. the focused pane); negative means
 *   nothing is selected.
 * @param currentFullscreenIdx the pane currently maximized, or -1 for none.
 * @returns -1 to restore the grid (target was already maximized), the target
 *   index to maximize it, or `null` when there is no pane to act on (no-op).
 */
export function nextFullscreen(targetIdx: number, currentFullscreenIdx: number): number | null {
  if (targetIdx < 0) return null;
  return currentFullscreenIdx === targetIdx ? -1 : targetIdx;
}

// Agents — live console/pane model derived from the real workspace tabs (#1643).
//
// Each workspace tab is a "console"; each live (non-disabled) pane is a row. An
// unassigned pane shows the safe default (Sandboxed) but is only ENFORCED once a
// profile is assigned to it. Pure — split out of SecurityWorkspace so the derivation is
// unit-testable and React-free.

import type { ConsoleSession, ConsolePane } from "@/features/security/lib/agentProfiles";

/** The minimal tab shape this derivation needs (a subset of the store's `Tab`). */
export interface ConsoleTab {
  name: string;
  /** Grid layout like `"2×2"` — cols × rows. */
  layout: string;
}

export interface DeriveConsolesArgs {
  tabs: readonly ConsoleTab[];
  /** Per-tab, per-pane display name (`paneNames[tabIdx][paneIdx]`). */
  paneNames: Record<number, Record<number, string>>;
  /** Panes that were unmounted / killed, keyed `t{tab}p{pane}`. */
  disabledPanes: Record<string, boolean>;
  /** Per-pane assigned profile id, keyed `t{tab}p{pane}`. */
  paneProfiles: Record<string, string>;
  /** The active repo name (falls back to `—` when none). */
  activeRepoName?: string | null;
}

/**
 * Derive the console/pane model from the workspace tabs. One console per tab; one
 * pane row per live grid cell (disabled panes are skipped). An unassigned pane
 * defaults to `pf_sandbox`.
 */
export function deriveConsoles({
  tabs, paneNames, disabledPanes, paneProfiles, activeRepoName,
}: DeriveConsolesArgs): ConsoleSession[] {
  return tabs.map((t, ti) => {
    const [cols, rows] = t.layout.split("×").map(Number);
    const count = (cols || 1) * (rows || 1);
    const panes: ConsolePane[] = [];
    for (let i = 0; i < count; i++) {
      const pid = `t${ti}p${i}`;
      if (disabledPanes[pid]) continue;
      panes.push({
        id: pid,
        agent: paneNames[ti]?.[i] ?? `pane ${i + 1}`,
        status: "idle",
        profileId: paneProfiles[pid] ?? "pf_sandbox",
      });
    }
    return { id: `t${ti}`, name: t.name, repo: activeRepoName ?? "—", status: "running", projectAllow: [], panes };
  });
}

// ConsoleSlice — extracted from the store implementation (store split, stage 2).
// Typed Pick<AppStore, …> so AppStore stays whole in types.ts while the create() composes slices.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import type { InterruptedLoop } from "@/store/types/console";
import { bscJson } from "@/shared/lib/core/bsc";
