type ConsoleSlice = Pick<AppStore,
  "activeWorkspace" | "setWorkspace" | "navigate" | "hasHydrated" | "setHasHydrated" | "tabs" | "activeTabIdx" | "paneMenuOpenIdx" | "focusedPaneIdx" | "fullscreenPaneIdx" | "consoleBroadcast" | "setConsoleBroadcast" | "focusQueue" | "focusTarget" | "setFocusTarget" | "enqueueFocus" | "removeFocus" | "clearFocusQueue" | "reconcileFocusQueue" | "advanceFocus" | "terminalFontSize" | "setTerminalFontSize" | "accent" | "setAccent" | "kitTheme" | "setKitTheme" | "soundNotifications" | "setSoundNotifications" | "ttsEnabled" | "setTtsEnabled" | "ttsRate" | "setTtsRate" | "ttsVoice" | "setTtsVoice" | "ttsVerbosity" | "setTtsVerbosity" | "keybindings" | "setKeybinding" | "resetKeybinding" | "resetAllKeybindings" | "paneViews" | "paneNames" | "paneCwds" | "paneWasClaude" | "uncleanShutdown" | "setUncleanShutdown" | "interruptedLoops" | "probeInterruptedLoops" | "reapInterruptedLoops" | "dismissInterruptedLoops" | "restoreRequested" | "restoreSessionsFromCrash" | "achievements" | "unlockAchievement" | "setPaneWasClaude" | "setPaneCwd" | "paneStatus" | "setPaneStatus" | "quarantinedPanes" | "markQuarantine" | "clearQuarantine" | "acknowledgeQuarantine" | "wardenSince" | "clearProjectQuarantine" | "endedPanes" | "markPaneEnded" | "clearEndedPanes" | "reopenPane" | "dormantPanes" | "paneLastActivity" | "idleReaper" | "reapPane" | "resumePane" | "resumePaneSession" | "setIdleReaperConfig" | "recomputeTabState" | "clearTabStatuses" | "paneInitCmds" | "setPaneInitCmd" | "paneStartupPromptDocs" | "paneCheckpointDocs" | "paneStartupPromptText" | "paneContinue" | "disabledPanes" | "setPaneDisabled" | "paneRoles" | "setPaneRole" | "panePersonas" | "setPanePersona" | "agentProfiles" | "setAgentProfiles" | "updateAgentProfile" | "panePermsStale" | "clearPanePermsStale" | "paneRedrawNonce" | "requestPaneRedraw" | "paneProfiles" | "paneRoleGlobs" | "paneRepos" | "paneFlows" | "paneProviders" | "setPaneProvider" | "paneWslDistro" | "paneMaintaining" | "setPaneMaintaining" | "paneAttention" | "setPaneAttention" | "paneClaudeActive" | "setPaneClaudeActive" | "setPaneProfile" | "setActiveTab" | "addTab" | "closeTab" | "moveTab" | "renameTab" | "setTabState" | "setTabLayout" | "setPaneMenu" | "setFocusedPane" | "setFullscreenPane" | "focusedAgentName" | "setFocusedAgentName" | "setPaneView" | "setAllPanesView" | "setPaneName" | "liveAgents" | "bumpLiveAgents" | "paneDirectorDrive" | "paneDirectorMode" | "paneStream"
>;

/** Shallow equality for a pane->flag map, so an unchanged read does not re-render the graph. The
 *  pane-activity table is re-read on every activity-log write and is usually identical. */
function sameFlagMap(a: Record<string, boolean>, b: Record<string, boolean>): boolean {
  const ka = Object.keys(a), kb = Object.keys(b);
  return ka.length === kb.length && ka.every((k) => a[k] === b[k]);
}

export const createConsoleSlice: StateCreator<AppStore, [], [], ConsoleSlice> = (set, get) => ({
      activeWorkspace: "console",
      setWorkspace: (screen) => set({ activeWorkspace: screen }),
      // #3602: switch workspace AND set its page/entity together, so a jump can't forget the page.
      // applyNavigation calls store setters (each fires its own `set`); get() hands it the live store.
      navigate: (loc) => applyNavigation(get(), loc),
      hasHydrated: false,
      setHasHydrated: (v) => set({ hasHydrated: v }),

      tabs: [],
      activeTabIdx: 0,
      paneMenuOpenIdx: -1,
      focusedPaneIdx: -1,
      fullscreenPaneIdx: -1,
      consoleBroadcast: false,
      setConsoleBroadcast: (v) => set({ consoleBroadcast: v }),
      focusQueue: [],
      focusTarget: DEFAULT_FOCUS_TARGET,
      setFocusTarget: (target) =>
        // Re-gate the live queue against the new target so panes that no longer
        // match drop out (and the cursor isn't stranded on them).
        set((s) => ({
          focusTarget: target,
          focusQueue: s.focusQueue.filter((q) => shouldFocus(s.paneRoles[`t${q.tab}p${q.pane}`], target)),
        })),
      enqueueFocus: (tab, pane) =>
        // Role-aware gate (#392): only queue the pane if its role matches the
        // active focus target (a plain console always queues except under "none").
        set((s) =>
          shouldFocus(s.paneRoles[`t${tab}p${pane}`], s.focusTarget)
            ? { focusQueue: enqueueFocusQueue(s.focusQueue, { tab, pane }) }
            : {}),
      removeFocus: (tab, pane) =>
        set((s) => ({ focusQueue: removeFromQueue(s.focusQueue, { tab, pane }) })),
      clearFocusQueue: () => set({ focusQueue: [] }),
      reconcileFocusQueue: (waitingByTab) =>
        set((s) => ({ focusQueue: reconcileQueue(s.focusQueue, waitingByTab) })),
      // Cycle to the next waiting pane relative to the one you're on (maximized
      // pane if maximized, else focused). Focuses it — switching to its tab first
      // when it lives on another tab — and swaps the maximized pane to it so you
      // stay full-screen. Does NOT dequeue: a pane leaves the queue only when you
      // respond to it (see Console.handleStatusChange).
      advanceFocus: () =>
        set((s) => {
          const pane = s.fullscreenPaneIdx >= 0 ? s.fullscreenPaneIdx : s.focusedPaneIdx;
          const next = nextInCycle(s.focusQueue, { tab: s.activeTabIdx, pane });
          if (next === null) return {};
          const maximized = s.fullscreenPaneIdx >= 0;
          if (next.tab !== s.activeTabIdx) {
            // Hop to the tab holding the waiting console, focusing (and re-maximizing) it.
            return {
              activeTabIdx: next.tab,
              focusedPaneIdx: next.pane,
              fullscreenPaneIdx: maximized ? next.pane : -1,
              paneMenuOpenIdx: -1,
            };
          }
          return maximized
            ? { focusedPaneIdx: next.pane, fullscreenPaneIdx: next.pane }
            : { focusedPaneIdx: next.pane };
        }),
      terminalFontSize: DEFAULT_TERMINAL_FONT_SIZE,
      setTerminalFontSize: (size) => set({ terminalFontSize: clampFontSize(size) }),
      accent: DEFAULT_ACCENT,
      setAccent: (id) => set({ accent: id }),
      kitTheme: DEFAULT_THEME,
      setKitTheme: (id) => set({ kitTheme: id }),
      soundNotifications: false,
      setSoundNotifications: (on) => set({ soundNotifications: on }),
      // App-owned TTS (#3804, a11y Tier 1): opt-in, default OFF. useCoordSpeaker() speaks new fleet
      // coordination events via speechSynthesis when on.
      ttsEnabled: false,
      setTtsEnabled: (on) => set({ ttsEnabled: on }),
      ttsRate: 1,
      setTtsRate: (rate) => set({ ttsRate: rate }),
      ttsVoice: "",
      setTtsVoice: (voiceURI) => set({ ttsVoice: voiceURI }),
      ttsVerbosity: "verbose",
      setTtsVerbosity: (v) => set({ ttsVerbosity: v }),
      keybindings: {},
      setKeybinding: (id, chord) =>
        set((s) => ({ keybindings: setMapEntry(s.keybindings, id, chord) })),
      resetKeybinding: (id) =>
        set((s) => ({ keybindings: deleteMapEntry(s.keybindings, id) })),
      resetAllKeybindings: () => set({ keybindings: {} }),
      paneViews: [],
      paneNames: {},
      paneCwds: {},
      paneWasClaude: {},
  liveAgents: 0,
  bumpLiveAgents: (delta) => set((s) => ({ liveAgents: Math.max(0, s.liveAgents + delta) })),
      achievements: {},
      unlockAchievement: (id) => {
        const next = unlock(get().achievements, id, Date.now());
        if (!next) return false;            // already unlocked — once ever
        set({ achievements: next });
        return true;
      },
      setPaneWasClaude: (paneId, on) =>
        set((s) => {
          const cur = s.paneWasClaude[paneId];
          // Avoid producing a new object reference when nothing changed —
          // OSC 100 "run" can fire many times in a session.
          if (cur === on) return s;
          const next = { ...s.paneWasClaude };
          if (on) next[paneId] = true; else delete next[paneId];
          return { paneWasClaude: next };
        }),
      // Crash recovery (#1041): the boot flag + the one-click restore.
      uncleanShutdown: false,
      setUncleanShutdown: (v: boolean) => set({ uncleanShutdown: v }),

      // #3961 — loops an unclean shutdown stranded. `--dry-run` COUNTS without writing, so the boot
      // probe never mutates the store behind the user's back; the write happens only when they act.
      interruptedLoops: [],
      probeInterruptedLoops: async () => {
        const out = await bscJson<{ loops?: InterruptedLoop[] } | null>(
          null, ["loop", "reap", "--dry-run", "--json"], null);
        set({ interruptedLoops: out?.loops ?? [] });
      },
      reapInterruptedLoops: async () => {
        await bscJson<unknown>(null, ["loop", "reap", "--json"], null);
        set({ interruptedLoops: [] });
      },
      dismissInterruptedLoops: () => set({ interruptedLoops: [] }),
      restoreRequested: {},
      restoreSessionsFromCrash: () => {
        const s = get();
        const panes = Object.keys(s.paneWasClaude).filter((p) => s.paneWasClaude[p]);
        // Stage 3 of stable pane identity (#1176): walk identity ids, not grid positions.
        // Manual consoles (`man:…`) are never auto-recovered — a scratch shell must not silently
        // resume. Fleet/triage panes now carry a project-scoped identity id recorded on the tab's
        // `paneIds[]`, so we locate the hosting tab by that id; a legacy positional id still encodes
        // its tab index directly (fallback).
        let scheduled = 0;
        panes.forEach((paneId) => {
          if (isManualPaneId(paneId)) return;
          let tabIdx = s.tabs.findIndex((t) => t.paneIds?.includes(paneId));
          if (tabIdx < 0) {
            const m = /^t(\d+)p\d+$/.exec(paneId);
            if (!m) return; // unrecognized id shape (no host tab) — not recoverable
            tabIdx = Number(m[1]);
          }
          const order = scheduled++;
          // Stagger the relaunches so N Claudes don't cold-start at once (#1041) — each remount
          // resolves to `claude --continue` because restoreRequested is set for the pane.
          setTimeout(() => {
            set((st) => {
              // Skip disabled panes and auto-ended workers (#920) — a finished worker must not
              // be re-opened on crash-restore; its ended state is persisted + recovery-gated here.
              if (tabIdx < 0 || tabIdx >= st.tabs.length || st.disabledPanes[paneId] || st.endedPanes[paneId]) return {};
              return {
                restoreRequested: setMapEntry(st.restoreRequested, paneId, true),
                tabs: st.tabs.map((t, idx) => (idx === tabIdx ? { ...t, runId: (t.runId ?? 0) + 1 } : t)),
              };
            });
          }, order * 250);
        });
        return scheduled;
      },
      setPaneCwd: (paneId, cwd) =>
        set((s) => ({ paneCwds: setMapEntry(s.paneCwds, paneId, cwd) })),
      paneStatus: {},
      setPaneStatus: (paneId, status) =>
        set((s) => {
          if (s.paneStatus[paneId] === status) return {}; // no-op — same status
          const paneStatus = setMapEntry(s.paneStatus, paneId, status);
          // Stamp last-activity on every status CHANGE (#849): a run↔idle transition is the
          // idle-reaper's clock — for an idle pane this records the moment it went idle, which
          // is exactly what the reaper ages from. (Same-status pings early-return above, so an
          // idle pane that stays idle keeps aging correctly.)
          const paneLastActivity = setMapEntry(s.paneLastActivity, paneId, Date.now());
          // Resolve the owning tab by IDENTITY (#1176) — a manual/minted pane id never
          // parses as a positional `t{idx}p{n}`, so the old positional parse dropped the
          // rollup for every fleet/triage/manual pane (its activity dot got stuck).
          const owner = findPaneOwnerTab(s.tabs, paneId);
          if (!owner) return { paneStatus, paneLastActivity };
          // Re-roll the owning tab from the full live set; only rebuild the tabs
          // array when the rollup actually changes (status events are frequent).
          const nextState = aggregateTabState(owner.tab, owner.tabIdx, paneStatus, s.disabledPanes);
          if (nextState === owner.tab.state) return { paneStatus, paneLastActivity };
          return {
            paneStatus,
            paneLastActivity,
            tabs: updateArrayItem(s.tabs, owner.tabIdx, { state: nextState }),
          };
        }),
      // ── Warden quarantine (#1102) ────────────────────────────────────────────
      quarantinedPanes: {},
      markQuarantine: (paneId, info) =>
        set((s) => (s.quarantinedPanes[paneId]
          ? {} // already quarantined — never re-mark (the warden's planWarden also dedupes)
          : { quarantinedPanes: setMapEntry(s.quarantinedPanes, paneId, info) })),
      // FULLY remove a pane's quarantine — the warden lifts it for a completed worker, and triage
      // relaunch clears it. Stamps the warden floor too, so a stale denied command can't immediately
      // re-trip if the pane is re-evaluated. (Banner dismiss does NOT call this — see acknowledgeQuarantine.)
      clearQuarantine: (paneId) =>
        set((s) => {
          if (!s.quarantinedPanes[paneId]) return {};
          return {
            quarantinedPanes: deleteMapEntry(s.quarantinedPanes, paneId),
            wardenSince: setMapEntry(s.wardenSince, paneId, Date.now()),
          };
        }),
      // Banner dismiss: acknowledge WITHOUT un-quarantining. The pane's PTY is already dead (paused),
      // so we keep it in quarantinedPanes — which the warden's skip-set already honors — and only hide
      // the banner. This stops a still-present out-of-lane edit in the diff from re-tripping every tick
      // and re-showing the banner. A real clear happens on relaunch / completion.
      acknowledgeQuarantine: (paneId) =>
        set((s) => {
          const info = s.quarantinedPanes[paneId];
          if (!info || info.acknowledged) return {};
          return { quarantinedPanes: setMapEntry(s.quarantinedPanes, paneId, { ...info, acknowledged: true }) };
        }),
      wardenSince: {},
      clearProjectQuarantine: (projectKey, panes, since) =>
        set((s) => {
          const prefix = `${projectKey}:`;
          const quarantinedPanes = { ...s.quarantinedPanes };
          for (const paneId of Object.keys(s.quarantinedPanes)) {
            if (paneId.startsWith(prefix)) delete quarantinedPanes[paneId];
          }
          // Stamp the warden floor for EVERY relaunching pane (not just the ones currently flagged),
          // so a stale denied command that hasn't tripped the warden yet also can't re-pause on relaunch.
          const wardenSince = { ...s.wardenSince };
          for (const paneId of panes) wardenSince[paneId] = since;
          return { quarantinedPanes, wardenSince };
        }),
      // ── Auto-end finished workers (#920) ─────────────────────────────────────
      endedPanes: {},
      markPaneEnded: (paneId, info) =>
        set((s) => {
          if (s.endedPanes[paneId]) return {}; // already ended — never re-mark
          // Drop the live status so the pane reads as not-running (its PTY has exited).
          return { endedPanes: setMapEntry(s.endedPanes, paneId, info), paneStatus: deleteMapEntry(s.paneStatus, paneId) };
        }),
      reopenPane: (paneId) =>
        set((s) => {
          if (!s.endedPanes[paneId]) return {};
          return { endedPanes: deleteMapEntry(s.endedPanes, paneId), paneLastActivity: setMapEntry(s.paneLastActivity, paneId, Date.now()) };
        }),
      // ── Idle session reaping (#849) ──────────────────────────────────────────
      dormantPanes: {},
      paneLastActivity: {},
      idleReaper: DEFAULT_REAPER_CONFIG,
      reapPane: (paneId) =>
        set((s) => {
          if (s.dormantPanes[paneId]) return {};
          // Mark dormant + drop the live status so the pane reads as not-running while its
          // PTY is gone (the hook fires pty_kill alongside this).
          return { dormantPanes: setMapEntry(s.dormantPanes, paneId, true), paneStatus: deleteMapEntry(s.paneStatus, paneId) };
        }),
      resumePane: (paneId) =>
        set((s) => {
          if (!s.dormantPanes[paneId]) return {};
          return { dormantPanes: deleteMapEntry(s.dormantPanes, paneId), paneLastActivity: setMapEntry(s.paneLastActivity, paneId, Date.now()) };
        }),
      // Resume a single dormant fleet/agent session in place (#glance-resume). The Glance node
      // "Resume" action lands here for a NON-live agent whose build tab is still open: clearing the
      // ended/disabled/dormant flags remounts JUST this pane's terminal (see PaneAt), and
      // `restoreRequested` makes that remount resolve to `claude --continue` (resolveInitCmd) so the
      // agent's prior conversation resumes. Only this pane is touched — no runId bump — so live
      // siblings in the same tab are untouched. Returns false when no OPEN tab hosts the id, so the
      // caller falls back to a full fleet relaunch (which reopens the build tab).
      clearEndedPanes: (paneIds) =>
        set((st) => {
          // #3916: drop the ENDED flag for a set of panes about to be relaunched. `TerminalView` bails
          // before `pty_create` while a pane is ended, and `endedPanes` is persisted — so without this a
          // project resume rebuilt every pane and started nothing. Unlike `resumePaneSession` this does
          // NOT require the pane to already belong to a tab (the resume clears BEFORE the tab is built)
          // and does not touch dormant/restore state.
          let next = st.endedPanes;
          for (const id of paneIds) if (next[id]) next = deleteMapEntry(next, id);
          return next === st.endedPanes ? {} : { endedPanes: next };
        }),
      resumePaneSession: (paneId) => {
        const s = get();
        const owner = findPaneOwnerTab(s.tabs, paneId);
        if (!owner) return false;
        const disabledPanes = deleteMapEntry(s.disabledPanes, paneId);
        set({
          endedPanes: deleteMapEntry(s.endedPanes, paneId),
          disabledPanes,
          dormantPanes: deleteMapEntry(s.dormantPanes, paneId),
          restoreRequested: setMapEntry(s.restoreRequested, paneId, true),
          paneLastActivity: setMapEntry(s.paneLastActivity, paneId, Date.now()),
          // Re-enabling a cell changes which panes count toward the tab's rollup, so re-roll it
          // (mirrors setPaneDisabled) — otherwise the tab dot can stay stale.
          tabs: s.tabs.map((t, i) =>
            i === owner.tabIdx ? { ...t, state: aggregateTabState(t, i, s.paneStatus, disabledPanes) } : t),
        });
        return true;
      },
      setIdleReaperConfig: (cfg) =>
        set((s) => ({ idleReaper: { ...s.idleReaper, ...cfg } })),
      recomputeTabState: (tabIdx) =>
        set((s) => {
          const tab = s.tabs[tabIdx];
          if (!tab) return {};
          const state = aggregateTabState(tab, tabIdx, s.paneStatus, s.disabledPanes);
          return state === tab.state
            ? {}
            : { tabs: updateArrayItem(s.tabs, tabIdx, { state }) };
        }),
      clearTabStatuses: (tabIdx) =>
        set((s) => {
          const tab = s.tabs[tabIdx];
          if (!tab) return {};
          const paneStatus = clearTabStatusesPure(s.paneStatus, tab, tabIdx);
          const tabs = s.tabs.map((t, i) =>
            i === tabIdx
              ? { ...t, state: aggregateTabState(t, i, paneStatus, s.disabledPanes) }
              : t);
          return { paneStatus, tabs };
        }),
      paneInitCmds: {},
      setPaneInitCmd: (paneId, cmd) =>
        set((s) => ({ paneInitCmds: setMapEntry(s.paneInitCmds, paneId, cmd) })),
      paneStartupPromptDocs: {},
      paneCheckpointDocs: {},
      paneStartupPromptText: {},
      paneContinue: {},
      disabledPanes: {},
      setPaneDisabled: (paneId, disabled) =>
        set((s) => {
          const next = { ...s.disabledPanes };
          if (disabled) next[paneId] = true; else delete next[paneId];
          // Enabling/disabling a pane changes which cells count in its tab's rollup
          // (a disabled cell can't be "run"), so re-roll the owning tab (#435). Resolve
          // the tab by identity so a manual/minted pane id rolls up too (#1176).
          const owner = findPaneOwnerTab(s.tabs, paneId);
          const tabs = owner
            ? s.tabs.map((t, i) =>
                i === owner.tabIdx
                  ? { ...t, state: aggregateTabState(t, i, s.paneStatus, next) }
                  : t)
            : s.tabs;
          return { disabledPanes: next, tabs };
        }),
      paneRoles: {},
      // The PERSONA a pane launches as (epic `the-persona-is-the-whole-agent`). Written beside
      // `paneRoles` wherever a role is assigned, and read FIRST at launch so a persona's own floor —
      // which may be NARROWER than its role's — is what the session actually gets. Transient like
      // `paneRoles` (neither is in the persist allowlist), so there is no migration: both are
      // rewritten by whatever re-seeds the pane after a restart.
      panePersonas: {},
    paneDirectorDrive: {},
    paneDirectorMode: {},
    paneStream: {},
      setPaneRole: (paneId, role) =>
        set((s) => ({ paneRoles: setMapEntry(s.paneRoles, paneId, role) })),
      setPanePersona: (paneId, personaId) =>
        set((s) => ({ panePersonas: setMapEntry(s.panePersonas, paneId, personaId) })),

      // Agents (#255): seed the editable profiles from the built-in defaults; persisted
      // edits replace this on rehydrate. Deep-cloned so edits never mutate the defaults.
      agentProfiles: JSON.parse(JSON.stringify(PROFILES)) as AgentProfile[],
      setAgentProfiles: (profiles) => set({ agentProfiles: profiles }),
      updateAgentProfile: (id, patch) =>
        set((s) => {
          // Mark every console using this profile as stale so it can prompt a relaunch to
          // apply the edit — the launch path rewrites settings.json with replacePermissions (#799).
          const panePermsStale = { ...s.panePermsStale };
          for (const [paneId, profileId] of Object.entries(s.paneProfiles)) {
            if (profileId === id) panePermsStale[paneId] = true;
          }
          return {
            agentProfiles: s.agentProfiles.map((p) => (p.id === id ? { ...p, ...patch } : p)),
            panePermsStale,
          };
        }),
      panePermsStale: {},
      clearPanePermsStale: (paneId) =>
        set((s) => {
          if (!s.panePermsStale[paneId]) return {};
          return { panePermsStale: deleteMapEntry(s.panePermsStale, paneId) };
        }),
      paneRedrawNonce: {},
      requestPaneRedraw: (paneId) =>
        set((s) => ({ paneRedrawNonce: setMapEntry(s.paneRedrawNonce, paneId, (s.paneRedrawNonce[paneId] ?? 0) + 1) })),
      paneProfiles: {},
      paneRoleGlobs: {},
      paneRepos: {},
      paneFlows: {},
      paneProviders: {},
      setPaneProvider: (paneId, providerId) =>
        set((s) => ({ paneProviders: setMapEntry(s.paneProviders, paneId, providerId) })),
      paneWslDistro: {},
      paneMaintaining: {},
      setPaneMaintaining: (panes) =>
        set((s) => (sameFlagMap(s.paneMaintaining, panes) ? {} : { paneMaintaining: panes })),
      paneAttention: {},
      // Replaces the whole map in one set: the source is a full-table read, so a per-pane setter
      // would fire N times per activity-log write for the exact shape #3944 batched away.
      setPaneAttention: (panes) =>
        set((s) => (sameFlagMap(s.paneAttention, panes) ? {} : { paneAttention: panes })),
      paneClaudeActive: {},
      setPaneClaudeActive: (paneId, active) =>
        set((s) => (!!s.paneClaudeActive[paneId] === active
          ? s
          : { paneClaudeActive: setMapEntry(s.paneClaudeActive, paneId, active) })),
      setPaneProfile: (paneId, profileId) =>
        set((s) => {
          const next = { ...s.paneProfiles };
          if (profileId === null) delete next[paneId];
          else next[paneId] = profileId;
          return { paneProfiles: next };
        }),
      // Switching tabs clears focus/fullscreen/menu — these are positional and
      // global, so a stale index from the previous tab would mis-target features
      // like broadcast (excluding a console that isn't actually focused). The focus
      // queue is NOT cleared: it spans tabs now, so waiting consoles left behind on
      // this tab stay reachable via Ctrl+Shift+N (which hops back to them).
      setActiveTab: (idx) => set({ activeTabIdx: idx, focusedPaneIdx: -1, fullscreenPaneIdx: -1, paneMenuOpenIdx: -1 }),
      addTab: (tab) =>
        set((s) => ({
          tabs: [...s.tabs, { ...tab, id: tab.id ?? newTabId() }],
          activeTabIdx: s.tabs.length,
          focusedPaneIdx: -1,
          fullscreenPaneIdx: -1,
          paneMenuOpenIdx: -1,
        })),
      closeTab: (idx) =>
        set((s) => {
          const closing = s.tabs[idx];
          const tabs = s.tabs.filter((_, i) => i !== idx);
          // Drop the closed tab's pane statuses so its sessions' "run"/"on" can't
          // linger as a stale activity dot (#435) — like the focusQueue reset.
          const paneStatus = closing ? clearTabStatusesPure(s.paneStatus, closing, idx) : s.paneStatus;
          // Release the closed tab's worker pane state (#1951). The always-on warden (#1102) watches
          // every pane in `fleetPaneStreams`; leaving the closed tab's now-dead (PTY-killed) workers
          // there means it keeps re-evaluating them, sees the worktree still off-plan, and
          // re-quarantines them every tick — so the "Worker quarantined" banner reappears despite the
          // tab AND the banner being closed. The tab's minted identity ids (`paneIds`) are exactly the
          // keys `fleetStartProject` set in these maps, so drop them here (mirrors that teardown).
          const ids = closing?.paneIds ?? [];
          const released = ids.length
            ? {
                fleetPaneStreams: deleteMapEntries(s.fleetPaneStreams, ids),
                paneCwds: deleteMapEntries(s.paneCwds, ids),
                quarantinedPanes: deleteMapEntries(s.quarantinedPanes, ids),
              }
            : {};
          if (tabs.length === 0) return { tabs, activeTabIdx: 0, focusQueue: [], paneStatus, ...released };
          let activeTabIdx = s.activeTabIdx;
          if (idx < s.activeTabIdx) activeTabIdx -= 1;
          else if (idx === s.activeTabIdx) activeTabIdx = Math.min(activeTabIdx, tabs.length - 1);
          return { tabs, activeTabIdx, focusQueue: [], paneStatus, ...released };
        }),
      moveTab: (from, to) =>
        set((s) => {
          if (from === to || from < 0 || to < 0 || from >= s.tabs.length || to >= s.tabs.length) return {};
          // OLD tab index → NEW tab index; remap every index-keyed structure so
          // a reordered tab keeps its panes' names/cwd/status/disabled/etc.
          const map = tabIndexMap(s.tabs.length, from, to);
          return {
            tabs: moveInArray(s.tabs, from, to),
            activeTabIdx: map[s.activeTabIdx] ?? s.activeTabIdx,
            paneNames: rekeyByTab(s.paneNames, map),
            paneCwds: rekeyByPaneId(s.paneCwds, map),
            paneStatus: rekeyByPaneId(s.paneStatus, map),
            disabledPanes: rekeyByPaneId(s.disabledPanes, map),
            paneMcpServers: rekeyByPaneId(s.paneMcpServers, map),
            paneHooks: rekeyByPaneId(s.paneHooks, map),
            focusQueue: remapFocusQueue(s.focusQueue, map),
          };
        }),
      renameTab: (idx, name) =>
        set((s) => ({ tabs: updateArrayItem(s.tabs, idx, { name }) })),
      setTabState: (tabIdx, state) =>
        set((s) => ({ tabs: updateArrayItem(s.tabs, tabIdx, { state }) })),
      setTabLayout: (tabIdx, layout) =>
        set((s) => {
          const [newCols, newRows] = layout.split("×").map(Number);
          const newCount = newCols * newRows;
          const tabs = [...s.tabs];
          tabs[tabIdx] = { ...tabs[tabIdx], layout };
          // Trim pane names for this tab to only surviving indices
          const tabPaneNames = { ...(s.paneNames[tabIdx] ?? {}) };
          (Object.keys(tabPaneNames) as unknown as number[]).forEach((k) => {
            if (Number(k) >= newCount) delete tabPaneNames[Number(k)];
          });
          // Trim cwds keyed by "t{tabIdx}p{n}"
          const paneCwds = { ...s.paneCwds };
          const isExcess = (key: string) => {
            const m = key.match(/^t(\d+)p(\d+)$/);
            return m && Number(m[1]) === tabIdx && Number(m[2]) >= newCount;
          };
          Object.keys(paneCwds).forEach((key) => { if (isExcess(key)) delete paneCwds[key]; });
          // Re-roll this tab's state against the new grid: cells trimmed away by a
          // smaller layout stop contributing their "run"/"on" (#435).
          tabs[tabIdx] = { ...tabs[tabIdx], state: aggregateTabState(tabs[tabIdx], tabIdx, s.paneStatus, s.disabledPanes) };
          return {
            tabs,
            paneNames: setMapEntry(s.paneNames, tabIdx, tabPaneNames),
            paneCwds,
          };
        }),
      setPaneMenu:       (idx) => set({ paneMenuOpenIdx: idx }),
      setFocusedPane:    (idx) => set({ focusedPaneIdx: idx }),
      setFullscreenPane: (idx) => set({ fullscreenPaneIdx: idx }),
      focusedAgentName: "",
      setFocusedAgentName: (name) => set({ focusedAgentName: name }),
      setPaneView: (idx, view) =>
        set((s) => { const v = [...s.paneViews]; v[idx] = view; return { paneViews: v }; }),
      setAllPanesView: (view) =>
        set((s) => {
          // paneViews is a shared index→view map that defaults to [] and is only grown lazily by
          // setPaneView — so mapping over it was a silent no-op until a pane had been switched
          // individually. Fill at least the ACTIVE tab's pane slots (the point of "switch all"),
          // keeping any higher indices a larger tab may have populated. (#1182)
          const tab = s.tabs[s.activeTabIdx];
          const [c, r] = tab ? tab.layout.split("×").map(Number) : [0, 0];
          const count = Math.max((c || 0) * (r || 0), s.paneViews.length);
          return { paneViews: Array.from({ length: count }, () => view) };
        }),
      setPaneName: (tabIdx, paneIdx, name) =>
        set((s) => ({
          paneNames: setMapEntry(s.paneNames, tabIdx, { ...s.paneNames[tabIdx], [paneIdx]: name }),
        })),
});

// Console kickoff prompts sent as the first message to a launched session. Plain text only
// (no double quotes / $ / backticks) so each is safe to pass as `claude "<prompt>"`. Extracted
// from store/index.ts (store split, stage 1).
//
// The prompt PROSE is externalized to `@data/console/kickoff-prompts.json` (#2416) — editable
// without touching code + part of the exportable config bundle; the config-dir copy (#2047)
// overlays the embedded default via `overlayFile`. This module keeps only the interpolation
// (`fillTemplate` over `{{…}}` placeholders) and the assembly.

import { BSC_ISSUE_LABEL, triageIssueListArgs } from "@/shared/lib/github/issueProvenance";
import kickoffPromptsEmbedded from "@data/console/kickoff-prompts.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";
import { fillTemplate } from "@/shared/lib/core/template";

const PROMPTS = overlayFile("console/kickoff-prompts.json", kickoffPromptsEmbedded);

// Sent as the first message to each console when a project tab is opened, so the
// session starts by reading and executing the laid-out plan. Plain text only — no
// double quotes / $ / backticks — so it's safe to pass as `claude "<prompt>"`.
export const PROJECT_INIT_PROMPT = PROMPTS.projectInit;

// Sent verbatim as the first message to each triage console. Drives an issue
// triage pass over the pane's repo. Plain text only (no double quotes / $ /
// backticks) so it is safe to type into the PTY as a single line.
/**
 * Render the since-last-run delta (#1004) into a one-line lead for the triage prompt, so a re-run
 * resumes cheaply from what changed instead of re-ingesting the whole project. `changed` is the
 * plan.db `issues_changed_since(T)` result; `lastRun` is the marker (null ⇒ first triage). Empty
 * string when there's no marker (a fresh triage gets the full prompt).
 */
export function renderTriageDelta(
  changed: { ref: string; title: string; status: string }[],
  lastRun: number | null,
): string {
  if (lastRun === null) return ""; // never triaged → no delta lead; do the full pass
  if (changed.length === 0) return PROMPTS.triageDelta.noChanges;
  const by = (s: string) => changed.filter((i) => i.status === s).map((i) => i.ref);
  const groups: string[] = [];
  const landed = [...by("complete"), ...by("verified")];
  const stuck = [...by("blocked"), ...by("failed")];
  if (landed.length) groups.push(PROMPTS.triageDelta.groupLanded + landed.join(", "));
  if (stuck.length) groups.push(PROMPTS.triageDelta.groupStuck + stuck.join(", "));
  const detail = groups.length ? ` (${groups.join("; ")})` : "";
  return fillTemplate(PROMPTS.triageDelta.changed, { COUNT: String(changed.length), DETAIL: detail });
}

/**
 * The triage kickoff. When `restrictToBsc` (the secure default, #738), triage works ONLY
 * issues authored by base-studio-code (the `bsc-generated` label) and treats every other open
 * issue as untrusted — so a hand-created or injected issue isn't acted on. Off → all open issues.
 */
export function buildTriagePrompt(restrictToBsc: boolean, delta?: string, local?: boolean): string {
  // #1004: a non-empty delta leads the prompt so the agent resumes from what changed (token-aware).
  const resume = delta && delta.length > 0 ? delta + " " : "";
  // #3281 local-first: with no GitHub, the issues live in plan.db — fetch + work them via `bsc plan`,
  // not `gh`. Every plan.db issue is planner-authored, so the #738 restrict-to-bsc untrusted-external-
  // issue guard doesn't apply (there is no external channel) — the local path ignores `restrictToBsc`.
  if (local) {
    return resume + PROMPTS.triage.leadLocal + PROMPTS.triage.fetchLocal + PROMPTS.triage.rubricLocal;
  }
  const fetch = restrictToBsc
    ? fillTemplate(PROMPTS.triage.fetchRestricted, {
        LABEL: BSC_ISSUE_LABEL,
        LIST_ARGS: triageIssueListArgs(true),
      })
    : fillTemplate(PROMPTS.triage.fetchAll, { LIST_ARGS: triageIssueListArgs(false) });
  return resume + PROMPTS.triage.lead + fetch + PROMPTS.triage.rubric;
}

/** The secure-default triage prompt (bsc-authored issues only). */
export const TRIAGE_PROMPT = buildTriagePrompt(true);

// Design contributions overlay (#2650, epic #2606 slice 5b-1) — the compose-don't-MUTATE application of
// the design tokens a downloaded blueprint contributes. When reconciliation (#2646) fills a blueprint's
// missing categories via the generator (#2636), the generated `--graph-category-<key>: <colour>` tokens
// are REGISTERED as a contribution (provenance = the blueprint), never written into the shared contract
// — `tokens.css` / the descriptor stay untouched. This compiles the registered contributions into ONE
// managed `<style>` of `:root` custom properties, so removing a blueprint drops exactly its overlay with
// no contract file touched. Mirrors the variant overlay (variants.ts) + applyThemeToRoot.
//
// DEFENSE IN DEPTH: the values come from the generator + are stored data, but this compiles them into
// live CSS, so a token NAME must be a safe custom property and a VALUE must not contain a
// declaration-ending / injection sequence. Anything failing is skipped, never emitted.

/** One design contribution — the generated tokens a source (a blueprint) adds to the running app. */
export interface DesignContributionOverlay {
  /** Provenance — the blueprint id the tokens came from, so removing it drops exactly these. */
  source: string;
  /** Full custom-property name (e.g. `--graph-category-simulation`) → value (an oklch/hex colour). */
  tokens: Record<string, string>;
}

const STYLE_ID = "bsc-ui-contributions";
/** A full custom-property name: `--` + a safe identifier tail. */
const SAFE_TOKEN = /^--[a-z][a-z0-9-]*$/;
/** A value that could END the declaration or INJECT CSS — refused (defense in depth). */
const UNSAFE_VALUE = /[;{}<>\\]|url\(|expression\(|@import|\/\*/i;

/** The contract token name a graph-category key fills (#2650): `simulation` → `--graph-category-simulation`. */
export function graphCategoryToken(key: string): string {
  return `--graph-category-${key}`;
}

/** Shape a source's generated category colours into an applicable overlay (#2650): each
 *  `{ category → colour }` becomes its `--graph-category-<key>` token. Colours come from the generator
 *  (`bsc ui generate`) at confirm time; this only maps them. Pure. */
export function contributionFromCategories(source: string, colors: Record<string, string>): DesignContributionOverlay {
  const tokens: Record<string, string> = {};
  for (const [key, color] of Object.entries(colors)) tokens[graphCategoryToken(key)] = color;
  return { source, tokens };
}

/** Compile contributions into ONE `:root { … }` block of custom-property declarations. Pure + guarded:
 *  skips any token whose NAME isn't a safe custom property or whose VALUE looks like an injection; on a
 *  duplicate token the LAST source wins. Empty string when nothing is renderable. */
export function compileContributionsCss(overlays: DesignContributionOverlay[]): string {
  const decls = new Map<string, string>();
  for (const o of overlays ?? []) {
    for (const [name, value] of Object.entries(o?.tokens ?? {})) {
      if (SAFE_TOKEN.test(name) && typeof value === "string" && value && !UNSAFE_VALUE.test(value)) {
        decls.set(name, value);
      }
    }
  }
  if (decls.size === 0) return "";
  return `:root {\n${[...decls].map(([name, value]) => `  ${name}: ${value};`).join("\n")}\n}`;
}

/** Inject / update / clear the managed `<style id="bsc-ui-contributions">`. Removing all contributions
 *  removes the element (the contract's own defaults resume). `doc` is param'd for tests. */
export function applyContributionsToRoot(overlays: DesignContributionOverlay[], doc: Document = document): void {
  const css = compileContributionsCss(overlays);
  let el = doc.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!css) {
    el?.remove();
    return;
  }
  if (!el) {
    el = doc.createElement("style");
    el.id = STYLE_ID;
    doc.head.appendChild(el);
  }
  el.textContent = css;
}

// Mobile → desktop coordination control (#935). The phone can ask the desktop to WAKE a
// parked worker (its blocking dependency landed) or APPROVE a worker paused for the user
// (a checkpoint / push-confirm gate). Both arrive as Tauri events the desktop already
// decodes from the tunnel (`tunnel://coord-wake` / `tunnel://coord-approve`, src-tauri/
// src/tunnel.rs); this module decides — purely, from the coordination state — how to
// honor one. Launching the fleet is deliberately NOT reachable from the phone.

import {
  wakePromptFor,
  waitingWakePrompt,
  type CoordState,
  type Waiter,
} from "@/shared/lib/fleet/coordination";

export type CoordControlKind = "wake" | "approve";

export interface MobileResume {
  session: string;
  /** The wake/resume prompt delivered to the session. */
  prompt: string;
  /**
   * How to deliver it:
   *  - "fresh"  → relaunch the parked pane (a dependency waiter; matches the inbox Wake).
   *  - "inject" → deliver into the live, paused pane (a user-paused gate; keeps context).
   */
  via: "fresh" | "inject";
}

/**
 * Decide how to honor a mobile coordination request for `session`, given the current
 * coordination state and the set of dependency waiters whose deps have landed (`ready`).
 *
 * Returns `null` when the session isn't in a state that request can resolve — we never
 * wake or approve an arbitrary session a phone names, only one the coordination log shows
 * actually parked. So:
 *  - `approve` resolves ONLY a session paused for the user (`state.waiting`).
 *  - `wake` resolves a ready dependency waiter, and also a user-paused session (a phone
 *    "wake" on a paused gate is a reasonable resume), never an unknown session.
 */
export function planMobileResume(
  kind: CoordControlKind,
  session: string,
  state: CoordState,
  ready: Waiter[],
): MobileResume | null {
  const paused = state.waiting.find((w) => w.session === session);

  if (kind === "approve") {
    return paused ? { session, prompt: waitingWakePrompt(paused), via: "inject" } : null;
  }

  // kind === "wake"
  const readyWaiter = ready.find((w) => w.session === session);
  if (readyWaiter) return { session, prompt: wakePromptFor(readyWaiter, state), via: "fresh" };
  if (paused) return { session, prompt: waitingWakePrompt(paused), via: "inject" };
  return null;
}

// Which coordination alerts to speak, by verbosity (#3804, a11y epic #2725 Tier 1). Pure so the
// policy is unit-tested without the engine. `AlertKind`/verbosity are the same taxonomy the ARIA
// announcer + mobile alerts use, so spoken output stays consistent with the rest of the app.
import type { AlertKind } from "@/features/tunnel";
import type { TtsVerbosity } from "@/shared/lib/a11y/speech";

// The needs-you / went-wrong alerts — the actionable ones, always spoken. `verbose` ADDS the progress
// alerts (`fleet-landed`, `gate-ready`) so a user driving by ear hears the fleet make headway too.
const TERSE_KINDS: readonly AlertKind[] = [
  "agent-paused",
  "prompt-waiting",
  "worker-question",
  "planner-waiting",
  "fleet-failed",
];

/** Whether an alert of `kind` should be spoken at the chosen `verbosity`. */
export function shouldSpeak(kind: AlertKind, verbosity: TtsVerbosity): boolean {
  return verbosity === "verbose" || TERSE_KINDS.includes(kind);
}

// -- Cycle / deadlock detection (#199 AC#5) -------------------------------------
// "Satisfied" is monotonic, so the *only* way a parked waiter never wakes is a wait-for
// CYCLE: A waits on something B produces while B waits on something A produces (or a
// longer ring). No producer in the ring can move, so all of them hang. The runtime must
// DETECT this and escalate rather than spin forever (the planning critic rejects a cyclic
// plan up front; this is the runtime safety net for cycles that slip through).
//
// To build the wait-for graph we need to know which session is expected to satisfy a dep.
// A `session:<id>` dep names that producer directly (id -> that session). Other ref kinds
// (#issue, contract:, file:, predicate:) carry no producer in the log today, so they yield
// NO edge under the default resolver -- zero false positives. Pass a plan-derived resolver
// from {@link buildProducerOf} (fed by the fleet's Produces/Consumes + issue/file ownership)
// and the same algorithm lights up for contract/issue/file cycles too (#199 AC#7). Pure (no
// IO) so it's fully testable.
import { matchGlob } from "@/shared/lib/session/sessionRoles";
import type {
  CoordRef,
  CoordState,
  ProducerOf,
  SessionProduces,
  Deadlock,
} from "@/shared/lib/fleet/coordination.types";
import { isSatisfied } from "@/shared/lib/fleet/coordinationState";

/** The default resolver: only a `session:<id>` dep yields a producer (itself). All other
 *  kinds are unknown until plan-derived Produces/Consumes is supplied (#199 AC#7). */
export function defaultProducerOf(ref: CoordRef): string | undefined {
  return ref.kind === "session" ? ref.id : undefined;
}

/** Parse an issue ref (`#42`, `42`, or `42`) into its number, or undefined if not one. */
function issueNumber(ref: string | number): number | undefined {
  const n = typeof ref === "number" ? ref : Number(String(ref).trim().replace(/^#/, ""));
  return Number.isInteger(n) && n > 0 ? n : undefined;
}

/**
 * Build a {@link ProducerOf} from the plan's Produces/Consumes data (#199 AC#7): each
 * session declares the contracts, issues, and file globs it produces, and the resolver
 * maps a dep ref back to the session expected to satisfy it. This is what lights up
 * contract/issue/file wait-for cycles in {@link detectDeadlocks} — not just `session:`
 * ones (which it still resolves, like {@link defaultProducerOf}).
 *
 * First declaration wins on a collision (a contract/issue should have exactly one
 * producer; the planning critic rejects duplicate `produces`). Predicate deps never
 * resolve to a producer (no session "produces" a predicate). Pure.
 */
export function buildProducerOf(producers: SessionProduces[]): ProducerOf {
  const byContract = new Map<string, string>();
  const byIssue = new Map<number, string>();
  const fileOwners: { glob: string; session: string }[] = [];
  for (const p of producers) {
    for (const name of p.contracts ?? []) {
      if (name && !byContract.has(name)) byContract.set(name, p.session);
    }
    for (const ref of p.issues ?? []) {
      const n = issueNumber(ref);
      if (n !== undefined && !byIssue.has(n)) byIssue.set(n, p.session);
    }
    for (const glob of p.owns ?? []) if (glob) fileOwners.push({ glob, session: p.session });
  }
  return (ref) => {
    switch (ref.kind) {
      case "session": return ref.id;
      case "contract": return byContract.get(ref.name);
      case "issue": return byIssue.get(ref.number);
      case "file": return fileOwners.find((o) => matchGlob(o.glob, ref.path))?.session;
      case "predicate": return undefined;
    }
  };
}

/**
 * Project a `paneId -> launched-stream` map (the store's `fleetPaneStreams`) into the
 * {@link SessionProduces} list {@link buildProducerOf} consumes. The producing `session`
 * is the PANE id — the same id space waiters register under (BSC_AUDIT_PANE) — so the
 * resolved edges land on real parked panes, not on stream slugs. Each stream's `owns`
 * and `issues` (and any future `contracts`) become its produced refs. Structural typing:
 * an `AgentStream` satisfies this shape, so the store passes its fleet map straight in.
 * Pure. See `buildProducerOf(producesFromPaneStreams(map))` for the full resolver.
 */
export function producesFromPaneStreams(
  paneStreams: Record<string, { owns?: string[]; issues?: (string | number)[]; contracts?: string[] }>,
): SessionProduces[] {
  return Object.entries(paneStreams).map(([session, s]) => ({
    session,
    owns: s.owns,
    issues: s.issues,
    contracts: s.contracts,
  }));
}

/**
 * Find every wait-for cycle among the parked waiters. An edge `A -> B` means waiter A has
 * an UNSATISFIED dep that waiter B is expected to produce (a satisfied dep imposes no wait,
 * and an edge to a non-waiter is harmless since that producer can still finish). Cycles are
 * the strongly-connected components of size >= 2, plus any self-loop. Idempotent + pure.
 */
export function detectDeadlocks(s: CoordState, producerOf: ProducerOf = defaultProducerOf): Deadlock[] {
  const waiterIds = new Set(s.waiters.map((w) => w.session));
  const adj = new Map<string, Set<string>>();
  for (const w of s.waiters) {
    const outs = new Set<string>();
    for (const d of w.deps) {
      if (isSatisfied(s, d)) continue;             // satisfied -> no longer blocking
      const p = producerOf(d);
      if (p && waiterIds.has(p)) outs.add(p);      // only an edge to another parked session
    }
    adj.set(w.session, outs);
  }
  return tarjanCycles(adj);
}

/** Whether any parked waiter sits in a wait-for cycle. */
export function hasDeadlock(s: CoordState, producerOf: ProducerOf = defaultProducerOf): boolean {
  return detectDeadlocks(s, producerOf).length > 0;
}

/** Tarjan's SCC -- the cyclic components (size >= 2) plus self-loops, each as a `Deadlock`.
 *  Graphs are tiny (one node per parked pane), so recursive DFS is fine. */
function tarjanCycles(adj: Map<string, Set<string>>): Deadlock[] {
  let index = 0;
  const idx = new Map<string, number>();
  const low = new Map<string, number>();
  const onStack = new Set<string>();
  const stack: string[] = [];
  const cycles: Deadlock[] = [];

  const connect = (v: string): void => {
    idx.set(v, index);
    low.set(v, index);
    index++;
    stack.push(v);
    onStack.add(v);
    for (const nxt of adj.get(v) ?? []) {
      if (!idx.has(nxt)) {
        connect(nxt);
        low.set(v, Math.min(low.get(v)!, low.get(nxt)!));
      } else if (onStack.has(nxt)) {
        low.set(v, Math.min(low.get(v)!, idx.get(nxt)!));
      }
    }
    if (low.get(v) === idx.get(v)) {
      const comp: string[] = [];
      let node: string;
      do {
        node = stack.pop()!;
        onStack.delete(node);
        comp.push(node);
      } while (node !== v);
      // A multi-node SCC is a ring; a lone node is a cycle only if it waits on itself.
      if (comp.length > 1 || adj.get(comp[0])?.has(comp[0])) {
        cycles.push({ cycle: comp.reverse() });
      }
    }
  };

  for (const n of adj.keys()) if (!idx.has(n)) connect(n);
  return cycles;
}

// -- Verification jury (#394) ----------------------------------------------------
// The jury is the watchdog's BRAIN, not a new gate. Under self-merge a worker writes
// the code AND its tests and merges on a green gate -- which proves internal
// consistency, not correctness. The jury reviews POST-merge and async: each juror
// judges the landing from a DIFFERENT anchor than the worker used (acceptance
// criteria / lens / subsystem slice), so their errors are uncorrelated; a reject
// drives the SAME revert+ping reflex the watchdog already runs (#382), with the
// juror's reason as a fix-forward instruction. Pure + testable; the foreman/strategy
// wiring lands on top.
import type {
  CoordEvent,
  JurorVerdict,
  AggregationRule,
  JuryStrictness,
  JuryAggregate,
  JuryAction,
  TriageDecision,
  TriageConfig,
  LandingSignals,
} from "@/shared/lib/fleet/coordination.types";
import { parseRef } from "@/shared/lib/fleet/coordinationState";

export const DEFAULT_TRIAGE_CONFIG: TriageConfig = { maxDiffLines: 150, minCoverageDelta: -1 };

/**
 * Risk-triage a landing: a cheap signal decides whether the full jury convenes or the
 * change takes the fast-path (no panel). Any high-risk signal — a shared/contract file,
 * a security path, a repeat-offender region, a large diff, or a coverage drop — forces a
 * panel; otherwise fast-path. Like risk-based testing: spend the panel where it pays.
 */
export function triageLanding(sig: LandingSignals, cfg: TriageConfig = DEFAULT_TRIAGE_CONFIG): TriageDecision {
  if (sig.touchesSharedOrContract || sig.securitySensitive || sig.revertedBefore) return "panel";
  if ((sig.diffLines ?? 0) >= cfg.maxDiffLines) return "panel";
  if (sig.coverageDelta !== undefined && sig.coverageDelta <= cfg.minCoverageDelta) return "panel";
  return "fast-path";
}

/**
 * Aggregate a panel's verdicts into one outcome, robust to noisy jurors. Under the
 * default `pass-unless-concrete` strictness a reject only counts if it carries a reason,
 * so a juror that rejects on vague doubt can't sink a landing. The `quorum` rule first
 * restricts to jurors whose slice the change touches (`relevant !== false`), so an
 * off-slice juror's noise is ignored entirely.
 */
export function aggregateVerdicts(
  verdicts: JurorVerdict[],
  rule: AggregationRule,
  strictness: JuryStrictness = "pass-unless-concrete",
): JuryAggregate {
  const counts = (v: JurorVerdict) =>
    v.verdict === "reject" && (strictness === "reject-on-doubt" || !!v.reason?.trim());
  const panel = rule === "quorum" ? verdicts.filter((v) => v.relevant !== false) : verdicts;
  const rejects = panel.filter(counts);
  const reject =
    rule === "veto"
      ? rejects.length > 0
      : rejects.length * 2 > panel.length; // strict majority (of the relevant panel for quorum)
  return {
    verdict: reject ? "reject" : "pass",
    rejecters: reject ? rejects.map((v) => v.juror) : [],
    reason: reject ? rejects.find((v) => v.reason?.trim())?.reason : undefined,
  };
}

/** Fold verdict events into per-landing tallies (keyed by the verdict `target`). A juror's
 *  latest verdict on a target replaces an earlier one. Non-verdict events are ignored. */
export function tallyVerdicts(events: CoordEvent[]): Map<string, JurorVerdict[]> {
  const byTarget = new Map<string, Map<string, JurorVerdict>>();
  for (const e of events) {
    if (e.type !== "verdict") continue;
    const jurors = byTarget.get(e.target) ?? new Map<string, JurorVerdict>();
    jurors.set(e.juror, { juror: e.juror, verdict: e.verdict, reason: e.reason, relevant: e.relevant });
    byTarget.set(e.target, jurors);
  }
  const out = new Map<string, JurorVerdict[]>();
  for (const [target, jurors] of byTarget) out.set(target, [...jurors.values()]);
  return out;
}

/** Compose the owner-facing ping for a rejected landing — the fix-forward instruction. */
export function juryPingMessage(target: string, reason: string | undefined): string {
  return `The verification jury rejected ${target}: ${reason?.trim() || "see the jurors' notes"}. It was reverted — fix forward and re-land.`;
}

/**
 * Decide the foreman's action for a landing from its panel: aggregate the verdicts and,
 * on reject, produce a revert targeting the landing ref plus an owner ping carrying the
 * reason. On pass, no action. This is the reject→revert+ping wiring in pure form — the
 * caller feeds `ref` into {@link fail} and delivers `ping` via the existing notification
 * path.
 */
export function planJuryAction(
  target: string,
  verdicts: JurorVerdict[],
  rule: AggregationRule,
  strictness: JuryStrictness = "pass-unless-concrete",
): JuryAction {
  const agg = aggregateVerdicts(verdicts, rule, strictness);
  if (agg.verdict === "pass") return { target, action: "pass", ref: parseRef(target) };
  return {
    target,
    action: "revert",
    ref: parseRef(target),
    reason: agg.reason,
    ping: juryPingMessage(target, agg.reason),
  };
}

// -- Event ingestion (#199 slice 2) ---------------------------------------------
// The `bsc-*` coordination emitters (`src-tauri/data/shell/coord-emit.sh`) each append one TSV line to
// $BSC_COORD_LOG: `bsc-wait` (paused for the user), `bsc-ask`/`bsc-answer`, `bsc-issue`/`bsc-assign`,
// `bsc-brief`, and the completion set `bsc-landed`/`merged`/`closed`/`failed`, which is what satisfies a
// latch. `parseCoordLine` turns one line into a typed event, `applyCoordEvent` folds it into the latch
// state, and `ingestCoordLog` replays a whole log -- so the coordinator is just "read the log ->
// CoordState".
//
// The `blocked` kind has had NO emitter since #1039 removed runtime dependency-wait, and it got no
// replacement: `dependsOn` is a planning-time hint, enforced at LAUNCH by `streamGate.ts`, and a started
// worker never parks on an upstream. Parsing it stays so a log written before then still replays.
import type {
  CoordRef,
  Waiter,
  CoordState,
  AssignedWork,
  AnsweredWake,
  CoordEvent,
  CrossProjectRefusal,
} from "@/shared/lib/fleet/coordination.types";
import { emptyCoordState, parseRef, registerWaiter, satisfy, fail } from "@/shared/lib/fleet/coordinationState";

/**
 * Parse one TSV `$BSC_COORD_LOG` line into an event, or null if unrecognized.
 * Columns: `ts \t session \t kind \t <payload…>`.
 * - blocked: payload = `<comma-refs> \t <checkpoint?>`
 * - landed/merged/closed: payload = `<ref>`
 * - failed: payload = `<ref> \t <reason>`
 */
/**
 * The PROJECT a pane belongs to. Pane identity is `<projectKey>:<stream>` (paneIdentity.ts), so the
 * scope is already on the wire — this only reads it.
 *
 * A pane id with no colon (a bare or malformed id) yields the whole string — see
 * {@link sameCoordProject} for how an unplaceable id is then treated at delivery.
 */
export function coordProjectOf(paneId: string): string {
  const i = paneId.indexOf(":");
  return i < 0 ? paneId : paneId.slice(0, i);
}

/**
 * May `from` direct `target`? Only within one project.
 *
 * `coord.log` is ONE app-wide file and every consumer replays the whole tail, so before this a
 * director in project A could answer a worker in project B — and the instruction arrived through the
 * same trusted channel the worker's real director uses, with nothing in-band to tell them apart. Two
 * workers caught it only because the content named an unfamiliar repo.
 */
export function sameCoordProject(from: string, target: string): boolean {
  const a = coordProjectOf(from);
  const b = coordProjectOf(target);
  // REFUSE ONLY ON PROOF OF CROSSING. A pane id with no `:` cannot be placed in a project — the
  // retired positional ids (`t0p2`, #1176) and any bare id look like this — and refusing what we
  // cannot place would break single-project coordination that never used prefixed ids, which the
  // item explicitly requires to be unchanged. So an unplaceable id is ALLOWED: we only refuse when
  // both sides name a project and the projects differ.
  //
  // The residual is deliberate and worth stating: a bare-id target is reachable from any project.
  // That is strictly no worse than before this change, and prefixed ids are what the app mints now,
  // so the real fleet is covered. Tightening it means retiring bare ids, not tightening this rule.
  if (a === from || b === target) return true;
  return a === b;
}

/**
 * Stable per-EVENT key for a refusal, so a consumer can report each one exactly once
 * (#the-refusal-warning-replays-the-whole-log-every-minute).
 *
 * Every consumer re-derives `refused` from the WHOLE log tail on each read, so the same historical
 * refusals come back on every single read — forever, since nothing prunes them out of the tail. A
 * consumer that reports without a guard therefore repeats itself for as long as the app runs.
 *
 * `at` IS PART OF THE KEY, and that is the whole point of keying per event rather than per pair
 * (which is what {@link CoordNotification}'s `<kind>:<session>` does, correctly, for a STATE). A
 * refusal is not a state that resolves — it is a thing that happened. The same director really can
 * misdirect the same worker again a minute later, and that second attempt is news; a pair-keyed guard
 * would swallow it behind the stale first key and the sender would never be told.
 */
export function refusalKey(r: CrossProjectRefusal): string {
  return `${r.kind}@${r.from}@${r.target}@${r.at}`;
}

export function parseCoordLine(line: string): CoordEvent | null {
  const cols = line.replace(/\r?\n$/, "").split("\t");
  if (cols.length < 4) return null;
  const [ts, session, kind, ...rest] = cols;
  const parsed = Date.parse(ts);
  const at = Number.isFinite(parsed) ? parsed : 0;
  switch (kind) {
    case "blocked": {
      const deps = (rest[0] ?? "").split(",").map(parseRef).filter((r): r is CoordRef => r !== null);
      if (deps.length === 0) return null;
      const checkpoint = rest[1]?.trim() || undefined;
      return { type: "blocked", session, deps, checkpoint, at };
    }
    case "landed":
    case "merged":
    case "closed": {
      const ref = parseRef(rest[0] ?? "");
      return ref ? { type: kind as "landed" | "merged" | "closed", ref, at } : null;
    }
    case "failed": {
      const ref = parseRef(rest[0] ?? "");
      return ref ? { type: "failed", ref, reason: rest[1] ?? "", at } : null;
    }
    case "waiting":
      return { type: "waiting", session, reason: rest[0] ?? "", checkpoint: rest[1]?.trim() || undefined, at };
    case "ask":
      return { type: "ask", session, question: rest[0] ?? "", checkpoint: rest[1]?.trim() || undefined, at };
    // #4106: emitted by the `bsc-fork` PreToolUse hook, so it lands whether or not the spawning
    // session chose to announce itself — the visibility cannot depend on the forker's cooperation.
    case "fork": {
      const description = (rest[0] ?? "").trim();
      return description
        ? { type: "fork", session, description, subagentType: rest[1]?.trim() || undefined, at }
        : null;
    }
    case "answer": {
      const target = (rest[0] ?? "").trim();
      // `session` is the EMITTER — carried as `from` since
      // #coord-log-is-app-wide-answers-cross-projects, because delivery has to compare its project
      // with the target's. `brief` already carried its emitter for the same reason.
      return target ? { type: "answer", from: session, target, answer: rest[1] ?? "", at } : null;
    }
    // #4001: `bsc plan request new|resolve` emit these from the CLI (not a shell helper) because the
    // notification has to carry the id the store just assigned. payload = <id> TAB <text|note>.
    case "request": {
      const id = (rest[0] ?? "").trim();
      return id ? { type: "request", session, id, text: rest[1] ?? "", at } : null;
    }
    case "request-resolved": {
      const id = (rest[0] ?? "").trim();
      return id ? { type: "request-resolved", id, at } : null;
    }
    case "issue": {
      // payload = <title> \t <body?> \t <suggested?> \t <id?>
      const title = (rest[0] ?? "").trim();
      if (!title) return null;
      const id = rest[3]?.trim() || `${session}@${at}`;
      return { type: "issue", session, id, title, body: rest[1]?.trim() || undefined, suggested: rest[2]?.trim() || undefined, at };
    }
    case "assign": {
      // payload = <target> \t <body> \t <issueId?> \t <title?>
      const target = (rest[0] ?? "").trim();
      if (!target) return null;
      return { type: "assign", session, target, body: rest[1] ?? "", issueId: rest[2]?.trim() || undefined, title: rest[3]?.trim() || undefined, at };
    }
    case "maintain":
      return { type: "maintain", session, note: rest[0]?.trim() || undefined, at };
    case "brief": {
      // payload = <target> \t <body> \t <ref?>. The `session` column is the emitter (the
      // planner's pane). `from` mirrors it; `id` (`<from>@<at>`) dedupes a replayed log.
      const target = (rest[0] ?? "").trim();
      if (!target) return null;
      const body = rest[1] ?? "";
      if (!body.trim()) return null;
      const ref = parseRef(rest[2] ?? "") ?? undefined;
      return { type: "brief", from: session, target, body, ref, id: `${session}@${at}`, at };
    }
    case "commission": {
      // payload = <target> \t <body> \t <ref?> (mirrors `brief`, #2940). The `session` column is
      // the requesting studio pane; `id` (`<from>@<at>`) is what a `deliver` references back.
      const target = (rest[0] ?? "").trim();
      if (!target) return null;
      const body = rest[1] ?? "";
      if (!body.trim()) return null;
      const ref = parseRef(rest[2] ?? "") ?? undefined;
      return { type: "commission", from: session, target, body, ref, id: `${session}@${at}`, at };
    }
    case "deliver": {
      // payload = <commissionId> \t <artifactId>. The `session` column is the delivering studio.
      const commissionId = (rest[0] ?? "").trim();
      const artifactId = (rest[1] ?? "").trim();
      if (!commissionId || !artifactId) return null;
      return { type: "deliver", commissionId, artifactId, from: session, at };
    }
    case "verdict": {
      // payload = <target> \t <pass|reject> \t <reason?> \t <relevant?>; the juror is the session column.
      const target = (rest[0] ?? "").trim();
      const v = (rest[1] ?? "").trim().toLowerCase();
      if (!target || (v !== "pass" && v !== "reject")) return null;
      const relevant = rest[3] === undefined ? undefined : rest[3].trim() !== "false" && rest[3].trim() !== "0";
      return { type: "verdict", juror: session, target, verdict: v, reason: rest[2]?.trim() || undefined, relevant, at };
    }
    case "woke":
      return { type: "woke", session, at };
    default:
      return null;
  }
}

/** Fold one event into the latch state, returning what it triggered. */
export function applyCoordEvent(s: CoordState, e: CoordEvent): {
  state: CoordState; woken: Waiter[]; ready: boolean; stalled: Waiter[]; answered: AnsweredWake[]; assigned: AssignedWork[]; refused?: CrossProjectRefusal[];
} {
  switch (e.type) {
    case "blocked": {
      const r = registerWaiter(s, { session: e.session, deps: e.deps, checkpoint: e.checkpoint, registeredAt: e.at });
      // A session that now declares a real dependency leaves the manual-wait list.
      const state = { ...r.state, waiting: r.state.waiting.filter((w) => w.session !== e.session) };
      return { state, woken: [], ready: r.ready, stalled: [], answered: [], assigned: [] };
    }
    case "waiting": {
      const waiting = [
        ...s.waiting.filter((w) => w.session !== e.session),
        { session: e.session, reason: e.reason, checkpoint: e.checkpoint, at: e.at },
      ];
      return { state: { ...s, waiting }, woken: [], ready: false, stalled: [], answered: [], assigned: [] };
    }
    case "landed":
    case "merged":
    case "closed": {
      const r = satisfy(s, e.ref, e.type, e.at);
      return { state: r.state, woken: r.woken, ready: false, stalled: [], answered: [], assigned: [] };
    }
    case "failed": {
      const r = fail(s, e.ref, e.reason, e.at);
      return { state: r.state, woken: [], ready: false, stalled: r.stalled, answered: [], assigned: [] };
    }
    case "woke": {
      // `maintaining` is carried (not cleared): once a worker enters maintenance it STAYS a
      // maintenance worker across dispatches — auto-end permanently skips it (that IS the mode).
      return { state: { latches: s.latches, waiters: s.waiters.filter((w) => w.session !== e.session), waiting: s.waiting.filter((w) => w.session !== e.session), asking: s.asking.filter((a) => a.session !== e.session), issues: s.issues, maintaining: s.maintaining, briefs: s.briefs, forks: s.forks, commissions: s.commissions, requests: s.requests }, woken: [], ready: false, stalled: [], answered: [], assigned: [] };
    }
    case "ask": {
      const asking = [
        ...s.asking.filter((a) => a.session !== e.session),
        { session: e.session, question: e.question, checkpoint: e.checkpoint, at: e.at },
      ];
      // Asking the director supersedes any prior user-wait registration for this session.
      const waiting = s.waiting.filter((w) => w.session !== e.session);
      return { state: { ...s, asking, waiting }, woken: [], ready: false, stalled: [], answered: [], assigned: [] };
    }
    case "answer": {
      // The director is addressing a specific worker — resume it whatever its park (an
      // ask, a dependency block, or a user-wait) and deliver the directive (#376). bsc-answer
      // is the director's universal "unblock + tell this worker" command, not just for asks.
      const ask = s.asking.find((a) => a.session === e.target);
      const waiter = s.waiters.find((w) => w.session === e.target);
      const waitS = s.waiting.find((w) => w.session === e.target);
      const checkpoint = ask?.checkpoint ?? waitS?.checkpoint ?? waiter?.checkpoint;
      // CROSS-PROJECT REFUSAL (#coord-log-is-app-wide-answers-cross-projects). The state is left
      // untouched as well as the delivery: clearing `asking`/`waiting` here would mark the worker as
      // answered by an actor with no authority over it, so its REAL director would then see nothing
      // outstanding and never reply.
      if (!sameCoordProject(e.from, e.target)) {
        return {
          state: s,
          woken: [], ready: false, stalled: [], answered: [], assigned: [],
          refused: [{ kind: "answer", from: e.from, target: e.target, at: e.at }],
        };
      }
      const answered: AnsweredWake[] = [{ session: e.target, answer: e.answer, checkpoint, at: e.at }];
      return {
        state: {
          ...s,
          asking: s.asking.filter((a) => a.session !== e.target),
          waiters: s.waiters.filter((w) => w.session !== e.target),
          waiting: s.waiting.filter((w) => w.session !== e.target),
        },
        woken: [], ready: false, stalled: [], answered, assigned: [],
      };
    }
    case "request": {
      // Dedup by id so a replayed log doesn't double it — the same guard `issue` uses.
      const requests = [
        ...s.requests.filter((r) => r.id !== e.id),
        { id: e.id, from: e.session, text: e.text, at: e.at },
      ];
      return { state: { ...s, requests }, woken: [], ready: false, stalled: [], answered: [], assigned: [] };
    }
    case "request-resolved": {
      // The director answered it. Removing it here is what lets the pump's surfaced-once guard be
      // PRUNED, so a later re-file of the same ask surfaces again rather than being suppressed
      // forever by a stale key.
      return {
        state: { ...s, requests: s.requests.filter((r) => r.id !== e.id) },
        woken: [], ready: false, stalled: [], answered: [], assigned: [],
      };
    }
    case "issue": {
      // The issuer captured new work — append it to the director's pending-issue
      // intake list (dedup by id so a replayed log doesn't double it).
      const issues = [
        ...s.issues.filter((i) => i.id !== e.id),
        { id: e.id, session: e.session, title: e.title, body: e.body, suggested: e.suggested, at: e.at },
      ];
      return { state: { ...s, issues }, woken: [], ready: false, stalled: [], answered: [], assigned: [] };
    }
    case "assign": {
      // The director routed an issue to a worker — resume that worker whatever its
      // park and inject the issue, and clear the matching pending issue from intake.
      const waiter = s.waiters.find((w) => w.session === e.target);
      const waitS = s.waiting.find((w) => w.session === e.target);
      const ask = s.asking.find((a) => a.session === e.target);
      const checkpoint = ask?.checkpoint ?? waitS?.checkpoint ?? waiter?.checkpoint;
      // Same refusal as `answer`, and for the stronger reason: an assign hands a worker WORK. Taking
      // an assignment from another project's director means building something for a plan, repo and
      // lane that actor has no authority over.
      if (!sameCoordProject(e.session, e.target)) {
        return {
          state: s,
          woken: [], ready: false, stalled: [], answered: [], assigned: [],
          refused: [{ kind: "assign", from: e.session, target: e.target, at: e.at }],
        };
      }
      const assigned: AssignedWork[] = [{ session: e.target, title: e.title, body: e.body, checkpoint, at: e.at }];
      return {
        state: {
          ...s,
          asking: s.asking.filter((a) => a.session !== e.target),
          waiters: s.waiters.filter((w) => w.session !== e.target),
          waiting: s.waiting.filter((w) => w.session !== e.target),
          issues: e.issueId ? s.issues.filter((i) => i.id !== e.issueId) : s.issues,
        },
        woken: [], ready: false, stalled: [], answered: [], assigned,
      };
    }
    case "maintain": {
      // A finished worker parks alive in maintenance (#1957). Replace any prior entry for it, and
      // drop it from waiting/asking — it's idle-ready, not waiting on a human. It stays maintaining
      // across dispatches, so `useWorkerAutoEnd` never nudges it to close.
      const maintaining = [
        ...s.maintaining.filter((m) => m.session !== e.session),
        { session: e.session, note: e.note ?? "", at: e.at },
      ];
      return {
        state: { ...s, maintaining, waiting: s.waiting.filter((w) => w.session !== e.session), asking: s.asking.filter((a) => a.session !== e.session) },
        woken: [], ready: false, stalled: [], answered: [], assigned: [],
      };
    }
    case "fork": {
      // Appended + deduped by id, like a brief: a replayed log must not multiply one fork. Never
      // auto-cleared — this records what a session DID, which does not stop being true.
      const forks = [...s.forks.filter((f) => f.id !== `${e.session}@${e.at}`), {
        id: `${e.session}@${e.at}`, session: e.session, description: e.description,
        subagentType: e.subagentType, at: e.at,
      }];
      return { state: { ...s, forks }, woken: [], ready: false, stalled: [], answered: [], assigned: [] };
    }
    case "brief": {
      // The planner pushed a mid-build plan update to the director/issuer (#2377). Append it
      // to the received-briefs list (dedup by id so a replayed log doesn't double it). Unlike
      // an ask/issue there is no consuming event that clears it — it's a standing record; the
      // director's surfacing is guarded once-per-pane by the pump, not by removal here.
      const briefs = [
        ...s.briefs.filter((b) => b.id !== e.id),
        { id: e.id, from: e.from, target: e.target, body: e.body, ref: e.ref, at: e.at },
      ];
      return { state: { ...s, briefs }, woken: [], ready: false, stalled: [], answered: [], assigned: [] };
    }
    case "commission": {
      // A studio session commissioned another for an artifact (#2940). Append to the open list
      // (dedup by id so a replayed log doesn't double it). Like a brief, no consuming event
      // removes it — a `deliver` sets `delivered`; the pump guards its once-per-commission routing.
      const commissions = [
        ...s.commissions.filter((c) => c.id !== e.id),
        { id: e.id, from: e.from, target: e.target, body: e.body, ref: e.ref, at: e.at },
      ];
      return { state: { ...s, commissions }, woken: [], ready: false, stalled: [], answered: [], assigned: [] };
    }
    case "deliver": {
      // The target studio delivered the authored artifact (#2940). Stamp `delivered` on the matching
      // commission so the pump surfaces the id back to the requester. An unmatched deliver (no open
      // commission for the id — e.g. a truncated log) is a no-op rather than an error.
      const commissions = s.commissions.map((c) =>
        c.id === e.commissionId ? { ...c, delivered: e.artifactId } : c,
      );
      return { state: { ...s, commissions }, woken: [], ready: false, stalled: [], answered: [], assigned: [] };
    }
    case "verdict":
      // Verdicts don't move the latch/waiter state — the foreman tallies them off the
      // log (see {@link tallyVerdicts} / {@link planJuryAction}) and emits the revert
      // (a `failed` event) when the panel rejects. So this fold is a no-op.
      return { state: s, woken: [], ready: false, stalled: [], answered: [], assigned: [] };
  }
}

/**
 * Replay a whole `$BSC_COORD_LOG` (oldest-first) into latch state, collecting the waiters
 * still awaiting wake in `ready` (became ready, no `woke` ack yet) -- the coordinator's
 * rebuild-from-disk. Unparseable lines are skipped.
 */
export function ingestCoordLog(lines: string[], initial: CoordState = emptyCoordState()): {
  state: CoordState; woken: Waiter[]; ready: Waiter[]; answered: AnsweredWake[]; assigned: AssignedWork[];
  /** Events refused because they crossed a project boundary
   *  (#coord-log-is-app-wide-answers-cross-projects). Surfaced rather than dropped so the sender can
   *  be told its answer never landed. */
  refused: CrossProjectRefusal[];
} {
  let state = initial;
  const woken: Waiter[] = [];
  // `pending`: waiters that became ready (all deps satisfied) and have NOT yet been
  // acknowledged by a `woke` event -- i.e. the ones still awaiting actuation. The woke
  // event is what makes the wake idempotent across polls + app restarts.
  const pending = new Map<string, Waiter>();
  // `answeredPending`: asking sessions the director has answered (#369) but that have not
  // yet acked with a `woke` — the ones still awaiting an auto-wake with the answer.
  const answeredPending = new Map<string, AnsweredWake>();
  // `assignedPending`: workers the director assigned new work (#376), awaiting injection.
  const assignedPending = new Map<string, AssignedWork>();
  const refused: CrossProjectRefusal[] = [];
  for (const line of lines) {
    const ev = parseCoordLine(line);
    if (!ev) continue;
    if (ev.type === "woke") {
      pending.delete(ev.session);
      answeredPending.delete(ev.session);
      assignedPending.delete(ev.session);
      state = applyCoordEvent(state, ev).state;
      continue;
    }
    const r = applyCoordEvent(state, ev);
    state = r.state;
    for (const w of r.woken) {
      woken.push(w);
      pending.set(w.session, w);
    }
    for (const a of r.answered) answeredPending.set(a.session, a);
    for (const a of r.assigned) assignedPending.set(a.session, a);
    if (r.refused) refused.push(...r.refused);
  }
  return {
    state, woken, ready: [...pending.values()],
    answered: [...answeredPending.values()], assigned: [...assignedPending.values()], refused,
  };
}

// -- Mobile-push notifications (#199 AC#5 / #366) -------------------------------
// The coordinator must reach the human/director on their phone when a chain needs
// attention -- a dep just LANDED (a parked session is wakeable) or a chain is STUCK
// (a failed dep, or a wait-for deadlock no producer will ever clear). Delivery rides
// the existing tunnel `user_request` -> FCM path (a parked pane flipped to
// awaiting_input with this summary as its prompt; see useCoordinator). Kept pure here
// -- "which sessions alert, with what message" -- so the escalation logic is testable
// without the tunnel. One notification per session, most-severe-wins:
// deadlocked > stalled (both are "stuck"); `ready` comes from a disjoint set (the
// newly-woken waiters, which are no longer parked) so it never collides.
import type {
  Waiter,
  CoordState,
  ProducerOf,
  CoordNotificationKind,
  CoordNotification,
} from "@/shared/lib/fleet/coordination.types";
import { refKey, isSatisfied } from "@/shared/lib/fleet/coordinationState";
import { detectDeadlocks, defaultProducerOf } from "@/shared/lib/fleet/coordinationDeadlock";

function notificationSummary(kind: CoordNotificationKind, session: string, refs: string[]): string {
  const list = refs.join(", ");
  switch (kind) {
    case "ready":
      return `${session}: ${refs.length === 1 ? "dependency" : "dependencies"} landed (${list}) -- ready to resume.`;
    case "stalled":
      return `${session}: blocked chain stalled -- a dependency failed (${list}). Needs attention.`;
    case "deadlocked":
      return `${session}: wait-for deadlock (${list}) -- no producer can clear it. Needs the director.`;
  }
}

/**
 * Derive the push notifications for the current coordinator state (#366): the newly-ready
 * waiters (their gating deps just landed -- wakeable) plus every still-parked waiter whose
 * chain is STUCK -- a failed dep (stalled) or a wait-for cycle (deadlocked). One
 * notification per session, deadlocked taking precedence over stalled (the more severe
 * "no producer will ever clear it"). `ready` is the disjoint list of waiters that just
 * became ready (e.g. {@link ingestCoordLog}'s `ready`, or a satisfy/predicate event's
 * `woken`) -- they're already removed from `s.waiters`, so the ready set and the
 * stuck set never overlap. Pure + deterministic (no IO); the tunnel delivery is a thin
 * layer on top in useCoordinator. `producerOf` resolves deadlock edges (see
 * {@link detectDeadlocks}; defaults to the `session:` self-resolver).
 */
export function coordNotifications(
  s: CoordState,
  ready: Waiter[] = [],
  producerOf: ProducerOf = defaultProducerOf,
): CoordNotification[] {
  const out: CoordNotification[] = [];
  for (const w of ready) {
    const refs = w.deps.map(refKey);
    out.push({ kind: "ready", session: w.session, refs, summary: notificationSummary("ready", w.session, refs), key: `ready:${w.session}` });
  }
  const deadlocked = new Set(detectDeadlocks(s, producerOf).flatMap((d) => d.cycle));
  for (const w of s.waiters) {
    if (deadlocked.has(w.session)) {
      const refs = w.deps.filter((d) => !isSatisfied(s, d)).map(refKey);
      out.push({ kind: "deadlocked", session: w.session, refs, summary: notificationSummary("deadlocked", w.session, refs), key: `deadlocked:${w.session}` });
      continue; // deadlocked outranks stalled -- one notification per session
    }
    const failedRefs = w.deps.filter((d) => s.latches[refKey(d)]?.state === "failed").map(refKey);
    if (failedRefs.length > 0) {
      out.push({ kind: "stalled", session: w.session, refs: failedRefs, summary: notificationSummary("stalled", w.session, failedRefs), key: `stalled:${w.session}` });
    }
  }
  return out;
}

// -- Predicate-based readiness (#199 / #365) ------------------------------------
// PR-merged / issue-closed have an authoritative emitter (the director), so they arrive
// as explicit satisfy events. A `predicate:` dep does NOT -- "the symbol exists", "the
// stub is implemented", "tests pass" has no one to emit it, so the coordinator POLLS it:
// the host evaluates the predicate against the repo and, when it holds, the latch is set
// (the third satisfy path). Kept pure -- the actual repo-checking lives in the injected
// `evaluate`, so the readiness logic stays exhaustively unit-testable.
import type {
  CoordRef,
  Waiter,
  CoordState,
  Predicate,
  PredicateEvaluator,
} from "@/shared/lib/fleet/coordination.types";
import { refKey, isSatisfied, satisfy } from "@/shared/lib/fleet/coordinationState";

/** Parse a predicate's inner expr (the part after `predicate:`) into a typed {@link
 *  Predicate}. Never throws -- an unrecognized/headless expr becomes `custom`. Pure. */
export function parsePredicate(expr: string): Predicate {
  const e = expr.trim();
  if (e === "tests-pass" || e === "tests") return { kind: "tests-pass" };
  const colon = e.indexOf(":");
  if (colon > 0) {
    const head = e.slice(0, colon);
    const rest = e.slice(colon + 1).trim();
    if (rest) {
      if (head === "symbol") return { kind: "symbol", name: rest };
      if (head === "file-exists" || head === "file") return { kind: "file-exists", path: rest };
      if (head === "stub") return { kind: "stub", name: rest };
    }
  }
  return { kind: "custom", expr: e };
}

/**
 * Evaluate every UNSATISFIED `predicate:` dep currently gating a parked waiter and satisfy
 * the latches whose predicate now holds -- the polled, third satisfy path alongside
 * merged/closed/landed (a satisfied predicate uses source `landed`: it finished, like any
 * produced ref). Distinct refs are evaluated once each (a predicate shared by N waiters is
 * checked one time). Returns the next state + the waiters now fully ready (all deps
 * satisfied), removed from the table -- feed them to {@link planWakes} exactly like a
 * satisfy event's `woken`. Pure (the repo-checking is in `evaluate`) and idempotent:
 * re-polling an already-satisfied predicate is a no-op. `at` stamps the satisfy time so the
 * auto-wake recency gate ({@link isFreshlyReady}) treats a polled predicate like any latch.
 */
export function evaluatePredicates(
  s: CoordState,
  evaluate: PredicateEvaluator,
  at: number,
): { state: CoordState; woken: Waiter[] } {
  const seen = new Set<string>();
  const toSatisfy: CoordRef[] = [];
  for (const wtr of s.waiters) {
    for (const d of wtr.deps) {
      if (d.kind !== "predicate") continue;
      const key = refKey(d);
      if (seen.has(key)) continue;        // each distinct predicate evaluated once
      seen.add(key);
      if (isSatisfied(s, d)) continue;    // already latched -- skip
      if (evaluate(d.expr) === true) toSatisfy.push(d);
    }
  }
  let state = s;
  const wokenIds = new Set<string>();
  const woken: Waiter[] = [];
  for (const ref of toSatisfy) {
    const r = satisfy(state, ref, "landed", at);
    state = r.state;
    for (const wtr of r.woken) {
      if (!wokenIds.has(wtr.session)) { wokenIds.add(wtr.session); woken.push(wtr); }
    }
  }
  return { state, woken };
}

/**
 * The distinct, still-unsatisfied `predicate:` exprs currently gating a parked waiter -- the
 * exact set the runtime must re-check this poll. This is the contract the host evaluator
 * consumes: the poll loop calls this, hands the list to the host (which checks the repo and
 * returns which now hold), then feeds the result back through {@link evaluatePredicates}.
 * Pure and dedup'd (a predicate shared by N waiters appears once); empty when nothing is
 * predicate-gated, so the runtime can skip the host round-trip entirely. The inner expr is
 * returned (the part after `predicate:`), ready for {@link parsePredicate}.
 */
export function pendingPredicateExprs(s: CoordState): string[] {
  const seen = new Set<string>();
  const exprs: string[] = [];
  for (const wtr of s.waiters) {
    for (const d of wtr.deps) {
      if (d.kind !== "predicate") continue;
      if (isSatisfied(s, d)) continue;
      const key = refKey(d);
      if (seen.has(key)) continue;
      seen.add(key);
      exprs.push(d.expr);
    }
  }
  return exprs;
}

// Inter-session coordination core (#199): the lost-wakeup-safe readiness model.
//
// The key correctness insight: readiness is **state** (a queryable latch), not an
// edge-triggered ping. A producer that finishes *before* the waiter registers must not
// cause a lost wakeup and a permanent hang. So a blocking session both registers as a
// waiter AND immediately checks the latch (proceed now if already satisfied); satisfy
// events set the latch and return the waiters whose **all** deps are now satisfied.
//
// This module is pure (no PTY/store/IO) so it's exhaustively unit-testable. Half its wiring is live:
// the completion emitters (`bsc-landed`/`merged`/`closed`/`failed`) -> satisfy, and the Flow tab wakes a
// ready pane. The other half is not — registration used to come from a `bsc-blocked --on` shell helper,
// and #1039 removed runtime dependency-wait outright rather than replacing it, so nothing declares
// dependence mid-task any more; `streamGate.ts` decides the same question at LAUNCH instead, off the
// plan's `dependsOn`. `failed` is deliberately NOT a satisfy: dependents stay blocked and surface as a
// stalled chain (finished != succeeded).
import type {
  CoordRef,
  SatisfySource,
  Waiter,
  CoordState,
} from "@/shared/lib/fleet/coordination.types";

export function emptyCoordState(): CoordState {
  return { latches: {}, waiters: [], waiting: [], asking: [], issues: [], maintaining: [], briefs: [], forks: [], commissions: [], requests: [] };
}

/** Canonical string key for a ref -- and the wire form too: it is exactly the token the completion
 *  emitters take as their argument (`bsc-landed '#42'`, `bsc-merged contract:X`). */
export function refKey(ref: CoordRef): string {
  switch (ref.kind) {
    case "issue": return `#${ref.number}`;
    case "contract": return `contract:${ref.name}`;
    case "file": return `file:${ref.path}`;
    case "predicate": return `predicate:${ref.expr}`;
    case "session": return `session:${ref.id}`;
  }
}

/** Parse a wire token (`#42`, `contract:X`, `file:path`, `predicate:expr`) back into a ref -- the
 *  argument form of `bsc-landed`/`merged`/`closed`/`failed`, and of the dep columns in a pre-#1039
 *  `blocked` line. Returns null for an unrecognized/empty token. A bare `42` or `#42` is an issue; an
 *  unprefixed non-numeric token is treated as a predicate. */
export function parseRef(token: string): CoordRef | null {
  const t = token.trim();
  if (!t) return null;
  if (t.startsWith("#")) {
    const n = Number(t.slice(1));
    return Number.isInteger(n) && n > 0 ? { kind: "issue", number: n } : null;
  }
  const colon = t.indexOf(":");
  if (colon > 0) {
    const prefix = t.slice(0, colon);
    const rest = t.slice(colon + 1).trim();
    if (!rest) return null;
    if (prefix === "contract") return { kind: "contract", name: rest };
    if (prefix === "file") return { kind: "file", path: rest };
    if (prefix === "predicate") return { kind: "predicate", expr: rest };
    if (prefix === "session") return { kind: "session", id: rest };
    return null;
  }
  if (/^\d+$/.test(t)) return { kind: "issue", number: Number(t) };
  return { kind: "predicate", expr: t };
}

/** Whether `ref` is satisfied (truly done -- not merely failed). */
export function isSatisfied(s: CoordState, ref: CoordRef): boolean {
  return s.latches[refKey(ref)]?.state === "satisfied";
}

/** Whether all of a waiter's deps are satisfied. */
export function isReady(s: CoordState, w: Waiter): boolean {
  return w.deps.every((d) => isSatisfied(s, d));
}

/** Waiters currently blocked on a ref that has *failed* -- a stalled chain to escalate. */
export function stalledWaiters(s: CoordState, ref: CoordRef): Waiter[] {
  const key = refKey(ref);
  if (s.latches[key]?.state !== "failed") return [];
  return s.waiters.filter((w) => w.deps.some((d) => refKey(d) === key));
}

/**
 * Register a blocking session. Returns the next state and `ready`: whether all its deps
 * are ALREADY satisfied (the register-then-check that defeats lost wakeups -- the caller
 * should proceed immediately when `ready`). When already ready, the waiter is not added
 * (nothing to wait for); otherwise it's added/replaced by `session` id (idempotent).
 */
export function registerWaiter(s: CoordState, w: Waiter): { state: CoordState; ready: boolean } {
  const ready = isReady(s, w);
  const others = s.waiters.filter((x) => x.session !== w.session);
  const state: CoordState = {
    latches: s.latches,
    waiters: ready ? others : [...others, w],
    waiting: s.waiting,
    asking: s.asking,
    issues: s.issues,
    maintaining: s.maintaining,
    briefs: s.briefs,
    forks: s.forks,
    requests: s.requests,
    commissions: s.commissions,
  };
  return { state, ready };
}

/**
 * Mark a ref satisfied (a `landed`/`merged`/`closed` event). Sets the latch and returns
 * the waiters that are now fully ready (all deps satisfied), removing them from the
 * table. Idempotent: re-delivering the same satisfy is harmless (readiness is state).
 */
export function satisfy(
  s: CoordState,
  ref: CoordRef,
  source: SatisfySource,
  at: number,
): { state: CoordState; woken: Waiter[] } {
  const latches = { ...s.latches, [refKey(ref)]: { state: "satisfied" as const, source, at } };
  const probe: CoordState = { latches, waiters: s.waiters, waiting: s.waiting, asking: s.asking, issues: s.issues, maintaining: s.maintaining, briefs: s.briefs, forks: s.forks, commissions: s.commissions, requests: s.requests };
  const woken = s.waiters.filter((w) => isReady(probe, w));
  const wokenIds = new Set(woken.map((w) => w.session));
  return { state: { latches, waiters: s.waiters.filter((w) => !wokenIds.has(w.session)), waiting: s.waiting, asking: s.asking, issues: s.issues, maintaining: s.maintaining, briefs: s.briefs, forks: s.forks, commissions: s.commissions, requests: s.requests }, woken };
}

/**
 * Mark a ref failed (a `failed` event). Does NOT satisfy the latch -- dependents stay
 * blocked. Returns the waiters now stalled on this failed ref so the caller can raise a
 * blocked-chain alert. Idempotent.
 */
export function fail(
  s: CoordState,
  ref: CoordRef,
  reason: string,
  at: number,
): { state: CoordState; stalled: Waiter[] } {
  const latches = { ...s.latches, [refKey(ref)]: { state: "failed" as const, reason, at } };
  const next: CoordState = { latches, waiters: s.waiters, waiting: s.waiting, asking: s.asking, issues: s.issues, maintaining: s.maintaining, briefs: s.briefs, forks: s.forks, commissions: s.commissions, requests: s.requests };
  return { state: next, stalled: stalledWaiters(next, ref) };
}

// -- Wake planning + inbox view (#199 slice 3) ----------------------------------
// Pure "decide + present": given the ingested latch state, what to wake (with what
// prompt) and what the inbox/health view shows. The store/PTY execution (relaunch the
// pane, render the panel) is a thin layer on top of these in a later slice.
import type {
  CoordRef,
  Waiter,
  CoordState,
  AssignedWork,
  AnsweredWake,
  WaitingSession,
  WakeAction,
  BlockedView,
  ProducerOf,
} from "@/shared/lib/fleet/coordination.types";
import { refKey } from "@/shared/lib/fleet/coordinationState";
import { detectDeadlocks, defaultProducerOf } from "@/shared/lib/fleet/coordinationDeadlock";

/** A ref's latch status as a short label (for prompts + the inbox view). */
function statusOf(s: CoordState, ref: CoordRef): "satisfied" | "failed" | "pending" {
  const l = s.latches[refKey(ref)];
  return l?.state === "satisfied" ? "satisfied" : l?.state === "failed" ? "failed" : "pending";
}

/**
 * Compose the token-aware wake prompt for a woken waiter -- names the landed deps (with
 * how they were satisfied) and points at the checkpoint, so the FRESH session resumes
 * without re-deriving context (never `--continue` on a fat transcript; see #199).
 */
export function wakePromptFor(w: Waiter, s: CoordState): string {
  const landed = w.deps
    .map((d) => {
      const l = s.latches[refKey(d)];
      const via = l?.state === "satisfied" ? l.source : "ready";
      return `${refKey(d)} (${via})`;
    })
    .join(", ");
  const lines = [
    `Your blocking ${w.deps.length === 1 ? "dependency has" : "dependencies have"} landed -- resume now.`,
    `Satisfied: ${landed}.`,
  ];
  if (w.checkpoint) {
    lines.push(`Resume from your checkpoint: ${w.checkpoint} -- read it first, then continue from where you left off.`);
  }
  return lines.join("\n");
}

/**
 * Compose the wake prompt for a session that paused for the USER (#297 checkpoint/
 * confirm flow) — names the reason it paused and points at the checkpoint so the
 * fresh session resumes in context. Unlike {@link wakePromptFor}, there are no deps
 * to report; the user has decided to resume it.
 */
export function waitingWakePrompt(w: WaitingSession): string {
  const lines = [
    w.reason.trim()
      ? `You paused for confirmation: ${w.reason.trim()} — the user has resumed you; proceed.`
      : "You paused for the user — you have been resumed; proceed.",
  ];
  if (w.checkpoint) {
    lines.push(`Resume from your checkpoint: ${w.checkpoint} — read it first, then continue from where you left off.`);
  }
  return lines.join("\n");
}

/**
 * Compose the wake prompt for a session the DIRECTOR answered (#369). Carries the
 * director's answer and points at the checkpoint, so the fresh session resumes on that
 * basis without re-asking. This is what makes "defer to the director" a real round-trip.
 */
export function answerWakePrompt(a: AnsweredWake): string {
  const lines = [
    `The director responded: ${a.answer.trim() || "(see the director's notes)"} — proceed on that basis; you are no longer parked. Do not ask the user.`,
  ];
  if (a.checkpoint) {
    lines.push(`Resume from your checkpoint: ${a.checkpoint} — read it first, then continue.`);
  }
  return lines.join("\n");
}

/**
 * Compose the injection prompt for a worker the director assigned new work (#376).
 * States it is new work routed by the director, carries the title + body, and points
 * at the checkpoint so a resumed worker re-grounds before starting. The worker then
 * flows into its normal implement → integrate loop.
 */
export function assignWakePrompt(a: AssignedWork): string {
  const lines = [
    `The director assigned you new work${a.title ? `: ${a.title}` : ""}. Start on it now and carry it through your normal loop (implement → gate → integrate). Do not ask the user.`,
  ];
  if (a.body.trim()) lines.push("", a.body.trim());
  if (a.checkpoint) {
    lines.push("", `First re-read your checkpoint: ${a.checkpoint}, then begin the new work.`);
  }
  return lines.join("\n");
}

/** Map newly-woken waiters to wake actions (the prompt-injection payloads slice 4 runs). */
export function planWakes(woken: Waiter[], s: CoordState): WakeAction[] {
  return woken.map((w) => ({ session: w.session, deps: w.deps, prompt: wakePromptFor(w, s) }));
}

/** Derive the inbox/health view from latch state: every still-parked waiter, each dep's
 *  status, whether the chain is stalled (a failed dep), and whether it sits in a wait-for
 *  cycle (a deadlock). `producerOf` resolves which session satisfies a dep (defaults to
 *  the `session:` self-resolver -- see {@link detectDeadlocks}). */
export function coordinationSummary(s: CoordState, producerOf: ProducerOf = defaultProducerOf): BlockedView[] {
  const deadlocked = new Set(detectDeadlocks(s, producerOf).flatMap((d) => d.cycle));
  return s.waiters.map((w) => {
    const deps = w.deps.map((d) => ({ ref: refKey(d), status: statusOf(s, d) }));
    return {
      session: w.session,
      checkpoint: w.checkpoint,
      deps,
      stalled: deps.some((d) => d.status === "failed"),
      deadlocked: deadlocked.has(w.session),
    };
  });
}

// -- Auto-wake recency gate (#199) ----------------------------------------------
// The always-on coordinator only auto-relaunches a ready session if its deps landed
// RECENTLY, so an app restart (which replays the whole log) can't relaunch sessions whose
// dependencies were satisfied long ago and were never woken. The manual Wake button has
// no such limit. Kept pure (takes `now`) so it's testable.

/** Newest moment among a waiter's deps at which one became satisfied (ms epoch), or 0. */
export function readinessAt(w: Waiter, s: CoordState): number {
  let newest = 0;
  for (const d of w.deps) {
    const l = s.latches[refKey(d)];
    if (l?.state === "satisfied" && l.at > newest) newest = l.at;
  }
  return newest;
}

/** Whether `w` became ready within `windowMs` of `now`. */
export function isFreshlyReady(w: Waiter, s: CoordState, now: number, windowMs: number): boolean {
  const at = readinessAt(w, s);
  return at > 0 && now - at < windowMs;
}

// Inter-session coordination core (#199) — the public barrel.
//
// The coord-log event model was decomposed into colocated concern-modules (#2148) while
// this file stays the single public import surface: `@/shared/lib/fleet/coordination` keeps
// re-exporting every symbol, so no importer changes. The behavior is byte-for-byte the
// pre-split code, moved verbatim. The concern-modules:
//   - coordinationState         — the lost-wakeup-safe latch/waiter model (refKey/parseRef/
//                                 isSatisfied/isReady/stalledWaiters/registerWaiter/satisfy/fail)
//   - coordinationLog           — event ingestion (parseCoordLine/applyCoordEvent/ingestCoordLog)
//   - coordinationWakes         — wake prompts + inbox view + auto-wake recency gate
//   - coordinationPredicates    — the polled `predicate:` third satisfy path
//   - coordinationNotifications — mobile-push escalation
//   - coordinationDeadlock      — producer resolvers + Tarjan wait-for cycle detection
//   - coordinationJury          — the verification jury (#394) triage/aggregate/plan
//
// Types were already split out into ./coordination.types.ts (#1633).

// Re-export the coordination types (split into ./coordination.types.ts, #1633) so the
// public import surface `@/shared/lib/fleet/coordination` is unchanged for every importer.
export type * from "@/shared/lib/fleet/coordination.types";

export * from "@/shared/lib/fleet/coordinationState";
export * from "@/shared/lib/fleet/coordinationLog";
export * from "@/shared/lib/fleet/coordinationWakes";
export * from "@/shared/lib/fleet/coordinationPredicates";
export * from "@/shared/lib/fleet/coordinationNotifications";
export * from "@/shared/lib/fleet/coordinationDeadlock";
export * from "@/shared/lib/fleet/coordinationJury";

// Inter-session coordination types (#199 / #1633): the type/interface declarations for the
// lost-wakeup-safe readiness model. Split out of `coordination.ts` so the data shapes live
// apart from the pure runtime logic. `coordination.ts` re-exports everything here, so the
// public import surface (`@/shared/lib/fleet/coordination`) is unchanged.

/** A structured dependency target -- what a session is blocked *on*, or what landed. */
export type CoordRef =
  | { kind: "issue"; number: number }   // #42
  | { kind: "contract"; name: string }  // contract:TunnelState
  | { kind: "file"; path: string }      // file:src/lib/x.ts
  | { kind: "predicate"; expr: string } // predicate:tests-pass
  | { kind: "session"; id: string };    // session:t0p2 -- "blocked until pane X finishes"

/** The authoritative signal that satisfied a latch (most->least authoritative). */
export type SatisfySource = "merged" | "closed" | "landed";

/** Per-ref latch status. `satisfied` wakes dependents; `failed` holds them (a stalled
 *  chain the director is alerted to) -- the two are distinct on purpose. */
export type LatchStatus =
  | { state: "satisfied"; source: SatisfySource; at: number }
  | { state: "failed"; reason: string; at: number };

/** A parked session waiting on every ref in `deps`. `checkpoint` is the compact resume
 *  seed (a `bsc-checkpoint` ref) carried into the wake prompt. */
export interface Waiter {
  /** The parked session/pane id. Unique key -- re-registering replaces the entry. */
  session: string;
  /** All of these must be satisfied for the waiter to wake. */
  deps: CoordRef[];
  /** Resume seed (e.g. a checkpoint doc relpath); carried into the wake prompt. */
  checkpoint?: string;
  /** When the block was declared (ms epoch), passed in by the caller. */
  registeredAt: number;
}

/** The coordinator's persistable state: the latch table + the waiter table. */
/** A coordination event REFUSED at delivery because its target belongs to a different project
 *  (#coord-log-is-app-wide-answers-cross-projects). Kept rather than dropped: a silently swallowed
 *  answer looks to the director exactly like one that was delivered, so it would go on believing it
 *  had unblocked a worker it never reached. */
export interface CrossProjectRefusal {
  kind: "answer" | "assign";
  /** The emitting pane, and therefore the project with authority over this event. */
  from: string;
  /** The pane it tried to reach — in a DIFFERENT project. */
  target: string;
  at: number;
}

export interface CoordState {
  latches: Record<string, LatchStatus>;
  waiters: Waiter[];
  /** Sessions paused for the user (#297 checkpoint/confirm flow) — woken manually. */
  waiting: WaitingSession[];
  /** Sessions that asked the DIRECTOR a question (#369) — woken when it answers. */
  asking: AskingSession[];
  /** New work the ISSUER captured (#376), pending the director's routing decision. */
  issues: PendingIssue[];
  /** Workers in MAINTENANCE (#1957): they finished every owned issue and parked alive + ready
   *  instead of ending — the director routes new/regressed lane work to them via `bsc-assign`.
   *  Cleared when the worker is dispatched (assign/answer) or resumes (woke). */
  maintaining: MaintainingSession[];
  /** Mid-build plan updates the PLANNER pushed to a running director/issuer (#2377) — the
   *  planner's runtime voice into the fleet, beyond the one-shot kickoff/plan.db handoff.
   *  Appended (never auto-cleared); the director reconciles the plan and routes any carried
   *  `ref` onward via `bsc-assign`. */
  briefs: ReceivedBrief[];
  /** Subagents a session has spawned (#4106). A fork has no pane, no roster row, no worktree and no
   *  branch, so without this it is the one actor in the fleet nobody can see. Appended, never
   *  auto-cleared — a fork is a fact about what a session DID, not a state that resolves. */
  forks: SpawnedFork[];
  /** Open commissions in the studio network (#2940): a studio session (planner/designer) asked
   *  another (designer/librarian) to author an artifact. The pump routes each to the target studio
   *  session; a matching `deliver` sets `delivered` (the authored artifact's id) so the pump can
   *  surface the result back to the requester. Appended + dedup by id; never auto-removed (the
   *  surfacing is guarded once-per-commission by the pump, like {@link ReceivedBrief}). */
  commissions: OpenCommission[];
  /** OPEN project change-requests (#4000/#4001): a worker asked the DIRECTOR for something outside
   *  its own worktree — an integration branch that does not exist, a kickoff path that is wrong. The
   *  pump surfaces each to the director once; a matching `request-resolved` removes it, so unlike
   *  {@link ReceivedBrief} this list genuinely empties. The durable record lives in the project's
   *  plan.db (`bsc plan request`); this is only the delivery signal. */
  requests: OpenRequest[];
}

/** A worker→director change request awaiting an answer (#4001). The `cmd` grounding is what makes it
 *  actionable without a conversation: the exact command that failed. */
export interface OpenRequest {
  /** The plan.db row id — how the director resolves it (`bsc plan request resolve <id>`). */
  id: string;
  /** The requesting SESSION — the emitting pane id, from the coord line's session column. NOT the
   *  plan.db row's `from`, which records the STREAM (`$BSC_STREAM`). Both identify the same worker;
   *  the pane id is the more useful one here because it is what the director would `bsc-answer`. */
  from: string;
  /** What is being asked for. */
  text: string;
  /** When it was filed (epoch ms), for the surfaced-once key. */
  at: number;
}

/** A subagent a session spawned (#4106).
 *
 *  Recorded because a director forking to complete a worker's job is invisible otherwise — that is how
 *  it went unnoticed until someone happened to be watching. Legitimate forks (a coordinator reviewing
 *  several PRs in parallel, the designer's harvest fan-out) are recorded identically: the point is that
 *  a fork is never silent, not that a fork is wrong. */
export interface SpawnedFork {
  /** Stable key (`<session>@<at>`) — dedupes a replayed log. */
  id: string;
  /** The pane that forked. */
  session: string;
  /** The task the fork was given, as the spawning session described it. */
  description: string;
  /** The requested agent type, when one was named (e.g. `general-purpose`). */
  subagentType?: string;
  at: number;
}

/** A structured plan update the planner streamed to a running director/issuer (#2377). The
 *  planner is plan-only, so a brief is a COORDINATION write (append to `coord.log`), never a
 *  code/git write — the first runtime consumer of the planner→{director,issuer} org edge.
 *  Modelled like {@link PendingIssue}/{@link AssignedWork}. */
export interface ReceivedBrief {
  /** Stable key (`<from>@<at>`) — dedupes a replayed log + keys the surfaced-once guard. */
  id: string;
  /** The originating session (the planner's pane id / "planner"). */
  from: string;
  /** The intended audience — `"director"`, `"issuer"`, or a specific session id. */
  target: string;
  /** The brief prose (a plan change, added scope, a re-sequencing directive). */
  body: string;
  /** Optional structured ref the director can act on onward (a new/updated `#issue`,
   *  a `contract:`, a `file:`) — e.g. route it to the owning worker via `bsc-assign`. */
  ref?: CoordRef;
  /** When pushed (ms epoch). */
  at: number;
}

/** A commission in the studio-session network (#2940): a studio session asked another to author an
 *  artifact into its own store (designer → a `bsc ui` component; librarian → a `bsc graph` impl).
 *  Modelled like {@link ReceivedBrief}; a `deliver` correlates back by {@link id} and sets
 *  {@link delivered}. */
export interface OpenCommission {
  /** Stable key (`<from>@<at>`) — the id a `deliver` references to resolve + route the result back. */
  id: string;
  /** The requesting studio session (the emitter's pane id, e.g. the planner or designer pane). */
  from: string;
  /** The target studio — `"designer"` | `"librarian"` (or a specific session id). */
  target: string;
  /** What to author (the spec / need). */
  body: string;
  /** Optional structured ref the requester carried (a `#issue`, a `file:`, a `contract:`). */
  ref?: CoordRef;
  /** When commissioned (ms epoch). */
  at: number;
  /** Set once a matching `deliver` arrives: the authored artifact's id (component id / impl id). */
  delivered?: string;
}

/** A shaped issue the issuer captured, awaiting the director's `bsc-assign` (#376). The
 *  issuer does intake only; the director picks the owning worker by `owns`/stream. */
export interface PendingIssue {
  /** Stable key — the wire id, else `<session>@<at>`. Dedupes + lets `assign` clear it. */
  id: string;
  /** The issuer session that captured it. */
  session: string;
  /** Well-formed issue title. */
  title: string;
  /** Issue body (acceptance criteria, etc.); may be empty. */
  body?: string;
  /** The issuer's suggested repo or stream, from the plan (the director may override). */
  suggested?: string;
  /** When captured (ms epoch). */
  at: number;
}

/** A pending injection produced when the director assigns an issue to a worker (#376).
 *  Carries the issue into the target worker's fresh session, like {@link AnsweredWake}. */
export interface AssignedWork {
  /** The target worker session/pane id. */
  session: string;
  /** The issue title (when known). */
  title?: string;
  /** The issue body / instructions to start on. */
  body: string;
  /** Resume seed, if the target was parked with one. */
  checkpoint?: string;
  /** When assigned (ms epoch). */
  at: number;
}

/** A session paused for the USER, not blocked on a dependency latch (#297). It carries
 *  no deps, never participates in auto-wake, and is resumed only from the inbox. */
export interface WaitingSession {
  /** The parked session/pane id. Unique key — a newer wait replaces the entry. */
  session: string;
  /** Why it paused (the `bsc-wait` note); may be empty. */
  reason: string;
  /** Resume seed (e.g. a checkpoint doc relpath); carried into the wake prompt. */
  checkpoint?: string;
  /** When the pause was declared (ms epoch), passed in by the caller. */
  at: number;
}

/** A worker in MAINTENANCE (#1957): it finished every owned issue and, instead of ending, parked
 *  alive in a ready posture. Unlike a user-wait it needs no human action — it idles cheaply until
 *  the director dispatches new lane work (`bsc-assign`) or a regression wakes it. */
export interface MaintainingSession {
  session: string;
  /** The standing note (the `bsc-maintain` message), e.g. "owned issues complete — standing by". */
  note: string;
  at: number;
}

/** A session parked on a `bsc-ask` question to the director (#369). Unlike a user-wait,
 *  it is resumed automatically when the director answers via `bsc-answer <session>`. */
export interface AskingSession {
  session: string;
  question: string;
  checkpoint?: string;
  at: number;
}

/** A pending wake produced when the director answers an asking session (#369). */
export interface AnsweredWake {
  session: string;
  answer: string;
  checkpoint?: string;
  at: number;
}

/** A structured coordination event (one per `$BSC_COORD_LOG` line). */
export type CoordEvent =
  | { type: "blocked"; session: string; deps: CoordRef[]; checkpoint?: string; at: number }
  | { type: "landed"; ref: CoordRef; at: number }
  | { type: "merged"; ref: CoordRef; at: number }
  | { type: "closed"; ref: CoordRef; at: number }
  | { type: "failed"; ref: CoordRef; reason: string; at: number }
  | { type: "woke"; session: string; at: number }
  | { type: "waiting"; session: string; reason: string; checkpoint?: string; at: number }
  | { type: "ask"; session: string; question: string; checkpoint?: string; at: number }
  // `from` is the EMITTER's pane (the `session` column). It was parsed and thrown away until
  // #coord-log-is-app-wide-answers-cross-projects: without it there is nothing to compare the target
  // against, so an answer from another project's director was indistinguishable from this project's.
  | { type: "answer"; from: string; target: string; answer: string; at: number }
  // Issuer flow (#376): the issuer captures new work; the director routes it to a worker.
  | { type: "issue"; session: string; id: string; title: string; body?: string; suggested?: string; at: number }
  | { type: "assign"; session: string; target: string; body: string; issueId?: string; title?: string; at: number }
  // Maintenance mode (#1957): a finished worker parks alive + ready instead of ending.
  | { type: "maintain"; session: string; note?: string; at: number }
  // Fork (#4106): a session spawned a subagent. Emitted by a PreToolUse hook, so it is recorded
  // whether or not the spawning session announces it.
  | { type: "fork"; session: string; description: string; subagentType?: string; at: number }
  // Planner brief (#2377): the planner streams a mid-build plan update to a director/issuer.
  // #4001 — the worker→director request lane. Both ends are events because the pump derives its
  // pending set from the LOG: `request` opens one, `request-resolved` closes it.
  | { type: "request"; session: string; id: string; text: string; at: number }
  | { type: "request-resolved"; id: string; at: number }
  | { type: "brief"; from: string; target: string; body: string; ref?: CoordRef; id: string; at: number }
  // Studio network (#2940): a studio session commissions another to author an artifact; the target
  // delivers its id back. `commission` mirrors `brief`; `deliver` correlates by the commission id.
  | { type: "commission"; from: string; target: string; body: string; ref?: CoordRef; id: string; at: number }
  | { type: "deliver"; commissionId: string; artifactId: string; from: string; at: number }
  // Verification jury (#394): a juror reports a structured verdict on a landing; the
  // foreman tallies them and, on reject, drives the existing revert+ping reflex.
  | { type: "verdict"; juror: string; target: string; verdict: JuryVerdict; reason?: string; relevant?: boolean; at: number };

export interface WakeAction {
  /** The parked session/pane to relaunch. */
  session: string;
  /** The token-aware wake prompt seeded into the fresh session. */
  prompt: string;
  /** The deps that gated this waiter (now all satisfied). */
  deps: CoordRef[];
}

/** One blocked session as the inbox / blocked-chain health view would show it. */
export interface BlockedView {
  session: string;
  checkpoint?: string;
  deps: { ref: string; status: "satisfied" | "failed" | "pending" }[];
  /** True when any dep has failed -- a stalled chain to escalate. */
  stalled: boolean;
  /** True when this session is part of a wait-for cycle -- a deadlock to escalate
   *  (no producer will ever satisfy it, so it would otherwise hang forever). */
  deadlocked: boolean;
}

/** A parsed `predicate:` expression -- the readiness checks the host evaluates against
 *  the repo. The inner expr (after the `predicate:` prefix) carries an optional kind
 *  prefix: `tests-pass`, `symbol:<Name>`, `file-exists:<path>`, `stub:<name>`; anything
 *  else is a `custom` expr the host interprets. Lets the evaluator dispatch on kind. */
export type Predicate =
  | { kind: "tests-pass" }
  | { kind: "symbol"; name: string }       // symbol:TunnelState -- a symbol exists in the tree
  | { kind: "file-exists"; path: string }  // file-exists:src/lib/x.ts
  | { kind: "stub"; name: string }         // stub:handleFoo -- a stub/impl landed
  | { kind: "custom"; expr: string };      // anything else -- host-defined

/** Evaluates whether a predicate expression currently holds against the repo. Injected by
 *  the runtime (the host runs the actual check); pure here so it's testable. Returns
 *  `true` (holds -> satisfy), `false` (does not hold), or `undefined` (not yet evaluable
 *  -- left pending, retried on the next poll). The arg is the predicate's inner expr (the
 *  part after `predicate:`) -- feed it through {@link parsePredicate} to dispatch on kind. */
export type PredicateEvaluator = (expr: string) => boolean | undefined;

export type CoordNotificationKind = "ready" | "stalled" | "deadlocked";

/** A push-worthy coordination event for one session: what happened and a mobile-facing
 *  one-liner. `refs` are the involved dep keys (for the inbox / notification body). */
export interface CoordNotification {
  kind: CoordNotificationKind;
  /** The parked/woken session (pane id) the notification is about. */
  session: string;
  /** A short human/mobile-facing summary -- used as the `user_request` prompt. */
  summary: string;
  /** The dep keys involved (landed deps for `ready`; the stuck deps otherwise). */
  refs: string[];
  /** A stable de-dupe key (`<kind>:<session>`) so a poll loop fires each alert once. */
  key: string;
}

/** Resolves which session is expected to satisfy a dep ref, or undefined if unknown. */
export type ProducerOf = (ref: CoordRef) => string | undefined;

/** One session's declared outputs -- the plan-derived data a {@link ProducerOf} is built
 *  from. The fields mirror what the planner already carries: `contracts` are
 *  `FeatureContract.produces[].name`, `issues` are `AgentStream.issues`, and `owns` are
 *  `AgentStream.owns` (file globs). `session` is the producing session id -- the SAME id
 *  space as a waiter's `session` and a `session:<id>` ref (the launched pane id), so the
 *  resolved edges land on real parked waiters. */
export interface SessionProduces {
  /** Producing session id (pane id) -- must match the waiter ids edges connect to. */
  session: string;
  /** Contract names it produces (resolves `contract:<name>` deps). */
  contracts?: string[];
  /** Issue refs it owns -- `#42`, `42`, or a number (resolves `#issue` deps). */
  issues?: (string | number)[];
  /** File globs it owns -- `src/lib/**` (resolves `file:<path>` deps via glob match). */
  owns?: string[];
}

/** A detected wait-for cycle: the parked sessions that mutually block, in ring order.
 *  A single-element cycle is a session waiting (transitively) on its own output. */
export interface Deadlock {
  cycle: string[];
}

/** Cheap, risk-triage signals about a landing — decide fast-path vs convene a panel. */
export interface LandingSignals {
  /** The change touched a shared / contract file (high blast radius). */
  touchesSharedOrContract?: boolean;
  /** The change touched a security-sensitive path. */
  securitySensitive?: boolean;
  /** A region that was reverted before (repeat-offender). */
  revertedBefore?: boolean;
  /** Lines changed in the diff. */
  diffLines?: number;
  /** Coverage delta (negative = a drop). */
  coverageDelta?: number;
}

export type TriageDecision = "fast-path" | "panel";

/** Risk-triage thresholds (overridable). */
export interface TriageConfig {
  /** Diffs at/above this many lines convene a panel. */
  maxDiffLines: number;
  /** Coverage drops at/below this delta convene a panel. */
  minCoverageDelta: number;
}

export type JuryVerdict = "pass" | "reject";

/** One juror's structured verdict on a landing. `relevant` (default true) marks whether
 *  the change touches this juror's slice — used by the quorum rule. */
export interface JurorVerdict {
  juror: string;
  verdict: JuryVerdict;
  reason?: string;
  location?: string;
  relevant?: boolean;
}

/** How the foreman tallies the panel. veto: any reject fails. majority: >half reject.
 *  quorum: only jurors whose slice the change touches vote, majority of those. */
export type AggregationRule = "veto" | "majority" | "quorum";

/** Strictness when a juror is uncertain. pass-unless-concrete (default for a merge gate):
 *  only a reject WITH a concrete reason counts — keeps the fleet flowing. reject-on-doubt:
 *  every reject counts (safety over speed; for bug-hunts). */
export type JuryStrictness = "pass-unless-concrete" | "reject-on-doubt";

export interface JuryAggregate {
  verdict: JuryVerdict;
  /** The jurors whose rejection counted toward the outcome. */
  rejecters: string[];
  /** The first counted rejecter's reason — the fix-forward instruction. */
  reason?: string;
}

/** What the foreman does with a tallied landing: pass, or revert + ping the owner. The
 *  `ref` is the landing parsed as a coord ref (an issue #, a `session:` id, …), ready to
 *  feed into {@link fail} — the SAME revert reflex the watchdog runs (#382). */
export interface JuryAction {
  target: string;
  action: "pass" | "revert";
  ref: CoordRef | null;
  /** The fix-forward reason (a counted rejecter's reason), present on a revert. */
  reason?: string;
  /** The owner-facing ping message, present on a revert. */
  ping?: string;
}

// Shared wake actuation (#199): kill the parked pane, relaunch it fresh via the store's
// wakePane, then record the `woke` event so it isn't offered again. Used by both the
// inbox "Wake" button and the always-on auto-wake coordinator.
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { injectRedirect } from "@/shared/lib/fleet/paneInject";

export async function actuateWake(
  session: string,
  prompt: string,
  wakePane: (paneId: string, prompt: string) => boolean,
): Promise<boolean> {
  // Kill first so the runId-bump remount spawns a FRESH session (not a reconnect).
  await safeInvoke("pty_kill", { paneId: session }, undefined);
  const ok = wakePane(session, prompt);
  if (ok) await safeInvoke("append_coord_woke", { session }, undefined);
  return ok;
}

/**
 * Deliver a wake to a LIVE (parked) session by injecting the prompt straight into its pane
 * (#374) — instant, keeps the session's own context, and consistent with how the director
 * pump + CI watcher deliver. Records the `woke` event so it isn't re-fired. This is the
 * automatic path; the manual inbox button still uses actuateWake (a fresh relaunch).
 */
export async function injectWake(session: string, prompt: string): Promise<boolean> {
  // `injectRedirect`, not `injectPrompt` (#4253): a PARKED session is frequently parked ON a permission
  // dialog, and a plain paste lands in that dialog rather than the composer — so the wake was recorded
  // as delivered while the session never moved. Clearing first is the whole point of a wake.
  await injectRedirect(session, prompt);
  await safeInvoke("append_coord_woke", { session }, undefined);
  return true;
}

// CoreSlice — the residual of the former `automations` grab-bag after the automations CRUD moved
// to the Automations feature slice (@/features/automations/store, #1309) and the API-tier LLM
// provider config moved to the LlmSettings slice (#2715). Now: active-project / draft state + the
// projects-page view state. Typed Pick<AppStore, …>.
import type { StateCreator } from "zustand";
// LEAF import, not the barrel (#3245): `src/store/**` importing `@/features/planner` creates a
// module-init cycle — it broke five unrelated tunnel tests when this first went in as a barrel.
import { setDbTriaged } from "@/features/planner/list/projectsDbBridge";
import type { AppStore } from "@/store/types";
import { setMapEntry, deleteMapEntry } from "@/store/updateHelpers";
import { projectLinkId } from "@/features/glance/lib/projectLinks";
import { loadProjectLinks, pushProjectLink, dropProjectLink } from "@/features/glance/lib/projectLinksBridge";

type CoreSlice = Pick<AppStore,
  "projectsPageMode" | "setProjectsPageMode" | "glanceDrill" | "setGlanceDrill" | "previewSources" | "setPreviewSource" | "previewBuilding" | "setPreviewBuilding" | "reviewFindings" | "setReviewFindings" | "teamsDrill" | "setTeamsDrill" | "projectLinks" | "addProjectLink" | "removeProjectLink" | "hydrateProjectLinks" | "projectsView" | "setProjectsView" | "activeProjectId" | "activeProjectName" | "activeProjectRepo" | "activeProjectRepos" | "activeProjectNumber" | "setActiveProject" | "setActiveProjectMeta" | "hiddenProjectIds" | "dismissProject" | "addDraftProject" | "updateDraftProject" | "removeDraftProject" | "triagedProjects" | "markProjectTriaged" | "hydrateTriaged"
>;

export const createCoreSlice: StateCreator<AppStore, [], [], CoreSlice> = (set) => ({
      projectsPageMode: "projects",
      setProjectsPageMode: (v) => set({ projectsPageMode: v }),
      glanceDrill: null,
      setGlanceDrill: (id) => set({ glanceDrill: id }),
      // Verify-preview (#2623): the built PreviewSource + in-flight flag per project (transient).
      previewSources: {},
      setPreviewSource: (key, source) => set((s) => ({ previewSources: { ...s.previewSources, [key]: source } })),
      previewBuilding: {},
      setPreviewBuilding: (key, building) => set((s) => ({ previewBuilding: { ...s.previewBuilding, [key]: building } })),
      // Preview-review findings per project (#2623 slice 5b, transient) — the confirm-gated inbox.
      reviewFindings: {},
      setReviewFindings: (key, findings) => set((s) => ({ reviewFindings: { ...s.reviewFindings, [key]: findings } })),
      teamsDrill: null,
      setTeamsDrill: (id) => set({ teamsDrill: id }),

      // #2253 → #3786 write-through cache over `bsc project link` — hydrate authoritative on boot, each
      // mutation pushes through the bridge so agents (and a restart) see the same contracts. `target`
      // (#3786) names a non-project endpoint (a service / mcp server); a project↔project contract leaves it
      // absent so the persisted/wire shape stays byte-identical to the pre-#3786 model.
      projectLinks: [],
      addProjectLink: (from, to, kind, target) => {
        // A self-loop is only meaningless for a project target — an external service/mcp endpoint lives in
        // its own namespace, so `from === to` there is a legitimate contract (matches the Rust add_contract).
        if (from === to && (!target || target.type === "project")) return;
        const id = projectLinkId(from, to, kind);
        // Only a non-project target is stored on the link (keeps a project contract byte-identical).
        const external = target && target.type !== "project" ? target : undefined;
        let added = false;
        set((s) => {
          if (s.projectLinks.some((l) => l.id === id)) return {};
          added = true;
          return { projectLinks: [...s.projectLinks, { id, from, to, kind, ...(external ? { target: external } : {}) }] };
        });
        // Keep the plain project-link call at 3 args (a trailing undefined is a distinct arity to
        // `toHaveBeenCalledWith`) so the pre-#3786 write-through contract is unchanged.
        if (added) void (external ? pushProjectLink(from, to, kind, external) : pushProjectLink(from, to, kind));
      },
      removeProjectLink: (id) => {
        set((s) => ({ projectLinks: s.projectLinks.filter((l) => l.id !== id) }));
        void dropProjectLink(id);
      },
      hydrateProjectLinks: async () => {
        const loaded = await loadProjectLinks();
        if (loaded) set({ projectLinks: loaded }); // bridge unreachable → keep the persisted cache
      },
      projectsView: "list",
      setProjectsView: (v) => set({ projectsView: v }),
      activeProjectId: null,
      activeProjectName: "",
      activeProjectRepo: "",
      activeProjectRepos: [],
      activeProjectNumber: 0,
      setActiveProject: (id) => set({ activeProjectId: id }),
      // The node id is API-only meta (#2409): the project's data/folder key derives from its NAME
      // (`projectSlug`), so there is no node-id → key alias to record here anymore.
      setActiveProjectMeta: (id, name, repo, number, repos = []) =>
        set({
          activeProjectId: id, activeProjectName: name, activeProjectRepo: repo, activeProjectNumber: number, activeProjectRepos: repos,
        }),
      hiddenProjectIds: [],
      dismissProject: (id) =>
        set((s) => (!id || s.hiddenProjectIds.includes(id) ? {} : { hiddenProjectIds: [...s.hiddenProjectIds, id] })),
      addDraftProject: (key, draft) =>
        set((s) => ({ localDraftProjects: setMapEntry(s.localDraftProjects, key, draft) })),
      // Patch a draft record in place (#1222) — used to persist a title edit so it survives a
      // reopen. Keyed by the FROZEN key (not re-derived from the new title), so the on-disk folder
      // stays put. No-ops if the draft is gone.
      updateDraftProject: (key, patch) =>
        set((s) => {
          const cur = s.localDraftProjects[key];
          if (!cur) return {};
          return { localDraftProjects: setMapEntry(s.localDraftProjects, key, { ...cur, ...patch }) };
        }),
      removeDraftProject: (key) =>
        set((s) => ({ localDraftProjects: deleteMapEntry(s.localDraftProjects, key) })),
      // TRIAGED marker (#2541) — the drafted→triaged transition that gates the Glance network.
      // Idempotent: keeps the first timestamp so re-triaging doesn't reset it.
      //
      // #4088 — `projects.db` is the SOURCE; this map is an in-memory cache hydrated at boot, exactly
      // like skills/personas/teams. It used to live only in app-state.json, where no `bsc` command
      // could read or repair it and an app-state reset silently emptied the Glance network.
      triagedProjects: {},
      markProjectTriaged: (key) => {
        if (!key) return;
        // Write through FIRST so the durable marker lands even if this session never persists again.
        // `set` is idempotent server-side too, so a re-triage cannot rewrite the original timestamp.
        void setDbTriaged(key);
        set((s) => (s.triagedProjects[key] ? {} : { triagedProjects: { ...s.triagedProjects, [key]: Date.now() } }));
      },
      /** Replace the cache from `projects.db` (#4088), UNIONED with whatever is already in memory.
       *
       *  Union, not replace: a marker set in this session before hydration finished (or by a pre-#4088
       *  app-state that has not migrated yet) must not be dropped on the floor — losing one makes a
       *  worked project vanish from Glance, which is the exact bug this move exists to end. */
      hydrateTriaged: (fromDb) =>
        set((s) => ({ triagedProjects: { ...fromDb, ...s.triagedProjects } })),
});

// Minimal, dependency-free 5-field cron support for Automations (#171):
//   minute(0-59) hour(0-23) day-of-month(1-31) month(1-12) day-of-week(0-7, 0|7=Sun)
// Each field accepts `*`, single values, `a,b` lists, `a-b` ranges, and `*/n` /
// `a-b/n` / `a/n` steps. Day-of-month / day-of-week use the standard Vixie
// semantics: when both are restricted a date matches if EITHER matches.

interface CronFields {
  minute: Set<number>;
  hour: Set<number>;
  dom: Set<number>;
  month: Set<number>;
  dow: Set<number>;
  domRestricted: boolean;
  dowRestricted: boolean;
}

/** Parse one field into the set of allowed values, or null if malformed. */
function parseField(field: string, min: number, max: number): Set<number> | null {
  const out = new Set<number>();
  for (const part of field.split(",")) {
    if (part === "") return null;
    const slash = part.split("/");
    if (slash.length > 2) return null;
    let step = 1;
    if (slash.length === 2) {
      step = parseInt(slash[1], 10);
      if (!Number.isInteger(step) || step <= 0) return null;
    }
    const range = slash[0];

    let lo: number, hi: number;
    if (range === "*") {
      lo = min; hi = max;
    } else if (range.includes("-")) {
      const [a, b] = range.split("-");
      lo = parseInt(a, 10); hi = parseInt(b, 10);
      if (!Number.isInteger(lo) || !Number.isInteger(hi)) return null;
    } else {
      lo = parseInt(range, 10);
      if (!Number.isInteger(lo)) return null;
      // `a/n` means from a, stepping, up to max; a bare `a` is just {a}.
      hi = step !== 1 ? max : lo;
    }
    if (lo < min || hi > max || lo > hi) return null;
    for (let v = lo; v <= hi; v += step) out.add(v);
  }
  return out.size ? out : null;
}

/** Parse a 5-field cron expression, or null if invalid. */
export function parseCron(expr: string): CronFields | null {
  const parts = expr.trim().split(/\s+/);
  if (parts.length !== 5) return null;
  const minute = parseField(parts[0], 0, 59);
  const hour = parseField(parts[1], 0, 23);
  const dom = parseField(parts[2], 1, 31);
  const month = parseField(parts[3], 1, 12);
  const dowRaw = parseField(parts[4], 0, 7);
  if (!minute || !hour || !dom || !month || !dowRaw) return null;
  const dow = new Set<number>();
  for (const d of dowRaw) dow.add(d === 7 ? 0 : d); // 7 and 0 both mean Sunday
  return {
    minute, hour, dom, month, dow,
    domRestricted: parts[2] !== "*",
    dowRestricted: parts[4] !== "*",
  };
}

/** Whether a local Date (at minute resolution) matches the parsed fields. */
export function cronMatches(f: CronFields, d: Date): boolean {
  if (!f.minute.has(d.getMinutes())) return false;
  if (!f.hour.has(d.getHours())) return false;
  if (!f.month.has(d.getMonth() + 1)) return false;
  const domOk = f.dom.has(d.getDate());
  const dowOk = f.dow.has(d.getDay());
  if (f.domRestricted && f.dowRestricted) return domOk || dowOk;
  if (f.domRestricted) return domOk;
  if (f.dowRestricted) return dowOk;
  return true;
}

// Search horizon — ~4 years so leap-day-only expressions still resolve. The
// loop breaks on the first match, so this bound only matters for never-matching
// (but syntactically valid) expressions, which then return null.
const CAP_MINUTES = 366 * 4 * 1440;

/** Epoch ms of the next minute strictly after `fromMs` that matches, or null. */
export function nextCronRun(expr: string, fromMs: number): number | null {
  const f = parseCron(expr);
  if (!f) return null;
  let t = Math.floor(fromMs / 60000) * 60000 + 60000;
  for (let i = 0; i < CAP_MINUTES; i++) {
    if (cronMatches(f, new Date(t))) return t;
    t += 60000;
  }
  return null;
}

/** Cheap validity check for UI feedback. */
export function isValidCron(expr: string): boolean {
  return parseCron(expr) !== null;
}

// Cross-graph adapter (#3117, epic #3114) — the Sounds feature's map from its OWN store shape (a
// `SoundKit`) onto the feature-agnostic {@link NodeLookup} the shared cross-graph resolver composes,
// mirroring the Algorithms adapter (`algorithms/lib/crossGraphAdapter.ts`, #3116). The three pillars stay
// decoupled: `shared/lib/graph/crossGraph` knows nothing about a `SoundKit`; THIS module adapts it, and the
// consumer (the Design Studio preview + component graph, `designs/lib/libraryModules.ts`) wires it via
// `makeUrnResolver`. Pure + React-free.
//
// A node URN's `kit` is, for the sound graph, a SoundKit id (`signal`) and its `id` is the in-kit node id.
// A `@bsc/sounds/<id>` import a component author writes is KIT-LESS — the consumer picks the kit (the
// DEFAULT sound kit). `<id>` names, in priority order:
//   • a CUE (the playable product; primary) → `code` is a self-contained player module (`cuePlayerModule`),
//   • else a VOICE (a playable patch) → `code` is a player module for a synthetic one-shot cue of it,
//   • else a PRIMITIVE (a raw source descriptor) → resolves but carries NO `code`, so it's not
//     importable/vendorable — mirroring an algorithm primitive (a descriptor, not code).
// A sound has no JS source, so unlike an algorithm (whose `code` is real, vendored verbatim) the `code`
// here is SYNTHESIZED at resolve time — the one place a cue becomes a runnable module.
import type { NodeLookup, ResolvedNode } from "@/shared/lib/graph/crossGraph";
import type { Cue, SoundKit } from "@/features/sounds/lib/soundDescriptor";
import { BUILTIN_KITS } from "@/features/sounds/lib/soundKits";
import { cuePlayerModule } from "@/features/sounds/lib/cuePlayerModule";

/** A synthetic one-shot cue wrapping a single voice — so a VOICE (a playable patch) is importable +
 *  playable exactly like a cue: its emitted `code` is a player module for this one-layer wrapper. */
function voiceAsCue(voiceId: string, name: string): Cue {
  return { id: voiceId, name, category: "ui", layers: [{ voice: voiceId, at: 0 }] };
}

/**
 * A {@link NodeLookup} over the sound library for the `sound` graph. Given a `kit` (a SoundKit id) and an
 * in-kit `id`, resolve — in priority order — a CUE, else a VOICE, else a PRIMITIVE, to its
 * {@link ResolvedNode}, or `null` on a miss. Defaults to the packaged {@link BUILTIN_KITS}; a caller can
 * pass the live-hydrated kits. The returned node's `urn`/`graph`/`kit`/`id` are placeholders —
 * `makeUrnResolver` overwrites them from the URN — so only `label`/`kind`/`code` carry through (`id` is set
 * to the matched node's id so a caller can canonicalize the URN). A cue/voice carries the vendorable player
 * module in `code`; a primitive carries none (a descriptor). A broken kit (a dangling composes edge) makes
 * the player emit throw → this returns `null` rather than letting the resolver throw.
 */
export function soundNodeLookup(kits: SoundKit[] = BUILTIN_KITS): NodeLookup {
  return (kitId: string, id: string): ResolvedNode | null => {
    const kit = kits.find((k) => k.id === kitId);
    if (!kit) return null;

    // Build a resolved node; when `playable` is supplied, synthesize its self-contained player module as
    // `code` (a throw during compile — a broken kit — collapses to a clean miss).
    const resolved = (kind: string, label: string, playable: Cue | null): ResolvedNode | null => {
      let code: string | undefined;
      if (playable) {
        try {
          code = cuePlayerModule(playable, kit);
        } catch {
          return null;
        }
      }
      return { urn: "", graph: "sound", kit: kitId, id, label, kind, code };
    };

    const cue = kit.cues.find((c) => c.id === id);
    if (cue) return resolved("cue", cue.name, cue);
    const voice = kit.voices.find((v) => v.id === id);
    if (voice) return resolved("voice", voice.name, voiceAsCue(voice.id, voice.name));
    const prim = kit.primitives.find((p) => p.id === id);
    if (prim) return resolved("primitive", prim.name, null); // a descriptor — no code, not importable
    return null;
  };
}

// Cross-graph resolution + the `requires` edge (#3115, epic #3114). Builds on the URN grammar in
// ./nodeUrn: a URN NAMES a node; this module RESOLVES it to a normalized record, models the cross-graph
// `requires` edge, and lays foreign nodes out in a fenced band (the shape generalized from Glance's UI-kit
// band, #3007). All pure + feature-agnostic — a feature adapts its own hydrated store into a `NodeLookup`
// (it never imports another feature's types), and the consumer composes the per-graph lookups into one
// resolver via {@link makeUrnResolver}.
import { parseNodeUrn, type NodeGraph } from "@/shared/lib/graph/nodeUrn";

/** A node resolved across graphs — the normalized shape every pillar maps its own record onto, so a
 *  consumer (the component preview, the app graph) can treat an algorithm, a component, and a sound cue
 *  uniformly. Deliberately minimal: identity + label + kind, plus the reusable implementation when the
 *  graph carries one (an algorithm's `code`), which is what the preview vendors (#3116). */
export interface ResolvedNode {
  /** The canonical `<graph>:<kit>/<id>` URN this node resolved from. */
  urn: string;
  graph: NodeGraph;
  kit: string;
  id: string;
  /** Human label for the node card (the node's display name). */
  label: string;
  /** The graph-specific kind slug — `algorithm`/`primitive`, a component `role`, or `cue`/`voice`/
   *  `primitive`. Opaque here; the consumer/legend interprets it per graph. */
  kind: string;
  /** The reusable implementation source when the graph has one (an algorithm's `code`). Absent for a
   *  descriptor-only node (a sounds primitive, a spec component). The preview vendors this (#3116). */
  code?: string;
}

/** A single graph's lookup: given a kit + in-kit id, return the resolved node or null. A feature builds
 *  this from its hydrated store data (e.g. algorithms: find the impl with `tech === kit && id === id`). */
export type NodeLookup = (kit: string, id: string) => ResolvedNode | null;

/** Resolve any node URN to its {@link ResolvedNode}, or null (unknown graph, or the target doesn't exist). */
export type UrnResolver = (urn: string) => ResolvedNode | null;

/**
 * Compose per-graph {@link NodeLookup}s into one {@link UrnResolver}. A missing graph in the registry (or
 * a lookup miss) resolves to null — so a resolver wired with only `{ algo }` cleanly returns null for a
 * `sound:` URN instead of throwing. The returned node's `urn`/`graph`/`kit`/`id` are always overwritten
 * from the URN, so a lookup can't mislabel identity (it only supplies `label`/`kind`/`code`).
 */
export function makeUrnResolver(registry: Partial<Record<NodeGraph, NodeLookup>>): UrnResolver {
  return (urn: string): ResolvedNode | null => {
    const parts = parseNodeUrn(urn);
    if (!parts) return null;
    const lookup = registry[parts.graph];
    if (!lookup) return null;
    const found = lookup(parts.kit, parts.id);
    if (!found) return null;
    return { ...found, urn, graph: parts.graph, kit: parts.kit, id: parts.id };
  };
}

/** The only cross-graph relationship today — a node `requires` a node in another graph (a UI component
 *  requires an algorithm). Kept distinct from an in-kit `composes` so "built from my siblings" never
 *  blurs with "pulls in a foreign capability". */
export type CrossGraphRel = "requires";

/** A directed edge between two graphs: the node at `fromUrn` requires the node at `toUrn`. */
export interface CrossGraphEdge {
  id: string;
  fromUrn: string;
  toUrn: string;
  rel: CrossGraphRel;
}

/** Stable, collision-proof id for a cross-graph edge (`<fromUrn>~requires~<toUrn>`). */
export function crossGraphEdgeId(fromUrn: string, toUrn: string, rel: CrossGraphRel = "requires"): string {
  return `${fromUrn}~${rel}~${toUrn}`;
}

// ── The fenced band (#3007, generalized) — foreign/library nodes lifted OUT of a graph's main layout into
// a single row across the top, reading as a separate dimension. Glance does exactly this for UI-kit nodes;
// this is that math, parameterized, so the component graph (#3116/#3117) and the app graph (#3119) all
// render their pulled-in library nodes the same way. Pure + deterministic. ──

/** Inputs for {@link layoutBand} — all in world (design) coordinates. */
export interface BandOpts {
  /** Left edge of the content span the band centers over (Glance uses its layout's 70px left pad). */
  spanX0: number;
  /** Right edge of the content span (Glance uses the max project-node x). */
  spanX1: number;
  /** y of the band cards' TOP edge. */
  topPad: number;
  /** Band card height (so the divider clears the cards). */
  nodeH: number;
  /** Clearance from the cards' bottom down to the fence divider. */
  gap: number;
  /** Cap on the horizontal step between cards, so a couple of nodes cluster in the middle instead of
   *  stretching the full width (Glance caps at one column gap). */
  maxStep: number;
}

/** A laid-out band: each node's top-left position, plus the band's vertical extent + fence divider y. */
export interface BandLayout {
  positions: { x: number; y: number }[];
  /** Top of the band zone. */
  y0: number;
  /** Bottom of the band zone (== `dividerY`) — the rest of the graph shifts down by this much. */
  y1: number;
  /** y of the fence divider drawn under the band. */
  dividerY: number;
}

/**
 * Lay `count` foreign nodes out in a single centered row across the top, and report the fence divider the
 * main graph shifts below. Mirrors Glance's kit-band math (#3007): evenly spaced over [spanX0, spanX1] but
 * the step never exceeds `maxStep`. `count === 0` → no positions (the caller omits the band entirely).
 * Deterministic.
 */
export function layoutBand(count: number, opts: BandOpts): BandLayout {
  const { spanX0, spanX1, topPad, nodeH, gap, maxStep } = opts;
  const dividerY = topPad + nodeH + gap;
  const positions: { x: number; y: number }[] = [];
  if (count > 0) {
    const span = Math.max(0, spanX1 - spanX0);
    const step = count > 1 ? Math.min(span / (count - 1), maxStep) : 0;
    const rowW = step * (count - 1);
    const startX = spanX0 + (span - rowW) / 2;
    for (let i = 0; i < count; i++) positions.push({ x: startX + i * step, y: topPad });
  }
  return { positions, y0: 0, y1: dividerY, dividerY };
}

// Self-contained sound-cue player emit (#3117, epic #3114) — the Sounds analog of an algorithm's
// vendorable `code` (libraryModules.ts, #3116). An algorithm ships real JS `code` the preview vendors
// verbatim; a sound has NO JS source, so we can't vendor a file. Instead we COMPILE the cue here (synth.ts
// `compileCue`) and EMIT A STRING that is a self-contained ES module: it embeds the resulting flat
// `SCHEDULE` and inlines a MINIMAL Web Audio player ported from `synth.ts` — the preview iframe runs in
// isolation and canNOT import the app's `synth`, so the player must travel with the cue. Pure — no Web
// Audio, no React (the emitted STRING touches Web Audio only when its `play()` runs inside the preview).
//
// EXPORT API (what a component author binds): `import { play } from "@bsc/sounds/<id>"` — `play()` plays
// the cue now and returns its duration in seconds (0 where Web Audio is unavailable — a safe no-op in
// SSR/jsdom), reading naturally in an `onClick={() => play()}`. A DEFAULT export mirrors it, so
// `import play from "@bsc/sounds/<id>"` binds too.
import { compileCue } from "@/features/sounds/lib/synth";
import type { Cue, SoundKit } from "@/features/sounds/lib/soundDescriptor";

/** The static player runtime inlined into every emitted module — a minimal port of synth.ts's
 *  `getCtx`/`whiteNoise`/`scheduleVoice`/`playCue` that reads the pre-compiled `SCHEDULE` the emit prepends.
 *  Kept as ONE literal so the emit is just `SCHEDULE` + this. MUST stay behaviorally in lockstep with
 *  `synth.ts` (the desktop player) — both realize the same compiled schedule on a Web Audio graph. */
const PLAYER_RUNTIME = `
let __ctx = null;
let __noise = null;

function __getCtx() {
  if (typeof window === "undefined") return null;
  const Ctor = window.AudioContext || window.webkitAudioContext;
  if (!Ctor) return null;
  if (!__ctx) __ctx = new Ctor();
  if (__ctx.state === "suspended") __ctx.resume();
  return __ctx;
}

function __whiteNoise(ctx) {
  if (__noise && __noise.sampleRate === ctx.sampleRate) return __noise;
  const buf = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  __noise = buf;
  return buf;
}

function __scheduleVoice(ctx, v, t0) {
  const start = t0 + v.startAt;
  const { attack, decay, sustain, release } = v.env;
  const peak = Math.max(0.0001, v.gain);

  const amp = ctx.createGain();
  amp.gain.setValueAtTime(0.0001, start);
  amp.gain.linearRampToValueAtTime(peak, start + attack);
  amp.gain.linearRampToValueAtTime(Math.max(0.0001, sustain * peak), start + attack + decay);
  amp.gain.linearRampToValueAtTime(0.0001, start + attack + decay + release);

  let node;
  if (v.source === "noise") {
    const src = ctx.createBufferSource();
    src.buffer = __whiteNoise(ctx);
    src.loop = true;
    node = src;
  } else {
    const osc = ctx.createOscillator();
    osc.type = v.waveform;
    osc.detune.setValueAtTime(v.detune, start);
    osc.frequency.setValueAtTime(v.freq, start);
    if (v.pitchTo != null && v.pitchTo !== v.freq) {
      osc.frequency.linearRampToValueAtTime(v.pitchTo, start + v.duration);
    }
    node = osc;
  }

  let tail = node;
  if (v.filter) {
    const f = ctx.createBiquadFilter();
    f.type = v.filter.type;
    f.frequency.setValueAtTime(v.filter.cutoff, start);
    tail.connect(f);
    tail = f;
  }
  tail.connect(amp);
  amp.connect(ctx.destination);

  node.start(start);
  node.stop(start + v.duration + 0.02);
}

/** Play the cue now; returns its duration in seconds (0 where Web Audio is unavailable — a safe no-op). */
export function play() {
  const ctx = __getCtx();
  if (!ctx) return 0;
  const t0 = ctx.currentTime + 0.02;
  for (const v of SCHEDULE.voices) __scheduleVoice(ctx, v, t0);
  return SCHEDULE.duration;
}

export default play;
`;

/**
 * Emit a self-contained ES module (as a string) that plays `cue` — the vendorable "code" for a sound the
 * Design Studio preview imports as `@bsc/sounds/<id>` (#3117). Compiles `cue` against `kit` (synth.ts
 * `compileCue`) and embeds the resulting flat `SCHEDULE` ahead of the inlined {@link PLAYER_RUNTIME}.
 * Deterministic + pure.
 *
 * Throws only when the kit has a DANGLING composes edge (a broken user kit) — the packaged kits are
 * test-guarded, so the caller (the sounds `NodeLookup`) treats a throw as "not resolvable" and returns
 * `null`, exactly as an algorithm primitive (no `code`) is not vendorable.
 */
export function cuePlayerModule(cue: Cue, kit: SoundKit): string {
  const compiled = compileCue(cue, kit);
  const header =
    `// Generated player for the "${cue.name}" sound cue (@bsc/sounds/${cue.id}) — self-contained, no app\n` +
    `// imports (#3117). Embeds the compiled schedule + a minimal Web Audio player.\n`;
  return `${header}const SCHEDULE = ${JSON.stringify(compiled)};\n${PLAYER_RUNTIME}`;
}

// Cull reporting (#measure-where-the-components-graph-spends-its-commit) — how much of a graph is
// actually mounted, so the effect of viewport culling is a measured number rather than an assumption.
//
// WHY THIS IS NOT OBVIOUS FROM THE CODE. Culling's reach is a function of three things that only meet at
// runtime: the world's shape, the viewport's shape, and the zoom. The components graph wraps at 8 per row,
// so 459 nodes make a world ~1676 wide and ~4800 tall — and with a one-viewport margin the mounted rect is
// WIDER than the entire world at any zoom below ~2.5x. Culling therefore removes nothing horizontally and
// only trims vertically above ~0.5 zoom. None of that is visible from reading the filter; it falls out of
// the arithmetic at the zoom the user happens to be at.
//
// So the honest way to know whether culling is doing anything is to count.

/** One reading of how much of a graph is mounted. */
export interface CullReading {
  shown: number;
  total: number;
  /** The zoom it was taken at — the variable that decides whether culling can help at all. */
  scale: number;
}

/**
 * A one-line summary of a cull reading, or `null` when it is not worth logging.
 *
 * Returns null when NOTHING is culled (`shown === total`). That is the common case at a fit-the-graph
 * zoom, where every node genuinely is visible — reporting it every time would bury the readings that
 * carry information under ones that carry none.
 *
 * Pure so the threshold and the wording are testable without a DOM, a store or a graph.
 */
export function cullSummary(r: CullReading): string | null {
  if (r.total <= 0 || r.shown >= r.total) return null;
  const pct = Math.round((r.shown / r.total) * 100);
  return `[perf] graph cull: ${r.shown}/${r.total} nodes mounted (${pct}%) at ${Math.round(r.scale * 100)}% zoom`;
}

/**
 * Has the reading changed enough to be worth another line?
 *
 * Culling recomputes on every view commit, so an unguarded log would write a line per pan and per zoom
 * step and drown the phase timings this was added to sit beside. A reading is interesting when the
 * mounted COUNT moves materially — `minDelta` nodes — or when it crosses into or out of "nothing culled",
 * which is the transition that actually answers "does culling engage at this zoom".
 */
export function worthReporting(prev: CullReading | null, next: CullReading, minDelta = 20): boolean {
  if (!prev) return true;
  const wasCulling = prev.shown < prev.total;
  const isCulling = next.shown < next.total;
  if (wasCulling !== isCulling) return true;
  return Math.abs(next.shown - prev.shown) >= minDelta;
}

// Cycle detection (#2217, graph-core epic #2214) — the shared primitives the graphs use to find cycles
// in a directed graph. Two flavours, matching what the features already do:
//   • findBackEdges — DFS (white/grey/black) back-edge detection: finds ANY-length cycle and returns
//     the edges that close one. Used for topological layering (exclude back-edges so a cycle can't
//     explode the layout) and to flag coordination deadlocks. This is the relationship graph's algorithm.
//   • mutualPairs — the 2-cycle special case (a↔b): the cheap "mutual dependency" check the Glance
//     network surfaces as coordination hazards.
// Both are pure; the caller pre-filters to whichever edge subset is order-bearing.
import type { GraphEdge } from "@/shared/lib/graph/types";

/**
 * DFS back-edge detection over `edges` restricted to `nodeIds`. Returns the set of edge ids that close
 * a cycle (grey-target back-edges) and whether any cycle exists. Nodes are visited in `nodeIds` order
 * and each node's out-edges in `edges` order, so the result is deterministic.
 */
export function findBackEdges(nodeIds: readonly string[], edges: readonly GraphEdge[]): { backEdgeIds: Set<string>; hasCycle: boolean } {
  const idSet = new Set(nodeIds);
  const adj = new Map<string, { to: string; id: string }[]>(nodeIds.map((i) => [i, []]));
  for (const e of edges) {
    if (idSet.has(e.from) && idSet.has(e.to)) adj.get(e.from)!.push({ to: e.to, id: e.id });
  }
  const color = new Map<string, 0 | 1 | 2>(); // 0 white · 1 grey (on stack) · 2 black
  const backEdgeIds = new Set<string>();
  let hasCycle = false;
  const dfs = (n: string) => {
    color.set(n, 1);
    for (const { to, id } of adj.get(n) ?? []) {
      const c = color.get(to) ?? 0;
      if (c === 1) { hasCycle = true; backEdgeIds.add(id); } // back-edge → a cycle
      else if (c === 0) dfs(to);
    }
    color.set(n, 2);
  };
  for (const i of nodeIds) if ((color.get(i) ?? 0) === 0) dfs(i);
  return { backEdgeIds, hasCycle };
}

/**
 * Mutual pairs (a↔b) — every pair of nodes with edges in both directions. Returns the pairs (each once,
 * `from < to`), the ids of ALL edges in a mutual pair (both directions), and the node ids involved.
 */
export function mutualPairs(edges: readonly GraphEdge[]): { pairs: [string, string][]; edgeIds: Set<string>; nodeIds: Set<string> } {
  const pairs: [string, string][] = [];
  const edgeIds = new Set<string>();
  const nodeIds = new Set<string>();
  for (const a of edges) for (const b of edges) {
    if (a.from === b.to && a.to === b.from && a.from < a.to) {
      edgeIds.add(a.id); edgeIds.add(b.id);
      pairs.push([a.from, a.to]);
      nodeIds.add(a.from); nodeIds.add(a.to);
    }
  }
  return { pairs, edgeIds, nodeIds };
}

// Source-mode atoms for the planner focused-pane bodies — the `scrape` vs `fetch` vocabulary
// and the declared-source shape that `bodyPrimitives.tsx` renders (ModeChip / SourceHead).
//
// Pure types + one helper; React-free by design (the primitives that consume them are the
// React half).
//
// History: this module used to also carry the JSON contracts for a data-COLLECTION pane
// system (Targets · Licensing · Acquire · Extract · Map · Clean · Load) plus a
// `parseStageJson` loader, all keyed to a `useStageJson.ts` hook that was never written.
// None of it ever had a consumer; removed in #3244. If those panes get built, the contracts
// should be re-derived from the panes that actually need them rather than restored wholesale.

export type CollectMode = "scrape" | "fetch";

/** One declared external source (a site to scrape or an API/dataset to fetch). */
export interface CollectSource {
  id: string;
  mode: CollectMode;
  label: string;
  /** URL / endpoint / dataset identifier. */
  loc?: string;
  /** Free-text kind ("website", "REST API", "CSV dataset", …). */
  type?: string;
  /** Data Model entity names this source is expected to populate. */
  feeds?: string[];
  /** Crawl/fetch bounds — keeps acquisition bounded. */
  scope?: { start?: string; pattern?: string; bound?: string };
}

/** Mode chip hue (matches the design: scrape=230, fetch=175). */
export function modeHue(mode: CollectMode): number {
  return mode === "scrape" ? 230 : 175;
}

// Migration SOURCE → canonical Data Model derivation (#1205, "data dictates structure") — the pure
// helper that turns a scan into the project's Data Model: one entity per discovered object (deduped
// across sources), fields from the discovered columns (or a default `id` identity), with relationships
// resolved from connector-declared lookups (#1219) or inferred by name (#1209). This is what
// `features`/`structure` design over — the Source pane persists it to the project's DuckDB store via
// `bsc data model set --refined` (#1446), NOT to any file. Split out of sourceValidate.ts (#1712);
// the type model lives in sourceSpecs.ts.

import type { DataModel, Entity, Field, FieldType } from "@/features/planner/data/dataModel";
import type { DiscoveredField, SourceConfig } from "@/features/planner/lib/sourceSpecs";

const fieldName = (f: string | DiscoveredField): string => (typeof f === "string" ? f : f.name);
const fieldMeta = (f: string | DiscoveredField): { type?: FieldType; enumValues?: string[]; ref?: string } =>
  typeof f === "string" ? {} : { type: f.type, enumValues: f.enumValues, ref: f.ref };

/** Slug a source object/column name into a safe Data Model key (matches dataModel.ts SAFE_IDENT). */
export function safeKey(raw: string): string {
  const s = raw.trim().toLowerCase().replace(/[^a-z0-9_]+/g, "_").replace(/^_+|_+$/g, "");
  return /^[a-z_]/.test(s) ? s : `e_${s}`;
}

/** Build a Data Model from the scanned sources — entities from discovered objects, fields from
 *  their columns (or a default `id` key), deduped by entity key. */
export function deriveDataModel(cfg: SourceConfig, id = "dm-source"): DataModel {
  const entities: Entity[] = [];
  const seen = new Set<string>();
  for (const s of cfg.sources) {
    if (s.status !== "scanned") continue;
    for (const o of s.objects ?? []) {
      const key = safeKey(o.name) || "entity";
      if (seen.has(key)) continue; // one entity per object name, across sources
      seen.add(key);
      const fseen = new Set<string>();
      const cols = (o.fields ?? [])
        .map((f) => ({ key: safeKey(fieldName(f)), meta: fieldMeta(f) }))
        .filter((c) => c.key && !fseen.has(c.key) && (fseen.add(c.key), true));
      const fields: Field[] = cols.length
        ? cols.map((c) => ({
            key: c.key,
            type: c.meta.type ?? "string",
            ...(c.meta.enumValues && c.meta.enumValues.length ? { enum_values: c.meta.enumValues } : {}),
            ...(c.meta.ref ? { ref: safeKey(c.meta.ref) } : {}),
          }))
        : [{ key: "id", type: "string" as const, required: true }];
      const identity = fields.some((f) => f.key === "id") ? ["id"] : fields[0] ? [fields[0].key] : [];
      entities.push({ key, label: o.name, fields, identity });
    }
  }
  // Resolve relationships. A connector-declared lookup (#1219, e.g. Salesforce AccountId → Account)
  // wins when its target was scanned — it's exact, and its field key (`accountid`) wouldn't match by
  // name. Otherwise infer (#1209): a field whose key matches another entity's key is a `ref` to it
  // (e.g. Contact.account → Account). Either gives the graph its edges and the list its ref chips.
  const entityKeys = new Set(entities.map((e) => e.key));
  for (const e of entities) {
    for (const f of e.fields) {
      if (f.ref && entityKeys.has(f.ref)) {
        f.type = "ref";
        delete f.enum_values; // a ref isn't an enum
      } else if (f.key !== e.key && entityKeys.has(f.key)) {
        f.type = "ref";
        f.ref = f.key;
        delete f.enum_values;
      } else if (f.ref) {
        // Declared ref to an object that wasn't scanned — drop the dangling link, keep a plain field.
        delete f.ref;
        if (f.type === "ref") f.type = "string";
      }
    }
  }
  return { id, name: cfg.dataModelName || "Source Data Model", version: 1, entities };
}

// Canonical Data Model authoring (#780) — the TS side of the data-platform substrate.
//
// JSON-compatible with the Rust `bsc_data::schema` types (crates/data, #781): the same
// wire shape round-trips, so the planner / this UI author a model and the DuckDB store
// materializes it. Field names match the Rust serde output exactly (`type`, `ref`,
// `enum_values`); `id` is TS-library bookkeeping only and the Rust store ignores it
// (serde drops unknown fields).
//
// Pure (no React/Tauri) so the validation + edit transforms are unit-testable and the
// store can seed from it directly — mirrors how blueprints.ts works.
//
// SCOPE: this module owns the SHAPE (`DataModel`/`Entity`/`Field`) and the SHAPING OPS over it —
// it is NOT the canonical Data Model. The canonical model is the per-project DuckDB store in
// crates/data, reached via `bsc data model get` / `bsc data model set` (#1446); the Source pane
// derives a model from a scan (`lib/dataModelDerivation.ts`) and persists it there.
//
// The edit transforms (`addEntity` / `updateEntity` / `removeEntity` / `addField` / `updateField` /
// `removeField` / `toggleIdentity`) are the PENDING SHAPING SURFACE — the intended implementation of
// "the user shapes the derived result" — and have no UI caller yet (#3249). They are deliberately
// kept: not dead code (#3244).

export type FieldType = "string" | "number" | "bool" | "date" | "money" | "ref" | "enum";

/** Entity/field keys become SQL identifiers in the store, which whitelists exactly this
 *  shape (`ddl::quote_ident`). Surfacing it here lets the editor flag a bad key before a
 *  load would be rejected. */
export const SAFE_IDENT = /^[A-Za-z_][A-Za-z0-9_]*$/;

export interface Field {
  key: string;
  label?: string;
  type: FieldType;
  required?: boolean;
  /** Target entity key when `type === "ref"`. */
  ref?: string;
  /** Allowed values when `type === "enum"`. */
  enum_values?: string[];
  /** Declarative validation rule id, read by the quality gate (#783). */
  validate?: string;
}

export interface Entity {
  key: string;
  label?: string;
  fields: Field[];
  /** Field keys forming the natural / merge identity — used by the director to merge
   *  records across sources (#785). */
  identity: string[];
}

export interface DataModel {
  /** TS library id; ignored by the Rust store. */
  id: string;
  name: string;
  version: number;
  entities: Entity[];
}

/** A fresh, empty model. */
export function emptyDataModel(id: string, name = "Untitled model"): DataModel {
  return { id, name, version: 1, entities: [] };
}

/**
 * Structural validation, independent of any data — mirrors the Rust `DataModel::check`
 * plus identifier safety. Returns the list of problems (empty ⇒ valid) for the editor to
 * surface; a model with problems shouldn't be loaded.
 */
export function checkDataModel(m: DataModel): string[] {
  const problems: string[] = [];
  const seenEntities = new Set<string>();
  for (const e of m.entities) {
    if (!e.key.trim()) problems.push("an entity has an empty key");
    else if (!SAFE_IDENT.test(e.key)) problems.push(`entity key "${e.key}" is not a safe identifier`);
    if (seenEntities.has(e.key)) problems.push(`duplicate entity key "${e.key}"`);
    seenEntities.add(e.key);

    const seenFields = new Set<string>();
    for (const f of e.fields) {
      if (!f.key.trim()) problems.push(`${e.key}: a field has an empty key`);
      else if (!SAFE_IDENT.test(f.key)) problems.push(`${e.key}.${f.key}: not a safe identifier`);
      if (seenFields.has(f.key)) problems.push(`${e.key}: duplicate field key "${f.key}"`);
      seenFields.add(f.key);

      if (f.type === "ref") {
        if (!f.ref) problems.push(`${e.key}.${f.key}: ref field has no target entity`);
        else if (!m.entities.some((x) => x.key === f.ref)) problems.push(`${e.key}.${f.key}: ref to unknown entity "${f.ref}"`);
      }
    }
    for (const id of e.identity) {
      if (!e.fields.some((f) => f.key === id)) problems.push(`${e.key}: identity field "${id}" is not a field`);
    }
  }
  return problems;
}

// ── pure edit transforms (return a new model) ─────────────────────────────────

const mapEntity = (m: DataModel, key: string, fn: (e: Entity) => Entity): DataModel => ({
  ...m,
  entities: m.entities.map((e) => (e.key === key ? fn(e) : e)),
});

export function addEntity(m: DataModel, key: string): DataModel {
  return { ...m, entities: [...m.entities, { key, label: "", fields: [], identity: [] }] };
}

export function updateEntity(m: DataModel, key: string, patch: Partial<Pick<Entity, "key" | "label">>): DataModel {
  return mapEntity(m, key, (e) => ({ ...e, ...patch }));
}

export function removeEntity(m: DataModel, key: string): DataModel {
  return { ...m, entities: m.entities.filter((e) => e.key !== key) };
}

export function addField(m: DataModel, entityKey: string, field: Field): DataModel {
  return mapEntity(m, entityKey, (e) => ({ ...e, fields: [...e.fields, field] }));
}

export function updateField(m: DataModel, entityKey: string, fieldKey: string, patch: Partial<Field>): DataModel {
  return mapEntity(m, entityKey, (e) => ({
    ...e,
    fields: e.fields.map((f) => (f.key === fieldKey ? { ...f, ...patch } : f)),
  }));
}

export function removeField(m: DataModel, entityKey: string, fieldKey: string): DataModel {
  return mapEntity(m, entityKey, (e) => ({
    ...e,
    fields: e.fields.filter((f) => f.key !== fieldKey),
    identity: e.identity.filter((id) => id !== fieldKey),
  }));
}

/** Toggle whether a field is part of the entity's merge identity. */
export function toggleIdentity(m: DataModel, entityKey: string, fieldKey: string): DataModel {
  return mapEntity(m, entityKey, (e) => ({
    ...e,
    identity: e.identity.includes(fieldKey) ? e.identity.filter((id) => id !== fieldKey) : [...e.identity, fieldKey],
  }));
}

/** Starter library — one canonical CRM model so the page isn't empty and the wire format
 *  is demonstrated end-to-end. */
export function seedDataModels(): DataModel[] {
  return [
    {
      id: "dm-crm",
      name: "CRM Core",
      version: 1,
      entities: [
        {
          key: "account", label: "Account", identity: ["id"],
          fields: [
            { key: "id", type: "string", required: true },
            { key: "name", type: "string", required: true },
            { key: "industry", type: "string" },
            { key: "annual_revenue", type: "money" },
          ],
        },
        {
          key: "contact", label: "Contact", identity: ["id"],
          fields: [
            { key: "id", type: "string", required: true },
            { key: "full_name", type: "string", required: true },
            { key: "email", type: "string" },
            { key: "account", type: "ref", ref: "account" },
          ],
        },
      ],
    },
  ];
}

// debugBridge (#3437, epic #3260) — the PURE half of `bsc debug`: turn an inspection request into a
// result, with every environment-dependent capability injected.
//
// WHY PURE + INJECTED
// The two facts this verb exists to report are exactly the two jsdom cannot produce: `elementFromPoint`
// (jsdom has no hit-testing at all) and a real `getBoundingClientRect` (jsdom returns zeros). If the
// logic reached for them directly, the module would be untestable and the shipped behavior would be
// pinned by nothing. Injecting them means the DECISIONS — is this element covered, which ancestor chain,
// how is a silent engine distinguished from an absent one — are unit-testable, and only the thin adapter
// (`useDebugChannel`) touches the real DOM.
//
// READ-ONLY BY CONSTRUCTION
// There is no branch here that evaluates caller-supplied code, and there must never be one: the whole
// point of the `designer` role (#2471) is that its writable surface is `bsc ui` alone, and an eval verb
// on the same binary would be a way around it. Every request is one of a closed set (see `DebugRequest`).
import type { PreviewFrameEntry } from "@/features/designs";

/** The wire request, mirroring the Rust `bsc_debug::DebugRequest` (serde tag = `op`). */
export type DebugRequest =
  | { op: "hit"; x: number; y: number }
  | { op: "probe"; selector: string; all?: boolean }
  | { op: "frames" };

/** One element's report — mirrors `bsc_debug::ElementInfo`. Snake_case: it crosses to Rust verbatim. */
export interface ElementInfo {
  label: string;
  rect: [number, number, number, number];
  styles: Record<string, string>;
  topmost_at_centre: boolean;
  covered_by?: string;
}

export interface EngineProbe {
  listening: boolean;
  transform: string;
  scale: number;
  pan: [number, number];
}

export interface FrameInfo {
  component: string;
  element: ElementInfo;
  engine_requested: boolean;
  engine_in_srcdoc: boolean;
  engine?: EngineProbe;
}

/** Mirrors `bsc_debug::DebugResult` (serde rename_all = lowercase, externally tagged). */
export type DebugResult =
  | { hit: { chain: ElementInfo[] } }
  | { probe: { matched: ElementInfo[] } }
  | { frames: { frames: FrameInfo[] } };

/** Everything environment-dependent, injected so the decisions above stay testable. */
export interface InspectDeps {
  /** Hit-test a viewport point. jsdom has none, so tests supply their own. */
  at: (x: number, y: number) => Element | null;
  /** Viewport rect for an element, in CSS px. */
  rectOf: (el: Element) => { x: number; y: number; width: number; height: number };
  /** The computed styles this verb reports (only these — a full dump would bury the signal). */
  stylesOf: (el: Element) => Record<string, string>;
  /** Elements matching a selector. Throws on an invalid selector; the caller turns that into an error. */
  query: (selector: string) => Element[];
  /** The mounted previews (the registry). */
  frames: () => PreviewFrameEntry[];
  /** Ask one preview's engine to describe itself. Resolves `null` when it never answers — which is the
   *  signal that the script is present but not running. */
  probeEngine: (iframe: HTMLIFrameElement) => Promise<EngineProbe | null>;
}

/** The styles that decide whether a click reaches an element (plus the two that explain "I can see it but
 *  can't grab it"). Kept small on purpose: this output is read by a human mid-debug. */
export const REPORTED_STYLES = [
  "pointer-events",
  "z-index",
  "opacity",
  "position",
  "transform",
  "cursor",
  "user-select",
] as const;

/** `tag#id.class1.class2` — enough to find the element in the source without dumping the DOM. */
export function labelOf(el: Element): string {
  const tag = el.tagName.toLowerCase();
  const id = el.id ? `#${el.id}` : "";
  const cls = typeof el.className === "string" && el.className.trim()
    ? `.${el.className.trim().split(/\s+/).slice(0, 3).join(".")}`
    : "";
  return `${tag}${id}${cls}`;
}

/**
 * Describe one element, including the question that matters: would a click aimed at its centre actually
 * land on it?
 *
 * "Topmost" means the hit-test returns this element **or a descendant** — a descendant still means the
 * click reaches this subtree. An ANCESTOR coming back means it does not (this element is transparent to
 * hit-testing, e.g. `pointer-events: none`), so that counts as covered and the ancestor is named.
 */
export function describeElement(el: Element, deps: InspectDeps): ElementInfo {
  const r = deps.rectOf(el);
  const cx = r.x + r.width / 2;
  const cy = r.y + r.height / 2;
  // A zero-area element can never be hit; hit-testing its "centre" would report whatever is behind it
  // and read as "covered", which misdiagnoses a collapsed rect as an overlay bug.
  const collapsed = r.width < 1 || r.height < 1;
  const top = collapsed ? null : deps.at(cx, cy);
  const topmost = !collapsed && !!top && (top === el || el.contains(top));
  return {
    label: labelOf(el),
    rect: [r.x, r.y, r.width, r.height],
    styles: deps.stylesOf(el),
    topmost_at_centre: topmost,
    ...(topmost ? {} : { covered_by: collapsed ? "(zero-area rect)" : top ? labelOf(top) : "(nothing hit-tests there)" }),
  };
}

/** Run one inspection. Never throws for a "nothing found" case — an empty match is an ANSWER. */
export async function inspectDebug(req: DebugRequest, deps: InspectDeps): Promise<DebugResult> {
  switch (req.op) {
    case "hit": {
      const target = deps.at(req.x, req.y);
      if (!target) return { hit: { chain: [] } };
      const chain: ElementInfo[] = [];
      for (let el: Element | null = target; el; el = el.parentElement) {
        chain.push(describeElement(el, deps));
      }
      return { hit: { chain } };
    }
    case "probe": {
      const found = deps.query(req.selector);
      const picked = req.all ? found : found.slice(0, 1);
      return { probe: { matched: picked.map((el) => describeElement(el, deps)) } };
    }
    case "frames": {
      const entries = deps.frames();
      const frames = await Promise.all(
        entries.map(async (f): Promise<FrameInfo> => {
          const engine = await deps.probeEngine(f.iframe);
          return {
            component: f.component,
            element: describeElement(f.iframe, deps),
            engine_requested: f.engineRequested,
            engine_in_srcdoc: f.engineInSrcdoc,
            ...(engine ? { engine } : {}),
          };
        }),
      );
      return { frames: { frames } };
    }
  }
}

// The debug feature's graph-platform surface (register-the-feature-logic-surface) — the modules a
// graph-loaded record imports from this feature but does NOT redraw.
//
// Registered HERE, inside the feature, because the shell must not reach a feature's internals (#1545)
// and eager-importing them from `app/` would de-lazy the whole feature at boot. The feature's BARREL
// calls this at module load, so the shadow catalogue's `ensurePlatform: () => import("@/features/debug")`
// is what registers them — the same shape `registerAutomationsPlatform` already uses.
//
// These files STAY on disk: registration is not migration. It makes a record that imports them
// loadable, which is the prerequisite for migrating the modules that import THEM.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as RequestSession from "@/features/debug/requestSession";

let done = false;

/** Register this feature's injected graph-platform modules by the specifiers a record imports. Idempotent. */
export function registerDebugPlatform(): void {
  if (done) return;
  done = true;
  registerAppModule("@/features/debug/requestSession", RequestSession);
}

// The shadow catalogue registers this feature's graph-platform modules by importing
// `./graphPlatform` DIRECTLY and calling its register function (see `shadowPages.ts`). This barrel
// therefore has NO import-time side effect — it is re-exports only, which is what lets it be a
// record rather than a file that must run to be correct.

