// The dependency manifest (#1111/#1127): the authoritative, planner-owned list of the libraries every
// repo depends on, defined ONCE during planning so the fleet doesn't each add/redefine deps in
// parallel worktrees and collide at integration. The planner records it via `bsc-plan deps set` into
// plan.db (#1191 — was a raw `dependencies.json`); the poll reflects the stored manifest into the
// DEPENDENCIES section, the Dependencies gate reads its count, publish pre-populates each repo's real
// `package.json` / `Cargo.toml` from it, and each worker's CLAUDE.local.md inlines the locked set with
// a "don't touch the manifests" guardrail. This module stays a pure + tolerant manifest model (it
// parses the same shape whether it arrives from plan.db or a legacy file) — no React/Tauri.
//
// BARREL (#2148): the model was decomposed into colocated sibling modules; this file preserves the
// original public API so every importer keeps working unchanged. Each concern lives in its own module:
//   · dependencyTypes           — the manifest types + section key
//   · dependencyParse           — parsing + the per-repo / per-ecosystem selectors
//   · dependencySources         — grouping deps by their source registry (Deploy pane, #1127)
//   · dependencyStreams         — the per-stream shared-dependencies view (Streams pane, #1429)
//   · dependencyManifests       — the publish-time package.json / Cargo.toml writers
//   · dependencyRegistryConfig  — the .npmrc / .cargo/config.toml writers
//   · dependencyWorkerBlock     — the CLAUDE.local.md locked-deps block

export {
  DEPENDENCIES_KEY,
  type DependencyEcosystem,
  type PlanDependency,
  type DependencyRegistry,
  type DependencyManifest,
} from "@/features/planner/issues/dependencyTypes";

export {
  parseDependencyManifest,
  parseDependenciesFile,
  depsForRepo,
  bucketByEcosystem,
} from "@/features/planner/issues/dependencyParse";

export {
  type DependencySourceGroup,
  groupDependenciesBySource,
} from "@/features/planner/issues/dependencySources";

export {
  type StreamDependency,
  type StreamDepGroup,
  type SharedRepoDeps,
  sharedRepoDependencies,
  unlockedSharedRepos,
} from "@/features/planner/issues/dependencyStreams";

export {
  mergeIntoPackageJson,
  mergeIntoCargoToml,
} from "@/features/planner/issues/dependencyManifests";

export {
  buildNpmrc,
  buildCargoConfig,
} from "@/features/planner/issues/dependencyRegistryConfig";

export {
  buildWorkerDependencyBlock,
} from "@/features/planner/issues/dependencyWorkerBlock";

// ── Manifest writers (publish-time scaffold seed, #1111) ──────────────────────────
// Additive + never-clobber: an existing pinned version always wins over the planned one, so
// re-publishing or seeding a hand-edited manifest never downgrades or fights a real dependency.

import type { PlanDependency } from "@/features/planner/issues/dependencyTypes";

/** A crate/package name reduced to a valid bare identifier for a generated manifest. */
function safePkgName(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9_-]+/g, "-").replace(/^-+|-+$/g, "") || "app";
}

/**
 * Merge the npm dependencies into a `package.json`, returning the pretty-printed JSON (or `null`
 * when there are none to add). `existing` is the current file content (or null/empty for a fresh
 * repo — a minimal private package is generated). An npm dep already present in the manifest keeps
 * its pinned version; only genuinely missing deps are added.
 */
export function mergeIntoPackageJson(existing: string | null, pkgName: string, deps: PlanDependency[]): string | null {
  const npm = deps.filter((d) => d.ecosystem === "npm");
  if (!npm.length) return null;

  let json: Record<string, unknown> = {};
  if (existing && existing.trim()) {
    try {
      const parsed: unknown = JSON.parse(existing);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) json = parsed as Record<string, unknown>;
    } catch { /* unparseable — treat as fresh rather than clobber blindly */ return null; }
  } else {
    json = { name: safePkgName(pkgName), version: "0.1.0", private: true };
  }

  const ensure = (field: "dependencies" | "devDependencies") => {
    const cur = json[field];
    return (cur && typeof cur === "object" && !Array.isArray(cur)) ? { ...(cur as Record<string, string>) } : {};
  };
  const runtime = ensure("dependencies");
  const development = ensure("devDependencies");

  for (const d of npm) {
    const target = d.dev ? development : runtime;
    if (target[d.name] === undefined) target[d.name] = d.version ?? "*"; // never clobber a pinned version
  }
  if (Object.keys(runtime).length) json.dependencies = sortedRecord(runtime);
  if (Object.keys(development).length) json.devDependencies = sortedRecord(development);

  return JSON.stringify(json, null, 2) + "\n";
}

function sortedRecord(r: Record<string, string>): Record<string, string> {
  return Object.fromEntries(Object.keys(r).sort().map((k) => [k, r[k]]));
}

/** A single Cargo dependency line. A dep with a non-default `source` takes the table form so cargo
 *  resolves it against the named registry: `name = { version = "x", registry = "src" }`. */
function cargoDepLine(d: PlanDependency): string {
  const ver = d.version ?? "*";
  return d.source
    ? `${d.name} = { version = "${ver}", registry = "${d.source}" }`
    : `${d.name} = "${ver}"`;
}

/**
 * Merge the cargo dependencies into a `Cargo.toml`, returning the file content (or `null` when
 * there are none to add). With no existing manifest a minimal valid one is generated (`[package]`
 * + `[dependencies]`); with an existing one, missing deps are appended to its `[dependencies]` /
 * `[dev-dependencies]` table (a dep already named in the file is left untouched — never clobbered).
 * Line-oriented on purpose: it adds without re-serializing, so hand-written formatting/comments
 * survive.
 */
export function mergeIntoCargoToml(existing: string | null, crateName: string, deps: PlanDependency[]): string | null {
  const cargo = deps.filter((d) => d.ecosystem === "cargo");
  if (!cargo.length) return null;

  if (!existing || !existing.trim()) {
    const runtime = cargo.filter((d) => !d.dev);
    const development = cargo.filter((d) => d.dev);
    const out = [
      "[package]",
      `name = "${safePkgName(crateName)}"`,
      `version = "0.1.0"`,
      `edition = "2021"`,
      "",
      "[dependencies]",
      ...runtime.map(cargoDepLine),
    ];
    if (development.length) out.push("", "[dev-dependencies]", ...development.map(cargoDepLine));
    return out.join("\n") + "\n";
  }

  // Append-only into the existing file: add a missing dep under its table, creating the table if needed.
  const named = new Set(
    [...existing.matchAll(/^\s*([A-Za-z0-9_-]+)\s*=/gm)].map((m) => m[1].toLowerCase()),
  );
  let out = existing.replace(/\s*$/, "\n");
  const addToTable = (header: string, table: PlanDependency[]) => {
    const missing = table.filter((d) => !named.has(d.name.toLowerCase()));
    if (!missing.length) return;
    const lines = missing.map(cargoDepLine);
    const headerRe = new RegExp(`^\\[${header.replace(/[-]/g, "\\$&")}\\]\\s*$`, "m");
    const m = headerRe.exec(out);
    if (m) {
      // Insert right after the table header.
      const insertAt = m.index + m[0].length;
      out = out.slice(0, insertAt) + "\n" + lines.join("\n") + out.slice(insertAt);
    } else {
      out = out.replace(/\n*$/, "\n") + `\n[${header}]\n` + lines.join("\n") + "\n";
    }
    missing.forEach((d) => named.add(d.name.toLowerCase()));
  };
  addToTable("dependencies", cargo.filter((d) => !d.dev));
  addToTable("dev-dependencies", cargo.filter((d) => d.dev));
  return out;
}

// Parsing + basic selectors for the dependency manifest (#1111/#1127). Pure + tolerant: it parses the
// same shape whether it arrives from plan.db or a legacy `dependencies.json`, and the selectors below
// slice the parsed list per-repo / per-ecosystem for the writers and the worker block.

import type {
  DependencyEcosystem,
  DependencyManifest,
  DependencyRegistry,
  PlanDependency,
} from "@/features/planner/issues/dependencyTypes";

function str(v: unknown): string | undefined {
  return typeof v === "string" && v.trim() ? v.trim() : undefined;
}

/**
 * Parse a stored dependency manifest (the plan.db blob, or a legacy `dependencies.json`) into the
 * full manifest (#1127). Accepts a bare JSON array of dependency
 * objects (the #1111 form, ⇒ no registries), or `{ "dependencies": [...], "registries": {...} }`.
 * Tolerant: bad JSON ⇒ empty manifest; a dependency without a name or a recognized ecosystem
 * (`npm` | `cargo`) is dropped; duplicates (same repo+ecosystem+name) are de-duped, first write
 * winning; a registry without a string `url` is dropped.
 */
export function parseDependencyManifest(raw: string): DependencyManifest {
  const empty: DependencyManifest = { dependencies: [], registries: {} };
  const t = (raw ?? "").trim();
  if (!t) return empty;
  let data: unknown;
  try { data = JSON.parse(t); } catch { return empty; }
  const obj = (data && typeof data === "object" && !Array.isArray(data)) ? data as Record<string, unknown> : null;
  const arr: unknown[] = Array.isArray(data)
    ? data
    : (obj && Array.isArray(obj.dependencies)) ? obj.dependencies as unknown[] : [];

  const dependencies: PlanDependency[] = [];
  const seen = new Set<string>();
  for (const item of arr) {
    if (!item || typeof item !== "object") continue;
    const o = item as Record<string, unknown>;
    const name = str(o.name);
    const eco = str(o.ecosystem)?.toLowerCase();
    if (!name || (eco !== "npm" && eco !== "cargo")) continue;
    const repo = str(o.repo);
    const key = `${repo ?? "*"}|${eco}|${name.toLowerCase()}`;
    if (seen.has(key)) continue;
    seen.add(key);
    dependencies.push({
      repo,
      ecosystem: eco,
      name,
      version: str(o.version),
      dev: o.dev === true,
      why: str(o.why),
      source: str(o.source),
      stream: str(o.stream),
    });
  }

  const registries: Record<string, DependencyRegistry> = {};
  const regRaw = obj && obj.registries && typeof obj.registries === "object" && !Array.isArray(obj.registries)
    ? obj.registries as Record<string, unknown> : {};
  for (const [k, v] of Object.entries(regRaw)) {
    if (!v || typeof v !== "object") continue;
    const r = v as Record<string, unknown>;
    const url = str(r.url);
    if (!url) continue;
    registries[k] = { url, scope: str(r.scope), auth: str(r.auth) };
  }
  return { dependencies, registries };
}

/** Parse just the dependency list (#1111 back-compat — the count/gate/seeding callers). */
export function parseDependenciesFile(raw: string): PlanDependency[] {
  return parseDependencyManifest(raw).dependencies;
}

/** The dependencies that apply to a given repo: those tagged with that `owner/repo`, plus the
 *  ecosystem-wide ones (no `repo`). */
export function depsForRepo(deps: PlanDependency[], fullName: string): PlanDependency[] {
  return deps.filter((d) => !d.repo || d.repo === fullName);
}

/** Split a repo's deps into npm / cargo buckets (for the manifest writers + the worker block). */
export function bucketByEcosystem(deps: PlanDependency[]): Record<DependencyEcosystem, PlanDependency[]> {
  return {
    npm: deps.filter((d) => d.ecosystem === "npm"),
    cargo: deps.filter((d) => d.ecosystem === "cargo"),
  };
}

// ── Registry config writers (#1127) ──────────────────────────────────────────────
// Generate the source/registry config so a private dependency is fetchable from the first commit.
// Only the registries a repo's deps actually reference are emitted; public-only repos get nothing.

import type {
  DependencyEcosystem,
  DependencyRegistry,
  PlanDependency,
} from "@/features/planner/issues/dependencyTypes";

/** The `//host[/path]/` key npm's `.npmrc` uses for an auth token, derived from a registry URL. */
function npmrcHostKey(url: string): string {
  return url.replace(/^https?:/i, "").replace(/\/?$/, "/");
}

/** The registry KEYs (sorted, deterministic) that a repo's deps of one ecosystem reference and that
 *  are actually defined in the registries map. */
function usedRegistries(registries: Record<string, DependencyRegistry>, deps: PlanDependency[], eco: DependencyEcosystem): string[] {
  const used = new Set(deps.filter((d) => d.ecosystem === eco && d.source && registries[d.source]).map((d) => d.source!));
  return [...used].sort();
}

/**
 * Build a repo's `.npmrc` from the registries its npm deps reference (#1127): a scoped registry as
 * `@scope:registry=<url>`, an unscoped one as the default `registry=<url>`, plus a `${SECRET}` auth
 * token line when the registry declares one. Returns null when no npm dep uses a private source.
 */
export function buildNpmrc(registries: Record<string, DependencyRegistry>, deps: PlanDependency[]): string | null {
  const keys = usedRegistries(registries, deps, "npm");
  if (!keys.length) return null;
  const lines: string[] = [];
  for (const key of keys) {
    const r = registries[key];
    lines.push(r.scope ? `${r.scope}:registry=${r.url}` : `registry=${r.url}`);
    if (r.auth) lines.push(`${npmrcHostKey(r.url)}:_authToken=\${${r.auth}}`);
  }
  return lines.join("\n") + "\n";
}

/**
 * Build a repo's `.cargo/config.toml` from the registries its cargo deps reference (#1127) — one
 * `[registries.<name>]` table with the index URL each. Returns null when no cargo dep uses a private
 * source. (Cargo reads the token from `CARGO_REGISTRIES_<NAME>_TOKEN`, kept out of the file.)
 */
export function buildCargoConfig(registries: Record<string, DependencyRegistry>, deps: PlanDependency[]): string | null {
  const keys = usedRegistries(registries, deps, "cargo");
  if (!keys.length) return null;
  const lines: string[] = [];
  for (const key of keys) lines.push(`[registries.${key}]`, `index = "${registries[key].url}"`, "");
  return lines.join("\n").replace(/\n+$/, "\n");
}

// Group locked deps by the source (registry) each is pulled from (#1127) — the Deploy pane surface.

import type {
  DependencyEcosystem,
  DependencyRegistry,
  PlanDependency,
} from "@/features/planner/issues/dependencyTypes";

/** A source (registry) the project pulls from, with the deps fetched through it (#1127 UI). The
 *  public default per ecosystem is synthesized when a dep carries no `source`. */
export interface DependencySourceGroup {
  /** Stable key — the registry key, or `"npm"` / `"cargo"` for the ecosystem default. */
  key: string;
  name: string;
  /** True when this source is a non-default (private) registry. */
  private: boolean;
  url: string;
  scope?: string;
  /** Auth-token secret name (private sources only). */
  auth?: string;
  deps: PlanDependency[];
}

const PUBLIC_SOURCE: Record<DependencyEcosystem, { name: string; url: string }> = {
  npm:   { name: "npm registry", url: "registry.npmjs.org" },
  cargo: { name: "crates.io",    url: "crates.io" },
};

/** Group locked deps BY the source each is pulled from (#1127): one group per non-default registry
 *  referenced, plus one per ecosystem-default for deps without a `source`. Sorted defaults-first
 *  then by name, so the view is deterministic. Pure. */
export function groupDependenciesBySource(
  deps: PlanDependency[],
  registries: Record<string, DependencyRegistry>,
): DependencySourceGroup[] {
  const groups = new Map<string, DependencySourceGroup>();
  for (const dep of deps) {
    const reg = dep.source ? registries[dep.source] : undefined;
    // A dep whose `source` isn't a known registry falls back to the ecosystem's public default.
    const key = reg ? dep.source! : dep.ecosystem;
    let g = groups.get(key);
    if (!g) {
      g = reg
        ? { key, name: dep.source!, private: true, url: reg.url, scope: reg.scope, auth: reg.auth, deps: [] }
        : { key, name: PUBLIC_SOURCE[dep.ecosystem].name, private: false, url: PUBLIC_SOURCE[dep.ecosystem].url, deps: [] };
      groups.set(key, g);
    }
    g.deps.push(dep);
  }
  return [...groups.values()].sort((a, b) =>
    a.private === b.private ? a.name.localeCompare(b.name) : a.private ? 1 : -1);
}

// ── Shared-dependencies view (#1429) — the Streams pane surface ───────────────────────
// When 2+ streams build the same repo, each declares its OWN deps and they're reconciled into the
// repo's single lock. The pane shows them per repo → per stream, flags version-locked overlaps, and
// omits single-owner repos (their deps stay agent-managed — no parallel collision).

import type {
  DependencyRegistry,
  PlanDependency,
} from "@/features/planner/issues/dependencyTypes";
import {
  type DependencySourceGroup,
  groupDependenciesBySource,
} from "@/features/planner/issues/dependencySources";

/** A dep in the per-stream view + the cross-stream version-lock it participates in (#1429). */
export interface StreamDependency extends PlanDependency {
  /** Other streams on the SAME repo declaring the same package — a version-lock overlap. Empty ⇒ this
   *  stream alone declares it. Derived, not stored. */
  sharedWith: string[];
}

/** One stream's declared deps within a shared repo. */
export interface StreamDepGroup {
  stream: string;
  /** True when this stream owns no build deps (e.g. a director that just holds the reconciled lock). */
  empty: boolean;
  deps: StreamDependency[];
}

/** A repo built by 2+ streams: its per-stream declared deps (with shared overlaps derived), any
 *  unattributed repo-level deps, and the registries its deps reference. */
export interface SharedRepoDeps {
  repo: string;
  /** The streams building this repo (2+, in the order given). */
  streams: string[];
  byStream: StreamDepGroup[];
  /** Deps tagged to the repo but no stream (apply to every stream on it). */
  repoLevel: StreamDependency[];
  /** The source groups (public + private registries) the repo's deps reference. */
  registries: DependencySourceGroup[];
  /** Total declared deps across the repo. */
  total: number;
}

/**
 * Build the Streams pane's Shared-dependencies view (#1429): for every repo that 2+ streams build,
 * group its deps by the declaring stream and derive the cross-stream version-lock ("shared")
 * overlaps (same ecosystem+name declared by 2+ streams). A repo with a single owning stream is
 * OMITTED — its deps stay agent-managed. A multi-stream repo with no deps yet IS included (the
 * gate-blocking empty state). `repoStreams` maps each repo → the streams building it (from the
 * fleet, director included). Pure + deterministic (repos + streams sorted by the input order /
 * name). */
export function sharedRepoDependencies(
  deps: PlanDependency[],
  registries: Record<string, DependencyRegistry>,
  repoStreams: Record<string, string[]>,
): SharedRepoDeps[] {
  const out: SharedRepoDeps[] = [];
  for (const repo of Object.keys(repoStreams).sort()) {
    const streams = repoStreams[repo];
    if (!streams || streams.length < 2) continue; // single-owner / unbuilt repos excluded
    const repoDeps = deps.filter((d) => d.repo === repo);

    // name → set of streams that declare it (for the version-lock derivation).
    const declarers = new Map<string, Set<string>>();
    for (const d of repoDeps) {
      if (!d.stream) continue;
      const k = `${d.ecosystem}|${d.name.toLowerCase()}`;
      let s = declarers.get(k);
      if (!s) { s = new Set(); declarers.set(k, s); }
      s.add(d.stream);
    }
    const sharedFor = (d: PlanDependency): string[] => {
      const all = declarers.get(`${d.ecosystem}|${d.name.toLowerCase()}`);
      return all ? [...all].filter((x) => x !== d.stream).sort() : [];
    };

    const byStreamMap = new Map<string, StreamDependency[]>(streams.map((s) => [s, []]));
    const repoLevel: StreamDependency[] = [];
    for (const d of repoDeps) {
      const sd: StreamDependency = { ...d, sharedWith: sharedFor(d) };
      if (d.stream && byStreamMap.has(d.stream)) byStreamMap.get(d.stream)!.push(sd);
      else if (d.stream) { byStreamMap.set(d.stream, [sd]); }   // a declarer not in repoStreams — keep it
      else repoLevel.push(sd);
    }
    const byStream: StreamDepGroup[] = [...byStreamMap.keys()].map((s) => {
      const sd = byStreamMap.get(s)!;
      return { stream: s, empty: sd.length === 0, deps: sd };
    });
    out.push({
      repo, streams,
      byStream,
      repoLevel,
      registries: groupDependenciesBySource(repoDeps, registries),
      total: repoDeps.length,
    });
  }
  return out;
}

/** Repos that have 2+ streams but NO locked deps yet — the gate-blocking shared repos (#1429). The
 *  Streams dependency gate requires every multi-stream repo to have ≥1 locked dep; this lists the
 *  ones still missing. Empty ⇒ the (conditional) dependency gate is satisfied. */
export function unlockedSharedRepos(
  deps: PlanDependency[],
  repoStreams: Record<string, string[]>,
): string[] {
  return Object.keys(repoStreams)
    .filter((r) => (repoStreams[r]?.length ?? 0) >= 2 && !deps.some((d) => d.repo === r))
    .sort();
}

// The dependency manifest (#1111/#1127): the authoritative, planner-owned list of the libraries every
// repo depends on, defined ONCE during planning so the fleet doesn't each add/redefine deps in
// parallel worktrees and collide at integration. The planner records it via `bsc-plan deps set` into
// plan.db (#1191 — was a raw `dependencies.json`); the poll reflects the stored manifest into the
// DEPENDENCIES section, the Dependencies gate reads its count, publish pre-populates each repo's real
// `package.json` / `Cargo.toml` from it, and each worker's CLAUDE.local.md inlines the locked set with
// a "don't touch the manifests" guardrail. This module stays a pure + tolerant manifest model (it
// parses the same shape whether it arrives from plan.db or a legacy file) — no React/Tauri.

/** The dependency-manifest section key. The stored manifest (`{ dependencies, registries }`) is
 *  DB-owned (#1191): the poll mirrors `plan_get_deps` here. Surfaced by the poll like `features.json`;
 *  not rendered as a plan section. The legacy `dependencies.json` file shares this key during the
 *  one-time import. */
export const DEPENDENCIES_KEY = "dependencies";

/** A package-manager ecosystem the manifest can target. */
export type DependencyEcosystem = "npm" | "cargo";

/** One locked dependency: which repo + ecosystem it belongs to, its name + version, and why. */
export interface PlanDependency {
  /** `owner/repo` this applies to. Absent ⇒ applies to every repo of its ecosystem. */
  repo?: string;
  /** The package manager this dependency installs through. */
  ecosystem: DependencyEcosystem;
  /** Package / crate name. */
  name: string;
  /** Version range (npm: `^1.2.0`) or version (cargo: `1.2`). Absent ⇒ `*` / latest. */
  version?: string;
  /** A development-only dependency (devDependencies / [dev-dependencies]). */
  dev?: boolean;
  /** One-line rationale — surfaced in the worker manifest so the choice is legible. */
  why?: string;
  /** The registry this is fetched from (#1127) — a KEY into the manifest's `registries` map. Absent
   *  ⇒ the ecosystem's public default (npm registry / crates.io). A non-public source generates the
   *  registry config (`.npmrc` / `.cargo/config.toml`) at publish. */
  source?: string;
  /** The fleet STREAM that declared this dep (#1429). When 2+ streams build the same repo, deps are
   *  declared per stream and reconciled into the repo's single lock; the Streams pane surfaces them
   *  per stream and flags version-locked overlaps. Absent ⇒ a repo-level (unattributed) dep. */
  stream?: string;
}

/** A non-default registry a dependency is fetched from (#1127). The `auth` token's VALUE lives in the
 *  host vault — only its secret NAME is recorded here (and as a deploy secret). */
export interface DependencyRegistry {
  /** Registry base URL (npm) / index URL (cargo). */
  url: string;
  /** npm scope this registry serves (e.g. `@acme`). Absent ⇒ the npm default registry. Ignored by cargo. */
  scope?: string;
  /** Name of the auth-token secret (value lives in the host vault; recorded as a deploy secret). */
  auth?: string;
}

/** The full dependency manifest (#1127): the locked libraries plus the non-default registries they
 *  come from, keyed by the `source` each dependency references. */
export interface DependencyManifest {
  dependencies: PlanDependency[];
  registries: Record<string, DependencyRegistry>;
}

// The worker-context dependency block (#1111): the locked set for ONE repo, inlined into its
// CLAUDE.local.md as the single authority every worker reads.

import type { PlanDependency } from "@/features/planner/issues/dependencyTypes";
import { bucketByEcosystem } from "@/features/planner/issues/dependencyParse";

/**
 * Render the locked dependency set for ONE repo as the worker-context block inlined into its
 * CLAUDE.local.md (#1111) — the single authority every worker reads, with the guardrail that the
 * manifests are planner-owned and new deps route through the director. Returns "" when the repo has
 * no locked deps (nothing to inline).
 */
export function buildWorkerDependencyBlock(deps: PlanDependency[]): string {
  if (!deps.length) return "";
  const { npm, cargo } = bucketByEcosystem(deps);
  const fmt = (d: PlanDependency) => {
    const ver = d.version ? `@${d.version}` : "";
    const dev = d.dev ? " *(dev)*" : "";
    const src = d.source ? ` *(from \`${d.source}\` registry)*` : "";
    const why = d.why ? ` — ${d.why}` : "";
    return `  - \`${d.name}${ver}\`${dev}${src}${why}`;
  };
  const hasSource = deps.some((d) => d.source);
  const lines = ["## Dependencies (locked by the planner)", ""];
  if (npm.length) lines.push("**npm** (`package.json`):", ...npm.map(fmt), "");
  if (cargo.length) lines.push("**cargo** (`Cargo.toml`):", ...cargo.map(fmt), "");
  lines.push(
    "These are already present in the repo's manifests — installing them is enough. **Do NOT add to or",
    "edit `package.json` / `Cargo.toml`** (the role gate blocks it): redefining deps in parallel",
    "worktrees is exactly what collides at integration. If you genuinely need a new dependency, request",
    "it from the director (`bsc-ask`) rather than adding it yourself.",
  );
  if (hasSource) {
    lines.push(
      "",
      "Private-registry sources are already wired in `.npmrc` / `.cargo/config.toml` (their auth tokens",
      "come from the environment) — don't reconfigure them.",
    );
  }
  return lines.join("\n");
}

// Planner deploy channel (#919/#1421) — coerce the planner's lenient/partial deploy config JSON into
// a full DeployConfig, and parse the `<deploy_config>` tag body. Pure (no React/Tauri). Split out of
// deployConfig.ts (#1639).
//
// The planner emits a lenient/partial shape, one service per repo, each carrying its own
// environments/pipeline/config/secrets/release/health; we overlay it onto seeded defaults so the gate
// can clear from the planner's output. Defensive: any missing piece falls back to a sensible default;
// the caller try/catches bad JSON and the planner re-emits.

import { repoShortName } from "@/shared/lib/core/projectPaths";
import { platform, type Workload } from "@/features/planner/lib/deployPlatforms";
import {
  PIPE_TRIGGERS, PUBLISH_REGISTRIES, PUBLISH_TRIGGERS, PORT_FORWARD_METHODS,
  type DeployEnvironment, type Pipeline, type DeployConfigBlock, type DeployConfigRow, type DeploySecretRow,
  type ReleasePolicy, type HealthPolicy, type PipeTrigger,
  type DeployMode, type LocalKind, type PublishRegistry, type PublishTrigger, type PortForward, type PortForwardMethod,
} from "@/features/planner/lib/deployEnv";
import { defaultDeployConfig, defaultService, type DeployService, type DeployConfig } from "@/features/planner/lib/deployServices";

type Raw = Record<string, unknown>;
const asArr = (v: unknown): Raw[] => Array.isArray(v) ? v.filter((x): x is Raw => !!x && typeof x === "object") : [];
const asStr = (v: unknown, d = ""): string => typeof v === "string" ? v : d;
const asBool = (v: unknown, d: boolean): boolean => typeof v === "boolean" ? v : d;

/** Coerce a service's environment ladder (accepts `environments` or `envs`). */
function coerceEnvs(o: Raw, base: DeployEnvironment[]): DeployEnvironment[] {
  const raw = asArr(o.environments).length ? asArr(o.environments) : asArr(o.envs);
  const envs = (raw.length ? raw : base).map((e, i) => {
    const name = asStr(e.name) || base[i]?.name || `env-${i + 1}`;
    return { id: asStr(e.id) || name, name, branch: asStr(e.branch, "main"), url: asStr(e.url), auto: asBool(e.auto, true) };
  });
  return envs.length ? envs : base;
}

/** Coerce a service's pipeline. */
function coercePipeline(o: Raw, base: Pipeline): Pipeline {
  const rawPipe = (o.pipeline && typeof o.pipeline === "object" ? o.pipeline : {}) as Raw;
  const rawStages = asArr(rawPipe.stages);
  return {
    provider: asStr(rawPipe.provider, base.provider),
    stages: (rawStages.length ? rawStages : base.stages).map((st, i) => {
      const trig = asStr(st.trigger) as PipeTrigger;
      return {
        id: asStr(st.id) || asStr(st.name) || `stage-${i + 1}`,
        name: asStr(st.name) || `stage-${i + 1}`,
        trigger: PIPE_TRIGGERS.includes(trig) ? trig : "push",
        gate: asBool(st.gate, false), cmd: asStr(st.cmd),
      };
    }),
  };
}

/** Coerce a service's config block. A secret may carry `envs: ["dev","prod"]` OR per-env booleans;
 *  an unspecified secret defaults to wired in every env (so the planner needn't enumerate). */
function coerceConfigBlock(o: Raw, envs: DeployEnvironment[]): DeployConfigBlock {
  const config: DeployConfigRow[] = asArr(o.config).map((r) => {
    const row: DeployConfigRow = { key: asStr(r.key) };
    for (const e of envs) row[e.id] = asStr(r[e.id]);
    return row;
  });
  const secrets: DeploySecretRow[] = asArr(o.secrets).map((r) => {
    const listed = Array.isArray(r.envs) ? new Set((r.envs as unknown[]).map((x) => String(x))) : null;
    const row: DeploySecretRow = { key: asStr(r.key) };
    for (const e of envs) {
      row[e.id] = listed ? (listed.has(e.id) || listed.has(e.name)) : (typeof r[e.id] === "boolean" ? (r[e.id] as boolean) : true);
    }
    return row;
  });
  return { config, secrets, vault: asStr((o.config as Raw)?.vault) || asStr(o.vault, "host vault") };
}

function coerceRelease(o: Raw, base: ReleasePolicy): ReleasePolicy {
  const rawRel = (o.release && typeof o.release === "object" ? o.release : {}) as Raw;
  return {
    // Preserve ANY non-empty strategy the planner authored — not just the four cloud-rollout enum
    // values (#2021). A release-artifact deploy (GitHub Pages/Releases, npm publish, packaging) has a
    // legitimate free-text strategy; the old enum-only check dropped it to "" and silently jammed the
    // deploy gate (the poll's coercion disagreed with `normalizeDeployConfig`, which the gate trusts).
    strategy: asStr(rawRel.strategy),
    autoRollback: asBool(rawRel.autoRollback, base.autoRollback),
    keep: typeof rawRel.keep === "number" ? rawRel.keep : base.keep,
    migrateWithDeploy: asBool(rawRel.migrateWithDeploy, base.migrateWithDeploy),
  };
}

function coerceHealth(o: Raw, base: HealthPolicy): HealthPolicy {
  const rawHealth = (o.health && typeof o.health === "object" ? o.health : {}) as Raw;
  return {
    probe: asStr(rawHealth.probe, base.probe), probeOn: asBool(rawHealth.probeOn, !!asStr(rawHealth.probe)),
    slo: asStr(rawHealth.slo), sloOn: asBool(rawHealth.sloOn, !!asStr(rawHealth.slo)),
    alerts: asStr(rawHealth.alerts), alertsOn: asBool(rawHealth.alertsOn, !!asStr(rawHealth.alerts)),
  };
}

/** Coerce one planner-emitted service object onto the seeded default for its repo. */
function coerceService(s: Raw, base: DeployService, idx: number): DeployService {
  const repo = asStr(s.repo, base.repo);
  const id = asStr(s.id) || (repo ? repoShortName(repo) : `service-${idx + 1}`);
  const plat = platform(asStr(s.platform));
  const wl = asStr(s.workload) as Workload;
  const workload: Workload = plat.kinds.includes(wl) ? wl : (plat.kinds[0] ?? "static");
  const reps = typeof s.replicas === "number" ? String(s.replicas) : asStr(s.replicas);
  const mode: DeployMode = asStr(s.mode) === "local" ? "local" : "cloud";
  const rawKind = asStr(s.localKind);
  const localKind: LocalKind | undefined = rawKind === "library" || rawKind === "application" ? rawKind : (mode === "local" ? "application" : undefined);
  const rawReg = asStr(s.publishRegistry);
  const publishRegistry = (PUBLISH_REGISTRIES as readonly string[]).includes(rawReg) ? (rawReg as PublishRegistry) : undefined;
  const rawTrig = asStr(s.publishTrigger);
  const publishTrigger = (PUBLISH_TRIGGERS as readonly string[]).includes(rawTrig) ? (rawTrig as PublishTrigger) : undefined;
  const pf = (s.portForward && typeof s.portForward === "object" ? s.portForward : null) as Raw | null;
  const rawMethod = pf ? asStr(pf.method) : "";
  const portForward: PortForward | undefined = pf
    ? { enabled: asBool(pf.enabled, false), port: asStr(pf.port), method: (PORT_FORWARD_METHODS as readonly string[]).includes(rawMethod) ? (rawMethod as PortForwardMethod) : "cloudflared" }
    : undefined;
  const envs = coerceEnvs(s, base.envs);
  return {
    id, repo, path: asStr(s.path, "."), stack: asStr(s.stack, "—"),
    platform: asStr(s.platform), workload, proposed: false,
    region: asStr(s.region, "—"), build: asStr(s.build, "—"),
    output: asStr(s.output, "dist"), runtime: asStr(s.runtime, "—"),
    host: asStr(s.host) || base.host || "github",
    registry: asStr(s.registry) || undefined,
    orchestrator: asStr(s.orchestrator) || undefined,
    replicas: reps || undefined,
    mode,
    localKind: mode === "local" ? localKind : (localKind || undefined),
    publishRegistry,
    packageName: asStr(s.packageName) || undefined,
    publishTrigger,
    buildTargets: asStr(s.buildTargets) || undefined,
    artifact: asStr(s.artifact) || undefined,
    runCmd: asStr(s.runCmd) || undefined,
    portForward,
    envs,
    pipeline: coercePipeline(s, base.pipeline),
    config: coerceConfigBlock(s, envs),
    release: coerceRelease(s, base.release),
    health: coerceHealth(s, base.health),
  };
}

export function coerceDeployConfig(raw: unknown, repos: string[] = []): DeployConfig {
  const o = (raw && typeof raw === "object" ? raw : {}) as Raw;
  const base = defaultDeployConfig(repos);
  const rawServices = asArr(o.services);
  // A config saved before the per-repo rework (#1421) carries environments/pipeline/config/secrets/
  // release/health at the TOP LEVEL, shared across services; the per-repo model wants them ON each
  // service. Fold the top-level set into a service that lacks its own, so a migrated legacy config
  // stays deploy-ready (its `release.strategy` etc. reach each service) instead of resetting to empty
  // defaults and silently blocking the gate (#1438). A service's own fields always win.
  const legacyTop: Raw = {
    environments: o.environments ?? o.envs, pipeline: o.pipeline,
    config: o.config, secrets: o.secrets, release: o.release, health: o.health,
  };
  const services: DeployService[] = (rawServices.length ? rawServices : base.services as unknown as Raw[]).map((s, i) =>
    coerceService({ ...legacyTop, ...(s as Raw) }, base.services[i] ?? defaultService(asStr((s as Raw).repo)), i),
  );
  return { services };
}

/** Parse the body of a `<deploy_config>` tag into a DeployConfig. Forgiving on two fronts (#919):
 *  (1) stray prose/tags around the JSON (e.g. a leaked `</parameter>`) — we extract the outermost
 *  `{ … }` object; (2) the planner CLI's terminal line-WRAPS the big JSON block, injecting raw
 *  newlines + indent that can land INSIDE string values (invalid JSON). When a clean parse fails we
 *  collapse newline-spanning whitespace to a single space and retry, which repairs the wraps
 *  (`"fly  \n  app"` → `"fly app"`). Returns null only if neither parse works. */
export function parseDeployConfigTag(body: string, repos: string[] = []): DeployConfig | null {
  const json = body.match(/\{[\s\S]*\}/)?.[0];
  if (!json) return null;
  const tryParse = (s: string): unknown => { try { return JSON.parse(s); } catch { return undefined; } };
  // Raw newlines are only ever wrap artifacts inside a JSON string (real string newlines are escaped
  // `\n`), so collapsing them is safe; between tokens it's just whitespace JSON ignores anyway.
  const parsed = tryParse(json) ?? tryParse(json.replace(/[ \t]*[\r\n]+[ \t]*/g, " "));
  if (parsed === undefined || parsed === null) return null;
  try {
    return coerceDeployConfig(parsed, repos);
  } catch {
    return null;
  }
}

// Deployment & infrastructure config (#919; per-repo rework #1421) — the data model behind the
// planner's Deployment stage (right after Repos). Pure (no React/Tauri) so the readiness checks that
// drive the stage gate are unit-testable.
//
// Split into focused modules (#1639); this barrel re-exports the full public surface so importers
// don't churn:
//   - deployPlatforms.ts — the deploy-target catalog (platforms, workloads, git hosts, orchestrators)
//   - deployEnv.ts       — per-service building blocks (envs, pipeline, config/secrets, release,
//                          health, local-mode option lists) + the default builders
//   - deployServices.ts  — the DeployService/DeployConfig model + readiness checks + gate + issues
//   - deployCoerce.ts    — the planner channel (coerceDeployConfig + parseDeployConfigTag)

export * from "@/features/planner/lib/deployPlatforms";
export * from "@/features/planner/lib/deployEnv";
export * from "@/features/planner/lib/deployServices";
export * from "@/features/planner/lib/deployCoerce";

// Per-service deploy building blocks (#919; per-repo rework #1421; local mode #1192) — the
// environment ladder, CI/CD pipeline, config/secrets block, release policy, and health policy that
// each DeployService owns, plus the ship-mode option lists and the sensible default a fresh service
// starts from.
//
// The DATA (option lists + defaults) is externalized to `@data/deploy/taxonomy.json` (#2027 P1) —
// the single source, editable without touching code and part of the exportable app-config bundle.
// This module keeps only the TYPES + the accessor/const names + the default BUILDERS (which return a
// fresh deep copy of the JSON default each call, since callers mutate them). Pure (no React/Tauri).

import taxonomyEmbedded from "@data/deploy/taxonomy.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

// The config-dir copy (#2047) overlays the embedded default — editable without a rebuild.
const taxonomy = overlayFile("deploy/taxonomy.json", taxonomyEmbedded);

/** How a service ships (#1192). `cloud` = a hosted platform; `local` = a published library or a
 *  build-and-run-here application (CLI / desktop / local server). A monorepo can mix the two. */
export type DeployMode = "cloud" | "local";
/** A local service is either a published library or a built application (#1192). */
export type LocalKind = "library" | "application";

/** Package registries a local LIBRARY can publish to (#1192). */
export type PublishRegistry = "npm" | "crates.io" | "PyPI" | "internal";
export const PUBLISH_REGISTRIES = taxonomy.publishRegistries as readonly PublishRegistry[];
/** When a library's publish workflow fires (#1192). */
export type PublishTrigger = "on-tag" | "manual";
export const PUBLISH_TRIGGERS = taxonomy.publishTriggers as readonly PublishTrigger[];

/** How a locally-running deployment is exposed remotely (#1192). `cloudflared` is the default —
 *  we already run a Cloudflare relay for the mobile tunnel. */
export type PortForwardMethod = "cloudflared" | "ngrok" | "tailscale" | "LAN";
export const PORT_FORWARD_METHODS = taxonomy.portForwardMethods as readonly PortForwardMethod[];

/** Optional remote exposure for a local Application / server (#1192). */
export interface PortForward {
  enabled: boolean;
  /** Port to expose (string so the field stays free-form, e.g. "8080"). */
  port: string;
  method: PortForwardMethod;
}

export interface DeployEnvironment {
  id: string;
  name: string;
  branch: string;
  url: string;
  /** Auto-deploy on push to `branch` (vs manual promotion). */
  auto: boolean;
  proposed?: boolean;
}

export type PipeTrigger = "push" | "tag" | "on-green" | "manual";
export const PIPE_TRIGGERS = taxonomy.pipeTriggers as PipeTrigger[];

export interface PipelineStage {
  id: string;
  name: string;
  trigger: PipeTrigger;
  /** Blocks promotion until green. */
  gate: boolean;
  cmd: string;
}
export interface Pipeline {
  provider: string;
  stages: PipelineStage[];
}

export interface DeployConfigRow { key: string; [env: string]: string }
export interface DeploySecretRow { key: string; [env: string]: boolean | string }
export interface DeployConfigBlock {
  config: DeployConfigRow[];
  /** Secrets are tracked by NAME + per-env "wired" flag — values never live here. */
  secrets: DeploySecretRow[];
  vault: string;
}

export type ReleaseStrategy = "recreate" | "rolling" | "blue-green" | "canary";
export const RELEASE_STRATEGIES = taxonomy.releaseStrategies as { id: ReleaseStrategy; label: string; desc: string }[];
export interface ReleasePolicy {
  /** The rollout/release strategy. {@link RELEASE_STRATEGIES} are the KNOWN cloud-rollout options the
   *  picker offers, but the field accepts ANY non-empty string — a release-artifact deploy (GitHub
   *  Pages/Releases, npm publish, packaging) legitimately carries a free-text strategy like
   *  `github-release (tag on main → …)` that isn't one of the four. `""` = unset. */
  strategy: string;
  autoRollback: boolean;
  keep: number;
  migrateWithDeploy: boolean;
}

export interface HealthPolicy {
  probe: string; probeOn: boolean;
  slo: string; sloOn: boolean;
  alerts: string; alertsOn: boolean;
}

// The sensible defaults a fresh service's deploy plan starts from (from `@data/deploy/taxonomy.json`).
// Each builder returns a fresh DEEP COPY so callers can mutate their service's config independently.
// `<T,>` not `<T>` — the trailing comma is load-bearing. The runtime loader compiles every record with
// esbuild's TSX loader, where a single-type-param generic arrow reads as an unclosed JSX element, so
// `<T>` made this module the one thing standing between deployCoerce/deployConfig/deployServices and
// their records. The comma is valid in both dialects and changes nothing at runtime.
const clone = <T,>(v: T): T => structuredClone(v);

/** A sensible default environment ladder a repo's deploy plan starts from. */
export function defaultEnvs(): DeployEnvironment[] {
  return clone(taxonomy.defaults.envs) as DeployEnvironment[];
}
/** A sensible default pipeline a repo's deploy plan starts from. */
export function defaultPipeline(): Pipeline {
  return clone(taxonomy.defaults.pipeline) as Pipeline;
}
export function defaultRelease(): ReleasePolicy {
  return clone(taxonomy.defaults.release) as ReleasePolicy;
}
export function defaultHealth(): HealthPolicy {
  return clone(taxonomy.defaults.health) as HealthPolicy;
}

// Deploy target catalog (#919; per-repo rework #1421) — the platforms a service can ship to, the
// workload kinds, the git hosts a repo can live on, and the container orchestration options.
//
// The DATA is externalized to `@data/deploy/taxonomy.json` (#2027 P1) — the single source, editable
// without touching code and part of the exportable app-config bundle. This module keeps only the
// TYPES + accessor helpers over that data (no React/Tauri, so it stays unit-testable).

import taxonomyEmbedded from "@data/deploy/taxonomy.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

// The config-dir copy (#2047) overlays the embedded default — editable without a rebuild.
const taxonomy = overlayFile("deploy/taxonomy.json", taxonomyEmbedded);

/** Workload kind a service deploys as. */
export type Workload = "static" | "serverless" | "container" | "service";

export interface DeployPlatform {
  id: string;
  name: string;
  /** Workload kinds this platform supports. */
  kinds: Workload[];
  /** oklch hue for the platform tile glyph. */
  h: number;
  glyph: string;
}

/** Platform catalog — the deploy targets a service can pick (from `@data/deploy/taxonomy.json`). */
export const PLATFORMS: DeployPlatform[] = taxonomy.platforms as DeployPlatform[];

export function platform(id: string): DeployPlatform {
  return PLATFORMS.find((p) => p.id === id) ?? { id, name: id, h: 250, glyph: "■", kinds: [] };
}

export const WORKLOAD: Record<Workload, { label: string; c: string }> =
  taxonomy.workloads as Record<Workload, { label: string; c: string }>;

/** A git host a project's repos can live on — a project may span clouds or a self-hosted server. */
export interface GitHost { key: string; domain: string; label: string; kind: "cloud" | "self-hosted"; color: string }
export const HOSTS: Record<string, GitHost> = taxonomy.gitHosts as Record<string, GitHost>;
export function hostMeta(id: string | undefined): GitHost {
  return HOSTS[id ?? "github"] ?? HOSTS.github;
}

/** Orchestrators a distributed (container) workload can run under. */
export const ORCHESTRATORS: { id: string; label: string }[] = taxonomy.orchestrators;
/** Replica-count options for a container workload (string so "auto" fits the same control). */
export const REPLICA_OPTIONS: readonly string[] = taxonomy.replicaOptions;

// The deployable-unit model (#919; per-repo rework #1421; local mode #1192) — one DeployService per
// linked repo, the project-wide DeployConfig that aggregates them, the readiness checks that drive
// the stage gate, the default/normalize seeders, and the `stream:deploy` issue preview. Pure (no
// React/Tauri) so the gate logic is unit-testable. Split out of deployConfig.ts (#1639).
//
// One DeployConfig per project (store slice `planDeployConfig`) holding ONE DeployService per linked
// repo. Each service is a fully self-contained deployable unit — it owns its OWN environments,
// pipeline, config/secrets, release, and health. The `deploymentDefined` gate signal is
// `services.length > 0 && services.every(serviceReady)`; the pane shows "N of M repos deploy-ready".

import { repoShortName } from "@/shared/lib/core/projectPaths";
import type { ReadinessCheck } from "@/features/planner/lib/readiness";
import { platform, WORKLOAD, type Workload } from "@/features/planner/lib/deployPlatforms";
import {
  defaultEnvs, defaultPipeline, defaultRelease, defaultHealth,
  type DeployEnvironment, type Pipeline, type DeployConfigBlock,
  type ReleasePolicy, type HealthPolicy,
  type DeployMode, type LocalKind, type PublishRegistry, type PublishTrigger, type PortForward,
} from "@/features/planner/lib/deployEnv";

/** A deployable unit — one per linked repo (or sub-path). Each owns its OWN environments, pipeline,
 *  config/secrets, release, and health (#1421): every repo is a self-contained deployable unit. */
export interface DeployService {
  id: string;
  repo: string;
  path: string;
  stack: string;
  platform: string;
  workload: Workload;
  /** True until the user accepts/edits the planner's proposed target. */
  proposed: boolean;
  region: string;
  build: string;
  output: string;
  runtime: string;
  /** Git host the repo lives on (key into {@link HOSTS}) — display only; defaults to github. */
  host?: string;
  /** Container image registry for a container workload. Absent ⇒ derived `ghcr.io/<repo>`. */
  registry?: string;
  /** Orchestrator id for a distributed container workload (see {@link ORCHESTRATORS}). */
  orchestrator?: string;
  /** Replica count for a container workload — a {@link REPLICA_OPTIONS} value ("auto" allowed). */
  replicas?: string;
  // ── Local mode (#1192) — a library or a build-and-run-here app. Absent `mode` ⇒ "cloud". ──
  /** Whether the service ships to a cloud platform or as a local artifact. Defaults to "cloud". */
  mode?: DeployMode;
  /** For a local service: library (published) vs application (built + run). */
  localKind?: LocalKind;
  /** Library: the registry it publishes to. */
  publishRegistry?: PublishRegistry;
  /** Library: the published package name. */
  packageName?: string;
  /** Library: when the publish workflow fires. */
  publishTrigger?: PublishTrigger;
  /** Application: target platform(s) to build for (OS/arch or "desktop installer"). */
  buildTargets?: string;
  /** Application: the produced artifact (e.g. a binary or installer name). */
  artifact?: string;
  /** Application: how to run the built artifact. */
  runCmd?: string;
  /** Optional remote exposure for a locally-running application. */
  portForward?: PortForward;
  // ── Per-repo deploy plan (#1421) — every repo carries its own full ship config. ──
  envs: DeployEnvironment[];
  pipeline: Pipeline;
  config: DeployConfigBlock;
  release: ReleasePolicy;
  health: HealthPolicy;
}

/** Default mode for a service whose `mode` is unset (legacy configs) — cloud. */
export function serviceMode(s: DeployService): DeployMode {
  return s.mode ?? "cloud";
}

/** A local service's `target` check passes once its mode-appropriate fields are set: a library needs
 *  a publish registry + package name; an application needs build targets + an artifact (#1192). */
export function localTargetDefined(s: DeployService): boolean {
  if (s.localKind === "library") return !!s.publishRegistry && !!(s.packageName && s.packageName.trim());
  if (s.localKind === "application") return !!(s.buildTargets && s.buildTargets.trim()) && !!(s.artifact && s.artifact.trim());
  return false;
}

/** A service has a defined deploy target — a cloud platform, or its local fields (#1192). */
export function serviceTargetDefined(s: DeployService): boolean {
  return serviceMode(s) === "local" ? localTargetDefined(s) : !!s.platform;
}

export interface DeployConfig {
  services: DeployService[];
}

/** Seed one proposed service (deployable unit) for a repo, with its own env ladder / pipeline /
 *  config / release / health the planner can refine. */
export function defaultService(repo: string): DeployService {
  const short = repo ? repoShortName(repo) : "app";
  return {
    id: short, repo, path: ".", stack: "—",
    platform: "", workload: "static", proposed: true,
    region: "—", build: "—", output: "dist", runtime: "—", host: "github",
    mode: "cloud",
    envs: defaultEnvs(),
    pipeline: defaultPipeline(),
    config: { config: [], secrets: [], vault: "host vault" },
    release: defaultRelease(),
    health: defaultHealth(),
  };
}

/** Seed a config for a project from its linked repos — one proposed service per repo. */
export function defaultDeployConfig(repos: string[]): DeployConfig {
  return { services: (repos.length ? repos : [""]).map(defaultService) };
}

/** Backfill a possibly-OLD-shape config (#1421/#1425 migration). Pre-rework configs kept `envs` /
 *  `pipeline` / `config` / `release` / `health` at the TOP level (shared across services); the
 *  per-repo rework moved them ONTO each service. A persisted old config therefore has services with
 *  none of those fields, and the per-service readers (`serviceChecks` → `s.config.secrets`) crash on
 *  it. Ensure every service owns its sub-configs — from the service, else the legacy top-level, else
 *  the defaults — and drop the `undefined`/empty case to a fresh config. Self-heals on the next save. */
export function normalizeDeployConfig(d: DeployConfig | undefined, repos: string[] = []): DeployConfig {
  if (!d || !Array.isArray(d.services) || d.services.length === 0) return defaultDeployConfig(repos);
  const legacy = d as Partial<{ envs: DeployEnvironment[]; pipeline: Pipeline; config: DeployConfigBlock; release: ReleasePolicy; health: HealthPolicy }>;
  return {
    services: d.services.map((s) => ({
      ...s,
      envs: Array.isArray(s.envs) ? s.envs : (legacy.envs ?? defaultEnvs()),
      pipeline: s.pipeline?.stages ? s.pipeline : (legacy.pipeline ?? defaultPipeline()),
      config: s.config?.secrets ? s.config : (legacy.config ?? { config: [], secrets: [], vault: "host vault" }),
      release: s.release && s.release.strategy !== undefined ? s.release : (legacy.release ?? defaultRelease()),
      health: s.health ?? legacy.health ?? defaultHealth(),
    })),
  };
}

/** The pipeline's final stage label adapts to a service's mode (#1192): cloud ships (`deploy`), a
 *  library publishes (`publish`), a local app packages (`package`). The gating `test` stays put. */
export function finalStageName(s: DeployService | undefined): "deploy" | "publish" | "package" {
  if (s && serviceMode(s) === "local") return s.localKind === "library" ? "publish" : "package";
  return "deploy";
}

/** The readiness checks for ONE service (repo) — every one `ok` ⇒ this repo is deploy-ready. Checks
 *  are MODE-AWARE (#2023): GitHub (Actions/environments/secrets) is a mandatory baseline, so BOTH
 *  modes gate on target + CI/CD pipeline + environments + config-secrets. Only the cloud
 *  instance-replacement **release/rollout** strategy (recreate/rolling/blue-green/canary) is
 *  cloud-only — a local build (library publish / application package) has no rollout, so that check
 *  is omitted for local mode (its shipping is the pipeline's publish/package stage instead). */
export function serviceChecks(s: DeployService): ReadinessCheck[] {
  const prodSecrets = s.config.secrets.length === 0 || s.config.secrets.every((row) => !!row.prod);
  const checks: ReadinessCheck[] = [
    { id: "target",   label: "Deploy target set",          ok: serviceTargetDefined(s),     detail: serviceMode(s) === "local" ? (s.localKind ?? "local") : (platform(s.platform).name || "—") },
    { id: "envs",     label: "Environment ladder defined", ok: s.envs.length >= 2,           detail: `${s.envs.length} environments` },
    { id: "pipeline", label: "CI/CD pipeline staged",      ok: s.pipeline.stages.length >= 2, detail: s.pipeline.provider },
    { id: "secrets",  label: "Secrets wired for every env", ok: prodSecrets,                 detail: prodSecrets ? "all set" : "missing prod" },
  ];
  if (serviceMode(s) === "cloud") {
    checks.push({ id: "release", label: "Release & rollback strategy", ok: !!s.release.strategy, detail: s.release.strategy || "—" });
  }
  return checks;
}

/** Whether a single repo's deploy plan is complete (all its checks pass). */
export function serviceReady(s: DeployService): boolean {
  return serviceChecks(s).every((c) => c.ok);
}

/** How many of the project's repos are fully deploy-ready (drives "N of M repos deploy-ready"). */
export function readyServiceCount(d: DeployConfig | undefined): number {
  return d ? d.services.filter(serviceReady).length : 0;
}

/** The `deploymentDefined` gate signal: at least one repo, and EVERY repo's deploy plan complete. */
export function deploymentDefined(d: DeployConfig | undefined): boolean {
  return !!d && d.services.length > 0 && d.services.every(serviceReady);
}

/** A deployment task this config will generate as a `stream:deploy` issue at publish. */
export interface DeployIssue { text: string; tag: string; blocking: boolean }

/** Preview the `stream:deploy` issues ONE service generates at publish — its deploy/publish/package
 *  workflow, non-prod env provisioning, prod secret wiring (blocking while unset), and (for anything
 *  that RUNS) a prod health check. */
export function serviceIssues(s: DeployService): DeployIssue[] {
  const out: DeployIssue[] = [];
  if (!serviceTargetDefined(s)) return out;
  if (serviceMode(s) === "local") {
    out.push(s.localKind === "library"
      ? { text: `Add ${s.publishRegistry ?? "registry"} publish workflow for ${s.id} (${s.packageName || s.id})`, tag: "all", blocking: false }
      : { text: `Add package + build workflow for ${s.id} → ${s.buildTargets || "local artifact"}`, tag: "all", blocking: false });
  } else {
    out.push({ text: `Add ${platform(s.platform).name} deploy workflow for ${s.id} → ${WORKLOAD[s.workload].label}`, tag: "all", blocking: false });
  }
  for (const e of s.envs.filter((e) => e.id !== "prod" && e.name !== "prod" && e.id !== "dev" && e.name !== "dev")) {
    out.push({ text: `Provision ${s.id} ${e.name} environment + secrets`, tag: e.name, blocking: false });
  }
  const unwired = s.config.secrets.filter((row) => !row.prod);
  if (unwired.length) {
    out.push({ text: `Wire ${s.id} prod secrets (${unwired.map((r) => r.key).join(", ")})`, tag: "prod", blocking: true });
  }
  if (!(serviceMode(s) === "local" && s.localKind === "library")) {
    out.push({ text: `Add ${s.id} prod health check + auto-rollback`, tag: "prod", blocking: false });
  }
  return out;
}

/** Preview every `stream:deploy` issue this project's deploy plan generates — across all repos. */
export function deployIssues(d: DeployConfig): DeployIssue[] {
  return d.services.flatMap(serviceIssues);
}

// The design-generator bridge (#2658, epic #2606) — the frontend calls the SAME deterministic palette
// generator (`bsc ui generate`, crates/bsc-ui, #2636) the designer + agents use, over the generic `bsc`
// bridge. When a downloaded blueprint's reconcile (#2646) leaves categories the contract doesn't define,
// this fills each with a coherent colour so the shared blueprint brings its look with NO holes.
//
// ⭐ FALL LOUDLY (a maintainer VALUE): the generator is the no-holes guarantee, so an UNREACHABLE
// generator must NOT silently degrade to a hole — this THROWS, and the confirm-list surfaces the failure
// (an error banner) instead of registering a partial/empty contribution. Silent failure is the enemy.
import { bsc } from "@/shared/lib/core/bsc";
import DESCRIPTOR from "@data/ui/style-descriptor.json";
import { hueOfColor } from "@/features/designs/lib/colorHue";

interface DomainDescriptor {
  domain?: { group: string; tokens?: { value?: string }[] }[];
}

/** The hues the contract's existing graph-category colours ACTUALLY occupy — parsed from their real
 *  values in the style descriptor (#2663), not reconstructed from an assumed even-spacing layout the
 *  contract never used (the built-ins are hand-authored hex at unrelated OKLCH hues). Feeding these real
 *  hues as the generator's "already used" set is what keeps a new category visually distinct from the
 *  built-ins. Computed once; a value that doesn't parse is skipped. */
const KNOWN_CATEGORY_HUES: number[] = (() => {
  const d = DESCRIPTOR as DomainDescriptor;
  const group = (d.domain ?? []).find((g) => g.group === "graph-category");
  return (group?.tokens ?? [])
    .map((t) => (t.value ? hueOfColor(t.value) : null))
    .filter((h): h is number => h != null);
})();

/**
 * Generate a distinct colour for each `missing` category via the deterministic generator (#2636),
 * placing each new hue in the LARGEST circular gap among the hues already in use — the "no-holes"
 * primitive (`bsc ui generate next`) — seeded with the contract's existing category hues so new
 * categories don't collide with the built-ins, and with each freshly-placed hue so they don't collide
 * with each other. Returns `{ category → colour }` in `missing` order.
 *
 * @throws if the generator is unreachable or returns an unexpected shape — falls LOUDLY so the caller
 *   surfaces it rather than shipping a silent hole.
 */
export async function generateCategoryColors(missing: string[]): Promise<Record<string, string>> {
  const used = [...KNOWN_CATEGORY_HUES];
  const out: Record<string, string> = {};
  for (const cat of missing) {
    const raw = (await bsc(null, ["ui", "generate", "next", "--existing", used.join(",")])).trim();
    const parsed = JSON.parse(raw) as { hue?: number; color?: string };
    if (typeof parsed.hue !== "number" || typeof parsed.color !== "string" || !parsed.color) {
      throw new Error(`generator returned an unexpected shape for “${cat}”: ${raw.slice(0, 120)}`);
    }
    used.push(parsed.hue);
    out[cat] = parsed.color;
  }
  return out;
}

// The designer-loop pump's PURE decision core (#3292, epic #3260) — the "driver brain" that keeps the live
// Design Studio session iterating on a `bsc loop`. React-free + side-effect-free so it's unit-testable in
// isolation; the hook (`useDesignerLoopPump`) gathers the live loop state, calls this, and actuates.
//
// THE PROGRESS SIGNAL IS THE LOOP'S OWN TURN ORDER. The loop is `driver` (a, speaks first) ↔ `designer` (b).
// When it is the DRIVER's turn, the designer just finished (it recorded its last change), so the pump posts
// the driver's "continue" turn and injects the next-change prompt into the designer PTY. When it is the
// DESIGNER's turn, the designer is still working — the pump WAITS (it never floods). So the turn-flip the
// designer causes by recording `bsc loop say --as designer …` is exactly the "prompt me again" signal — no
// PTY idle-status parsing needed. A stall (the designer never records) is caught by a nudge timeout.
import type { DesignDirective } from "@/features/designs/lib/designerQueue";

/** The `driver`/`designer` participant names — the pump owns the driver side, the live session is designer. */
export const DRIVER = "driver";
export const DESIGNER = "designer";

/** Re-prompt the designer if it has neither recorded nor acted this long after the last inject (a stall). */
export const DEFAULT_NUDGE_MS = 90_000;

/** The subset of a `bsc loop` row the pump reads (from `bsc loop list --json`). */
export interface LoopRow {
  id: number;
  a: string;
  b: string;
  status: string; // "open" | "closed"
}

/** The subset of a turn the pump reads (from `bsc loop show --json`). */
export interface LoopTurn {
  participant: string;
}

/** What the pump should do this tick. */
/** The one OPEN loop between `a` and `b`, or `null`. Defaults to the `driver ↔ designer` pair — the UI
 *  loop this feature drives — but takes the pairing explicitly (#3850) so a DIFFERENT loop shape can
 *  coexist: #3263's tooling loop is `designer ↔ external`, and a hard-coded pair would have made the two
 *  mutually exclusive rather than concurrent. */
export function pickDesignerLoop(
  loops: readonly LoopRow[],
  a: string = DRIVER,
  b: string = DESIGNER,
): LoopRow | null {
  return loops.find((l) => l.status === "open" && l.a === a && l.b === b) ?? null;
}

/** Whose turn it is next — `a` first, strict alternation (mirrors the store's `next_speaker`). */
export function whoseTurn(a: string, b: string, turns: readonly LoopTurn[]): string {
  const last = turns.length ? turns[turns.length - 1].participant : null;
  return last === a ? b : a;
}

/** The stall nudge — the designer hasn't recorded; prod it to record or make the next change. Single line. */
export function nudgePrompt(id: number): string {
  return (
    `Design loop #${id}: record your last change now — ` +
    `\`bsc loop say --as designer ${id} --shot <path> "<summary>"\` — or make the next change.`
  );
}

// ── The loop decider (#3311/#3850). A designer session is either running a LOOP or in normal chat —
// there is no third "interactive loop" mode (the `decideLoopPumpAction` that used to sit above was a
// vestige, and it contradicted the launch contract, which already said the pump drives "ONLY while an
// open loop exists — so an interactive studio session stops and hands back"). So this is THE decider: each
// driver turn dispatches a specific DIRECTIVE from the auto-queue (buildDesignerQueue), grounds it with a
// shot, and is BUDGET-bounded — stopping on a turn ceiling OR when the queue drains (a GOOD end: nothing
// left to improve). ─────────────────────────────────────────────────────────────────────────────────────

/** Default overnight budget — "a while", not forever. The reachable Stop pill (#3294) can end it sooner. */
export const DEFAULT_MAX_TURNS = 40;

/** What the overnight pump should do this tick. */
export type OvernightAction =
  | { kind: "direct"; directive: DesignDirective; prompt: string; burst: boolean } // driver's turn: dispatch
  | { kind: "nudge"; prompt: string } //   the designer stalled — re-inject
  | { kind: "wait" } //                    the designer is working — hold
  | { kind: "stop"; reason: string } //    budget reached OR the queue drained (a good end)
  | { kind: "idle" }; //                   no open designer loop

/** The inputs an overnight tick decides over. */
export interface OvernightInput {
  loop: LoopRow | null;
  turns: readonly LoopTurn[];
  now: number;
  lastInjectAt: number;
  nudgeAfterMs: number;
  /** The ranked directive queue (from `buildDesignerQueue`). */
  queue: readonly DesignDirective[];
  /** Directives dispatched so far this run — the queue cursor AND the turn count. */
  cursor: number;
  /** The turn ceiling — stop once `cursor` reaches it. */
  maxTurns: number;
}

/** Decide the loop pump's action for this tick. Pure. The driver's turn dispatches the next queued
 *  directive — or stops (budget reached / queue drained). */
export function decideOvernightAction(inp: OvernightInput): OvernightAction {
  const { loop, turns, now, lastInjectAt, nudgeAfterMs, queue, cursor, maxTurns } = inp;
  if (!loop || loop.status !== "open") return { kind: "idle" };
  if (whoseTurn(loop.a, loop.b, turns) === DRIVER) {
    if (cursor >= maxTurns) return { kind: "stop", reason: `budget reached — ${maxTurns} changes made` };
    if (cursor >= queue.length) {
      return { kind: "stop", reason: `queue drained — ${queue.length} directive(s) done, nothing left to improve` };
    }
    const directive = queue[cursor];
    return { kind: "direct", directive, prompt: directivePrompt(loop.id, directive), burst: directive.kind === "motion" };
  }
  // The designer's turn — working. Re-prompt only on a clear stall past the last inject.
  if (now - lastInjectAt > nudgeAfterMs) return { kind: "nudge", prompt: nudgePrompt(loop.id) };
  return { kind: "wait" };
}

/** The directive prompt injected into the designer PTY. SINGLE LINE (injectPrompt submits on CR). A motion
 *  directive grounds with a --frames burst; everything else with a single component-preview shot (#3308). */
export function directivePrompt(id: number, d: DesignDirective): string {
  const shot = d.kind === "motion" ? "`bsc shot preview --frames 6`" : "`bsc shot preview`";
  return (
    `Design loop #${id} — ${d.title}: ${d.detail} Make the change via \`bsc ui\`, capture it with ${shot}, ` +
    `then record it — \`bsc loop say --as designer ${id} --shot <path> "<what you changed>"\` — and stop; ` +
    `you'll get the next directive. The shot is the ground truth, not your description.`
  );
}

/** The driver's own turn summary — what the pump posts (`bsc loop say --as driver … --shot <current>`)
 *  alongside the current-state shot, so the loop log reads as a grounded change history. */
export function driverSay(d: DesignDirective): string {
  return `[${d.kind}] ${d.title}`;
}

// The overnight designer loop's AUTO-QUEUE (#3311, epic #3260) — the pure "what to work on next" core.
// React-free + side-effect-free so it's unit-testable: the pump (a later slice) runs `bsc ui …
// --coverage`/`bsc ui resolve` and feeds the parsed reports here; this ranks the design system's own
// HONEST gaps into an ordered directive list the driver dispatches one-per-turn.
//
// GROUND-TRUTH FIRST. Objective findings (measured coverage gaps + real-pixel shots) rank ahead of
// open-ended polish, so the loop fixes what's demonstrably wrong before it starts "improving" on taste —
// the guard against a signal-less loop that agrees with anything (#3262). When the objective findings
// drain, the loop stops (a GOOD outcome: "nothing left to fix") unless motion/polish keep it going.

/** A single piece of direction the driver hands the designer. */
export type DirectiveKind =
  | "leak" //          a hardcoded color a token change can't reach (highest: demonstrably ungoverned)
  | "uncontracted" //  a consumed token the contract doesn't define (structural gap)
  | "theme-miss" //    a consumed token left at its contract default under the active theme
  | "low-coverage" //  a component consuming fewer tokens than it could (won't retint fully)
  | "dead-token" //    a contract token no component consumes (use or retire)
  | "motion" //        review/refine a component's animation (grounded by a --frames burst)
  | "polish"; //       a rotating high-level directive that sustains the run once findings drain

export interface DesignDirective {
  /** Stable-ish id (so a pump can dedup / log across rebuilds). */
  id: string;
  kind: DirectiveKind;
  /** Short human title (the driver's `bsc loop say` summary). */
  title: string;
  /** The specific instruction, grounded in the finding — what to change and why. */
  detail: string;
  /** The token / component / file the directive concerns (absent for a generic polish directive). */
  target?: string;
}

/** The `bsc ui components --coverage --json` fields the queue reads. */
export interface CoverageReport {
  /** Hardcoded colors a token change can't reach, per file (`{file, count}`). */
  leakCandidates: { file: string; count: number }[];
  /** Contract tokens NO component consumes. */
  zeroConsumers: string[];
  /** Per-component token consumption. */
  components: { component: string; tokensConsumed: number; tokensTotal: number }[];
}

/** The `bsc ui resolve --json` fields the queue reads. */
export interface ResolveReport {
  theme?: string;
  /** Consumed tokens the theme leaves at their contract default (the fall-loudly gap). */
  themeMisses: string[];
  /** Consumed tokens the contract does NOT define. */
  uncontracted: string[];
  complete?: boolean;
}

export interface QueueInput {
  coverage?: CoverageReport | null;
  resolve?: ResolveReport | null;
  /** The kit's components, for the motion directives (+ role, to skip pages — they animate parent-side). */
  components?: { id: string; name: string; role?: string }[];
  /** Rotates the motion + polish start so a long run varies rather than always leading with the same one. */
  round?: number;
}

/** Last path segment of a `/`- or `\`-separated path (for a compact leak title). */
function short(p: string): string {
  const parts = p.split(/[/\\]/);
  return parts[parts.length - 1] || p;
}

/** Rotate `arr` left by `n` (wrapping), so successive rounds start at a different entry. Pure. */
function rotate<T>(arr: readonly T[], n: number): T[] {
  if (arr.length === 0) return [];
  const k = ((Math.trunc(n) % arr.length) + arr.length) % arr.length;
  return [...arr.slice(k), ...arr.slice(0, k)];
}

function isRecord(x: unknown): x is Record<string, unknown> {
  return typeof x === "object" && x !== null;
}

/** Parse a `bsc ui components --coverage --json` reply tolerantly — a reply that isn't a coverage report
 *  (empty, an error object, a future shape) yields `null`, and malformed rows are dropped, never thrown. */
export function parseCoverage(json: unknown): CoverageReport | null {
  if (!isRecord(json)) return null;
  if (!("leakCandidates" in json) && !("zeroConsumers" in json) && !("components" in json)) return null;
  const leakCandidates = (Array.isArray(json.leakCandidates) ? json.leakCandidates : [])
    .filter((x): x is Record<string, unknown> => isRecord(x) && typeof x.file === "string" && typeof x.count === "number")
    .map((x) => ({ file: x.file as string, count: x.count as number }));
  const zeroConsumers = (Array.isArray(json.zeroConsumers) ? json.zeroConsumers : []).filter(
    (x): x is string => typeof x === "string",
  );
  const components = (Array.isArray(json.components) ? json.components : [])
    .filter(
      (x): x is Record<string, unknown> =>
        isRecord(x) && typeof x.component === "string" && typeof x.tokensConsumed === "number" && typeof x.tokensTotal === "number",
    )
    .map((x) => ({ component: x.component as string, tokensConsumed: x.tokensConsumed as number, tokensTotal: x.tokensTotal as number }));
  return { leakCandidates, zeroConsumers, components };
}

/** Parse a `bsc ui resolve --json` reply tolerantly (see {@link parseCoverage}). */
export function parseResolve(json: unknown): ResolveReport | null {
  if (!isRecord(json)) return null;
  if (!("themeMisses" in json) && !("uncontracted" in json)) return null;
  const strArr = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : []);
  return {
    theme: typeof json.theme === "string" ? json.theme : undefined,
    themeMisses: strArr(json.themeMisses),
    uncontracted: strArr(json.uncontracted),
    complete: typeof json.complete === "boolean" ? json.complete : undefined,
  };
}

/** The rotating polish directives — open-ended "keep improving" work that sustains a run once the
 *  objective findings drain. Deliberately last (subjective, no ground truth beyond the shot). */
const POLISH: { key: string; title: string; detail: string }[] = [
  { key: "hierarchy", title: "Sharpen visual hierarchy", detail: "Strengthen a component's visual hierarchy (size/weight/spacing) so its primary element reads first." },
  { key: "spacing", title: "Tighten spacing rhythm", detail: "Audit a component's spacing for one consistent scale — remove ad-hoc gaps so the rhythm reads deliberate." },
  { key: "contrast", title: "Raise weak contrast", detail: "Find a text-or-border-on-surface pair with weak contrast and lift it toward an accessible ratio via tokens." },
  { key: "states", title: "Complete interaction states", detail: "Pick a control and make hover/active/focus/disabled each read distinctly — as tokens/variants, not one-offs." },
];

/**
 * Build the ranked directive queue from the design system's own findings. Objective gaps first (leaks →
 * uncontracted → theme-misses → low-coverage → dead tokens), then motion (per component, so the loop
 * covers animations), then rotating polish. Pure — the same inputs always yield the same queue.
 */
export function buildDesignerQueue(inp: QueueInput): DesignDirective[] {
  const out: DesignDirective[] = [];
  const cov = inp.coverage ?? null;
  const res = inp.resolve ?? null;
  const comps = inp.components ?? [];
  const round = inp.round ?? 0;

  // 1 · LEAKS — hardcoded colors a token change literally can't reach. The migration's real targets.
  for (const l of cov?.leakCandidates ?? []) {
    if (l.count > 0) {
      out.push({
        id: `leak:${l.file}`,
        kind: "leak",
        target: l.file,
        title: `Replace hardcoded colors in ${short(l.file)}`,
        detail: `${l.file} has ${l.count} hardcoded color(s) the design system can't govern — replace them with theme tokens so a theme actually reaches them.`,
      });
    }
  }
  // 2 · UNCONTRACTED — a consumed token the contract doesn't define (a token the system can't govern).
  for (const t of res?.uncontracted ?? []) {
    out.push({
      id: `uncontracted:${t}`,
      kind: "uncontracted",
      target: t,
      title: `Bring token ${t} under the design system`,
      detail: `Token ${t} is consumed but uncontracted — add it to the contract so the theme can govern it instead of it drifting.`,
    });
  }
  // 3 · THEME MISSES — a consumed token left at its contract default under the active theme.
  for (const t of res?.themeMisses ?? []) {
    out.push({
      id: `theme-miss:${res?.theme ?? ""}:${t}`,
      kind: "theme-miss",
      target: t,
      title: `Give token ${t} a considered value`,
      detail: `Token ${t} sits at its contract default under theme ${res?.theme ?? "the active theme"} — set a deliberate value so the theme reads intentional, not fallen-through.`,
    });
  }
  // 4 · LOW COVERAGE — a component consuming fewer tokens than it could (won't retint fully).
  for (const c of cov?.components ?? []) {
    if (c.tokensTotal > 0 && c.tokensConsumed < c.tokensTotal) {
      out.push({
        id: `low-coverage:${c.component}`,
        kind: "low-coverage",
        target: c.component,
        title: `Wire ${c.component} to its tokens`,
        detail: `${c.component} consumes ${c.tokensConsumed}/${c.tokensTotal} of its tokens — wire the rest so it retints fully under a theme.`,
      });
    }
  }
  // 5 · DEAD TOKENS — contract tokens no component consumes (use them or retire them; keep it honest).
  for (const t of cov?.zeroConsumers ?? []) {
    out.push({
      id: `dead-token:${t}`,
      kind: "dead-token",
      target: t,
      title: `Use or retire token ${t}`,
      detail: `Token ${t} has no consumers — apply it where it belongs or retire it so the contract reflects what's real.`,
    });
  }
  // 6 · MOTION — one per component, so the loop covers ANIMATIONS (grounded by a --frames burst). Pages
  //     animate parent-side, so skip them. Rotated by `round` so a long run doesn't always start the same.
  const motionComps = comps.filter((c) => c.role !== "page");
  for (const c of rotate(motionComps, round)) {
    out.push({
      id: `motion:${c.id}`,
      kind: "motion",
      target: c.name,
      title: `Review the motion on ${c.name}`,
      detail: `Does ${c.name} have a considered entrance and interaction motion? Add or refine it, then capture the motion as a burst so the change is grounded.`,
    });
  }
  // 7 · POLISH — rotating high-level directives that sustain the run once objective findings drain.
  for (const p of rotate(POLISH, round)) {
    out.push({ id: `polish:${p.key}`, kind: "polish", title: p.title, detail: p.detail });
  }
  return out;
}

