// detachSection -- open a page's section (e.g. github → repos, the projects
// board) in its own OS window (section tear-off, #430).
//
// Lives in shared/ (#1703) because it's a generic, feature/app-agnostic window
// helper: it depends only on the Tauri webview API + window.location, not on any
// app/ or feature/ module. Both the per-page tab model (shared/hooks/usePageTabs)
// and the projects summary (a feature) drive section tear-off through it.
//
// The detached window loads the same app with `?detach=<page>&section=<id>`;
// the shell reads that (via detachedSection) and renders just that section.

import { WebviewWindow } from "@tauri-apps/api/webviewWindow";

let seq = 0;

/** Open a page's section (e.g. github → repos) in its own window (tear-off).
 *  `onClose` fires when that window is destroyed (best-effort re-dock). */
export function openDetachedSection(page: string, section: string, title?: string, onClose?: () => void): void {
  seq += 1;
  const label = `tab-${page}-${section}-${seq}`.replace(/[^A-Za-z0-9/:_-]/g, "_");
  const u = new URL(window.location.href);
  u.hash = "";
  u.search = `?detach=${encodeURIComponent(page)}&section=${encodeURIComponent(section)}`;
  try {
    // `dragDropEnabled: false` is NOT optional (#3925). Tauri's WebView captures drag/drop for OS
    // file-drop by default and swallows `dragstart`/`dragover`/`drop` before the DOM sees them — the bug
    // #461 fixed for the main window via tauri.conf.json. A RUNTIME window does not inherit that config,
    // so without this the torn-off window's tab cannot be dragged at all, and dock-back can never fire.
    const w = new WebviewWindow(label, {
      url: u.href, title: title || section, width: 1100, height: 800,
      decorations: false, dragDropEnabled: false,
    });
    if (onClose) w.once("tauri://destroyed", () => onClose());
  } catch (e) {
    console.error("openDetachedSection failed:", e);
  }
}

// detachWindow -- open a console tab in its own OS window (tab tear-off, #430).
//
// A detached window loads the same app with `?detachTab=<idx>`; App reads that
// (via detachedTabIndex) and renders just that tab's console. State comes from
// the shared persisted store (the new window hydrates the same snapshot); PTY
// sessions are backend-owned by paneId, so the detached panes re-attach to the
// same sessions rather than forking them.

import { WebviewWindow } from "@tauri-apps/api/webviewWindow";

let seq = 0;

/**
 * The detached tab index encoded in a window's URL, or null for the main window.
 * Pure (search is injectable) so it's unit-testable.
 */
/** The detached console tab's stable id (`?detachTab=<id>`), or null for the
 *  main / section windows. Id-based so the window pins to the tab across
 *  reorders. Pure. */
export function detachedTabId(search: string = window.location.search): string | null {
  return new URLSearchParams(search).get("detachTab");
}

/** A detached page-section window's target (`?detach=<page>&section=<id>`), or
 *  null for the main / console-tab windows. Pure. */
export function detachedSection(search: string = window.location.search): { page: string; section: string } | null {
  const p = new URLSearchParams(search);
  const page = p.get("detach");
  const section = p.get("section");
  return page && section ? { page, section } : null;
}

// openDetachedSection (page-section tear-off) moved to shared/ (#1703): it's a
// generic webview helper used by shared/hooks/usePageTabs + the projects feature,
// none of which should reach into app/console. See shared/lib/core/detachSection.

/**
 * Open tab `idx` in its own OS window. Best-effort: logs and swallows failures
 * so a denied/edge case never breaks the drag gesture.
 */
export function openDetachedTab(tabId: string, title?: string, onClose?: () => void): void {
  seq += 1;
  const label = `tab-${tabId}-${seq}`.replace(/[^A-Za-z0-9/:_-]/g, "_");
  // Load the SAME app this window is already running, just with the detach marker.
  // Deriving from window.location is robust across dev (http://localhost:1420) and
  // prod (the asset protocol) — a bare relative "index.html" doesn't reliably
  // resolve under the dev server and yields a blank window.
  const u = new URL(window.location.href);
  u.hash = "";
  u.search = `?detachTab=${encodeURIComponent(tabId)}`;
  try {
    const w = new WebviewWindow(label, {
      url: u.href,
      title: title || "Console",
      width: 960,
      height: 720,
      decorations: false, // use the app's custom titlebar, not the native OS frame
      // #3925: a RUNTIME window does not inherit tauri.conf.json's `dragDropEnabled: false`, so without
      // this its WebView swallows every HTML5 drag event for OS file-drop (the #461 bug).
      dragDropEnabled: false,
    });
    // Re-dock when the detached window closes (best-effort; restart recovers it
    // regardless, since the detached set is session-only).
    if (onClose) w.once("tauri://destroyed", () => onClose());
  } catch (e) {
    console.error("openDetachedTab failed:", e);
  }
}

use std::collections::{HashMap, HashSet};

/// Depth-first traversal order from `start` over a weighted adjacency map (weights ignored).
pub fn dfs(adj: &HashMap<String, Vec<(String, u32)>>, start: &str) -> Vec<String> {
    fn visit(
        adj: &HashMap<String, Vec<(String, u32)>>,
        node: &str,
        seen: &mut HashSet<String>,
        order: &mut Vec<String>,
    ) {
        if !seen.insert(node.to_string()) {
            return;
        }
        order.push(node.to_string());
        if let Some(neighbors) = adj.get(node) {
            for (next, _) in neighbors {
                visit(adj, next, seen, order);
            }
        }
    }
    let mut order = Vec::new();
    let mut seen = HashSet::new();
    visit(adj, start, &mut seen, &mut order);
    order
}

// Interpretation + report caching for the host-environment diagnostics (#446/#447).
//
// The backend `preflight` probe (`src-tauri/src/lib.rs`) runs the prerequisite
// checks in the same login shell + env an agent's subshells use and returns one
// `PrereqStatus` per external dependency (Git Bash, `claude`, `git`, `gh`, plus
// `gh` auth), each with presence/version/path and an install hint. This module
// turns that raw list into a single user-facing verdict — overall severity, a
// headline, and a per-prerequisite explanation of what specifically breaks when
// it is missing (a missing Git Bash or `claude` gets its own message, not a
// generic failure) — and caches the last report so the Diagnostics view can
// render immediately on open. The console-shell selection + its persistence
// lives in `shellConfig.ts` (split out in #1711).
//
// Free of React/Tauri imports so it can be unit-tested and shared. Mirrors
// `githubReadiness.ts` (the GitHub-readiness probe interpreter).

/**
 * One prerequisite's detected state. Field names match the backend `PrereqStatus`
 * (`src-tauri/src/lib.rs`) so the probe result deserializes straight into this.
 */
export interface PrereqStatus {
  /** Display name: "Git Bash", "claude", "git", "gh", or "gh auth". */
  name: string;
  /** Whether the tool was located (and, for "gh auth", authenticated). */
  found: boolean;
  /** First line of `<tool> --version`, when found. */
  version: string | null;
  /** Resolved on-disk path, when found. */
  path: string | null;
  /** Actionable install/fix hint from the backend — empty when `found`. */
  hint: string;
}

/** How badly a missing prerequisite degrades the app. */
export type PrereqSeverity = "critical" | "warning";

/**
 * A prerequisite plus the interpreted consequence of its current state. `ok`
 * mirrors `found`; when not ok, `severity` says how bad it is and `consequence`
 * explains, in user terms, what stops working until it is fixed.
 */
export interface PrereqVerdict extends PrereqStatus {
  ok: boolean;
  /** Only meaningful when `!ok`. */
  severity: PrereqSeverity;
  /** What breaks while this is missing — empty when `ok`. */
  consequence: string;
}

/** The whole-host verdict the Diagnostics view renders. */
export interface DiagnosticsReport {
  prereqs: PrereqVerdict[];
  /** True only when every prerequisite is satisfied. */
  allOk: boolean;
  /** Worst severity among the missing prerequisites; null when `allOk`. */
  worst: PrereqSeverity | null;
  /** One-line summary — "All prerequisites satisfied." or a count of what's missing. */
  headline: string;
}

/**
 * What stops working when a given prerequisite is missing, and how severe that is.
 * Critical prerequisites block agents from running at all; warnings degrade a
 * specific capability (PR creation). Names not listed default to a critical,
 * generic consequence so a newly-probed tool is never silently treated as benign.
 */
function consequenceFor(name: string): { severity: PrereqSeverity; consequence: string } {
  switch (name) {
    case "Git Bash":
      return {
        severity: "critical",
        consequence:
          "Console sessions can't launch — Git Bash is the shell that runs agents on Windows. Install Git for Windows, then relaunch.",
      };
    case "claude":
      return {
        severity: "critical",
        consequence:
          "Agents can't run — the `claude` CLI is what every console session executes. Install it, then relaunch.",
      };
    case "git":
      return {
        severity: "critical",
        consequence:
          "Repository operations fail — agents can't clone, commit, or create worktrees without `git`.",
      };
    case "gh":
      return {
        severity: "warning",
        consequence:
          "Agents can't open pull requests — install the GitHub CLI (`gh`) to enable PR creation and review.",
      };
    case "gh auth":
      return {
        severity: "warning",
        consequence:
          "`gh` is installed but not authenticated — set `GH_TOKEN` or run `gh auth login` so agents can push and open PRs.",
      };
    default:
      return {
        severity: "critical",
        consequence: "This prerequisite is required for agents to run.",
      };
  }
}

/**
 * Pure: turn the backend probe's prerequisite list into the full host verdict.
 * Each entry gains an `ok`/`severity`/`consequence`; the report's `allOk`,
 * `worst`, and `headline` summarize the set. A single missing critical
 * prerequisite makes `worst` critical even if warnings also exist.
 */
export function interpretDiagnostics(prereqs: PrereqStatus[]): DiagnosticsReport {
  const verdicts: PrereqVerdict[] = prereqs.map((p) => {
    if (p.found) {
      return { ...p, ok: true, severity: "warning", consequence: "" };
    }
    const { severity, consequence } = consequenceFor(p.name);
    return { ...p, ok: false, severity, consequence };
  });

  const missing = verdicts.filter((v) => !v.ok);
  const allOk = missing.length === 0;
  const worst: PrereqSeverity | null = allOk
    ? null
    : missing.some((m) => m.severity === "critical")
      ? "critical"
      : "warning";

  let headline: string;
  if (allOk) {
    headline = "All prerequisites satisfied.";
  } else {
    const names = missing.map((m) => m.name).join(", ");
    const noun = missing.length === 1 ? "prerequisite" : "prerequisites";
    headline = `${missing.length} ${noun} need attention: ${names}.`;
  }

  return { prereqs: verdicts, allOk, worst, headline };
}

// ── Diagnostics report cache (#447) ─────────────────────────────────────────

const REPORT_KEY = "bsc.diagnostics.report.v1";

/** A persisted diagnostics report plus when it was taken (epoch ms). */
export interface StoredReport {
  report: DiagnosticsReport;
  takenAt: number;
}

/** Cache the latest report so the view can render instantly on open. Best-effort. */
export function saveReport(report: DiagnosticsReport, takenAt: number): void {
  try {
    globalThis.localStorage?.setItem(REPORT_KEY, JSON.stringify({ report, takenAt }));
  } catch {
    /* storage unavailable — the view re-probes on open anyway */
  }
}

/** Read the cached report, or null when absent/unparseable. */
export function loadReport(): StoredReport | null {
  try {
    const raw = globalThis.localStorage?.getItem(REPORT_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as StoredReport;
    if (!parsed || !parsed.report || !Array.isArray(parsed.report.prereqs)) return null;
    return parsed;
  } catch {
    return null;
  }
}

// ── PTY-session readiness bridge (#564) ─────────────────────────────────────
// Adapts the DiagnosticsReport produced by interpretDiagnostics() into the
// simpler blocking/warning interface the pane's SessionFailure/SessionReadinessBanner
// components need. The backend `preflight` command returns Vec<PrereqStatus>; call
// interpretDiagnostics() first, then sessionVerdictFromReport().

export type CheckSeverity = "critical" | "warning" | "ok";

export interface ReadinessCheck {
  /** Stable id for the check — used as a React key and for filtering. */
  id: string;
  severity: CheckSeverity;
  /** User-facing one-liner. Empty string when severity is "ok". */
  message: string;
  /** Official download/install URL extracted from the backend hint, when present. */
  installUrl?: string;
}

export interface SessionVerdict {
  /** All checks, including passing ones. */
  checks: ReadinessCheck[];
  /** Worst severity across all checks. */
  worstSeverity: CheckSeverity;
  /** True when any critical check failed — the session cannot run until resolved. */
  blocking: boolean;
  /** Checks that did not pass (severity !== "ok"). */
  failed: ReadinessCheck[];
}

function toReadinessCheck(v: PrereqVerdict): ReadinessCheck {
  if (v.ok) return { id: v.name, severity: "ok", message: "" };
  const urlMatch = v.hint.match(/https?:\/\/\S+/);
  return {
    id: v.name,
    severity: v.severity,
    message: v.consequence,
    installUrl: urlMatch?.[0],
  };
}

/**
 * Convert a `DiagnosticsReport` into the pane-level `SessionVerdict` used by
 * `SessionFailure` and `SessionReadinessBanner`. Call after `interpretDiagnostics`.
 */
export function sessionVerdictFromReport(report: DiagnosticsReport): SessionVerdict {
  const checks = report.prereqs.map(toReadinessCheck);
  const failed = checks.filter((c) => c.severity !== "ok");
  const blocking = report.worst === "critical";
  const worstSeverity: CheckSeverity = report.worst ?? "ok";
  return { checks, worstSeverity, blocking, failed };
}

use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};

/// Dijkstra shortest-path distances from `start` over a non-negative weighted adjacency map.
pub fn dijkstra(adj: &HashMap<String, Vec<(String, u32)>>, start: &str) -> HashMap<String, u32> {
    let mut dist: HashMap<String, u32> = HashMap::from([(start.to_string(), 0)]);
    let mut heap: BinaryHeap<Reverse<(u32, String)>> = BinaryHeap::new();
    heap.push(Reverse((0, start.to_string())));
    while let Some(Reverse((d, node))) = heap.pop() {
        if d > dist.get(&node).copied().unwrap_or(u32::MAX) {
            continue;
        }
        if let Some(neighbors) = adj.get(&node) {
            for (next, w) in neighbors {
                let nd = d + w;
                if nd < dist.get(next).copied().unwrap_or(u32::MAX) {
                    dist.insert(next.clone(), nd);
                    heap.push(Reverse((nd, next.clone())));
                }
            }
        }
    }
    dist
}

// Director drive mode (#366) -- how the project's async-integrator "director" session is
// driven once the fleet is running. The director is a plain Claude session that, after its
// kickoff, idles forever; this config + the runtime pump (useDirectorPump) decide when to
// re-prompt it so it actually reviews/merges worker PRs and resolves coordination events.
// Pure + unit-tested; mirrors agentFlow.ts (the per-stream flow config pattern).


/**
 * - `event`     -- re-prompt the director whenever workers post new coordination events
 *                  (landed / blocked / waiting / failed), but only while it is idle.
 * - `heartbeat` -- re-prompt on a fixed interval (a periodic fleet sweep), idle-gated.
 * - `manual`    -- never auto-prompt; the user pokes it from the Coordination inbox.
 * - `off`       -- the director is never driven (a static session).
 */
export type DirectorDrive = "event" | "heartbeat" | "manual" | "off";

export const DIRECTOR_DRIVES: DirectorDrive[] = ["event", "heartbeat", "manual", "off"];
export const DEFAULT_DIRECTOR_DRIVE: DirectorDrive = "event";

/** Default heartbeat cadence and the post-inject cooldown (guards the inject-then-run race). */
export const DEFAULT_HEARTBEAT_MS = 10 * 60 * 1000;
export const INJECT_COOLDOWN_MS = 6000;

/** How often an IDLE director is re-told about outstanding questions (#4019).
 *
 *  Shorter than {@link DEFAULT_HEARTBEAT_MS} on purpose: a worker is PARKED for every second of
 *  this, so ten minutes of silence is ten minutes of a stalled agent. Long enough that a director
 *  working through a batch is not interrupted mid-thought each time it draws breath. */
export const ASK_REMINDER_MS = 3 * 60 * 1000;

/** Coerce a raw fleet.json value into a known drive mode (default when unrecognized). */
export function normalizeDirectorDrive(raw: unknown): DirectorDrive {
  if (typeof raw !== "string") return DEFAULT_DIRECTOR_DRIVE;
  const v = raw.trim().toLowerCase();
  // Accept the longer alias the planner prose uses for the event mode.
  if (v === "event-driven") return "event";
  return (DIRECTOR_DRIVES as string[]).includes(v) ? (v as DirectorDrive) : DEFAULT_DIRECTOR_DRIVE;
}

/** Apply the default when the drive is unset. */
export function resolveDirectorDrive(drive: DirectorDrive | undefined): DirectorDrive {
  return drive ?? DEFAULT_DIRECTOR_DRIVE;
}

/** Stable key for a pending ask (session + when), so the pump surfaces each ask once. */
export function askKey(a: { session: string; at: number }): string {
  return `${a.session}@${a.at}`;
}

// The brief surfacing MOVED to `shared/lib/fleet/briefRouting.ts` (#brief-routes-to-its-target).
// `briefKey`/`pendingBriefPrompt` lived here and keyed only `<from>@<at>`, with no notion of the
// target — which is why every brief was delivered to every director pane. Routing needs the whole
// pane set, not just the director's, so it does not belong in the director's own drive module.

/** Stable key for an open project request, so the pump surfaces each one once. Keyed on the plan.db
 *  ROW ID, not session+time: the id is the thing the director resolves by, and it is what
 *  `request-resolved` carries, so the key prunes exactly when the request is answered. */
export function requestKey(r: { id: string }): string {
  return `req:${r.id}`;
}

/**
 * Should an idle director be re-told about outstanding work (#4019)?
 *
 * The pump delivers each ask/request exactly ONCE (its `surfaced` guard), which is right for not
 * re-queueing every tick — but it makes a single missed delivery final. If the director was mid-turn,
 * or simply did not act, nothing ever says it again and the worker waits forever. Measured: 44 asks
 * against 20 answers.
 *
 * This is the backstop, and it is deliberately NOT wired into that guard: the immediate delivery stays
 * exactly as it was. Gated on `idle` because the whole point is to spend the moment the director has
 * nothing else to do, and rate-limited so a director that keeps ignoring it is nagged at a sane
 * interval rather than on every tick.
 */
export function shouldRemind(inp: { idle: boolean; pending: number; now: number; lastRemindAt: number; everyMs: number }): boolean {
  if (!inp.idle || inp.pending === 0) return false;
  return inp.lastRemindAt === 0 || inp.now - inp.lastRemindAt >= inp.everyMs;
}

// Fire one automation into its target pane (#937). Extracted from useScheduler so BOTH
// the scheduler tick and the mobile "run now" path dispatch identically — resolve the
// target pane, build the payload, write it, and record the run. No React here; the host
// (PTY write, store record, clock) is injected so it's unit-testable.

import { resolveTargetPane, dispatchPayload, type Automation, type AutomationRun, type TabLike } from "@/features/automations/lib/scheduler";
import { log } from "@/shared/lib/core/log";

export interface DispatchDeps {
  tabs: TabLike[];
  disabledPanes: Record<string, boolean>;
  /** Write into a pane (e.g. invoke("pty_write", …) + a trailing CR is added here). */
  write: (paneId: string, data: string) => Promise<void>;
  recordRun: (id: string, run: AutomationRun) => void;
  now: () => number;
}

/**
 * Dispatch `a` once, recording exactly one run (ok / skipped / fail). Never throws — a
 * write failure is captured as a failed run. Resolves after the run is recorded.
 */
export async function dispatchAutomation(a: Automation, deps: DispatchDeps): Promise<void> {
  const at = deps.now();
  const where = `${a.targetTab} › pane ${a.targetPaneIdx + 1}`;

  const paneId = resolveTargetPane(a.targetTab, a.targetPaneIdx, deps.tabs, deps.disabledPanes);
  if (!paneId) {
    deps.recordRun(a.id, { at, status: "skipped", note: `target ${where} not open` });
    return;
  }

  const payload = dispatchPayload(a);
  if (payload == null) {
    deps.recordRun(a.id, { at, status: "fail", note: "empty command" });
    return;
  }

  try {
    await deps.write(paneId, payload + "\r");
    deps.recordRun(a.id, { at, status: "ok", note: `ran command in ${where}` });
  } catch (e) {
    log.error(`automation ${a.id} dispatch failed: ${e}`);
    deps.recordRun(a.id, { at, status: "fail", note: String(e) });
  }
}

// dockBack — return a torn-off window's page to the main window (#3919, follows #3917).
//
// Tear-off was one-directional: `openDetachedSection` opens the window, and the only way home was CLOSING
// it, which reads as discarding the page rather than returning it.
//
// The obvious fix — drag the tab back onto the main window's strip — cannot work through the DOM. The tab
// drag is HTML5 drag-and-drop, which is scoped to ONE webview, so a drag begun in the detached window can
// never deliver a `drop` to the main window's `TabBar`. The signal therefore travels out-of-band, over the
// Tauri app-global event bus (the same mechanism `useDebugChannel` / `useNavigateBridge` already use).
//
// The GESTURE is an inversion of tear-off rather than something new: `TabBar` fires `onTearOff` when a tab
// is dropped outside its strip, and in a detached window that means the tab is leaving THIS window — i.e.
// going home. Same affordance, opposite direction.
import { emit, listen, type UnlistenFn } from "@tauri-apps/api/event";

/** The app-global event a detached window emits to hand its page back. */
export const DOCK_BACK_EVENT = "bsc://dock-back";

/** Which page/section is coming home. Mirrors `detachedSection`'s shape. */
export interface DockBackPayload {
  page: string;
  section: string;
}

/** Ask the main window to take this page back. Best-effort: a failure must never strand the gesture, so
 *  the caller still closes its window and the `tauri://destroyed` re-dock path remains the backstop. */
export async function emitDockBack(payload: DockBackPayload): Promise<void> {
  try {
    await emit(DOCK_BACK_EVENT, payload);
  } catch (e) {
    console.error("emitDockBack failed:", e);
  }
}

/** Listen for a page coming home. Returns an unlisten fn, or a no-op when the bus is unavailable (tests,
 *  a browser dev server) — the caller's cleanup must not have to care. */
export async function onDockBack(handler: (p: DockBackPayload) => void): Promise<UnlistenFn> {
  try {
    return await listen<DockBackPayload>(DOCK_BACK_EVENT, (e) => {
      const p = e.payload;
      // The bus is untyped at the wire; ignore anything that isn't the shape we sent.
      if (p && typeof p.page === "string" && typeof p.section === "string") handler(p);
    });
  } catch {
    return () => {};
  }
}

// Domain publisher (#2498) — the rev/dedup/debounce engine behind the generic `store_state`
// projections. One instance fans every domain's pushes through the single `tunnel_set_store_state`
// entry point (#2497) with three guarantees:
//   • DEBOUNCE — rapid store churn coalesces into one frame per domain per window (~300ms).
//   • DEDUP    — an unchanged payload (byte-equal serialized JSON) is never re-sent, so poll-driven
//                sources (faults, coord log) that rebuild identical objects cost nothing on the wire.
//   • REV      — a monotonically increasing per-domain revision stamps each send, so mobile can
//                cheap-skip stale replays. The counter never resets while the app lives.
// Pure (no Tauri/React imports): the transport is injected, so the whole engine is unit-testable
// with fake timers. The app-wide singleton bound to `tunnelSetStoreState` lives in tunnelDomains.ts.

/** Injected transport — the shape of `tunnelSetStoreState`. */
export type DomainSend = (domain: string, rev: number, json: string) => Promise<void>;

export interface DomainPublisherOpts {
  send: DomainSend;
  /** Per-domain debounce window in ms (default 300). `0` sends synchronously (tests). */
  debounceMs?: number;
  /** Error sink for a failed send (default: swallow — the tunnel may simply be down). */
  onError?: (domain: string, err: unknown) => void;
}

export interface DomainPublisher {
  /** Queue one domain's projection. Serializes now (a later mutation can't corrupt the frame),
   *  debounces per domain, and skips the send entirely when the payload is byte-identical to the
   *  last one sent for that domain. */
  publish(domain: string, payload: unknown): void;
  /** Cancel pending timers and forget the last-sent cache so the next publish re-sends each domain
   *  (used when the relay restarts). Rev counters are NOT reset — they stay monotonic. */
  reset(): void;
  /** The current revision for a domain (0 = never sent). Exposed for tests/diagnostics. */
  rev(domain: string): number;
}

export function createDomainPublisher(opts: DomainPublisherOpts): DomainPublisher {
  const debounceMs = opts.debounceMs ?? 300;
  const onError = opts.onError ?? (() => {});
  const revs = new Map<string, number>();
  const lastSent = new Map<string, string>();
  const pending = new Map<string, { json: string; timer: ReturnType<typeof setTimeout> | null }>();

  const fire = (domain: string): void => {
    const p = pending.get(domain);
    if (!p) return;
    pending.delete(domain);
    if (lastSent.get(domain) === p.json) return; // unchanged since the last send — drop
    const rev = (revs.get(domain) ?? 0) + 1;
    revs.set(domain, rev);
    lastSent.set(domain, p.json);
    opts.send(domain, rev, p.json).catch((e) => onError(domain, e));
  };

  return {
    publish(domain, payload) {
      const json = JSON.stringify(payload);
      const p = pending.get(domain);
      if (p) {
        // A send is already scheduled — just refresh the payload it will carry.
        p.json = json;
        return;
      }
      if (lastSent.get(domain) === json) return; // no change at all — nothing to schedule
      if (debounceMs <= 0) {
        pending.set(domain, { json, timer: null });
        fire(domain);
        return;
      }
      const timer = setTimeout(() => fire(domain), debounceMs);
      pending.set(domain, { json, timer });
    },
    reset() {
      for (const p of pending.values()) if (p.timer) clearTimeout(p.timer);
      pending.clear();
      lastSent.clear();
    },
    rev(domain) {
      return revs.get(domain) ?? 0;
    },
  };
}

// Commit a DRAFT project's title edit (#1222) — the pure guard, extracted from Planning.tsx so
// it's unit-testable. The draft record (localDraftProjects[key].title, persisted) is the source of
// truth a reopen reads, so persisting the edit there is what makes it survive. The FROZEN key is
// kept — renames are display-only (#2409): the on-disk folder keeps its birth-slug.

import { projectSlug } from "@/shared/lib/core/projectPaths";

export type DraftCommit =
  | { kind: "revert" }                       // empty → restore the saved title
  | { kind: "noop" }                         // unchanged
  | { kind: "error"; message: string }       // collides with another project
  | { kind: "commit"; title: string };       // persist the new title

/**
 * Decide what blurring/Entering the draft title input should do, given the raw input, the saved
 * draft title, and the OTHER projects' keys (drafts + published aliases) for the duplicate guard.
 * Empty reverts; unchanged no-ops; a name that slugifies onto another project's key errors;
 * otherwise commit the trimmed title.
 */
export function planDraftCommit(raw: string, saved: string, otherKeys: ReadonlySet<string>): DraftCommit {
  const next = raw.trim();
  if (!next) return { kind: "revert" };
  if (next === saved) return { kind: "noop" };
  // Keys are name-derived slugs (#2409): a title whose slug lands on another project's key would
  // make two names resolve to ONE hub at reopen — block it here.
  if (otherKeys.has(projectSlug(next))) {
    return { kind: "error", message: "Another project already uses that name." };
  }
  return { kind: "commit", title: next };
}

// Pure draft-list selection for the Projects page (#1449). Extracted from ProjectsList so the
// "published hub leaks into Drafts" dedup is unit-testable.
//
// The Drafts list = on-disk local hubs ∪ the store draft map, MINUS anything already published.
// Published-ness is the authoritative in-place `.published` marker (#922), surfaced per hub as
// `LocalProject.published`. The earlier dedup excluded a draft only when its folder `key` matched
// a title-derived key or a node-id alias value — a fragile derivation that drifts from the marker:
// `sanitizeProjectKey` is case-PRESERVING, but the published-marker reconcile matches the GitHub
// board case-INSENSITIVELY (and the title is read from goal.md), so a hub whose folder key differs
// in case/spelling from the board title got marked published yet survived the draft filter —
// showing in BOTH lists. Keying off `lp.published` is the fix; the board-title keys stay as a
// secondary signal for hubs the reconcile hasn't marked yet. (The node-id alias is retired, #2409 —
// a board's key derives from its name.)
//
// #2995 adds a THIRD source unioned in on top: the durable projects DB (`bsc project db`). That layer
// is a strictly ADDITIVE mirror of the store draft map so a draft survives a restart even when the
// fragile `localDraftProjects` cache misses — see `mergeDbDrafts`.

import type { DbProject } from "@/features/planner/list/projectsDbBridge";

/** The fields of the backend `LocalProject` this selection needs. */
export interface LocalProjectLite {
  key: string;
  title: string;
  hasPlan: boolean;
  updatedAt: number;
  published: boolean;
  /** True when the title came from the `.title` sidecar (user input) — false = derived (de-slugged
   *  key / goal.md / placeholder), the board-title backfill's target set (#2467). Optional only for
   *  older fixtures; the live wire always carries it. */
  titled?: boolean;
}

/** A store draft-map entry (`addDraftProject`). */
export interface DraftMapEntry { title: string; pitch: string; createdAt: number }

/**
 * A bare on-disk scaffold hub — no plan, no user title, and never published (#2998). `buildDrafts`
 * filters these out of the Drafts list (only `hasPlan || titled` hubs are kept), so they're invisible
 * yet clutter the `projects/` dir. The Projects page surfaces them for a confirm-gated cleanup. Pure
 * so the predicate is unit-testable independently of the memo that also excludes anything already
 * shown as a draft.
 */
export function isOrphanScaffold(lp: LocalProjectLite): boolean {
  return !lp.hasPlan && !lp.titled && !lp.published;
}

/** A row in the Drafts list. */
export interface DraftRow { key: string; title: string; pitch: string; sort: number }

/**
 * Build the Drafts list, dropping every already-published project.
 *
 * @param localProjects     on-disk hubs from `list_local_projects` (carry the `.published` marker).
 * @param localDraftProjects the store's draft map (key → {title, pitch, createdAt}).
 * @param publishedTitleKeys every key form of each visible GitHub board title — the name-derived
 *                           `projectSlug(title)` (#2409) plus the legacy `sanitizeProjectKey(title)`
 *                           for grandfathered title-keyed hubs.
 * @returns draft rows, deduped by key, sorted not applied (caller sorts).
 */
export function buildDrafts(
  localProjects: LocalProjectLite[],
  localDraftProjects: Record<string, DraftMapEntry>,
  publishedTitleKeys: string[],
): DraftRow[] {
  const safeLocals = Array.isArray(localProjects) ? localProjects : [];
  const publishedKeys = new Set<string>([
    ...publishedTitleKeys,
    // The authoritative signal (#922): a hub flagged published is never a draft, regardless of
    // whether its folder key matches a board-title-derived key.
    ...safeLocals.filter(lp => lp?.published).map(lp => lp.key),
  ]);

  const byKey = new Map<string, DraftRow>();
  for (const lp of safeLocals) {
    // A hub is a draft when it has a plan OR the user named it (`titled`, #2994) — a user-titled hub
    // with a plan.db but no goal/scope section yet is still a real draft. Only a bare, UNTITLED
    // scaffold is skipped. (Interim until the DB-backed list, epic #2993.)
    if (!lp?.hasPlan && !lp?.titled) continue;
    if (lp.published) continue;   // published hubs are not drafts (#922)
    byKey.set(lp.key, { key: lp.key, title: lp.title, pitch: "", sort: lp.updatedAt });
  }
  for (const [key, d] of Object.entries(localDraftProjects)) {
    const ex = byKey.get(key);
    byKey.set(key, { key, title: d.title, pitch: d.pitch, sort: Math.max(ex?.sort ?? 0, d.createdAt) });
  }
  return [...byKey.values()].filter(d => !publishedKeys.has(d.key));
}

/**
 * Union the durable projects-DB rows (#2995) into the assembled Drafts list. ADDITIVE only: every
 * `existing` row is kept, and a DB row that isn't already represented is appended — so a draft the
 * `localDraftProjects` cache lost on restart still surfaces from the DB. Only `drafted`/`planning`-state
 * rows are drafts; `published`/`created` rows are ignored (a published project is not a draft). Deduped
 * by key — an existing entry KEEPS its title + pitch when non-empty (the on-disk hub / store draft map
 * is the richer source), only borrowing the DB's when it has none; `sort` is the newer of the two.
 * Pure so it's unit-testable.
 *
 * @param existing the rows {@link buildDrafts} produced (on-disk hubs ∪ store draft map, minus published).
 * @param dbRows   every row from `bsc project db list` (see {@link DbProject}); non-draft states ignored.
 */
export function mergeDbDrafts(existing: DraftRow[], dbRows: DbProject[]): DraftRow[] {
  const byKey = new Map<string, DraftRow>();
  for (const d of existing) byKey.set(d.key, d);
  for (const r of Array.isArray(dbRows) ? dbRows : []) {
    if (r.state !== "drafted" && r.state !== "planning") continue;
    const dbSort = r.updatedAt || r.createdAt || 0;
    const ex = byKey.get(r.key);
    if (ex) {
      byKey.set(r.key, {
        key: r.key,
        title: ex.title || r.title,
        pitch: ex.pitch || r.pitch,
        sort: Math.max(ex.sort, dbSort),
      });
    } else {
      byKey.set(r.key, { key: r.key, title: r.title, pitch: r.pitch, sort: dbSort });
    }
  }
  return [...byKey.values()];
}

// Drag-and-drop folder traversal (#831). A dropped FOLDER does not appear in
// `DataTransfer.files` — it's a `FileSystemDirectoryEntry` reachable only via
// `DataTransferItem.webkitGetAsEntry()`. This walks each dropped entry recursively and
// collects every file with its relative path (so the folder structure is preserved under
// `design/`). The DOM entry API is callback-based; this promisifies + flattens it. Kept
// behind a minimal interface so it's unit-testable with fakes (no real DataTransfer needed).

/** The slice of `FileSystemEntry` (+ its file/directory subtypes) we use. Lets tests
 *  supply plain fakes instead of a real DOM entry tree. */
export interface FsEntryLike {
  isFile: boolean;
  isDirectory: boolean;
  name: string;
  file?(onSuccess: (f: File) => void, onError?: (e: unknown) => void): void;
  createReader?(): {
    readEntries(onSuccess: (entries: FsEntryLike[]) => void, onError?: (e: unknown) => void): void;
  };
}

/** A collected file plus its path relative to the drop root (e.g. `icons/home.svg`). */
export interface DroppedFile {
  file: File;
  path: string;
}

/** Recursively collect files from one dropped entry, preserving its relative path under
 *  `prefix`. A file yields one entry; a directory is read in batches (`readEntries` returns
 *  `[]` when exhausted) and recursed into. Unknown entries yield nothing. */
export async function collectEntry(entry: FsEntryLike, prefix = ""): Promise<DroppedFile[]> {
  if (entry.isFile && entry.file) {
    const fileFn = entry.file.bind(entry);
    const file = await new Promise<File>((resolve, reject) => fileFn(resolve, reject));
    return [{ file, path: prefix + entry.name }];
  }
  if (entry.isDirectory && entry.createReader) {
    const reader = entry.createReader();
    const out: DroppedFile[] = [];
    const childPrefix = `${prefix}${entry.name}/`;
    // readEntries yields the directory in batches; call until it returns an empty batch.
    for (;;) {
      const batch = await new Promise<FsEntryLike[]>((resolve, reject) =>
        reader.readEntries(resolve, reject),
      );
      if (batch.length === 0) break;
      for (const child of batch) out.push(...(await collectEntry(child, childPrefix)));
    }
    return out;
  }
  return [];
}

/** Collect every file from a set of dropped entries, folders walked recursively. */
export async function collectDroppedEntries(entries: FsEntryLike[]): Promise<DroppedFile[]> {
  const all = await Promise.all(entries.map((e) => collectEntry(e)));
  return all.flat();
}

// Edge batching (#4150) — collapse the graph's edge layer from three SVG elements PER EDGE into one
// merged path per visual class.
//
// Each edge used to render `<g>` + a stroke `<path>` + a filled arrowhead `<path>`: 799 edges on the
// 248-component kit is ~2,400 elements, and ~9,600 at the 1000-component target. SVG path data takes
// MULTIPLE SUBPATHS (`M…L… M…L…`), so lines sharing a stroke are one `<path>` and arrowheads sharing a
// fill are one more.
//
// Two properties make that safe rather than clever:
//   • the edge layer is `pointer-events: none`, so no per-edge element is needed for behaviour;
//   • the non-highlighted bulk all draws identically, so it has no per-edge styling to lose.
//
// The SELECTION-incident edges stay individual — they are few, and they are the ones whose appearance
// actually differs. Pure, so the merge is testable without a DOM.

/** One edge's geometry, as `graphEdge` returns it: the line and its arrowhead, both path `d` strings. */
export interface EdgeGeom {
  /** The line's path data. */
  d: string;
  /** The arrowhead's path data — a closed, filled shape. */
  arrow: string;
}

/** The merged bulk plus the edges held back to render individually. */
export interface EdgeBatch<T> {
  /** Every bulk line concatenated into one path `d`, or `""` when the bulk is empty. */
  d: string;
  /** Every bulk arrowhead concatenated into one path `d`, or `""` when the bulk is empty. */
  arrow: string;
  /** The edges the caller must render itself (the highlighted ones), in input order. */
  individual: T[];
}

/**
 * Split `edges` into a merged bulk and an individual remainder.
 *
 * `geom` returns an edge's geometry, or `null` to DROP it (an endpoint with no laid-out position — the
 * same skip the per-edge render did). `individually` marks the edges to hold back.
 *
 * Concatenating with a space keeps each subpath's leading `M` its own token, so the result is the exact
 * sequence of subpaths the separate elements drew — merging changes the element COUNT, never the pixels.
 *
 * Filled arrowheads merge under the default nonzero winding rule: separate closed triangles each fill,
 * and two that overlap simply paint the same colour twice.
 */
export function batchEdges<T>(
  edges: readonly T[],
  geom: (edge: T) => EdgeGeom | null,
  individually: (edge: T) => boolean = () => false,
): EdgeBatch<T> {
  const lines: string[] = [];
  const arrows: string[] = [];
  const individual: T[] = [];
  for (const e of edges) {
    const g = geom(e);
    if (!g) continue; // an endpoint with no position — dropped, exactly as before
    if (individually(e)) {
      individual.push(e);
      continue;
    }
    if (g.d) lines.push(g.d);
    if (g.arrow) arrows.push(g.arrow);
  }
  return { d: lines.join(" "), arrow: arrows.join(" "), individual };
}

// Shared edge geometry (#2222, graph design-language #2221) — the ONE line-type every graph draws its
// edges with: a cubic bezier + a filled-triangle arrowhead + a label midpoint, in a shared grammar.
// Only the ROUTING (where the curve meets each card) is layout-dependent (#2226), via `routing`:
//   • "anchor" — perimeter-anchor: leaves each card at the point on its border facing the other card.
//     Right for FREE / ORGANIC layouts (the Org designer's force graph).
//   • "ports"  — side ports: leaves the right (or left) edge at the vertical middle with horizontal
//     control handles. Right for LAYERED left→right graphs (Glance's dependency DAG) — clean columnar
//     flow. (Restores Glance's pre-#2222 geometry; the perimeter router read messy on a layered graph.)
// Both share the arrowhead + label + `bow` (perpendicular separation for parallel/bidirectional/cycle
// edges) + `doubleEnded` (a source arrow for bidirectional relationships). Pure.

export interface EdgeBox { x: number; y: number; w: number; h: number }

export type EdgeRouting = "anchor" | "ports";

export interface GraphEdgeOpts {
  /** Where the curve meets each card. Default "anchor" (perimeter); "ports" for layered graphs. */
  routing?: EdgeRouting;
  /** Perpendicular bow (px) so parallel/bidirectional/cycle edges separate. Default 0. */
  bow?: number;
  /** ("anchor" only) how far short of the target border the curve ends, for the arrow. Default 9. */
  endGap?: number;
  /** Arrowhead length (px); half-width ≈ 0.58×. Default 9. */
  arrowSize?: number;
  /** Also draw an arrowhead at the source (bidirectional). Default false. */
  doubleEnded?: boolean;
}

export interface GraphEdgeGeom {
  /** The cubic-bezier path `d`. */
  d: string;
  /** Filled-triangle arrowhead path at the target border. */
  arrow: string;
  /** Filled-triangle arrowhead at the source border (only when `doubleEnded`). */
  arrowStart?: string;
  /** The curve midpoint — where an edge label pill sits. */
  labelX: number;
  labelY: number;
}

const f = (v: number): number => Math.round(v * 10) / 10;

/** The point on box `a`'s perimeter along the ray toward (tx,ty), with a 3px outset so the line clears
 *  the border. (The Org designer's `anchor` — exported since #2418 replaced org's byte-identical copy;
 *  its feature barrel re-exports this one.) */
export function anchor(a: EdgeBox, tx: number, ty: number): [number, number] {
  const cx = a.x + a.w / 2, cy = a.y + a.h / 2, dx = tx - cx, dy = ty - cy;
  const hw = a.w / 2 + 3, hh = a.h / 2 + 3;
  const sx = dx === 0 ? 1e9 : hw / Math.abs(dx);
  const sy = dy === 0 ? 1e9 : hh / Math.abs(dy);
  const s = Math.min(sx, sy);
  return [cx + dx * s, cy + dy * s];
}

/** A filled-triangle arrow with its tip at (tipx,tipy), pointing along `ang`. */
function arrowPath(tipx: number, tipy: number, ang: number, len: number): string {
  const w = len * 0.58;
  const bx = tipx - Math.cos(ang) * len, by = tipy - Math.sin(ang) * len;
  const nx = -Math.sin(ang), ny = Math.cos(ang);
  return `M ${f(tipx)} ${f(tipy)} L ${f(bx + nx * w)} ${f(by + ny * w)} L ${f(bx - nx * w)} ${f(by - ny * w)} Z`;
}

/** Assemble the geometry from the four control points (source, two handles, arrow tip). Shared by both
 *  routers: the curve ends at `tip`, the arrow sits there, the label is the cubic midpoint. */
function assemble(p1x: number, p1y: number, c1x: number, c1y: number, c2x: number, c2y: number, tipx: number, tipy: number, arrowSize: number, doubleEnded: boolean): GraphEdgeGeom {
  const d = `M ${f(p1x)} ${f(p1y)} C ${f(c1x)} ${f(c1y)} ${f(c2x)} ${f(c2y)} ${f(tipx)} ${f(tipy)}`;
  // The cubic's midpoint (t=0.5) via the Bernstein weights (1/8, 3/8, 3/8, 1/8).
  const labelX = 0.125 * p1x + 0.375 * c1x + 0.375 * c2x + 0.125 * tipx;
  const labelY = 0.125 * p1y + 0.375 * c1y + 0.375 * c2y + 0.125 * tipy;
  const arrow = arrowPath(tipx, tipy, Math.atan2(tipy - c2y, tipx - c2x), arrowSize);
  const arrowStart = doubleEnded ? arrowPath(p1x, p1y, Math.atan2(p1y - c1y, p1x - c1x), arrowSize) : undefined;
  return { d, arrow, arrowStart, labelX, labelY };
}

/** Perimeter-anchor routing — for free/organic layouts. Byte-identical to the Org designer's geometry. */
function anchorEdge(from: EdgeBox, to: EdgeBox, opts: GraphEdgeOpts): GraphEdgeGeom {
  const bow = opts.bow ?? 0, endGap = opts.endGap ?? 9, arrowSize = opts.arrowSize ?? 9;
  const acx = from.x + from.w / 2, acy = from.y + from.h / 2, bcx = to.x + to.w / 2, bcy = to.y + to.h / 2;
  const [p1x, p1y] = anchor(from, bcx, bcy);
  const [b2x, b2y] = anchor(to, acx, acy);       // the target border point — the arrow tip
  const dx0 = b2x - p1x, dy0 = b2y - p1y, L = Math.hypot(dx0, dy0) || 1;
  const p2x = b2x - (dx0 / L) * endGap;          // curve ends short of the border
  const p2y = b2y - (dy0 / L) * endGap;
  const dx = p2x - p1x, dy = p2y - p1y;
  const nx = -dy / L, ny = dx / L;
  const c1x = p1x + dx * 0.35 + nx * bow, c1y = p1y + dy * 0.35 + ny * bow;
  const c2x = p1x + dx * 0.65 + nx * bow, c2y = p1y + dy * 0.65 + ny * bow;
  // NB: the arrow tip is the border point; the curve ends short of it (p2).
  return {
    ...assemble(p1x, p1y, c1x, c1y, c2x, c2y, p2x, p2y, arrowSize, !!opts.doubleEnded),
    arrow: arrowPath(b2x, b2y, Math.atan2(p2y - c2y, p2x - c2x), arrowSize),
  };
}

/** Side-port routing — for layered left→right graphs. Leaves the right (or left) edge at the vertical
 *  middle with horizontal control handles, giving a clean columnar flow. Restores Glance's geometry. */
function portsEdge(from: EdgeBox, to: EdgeBox, opts: GraphEdgeOpts): GraphEdgeGeom {
  const bow = opts.bow ?? 0, arrowSize = opts.arrowSize ?? 9;
  const fRight = from.x < to.x;
  const p1x = from.x + (fRight ? from.w : 0), p1y = from.y + from.h / 2;
  const tLeftPort = to.x >= from.x;
  const tx = to.x + (tLeftPort ? 0 : to.w), ty = to.y + to.h / 2;   // target port — the arrow tip
  const k = Math.max(46, Math.abs(tx - p1x) * 0.5);
  const c1x = p1x + (fRight ? k : -k), c1y = p1y + bow;
  const c2x = tx + (tLeftPort ? -k : k), c2y = ty + bow;
  return assemble(p1x, p1y, c1x, c1y, c2x, c2y, tx, ty, arrowSize, !!opts.doubleEnded);
}

/** The shared line-type between two boxes; `routing` picks the router. See the module header. */
export function graphEdge(from: EdgeBox, to: EdgeBox, opts: GraphEdgeOpts = {}): GraphEdgeGeom {
  return opts.routing === "ports" ? portsEdge(from, to, opts) : anchorEdge(from, to, opts);
}

// Resume for a pane whose PTY is ALREADY ALIVE (#3998).
//
// Every Resume site in the app ultimately relies on `pty_create` to launch the agent — but
// `pty_create` returns before it ever reads `init_cmd` when a session already exists for the pane
// ("reconnect to existing session"). So for a live pane, the carefully-resolved
// `claude --continue 2>/dev/null || claude` is computed, handed to the backend, and thrown away.
// The pane gets a Ctrl+L repaint of its bash prompt and nothing else. That is why Resume appeared to
// do nothing on a session whose agent had already exited.
//
// `TerminalView` never remounts such a pane either: it is portal-hosted keyed by `paneId`, so the
// `runId` bump a resume performs re-keys the SLOT, not the terminal. Only a pane in a placeholder
// state (ended / disabled / dormant) unmounts and remounts.
//
// So the fix cannot live in the launch path — the launch path is unreachable. It has to act on the
// live shell directly: ask what the pane is actually doing, and if it is sitting at a prompt, type
// the resume command into it.

import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { log } from "@/shared/lib/core/log";

/** `claude --continue`, degrading to a fresh session when there is no conversation to resume (#3937).
 *  Defined here rather than in `app/console/lib/resumeClaude.ts` so BOTH the mount-time launch path
 *  and this live-shell path emit the byte-identical command — a resumed pane must not depend on which
 *  of the two routes happened to reach it. stderr is dropped because claude's "no session" message is
 *  expected on the first `--continue` of a fresh worktree. */
export const CONTINUE_OR_FRESH = "claude --continue 2>/dev/null || claude";

/** What the backend reports for one pane (`pty_pane_runtime`). */
export type PaneRuntime = {
  paneId: string;
  /** A PTY session exists — `pty_create` would RECONNECT rather than launch. */
  live: boolean;
  /** Its shell has a live descendant, i.e. something is running in it. */
  busy: boolean;
};

/** Why a pane was or wasn't started, for logging and tests. */
export type ResumeOutcome = "started" | "already-running" | "not-live";

/**
 * Decide what a resume should do with each pane, given the backend's runtime report.
 *
 * Pure so the policy is testable without a live PTY. The three cases:
 *  - `not-live`     — no PTY yet. Do nothing: the pane's mount will run the normal launch path,
 *                     which handles `--continue` properly. Typing into a shell that doesn't exist
 *                     would be dropped anyway.
 *  - `already-running` — the shell has a descendant. Do nothing. This is the guard that stops a
 *                     resume from injecting a second `claude` into an agent that is mid-turn, and it
 *                     is why the backend probe asks about DESCENDANTS rather than trying to spot a
 *                     process named `claude` (which is `node.exe` on Windows).
 *  - `started`      — live, at a prompt. Type the resume command in.
 */
export function planResume(runtimes: readonly PaneRuntime[]): Map<string, ResumeOutcome> {
  const out = new Map<string, ResumeOutcome>();
  for (const r of runtimes) {
    out.set(r.paneId, !r.live ? "not-live" : r.busy ? "already-running" : "started");
  }
  return out;
}

/**
 * Make sure claude is running in each of `paneIds` whose PTY is alive but idle.
 *
 * Batched: the backend's busy check walks the process table, so asking about every pane at once costs
 * one walk instead of N — a project-wide resume touches dozens of panes.
 *
 * Returns the per-pane outcome so callers can report "started N" honestly instead of claiming a
 * resume that didn't happen.
 */
export async function ensureClaudeRunning(paneIds: readonly string[]): Promise<Map<string, ResumeOutcome>> {
  if (paneIds.length === 0) return new Map();
  const runtimes = await safeInvoke<PaneRuntime[]>("pty_pane_runtime", { paneIds: [...paneIds] }, []);
  const plan = planResume(runtimes);

  const started: string[] = [];
  for (const [paneId, outcome] of plan) {
    if (outcome !== "started") continue;
    // A plain write, NOT `injectPrompt`: that wraps text in bracketed-paste markers for claude's TUI,
    // and this is going to a bash prompt, where the markers would be echoed as literal characters.
    // The trailing newline is the Enter that runs it.
    await safeInvoke("pty_write", { paneId, data: `${CONTINUE_OR_FRESH}\n` }, undefined);
    started.push(paneId);
  }
  if (started.length > 0) {
    log.info(`resume: started claude in ${started.length} idle pane(s): ${started.join(", ")}`);
  }
  return plan;
}

import { Component, type ErrorInfo, type ReactNode } from "react";
import { log } from "@/shared/lib/core/log";

interface Props {
  children: ReactNode;
  /** Optional label for the area this boundary wraps (shown in the fallback + logs). */
  label?: string;
  /** When any value here changes, the boundary clears its error — without remounting the
   *  children. Pass `[activeWorkspace]` so navigating away from a crashed view auto-recovers
   *  while persistent screens (Projects/Knowledge with live PTY sessions) keep their mount. */
  resetKeys?: unknown[];
}

interface State {
  err: Error | null;
}

/** Shallow element-wise inequality, treating different lengths as changed. */
function keysChanged(a: unknown[] = [], b: unknown[] = []): boolean {
  return a.length !== b.length || a.some((v, i) => !Object.is(v, b[i]));
}

/**
 * App-wide safety net. Without a boundary, a render error in any screen unmounts the
 * entire React tree — the window goes blank and looks like the whole app crashed (e.g.
 * deleting a project draft, #874). This catches the error, keeps the chrome alive, and
 * shows a recoverable fallback with a "try again" reset so the user never loses the app.
 *
 * It only catches errors thrown during render / lifecycle of its children. Errors in
 * async callbacks (event handlers, promises) don't propagate here — those are handled at
 * their call sites — but any state change they cause that then crashes a render IS caught.
 */
export class ErrorBoundary extends Component<Props, State> {
  state: State = { err: null };

  static getDerivedStateFromError(err: Error): State {
    return { err };
  }

  componentDidCatch(err: Error, info: ErrorInfo) {
    // Best-effort structured log to the always-audited file sink (#1389); never let logging throw.
    // Scope `safety` so its devtools output can be toggled independently of feature noise.
    log.error(
      `ErrorBoundary${this.props.label ? ` [${this.props.label}]` : ""} caught: ${err?.message ?? err}\n${info?.componentStack ?? ""}`,
      "safety",
    );
  }

  componentDidUpdate(prev: Props) {
    // Auto-recover when the reset keys change (e.g. the user navigated to another screen),
    // so a one-off crash doesn't strand the view behind the fallback forever.
    if (this.state.err && keysChanged(prev.resetKeys, this.props.resetKeys)) {
      this.setState({ err: null });
    }
  }

  reset = () => this.setState({ err: null });

  render() {
    if (!this.state.err) return this.props.children;
    return (
      // eslint-disable-next-line no-restricted-syntax -- crash boundary must render without depending on the UI kit
      <div
        role="alert"
        className="mono"
        style={{
          display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",
          gap: 14, height: "100%", minHeight: 240, padding: 32, textAlign: "center",
          color: "var(--fg)",
        }}
      >
        {/* eslint-disable-next-line no-restricted-syntax -- crash boundary must render without depending on the UI kit */}
        <div style={{ fontSize: 14, fontWeight: 600 }}>Something went wrong{this.props.label ? ` in ${this.props.label}` : ""}.</div>
        {/* eslint-disable-next-line no-restricted-syntax -- crash boundary must render without depending on the UI kit */}
        <div style={{ fontSize: 11.5, color: "var(--fg-muted)", maxWidth: 520, lineHeight: 1.5 }}>
          The view hit an unexpected error and was stopped to keep the rest of the app running.
        </div>
        <pre
          style={{
            margin: 0, maxWidth: 520, maxHeight: 140, overflow: "auto", textAlign: "left",
            fontSize: 10.5, color: "var(--danger)", background: "color-mix(in oklch, var(--danger), transparent 92%)",
            border: "1px solid color-mix(in oklch, var(--danger), transparent 70%)", borderRadius: "var(--r-md)",
            padding: "8px 10px", whiteSpace: "pre-wrap", wordBreak: "break-word",
          }}
        >{this.state.err.message || String(this.state.err)}</pre>
        {/* eslint-disable-next-line no-restricted-syntax -- crash boundary must render without depending on the UI kit */}
        <button className="btn primary" onClick={this.reset} style={{ height: 28 }}>try again</button>
      </div>
    );
  }
}

/// Greatest common divisor via the Euclidean algorithm (iterated remainder).
pub fn gcd(mut a: u64, mut b: u64) -> u64 {
    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }
    a
}

// What clicking a node to EXPAND it should do (#expanding-a-node-resumes-its-session).
//
// The per-node Resume button lived in the right pane, which was retired — so the expand click is now
// the resume. Studio nodes already worked this way (`useStudioViewers` starts a studio when its morph
// opens); this gives the fleet the same rule.
//
// Pure, and separate from GlanceWorkspace, for the reason `directorDrive` and `briefRouting` are: the
// interesting part is a four-way decision with one genuinely non-obvious branch, and testing it through
// a rendered graph would mean standing up a whole drilled fleet to assert a boolean.

/** The one non-obvious input, spelled out because it has misled this codebase repeatedly. */
export interface ExpandInput {
  /** Is THIS NODE an app-owned studio session? Such a node owns its lifecycle — the morph starts it.
   *
   *  Per NODE, not per drill (#the-app-drills-into-a-project-that-was-deleted). It used to be
   *  `isStudioProject`, answered once for the whole graph, which was true only while the studio sessions
   *  lived on a project of their own. They now share the app's project drill with its plan.db workers, so
   *  a graph holds both kinds and the question can only be asked of one node at a time. */
  isAppOwnedSession: boolean;
  /** For a studio node: does it morph (i.e. has a session) at all? Library/resource nodes do not. */
  studioMorphs?: boolean;
  /** Does a session CELL exist for this pane — i.e. is it a member of an open tab?
   *
   *  NOT "an agent is running". `livePaneIds` is tab membership (`glanceFleet.ts`), and #3998 measured
   *  77 of 78 fleet panes reading as live while sitting at a bare `$` prompt with no agent. Treating
   *  this as "running" is why Resume looked inert for so long. */
  paneIsLive: boolean;
  /** Has this worker finished its owned work? (#4029) */
  paneIsComplete: boolean;
  /** Is the project's build tab still open, so ONE pane can be resumed in place? */
  canResumeInPlace: boolean;
}

export type ExpandAction =
  /** Open the morph; the studio's own lazy start brings the session up. */
  | { kind: "studio-morph" }
  /** No session to open (a library/resource node) — just select it. */
  | { kind: "select" }
  /** A finished worker is not put back on the model by a stray click; say why, do not expand. */
  | { kind: "refuse-complete"; reason: string }
  /** The pane exists but its agent exited — type the resume into the shell it already has. */
  | { kind: "expand-and-restart-agent" }
  /** No pane, but its build tab is open — resume just this one in place. */
  | { kind: "expand-and-resume-pane" }
  /** No pane and no tab — the whole fleet has to come back before this node can. */
  | { kind: "expand-and-resume-fleet" };

export const COMPLETE_REASON =
  "This worker is complete. The director wakes it when it dispatches work.";

/**
 * Decide what an expand click means for one node.
 *
 * Order matters: the COMPLETE check precedes every expansion, so a finished worker cannot be restarted
 * by a click that was only meant to look at it.
 */
export function decideExpand(input: ExpandInput): ExpandAction {
  if (input.isAppOwnedSession) {
    return input.studioMorphs ? { kind: "studio-morph" } : { kind: "select" };
  }
  if (input.paneIsComplete) return { kind: "refuse-complete", reason: COMPLETE_REASON };
  if (input.paneIsLive) return { kind: "expand-and-restart-agent" };
  if (input.canResumeInPlace) return { kind: "expand-and-resume-pane" };
  return { kind: "expand-and-resume-fleet" };
}

// expandedPreviewFit (#3551) — size + place the expanded theme try-on's design frame inside the measured
// canvas. Pure so the width-first / fluid-fill contract is unit-testable (the DesignsWorkbench layout it
// feeds cannot be seen by jsdom).

export type PreviewViewport = "sm" | "md" | "auto";

export interface ExpandedFit {
  /** The design frame's CSS width — the breakpoint the component renders at. */
  previewW: number;
  /** The design frame's CSS height. */
  previewH: number;
  /** Host framing scale of the frame into the canvas. Always ≤ 1 (never upscales → the iframe texture
   *  stays crisp; the user zooms IN via the in-iframe engine, not by host-scaling). */
  scale: number;
  /** Centering offset of the scaled frame within the canvas. */
  tx: number;
  ty: number;
}

/**
 * WIDTH-first framing, and `auto` is truly FLUID (#3551).
 *
 * `auto` fills the whole canvas — `previewW` = canvas width, `previewH` = canvas height — at **scale 1**.
 * So the preview uses the full width, GROWS when the panel is resized, and (critically) is NOT
 * host-CSS-scaled: a host downscale (the old fixed `1200×440` frame `Math.min(1, …)`-fit into the canvas)
 * both shrank the preview AND desynced the in-iframe pan engine, whose pointer math reads iframe-internal
 * `clientX` — hence "no click and drag". At scale 1 the drag tracks the cursor 1:1 again.
 *
 * `sm`/`md` render at their fixed CSS breakpoint width but use the canvas HEIGHT (not a short fixed 440)
 * and downscale-only-fit — never upscaling a small breakpoint (it would blur), so it stays crisp and the
 * user zooms in with the engine.
 *
 * @param vp the selected viewport (`sm` 380px · `md` 640px · `auto` fluid)
 * @param cw measured canvas width in px (0 before layout)
 * @param ch measured canvas height in px (0 before layout)
 */
export function expandedPreviewFit(vp: PreviewViewport, cw: number, ch: number): ExpandedFit {
  const fluid = vp === "auto";
  const previewW = vp === "sm" ? 380 : vp === "md" ? 640 : cw || 1200;
  const previewH = ch || 440;
  if (!cw || !ch) return { previewW, previewH, scale: 1, tx: 0, ty: 0 };
  // Fluid has NO padding — it fills edge to edge (frame === canvas → scale resolves to 1). A fixed
  // breakpoint keeps a small inset so its frame border reads and it doesn't touch the canvas edges.
  const pad = fluid ? 0 : 24;
  const scale = Math.min(1, (cw - pad * 2) / previewW, (ch - pad * 2) / previewH);
  return { previewW, previewH, scale, tx: (cw - previewW * scale) / 2, ty: (ch - previewH * scale) / 2 };
}

// Last-resort crash surface — self-installing on import. A detached/secondary window's logs may
// never reach the Tauri sink (the IPC/log bridge can be absent in a runtime-created window), so a
// crash there is otherwise invisible — blank window, no logs (#tab-tearoff). This is PURE DOM (no
// Tauri dependency) and registers its handlers at IMPORT time, so it surfaces the real error/stack
// even for module-eval and pre-React failures — provided this module is imported FIRST.

// Browser warnings that fire as window `error` events but are NOT real crashes — never overlay on
// these. "ResizeObserver loop …" is benign (a resize callback caused more layout; the browser just
// deferred a frame) and fires constantly on resizable/observed layouts like the planner split panes.
// "Script error." is the opaque cross-origin placeholder with no actionable detail.
const BENIGN = [
  "ResizeObserver loop limit exceeded",
  "ResizeObserver loop completed with undelivered notifications",
  "Script error.",
];
/** True for harmless browser warnings the overlay must ignore (exported for tests). */
export const isBenign = (msg: string) => BENIGN.some((b) => msg.includes(b));

let shown = false;
function show(title: string, detail: string) {
  if (shown) return; // first real fatal only — don't stack overlays on repeated errors
  shown = true;
  try {
    const el = document.createElement("pre");
    el.setAttribute("data-fatal-overlay", "");
    el.style.cssText =
      "position:fixed;inset:0;z-index:99999;margin:0;padding:16px;overflow:auto;" +
      "background:#181a1e;color:#ff6b6b;font:11px/1.55 ui-monospace,monospace;white-space:pre-wrap;word-break:break-word;";
    el.textContent = `${title}\n\n${detail}`;
    (document.body || document.documentElement).appendChild(el);
  } catch { /* nothing more we can do */ }
}

window.addEventListener("error", (e) => {
  if (isBenign(e.message || "")) return;
  show("Uncaught error", (e.error && (e.error.stack || e.error.message)) || e.message || String(e));
});
window.addEventListener("unhandledrejection", (e) => {
  const r = (e as PromiseRejectionEvent).reason;
  const detail = (r && (r.stack || r.message)) || String(r);
  if (isBenign(detail)) return;
  show("Unhandled promise rejection", detail);
});

// Runtime fault → routed fix loop (#2265, part of #2258). The PURE decision core that turns a project's
// unresolved runtime faults (read from `bsc errors list --unresolved --json`, the errordb store #2260)
// into a bounded, deduped set of fix DISPATCHES — the director then routes each via the existing
// coordination emitters `bsc-issue` (capture) → `bsc-assign` (route to a worker), and clears it on land
// with `bsc errors resolve <fingerprint>`.
//
// Kept React/Tauri-free so the three guarantees the acceptance turns on are unit-tested in isolation:
//   • GATE     — the per-project auto-triage toggle. OFF ⇒ surface-only, dispatch nothing.
//   • DEDUP    — never dispatch the same fingerprint twice while it stays open (idempotent per fault).
//   • RATE-LIMIT — a fault storm (N occurrences, or many faults at once) never exceeds the fan-out cap.
//
// The `useFaultTriage` hook is the thin poll+inject actuator over this; the maintenance/kickoff prose
// (director-protocol.md) primes the director to expect the injected fault and to resolve it on land.

import { clamp } from "@/shared/lib/core/math";

export type FaultLevel = "warn" | "error" | "fatal";

/** The minimal fault shape the triage core reads — a projection of the errordb `Fault` row (#2260). */
export interface FaultLite {
  fingerprint: string;
  level: FaultLevel;
  title: string;
  count: number;
  /** ms epoch when resolved; absent/null ⇒ open. (`--unresolved` lists only opens, but the fn is total
   *  over any list so a mixed list still behaves.) */
  resolvedAt?: number | null;
}

/** Per-project triage policy. `enabled` is the auto-triage toggle; the rest are the rate/severity knobs. */
export interface FaultTriageConfig {
  /** The per-project auto-triage toggle. `false` ⇒ surface-only (default): faults are shown, none routed. */
  enabled: boolean;
  /** Minimum occurrence `count` before a fault is worth routing a fix for. */
  threshold: number;
  /** Minimum severity to route (below it, surface-only). */
  minLevel: FaultLevel;
  /** Fan-out cap: at most this many concurrently dispatched-but-still-open fixes for the project. */
  maxInFlight: number;
  /** Storm guard: at most this many NEW dispatches emitted in a single poll cycle. */
  maxPerCycle: number;
}

/** The default knobs (the toggle itself defaults OFF, supplied separately per project). Conservative:
 *  error+ only, a small fan-out, ≤2 new fixes per cycle — a storm can't spawn a fleet. */
export const DEFAULT_FAULT_TRIAGE: Omit<FaultTriageConfig, "enabled"> = {
  threshold: 1,
  minLevel: "error",
  maxInFlight: 3,
  maxPerCycle: 2,
};

/** One fault chosen for routing this cycle. */
export interface FaultDispatch {
  fingerprint: string;
  level: FaultLevel;
  title: string;
  count: number;
}

export interface FaultTriagePlan {
  /** Faults to route THIS cycle (the director captures + assigns one fix each). */
  dispatch: FaultDispatch[];
  /** The fingerprints now considered handled — carry this back in as `dispatched` next cycle. Pruned to
   *  still-open faults, so a resolved fault drops out (freeing its fan-out slot) and a later recurrence
   *  re-dispatches. */
  nextDispatched: string[];
}

const LEVEL_RANK: Record<FaultLevel, number> = { warn: 1, error: 2, fatal: 3 };
function rank(l: FaultLevel): number {
  return LEVEL_RANK[l] ?? 0;
}

/**
 * Decide which unresolved faults to route this poll cycle. Pure + deterministic.
 *
 * @param faults      the project's fault list (typically `bsc errors list --unresolved --json`).
 * @param dispatched  fingerprints already routed in prior cycles (the dedup ledger; carry `nextDispatched`).
 * @param cfg         the per-project policy (gate + rate/severity knobs).
 *
 * Guarantees:
 *  - GATE: `cfg.enabled === false` ⇒ `dispatch` is empty (surface-only).
 *  - DEDUP: a fingerprint already in `dispatched` (and still open) is never re-dispatched.
 *  - RATE-LIMIT: `dispatch.length ≤ maxPerCycle` AND `inFlight + dispatch.length ≤ maxInFlight`.
 */
export function planFaultDispatch(
  faults: FaultLite[],
  dispatched: Iterable<string>,
  cfg: FaultTriageConfig,
): FaultTriagePlan {
  const already = new Set(dispatched);
  const open = faults.filter((f) => !f.resolvedAt);
  const openFps = new Set(open.map((f) => f.fingerprint));

  // Prune the dedup ledger to fingerprints that are still open. A resolved (or aged-out) fault drops out
  // — this is the resolve→clear path: clearing a fault frees its fan-out slot and lets a genuine
  // recurrence (errordb re-opens the same fingerprint) re-dispatch.
  const pruned = [...already].filter((fp) => openFps.has(fp));

  // GATE: toggle OFF ⇒ surface only. Still return the pruned ledger so turning it on later doesn't
  // re-dispatch faults resolved while it was off.
  if (!cfg.enabled) return { dispatch: [], nextDispatched: pruned };

  // In-flight = dispatched fingerprints still open (fixes routed but not yet resolved). `pruned` is
  // exactly `already ∩ open`, so its size is the live fan-out.
  const inFlight = pruned.length;
  const slots = clamp(cfg.maxInFlight - inFlight, 0, cfg.maxPerCycle);
  if (slots === 0) return { dispatch: [], nextDispatched: pruned };

  const minRank = rank(cfg.minLevel);
  const candidates = open
    .filter((f) => !already.has(f.fingerprint) && f.count >= cfg.threshold && rank(f.level) >= minRank)
    // Worst first (so under a cap the most severe/frequent faults win the slots): severity, then volume,
    // then fingerprint for a stable, deterministic order.
    .sort((a, b) =>
      rank(b.level) - rank(a.level) || b.count - a.count || a.fingerprint.localeCompare(b.fingerprint),
    );

  const chosen = candidates.slice(0, slots);
  return {
    dispatch: chosen.map((f) => ({ fingerprint: f.fingerprint, level: f.level, title: f.title, count: f.count })),
    nextDispatched: [...pruned, ...chosen.map((f) => f.fingerprint)],
  };
}

/** Count of unresolved faults in a list — the number the Glance inspector shows. */
export function unresolvedCount(faults: FaultLite[]): number {
  return faults.reduce((n, f) => (f.resolvedAt ? n : n + 1), 0);
}

/** The single worst OPEN fault — highest severity, then highest volume, then a stable fingerprint tie-
 *  break — or null when nothing is open. Drives the Glance health dot's colour + reason text (#2541). */
export function worstFault(faults: FaultLite[]): FaultLite | null {
  return faults
    .filter((f) => !f.resolvedAt)
    .sort((a, b) => rank(b.level) - rank(a.level) || b.count - a.count || a.fingerprint.localeCompare(b.fingerprint))[0] ?? null;
}

// `faultDispatchPrompt` was DELETED here (#coord-prefix-names-the-sender): it built a
// `[fault-triage] ...` string for useFaultTriage, which no longer injects, and had no other
// reference. The classification above still runs and still records — observing is not dispatching.

// The feature list (#…): the authoritative artifact of the Features stage. Each entry is a
// capability AND a fleet stream, carrying a dependency DAG (`dependsOn`). The planner writes them to
// plan.db (surfaced by the poll as the `features` section); the Features board renders it and the
// gate signal reads it. Issues are generated FROM features at publish — `featuresToPlanIssues`.
// Pure + tolerant of partial/malformed input — no React/Tauri.

import type { PlanIssue } from "@/features/planner/issues/planIssues";
import { slugify } from "@/shared/lib/core/format";

export interface PlanFeature {
  /** Stable slug / stream id (kebab-case). */
  slug: string;
  /** Capability name ("Invite teammates", "Geometry kernel"). Not just user-facing — a feature can
   *  be foundational (others depend on it). */
  name: string;
  /** What it does + when, in the user's terms. */
  behavior?: string;
  /** Done-when checklist a building agent verifies against. */
  acceptance?: string[];
  /** The build approach — the shape of the solution. */
  approach?: string;
  /** Specific libraries / services / frameworks. */
  tools?: string[];
  /** Feature slugs this feature builds on — the coarse roadmap DAG (#plan-db). Must stay acyclic. */
  dependsOn?: string[];
  /** What it stores/reads. */
  data?: string;
  /** The fleet stream that owns it (defaults to the slug — a feature IS a stream). */
  stream?: string;
  /** Algorithm impl ids from the GLOBAL `bsc graph` store this capability needs (#4080) — the plan →
   *  algorithms-graph edge, so a worker is pointed at the reference implementation instead of re-coding
   *  it. DECLARED intent (the planner names them at Features time), not derived fact. */
  requires?: string[];
}

function str(v: unknown): string | undefined {
  return typeof v === "string" && v.trim() ? v.trim() : undefined;
}
function strArray(v: unknown): string[] | undefined {
  if (!Array.isArray(v)) return undefined;
  const out = v.filter((x): x is string => typeof x === "string" && x.trim().length > 0).map((s) => s.trim());
  return out.length ? out : undefined;
}
/** Parse `features.json` (a JSON array of feature objects) into a clean list. Tolerant: bad JSON
 *  ⇒ []; entries missing both slug and name are dropped; duplicate slugs are de-duped; a missing
 *  slug is derived from the name, and stream defaults to the slug. */
export function parseFeaturesFile(raw: string): PlanFeature[] {
  if (!raw.trim()) return [];
  let data: unknown;
  try { data = JSON.parse(raw); } catch { return []; }
  if (!Array.isArray(data)) return [];
  const out: PlanFeature[] = [];
  const seen = new Set<string>();
  for (const item of data) {
    if (!item || typeof item !== "object") continue;
    const o = item as Record<string, unknown>;
    const name = str(o.name) ?? "";
    const slug = str(o.slug) ?? slugify(name, 60);
    if (!slug || !name || seen.has(slug)) continue;
    seen.add(slug);
    out.push({
      slug, name,
      behavior: str(o.behavior),
      acceptance: strArray(o.acceptance),
      approach: str(o.approach),
      tools: strArray(o.tools),
      dependsOn: strArray(o.dependsOn ?? o.depends_on),
      // Both spellings, like `dependsOn` — the store emits camelCase, but a hand-written or older
      // payload may carry snake, and silently dropping it would lose the reference entirely.
      requires: strArray(o.requires ?? o.requires_),
      data: str(o.data),
      stream: str(o.stream) ?? slug,
    });
  }
  return out;
}

/** A feature is fully defined once it has a name, behavior, and ≥1 acceptance criterion — enough
 *  for the Plan stage to decompose it into agent-ready issues. */
export function featureDefined(f: PlanFeature): boolean {
  return !!f.name && !!f.behavior && (f.acceptance?.length ?? 0) > 0;
}

/** The Features-gate summary: how many capabilities exist, and whether ALL are fully defined. */
export function featuresSummary(features: PlanFeature[]): { count: number; allConfirmed: boolean } {
  return { count: features.length, allConfirmed: features.length > 0 && features.every(featureDefined) };
}

/**
 * Whether the Features stage may COMPLETE (#plan-db): every feature populated AND the user has
 * confirmed the set. The user-confirm is the boundary that stops a single fully-populated feature
 * from auto-advancing the stage — the planner works titles-first, then the user confirms at the end.
 */
export function featuresGateComplete(summary: { allConfirmed: boolean }, userConfirmed: boolean): boolean {
  return summary.allConfirmed && userConfirmed;
}

/** Whether to OFFER the one-click confirm: every feature is populated but the user hasn't confirmed
 *  yet. While features are still being populated, no confirm is offered (the gate stays closed). */
export function featuresAwaitingConfirm(summary: { allConfirmed: boolean }, userConfirmed: boolean): boolean {
  return summary.allConfirmed && !userConfirmed;
}

/** The extra prose (beyond acceptance/owns/dependsOn, which `renderIssueBody` adds) for a feature's
 *  published issue: its behavior + approach + data + tools. */
function featureBody(f: PlanFeature): string | undefined {
  const parts: string[] = [];
  if (f.behavior?.trim()) parts.push(f.behavior.trim());
  if (f.approach?.trim()) parts.push(`## Approach\n${f.approach.trim()}`);
  if (f.data?.trim()) parts.push(`## Data\n${f.data.trim()}`);
  if (f.tools?.length) parts.push(`## Tools\n${f.tools.map((t) => `- ${t}`).join("\n")}`);
  return parts.join("\n\n").trim() || undefined;
}

/**
 * Project features into the issues published from them (#plan-db) — ONE issue per feature. Issues
 * aren't authored during planning; this is what publish (and the structure card) generate from the
 * DB features. The feature's slug becomes the issue `ref`, so a `dependsOn` between features is a
 * `dependsOn` between issues; acceptance carries over; behavior/approach/data/tools become the
 * body. `owns`/`labels` are left to the fleet (assigned to the stream in the Permissions stage).
 */
export function featuresToPlanIssues(features: PlanFeature[]): PlanIssue[] {
  return features.map((f) => ({
    ref: f.slug,
    title: f.name || f.slug,
    acceptance: f.acceptance ?? [],
    owns: [],
    dependsOn: f.dependsOn ?? [],
    labels: [],
    stream: f.stream ?? f.slug,
    body: featureBody(f),
  }));
}

/**
 * Find a cycle in the feature dependency DAG (#plan-db) — a cycle is a planning deadlock and holds
 * the Features gate. Returns the slugs on the first cycle found (e.g. `["a","b","a"]`) or `[]` when
 * acyclic. Edges to unknown slugs are ignored (a dangling dep isn't a cycle). Iterative-style DFS
 * with a colour map; self-deps (`a → a`) count.
 */
export function featureDependencyCycle(features: PlanFeature[]): string[] {
  const bySlug = new Map(features.map((f) => [f.slug, f]));
  const color = new Map<string, 1 | 2>(); // 1 = on the current path, 2 = fully explored
  const path: string[] = [];
  let found: string[] = [];

  const visit = (slug: string): boolean => {
    if (color.get(slug) === 2) return false;
    if (color.get(slug) === 1) {
      found = path.slice(path.indexOf(slug)).concat(slug); // back-edge → extract the cycle
      return true;
    }
    color.set(slug, 1);
    path.push(slug);
    for (const dep of bySlug.get(slug)?.dependsOn ?? []) {
      if (bySlug.has(dep) && visit(dep)) return true;
    }
    path.pop();
    color.set(slug, 2);
    return false;
  };

  for (const f of features) {
    if (color.get(f.slug) !== 2 && visit(f.slug)) break;
  }
  return found;
}

/// Recursive radix-2 Cooley–Tukey FFT over complex samples `(re, im)`.
/// `input.len()` must be a power of two.
pub fn fft(input: &[(f64, f64)]) -> Vec<(f64, f64)> {
    let n = input.len();
    if n <= 1 {
        return input.to_vec();
    }
    assert!(n & (n - 1) == 0, "fft: length must be a power of two");
    let even = fft(&input.iter().step_by(2).copied().collect::<Vec<_>>());
    let odd = fft(&input.iter().skip(1).step_by(2).copied().collect::<Vec<_>>());
    let mut out = vec![(0.0, 0.0); n];
    for k in 0..n / 2 {
        let angle = -2.0 * std::f64::consts::PI * k as f64 / n as f64;
        let (tw_re, tw_im) = (angle.cos(), angle.sin());
        let (o_re, o_im) = odd[k];
        let t = (tw_re * o_re - tw_im * o_im, tw_re * o_im + tw_im * o_re);
        let (e_re, e_im) = even[k];
        out[k] = (e_re + t.0, e_im + t.1);
        out[k + n / 2] = (e_re - t.0, e_im - t.1);
    }
    out
}

/// The nth Fibonacci number (0-indexed: F0 = 0, F1 = 1), iterated bottom-up.
pub fn fibonacci(n: u64) -> u64 {
    if n < 2 {
        return n;
    }
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 2..=n {
        let next = a + b;
        a = b;
        b = next;
    }
    b
}

export function fibonacci(n: number): number {
  if (n < 2) return n;
  let a = 0,
    b = 1;
  for (let i = 2; i <= n; i++) {
    const next = a + b;
    a = b;
    b = next;
  }
  return b;
}

// File-intake pipeline core (#604). Pure helpers for the drag-and-drop intake: classify
// a dropped file into a coarse KIND (a routing hint for the planner) and build the
// `intake.json` manifest the planner reads to route files to the right repo/stage.
// Free of React/Tauri so it's unit-testable; the drop-zone screen + Rust writes wrap it.

/** Coarse classification — a hint, not a contract. The planner does the real routing. */
export type IntakeKind = "image" | "vector" | "markup" | "style" | "component" | "data" | "doc" | "other";

/** One staged file in the intake manifest. */
export interface IntakeEntry {
  /** Original file name (also the relpath under `.intake/`). */
  name: string;
  /** Coarse kind (routing hint). */
  kind: IntakeKind;
  /** Byte size. */
  size: number;
  /** MIME type if the browser provided one. */
  mime?: string;
  /** #2097 — content hash of the staged file, so a re-drop of an edited file is detectable. */
  hash: string;
  /** #2097 — the `hash` value at the last time this file was ROUTED to the project (on triage).
   *  Undefined ⇒ never routed. `hash !== routedHash` ⇒ new or changed since the last route. */
  routedHash?: string;
}

const EXT_KIND: Record<string, IntakeKind> = {
  png: "image", jpg: "image", jpeg: "image", gif: "image", webp: "image", avif: "image", bmp: "image", ico: "image",
  svg: "vector",
  html: "markup", htm: "markup",
  css: "style", scss: "style", sass: "style", less: "style",
  jsx: "component", tsx: "component", vue: "component", svelte: "component",
  json: "data", yaml: "data", yml: "data", toml: "data", csv: "data",
  md: "doc", mdx: "doc", txt: "doc", pdf: "doc",
};

/** Classify a file by extension first, then MIME family. Unknown ⇒ "other". */
export function classifyFile(name: string, mime?: string): IntakeKind {
  const ext = name.includes(".") ? name.slice(name.lastIndexOf(".") + 1).toLowerCase() : "";
  if (ext && EXT_KIND[ext]) return EXT_KIND[ext];
  if (mime) {
    if (mime === "image/svg+xml") return "vector";
    if (mime.startsWith("image/")) return "image";
    if (mime === "text/html") return "markup";
    if (mime === "text/css") return "style";
    if (mime === "application/json") return "data";
    if (mime.startsWith("text/")) return "doc";
  }
  return "other";
}

/** Whether a file should be staged via the binary (base64) write vs text. Images,
 *  vectors-as-binary, fonts, pdfs, and anything non-text go binary; markup/style/
 *  component/data/doc are text. */
export function isBinaryKind(kind: IntakeKind): boolean {
  return kind === "image" || kind === "other";
}

/** A fast, deterministic content hash (FNV-1a, 32-bit → hex) — enough to detect a file changed
 *  between drops; not cryptographic. Text files hash their text; binary files hash their base64. */
export function hashContent(content: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < content.length; i++) {
    h ^= content.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}

/** Build one manifest entry from a file's metadata + its content hash. */
export function intakeEntry(name: string, size: number, hash: string, mime?: string): IntakeEntry {
  return { name, kind: classifyFile(name, mime), size, hash, ...(mime ? { mime } : {}) };
}

/** Merge new entries into an existing manifest, de-duping by name (newest content wins), preserving
 *  order (existing first, then new names). A re-dropped file keeps its prior `routedHash` so the
 *  change vs the last route is preserved (a new `hash` different from `routedHash` ⇒ needs routing). */
export function mergeIntake(existing: IntakeEntry[], added: IntakeEntry[]): IntakeEntry[] {
  const byName = new Map(existing.map((e) => [e.name, e]));
  for (const e of added) {
    const prev = byName.get(e.name);
    byName.set(e.name, prev ? { ...e, routedHash: prev.routedHash } : e);
  }
  return [...byName.values()];
}

/** The staged files that are new or changed since their last route (`hash !== routedHash`). */
export function changedDesignFiles(entries: IntakeEntry[]): IntakeEntry[] {
  return entries.filter((e) => e.hash !== e.routedHash);
}

/** Stamp every entry as routed at its current content (`routedHash = hash`) — called after a route. */
export function markRouted(entries: IntakeEntry[]): IntakeEntry[] {
  return entries.map((e) => ({ ...e, routedHash: e.hash }));
}

/** #2097 — the design-routing lead prepended to a triage prompt when design files changed, mirroring
 *  `renderTriageDelta`. Empty when nothing changed (so triage does its normal issue pass untouched).
 *  `routeInstruction` is the UI stage's `routePrompt` (the classify-and-route directive). */
export function renderDesignDelta(changed: IntakeEntry[], routeInstruction: string): string {
  if (changed.length === 0) return "";
  const names = changed.map((e) => e.name).join(", ");
  return (
    `DESIGN ROUTING: ${changed.length} design file(s) changed since the last route — ${names}. ` +
    `Route ONLY these changed files (the rest are already in place): ${routeInstruction} ` +
    `Then continue with the issue triage below. `
  );
}

/** Serialize the manifest exactly as it's stored (stable, pretty, trailing newline). */
export function serializeIntake(entries: IntakeEntry[]): string {
  return JSON.stringify(entries, null, 2) + "\n";
}

/** Parse a stored `intake.json` tolerantly (bad/blank ⇒ []). */
export function parseIntake(raw: string): IntakeEntry[] {
  if (!raw || !raw.trim()) return [];
  try {
    const j: unknown = JSON.parse(raw);
    if (!Array.isArray(j)) return [];
    return j.filter((e): e is IntakeEntry => !!e && typeof e === "object" && typeof (e as IntakeEntry).name === "string")
      .map((e) => ({
        name: e.name, kind: e.kind ?? "other", size: typeof e.size === "number" ? e.size : 0,
        hash: typeof e.hash === "string" ? e.hash : "", ...(e.routedHash ? { routedHash: e.routedHash } : {}),
        ...(e.mime ? { mime: e.mime } : {}),
      }));
  } catch {
    return [];
  }
}

/** Where intake stages files within the project hub — a visible `design/` directory so
 *  dropped design assets are easy to find (#829), not a hidden `.intake/`. */
export const INTAKE_DIR = "design";
export const INTAKE_MANIFEST = "design/intake.json";

/** The built-in pipeline id (matches its PIPELINE_LIB entry + screen registration). */
export const FILE_INTAKE_ID = "file-intake";

// The file-intake "Route" instruction now lives in the UI stage's DATA
// (`src-tauri/data/stages/ui.json` → `routePrompt`), read via `STAGE_DEFS.ui.routePrompt` — not
// hardcoded here, so the prompt is editable alongside the rest of the stage (#604).

// Resolve the GitHub assignee for a published issue (#847). A worker/stream is an agent
// session, not a GitHub user, so the assignee is a human/collaborator login configured per
// stream (`AgentStream.assignee`), falling back to the account running the publish. The
// `stream:<id>` label stays as the agent-ownership marker; this drives the first-class
// GitHub assignee field. Pure + unit-tested; the publish flow applies it best-effort.

import type { AgentStream } from "@/features/planner/fleet/planFleet";

/**
 * The GitHub login to assign an issue to, given its owning stream id.
 *
 * - The owning stream's configured `assignee`, when set and non-empty.
 * - Otherwise the publishing account (`viewerLogin`) — so issues are never left unassigned.
 * - `null` only when there's no stream login AND no viewer login (assignment is then skipped).
 *
 * Trims whitespace; an all-whitespace stream assignee is treated as unset.
 */
export function resolveIssueAssignee(
  streamId: string | undefined,
  streams: readonly AgentStream[],
  viewerLogin: string,
): string | null {
  const stream = streamId ? streams.find((s) => s.id === streamId) : undefined;
  const streamLogin = stream?.assignee?.trim();
  if (streamLogin) return streamLogin;
  const viewer = viewerLogin.trim();
  return viewer || null;
}

// Fleet cost & energy (#2237) — pure aggregation of per-pane token/cost telemetry over the live worker
// roster. COST is real (priced from each transcript's actual model by `bsc logs cost`); ENERGY is a
// clearly-labeled DIRECTIONAL ESTIMATE (tokens × a per-model-tier coefficient), never metered.
//
// The groupBy-and-total is the generic `groupTotals` (#3465) — the reusable "roll rows up per key +
// overall in one pass" algorithm this panel was a source for. The Wh-per-token energy estimate is
// likewise the generic `estimateEnergyWh` node (#3462, `llmEnergy.ts`) — this panel was its source,
// so the local copy is gone and it's delegated + re-exported (#3607).
import { groupTotals } from "@/shared/lib/algorithms/groupTotals";
import { estimateEnergyWh } from "@/shared/lib/algorithms/llmEnergy";

/** The per-pane rollup shape from `bsc logs cost --full` (subset used here; keys = the Rust struct). */
export interface TokenUsage {
  pane: string;
  model: string;
  input_tokens: number;
  output_tokens: number;
  cache_creation_tokens: number;
  cache_read_tokens: number;
  cost_usd: number;
}

/** Minimal roster shape — just the pane id + display name (LiveWorker is a superset). */
export interface CostWorkerLike { id: string; name: string }

export interface WorkerCost {
  id: string; name: string; model: string;
  input: number; output: number; cache: number; totalTokens: number;
  costUsd: number;
  /** Estimated Wh — directional, not metered. */
  energyWh: number;
}

export interface FleetCost {
  workers: WorkerCost[];
  totalTokens: number; totalInput: number; totalOutput: number; totalCache: number;
  totalCostUsd: number;
  /** Estimated total Wh (directional). */
  totalEnergyWh: number;
  byModel: Array<{ model: string; tokens: number; costUsd: number; energyWh: number }>;
  hasData: boolean;
}

// ── Energy estimate ────────────────────────────────────────────────────────────
// `estimateEnergyWh` is the generic algorithms-graph node (`llmEnergy.ts`, #3462): tokens × a
// per-model-tier coefficient, directional not metered. It's re-exported here so this panel and its
// test still resolve it from one place, while the single implementation lives in the graph (#3607).
export { estimateEnergyWh };

/** Average grid carbon intensity (kg CO₂ per kWh) — a rough global figure for the CO₂ estimate. */
export const CO2_KG_PER_KWH = 0.40;

/** Join per-pane usage to the live roster and roll up per-worker + fleet totals + a by-model split. */
export function aggregateFleetCost(workers: CostWorkerLike[], usage: Map<string, TokenUsage>): FleetCost {
  const list: WorkerCost[] = [];
  for (const w of workers) {
    const u = usage.get(w.id);
    if (!u) continue;
    const cache = u.cache_creation_tokens + u.cache_read_tokens;
    list.push({
      id: w.id, name: w.name, model: u.model,
      input: u.input_tokens, output: u.output_tokens, cache,
      totalTokens: u.input_tokens + u.output_tokens + cache,
      costUsd: u.cost_usd,
      energyWh: estimateEnergyWh(u.model, u.input_tokens, u.output_tokens),
    });
  }
  list.sort((a, b) => b.costUsd - a.costUsd);

  // The groupBy-by-model + every fleet total is the generic `groupTotals` (#3465), one pass over the
  // rolled-up rows — so a fleet total can never disagree with the sum of its per-model breakdown. The
  // JOIN + per-row rollup above (usage → worker cost) stays here: it is the app-specific projection,
  // and a graph algorithm cannot know a TokenUsage.
  const { totals, groups } = groupTotals(list, (c) => c.model, {
    totalTokens: (c) => c.totalTokens,
    totalInput: (c) => c.input,
    totalOutput: (c) => c.output,
    totalCache: (c) => c.cache,
    totalCostUsd: (c) => c.costUsd,
    totalEnergyWh: (c) => c.energyWh,
  });

  return {
    workers: list,
    ...totals,
    byModel: groups
      .map((g) => ({ model: g.key, tokens: g.totals.totalTokens, costUsd: g.totals.totalCostUsd, energyWh: g.totals.totalEnergyWh }))
      .sort((a, b) => b.costUsd - a.costUsd),
    hasData: list.length > 0,
  };
}

// fleetDirectorBridge (#architect-creates-a-director-with-discovery) — decide what a
// `bsc fleet director new` request does to the store.
//
// Pure on purpose: the DECISION is testable without Tauri or a rendered app, and the listener stays a
// thin adapter — the same split `fleetWakeBridge` and `systemSessionBridge` use.
//
// WHY IT BUILDS A FleetPlan INSTEAD OF PLACING A PANE ITSELF
// A director is not just a pane: it is a cwd at the project hub, a `director-kickoff.md` startup doc,
// a checkpoint doc, a `director` role, a director DRIVE and a director MODE, on a pane id the rest of
// the app already knows how to find. All of that lives in `fleetStartProject`, which is exercised by
// every real fleet launch. Reimplementing the subset here would be a second launch path that drifts
// from the first — the "superseded but never removed" duplication this codebase has paid for more
// than once. So this constructs the SMALLEST honest FleetPlan (a director, no streams) and hands it
// to the path that already works.
//
// The plan is a launch input, not a stored one: nothing here writes plan.db, so a project whose real
// fleet has ten streams keeps them. Launching the full fleet later rebuilds the tab in place.

// The deep type path, matching `AppBanners` (the other shell-side fleet launcher): a cross-feature
// `import type` is allowed, and `FleetPlan` is not on the planner barrel.
import type { FleetPlan } from "@/features/planner/fleet/planFleet";

/** The request as it arrives from Rust (`bsc://fleet-director`). */
export interface DirectorRequest {
  /** Correlates the ack. */
  id: string;
  projectKey: string;
  /** `<projectKey>:director` — resolved in Rust so create/list/brief share one spelling. */
  paneId: string;
  /** The absolute hub path, resolved in Rust (#905) so the launch never depends on the
   *  async-loaded `bscBaseDir` mirror — an empty one drops the session at the user root. */
  hubPath: string;
}

/** What we send back via `fleet_director_ack`. */
export interface DirectorAck {
  id: string;
  error?: string;
  created: boolean;
}

/**
 * The store surface this needs — narrowed so the pure fn stays decoupled from the slice.
 */
export interface DirectorDeps {
  /** The real `fleetStartProject`. */
  fleetStartProject: (
    projectName: string,
    fleet: FleetPlan,
    projectKey: string,
    paths?: { hubPath?: string; worktreePaths?: Record<string, string> },
  ) => unknown;
}

/**
 * The smallest honest fleet: a director and nothing else.
 *
 * `recommended: 0` and an empty `streams` are the TRUTH here, not placeholders — this launch is not a
 * fleet, and claiming a worker count would put a number on the tab that no session backs. `reasoning`
 * is carried because it is what a later reader sees when asking why this tab has one pane.
 */
export function directorOnlyPlan(): FleetPlan {
  return {
    recommended: 0,
    reasoning:
      "Director created on its own by the architect (bsc fleet director new) — no worker streams " +
      "were launched with it.",
    streams: [],
    director: { enabled: true },
  };
}

/**
 * Apply one director-create request. Never throws — every path produces an ack, because silence would
 * strand the Rust waiter until its timeout and surface as "the frontend did not create the director",
 * sending someone to debug the wrong thing.
 *
 * Rust has already settled everything checkable before this runs: the project exists, no director is
 * live, and the kickoff is on disk. What is left is the launch.
 */
export function applyDirectorNew(req: DirectorRequest, deps: DirectorDeps): DirectorAck {
  const { id } = req;
  const projectKey = (req.projectKey ?? "").trim();
  if (!projectKey) return { id, error: "fleet director: no project key", created: false };

  try {
    // The project's own key doubles as its display name here. `fleetStartProject` uses the first
    // argument only to NAME the tab (`<name> · build`), and the key is what the architect asked for —
    // a prettier title would have to come from a store read this pure function deliberately avoids.
    deps.fleetStartProject(projectKey, directorOnlyPlan(), projectKey, { hubPath: req.hubPath || undefined });
    return { id, created: true };
  } catch (err) {
    return {
      id,
      error: `fleet director: the launch threw: ${err instanceof Error ? err.message : String(err)}`,
      created: false,
    };
  }
}

// Fleet GitHub-derived panels (#415) — PURE mappers over GitHub REST payloads
// aggregated across the fleet's repos: throughput (issues landed vs PRs merged),
// the director merge queue (open PRs + CI status), and time-to-land (merged-PR
// durations). Reuses the day-bucketing + review-latency helpers from
// repoPulseLive. Framework-free + unit-tested; fetch orchestration is in
// hooks/useFleetGithub.
import { mapReviewLatency, medianLatencyH, type GhPull } from "@/shared/lib/github/repoPulseLive";
import { orderByRank } from "@/shared/lib/algorithms/orderByRank";
import { windowedTally } from "@/shared/lib/algorithms/windowedTally";
import type { GhIssueItem } from "@/shared/lib/github/types";

export type { GhPull };
// The issue-row shape (the `issues` endpoint also returns PRs — rows with `pull_request` set are
// PRs, excluded from "issues"). Canonical now lives in shared/lib/github/types (#1528); re-exported
// so existing importers (useFleetGithub, the tests) keep their `from "@/shared/lib/github/fleetGithub"` import.
export type { GhIssueItem };

/** Combined commit status for a PR head (`commits/{sha}/status`). */
export type GhStatusState = "success" | "pending" | "failure" | "error" | string;

export interface ThroughputSlice { labels: string[]; landed: number[]; merged: number[] }

/**
 * Issues landed (closed, non-PR) vs PRs merged, per day over the window.
 *
 * The bucketing is the generic `windowedTally` (#3465), which is what guarantees the two series are
 * ALIGNED — one shared window, one entry per label in both. Tallying each series separately (as this
 * did) leaves nothing checking that they line up, and a chart layering them cannot tell.
 */
export function mapThroughput(pulls: GhPull[], issues: GhIssueItem[], days: number, now: Date): ThroughputSlice {
  const { labels, series } = windowedTally(
    {
      landed: issues.filter(i => !i.pull_request && i.closed_at).map(i => i.closed_at),
      merged: pulls.map(p => p.merged_at),
    },
    days,
    now,
  );
  return { labels, landed: series.landed, merged: series.merged };
}

/** A PR awaiting integration, with its repo + CI state. */
export interface MergeQueueInput {
  pr: GhPull;
  repo: string;
  /** combined commit status for the head, or null if unknown. */
  status: GhStatusState | null;
}
export interface MergeQueueRow {
  pr: string;
  repo: string;
  title: string;
  state: "green" | "running" | "blocked" | "draft";
  checks: string;
}

/** The merge queue's ATTENTION order (#3465): ready-but-failing first (needs a human), then running,
 *  then green, then drafts. Declared as data + applied by the generic `orderByRank` — it was a chain
 *  of magic numbers inside a comparator, where this domain decision could not be read as a list. */
const MERGE_QUEUE_ORDER: MergeQueueRow["state"][] = ["blocked", "running", "green", "draft"];

/** Map open PRs (+ CI status) to merge-queue rows. Draft PRs read "draft";
 *  otherwise green/running/blocked from the combined commit status. */
export function mapMergeQueue(items: MergeQueueInput[]): MergeQueueRow[] {
  const rows = items.map(({ pr, repo, status }): MergeQueueRow => {
    const state: MergeQueueRow["state"] =
      pr.draft ? "draft"
      : status === "success" ? "green"
      : status === "pending" || status === null ? "running"
      : "blocked";
    const checks = pr.draft ? "draft" : status ?? "—";
    return { pr: `#${pr.number}`, repo, title: pr.title, state, checks };
  });
  return orderByRank(rows, (r) => r.state, MERGE_QUEUE_ORDER);
}

// Re-export the shared latency mappers so the Fleet hook imports from one place.
export { mapReviewLatency as mapTimeToLand, medianLatencyH };

export interface FleetThroughputKpis {
  landedToday: number;
  prsMergedWeek: number;
  avgLandH: number;
}
export function deriveThroughputKpis(throughput: ThroughputSlice, pulls: GhPull[], now: Date): FleetThroughputKpis {
  const within = (iso: string | null, ms: number) => !!iso && (now.getTime() - new Date(iso).getTime()) <= ms;
  return {
    landedToday: throughput.landed[throughput.landed.length - 1] ?? 0,
    prsMergedWeek: pulls.filter(p => within(p.merged_at, 7 * 86_400_000)).length,
    avgLandH: medianLatencyH(pulls.filter(p => within(p.merged_at, 14 * 86_400_000))),
  };
}

// Fleet health & errors (#2240) — a pure unifier of the fleet's ERROR signals that exist but weren't
// surfaced: permission denials (`bsc logs perm`), coordination stalls/deadlocks (`coordinationSummary`),
// warden quarantine trips, and auto-end needs-attention/blocked verdicts. Produces one recent-errors
// feed + counts. No fabrication — every item is a real recorded signal.
//
// The merge itself is the generic `mergeFeeds` (#3465) — the reusable "K streams → one recent-first
// feed with a pinned class + per-kind counts" algorithm this panel was the source for.
import { mergeFeeds, feedStream } from "@/shared/lib/algorithms/streamMerge";

/** One `bsc logs perm --json` row (subset). `summary` is already human-readable (e.g. "scope block src/App.tsx"). */
export interface PermEvent { ts_ms: number; session: string; summary: string }
/** Warden quarantine (store `quarantinedPanes` value). */
export interface QuarantineLike { streamId: string; summary: string; at: number; acknowledged?: boolean }
/** Auto-end verdict (store `endedPanes` value). */
export interface EndedLike { state: "done" | "needs-attention" | "blocked"; streamId: string; summary: string; at: number }
/** A coordination BlockedView (subset) — stalled = a failed dep; deadlocked = a wait-for cycle. */
export interface BlockedLike { session: string; stalled: boolean; deadlocked: boolean; deps: { ref: string; status: string }[] }

export type HealthKind = "deadlock" | "stalled" | "quarantine" | "blocked" | "attention" | "denied";

export interface HealthItem {
  kind: HealthKind;
  /** The worker/agent the item is about (resolved name, else the raw id). */
  label: string;
  /** The one-line reason. */
  detail: string;
  /** Sort key (epoch ms; live coord issues use Infinity so they pin to the top). */
  sortKey: number;
  /** true = red (error), false = amber (warning). */
  danger: boolean;
}

export interface FleetHealth {
  items: HealthItem[];
  counts: Record<HealthKind, number>;
  total: number;
  hasIssues: boolean;
}

/** Display label per kind. */
export const HEALTH_LABEL: Record<HealthKind, string> = {
  deadlock: "deadlock", stalled: "stalled", quarantine: "quarantined",
  blocked: "blocked", attention: "needs attention", denied: "denied",
};

export interface HealthInput {
  perm: PermEvent[];
  quarantined: Record<string, QuarantineLike>;
  ended: Record<string, EndedLike>;
  blocked: BlockedLike[];
  /** paneId → worker display name, to humanize ids. */
  nameByPane: Map<string, string>;
  /** Cap on the number of recent permission denials shown. Default 8. */
  permLimit?: number;
}

/** The kind set, in badge order — passed to `mergeFeeds` so `counts` carries a zero for every one. */
const HEALTH_KINDS: HealthKind[] = ["deadlock", "stalled", "quarantine", "blocked", "attention", "denied"];

/** The per-item payload the feed carries beyond `{ kind, pinned, sortKey }`. */
type HealthPayload = { label: string; detail: string; danger: boolean };

/**
 * Merge every error signal into one recent-first feed + counts. Pure.
 *
 * Delegates the merge to the generic `mergeFeeds` (#3465): this function is now the DOMAIN part —
 * which signal sources exist and how each projects to a kind/label/detail — while the ordering, the
 * pin-above-recency rule, and the per-kind count are the shared algorithm. The stalls/deadlocks are
 * `pinned` (a live problem sits above the time sort), replacing the `sortKey: Infinity` sentinel the
 * hand-written version used, which left two live items with no defined order between them.
 */
export function buildFleetHealth(input: HealthInput): FleetHealth {
  const name = (id: string, fallback: string) => input.nameByPane.get(id) ?? fallback;
  const recentPerm = [...input.perm].sort((a, b) => b.ts_ms - a.ts_ms).slice(0, input.permLimit ?? 8);

  const { items, counts, total, hasItems } = mergeFeeds<HealthKind, HealthPayload>(
    [
      // Coordination stalls / deadlocks — LIVE, so they PIN above the time sort.
      feedStream(input.blocked, (b) => {
        if (!b.stalled && !b.deadlocked) return null;
        const failed = b.deps.filter((d) => d.status === "failed").map((d) => d.ref).join(", ");
        return {
          kind: b.deadlocked ? "deadlock" : "stalled", pinned: true, sortKey: 0,
          label: name(b.session, b.session),
          detail: b.deadlocked ? "in a wait-for cycle — no producer will satisfy it" : `stalled on ${failed || "a failed dependency"}`,
          danger: true,
        };
      }),
      // Warden quarantine trips.
      feedStream(Object.entries(input.quarantined), ([pane, q]) => ({
        kind: "quarantine", pinned: false, sortKey: q.at, label: name(pane, q.streamId), detail: q.summary, danger: true,
      })),
      // Auto-end verdicts that need eyes (done is not an error → dropped by returning null).
      feedStream(Object.entries(input.ended), ([pane, e]) =>
        e.state === "done" ? null : {
          kind: e.state === "blocked" ? "blocked" : "attention", pinned: false, sortKey: e.at,
          label: name(pane, e.streamId), detail: e.summary, danger: e.state === "blocked",
        }),
      // Recent permission denials.
      feedStream(recentPerm, (p) => ({
        kind: "denied", pinned: false, sortKey: p.ts_ms, label: name(p.session, p.session), detail: p.summary, danger: false,
      })),
    ],
    HEALTH_KINDS,
  );

  return { items, counts, total, hasIssues: hasItems };
}

// Resolving a fleet's issue states WITHOUT a React render (#4103).
//
// #4102 put the GitHub overlay behind `useFleetIssueState`, a hook — which is right for the graph, and
// useless to the three places that decide whether a worker is FINISHED: the progress-gated relaunch
// (`resumeProjectFleet`), the dependency gate (`useFleetHeld`) and the publish-time prune
// (`usePlanPublish`). Those run in async callbacks, not renders.
//
// So the fetch lives here as a plain async function and the hook sits on top of it. One query builder,
// one parse, two entry points — a second copy would be the thing that eventually disagrees about
// whether an issue is closed.
import { githubGraphql } from "@/shared/lib/github/github";
import { groupRefsByRepo, buildIssueStateQuery, parseIssueStates } from "@/features/glance/lib/issueStateQuery";
import { normalizeRef } from "@/features/glance/lib/fleetPlanProgress";

/** Same window the hook uses — served from the backend's ETag cache, so the gate and the graph do not
 *  each spend a call. */
const MAX_AGE_SECS = 120;

/** A stream as this needs it — structural, so a caller does not have to hand over a whole `AgentStream`. */
export interface RefBearingStream {
  repo?: string;
  issues?: readonly string[];
}

/**
 * The refs GitHub reports CLOSED, returned in each stream's OWN ref spelling.
 *
 * That spelling is the whole point. `streamComplete` asks `stream.issues.every((r) => done.has(r))`,
 * and a stream stores `"#3898"` while the GitHub response carries the number `3898`. A set of
 * normalized refs would therefore match NOTHING and every stream would read as unfinished — the exact
 * silent failure #4103 is about, reintroduced from the other side. Emitting the original strings makes
 * the formats agree by construction rather than by convention.
 *
 * Returns an EMPTY set on any failure (no token, offline, a GraphQL error). That is deliberate and
 * matches the pre-existing rule these gates already follow: absent evidence must under-report
 * completion, never over-report it. Claiming a stream finished because a fetch failed would skip a
 * worker that still has work.
 */
export async function resolveClosedRefs(
  streams: readonly RefBearingStream[],
): Promise<Set<string>> {
  const out = new Set<string>();
  const query = buildIssueStateQuery(groupRefsByRepo(streams));
  if (!query) return out;                    // nothing addressable ⇒ no request at all
  try {
    const states = parseIssueStates(await githubGraphql<unknown>(query, null, { maxAgeSecs: MAX_AGE_SECS }));
    for (const s of streams) {
      for (const ref of s.issues ?? []) {
        if (states.get(normalizeRef(ref)) === true) out.add(ref);
      }
    }
  } catch {
    return new Set();                        // fail CLOSED — under-report, never over-report
  }
  return out;
}

// Live Fleet data (#412) — PURE mappers from the running app state to the Fleet
// board shapes. The roster comes from the store's launched fleet
// (`fleetPaneStreams`), run/idle from the live `paneStatus` map (#412), and
// blocked/asking/waiting from the coordination log (CoordState). No fabrication —
// GitHub-derived analytics (throughput, merge queue, time-to-land) and token/cost
// accounting are deferred to follow-ups and rendered as explicit "not wired" states.
//
// Framework-free + unit-tested; the store/coord wiring lives in hooks/useFleetLive.

import { hashString } from "@/shared/lib/core/format";
import { resolveByPrecedence, type PrecedenceRule } from "@/shared/lib/algorithms/precedenceResolve";
import type { CoordState } from "@/shared/lib/fleet/coordination";
import type { AgentStream } from "@/features/planner/fleet/planFleet";
import type { WorkerStatus } from "@/shared/data/fleet";

/** Minimal AgentProfile fields we need for labels/colors (avoids a hard dep). */
export interface ProfileLike { id: string; name: string }

export interface LiveWorker {
  /** pane id, e.g. "t2p0" — the coordination `session` key too. */
  id: string;
  /** display name (the stream name). */
  name: string;
  /** stream/worktree repo. */
  repo: string;
  /** resolved profile label + a stable color. */
  profileLabel: string;
  profileColor: string;
  status: WorkerStatus;
  /** the work item it's on (first owned issue, else the stream name). */
  issue: string;
  /** a short sub-note: the block dep / question / wait reason, when parked. */
  note: string;
  /** count of issues this stream owns. */
  ownedTotal: number;
}

/** Stable color from a string (profile id), matching the loginColor convention. */
function hashColor(s: string): string {
  return `oklch(0.72 0.13 ${hashString(s) % 360})`;
}

/**
 * The live status for a worker pane: coordination wins (a parked worker is
 * asking / waiting / blocked), otherwise the raw run/idle from `paneStatus`
 * ("run" → running, anything else → idle).
 *
 * The precedence is DATA (#3465) — the `PRECEDENCE` table below, resolved by the generic
 * `resolveByPrecedence`. As a chain of `if` returns the ordering existed only in statement order:
 * unreadable as a whole, untestable on its own, and reorderable by accident. The order itself is the
 * decision worth being explicit about — a worker that needs a human must never be hidden behind a
 * mechanical "running", which is why the coordination states sit above the run sample.
 */
const PRECEDENCE: PrecedenceRule<{ paneId: string; coord: CoordState; paneStatus: Record<string, "run" | "on" | "idle"> }, WorkerStatus>[] = [
  { state: "asking", when: ({ paneId, coord }) => coord.asking.some(a => a.session === paneId) },
  { state: "waiting", when: ({ paneId, coord }) => coord.waiting.some(w => w.session === paneId) },
  { state: "blocked", when: ({ paneId, coord }) => coord.waiters.some(w => w.session === paneId) },
  // Active work wins over a parked state (a dispatched maintenance worker is running, not parked).
  { state: "running", when: ({ paneId, paneStatus }) => paneStatus[paneId] === "run" },
  // A finished worker parked in maintenance (#1957) reads `maintenance`, not plain idle.
  { state: "maintenance", when: ({ paneId, coord }) => coord.maintaining.some(m => m.session === paneId) },
];

export function statusForPane(
  paneId: string, coord: CoordState, paneStatus: Record<string, "run" | "on" | "idle">,
): WorkerStatus {
  return resolveByPrecedence({ paneId, coord, paneStatus }, PRECEDENCE, "idle");
}

/** The parked-state note for a pane (question / wait reason / block deps), or "". */
function noteForPane(paneId: string, coord: CoordState): string {
  const ask = coord.asking.find(a => a.session === paneId);
  if (ask) return ask.question;
  const wait = coord.waiting.find(w => w.session === paneId);
  if (wait) return wait.reason;
  const blocked = coord.waiters.find(w => w.session === paneId);
  if (blocked) {
    const deps = blocked.deps.map(d => (d.kind === "issue" ? `#${d.number}` : d.kind === "contract" ? `contract:${d.name}` : d.kind)).join(", ");
    return deps ? `blocked on ${deps}` : "blocked";
  }
  const maint = coord.maintaining.find(m => m.session === paneId);
  if (maint) return maint.note || "owned issues complete — standing by";
  return "";
}

export interface BuildWorkersInput {
  /** the launched fleet: pane id → its stream, keyed by the #1176 IDENTITY id (`<key>:<stream>`). */
  fleetPaneStreams: Record<string, AgentStream>;
  paneStatus: Record<string, "run" | "on" | "idle">;
  coord: CoordState;
  /** The open tabs (with their minted `paneIds`), so a worker whose tab was closed is dropped. */
  tabs: { paneIds?: string[] }[];
  disabledPanes: Record<string, boolean>;
  profiles: ProfileLike[];
}

/** Build the live worker roster from the running fleet. Only panes whose tab is
 *  still open and not disabled are included (a launched-then-closed fleet drops). */
export function buildLiveWorkers(input: BuildWorkersInput): LiveWorker[] {
  const { fleetPaneStreams, paneStatus, coord, tabs, disabledPanes, profiles } = input;
  const profById = new Map(profiles.map(p => [p.id, p]));
  // A worker is live only while its pane is still one of an OPEN tab's minted cells (#1176): the
  // fleet/triage launch records each pane's IDENTITY id (`<key>:<stream>`) on the tab's `paneIds`, so
  // a closed tab drops its workers. (The old positional `tabOfPane` parse matched only `t<idx>p<idx>`
  // and so silently dropped EVERY identity-keyed pane — the "No fleet running" bug.)
  const livePaneIds = new Set(tabs.flatMap(t => t.paneIds ?? []));
  const workers: LiveWorker[] = [];
  for (const [paneId, stream] of Object.entries(fleetPaneStreams)) {
    if (!livePaneIds.has(paneId) || disabledPanes[paneId]) continue;
    const prof = stream.profile ? profById.get(stream.profile) : undefined;
    workers.push({
      id: paneId,
      name: stream.name,
      repo: stream.repo,
      profileLabel: prof?.name ?? stream.profile ?? "—",
      profileColor: stream.profile ? hashColor(stream.profile) : "var(--fg-dim)",
      status: statusForPane(paneId, coord, paneStatus),
      issue: stream.issues[0] ?? stream.name,
      note: noteForPane(paneId, coord),
      ownedTotal: stream.issues.length,
    });
  }
  // Stable order: by tab/pane id.
  return workers.sort((a, b) => a.id.localeCompare(b.id, undefined, { numeric: true }));
}

/** Worker counts per status (drives the donut). */
export function statusCounts(workers: LiveWorker[]): Partial<Record<WorkerStatus, number>> {
  const c: Partial<Record<WorkerStatus, number>> = {};
  for (const w of workers) c[w.status] = (c[w.status] ?? 0) + 1;
  return c;
}

export interface FleetKpis {
  total: number;
  active: number;       // running
  needAttention: number; // blocked | asking | waiting
  idle: number;
  maintenance: number;  // parked & ready — finished every owned issue, standing by (#1957)
}
export function deriveFleetKpis(workers: LiveWorker[]): FleetKpis {
  const is = (s: WorkerStatus) => workers.filter(w => w.status === s).length;
  return {
    total: workers.length,
    active: is("running"),
    needAttention: is("blocked") + is("asking") + is("waiting"),
    idle: is("idle"),
    maintenance: is("maintenance"),
  };
}

// Per-worker issue progress, derived from the FLEET PLAN (#4102).
//
// ── WHY THIS EXISTS ALONGSIDE `streamProgress.ts` ────────────────────────────────────────────────
// #4050 derived progress entirely from plan.db's `issues` table: it partitioned `bsc plan list` by
// each issue's `stream` field. That is correct wherever those rows exist — and invisible wherever they
// do not. Measured on the live store (`plans/studio-code.db`): 40 `fleet_streams`, 40 `features`, and
// ZERO `issues`. So every stream got `total: 0`, and `GlanceNode`'s (correct) `total > 0` guard hid a
// bar it had no data for. The bars had simply never had an input.
//
// Ownership was not missing, only stored elsewhere: a stream carries its own work as GitHub refs in
// `AgentStream.issues` (`["#3898","#3979"]`) — 60 refs across 24 of the 40 streams. That is the
// authoritative ownership record, it is already in memory via the fleet plan, and it needs no network.
//
// ── THE SPLIT: OWNERSHIP IS LOCAL, DONE-NESS IS EVIDENCE ─────────────────────────────────────────
// So `total` comes from the plan (always available, always right) and `done` comes from whatever
// evidence exists that a ref is finished — plan.db statuses where rows were authored, GitHub
// open/closed otherwise. Unioning them means a project with a populated plan.db keeps working exactly
// as it did under #4050, while one without it stops rendering a permanently empty graph.
//
// Keeping `total` off plan.db is the actual fix. A denominator that silently drops to zero does not
// look broken — it looks like a fleet that owns no work.

import type { StreamProgress } from "@/features/glance/lib/streamProgress";

/** The minimum shape this needs from a fleet stream — kept structural so the pure fn does not drag in
 *  the whole `AgentStream` (and so tests can state a stream in one line). */
export interface OwningStream {
  id: string;
  /** Issue refs this stream owns, e.g. `["#3898"]`. */
  issues: readonly string[];
}

/** Normalise a ref for comparison: `#3898`, `3898` and ` #3898 ` are the same issue.
 *
 *  Worth doing rather than trusting equality — the refs come from three places (the plan's stored
 *  strings, plan.db's `ref` column, GitHub's numeric `number`) and a formatting mismatch between any
 *  two would show as a bar stuck at 0/N, which is exactly the failure this file exists to end. */
export function normalizeRef(ref: string | number): string {
  return String(ref).trim().replace(/^#/, "");
}

/**
 * Every alias a plan.db issue answers to, so a stream's ref can be matched against ITS OWN namespace.
 *
 * `glance-progress-ref-namespace-split`. A stream's `issues` and plan.db's `ref` column are two separate
 * ownership records, and they do not always speak the same language. Measured across the two live
 * projects:
 *
 *   base-studio-code   22 stream refs, ALL 22 are plan.db slugs   -> 22/22 resolve
 *   studio-code        56 stream refs, ALL bare GitHub numbers    -> 0/56 resolve (plan.db is slugs,
 *                                                                    and carries no gh_number at all)
 *
 * A slug that carries its origin number (`4260-sandbox-by-default-…`) therefore also answers to `4260`,
 * which is the one join available without a schema change — `bsc plan list --full` does not project
 * `gh_number`, so the number embedded in the ref is the only GitHub identity reachable from here.
 */
export function knownRefAliases(issues: readonly { ref: string }[]): Set<string> {
  const out = new Set<string>();
  for (const i of issues) {
    const ref = normalizeRef(i.ref ?? "");
    if (!ref) continue;
    out.add(ref);
    const lead = /^(\d+)-/.exec(ref);
    if (lead) out.add(lead[1]);
  }
  return out;
}

/**
 * Per-stream `done / total` for a fleet.
 *
 * `total` is what the stream OWNS. `done` counts its refs present in `doneRefs` — so a ref that is
 * done but owned by nobody cannot inflate anyone's progress, and a stream owning nothing yields
 * `total: 0`, which the node renders as NO bar (deliberately: an empty bar and a zero-progress bar
 * say different things, and only one of them is true).
 *
 * Pure. `doneRefs` may hold refs in either form; both sides are normalised.
 */
export function fleetPlanProgress(
  streams: readonly OwningStream[],
  doneRefs: ReadonlySet<string>,
  /** When set, ALSO emit this node id carrying the union of EVERY stream's refs (#4122).
   *
   *  The director is not a stream — it owns no lane — so a per-stream map leaves its node with no
   *  progress at all. But it is the one agent responsible for the whole board, so its bar is the
   *  project's: every issue any worker owns, de-duplicated, because two streams naming one ref is one
   *  piece of work and double-counting would make the director's denominator disagree with the sum of
   *  its workers'. */
  aggregateId?: string,
  /** The refs plan.db actually knows ({@link knownRefAliases}). When given, a stream whose refs are ALL
   *  unknown emits NO entry, so `mergeStreamProgress` lets plan.db answer instead.
   *
   *  `glance-progress-ref-namespace-split`: without this, a ref path that can never resolve still won,
   *  because winning only required `total > 0`. On `studio-code` every one of the 56 stream refs is a
   *  GitHub number this plan.db has no row for, so all 24 owning streams rendered `0/N` — and
   *  `design-studio`, which plan.db knows to be 8/8 DONE, rendered `0/15`. A denominator with no
   *  reachable numerator is not evidence; it is the absence of evidence wearing evidence's clothes.
   *
   *  Omitted ⇒ every stream emits, exactly as before (the pre-existing callers and tests are unchanged). */
  knownRefs?: ReadonlySet<string>,
): Map<string, StreamProgress> {
  const done = new Set<string>();
  for (const r of doneRefs) done.add(normalizeRef(r));
  const resolves = (r: string) => !knownRefs || knownRefs.has(r);

  const out = new Map<string, StreamProgress>();
  for (const s of streams) {
    // De-duplicate within a stream: a ref listed twice would push `done` past `total` and render a bar
    // over 100%. `progressFraction` clamps the fill, but the "3/2" label beside it would still be wrong.
    const refs = new Set(s.issues.map(normalizeRef));
    // Only a stream that owns refs AND resolves NONE of them stands aside. A stream owning NOTHING must
    // still emit `{0,0}` — that is the documented contract (`mergeStreamProgress` reads `total === 0` as
    // "owns no refs, let plan.db answer", and the node renders no bar). Skipping it here instead made
    // `fleetPlanProgress`'s own tests fail on `expected undefined`, which is the distinction: "owns
    // nothing" and "owns things I cannot resolve" reach the same UI, but only one of them is a fact
    // about the stream rather than about my ability to look it up.
    if (refs.size > 0 && ![...refs].some(resolves)) continue;
    let d = 0;
    for (const r of refs) if (done.has(r)) d += 1;
    out.set(s.id, { done: d, total: refs.size });
  }

  if (aggregateId) {
    // Union across streams, then count — NOT a sum of the per-stream rows, which would double-count a
    // ref two streams both claim.
    const all = new Set<string>();
    for (const s of streams) for (const r of s.issues) all.add(normalizeRef(r));
    // Same rule as a stream: an aggregate over refs that resolve to nothing is the director's `0/56`.
    if ([...all].some(resolves)) {
      let d = 0;
      for (const r of all) if (done.has(r)) d += 1;
      out.set(aggregateId, { done: d, total: all.size });
    }
  }
  return out;
}

/**
 * Combine the ref-derived progress with plan.db's own, per stream.
 *
 * A stream that owns refs uses the ref-derived numbers — that is the fix, and its denominator cannot
 * silently collapse to zero. A stream that owns NONE falls back to plan.db's entry, which preserves
 * #4050 exactly where it already worked: a project whose planner run authored issue rows carrying a
 * `stream` field, but whose stream records never listed the refs, still shows the bar it showed before.
 *
 * Neither source is dropped, so this cannot regress a project that was working.
 */
export function mergeStreamProgress(
  fromRefs: ReadonlyMap<string, StreamProgress>,
  fromPlanDb: ReadonlyMap<string, StreamProgress>,
): Map<string, StreamProgress> {
  const out = new Map<string, StreamProgress>(fromPlanDb);
  for (const [id, p] of fromRefs) {
    // `total === 0` means "owns no refs", which is not evidence of anything — let plan.db answer.
    if (p.total > 0) out.set(id, p);
  }
  return out;
}

/**
 * Union the done-evidence sources into the set `fleetPlanProgress` consumes.
 *
 * Both are partial and neither is authoritative alone: plan.db knows only what a planner run authored
 * (nothing, for a hand-assembled fleet), and GitHub knows only what a token could reach (nothing, when
 * disconnected). A ref that either source calls finished IS finished — treating one as authoritative
 * would make progress vanish the moment that source is the empty one, which is the bug being fixed.
 */
export function unionDone(...sources: ReadonlyArray<Iterable<string> | undefined>): Set<string> {
  const out = new Set<string>();
  for (const src of sources) {
    if (!src) continue;
    for (const r of src) out.add(normalizeRef(r));
  }
  return out;
}

// Blueprint fleet-policy resolution (#1854 Phase b) — the pure resolvers that compose a stream's
// effective profile + flow from three layers, in precedence order:
//
//   1. the stream's OWN declared value      (planner-GENERATED, per-project — always wins)
//   2. the seeding blueprint's FleetPolicy   (the DEFAULT this project type declares)
//   3. the hard launch-time default          (role default profile / DEFAULT_FLOW)
//
// This is the "planner reads defaults from the blueprint" wiring: the blueprint carries the
// recipe/policy, the planner instantiates concrete per-stream config, and a stream's own choice
// still overrides. When the blueprint declares no policy, every resolver reduces to today's
// behavior byte-for-byte (see the fleetStartProject launch path).
//
// Pure (no React/Tauri) so it's unit-testable and shared by the launch path.

import type { AgentFlow } from "@/features/planner/fleet/agentFlow";

/**
 * The effective FLOW for a stream: the stream's own `flow` wins; else the blueprint policy's flow
 * default; else `undefined` — deliberately NOT {@link DEFAULT_FLOW}, so the launch path keeps its
 * "absent ⇒ apply DEFAULT_FLOW downstream" semantics. Returning `undefined` when neither layer
 * sets a flow makes the resolution byte-identical to the pre-policy behavior.
 *
 * @param streamFlow the stream's own declared flow, or `undefined`
 * @param policyFlow the seeding blueprint's `fleetPolicy.flow` default, or `undefined`
 */
export function resolveStreamFlow(
  streamFlow: AgentFlow | undefined,
  policyFlow: AgentFlow | undefined,
): AgentFlow | undefined {
  return streamFlow ?? policyFlow;
}

/**
 * The effective PROFILE id for a stream: the stream's own pinned `profile` wins; else the blueprint
 * policy's profile default; else the role default. The blueprint only SEEDS the launch default — the
 * role gate (#219) still caps the session at launch (the request-vs-cap posture is Phase c).
 *
 * The caller is responsible for passing `policyProfile: undefined` for the director (the policy is a
 * per-WORKER default), so the director always resolves to its role's read-only review profile.
 *
 * @param streamProfile the stream's own pinned profile id, or `undefined`
 * @param policyProfile the seeding blueprint's `fleetPolicy.profile` default, or `undefined`
 * @param roleDefault   the role's default profile id (the historical fallback)
 */
export function resolveStreamProfile(
  streamProfile: string | undefined,
  policyProfile: string | undefined,
  roleDefault: string,
): string {
  return streamProfile ?? policyProfile ?? roleDefault;
}

// Fleet roster (#734) — persists the launched fleet's session roster to the project hub as
// `fleet.roster.tsv`, so the director's `bsc-fleet` shell helper can enumerate every worker
// (console id / stream / repo / branch / role) and, joined with coord.log, each one's state.
//
// The store builds the rows (it knows the pane keys) but stays Tauri-free; this is the
// component-side writer the launch callers use. It ALSO records the durable session ledger (#2405)
// from the same rows, so recovery reads a fact instead of inferring from disk.

import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { bscWrite } from "@/shared/lib/core/bsc";

/** Write the roster rows to `<hub>/fleet.roster.tsv` AND record each launched agent in the durable
 *  per-project session ledger (#2405). No-op on an empty roster. */
export function publishFleetRoster(projectKey: string, rosterRows: string[]): void {
  if (rosterRows.length === 0) return;
  fireInvoke("write_project_file", {
    projectKey, relpath: "fleet.roster.tsv", contents: rosterRows.join("\n") + "\n",
  }, (e) => console.error("write fleet.roster.tsv failed:", e));
  recordFleetSessions(projectKey, rosterRows);
}

/** Record each launched agent in the durable session ledger (#2405) — the authoritative "these agents
 *  were launched" that survives a clean quit, so recovery can offer to restart the fleet. Best-effort,
 *  fire-and-forget per agent: a failed write never blocks the launch. Fields come straight from the
 *  roster row (`paneId/stream/repo/branch/role`); `cwd` is re-derived from the plan on restart, so it's
 *  left blank here. Exported for the callers/tests; `publishFleetRoster` already invokes it. */
export function recordFleetSessions(projectKey: string, rosterRows: string[]): void {
  for (const row of rosterRows) {
    const [paneId, stream, , , role] = row.split("\t");
    if (!paneId) continue;
    void bscWrite(projectKey, ["plan", "fleet", "session", "set"], {
      paneId,
      // The director row carries "director" in the stream column; a real stream id only for workers.
      streamId: role === "director" ? "" : (stream ?? ""),
      role: role ?? "",
      status: "running",
    }).catch((e) => console.error("record fleet session failed:", e));
  }
}

// fleetWakeBridge (#4101) — decide what a `bsc fleet wake` request does to the store.
//
// Pure on purpose: the DECISION (refuse a busy pane, pick the prompt, report what happened) is testable
// without Tauri or a rendered app, and the listener stays a thin adapter — the same split
// `navigateBridge` uses.
//
// WHY THE VERDICT MATTERS
// `wakePane` returns false when it cannot resolve the pane's owning tab, or when the pane is disabled —
// and a false reported as success leaves a dead worker behind a caller that believes it is running. That
// is #4025 exactly: `wakePane` resolved tabs by the retired positional pane id, returned false for all
// 273 real sessions, and the Wake button killed every parked worker silently. So the verdict is carried
// all the way back to the CLI.
//
// WHY THE KILL IS HERE AND NOT ONLY IN `wakePane`
// `wakePane` does NOT kill anything — it bakes the startup prompt and bumps the owning tab's `runId`.
// (A comment here used to claim otherwise, which is very likely why this path never killed: it read as
// already handled.) The bump remounts the pane, and `pty_create` "returns true for a new session, FALSE
// when reconnecting to an existing one" (TerminalView) — on reconnect it just sends `\n` and the baked
// prompt is discarded (the #3998 init_cmd-on-reconnect trap).
//
// So for a pane whose SHELL OUTLIVED ITS AGENT — bash alive, Claude exited, which `bsc fleet list`
// reports as `live && !busy` — the wake reconnected to bash, never started Claude, and still returned
// `woke: true`. Worse than a refusal: the director was told it landed. The coordinator's `actuateWake`
// already got this right ("Kill first so the runId-bump remount spawns a FRESH session (not a
// reconnect)"); this path was missing exactly that step, and the two differed by one line for no reason
// anyone recorded.

/** The wake request as it arrives from Rust (`bsc://fleet-wake`). */
export interface WakeRequest {
  paneId: string;
  /** Empty ⇒ use {@link DEFAULT_WAKE_PROMPT}. */
  prompt?: string;
  /** Carried for completeness; the BUSY refusal it governs is applied in Rust, before this is emitted. */
  force?: boolean;
}

/** What we send back via `fleet_wake_ack`. */
export interface WakeAck {
  id: string;
  error?: string;
  woke: boolean;
}

/**
 * The wake text a director gets when it does not supply one.
 *
 * Deliberately a CHANGE-REQUEST framing rather than a bare "continue": a woken worker is being brought
 * back because something needs doing, and an empty prompt would drop it at a prompt with no task — the
 * failure mode maintenance mode (#1957) exists to avoid.
 */
export const DEFAULT_WAKE_PROMPT =
  "You have been woken by the director because there is a change request for your stream. " +
  "Re-read your assignment, check `bsc plan issue list` for what is open on it, and continue.";

/**
 * The store surface this needs — narrowed so the pure fn stays decoupled from the slice.
 *
 * Note there is no busy check: BUSY is resolved in Rust before the request is ever emitted, since the
 * store cannot see whether a shell has a live descendant.
 */
export interface WakeDeps {
  /** The real `wakePane`. Returns whether the wake actually landed. */
  wakePane: (paneId: string, prompt: string) => boolean;
  /** `pty_kill` for this pane. MUST run before {@link WakeDeps.wakePane} so the remount SPAWNS rather
   *  than reconnecting — see the header. A no-op when there is no PTY (a dormant/reaped pane), which is
   *  why it is safe to call unconditionally rather than probing liveness first: the probe would be a
   *  second source of truth about what is alive, and Rust already owns that answer. */
  killPane: (paneId: string) => Promise<void>;
}

/**
 * Apply one wake request. Never throws — every path produces an ack, because silence would strand the
 * Rust waiter until its timeout and surface as "the frontend did not apply the wake", sending someone
 * to debug the wrong thing.
 *
 * ORDER IS LOAD-BEARING: kill, then wake. Reversed, the remount races the kill and can reconnect to a
 * PTY that is about to die; skipped, a live shell is reconnected and the prompt is silently dropped.
 */
export async function applyWake(id: string, req: WakeRequest, deps: WakeDeps): Promise<WakeAck> {
  const paneId = (req.paneId ?? "").trim();
  if (!paneId) return { id, error: "fleet wake: no pane id", woke: false };

  // A kill failure must not abort the wake: the common reason is that there was nothing to kill, and
  // refusing to wake a dormant pane because its absent PTY could not be killed would break the case
  // this command was built for.
  await deps.killPane(paneId).catch(() => {});
  const woke = deps.wakePane(paneId, req.prompt?.trim() || DEFAULT_WAKE_PROMPT);
  return { id, woke };
}

// Pure mappers for the per-agent page (#499): turn a worker's AgentProfile +
// AgentFlow into the render rows the page shows. Free of React/Tauri so the
// mapping is unit-testable and shared with the component.

import type { AgentProfile, ToolKey, Tier } from "@/features/security";
import type { AgentFlow } from "@/features/planner/fleet/agentFlow";

/** Tool display order, matching the design's two-column Permissions card. */
export const TOOL_ORDER: ToolKey[] = ["read", "glob", "write", "web", "grep", "edit", "bash", "task"];

export interface PermRow { key: ToolKey; tier: Tier; }
/** Per-tool posture rows from the profile (empty when no profile is assigned). */
export function permissionRows(profile: AgentProfile | undefined): PermRow[] {
  if (!profile) return [];
  return TOOL_ORDER.map((key) => ({ key, tier: profile.tools[key] }));
}

export interface FlowRow { key: string; value: string; desc: string; }
/** The execution-flow rows (autonomy / push / trigger / gate) with descriptions. */
export function flowRows(flow: AgentFlow): FlowRow[] {
  return [
    { key: "autonomy", value: flow.autonomy, desc: "how it handles underspecified decisions" },
    { key: "push",     value: flow.push,     desc: "what / whether it pushes to GitHub" },
    { key: "trigger",  value: flow.trigger,  desc: "when a push fires" },
    { key: "gate",     value: flow.gate,     desc: "how a confirm pause is enforced" },
  ];
}

/** Parse a pane id "t{tab}p{pane}" into its tab + pane indices (or nulls). */
export function paneCoords(paneId: string): { tab: number; pane: number } | null {
  const m = /^t(\d+)p(\d+)$/.exec(paneId);
  return m ? { tab: Number(m[1]), pane: Number(m[2]) } : null;
}

// Typed shapes + display maps for the Projects → Fleet page (#401). The page is
// now driven by live app state (#412) — the running fleet roster + coordination
// log — via lib/fleetLive; these are the status/profile display maps the board
// renders. (The original sample dataset was removed once the page went live.)

export type WorkerStatus = "running" | "asking" | "blocked" | "waiting" | "idle" | "done" | "maintenance";
export type FleetProfile = "build" | "review" | "docs" | "auto" | "sandbox";

export interface ProfileMeta { label: string; color: string }
export interface StatusMeta { label: string; color: string }

const ACCENT = "var(--accent)", INFO = "var(--info)", OK = "var(--success)",
  DANGER = "var(--danger)", VIOLET = "oklch(0.7 0.12 290)", DIM = "var(--fg-dim)",
  TEAL = "oklch(0.75 0.10 195)";

/** Profile palette (mirrors agentProfiles colors). */
export const PROFILE: Record<FleetProfile, ProfileMeta> = {
  build:   { label: "Build & test",     color: "oklch(0.78 0.14 70)" },
  review:  { label: "Read-only review", color: "oklch(0.72 0.10 230)" },
  docs:    { label: "Docs writer",      color: "oklch(0.7 0.06 90)" },
  auto:    { label: "Autonomous",       color: "oklch(0.74 0.13 145)" },
  sandbox: { label: "Sandboxed",        color: "oklch(0.68 0.18 25)" },
};

/** Worker status → label + color (also keys the `.wd` status dot class). */
export const STATUS: Record<WorkerStatus, StatusMeta> = {
  running: { label: "running", color: ACCENT },
  asking:  { label: "asking",  color: VIOLET },
  blocked: { label: "blocked", color: DANGER },
  waiting: { label: "waiting", color: INFO },
  idle:    { label: "idle",    color: DIM },
  maintenance: { label: "maintenance", color: TEAL },
  done:    { label: "landed",  color: OK },
};

// Generate the autonomy + push paragraph of a fleet stream's kickoff from its
// flow (#297). The kickoff is the first message a worker session receives; these
// two sentences tell it how to handle decisions (pause vs continue) and what /
// when to push — so the prose matches the permissions the flow also enforces
// (flowPermissions.ts). Pure; unit-tested.

import type { AgentFlow, FlowTrigger } from "@/features/planner/fleet/agentFlow";
import { resolveFlow } from "@/features/planner/fleet/agentFlow";
import flowKickoffEmbedded from "@data/fleet/flow-kickoff.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

export interface FlowKickoffText {
  /** How to handle underspecified / risky decisions. */
  autonomy: string;
  /** What and when to push to GitHub. */
  push: string;
}

// The trigger-phrase MAP + the per-autonomy PROSE are externalized to `@data/fleet/flow-kickoff.json`
// (#2145, epic #2027 tail) — editable without touching code + part of the exportable config bundle; the
// config-dir copy (#2047) overlays the embedded default via `overlayFile`. Only these fully-static strings
// moved; the push sentences below stay inline because they interpolate `${when}`/`${branch}` mid-string.
const KICKOFF_PROSE = overlayFile("fleet/flow-kickoff.json", flowKickoffEmbedded);

/** When a push fires, phrased for the kickoff sentence. */
const TRIGGER_PHRASE = KICKOFF_PROSE.triggerPhrase as Record<FlowTrigger, string>;

/**
 * Build the autonomy + push sentences for a stream's kickoff. `branch` is the
 * worktree branch (the stream id) the push sentence references. Falls back to
 * DEFAULT_FLOW when `flow` is unset, so pre-flow plans read exactly as before
 * (continuous + auto-pr).
 */
export function flowKickoffText(flow: AgentFlow | undefined, branch: string): FlowKickoffText {
  const f = resolveFlow(flow);
  const when = TRIGGER_PHRASE[f.trigger];

  // The autonomy prose is fully static (no interpolation) → sourced from data, keyed by autonomy mode.
  const autonomy = KICKOFF_PROSE.autonomy[f.autonomy];

  let push: string;
  switch (f.push) {
    case "push-confirm":
      push = f.gate === "hard"
        ? `When your work is ready (${when}), commit to your branch ${branch} and run the checks locally, then STOP and ask the user before pushing — the push and PR commands prompt for approval, so wait for it.`
        : `When your work is ready (${when}), commit to your branch ${branch} and run the checks locally, then pause and ask the user before you push or open a PR.`;
      break;
    case "self-merge":
      push = `When your work is ready, integrate it yourself (${when}) — do NOT open a PR and do NOT wait for CI. Steps: (1) run the FULL local gate (typecheck + tests + any native build) and make it green; (2) git fetch origin develop and rebase your branch ${branch} onto origin/develop; (3) re-run the FULL gate on the rebased, integrated tree — this is the integration check; (4) if green, merge ${branch} into develop and push develop. If the push is rejected because another stream merged first, re-fetch, rebase, re-gate, and push again. After develop has your commit, pipe your landed issue ref into bsc-landed on stdin (e.g. echo "#42" | bsc-landed) so the director and board track it, then continue to your next issue. develop's CI is the director's backstop, not your gate. Do not stop while you still have owned issues to integrate — only end your turn once every owned issue is on develop with the gate green.`;
      break;
    case "local":
      push = `When your work is ready (${when}), run the FULL local gate (typecheck + lint + tests, plus any native build) and make it green, then commit to your branch ${branch} and STOP. Do NOT push. Do NOT open a PR. Nothing you do reaches a remote — this project integrates locally, and the integration stream merges your branch into the integration branch once your work is confirmed. Record what the gate actually did with \`bsc plan change gate <ref> <step> <pass|fail|not-run>\` — a step you skipped is recorded as skipped, never omitted — then mark your item \`bsc plan status <ref> complete\` and move to your next issue. \`complete\` means "I did my part", not "this is done": do not mark it verified and do not merge your own branch.`;
      break;
    case "commit-only":
      push = `Commit your work to your branch ${branch} as you go, but do not push — the user or director will push your branch and open any PR.`;
      break;
    case "none":
      push = "This is a read-only role: do not commit, push, or open PRs. Report what you find by piping notes into bsc-note on stdin.";
      break;
    default: // auto-pr
      push = `When your work is ready and the checks pass (${when}), commit to your branch ${branch}, push it, and open a PR to develop. After opening the PR, STOP -- CI runs automatically and is watched for you: when it finishes you will be told to continue (if it passed) or to fix the build and push (if it failed). Do not poll CI, close, merge, reopen, or duplicate the PR -- GitHub is the DIRECTOR's job: the director reviews, merges, and closes your PR once it is green. Never run gh pr merge or gh pr close on your own PR.`;
  }

  // Issue lifecycle is the director's job (#906): a worker signals completion (above) but
  // never closes the GitHub issue itself — workers have GitHub read access only, so the role
  // gate blocks `gh issue close` and attempting it just wastes a turn. The director closes the
  // issue once the work lands (it sees the PR merge / your `bsc-landed`). A read-only (`none`)
  // role owns no issue to close, so it gets no such clause.
  // `local` is excluded too (#fleet-local-completion-flow): there is no GitHub issue to leave alone,
  // and its own prose already names the completion handoff (`bsc plan status … complete`). Telling a
  // local worker about GitHub issue state would point it at a surface this project deliberately
  // keeps silent.
  if (f.push !== "none" && f.push !== "local") {
    push += " Do not close, reopen, or edit the GitHub issue yourself — the director manages issue state and closes it once your work lands; just signal completion as above.";
  }

  return { autonomy, push };
}

// Agents — Flow-tab derivation + status colors (#199 / #1643).
//
// The fleet's live work-flow on the Agents screen: which sessions are parked on a
// dependency. Pure summary + color helpers, split out of SecurityWorkspace so they're
// React-free + testable.

import type { BlockedView, Waiter } from "@/shared/lib/fleet/coordination";

export interface FlowSummary {
  /** Blocked sessions flagged as stalled. */
  stalled: number;
  /** Blocked sessions sitting in a wait-for cycle. */
  deadlocked: number;
  /** Nothing ready or blocked — show the idle hint. */
  idle: boolean;
}

/** Summarize the Flow tab's coordination state. */
export function flowSummary(
  views: BlockedView[],
  ready: Waiter[],
): FlowSummary {
  const stalled = views.filter((v) => v.stalled).length;
  const deadlocked = views.filter((v) => v.deadlocked).length;
  const idle = ready.length === 0 && views.length === 0;
  return { stalled, deadlocked, idle };
}

/** Color for a dependency's satisfaction status. */
export function depColor(status: BlockedView["deps"][number]["status"]): string {
  return status === "satisfied" ? "var(--success)" : status === "failed" ? "var(--danger)" : "var(--fg-dim)";
}

// Translate a per-agent flow (#297) into the launch-time permission rules that
// govern its GitHub writes. The session already allows the Bash tool broadly
// (start-and-go) and guarantees gh/git; this layer narrows ONLY the propagation
// writes — `git push` and `gh pr create` — per the flow's push policy and gate.
//
// Precedence in Claude Code settings is deny > ask > allow, so a specific `ask`
// rule prompts even under the broad Bash allow, and a specific `deny` hard-blocks.
// That maps the flow's push axis cleanly:
//   local         → deny push/PR (nothing reaches a remote; the integration stream merges locally)
//   auto-pr       → no rules (broad allow permits push+PR; --force stays denied)
//   push-confirm  → hard: ask before push/PR (prompt); soft: no rule (kickoff asks)
//   commit-only   → deny push/PR (commits stay local)
//   none          → deny push/PR (no GitHub propagation)
//
// The autonomy axis is behavioral (enforced via the kickoff, S4), and a stream's
// no-commit / no-code posture is the role/profile's job (#219/#289) — so this
// module reads only `push` + `gate`. Pure; unit-tested.

import type { AgentFlow } from "@/features/planner/fleet/agentFlow";
import { resolveFlow } from "@/features/planner/fleet/agentFlow";

export interface FlowPermissionRules {
  /** Tool rules forcing a prompt before the command (Claude Code `ask` tier). */
  askToolRules: string[];
  /** Tool rules hard-blocking the command (Claude Code `deny` tier). */
  denyToolRules: string[];
}

/**
 * The GitHub-propagation writes the flow gates. `git push` covers branch pushes;
 * `gh pr create` covers opening PRs. Merging (`gh pr merge`) is the director's job
 * and is never granted to a worker flow here. The space boundary matches the
 * codebase's `Bash(<bin> *)` rule style.
 */
export const PUSH_WRITE_RULES = ["Bash(git push *)", "Bash(gh pr create *)"] as const;

/** Compute the ask/deny rules a stream's flow contributes at launch.
 *
 *  FAILS CLOSED. The `default` branch denies rather than permitting, and the policies that DO reach a
 *  remote are enumerated explicitly. It used to be the other way around — an unrecognized (or newly
 *  added) push value fell through to "no rules", which under the broad Bash allow means push and PR
 *  are permitted. That is the wrong direction for a value nobody has thought about yet, and it is not
 *  hypothetical: `self-merge` was never a case here and reached the remote through this branch. */
export function flowPermissionRules(flow: AgentFlow | undefined): FlowPermissionRules {
  const f = resolveFlow(flow);
  const push = [...PUSH_WRITE_RULES];
  switch (f.push) {
    case "auto-pr":
    case "self-merge":
      return { askToolRules: [], denyToolRules: [] };
    case "push-confirm":
      return f.gate === "hard"
        ? { askToolRules: push, denyToolRules: [] }
        : { askToolRules: [], denyToolRules: [] };
    case "local":
    case "commit-only":
    case "none":
      return { askToolRules: [], denyToolRules: push };
    default:
      return { askToolRules: [], denyToolRules: push };
  }
}


/**
 * Command prefixes the flow GRANTS — the role gate's broader gh/git-write denies must be
 * lifted for exactly these so the flow's GitHub intent wins (#304). A worker role is
 * `github: "read"` and so denies `gh pr create`, but an `auto-pr` / `push-confirm` flow
 * needs the worker to open its PR; everything else the role denies (gh pr merge, repo
 * delete, issue mutations, …) stays denied. `commit-only` / `none` grant nothing, so the
 * role's denies hold (consistent — both block push). Prefixes match `roleDeniedCommands`.
 */
export function flowGrantedPushCommands(flow: AgentFlow | undefined): string[] {
  const f = resolveFlow(flow);
  return f.push === "auto-pr" || f.push === "push-confirm"
    ? ["git push", "gh pr create"]
    : [];
}

// Pure logic for the console focus queue — the ordered set of panes (across all
// tabs) that finished a turn (run -> idle) and await a response, cycled through
// with Ctrl+Shift+N or auto-advance on reply. A pane stays queued (even while you
// view it) until you actually send it a response; advancing just moves the cursor,
// switching tabs when the next waiting pane lives on a different tab.

/** A pane's global identity: which tab it's on and its index within that tab. */
export interface QueuedPane {
  tab: number;
  pane: number;
}

// ── Role-aware focus targeting (#392) ─────────────────────────────────────────
//
// Which panes the autofocus queue pulls your attention to. With a director/worker
// fleet, you usually want only the DIRECTOR to surface — workers run dark and
// escalate via bsc-ask (which flips their pane to awaiting-input through the
// coordinator), so genuine worker questions still reach you. A plain console
// (no role) always queues, except under "none".

export type FocusTarget =
  | "director"   // default: the integrator + plain consoles; workers run dark
  | "workers"    // workers + plain consoles (debug worker behavior)
  | "fleet"      // every fleet role (director + workers) + consoles
  | "everything" // every idle pane, whatever its role
  | "none";      // nothing auto-queues (fully manual)

/** The presets, in display order — for a picker control. */
export const FOCUS_TARGETS: FocusTarget[] = ["director", "workers", "fleet", "everything", "none"];

/** Default focus target — surface the director; let workers run dark. */
export const DEFAULT_FOCUS_TARGET: FocusTarget = "director";

/** Human label for a focus target. */
export function focusTargetLabel(t: FocusTarget): string {
  switch (t) {
    case "director": return "Director";
    case "workers": return "Workers";
    case "fleet": return "Director + workers";
    case "everything": return "Everything";
    case "none": return "None";
  }
}

/**
 * Whether a pane that just went idle should join the focus queue, given the active
 * target. A role-less pane (a plain console — `role` undefined/empty) always queues
 * except under "none", so single-console behavior is unchanged for every target but
 * "none". A fleet pane queues only when its role matches the target.
 *
 * @param role the pane's session role (`paneRoles[pid]`), or undefined for a plain console.
 * @param target the active focus target.
 */
export function shouldFocus(role: string | undefined, target: FocusTarget): boolean {
  if (target === "none") return false;
  if (!role) return true;                       // plain console — always queue (except "none")
  switch (target) {
    case "everything": return true;
    case "director":   return role === "director";
    case "workers":    return role === "worker";
    case "fleet":      return role === "director" || role === "worker";
  }
}

// ── Configurable auto-focus modes (#434) ──────────────────────────────────────
//
// Controls WHEN focus auto-advances after you send a message to the active pane.
// Replaces the old `autoAdvanceOnReply` boolean (still exported for back-compat).

export type ConsoleAutoFocusMode =
  | "cycle-on-reply" // advance to the next queued pane each time you reply (was `true`)
  | "off";           // no automatic advance; use Ctrl+Shift+N manually (was `false`)

/** The presets, in display order — for a picker control. */
export const AUTO_FOCUS_MODES: ConsoleAutoFocusMode[] = ["cycle-on-reply", "off"];

/** Default auto-focus mode: cycle on reply (the original behavior). */
export const DEFAULT_AUTO_FOCUS_MODE: ConsoleAutoFocusMode = "cycle-on-reply";

/** Human label for an auto-focus mode. */
export function autoFocusModeLabel(m: ConsoleAutoFocusMode): string {
  switch (m) {
    case "cycle-on-reply": return "Cycle on reply";
    case "off":            return "Off (manual)";
  }
}

const samePane = (a: QueuedPane, b: QueuedPane) => a.tab === b.tab && a.pane === b.pane;

/**
 * Append a pane to the waiting queue, de-duplicated and order-preserving. Returns
 * the same array reference when nothing changes (so the store can skip a needless
 * update).
 *
 * @param queue current waiting queue.
 * @param entry pane that just went idle.
 */
export function enqueue(queue: QueuedPane[], entry: QueuedPane): QueuedPane[] {
  if (entry.pane < 0 || queue.some((q) => samePane(q, entry))) return queue;
  return [...queue, entry];
}

/** Remove a pane (attended, or back to "run"); same reference if not present. */
export function removeFromQueue(queue: QueuedPane[], entry: QueuedPane): QueuedPane[] {
  return queue.some((q) => samePane(q, entry)) ? queue.filter((q) => !samePane(q, entry)) : queue;
}

/**
 * The next pane to move to when cycling the queue, relative to the pane you're on.
 * Round-robins through the waiting panes — the current one is NOT removed (a pane
 * leaves only when you respond to it), so cycling can land back on it later.
 *
 * @param queue waiting panes.
 * @param current the pane you're on (focused, or maximized).
 * @returns the next waiting pane (possibly on another tab), or null when there's
 *   nowhere else to go (empty queue, or the only queued pane is the current one).
 */
export function nextInCycle(queue: QueuedPane[], current: QueuedPane): QueuedPane | null {
  if (queue.length === 0) return null;
  const idx = queue.findIndex((q) => samePane(q, current));
  if (idx === -1) return queue[0];                 // current isn't waiting → first waiting pane
  const next = queue[(idx + 1) % queue.length];
  return samePane(next, current) ? null : next;     // only the current pane is queued → nowhere to go
}

/**
 * Prune the queue to the panes still waiting, across every tab whose live status
 * we have. After #187 every tab's panes stay mounted, so the caller can supply a
 * per-tab waiting set for every tab — a queued entry stays iff its pane appears
 * in its tab's set. Tabs absent from the map (no live data — e.g. an empty
 * workspace mid-transition) leave their entries alone, since we don't want a
 * temporarily-missing tab to silently drop queued panes.
 *
 * @param queue current waiting queue.
 * @param waitingByTab live waiting indices per tab (idle panes that should stay queued).
 * @returns the pruned queue, or the same reference when nothing changed.
 */
export function reconcileQueue(
  queue: QueuedPane[],
  waitingByTab: ReadonlyMap<number, ReadonlySet<number>>,
): QueuedPane[] {
  const pruned = queue.filter((q) => {
    const waiting = waitingByTab.get(q.tab);
    return waiting === undefined || waiting.has(q.pane);
  });
  return pruned.length === queue.length ? queue : pruned;
}

// Shared handler/types for the focused phase bodies (#1757, split from FocusedBodies.tsx).
// These are imported by BOTH the per-body components AND the FocusedStageBody dispatcher, so they
// live in their own React-free module to avoid a dispatcher↔body import cycle.
import type { Flow, McpServer } from "@/features/planner/pane/projectPaneData";
import type { ModelId } from "@/app/console/lib/models";
import type { Topology } from "@/features/planner/relationship/relationshipGraph";
import type { DirectorDrive } from "@/features/planner/fleet/directorDrive";

export type SyncState = "idle" | "running" | "done" | "error";

/** The fleet/permissions handler set (#1640). Shared by the Permissions body and the merged Streams
 *  body that embeds it, and assembled once by the dispatcher so each case spreads it instead of
 *  re-threading the handlers by name. Per-stream model + flow only — the role decides the profile. */
export interface FleetHandlers {
  onFlow?: (streamId: string, flow: Flow) => void;
  onModel?: (streamId: string, model: ModelId | undefined) => void;
  /** #2094: set/clear the persona a stream launches as (resolves role/prompt/skills/model at launch). */
  onPersona?: (streamId: string, personaId: string | undefined) => void;
  /** Set the project's coordination topology (#…). */
  onTopology?: (t: Topology) => void;
  /** Set the director's drive mode (#…) — only meaningful when the topology routes through it. */
  onDirectorDrive?: (d: DirectorDrive) => void;
}

/** The MCP-stage handler set (#1640). Assembled once by the dispatcher (mapping the on*Mcp props to
 *  the body's verb names) so the `mcp` case spreads it instead of threading four handlers by name. */
export interface McpHandlers {
  onToggle?: (id: string) => void;
  onBuild?: (s: McpServer) => void;
  onAdd?: (input: string) => void;
  onRemove?: (id: string) => void;
}

// Focused planner pane (#652) — the pure model behind the one-stage-at-a-time right
// pane. It wraps the EXISTING blueprint/signal/gate logic (stageStatus / currentStage
// / evalGate) into a navigable "stage" view: which stages are visible, each one's status
// (complete / active / locked / upcoming), the gate pill, and the advance-bar action.
// Pure + serializable so it's fully unit-testable; no React/Tauri.

import {
  enabledStages, currentStage, stageStatus, stageSkipped,
  type BlueprintStage,
} from "@/features/planner/stages/blueprints";
import { evalGate, evalRequirement, gateReasons, type PlanSignals } from "@/features/planner/stages/stageGate";
import type { StagePrompt } from "@/features/planner/session/plannerConductor";

// "complete" = done IN sequence (at/behind the current position); "ahead" = done OUT of
// sequence (gate met past the current position — "banked"); "skipped" = an OPTIONAL section
// the USER deliberately skipped (#921 — the flow now STOPS on every optional stage; the only way
// past one without completing it is a user skip). The rail renders each distinctly so a future
// stage finishing early / a deliberately skipped stage don't read as in-order progress or as a
// not-yet-reached stage (#668).
export type StageStatus = "complete" | "ahead" | "active" | "skipped" | "locked" | "upcoming";

export interface Stage {
  key: string;
  name: string;
  glyph: string;
  blurb: string;
  /** The section's human gate description. */
  gate: string;
  index: number;
  total: number;
  status: StageStatus;
  /** Gate fill 0..1 for the in-progress fraction. */
  fraction: number;
  /** An optional stage — shown but never required (#676). */
  optional?: boolean;
  /** Whether the stage is SKIPPABLE right now (#2854): intrinsically `optional`, OR its declarative
   *  `skipWhen` rule passes against the live signals (e.g. an empty Features stage). Drives whether
   *  the footer renders a Skip control at all — a required stage (no rule) shows none, not a disabled
   *  ghost. Absent ⇒ not skippable. */
  skippable?: boolean;
  /** The Repos stage folds Deploy in as a "ship" substep (#1383) — drives the combined body. */
  ship?: boolean;
  /** The Structure stage folds Permissions in as a "fleet" substep → the "Streams" stage — drives
   *  the combined body (graph + coordination + permissions). */
  fleet?: boolean;
  /** The still-unmet gate requirements (label + progress detail) — drives the "why is this
   *  blocked" feedback on the gate pill (#805). Empty once the gate passes. */
  unmet?: { label: string; detail?: string }[];
}

/**
 * The visible stage list: enabled, non-N/A sections in declared order, each tagged with
 * its status — complete (gate passed), active (the current reached stage), locked (a
 * dependency is unmet), or upcoming (reachable but not yet current).
 */
export function stagesFrom(sections: BlueprintStage[], signals: PlanSignals): Stage[] {
  const current = currentStage(sections, signals);
  const visible = enabledStages(sections)
    .map((s) => ({ s, st: stageStatus(s, sections, signals) }))
    .filter(({ st }) => st.status !== "na");
  // The current position among visible stages; everything complete PAST it is "ahead".
  const activeIdx = current ? visible.findIndex(({ s }) => s.key === current.key) : visible.length;
  return visible.map(({ s, st }, i) => {
    let status: StageStatus;
    // A deliberately user-skipped optional stage reads as "skipped", not "complete" — even though
    // it counts as resolved for the frontier/gate (`stageDone`). Check this first (#921).
    if (stageSkipped(s, signals)) status = "skipped";
    else if (st.status === "complete") status = i > activeIdx ? "ahead" : "complete";
    else if (st.status === "locked") status = "locked";
    else status = current && s.key === current.key ? "active" : "upcoming";
    const unmet = gateReasons(s.gateRule, signals)
      .filter((r) => !r.pass)
      .map(({ label, detail }) => ({ label, detail }));
    // Skippable RIGHT NOW (#2854): intrinsically optional, or the declarative `skipWhen` rule passes
    // against the live signals (e.g. featuresDefined == 0). Drives whether the footer offers Skip.
    const skippable = s.optional === true || (s.skipWhen ? evalRequirement(s.skipWhen, signals).pass : false);
    return {
      key: s.key, name: s.name, glyph: s.glyph, blurb: s.blurb, gate: s.gate,
      index: i, total: visible.length, status, fraction: st.fraction, optional: s.optional, skippable, unmet,
      // #1383: the Repos stage folds Deploy in as a "ship" substep when a blueprint opts in — the
      // combined body renders the deploy block only then.
      ship: s.substeps?.some((ss) => ss.key === "ship"),
      fleet: s.substeps?.some((ss) => ss.key === "fleet"),
    };
  });
}

/**
 * The blueprint section for a stage, resolved BY KEY (#815). `stages` is a FILTERED subset of the
 * raw section list (disabled / not-applicable sections like `ui` are dropped by {@link stagesFrom}),
 * so indexing the raw sections with a stage index lands on the wrong section once any earlier one is
 * dropped. The conductor uses this to inject the *active stage's* prompt, not a neighbor's.
 */
export function sectionForStage<T extends { key: string }>(
  sections: T[], stage: { key: string } | undefined,
): T | undefined {
  return stage ? sections.find((s) => s.key === stage.key) : undefined;
}

export type ConnectorKind = "solid" | "partial" | "dashed" | "dim";

/** The rail connector AFTER node `i` (#668): solid traces the walked in-sequence path,
 *  partial leaves the current node, dashed reaches a banked-ahead node, dim otherwise. */
export function connectorKind(stages: Stage[], i: number): ConnectorKind {
  const role = stages[i]?.status;
  const next = stages[i + 1]?.status;
  // A banked-ahead node (done out of sequence) is reached by a dashed connector.
  if (role === "ahead" || next === "ahead") return "dashed";
  // The walked path is green UP TO the current node: every connector positioned BEFORE the
  // active node is solid — including the one leaving a skipped/optional section — so the
  // green leads INTO the current node, never out of it. Beyond the current node: dim (#668).
  const activeIdx = stages.findIndex((p) => p.status === "active");
  const frontier = activeIdx >= 0 ? activeIdx : stages.length;
  return i < frontier ? "solid" : "dim";
}

/** Index of the active stage (else the last) — what the selection auto-follows. */
export function activeIndex(stages: Stage[]): number {
  const a = stages.findIndex((p) => p.status === "active");
  return a >= 0 ? a : Math.max(0, stages.length - 1);
}

/** Clamp an index into [0, count-1] (0 when empty) — guards against a shrunk stage list
 *  after a blueprint switch / clear. */
export function clampIndex(i: number, count: number): number {
  if (count <= 0) return 0;
  return Math.min(Math.max(0, i), count - 1);
}

export type GatePill = "pass" | "wait";

/** Gate pill for a stage, from the declarative gate (#897 Phase 4c removed the legacy
 *  pipeline gate): "pass" once the stage's gateRule is satisfied, else "wait". */
export function gatePill(stage: Stage): GatePill {
  return stage.status === "complete" || stage.status === "ahead" ? "pass" : "wait";
}

/** Whether a stage has any GUIDANCE to reveal (#3257) — the gate's unmet requirements (while it's
 *  blocking) and/or a suggested next-step prompt. Drives whether the gate pill acts as a disclosure
 *  TOGGLE for the guidance card: with nothing to reveal the pill stays a plain status chip. */
export function hasStageGuidance(stage: Stage, pill: GatePill, prompt?: StagePrompt, onInject?: (text: string) => void): boolean {
  const showReqs = pill !== "pass" && (stage.unmet ?? []).length > 0;
  const showPrompt = !!prompt && !!onInject;
  return showReqs || showPrompt;
}

export type FooterKind = "back-to-current" | "jump-to-current" | "approve-continue" | "route-design" | "publish" | "awaiting";

export interface FooterAction {
  kind: FooterKind;
  enabled: boolean;
  /** Whether this action KIND supports a Skip control — set by {@link footerAction} on the active-stage
   *  advance actions (approve-continue / route-design), never on navigation/publish. A marker only:
   *  {@link resolveFooter} decides whether Skip actually RENDERS (`skipEnabled`) from the live signals. */
  canSkip?: boolean;
  /** Whether the Skip control RENDERS as an actionable button (#2854): true only when the stage is
   *  skippable now (its `skipWhen` rule passes / it's intrinsically optional) OR the user enabled
   *  "allow gate override" (#1285). A required stage like Discovery shows NO Skip — not a disabled
   *  ghost (the #2533 always-visible-Skip behavior regressed into a greyed button beside "gate
   *  blocking…"). The footer renders Skip iff this is set. */
  skipEnabled?: boolean;
}

/**
 * The advance-bar's primary action, by where the selection sits relative to the active
 * stage. Browsing a future (locked) stage → back to current; a past stage → jump to
 * current; on the active stage → approve & continue, or publish when the plan is complete.
 *
 * `userGated` (#funnel-ui-into-stores) is what turns this bar from a CONTROL into a PROGRESS
 * readout. Under the three-tier funnel the director advances the Features and Plan gates itself when
 * the requirement's authority covers them (#funnel-unattended-director), so an "approve & continue"
 * button there would offer the user a decision that is no longer theirs to make — and worse, one that
 * has often already been made. Those stages report `awaiting` instead: the funnel is running, watch it.
 *
 * A stage that keeps a REAL user gate passes `userGated: true` and is unchanged. The transformation
 * queue is the standing example, and the reason is worth carrying: it reverse-scopes a RUNNING app
 * rather than shaping one being created.
 *
 * `canSkip` marks the active-stage advance actions (approve-continue, route-design) as skip-ELIGIBLE
 * — a marker, not a render decision. Whether Skip actually appears is decided later by
 * {@link resolveFooter} (`skipEnabled`) from the live signals: skippable stage or gate-override on.
 * Navigation, publish and `awaiting` are never skip-eligible.
 */
export function footerAction(
  selectedIdx: number, activeIdx: number, planComplete: boolean, currentGateReady: boolean,
  routeDesign = false, userGated = true,
): FooterAction {
  if (selectedIdx > activeIdx) return { kind: "back-to-current", enabled: true };
  if (selectedIdx < activeIdx) return { kind: "jump-to-current", enabled: true };
  if (planComplete) return { kind: "publish", enabled: true };
  // #2121: the active UI stage whose design is missing or stale → the primary action ROUTES the
  // design (sync the skeleton + mark it current) instead of advancing. It's skip-eligible too —
  // routing and skipping are both valid choices — but resolveFooter still gates the actual Skip.
  if (routeDesign) return { kind: "route-design", enabled: true, canSkip: true };
  // Not user-gated ⇒ the director advances this stage under authority. Report, do not offer.
  // Deliberately NOT skip-eligible: skipping is a user decision about a gate the user no longer holds.
  if (!userGated) return { kind: "awaiting", enabled: false };
  return { kind: "approve-continue", enabled: currentGateReady, canSkip: true };
}

/**
 * Stage ids that keep a REAL user gate under the funnel (#funnel-ui-into-stores). Everything else
 * advances under the requirement's authority clauses, so its advance bar reports rather than offers.
 *
 * An ALLOW-list, not a deny-list, and that direction is the point: a stage added later is
 * authority-governed by default and has to argue its way onto this list, rather than silently keeping
 * a human gate nobody revisited.
 */
export const USER_GATED_STAGES: readonly string[] = ["transformations"];

/** Whether `stageId` keeps a user gate — see {@link USER_GATED_STAGES}. */
export function isUserGated(stageId: string | undefined): boolean {
  return !!stageId && USER_GATED_STAGES.includes(stageId);
}

/**
 * Resolve the final advance-bar action from the raw {@link footerAction}. Two independent axes:
 *
 * PRIMARY — a blocking "approve & continue" (gate not ready) lights up when `pendingCount > 0`:
 * there are drafted-but-unconfirmed sections and clicking confirms them (the one-click approval).
 * Otherwise the primary stays disabled ("gate blocking…").
 *
 * SKIP (#2854) — the Skip control RENDERS (`skipEnabled`) only when the KIND is skip-eligible
 * (`canSkip`) AND the active stage is skippable now (its `skipWhen` rule passes / it's intrinsically
 * optional) OR the user enabled gate override (#1285). A required stage (Discovery) shows NO Skip —
 * not a disabled ghost. When Skip renders it is always actionable, so there is no disabled state.
 *
 * Pure + unit-tested.
 */
export function resolveFooter(
  raw: FooterAction, pendingCount: number, allowOverride: boolean, skippable: boolean,
): FooterAction {
  // Skip renders only when its KIND is eligible AND the stage is skippable now (or override is on).
  const withSkip = raw.canSkip ? { ...raw, skipEnabled: skippable || allowOverride } : raw;
  // One-click confirm lights the blocking primary; nothing else force-enables it now.
  if (withSkip.kind !== "approve-continue" || withSkip.enabled) return withSkip;
  if (pendingCount > 0) return { ...withSkip, enabled: true };
  return withSkip;
}

/** Whether the active stage's gate is satisfied — enables "approve & continue". */
export function currentGateReady(sections: BlueprintStage[], signals: PlanSignals): boolean {
  const cur = currentStage(sections, signals);
  return !!cur && evalGate(cur.gateRule, signals).done;
}

/**
 * Whether the auto-complete-gates effect should confirm the active stage's pending sections (#1068):
 * the global flag is on, the planning autopilot is NOT driving (it owns confirmation then), and the
 * active stage actually has sections awaiting confirmation. The same "approve & continue" action the
 * user would click, minus the click — so it advances exactly the gates the manual path would.
 */
export function shouldAutoCompleteGate(autoOn: boolean, autopilotActive: boolean, pending: string[]): boolean {
  return autoOn && !autopilotActive && pending.length > 0;
}

// The rail FOLDER TREE (#4128) — the ONE nested-folder model both library rails render.
//
// Components (`RailTree`) and Algorithms (`AlgorithmsRail`) each browse a library organized like a
// completed project's folders: a `/`-delimited path per record (derived from its source by the shared
// `bsc_util::folder_from_src`, so a component and an algorithm harvested from the same tree land in the
// same place) split into nested folders. Until #4128 each feature owned its own builder — components'
// `groupComponentsByFolder` (#3048/#3582) and algorithms' `folderTree` (#4107) — which had silently
// diverged on the two decisions that are actually visible in the rail:
//
//   * an item with NO folder: components bucketed it into a trailing "ungrouped" folder, algorithms
//     spilled it flat beside the tree;
//   * folder order: components kept first-appearance order (of already-sorted rows), algorithms re-sorted
//     alphabetically and ignored the caller's ordering.
//
// Two implementations of "the same structure" cannot stay the same by agreement, so this is the single
// one. Generic over the record type — it only ever asks for a record's folder path — so neither feature's
// model leaks into `shared/`.
//
// Pure and React-free: the tree shape is testable without a render, and both rails' tests exercise the
// same code the app does.

/** Header label of the trailing bucket holding the records that carry no folder. */
export const UNGROUPED_LABEL = "ungrouped";

/** The stable expand-state key of the trailing {@link UNGROUPED_LABEL} folder. A sentinel, so it can
 *  never collide with a real single-segment folder path (a source folder is never literally named this). */
export const UNGROUPED_KEY = "__ungrouped__";

/**
 * One folder of a library's tree — a folder that mirrors a segment of its records' folder paths
 * (`shared` › `ui` › `controls`).
 *
 * A folder holds BOTH sub-`folders` (deeper path segments) AND direct `items` (records whose path ends
 * exactly here — a component grouped `shared/ui` sits directly under the `ui` folder alongside its
 * `controls`/`data` subfolders).
 */
export interface FolderNode<T> {
  /** Stable expand-state key — the folder's FULL path (`shared/ui/controls`), or {@link UNGROUPED_KEY}
   *  for the trailing bucket. Unique within one tree. */
  key: string;
  /** Header label — the LAST path segment (`controls`), or {@link UNGROUPED_LABEL} for the bucket. */
  label: string;
  /** Whether this is the forced-last bucket of records carrying no folder. */
  ungrouped: boolean;
  /** Child folders (deeper path segments), in first-appearance order. */
  folders: FolderNode<T>[];
  /** Records whose folder path ENDS at this folder (its direct members). */
  items: T[];
}

/** Total records under a folder, transitively (its own + every descendant's) — the header count. A
 *  collapsed folder still has to say how much is inside it, or a deep tree gives no sense of where the
 *  work lives. */
export function folderItemCount<T>(f: FolderNode<T>): number {
  return f.items.length + f.folders.reduce((n, sub) => n + folderItemCount(sub), 0);
}

/**
 * Partition records into a nested FOLDER TREE by their folder path — split each path on `/` and nest
 * (`shared/ui/controls` → `shared` › `ui` › `controls`), so a library browses like a project's folders.
 * A record sits at the LEAF of its path.
 *
 * Order is the CALLER's: folders appear in the first-appearance order of the passed (already-sorted)
 * records, and a folder's own records keep their relative order — so a rail that sorts pages first, or
 * primitives before algorithms, keeps that reading inside every folder. The "ungrouped" bucket is forced
 * LAST at the root.
 *
 * Returns `null` when NO record carries a folder, so a caller renders its flat list exactly as it would
 * without folders at all — a library that has not been foldered yet must not collapse under one blank
 * node. A depth-1 path (`forms`) yields a single root folder with no subfolders: the flat case is just
 * the shallow case of this tree.
 *
 * @param items    the records to organize, in the order they should read
 * @param folderOf a record's `/`-delimited folder path; blank/absent ⇒ the ungrouped bucket
 */
export function buildFolderTree<T>(
  items: readonly T[],
  folderOf: (item: T) => string | undefined,
): FolderNode<T>[] | null {
  if (!items.some((it) => (folderOf(it) ?? "").trim())) return null;

  // Mutable builder: `children` is a Map so it preserves first-appearance insertion order.
  interface Build {
    key: string;
    label: string;
    ungrouped: boolean;
    children: Map<string, Build>;
    items: T[];
  }
  const mk = (key: string, label: string, ungrouped = false): Build => ({
    key,
    label,
    ungrouped,
    children: new Map(),
    items: [],
  });

  const roots = new Map<string, Build>();
  let ungrouped: Build | null = null;

  for (const it of items) {
    const path = (folderOf(it) ?? "").trim();
    if (!path) {
      ungrouped ??= mk(UNGROUPED_KEY, UNGROUPED_LABEL, true);
      ungrouped.items.push(it);
      continue;
    }
    const segs = path.split("/").map((s) => s.trim()).filter(Boolean);
    // A path of only separators/blanks (`"/"`, `"  /  "`) has no usable segment — treat it as unfoldered
    // rather than manufacturing a `""` node the rail would render as a nameless folder.
    if (segs.length === 0) {
      ungrouped ??= mk(UNGROUPED_KEY, UNGROUPED_LABEL, true);
      ungrouped.items.push(it);
      continue;
    }
    let level = roots;
    let node: Build | null = null;
    let acc = "";
    for (const seg of segs) {
      acc = acc ? `${acc}/${seg}` : seg;
      let child = level.get(seg);
      if (!child) {
        child = mk(acc, seg);
        level.set(seg, child);
      }
      node = child;
      level = child.children;
    }
    // `node` is non-null: a non-empty `segs` yields at least one iteration.
    node!.items.push(it);
  }

  const freeze = (b: Build): FolderNode<T> => ({
    key: b.key,
    label: b.label,
    ungrouped: b.ungrouped,
    folders: [...b.children.values()].map(freeze),
    items: b.items,
  });

  const out = [...roots.values()].map(freeze);
  if (ungrouped) out.push(freeze(ungrouped)); // forced last
  return out;
}

// Shared presentation helpers (#1471) — feature-agnostic, pure. Used by the GitHub and
// planner summaries. Extracted to remove byte-identical copies in ProjectsSummary +
// GitHubSummary.

/**
 * A coarse "time since" label from an ISO timestamp: `5s ago` / `3m ago` / `2h ago` /
 * `4d ago` / `2mo ago`. Returns "" for an empty, non-finite, or future timestamp.
 */
export function timeAgo(iso: string): string {
  return sinceLabel(iso, " ago");
}

/** Compact variant of {@link timeAgo} without the trailing " ago": `5s` / `4d` / `2mo`. */
export function timeAgoShort(iso: string): string {
  return sinceLabel(iso, "");
}

function sinceLabel(iso: string, suffix: string): string {
  if (!iso) return "";
  const s = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
  if (!isFinite(s) || s < 0) return "";
  if (s < 60) return `${s}s${suffix}`;
  const m = Math.floor(s / 60); if (m < 60) return `${m}m${suffix}`;
  const h = Math.floor(m / 60); if (h < 24) return `${h}h${suffix}`;
  const d = Math.floor(h / 24); if (d < 30) return `${d}d${suffix}`;
  return `${Math.floor(d / 30)}mo${suffix}`;
}

/** A coarse "time since" label from epoch millis; "—" when non-positive. */
export function timeAgoMs(ms: number): string {
  return ms > 0 ? timeAgo(new Date(ms).toISOString()) : "—";
}

/**
 * A stable 32-bit unsigned hash of a string (`h = h*31 + charCode`, truncated to
 * uint32 each step). Deterministic, so the same string always hashes the same — the
 * shared core behind the continuous-hue color helpers ({@link loginColor} + the fleet
 * board's profile color). Callers map the hash to their own space (e.g. `% 360` for a hue).
 *
 * Note: `hueFor` (per-step `% 360`) and the discrete `avatarColor` (per-step `& 0xffff`)
 * use *different* reductions and are intentionally NOT built on this — they'd produce
 * different colors.
 */
export function hashString(s: string): number {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return h;
}

/** A stable oklch color hashed from a login, so the same user always renders the same hue. */
export function loginColor(login: string): string {
  return `oklch(0.68 0.12 ${hashString(login) % 360})`;
}

/** A deterministic hue (0–359) hashed from a string — a tile/category accent. */
export function hueFor(s: string): number {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) % 360;
  return h;
}

/** Human-readable byte size: `0 B` / `1.5 KB` / `2.3 GB` / `1.1 TB`. */
export function fmtBytes(n: number): string {
  if (n <= 0) return "0 B";
  const u = ["B", "KB", "MB", "GB", "TB"];
  const i = Math.min(u.length - 1, Math.floor(Math.log(n) / Math.log(1024)));
  return `${(n / Math.pow(1024, i)).toFixed(i === 0 ? 0 : 1)} ${u[i]}`;
}

/**
 * Truncate `s` with a `…` when it exceeds `max` characters (#2421 — the one home for the
 * five hand-rolled ellipsis chains).
 *
 * `keep` is how many characters survive before the ellipsis and defaults to `max` — the
 * "hard cap" shape (`s.slice(0, max) + "…"` only when longer, e.g. an issue body preview).
 * Pass a smaller `keep` for the "display budget" shape the label sites use, where the
 * truncated form must fit the same budget as the untruncated one (e.g. `truncate(s, 20, 18)`).
 */
export function truncate(s: string, max: number, keep = max): string {
  return s.length > max ? `${s.slice(0, keep)}…` : s;
}

/**
 * Kebab-case slug: lowercase, every run of non-alphanumerics collapsed to a single `-`,
 * edge dashes stripped, optionally capped at `max` characters (#2421 — the one home for the
 * planner/source/DesignsWorkbench copies). Returns `""` for input with no alphanumerics — callers
 * that need a fallback apply their own (`slugify(x, 40) || "source"`).
 *
 * NOT {@link sanitizeProjectKey} (../core/projectPaths.ts): that mirrors the Rust backend
 * byte-for-byte (keeps case, `_` replacement, cap 80) and must not change; this is the
 * display/id kebab-case convention.
 *
 * Note: the cap is applied AFTER edge-stripping (matching every former copy), so a capped
 * slug can still end in a `-` when the cut lands on a word boundary.
 */
export function slugify(s: string, max?: number): string {
  const slug = s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  return max != null ? slug.slice(0, max) : slug;
}

/** Local wall-clock `HH:MM` (or `HH:MM:SS` with `{ seconds: true }`) for an epoch-ms
 *  timestamp; `—` for null (#2421 — automations' HH:MM + MCP Analytics' HH:MM:SS unified). */
export function fmtClock(ms: number | null, opts: { seconds?: boolean } = {}): string {
  if (ms == null) return "—";
  const d = new Date(ms);
  const hm = `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
  return opts.seconds ? `${hm}:${String(d.getSeconds()).padStart(2, "0")}` : hm;
}

/** Local `YYYY-MM-DD` for an epoch-ms timestamp — the daily-bucket key the telemetry
 *  aggregators and their charts share (#2421; was byte-identical in hook/mcp telemetry). */
export function dayKey(ts: number): string {
  const d = new Date(ts);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

// Filesystem confinement (#158) — the file-tool axis of per-session repo isolation.
//
// A session for repo A shouldn't read/write files in sibling repos. The `bsc-confine`
// PreToolUse hook (gated panes) blocks Claude's file tools (Read/Edit/Write/MultiEdit/
// NotebookEdit) when their target path escapes the session's repo root. This module is
// the pure decision the hook mirrors in shell — so the rule is unit-tested even though
// the runtime check runs in bash.
//
// Deliberately conservative + string-based (no realpath, portable across OSes): any
// `..` segment is rejected, and an absolute path must sit under the repo root. It only
// covers the AI's file tools — true Bash-command confinement needs OS-level sandboxing.

function normalize(p: string): string {
  return p.replace(/\\/g, "/");
}

/** Absolute paths: POSIX (`/…`), home (`~…`), Windows drive (`C:…`), or UNC (`\\…`). */
function isAbsolute(p: string): boolean {
  return /^(\/|~|[A-Za-z]:)/.test(p) || p.startsWith("\\\\");
}

/** True if any path segment is a `..` (an upward traversal). */
function hasParentSegment(p: string): boolean {
  return normalize(p).split("/").some((seg) => seg === "..");
}

function underRoot(root: string, target: string): boolean {
  const r = normalize(root).replace(/\/+$/, "");
  const t = normalize(target);
  return t === r || t.startsWith(r + "/");
}

/**
 * Whether a file-tool target stays within `repoRoot`:
 * - empty path → confined (not a path op);
 * - any `..` segment → NOT confined (rejected conservatively, even within-repo);
 * - absolute path → confined only if it sits under `repoRoot`;
 * - plain relative path → confined (resolved against the repo-root cwd).
 */
export function isPathConfined(repoRoot: string, target: string): boolean {
  if (!target) return true;
  if (hasParentSegment(target)) return false;
  if (isAbsolute(target)) return underRoot(repoRoot, target);
  return true;
}

/**
 * Whether a **read** may reach `target` even though it sits OUTSIDE the repo root: it is an absolute
 * path under one of the session's declared read-only HARVEST roots (#3509 / #3530).
 *
 * #3509 widened what `bsc ui harvest` / `bsc graph harvest` may SCAN via `$BSC_HARVEST_ROOTS`, but the
 * session's Read tool is gated by the separate `bsc-confine` hook, which knew nothing of those roots — so
 * the designer could harvest components from the app repo yet not Read the sibling files they import
 * (the utility/hook/type modules harvest doesn't surface). This closes that: a Read of a harvest root is
 * allowed. It is deliberately **read-only** — only the caller's `Read` tool composes this; Write/Edit stay
 * confined — so a harvest root grants no write anywhere, matching the #3509 contract.
 *
 * Same conservatism as {@link isPathConfined}: a `..` segment is rejected, and only ABSOLUTE paths are
 * considered (a plain relative path resolves against the repo-root cwd, so it is in-repo by construction
 * and can only escape via `..`, which is already blocked). Empty roots contribute nothing.
 */
export function isUnderHarvestRoot(harvestRoots: readonly string[], target: string): boolean {
  if (!target || hasParentSegment(target) || !isAbsolute(target)) return false;
  return harvestRoots.some((r) => r && underRoot(r, target));
}

/**
 * Whether `target` is the session's OWN `.claude/` config (the hook list + permissions) — which the
 * file tools must never touch, even though it sits INSIDE the repo root (so {@link isPathConfined}
 * passes it). The `bsc-confine` hook blocks it too (#1916 config self-protection): an agent must not
 * be able to edit `settings.json` to remove the confinement hooks once a session runs under
 * `bypassPermissions`, where the `permissions.deny` rule that used to guard it is ignored. Only the
 * repo-root `.claude` is protected (a nested `src/.claude` is not the session config).
 */
export function isConfigProtected(repoRoot: string, target: string): boolean {
  if (!target) return false;
  const r = normalize(repoRoot).replace(/\/+$/, "");
  const t = normalize(target).replace(/\/+$/, "");
  const rel = (t === r ? "" : t.startsWith(r + "/") ? t.slice(r.length + 1) : t).replace(/^\.\//, "");
  return rel === ".claude" || rel.startsWith(".claude/");
}

import type { ConsoleProvider } from "@/app/console/lib/providers/types";

export const geminiProvider: ConsoleProvider = {
  id: "gemini",
  displayName: "Gemini CLI",
