  prereqProbe: "which gemini",
};

// The node — `{ type, props, children, binds, actions }` over the full primitive registry (#3485,
// #3496, #3500; the keystone is #3484).
//
// This REPLACED a closed `KitNode` union of 8 hardcoded kinds (card/header/field/button/row/toggle/
// tag/text) that could address only 8 of the ~67 primitives in the manifest, each with its own
// hand-written branch in the renderer. #3500 deleted that vocabulary outright: a node now names a real
// component, so the authorable surface IS the kit.
//
// THE VOCABULARY IS DERIVED, NOT DECLARED. Both the set of valid `type`s and the per-type prop rules
// come from `UI_KIT` (`shared/ui/manifest.ts`), so adding a primitive there makes it authorable here
// with no edit to this file. A hand-maintained mirror would drift, and a contract that drifts from the
// code is worse than no contract — agents author against it.
import { UI_KIT, type PrimitiveName, type PropSpec } from "@/shared/ui/manifest";

/** A node addressing any primitive in the manifest. `props` is open; the validator constrains it. */
export interface GeneralNode {
  type: PrimitiveName;
  props?: Record<string, unknown>;
  /**
   * Children — nodes, or plain TEXT.
   *
   * Text is included because the manifest types `children` as `node`, and a `node` slot legitimately
   * holds text — `<Text>hello</Text>` is the commonest node in the tree. An array-only type here would
   * be NARROWER than what the validator accepts, and a type that disagrees with the contract it
   * describes is worse than no type: the compiler would reject trees the runtime happily validates.
   */
  children?: GeneralNode[] | GeneralNode | string | number;
  /**
   * Handlers, as prop name → host ACTION NAME (#3496).
   *
   * The renderer otherwise learns which props are handlers from the manifest's declared
   * `type: "function"` — deliberately, so it never infers meaning from a prop's NAME. But 9 primitives
   * are `passthrough`: they forward arbitrary DOM props by design, so their handlers are *undeclared*
   * and that inference has nothing to work from. `Button` does not declare `onClick`, which is the
   * commonest handler in any UI.
   *
   * This map closes that without guessing: it states outright which props are handlers. It also
   * generalises the legacy vocabulary, where a `button` node already carried a node-level `action`.
   *
   * PRECEDENCE: an entry here WINS over a declared `function` prop of the same name. The map is the
   * more explicit statement, and letting the implicit path override an explicit one would be
   * surprising in exactly the case where an author is trying to be unambiguous.
   */
  actions?: Record<string, string>;
  /**
   * Value bindings, as prop name → host STATE KEY (#3500).
   *
   * The mirror of {@link actions}: that map carries behaviour *out* of the tree, this brings state
   * *in*. The renderer reads `values[key]` and passes it as the prop, so a control can show host state
   * without the tree containing that state.
   *
   * WRITES GO THROUGH `actions`, deliberately. The legacy `toggle`/`field` kinds derived the writer
   * automatically (`onBind(bind, !isOn)`), which required the renderer to know that `on` pairs with
   * `onClick` and `value` with `onChange` — pairing the manifest does not declare, so deriving it means
   * inferring from prop NAMES. This design has refused that three times; it refuses it here too. The
   * host exposes an action instead, which also makes the state write visible in the host rather than
   * invisible magic inside the renderer.
   */
  binds?: Record<string, string>;
}

/** Every primitive name the manifest defines — the closed `type` vocabulary. */
export const PRIMITIVE_NAMES: readonly string[] = UI_KIT.map((p) => p.name);

const BY_NAME = new Map(UI_KIT.map((p) => [p.name as string, p]));

/**
 * What the validator can and cannot enforce, stated exactly (#3485).
 *
 * `PropSpec.type` is a CLOSED 13-member union with an explicit `values` list for enums, so most props
 * get real enforcement. The two genuine gaps are `array` and `object`, whose element/field shapes the
 * manifest keeps in prose (`description`) rather than as a machine-readable schema — so the container
 * type is checked and its CONTENTS are not.
 *
 * This is published rather than left implicit on purpose: `bsc ui validate` reporting "valid" while
 * silently meaning "the names look right" is a half-truth that gets trusted and then bites. Anything
 * that consumes this contract can read exactly where the guarantees stop.
 */
export const VALIDATION_COVERAGE: Readonly<Record<string, "checked" | "container-only">> = {
  string: "checked",
  number: "checked",
  boolean: "checked",
  enum: "checked",
  node: "checked",
  function: "checked",
  color: "checked",
  space: "checked",
  fontSize: "checked",
  tracks: "checked",
  style: "container-only",
  array: "container-only",
  object: "container-only",
};

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/** A node-ish value — an object naming a primitive with `type`. */
function isNodeLike(v: unknown): boolean {
  return isPlainObject(v) && typeof v.type === "string";
}

/**
 * Check one prop VALUE against its spec. Returns an error message, or null when acceptable.
 *
 * Note `function`: in a data tree a handler can never be a literal — it is the NAME of an action the
 * host exposes (the `bind`/`action` seam). So requiring a string here is not a weaker check than a type
 * check, it is a stricter and more meaningful one: a serialized function would be nonsense, and an
 * inline arrow would mean the tree had stopped being data.
 */
function checkValue(spec: PropSpec, value: unknown): string | null {
  switch (spec.type) {
    case "string":
      return typeof value === "string" ? null : `expected a string`;
    case "number":
      return typeof value === "number" ? null : `expected a number`;
    case "boolean":
      return typeof value === "boolean" ? null : `expected a boolean`;
    case "enum": {
      const allowed = spec.values ?? [];
      if (allowed.length === 0) return null; // an enum with no declared set constrains nothing
      return allowed.includes(value as string)
        ? null
        : `"${String(value)}" is not one of ${allowed.join(", ")}`;
    }
    case "node":
      // A slot: a child node, a list of them, or plain text.
      if (typeof value === "string" || typeof value === "number") return null;
      if (Array.isArray(value)) return value.every(isNodeLike) ? null : `expected nodes or text`;
      return isNodeLike(value) ? null : `expected a node, a list of nodes, or text`;
    case "function":
      return typeof value === "string"
        ? null
        : `expected an action NAME (a string) — a data tree binds handlers by name, it cannot carry a function`;
    case "color":
      return typeof value === "string" ? null : `expected a color string (token or CSS color)`;
    case "space":
    case "fontSize":
      return typeof value === "number" || typeof value === "string"
        ? null
        : `expected a rung name or a number`;
    case "tracks":
      return typeof value === "number" || typeof value === "string"
        ? null
        : `expected a track count (number) or a template string`;
    case "style":
      return isPlainObject(value) ? null : `expected a style object`;
    case "array":
      // Contents deliberately unchecked — see VALIDATION_COVERAGE.
      return Array.isArray(value) ? null : `expected an array`;
    case "object":
      return isPlainObject(value) ? null : `expected an object`;
    default:
      return null;
  }
}

/**
 * Structurally validate a node tree against the manifest. Returns a flat list of human-readable errors
 * (empty = valid), identical to what `bsc ui validate` prints for the same tree — the two validators
 * are held to that by a shared fixture set (`node-validation.fixtures.json`).
 *
 * At every node: `type` present and a real primitive · every required prop present · no prop outside
 * the primitive's declared set (UNLESS it declares `passthrough`, which legitimately accepts arbitrary
 * DOM props) · every present prop's value acceptable for its declared `PropType` · recursion into
 * `children` and into any node-valued prop.
 *
 * @param node - the value to validate (typically parsed from agent-emitted JSON)
 * @param path - dotted path used to locate errors (defaults to "$")
 */
export function validateGeneralNode(node: unknown, path = "$"): string[] {
  const errors: string[] = [];
  walkGeneral(node, path, errors);
  return errors;
}

function walkGeneral(node: unknown, path: string, errors: string[]): void {
  if (!isPlainObject(node)) {
    errors.push(`${path}: expected a node object`);
    return;
  }
  const type = node.type;
  if (typeof type !== "string") {
    errors.push(`${path}: missing string "type"`);
    return;
  }
  const spec = BY_NAME.get(type);
  if (!spec) {
    errors.push(`${path}: unknown primitive "${type}"`);
    return;
  }

  const props = node.props;
  if (props !== undefined && !isPlainObject(props)) {
    errors.push(`${path}.props: expected an object`);
    return;
  }
  // Node-level `children` is SUGAR for the `children` PROP. The manifest models children the way React
  // does — a prop of type `node`, declared REQUIRED on containers (Stack/Row/Card/…) — but writing a
  // tree as `props: { children: [...] }` at every level is miserable. Normalising here means both forms
  // validate identically, and a bare `children` is not misread as "missing required prop".
  const given: Record<string, unknown> = { ...((props ?? {}) as Record<string, unknown>) };
  if (node.children !== undefined) given.children = node.children;
  const byProp = new Map(spec.props.map((p) => [p.name, p]));

  // Unknown props — skipped for a passthrough primitive, which forwards arbitrary DOM props
  // (className/style/data-*/handlers) to its root by design. Flagging those would be a false positive.
  if (!spec.passthrough) {
    for (const key of Object.keys(given)) {
      if (!byProp.has(key)) errors.push(`${path}.props.${key}: unknown prop for "${type}"`);
    }
  }

  // A prop can be supplied THREE ways — `props`, `binds` (value from host state) or `actions` (a host
  // handler) — so "required" must consider all of them. Checking only `props` would demand a literal
  // for `Toggle.on` even when it is bound, and for a REQUIRED handler like `Dialog.onDismiss` even when
  // it is wired through the actions map.
  const suppliedByMap = new Set([
    ...(isPlainObject(node.binds) ? Object.keys(node.binds) : []),
    ...(isPlainObject(node.actions) ? Object.keys(node.actions) : []),
  ]);

  for (const p of spec.props) {
    const v = given[p.name];
    if (p.required && v == null && !suppliedByMap.has(p.name)) {
      errors.push(`${path}.props.${p.name}: missing required prop for "${type}"`);
      continue;
    }
    if (v == null) continue; // an absent optional prop takes the component's default
    const err = checkValue(p, v);
    if (err) errors.push(`${path}.props.${p.name}: ${err}`);
  }

  // The node-level actions map (#3496): prop name → host action name.
  const actions = node.actions;
  if (actions !== undefined) {
    if (!isPlainObject(actions)) {
      errors.push(`${path}.actions: expected an object of prop → action name`);
    } else {
      for (const [propName, actionName] of Object.entries(actions)) {
        if (typeof actionName !== "string" || actionName === "") {
          errors.push(`${path}.actions.${propName}: expected a non-empty action name (a string)`);
        }
        const declared = byProp.get(propName);
        if (declared && declared.type !== "function") {
          // Binding a handler onto a prop the component treats as data would produce a function where
          // a value belongs — a mistake worth naming rather than rendering.
          errors.push(
            `${path}.actions.${propName}: "${propName}" is declared as ${declared.type}, not a handler, on "${type}"`,
          );
        }
        // An UNDECLARED key is legitimate only where undeclared props are (a passthrough primitive):
        // that is the whole reason this map exists. Elsewhere it is the same mistake as an unknown prop.
        if (!declared && !spec.passthrough) {
          errors.push(`${path}.actions.${propName}: unknown prop for "${type}"`);
        }
      }
    }
  }

  // The node-level binds map (#3500): prop name → host state key. Same shape rules as `actions`,
  // inverted in one respect — binding a VALUE onto a prop the manifest declares as a handler is the
  // mistake here, where for `actions` it was binding a handler onto a data prop.
  const binds = node.binds;
  if (binds !== undefined) {
    if (!isPlainObject(binds)) {
      errors.push(`${path}.binds: expected an object of prop → state key`);
    } else {
      for (const [propName, stateKey] of Object.entries(binds)) {
        if (typeof stateKey !== "string" || stateKey === "") {
          errors.push(`${path}.binds.${propName}: expected a non-empty state key (a string)`);
        }
        const declared = byProp.get(propName);
        if (declared && declared.type === "function") {
          errors.push(
            `${path}.binds.${propName}: "${propName}" is a handler on "${type}" — bind it with "actions", not "binds"`,
          );
        }
        if (!declared && !spec.passthrough) {
          errors.push(`${path}.binds.${propName}: unknown prop for "${type}"`);
        }
      }
    }
  }

  // Recurse into every node-valued prop (a slot) — `children` included, since it was normalised above.
  // The error path reports where the value was WRITTEN (`$.children[0]` vs `$.props.children[0]`) so a
  // message points at the author's own source rather than at the normalised form.
  const wroteChildrenAtNodeLevel = node.children !== undefined;
  for (const [name, value] of Object.entries(given)) {
    if (byProp.get(name)?.type !== "node") continue;
    const where = name === "children" && wroteChildrenAtNodeLevel ? `${path}.children` : `${path}.props.${name}`;
    if (Array.isArray(value)) {
      value.forEach((child, i) => {
        if (isNodeLike(child)) walkGeneral(child, `${where}[${i}]`, errors);
      });
    } else if (isNodeLike(value)) {
      walkGeneral(value, where, errors);
    }
  }
}

// Live issue-progression overlay (#393, Layer 2). Where buildGhStructure derives
// the *plan* (what GitHub objects this plan produces), this module derives the
// *progress*: for an already-published project it maps each structure node id to
// a NodeProgress reflecting what's actually CLOSED/done on GitHub.
//
// Pure - no React / Tauri / network. The caller fetches per-repo issue state and
// hands it here; this builds a deterministic id -> NodeProgress overlay the
// structure card renders (done checkmarks, per-repo rollups, an overall rollup).
// Kept I/O-free so it can be unit tested in isolation.

import type { GhStructure } from "@/features/planner/github/ghStructure";

/** One GitHub issue's live state, normalized from the REST `issues` payload. */
export interface IssueState {
  title: string;
  state: "open" | "closed";
  number: number;
  url: string;
  /** Milestone title the issue is pinned to, or null when unmilestoned. */
  milestone: string | null;
}

/**
 * Progress for a single structure node.
 * - Issue nodes: `done` (closed), plus `url`/`number` for linking.
 * - Rollup nodes (milestone/repo/project): `closed`/`total` counts; `done` when complete.
 */
export interface NodeProgress {
  done?: boolean;
  closed?: number;
  total?: number;
  url?: string;
  number?: number;
}

/** Case-insensitive, whitespace-trimmed key for matching an issue node label to a GitHub title. */
const norm = (s: string): string => s.trim().toLowerCase();

/**
 * Build the live-progression overlay: a structure-node id -> {@link NodeProgress}
 * map, derived from per-repo GitHub issue and milestone state. Pure and
 * deterministic.
 *
 * - **Issue nodes** (`issue:{repo}:{ref}`): matched to a GitHub issue by its
 *   persisted link (#393 Layer 1) — node id -> exact issue NUMBER — falling back
 *   to case-insensitive/trimmed title equality within the same repo. A match
 *   yields `{ done: state==="closed", url, number }`.
 * - **Repo nodes** (`repo:{fullName}`): rolled up from that repo's matched issue
 *   nodes -> `{ closed, total }` (total = matched issue nodes only).
 * - **Project node** (`project`): rolled up across all matched issues.
 * - **Stream nodes**: skipped - no reliable mapping without #393 Layer 1.
 *
 * @param structure        the derived GitHub object graph (node ids + labels)
 * @param issuesByRepo     full_name -> its GitHub issues (PRs already filtered out)
 * @param links            optional node id -> linked GitHub issue ({number,url}); when
 *                         present, an issue node is matched to that exact issue number
 *                         (robust to title drift) before falling back to title match.
 * @returns node id -> progress; nodes with no progress are simply absent.
 */
export function buildProgressOverlay(
  structure: GhStructure,
  issuesByRepo: Record<string, IssueState[]>,
  links?: Record<string, { number: number; url: string }>,   // nodeId -> linked GitHub issue
): Record<string, NodeProgress> {
  const overlay: Record<string, NodeProgress> = {};

  // Running tallies for the project rollup, across every repo's matched issues.
  let projClosed = 0;
  let projTotal = 0;

  // -- Issue + repo nodes ------------------------------------------------------
  for (const repo of structure.repos) {
    const fullName = repo.node.label;
    const issues = issuesByRepo[fullName] ?? [];
    // Index this repo's GitHub issues by normalized title for O(1) matching.
    // Last write wins on duplicate titles - fine; titles are effectively unique.
    const byTitle = new Map<string, IssueState>();
    for (const iss of issues) byTitle.set(norm(iss.title), iss);
    // Index by issue number too, so a persisted link (#393 Layer 1) matches the
    // exact GitHub issue regardless of title drift.
    const byNumber = new Map<number, IssueState>();
    for (const iss of issues) byNumber.set(iss.number, iss);

    let repoClosed = 0;
    let repoTotal = 0;

    for (const node of repo.issues) {
      // Robust path: a persisted link pins this node to a real GitHub issue
      // number; match by number first, then fall back to title equality.
      const linked = links?.[node.id];
      const match = (linked && byNumber.get(linked.number)) ?? byTitle.get(norm(node.label));
      if (!match) continue; // unmatched (e.g. legacy phase-tracker node) -> no progress
      const done = match.state === "closed";
      overlay[node.id] = { done, url: match.url, number: match.number };
      repoTotal++;
      projTotal++;
      if (done) {
        repoClosed++;
        projClosed++;
      }
    }

    if (repoTotal > 0) {
      overlay[repo.node.id] = { closed: repoClosed, total: repoTotal };
    }
  }

  // -- Project node ------------------------------------------------------------
  if (projTotal > 0) {
    overlay.project = { closed: projClosed, total: projTotal };
  }

  return overlay;
}

// Pure helpers for the project planner's GitHub object graph.
//
// Kept free of React / xterm / Tauri imports so the derivation logic can be unit
// tested in isolation and shared between Planning.tsx and its tests.

import { parseFeaturesFile, featuresToPlanIssues } from "@/features/planner/issues/featureList";
import type { FleetPlan } from "@/features/planner/fleet/planFleet";

// The planner is dynamic: Claude documents whatever topics a project warrants,
// so a section key is any file stem (`goal`, `security`, `data_lifecycle`, or a
// per-repo `repo__web__api`). `goal` remains semantically special — the publish
// flow keys the project title off it.
export type SectionKey = string;
export type SectionState = "pending" | "drafted" | "confirmed";

export interface Section {
  k: SectionKey;
  title: string;
  state: SectionState;
  content: string;
}

export interface GhNode { id: string; label: string; }

/** A repository plus the issues that belong to it (one per feature). */
export interface GhRepoNode {
  node: GhNode;
  issues: GhNode[];
}

/** A fleet stream as a GitHub object: the `stream:<id>` label and the issues it owns. */
export interface GhStreamNode {
  /** Status-map id, namespaced `stream:<id>` (also the label name). */
  id: string;
  label: string;
  repo: string;
  /** Owned issue refs (e.g. `#12`). */
  issues: string[];
}

export interface GhStructure {
  project: GhNode;
  repos: GhRepoNode[];
  streams: GhStreamNode[];
}

/**
 * Derive the GitHub object graph from the confirmed/drafted plan. Pure — the
 * publish flow uses the same node ids so its status updates line up with the
 * structure card one-to-one.
 *
 * - one project board node
 * - one repo node per linked repository, each owning one issue per feature
 *
 * Issue ids are namespaced by repo (`issue:{fullName}:{ref}`).
 */
export function buildGhStructure(
  sections: Section[],
  repos: string[],
  projectTitle: string,
  fleet?: FleetPlan,
): GhStructure {
  // Issues are generated from the features (one per feature) — issues aren't authored during
  // planning (#plan-db). The card shows the same nodes publish will create.
  const planIssues = featuresToPlanIssues(parseFeaturesFile(sections.find(s => s.k === "features")?.content ?? ""));
  return {
    project:    { id: "project", label: projectTitle },
    repos: repos.map((fullName, repoIdx) => ({
      node:   { id: `repo:${fullName}`, label: fullName },
      // Granular issues (#311): one node per PlanIssue belonging to this repo (its
      // `repo`, or the default repo when unset).
      issues: planIssues
        .filter(iss => iss.repo ? iss.repo === fullName : repoIdx === 0)
        .map((iss, idx) => ({ id: `issue:${fullName}:${iss.ref ?? idx}`, label: iss.title })),
    })),
    streams: (fleet?.streams ?? []).map(st => ({
      id:     `stream:${st.id}`,
      label:  st.name,
      repo:   st.repo,
      issues: st.issues,
    })),
  };
}

// Extension manifest envelope (#598) — the single wrapper every distributable thing
// ships in: blueprints today, MCP / skills / app-state later. One envelope means one
// install / validate / store path regardless of kind. Pure (no React/Tauri) so it's
// shared by the importer, the share-code path, and (later) the gist layer.

/** Bump only on a breaking envelope change; an app refuses a NEWER manifest it can't read. */
export const MANIFEST_VERSION = 1;

/** Distributable kinds. `blueprint` (shared today), `app-state` (#2272 — the app-wide demo/state
 *  snapshot), `component-kit` (#2305), `sound-kit` (#3372 — a shareable sound kit, the sounds twin of
 *  `component-kit`) and `studio` (#2891 — the app-library snapshot bundle) are live; `mcp`/`skill` are
 *  reserved. (The legacy code-bearing `pipeline` kind was removed in #2271 — a dead concept.) NOTE: the
 *  type union and the `KINDS` array MUST stay in sync (validateManifest checks membership against
 *  `KINDS`). */
export type ExtensionKind =
  | "blueprint" | "mcp" | "skill" | "app-state" | "component-kit" | "sound-kit" | "studio";
const KINDS: ExtensionKind[] = [
  "blueprint", "mcp", "skill", "app-state", "component-kit", "sound-kit", "studio",
];

/** Capabilities a code-bearing extension may request (declared + user-approved at
 *  install, enforced by the sandbox). Reserved for future code-bearing kinds; the
 *  current data-only kinds (blueprint/mcp/skill) declare none. */
export type Capability = "read-signals" | "write-files" | "render" | "network";

/** The wire/file/share-code envelope. `payload` is the kind-specific object. */
export interface ExtensionManifest<P = unknown> {
  /** Envelope version (see MANIFEST_VERSION). */
  manifest: number;
  kind: ExtensionKind;
  /** Stable extension id (slug). */
  id: string;
  name: string;
  /** Author-set version string (semver-ish); used for update prompts + integrity. */
  version: string;
  author?: string;
  description?: string;
  /** Minimum app version that can run this (string compare is the caller's job). */
  minAppVersion?: string;
  /** Requested capabilities — empty/absent for data-only kinds. */
  capabilities?: Capability[];
  /** Optional content hash (e.g. sha256), recorded at install so silent gist edits can't slip in.
   *  Absent unless the producer sets it. */
  integrity?: string;
  payload: P;
}

export interface WrapMeta {
  author?: string;
  description?: string;
  minAppVersion?: string;
  capabilities?: Capability[];
  integrity?: string;
}

/** Build an envelope around a kind-specific payload. */
export function wrapExtension<P>(
  kind: ExtensionKind, id: string, name: string, version: string, payload: P, meta: WrapMeta = {},
): ExtensionManifest<P> {
  const m: ExtensionManifest<P> = { manifest: MANIFEST_VERSION, kind, id, name, version, payload };
  if (meta.author) m.author = meta.author;
  if (meta.description) m.description = meta.description;
  if (meta.minAppVersion) m.minAppVersion = meta.minAppVersion;
  if (meta.capabilities && meta.capabilities.length) m.capabilities = meta.capabilities;
  if (meta.integrity) m.integrity = meta.integrity;
  return m;
}

export type ValidateResult =
  | { ok: true; manifest: ExtensionManifest }
  | { ok: false; error: string };

/**
 * Validate an unknown value as an ExtensionManifest. Checks the envelope only (not the
 * kind-specific payload — kind handlers do that). Refuses a manifest version newer than
 * this app understands so a future format can't be half-applied.
 */
export function validateManifest(value: unknown): ValidateResult {
  if (!value || typeof value !== "object") return { ok: false, error: "not an object" };
  const o = value as Record<string, unknown>;
  if (typeof o.manifest !== "number") return { ok: false, error: "missing manifest version" };
  if (o.manifest > MANIFEST_VERSION) {
    return { ok: false, error: `manifest v${o.manifest} is newer than this app supports (v${MANIFEST_VERSION}) — update to install` };
  }
  if (typeof o.kind !== "string" || !KINDS.includes(o.kind as ExtensionKind)) {
    return { ok: false, error: `unknown kind '${String(o.kind)}'` };
  }
  if (typeof o.id !== "string" || !o.id.trim()) return { ok: false, error: "missing id" };
  if (typeof o.name !== "string" || !o.name.trim()) return { ok: false, error: "missing name" };
  if (typeof o.version !== "string" || !o.version.trim()) return { ok: false, error: "missing version" };
  if (!("payload" in o)) return { ok: false, error: "missing payload" };
  return { ok: true, manifest: o as unknown as ExtensionManifest };
}

/** Parse a JSON string into a validated manifest (tolerant of bad JSON). */
export function parseManifest(text: string): ValidateResult {
  let v: unknown;
  try { v = JSON.parse(text); } catch (e) { return { ok: false, error: `invalid JSON: ${String(e)}` }; }
  return validateManifest(v);
}

// ── Share code (copy-paste transport) ─────────────────────────────────────────
// A single opaque string carrying the whole manifest — the no-account, no-network
// path. Unicode-safe base64url of the JSON (no compression; manifests are small).

function toBase64Url(s: string): string {
  const bytes = new TextEncoder().encode(s);
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
function fromBase64Url(code: string): string {
  const b64 = code.replace(/-/g, "+").replace(/_/g, "/");
  const bin = atob(b64);
  return new TextDecoder().decode(Uint8Array.from(bin, (c) => c.charCodeAt(0)));
}

/** Encode a manifest as a shareable code string. */
export function encodeShareCode(m: ExtensionManifest): string {
  return toBase64Url(JSON.stringify(m));
}

/** Decode + validate a share-code string back into a manifest. */
export function decodeShareCode(code: string): ValidateResult {
  let json: string;
  try { json = fromBase64Url(code.trim()); } catch (e) { return { ok: false, error: `bad share code: ${String(e)}` }; }
  return parseManifest(json);
}

// Gist transport for extensions (#598 M2). Publish an extension manifest as a gist
// (one shareable URL, free hosting) and install it back by URL. Reading a public/secret
// gist needs no auth; publishing needs a token with the `gist` scope. Pure helpers
// (id parsing, file selection) are split out so they're unit-testable without Tauri.

import { invoke } from "@tauri-apps/api/core";
import { parseManifest, type ExtensionManifest, type ValidateResult } from "@/features/planner/lib/gist/manifest";

/** The file name an extension's manifest is published under inside a gist. */
export const MANIFEST_FILENAME = "extension.json";

/**
 * Extract a gist id from anything the user might paste: a gist web URL
 * (`gist.github.com/<user>/<id>` or `/<id>`), an API URL (`api.github.com/gists/<id>`),
 * or a bare id. Returns null when no plausible id is present.
 */
export function gistIdFromUrl(input: string): string | null {
  const s = input.trim();
  if (!s) return null;
  // Bare id (hex, ≥ 8 chars) — accept as-is.
  if (/^[0-9a-f]{8,}$/i.test(s)) return s;
  // Last path segment that looks like a gist id.
  const m = s.match(/gist(?:\.github\.com|s)[/:]([^/\s?#]+\/)?([0-9a-f]{8,})/i);
  if (m) return m[2];
  // Fallback: the final path-ish chunk if it's id-shaped.
  const tail = s.split(/[/?#]/).filter(Boolean).pop() ?? "";
  return /^[0-9a-f]{8,}$/i.test(tail) ? tail : null;
}

/** Shape of the relevant bits of the GitHub gist API response. */
interface GistApiResponse {
  id?: string;
  html_url?: string;
  description?: string | null;
  updated_at?: string;
  owner?: { login?: string } | null;
  files?: Record<string, { content?: string; raw_url?: string; filename?: string }>;
  history?: GistHistoryItem[];
}

/** One blueprint gist from a source user's gists (#923). */
export interface BlueprintGistItem {
  id: string;
  /** Blueprint name, parsed from the gist description (`blueprint: <name>`, set by publishGist). */
  name: string;
  description: string;
  owner: string;
  htmlUrl: string;
  updatedAt: string;
}

/** List a GitHub user's BLUEPRINT gists (#923). A gist is a blueprint when its description carries
 *  the `blueprint:` prefix publishGist writes (`${kind}: ${name}`) — the list endpoint omits file
 *  content, so the description is the reliable signal. No auth needed for public gists; `token`
 *  raises the rate limit + surfaces the user's secret gists. Empty on error. */
export async function listBlueprintGists(user: string, token = ""): Promise<BlueprintGistItem[]> {
  if (!user.trim()) return [];
  let gists: GistApiResponse[];
  try {
    gists = (await invoke("github_request", { token, path: `users/${user}/gists?per_page=100`, maxAgeSecs: 60, force: false })) as GistApiResponse[];
  } catch {
    return [];
  }
  if (!Array.isArray(gists)) return [];
  return gists
    .filter((g) => !!g.id && (g.description ?? "").trim().toLowerCase().startsWith("blueprint:"))
    .map((g) => {
      const description = (g.description ?? "").trim();
      return {
        id: g.id!,
        name: description.replace(/^blueprint:\s*/i, "").trim() || "(untitled blueprint)",
        description,
        owner: g.owner?.login ?? user,
        htmlUrl: g.html_url ?? "",
        updatedAt: g.updated_at ?? "",
      };
    });
}

interface GistHistoryItem {
  version?: string;
  committed_at?: string;
  change_status?: { total?: number; additions?: number; deletions?: number };
  user?: { login?: string } | null;
}

/** One published revision of a gist (newest first). */
export interface GistRevision {
  /** Full commit sha of this revision (use with installFromGistRevision). */
  version: string;
  committedAt: string;
  additions: number;
  deletions: number;
  login: string;
}

/** Pick the manifest file's content from a gist's files: prefer {@link MANIFEST_FILENAME},
 *  else the first `.json` file. Returns null when none is present. */
export function pickManifestContent(files: GistApiResponse["files"]): string | null {
  if (!files) return null;
  const named = files[MANIFEST_FILENAME];
  if (named?.content) return named.content;
  const firstJson = Object.values(files).find((f) => f.filename?.toLowerCase().endsWith(".json") && f.content);
  return firstJson?.content ?? null;
}

export interface PublishResult { id: string; htmlUrl: string }

/**
 * Publish a manifest as a gist (secret by default). Returns the gist id + web URL to
 * share. Throws on failure (no token / `gist` scope missing / network).
 */
export async function publishGist(
  token: string, manifest: ExtensionManifest, opts: { public?: boolean; description?: string } = {},
): Promise<PublishResult> {
  const files = { [MANIFEST_FILENAME]: JSON.stringify(manifest, null, 2) };
  const description = opts.description ?? `${manifest.kind}: ${manifest.name}`;
  const res = (await invoke("gist_create", { token, files, description, public: opts.public ?? false })) as GistApiResponse;
  if (!res.id || !res.html_url) throw new Error("gist_create returned no id/url");
  return { id: res.id, htmlUrl: res.html_url };
}

/**
 * Update an EXISTING gist's manifest in place (#970) — PATCH so re-publishing a blueprint that's
 * already on a gist updates the original instead of minting a duplicate. Throws on failure (bad
 * token / not the owner / network).
 */
export async function updateGist(
  token: string, id: string, manifest: ExtensionManifest, opts: { description?: string } = {},
): Promise<PublishResult> {
  const files = { [MANIFEST_FILENAME]: JSON.stringify(manifest, null, 2) };
  const description = opts.description ?? `${manifest.kind}: ${manifest.name}`;
  const res = (await invoke("gist_update", { token, id, files, description })) as GistApiResponse;
  if (!res.id || !res.html_url) throw new Error("gist_update returned no id/url");
  return { id: res.id, htmlUrl: res.html_url };
}

/** A gist's manifest file fetched VERBATIM — the exact bytes the publisher wrote, before any
 *  parsing. The kit-store integrity path (#2465) hashes these bytes, so it must see the raw text,
 *  not a re-serialization. `owner` is the gist owner's login when the API reports one. */
export type GistTextResult =
  | { ok: true; text: string; owner?: string }
  | { ok: false; error: string };

/**
 * Fetch a gist's manifest file content verbatim (no auth needed for public/secret gists; `token`
 * raises rate limits / reads a private gist). The raw-text layer both `installFromGist` (parse +
 * validate) and the kit-store fetch (hash-before-accept, #2465) share.
 */
export async function fetchGistManifestText(ref: string, token = ""): Promise<GistTextResult> {
  const id = gistIdFromUrl(ref);
  if (!id) return { ok: false, error: "that doesn't look like a gist URL or id" };
  let gist: GistApiResponse | null;
  try {
    gist = (await invoke("github_request", { token, path: `gists/${id}`, maxAgeSecs: 0, force: true })) as GistApiResponse | null;
  } catch (e) {
    return { ok: false, error: `couldn't fetch the gist: ${String(e)}` };
  }
  // A missing/404 gist can come back as null rather than a throw (#2515) — that's a soft
  // "not found", never a TypeError.
  const content = pickManifestContent(gist?.files);
  if (!content) return { ok: false, error: "no extension manifest found in that gist" };
  return { ok: true, text: content, ...(gist?.owner?.login ? { owner: gist.owner.login } : {}) };
}

/**
 * Install from a gist URL/id: fetch the gist (no auth needed for public/secret), pull
 * its manifest file, and validate it. `token` is optional (used only to raise rate
 * limits / read a private gist).
 */
export async function installFromGist(ref: string, token = ""): Promise<ValidateResult> {
  const raw = await fetchGistManifestText(ref, token);
  return raw.ok ? parseManifest(raw.text) : raw;
}

/** Map a gist's API `history` into our GistRevision list (newest first). Pure. */
export function toRevisions(history: GistHistoryItem[] | undefined): GistRevision[] {
  return (history ?? [])
    .filter((h): h is GistHistoryItem & { version: string } => typeof h.version === "string")
    .map((h) => ({
      version: h.version,
      committedAt: h.committed_at ?? "",
      additions: h.change_status?.additions ?? 0,
      deletions: h.change_status?.deletions ?? 0,
      login: h.user?.login ?? "unknown",
    }));
}

/** Fetch a gist's revision history (newest first). Empty on error. */
export async function gistRevisions(id: string, token = ""): Promise<GistRevision[]> {
  try {
    const gist = (await invoke("github_request", { token, path: `gists/${id}`, maxAgeSecs: 0, force: true })) as GistApiResponse;
    return toRevisions(gist.history);
  } catch {
    return [];
  }
}

/** Install the manifest as it existed at a specific gist revision (sha). */
export async function installFromGistRevision(id: string, sha: string, token = ""): Promise<ValidateResult> {
  let gist: GistApiResponse;
  try {
    gist = (await invoke("github_request", { token, path: `gists/${id}/${sha}`, maxAgeSecs: 0, force: true })) as GistApiResponse;
  } catch (e) {
    return { ok: false, error: `couldn't fetch that revision: ${String(e)}` };
  }
  const content = pickManifestContent(gist.files);
  if (!content) return { ok: false, error: "no extension manifest at that revision" };
  return parseManifest(content);
}

// githubDeviceFlow -- pure interpretation of a GitHub OAuth Device Flow poll.
//
// The backend `github_device_poll` command performs one token exchange and returns
// `{ access_token?, error? }`. This module turns that raw result (plus the current
// poll interval) into the next action the UI should take, so the polling component
// stays a thin loop and the branching logic is unit-testable without Tauri.
//
// GitHub's device-flow error strings (see the OAuth docs):
//   authorization_pending — user hasn't authorized yet; keep polling at the interval
//   slow_down             — polling too fast; keep going but add 5s to the interval
//   expired_token         — the device code expired; restart the flow
//   access_denied         — the user cancelled at github.com; restart the flow
//   (others)              — treated as fatal with the raw message

/** Raw shape returned by the `github_device_poll` Tauri command. */
export interface DevicePollResult {
  access_token?: string | null;
  error?: string | null;
}

/** What the polling loop should do next. */
export type DeviceFlowAction =
  | { kind: "success"; token: string }
  | { kind: "pending"; intervalSec: number }
  | { kind: "error"; message: string };

/** GitHub's `slow_down` asks the client to add at least 5s to its poll interval. */
export const SLOW_DOWN_BUMP_SEC = 5;

/**
 * Interpret one poll result into the next action.
 *
 * @param res         the `{ access_token?, error? }` from `github_device_poll`
 * @param intervalSec the current poll interval (seconds), echoed back on `pending`
 *                    and bumped on `slow_down`
 */
export function mapDevicePoll(res: DevicePollResult, intervalSec: number): DeviceFlowAction {
  if (res.access_token) {
    return { kind: "success", token: res.access_token };
  }
  switch (res.error) {
    case "authorization_pending":
      return { kind: "pending", intervalSec };
    case "slow_down":
      return { kind: "pending", intervalSec: intervalSec + SLOW_DOWN_BUMP_SEC };
    case "expired_token":
      return { kind: "error", message: "The code expired before you authorized. Please try again." };
    case "access_denied":
      return { kind: "error", message: "Authorization was cancelled on GitHub." };
    case undefined:
    case null:
    case "":
      return { kind: "error", message: "Unexpected response from GitHub. Please try again." };
    default:
      return { kind: "error", message: `GitHub: ${res.error}` };
  }
}

// ── Device-flow driver (#594) ─────────────────────────────────────────────────
// The start + poll loop, extracted out of the React component so it (a) is unit-
// testable without Tauri/timers and (b) is NOT tied to a component's lifecycle.
// The component used to cancel the loop on unmount, which silently aborted an
// in-flight authorization the moment the user navigated off Settings. Here,
// cancellation is an injected predicate the caller controls (an explicit restart),
// and `onSuccess` (the store write) runs to completion regardless of any UI.

/** The `github_device_start` payload (mirrors the Rust `DeviceStart`). */
export interface DeviceStartInfo {
  device_code: string;
  user_code: string;
  verification_uri: string;
  interval: number;
  expires_in: number;
}

/** Injected dependencies — Tauri calls, timing, cancellation, and side effects. */
export interface DeviceFlowDeps {
  /** Begin the flow (→ `github_device_start`). */
  start: () => Promise<DeviceStartInfo>;
  /** Exchange the device code once (→ `github_device_poll`). */
  poll: (deviceCode: string) => Promise<DevicePollResult>;
  /** Wait between polls (the component passes a real setTimeout; tests an immediate). */
  sleep: (ms: number) => Promise<void>;
  /** Current epoch ms — injected so the expiry deadline is testable. Default Date.now. */
  now?: () => number;
  /** Cancelled when this returns true (e.g. the user restarted the flow). NOT unmount. */
  isCancelled: () => boolean;
  /** The device code is ready — show it / open the verification URL. */
  onDevice?: (info: DeviceStartInfo) => void;
  /** Authorized — persist the token. Awaited; must survive a component unmount. */
  onSuccess: (token: string) => void | Promise<void>;
  /** A user-facing error (expired / denied / unexpected). */
  onError?: (message: string) => void;
}

export type DeviceFlowOutcome =
  | { kind: "connected" }
  | { kind: "cancelled" }
  | { kind: "error"; message: string }
  | { kind: "expired" };

/**
 * Drive a GitHub OAuth Device Flow to completion: start, then poll at the server's
 * interval (honoring `slow_down`) until authorized, denied/expired, cancelled, or the
 * device code's own expiry. `onSuccess` is the only mandatory side effect and is
 * awaited, so the connection completes even if the UI that kicked it off is gone.
 */
export async function runDeviceFlow(deps: DeviceFlowDeps): Promise<DeviceFlowOutcome> {
  const now = deps.now ?? (() => Date.now());
  const info = await deps.start();
  if (deps.isCancelled()) return { kind: "cancelled" };
  deps.onDevice?.(info);

  const deadline = now() + info.expires_in * 1000;
  let intervalSec = info.interval;
  while (!deps.isCancelled() && now() < deadline) {
    await deps.sleep(intervalSec * 1000);
    if (deps.isCancelled()) return { kind: "cancelled" };
    const action = mapDevicePoll(await deps.poll(info.device_code), intervalSec);
    if (action.kind === "success") {
      await deps.onSuccess(action.token);
      return { kind: "connected" };
    }
    if (action.kind === "error") {
      deps.onError?.(action.message);
      return { kind: "error", message: action.message };
    }
    intervalSec = action.intervalSec;
  }
  if (deps.isCancelled()) return { kind: "cancelled" };
  const message = "The code expired before you authorized. Please try again.";
  deps.onError?.(message);
  return { kind: "expired" };
}

// The github feature's PUBLIC API — a re-export only.
//
// The GitHub screen itself is the `githubpage` RECORD, mounted by GitHubGraphHost — which is what
// `lazyWorkspaces` resolves the `GitHubWorkspace` symbol to, in both App.tsx and DetachedWindow.
// The copy that used to live in this file was a dead duplicate: nothing imported it. Its tab table
// and `langTag` helper went with it, since only it used them.
export { GitHubGraphHost } from "@/features/github/GitHubGraphHost";

// The frontend ↔ github-state bridge (#2446) — mirrors the last-known GitHub board state into the
// bsc-project store (`~/.base-studio-code/github-state.json`) so the durable copy is reachable from a
// live session via `bsc project github-state` (golden rule: every persistent app store is
// `bsc`-reachable). Same pattern as projectLinksBridge (#2253): the zustand copy is the write-through
// CACHE; each successful fetch pushes the whole state here. Global (no project key) → null.
import { bscWrite } from "@/shared/lib/core/bsc";
import type { GithubState } from "@/shared/lib/github/githubState";

/** Write-through the whole state (`bsc project github-state set`, JSON on stdin). Fire-and-forget;
 *  never throws (degrades to cache-only when the bridge/binary is absent). */
export async function pushGithubState(state: GithubState): Promise<void> {
  await bscWrite(null, ["project", "github-state", "set"], state);
}

// Persisted GitHub board state (#2446, epic #2444) — the pure model behind the last-known-projects
// cache. A successful `PROJECTS_QUERY` fetch is boiled down to one MINIMAL record per board
// (identity + lifecycle + progress counts + repos — enough for the Projects column, the Glance
// nodes, and the progress meters offline) and stored as `{ records, fetchedAt }`:
//   - in the zustand store (persisted; the fast-paint CACHE — golden rule: cache, not source of truth),
//   - mirrored into the bsc-project store (`~/.base-studio-code/github-state.json`, via
//     `bsc project github-state set`) so the durable copy is `bsc`-reachable (golden rule #2).
//
// Precedence at the consumers (useGlanceProjects + ProjectsList): live fetch > persisted records >
// local-inventory-only (#2445). The persisted fallback is always FILTERED to projects that still
// exist locally ({@link filterRecordsToLocal}) — a record whose hub was deleted must not resurrect
// the project; only the LIVE fetch can vouch for a GitHub-only board.
//
// Board/Issues/Insights detail (fieldValues, labels, comments) deliberately stays refetch-on-view —
// only this entry-point set persists.

import { projectSlug, sanitizeProjectKey } from "@/shared/lib/core/projectPaths";

/** One `projectsV2` item as the wire carries it (structural twin of publishedModel's GhProjectItem). */
interface GhItemShape { content: { __typename?: string; state?: string } | null }

/**
 * The `projectsV2` node shape this module reads/synthesizes — a structural twin of the planner's
 * `GhProject` (publishedModel.ts), declared here so `shared/` stays feature-agnostic. Anything
 * matching this shape (including `GhProject` itself) interoperates both ways.
 */
export interface GhProjectShape {
  id: string;
  number: number;
  title: string;
  shortDescription: string | null;
  url: string;
  closed: boolean;
  updatedAt: string;
  items: { totalCount: number; nodes: GhItemShape[] };
  repositories: { nodes: Array<{ nameWithOwner: string }> };
}

/** The minimal per-board record that persists (#2446) — identity + lifecycle + progress + repos. */
export interface MinimalGhProject {
  id: string;
  number: number;
  title: string;
  shortDescription: string | null;
  url: string;
  closed: boolean;
  updatedAt: string;
  /** True item count (the fetched item page is capped at 100; this is the headline number). */
  itemsTotalCount: number;
  /** Open issues/PRs among the fetched items (mirrors publishedModel's `projectProgress`). */
  openCount: number;
  /** Closed/merged issues/PRs among the fetched items. */
  closedCount: number;
  /** `nameWithOwner` per linked repository. */
  repos: string[];
}

/** The persisted state: the last successful fetch's records + when it landed (epoch ms). */
export interface GithubState {
  records: MinimalGhProject[];
  fetchedAt: number;
}

/**
 * Boil a fetched `projectsV2` set down to the minimal persisted records. Open/closed counts derive
 * from the fetched item states exactly like `projectProgress` (MERGED counts as closed; a draft
 * item — `content: null` — counts as neither).
 */
export function toMinimalGhProjects(projects: GhProjectShape[]): MinimalGhProject[] {
  return projects.map((p) => {
    let openCount = 0, closedCount = 0;
    for (const n of p.items?.nodes ?? []) {
      const s = n.content?.state;
      if (s === "OPEN") openCount++;
      else if (s === "CLOSED" || s === "MERGED") closedCount++;
    }
    return {
      id: p.id, number: p.number, title: p.title, shortDescription: p.shortDescription,
      url: p.url, closed: p.closed, updatedAt: p.updatedAt,
      itemsTotalCount: p.items?.totalCount ?? 0, openCount, closedCount,
      repos: (p.repositories?.nodes ?? []).map((r) => r.nameWithOwner),
    };
  });
}

/**
 * Expand a persisted record back into the `GhProject` shape the existing published rendering
 * consumes, synthesizing `openCount`/`closedCount` item stubs so `projectProgress` computes the
 * exact same open count + closed fraction the record was derived from. This is what lets the stale
 * overlay reuse the live `ProjectRow`/merge paths untouched.
 */
export function minimalToGhProject(r: MinimalGhProject): GhProjectShape {
  const nodes: GhItemShape[] = [
    ...Array.from({ length: r.openCount }, () => ({ content: { state: "OPEN" } })),
    ...Array.from({ length: r.closedCount }, () => ({ content: { state: "CLOSED" } })),
  ];
  return {
    id: r.id, number: r.number, title: r.title, shortDescription: r.shortDescription,
    url: r.url, closed: r.closed, updatedAt: r.updatedAt,
    items: { totalCount: r.itemsTotalCount, nodes },
    repositories: { nodes: r.repos.map((nameWithOwner) => ({ nameWithOwner })) },
  };
}

/**
 * Keep only the records that still correspond to a LOCAL project — the don't-resurrect rule (#2446).
 * Matching mirrors the #2445 overlay (`buildLocalPublished` / the `mark_published` reconcile): a
 * record covers a local entry when the entry's key equals the record's name-derived
 * `projectSlug(title)` (today's keys) or the legacy `sanitizeProjectKey(title)` (grandfathered
 * title-keyed hubs), or when the titles match case-insensitively.
 *
 * @param records the persisted records (the last-known board state).
 * @param locals  the projects that exist locally — on-disk hubs and/or store drafts (`key` + `title`).
 */
export function filterRecordsToLocal(
  records: MinimalGhProject[],
  locals: Array<{ key: string; title: string }>,
): MinimalGhProject[] {
  if (records.length === 0 || locals.length === 0) return [];
  const keys = new Set(locals.map((l) => l.key));
  const titles = new Set(locals.map((l) => l.title.toLowerCase()));
  return records.filter((r) =>
    keys.has(projectSlug(r.title)) || keys.has(sanitizeProjectKey(r.title)) || titles.has(r.title.toLowerCase()),
  );
}

// GitHub feature store slice (#1309) — connection state, token (+ repo-scoped tokens), user, repos,
// active repo, and the page mode. Extracted from the former grab-bag `github` slice (whose residual
// — app-chrome + tunnel state — is now store/slices/shell.ts). Composed by store/index.ts.
import type { StateCreator } from "zustand";
import type { AppStore, GithubUser, GithubRepo } from "@/store/types";
import type { GithubState, MinimalGhProject } from "@/shared/lib/github/githubState";
import { pushGithubState } from "@/shared/lib/github/githubStateBridge";

export interface GithubSlice {
  githubConnected: boolean;
  githubToken: string;
  // The last-known GitHub board state (#2446): the minimal per-project records from the most recent
  // successful projects fetch + when it landed. Persisted (the fast-paint cache — survives restart
  // and renders as a stale-marked overlay while logged out / pre-refresh) and mirrored into the
  // bsc-project store so the durable copy is `bsc`-reachable. `null` until a fetch ever lands.
  // Deliberately NOT cleared by disconnectGithub — surviving the logged-out state is its point.
  githubState: GithubState | null;
  /** Overwrite the records wholesale (a fresh fetch), stamping `fetchedAt` and mirroring to bsc. */
  setGithubState: (records: MinimalGhProject[]) => void;
  // Repo-scoped GitHub credentials (#158): per-`owner/name` fine-grained token; persisted, never
  // logged. A request targeting that repo uses it instead of the global PAT.
  repoGithubTokens: Record<string, string>;
  setRepoGithubToken: (repo: string, token: string | null) => void;
  githubUser: GithubUser | null;
  githubRepos: GithubRepo[];
  activeRepoName: string;
  githubPageMode: "summary" | "projects" | "repos";
  setGithubPageMode: (v: "summary" | "projects" | "repos") => void;
  setGithubToken: (token: string) => void;
  setGithubUser: (user: GithubUser | null) => void;
  setGithubRepos: (repos: GithubRepo[]) => void;
  setActiveRepo: (name: string) => void;
  setGithubConnected: (connected: boolean) => void;
  disconnectGithub: () => void;
  markGithubTokenInvalid: () => void;
}

export const createGithubSlice: StateCreator<AppStore, [], [], GithubSlice> = (set) => ({
  githubConnected: false,
  githubToken: "",
  githubState: null,
  setGithubState: (records) => {
    const next: GithubState = { records, fetchedAt: Date.now() };
    set({ githubState: next });
    void pushGithubState(next); // mirror the durable copy into the bsc-project store (#2446)
  },
  repoGithubTokens: {},
  setRepoGithubToken: (repo, token) =>
    set((s) => {
      const next = { ...s.repoGithubTokens };
      if (token && token.trim()) next[repo] = token.trim();
      else delete next[repo];
      return { repoGithubTokens: next };
    }),
  githubUser: null,
  githubRepos: [],
  activeRepoName: "",
  githubPageMode: "summary",
  setGithubPageMode: (v) => set({ githubPageMode: v }),
  setGithubToken: (token) => set({ githubToken: token }),
  setGithubUser: (user) => set({ githubUser: user }),
  setGithubRepos: (repos) => set({ githubRepos: repos }),
  setActiveRepo: (name) => set({ activeRepoName: name }),
  setGithubConnected: (connected) => set({ githubConnected: connected }),
  disconnectGithub: () => set({
    githubConnected: false,
    githubToken: "",
    repoGithubTokens: {},
    githubUser: null,
    githubRepos: [],
    activeRepoName: "",
  }),
  // A request returned 401 (token expired/revoked) — flip to disconnected so the UI prompts a
  // reconnect instead of 401-looping; cached user/repos stay for context until reconnect.
  markGithubTokenInvalid: () => set((s) => (s.githubConnected ? { githubConnected: false } : {})),
});

// Pure domain for the GitHub summary dashboard (#1644).
//
// All the React-free shaping the summary needs: the GraphQL contribution query,
// the GitHub event → activity mapping, the language/contributor/PR/CI/repo-grid
// aggregations, and the 28-week × 7-day activity-heatmap math. The data hook
// (`useGithubSummary`) and the card components consume these; nothing here imports
// React, so it's unit-testable in isolation.

import type { GHEvent } from "@/shared/lib/github/types";
import type { GithubRepo } from "@/store";
import { quartileScale } from "@/features/github/heatScale";

// ── Wire types ────────────────────────────────────────────────────────────────

export interface GHPRItem {
  number: number;
  title: string;
  user: { login: string };
  created_at: string;
  draft: boolean;
}

export interface GHRunItem {
  id: number;
  status: string;
  conclusion: string | null;
  created_at: string;
}

export interface GHContrib {
  author: { login: string } | null;
  total: number;
}

export interface RepoData {
  prs: GHPRItem[];
  langBytes: Record<string, number>;
  runs: GHRunItem[];
  contribs: GHContrib[];
}

export interface ContribDay {
  date: string;    // YYYY-MM-DD
  weekday: number; // 0=Sun … 6=Sat (GitHub convention)
  count: number;
}

// ── Shaped output (card props) ────────────────────────────────────────────────

export interface CrossRepoEvent {
  login: string;
  action: string;
  target: string;
  repo: string;
  createdAt: string;
}

export interface OpenPR {
  n: string;
  t: string;
  who: string;
  repo: string;
  draft: boolean;
  age: string;
}

export interface Contributor {
  login: string;
  commits: number;
}

export interface CiRow {
  name: string;
  days: (boolean | null)[];
}

export interface RepoCardData {
  full_name: string;
  description: string | null;
  language: string | null;
  prCount: number;
  ciStatus: "passing" | "failing" | "unknown";
  lastPush: string;
  spark: number[];
}

export interface HeatmapData {
  heatmapCells: number[];
  rawCounts: number[];
  rawDates: string[];
  totalContribs: number;
}

// ── Constants ─────────────────────────────────────────────────────────────────

/** The summary samples only the N most-recently-updated repos (GitHub returns
 *  `user/repos` sorted `updated`). Surfaced on the cards so the sample size is honest. */
export const SUMMARY_REPO_SAMPLE = 6;

export const CONTRIB_QUERY = `
query GitHubContributions {
  viewer {
    contributionsCollection {
      contributionCalendar {
        weeks {
          contributionDays {
            contributionCount
            date
            weekday
          }
        }
      }
    }
  }
}`;

const LANG_COLORS: Record<string, string> = {
  Rust: "oklch(0.78 0.14 30)",
  TypeScript: "oklch(0.7 0.12 240)",
  JavaScript: "oklch(0.78 0.13 90)",
  Python: "oklch(0.78 0.12 90)",
  Go: "oklch(0.72 0.10 195)",
  Java: "oklch(0.7 0.12 50)",
  "C++": "oklch(0.75 0.10 240)",
  C: "oklch(0.72 0.08 220)",
  Shell: "oklch(0.72 0.10 145)",
  HTML: "oklch(0.7 0.12 30)",
  CSS: "oklch(0.7 0.10 260)",
};

export function langColor(lang: string): string {
  return LANG_COLORS[lang] ?? "oklch(0.5 0 0)";
}

export const EVENT_TONE: Record<string, string> = {
  merged: "var(--info)", opened: "var(--accent)", pushed: "var(--success)",
  reviewed: "var(--fg-muted)", closed: "var(--fg-dim)", created: "var(--accent)",
  commented: "var(--fg-dim)", "force-pushed": "var(--danger)",
};

// ── Helpers ───────────────────────────────────────────────────────────────────

export function formatHeatDate(iso: string): string {
  if (!iso) return "";
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(y, m - 1, d).toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" });
}

/** Map a raw GitHub event to a `{ action, target }` for the activity feed, or null to drop it. */
export function mapEvent(evt: GHEvent): { action: string; target: string } | null {
  const p = evt.payload as Record<string, unknown>;
  switch (evt.type) {
    case "PushEvent": {
      const commits = p.commits as Array<{ message: string }> | undefined;
      const sha = (p.head as string | undefined)?.slice(0, 7) ?? "";
      const msg = commits?.[0]?.message?.split("\n")[0] ?? "";
      if (!sha && !msg) return null;
      return { action: "pushed", target: sha ? `${sha} ${msg}` : msg };
    }
    case "PullRequestEvent": {
      const pr = p.pull_request as { number: number; title: string; merged?: boolean } | undefined;
      if (!pr) return null;
      const action = p.action === "closed" && pr.merged ? "merged"
        : (p.action as string) ?? "updated";
      return { action, target: `#${pr.number} ${pr.title}` };
    }
    case "PullRequestReviewEvent": {
      const pr = p.pull_request as { number: number; title: string } | undefined;
      if (!pr) return null;
      return { action: "reviewed", target: `#${pr.number} ${pr.title}` };
    }
    case "IssuesEvent": {
      const issue = p.issue as { number: number; title: string } | undefined;
      if (!issue) return null;
      return { action: (p.action as string) ?? "updated", target: `#${issue.number} ${issue.title}` };
    }
    case "IssueCommentEvent": {
      const issue = p.issue as { number: number; title: string } | undefined;
      if (!issue) return null;
      return { action: "commented", target: `#${issue.number} ${issue.title}` };
    }
    case "CreateEvent": {
      const ref = p.ref as string | undefined;
      if (!ref) return null;
      return { action: "created", target: `${(p.ref_type as string) ?? "branch"} ${ref}` };
    }
    default:
      return null;
  }
}

// ── Derivations ───────────────────────────────────────────────────────────────

/** Map a contribution calendar (days) into 28-week × 7-day heatmap cells. */
export function buildHeatmap(contribDays: ContribDay[]): HeatmapData {
  const counts = new Array(28 * 7).fill(0);
  const dates = new Array(28 * 7).fill("");
  let totalContribs = 0;

  const now = new Date();
  const todayDow = (now.getDay() + 6) % 7; // Mon=0
  const currentWeekMon = new Date(now);
  currentWeekMon.setHours(0, 0, 0, 0);
  currentWeekMon.setDate(currentWeekMon.getDate() - todayDow);

  contribDays.forEach(day => {
    const [y, m, d] = day.date.split("-").map(Number);
    const date = new Date(y, m - 1, d); // local date
    const dayDow = (date.getDay() + 6) % 7; // Mon=0
    const dayWeekMon = new Date(date);
    dayWeekMon.setDate(dayWeekMon.getDate() - dayDow);
    const weeksAgo = Math.round((currentWeekMon.getTime() - dayWeekMon.getTime()) / (7 * 86400000));
    if (weeksAgo < 0 || weeksAgo >= 28) return;
    const col = 27 - weeksAgo;
    const row = (day.weekday + 6) % 7; // GitHub: 0=Sun → row 6; 1=Mon → row 0
    const idx = col * 7 + row;
    counts[idx] = day.count;
    dates[idx] = day.date;
    totalContribs += day.count;
  });

  // Quartile (rank-based) intensity — robust to outlier days; see heatScale.
  return { heatmapCells: quartileScale(counts), rawCounts: counts, rawDates: dates, totalContribs };
}

/** Count merged PRs in the event stream (last ~90 days). */
export function countMergedPRs(events: GHEvent[]): number {
  return events.reduce((n, evt) => {
    if (evt.type !== "PullRequestEvent") return n;
    const p = evt.payload as { action?: string; pull_request?: { merged?: boolean } };
    return n + (p?.action === "closed" && p?.pull_request?.merged ? 1 : 0);
  }, 0);
}

/** Latest ≤8 mappable cross-repo events for the activity feed. */
export function buildCrossRepoEvents(events: GHEvent[]): CrossRepoEvent[] {
  return events.slice(0, 60).map(evt => {
    const mapped = mapEvent(evt);
    if (!mapped) return null;
    return { login: evt.actor.login, ...mapped, repo: evt.repo.name, createdAt: evt.created_at };
  }).filter((e): e is CrossRepoEvent => e !== null).slice(0, 8);
}

/** Up to 8 open PRs across all sampled repos (≤3 per repo), with a humanized age. */
export function buildOpenPRs(repoData: Record<string, RepoData>, ageOf: (iso: string) => string): OpenPR[] {
  const all: OpenPR[] = [];
  Object.entries(repoData).forEach(([slug, rd]) => {
    rd.prs.slice(0, 3).forEach(pr => {
      all.push({ n: `#${pr.number}`, t: pr.title, who: pr.user.login, repo: slug, draft: pr.draft, age: ageOf(pr.created_at) });
    });
  });
  return all.slice(0, 8);
}

/** Top 5 contributors by commit count across all sampled repos. */
export function buildContributors(repoData: Record<string, RepoData>): Contributor[] {
  const totals: Record<string, number> = {};
  Object.values(repoData).forEach(rd => {
    rd.contribs.forEach(c => {
      if (!c.author) return;
      totals[c.author.login] = (totals[c.author.login] ?? 0) + c.total;
    });
  });
  return Object.entries(totals)
    .map(([login, commits]) => ({ login, commits }))
    .sort((a, b) => b.commits - a.commits)
    .slice(0, 5);
}

/** CI pass/fail matrix for the last 7 days per repo (rows with at least one run). */
export function buildCiMatrix(repos: GithubRepo[], repoData: Record<string, RepoData>): CiRow[] {
  return repos.slice(0, SUMMARY_REPO_SAMPLE).map(r => {
    const runs = repoData[r.full_name]?.runs ?? [];
    const name = r.full_name.split("/")[1] ?? r.full_name;
    const days = Array.from({ length: 7 }, (_, i) => {
      const dayStart = new Date();
      dayStart.setHours(0, 0, 0, 0);
      dayStart.setDate(dayStart.getDate() - (6 - i));
      const dayEnd = new Date(dayStart);
      dayEnd.setDate(dayEnd.getDate() + 1);
      const dayRuns = runs.filter(run => {
        const t = new Date(run.created_at).getTime();
        return t >= dayStart.getTime() && t < dayEnd.getTime() && run.status === "completed";
      });
      if (dayRuns.length === 0) return null as null;
      return dayRuns.some(run => run.conclusion === "success");
    });
    return { name, days };
  }).filter(m => m.days.some(d => d !== null));
}

/** Per-repo card data: PR count, CI status, and a 12-week commit sparkline from events. */
export function buildRepoGrid(repos: GithubRepo[], repoData: Record<string, RepoData>, events: GHEvent[]): RepoCardData[] {
  return repos.slice(0, SUMMARY_REPO_SAMPLE).map(r => {
    const rd = repoData[r.full_name];
    const runs = rd?.runs ?? [];
    const latestRun = runs[0];
    const ciStatus = latestRun
      ? (latestRun.conclusion === "success" ? "passing" : "failing")
      : "unknown";
    // Build commit sparkline (12 weeks) from user events for this repo
    const spark = new Array(12).fill(0);
    events.forEach(evt => {
      if (evt.type !== "PushEvent" || evt.repo.name !== r.full_name) return;
      const weeksAgo = Math.floor((Date.now() - new Date(evt.created_at).getTime()) / (7 * 86400000));
      if (weeksAgo < 12) {
        const p = evt.payload as { commits?: unknown[] };
        spark[11 - weeksAgo] += p?.commits?.length ?? 1;
      }
    });
    return { full_name: r.full_name, description: r.description, language: r.language, prCount: rd?.prs.length ?? 0, ciStatus: ciStatus as "passing" | "failing" | "unknown", lastPush: r.pushed_at, spark };
  });
}

/** Percent of sampled repos whose latest run succeeded, or null when none have runs. */
export function ciPassingPercent(repos: GithubRepo[], repoData: Record<string, RepoData>): number | null {
  const withRuns = repos.slice(0, SUMMARY_REPO_SAMPLE).filter(r => (repoData[r.full_name]?.runs.length ?? 0) > 0);
  if (withRuns.length === 0) return null;
  const passing = withRuns.filter(r => repoData[r.full_name]?.runs[0]?.conclusion === "success");
  return Math.round(passing.length / withRuns.length * 100);
}

// Shared GitHub data shapes (#1492, #1528) — reused across features (mcp, skills, planner,
// github). Genuinely-shared shapes live here; truly view-specific supersets (the full
// projectsV2 node in ProjectsList) stay with their feature.

/** A minimal GitHub Project reference (subset of the GraphQL `projectsV2` node). */
export interface GhProjectRef {
