  number: number;
  title: string;
}

/** A GitHub REST milestone (the superset the Roadmap Gantt needs; ProjectsSummary reads a subset). */
export interface GhMilestone {
  number: number;
  title: string;
  description: string | null;
  state: "open" | "closed";
  due_on: string | null;
  created_at: string;
  open_issues: number;
  closed_issues: number;
  creator: { login: string } | null;
}

/** A GitHub REST issue row (the `issues` endpoint also returns PRs — rows with `pull_request`
 *  set are PRs and must be excluded from "issues"). Union of the fields the fleet + portfolio
 *  views read. */
export interface GhIssueItem {
  number: number;
  title: string;
  state: string;
  created_at: string;
  closed_at: string | null;
  pull_request?: unknown;
}

/** A GitHub Events API event — the shape the user/repo activity feeds consume. */
export interface GHEvent {
  id: string;
  type: string;
  actor: { login: string };
  repo: { name: string };
  payload: unknown;
  created_at: string;
}

/** A GitHub issue/PR label — `name` + a 6-hex `color` (no leading `#`). */
export interface GhLabel {
  name: string;
  color: string;
}

import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { resolveGithubToken } from "@/shared/lib/github/repoCredentials";

/**
 * Default in-memory freshness window. Within this many seconds of the last fetch,
 * a revisit is served straight from the backend cache with **no network call** —
 * so navigating between screens doesn't refetch GitHub every time. After the
 * window the next call revalidates cheaply (ETag → 304). `force` (manual refresh)
 * always bypasses it; pass `maxAgeSecs: 0` to always revalidate-on-view.
 */
export const DEFAULT_MAX_AGE_SECS = 300;

export interface GithubRequestOpts {
  /** Serve the cached body without any network call when it's younger than this
   *  (seconds). Defaults to {@link DEFAULT_MAX_AGE_SECS}; pass 0 to always revalidate. */
  maxAgeSecs?: number;
  /** Bypass the cache + ETag and force a fresh fetch (manual refresh). */
  force?: boolean;
}

/** A `github_request` failure that is a 401 — the stored token is expired/revoked. */
export function isGithubAuthError(e: unknown): boolean {
  const s = String(e);
  return s.includes("401") || s.includes("Bad credentials");
}

/**
 * Match the backend's typed rate-limit error (#2448): `github rate-limited until <epoch secs>` —
 * raised when GitHub's quota is exhausted (403/429 + `X-RateLimit-Remaining: 0` / `Retry-After`)
 * and while the backend's in-memory gate short-circuits further requests.
 *
 * @returns the reset time in epoch **milliseconds**, or null for any other failure.
 */
export function rateLimitedUntil(e: unknown): number | null {
  const m = /github rate-limited until (\d+)/.exec(String(e));
  return m ? Number(m[1]) * 1000 : null;
}

/** The quiet inline wording for a rate-limited query (#2448), or null for any other error —
 *  callers render this as a dim note instead of the red error banner. */
export function rateLimitNote(e: unknown): string | null {
  const until = rateLimitedUntil(e);
  if (until === null) return null;
  const at = new Date(until).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
  return `GitHub rate limit reached — showing cached data; retrying after ${at}.`;
}

/**
 * Call the GitHub REST API through the ETag-validated backend cache (`github_request`).
 *
 * - Pulls the token from the store, so callers just pass a path.
 * - Passes `maxAgeSecs`/`force` through to the cache: within `maxAgeSecs` the cached
 *   body is served with no network call; `force` bypasses the cache for a manual refresh.
 *   Otherwise the backend revalidates cheaply with `If-None-Match` (304 → cached).
 * - On a 401 (expired/revoked PAT) it flips the app to disconnected via
 *   {@link markGithubTokenInvalid} so the UI prompts a reconnect instead of
 *   silently 401-looping, then rethrows.
 */
export async function githubRequest<T>(path: string, opts: GithubRequestOpts = {}): Promise<T> {
  // Repo-scoped credentials (#158): a request targeting a repo with an assigned
  // fine-grained token uses it instead of the global PAT (so a session can't reach
  // other repos via the proxy); everything else uses the global token.
  const s = useAppStore.getState();
  const token = resolveGithubToken(path, s.repoGithubTokens, s.githubToken);
  try {
    return await invoke<T>("github_request", {
      token,
      path,
      maxAgeSecs: opts.maxAgeSecs ?? DEFAULT_MAX_AGE_SECS,
      force: opts.force,
    });
  } catch (e) {
    if (isGithubAuthError(e)) useAppStore.getState().markGithubTokenInvalid();
    throw e;
  }
}

/**
 * Call the GitHub GraphQL API through the backend cache (`github_graphql`).
 * GraphQL has no ETag, so the cache is purely time-windowed: within `maxAgeSecs`
 * (default {@link DEFAULT_MAX_AGE_SECS}) the cached result is served with no
 * network call; otherwise it re-POSTs. `force` bypasses. 401 → disconnect, as with
 * {@link githubRequest}.
 */
export async function githubGraphql<T>(
  query: string,
  variables: Record<string, unknown> | null,
  opts: GithubRequestOpts = {},
): Promise<T> {
  const token = useAppStore.getState().githubToken;
  try {
    return await invoke<T>("github_graphql", {
      token,
      query,
      variables,
      maxAgeSecs: opts.maxAgeSecs ?? DEFAULT_MAX_AGE_SECS,
      force: opts.force,
    });
  } catch (e) {
    if (isGithubAuthError(e)) useAppStore.getState().markGithubTokenInvalid();
    throw e;
  }
}

/** Drop the backend's cached GitHub responses (call on connect / disconnect / re-auth). */
export function clearGithubCache(): Promise<void> {
  return invoke("github_cache_clear");
}

// Glance data adapter (#2206) — bridges the app's REAL project list into the graph model. Nodes come
// from the user's projects; the TOPOLOGY (roles · edge kinds · dependencies · status) is clearly-marked
// SAMPLE until a real cross-project dependency model exists (epic #2205, slice 4). Isolated here so
// wiring real edges later is a drop-in — the page + graph core never change.
import sampleGraphEmbedded from "@data/glance/sample-graph.json";
import type { GRawNode, GRawEdge, GRole, GHealth, GActivity } from "@/features/glance/lib/glanceGraph";
import { kitNodeId, usesKitEdgeId, libraryNodeId, requiresEdgeId, mcpNodeId, usesMcpEdgeId, serviceNodeId, usesServiceEdgeId, architectNodeId, ownedByEdgeId, surfaceNodeId } from "@/features/glance/lib/glanceGraph";
import { isProjectContract, type ProjectLink } from "@/features/glance/lib/projectLinks";
// Cross-feature types only, via the barrel (#1309 boundary): the consumer index (`kitUsage`) whose
// (projectKey, kitId) edges the kit nodes are built from, plus the kit→library `requires` roll-up
// (`resolveKitLibraryRefs`, #3133) the caller resolves and hands in as plain data.
import type { KitConsumer, KitLibraryRef } from "@/features/designs";
// The project's application architecture (#3786/#3802) — the contract endpoint-type discriminator carried
// onto each project node. `import type` is erased at build (no runtime edge to the planner).
import type { AppType } from "@/features/planner";

export interface GlanceData { rawNodes: GRawNode[]; rawEdges: GRawEdge[]; sample: boolean }

/** A minimal project as the adapter needs it — id + display name, plus the two axes the caller has
 *  resolved (#2541): `health` (idle/healthy/warning/error) and `activity` (the lifecycle word), with an
 *  optional `reason` (the fault title) shown when health is degraded. `appType` (#3786) is the project's
 *  application architecture — the contract endpoint-type discriminator, absent ⇒ read as "application". */
export interface ProjectLite { id: string; name: string; role?: GRole; lifecycle?: string; health?: GHealth; activity?: GActivity; reason?: string; faults?: number; appType?: AppType; /** Issue completion (#4118) — carried onto the L0 node so a project shows the same bar a worker does. */ progress?: { done: number; total: number }; /** The ARCHITECT persona id that OWNS this project (#architects-own-projects), absent ⇒ unassigned. Set only by `bsc project architect set`; see {@link architectForProject} for how an unassigned project resolves. */ architect?: string }

/** A UI kit as the adapter needs it (#2571) — id + display name, so a kit node reads the kit's NAME
 *  (falling back to the id). The store's `Kit[]` is structurally assignable, so the caller passes it as-is. */
export interface KitLite { id: string; name: string }

/** An MCP server as the adapter needs it (#3786) — id + name + its per-server project scope + transport,
 *  so an mcp node reads the server's NAME and derives its `appType` from the transport. The store's
 *  `McpServer[]` is structurally assignable, so the caller passes it as-is. A server with an EMPTY
 *  `projects` list is GLOBAL (every session gets it) — not a specific contract, so it is skipped. */
export interface McpLite { id: string; name: string; projects: string[]; transport?: "stdio" | "http" }
/** An ARCHITECT persona, pared to what the L0 band needs (#glance-architect-band) — the funnel tier-1
 *  personas from the persona store, filtered to `role: "architect"` by the caller. */
export interface ArchitectLite { id: string; name: string }

/** One `bsc` COMMAND SURFACE, exactly as `bsc surface list --json` reports it
 *  (`epic-command-surfaces-are-nodes`).
 *
 *  This mirrors the catalog's own JSON rather than restating a surface list, which is the whole point of
 *  the slice: three separate plan items already exist for hand-kept copies of this set drifting from
 *  what actually dispatches, and a fourth copy in the frontend would be the next one. `store` and
 *  `summary` are optional because the catalog leaves them out for a surface that reads no store. */
export interface SurfaceLite { name: string; status?: string; store?: string; summary?: string }

/**
 * Which architect a project belongs to on the network (#architects-own-projects), or `null` for none.
 *
 * Three cases, and the middle one is the whole design:
 *
 *  1. ASSIGNED to an architect that exists → that architect. The normal case, set by
 *     `bsc project architect set`.
 *  2. UNASSIGNED, and there is exactly ONE architect → that architect. Ownership only means something
 *     once there is a choice to make, and this is what keeps a single-architect install looking
 *     exactly as it always did instead of every project silently detaching the day this shipped.
 *  3. UNASSIGNED with SEVERAL architects → none. There is no honest answer, and guessing one would
 *     put a project under an architect that never claimed it. The empty edge is the graph asking.
 *
 * An assignment naming an architect that no longer exists (its persona was deleted or re-roled) falls
 * through to the unassigned rules rather than drawing an edge to nothing — a stale id is a missing
 * owner, not a different one.
 */
export function architectForProject(project: ProjectLite, architects: readonly ArchitectLite[]): string | null {
  if (project.architect && architects.some((a) => a.id === project.architect)) return project.architect;
  return architects.length === 1 ? architects[0].id : null;
}

/** The packaged SAMPLE project network — the spec's example (roles · edge kinds · a dependency CYCLE:
 *  reporting → analytics → reporting · hazards). No longer an auto-fallback for an empty app (#2272 — an
 *  unseeded Glance shows a REAL empty state, not the mock); kept as the seed of the curated app-state
 *  DEMO (#2272 slice 4). Marked `sample`. The nodes/edges live in `@data/glance/sample-graph.json`
 *  (#2419) — a plain embedded import, NOT config-dir-overlaid, because the demo snapshot is built on
 *  this spine and must stay byte-deterministic (stable gist bytes). */
export const SAMPLE_GRAPH: GlanceData = {
  sample: true,
  rawNodes: sampleGraphEmbedded.rawNodes as GRawNode[],
  rawEdges: sampleGraphEmbedded.rawEdges as GRawEdge[],
};

/** Build the Glance graph from the REAL project list: every project a node (its resolved role/status, or
 *  a derived role + idle). Cross-project dependency EDGES are NOT fabricated — the only project↔project
 *  edges are the user-drawn relationships (#2253), so an un-wired project is simply an isolated node. On
 *  top, one UI-KIT node per distinct `bsc ui` kit in use (#2571), edged to every consuming project so the
 *  network shows which projects SHARE a kit. Zero projects yields an EMPTY graph (`sample: false`) — the
 *  workspace renders a real empty state (#2272), no mock.
 *
 *  On top of that, the generalized CROSS-GRAPH library dimension (#3133): a project transitively `requires`
 *  every algorithm / sound node the components of its kits import, so the fenced band carries real library
 *  dependencies (the logistics example: a route-planner project → its `algo:` dijkstra node), not just kits.
 *
 *  On top of THAT, the external CONTRACT dimension (#3786): (Phase 1) one auto-derived node per MCP server
 *  SCOPED to ≥1 project in this graph, edged from each consuming project — mirroring the kit dimension; a
 *  GLOBAL server (`projects: []`) is skipped. (Phase 2) plus EXPLICIT, planner-declared contracts — a
 *  stored `ProjectLink` whose `target` is a `service` or `mcp` endpoint becomes an external band node
 *  edged from `from`, DEDUPED against the Phase-1 auto-mcp nodes by node id. A project's `appType` (#3802)
 *  is surfaced on its node as the endpoint-type discriminator.
 *
 *  @param kitUsage    the consumer index (`kitUsage`) — (projectKey, kitId) edges (from `@/features/designs`).
 *  @param kits        the kit library, so a kit node reads the kit's NAME (else its id).
 *  @param libraryRefs the kit→library `requires` roll-up (`resolveKitLibraryRefs`, #3133) — resolved by the
 *                     CALLER and memoized on the component list, because deriving it scans component source;
 *                     this function must stay cheap (it re-runs on every project-status tick).
 *  @param mcpServers  the MCP server store (#3786) — a scoped server (`projects` non-empty) becomes one
 *                     external contract node edged from each consuming project; a global server is skipped. */
export function buildGlanceData(
  projects: ProjectLite[],
  links: ProjectLink[] = [],
  kitUsage: KitConsumer[] = [],
  kits: KitLite[] = [],
  libraryRefs: KitLibraryRef[] = [],
  mcpServers: McpLite[] = [],
  architects: ArchitectLite[] = [],
  surfaces: SurfaceLite[] = [],
): GlanceData {
  const rawNodes: GRawNode[] = projects.map((p) => ({
    id: p.id,
    slug: p.name || p.id,
    // `role` survives as the curated-only accent (a demo project may declare one); the default is
    // benign and the old hash-per-id tier is GONE.
    role: p.role ?? "service",
    // #4062 — the DISCOVERED lifecycle intent, passed through UNDEFAULTED: an unclassified project
    // must render no chip at all rather than a confident guess (the #4052 lesson).
    lifecycle: p.lifecycle,
    health: p.health ?? "off",      // #2541 axis 1 — resolved by the caller from faults/liveness;
                                    // #4042: the default is `off` (nothing live behind it), not a second grey
    activity: p.activity ?? "idle", // #2551 axis 2 — RESTING default; `building` is derived from live agents, not a fallback
    // #4118 — issue completion, so an L0 project node draws the same bar a drilled worker does. This
    // list is EXPLICIT (not a spread), so a new field is dropped unless it is named here; that is how
    // the bar could be wired end-to-end and still never appear on the board.
    progress: p.progress,
    reason: p.reason,                  // the fault title shown when health is degraded
    faults: p.faults,                  // #2265: unresolved runtime-fault count (inspector)
    appType: p.appType,                // #3786/#3802: the contract endpoint-type discriminator (absent ⇒ "application", rendered plain)
    // `kind` is left ABSENT here (⇒ "project", #2571) so a project node's shape is byte-identical to before.
  }));
  // The project↔project contracts (#2253) — the real edges, filtered to PROJECT-target links between two
  // nodes that still exist. No fabricated topology; an un-wired project is simply an isolated node. A
  // contract whose target is an external service / mcp server (#3786 Phase 2) is NOT a project edge — it
  // is lifted into the band below.
  const ids = new Set(rawNodes.map((n) => n.id));
  const rawEdges: GRawEdge[] = links
    .filter((l) => isProjectContract(l) && ids.has(l.from) && ids.has(l.to))
    .map((l) => ({ id: l.id, from: l.from, to: l.to, kind: l.kind }));

  // The ARCHITECT dimension (#glance-architect-band) — the funnel's tier 1 lifted into the same fenced
  // band as the library + contract dimensions. One node per architect persona, edged from the projects
  // it OWNS (#architects-own-projects).
  //
  // This replaces the FIRST CUT, which edged every architect to every project because the ownership
  // field did not exist and filtering on it would have drawn an architect with no edges at all. It now
  // exists (`ProjectRow.architect`, written only by `bsc project architect set`), so a networking
  // architect draws exactly its LAN/WAN projects and nobody else's.
  //
  // Edge direction follows the graph's consumer→provider convention (`from depends on to`), the same as
  // every other band dimension: the PROJECT is `from` and the lifted architect is `to`. That is also
  // what keeps an architect's health from ever rolling up into a project's.
  for (const a of architects) {
    const nodeId = architectNodeId(a.id);
    rawNodes.push({
      id: nodeId,
      slug: a.name || a.id,
      kind: "architect",
      role: "infra",   // lifted + foundational, like a kit — the canvas draws it from `kind`
      health: "off",   // an architect persona is a definition, not a running session — `off` is exactly that
      activity: "idle",
    });
    for (const p of projects) {
      if (architectForProject(p, architects) !== a.id) continue;
      rawEdges.push({ id: ownedByEdgeId(p.id, a.id), from: p.id, to: nodeId, kind: "owned-by" });
    }
  }

  // The SYSTEM-SESSION dimension MOVED (#architect-node-expands-into-system-sessions). It used to emit
  // one L0 node per app-owned session as a SIBLING to the architect's left, wired `architect -> session`
  // (#glance-reads-left-to-right-sessions-to-libraries). The maintainer's directive is that the
  // architect's node EXPANDS INTO them instead, so they are now the architect node's DRILL-IN
  // (`buildArchitectFleetData`) and no longer appear at L0 at all.
  //
  // The edge-direction work from that item is not lost — it moved INSIDE. `studioNetworkForArchitect`
  // wires the architect to each session it commands, so the relationship the L0 row expressed is still
  // drawn, one level down, where the drill-in needs it.
  //
  // The ARCHITECT node itself is unchanged and still emitted above: it is the thing that expands.

  // The UI-KIT dimension (#2571): one node per DISTINCT kit that has ≥1 consumer AMONG the current
  // projects, edged from every consuming project to the shared kit node. The edge follows the graph's
  // consumer→provider convention (`from depends on to`): the PROJECT consumes the kit, so `from` is the
  // project and `to` is the kit — which lays the shared kit foundational and keeps a kit's `idle` health
  // from ever rolling up into a project. A stale usage row for a project not in this graph is skipped, so
  // a kit node is never emitted without a visible edge.
  const kitName = new Map(kits.map((k) => [k.id, k.name]));
  const consumersByKit = new Map<string, string[]>();
  for (const u of kitUsage) {
    if (!ids.has(u.projectKey)) continue;                    // consumer must be a project node in this graph
    const arr = consumersByKit.get(u.kitId) ?? [];
    if (!arr.includes(u.projectKey)) arr.push(u.projectKey); // dedupe a duplicate (projectKey, kitId)
    consumersByKit.set(u.kitId, arr);
  }
  for (const [kitId, consumers] of consumersByKit) {
    rawNodes.push({
      id: kitNodeId(kitId),
      slug: kitName.get(kitId) ?? kitId,
      kind: "kit",
      role: "infra",   // a kit is a shared foundational dependency; `category` absent ⇒ the canvas draws it as a kit
      health: "off",  // #4042 — a kit never RUNS, so it has no runtime health; `off` is now exactly that
      activity: "idle",
    });
    for (const projectKey of consumers) {
      rawEdges.push({ id: usesKitEdgeId(projectKey, kitId), from: projectKey, to: kitNodeId(kitId), kind: "uses-kit" });
    }
  }

  // The generalized CROSS-GRAPH LIBRARY dimension (#3133, epic #3114) — the same fenced band, now carrying
  // ALGORITHM + SOUND nodes with `requires` edges. The dependency is TRANSITIVE and derived, never authored:
  // a project consumes a kit (`kitUsage`), that kit's components import `@bsc/algorithms/…` / `@bsc/sounds/…`
  // (`resolveKitLibraryRefs`), therefore the project requires those library nodes. Edge direction matches the
  // kit dimension (consumer→provider), so a library node lands foundational in the band alongside the kits
  // and its `idle` health never rolls up into a project.
  //
  // Emitted AFTER the kit loop and gated on `consumersByKit`, so: a project with no library-importing kit is
  // byte-identical to before, and a library node never appears without ≥1 visible edge.
  const refsByKit = new Map<string, KitLibraryRef[]>();
  for (const ref of libraryRefs) {
    const arr = refsByKit.get(ref.kitId) ?? [];
    arr.push(ref);
    refsByKit.set(ref.kitId, arr);
  }
  const seenLibNode = new Set<string>();
  const seenReqEdge = new Set<string>();
  for (const [kitId, consumers] of consumersByKit) {
    for (const ref of refsByKit.get(kitId) ?? []) {
      const nodeId = libraryNodeId(ref.graph, ref.id);
      if (!seenLibNode.has(nodeId)) {
        // Deduped ACROSS kits: two kits requiring `fibonacci` share ONE band node (that sharing is the point
        // — the band shows a library node's full consumer set).
        seenLibNode.add(nodeId);
        rawNodes.push({
          id: nodeId,
          slug: ref.label || ref.id,
          kind: "library",
          library: ref.graph,  // the band/legend/inspector colour + kind word (algorithm · sound)
          role: "infra",       // a shared foundational dependency, like a kit
          health: "off",      // #4042 — a library never runs; `off` = no live session behind this node
          activity: "idle",
        });
      }
      for (const projectKey of consumers) {
        // Deduped per (project, node): a project consuming two kits that both require `fibonacci` draws ONE
        // edge, not a doubled one.
        const id = requiresEdgeId(projectKey, nodeId);
        if (seenReqEdge.has(id)) continue;
        seenReqEdge.add(id);
        rawEdges.push({ id, from: projectKey, to: nodeId, kind: "requires" });
      }
    }
  }

  // The external MCP-CONTRACT dimension (#3786, Phase 1 inter-app contracts) — the SAME shape as the kit
  // loop, mapped onto the MCP server store: one node per server SCOPED to ≥1 project in this graph, edged
  // from every consuming project. A server with an EMPTY `projects` list is GLOBAL (every session gets it),
  // so it is NOT a specific contract and is skipped. A scoped project not in this graph is skipped, so an
  // mcp node is never emitted without a visible edge. Deduped per (project, server) like the kit loop. Edge
  // direction follows the consumer→provider convention (project consumes the server), so the mcp node lands
  // foundational in the band and its `idle` health never rolls up into a project. The mcp node's `appType`
  // is derived from its transport — http ⇒ `api`, stdio (local) ⇒ `serverless` (the user's framing: "an
  // mcp server, which can be serverless").
  const consumersByMcp = new Map<string, string[]>();   // serverId → consuming project keys (in this graph)
  const mcpById = new Map<string, McpLite>();
  for (const s of mcpServers) {
    if (s.projects.length === 0) continue;               // global — not a specific contract, skip
    for (const projectKey of s.projects) {
      if (!ids.has(projectKey)) continue;                // consumer must be a project node in this graph
      const arr = consumersByMcp.get(s.id) ?? [];
      if (!arr.includes(projectKey)) arr.push(projectKey); // dedupe a duplicate (projectKey, serverId)
      consumersByMcp.set(s.id, arr);
      mcpById.set(s.id, s);
    }
  }
  for (const [serverId, consumers] of consumersByMcp) {
    const s = mcpById.get(serverId)!;
    rawNodes.push({
      id: mcpNodeId(serverId),
      slug: s.name || serverId,
      kind: "mcp",
      role: "infra",   // an external contract is a shared foundational dependency; `category` absent ⇒ the canvas draws it as an mcp node
      appType: s.transport === "http" ? "api" : "serverless", // http endpoint ⇒ api · stdio (local) ⇒ serverless
      health: "off",  // #4042 — an external contract never runs; `off` = no live session behind this node
      activity: "idle",
    });
    for (const projectKey of consumers) {
      rawEdges.push({ id: usesMcpEdgeId(projectKey, serverId), from: projectKey, to: mcpNodeId(serverId), kind: "uses-mcp" });
    }
  }

  // EXPLICIT, PLANNER-DECLARED external contracts (#3786 Phase 2) — a stored contract whose `target` is a
  // `service` or `mcp` endpoint (not another project) becomes an external BAND node edged from `from`. This
  // GENERALIZES the Phase-1 auto-derived mcp nodes (which come from the McpServer scope) to contracts the
  // planner declares directly via `bsc project link add … --target-type`. DEDUPED against the auto-mcp
  // nodes by node id: an explicit mcp contract to a server already in the scope reuses the ONE existing
  // node (`mcp:<serverId>`) and its edge id collides, so neither node nor edge is doubled. A `service`
  // target has no auto-derivation, so it always mints its own node. Additive + data-gated: no
  // external-target contracts ⇒ nothing added (byte-identical to Phase 1).
  const seenBandNodeId = new Set(rawNodes.map((n) => n.id)); // includes the auto-mcp nodes emitted above
  const seenEdgeId = new Set(rawEdges.map((e) => e.id));
  for (const l of links) {
    const t = l.target;
    if (!t || (t.type !== "service" && t.type !== "mcp")) continue; // project targets are drawn above
    if (!ids.has(l.from)) continue;                                 // the consumer must be a project in this graph
    const nodeId = t.type === "mcp" ? mcpNodeId(l.to) : serviceNodeId(l.to);
    if (!seenBandNodeId.has(nodeId)) {
      seenBandNodeId.add(nodeId);
      rawNodes.push({
        id: nodeId,
        slug: t.name || l.to,
        kind: t.type,        // "mcp" | "service"
        role: "infra",       // an external contract is a shared foundational dependency
        appType: t.appType,  // the planner-declared endpoint type (absent ⇒ rendered plain)
        health: "off",      // #4042 — an external contract never runs; `off` = no live session behind it
        activity: "idle",
      });
    }
    const edgeId = t.type === "mcp" ? usesMcpEdgeId(l.from, l.to) : usesServiceEdgeId(l.from, l.to);
    if (!seenEdgeId.has(edgeId)) {
      seenEdgeId.add(edgeId);
      rawEdges.push({ id: edgeId, from: l.from, to: nodeId, kind: t.type === "mcp" ? "uses-mcp" : "uses-service" });
    }
  }

  // COMMAND SURFACES (`command-surfaces-are-glance-nodes`, epic `epic-command-surfaces-are-nodes`) —
  // one fenced-band node per `bsc` subcommand, GENERATED from `bsc surface list --json`. The interface
  // every agent drives this system through was the one dimension no graph could see.
  //
  // DEPRECATED SURFACES ARE SKIPPED. `bsc org` is a deprecated alias serving the same store as
  // `bsc teams`; drawing both would put two nodes on one store and overstate the surface area. The
  // catalog already carries the distinction, so this reads it rather than keeping a skip-list.
  //
  // NO `invokes` EDGE IS EMITTED HERE, and that is not an omission. The edge is meant to run
  // session→surface, but system-session nodes are no longer at L0: they MOVED into the architect node's
  // drill-in (`buildArchitectFleetData`, #architect-node-expands-into-system-sessions), so at this level
  // there is no session node for such an edge to leave. Emitting one anyway would either dangle or
  // invent a project→surface relationship the epic explicitly rejected. The edge belongs in the
  // drill-in, where the sessions actually are.
  for (const s of surfaces) {
    if (s.status && s.status !== "active") continue;
    rawNodes.push({
      id: surfaceNodeId(s.name),
      slug: s.name,
      kind: "surface",
      role: "infra",  // lifted + foundational, like a kit or an mcp node — the canvas draws it from `kind`
      health: "off",  // a command surface is a capability, never a running thing; `off` = nothing live behind it
      activity: "idle",
    });
  }

  return { rawNodes, rawEdges, sample: false };
}

// Glance fleet drill (#…) — the L1 graph you get by clicking a project on the L0 project network: that
// project's FLEET as a graph in the same Glance node/edge language (director + workers + a reviewer,
// wired by coordination edges), so the drill reads as one recursive graph zooming in. The topology is a
// deterministic SAMPLE per project until a real per-project fleet-plan feed lands (mirrors glanceData's
// sample project topology) — isolated here so wiring the real fleet later is a drop-in.
import type { GRawNode, GRawEdge, GRole, GEdgeKind, GNodeComm } from "@/features/glance/lib/glanceGraph";
import type { GlanceData, ProjectLite } from "@/features/glance/lib/glanceData";
import { hashAbs } from "@/features/glance/lib/hash";
import type { FleetPlan } from "@/features/planner/fleet/planFleet";
import type { Persona } from "@/features/personas";
import { archetypeById, positionComms, type Team, type Position, type Relationship } from "@/features/teams";
import type { BlueprintTeam } from "@/features/planner/stages/blueprintTypes";

/** Session-role → Glance colour bucket, grouped by agent FUNCTION (#2561): ORCHESTRATE (planner ·
 *  director) = infra, BUILD (worker) = service, VERIFY (reviewer · tester · juror) = data, FLOW (issuer ·
 *  triage · documentor · designer — intake, routing, docs, UI) = client. The bucket drives the colour;
 *  the real session role rides as `roleLabel` + the legend reads the function-group names at L1. */
const ROLE_TO_GROLE: Record<string, GRole> = {
  planner: "infra", director: "infra", debugger: "infra",
  worker: "service",
  reviewer: "data", tester: "data", juror: "data",
  issuer: "client", triage: "client", documentor: "client", designer: "client",
  // The AUTHORING system sessions join `designer` in the FLOW bucket: like it, they produce the material
  // a build runs on (algorithms, teams, sounds, connectors) rather than the build itself. Without these
  // entries `gRole` falls through to "service" and a librarian would draw as a worker.
  librarian: "client", architect: "client", "sound-designer": "client", integrator: "client",
};
const gRole = (role?: string): GRole => (role && ROLE_TO_GROLE[role]) || "service";

/** The planner position's node id — fixed, like `"director"`, so the graph, the role fallback and any
 *  later pane binding all name it the same way. Not a stream id: `AgentStream.id` comes from the plan
 *  and could in principle collide, which `fleetToOrg`'s `rel()` guard (`from === to`) would then hide. */
export const PLANNER_NODE_ID = "planner";

/** The app-owned SYSTEM SESSIONS a project can declare (`FleetPlan.systemSessions`) → the session role
 *  each renders as. The ids match both the fixed singletons in `shared/lib/session/systemSessions` and
 *  the Studio Network team's position ids, so one of these means the same thing everywhere.
 *
 *  Deliberately NOT called "studios": a **Studio** is already the export/import unit for the whole app
 *  library (studio snapshots). Two unrelated concepts sharing one word in one codebase is how a reader
 *  ends up looking at the wrong feature.
 *
 *  An id outside this map is IGNORED rather than rendered: a typo in the plan should cost that one node,
 *  not put a phantom agent on the graph that no session can ever back. */
const SYSTEM_SESSION_ROLES: Record<string, string> = {
  designer: "designer",
  librarian: "librarian",
  architect: "architect",
  "sound-designer": "sound-designer",
  integrator: "integrator",
  // The DEBUGGER is app-owned like the rest, but a project never DECLARES it: the caller injects it
  // into `systemSessions` while a request is open, so the node comes and goes with the queue.
  // Listing it here is what lets `resolveSystemSessions` admit it, and what keeps it out of the
  // `worker` role-colour fallback.
  debugger: "debugger",
};

/**
 * The per-TECHNOLOGY sessions a declared kind expands into (#system-sessions-are-per-technology).
 *
 * A project declares `designer`, but there is no such SESSION — there are `design-studio:designer-react`
 * and `…-react-native`, and the same for the librarian's three languages. Rendering the bare kind gives a
 * node that cannot open anything, because the pane-id map is keyed per technology. So the kind expands
 * here, once, and every downstream consumer (positions, personaOf, the role fallback) sees only real
 * sessions.
 */
const SYSTEM_SESSION_VARIANTS: Record<string, readonly string[]> = {
  designer: ["designer-react", "designer-react-native"],
  librarian: ["librarian-rust", "librarian-typescript", "librarian-python"],
};

/** A system-session node's DISPLAY label. `designer-react` reads "designer · react"; a kind with no
 *  technologies keeps its own name. The node id stays the machine identity — this is only what shows. */
export function systemSessionLabel(nodeId: string): string {
  for (const [kind, ids] of Object.entries(SYSTEM_SESSION_VARIANTS)) {
    if (ids.includes(nodeId)) return `${kind} · ${nodeId.slice(kind.length + 1)}`;
  }
  return nodeId;
}

/** The KIND behind a per-technology session id, for the role fallback + persona lookup. */
function systemSessionKind(nodeId: string): string {
  for (const [kind, ids] of Object.entries(SYSTEM_SESSION_VARIANTS)) {
    if (ids.includes(nodeId)) return kind;
  }
  return nodeId;
}

/** Every app-owned system session id, in display order. Exported so the L0 graph
 *  (#glance-reads-left-to-right-sessions-to-libraries) draws the SAME set this fleet graph resolves —
 *  one list, so a session added here appears in both places at once rather than in whichever was
 *  remembered. */
export const SYSTEM_SESSION_IDS: readonly string[] = Object.keys(SYSTEM_SESSION_ROLES);

/** The declared system sessions that are real, de-duplicated, in a stable order. */
export function resolveSystemSessions(ids: readonly string[] | undefined): string[] {
  const known = [...new Set(ids ?? [])].filter((s) => s in SYSTEM_SESSION_ROLES);
  return [...new Set(known.flatMap((s) => SYSTEM_SESSION_VARIANTS[s] ?? [s]))];
}

/** The session role for a position whose persona did not resolve. The fixed-id agents are known by
 *  their id — without this a planner falls through to `worker` and renders in the BUILD colour, which
 *  is exactly wrong for an ORCHESTRATE agent (`ROLE_TO_GROLE` already buckets `planner` as infra). */
function fallbackRole(nodeId: string): string {
  if (nodeId === "director" || nodeId === PLANNER_NODE_ID) return nodeId;
  return SYSTEM_SESSION_ROLES[systemSessionKind(nodeId)] ?? "worker";
}

/** Fleet coordination kind → Org relationship ARCHETYPE (#2561, interim map until fleets are authored as
 *  Orgs). The archetype names the relationship (Oversees a review, Stewards a shared resource, Peers on a
 *  handoff) and expands into the communication forms shown in the edge inspector. The director hub is a
 *  `manages` relationship; plain `dependsOn` is a lateral `peers` seam. */
const KIND_TO_ARCHETYPE: Record<string, string> = {
  handoff: "peers", blocking: "peers", sequence: "peers", review: "oversees", notify: "peers", shared: "peers", mutex: "stewards",
};

/** Resolve the persona surfaced on a fleet node (#2561): who is at this terminal. */
function nodePersona(p: Persona | undefined): GRawNode["persona"] {
  return p ? { name: p.name, role: p.role, model: p.model, skills: p.skills ?? [], responsibilities: p.responsibilities ?? [] } : undefined;
}

/**
 * Project a {@link FleetPlan} into a real {@link Org} (#2563) — the "fleet as Org" bridge. Streams (+ an
 * enabled director) become POSITIONS (personas referenced by id); coordination becomes RELATIONSHIPS
 * tagged with their archetype, in ARCHETYPE-NATIVE direction: the director MANAGES each stream, a typed
 * edge maps its kind (producer→consumer), a plain `dependsOn` is a lateral peer seam. Reusing the Org
 * model lets the drill derive each agent's communication surface (`positionComms`) from ONE source of
 * truth — the foundation for later authoring the fleet as an Org. Pure + exported for testing.
 */
export function fleetToOrg(fleet: FleetPlan, team?: BlueprintTeam): Team {
  // `planner` is a RESERVED id that no longer renders. Dropping the synthesized node is not enough: a
  // fleet can carry a REAL stream under that id (studio-code's is named "Project planning session"),
  // and removing only the synthetic one would leave the real stream in its place — the same node the
  // maintainer asked to remove, under a different label.
  const positions: Position[] = fleet.streams
    .filter((s) => s.id !== PLANNER_NODE_ID)
    .map((s) => ({ nodeId: s.id, kind: "agent", personaId: s.persona, label: s.name || s.id }));
  if (fleet.director?.enabled) positions.push({ nodeId: "director", kind: "agent", personaId: "director", label: "director" });
  // The PLANNER, always (#glance-planner-node-per-project). Every project has one — the session that
  // produced this plan — and until now it was the one agent absent from the graph of the work it
  // authored. Unconditional, unlike the director: a project can decline a director, but a plan it can
  // drill into necessarily came from a planning session.
  //
  // Guarded against a stream that is itself called `planner`: two positions sharing a nodeId would put
  // two nodes with one id in the graph, and `rel()` de-dupes by id — so the collision would not look
  // like a duplicate, it would look like edges going missing. A real stream keeps the name; we add ours
  // only when nothing already claims it.
  // NO PLANNER POSITION, and none survives from the fleet either (see the filter below). Reverses
  // #glance-planner-node-per-project on the maintainer's call: the planning session authored the plan
  // but is not part of the RUNTIME picture, so the drill starts at the director.
  // The SYSTEM SESSIONS this project DECLARES it uses. Same collision
  // guard as the planner: a stream already owning the id keeps it.
  const systemSessions = resolveSystemSessions(fleet.systemSessions);
  for (const s of systemSessions) {
    if (!positions.some((p) => p.nodeId === s)) {
      positions.push({ nodeId: s, kind: "agent", personaId: systemSessionKind(s), label: systemSessionLabel(s) });
    }
  }
  const posIds = new Set(positions.map((p) => p.nodeId));
  // Authored-team archetype overlay (#2572): a `persona→persona` pair the blueprint team wired with an
  // archetype OVERRIDES the coordination-derived archetype for that pair — so the authored design's
  // semantics drive the drill wherever the team authored them. Empty (no team) ⇒ pure derived, unchanged.
  const authored = teamArchetypeByPersonaPair(team);
  const personaOf = new Map<string, string | undefined>(fleet.streams.map((s) => [s.id, s.persona]));
  personaOf.set("director", "director");
  personaOf.set(PLANNER_NODE_ID, "planner");
  for (const s of resolveSystemSessions(fleet.systemSessions)) personaOf.set(s, s);
  const archOf = (from: string, to: string, derived: string): string => {
    const pf = personaOf.get(from), pt = personaOf.get(to);
    return (pf && pt && authored.get(`${pf}|${pt}`)) || derived;
  };
  const relationships: Relationship[] = [];
  const seen = new Set<string>();
  const rel = (from: string, to: string, archetype: string) => {
    if (from === to || !posIds.has(from) || !posIds.has(to)) return;
    const k = `${from}|${to}`;
    if (seen.has(k)) return;
    seen.add(k);
    relationships.push({ id: `r${relationships.length}`, archetype, from, to });
  };
  // manager → report, for every stream EXCEPT the planner. A fleet may carry a real stream whose id is
  // `planner` (studio-code's "Project planning session" is one), and pairing `director manages planner`
  // with the `planner serves director` edge below makes a MUTUAL PAIR — which `mutualPairs` classifies
  // as a cycle, and cycle edges are handed to `layerDag` as the break set. Both edges then drop out of
  // layering, the planner loses every constraint, and it lands among the workers to the RIGHT of the
  // director — the opposite of the intent, reported in-app as `dependency cycle: director ⇄ Project
  // planning session`.
  //
  // Excluding it is the right semantics regardless of the cycle: the planning session is not a worker in
  // the director's lane. It hands the plan over and briefs it, which is exactly what `serves` says.
  if (fleet.director?.enabled) {
    for (const s of fleet.streams) {
      if (s.id === PLANNER_NODE_ID) continue;
      rel("director", s.id, archOf("director", s.id, "manages"));
    }
  }
  // planner → director (#glance-planner-node-per-project). `serves`, not `manages`: the planner hands
  // the plan over and briefs it at runtime (`bsc-brief`, #2377) but owns none of the execution — the
  // director does. That makes the authority chain read end to end in one direction: the system sessions serve
  // the planner, the planner serves the director, the director manages the workers.

  // studio → planner, the SAME archetype + direction the Studio Network team already uses. This is what
  // places them: Glance layers by dependency depth, `serves` puts the server at the lower (further-left)
  // layer, so they land left of the planner, which is left of the director, with the workers
  // right of it. The arrangement is a consequence of the archetype, not a layout rule.
  for (const s of systemSessions) rel(s, "director", archOf(s, "director", "serves"));
  // producer → consumer, and upstream ↔ dependent — both SKIPPING the planner entirely.
  //
  // The planner participates in exactly ONE relationship: `serves director` (above). Every other edge
  // touching it is dropped, because a planning session is not a peer of the build streams it produced.
  //
  // This is load-bearing, not tidiness. A fleet may carry a real `planner` stream WITH `dependsOn` on
  // build streams (studio-code's does). The director manages those streams, so the planner sat BELOW the
  // director via its dependency AND above it via `serves` — closing cycles like
  //   console -> planner -> director -> console
  //   cli-platform -> console -> planner -> director -> cli-platform
  // `mutualPairs` only finds 2-CYCLES, so these never reached `layerDag`'s break set and the relaxation
  // ran away: measured at layer 141 across 46 nodes, spreading the graph over 142 columns, which renders
  // as an EMPTY canvas. (The old `director manages planner` edge had been masking it — that made a
  // 2-cycle, which mutualPairs did catch.)
  const touchesPlanner = (a: string, b: string) => a === PLANNER_NODE_ID || b === PLANNER_NODE_ID;
  for (const e of fleet.edges ?? []) {
    if (touchesPlanner(e.from, e.to)) continue;
    rel(e.from, e.to, archOf(e.from, e.to, KIND_TO_ARCHETYPE[e.kind] ?? "peers"));
  }
  for (const s of fleet.streams) {
    for (const dep of s.dependsOn) {
      if (touchesPlanner(dep, s.id)) continue;
      rel(dep, s.id, archOf(dep, s.id, "peers"));
    }
  }

  // Phase 2 (#2575): ADD the team's authored relationships that have no derived edge, INSTANTIATED onto
  // the streams by persona — a team rel posA→posB becomes every {posA-persona stream} × {posB-persona
  // stream} pair with the team's archetype. `rel` dedups vs the derived edges above (a pair with both
  // keeps its slice-3-overlaid archetype), so this only ADDS authored relationships the coordination
  // didn't wire. Nodes stay the fleet streams (identity + liveness preserved).
  if (team) {
    const streamsByPersona = new Map<string, string[]>();
    for (const s of fleet.streams) if (s.persona) {
      const arr = streamsByPersona.get(s.persona);
      if (arr) arr.push(s.id); else streamsByPersona.set(s.persona, [s.id]);
    }
    const personaOfPos = new Map(team.positions.map((p) => [p.nodeId, p.personaId]));
    for (const tr of team.relationships) {
      const pa = personaOfPos.get(tr.from), pb = personaOfPos.get(tr.to);
      if (!pa || !pb) continue;
      for (const sa of streamsByPersona.get(pa) ?? []) for (const sb of streamsByPersona.get(pb) ?? []) rel(sa, sb, tr.archetype);
    }
  }
  return { id: "fleet", name: "Fleet", positions, relationships };
}

/** A `personaFrom|personaTo → archetype` lookup from a blueprint {@link BlueprintTeam}'s authored
 *  relationships (#2572) — so the fleet projection can override a coordination pair's archetype with the
 *  team's authored one when the two streams' personas match (direction included). Empty for no team. */
function teamArchetypeByPersonaPair(team?: BlueprintTeam): Map<string, string> {
  const m = new Map<string, string>();
  if (!team) return m;
  const personaOf = new Map(team.positions.map((p) => [p.nodeId, p.personaId]));
  for (const r of team.relationships) {
    const pf = personaOf.get(r.from), pt = personaOf.get(r.to);
    if (pf && pt) m.set(`${pf}|${pt}`, r.archetype);
  }
  return m;
}

/** Convert a blueprint {@link BlueprintTeam} into a standalone {@link Org} (#2572) — the team is already
 *  `{positions, relationships}`, so this just stamps the library-identity fields. Exported for phase 2
 *  (rendering the drill from the authored team directly). */
export function teamToOrg(team: BlueprintTeam): Team {
  return { id: "team", name: "Team", positions: team.positions, relationships: team.relationships };
}

/** A minimal persona for a node with no matching persona entry (e.g. the director hub) — so its comms
 *  surface still renders. */
const fallbackPersona = (name: string, role: string): NonNullable<GRawNode["persona"]> => ({ name, role, skills: [], responsibilities: [] });

/** Org relationship archetype → a representative Glance edge `kind` (#2565). For a fleet-drill (L1) edge
 *  the `kind` is largely vestigial — the edge is coloured + labelled by its ARCHETYPE now (#2561), and
 *  `kind` drives only the `hard` flag (unshown at L1); the archetype is the real identity. */
const ARCHETYPE_TO_KIND: Record<string, GEdgeKind> = {
  manages: "api", oversees: "data", consults: "events", peers: "api", serves: "events", stewards: "data",
};

/**
 * Render a Glance fleet graph FROM an {@link Org} (#2565) — the ONE source that drives the drill's nodes,
 * edges, AND comms. Positions → nodes (persona resolved + its communication surface via `positionComms`);
 * relationships → edges. Direction: a Glance edge is "from depends on to" — the INVERSE of an org
 * relationship's archetype-native direction (a report depends on its manager, a consumer on its producer)
 * — so each relationship maps to a Glance edge REVERSED. Pure + exported: the org may be projected from a
 * running fleet (below) or, later, sourced from a blueprint's authored `team`.
 */
export function buildOrgFleetData(org: Team, personas: Persona[]): GlanceData {
  const personaById = new Map(personas.map((p) => [p.id, p]));
  const rawNodes: GRawNode[] = org.positions.map((pos) => {
    const persona = pos.personaId ? personaById.get(pos.personaId) : undefined;
    const role = persona?.role ?? fallbackRole(pos.nodeId);
    const p = nodePersona(persona) ?? fallbackPersona(pos.label ?? persona?.name ?? pos.nodeId, role);
    p.comms = projectComms(org, pos, personas); // who this agent talks to + how (#2563)
    // Rests at idle (#2551) — a planned position isn't "building" until its session is actually live.
    // A `resource` position (a library, not an agent) is marked so the canvas draws it distinctly (#3322)
    // instead of the persona-less "worker" fallback role reading as an agent node.
    return { id: pos.nodeId, slug: pos.label ?? persona?.name ?? pos.nodeId, role: gRole(role), roleLabel: role, health: "off" as const, activity: "idle" as const, persona: p, resource: pos.kind === "resource" || undefined };
  });
  const ids = new Set(rawNodes.map((n) => n.id));
  const rawEdges: GRawEdge[] = [];
  const seen = new Set<string>();
  for (const r of org.relationships) {
    // A CYCLICAL archetype (iterates, #2578) is a deliberate feedback LOOP — emit BOTH directions so the
    // shared graph-core cycle primitive (`mutualPairs`) detects it and renders it as a bowed loop; every
    // other archetype maps to ONE reversed edge (Glance "from depends on to" inverts the org direction).
    const dirs: [string, string][] = archetypeById(r.archetype)?.cyclical
      ? [[r.to, r.from], [r.from, r.to]]
      : [[r.to, r.from]];
    for (const [from, to] of dirs) {
      if (from === to || !ids.has(from) || !ids.has(to)) continue;
      const k = `${from}|${to}`;
      if (seen.has(k)) continue;
      seen.add(k);
      rawEdges.push({ from, to, kind: ARCHETYPE_TO_KIND[r.archetype] ?? "api", archetype: r.archetype });
    }
  }
  return { rawNodes, rawEdges, sample: false };
}

/** Build a project's REAL fleet as a Glance graph — project the {@link FleetPlan} into an Org (#2563) and
 *  render from it (#2565), so the drill's nodes / edges / comms all flow from ONE source (the Org). The
 *  layout is topology-identical to the pre-#2565 inline builder. Returns `sample:false`. */
export function buildRealFleetData(fleet: FleetPlan, personas: Persona[], team?: BlueprintTeam): GlanceData {
  return buildOrgFleetData(fleetToOrg(fleet, team), personas);
}

/** The fleet-drill's PREVIEW node id (#2623) — a reserved, non-agent node, so it never collides with a
 *  stream id (stream ids are slugs; this carries the structural `:` + reserved tail, like `:director`). */
export const PREVIEW_NODE_ID = "__preview__";

/**
 * Add the PREVIEW node to a fleet-drill graph when the project is COMPLETE (#2623) — the surface the user
 * clicks to render the finished application in the graph (it morphs open the app preview the way an agent
 * node morphs open its terminal). Not an agent: no persona/edges, marked `preview`, and rendered
 * distinctly by the canvas. Idempotent (never doubles) and a no-op while the project is still building, so
 * the node appears exactly when there's something to preview. Pure.
 */
export function withPreviewNode(data: GlanceData, complete: boolean): GlanceData {
  if (!complete || data.rawNodes.some((n) => n.preview)) return data;
  const preview: GRawNode = {
    id: PREVIEW_NODE_ID, slug: "preview", role: "client", roleLabel: "preview",
    health: "healthy", activity: "live", preview: true,
  };
  return { ...data, rawNodes: [...data.rawNodes, preview] };
}

/** Pare an org {@link positionComms} summary down to the glance node's {@link GNodeComm} shape (labels +
 *  transports only) — keeping the glance model decoupled from the Org form types. */
function projectComms(org: Team, pos: Position, personas: Persona[]): GNodeComm[] {
  return positionComms(org, pos, personas).map((c) => ({
    withName: c.counterpartName,
    archetypeLabel: c.archetypeLabel,
    hue: c.hue,
    sends: c.sends.map((f) => ({ label: f.label, transport: f.transport })),
    receives: c.receives.map((f) => ({ label: f.label, transport: f.transport })),
  }));
}

/**
 * Whether a fleet node has a LIVE terminal to open — the check that decides if clicking it morphs the
 * node into its in-graph terminal (#2534). A node is openable iff its identity pane id
 * (`<project>:<stream>` or `<project>:director`) is a live CELL of a launched fleet tab — the durable,
 * symmetric truth for BOTH workers and the DIRECTOR (#2542). Both are cells in the build tab, so both
 * open. This replaced the earlier per-pane runtime signals (roster / paneStatus / paneClaudeActive),
 * which covered workers but never the director: it isn't a stream (off the roster) and sits at "idle"
 * between prompts, so no transient runtime signal was true at click time. `livePaneIds` is the set of
 * pane ids that are cells of an open tab, minus ended/disabled panes. Pure.
 */
export function nodeHasLiveSession(paneId: string, livePaneIds: ReadonlySet<string>): boolean {
  return livePaneIds.has(paneId);
}

/**
 * Every live session pane that belongs to a project — its director + workers — so the whole fleet can be
 * ended at once (#3052). A fleet pane id is `<projectKey>:<streamId>` (fleetPaneId), so the project's
 * panes are exactly those with the `<projectKey>:` prefix. The trailing `:` makes the match EXACT: a
 * project keyed `cli` never captures `cli-typer`'s panes. Pure; the caller kills each returned pane.
 */
export function livePanesForProject(projectKey: string, livePaneIds: ReadonlySet<string>): string[] {
  if (!projectKey) return [];
  const prefix = `${projectKey}:`;
  return [...livePaneIds].filter((pid) => pid.startsWith(prefix));
}

/** Build a project's fleet as a Glance graph: a director (infra hub), 2–4 workers (service), a reviewer
 *  (data), and an auditor (data) in a CYCLICAL loop with the reviewer (#2578). Edges are "depends on":
 *  each worker depends on the director's direction (api), the reviewer oversees each worker's output
 *  (data), and the auditor ⟳ reviewer edge is a deliberate iteration loop (findings ⟳ revisions). All
 *  clearly `sample` until a real fleet feed replaces it. */
export function buildFleetData(project: ProjectLite): GlanceData {
  const workers = 2 + (hashAbs(project.id) % 3); // 2..4
  const rawNodes: GRawNode[] = [
    { id: "director", slug: "director", role: "infra", roleLabel: "director", health: "healthy", activity: "building" },
    { id: "reviewer", slug: "reviewer", role: "data", roleLabel: "reviewer", health: "off", activity: "review" },
    { id: "auditor", slug: "auditor", role: "data", roleLabel: "auditor", health: "off", activity: "review" },
  ];
  // The auditor ⟳ reviewer iteration loop (#2578): both directions so `mutualPairs` reads it as a cycle.
  const rawEdges: GRawEdge[] = [
    { from: "auditor", to: "reviewer", kind: "data", archetype: "iterates" },
    { from: "reviewer", to: "auditor", kind: "data", archetype: "iterates" },
  ];
  for (let i = 1; i <= workers; i++) {
    const id = `worker-${i}`;
    rawNodes.push({ id, slug: `worker ${i}`, role: "service", roleLabel: "worker", health: hashAbs(id + project.id) % 2 ? "healthy" : "off", activity: "building" });
    rawEdges.push({ from: id, to: "director", kind: "api", archetype: "manages" });   // the director manages the worker
    rawEdges.push({ from: "reviewer", to: id, kind: "data", archetype: "oversees" }); // the reviewer oversees the worker's output
  }
  return { rawNodes, rawEdges, sample: true };
}

// Glance — the workspace project-network graph model (#2206, epic #2205). Pure (no React/Tauri): turns
// a raw {nodes, edges} project graph into a laid-out, cycle-aware model the canvas renders. Ported from
// the user's "Relationship graph interaction spec" (Glance Network) buildModel — generalized to take
// the graph as input (the real project list feeds it via glanceData.ts) instead of hardcoded data.
//
// The graph is a DEPENDENCY DAG: `from depends on to`. Layers flow left→right by dependency depth
// (a foundational project with no deps sits at layer 0). Mutual pairs (a↔b) are CYCLES — surfaced as
// coordination hazards. This is the DAG/graph layout in the "layout follows data structure" sense
// (#2204): the same layered algorithm the Org designer uses, on a different domain.
import { neighborSpotlight } from "@/shared/lib/graph/spotlight";
import { mutualPairs } from "@/shared/lib/graph/cycles";
import { layerDag } from "@/shared/lib/graph/layers";
import { orderLayers } from "@/shared/lib/graph/order";
import { graphEdge } from "@/shared/lib/graph/edgePath";
import type { NodeGraph } from "@/shared/lib/graph/nodeUrn";
// Cross-feature TYPE only, via the barrel (#1309 boundary) — the project's application architecture
// (#3786/#3802), surfaced on each project node as the contract endpoint-type discriminator. `import type`
// is erased at build, so this adds no runtime edge to the planner (no cycle, HMR-safe).
import type { AppType } from "@/features/planner";

export type GRole = "infra" | "service" | "data" | "client";
/** Axis 1 — HEALTH (#2541): the top-left dot colour + the attention/propagation signal. An escalation
 *  ladder that rolls UP the dependency chain (a node shows the worst of itself + everything it depends
 *  on). `healthy` never propagates — only `warning`/`error` do. Sourced from the worst unresolved
 *  `bsc errors` FaultLevel; this REPLACES the old separate fault badge. `off` (#3239) is the one MANUAL
 *  value — the user has deactivated the node from its details pane; it renders greyed, wins over the live
 *  status ("if it's not idle then it should be off"), and — being rank 0 — never propagates and never
 *  inherits a downstream error (see {@link rollUpHealth}).
 *
 *  `modifying` (#4052) is the rung that was missing: `healthy` says nothing is WRONG and `complete` says
 *  the work is DONE, but neither said the work is IN FLIGHT. It replaces the LIFECYCLE category axis,
 *  which had degenerated to one boolean — across the local hubs NO project carried a discovered
 *  lifecycle, so `resolveProjectCategory` always fell through to `isDraft ? greenfield : maintain`, and
 *  six legend rows rendered two values. (The same degeneration removed the blueprint category in #3785.)
 *  Now L0 projects read on the SAME two axes as fleet nodes instead of a third, mostly-dead one. */
export type GHealth = "healthy" | "warning" | "error" | "off" | "complete" | "modifying";
/**
 * Does this node carry the BUILDING pulse (#4015)?
 *
 * A worker actively building breathes; one parked in maintenance sits still. That is the whole
 * distinction, and an animation carries it without inventing a health state — a colour would have to
 * compete with the health axis, which already means something else — and without changing the node's
 * static appearance at all.
 *
 * `fleet` gates it to the DRILLED fleet (L1). A project node on L0 must never animate, however busy
 * the project is — an L0 project in flight says so on the health axis (`modifying`, #4052), which is
 * still. The gate is an explicit flag rather than anything derived from the node, so a data change can
 * never quietly start animating the L0 layer.
 *
 * Suppressed on a deactivated node (meant to read calm) and on an errored one (its own error pulse is
 * the thing to look at; two competing animations on one node read as noise).
 *
 * Pure + exported so the gating is testable — the animation is an inline style, and what matters is
 * WHICH nodes get it, not the frames.
 */
export function showsBuildingPulse(
  n: { activity: GActivity },
  ctx: { fleet: boolean; isOff: boolean; isError: boolean },
): boolean {
  return ctx.fleet && !ctx.isOff && !ctx.isError && n.activity === "building";
}

/** Axis 2 — ACTIVITY (#2541): the bottom-right lifecycle word — what the project is doing right now.
 *  `idle` is the RESTING default (#2551): a triaged project with nothing running reads idle, NOT
 *  building — `building` means agents are ACTUALLY running (derived from live sessions, never a
 *  fallback). `planning` surfaces ONLY when the user has re-opened the planner on an already-triaged
 *  project (a re-edit state). `waiting` = an EXPECTED blocked state (an agent parked for the user,
 *  `bsc-wait`) — calm, not alarming; it lives here, not on the health axis. */
export type GActivity = "idle" | "planning" | "building" | "waiting" | "review" | "live" | "complete";
/** A Glance edge's kind. The project-network contracts (`api`/`data`/`events`) plus the CROSS-GRAPH
 *  LIBRARY edges: `uses-kit` (a project consumes a `bsc ui` kit, #2571) and the generalized `requires`
 *  (#3119, epic #3114) — a project/page pulls in an ALGORITHM or a SOUND library node — plus the EXTERNAL
 *  CONTRACT edges (#3786): `uses-mcp` (an MCP server) and `uses-service` (a third-party service). Every
 *  band edge ({@link isBandEdge}) routes vertically into the fenced band; the project contracts flow
 *  left→right. */
export type GEdgeKind = "api" | "data" | "events" | "uses-kit" | "requires" | "uses-mcp" | "uses-service" | "owned-by" | "served-by" | "invokes";
/** A Glance node's KIND (#2571 → generalized #3119 → external contracts #3786). A PROJECT (the default), a
 *  UI-KIT node (`kit`, the `ui` library graph — kept as-is so existing fixtures + persisted ids are
 *  unaffected), a generalized cross-graph `library` node (an algorithm / sound, carrying
 *  {@link GRawNode.library}), an `mcp` contract node (an external MCP server a project uses, #3786 Phase 1
 *  auto-derived + Phase 2 planner-declared), or a `service` contract node (a third-party service a project
 *  contracts with, #3786 Phase 2). ABSENT ⇒ `"project"`. A non-project node's id is namespaced (`kit:` /
 *  `algo:` / `sound:` / `mcp:` / `service:`, see {@link libraryNodeId} / {@link mcpNodeId} /
 *  {@link serviceNodeId}) so it can never collide with a project key (a `[a-z0-9-]` slug — no colon).
 *
 *  A `surface` node (`command-surfaces-are-glance-nodes`, epic `epic-command-surfaces-are-nodes`) is one
 *  `bsc` COMMAND SURFACE — the interface agents actually drive this system through, which every graph was
 *  blind to until now. It is generated from `bsc surface list --json`, never hand-listed: a hand-kept list
 *  would be the fourth copy of the surface set to drift, and three separate plan items already exist for
 *  the first three drifting. */
export type GNodeKind = "project" | "kit" | "library" | "mcp" | "service" | "architect" | "session" | "surface";

/** The cross-graph LIBRARY dimensions a band node can belong to (#3119) — reuses A's {@link NodeGraph}
 *  (algorithms · UI kits · sounds). A `kit` node is the `ui` case (kept for back-compat); a generalized
 *  `library` node names its graph via {@link GRawNode.library}. */
export type GLibraryGraph = NodeGraph; // "algo" | "ui" | "sound"

/** UI-KIT node/edge accent (#2571) — a distinct cyan that stands apart from the lifecycle-category
 *  palette (teal/indigo/bronze/slate/magenta/gold), the health dots, and the iteration-loop violet, so a
 *  kit node + its `uses-kit` edges read as a separate relationship dimension. */
export const KIT_COLOR = "#22d3ee";
/** Algorithm-library accent (#3119) — violet. */
export const ALGO_COLOR = "#a78bfa";
/** Sound-library accent (#3119) — pink. */
export const SOUND_COLOR = "#f472b6";
/** MCP-contract accent (#3786) — amber, distinct from the library dimensions (cyan kit / violet algo /
 *  pink sound) so an external-contract node + its `uses-mcp` edges read as their own dimension. MCP nodes
 *  are dashed band cards with no health dot, so this never blurs with the warning-health orange. */
export const MCP_COLOR = "#f59e0b";
/** External-SERVICE accent (#3786 Phase 2) — indigo, distinct from every other band dimension (cyan kit /
 *  violet algo / pink sound / amber mcp) AND from the health palette (blue/green/orange/red), so a
 *  third-party service node + its `uses-service` edges read as their own contract dimension. Like the mcp
 *  node it is a dashed band card with no health dot. */
export const SERVICE_COLOR = "#818cf8";

/** The presentation row shared by every fenced-BAND node (#3119 + #3786) — the accent colour, the node
 *  glyph + kind word, the band header, the inspector panel title, the consumer-edge label, and the
 *  inspector blurb. Used per library-graph ({@link LIBRARY_META}) and for the MCP dimension ({@link MCP_META}). */
export type BandMeta = {
  color: string; marker: string; kindLabel: string; bandLabel: string; panelTitle: string; edgeLabel: string; blurb: string;
};

/** Per-library-graph presentation (#3119). The `ui` row is EXACTLY the pre-#3119 kit treatment
 *  (cyan · ◆ · "kit" · "UI KITS" · "UI KIT" · "uses kit"), so a kit-only graph stays byte-identical. */
export const LIBRARY_META: Record<GLibraryGraph, BandMeta> = {
  ui: {
    color: KIT_COLOR, marker: "◆", kindLabel: "kit", bandLabel: "UI KITS", panelTitle: "UI KIT", edgeLabel: "uses kit",
    blurb: "A shared `bsc ui` kit. Every project below consumes it — a design-system dependency, so a breaking kit change fans out to them all.",
  },
  algo: {
    color: ALGO_COLOR, marker: "∑", kindLabel: "algorithm", bandLabel: "ALGORITHMS", panelTitle: "ALGORITHM", edgeLabel: "requires",
    blurb: "A shared algorithm from the algorithms graph. Every project above requires it — a cross-graph library dependency, so the reference implementation is reused, not re-coded.",
  },
  sound: {
    color: SOUND_COLOR, marker: "♪", kindLabel: "sound", bandLabel: "SOUNDS", panelTitle: "SOUND", edgeLabel: "requires",
    blurb: "A shared sound cue from the sounds graph. Every project above requires it — a cross-graph library dependency.",
  },
};

/** MCP-contract node presentation (#3786) — an external MCP server a project uses. Rendered in the same
 *  fenced top band as the library dimensions, but distinct (amber · ⇄ · "mcp" · "MCP SERVERS") so it reads
 *  as an EXTERNAL wire contract rather than a bundled library. This is Phase 1 of the inter-app contract
 *  model — the endpoint-type discriminator lives on the consuming project's `appType`. */
export const MCP_META: BandMeta = {
  color: MCP_COLOR, marker: "⇄", kindLabel: "mcp", bandLabel: "MCP SERVERS", panelTitle: "MCP SERVER", edgeLabel: "contracts with",
  blurb: "An external MCP server this project contracts with — a wire contract to a tool/data server, scoped to the projects that use it (a global built-in is not a specific contract, so it is not drawn here).",
};

/** External-SERVICE contract node presentation (#3786 Phase 2) — a third-party service (a payments API, a
 *  SaaS backend, another team's endpoint) a project's planner has DECLARED it depends on. Rendered in the
 *  same fenced top band as the mcp + library dimensions, but distinct (indigo · ☁ · "service" ·
 *  "SERVICES") so it reads as an external, planner-declared wire contract. Its endpoint type lives on the
 *  node's `appType`. */
export const SERVICE_META: BandMeta = {
  color: SERVICE_COLOR, marker: "☁", kindLabel: "service", bandLabel: "SERVICES", panelTitle: "SERVICE", edgeLabel: "contracts with",
  blurb: "An external service this project contracts with — a third-party endpoint (a payments API, a SaaS backend, another team's service) the planner declared as a dependency, so the relationship is visible and downstream agents know the contract.",
};

/** COMMAND-SURFACE accent (`command-surfaces-are-glance-nodes`) — lime. The band palette was already
 *  crowded (cyan kit / violet algo / pink sound / amber mcp / indigo service / bronze architect), and lime
 *  is the one region none of them occupy. It sits near the healthy-green of the health dots, which is
 *  fine for the same reason MCP's amber sits near warning-orange: a band node is a dashed card with NO
 *  health dot, so the two can never be read off the same mark. */
export const SURFACE_COLOR = "#a3e635";
/** COMMAND-SURFACE node presentation — one `bsc` subcommand, generated from `bsc surface list --json`.
 *
 *  The edge label is "invokes" rather than the contract dimensions' "contracts with": a session does not
 *  negotiate with a command surface, it RUNS it. */
export const SURFACE_META: BandMeta = {
  color: SURFACE_COLOR, marker: "❯", kindLabel: "surface", bandLabel: "COMMAND SURFACES", panelTitle: "COMMAND SURFACE", edgeLabel: "invokes",
  blurb: "A `bsc` command surface — one subcommand of the CLI every agent drives this system through. Generated from the one catalog that also drives `bsc help`, so what is drawn here cannot disagree with what actually dispatches.",
};

/** ARCHITECT node presentation (#glance-architect-band) — the funnel's tier 1, the only session that
 *  converses with the user. Rendered in the same fenced top band as the library + contract dimensions,
 *  but distinct (amber · ◈ · "architect" · "ARCHITECTS") so the tier that CREATES projects reads apart
 *  from the dependencies they consume. */
export const ARCHITECT_COLOR = "#e0a458";
export const ARCHITECT_META: BandMeta = {
  color: ARCHITECT_COLOR, marker: "◈", kindLabel: "architect", bandLabel: "ARCHITECTS", panelTitle: "ARCHITECT", edgeLabel: "created by",
  blurb: "The architect session that creates projects — the funnel's front door, and the only tier that talks to you. It runs discovery and hands a sealed requirement (plus the authority granted with it) down to each project's director.",
};

/** SYSTEM-SESSION node presentation (#glance-reads-left-to-right-sessions-to-libraries) — the app-owned
 *  singleton studios (designer · librarian · sound-designer · integrator) that produce the material a
 *  build runs on. Like the architect these are NETWORK nodes, not band nodes: they take a layer from the
 *  DAG, which is what places them left of the architect. Slate + ◇ so they read as the quiet upstream of
 *  the funnel rather than competing with the architect's amber. */
export const SESSION_COLOR = "#8b93a7";
export const SESSION_META: BandMeta = {
  color: SESSION_COLOR, marker: "◇", kindLabel: "session", bandLabel: "SYSTEM SESSIONS", panelTitle: "SYSTEM SESSION", edgeLabel: "served by",
  blurb: "An app-owned studio session — a singleton the app launches on demand rather than a fleet worker. These produce the material every build runs on: UI kits, algorithms, sounds, and integration connectors.",
};

/** Namespace prefix for a SYSTEM-SESSION node id — its own namespace, for the same reason the architect
 *  has one: a bare `designer` would be indistinguishable from a project key.
 *
 *  NOTE (#architect-node-expands-into-system-sessions): the L0 graph no longer EMITS these. The system
 *  sessions moved into the architect node's drill-in, which is built by the Team→Glance adapter and so
 *  produces `agent` nodes. This vocabulary — the id namespace, `SESSION_META`, `SESSION_COLOR` and the
 *  `served-by` edge row — is kept rather than deleted because it is shared presentation the inspector
 *  and legend still read from, and because the L0 row is a layout decision that could reasonably come
 *  back. Nothing constructs a `session` NODE today; if that is still true next time someone is here,
 *  retiring the kind is a contained edit in this file. */
export const SESSION_NODE_PREFIX = "session:";
/** The stable, collision-proof id of the graph node for an app-owned system session. */
export const sessionNodeId = (sessionId: string): string => `${SESSION_NODE_PREFIX}${sessionId}`;
/** The session id behind a `session:<id>` node id (identity for anything already bare). */
export const sessionIdOfNode = (nodeId: string): string =>
  nodeId.startsWith(SESSION_NODE_PREFIX) ? nodeId.slice(SESSION_NODE_PREFIX.length) : nodeId;
/** Stable id for an architect→session `served-by` edge — prefixed so it never collides with any other
 *  edge id. */
export const servedByEdgeId = (personaId: string, sessionId: string): string => `servedby:${personaId}>${sessionId}`;

/** Namespace prefix for an ARCHITECT node id — its own namespace so it can never collide with a project
 *  key (a `[a-z0-9-]` slug, no colon) or another band node id. */
export const ARCHITECT_NODE_PREFIX = "architect:";
/** The stable, collision-proof id of the graph node for an architect persona. */
export const architectNodeId = (personaId: string): string => `${ARCHITECT_NODE_PREFIX}${personaId}`;
/** Whether a node id names an ARCHITECT persona — the L0 node that expands into the system sessions
 *  it commands (#architect-node-expands-into-system-sessions). Prefix-keyed, like every other band
 *  namespace, so it can never mistake a project key (a `[a-z0-9-]` slug, no colon) for one. */
export const isArchitectNodeId = (nodeId: string): boolean => nodeId.startsWith(ARCHITECT_NODE_PREFIX);
/** The persona id behind an `architect:<personaId>` node id (identity for anything already bare). */
export const architectIdOfNode = (nodeId: string): string =>
  nodeId.startsWith(ARCHITECT_NODE_PREFIX) ? nodeId.slice(ARCHITECT_NODE_PREFIX.length) : nodeId;
/** Stable id for a project→architect `owned-by` edge — prefixed so it never collides with any other
 *  edge id. */
export const ownedByEdgeId = (projectKey: string, personaId: string): string => `ownedby:${projectKey}>${personaId}`;

/** Namespace prefix for a KIT node id (#2571). */
export const KIT_NODE_PREFIX = "kit:";
/** graph → the namespace prefix for a library node id (#3119). `ui` stays `kit:` so {@link kitNodeId}
 *  and every persisted `kit:<id>` node id are unchanged; algo/sound get their own namespaces. */
export const LIBRARY_NODE_PREFIX: Record<GLibraryGraph, string> = { ui: KIT_NODE_PREFIX, algo: "algo:", sound: "sound:" };
/** The stable, collision-proof id of a library node in `graph` (#3119). `libraryNodeId("ui", x)` is
 *  exactly {@link kitNodeId}`(x)`. */
export const libraryNodeId = (graph: GLibraryGraph, libId: string): string => `${LIBRARY_NODE_PREFIX[graph]}${libId}`;
/** The stable, collision-proof id of the graph node for a `bsc ui` kit (#2571). */
export const kitNodeId = (kitId: string): string => `${KIT_NODE_PREFIX}${kitId}`;
/** The kit id behind a `kit:<kitId>` node id (identity for anything already bare). */
export const kitIdOfNode = (nodeId: string): string =>
  nodeId.startsWith(KIT_NODE_PREFIX) ? nodeId.slice(KIT_NODE_PREFIX.length) : nodeId;
/** The in-graph library id behind a library node id (#3119), stripping whichever graph prefix matches. */
export const libIdOfNode = (nodeId: string): string => {
  for (const p of Object.values(LIBRARY_NODE_PREFIX)) if (nodeId.startsWith(p)) return nodeId.slice(p.length);
  return nodeId;
};
/** Stable id for a project→kit `uses-kit` edge (#2571) — prefixed so it can never collide with a
 *  {@link projectLinkId} (`from>to:kind`). */
export const usesKitEdgeId = (projectKey: string, kitId: string): string => `usekit:${projectKey}>${kitId}`;
/** Stable id for a project→library `requires` edge (#3119) — prefixed so it never collides with a
 *  {@link projectLinkId} or a {@link usesKitEdgeId}. `toNodeId` is the target library node id. */
export const requiresEdgeId = (fromKey: string, toNodeId: string): string => `req:${fromKey}>${toNodeId}`;

/** Namespace prefix for an MCP-contract node id (#3786) — its own namespace so it never collides with a
 *  project key or a library node id (`kit:`/`algo:`/`sound:`). */
export const MCP_NODE_PREFIX = "mcp:";
/** The stable, collision-proof id of the graph node for an MCP server (#3786). */
export const mcpNodeId = (serverId: string): string => `${MCP_NODE_PREFIX}${serverId}`;
/** The MCP server id behind an `mcp:<serverId>` node id (identity for anything already bare). */
export const mcpIdOfNode = (nodeId: string): string =>
  nodeId.startsWith(MCP_NODE_PREFIX) ? nodeId.slice(MCP_NODE_PREFIX.length) : nodeId;
/** Stable id for a project→mcp `uses-mcp` edge (#3786) — prefixed so it never collides with a
 *  {@link projectLinkId}, a {@link usesKitEdgeId}, or a {@link requiresEdgeId}. */
export const usesMcpEdgeId = (projectKey: string, serverId: string): string => `usemcp:${projectKey}>${serverId}`;

/** Namespace prefix for an external-SERVICE contract node id (#3786 Phase 2) — its own namespace so it
 *  never collides with a project key or another band node id (`kit:`/`algo:`/`sound:`/`mcp:`). */
export const SERVICE_NODE_PREFIX = "service:";
/** The stable, collision-proof id of the graph node for an external service (#3786 Phase 2). `serviceId`
 *  is the contract's `to` endpoint (the service name/slug the planner declared). */
export const serviceNodeId = (serviceId: string): string => `${SERVICE_NODE_PREFIX}${serviceId}`;
/** The service id behind a `service:<serviceId>` node id (identity for anything already bare). */
export const serviceIdOfNode = (nodeId: string): string =>
  nodeId.startsWith(SERVICE_NODE_PREFIX) ? nodeId.slice(SERVICE_NODE_PREFIX.length) : nodeId;
/** Stable id for a project→service `uses-service` edge (#3786 Phase 2) — prefixed so it never collides
 *  with a {@link projectLinkId}, a {@link usesKitEdgeId}, a {@link requiresEdgeId}, or a {@link usesMcpEdgeId}. */
export const usesServiceEdgeId = (projectKey: string, serviceId: string): string => `usesvc:${projectKey}>${serviceId}`;

/** Namespace prefix for a COMMAND-SURFACE node id — its own namespace so it never collides with a project
 *  key or another band node id (`kit:`/`algo:`/`sound:`/`mcp:`/`service:`). */
export const SURFACE_NODE_PREFIX = "surface:";
/** The stable, collision-proof id of the graph node for a `bsc` command surface. `name` is the subcommand
 *  token exactly as `bsc surface list` reports it (`plan`, `ui`, `graph`, …). */
export const surfaceNodeId = (name: string): string => `${SURFACE_NODE_PREFIX}${name}`;
/** The surface name behind a `surface:<name>` node id (identity for anything already bare). */
export const surfaceNameOfNode = (nodeId: string): string =>
  nodeId.startsWith(SURFACE_NODE_PREFIX) ? nodeId.slice(SURFACE_NODE_PREFIX.length) : nodeId;
/** Stable id for a session→surface `invokes` edge — prefixed so it never collides with any other edge id.
 *  Keyed on the SESSION node id rather than a project key, because a command surface is invoked by a
 *  session; that is the one place this dimension departs from the other bands, which hang off projects. */
export const invokesEdgeId = (sessionNodeId: string, surfaceName: string): string => `invokes:${sessionNodeId}>${surfaceName}`;

/** Is `n` a cross-graph LIBRARY node (#3119) — a lifted band node, not a project? True for a legacy `kit`
 *  node (the `ui` graph) or a generalized `library` node (algo/sound/ui). */
export const isLibraryNode = (n: { kind?: GNodeKind }): boolean => n.kind === "kit" || n.kind === "library";
/** The library graph a node belongs to (#3119): `kit` ⇒ `"ui"` (back-compat), a `library` node ⇒ its
 *  `library` field (defaulting to `"ui"`), else undefined (a project). */
export const libraryGraphOf = (n: { kind?: GNodeKind; library?: GLibraryGraph }): GLibraryGraph | undefined =>
  n.kind === "kit" ? "ui" : n.kind === "library" ? (n.library ?? "ui") : undefined;
/** Is `kind` a cross-graph LIBRARY edge (#3119) — a `uses-kit` (ui) or generalized `requires` edge? These
 *  route VERTICALLY into the fenced band and are excluded from the project-network layout. */
export const isLibraryEdge = (kind: GEdgeKind): boolean => kind === "uses-kit" || kind === "requires";

/** The ARCHITECT is deliberately NOT here (#architect-sits-with-the-projects). Every other non-project
 *  node in this graph is a shared DEPENDENCY — a kit, an algorithm, an MCP server — and lifting those
 *  keeps their health out of a project's roll-up and their edges out of the project DAG. An architect is
 *  the opposite relationship: it CREATED these projects rather than being consumed by them, so it belongs
 *  beside them in the same network. It is safe there because it is a SINK — every `owned-by` edge
 *  points AT it — and a cycle needs a path back out.
 *
 *  Is `n` a fenced-BAND node (#3786) — ANY lifted non-project node: a library node (kit/algorithm/sound)
 *  OR an external contract node (`mcp` / `service`). These are lifted OUT of the project DAG into the top
 *  band. */
export const isBandNode = (n: { kind?: GNodeKind }): boolean =>
  isLibraryNode(n) || n.kind === "mcp" || n.kind === "service" || n.kind === "surface";
/** Is `kind` a BAND edge (#3786) — a library edge OR an external-contract edge (`uses-mcp`/`uses-service`).
 *  These route VERTICALLY into the fenced band and are excluded from the project-network layout. */
export const isBandEdge = (kind: GEdgeKind): boolean =>
  isLibraryEdge(kind) || kind === "uses-mcp" || kind === "uses-service" || kind === "invokes";
/** The band presentation ({@link BandMeta}) for a fenced-band node (#3786) — the MCP row for an `mcp`
 *  contract node, the SERVICE row for a `service` contract node, else the library-graph row for a
 *  kit/algorithm/sound node. */
export const bandNodeMeta = (n: { kind?: GNodeKind; library?: GLibraryGraph }): BandMeta =>
  n.kind === "session" ? SESSION_META
  : n.kind === "architect" ? ARCHITECT_META
  : n.kind === "mcp" ? MCP_META
  : n.kind === "service" ? SERVICE_META
  : n.kind === "surface" ? SURFACE_META
  : LIBRARY_META[libraryGraphOf(n) ?? "ui"];

/** One communication form on a fleet node's comms surface (#2563) — a typed interaction + its `bsc-*`
 *  runtime transport, pared from the Org model so the glance node model stays decoupled from it. */
export interface GNodeCommForm { label: string; transport?: string }
/** A fleet node's communication surface with ONE counterpart (#2563), derived from the fleet-as-Org
 *  projection: the archetype, the other agent, and the forms this node SENDS / RECEIVES across it. */
export interface GNodeComm { withName: string; archetypeLabel: string; hue: number; sends: GNodeCommForm[]; receives: GNodeCommForm[] }

/** The agent identity behind a fleet node (#2561) — the persona surfaced on the drill node + inspector,
 *  so the user sees WHO is at that terminal (name · role · model · skills · charter), not just a role. */
export interface GNodePersona {
  name: string;
  role: string;
  model?: string;
  skills: string[];
  responsibilities: string[];
  /** The agent's communication surface (#2563) — who it talks to and how, one entry per relationship,
   *  derived from the fleet-as-Org projection. Absent until computed (fleet drill only). */
  comms?: GNodeComm[];
}

/** Severity rank for the health rollup — only `warning`/`error` (rank ≥ 1) propagate up dependency
 *  edges; everything else is "no problem" (rank 0) and stays put. */
// `complete` is rank 0 — finished is not a problem, so it must never propagate up a dependency edge
// and light a parent that is perfectly fine. `modifying` (#4052) is rank 0 for the same reason: work
// being IN FLIGHT is the normal state of a live project, and a dependency that is merely busy must
// never make its dependents look degraded.
export const HEALTH_RANK: Record<GHealth, number> = { healthy: 0, complete: 0, modifying: 0, warning: 1, error: 2, off: 0 };

/** A project node as supplied by the data adapter (before layout). */
export interface GRawNode {
  id: string;
  /** Owned-issue completion (#4050) — `done / total` for this node's stream. Absent for a node with no
   *  stream, or before the first read lands. PRESENTATIONAL ONLY: it never feeds health or activity,
   *  so a stale or missing read can never change what state the node reports. */
  progress?: { done: number; total: number };
  /** Display name (defaults to id). */
  slug?: string;
  role: GRole;
  /** The DISCOVERED lifecycle intent (#4062) — the L0 project node's accent chip. Absent for an
   *  unclassified project (⇒ no chip; see {@link LIFECYCLE_META}) and for fleet-drill (L1) nodes,
   *  which show their function group there instead. */
  lifecycle?: string;
  /** Axis 1 — the node's OWN health (before the dependency rollup). #2541. */
  health: GHealth;
  /** Axis 2 — the lifecycle word shown bottom-right. #2541. */
  activity: GActivity;
  /** When health is `warning`/`error`, the short reason (the `Fault.title` that set it) shown in place
   *  of the activity word, so the user sees WHY the dot changed. #2541. */
  reason?: string;
  /** Optional director id (for the node badge / inspector). */
  director?: string;
  /** Display label for the role when the mapped `role` category isn't the real thing — e.g. a fleet
   *  agent's actual session role ("worker" / "reviewer" / "director"), from its persona. The `role`
   *  category still drives the colour; this is the text shown on the card + inspector. */
  roleLabel?: string;
  /** Unresolved runtime-fault count for the project (#2265), from `bsc errors` — surfaced in the
   *  inspector. The count's worst LEVEL drives `health` (#2541); absent/0 ⇒ healthy/idle. */
  faults?: number;
  /** The agent identity at this node (#2561) — set for fleet-drill (L1) nodes, absent for project (L0)
   *  nodes. The inspector renders it as the persona card. */
  persona?: GNodePersona;
  /** The PREVIEW node (#2623) — not an agent: the surface that renders the finished application in the
   *  graph when the project is complete. Clicking it morphs open the app preview (`GlancePreviewMorph`)
   *  the way an agent node morphs open its terminal. The canvas renders it distinctly (▷). */
  preview?: boolean;
  /** A shared-RESOURCE node (#3322) — a team position of `kind:"resource"` (a library a session stewards,
   *  not an agent). The canvas renders it as a distinct dashed card so it never reads as a worker/agent. */
  resource?: boolean;
  /** The node KIND (#2571 → generalized #3119) — `"kit"` for a UI-kit node, `"library"` for a generalized
   *  cross-graph library node (algorithm / sound), else a PROJECT node. ABSENT ⇒ `"project"` so existing
   *  nodes/tests are unaffected; the canvas + inspector render a library node distinctly (its graph glyph
   *  · kind word · consumer count). */
  kind?: GNodeKind;
  /** The library graph this node belongs to (#3119) — set on a generalized `library` node to say which
   *  cross-graph dimension it is (`algo`/`sound`/`ui`). A legacy `kit` node leaves this ABSENT (it is
   *  implicitly `ui`). Absent on a project. */
  library?: GLibraryGraph;
  /** The project's APPLICATION ARCHITECTURE (#3786/#3802) — the contract endpoint-type discriminator:
   *  application/api/serverless/static/desktop/mobile/cli/library. Set on a PROJECT node from
   *  `planClassification[key].appType` (absent ⇒ "application"/unknown, rendered plain); on an `mcp`
   *  contract node from its transport (http ⇒ api, stdio ⇒ serverless) or a planner-declared `--app-type`;
   *  and on a `service` contract node from the planner-declared `--app-type` (#3786 Phase 2). Absent on
   *  library/kit nodes. */
  appType?: AppType;
}
/** A dependency edge: `from` depends on `to`, over a contract of `kind`. Optional stable `id` (a
 *  user-drawn project link carries its own; sample/derived edges fall back to a positional id).
 *  `archetype` (#2561) is the Org relationship archetype id for a fleet-drill (L1) edge — Manages /
 *  Oversees / Peers / … — which drives the edge colour + the communication forms shown in the inspector;
 *  absent for project (L0) edges, which keep the `kind` vocabulary. */
export interface GRawEdge { from: string; to: string; kind: GEdgeKind; id?: string; archetype?: string }

export interface GNode extends GRawNode {
  slug: string; layer: number; x: number; y: number;
  /** Health after the up-the-chain rollup (#2541): the worst of this node's own `health` and every node
   *  it (transitively) depends on. This is what the top-left dot renders. */
  rollupHealth: GHealth;
  /** True when `rollupHealth` is worse than the node's OWN `health` — i.e. the node is only lit because
   *  of a downstream dependency. Renders as a MUTED dot (the origin keeps the full/pulsing treatment). */
  healthInherited: boolean;
}
export interface GEdge {
  id: string; from: string; to: string; kind: GEdgeKind;
  /** A hard dependency (api/data) blocks the consumer on a breaking change; events are soft. */
  hard: boolean;
  isCycle: boolean;
  /** Org relationship archetype id for a fleet-drill (L1) edge (#2561) — drives colour + the inspector's
   *  communication forms. Absent for project (L0) edges. */
  archetype?: string;
  /** SVG path + arrowhead in world coordinates. */
  d: string; arrow: string;
}

export interface GraphModel {
  nodes: GNode[];
  edges: GEdge[];
  /** Mutual-dependency pairs (a↔b) — the coordination hazards. */
  cyclePairs: [string, string][];
  cycleNodeIds: Set<string>;
  worldW: number;
  worldH: number;
  /** The fenced LIBRARY band across the top (#3007, generalized #3119) — the vertical zone [`y0`, `y1`]
   *  the lifted library nodes occupy (UI kits AND/OR algorithms/sounds), with `y1` the fence divider below
   *  them. ABSENT when the graph has no library nodes, so a project-only graph is unchanged. The canvas
   *  draws a tinted backdrop + divider + a header label (the graph's name for a single-dimension band —
   *  "UI KITS"/"ALGORITHMS"/"SOUNDS" — else "LIBRARIES"). The field name stays `kitBand` for persist/test
   *  stability. */
  bandZone?: { x0: number; x1: number };
}

/**
 * Project LIFECYCLE INTENT → accent colour + label (#4062) — the L0 project node's lower-left chip.
 *
 * The vocabulary is `Lifecycle` (`planner/lib/classifyConfig.ts`), DISCOVERED per project by the
 * planner at the Discovery stage (`bsc plan classify set`). Typed structurally rather than importing
 * the planner's type, so the graph model stays free of a cross-feature value import.
 *
 * ── NO DEFAULT, EVER ────────────────────────────────────────────────────────────────────────────
 * A project with no discovered lifecycle renders NOTHING here. This is the entire lesson of #4052,
 * which deleted the previous incarnation: `resolveProjectCategory` ended in `isDraft ? greenfield :
 * maintain`, so every unclassified project wore a confident label and six of them carried one bit of
 * real information between them. `lifecycleOf`'s `?? "greenfield"` default exists for STAGE GATING,
 * where a missing value must not hide a stage — it is exactly wrong for display, where a blank slot
 * is honest and a defaulted label is a lie that looks like data.
 */
export const LIFECYCLE_META: Record<string, { label: string; color: string }> = {
  greenfield: { label: "greenfield", color: "var(--graph-lifecycle-greenfield)" }, // build from a pitch
  transform:  { label: "transform",  color: "var(--graph-lifecycle-transform)" },  // restructure existing repos
  harden:     { label: "harden",     color: "var(--graph-lifecycle-harden)" },     // improve in place
  maintain:   { label: "maintain",   color: "var(--graph-lifecycle-maintain)" },   // keep a shipped system running
  harvest:    { label: "harvest",    color: "var(--graph-lifecycle-harvest)" },    // extract data out of sources (#4062)
};

/** Role → accent colour (drives the node left-border + role chip + legend). */
export const ROLE_COLOR: Record<GRole, string> = {
  infra: "var(--graph-kind-infra)", service: "var(--graph-kind-service)", data: "var(--graph-kind-data)", client: "var(--graph-kind-client)",
};
/** Axis 1 — HEALTH → the top-left dot colour + whether it pulses (#2541). Blue = finished, green =
 *  active & fine, orange = warning, red = error/fatal (pulses; the node to look at).
 *
 *  A pulse also has a CHARACTER (#4052), because two states now pulse for opposite reasons. `error`
 *  is an ALARM — fast, and haloed so it carries across the graph. `modifying` is a BREATH — slower and
 *  bare, so a busy project reads as alive without competing with a broken one for the eye. Both
 *  fields default to the alarm shape, so `error` is untouched. */
export const HEALTH_META: Record<GHealth, { label: string; color: string; pulse: boolean; pulseMs?: number; glow?: boolean }> = {
  // #4034 — the worker FINISHED. Blue, the palette's most alive colour, which was previously spent
  // on `idle` (a resting node) while the state that had actually achieved something had none.
  // Never pulses: complete is STILL, the same reason its activity carries no motion (#4032).
  complete: { label: "complete", color: "var(--graph-health-complete)", pulse: false },
  // #4052 — work IN FLIGHT. Deliberately COMPLETE'S OWN BLUE, separated by motion alone: modifying is
  // "on its way to complete", so sharing the hue is the point, and still-vs-breathing carries the rest.
  // Every hue freed by deleting the lifecycle palette crowded an existing health colour anyway (teal
  // 19° from healthy, slate 7° from complete, violet 27°, pink 35°) — the same too-close-to-blue
  // objection that ruled out a purple attention state. So this state costs the palette no new hue.
  modifying: { label: "modifying", color: "var(--graph-health-modifying)", pulse: true, pulseMs: 2600, glow: false },
  healthy: { label: "healthy", color: "var(--graph-health-healthy)", pulse: false },
  warning: { label: "warning", color: "var(--graph-health-warning)", pulse: false },
  error: { label: "error", color: "var(--graph-health-error)", pulse: true },
  // #3239 — the user-deactivated node: a muted grey dot, never pulsing. The manual "turned off" state.
  // #4042 — `off` now means "NO LIVE SESSION behind this node", which covers all three ways that
  // happens: the user deactivated it, it was never launched, or it is structural furniture (a kit, a
  // library, an external contract) that never runs at all. Those used to be `idle`, a second grey
  // that looked identical to this one — and the dimming has always actually meant this.
  off: { label: "off", color: "var(--graph-health-off)", pulse: false },
};
/**
 * The node's bottom-right STATE WORD (#3957) — axis 2's one-word slot.
 *
 * Precedence: a user-deactivated node reads `off` (that wins over any live status, #3239); a node whose
 * OWN health is degraded reads its health word (`warning`/`error`); otherwise its activity word.
 *
 * It deliberately does NOT return the node's `reason`. It used to: #2541 swapped the reason in "so the
 * user sees WHY the dot changed", which worked while reasons were short fault titles. They aren't — 
 * `applyStallHealth` appends a duration and #3931's `heldReason` names every unlanded upstream. The slot
 * is 108px, nowrap, ellipsis, so a sentence never overflowed, it TRUNCATED:
 * "waiting on 2 upstreams to land (domain-model…" rendered as "waiting on 2 upstre…", which reads as
 * garbage rather than a status. The reason is still on hover (`title`) and in the inspector's REASON
 * tile, both of which can actually display it.
 *
 * `rollupHealth` decides `off` (the deactivation is a rollup concern); `health` decides degraded (a node
 * must not read `warning` because a DEPENDENCY is degraded). Pure.
 */
export function nodeStateWord(n: { health: GHealth; rollupHealth?: GHealth; activity: GActivity }): string {
  // #4034 — no `off` WORD. A deactivated node is already dimmed in place (`offOpacity`, #3239) and
  // that IS the signal; spending the one word slot on it meant a node that was off AND complete read
  // "off" and lost the more useful fact. The dimming carries deactivation, the word carries what the
  // node IS.
  if (n.health === "warning" || n.health === "error") return HEALTH_META[n.health].label;
  return ACTIVITY_META[n.activity].label;
}

/** Axis 2 — ACTIVITY → the bottom-right lifecycle word (#2541). Colour is the health axis's job; this
 *  is just the label + whether it animates (a live app / building fleet reads as active). */
export const ACTIVITY_META: Record<GActivity, { label: string; pulse: boolean }> = {
  idle: { label: "idle", pulse: false },
  planning: { label: "planning", pulse: false },
  building: { label: "building", pulse: true },
  waiting: { label: "waiting", pulse: false },
  review: { label: "in review", pulse: false },
  live: { label: "live", pulse: true },
  // #4027 — the worker FINISHED. On the lifecycle axis, not health: health is the perpendicular
  // axis and already means something else, and "finished" is a lifecycle fact.
  //
  // Never pulses, deliberately — that completes the vocabulary: building BREATHES (#4015),
  // attention RINGS (#4005), complete is STILL. Motion means "look at this"; a finished worker is
  // the one state with nothing to do about it.
  complete: { label: "complete", pulse: false },
};
/** Project-network (L0) edge kind → label · colour · dash · line width · the relationship "surface"
 *  blurb (#2561 relabel). The relationships a user draws between PROJECTS — a build/runtime **dependency**,
 *  a **data flow** (one project consumes another's data — connectors/pipelines/migration), or an async
 *  **event stream** — NOT the microservice "API contract" framing this replaced. (The internal key `api`
 *  is kept for data/persist stability; only the user-facing label reads "depends on".) Fleet-drill (L1)
 *  edges speak the Org archetype grammar instead — see `glanceFleet`. */
export const EDGE_META: Record<GEdgeKind, { label: string; color: string; dash: string; w: number; surface: string }> = {
  api: { label: "depends on", color: "var(--graph-edge-api)", dash: "", w: 1.8, surface: "build & runtime dependency" },
  data: { label: "data flow", color: "var(--graph-edge-data)", dash: "", w: 1.8, surface: "consumes a data feed · schema-locked" },
  events: { label: "event stream", color: "var(--graph-edge-events)", dash: "6 5", w: 1.7, surface: "async messages · at-least-once" },
  // The kit-consumer dimension (#2571): a project CONSUMES a shared `bsc ui` kit — a design-system
  // dependency drawn to the shared kit node. Dashed cyan so it reads apart from the project edges.
  "uses-kit": { label: "uses kit", color: KIT_COLOR, dash: "4 4", w: 1.6, surface: "consumes a shared bsc ui kit · design-system dependency" },
  // The generalized cross-graph LIBRARY dimension (#3119, epic #3114): a project/page REQUIRES a node in
  // ANOTHER graph — an algorithm or a sound cue. Dashed like `uses-kit` so it reads as a library
  // dependency; the canvas tints each edge by the TARGET node's graph colour (LIBRARY_META), so this
  // static `color` is only a neutral fallback (e.g. the legend swatch).
  requires: { label: "requires", color: "var(--fg-muted)", dash: "4 4", w: 1.6, surface: "requires a shared library node (algorithm / sound) · cross-graph dependency" },
  // The COMMAND-SURFACE dimension (`command-surfaces-are-glance-nodes`): a SESSION invokes a `bsc`
  // subcommand. Dashed lime like the other band edges, and the only one whose source is a session
  // rather than a project — a command surface is run BY an agent, not depended on by a codebase.
  invokes: { label: "invokes", color: SURFACE_COLOR, dash: "4 4", w: 1.6, surface: "runs a bsc command surface · the interface an agent drives the system through" },
  // The PROVENANCE dimension (#glance-architect-band): the architect session that created this project.
  // Dashed amber, matching ARCHITECT_META, so the tier that CREATES a project reads apart from the
  // dependencies it consumes.
  // #architects-own-projects: OWNERSHIP, not provenance. It was `created-by`/"created by", which stopped
  // being true the moment a project could be REASSIGNED — an edge that can move cannot claim to record
  // who created the thing. The surface names the command because there is no picker anywhere: `bsc` is
  // the only surface that sets this, so the graph is where a user has to learn the verb exists.
  "owned-by": { label: "architect", color: ARCHITECT_COLOR, dash: "4 4", w: 1.6, surface: "this project's architect · reassign with `bsc project architect set <key> <persona>`" },
  // The SYSTEM-SESSION dimension (#glance-reads-left-to-right-sessions-to-libraries): the architect is
  // SERVED BY the app-owned studio sessions that produce the material its projects are built from.
  // Dashed slate, matching SESSION_META, and drawn architect→session so the session sits one layer
  // LEFT — the far upstream of the left→right funnel.
  "served-by": { label: "served by", color: SESSION_COLOR, dash: "4 4", w: 1.6, surface: "served by an app-owned studio session · produces kits / algorithms / sounds / connectors" },
  // The external MCP-CONTRACT dimension (#3786): a project CONTRACTS WITH a scoped MCP server — a wire
  // contract to an external tool/data server, drawn to the shared mcp node. Tight-dotted amber so it reads
  // apart from the kit/library edges.
  "uses-mcp": { label: "contracts with", color: MCP_COLOR, dash: "2 3", w: 1.6, surface: "contracts with a scoped external MCP server · a wire contract (Phase 1 inter-app contracts)" },
  // The external SERVICE-CONTRACT dimension (#3786 Phase 2): a project CONTRACTS WITH a third-party
  // service its planner declared — a wire contract to an external endpoint, drawn to the shared service
  // node. Tight-dotted indigo so it reads apart from the mcp + kit/library edges.
  "uses-service": { label: "contracts with", color: SERVICE_COLOR, dash: "2 3", w: 1.6, surface: "contracts with an external service · a planner-declared wire contract (Phase 2 inter-app contracts)" },
};

// Node box + spacing in world (design) coordinates.
export const NW = 186, NH = 66;
const COLGAP = 252, ROWGAP = 102;

// The fenced LIBRARY band, RIGHT of the projects (#3007, generalized #3119; reoriented by
// #glance-reads-left-to-right-sessions-to-libraries). Band nodes (UI kits + algorithms + sounds + MCP
// servers + external services) are LIFTED out of the project dependency DAG into a single COLUMN here, so
// they read as a separate library dimension instead of an intermixed project column.
//
// It used to be a horizontal row across the TOP, which meant the graph was drawn on two axes at once:
// the funnel ran left→right (sessions → architect → projects) while the thing those projects consume sat
// above them. One axis reads as one pipeline, so the band moved to the end of the line.
const BAND_FENCE_PAD = 40;  // clearance from the projects' right edge out to the fence divider
const BAND_CARD_GAP = 34;   // clearance from the fence divider across to the band cards' left edge

/** Lay out `count` band cards as a vertical COLUMN — the transpose of A's shared `layoutBand`, which
 *  only does rows. Evenly spaced and centred over the project span [`spanY0`, `spanY1`], the step capped
 *  at `maxStep` so a couple of nodes cluster in the middle instead of stretching the full height.
 *
 *  Deliberately local rather than a change to `layoutBand`: that helper is shared with the Design Studio
 *  composition swimlanes, which are genuinely horizontal, so generalizing it to both axes would make
 *  every caller pass an orientation to get what it already had. */
function layoutBandColumn(count: number, spanY0: number, spanY1: number, x: number, maxStep: number): { x: number; y: number }[] {
  if (count <= 0) return [];
  const span = Math.max(0, spanY1 - spanY0);
  const step = count > 1 ? Math.min(span / (count - 1), maxStep) : 0;
  const colH = step * (count - 1);
  const startY = spanY0 + (span - colH) / 2;
  return Array.from({ length: count }, (_, i) => ({ x, y: startY + i * step }));
}

/** Bezier path + arrowhead between two node boxes (F depends on T). Cycle back-edges bow to separate the
 *  two directions. Ported from the spec's edgeGeom.
 *
 *  EVERY edge now uses side-port routing (#glance-reads-left-to-right-sessions-to-libraries). It used to
 *  branch on `kind`: a library edge ran VERTICALLY into the top band, where side ports would have met the
 *  wrong faces, so it fell back to the perimeter-anchor router. With the band moved to a column RIGHT of
 *  the projects, every dimension — sessions, architect, projects, libraries — lies on the same left→right
 *  axis, so there is no longer a second orientation to special-case. `kind` is kept in the signature
 *  because callers pass it and the legend/labels still key off it. */
export function edgeGeom(F: { x: number; y: number; id: string }, T: { x: number; y: number; id: string }, isCycle: boolean, _kind?: GEdgeKind): { d: string; arrow: string } {
  // The shared graph line-type (#2222) with SIDE-PORT routing (#2226) — Glance is a layered left→right
  // DAG, so edges leave the right edge / enter the left at the vertical middle for a clean columnar flow
  // (the perimeter-anchor router read messy here). Cycle back-edges bow apart (deterministic sign by id
  // order) so the two directions of a↔b don't overlap.
  const bow = isCycle ? (F.id < T.id ? -46 : 46) : 0;
  const { d, arrow } = graphEdge({ x: F.x, y: F.y, w: NW, h: NH }, { x: T.x, y: T.y, w: NW, h: NH }, { bow, routing: "ports" as const });
  return { d, arrow };
}

/** The nodes + edges to KEEP lit when something is focused (hovered/selected), so the rest dims. Null
 *  means "nothing focused — everything lit." A node lights itself + its neighbors + connecting edges;
 *  an edge lights its two endpoints; `showCycle` lights every cycle edge + its nodes. Pure. */
export function focusSets(
  model: GraphModel,
  activeNodeId: string | null,
  activeEdgeId: string | null,
  showCycle: boolean,
): { nodes: Set<string>; edges: Set<string> } | null {
  if (activeNodeId) {
    const sp = neighborSpotlight(model.edges, activeNodeId);
    return { nodes: sp.litNodes, edges: sp.litEdges };
  }
  if (activeEdgeId) {
    const e = model.edges.find((x) => x.id === activeEdgeId);
    return e ? { nodes: new Set([e.from, e.to]), edges: new Set([e.id]) } : null;
  }
  if (showCycle) {
    const nodes = new Set<string>(), edges = new Set<string>();
    for (const e of model.edges) if (e.isCycle) { edges.add(e.id); nodes.add(e.from); nodes.add(e.to); }
    return { nodes, edges };
  }
  return null;
}

/**
 * Roll HEALTH up the dependency chain (#2541): each node's effective health is the WORST of its own
 * health and every node it (transitively) depends on — so a foundational service's error surfaces on
 * everything downstream that depends on it. Only `warning`/`error` (rank ≥ 1) propagate; `idle`/`healthy`
 * never override the dependent's own resting state. Cycle-safe (a per-start visited set). Pure.
 *
 * Returns, per node id, the rolled-up `health` and whether it is `inherited` (worse than the node's own
 * health — i.e. lit only because of a dependency, so the dot renders muted, not as the origin).
 */
export function rollUpHealth(
  nodes: { id: string; health: GHealth }[],
  edges: { from: string; to: string }[],
): Map<string, { health: GHealth; inherited: boolean }> {
  const own = new Map(nodes.map((n) => [n.id, n.health]));
  const deps = new Map<string, string[]>(nodes.map((n) => [n.id, []]));
  for (const e of edges) deps.get(e.from)?.push(e.to); // `from depends on to`
  const worstFrom = (start: string): GHealth => {
    // A user-deactivated node stays `off` (#3239): the deliberate mute wins over any downstream error,
    // so an off node never lights up because of a dependency. (`off` is rank 0, so it also never
    // propagates OUT — a node depending on an off node is unaffected.)
    if (own.get(start) === "off") return "off";
    let worst: GHealth = own.get(start) ?? "off";
    const seen = new Set<string>([start]);
    const stack = [...(deps.get(start) ?? [])];
    while (stack.length) {
      const id = stack.pop()!;
      if (seen.has(id)) continue;
      seen.add(id);
      const h: GHealth = own.get(id) ?? "off";   // #4042: no own health ⇒ nothing live behind it
      if (HEALTH_RANK[h] > HEALTH_RANK[worst]) worst = h;
      for (const d of deps.get(id) ?? []) stack.push(d);
    }
    return worst;
  };
  const out = new Map<string, { health: GHealth; inherited: boolean }>();
  for (const n of nodes) {
    const eff = worstFrom(n.id);
    out.set(n.id, { health: eff, inherited: HEALTH_RANK[eff] > HEALTH_RANK[own.get(n.id) ?? "off"] });
  }
  return out;
}

/** Lay out the PROJECT network (kits excluded, #3007) with the layered left→right DAG engine — a plain
 *  GRID when there are no project dependency edges, else longest-path layering + barycenter ordering.
 *  Mutates each project node's `layer`/`x`/`y` in place. `byId` indexes ALL nodes; `cycleEdge` is the set
 *  of mutual-pair edge ids to exclude from layering. This is the pre-#3007 `buildGraph` body verbatim,
 *  scoped to `projNodes`/`projEdges` (so a project-only graph is byte-identical to before). */
function layoutProjectNetwork(projNodes: GNode[], projEdges: GEdge[], byId: Record<string, GNode>, cycleEdge: ReadonlySet<string>): void {
  // No dependency edges (real projects before a cross-project relationship model exists): a plain GRID so
  // the cards read as a network of peers instead of stacking in one column. Skip the layering.
  if (projEdges.length === 0) {
    const cols = Math.max(1, Math.round(Math.sqrt(projNodes.length)));
    projNodes.forEach((n, i) => { n.layer = 0; n.x = 70 + (i % cols) * COLGAP; n.y = 70 + Math.floor(i / cols) * ROWGAP; });
    return;
  }

  // Longest-path layering via the shared layerer (#2214). Glance is a DEPENDS-ON DAG (from depends on
  // to → the dependency `to` must sit at a LOWER layer), so we hand `layerDag` the edges REVERSED — its
  // "from → deeper" convention then puts each dependency below its dependent. Cycle (mutual-pair) edges
  // are excluded so the loop can't diverge.
  const reversed = projEdges.map((e) => ({ id: e.id, from: e.to, to: e.from }));
  const layer = layerDag(projNodes.map((n) => n.id), reversed, cycleEdge);
  projNodes.forEach((n) => (n.layer = layer[n.id]));

  // Crossing reduction via the shared barycenter orderer (#2418) with glance's tunables: every edge
  // endpoint pulls (both directions, cycle edges included), 6 snapshot sweeps.
  const nb = new Map<string, string[]>(projNodes.map((n) => [n.id, []]));
  projEdges.forEach((e) => { nb.get(e.from)!.push(e.to); nb.get(e.to)!.push(e.from); });
  const order = orderLayers(projNodes.map((n) => n.id), (id) => layer[id], (id) => nb.get(id)!, { passes: 6, sweep: "snapshot" });

  const maxCount = Math.max(1, ...[...order.values()].map((a) => a.length));
  const Cy = 70 + (maxCount - 1) * ROWGAP / 2;
  for (const [L, arr] of order) {
    arr.forEach((id, i) => {
      byId[id].x = 70 + L * COLGAP;
      byId[id].y = Cy + (i - (arr.length - 1) / 2) * ROWGAP;
    });
  }
}

/** Build the laid-out, cycle-aware graph model from raw nodes + edges. Deterministic. */
export function buildGraph(rawNodes: GRawNode[], rawEdges: GRawEdge[]): GraphModel {
  const nodes: GNode[] = rawNodes.map((n) => ({ ...n, slug: n.slug ?? n.id, layer: 0, x: 0, y: 0, rollupHealth: n.health, healthInherited: false }));
  const byId: Record<string, GNode> = {};
  nodes.forEach((n) => (byId[n.id] = n));

  const edges: GEdge[] = rawEdges
    .filter((e) => byId[e.from] && byId[e.to] && e.from !== e.to)
    .map((e, i) => ({ id: e.id ?? "e" + i, from: e.from, to: e.to, kind: e.kind, archetype: e.archetype, hard: e.kind !== "events", isCycle: false, d: "", arrow: "" }));

  // Cycle detection: mutual pairs (a→b AND b→a) — the shared graph-core primitive (#2217).
  const { pairs: cyclePairs, edgeIds: cycleEdge, nodeIds: cycleNodeIds } = mutualPairs(edges);
  edges.forEach((e) => { if (cycleEdge.has(e.id)) e.isCycle = true; });

  // Roll health up the dependency edges (#2541) — every node now carries its effective (rolled) health.
  // Band nodes (kits/algorithms/sounds AND mcp contracts, #3786) are always `idle` and never propagate, so
  // the `uses-kit` / `requires` / `uses-mcp` edges have no effect here (#3007/#3119/#3786).
  const rolled = rollUpHealth(nodes, edges);
  nodes.forEach((n) => { const r = rolled.get(n.id)!; n.rollupHealth = r.health; n.healthInherited = r.inherited; });

  // #3007 (generalized #3119 → external contracts #3786) — LIFT every non-project BAND node (UI kits
  // AND/OR algorithms/sounds AND/OR mcp contracts) out of the dependency DAG into their own fenced band
  // across the top, so they read as a separate dimension, not an intermixed project column. The PROJECT
  // network lays out with ONLY the project nodes + project edges (the existing engine, unchanged); the band
  // nodes then sit in a single row above it and every project node shifts down to clear the band.
  const bandNodes = nodes.filter(isBandNode);
  const projNodes = nodes.filter((n) => !isBandNode(n));
  const projEdges = edges.filter((e) => !isBandEdge(e.kind));

  layoutProjectNetwork(projNodes, projEdges, byId, cycleEdge);

  let bandZone: { x0: number; x1: number } | undefined;
  if (bandNodes.length > 0) {
    // A single library COLUMN past the rightmost project, evenly spaced and centred over the project's
    // vertical span, the step capped at one row gap so a couple of nodes cluster in the middle instead of
    // stretching the full height. `layer = -1` marks them as band nodes (outside the project layering).
    //
    // Unlike the old top band, nothing shifts: the column occupies space the project network never used,
    // so the projects keep the exact positions the layout engine gave them.
    const projMaxX = projNodes.length ? Math.max(...projNodes.map((n) => n.x)) : 70;
    const projMinY = projNodes.length ? Math.min(...projNodes.map((n) => n.y)) : 70;
    const projMaxY = projNodes.length ? Math.max(...projNodes.map((n) => n.y)) : 70;
    const fenceX = projMaxX + NW + BAND_FENCE_PAD;
    const cardX = fenceX + BAND_CARD_GAP;
    const positions = layoutBandColumn(bandNodes.length, projMinY, projMaxY, cardX, ROWGAP);
    bandNodes.forEach((k, i) => { k.layer = -1; k.x = positions[i].x; k.y = positions[i].y; });

    // The fence sits a gap to the LEFT of the band cards; the zone runs from there out past their right
    // edge, so the canvas has a rect to wash and a divider line to draw.
    bandZone = { x0: fenceX, x1: cardX + NW + BAND_FENCE_PAD };
  }

  let maxX = 0, maxY = 0;
  nodes.forEach((n) => { maxX = Math.max(maxX, n.x); maxY = Math.max(maxY, n.y); });
  const worldW = maxX + NW + 80, worldH = maxY + NH + 90;

  // Edge geometry LAST — after both the project layout and the library-band shift — so every endpoint is
  // final. `e.kind` routes LIBRARY edges (`uses-kit`/`requires`) vertically (perimeter-anchor); project
  // edges keep side ports.
  edges.forEach((e) => Object.assign(e, edgeGeom(byId[e.from], byId[e.to], e.isCycle, e.kind)));

  return { nodes, edges, cyclePairs, cycleNodeIds, worldW, worldH, bandZone };
}

