// The `glance-node` kit's MOTION library as DATA (#4032, epic #2942) — the fleet node's live states
// authored as {@link KitAnimation} data and compiled by the kit-motion engine, instead of the raw
// keyframe + inline style they were.
//
// ── WHY THIS LIVES IN shared/ui/kit ──────────────────────────────────────────────────────────────
// The same reason the array / graph / matrix viz sets do (#3242): two consumers, one definition. Here
// they are the live `GlanceNode` renderer and the designer, which reads the registered component
// record. Feature-agnostic motion belongs where neither feature owns it.
//
// ── WHY `trigger: "always"` ──────────────────────────────────────────────────────────────────────
// These are STATE animations: they play for as long as the node is in the state, unlike the viz kits'
// one-shot transitions. The engine already models that — `compileAnimationsCss` emits `infinite` for
// an `always` trigger — so nothing about the schema had to change to express them. Nobody had simply
// authored one before: the store held 254 component records and ZERO motion.
//
// ── WHY THERE IS NO `complete` ENTRY, AND NO AMBIENT GLOW ───────────────────────────────────────
// #4040 removed a health glow that ran on EVERY node, all the time. It read as work happening, which
// spent the node's strongest signal on the one thing carrying no information — motion means "look at
// this", and if everything moves, nothing does. Health is a COLOUR (the dot); motion is reserved for
// the two states that want you.
// Its stillness IS the statement. The node vocabulary is: building BREATHES, attention RINGS, complete
// is STILL — motion means "look at this", and a finished worker is the one state with nothing to do
// about it. The absence of an entry is how that reads as data, so a designer adding one is making a
// deliberate change rather than filling a gap.

import type { KitAnimation } from "@/shared/ui/kit/animations";

/** The fleet-node motion kit id — `.glance-node-anim-<name>` + `@keyframes bsc-glance-node-<name>`. */
export const GLANCE_NODE_KIT_ID = "glance-node";

/**
 * The fleet node's state motion as DATA. Bound to the `data-node-state` attribute `GlanceNode` stamps,
 * so the selector IS the state — no class bookkeeping, and a designer reading the record can see which
 * state each animation belongs to.
 */
export const GLANCE_NODE_ANIMATIONS: KitAnimation[] = [
  // BUILDING — the node breathes while the worker is actively working.
  //
  // Shallow (1 → .78) and slower than the status dot (1.8s vs 1.4s), both deliberately: the dot's .45
  // floor applied to a whole node reads as BROKEN rather than busy, and a row of workers dipping that
  // far in unison is unpleasant to look at. This is the one animation a whole fleet may run at once.
  {
    name: "building",
    selector: '[data-node-state="building"]',
    trigger: "always",
    duration: "1800ms",
    easing: "ease-in-out",
    keyframes: {
      "0%": { opacity: "1" },
      "50%": { opacity: "0.78" },
      "100%": { opacity: "1" },
    },
  },
];

// The `glance-node` kit's MOTION wiring (#4032, epic #2942) — compiles the authored animation DATA
// into CSS once and injects it into a managed <style>. Mirrors `ensureGraphViewMotion` on its own
// style id; the animation data itself lives in `@/shared/ui/kit/glanceNodeAnimations` so the designer
// and this renderer read ONE definition.
import { animClassName, compileAnimationsCss, kitAnimations } from "@/shared/ui/kit";
import { GLANCE_NODE_KIT_ID, GLANCE_NODE_ANIMATIONS } from "@/shared/ui/kit/glanceNodeAnimations";

export { GLANCE_NODE_KIT_ID, GLANCE_NODE_ANIMATIONS };

/** The applying classes the node carries so the state-scoped rules match it. */
export const GLANCE_NODE_ANIM_CLASSES: string = GLANCE_NODE_ANIMATIONS.map((a) =>
  animClassName({ kit: GLANCE_NODE_KIT_ID, name: a.name }),
).join(" ");

/** The compiled motion CSS — produced ONCE from the authored data. Pure. */
export const GLANCE_NODE_MOTION_CSS: string = compileAnimationsCss(
  kitAnimations([{ id: GLANCE_NODE_KIT_ID, animations: GLANCE_NODE_ANIMATIONS }]),
);

const STYLE_ID = "bsc-glance-node-animations";

/** Inject the compiled node motion CSS into a dedicated managed `<style>` (idempotent). `doc` param'd
 *  for tests. */
export function ensureGlanceNodeMotion(doc: Document = document): void {
  if (!GLANCE_NODE_MOTION_CSS) return;
  let el = doc.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!el) {
    el = doc.createElement("style");
    el.id = STYLE_ID;
    doc.head.appendChild(el);
  }
  if (el.textContent !== GLANCE_NODE_MOTION_CSS) el.textContent = GLANCE_NODE_MOTION_CSS;
}

// Node-parting geometry (#2671, supersedes the #2666 d3-force relaxation) — when the terminal morph GROWS
// in the graph (#2534/#2662), the neighbourhood PARTS to make room in four rigid "curtains" (left/right/
// up/down), split by the panel's aspect-scaled diagonals. Each curtain translates as ONE block by the
// clearance its most-penetrating member needs, so:
//   1. every neighbour clears the panel BY CONSTRUCTION — a hard guarantee the old soft, alpha-scaled
//      force could not make (it settled at equilibrium with residual penetration → the visible clipping);
//   2. nodes never clip INTO each other either — a curtain shifts RIGIDLY, so members keep their exact
//      relative spacing (the whole region slides aside, like curtains parting), and orthogonal curtains
//      move away from their shared diagonal.
// Closed-form + deterministic (no simulation, no tuning knobs): the same rect always yields the same
// offsets — no jitter — and it's cheap enough to recompute live during a resize drag. Pure (React/DOM-
// free) so the clearance guarantee + the rigid spacing are unit-tested in isolation. The canvas animates
// each node's offset AND the panel's grow off one matched easing, so the two read as a single motion.
import { NW, NH } from "@/features/glance/lib/glanceGraph";

/** The expanded panel's world box — reported by the morph, consumed by the canvas. */
export interface MorphRect { left: number; top: number; w: number; h: number }

/** Clearance (world px) every neighbour keeps from the expanded terminal panel. */
export const PUSH_MARGIN = 36;

type Dir = "left" | "right" | "up" | "down";

/**
 * Per-node box offset so the graph PARTS to make room for the open panel `rect` — the four-curtain model.
 * Each neighbour is assigned to a curtain by which side of the panel it sits on (the panel's aspect-scaled
 * diagonals decide the dominant axis), then every curtain translates as one rigid block by the largest
 * clearance any of its members needs. Result: the panel is cleared by construction (no node clips into it)
 * and every curtain keeps its internal spacing (no node clips into a neighbour). Returns a
 * `nodeId → {dx,dy}` map of the NON-ZERO shifts only. Pure + deterministic.
 *
 * `rect` is the region to clear. Since #3361 that is the whole OCCUPIED GRID REGION (the bounding box of
 * every open morph's slot), not a single free-floating panel — the four-curtain model is indifferent to
 * how large the region is, so parting around N morphs is the same computation as parting around one.
 *
 * `exclude` are the nodes sitting UNDER the region — the grown nodes themselves — which must not be
 * pushed. Accepts one id or a set (the multi-morph case).
 */
export function partAroundPanel(
  nodes: { id: string; x: number; y: number }[],
  rect: MorphRect,
  exclude?: string | ReadonlySet<string>,
): Map<string, { dx: number; dy: number }> {
  const excluded = typeof exclude === "string" ? new Set([exclude]) : exclude;
  const out = new Map<string, { dx: number; dy: number }>();
  const cx0 = rect.left + rect.w / 2, cy0 = rect.top + rect.h / 2;
  const hx = rect.w / 2, hy = rect.h / 2;
  // The Minkowski-expanded forbidden box for a node CENTRE: the panel grown by the node's half-extent +
  // the margin. A node centre inside this box means its card overlaps the panel (within the margin).
  const fx0 = rect.left - NW / 2 - PUSH_MARGIN, fx1 = rect.left + rect.w + NW / 2 + PUSH_MARGIN;
  const fy0 = rect.top - NH / 2 - PUSH_MARGIN, fy1 = rect.top + rect.h + NH / 2 + PUSH_MARGIN;

  // Pass 1 — assign each node to a curtain and record the max clearance that curtain must provide.
  const need: Record<Dir, number> = { left: 0, right: 0, up: 0, down: 0 };
  const dirOf = new Map<string, Dir>();
  for (const n of nodes) {
    if (excluded?.has(n.id)) continue;
    const cx = n.x + NW / 2, cy = n.y + NH / 2;
    // Wedge by the panel's diagonals, scaled to its aspect: whichever axis the node is more displaced
    // along (relative to the panel's half-size) wins, so the split lines run corner-to-corner.
    const dir: Dir =
      Math.abs(cx - cx0) / hx >= Math.abs(cy - cy0) / hy
        ? (cx < cx0 ? "left" : "right")
        : (cy < cy0 ? "up" : "down");
    dirOf.set(n.id, dir);
    // If this node overlaps the panel, the distance to slide it out of the forbidden box along its
    // curtain's OWN axis (always positive for an overlapper, since its centre is inside the box).
    if (cx > fx0 && cx < fx1 && cy > fy0 && cy < fy1) {
      const exit = dir === "left" ? cx - fx0 : dir === "right" ? fx1 - cx : dir === "up" ? cy - fy0 : fy1 - cy;
      if (exit > need[dir]) need[dir] = exit;
    }
  }

  // Pass 2 — every member of a curtain takes that curtain's block shift (rigid → spacing preserved).
  const vec: Record<Dir, { dx: number; dy: number }> = {
    left: { dx: -need.left, dy: 0 }, right: { dx: need.right, dy: 0 },
    up: { dx: 0, dy: -need.up }, down: { dx: 0, dy: need.down },
  };
  for (const n of nodes) {
    const dir = dirOf.get(n.id);
    if (!dir) continue;
    const v = vec[dir];
    if (v.dx || v.dy) out.set(n.id, v);
  }
  return out;
}

// The glancepage PROJECTION (#the-glance-record-lost-the-architect-and-four-other-fixes).
//
// WHY THIS EXISTS. Glance does not render `GlanceWorkspace.tsx`. `lazyWorkspaces.tsx` aliases the
// workspace to `GlanceGraphHost`, which renders `<GraphComponent id="glancepage" />` (#4185, epic
// #3604) — so the running cockpit is the `glancepage` RECORD, and the `.tsx` is its source of truth
// only if something keeps the two in step. Nothing did. The record was last mirrored by hand in
// bc3f38d1 (2026-08-12) and then drifted for weeks, silently losing the architect drill
// (#architect-node-expands-into-system-sessions), the contract re-read
// (#architect-wires-project-relationships), plan.db outranking the persisted fleet, the progress
// ref-namespace split, and the director progress fallback. Every one of those was live in `src/`
// and dead in the app.
//
// THE RECORD IS A PROJECTION, NOT A COPY, and all three differences below are deliberate — reproduce
// them or the page breaks:
//
//   1. The AS GRAPH SOURCE preamble, which tells a reader of the record where its behaviour comes from.
//   2. First-party RELATIVE specifiers rewritten ABSOLUTE. The runtime loader resolves a record's
//      imports against the app's module registry, not against a directory, so `./lib/glanceData` has
//      no meaning to it. Sibling COMPONENTS resolve differently again — as `@/components/<record-id>`
//      graph records, not as feature paths — which is why they need their own map rather than the
//      same prefix rule.
//   3. `import "@/features/glance/lib/glance.css"` STRIPPED. The loader cannot resolve a CSS side-effect import;
//      `GlanceGraphHost` owns the stylesheet instead (see its header).
//
// Keeping this as a pure function, rather than inline in the generator, is what lets the guard test
// assert the record IS the projection — the check that would have caught the drift.

/** The record's preamble — four lines, verbatim, ahead of the file's own header. */
export const GRAPH_SOURCE_HEADER = [
  "// Glance → the cockpit workspace (#2206), AS GRAPH SOURCE (#4185, epic #3604). Transcribed from the live feature file: the runtime",
  "// loader compiles this and mounts it, resolving every import to the app's real modules (the shared/ui",
  "// design system + the store via appModules, the glance lib/hook surface via the glance graph-platform,",
  "// and the sibling components as @/components/* graph records). Behaviour runs here.",
];

/** Sibling COMPONENTS resolve as graph records (`@/components/<id>`), not as feature paths. A sibling
 *  added to `GlanceWorkspace.tsx` without an entry here would be rewritten to a feature path that the
 *  loader cannot resolve, so {@link projectGlancePage} throws rather than emitting a broken record. */
export const SIBLING_RECORDS: Record<string, string> = {
  "./GlanceCanvas": "@/components/glance-canvas",
  "./GlanceChatDock": "@/components/glance-chat-dock",
};

/** Relative specifiers that are NOT sibling components resolve as feature paths under the glance slice. */
const FEATURE_PREFIX = "@/features/glance/";

/** The CSS side-effect import the loader cannot resolve — dropped; the host imports it instead. */
const CSS_IMPORT = 'import "@/features/glance/lib/glance.css";';

/**
 * Project `GlanceWorkspace.tsx` source into the `glancepage` record's `srcText`.
 *
 * @param src the file's verbatim contents (LF-normalized by the caller).
 * @returns the record source: preamble + the file with its relative imports resolved and the CSS
 *   side-effect import removed.
 * @throws if a relative specifier points OUT of the glance slice (`../`), which the record has no way
 *   to express — better to fail the generator than to emit a record that compiles to the wrong module.
 */
export function projectGlancePage(src: string): string {
  const out: string[] = [];
  for (const line of src.replace(/\r\n/g, "\n").split("\n")) {
    if (line.trim() === CSS_IMPORT) continue;
    out.push(rewriteSpecifier(line));
  }
  return [...GRAPH_SOURCE_HEADER, ...out].join("\n");
}

/** Rewrite one line's relative import specifier, if it has one. */
function rewriteSpecifier(line: string): string {
  return line.replace(/from "(\.\.?\/[^"]+)"/, (_match, spec: string) => {
    if (SIBLING_RECORDS[spec]) return `from "${SIBLING_RECORDS[spec]}"`;
    if (spec.startsWith("../")) {
      throw new Error(
        `glancepage projection: cannot express the out-of-slice specifier ${spec}. A record resolves ` +
        `against the module registry, so an import that leaves the glance slice needs an explicit ` +
        `@/… path in GlanceWorkspace.tsx, or an entry in SIBLING_RECORDS if it is a graph component.`,
      );
    }
    return `from "${FEATURE_PREFIX}${spec.slice(2)}"`;
  });
}

// glTF / scene renderer (#581 PV-gltf).
//
// Mounts a persistent iframe that runs three.js (loaded from esm.sh via import-map)
// and receives glTF data via postMessage. The iframe stays mounted between updates;
// each render_gltf command replaces the previous model without reloading the runtime.
//
// Payload shape: { url?: string; base64?: string }
//   url    — a URL the iframe can fetch (same-origin or CORS-enabled).
//   base64 — raw glTF JSON or binary GLB, base64-encoded.
//            The iframe constructs a data URI: data:model/gltf+json;base64,<base64>.

import type { PreviewRenderer, RendererHandle } from '@/features/planner/preview/registry';
import type { RenderableChunk, PreviewStatus } from '@/features/planner/preview/types';
import { buildGltfRuntimeHtml } from '@/features/planner/preview/streamingRuntime';

type GltfPayload = { url?: string; base64?: string };

function createGltfRenderer(): PreviewRenderer {
  return {
    kind: ['gltf', 'scene'],

    mount(container: HTMLElement, initial: RenderableChunk): RendererHandle {
      const iframe = document.createElement('iframe');
      iframe.title = 'glTF preview';
      // allow-scripts: run three.js; no host access.
      iframe.setAttribute('sandbox', 'allow-scripts');
      iframe.style.cssText = 'flex:1;width:100%;height:100%;border:none;background:#0d0d0f';
      container.style.cssText = 'display:flex;flex:1;min-height:0';
      container.appendChild(iframe);

      let statusCb: ((s: PreviewStatus) => void) | undefined;
      let runtimeReady = false;
      let pendingChunk: RenderableChunk | null = null;

      // Bootstrap the three.js runtime.
      iframe.srcdoc = buildGltfRuntimeHtml();

      function sendGltf(payload: GltfPayload) {
        iframe.contentWindow?.postMessage(
          { __preview_cmd: 'render_gltf', url: payload.url, base64: payload.base64 },
          '*',
        );
      }

      function onMsg(e: MessageEvent) {
        const d = e.data as { __preview?: string; message?: unknown } | null;
        if (!d || typeof d !== 'object') return;
        if (d.__preview === 'runtime_ready') {
          runtimeReady = true;
          if (pendingChunk) {
            sendGltf(pendingChunk.payload as GltfPayload);
            pendingChunk = null;
          }
        } else if (d.__preview === 'ready') {
          statusCb?.({ status: 'ready' });
        } else if (d.__preview === 'error') {
          statusCb?.({ status: 'error', message: String(d.message ?? '') });
        }
      }
      window.addEventListener('message', onMsg);

      // Apply initial chunk once runtime is ready.
      const initPayload = initial.payload as GltfPayload;
      if (initPayload.url || initPayload.base64) {
        if (runtimeReady) {
          sendGltf(initPayload);
        } else {
          pendingChunk = initial;
        }
      }

      const handle: RendererHandle = {
        update(chunk: RenderableChunk) {
          const p = chunk.payload as GltfPayload;
          if (!runtimeReady) {
            pendingChunk = chunk;
          } else {
            sendGltf(p);
          }
        },
        onStatus(cb) { statusCb = cb; },
        teardown() {
          window.removeEventListener('message', onMsg);
          if (container.contains(iframe)) container.removeChild(iframe);
        },
      };
      return handle;
    },
  };
}

export const gltfRenderer = createGltfRenderer();

// Graph traversal / shortest-path trace-programs (#3224, epic #3220/#3215) — real algorithms written over
// a TracedGraph, so the animation is DERIVED from the traversal's own execution: the frontier expands,
// nodes turn visited, edges relax. BFS is the proof; dfs / dijkstra / a-star / topological-sort follow.
// Keyed by base name (bfs.rs → bfs), so the existing Rust graph impls animate via their JS trace-program.
import type { TracedGraph, GraphInput } from "@/features/algorithms/lib/tracer";

/** A visualizable graph algorithm — its real logic over a {@link TracedGraph} + the graph to seed it. */
export interface GraphProgram {
  run: (g: TracedGraph) => void;
  defaultInput: GraphInput;
}

/** A small, connected example graph (6 nodes) — legible under the renderer's circular layout, and shows a
 *  clear BFS wavefront from `a`. */
export const DEFAULT_GRAPH: GraphInput = {
  nodes: ["a", "b", "c", "d", "e", "f"].map((id) => ({ id })),
  edges: [
    { from: "a", to: "b" },
    { from: "a", to: "c" },
    { from: "b", to: "d" },
    { from: "c", to: "d" },
    { from: "c", to: "e" },
    { from: "d", to: "f" },
    { from: "e", to: "f" },
  ],
};

/** Breadth-first search from the first node — a queue expands the frontier level by level; each dequeued
 *  node is visited and its undiscovered neighbours are relaxed + enqueued. The visit order is BFS order. */
export function bfs(g: TracedGraph): void {
  const ids = g.ids();
  if (ids.length === 0) return;
  const start = ids[0];
  const seen = new Set<string>([start]);
  const queue: string[] = [start];
  g.frontier(start);
  while (queue.length > 0) {
    const node = queue.shift() as string;
    g.visit(node);
    for (const nb of g.neighbours(node)) {
      if (!seen.has(nb.to)) {
        seen.add(nb.to);
        g.relax(node, nb.to);
        g.frontier(nb.to);
        queue.push(nb.to);
      }
    }
  }
}

/** Depth-first search from the first node — go deep along one path, backtracking when a node has no
 *  undiscovered neighbours. The visit order goes deep first (distinct from BFS's level-by-level order). */
export function dfs(g: TracedGraph): void {
  const ids = g.ids();
  if (ids.length === 0) return;
  const seen = new Set<string>([ids[0]]);
  const go = (node: string): void => {
    g.visit(node);
    for (const nb of g.neighbours(node)) {
      if (!seen.has(nb.to)) {
        seen.add(nb.to);
        g.relax(node, nb.to);
        g.frontier(nb.to);
        go(nb.to);
      }
    }
  };
  g.frontier(ids[0]);
  go(ids[0]);
}

/** A weighted graph for the shortest-path algorithms — the edge weights drive the visit ORDER. */
export const WEIGHTED_GRAPH: GraphInput = {
  nodes: ["a", "b", "c", "d", "e", "f"].map((id) => ({ id })),
  edges: [
    { from: "a", to: "b", weight: 4 },
    { from: "a", to: "c", weight: 2 },
    { from: "b", to: "c", weight: 1 },
    { from: "b", to: "d", weight: 5 },
    { from: "c", to: "d", weight: 8 },
    { from: "c", to: "e", weight: 10 },
    { from: "d", to: "e", weight: 2 },
    { from: "d", to: "f", weight: 6 },
    { from: "e", to: "f", weight: 3 },
  ],
};

/** Dijkstra's shortest path from the first node to the last — visit unvisited nodes in increasing
 *  distance (O(V²) min-extract, teaching-sized), relaxing edges to shorten neighbours, then light the
 *  final route. */
export function dijkstra(g: TracedGraph): void {
  const ids = g.ids();
  if (ids.length === 0) return;
  const start = ids[0];
  const goal = ids[ids.length - 1];
  const dist = new Map<string, number>(ids.map((id) => [id, Infinity]));
  const prev = new Map<string, string>();
  const done = new Set<string>();
  dist.set(start, 0);
  g.mark(start, "start");
  g.mark(goal, "goal");
  while (done.size < ids.length) {
    let u: string | null = null;
    let best = Infinity;
    for (const id of ids) {
      const d = dist.get(id) ?? Infinity;
      if (!done.has(id) && d < best) {
        best = d;
        u = id;
      }
    }
    if (u === null) break; // the remaining nodes are unreachable
    done.add(u);
    g.current(u);
    g.visit(u);
    for (const nb of g.neighbours(u)) {
      if (done.has(nb.to)) continue;
      g.relax(u, nb.to);
      const nd = (dist.get(u) ?? Infinity) + nb.weight;
      if (nd < (dist.get(nb.to) ?? Infinity)) {
        dist.set(nb.to, nd);
        prev.set(nb.to, u);
        g.frontier(nb.to);
      }
    }
  }
  if ((dist.get(goal) ?? Infinity) < Infinity) {
    const path: string[] = [];
    let cur: string | undefined = goal;
    while (cur !== undefined) {
      path.unshift(cur);
      cur = prev.get(cur);
    }
    g.path(path);
  }
}

/** A small DAG for topological sort — directed edges (`from → to`) with no cycle. */
const DAG_GRAPH: GraphInput = {
  nodes: ["a", "b", "c", "d", "e", "f"].map((id) => ({ id })),
  edges: [
    { from: "a", to: "c" },
    { from: "b", to: "c" },
    { from: "b", to: "d" },
    { from: "c", to: "e" },
    { from: "d", to: "e" },
    { from: "e", to: "f" },
  ],
};

/** Kahn's topological sort — repeatedly take a node with no remaining incoming edges (in-degree 0),
 *  visit it, and decrement its successors' in-degrees. The visit order is a valid topological order. */
export function topologicalSort(g: TracedGraph): void {
  const ids = g.ids();
  const indeg = g.inDegrees();
  const queue = ids.filter((id) => (indeg.get(id) ?? 0) === 0);
  const order: string[] = [];
  for (const id of queue) g.frontier(id);
  while (queue.length > 0) {
    const node = queue.shift() as string;
    g.visit(node);
    order.push(node);
    for (const nb of g.outNeighbours(node)) {
      g.relax(node, nb.to);
      const d = (indeg.get(nb.to) ?? 0) - 1;
      indeg.set(nb.to, d);
      if (d === 0) {
        g.frontier(nb.to);
        queue.push(nb.to);
      }
    }
  }
  if (order.length === ids.length) g.path(order); // a valid order exists (the DAG has no cycle)
}

/** A SPATIAL weighted graph (nodes carry x/y) — A*'s heuristic (straight-line distance to the goal) guides
 *  the search toward `g`, pruning the off-route nodes Dijkstra would still explore. Edge weights are the
 *  straight-line distances, so the heuristic is admissible. */
const SPATIAL_GRAPH: GraphInput = {
  nodes: [
    { id: "a", x: 0, y: 0 },
    { id: "b", x: 2, y: 0 },
    { id: "c", x: 1, y: 3 },
    { id: "d", x: 4, y: 0 },
    { id: "e", x: 4, y: 2 },
    { id: "g", x: 6, y: 0 },
  ],
  edges: [
    { from: "a", to: "b", weight: 2 },
    { from: "a", to: "c", weight: 3.2 },
    { from: "b", to: "d", weight: 2 },
    { from: "b", to: "e", weight: 2.8 },
    { from: "c", to: "e", weight: 3.2 },
    { from: "d", to: "e", weight: 2 },
    { from: "d", to: "g", weight: 2 },
    { from: "e", to: "g", weight: 2.8 },
  ],
};

/** Straight-line distance between two points; `0` when either lacks coordinates (A* → Dijkstra). */
function euclid(a: { x: number; y: number } | null, b: { x: number; y: number } | null): number {
  return a && b ? Math.hypot(a.x - b.x, a.y - b.y) : 0;
}

/** A* shortest path from the first node to the last — like Dijkstra, but the priority is g + h where h is
 *  the straight-line distance to the goal, so the search is guided toward it (exploring fewer nodes). */
export function aStar(g: TracedGraph): void {
  const ids = g.ids();
  if (ids.length === 0) return;
  const start = ids[0];
  const goal = ids[ids.length - 1];
  const gScore = new Map<string, number>(ids.map((id) => [id, Infinity]));
  const fScore = new Map<string, number>(ids.map((id) => [id, Infinity]));
  const prev = new Map<string, string>();
  const open = new Set<string>([start]);
  const closed = new Set<string>();
  const h = (id: string): number => euclid(g.coord(id), g.coord(goal));
  gScore.set(start, 0);
  fScore.set(start, h(start));
  g.mark(start, "start");
  g.mark(goal, "goal");
  while (open.size > 0) {
    let cur: string | null = null;
    let best = Infinity;
    for (const id of open) {
      const f = fScore.get(id) ?? Infinity;
      if (f < best) {
        best = f;
        cur = id;
      }
    }
    if (cur === null) break;
    open.delete(cur);
    closed.add(cur);
    g.current(cur);
    g.visit(cur);
    if (cur === goal) break; // reached — the heuristic guarantees this is optimal
    for (const nb of g.neighbours(cur)) {
      if (closed.has(nb.to)) continue;
      g.relax(cur, nb.to);
      const tentative = (gScore.get(cur) ?? Infinity) + nb.weight;
      if (tentative < (gScore.get(nb.to) ?? Infinity)) {
        prev.set(nb.to, cur);
        gScore.set(nb.to, tentative);
        fScore.set(nb.to, tentative + h(nb.to));
        open.add(nb.to);
        g.frontier(nb.to);
      }
    }
  }
  if (goal === start || prev.has(goal)) {
    const path: string[] = [];
    let c: string | undefined = goal;
    while (c !== undefined) {
      path.unshift(c);
      c = prev.get(c);
    }
    g.path(path);
  }
}

/** The visualizable graph algorithms, keyed by base name (#3224/#3226/#3228) — the full family. */
export const GRAPH_PROGRAMS: Record<string, GraphProgram> = {
  bfs: { run: bfs, defaultInput: DEFAULT_GRAPH },
  dfs: { run: dfs, defaultInput: DEFAULT_GRAPH },
  dijkstra: { run: dijkstra, defaultInput: WEIGHTED_GRAPH },
  "a-star": { run: aStar, defaultInput: SPATIAL_GRAPH },
  "topological-sort": { run: topologicalSort, defaultInput: DAG_GRAPH },
};

/** Serialize a graph to an adjacency-list text (undirected, each edge listed under its first endpoint). */
export function graphToText(input: GraphInput): string {
  const out = new Map<string, string[]>();
  for (const n of input.nodes) out.set(n.id, []);
  for (const e of input.edges) out.get(e.from)?.push(e.to);
  return input.nodes
    .filter((n) => (out.get(n.id) ?? []).length > 0)
    .map((n) => `${n.id}: ${(out.get(n.id) ?? []).join(", ")}`)
    .join("\n");
}

/**
 * Parse the "your input" text into a graph — an adjacency list, one node per line (`a: b, c`), rows split
 * by newline or `;`, neighbours by comma/space. Edges are UNDIRECTED (deduped). Throws a helpful `Error`
 * on empty or oversized input. Node order follows first appearance (the BFS start is the first node).
 */
export function parseGraphInput(text: string): GraphInput {
  const lines = text.split(/[\n;]/).map((l) => l.trim()).filter((l) => l.length > 0);
  if (lines.length === 0) throw new Error("Enter an adjacency list, e.g. a: b, c");
  const order: string[] = [];
  const seen = new Set<string>();
  const add = (id: string) => {
    if (!seen.has(id)) {
      seen.add(id);
      order.push(id);
    }
  };
  const edgeKeys = new Set<string>();
  const edges: { from: string; to: string }[] = [];
  for (const line of lines) {
    const [head, rest = ""] = line.split(":");
    const from = head.trim();
    if (!from) continue;
    add(from);
    for (const to of rest.split(/[\s,]+/).map((t) => t.trim()).filter((t) => t.length > 0)) {
      add(to);
      const key = [from, to].sort().join("~"); // undirected dedup
      if (!edgeKeys.has(key)) {
        edgeKeys.add(key);
        edges.push({ from, to });
      }
    }
  }
  if (order.length > 12) throw new Error("Keep it to 12 nodes or fewer so the graph stays legible");
  return { nodes: order.map((id) => ({ id })), edges };
}

// The Algorithms page's knowledge-graph hydrate (#2856) — the live read over the packaged seed.
// `loadGraph` returns `null` when the read is unavailable (the web shell, the tests) so the page keeps
// rendering the embedded seed rather than blanking. The whole-graph doc is shape-gated
// (`implementations` must be an array) before it's trusted, matching themeBridge's discipline.
//
// IN-PROCESS since #4078 (`graph_dump`), not the `bsc` bridge. `useKnowledgeGraph` polls this every 5s
// while the page is mounted, and through the bridge every tick SPAWNED a subprocess — to read 84 KB,
// hash it, and discard the result because nothing had changed, which is the common case. The command
// calls `bsc_graph::load`, the CLI's own reader, so it resolves the same store and reconciles the same
// seed; the rows are byte-identical.
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { buildKnowledge, type KnowledgeGraph, type RawKnowledge } from "@/features/algorithms/lib/knowledge";

/** Read the librarian's writable store (`~/.base-studio-code/knowledge/algorithms.json`, #2853) and
 *  build the {@link KnowledgeGraph}. `null` on ANY failure — an unavailable command, or a payload whose
 *  `implementations` isn't an array — so a degraded environment simply shows the packaged seed. */
export async function loadGraph(): Promise<KnowledgeGraph | null> {
  try {
    const doc = await safeInvoke<{ implementations?: unknown } | null>(
      "graph_dump",
      undefined,
      null,
    );
    if (!doc || !Array.isArray(doc.implementations)) return null;
    return buildKnowledge(doc as unknown as RawKnowledge);
  } catch {
    return null;
  }
}

// The graph layout (#3224) — a pure, deterministic placement of node ids for the SVG GraphView. Split out
// of the renderer so the renderer file exports only its component (fast-refresh) and the layout is
// unit-testable on its own.

/** The svg viewBox is VIEW × VIEW; the layout circle has this radius. */
export const GRAPH_VIEW = 320;
const RADIUS = 116;

const PAD = 38; // inset for the coordinate layout so nodes don't touch the frame edge

/** Place every id evenly on a circle, starting at the top (−90°). Pure + deterministic. */
export function circularLayout(ids: readonly string[]): Record<string, { x: number; y: number }> {
  const cx = GRAPH_VIEW / 2;
  const cy = GRAPH_VIEW / 2;
  const n = Math.max(1, ids.length);
  const pos: Record<string, { x: number; y: number }> = {};
  ids.forEach((id, i) => {
    const t = (i / n) * 2 * Math.PI - Math.PI / 2;
    pos[id] = { x: cx + RADIUS * Math.cos(t), y: cy + RADIUS * Math.sin(t) };
  });
  return pos;
}

/** A spatial layout from the nodes' own `x`/`y` (a road network, a grid) — scaled + padded to fit the
 *  viewBox. Returns `null` unless EVERY node has coordinates (so the caller can fall back to circular). */
export function coordinateLayout(
  nodes: readonly { id: string; x?: number; y?: number }[],
): Record<string, { x: number; y: number }> | null {
  if (nodes.length === 0 || !nodes.every((n) => n.x !== undefined && n.y !== undefined)) return null;
  const xs = nodes.map((n) => n.x as number);
  const ys = nodes.map((n) => n.y as number);
  const minX = Math.min(...xs);
  const minY = Math.min(...ys);
  const spanX = Math.max(...xs) - minX || 1;
  const spanY = Math.max(...ys) - minY || 1;
  const inner = GRAPH_VIEW - 2 * PAD;
  const pos: Record<string, { x: number; y: number }> = {};
  for (const n of nodes) {
    pos[n.id] = {
      x: PAD + (((n.x as number) - minX) / spanX) * inner,
      y: PAD + (((n.y as number) - minY) / spanY) * inner,
    };
  }
  return pos;
}

/** The layout GraphView uses — the nodes' own coordinates when they all carry them (A*'s spatial graph),
 *  else an even circle. */
export function layoutFor(
  nodes: readonly { id: string; x?: number; y?: number }[],
): Record<string, { x: number; y: number }> {
  return coordinateLayout(nodes) ?? circularLayout(nodes.map((n) => n.id));
}

// The store-backed graph-sibling resolver (#3606, epic #3604) — lets a graph component import ANOTHER graph
// component by id, so a page can compose its panels. Feature-agnostic (it only reads `@/store`, which shared/
// may import), so it sits with the loader in shared/lib/runtime; the loader stays store-agnostic and takes
// this as an injected [`GraphSourceResolver`].
import { useAppStore } from "@/store";
import type { GraphSourceResolver } from "@/shared/lib/runtime/componentLoader";

/** How a graph component imports a SIBLING by id: `import … from "@/components/<id>"`. There is no physical
 *  `@/components/` dir (feature-first killed the layer dirs, #1309), so this specifier never resolves to a
 *  real module — the loader intercepts it and vendors the sibling's source in its place. */
export const GRAPH_SIBLING_PREFIX = "@/components/";

/** Resolve a graph import to `srcText` the loader vendors — reading a snapshot (`getState`), not a
 *  subscription: a page re-loads on ITS OWN source change (the host keys on that); a sibling/override edit
 *  reflects on the page's next load. Two forms resolve to graph source; anything else returns `null` so it
 *  stays external (→ the registry):
 *    1. `@/components/<id>` — a SIBLING by id (a page composing its panels, #3606).
 *    2. a component whose `provides` field equals the specifier — a graph component OVERRIDING a registered
 *       PLATFORM module (#3660), e.g. a shared/ui primitive authored as DATA. Graph-first: this is why
 *       `routeImport` consults the resolver before the registry. */
export const resolveGraphSource: GraphSourceResolver = (specifier) => {
  const { components, algorithmImpls } = useAppStore.getState();
  if (specifier.startsWith(GRAPH_SIBLING_PREFIX)) {
    const id = specifier.slice(GRAPH_SIBLING_PREFIX.length);
    return components.find((c) => c.id === id)?.srcText ?? null;
  }
  const component = components.find((c) => c.provides === specifier);
  if (component) return component.srcText ?? null;
  // 3. an ALGORITHM IMPL whose `provides` equals the specifier — a logic module authored as a record
  //    rather than a file. Its `code` IS the module (harvested with `bsc graph harvest --module`), so it
  //    vendors exactly like a component's `srcText`.
  //
  //    LAST, and that ordering is a decision rather than an accident: two stores can now claim one
  //    specifier, and a component claiming it means a UI record overriding a registered platform module
  //    (#3660) — the established meaning of `provides`. If an impl could win, it would silently shadow a
  //    rendering component with a non-rendering module, which fails at mount rather than at resolution.
  //    So an impl resolves only where no component claims the specifier.
  return algorithmImpls.find((im) => im.provides === specifier)?.code ?? null;
};

// Shared graph core (#2214, epic) — the pure (React-free) graph primitives that Glance, the Org
// designer, and the agent-relationship graph all build on, so layering/cycle/focus logic lives once
// instead of being re-copied per domain (#2204: "layout is a function of the data structure"). The
// render layer is already shared (GraphCanvas + useGraphViewport, #2208); this is the model layer.
//
// Each feature extends these bases with its own domain fields (role/status/kind/hardness/…) and
// palettes — the core only knows ids + direction.

/** The minimum a node needs to participate in the shared graph algorithms. */
export interface GraphNode {
  id: string;
}

/** A directed edge; `from`/`to` are node ids. Direction matters for layering + cycle detection. */
export interface GraphEdge {
  id: string;
  from: string;
  to: string;
}

// The `graph` viz kit's MOTION wiring (#3224, epic #3220/#2942) — injects the compiled motion CSS
// (frontier / visit / relax) into the live GraphView. SVG-safe properties only. The animation DATA now
// lives in a SHARED, feature-agnostic home (`@/shared/ui/kit/graphVizAnimations`, #3242) so BOTH consumers
// read ONE definition: this renderer AND the Designs `graph-viz` builtin kit — see that module's doc for
// the why and the state-trigger seam. The renderer's root carries the applying classes.
import { animClassName, compileAnimationsCss, kitAnimations } from "@/shared/ui/kit";
import { GRAPH_VIZ_KIT_ID, GRAPH_VIZ_ANIMATIONS } from "@/shared/ui/kit/graphVizAnimations";

// Re-export the shared data so this renderer's public surface (and the algorithms barrel) is unchanged.
export { GRAPH_VIZ_KIT_ID, GRAPH_VIZ_ANIMATIONS };

/** The applying classes the renderer's root carries so the state-scoped rules match its SVG elements. */
export const GRAPH_VIZ_ANIM_CLASSES: string = GRAPH_VIZ_ANIMATIONS.map((a) =>
  animClassName({ kit: GRAPH_VIZ_KIT_ID, name: a.name }),
).join(" ");

/** The compiled motion CSS — produced ONCE from {@link GRAPH_VIZ_ANIMATIONS}. Pure. */
export const GRAPH_VIZ_MOTION_CSS: string = compileAnimationsCss(
  kitAnimations([{ id: GRAPH_VIZ_KIT_ID, animations: GRAPH_VIZ_ANIMATIONS }]),
);

const STYLE_ID = "bsc-graph-viz-animations";

/** Inject the compiled graph motion CSS into a dedicated managed `<style>` (idempotent). `doc` param'd for
 *  tests. Mirrors `ensureArrayViewMotion` on its own style id. */
export function ensureGraphViewMotion(doc: Document = document): void {
  if (!GRAPH_VIZ_MOTION_CSS) return;
  let el = doc.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!el) {
    el = doc.createElement("style");
    el.id = STYLE_ID;
    doc.head.appendChild(el);
  }
  if (el.textContent !== GRAPH_VIZ_MOTION_CSS) el.textContent = GRAPH_VIZ_MOTION_CSS;
}

// The `graph-viz` kit's MOTION library as DATA (#3224/#3242, epic #3220/#2942) — the frontier / visit /
// relax animations authored as {@link KitAnimation} data, compiled by the kit-motion engine. SVG-safe
// properties only (stroke / stroke-width / opacity / transform), since GraphView draws nodes + edges as SVG.
//
// ── WHY THIS LIVES IN shared/ui/kit ──────────────────────────────────────────────────────────────────
// Same as the array (#3194) + matrix sets: two consumers in two features, one definition — the Algorithms
// GraphView renderer (`features/algorithms/.../graphViewMotion.ts`) and the Designs seed
// (`features/designs/lib/graphVizKit.ts` → `seed.ts`, which registers `graph-viz` as a recoverable builtin
// kit). Feature-agnostic viz-motion, so it lives HERE to avoid a designs↔algorithms seed cycle (#3242).
//
// STATE-TRIGGER SEAM (#3058): each selector IS the transient data-op GraphView stamps
// (`[data-op="visit"]`, …) — the DURABLE node states (visited / frontier / current) are static colours in
// graphView.css; these are the one-shot transitions into them.

import type { KitAnimation } from "@/shared/ui/kit/animations";

/** The graph-visualization motion kit id — `.graph-viz-anim-<name>` + `@keyframes bsc-graph-viz-<name>`. */
export const GRAPH_VIZ_KIT_ID = "graph-viz";

/** The graph kit's animations as DATA — frontier (a node ring pulse as it's discovered), visit (a pop as a
 *  node is finished), relax (an edge flash as it's traversed). SVG-safe; the engine wraps each in
 *  `prefers-reduced-motion: no-preference`. The single source of truth the GraphView renderer AND the
 *  Designs `graph-viz` builtin kit both consume. */
export const GRAPH_VIZ_ANIMATIONS: KitAnimation[] = [
  // frontier — the node's outline pulses as it enters the frontier.
  {
    name: "frontier",
    selector: '[data-op="frontier"]',
    duration: "480ms",
    easing: "var(--ease-standard)",
    keyframes: {
      "0%": { "stroke-width": "1.5" },
      "45%": { "stroke-width": "4.5", stroke: "var(--state-wait)" },
      "100%": { "stroke-width": "1.5" },
    },
  },
  // visit — the node pops as it's finished (transform-box: fill-box in the CSS keeps it centred).
  {
    name: "visit",
    selector: '[data-op="visit"]',
    duration: "420ms",
