];

/**
 * Group rows by a key and total a set of numeric fields — per group AND overall — in ONE pass.
 *
 * The back half of every "spend by X" / "usage by Y" rollup: you have a flat list of rows, each with
 * several numbers, and you want both the grand totals and the same totals broken down by some
 * secondary key. Written by hand it is three separate reductions plus a `Map` accumulator, and the
 * usual bug is the group subtotals and the grand total drifting apart because they were summed
 * independently — here they come from the same traversal, so they cannot disagree.
 *
 * The fields to sum are DATA: a record of named numeric accessors. Adding a tracked metric is adding
 * one entry, not editing three reducers. Every field is totalled at both levels; a caller wanting only
 * some grouped just reads the ones it needs.
 *
 * Group order is FIRST-SEEN (insertion order of the backing Map), so the result is deterministic for a
 * given input and a caller that wants a different order sorts the returned groups itself — this does
 * not bake a sort in, because "by first appearance" is the one order that needs no opinion.
 *
 * Harvested from the Fleet page's cost panel (#3462/#3465), where it rolls per-worker token usage up
 * to fleet totals and a by-model breakdown.
 */

/** The totals for one field set — the same keys as the `fields` record, each a summed number. */
export type FieldTotals<F extends string> = Record<F, number>;

/** One group: its key, how many rows fell into it, and the per-field totals for those rows. */
export interface Group<K, F extends string> {
  key: K;
  count: number;
  totals: FieldTotals<F>;
}

/** The rollup: the grand totals over every row, and the per-group breakdown (first-seen order). */
export interface GroupTotals<K, F extends string> {
  totals: FieldTotals<F>;
  count: number;
  groups: Array<Group<K, F>>;
}

/**
 * Total `fields` over `rows`, grouped by `keyOf`.
 *
 * @param rows   the flat input.
 * @param keyOf  the grouping key for a row (the secondary axis — e.g. model name).
 * @param fields named numeric accessors; each is summed at both the group and grand-total level.
 */
export function groupTotals<T, K, F extends string>(
  rows: readonly T[],
  keyOf: (row: T) => K,
  fields: Record<F, (row: T) => number>,
): GroupTotals<K, F> {
  const names = Object.keys(fields) as F[];
  const zero = (): FieldTotals<F> => Object.fromEntries(names.map((n) => [n, 0])) as FieldTotals<F>;

  const grand = zero();
  const groups = new Map<K, Group<K, F>>();

  for (const row of rows) {
    const key = keyOf(row);
    let group = groups.get(key);
    if (!group) {
      group = { key, count: 0, totals: zero() };
      groups.set(key, group);
    }
    group.count += 1;
    for (const name of names) {
      const v = fields[name](row);
      group.totals[name] += v;
      grand[name] += v;
    }
  }

  return { totals: grand, count: rows.length, groups: [...groups.values()] };
}

// hashString (#2256) — a tiny, stable, non-cryptographic content fingerprint. Used to detect when a
// confirmed planning stage's content has CHANGED since it was confirmed (so just that stage resets).
// Not for security — only for change detection — so a cheap 32-bit rolling hash (djb2 variant) is
// plenty. Deterministic across runs/processes for the same input, which is the whole contract: the
// store's write-through and the poll's reconcile must agree on the same string → same fingerprint.

/** A stable base36 fingerprint of `content` (empty string → a fixed sentinel). Same input ⇒ same
 *  output, in any process — so the confirm-time and revisit-time fingerprints compare equal. */
export function hashString(content: string): string {
  let h = 5381;
  for (let i = 0; i < content.length; i++) {
    // h * 33 + c, kept in 32-bit range so the result is process-independent.
    h = (Math.imul(h, 33) + content.charCodeAt(i)) | 0;
  }
  // >>> 0 → unsigned, so the base36 string has no leading '-'. Prefix with the length as a cheap
  // extra discriminator (collisions on the 32-bit hash still differ if the lengths do).
  return `${content.length.toString(36)}-${(h >>> 0).toString(36)}`;
}

// The glance sample-data hash (#2421) — the one home for the private copies glanceData.ts and
// glanceFleet.ts each carried, derived from the shared `hashString` (shared/lib/core/format.ts)
// instead of re-implementing the loop.
//
// NOT plain `hashString`: the glance copies truncated each step with `| 0` (signed) and took a
// final `Math.abs`, while `hashString` truncates with `>>> 0` (unsigned). The per-step low 32 bits
// track identically either way (the 2^32 offset vanishes mod 2^32 under `* 31 + c`), so the two
// differ only in the FINAL reduction: when the sign bit is set, `Math.abs(h | 0)` = 2^32 − hashString.
// Reinterpreting `hashString`'s result as signed and abs-ing it therefore reproduces the historical
// values EXACTLY — which matters because the sample role / worker-count / status assignments
// (`hashAbs(id) % n`) must stay stable for existing projects.
import { hashString } from "@/shared/lib/core/format";

/** Stable small hash of a string → non-negative int (deterministic sample role/status/count
 *  assignment). Same outputs as the former private `hash()` copies — see the header. */
export function hashAbs(s: string): number {
  return Math.abs(hashString(s) | 0);
}

/// Heap sort — build a max-heap in place, then swap the root to the end and re-sift the rest.
pub fn heap_sort<T: Ord + Clone>(xs: &[T]) -> Vec<T> {
    fn sift_down<T: Ord>(a: &mut [T], start: usize, end: usize) {
        let mut root = start;
        loop {
            let left = 2 * root + 1;
            if left > end {
                return;
            }
            let right = left + 1;
            let mut largest = root;
            if a[largest] < a[left] {
                largest = left;
            }
            if right <= end && a[largest] < a[right] {
                largest = right;
            }
            if largest == root {
                return;
            }
            a.swap(root, largest);
            root = largest;
        }
    }
    let mut out = xs.to_vec();
    let n = out.len();
    if n < 2 {
        return out;
    }
    for start in (0..n / 2).rev() {
        sift_down(&mut out, start, n - 1);
    }
    for end in (1..n).rev() {
        out.swap(0, end);
        sift_down(&mut out, 0, end - 1);
    }
    out
}

/** Hue of `--accent` (amber). Locked here so every tier stays orange. */
const ACCENT_HUE = 70;

/**
 * Maps a normalized activity value to a heatmap cell colour.
 *
 * Empty days (`v <= 0`) render as the elevated background so "no activity"
 * stays visually distinct from low activity — the same convention GitHub's
 * own calendar uses. Non-zero values ramp through a *single hue* (the accent's
 * orange), with lightness and chroma climbing as activity rises, so the cell
 * colour reads purely as intensity ("more vs. less").
 *
 * We compute the shade directly in OKLCH rather than `color-mix`-ing
 * `var(--accent)` into `var(--bg-elev)`: that background is a cool blue-grey
 * (hue ≈ 250°), and OKLCH mixing interpolates the *hue* channel, dragging the
 * lower tiers toward blue. Locking the hue to {@link ACCENT_HUE} keeps every
 * tier unmistakably orange. `v === 1` reproduces `var(--accent)` exactly
 * (`oklch(0.80 0.14 70)`).
 *
 * @param v - activity normalized to `[0, 1]` (the quartile level / 4). Values
 *            above 1 are clamped; zero and negatives render as the background.
 * @returns a CSS colour string suitable for an SVG `fill` or CSS `background`.
 */
export function heatFill(v: number): string {
  if (v <= 0) return "var(--bg-elev)";
  const t = Math.min(v, 1);
  const lightness = 0.3 + t * 0.5;  // 0.30 → 0.80 (--accent lightness)
  const chroma = 0.05 + t * 0.09;   // 0.05 → 0.14 (--accent chroma)
  return `oklch(${lightness.toFixed(3)} ${chroma.toFixed(3)} ${ACCENT_HUE})`;
}

