/**
 * Quartile (rank-based) intensity scaling for the activity heatmap.
 *
 * GitHub's contribution calendar colours each day by which quartile of the
 * distribution of *non-zero* days its count falls into — not by `count / max`.
 * This is what makes it robust to outliers: a single 400-commit day can't wash
 * out the scale, because intensity is rank-based, not magnitude-based. The
 * busier days spread across levels 1–4 regardless of how extreme the peak is.
 *
 * The four non-zero levels are returned as evenly-spaced positions on `[0, 1]`
 * (0.25 / 0.5 / 0.75 / 1) so they sample the cool→warm gradient that {@link
 * heatFill} renders — the calendar keeps its two-colour ramp while bucketing
 * intensity GitHub-style. Empty days return 0 and render as background.
 *
 * Trade-off (inherent to quartile bucketing): absolute magnitude is lost — a
 * 10-commit day and a 400-commit day can share the top bucket. Exact counts are
 * surfaced in the cell tooltip instead.
 *
 * @param counts - raw contribution count per day (any length; order preserved).
 * @returns one normalized intensity per input day, each in {0, .25, .5, .75, 1}.
 */
export function quartileScale(counts: number[]): number[] {
  const nonZero = counts.filter(c => c > 0).sort((a, b) => a - b);
  if (nonZero.length === 0) return counts.map(() => 0);

  const q1 = percentile(nonZero, 0.25);
  const q2 = percentile(nonZero, 0.5);
  const q3 = percentile(nonZero, 0.75);

  return counts.map(c => {
    if (c <= 0) return 0;
    // Level = 1 + (number of quartile thresholds the count exceeds), so the
    // busiest days (above the 75th percentile) reach level 4 / full warmth.
    let level = 1;
    if (c > q1) level++;
    if (c > q2) level++;
    if (c > q3) level++;
    return level / 4;
  });
}

/**
 * Linear-interpolation percentile (type-7, as used by NumPy/Excel) over an
 * ascending pre-sorted array.
 *
 * @param sorted - non-empty array sorted ascending.
 * @param p - quantile in `[0, 1]`.
 */
function percentile(sorted: number[], p: number): number {
  if (sorted.length === 1) return sorted[0];
  const idx = (sorted.length - 1) * p;
  const lo = Math.floor(idx);
  const hi = Math.ceil(idx);
  if (lo === hi) return sorted[lo];
  return sorted[lo] + (idx - lo) * (sorted[hi] - sorted[lo]);
}

// Shared store helpers used by index.ts (rehydrate) + the projects slice (launch actions).
// Extracted from store/index.ts during the store split (stage 2).
import type { AppStore } from "@/store/types";
import type { DocAssignments } from "@/shared/lib/session/assignments";
import type { AgentStream } from "@/features/planner/fleet/planFleet";
import { type IntegrationStrategy, DEFAULT_STRATEGY, strategySettings } from "@/features/planner/lib/integrationStrategy";
import { resolveFlow } from "@/features/planner/fleet/agentFlow";
import { flowKickoffText } from "@/features/planner/fleet/flowKickoff";
import { type Automation, suggestionToAutomation, computeNextRun } from "@/features/automations/lib/scheduler";

/** Mint a stable tab id (#463). Prefers crypto.randomUUID; falls back for older
 *  webviews. Used for every tab the store creates + backfilled on hydration. */
export function newTabId(): string {
  try {
    if (typeof crypto !== "undefined" && crypto.randomUUID) return `tab_${crypto.randomUUID()}`;
  } catch { /* fall through */ }
  return `tab_${Date.now()}_${Math.floor(Math.random() * 1e9).toString(36)}`;
}

/**
 * Grid geometry for an N-pane console tab (#2712): the `cols`/`rows` a fleet or triage tab uses to
 * lay out `count` sessions. Byte-identical to the formula both launch reducers used inline — 1 col
 * for ≤1, 2 for ≤4, 3 for ≤9, else 4; rows = ceil(count / cols). Callers derive `paneCount =
 * cols * rows` (a full grid may have empty trailing cells).
 */
export function gridLayout(count: number): { cols: number; rows: number } {
  const cols = count <= 1 ? 1 : count <= 2 ? 2 : count <= 4 ? 2 : count <= 9 ? 3 : 4;
  const rows = Math.ceil(count / cols);
  return { cols, rows };
}

/**
 * Lifts the store's flat startup-prompt assignment fields into the
 * {@link DocAssignments} cascade the resolution module (#324) consumes. The
 * per-repo map is keyed by `repoPromptKey`, which is byte-identical to the
 * module's `scopeKey`, so it drops straight in. The session level is unused at
 * launch (assignment happens at the project/repo level).
 */
export function buildAssignments(s: {
  defaultStartupPromptDoc: string | null;
  projectStartupPromptDoc: Record<string, string | null>;
  repoStartupPromptDoc: Record<string, string | null>;
}): DocAssignments {
  return {
    startupPrompt: {
      default: s.defaultStartupPromptDoc,
      project: s.projectStartupPromptDoc,
      repo: s.repoStartupPromptDoc,
      session: {},
    },
  };
}


// Fallback first message for a fleet worker whose stream has no planner-authored
// kickoff script. Plain text only (no double quotes / $ / backticks) so it is safe
// to pass as claude's initial-message arg. The worker's SCOPE (owned globs, issues,
// dependencies) lives in CLAUDE.local.md — NOT the full plan (#844): the worktree is
// outside the hub, so the worker loads only its lane; high-level context is the
// director's. This points the session at that scope file and the autonomy rules.
export function buildStreamPrompt(stream: AgentStream, strategy?: IntegrationStrategy): string {
  const owns   = stream.owns.length   ? stream.owns.join(", ")   : "the files for your area";
  const issues = stream.issues.length ? stream.issues.join(", ") : "the issues assigned to your area";
  const strat = strategy ?? DEFAULT_STRATEGY;
  const effPush = strategySettings(strat).integrate;
  const effFlow = { ...resolveFlow(stream.flow), push: stream.flow?.push ?? effPush };
  const kick = flowKickoffText(effFlow, stream.id);
  return (
    `You are the ${stream.name} work stream, one of several Claude sessions building this project in parallel. ` +
    `Your scope — the files and issues you own, and what you depend on — is in CLAUDE.local.md; read it first. ` +
    `You do not have the full project plan; for high-level context, defer to the director. ` +
    `You are working in your own git worktree on branch ${stream.id}; do not switch branches or touch other worktrees. ` +
    `Your lane: you own ${owns}. Do not modify files outside your owned paths — another session owns them; ` +
    `coordinate through the director instead. Your issues: ${issues}. ` +
    `Integration interfaces between features live in the contracts directory — read them as the source of truth, ` +
    `and if one is unclear or must change, ask the director rather than reaching into another stream. ` +
    `${kick.autonomy} ` +
    `${kick.push} ` +
    `When you pause or finish a work session, pipe a short note of where you left off and the next step into bsc-checkpoint on stdin so your next session resumes there. ` +
    `Verify your work against the repo tests and CI rather than asking whether it is correct.`
  );
}


// #174: promote a project's planning-assigned automations into the real scheduler on
// launch. Idempotent (skips ones already present by name+command); scheduled (cron)
// suggestions arm, on-demand ones are saved unarmed. Each fires into `targetTab`.
export function activateAutomations(s: AppStore, projectId: string, targetTab: string): Automation[] {
  const suggestions = projectId ? s.planAutomations[projectId] ?? [] : [];
  if (suggestions.length === 0) return [];
  const have = new Set(s.automations.map((a) => `${a.name}�${a.command ?? ""}`));
  const added: Automation[] = [];
  for (const sug of suggestions) {
    const k = `${sug.name}�${sug.command}`;
    if (have.has(k)) continue;
    have.add(k);
    const input = suggestionToAutomation(sug, targetTab);
    added.push({
      ...input,
      id: `auto_${Math.random().toString(36).slice(2, 8)}`,
      lastRunAt: null,
      nextRunAt: input.armed ? computeNextRun(input.when, Date.now()) : null,
      runs: [],
    });
  }
  return added;
}

// Hook catalog. HOOK_CATALOG is the first-party lifecycle-hook catalog the Hooks view browses.
// The live hook list + fire stats come from the store / backend at runtime — not from this file.

import type { CatalogItem } from "@/shared/data/mcpCatalog";
import hookCatalogEmbedded from "@data/mcp/hooks.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

// The catalog DATA is externalized to `@data/mcp/hooks.json` (#2146, epic #2027 tail) — editable
// without touching code + part of the exportable config bundle; the config-dir copy (#2047) overlays
// the embedded default via `overlayFile`.
export const HOOK_CATALOG: CatalogItem[] = overlayFile("mcp/hooks.json", hookCatalogEmbedded as CatalogItem[]);

// Hook-fire telemetry (#865 PR 2) — parse + aggregate the hook-fire log for the Hook
// Analytics tab. Mirrors skillTelemetry.ts. The log lives at ~/.base-studio-code/hooks.log,
// one TSV line per fire: `ts \t pane \t event \t hook \t outcome` (#1743 prepended the pane
// column). Legacy lines written before #1743 have no pane (`ts \t event \t hook \t outcome`)
// and are still tolerated — the parser detects the shape by column count. Read newest-first via
// `bsc logs tail hook`. `outcome` is "allow" | "block" (PreToolUse decisions) or "ok"
// (PostToolUse / non-gating events). Pure + unit-tested; the hook wrappers that EMIT these
// lines are wired separately (PR 3).

import { dayKey } from "@/shared/lib/core/format";

export type HookOutcome = "allow" | "block" | "ok";

export interface HookFire {
  /** epoch ms */
  ts: number;
  /** PreToolUse | PostToolUse | Stop | … */
  event: string;
  /** the hook's name */
  hook: string;
  outcome: HookOutcome;
}

/** Parse the TSV hook-fire log into records, skipping malformed lines. */
export function parseHookLog(text: string): HookFire[] {
  const out: HookFire[] = [];
  for (const line of text.split("\n")) {
    if (!line.trim()) continue;
    const parts = line.split("\t");
    // #1743: new lines carry a leading pane column (5 fields: ts·pane·event·hook·outcome); legacy
    // lines have none (4 fields: ts·event·hook·outcome). Detect by column count and offset the field
    // reads. The pane isn't surfaced here (the analytics don't break down by session), so it's read
    // past, not stored.
    const b = parts.length >= 5 ? 1 : 0;
    const [tsRaw, event, hook, outcomeRaw] = [parts[0], parts[b + 1], parts[b + 2], parts[b + 3]];
    const ts = Number(tsRaw);
    if (!Number.isFinite(ts) || !event || !hook) continue;
    const outcome: HookOutcome = outcomeRaw === "block" ? "block" : outcomeRaw === "allow" ? "allow" : "ok";
    out.push({ ts, event, hook, outcome });
  }
  return out;
}

export interface DayBucket { day: string; allows: number; blocks: number; }
export interface HookCount { hook: string; event: string; fires: number; }
export interface PreHookSplit { hook: string; allows: number; blocks: number; }

export interface HookAnalytics {
  /** total fires in the window */
  total: number;
  /** PreToolUse fires denied (outcome === "block") */
  blocks: number;
  /** PreToolUse fires allowed (outcome === "allow") */
  allows: number;
  /** allows / (allows + blocks), 0–100; 100 when no PreToolUse decisions */
  allowRate: number;
  /** per-day allow (allow + ok) vs block counts, oldest→newest, length === days */
  daily: DayBucket[];
  /** fires per hook, descending */
  perHook: HookCount[];
  /** PreToolUse hooks only: allows vs blocks, descending by total */
  perPreHook: PreHookSplit[];
}

const DAY_MS = 86_400_000;

/**
 * Aggregate hook fires into the analytics the Hook Analytics tab renders. Only fires within
 * the last `days` (relative to `now`) are counted. `daily` always has exactly `days` buckets
 * (zero-filled), oldest→newest, so the chart has a stable x-axis.
 */
export function aggregateHookTelemetry(fires: HookFire[], now: Date, days = 14): HookAnalytics {
  const end = now.getTime();
  const start = end - days * DAY_MS;
  const inWindow = fires.filter((f) => f.ts >= start && f.ts <= end);

  // Stable daily buckets (oldest→newest), keyed by local day.
  const daily: DayBucket[] = [];
  const idxByDay = new Map<string, number>();
  for (let i = days - 1; i >= 0; i--) {
    const key = dayKey(end - i * DAY_MS);
    idxByDay.set(key, daily.length);
    daily.push({ day: key, allows: 0, blocks: 0 });
  }

  let blocks = 0;
  let allows = 0;
  const perHookMap = new Map<string, HookCount>();
  const perPreMap = new Map<string, PreHookSplit>();

  for (const f of inWindow) {
    if (f.outcome === "block") blocks++;
    else if (f.outcome === "allow") allows++;

    const bucket = idxByDay.get(dayKey(f.ts));
    if (bucket != null) {
      if (f.outcome === "block") daily[bucket].blocks++;
      else daily[bucket].allows++;
    }

    const hk = perHookMap.get(f.hook) ?? { hook: f.hook, event: f.event, fires: 0 };
    hk.fires++;
    perHookMap.set(f.hook, hk);

    if (f.event === "PreToolUse") {
      const ph = perPreMap.get(f.hook) ?? { hook: f.hook, allows: 0, blocks: 0 };
      if (f.outcome === "block") ph.blocks++;
      else ph.allows++;
      perPreMap.set(f.hook, ph);
    }
  }

  const perHook = [...perHookMap.values()].sort((a, b) => b.fires - a.fires);
  const perPreHook = [...perPreMap.values()].sort((a, b) => (b.allows + b.blocks) - (a.allows + a.blocks));
  const decided = allows + blocks;

  return {
    total: inWindow.length,
    blocks,
    allows,
    allowRate: decided > 0 ? Math.round((allows / decided) * 100) : 100,
    daily,
    perHook,
    perPreHook,
  };
}

// Hook model + per-session resolution + `.claude/settings.json` payload + catalog templates.
//
// A hook is a shell command Claude Code runs on a lifecycle event (PreToolUse, PostToolUse,
// Stop, …), optionally gated by a tool matcher. Pure (no React / Tauri) so it's shared by the
// store, the Hooks view, and TerminalView. Split out of the former unified `extensions.ts`.

/** A user-configured lifecycle hook. Scoped per-hook via {@link Hook.projects}. */
export interface Hook {
  id: string;
  name: string;
  enabled: boolean;
  /** `[]` = every project (global); otherwise the project ids it applies to. */
  projects: string[];
  event: string;       // PreToolUse | PostToolUse | Stop | …
  matcher?: string;    // optional tool matcher (regex)
  command: string;     // the shell command to run
  env?: Array<[string, string]>;
}

/**
 * The enabled hooks that apply to a session in `projectId`: a hook applies when it is enabled
 * AND either global (`projects` empty) or scoped to this project. An empty `projectId`
 * (no project) yields only global hooks.
 */
export function resolveHooks(all: Hook[], projectId: string): Hook[] {
  return all.filter(
    e => e.enabled && (e.projects.length === 0 || (!!projectId && e.projects.includes(projectId))),
  );
}

// ── Backend payload ───────────────────────────────────────────────────────────

export interface HookPayload {
  event: string;
  matcher: string;
  command: string;
}

/** POSIX single-quote escape: wrap in '…', and turn any embedded ' into '\''. Robust +
 *  portable (no base64) so the wrapper command can't be broken or injected by the name/cmd. */
function shQuote(s: string): string {
  return `'${s.replace(/'/g, "'\\''")}'`;
}

/**
 * A hook → its settings.json payload, or null if incomplete.
 *
 * The user's command is wrapped with `bsc-hook '<name>' '<command>'` (#867 follow-up) so each
 * fire is logged to `~/.base-studio-code/hooks.log` for the Hook Analytics tab — `bsc-hook`
 * runs the command, records the outcome (PreToolUse block/allow), and propagates the exit
 * code. Only USER hooks pass through here; the security hooks are injected backend-side and
 * are never wrapped.
 */
export function toHookPayload(e: Hook): HookPayload | null {
  if (!e.event || !e.command) return null;
  const command = `bsc-hook ${shQuote(e.name || "hook")} ${shQuote(e.command)}`;
  return { event: e.event, matcher: e.matcher ?? "", command };
}

// ── Catalog templates ─────────────────────────────────────────────────────────

const HOOK_CATALOG_TEMPLATES: Record<string, Partial<Hook>> = {
  "Block PII":   { event: "PreToolUse",  matcher: "Write|Edit", command: "" },
  "Auto-format": { event: "PostToolUse", matcher: "Write|Edit", command: "" },
  // A `Stop` hook fires when the agent finishes its turn — no tool matcher applies (it's not a
  // tool event), so it's left unset. The command is the user's to fill in (notify / snapshot / …).
  "Session end": { event: "Stop", command: "" },
};

/** A ready-to-add hook (minus id) for a catalog entry — disabled + global by default. */
export function hookFromCatalog(name: string): Omit<Hook, "id"> {
  const t = HOOK_CATALOG_TEMPLATES[name] ?? { event: "PostToolUse", matcher: "", command: "" };
  return {
    name,
    enabled: false,
    projects: [],
    event: t.event ?? "PostToolUse",
    matcher: t.matcher,
    command: t.command ?? "",
  };
}

/** A blank custom hook, ready for the add-custom form. */
export function blankHook(): Omit<Hook, "id"> {
  return { name: "", enabled: false, projects: [], event: "PostToolUse", matcher: "", command: "" };
}

// ── System hooks (the always-on floor) ──────────────────────────────────────────

/** A read-only descriptor for an always-on system hook the app injects. VIEW-only — not editable. */
export interface SystemHook {
  name: string;
  event: string;
  /** One-line description of what this hook enforces. */
  purpose: string;
}

/**
 * The always-on PreToolUse security floor (#1916/#2050) the app injects into EVERY session
 * backend-side (`console/shell_rc`). Unlike user hooks these are never wrapped by `bsc-hook`, are
 * not toggleable or removable, and fire AND block under BOTH permission postures — the default
 * allow-list AND bypass, where `permissions.deny` is ignored but PreToolUse hooks still block. They
 * are the real running floor beneath any user hook, so the Hooks view lists them (VIEW-only —
 * these describe what runs; the user can't change them here). Kept in sync with the `bsc-*` rc
 * helpers' contract (`bsc-deny`/`bsc-confine`/`bsc-scope` in `src-tauri/src/console/shell_rc`).
 */
export const SYSTEM_HOOKS: SystemHook[] = [
  { name: "bsc-deny",    event: "PreToolUse", purpose: "Dangerous-command floor + role/user command denies — blocks the mutating git/gh and destructive commands a session's role can't run." },
  { name: "bsc-confine", event: "PreToolUse", purpose: "Filesystem confinement — blocks file-tool reads/writes that leave the session's repo root or touch its own .claude config." },
  { name: "bsc-scope",   event: "PreToolUse", purpose: "Write-scope — blocks file writes outside a worker's owned globs (and denies all writes for code:none roles)." },
];

// html / react-bundle renderer (#581 PV-registry + PV-stream).
//
// Phase 1 (PV-registry): wraps the current srcDoc-swap path — same behavior as
// PlanPreviewPane/PreviewFrame, but routed through the registry. The iframe DOM node
// is persistent; srcdoc is set imperatively (no React re-render on update).
//
// Phase 2 (PV-stream): streaming-capable path kicks in when the payload carries
// `bundleJs` instead of (or in addition to) `srcDoc`. The iframe stays mounted and
// receives chunks via postMessage to a thin resident runtime, enabling zero-reload
// incremental updates. See streamingRuntime.ts for the in-frame protocol.
//
// Payload shapes:
//   { srcDoc: string }                         — full HTML srcdoc (current producer)
//   { bundleJs: string, importmap?: Record }   — streaming path (future producer)

import type { PreviewRenderer, RendererHandle } from '@/features/planner/preview/registry';
import type { RenderableChunk, PreviewStatus } from '@/features/planner/preview/types';
import { buildStreamingFrameHtml } from '@/features/planner/preview/streamingRuntime';
import { DEFAULT_IMPORTMAP } from '@/features/planner/preview/previewBundle';

type HtmlPayload =
  | { srcDoc: string; bundleJs?: never }
  | { bundleJs: string; importmap?: Record<string, string>; srcDoc?: never };

function applyHtmlPayload(
  iframe: HTMLIFrameElement,
  streamingReady: boolean,
  payload: HtmlPayload,
): void {
  if (payload.bundleJs != null) {
    // Streaming path: post bundle to resident runtime (no srcdoc swap, no reload).
    iframe.contentWindow?.postMessage(
      { __preview_cmd: 'render_bundle', bundleJs: payload.bundleJs, importmap: payload.importmap ?? DEFAULT_IMPORTMAP },
      '*',
    );
  } else if (payload.srcDoc != null) {
    if (streamingReady) {
      // Runtime is live — deliver as full-document replace inside the frame.
      iframe.contentWindow?.postMessage(
        { __preview_cmd: 'render_srcdoc', html: payload.srcDoc },
        '*',
      );
    } else {
      // Fallback: direct srcdoc assignment (same as legacy PreviewFrame behavior).
      iframe.srcdoc = payload.srcDoc;
    }
  }
}

function createHtmlRenderer(): PreviewRenderer {
  return {
    kind: ['react-bundle', 'html'],

    mount(container: HTMLElement, initial: RenderableChunk): RendererHandle {
      const iframe = document.createElement('iframe');
      iframe.title = 'UI preview';
      iframe.setAttribute('sandbox', 'allow-scripts');
      iframe.style.cssText = 'flex:1;width:100%;height:100%;border:none;background:var(--bg-canvas,#0d0d0f)';
      container.style.cssText = 'display:flex;flex:1;min-height:0';
      container.appendChild(iframe);

      let statusCb: ((s: PreviewStatus) => void) | undefined;
      let streamingReady = false;
      // Queue a chunk delivered before the runtime has signalled ready.
      let pendingChunk: RenderableChunk | null = null;

      const payload = initial.payload as HtmlPayload;
      const useStreaming = payload.bundleJs != null;

      if (useStreaming) {
        // Bootstrap the persistent streaming runtime.
        iframe.srcdoc = buildStreamingFrameHtml(payload.importmap ?? DEFAULT_IMPORTMAP);
        pendingChunk = initial; // apply once runtime_ready arrives
      } else if (payload.srcDoc != null) {
        iframe.srcdoc = payload.srcDoc;
      }

      function onMsg(e: MessageEvent) {
        const d = e.data as { __preview?: string; message?: unknown } | null;
        if (!d || typeof d !== 'object') return;
        if (d.__preview === 'runtime_ready') {
          streamingReady = true;
          if (pendingChunk) {
            applyHtmlPayload(iframe, true, pendingChunk.payload as HtmlPayload);
            pendingChunk = null;
          }
        } else if (d.__preview === 'ready') {
          statusCb?.({ status: 'ready' });
        } else if (d.__preview === 'error') {
          statusCb?.({ status: 'error', message: String(d.message ?? '') });
        }
      }
      window.addEventListener('message', onMsg);

      const handle: RendererHandle = {
        update(chunk: RenderableChunk) {
          const p = chunk.payload as HtmlPayload;
          if (!streamingReady && p.bundleJs != null) {
            pendingChunk = chunk;
          } else {
            applyHtmlPayload(iframe, streamingReady, p);
          }
        },
        onStatus(cb) { statusCb = cb; },
        teardown() {
          window.removeEventListener('message', onMsg);
          if (container.contains(iframe)) container.removeChild(iframe);
        },
      };
      return handle;
    },
  };
}

export const htmlRenderer = createHtmlRenderer();

// Human presence (#4248) — is somebody at the keyboard right now?
//
// ## Why this exists
// #3599 stopped a designer follow-along from stealing the user's page, and drew the line at EXPLICIT vs
// BACKGROUND: an explicit `--workspace`/`--page` was treated as a deliberate steer and honoured. That
// line does not separate the two cases, because an agent's background loop IS MADE OF EXPLICIT COMMANDS.
// Measured in `audit.log`, the designer issued `bsc navigate component …` (correctly declined off-Studio)
// followed immediately by `bsc navigate page designs` — every ~7 seconds, for the whole run.
//
// The distinction that actually matters is **who is driving**. Steering the view is right when the app is
// running unattended (the overnight loop, #3260/#3263 — the case the steering was built for) and wrong
// when a person is using it. Nothing in the bridge knew which it was.
//
// ## Why a module ref, not store state
// Every real input event would write the store, and anything subscribed would re-render on it — a
// per-keystroke commit for a value no UI displays. #4170 was exactly that shape (a store write in a
// publish path, feeding back into a render loop), so this stays a module-local timestamp: no subscribers,
// no commits, and reading it cannot participate in a render cycle.
//
// It is deliberately NOT "is the window focused". A session can be capturing while the user reads a
// terminal in the same window, and a focused-but-idle window overnight would block the loop forever.
// Recent INPUT is the honest signal for "someone is working right now".

/** How long after an input event a human still counts as present.
 *
 *  Long enough to cover reading and thinking between actions — a person scanning a page is still using
 *  it — and short enough that a machine left alone becomes unattended within one loop iteration. The
 *  designer loop fires roughly every 7s, so anything under ~10s would let it steal the view between two
 *  keystrokes, which is the complaint. */
export const PRESENT_WINDOW_MS = 45_000;

/** Wall-clock ms of the last real user input. `0` = none seen since load, i.e. unattended. */
let lastInputAt = 0;

/** The events that count as a person acting. Pointer/key/wheel only — NOT `mousemove`, which fires from
 *  incidental cursor drift and from some automation, and would report presence for a room nobody is in. */
const INPUT_EVENTS = ["pointerdown", "keydown", "wheel"] as const;

/** Record that a human just did something. Exported for tests and for any surface that knows about an
 *  interaction the DOM listeners cannot see. */
export function noteHumanActivity(at: number = Date.now()): void {
  if (at > lastInputAt) lastInputAt = at;
}

/** Is a human present right now? */
export function humanPresent(now: number = Date.now(), windowMs: number = PRESENT_WINDOW_MS): boolean {
  return lastInputAt > 0 && now - lastInputAt < windowMs;
}

/** Ms since the last input, or `null` when none has been seen. For the decline message — "nobody has
 *  touched this in 4 minutes" is checkable, "declined" alone is not. */
export function msSinceHumanActivity(now: number = Date.now()): number | null {
  return lastInputAt > 0 ? now - lastInputAt : null;
}

/** Test-only reset. */
export function __resetHumanPresence(): void {
  lastInputAt = 0;
}

/** Install the listeners. Called once by the shell. Returns a disposer.
 *
 *  `capture: true` + `passive: true`: capture so an event consumed by a component (a key handled by the
 *  terminal, say) is still SEEN — those are the most certain evidence of a person — and passive so this
 *  can never delay input handling. */
export function installHumanPresence(target: EventTarget = window): () => void {
  const on = () => noteHumanActivity();
  for (const e of INPUT_EVENTS) target.addEventListener(e, on, { capture: true, passive: true });
  return () => {
    for (const e of INPUT_EVENTS) target.removeEventListener(e, on, { capture: true });
  };
}

// Idle session reaping (#849) — decide which background console PTYs to reap to bound
// memory when many projects accumulate hidden `claude` processes. PURE decision: given a
// snapshot of live panes + the reaper config + the clock, return the pane ids to reap. The
// hook (useIdleReaper) does the side effects (pty_kill + mark dormant); the store renders a
// dormant placeholder and resumes on focus. Framework-free + unit-tested.
//
// Reaping is non-destructive: a worktree/cwd persists on disk and the pane resumes via the
// existing relaunch path, so a reaped session is recoverable, not lost.

import type { SessionRole } from "@/shared/lib/session/sessionRoles";

/** A live pane the reaper evaluates. */
export interface ReaperPane {
  paneId: string;
  /** Live PTY status: "run" = mid-turn (never reaped), "idle"/"on" = at rest. */
  status: "run" | "on" | "idle";
  role: SessionRole;
  /** Epoch ms of this pane's last activity (last status change / output). */
  lastActivityMs: number;
  /** The pane the user is currently watching — never reaped. */
  focused: boolean;
  /** Already dormant (reaped) — skip; nothing to reap twice. */
  dormant: boolean;
  /** DECLARED maintenance (#4025): this worker emitted `bsc-maintain` — everything it owns is done
   *  and it is standing by for the director to dispatch into. Distinct from ordinary idling, which is
   *  why it gets its own rule below rather than a shorter `workerIdleMs`. */
  maintaining?: boolean;
}

export interface ReaperConfig {
  /** Master switch. */
  enabled: boolean;
  /** Idle threshold (ms) for reapable project/planner sessions. */
  idleMs: number;
  /** Idle threshold (ms) for workers + the director — conservative. `null` ⇒ never reap
   *  them (the default), since they idle legitimately (parked on a dep / the director). */
  workerIdleMs: number | null;
  /** Idle threshold (ms) for the app-owned STUDIO sessions (designer/librarian/architect, #3357).
   *  A studio session deliberately outlives the page that opened it — it stays warm on TerminalHost
   *  so its Glance node can morph into it — so this is how long it may sit with NO surface showing
   *  it before being reclaimed. Separate from `idleMs` because the trigger is different: the studio
   *  reaper counts *unwatched* time (viewer count 0), not time since last output.
   *  OPTIONAL for back-compat: a config persisted before #3357 has no such key, and zustand's
   *  persist replaces the whole object rather than merging, so readers MUST fall back to
   *  {@link DEFAULT_STUDIO_IDLE_MS} rather than trusting it to be present. */
  studioIdleMs?: number;
}

/** Default idle grace before an unwatched studio session is reclaimed (#3357). Also the fallback
 *  for a `ReaperConfig` persisted before the key existed. */
export const DEFAULT_STUDIO_IDLE_MS = 30 * 60 * 1000;

/** The effective studio idle threshold for a config, tolerating a pre-#3357 persisted object. */
export function studioIdleMs(cfg: ReaperConfig): number {
  return cfg.studioIdleMs ?? DEFAULT_STUDIO_IDLE_MS;
}

/** Roles handled conservatively: they idle legitimately mid-fleet, so they're reaped only
 *  under the separate (longer / opt-in) `workerIdleMs`, never the project threshold. */
const CONSERVATIVE_ROLES: ReadonlySet<SessionRole> = new Set<SessionRole>(["worker", "director"]);

/** The idle threshold that applies to a pane by role, or `null` when its role is never
 *  reaped under the current config. */
export function thresholdFor(role: SessionRole, cfg: ReaperConfig): number | null {
  return CONSERVATIVE_ROLES.has(role) ? cfg.workerIdleMs : cfg.idleMs;
}

/** Whether a single pane is reapable right now. Exposed for focused unit tests. */
export function isReapable(pane: ReaperPane, cfg: ReaperConfig, nowMs: number): boolean {
  if (!cfg.enabled) return false;
  if (pane.dormant) return false;       // already reaped
  if (pane.focused) return false;       // the user is watching it
  if (pane.status === "run") return false; // mid-turn — never interrupt active work
  // DECLARED MAINTENANCE (#4025) — reaped IMMEDIATELY, with no threshold.
  //
  // `workerIdleMs` is null by default because a worker "idles legitimately (parked on a dep / the
  // director)" — you cannot tell that apart from a worker that is done, so the safe answer was to reap
  // neither. Maintenance removes the ambiguity: the worker has SAID everything it owns is complete and
  // it is standing by. That is the one idle state where the PTY holds nothing worth keeping — measured
  // at ~413 MB per parked `claude.exe`, 13.7 GB across 34 of them.
  //
  // Deliberately NOT expressed as a shorter `workerIdleMs`: that would also reap a worker parked on a
  // real question, which is exactly the case the null default protects. And no grace period — a
  // dispatch relaunches with the assignment baked in (`actuateWake`), so a reaped maintainer is
  // reachable, which is what makes immediate reaping free rather than a trade.
  if (pane.maintaining) return true;
  const threshold = thresholdFor(pane.role, cfg);
  if (threshold === null) return false; // this role is never reaped under the config
  return nowMs - pane.lastActivityMs >= threshold;
}

/**
 * The pane ids to reap from a snapshot. Selects only idle, non-focused, non-dormant panes
 * whose idle time exceeds the threshold for their role. A `run` (mid-turn) pane, the focused
 * pane, and — by default — workers/director are never selected.
 */
export function panesToReap(panes: readonly ReaperPane[], cfg: ReaperConfig, nowMs: number): string[] {
  return panes.filter((p) => isReapable(p, cfg, nowMs)).map((p) => p.paneId);
}

/** Sensible conservative defaults: on, 30 min for project sessions, workers/director never
 *  reaped (opt-in). Surfaced in Settings; persisted. */
export const DEFAULT_REAPER_CONFIG: ReaperConfig = {
  enabled: true,
  idleMs: 30 * 60 * 1000,
  workerIdleMs: null,
  studioIdleMs: DEFAULT_STUDIO_IDLE_MS,
};

// Idle scheduling (#graph-health-stops-blocking-first-paint) — run work AFTER the browser has painted,
// for derivations the user cannot see yet.
//
// The case this was written for: the Design Studio computed its graph-health findings in a `useMemo` on
// the render path, so ~121ms of analysis over 459 components ran BEFORE a single node reached the screen —
// twice per open. The findings drive corner badges and a toolbar count, and nothing about the graph's
// structure, layout or interactivity depends on them. Paint first; decorate after.
//
// WHY A TIMEOUT IS NOT OPTIONAL. `requestIdleCallback` with no deadline can be starved indefinitely on a
// busy main thread — which is exactly the condition a graph page is in while it mounts, so the work most
// worth deferring is also the work most likely never to run. The timeout converts "when convenient" into
// "soon, and at the latest by then".

/** How long idle work may wait before it runs regardless. Long enough to clear a first paint, short
 *  enough that a badge never feels missing. */
export const IDLE_TIMEOUT_MS = 200;

interface IdleWindow {
  requestIdleCallback?: (cb: () => void, opts?: { timeout: number }) => number;
  cancelIdleCallback?: (handle: number) => void;
}

/**
 * Run `fn` once the main thread is idle (or after `timeoutMs`, whichever comes first). Returns a CANCEL
 * function — call it from an effect cleanup so a superseded computation never lands after its inputs
 * changed.
 *
 * Falls back to `setTimeout` where `requestIdleCallback` is absent (jsdom, Safari historically, an
 * embedded shell). The fallback is deliberately not a no-op: the work still has to happen, it just loses
 * the "wait for a genuinely quiet moment" refinement. Degrading to "never computed" would trade a
 * performance win for a missing feature.
 */
export function runWhenIdle(fn: () => void, timeoutMs: number = IDLE_TIMEOUT_MS): () => void {
  const w = globalThis as unknown as IdleWindow;
  if (typeof w.requestIdleCallback === "function") {
    const handle = w.requestIdleCallback(fn, { timeout: timeoutMs });
    return () => w.cancelIdleCallback?.(handle);
  }
  const t = setTimeout(fn, timeoutMs);
  return () => clearTimeout(t);
}

import { fnv1a32hex } from "@/features/planner/lib/plannerCore/hash";

/**
 * Stable project identifier from a sanitized project name.
 * Format: "proj-{8 hex chars}" — deterministic, collision-resistant for typical
 * project-name spaces, and stable across renames only if the name doesn't change.
 * Stored in plan.json on first access so the id survives future title edits.
 */
export function projectId(sanitizedTitle: string): string {
  return `proj-${fnv1a32hex(sanitizedTitle)}`;
}

/**
 * Stable phase identifier from a phase name.
 * Format: "pid-{8 hex chars}". Used by the merge engine to key phase records.
 */
export function phaseId(phaseName: string): string {
  return `pid-${fnv1a32hex(phaseName)}`;
}

/**
 * Stable issue identifier — the canonical `id` field for the merge engine.
 * Maps directly from the desktop's `PlanIssue.ref` with no transformation:
 * the ref IS the stable id (the planner assigns it; it doesn't change).
 *
 * Parity point: the issue id field is "id" in the canonical model; desktop
 * calls it "ref". The bridge renames at the serialization boundary.
 */
export function issueId(ref: string): string {
  return ref;
}

/**
 * Stable PlanNode identifier for the adaptive planning tree (#201).
 * Format: "{kind}-{8 hex chars of title}". Deterministic across sessions so
 * the merge engine can key tree nodes stably.
 */
export function nodeId(kind: string, title: string): string {
  return `${kind}-${fnv1a32hex(title)}`;
}

// Shared module-path resolution for the in-browser previews (#3246 — consolidated from three copies:
// designs/lib/graphHealth, designs/lib/componentPreview, and shared/lib/preview/componentBundle).
// Pure string helpers — no DOM, no esbuild.

/** Collapse empty/`.`/`..` segments of a split module path (`..` pops the parent), joining with `/`. Pure. */
export function collapseSegments(segs: string[]): string {
  const out: string[] = [];
  for (const seg of segs) {
    if (seg === "" || seg === ".") continue;
    if (seg === "..") out.pop();
    else out.push(seg);
  }
  return out.join("/");
}

/** Resolve an INTERNAL import `spec` — imported FROM module `fromRel` (a `src/`-relative path) — to its
 *  `src/`-relative module BASE (no extension), or `null` when it isn't internal. `@/x` → `x`; a relative
 *  path is joined onto the importer's dir and `.`/`..` segments collapsed. Rust twin: `resolve_internal_base`. */
export function resolveInternalBase(spec: string, fromRel: string): string | null {
  let segs: string[];
  if (spec.startsWith("@/")) {
    segs = spec.slice(2).split("/");
  } else if (spec.startsWith("./") || spec.startsWith("../")) {
    const fromDir = fromRel.includes("/") ? fromRel.slice(0, fromRel.lastIndexOf("/")) : "";
    segs = (fromDir ? fromDir.split("/") : []).concat(spec.split("/"));
  } else {
    return null;
  }
  return collapseSegments(segs);
}

