// Prompt-injection detector (#1107). A pure, deterministic scan for the high-signal markers of an
// injected/hijacking instruction — the kind a poisoned repo or web page tries to smuggle through the
// planner into the fleet's trusted kickoffs. Used two ways:
//
//   1. The planner provenance gate (#1107): scan planner-authored artifacts (section files,
//      kickoffs, profiles) BEFORE they seed a worker, and surface flags to the user at the existing
//      confirmation boundary. A flag is human-reviewed, not auto-rejected — the planner's output
//      legitimately contains instructions, so the goal is to catch the *malicious* ones.
//   2. Shared detectors for the #1102 fleet warden, which can run the same `scanText` over what a
//      worker reads/writes.
//
// Deterministic + no LLM on purpose: the scan can't itself be prompt-injected. Patterns are tuned
// for HIGH SIGNAL (override phrasing, secret exfiltration, permission/safety bypass) over recall —
// false positives are a quick user dismissal; missed injections are a fleet compromise, but a noisy
// scan gets ignored, so the bar is "rarely appears in a legitimate plan".

/** A category of injection marker — drives how a finding is explained and grouped. */
export type InjectionCategory =
  | "override"      // "ignore previous instructions", role/identity hijack
  | "exfiltration"  // send secrets/env or repo contents to an external destination
  | "perms"         // skip/disable permissions, sandbox, or safety checks
  | "destructive"   // force-push, delete repo, self-merge, rm -rf
  | "ci";           // disable/bypass CI, workflows, or git hooks

export interface InjectionFinding {
  /** The artifact the marker was found in (e.g. `prompts/auth-kickoff.md`). */
  file: string;
  /** 1-based line number of the match. */
  line: number;
  category: InjectionCategory;
  /** Human label for the category. */
  label: string;
  /** The matched substring, trimmed for display. */
  match: string;
  /** The whole line (trimmed/clamped), so the user sees the marker in context. */
  context: string;
}

interface Pattern { category: InjectionCategory; label: string; re: RegExp }

// Each pattern targets a marker that is hostile in any plan deliverable and rare in legitimate ones.
// Verbs are required (not bare nouns) so that *describing* a subsystem ("the CI pipeline", "stores a
// token") doesn't trip — only *instructing* a hostile action does.
const PATTERNS: Pattern[] = [
  // Classic prompt-injection override / identity hijack. A legitimate plan never instructs this.
  { category: "override", label: "instruction-override phrasing",
    re: /\b(ignore|disregard|forget|override)\b[^.\n]{0,40}\b(previous|prior|above|earlier|all|the)?\s*(instructions?|directions?|rules?|prompts?|protocol|guardrails?|system\s*prompt)\b/i },
  { category: "override", label: "role / identity hijack",
    re: /(\byou are now\b|\bact as (an?\s+)?(unrestricted|jailbro|root|admin)|new\s+instructions\s*:|from now on[, ]+(ignore|disregard|you)|^\s*system\s*:\s*)/im },

  // Secret / environment / repo-content exfiltration. Each noun carries its own boundary so the
  // dot-prefixed forms (`.env`) match; `[^\n]` keeps it on one line but tolerates dots between.
  { category: "exfiltration", label: "secret or environment exfiltration",
    re: /\b(send|post|upload|exfiltrate|transmit|leak|curl|wget|fetch)\b[^\n]{0,60}(\benv(ironment)?\b|\bsecrets?\b|\btokens?\b|\bcredentials?\b|\bapi[\s_-]?keys?\b|\bpasswords?\b|\.env\b|\bprintenv\b)/i },
  { category: "exfiltration", label: "post data to an external destination",
    re: /\b(send|post|upload|exfiltrate|transmit|curl|wget)\b[^\n]{0,60}https?:\/\//i },

  // Permission / safety / sandbox bypass.
  { category: "perms", label: "permission or safety bypass",
    re: /(--dangerously[\w-]*|\bskip[\s-]?permissions?\b|\bdisable\b[^.\n]{0,30}\b(security|safety|sandbox|guard|protection|check|review|audit)\b|\bsudo\s|\bchmod\s+777\b|\bbypass\b[^.\n]{0,30}\b(security|permission|guard|sandbox|gate)\b)/i },

  // Destructive or out-of-lane git / GitHub operations.
  { category: "destructive", label: "destructive or out-of-lane git/GitHub op",
    re: /(git\s+push\s+(-f\b|--force)|\bforce[\s-]?push\b|gh\s+repo\s+delete\b|\brm\s+-rf\s+[/~]|git\s+push\b[^.\n]{0,40}\b(main|master)\b)/i },

  // CI / workflow / git-hook tampering — hostile verbs only (authoring a workflow is fine).
  { category: "ci", label: "CI/CD or git-hook tampering",
    re: /\b(disable|skip|bypass|turn\s+off|remove|delete)\b[^.\n]{0,30}(\.github\/workflows|\.git\/hooks|ci\/cd|\bci\b|pipeline|pre-?commit|\bhooks?\b|workflow)\b/i },
];

/** Scan one text blob for injection markers — first match per line per pattern. Pure. */
export function scanText(text: string): Omit<InjectionFinding, "file">[] {
  const out: Omit<InjectionFinding, "file">[] = [];
  const lines = (text ?? "").split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    for (const p of PATTERNS) {
      const m = p.re.exec(line);
      if (m) {
        out.push({
          line: i + 1,
          category: p.category,
          label: p.label,
          match: m[0].trim().slice(0, 120),
          context: line.trim().slice(0, 200),
        });
      }
    }
  }
  return out;
}

/** Scan a set of named artifacts (file → content). Pure; the planner gate's entry point. */
export function scanArtifacts(artifacts: Record<string, string>): InjectionFinding[] {
  const findings: InjectionFinding[] = [];
  for (const [file, content] of Object.entries(artifacts)) {
    for (const f of scanText(content)) findings.push({ file, ...f });
  }
  return findings;
}

/// Insertion sort — grow a sorted prefix, shifting larger elements right to open a slot.
pub fn insertion_sort<T: Ord + Clone>(xs: &[T]) -> Vec<T> {
    let mut out = xs.to_vec();
    for i in 1..out.len() {
        let mut j = i;
        while j > 0 && out[j - 1] > out[j] {
            out.swap(j - 1, j);
            j -= 1;
        }
    }
    out
}

// Integration gap detection (#1200) — scan the forming plan for the integrations it implies
// (MCP servers and the credentials a declared source needs), and classify each as
// already wired (`assigned`), one-click resolvable (`available`), or needing setup (`missing`).
// The native source-connector keyword rules were removed (#1976): connectors are agent-authored as
// runtime presets, so the plan no longer implies a fixed built-in connector to declare.
// Pure (no React/Tauri) so the detect+classify logic is unit-testable; the focused pane renders the
// result and offers the in-session add path. Heuristic + idempotent — re-running over the same plan
// yields the same set, and an integration already in play never re-appears as a gap.

import type { McpServer } from "@/features/mcp";
import { resolveMcpServers, mcpFromCatalog } from "@/features/mcp";
import { connector, type DeclaredSource } from "@/features/planner/lib/sourceConfig";

export type IntegrationKind = "mcp" | "connector" | "credential";
export type IntegrationStatus = "assigned" | "available" | "missing";
/** The single in-session affordance that resolves a gap. Absent ⇒ already assigned (nothing to do). */
export type IntegrationAction = "assign" | "declare" | "install" | "credential";

export interface ImpliedIntegration {
  /** Stable de-dupe key, e.g. `mcp:Stripe` / `connector:salesforce` / `credential:<uid>`. */
  key: string;
  kind: IntegrationKind;
  /** Server name | connector id | source uid — what the action operates on. */
  ref: string;
  label: string;
  /** Why the plan implies it (the matched signal), for the surfaced explanation. */
  reason: string;
  status: IntegrationStatus;
  detail: string;
  action?: IntegrationAction;
}

export interface IntegrationGapInput {
  /** Joined plan section text to scan (stack / features / architecture / …). */
  text: string;
  /** Declared sources from the project's source config. */
  sources: DeclaredSource[];
  /** The global MCP server list (scoped per-project via `projects`). */
  mcpServers: McpServer[];
  projectId: string;
}

export interface IntegrationGaps {
  items: ImpliedIntegration[];
  total: number;
  assigned: number;
  available: number;
  missing: number;
  /** Every implied integration is wired — nothing is `available`/`missing`. */
  ready: boolean;
}

interface Rule {
  re: RegExp;
  ref: string;
  label: string;
  reason: string;
}

// Stack/feature keywords → the MCP server they imply. Each `ref` is a catalog template name so the
// match is one-click resolvable (see `mcpFromCatalog`).
const MCP_RULES: Rule[] = [
  { re: /\bpostgres(ql)?\b/i, ref: "Postgres", label: "Postgres MCP", reason: "the stack uses PostgreSQL" },
  { re: /\bsqlite\b/i, ref: "SQLite", label: "SQLite MCP", reason: "the stack uses SQLite" },
  { re: /\b(stripe|billing|payments?|subscriptions?)\b/i, ref: "Stripe", label: "Stripe MCP", reason: "the plan involves billing/payments" },
  { re: /\bslack\b/i, ref: "Slack", label: "Slack MCP", reason: "the plan integrates Slack" },
  { re: /\b(sentry|error[ -]tracking)\b/i, ref: "Sentry", label: "Sentry MCP", reason: "the plan uses Sentry" },
  { re: /\blinear\b/i, ref: "Linear", label: "Linear MCP", reason: "the plan uses Linear" },
  { re: /\bnotion\b/i, ref: "Notion", label: "Notion MCP", reason: "the plan uses Notion" },
  { re: /\b(compliance|gdpr|hipaa|soc ?2|iso ?27001|pci( dss)?)\b/i, ref: "Compliance", label: "Compliance MCP", reason: "the plan has regulatory/compliance requirements" },
  { re: /\b(arxiv|pubmed|semantic scholar|scientific literature)\b/i, ref: "Research", label: "Research MCP", reason: "the plan needs scientific-literature research" },
];

/** Is this MCP server name something the app can resolve to a runnable config in one click? */
function mcpResolvable(name: string): boolean {
  const d = mcpFromCatalog(name);
  return !!(d.command || d.url);
}

/** A source is connected (secret saved to the keychain) once it is scanning or scanned. */
function connected(s: DeclaredSource): boolean {
  return s.status === "scanning" || s.status === "scanned";
}

/** Detect + classify the integrations the forming plan implies. */
export function integrationGaps(input: IntegrationGapInput): IntegrationGaps {
  const { text, sources, mcpServers, projectId } = input;
  const items: ImpliedIntegration[] = [];
  const seen = new Set<string>();
  const push = (it: ImpliedIntegration) => {
    if (!seen.has(it.key)) {
      seen.add(it.key);
      items.push(it);
    }
  };

  // 1. MCP servers — keyword matches in the plan text + every server the plan actually ASSIGNED
  // (recorded with `bsc plan mcp add`, resolved into the store by the plan.db poll — no longer a tag).
  const mcpNeeds = new Map<string, { label: string; reason: string }>();
  for (const r of MCP_RULES) {
    if (r.re.test(text)) mcpNeeds.set(r.ref, { label: r.label, reason: r.reason });
  }
  const scoped = resolveMcpServers(mcpServers, projectId);
  for (const s of scoped) {
    if (!mcpNeeds.has(s.name)) mcpNeeds.set(s.name, { label: s.name, reason: "the plan assigns this server" });
  }
  for (const [name, { label, reason }] of mcpNeeds) {
    const isAssigned = scoped.some((s) => s.name.toLowerCase() === name.toLowerCase());
    const resolvable = mcpResolvable(name);
    const status: IntegrationStatus = isAssigned ? "assigned" : resolvable ? "available" : "missing";
    push({
      key: `mcp:${name}`,
      kind: "mcp",
      ref: name,
      label,
      reason,
      status,
      detail: isAssigned ? "assigned to this project" : resolvable ? "one-click assign" : "add a custom MCP server in the MCP stage",
      action: isAssigned ? undefined : resolvable ? "assign" : "install",
    });
  }

  // 2. Credentials — a declared source that needs a secret it doesn't have yet (installed-but-
  //    unconfigured counts as missing, per the acceptance criteria).
  for (const s of sources) {
    const spec = connector(s.connectorId).spec;
    const needsSecret = spec.fields.some((f) => f.secret) || ["token", "password", "basic", "apiKey"].includes(spec.auth);
    if (needsSecret && !s.secretSaved && !connected(s)) {
      const name = connector(s.connectorId).name;
      push({
        key: `credential:${s.uid}`,
        kind: "credential",
        ref: s.uid,
        label: `${name} credential`,
        reason: `${name} is declared but not yet authorized`,
        status: "missing",
        detail: "enter the credential in the Source stage (stored on-device)",
        action: "credential",
      });
    }
  }

  const assigned = items.filter((i) => i.status === "assigned").length;
  const available = items.filter((i) => i.status === "available").length;
  const missing = items.filter((i) => i.status === "missing").length;
  return { items, total: items.length, assigned, available, missing, ready: available + missing === 0 };
}

import type { FlowPush } from "@/features/planner/fleet/agentFlow";

/** Fleet integration strategy (#378): a named preset that selects how workers integrate
 *  and how the director behaves. Chosen at the fleet level (project default) and
 *  overridable per stream. */
export type IntegrationStrategy = "local" | "self-merge" | "pr-ci" | "manual";
export type DirectorMode = "watchdog" | "integrator";
export type WorkerTest = "full" | "owned" | "none";

export const INTEGRATION_STRATEGIES: IntegrationStrategy[] = ["local", "self-merge", "pr-ci", "manual"];

/** `local` — the worker gates, commits on its branch and STOPS; the integration stream merges
 *  locally and nothing ever reaches a remote.
 *
 *  This is the default because the two prior candidates both wrote to a remote and neither said so
 *  at this layer: `self-merge` (the old default) pushes develop directly, and `pr-ci` pushes a
 *  branch and opens a PR. A project that has not chosen a strategy has not consented to either. */
export const DEFAULT_STRATEGY: IntegrationStrategy = "local";

export interface StrategySettings {
  /** What the worker runs before integrating. */
  test: WorkerTest;
  /** The worker push policy this strategy maps onto (a FlowPush value). */
  integrate: FlowPush;
  /** How the director behaves under this strategy. */
  director: DirectorMode;
}

export const STRATEGY_SETTINGS: Record<IntegrationStrategy, StrategySettings> = {
  // `local` keeps the integrator director on purpose: SOMETHING has to merge, and under this
  // strategy that is the integration stream, not the worker. A watchdog director (which only
  // watches develop's CI and reverts) would leave every completed branch unmerged forever.
  "local":      { test: "full", integrate: "local",       director: "integrator" },
  "self-merge": { test: "full", integrate: "self-merge",  director: "watchdog" },
  "pr-ci":      { test: "full", integrate: "auto-pr",     director: "integrator" },
  "manual":     { test: "full", integrate: "commit-only", director: "integrator" },
};

/** Coerce arbitrary input to a valid strategy or undefined. */
export function normalizeStrategy(v: unknown): IntegrationStrategy | undefined {
  if (typeof v !== "string") return undefined;
  const t = v.trim();
  return (INTEGRATION_STRATEGIES as string[]).includes(t) ? (t as IntegrationStrategy) : undefined;
}

/** Resolve the effective strategy for a stream: per-stream override, else fleet default, else DEFAULT_STRATEGY. */
export function resolveStrategy(
  streamStrategy: IntegrationStrategy | undefined,
  fleetStrategy: IntegrationStrategy | undefined,
): IntegrationStrategy {
  return streamStrategy ?? fleetStrategy ?? DEFAULT_STRATEGY;
}

export function strategySettings(s: IntegrationStrategy): StrategySettings {
  return STRATEGY_SETTINGS[s];
}

// Invoke round-trip timing (#3626) — surfaces WHICH backend command is slow when the app feels laggy
// but the frontend `[perf]` line is clean (the signature of backend saturation delaying invokes; see
// [[perf-lag-diagnosis]]/[[fleet-gc-split-brain]]). Every `safeInvoke`/`fireInvoke`/`bsc` round-trip is
// timed; a call slower than `SLOW_INVOKE_MS` gets a `[invoke] <label> Nms` warn line in the app log's
// `perf` scope — the same file sink `log.warn(msg, "perf")` reaches.
//
// It writes STRAIGHT to `frontend_log` (not via `log`) on purpose: `log.ts` imports `safeInvoke`, so
// routing back through `log` would form a `safeInvoke ↔ log` import cycle in the lowest-level invoke
// path. Talking to the sink directly keeps that path cycle-free. The pure `slowInvokeLine` carries the
// threshold + format so it can be unit-tested with no Tauri/`log` dependency.

import { invoke } from "@tauri-apps/api/core";

/** A round-trip at/over this many ms is logged. 100ms ≈ "this call visibly stalled the caller". */
export const SLOW_INVOKE_MS = 100;

/** Commands never timed: the logging subsystem's own invokes. `frontend_log` is our sink (would be
 *  self-referential) and `log_get_scopes` is polled by `log.ts` — excluding both keeps the signal about
 *  app work, not about logging. Keyed by the real Tauri command, so `bsc …` labels are unaffected. */
const EXCLUDED = new Set(["frontend_log", "log_get_scopes"]);

/**
 * The `[invoke] <label> Nms` line for a call that took `ms`, or `null` when it's under threshold or the
 * `command` is excluded. Pure (no I/O) so the threshold/format is unit-testable.
 * @param label human-readable call label (the Tauri command, or `bsc <sub> <verb>` for the bsc bridge)
 * @param ms measured round-trip in milliseconds
 * @param command the real Tauri command, checked against the exclusion set (defaults to `label`)
 */
export function slowInvokeLine(label: string, ms: number, command: string = label): string | null {
  if (EXCLUDED.has(command)) return null;
  if (ms < SLOW_INVOKE_MS) return null;
  return `[invoke] ${label} ${Math.round(ms)}ms`;
}

/**
 * Start a round-trip timer; call the returned `stop()` in a `finally` so both fulfilled and rejected
 * invokes are measured. Emits a `[invoke]` warn line to the app-log `perf` scope when the call ran
 * `>= SLOW_INVOKE_MS`. Fire-and-forget — the sink write never blocks or throws into the caller.
 * @param label human-readable call label
 * @param command the real Tauri command for the exclusion check (defaults to `label`)
 */
export function startInvokeTimer(label: string, command: string = label): () => void {
  const t0 = performance.now();
  return () => {
    const line = slowInvokeLine(label, performance.now() - t0, command);
    if (line) void invoke("frontend_log", { level: "warn", scope: "perf", message: line }).catch(() => {});
  };
}

/** The `bsc <sub> <verb>` label for a bsc-bridge call — the first two args identify the subcommand,
 *  without logging (potentially large) positional/JSON payloads. */
export function bscLabel(args: string[]): string {
  const head = args.slice(0, 2).join(" ").trim();
  return head ? `bsc ${head}` : "bsc";
}

// Issue provenance (#738) — security hardening for the untrusted-issue channel.
//
// GitHub issues are an untrusted input: a hand-created or injected issue could be picked up
// by an agent (the triage session runs `gh issue list` over EVERY open issue) and acted on.
// base-studio-code marks the issues IT publishes with a distinctive label; agents that pull
// live issues restrict to that label BY DEFAULT, so an issue the app didn't author is ignored.
//
// Caveat: a label is forgeable by anyone with repo write access — this stops accidental /
// hand-created pickup and raises the bar, but is not a cryptographic guarantee. For that,
// track the issue numbers the app created (a follow-up).

/** The label base-studio-code stamps on every issue it publishes. */
export const BSC_ISSUE_LABEL = "bsc-generated";

/** GitHub label color (hex, no #) for the provenance label. */
export const BSC_ISSUE_LABEL_COLOR = "1f6feb";

/** Add the provenance label to a plan issue's labels (idempotent). */
export function withProvenanceLabel(labels: string[]): string[] {
  return labels.includes(BSC_ISSUE_LABEL) ? labels : [...labels, BSC_ISSUE_LABEL];
}

/** The `gh issue list` selector triage uses — restricted to bsc-authored issues by default. */
export function triageIssueListArgs(restrictToBsc: boolean): string {
  return restrictToBsc
    ? `--state open --label ${BSC_ISSUE_LABEL} --limit 100`
    : `--state open --limit 100`;
}

// The GitHub overlay for a fleet's owned issue refs (#4102) — pure query construction + parsing.
//
// ── ONE CALL PER REPO, NOT ONE PER ISSUE ────────────────────────────────────────────────────────
// A drilled fleet owns ~60 refs. Asking GitHub for each one is 60 requests to render one graph — the
// N-per-node fan-out that has repeatedly cost this app real time (#3908/#3912/#3944/#3954), and the
// exact shape #4102 promises not to reintroduce. GraphQL takes aliased field selections, so every ref
// in a repo is resolvable in ONE query:
//
//   query { r0: repository(owner:"o", name:"n") { i3898: issue(number:3898) { number state } … } }
//
// ── WHY NOT `GET /issues?state=all` ─────────────────────────────────────────────────────────────
// It is paginated and returns PULL REQUESTS alongside issues (REST models a PR as an issue), so a
// fleet ref matching a PR number would report the wrong state. Asking for the exact numbers cannot
// make that mistake.
//
// Pure: no fetch, no store. The hook owns the lifecycle; this owns the contract.

import { normalizeRef } from "@/features/glance/lib/fleetPlanProgress";

/** `owner/name`, as a fleet stream stores it. */
export interface RepoRefs {
  repo: string;
  /** Normalised issue numbers owned in this repo. */
  numbers: string[];
}

/** Group refs by their owning repo, so each repo becomes one query. Refs are normalised and
 *  de-duplicated — two streams in a repo commonly own overlapping work, and asking twice wastes the
 *  budget this batching exists to protect. Streams with no repo or no refs are skipped. */
export function groupRefsByRepo(
  streams: readonly { repo?: string; issues?: readonly string[] }[],
): RepoRefs[] {
  const byRepo = new Map<string, Set<string>>();
  for (const s of streams) {
    const repo = s.repo?.trim();
    if (!repo || !repo.includes("/")) continue;
    for (const ref of s.issues ?? []) {
      const n = normalizeRef(ref);
      // Only numeric refs are addressable as `issue(number:)`. A cross-repo ref like `owner/x#5` or a
      // free-text placeholder is dropped rather than sent as a malformed query that fails the whole
      // batch — one bad ref must not blank out every other stream's progress.
      if (!/^\d+$/.test(n)) continue;
      let set = byRepo.get(repo);
      if (!set) byRepo.set(repo, (set = new Set()));
      set.add(n);
    }
  }
  return [...byRepo].map(([repo, numbers]) => ({ repo, numbers: [...numbers].sort() }));
}

/** GraphQL aliases must match `/^[_A-Za-z][_0-9A-Za-z]*$/`, so both levels are prefixed rather than
 *  interpolated raw — an alias starting with a digit is a syntax error that fails the whole query. */
const repoAlias = (i: number) => `r${i}`;
const issueAlias = (n: string) => `i${n}`;

/**
 * Build one query covering every repo/ref pair.
 *
 * Returns `null` when there is nothing to ask — the caller must not spend a request (nor show a
 * spinner) for a fleet that owns no addressable refs.
 *
 * Owner/name are split and embedded as quoted literals. They come from the fleet plan rather than
 * user input, but they are still validated as GitHub name characters so a malformed repo string
 * cannot inject query text.
 */
export function buildIssueStateQuery(groups: readonly RepoRefs[]): string | null {
  const parts: string[] = [];
  groups.forEach((g, i) => {
    const [owner, name] = g.repo.split("/");
    if (!owner || !name || !/^[\w.-]+$/.test(owner) || !/^[\w.-]+$/.test(name)) return;
    if (g.numbers.length === 0) return;
    const fields = g.numbers.map((n) => `${issueAlias(n)}: issue(number: ${n}) { number state }`).join(" ");
    parts.push(`${repoAlias(i)}: repository(owner: "${owner}", name: "${name}") { ${fields} }`);
  });
  return parts.length ? `query { ${parts.join(" ")} }` : null;
}

/** One issue as the overlay knows it. */
export interface IssueState {
  ref: string;
  closed: boolean;
}

/**
 * Parse the aliased response into `ref → closed`.
 *
 * Tolerant by construction: GitHub returns `null` for an alias whose issue does not exist (a stale
 * ref, or one belonging to a repo the token cannot see) and sends partial `data` ALONGSIDE `errors`
 * rather than failing the batch. Skipping the nulls means one dead ref costs its own state and
 * nothing else's — which matters because these refs are hand-maintained in the plan.
 */
export function parseIssueStates(data: unknown): Map<string, boolean> {
  const out = new Map<string, boolean>();
  if (!data || typeof data !== "object") return out;
  for (const repo of Object.values(data as Record<string, unknown>)) {
    if (!repo || typeof repo !== "object") continue;
    for (const issue of Object.values(repo as Record<string, unknown>)) {
      if (!issue || typeof issue !== "object") continue;
      const { number, state } = issue as { number?: unknown; state?: unknown };
      if (typeof number !== "number" || typeof state !== "string") continue;
      out.set(normalizeRef(number), state.toUpperCase() === "CLOSED");
    }
  }
  return out;
}

/** The refs the overlay reports as DONE — the set `fleetPlanProgress` consumes. */
export function closedRefs(states: ReadonlyMap<string, boolean>): Set<string> {
  const out = new Set<string>();
  for (const [ref, closed] of states) if (closed) out.add(ref);
  return out;
}

import { parseProjectV2Items, statusFieldValue, type ProjectV2Node } from "@/shared/lib/github/projectV2";
import type { GhLabel } from "@/shared/lib/github/types";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface GhUser  { login: string }

export interface FlatIssue {
  id: string;
  number: number;
  title: string;
  body: string;
  state: "OPEN" | "CLOSED";
  updatedAt: string;
  labels: GhLabel[];
  assignees: GhUser[];
  comments: number;
  milestone: string | null;
  statusName: string | null;   // project Status field value
}

export type StateFilter  = "all" | "open" | "closed";
export type SortKey      = "newest" | "oldest" | "number" | "comments";

export interface Filters {
  search: string;
  state: StateFilter;
  label: string;
  milestone: string;
  sort: SortKey;
}

// ── GraphQL query ─────────────────────────────────────────────────────────────

export const ISSUES_QUERY = `
query($id: ID!) {
  node(id: $id) {
    ... on ProjectV2 {
      items(first: 100) {
        nodes {
          id
          fieldValues(first: 10) {
            nodes {
              ... on ProjectV2ItemFieldSingleSelectValue {
                name
                field { ... on ProjectV2FieldCommon { name } }
              }
            }
          }
          content {
            __typename
            ... on Issue {
              number title body state updatedAt
              labels(first: 5)    { nodes { name color } }
              assignees(first: 3) { nodes { login } }
              comments            { totalCount }
              milestone           { title }
            }
          }
        }
      }
    }
  }
}`;

// ── Derivations ───────────────────────────────────────────────────────────────

export function parseIssues(node: ProjectV2Node | undefined): FlatIssue[] {
  return parseProjectV2Items<{
    number: number; title: string; body: string;
    state: "OPEN" | "CLOSED"; updatedAt: string;
    labels: { nodes: GhLabel[] };
    assignees: { nodes: GhUser[] };
    comments: { totalCount: number };
    milestone?: { title: string } | null;
  }, FlatIssue>(node, (c, item) => ({
    id: item.id,
    number: c.number,
    title: c.title,
    body: c.body ?? "",
    state: c.state,
    updatedAt: c.updatedAt,
    labels: c.labels.nodes,
    assignees: c.assignees.nodes,
    comments: c.comments.totalCount,
    milestone: c.milestone?.title ?? null,
    statusName: statusFieldValue(item)?.name ?? null,
  }));
}

export function deriveLabels(issues: FlatIssue[]): string[] {
  return [...new Set(issues.flatMap(i => i.labels.map(l => l.name)))].sort();
}

export function deriveMilestones(issues: FlatIssue[]): string[] {
  return [...new Set(issues.map(i => i.milestone).filter((m): m is string => m !== null))].sort();
}

export function applyFilters(issues: FlatIssue[], filters: Filters): FlatIssue[] {
  let list = issues;
  if (filters.state !== "all") {
    list = list.filter(i => i.state === (filters.state === "open" ? "OPEN" : "CLOSED"));
  }
  if (filters.search) {
    const q = filters.search.toLowerCase();
    list = list.filter(i =>
      i.title.toLowerCase().includes(q) ||
      String(i.number).includes(q) ||
      i.labels.some(l => l.name.toLowerCase().includes(q))
    );
  }
  if (filters.label) {
    list = list.filter(i => i.labels.some(l => l.name === filters.label));
  }
  if (filters.milestone) {
    list = list.filter(i => i.milestone === filters.milestone);
  }
  switch (filters.sort) {
    case "newest":   return [...list].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
    case "oldest":   return [...list].sort((a, b) => a.updatedAt.localeCompare(b.updatedAt));
    case "number":   return [...list].sort((a, b) => b.number - a.number);
    case "comments": return [...list].sort((a, b) => b.comments - a.comments);
    default:         return list;
  }
}

// JSX outline (#4169, epic #3604) — reduce a `.tsx` source to the TREE OF ELEMENTS it renders, so the
// graph copy of a page and the file copy can be compared structurally rather than byte-for-byte.
//
// WHY NOT a byte diff: the graph copy of a page is a transcription of the file with deliberate rewrites —
// a generated header comment, the CSS side-effect import stripped, barrel re-exports dropped, sibling
// specifiers rewritten to `@/components/<id>` (see `scripts/gen-*-graph.cjs`). Those differ by design, so a
// text diff is all noise. What must NOT differ is the SKELETON: the elements the page renders and how they
// nest. That is the "N nodes differ" signal #4169 asks shadow mode to report.
//
// WHY NOT a real parser: the loader's compile step is esbuild-wasm (browser-only), and shadow mode has to
// run everywhere the report is wanted — including a node test. This scanner is a lexical approximation: it
// walks the source skipping comments, strings and template literals, and records every JSX element it
// opens. It is deliberately NOT exact.
//
// The approximation is SOUND for the one job it has, because the comparison is SYMMETRIC: both sides are
// scanned by this same function, and the graph copy is a transcription of the file copy. A quirk (a
// generic arrow read as a tag, JSX inside a template literal missed) lands identically on both sides and
// cancels in the diff. What survives is real drift — an element added to the file and never carried to the
// graph node, which is exactly the migration risk this reports on.

/** One JSX element in the outline: its tag and the elements nested inside it. */
export interface OutlineNode {
  tag: string;
  children: OutlineNode[];
}

/** A JSX tag name: components (`Foo`, `Foo.Bar`), intrinsics (`div`), namespaced (`svg:use`). */
const TAG = /^[A-Za-z_$][A-Za-z0-9_$.:-]*/;

/** Token positions where a `<` at brace depth 0 can legitimately open JSX (`return <div/>`, `? <a/> : <b/>`,
 *  `{cond && <Row/>}`, `=> <Card/>`, an argument, an array element). Anything else — most importantly an
 *  identifier, as in `a < b` or `useState<Foo>(` — is NOT JSX. Only consulted OUTSIDE a JSX element; inside
 *  one, children context makes `<` unambiguous. */
const JSX_START_CONTEXT = /(^|[({[,;:=?&|!+*}>]|\b(?:return|default|case|typeof|await|yield|in|of|as)\s*)\s*$/;

/** Scan `source` and return the ROOT JSX elements it renders, each with its nested children. */
export function outlineJsx(source: string): OutlineNode[] {
  const roots: OutlineNode[] = [];
  const stack: OutlineNode[] = [];
  let i = 0;

  const push = (node: OutlineNode): void => {
    (stack.length ? stack[stack.length - 1].children : roots).push(node);
  };

  while (i < source.length) {
    const c = source[i];

    // — skip the regions a `<` inside cannot be JSX we care about —
    if (c === "/" && source[i + 1] === "/") {
      i = lineEnd(source, i);
      continue;
    }
    if (c === "/" && source[i + 1] === "*") {
      const end = source.indexOf("*/", i + 2);
      i = end < 0 ? source.length : end + 2;
      continue;
    }
    if (c === '"' || c === "'") {
      i = skipQuoted(source, i, c);
      continue;
    }
    if (c === "`") {
      i = skipTemplate(source, i);
      continue;
    }

    if (c !== "<") {
      i++;
      continue;
    }

    // — a `<`: closing tag, fragment, or an opening element —
    if (source[i + 1] === "/") {
      const gt = source.indexOf(">", i);
      if (gt < 0) break;
      if (stack.length) stack.pop();
      i = gt + 1;
      continue;
    }
    if (source[i + 1] === ">") {
      // `<>` — a fragment. Counted as a node: dropping one changes the tree the same way any wrapper does.
      const node: OutlineNode = { tag: "Fragment", children: [] };
      push(node);
      stack.push(node);
      i += 2;
      continue;
    }

    const name = TAG.exec(source.slice(i + 1))?.[0];
    // Outside a JSX element the `<` must sit where an expression can start, or it is a comparison / a type
    // argument. Inside one we are in children position, where `<` always opens an element.
    // A 32-char look-back window, not `slice(0, i)`: the pattern is anchored at its end, so only the tail
    // can match — and re-slicing the whole prefix at every `<` makes a 30k-char page quadratic.
    if (!name || (stack.length === 0 && !JSX_START_CONTEXT.test(source.slice(Math.max(0, i - 32), i)))) {
      i++;
      continue;
    }

    const tagEnd = findTagEnd(source, i + 1 + name.length);
    if (tagEnd.close < 0) break;
    const node: OutlineNode = { tag: name, children: [] };
    push(node);
    // Attribute expressions can render JSX of their own (`renderRow={(r) => <Row … />}`), and drift hides
    // there as readily as in children — so the attribute region is scanned too, and what it renders is
    // attached as children of the element that holds it.
    for (const child of outlineJsx(source.slice(i + 1 + name.length, tagEnd.close))) node.children.push(child);
    if (!tagEnd.selfClosing) stack.push(node);
    i = tagEnd.close + 1;
  }

  return roots;
}

/** Flatten an outline to one path per element (`Screen>TabBar>Chip`), depth-first. Compared as a MULTISET
 *  by [`diffOutlines`], so a repeated element counts once per occurrence and no sibling index is needed. */
export function outlinePaths(roots: OutlineNode[], prefix = ""): string[] {
  const paths: string[] = [];
  for (const node of roots) {
    const path = prefix ? `${prefix}>${node.tag}` : node.tag;
    paths.push(path);
    paths.push(...outlinePaths(node.children, path));
  }
  return paths;
}

/** Total elements in an outline — the denominator for "N of M nodes differ". */
export function countNodes(roots: OutlineNode[]): number {
  return roots.reduce((n, node) => n + 1 + countNodes(node.children), 0);
}

// ————— lexical skips —————

function lineEnd(src: string, from: number): number {
  const nl = src.indexOf("\n", from);
  return nl < 0 ? src.length : nl + 1;
}

/** Past the closing quote of a `'`/`"` literal opened at `from` (escapes respected; an unterminated
 *  literal — which a lexical scan can produce from an apostrophe in a comment it mis-skipped — stops at
 *  the newline rather than swallowing the rest of the file). */
function skipQuoted(src: string, from: number, quote: string): number {
  for (let i = from + 1; i < src.length; i++) {
    if (src[i] === "\\") i++;
    else if (src[i] === quote) return i + 1;
    else if (src[i] === "\n") return i + 1;
  }
  return src.length;
}

/** Past the closing backtick of a template literal — INCLUDING its `${…}` holes. JSX inside a template
 *  hole is not something this codebase writes, and skipping the whole literal keeps the scanner simple. */
function skipTemplate(src: string, from: number): number {
  let depth = 0;
  for (let i = from + 1; i < src.length; i++) {
    const c = src[i];
    if (c === "\\") i++;
    else if (c === "$" && src[i + 1] === "{") { depth++; i++; }
    else if (c === "}" && depth > 0) depth--;
    else if (c === "`" && depth === 0) return i + 1;
  }
  return src.length;
}

/** The `>` closing an opening tag, skipping attribute strings and `{…}` expression braces.
 *  `close` is the index of that `>` (−1 if unterminated); `selfClosing` reports a `/>`. */
function findTagEnd(src: string, from: number): { close: number; selfClosing: boolean } {
  let depth = 0;
  for (let i = from; i < src.length; i++) {
    const c = src[i];
    if (c === '"' || c === "'") { i = skipQuoted(src, i, c) - 1; continue; }
    if (c === "`") { i = skipTemplate(src, i) - 1; continue; }
    if (c === "{") { depth++; continue; }
    if (c === "}") { depth = Math.max(0, depth - 1); continue; }
    if (c === ">" && depth === 0) {
      return { close: i, selfClosing: /\/\s*$/.test(src.slice(from, i)) };
    }
  }
  return { close: -1, selfClosing: false };
}

// Jumble detection for the Claude CLI's TUI (#1250). Pure so the verdict is unit-testable from
// plain row strings — no xterm in jsdom. The caller (TerminalView) samples the bottom input-box
// rows of a *Claude CLI* session at each settle, runs this, and nudges (requestPaneRedraw, #1221)
// when the chrome is shattered. ONLY for the Claude CLI — an API / bsc-agent session renders its
// own UI, not this box chrome, so the caller must gate on the provider before sampling.

export type JumbleVerdict = "healthy" | "malformed" | "unknown";

// Horizontal box-drawing runs (incl. heavy / double / dashed) make up the input box's top + bottom
// borders — the structure we check for integrity.
const HORIZ = "─━═┄┅┈┉╌╍";
// Any box-drawing character — tells us TUI chrome is present at all (vs. plain output).
const BOX = /[─━═┄┅┈┉╌╍╭╮╰╯┌┐└┘╔╗╚╝│┃║┆┇┊┋]/;

/** Longest contiguous run of horizontal box-drawing characters in a row. */
function longestHorizRun(row: string): number {
  let best = 0;
  let cur = 0;
  for (const ch of row) {
    if (HORIZ.includes(ch)) {
      cur += 1;
      if (cur > best) best = cur;
    } else {
      cur = 0;
    }
  }
  return best;
}

/**
 * Classify the sampled chrome rows of a Claude CLI TUI (the bottom input-box region) as a `healthy`
 * render, a `malformed` (jumbled) one, or `unknown` when there's no chrome to judge.
 *
 * Heuristic: the Claude input box draws a full-width horizontal border (top + bottom). A clean
 * render has at least one long, unbroken run of horizontal box characters; a jumbled redraw
 * overwrites/shifts those cells, shattering the run. So:
 *   - no box-drawing characters at all   → `unknown` (plain output; can't tell — don't nudge)
 *   - box chars present + a long border   → `healthy`
 *   - box chars present but no long border → `malformed`
 *
 * Conservative by design: it only flags `malformed` when chrome IS present but broken, never on
 * ordinary text. The caller applies hysteresis (re-check before firing) to ride out a lone
 * mid-draw frame.
 */
export function probeJumble(rows: string[], cols: number): JumbleVerdict {
  if (cols <= 0 || rows.length === 0) return "unknown";
  if (!rows.some((r) => BOX.test(r))) return "unknown";
  // A healthy border spans most of the width; require half the columns (min 8 for a narrow pane).
  const healthyRun = Math.max(8, Math.floor(cols * 0.5));
  const longest = rows.reduce((m, r) => Math.max(m, longestHorizRun(r)), 0);
  return longest >= healthyRun ? "healthy" : "malformed";
}

// Rebindable keyboard shortcuts (#771, follow-up to #487).
//
// A "chord" is a normalized string: the active modifiers in a fixed order
// followed by the main key's `KeyboardEvent.code`, joined with "+", e.g.
// "Ctrl+Shift+KeyC", "Alt+Shift+Enter", "Ctrl+Shift+Backspace". Using `code`
// (physical key) rather than `key` keeps a binding stable across Shift/locale,
// matching how useHotkeys already discriminates (`e.code === "KeyC"`).
//
// Only the single-chord console actions are rebindable; the digit-family / range
// bindings (screen F-keys, Ctrl+1–9, Alt+1–5, zoom, …) are parameterized by a
// digit, not a single chord, so they stay fixed. Pure data + functions (no React
// / DOM types beyond the structural event shape) so this is unit-testable.

import { SHORTCUT_GROUPS } from "@/features/settings/lib/shortcuts";

/** The shortcut ids that can be rebound (single modifier+key chords). Screen
 *  navigation (single F-keys) and terminal zoom (single Ctrl chords) are single
 *  chords too, so they use this same mechanism. The digit-RANGE bindings
 *  (Ctrl+1–9 etc.) are a separate "leader" model — see LEADER_IDS below.
 *
 *  A `screen-*` id MUST be `screen-${Workspace}` for a workspace in SCREEN_HOTKEYS:
 *  `useHotkeys` looks its binding up by that derived key, so a Workspace rename that
 *  misses this list silently kills the F-key (#2702 renamed `agents` → `security` and
 *  left `screen-agents` here, so F7 matched nothing at all). The
 *  `screen-nav ids track SCREEN_HOTKEYS` test pins the two together. */
export const REBINDABLE_IDS = [
  "broadcast-toggle",
  "fullscreen-toggle",
  "focus-next-waiting",
  "clear-input",
  "redraw-pane",
  "send-all-enter",
  "page-prev",
  "page-next",
  "screen-glance",
  "screen-projects",
  "screen-skills",
  "screen-automation",
  "screen-mcp",
  "screen-github",
  "screen-security",
  "screen-settings",
  "zoom-in",
  "zoom-out",
  "zoom-reset",
] as const;

export type RebindableId = (typeof REBINDABLE_IDS)[number];

/** Built-in chord for each rebindable action — the value useHotkeys matched
 *  before rebinding existed. The user's overrides fall back to these.
 *
 *  Zoom defaults are the canonical `code` chords (used for conflict detection +
 *  the captured-override display); useHotkeys still matches the *unbound* zoom
 *  keys by `e.key` so `Ctrl++` and `Ctrl+=` both zoom in as before. */
export const DEFAULT_BINDINGS: Record<RebindableId, string> = {
  "broadcast-toggle":   "Ctrl+Shift+KeyC",
  "fullscreen-toggle":  "Ctrl+Shift+KeyF",
  "focus-next-waiting": "Ctrl+Shift+KeyN",
  "clear-input":        "Ctrl+Shift+Backspace",
  "redraw-pane":        "Ctrl+Shift+KeyR",
  "send-all-enter":     "Alt+Shift+Enter",
  // #4167 — PAGE navigation. Arrows, not digits: every digit combination is already a console selector
  // leader (Ctrl / Ctrl+Shift / Alt / Alt+Shift), so a digit family here could not avoid a collision.
  "page-prev":          "Ctrl+ArrowLeft",
  "page-next":          "Ctrl+ArrowRight",
  "screen-glance":      "F1",
  "screen-projects":    "F2",
  "screen-skills":      "F3",
  "screen-automation":  "F4",
  "screen-mcp":         "F5",
  "screen-github":      "F6",
  "screen-security":    "F7",
  "screen-settings":    "F8",
  "zoom-in":            "Ctrl+Equal",
  "zoom-out":           "Ctrl+Minus",
  "zoom-reset":         "Ctrl+Digit0",
};

/** The structural subset of KeyboardEvent the chord helpers read — lets the
 *  pure functions be called with a plain object in tests. */
export interface ChordEvent {
  ctrlKey: boolean;
  altKey: boolean;
  shiftKey: boolean;
  metaKey: boolean;
  code: string;
}

/** `code` values that are themselves modifier keys — a chord can't be just a
 *  modifier, so capture ignores these until a real key arrives. */
export function isModifierCode(code: string): boolean {
  return (
    code === "ControlLeft" || code === "ControlRight" ||
    code === "AltLeft"     || code === "AltRight" ||
    code === "ShiftLeft"   || code === "ShiftRight" ||
    code === "MetaLeft"    || code === "MetaRight"
  );
}

/** Serialize an event to its chord string, or `null` when the main key is a bare
 *  modifier (nothing to bind yet). */
export function eventToChord(e: ChordEvent): string | null {
  if (!e.code || isModifierCode(e.code)) return null;
  const parts: string[] = [];
  if (e.ctrlKey)  parts.push("Ctrl");
  if (e.altKey)   parts.push("Alt");
  if (e.shiftKey) parts.push("Shift");
  if (e.metaKey)  parts.push("Meta");
  parts.push(e.code);
  return parts.join("+");
}

/** Whether an event exactly matches a chord string (exact modifier set + key).
 *  Exact match is what enforces "no Meta, no Alt" etc. for the default chords. */
export function matchesChord(e: ChordEvent, chord: string): boolean {
  return eventToChord(e) === chord;
}

/** The active chord for an id: the user's override, else the built-in default. */
export function effectiveChord(
  bindings: Record<string, string>,
  id: RebindableId,
): string {
  return bindings[id] ?? DEFAULT_BINDINGS[id];
}

/** Whether an event matches the active binding for a rebindable id. */
export function matchesBinding(
  e: ChordEvent,
  bindings: Record<string, string>,
  id: RebindableId,
): boolean {
  return matchesChord(e, effectiveChord(bindings, id));
}

const CODE_LABELS: Record<string, string> = {
  Backspace: "Backspace",
  Enter: "Enter",
  Space: "Space",
  Escape: "Esc",
  Tab: "Tab",
  Delete: "Del",
  Equal: "=",
  Minus: "−",
};

const ARROW_CAPS: Record<string, string> = {
  ArrowLeft: "←", ArrowRight: "→", ArrowUp: "↑", ArrowDown: "↓",
};

/** A single `code` token → its key cap label (e.g. "KeyC" → "C", "Digit1" → "1",
 *  "Backspace" → "Backspace"). Modifier tokens pass through unchanged. */
function codeToCap(token: string): string {
  if (token.startsWith("Key")) return token.slice(3);
  if (token.startsWith("Digit")) return token.slice(5);
  if (token.startsWith("Numpad")) return token.slice(6);
  // Arrows render as their GLYPH (#4167) — "Ctrl ←" reads as a key cap where "Ctrl Left" reads as prose.
  if (token.startsWith("Arrow")) return ARROW_CAPS[token] ?? token.slice(5);
  return CODE_LABELS[token] ?? token;
}

/** Split a chord string into display key caps, e.g. "Ctrl+Shift+KeyC" →
 *  ["Ctrl", "Shift", "C"]. */
export function chordToCaps(chord: string): string[] {
  return chord.split("+").map(codeToCap);
}

/** The rebindable id (other than `self`) whose active binding equals `chord`,
 *  or `null` when there's no conflict. Lets the UI block a duplicate. */
export function findConflict(
  bindings: Record<string, string>,
  self: RebindableId,
  chord: string,
): RebindableId | null {
  for (const id of REBINDABLE_IDS) {
    if (id === self) continue;
    if (effectiveChord(bindings, id) === chord) return id;
  }
  return null;
}

/** Metadata for the rebindable shortcuts, sourced from SHORTCUT_GROUPS (a leaf
 *  module — no import cycle with useHotkeys) so the labels can't drift from the
 *  reference rows the same ids tag. */
export interface RebindableMeta {
  id: RebindableId;
  label: string;
}

const SHORTCUT_BY_ID: Record<string, string> = Object.fromEntries(
  SHORTCUT_GROUPS.flatMap((g) => g.items)
    .filter((s) => s.id != null)
    .map((s) => [s.id as string, s.desc]),
);

export const REBINDABLE: RebindableMeta[] = REBINDABLE_IDS.map((id) => ({
  id,
  label: SHORTCUT_BY_ID[id] ?? id,
}));

// ── Leader bindings (#773, Tier 2) ──────────────────────────────────────────
//
// The digit-RANGE shortcuts (Ctrl+1–9 tab switch, Ctrl+Shift+1–9 pane select,
// Alt+1–5 view, Alt+Shift+1–5 view-all) aren't single chords — they're a
// modifier "leader" + ANY digit. You rebind the leader (e.g. tab-switch Ctrl →
// Alt), not one key. A leader is the same modifier-order serialization as a
// chord, but with no main key (e.g. "Ctrl", "Ctrl+Shift").

export const LEADER_IDS = [
  "tab-switch",
  "pane-select",
  "view-switch",
  "view-switch-all",
] as const;

export type LeaderId = (typeof LEADER_IDS)[number];

export const DEFAULT_LEADERS: Record<LeaderId, string> = {
  "tab-switch":      "Ctrl",
  "pane-select":     "Ctrl+Shift",
  "view-switch":     "Alt",
  "view-switch-all": "Alt+Shift",
};

/** The modifier combos offered in the leader dropdown. */
export const LEADER_OPTIONS = [
  "Ctrl",
  "Alt",
  "Shift",
  "Ctrl+Shift",
  "Ctrl+Alt",
  "Alt+Shift",
  "Ctrl+Alt+Shift",
] as const;

/** The active modifiers of an event, in canonical order, with no main key —
 *  e.g. Ctrl+Shift+Digit1 → "Ctrl+Shift". "" when no modifier is held. */
export function eventToLeader(e: ChordEvent): string {
  const parts: string[] = [];
  if (e.ctrlKey)  parts.push("Ctrl");
  if (e.altKey)   parts.push("Alt");
  if (e.shiftKey) parts.push("Shift");
  if (e.metaKey)  parts.push("Meta");
  return parts.join("+");
}

/** The active leader for an id: the user's override, else the built-in default. */
export function effectiveLeader(bindings: Record<string, string>, id: LeaderId): string {
  return bindings[id] ?? DEFAULT_LEADERS[id];
}

/** Whether an event's modifiers exactly equal the active leader for an id. */
export function matchesLeader(e: ChordEvent, bindings: Record<string, string>, id: LeaderId): boolean {
  return eventToLeader(e) === effectiveLeader(bindings, id);
}

/** Another leader id (other than `self`) whose active leader equals `leader`. */
export function findLeaderConflict(
  bindings: Record<string, string>,
  self: LeaderId,
  leader: string,
): LeaderId | null {
  for (const id of LEADER_IDS) {
    if (id === self) continue;
    if (effectiveLeader(bindings, id) === leader) return id;
  }
  return null;
}

/** Leader string → modifier caps (e.g. "Ctrl+Shift" → ["Ctrl", "Shift"]). */
export function leaderToCaps(leader: string): string[] {
  return leader === "" ? [] : leader.split("+");
}

const LEADER_LABEL_BY_ID: Record<string, string> = SHORTCUT_BY_ID;
export const LEADER_META: { id: LeaderId; label: string }[] = LEADER_IDS.map((id) => ({
  id,
  label: LEADER_LABEL_BY_ID[id] ?? id,
}));

// kitChrome (#2420) — the small chrome bits this feature hand-rolled: the role-colored dot and the
// kit-switcher chip. Shared WITHIN the feature. `RoleDot` is used by both Design Studio and the
// Planner Components pane; `KitChip` is now used only by the Planner Components pane.
import type { ReactNode, CSSProperties } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { StatusDot } from "@/shared/ui/feedback/StatusDot";
import { ColorSwatch } from "@/shared/ui/controls/ColorSwatch";
import { ROLE_COLOR, type Role, type Kit } from "@/features/designs/lib/model";

/** The role-colored dot beside a component name. `glow` adds the soft ring (px) the studio's
 *  tree rows / inspector title use. */
export function RoleDot({ role, size = 8, glow, style }: { role: Role; size?: number; glow?: number; style?: CSSProperties }) {
  const color = ROLE_COLOR[role];
  return (
    <StatusDot
      color={color} size={size}
      style={{ ...(glow ? { boxShadow: `0 0 0 ${glow}px color-mix(in srgb, ${color} 22%, transparent)` } : {}), ...style }}
    />
  );
}

/** The kit-switcher chip: the kit's color swatch + name (+ optional trailing count). The caller
 *  supplies its own density via the `className` (the Planner Components pane passes `pcp-kitchip`). */
export function KitChip({ kit, on, className, title, onClick, children }: {
  kit: Kit;
  on: boolean;
  /** The surface's chip class — e.g. `pcp-kitchip` (planner pane). */
  className: string;
  title?: string;
  onClick?: () => void;
  /** Optional trailing content (e.g. the studio's component count). */
  children?: ReactNode;
}) {
  return (
    <Box as="button" className={`${className}${on ? " on" : ""}`} title={title} onClick={onClick}>
      <ColorSwatch color={kit.dot} size={6} />{kit.name}{children}
    </Box>
  );
}

// Component-kit gist transport (#2305 slice 1c) — publish/import a component KIT as a typed gist,
// reusing the SAME extension-manifest envelope + gist transport blueprints and app-state already use
// (#598/#2272). A kit is already a self-contained JSON file (slice 1b), so distribution is one file:
// wrap it in the `component-kit` envelope, publish it as a free GitHub gist (or copy a no-account
// share code), and import it back by URL/code. Pure envelope helpers (unit-testable) + Tauri-backed
// transport, mirroring `store/appStateGist.ts`.
import { wrapExtension, encodeShareCode, decodeShareCode, type ExtensionManifest, type ValidateResult } from "@/features/planner/lib/gist/manifest";
import { installFromGist, publishGist } from "@/features/planner/lib/gist/gist";
import { bsc } from "@/shared/lib/core/bsc";
import { sha256Hex } from "@/shared/lib/core/sha256";
import { DATA_SHAPES, ROLES, type ComponentRecord, type DataShape, type Kit, type PropSpec, type Role } from "@/features/designs/lib/model";

/** The manifest kind a component kit ships as. */
export const KIT_KIND = "component-kit" as const;

/** The GLOBAL kit-store identity a published kit carries (#2465): the publisher-scoped id
 *  (`<publisher>/<kit-slug>`) + exact version it registers under in the versioned kit store —
 *  what an importer pins (`Blueprint.uiKit`) instead of re-deriving an identity per download. */
export interface KitStoreIdentity {
  id: string;
  version: string;
}

/** The kit + its components — the payload a `component-kit` gist carries. `store` (#2465) stamps
 *  the publisher's kit-store identity so every importer lands it under the SAME id@version. */
export interface KitPayload {
  kit: Kit;
  components: ComponentRecord[];
  store?: KitStoreIdentity;
}

const str = (v: unknown, d = ""): string => (typeof v === "string" ? v : d);
const strArr = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : []);
const num = (v: unknown, d = 0): number => (typeof v === "number" && Number.isFinite(v) ? v : d);
const role = (v: unknown): Role => (ROLES.includes(v as Role) ? (v as Role) : "primitive");

function coerceProp(v: unknown): PropSpec | null {
  if (!v || typeof v !== "object") return null;
  const o = v as Record<string, unknown>;
  if (!str(o.name)) return null;
  return { name: str(o.name), type: str(o.type), req: o.req === true, desc: str(o.desc) };
}

/** Reconstruct a component from an untrusted payload, forcing it into `kitId` and dropping `builtin`
 *  (an imported record is user-owned). Returns null when it has no id/name. */
function coerceComponent(v: unknown, kitId: string): ComponentRecord | null {
  if (!v || typeof v !== "object") return null;
  const o = v as Record<string, unknown>;
  const name = str(o.name);
  const id = str(o.id) || name.toLowerCase();
  if (!id || !name) return null;
  const rec: ComponentRecord = {
    id, name, kitId, role: role(o.role), version: str(o.version, "1.0.0"), used: num(o.used),
    tags: strArr(o.tags), variants: strArr(o.variants).length ? strArr(o.variants) : ["default"],
    composes: strArr(o.composes),
    props: Array.isArray(o.props) ? o.props.map(coerceProp).filter((p): p is PropSpec => p !== null) : [],
    whenUse: strArr(o.whenUse), whenNot: strArr(o.whenNot),
    src: str(o.src), srcText: str(o.srcText),
  };
  if (str(o.wraps)) rec.wraps = str(o.wraps);
  // The data-shape axis (#2475/#3517) rides a shared kit, filtered to the seven-shape vocabulary.
  const shapes = strArr(o.shapes).filter((s): s is DataShape => (DATA_SHAPES as string[]).includes(s));
  if (shapes.length) rec.shapes = shapes;
  return rec;
}

/** Wrap a kit + its components in the typed extension envelope for publishing/sharing. `store`
 *  (#2465) stamps the payload with the publisher's kit-store identity (absent ⇒ the pre-#2465
 *  envelope, byte-identical). */
export function kitToManifest(kit: Kit, components: ComponentRecord[], version = "1.0.0", store?: KitStoreIdentity): ExtensionManifest<KitPayload> {
  const payload: KitPayload = { kit, components, ...(store ? { store } : {}) };
  return wrapExtension(KIT_KIND, kit.id, kit.name, version, payload, { description: `Component kit: ${kit.name}` });
}

/** Reconstruct a sanitized { kit, components } from a validated manifest, or an error if it's not a
 *  component kit. Components are forced into the kit's id; `builtin` is dropped so an imported kit is
 *  user-owned (deletable/editable) and can never masquerade as a packaged built-in. */
export function kitFromManifest(m: ExtensionManifest): { ok: true; kit: Kit; components: ComponentRecord[] } | { ok: false; error: string } {
  if (m.kind !== KIT_KIND) return { ok: false, error: `expected a component kit, got '${m.kind}'` };
  const p = (m.payload ?? {}) as Partial<KitPayload>;
  const rawKit = (p.kit ?? {}) as Record<string, unknown>;
  const id = str(rawKit.id) || str(m.id);
  const name = str(rawKit.name) || str(m.name);
  if (!id || !name) return { ok: false, error: "kit has no id or name" };
  const kit: Kit = { id, name, stack: str(rawKit.stack, "imported"), dot: str(rawKit.dot, "var(--accent)") };
  // The rail-hierarchy axes (#2487) ride when the payload declares them — tech normalized to its
  // lowercase-slug form; an absent axis stays ABSENT (the kit groups into the "other" bucket).
  if (str(rawKit.tech).trim()) kit.tech = str(rawKit.tech).trim().toLowerCase();
  if (str(rawKit.style).trim()) kit.style = str(rawKit.style).trim();
  const components = (Array.isArray(p.components) ? p.components : [])
    .map((c) => coerceComponent(c, id))
    .filter((c): c is ComponentRecord => c !== null);
  if (!components.length) return { ok: false, error: "kit has no valid components" };
  return { ok: true, kit, components };
}

/** Encode a kit as a no-account, copy-paste share code (base64url of the manifest). */
export function kitShareCode(kit: Kit, components: ComponentRecord[]): string {
  return encodeShareCode(kitToManifest(kit, components));
}

/** Decode a share code OR a raw manifest JSON string back into a kit. */
export function kitFromCode(text: string): { ok: true; kit: Kit; components: ComponentRecord[] } | { ok: false; error: string } {
  const res: ValidateResult = decodeShareCode(text);
  return res.ok ? kitFromManifest(res.manifest) : res;
}

/** Import a kit from a gist URL/id (public gists need no auth; `token` raises the rate limit / reads a
 *  secret gist). Fetch → validate envelope → coerce the kit payload. */
export async function importKitFromGist(url: string, token = ""): Promise<{ ok: true; kit: Kit; components: ComponentRecord[] } | { ok: false; error: string }> {
  const res = await installFromGist(url, token);
  return res.ok ? kitFromManifest(res.manifest) : res;
}

/** The pin a published kit hands its consumers (#2465): the kit-store identity + the sha256 of the
 *  published manifest bytes, with the gist URL as `source` — exactly the `Blueprint.uiKit` shape. */
export interface PublishedKitPin {
  id: string;
  version: string;
  hash: string;
  source: string;
}

/** A lowercase [a-z0-9-] slug segment for the store identity. */
const idSlug = (s: string): string => s.toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, "") || "kit";

/** Publish a kit as a gist (needs a token with the `gist` scope). `public` makes it a shareable public
 *  gist; the default is a secret gist. Returns the gist URL.
 *
 *  `publisher` (#2465) additionally registers the kit in the GLOBAL versioned kit store: the manifest
 *  is stamped with its store identity (`<publisher>/<kit-slug>@<version>`), hashed (sha256 of the
 *  EXACT bytes the gist holds), published, then written to the local store with the gist URL as
 *  `source` — so the publisher's own store entry, the gist bytes, and the returned `pin` all agree.
 *  A same-id@version conflict with different content is refused by the store (immutability) and
 *  surfaced as `warning` — the publish itself has already succeeded; bump `version` and re-publish. */
export async function publishKitToGist(
  token: string, kit: Kit, components: ComponentRecord[],
  opts: { public?: boolean; publisher?: string; version?: string } = {},
): Promise<{ ok: true; url: string; pin?: PublishedKitPin; warning?: string } | { ok: false; error: string }> {
  const store: KitStoreIdentity | undefined = opts.publisher
    ? { id: `${idSlug(opts.publisher)}/${idSlug(kit.id)}`, version: opts.version ?? "1.0.0" }
    : undefined;
  const manifest = kitToManifest(kit, components, store?.version ?? "1.0.0", store);
  try {
    const res = await publishGist(token, manifest, { public: opts.public });
    if (!store) return { ok: true, url: res.htmlUrl };
    // The bytes publishGist wrote (same object, same serialization) — the hash consumers verify.
    const text = JSON.stringify(manifest, null, 2);
    const pin: PublishedKitPin = { ...store, hash: await sha256Hex(text), source: res.htmlUrl };
    try {
      await bsc(
        null,
        ["ui", "release", "add", store.id, store.version, "--kind", KIT_KIND, "--sha256", pin.hash, "--source", res.htmlUrl],
        text,
      );
    } catch (e) {
      return { ok: true, url: res.htmlUrl, pin, warning: `published, but the local kit store refused ${store.id}@${store.version}: ${String(e)}` };
    }
    return { ok: true, url: res.htmlUrl, pin };
  } catch (e) {
    return { ok: false, error: String(e) };
  }
}

// Hierarchical kit navigation (#2487, policy fixed by #2506) — the PURE grouping model behind the
// Design Studio rail. The full hierarchy is technology → visual language → kit → components: `tech`
// (lowercase slug) is the top grouping axis, `style` (the visual language — a STRUCTURALLY different
// component set, i.e. a different kit; the palette/THEME axis restyles one kit via tokens and never
// appears here) is the second. React/Tauri-free so the rail render and the tests share one model.
//
// ALWAYS GROUPED (#2506) — the rail shows technology groups at the top level and style groups within
// each technology, ALWAYS. (#2487 originally auto-flattened a level whose partition was trivial; that
// heuristic is superseded by explicit user direction — the fixed two-level hierarchy is the point, so
// the packaged single-kit library reads React → Studio → components rather than a bare kit list.)
//
// THE SINGLE-KIT STYLE MERGE — a kit is a (tech, style) unit, so the normal case is a style bucket
// holding exactly ONE kit. Then the style header IS the kit: the group node carries `kit`, its
// components list directly under the style header, and no redundant kit row renders. Only when
// several kits share one (tech, style) pair does a kit level nest beneath the style group.
//
// MISSING FIELDS — kits without `tech`/`style` (user-authored, imported, pre-#2487) group into the
// trailing "other" bucket on that axis. Never a crash.
//
// THE `folder` AXIS UNDER A KIT (#3048/#3582) — a kit's components carry a `/`-delimited folder path
// derived from their `src`, so a kit browses like a completed project's folders. Building that tree is
// NOT this module's job any more: since #4128 the nested-folder model is shared with the Algorithms rail
// (`@/shared/lib/core/folderTree`), because two copies of "the same structure" had already drifted apart
// on ungrouped-handling and ordering. `groupComponentsByFolder` is now the components-typed binding of
// that one builder.
import { buildFolderTree, folderItemCount, type FolderNode } from "@/shared/lib/core/folderTree";
import type { Kit, ComponentRecord } from "@/features/designs/lib/model";

export { UNGROUPED_KEY, UNGROUPED_LABEL } from "@/shared/lib/core/folderTree";

/** The bucket kits without a `tech`/`style` value group under (always ordered last). */
export const OTHER_BUCKET = "other";

/** A kit row in the rail tree (only under a style that holds SEVERAL kits — see the module doc). */
export interface KitLeaf {
  kind: "kit";
  kit: Kit;
}

/** A collapsible group header in the rail tree (a tech or visual-language level). */
export interface KitGroup {
  kind: "group";
  level: "tech" | "style";
  /** Stable expand-state key (`tech:react`, `style:react/studio`). */
  key: string;
  label: string;
  /** Kits under this group (transitively). */
  count: number;
  /** Style level only: when the style holds exactly ONE kit, the header IS that kit — components
   *  render directly beneath it and `children` is empty (#2506). */
  kit?: Kit;
  children: KitTreeNode[];
}

export type KitTreeNode = KitGroup | KitLeaf;

const techOf = (k: Kit): string => (k.tech ?? "").trim().toLowerCase() || OTHER_BUCKET;
const styleOf = (k: Kit): string => (k.style ?? "").trim() || OTHER_BUCKET;

/** Bucket items by a key in first-appearance order, the missing-field OTHER bucket forced last.
 *  Generic over kits (the tech/style axes) and components (the #3048 `group` axis). */
function bucket<T>(items: readonly T[], keyOf: (x: T) => string): Map<string, T[]> {
  const m = new Map<string, T[]>();
  for (const x of items) {
    const key = keyOf(x);
    const arr = m.get(key);
    if (arr) arr.push(x);
    else m.set(key, [x]);
  }
  const other = m.get(OTHER_BUCKET);
  if (other && m.size > 1) {
    m.delete(OTHER_BUCKET);
    m.set(OTHER_BUCKET, other);
  }
  return m;
}

/** The style level under one tech group: a style group per bucket; a single-kit style merges the kit
 *  into its header (see the module doc). */
function styleLevel(kits: Kit[], keyPrefix: string): KitTreeNode[] {
  return [...bucket(kits, styleOf)].map(([style, inStyle]) => ({
    kind: "group" as const,
    level: "style" as const,
    key: `style:${keyPrefix}${style}`,
    label: style,
    count: inStyle.length,
    ...(inStyle.length === 1
      ? { kit: inStyle[0], children: [] as KitTreeNode[] }
      : { children: inStyle.map((kit): KitTreeNode => ({ kind: "kit", kit })) }),
  }));
}

/**
 * Group the kit library into the rail tree: tech groups → style groups (→ kit leaves only when a
 * style holds several kits) — ALWAYS grouped, per the module doc (#2506). Kits keep their library
 * order within a bucket; buckets order by first appearance, the "other" bucket last.
 */
export function groupKits(kits: Kit[]): KitTreeNode[] {
  return [...bucket(kits, techOf)].map(([tech, inTech]) => ({
    kind: "group" as const,
    level: "tech" as const,
    key: `tech:${tech}`,
    label: tech,
    count: inTech.length,
    children: styleLevel(inTech, `${tech}/`),
  }));
}

/** One folder of a kit's tree — the shared {@link FolderNode} bound to {@link ComponentRecord}. The
 *  components-side NAME for the shared node (#4128), kept so importers read in kit vocabulary; the
 *  SHAPE is the shared one, which is what makes the two library rails structurally identical. */
export type ComponentFolder = FolderNode<ComponentRecord>;

/** Total components under a folder, transitively (its own + every descendant's) — the header count. */
export const folderComponentCount = folderItemCount<ComponentRecord>;

/**
 * Partition ONE kit's components into a nested FOLDER TREE by their `folder` path (#3048/#3582) — the
 * components-typed binding of the shared {@link buildFolderTree} (#4128).
 *
 * `composes` is unaffected — it resolves across the whole kit, so components in different folders still
 * compose freely; this tree is organizational only.
 *
 * Returns `null` when NO component carries a `folder`, so the rail renders the flat component list
 * exactly as it would without folders (zero regression for folderless kits).
 */
export function groupComponentsByFolder(comps: readonly ComponentRecord[]): ComponentFolder[] | null {
  return buildFolderTree(comps, (c) => c.folder);
}

// The frontend ↔ kit-usage consumer-index bridge (#2277). Which projects use which kit — the GLOBAL
// edge store the change-propagation fan-out reads, reached (from the UI AND a live session's shell)
// through the SAME `bsc ui usage …` CLI over the generic `bsc` bridge (#2114). Global → every
// call passes `null` as the projectKey. The Zustand `kitUsage` slice is a write-through cache over it.
import { bsc, bscRun } from "@/shared/lib/core/bsc";
import type { KitConsumer } from "@/features/designs/lib/propagation";

/**
 * Load every consumer edge via `bsc ui usage list --json`. Returns `null` when the bridge is
 * unreachable (no Tauri host / an old binary) so the caller keeps its persisted cache rather than
 * blanking it. NOT `bscJson` — its degrade-to-`[]` would clobber the cache on a transient failure.
 */
export async function loadKitUsage(): Promise<KitConsumer[] | null> {
  try {
    const out = await bsc(null, ["ui", "usage", "list", "--json"]);
    const rows = JSON.parse(out.trim() || "[]") as { projectKey?: string; kitId?: string }[];
    return (rows ?? [])
      .filter((u): u is { projectKey: string; kitId: string } => !!u.projectKey && !!u.kitId)
      .map((u) => ({ projectKey: u.projectKey, kitId: u.kitId }));
  } catch {
    return null;
  }
}

/** Write-through an edge add (`bsc ui usage add`). Fire-and-forget; never throws (degrades to
 *  cache-only when the bridge/binary is absent). */
export async function pushKitUsage(projectKey: string, kitId: string): Promise<void> {
  try { await bscRun(null, ["ui", "usage", "add", projectKey, kitId]); } catch { /* bridge absent — cache-only */ }
}

/** Write-through an edge removal (`bsc ui usage remove <id>`). Never throws. */
export async function dropKitUsage(id: string): Promise<void> {
  try { await bscRun(null, ["ui", "usage", "remove", id]); } catch { /* bridge absent — cache-only */ }
}

// The Algorithms knowledge graph — pure model (#2761, epic #2760). React/Tauri-free so the tests, the
// page render, and the harvest lift all share ONE model. PRIMITIVES-ROOTED, impl-is-concept
// (#2958/#2961): each language kit is a graph of its implementations, rooted in that language's
// PRIMITIVES (Vec, Iterator, …) with algorithms composing UP from them. There is NO abstract concept
// layer — a node IS a concrete implementation. Loaded from the packaged seed
// (@data/knowledge/algorithms.json — the SAME source `bsc graph` embeds).
import { buildFolderTree, folderItemCount, type FolderNode } from "@/shared/lib/core/folderTree";
import RAW from "@data/knowledge/algorithms.json";

/** The languages a kit can be in (#2770). */
export type Tech = "typescript" | "rust";

/** The implementation techs, in display order. */
export const TECHS: Tech[] = ["typescript", "rust"];

/** Per-tech display label + file extension (an algorithm impl's id suffix) + rail dot color (a
 *  per-language identifier, the Algorithms analog of a Designs kit's `dot`). */
export const TECH_META: Record<Tech, { label: string; ext: string; dot: string }> = {
  typescript: { label: "TypeScript", ext: "ts", dot: "var(--info)" },
  rust: { label: "Rust", ext: "rs", dot: "var(--state-wait)" },
};

/** The tier of an implementation within a language kit (#2863/#2958): a `primitive` is a LANGUAGE
 *  built-in (`rust.iterator`, `rust.vec`); an `algorithm` composes primitives + simpler algorithms up.
 *  This is the "base vs growing" distinction the rail groups by. */
export type ImplRole = "primitive" | "algorithm";

/**
 * A unit of a language kit (#2863/#2958) — a node in one `tech`. The implementation IS the concept:
 * there is no abstract concept node. `role` splits **primitives** — a language BUILT-IN (`rust.vec`,
 * `rust.iterator`) that is DESCRIBED by its std `ref`, never re-coded (#2972) — from **algorithms**:
 * real reusable `code` that `compose`s OTHER impls of the SAME tech, growing UP from the primitive base
 * (e.g. `merge-sort.rs` composes `merge.rs`, `rust.vec`, `rust.slice`). `id` is `<name>.<ext>` for an
 * algorithm, `<tech>.<name>` for a primitive.
 */
/** The manipulation KINDS an algorithm can carry (#3210, epic #3209) — the "what it does" axis of the
 *  animation (`sort`/`search`/…), paired with the DATA STRUCTURE it operates on to pick the live
 *  visualization. Grows as more example animations land (matrix ops, etc.). */
export const ALGO_KINDS = ["sort", "search", "traversal", "accumulate", "transform"] as const;
export type AlgoKind = (typeof ALGO_KINDS)[number];

export interface AlgoImpl {
  /** `<name>.<ext>` (algorithm) or `<tech>.<name>` (primitive) — e.g. "merge-sort.rs", "rust.iterator". */
  id: string;
  tech: Tech;
  /** The tier (#2863) — `primitive` (a language built-in) or `algorithm` (composed). */
  role: ImplRole;
  name: string;
  summary?: string;
  /** OTHER implementation ids of the same tech this builds on — the "builds on" edges, pointing DOWN
   *  to the primitive base. */
  composes: string[];
  /** A primitive's std reference — the language built-in it names (`std::vec::Vec`, `i64`). Primitives
   *  are DESCRIBED, not re-coded (#2972); algorithms leave this unset. */
  ref?: string;
  /** An algorithm's real, reusable implementation in `tech`. Optional for a primitive — a language
   *  built-in is described (`ref` + `summary`), not re-coded (#2972). */
  code?: string;
  /** The `@/…` import specifier this impl SATISFIES, set by a module-granularity harvest
   *  (`bsc graph harvest --module`). Present only on impls that are whole MODULES: a function lifted out
   *  of a file satisfies no import, so the field stays absent there rather than null. It is what
   *  `resolveGraphSource` matches on, and the only thing that lets a component's import reach the
   *  algorithms graph at all — components resolve by specifier, algorithms otherwise compose by id. */
  provides?: string;
  /** PROVENANCE (#4091/#4107) — the scanned-root-relative path of the file this was harvested from.
   *  The Rust mirror is `AlgoImpl.src`. Absent on anything authored before it (every seeded impl). */
  src?: string;
  /** The module's TOP-LEVEL MUTABLE BINDINGS — the state it holds, named. Set by a module-granularity
   *  harvest; absent (never `[]`) on a pure module and on any function-granularity impl, which is a
   *  fragment of a file and so holds none of the file's module state.
   *
   *  This is the property that decides whether vendoring the record is equivalent to importing the
   *  module. `provides` makes the loader hand a graph consumer this source INSTEAD of the bundled
   *  module, so a module holding state gives that consumer a SECOND instance of it — a second queue,
   *  a second cache, a second timer — and the two diverge with nothing on screen to say so. Naming the
   *  bindings is what makes that visible rather than something each reader rediscovers in the source. */
  moduleState?: string[];
  /** The FOLDER (#4107) — the nested, `/`-delimited path this impl organizes under, derived from
   *  {@link src} by the SAME derivation components use (`bsc_util::folder_from_src`). Harvest is 1:1:
   *  the folder mirrors where the code actually lives, so the library reads like the tree it came from.
   *  Absent ⇒ the impl is UNFOLDERED and the rail lists it directly under its language. */
  folder?: string;
  /** Optional DOMAIN facet (#3120) — the lightweight, cross-language collection this impl belongs to
   *  (e.g. "logistics", "graphics"). ADDITIVE + backward-compatible: impls authored before the facet
   *  existed have no `domain` and are simply absent from every domain collection, so nothing breaks. A
   *  domain cross-cuts language, so a domain app can pull its relevant subset of the library — all
   *  `logistics` algorithms, across languages. Curated via `bsc graph impl set --domain <d>`. */
  domain?: string;
  /** Optional free-form tags (#3120) — additive keywords for search / cross-cutting collections. Absent
   *  on existing impls; curated via `bsc graph impl set --tags a,b,c`. */
  tags?: string[];
  /** Optional KIND facet (#3210) — the manipulation this algorithm performs (`sort`/`search`/…), the
   *  "what it does" axis that (with its data structure) selects the live animation. ADDITIVE + backward-
   *  compatible: the CREATOR assigns it (`bsc graph impl set --kind sort`), and a heuristic classifier
   *  fills it for untyped impls; absent on impls authored before the facet, so nothing breaks. */
  kind?: AlgoKind;
  /** Optional VIZ-CODE facet (#3218, epic #3215) — the algorithm's VISUALIZATION as data: a JS
   *  trace-program the executor (#3232) runs to DERIVE the animation from the real algorithm. It is a JS
   *  EXPRESSION evaluating to a self-describing descriptor `{ datatype, input, run }` — `datatype` is
   *  `"array" | "matrix" | "graph"` (picks the renderer + input seam), `input` is the default input, and
   *  `run(structure)` is the algorithm written against the matching Traced<Structure> API. The visualizable
   *  form of an impl whose reference `code` can't run in the browser (e.g. Rust). ADDITIVE; the librarian
   *  authors it (`bsc graph impl set --viz-code`). Absent (or malformed) ⇒ the impl falls back to an in-app
   *  trace-program (the sort family / matrix transforms / graph traversals) or shows no animation. */
  vizCode?: string;
}

/** The knowledge model — the per-language implementation tier (#2958); the abstract concept ontology
 *  (nodes/edges) was removed with #2961 (a node IS its implementation). */
export interface KnowledgeGraph {
  implementations: AlgoImpl[];
}

/** The raw graph document shape — `@data/knowledge/algorithms.json` and `bsc graph dump` (#2853). */
export interface RawKnowledge {
  implementations?: AlgoImpl[];
}

/** Build the model from a raw graph document, defaulting missing implementations to []. Shared by the
 *  packaged seed AND the live hydrate from the writable store (#2856), so both produce the identical
 *  model. Pure. */
export function buildKnowledge(raw: RawKnowledge): KnowledgeGraph {
  return { implementations: raw.implementations ?? [] };
}

/** The packaged seed graph — the fast-first-paint fallback + the ONE source `bsc graph` embeds. The live
 *  Algorithms view hydrates from the writable store (`bsc graph dump`, #2856) over this. */
export const KNOWLEDGE: KnowledgeGraph = buildKnowledge(RAW as unknown as RawKnowledge);

// ── The per-tech implementation tier — pure lookups over `graph.implementations`. ──

/** An implementation by its id (e.g. "merge-sort.rs"), or `undefined`. */
export function implById(graph: KnowledgeGraph, id: string): AlgoImpl | undefined {
  return graph.implementations.find((im) => im.id === id);
}

/** The implementations that `compose` `implId` — the reverse of `composes` ("used by"). */
export function usedByImpl(graph: KnowledgeGraph, implId: string): AlgoImpl[] {
  return graph.implementations.filter((im) => im.composes.includes(implId));
}

// ── Language kits (#2863) — a kit is every implementation of one `tech`; navigation groups a kit by
// `role` (primitives → algorithms) the way the Designs rail groups a kit by component role. ──

/** The techs that carry at least one implementation — the language kits present, in {@link TECHS}
 *  order first, then any others in seed order. */
export function kitTechs(graph: KnowledgeGraph): Tech[] {
  const seen = graph.implementations.map((im) => im.tech);
  const ordered = TECHS.filter((t) => seen.includes(t));
  const extras = seen.filter((t, i) => seen.indexOf(t) === i && !ordered.includes(t));
  return [...ordered, ...extras];
}

/** Every implementation in a language kit (all impls of `tech`), in seed order. */
export function kitImpls(graph: KnowledgeGraph, tech: Tech): AlgoImpl[] {
  return graph.implementations.filter((im) => im.tech === tech);
}

/** A kit's implementations of one `role` (its primitives, or its algorithms). */
export function kitImplsByRole(graph: KnowledgeGraph, tech: Tech, role: ImplRole): AlgoImpl[] {
  return graph.implementations.filter((im) => im.tech === tech && im.role === role);
}

// ── The language-folder rail model (#2899) — mirror the Designs rail (kitGroups.ts): each LANGUAGE is a
// folder (like each technology is a folder in Components), its impls the rows. Pure, so the rail render +
// tests share one model. ──

/** A language folder in the Algorithms rail — a `tech` and its implementations (primitives first). */
export interface AlgoLangGroup {
  tech: Tech;
  label: string;
  /** Stable expand-state key (`lang:<tech>`). */
  key: string;
  /** The folder-head color dot — the per-language identifier (#2902), like a Designs kit's `dot`. */
  dot: string;
  /** The kit's impls, primitives before algorithms, each in seed order. */
  impls: AlgoImpl[];
}

/** Group the implementations into one folder per language (#2899) — the rail tree. Languages in
 *  {@link kitTechs} order; within a folder, primitives lead the algorithms (the "base then grows up"
 *  reading). Pure + deterministic. */
export function groupImplsByLanguage(graph: KnowledgeGraph): AlgoLangGroup[] {
  return kitTechs(graph).map((tech) => ({
    tech,
    label: TECH_META[tech]?.label ?? tech,
    key: `lang:${tech}`,
    dot: TECH_META[tech]?.dot ?? "var(--fg-muted)",
    impls: [...kitImplsByRole(graph, tech, "primitive"), ...kitImplsByRole(graph, tech, "algorithm")],
  }));
}

/** One folder of a language's tree — the shared {@link FolderNode} bound to {@link AlgoImpl}. Since
 *  #4128 this is the SAME node the components rail renders, so the two libraries cannot drift apart on
 *  what a folder is. */
export type AlgoFolderNode = FolderNode<AlgoImpl>;

/** Total impls under a folder, transitively — the folder header's count. */
export const folderImplCount = folderItemCount<AlgoImpl>;

/**
 * Partition a language kit's impls into a nested FOLDER TREE by their {@link AlgoImpl.folder} path
 * (#4107) — the algorithms-typed binding of the shared {@link buildFolderTree} (#4128), the same one
 * `groupComponentsByFolder` binds for components.
 *
 * Impls with no folder land in the trailing "ungrouped" bucket rather than spilling flat beside the
 * tree, which is what the components rail has always done — before #4128 this side spilled them, and a
 * mostly-unfoldered library (the seeded classics carry no `src` to derive a folder from) therefore read
 * as a flat list with a few folders wedged on top.
 *
 * Returns `null` when NO impl carries a folder, so a wholly unfoldered kit renders its flat list
 * exactly as it would without folders at all.
 */
export function folderTree(impls: readonly AlgoImpl[]): AlgoFolderNode[] | null {
  return buildFolderTree(impls, (im) => im.folder);
}

/** Does an impl match a free-text rail query (name / id / folder path / tag, case-insensitive)? Mirrors
 *  the components rail's `matchesQuery` (#3589) — the folder path matches too, so a query like
 *  `viz/examples` filters the rail to a folder. Empty query → all. Pure. */
export function matchesImpl(im: AlgoImpl, query: string): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return (
    im.name.toLowerCase().includes(q) ||
    im.id.toLowerCase().includes(q) ||
    (im.folder ?? "").toLowerCase().includes(q) ||
    (im.tags ?? []).some((t) => t.toLowerCase().includes(q))
  );
}

// ── The per-kit graph (#2863/#2958) — the kit's OWN graph: nodes are its implementations (a concept IS
// its implementation), wired by `composes` (builds-on, pointing down to the primitive base). Per-language,
// not deduped: each kit renders only its own impls. This is what a kit's center graph draws. ──

/** A per-kit edge relationship — just `composes` now the abstract ontology is gone (#2961). */
export type KitRel = "composes";

/** Per-kit-rel display label + edge style. Shared by the kit-graph canvas AND the on-graph legend (#2909)
 *  so the key never drifts from the drawn edges. */
export const KIT_REL_META: Record<KitRel, { label: string; dashed?: boolean; doubleEnded?: boolean }> = {
  composes: { label: "composes" },
};

/** The order kit-rel legend rows read in. */
export const KIT_REL_ORDER: KitRel[] = ["composes"];

/** An edge in a kit graph — endpoints are implementation ids. */
export interface KitEdge { from: string; to: string; rel: KitRel }

/** A language kit as its own graph: the kit's impls + the `composes` edges between them. */
export interface KitGraph { nodes: AlgoImpl[]; edges: KitEdge[] }

/**
 * Build a kit's own graph (#2863/#2958) from `graph.implementations`, scoped to `tech`: each impl → the
 * same-tech impls it `composes` (the "grows up from the primitive base" edges). The abstract concept
 * ontology is gone (#2961), so `composes` is the only edge. Pure.
 */
export function kitGraph(graph: KnowledgeGraph, tech: Tech): KitGraph {
  const nodes = kitImpls(graph, tech);
  const ids = new Set(nodes.map((n) => n.id));
  const edges: KitEdge[] = [];
  for (const im of nodes) {
    for (const c of im.composes) if (ids.has(c)) edges.push({ from: im.id, to: c, rel: "composes" });
  }
  return { nodes, edges };
}

// ── Layout — the kit graph columns by compose depth (primitives at the base, algorithms deepening right). ──

/** A node's laid-out position (top-left, world coords). */
export interface NodePos { x: number; y: number }

/** A design-space box — matches the viewport's `GraphBox` so it can drive `contentBounds`. */
export interface Box { x: number; y: number; w: number; h: number }

export interface KnowledgeLayout {
  pos: Map<string, NodePos>;
  world: { w: number; h: number };
  /** The bounding box of the actual nodes — framed by `fit()` so the graph centers on content. */
  bounds: Box;
}

/** Node box size (world px) — shared by the layout and the canvas card. */
export const NODE_W = 172;
export const NODE_H = 58;
const COL_PITCH = NODE_W + 208;
const ROW_PITCH = NODE_H + 22;
const PAD = 48;

/** Per-impl "compose depth" within a kit: a primitive is the base (0); an algorithm is 1 + the deepest
 *  in-kit impl it composes (min 1). Drives the left→right column layout ("grows up" reads as it deepens).
 *  Cycle-guarded (composes shouldn't cycle, but a bad kit won't hang). */
function composeDepth(kit: KitGraph): Map<string, number> {
  const byId = new Map(kit.nodes.map((n) => [n.id, n]));
  const memo = new Map<string, number>();
  const visiting = new Set<string>();
  const depth = (id: string): number => {
    if (memo.has(id)) return memo.get(id)!;
    const node = byId.get(id);
    if (!node || node.role === "primitive") { memo.set(id, 0); return 0; }
    if (visiting.has(id)) return 1; // cycle guard
    visiting.add(id);
    const composed = node.composes.filter((c) => byId.has(c));
    const d = composed.length ? 1 + Math.max(...composed.map(depth)) : 1;
    visiting.delete(id);
    memo.set(id, d);
    return d;
  };
  for (const n of kit.nodes) depth(n.id);
  return memo;
}

/** Lay a kit graph out in columns by {@link composeDepth} (primitives at the base, algorithms deepening
 *  right), stacked in seed order within a column. Positions keyed by impl id, so the SAME canvas/viewport
 *  draw it. Pure + deterministic. */
export function layoutKitGraph(kit: KitGraph): KnowledgeLayout {
  const depths = composeDepth(kit);
  const pos = new Map<string, NodePos>();
  const maxDepth = Math.max(0, ...kit.nodes.map((n) => depths.get(n.id) ?? 0));
  const rowByCol = new Array<number>(maxDepth + 1).fill(0);
  for (const n of kit.nodes) {
    const col = depths.get(n.id) ?? 0;
    const row = rowByCol[col]++;
    pos.set(n.id, { x: PAD + col * COL_PITCH, y: PAD + row * ROW_PITCH });
  }
  const maxRows = Math.max(0, ...rowByCol);
  const cols = maxDepth + 1;
  const world = {
    w: PAD * 2 + (cols - 1) * COL_PITCH + NODE_W,
    h: PAD * 2 + Math.max(maxRows - 1, 0) * ROW_PITCH + NODE_H,
  };
  const bounds: Box = { x: PAD, y: PAD, w: world.w - PAD * 2, h: world.h - PAD * 2 };
  return { pos, world, bounds };
}

// Language-mix aggregation for the GitHub summary's Languages card.
//
// The summary samples only the N most-recently-updated repos (see SUMMARY_REPO_SAMPLE
// in GitHubSummary.tsx) and sums their `/languages` byte counts. This pure helper does
// the aggregation and — unlike the old inline code, which mislabeled the language count
// as a repo count — reports how many sampled repos actually contributed language data.

/** Just the language-byte slice of a repo's fetched data. */
export interface RepoLangData {
  langBytes: Record<string, number>;
}

export interface LanguageStats {
  /** Total bytes per language, summed across the contributing repos. */
  totals: Record<string, number>;
  /** How many of the sampled repos actually contributed language data. */
  repoCount: number;
}

/**
 * Aggregate per-repo language byte counts into a single mix. Repos with no detected
 * language (an empty `langBytes`) are skipped and not counted toward `repoCount`.
 */
export function languageStats(repoData: Record<string, RepoLangData>): LanguageStats {
  const totals: Record<string, number> = {};
  let repoCount = 0;
  for (const rd of Object.values(repoData)) {
    const langs = Object.entries(rd?.langBytes ?? {});
    if (langs.length === 0) continue;
    repoCount += 1;
    for (const [lang, bytes] of langs) {
      totals[lang] = (totals[lang] ?? 0) + bytes;
    }
  }
  return { totals, repoCount };
}

tests.src:
import { describe, it, expect } from "vitest";
import { languageStats } from "./languageStats";

describe("languageStats", () => {
  it("sums bytes per language across repos", () => {
    const { totals } = languageStats({
      "a/x": { langBytes: { TypeScript: 100, Dockerfile: 20 } },
      "a/y": { langBytes: { TypeScript: 50, Rust: 30 } },
    });
    expect(totals).toEqual({ TypeScript: 150, Dockerfile: 20, Rust: 30 });
  });

  it("counts only repos that contributed language data", () => {
    const { repoCount } = languageStats({
      "a/x": { langBytes: { TypeScript: 100 } },
      "a/empty": { langBytes: {} }, // no detected language → not counted
      "a/y": { langBytes: { Rust: 10 } },
    });
    expect(repoCount).toBe(2);
  });

  it("does not conflate the language count with the repo count", () => {
    // One repo, four languages — repoCount must be 1, not 4 (the old bug).
    const { totals, repoCount } = languageStats({
      "a/x": { langBytes: { TypeScript: 4, Dockerfile: 1, Rust: 1, CSS: 1 } },
    });
    expect(Object.keys(totals)).toHaveLength(4);
    expect(repoCount).toBe(1);
  });

  it("handles an empty sample", () => {
    expect(languageStats({})).toEqual({ totals: {}, repoCount: 0 });
  });
});

