// Self-correction lessons — the frontend side of #1362. A lesson is a mistake an agent caught
// mid-session (captured by the `bsc-learned` helper into the project's plan.db); the user reviews the
// pending queue here and confirms it into a project skill or discards it. These drive the SAME
// `bsc plan lesson …` verbs the planner/agents use, through the generic `bsc` bridge (#2114/#2115) —
// UI↔planner parity over one store surface (they replaced the per-verb `plan_lesson_*` Tauri commands).
//
// Kept Tauri-light + React-free so the mapping helpers are unit-testable; the LessonsTab component
// does the rendering. Mirrors how skillBridge.ts isolates the skilldb bridge.

import { bscJson, bscRun } from "@/shared/lib/core/bsc";
import { truncate } from "@/shared/lib/core/format";
import { blankSkill, skillSlug, type SkillDef } from "@/features/skills/lib/skills";

/** A captured lesson candidate — mirrors the Rust `plandb::Lesson` (camelCase). */
export interface Lesson {
  id: string;
  /** What went wrong. */
  mistake: string;
  /** Why it happened (optional). */
  cause: string;
  /** The corrective rule a future agent should follow. */
  rule: string;
  /** Origin tag set by the capture helper (`pane …, repo …`). */
  provenance: string;
  /** `pending` | `confirmed` | `discarded`. */
  status: string;
  /** How many times this same lesson was captured (dedup counter). */
  seen: number;
  createdAt: number;
  updatedAt: number;
}

/** The project's pending lesson candidates (the review queue). Returns [] when the bridge is absent
 *  (no Tauri host / no plan.db) so the UI degrades to an empty queue rather than throwing. */
export async function loadPendingLessons(projectKey: string): Promise<Lesson[]> {
  if (!projectKey) return [];
  // `bsc plan lesson list --status pending` emits the JSON array (the same `Vec<Lesson>` serde shape
  // the old `plan_lesson_list` command returned); bscJson degrades to [] when plan.db doesn't exist yet.
  return bscJson<Lesson[]>(projectKey, ["plan", "lesson", "list", "--status", "pending"], []);
}

/** Mark a candidate confirmed (the user accepted it). The caller also materializes it as a skill. */
export async function confirmLesson(projectKey: string, id: string): Promise<void> {
  await bscRun(projectKey, ["plan", "lesson", "confirm", id]);
}

/** Mark a candidate discarded (kept as a record; its seen count still grows if it recurs). */
export async function discardLesson(projectKey: string, id: string): Promise<void> {
  await bscRun(projectKey, ["plan", "lesson", "discard", id]);
}

/** A confirmed lesson's display title — the corrective rule (the actionable part), else the mistake,
 *  capped so it slugs to a sane skill directory name. */
export function lessonTitle(lesson: Pick<Lesson, "mistake" | "rule">): string {
  const base = (lesson.rule.trim() || lesson.mistake.trim()).replace(/\s+/g, " ");
  return truncate(base, 64, 61);
}

/**
 * Map a confirmed {@link Lesson} to a **project-scoped** {@link SkillDef} (the resolver then attaches
 * it to that project's future sessions). The skill is a `review`-kind corrective check: its body is
 * the transferable mistake → rule, scoped to `projectKey` (the user can later globalize it via the
 * normal skill-scope UI — that's the "promote to global" path, #1338). A stable id derived from the
 * lesson id keeps a re-confirm idempotent. Returns `null` when the lesson has nothing to name.
 */
export function lessonToSkill(lesson: Lesson, projectKey: string): (Omit<SkillDef, "id"> & { id: string }) | null {
  const name = lessonTitle(lesson);
  if (!skillSlug(name)) return null;
  const body = [
    lesson.mistake.trim() && `When: ${lesson.mistake.trim()}`,
    lesson.cause.trim() && `Why: ${lesson.cause.trim()}`,
    lesson.rule.trim() && `Do: ${lesson.rule.trim()}`,
  ].filter(Boolean).join("\n");
  return {
    ...blankSkill(),
    id: `lesson-skill-${lesson.id}`,
    name,
    kind: "review",
    source: "first-party",
    desc: lesson.mistake.trim() || lesson.rule.trim(),
    prompt: body,
    projects: projectKey ? [projectKey] : [],
    enabled: true,
  };
}

// Cross-graph adapter (#3116, epic #3114) — the Algorithms feature's map from its OWN store shape onto
// the feature-agnostic {@link NodeLookup} the shared cross-graph resolver composes. The three pillars
// stay decoupled: `shared/lib/graph/crossGraph` knows nothing about an `AlgoImpl`; THIS module adapts it,
// and the consumer (the Design Studio preview + component graph) wires it via `makeUrnResolver`. Pure +
// React-free.
//
// A node URN's `kit` is, for the algo graph, a language `Tech` (`typescript`/`rust`) and its `id` is the
// in-kit impl id (`fibonacci.ts`) OR the bare name (`fibonacci`) — the lookup accepts EITHER, because a
// component author writes the kit-less `@bsc/algorithms/fibonacci` and the store resolves it. `code` is the
// reusable implementation the preview vendors (absent for a primitive descriptor, which is not importable).
import type { NodeLookup, ResolvedNode } from "@/shared/lib/graph/crossGraph";
import { KNOWLEDGE, type KnowledgeGraph } from "@/features/algorithms/lib/knowledge";

/**
 * A {@link NodeLookup} over the algorithms store for the `algo` graph. Given a `kit` (a language `Tech`)
 * and an in-kit `id` — the exact impl id (`fibonacci.ts`) OR the bare name (`fibonacci`) — resolve to the
 * matching implementation, or `null`. Defaults to the packaged {@link KNOWLEDGE} seed; a caller can pass
 * the live-hydrated graph. The returned node's `urn`/`graph`/`kit`/`id` are placeholders — `makeUrnResolver`
 * overwrites them from the URN — so only `label`/`kind`/`code` carry through (`id` is set to the impl's
 * CANONICAL id so a caller can canonicalize the URN).
 */
export function algoNodeLookup(graph: KnowledgeGraph = KNOWLEDGE): NodeLookup {
  return (kit: string, id: string): ResolvedNode | null => {
    const impl = graph.implementations.find(
      (im) => im.tech === kit && (im.id === id || im.name === id),
    );
    if (!impl) return null;
    return {
      urn: "",
      graph: "algo",
      kit,
      id: impl.id,
      label: impl.name,
      kind: impl.role,
      code: impl.code,
    };
  };
}

// Barrel for the Skills feature's pure helpers — the SkillDef model, per-session
// resolution, catalog → definition templates, the planner `skills.json` parser,
// and the conversion to the backend payload written into a session's
// `.claude/skills/<slug>/SKILL.md`.
//
// Free of React / Tauri imports so it can be unit-tested and shared between the
// store, the Skills screen, the planner ingestion, and TerminalView. Mirrors
// lib/mcpServers.ts. Decomposed into colocated modules (#2151); this barrel keeps
// the original public API intact so every importer works unchanged.

export { type SkillDef, skillSlug, skillContentKey, blankSkill } from "@/features/skills/lib/skillsModel";
export { skillFromPayload, seedSkills, refreshPackagedSkills } from "@/features/skills/lib/skillsSeed";
export {
  resolveSkills, sessionSkillState, effectiveSessionSkills, applySessionSkillChoice,
  type SessionSkillOverride, type SessionSkillReason, type SessionSkillState,
} from "@/features/skills/lib/skillsSession";
export {
  expandGroups, groupSkillCount, parseSkillGroupsFile, type SkillGroup,
} from "@/features/skills/lib/skillGroups";
export { toSkillCfgs, type SkillCfg } from "@/features/skills/lib/skillsPayload";
export { parseSkillsFile, type PlannerSkill } from "@/features/skills/lib/skillsParser";
export { deriveSkillKpis, type DerivedSkillKpis } from "@/features/skills/lib/skillsKpis";

// Component → library cross-graph composition (#3116 algorithms, #3117 sounds; epic #3114) — derive the
// `requires` edges a kit's components declare by importing `@bsc/<segment>/<name>` (an ALGORITHM via
// `@bsc/algorithms/…` OR a SOUND cue/voice via `@bsc/sounds/…`), plus the unique library nodes they
// reference, so the composition graph can render those nodes in a FENCED BAND (A's `layoutBand`) with dashed
// `requires` edges into them. Pure + React-free; DesignsWorkbench turns this into band positions + edge paths.
//
// Graph-agnostic: it delegates identity + resolution to `resolveLibrarySpec` (libraryModules.ts), which
// resolves EACH library graph against its default kit — so an algorithm ref and a sound-cue ref are
// collected UNIFORMLY here, each referenced node carrying the reusable `code` the preview vendors (an
// algorithm's real source, or a sound cue's generated player module). A component's URN is `ui:<kitId>/<id>`
// (the design graph); the referenced node's URN is the CANONICAL `algo:…`/`sound:…` the resolver mints.
// Edges are deduped by `crossGraphEdgeId`; a component with NO `@bsc/…` import contributes nothing (an empty
// result ⇒ the band is omitted entirely, byte-identical today).
import { crossGraphEdgeId, type CrossGraphEdge, type ResolvedNode } from "@/shared/lib/graph/crossGraph";
import { formatNodeUrn, isLibrarySpec, parseNodeUrn, type NodeGraph } from "@/shared/lib/graph/nodeUrn";
import { resolveLibrarySpec } from "@/features/designs/lib/libraryModules";
import type { ComponentRecord } from "@/features/designs/lib/model";

/** The design graph a component node lives in (its URN's leading token). */
const DESIGN_GRAPH = "ui" as const;

/** Every module specifier imported/exported-from in `source`, deduped — a loose regex scan (over-inclusion
 *  is harmless; the caller only acts on the `@bsc/…` ones). A local twin of the scanners in
 *  componentPreview / graphHealth (kept local so this module doesn't depend on either). */
function importSpecifiers(source: string): string[] {
  const specs = new Set<string>();
  let m: RegExpExecArray | null;
  const fromRe = /\bfrom\s*["']([^"']+)["']/g;
  const importRe = /\bimport\s*\(?\s*["']([^"']+)["']/g;
  while ((m = fromRe.exec(source))) specs.add(m[1]);
  while ((m = importRe.exec(source))) specs.add(m[1]);
  return [...specs];
}

/** A component's scannable source — its explicit `source`, else its `srcText`. We scan whichever the record
 *  carries: even a usage-snippet `srcText` that imports `@bsc/…` honestly declares the dependency the graph
 *  should show (unlike the buildability checks, this is a VISUAL affordance, not a build gate). */
function componentSource(c: ComponentRecord): string {
  return (c.source?.trim() ? c.source : c.srcText) ?? "";
}

/** The derived cross-graph composition for a kit's components — its library `requires` edges + nodes. */
export interface LibraryComposition {
  /** The `requires` edges (a component URN → a library-node URN), deduped, in first-seen order. */
  edges: CrossGraphEdge[];
  /** The UNIQUE referenced library nodes (an algorithm's / sound's resolved node, carrying its `code`), in
   *  first-seen order — one band card each. */
  nodes: ResolvedNode[];
}

/**
 * Derive the `requires` edges + referenced library nodes for `comps` from their `@bsc/<segment>/<name>`
 * imports (algorithms AND sounds). Only references that RESOLVE to a runnable node (one carrying `code`) are
 * included — an unresolvable `@bsc/…/<missing>` (or a code-less primitive descriptor) is a graphHealth
 * finding, not a graph node. Deterministic. Pure.
 */
export function resolveComponentLibraryRefs(comps: readonly ComponentRecord[]): LibraryComposition {
  const edges: CrossGraphEdge[] = [];
  const nodesByUrn = new Map<string, ResolvedNode>();
  const seenEdge = new Set<string>();
  for (const c of comps) {
    const src = componentSource(c);
    if (!src) continue;
    const fromUrn = formatNodeUrn(DESIGN_GRAPH, c.kitId, c.id);
    if (!fromUrn) continue;
    for (const spec of importSpecifiers(src)) {
      if (!isLibrarySpec(spec)) continue;
      const node = resolveLibrarySpec(spec);
      if (!node || !node.code) continue; // resolvable + runnable (has code) only
      nodesByUrn.set(node.urn, node);
      const id = crossGraphEdgeId(fromUrn, node.urn);
      if (seenEdge.has(id)) continue;
      seenEdge.add(id);
      edges.push({ id, fromUrn, toUrn: node.urn, rel: "requires" });
    }
  }
  return { edges, nodes: [...nodesByUrn.values()] };
}

/** One (kit → library node) dependency, rolled up from the component level (#3133) — "some component of
 *  `kitId` requires this library node". The APP-LEVEL projection of {@link resolveComponentLibraryRefs}:
 *  Glance joins it against the kit-consumer index (`kitUsage`) to draw a PROJECT's `requires` edges, so it
 *  carries only what a band node needs (identity + label), never a component or a blob of `code`. */
export interface KitLibraryRef {
  /** The consuming kit — the join key against `kitUsage`'s `kitId`. */
  kitId: string;
  /** The library graph the required node lives in. Never `"ui"` (see {@link resolveKitLibraryRefs}). */
  graph: NodeGraph;
  /** The required node's canonical in-graph id (`fibonacci.ts`, `click`) — the band node's library id. */
  id: string;
  /** The node's display name (`fibonacci`) — the band card's label. */
  label: string;
}

/**
 * Roll a component library composition UP to the KIT level (#3133) — every (kit, library node) pair the
 * components declare, deduped, in first-seen order. This is the app-graph's data source: a project consumes
 * kits (`kitUsage`), a kit's components require library nodes, so a project transitively requires them.
 *
 * Derived from {@link resolveComponentLibraryRefs} (one scan, no second regex pass): each `requires` edge's
 * `fromUrn` is `ui:<kitId>/<componentId>`, so the kit falls straight out of the URN.
 *
 * `ui`-graph targets are EXCLUDED: a `ui` library node id would be `kit:<id>`, colliding with the Glance
 * node id of an actual UI kit. Today `resolveLibrarySpec` never resolves the `ui` graph, so this is a fence
 * against a future `@bsc/ui/…` vendor path silently corrupting the app graph, not live filtering.
 *
 * Cost is one pass over the derived edges — the expensive part is the source scan inside
 * `resolveComponentLibraryRefs`, so callers should memoize on the component list. Pure + deterministic.
 */
export function resolveKitLibraryRefs(comps: readonly ComponentRecord[]): KitLibraryRef[] {
  const { edges, nodes } = resolveComponentLibraryRefs(comps);
  const nodeByUrn = new Map(nodes.map((n) => [n.urn, n]));
  const out: KitLibraryRef[] = [];
  const seen = new Set<string>();
  for (const e of edges) {
    const from = parseNodeUrn(e.fromUrn);
    const node = nodeByUrn.get(e.toUrn);
    if (!from || !node || node.graph === "ui") continue;
    const key = `${from.kit}\u0000${node.urn}`; // one ref per (kit, node) — N components of a kit ⇒ 1 ref
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ kitId: from.kit, graph: node.graph, id: node.id, label: node.label });
  }
  return out;
}

// Library-module resolution (#3116, epic #3114) — the Design Studio's bridge from a `@bsc/<segment>/<name>`
// import a component author writes to (a) the resolved cross-graph node (for the requires edge) and (b) a
// VENDORABLE preview module (the algorithm's real `code`), so the live preview runs the LIBRARY impl with
// no inline copy. Composes A's URN grammar (`parseLibrarySpec`/`formatNodeUrn`) + resolver (`makeUrnResolver`)
// over the Algorithms feature's `NodeLookup` adapter — the ONE place the Design Studio decides WHICH kit a
// reference resolves against.
//
// KIT SELECTION — the ONE place the Design Studio decides WHICH kit a kit-less `@bsc/<segment>/<name>`
// reference resolves against, per graph:
//   • `algo`  → the TYPESCRIPT algorithm kit — a JS/TS preview can only vendor + run a TS impl (esbuild
//     can't build Rust).
//   • `sound` → the project's PINNED sound kit (#3412) — the blueprint's `soundKit` pin, resolved out of
//     the versioned release store, is the resolution target. A `@bsc/sounds/<id>` is kit-less, so it
//     resolves against whichever single kit {@link SoundKitSelection} names (#3117). The Rust twin
//     (`graph_health.rs`) takes the SAME kit through `HealthOptions::sound_kit_json`, so both sides agree.
//   • `ui` has no vendor path in this slice, so it doesn't resolve here (its imports stay honestly
//     unresolvable until #3118/#3119).
//
// SOUND-KIT SELECTION — ONE DEFAULT, TWO LOUD FAILURES (#3412; no silent fallback anywhere):
//   • no pin        → {@link STARTER_KIT}, the packaged default. This is the DOCUMENTED default, not a
//     fallback: an unpinned project resolves exactly as it did before #3412.
//   • pin resolved  → that kit, and ONLY that kit.
//   • pin UNRESOLVABLE (missing artifact / corrupt release / bridge failure) → the sound arm is DROPPED,
//     so every `@bsc/sounds/…` fails to resolve and surfaces as an unresolvable import. It deliberately
//     does NOT degrade to the starter kit: the user cannot HEAR that the wrong kit loaded, so a silent
//     degrade is undetectable by the only sense that would catch it (and it would contradict the
//     never-a-silent-fallback rule #3372 enforces for the pin itself).
//   A pinned kit that lacks the referenced cue fails the same way an unknown reference always has — no
//   per-cue fallback, because a half-pinned component would bleed two kits' palettes together with
//   nothing surfacing that its sound is mixed. A kit is adopted wholesale (epic #3071).
//
// Pure + React-free. The DEFAULT resolvers below read the packaged seeds ({@link KNOWLEDGE} /
// {@link BUILTIN_KITS}); a pinned kit arrives as injected state via {@link makeLibraryResolvers}, whose
// product is param-injected into the pure `componentPreviewFiles` so that module never imports a store.
import { makeUrnResolver, type NodeLookup, type ResolvedNode, type UrnResolver } from "@/shared/lib/graph/crossGraph";
import { formatNodeUrn, parseLibrarySpec, LIBRARY_ROOT, LIBRARY_SEGMENT, type NodeGraph } from "@/shared/lib/graph/nodeUrn";
import { KNOWLEDGE, algoNodeLookup } from "@/features/algorithms";
import { BUILTIN_KITS, STARTER_KIT, soundNodeLookup, type SoundKit } from "@/features/sounds";
import type { LibraryModuleResolver } from "@/features/designs/lib/componentPreview";

/**
 * WHICH sound kit `@bsc/sounds/…` resolves against — the injected state that replaced the old module-level
 * const (#3412). See the SOUND-KIT SELECTION note above for the policy behind each arm.
 */
export type SoundKitSelection =
  /** No blueprint pin — the packaged {@link STARTER_KIT}. The documented default, not a fallback. */
  | { kind: "default" }
  /** The blueprint's pin, resolved to its artifact. `ref` is `id@version` (for messages). */
  | { kind: "pinned"; ref: string; kit: SoundKit }
  /** A pin that could NOT be resolved. Nothing sound-shaped resolves — fail loudly, never a starter degrade. */
  | { kind: "unresolved"; ref: string; error: string };

/** The no-pin selection — the packaged default kit. A shared const so callers can compare identity. */
export const DEFAULT_SOUND_KIT: SoundKitSelection = { kind: "default" };

/** The resolver pair {@link makeLibraryResolvers} produces for one {@link SoundKitSelection}. */
export interface LibraryResolvers {
  /** See {@link resolveLibrarySpec} — bound to this selection's sound kit. */
  resolveLibrarySpec: (spec: string) => ResolvedNode | null;
  /** See {@link libraryModuleResolver} — bound to this selection's sound kit. */
  libraryModuleResolver: LibraryModuleResolver;
}

/** The sound graph's `{ kit, lookup }`, or `null` when NOTHING sound-shaped may resolve (an unresolvable
 *  pin). Dropping the arm — rather than substituting the starter kit — is what makes a broken pin loud. */
function soundArm(sound: SoundKitSelection): { kit: string; lookup: NodeLookup } | null {
  switch (sound.kind) {
    case "default":
      return { kit: STARTER_KIT.id, lookup: soundNodeLookup(BUILTIN_KITS) };
    case "pinned":
      // Scoped to the pinned kit ALONE: a cue the pin lacks must miss, never fall through to a built-in.
      return { kit: sound.kit.id, lookup: soundNodeLookup([sound.kit]) };
    case "unresolved":
      return null;
  }
}

/**
 * Build the library resolvers for one {@link SoundKitSelection} (#3412). Algorithms always resolve against
 * the TYPESCRIPT kit (a JS/TS preview can only vendor + run a TS impl); the sound arm follows the pin.
 *
 * Cheap but not free (it rebuilds the per-graph lookups), so callers hold the result across renders —
 * `useMemo` on the selection, not a fresh call per resolve.
 */
export function makeLibraryResolvers(sound: SoundKitSelection = DEFAULT_SOUND_KIT): LibraryResolvers {
  const arm = soundArm(sound);
  const kitForGraph: Partial<Record<NodeGraph, string>> = { algo: "typescript", ...(arm ? { sound: arm.kit } : {}) };
  const lookupForGraph: Partial<Record<NodeGraph, NodeLookup>> = {
    algo: algoNodeLookup(KNOWLEDGE),
    ...(arm ? { sound: arm.lookup } : {}),
  };
  const resolver: UrnResolver = makeUrnResolver(lookupForGraph);

  const resolveSpec = (spec: string): ResolvedNode | null => {
    const parsed = parseLibrarySpec(spec);
    if (!parsed) return null;
    const kit = kitForGraph[parsed.graph];
    const lookup = lookupForGraph[parsed.graph];
    if (!kit || !lookup) return null;
    // First resolve to the node to learn its CANONICAL id (so both name forms canonicalize to one URN),
    // then resolve THROUGH the shared resolver (A) so identity is minted the one canonical way.
    const found = lookup(kit, parsed.name);
    if (!found) return null;
    const urn = formatNodeUrn(parsed.graph, kit, found.id);
    return urn ? resolver(urn) : null;
  };

  return { resolveLibrarySpec: resolveSpec, libraryModuleResolver: makeModuleResolver(resolveSpec) };
}

/** The DEFAULT (no-pin) resolvers — built once over the packaged seeds. Every caller that has no project
 *  context resolves through these, so unpinned behavior is byte-identical to pre-#3412. */
const DEFAULT_RESOLVERS: LibraryResolvers = makeLibraryResolvers(DEFAULT_SOUND_KIT);

/**
 * Resolve a `@bsc/<segment>/<name>` library import specifier to its cross-graph {@link ResolvedNode}, or
 * `null` when it isn't a `@bsc/…` spec, targets a graph with no vendor path here, or names no such node.
 * For `algo`, `name` accepts the bare name (`fibonacci`) OR the exact id (`fibonacci.ts`); for `sound`, it
 * is the cue/voice/primitive id (`click`). The returned node's `urn` is CANONICAL (built from the resolved
 * node's id), so both name forms of an algorithm resolve to ONE node (one band card, one edge target).
 *
 * Bound to the packaged DEFAULT sound kit. A caller with project context resolves the blueprint's pin
 * instead, via {@link makeLibraryResolvers} (#3412).
 */
export function resolveLibrarySpec(spec: string): ResolvedNode | null {
  return DEFAULT_RESOLVERS.resolveLibrarySpec(spec);
}

/**
 * The default {@link LibraryModuleResolver} for the Design Studio preview: resolve `spec` and, when it names
 * a node carrying reusable `code`, return the vendorable preview module — the file `path` the import
 * resolves to (the literal specifier + a `.ts` extension unless it already has one, so the mem bundler's
 * TS loader handles it) + the module `source`. `null` when the spec doesn't resolve or the target has no
 * code (a primitive descriptor — an algorithm OR a sound primitive — is not importable). ONE source of
 * truth — the component holds no copy.
 *
 * The vendored source is graph-specific: for an ALGORITHM it's the impl's `code` VERBATIM — a self-contained
 * ES module that EXPORTS its public symbol (see the `fibonacci.ts` seed), so the import binds directly; for
 * a SOUND cue/voice it's the SELF-CONTAINED player module synthesized at resolve time (`cuePlayerModule`,
 * #3117), which exports `play`. Both already declare an `export`, so the bare-function safety net below is a
 * no-op for them; it only kicks in for a bare-function algorithm `code` (append `export { <name> };`).
 */
export const libraryModuleResolver: LibraryModuleResolver = (spec: string) =>
  DEFAULT_RESOLVERS.libraryModuleResolver(spec);

/** Build the {@link LibraryModuleResolver} over one selection's spec resolver — the shared body behind both
 *  the default export above and every pin-bound resolver {@link makeLibraryResolvers} hands out. */
function makeModuleResolver(resolveSpec: (spec: string) => ResolvedNode | null): LibraryModuleResolver {
  return (spec: string) => {
    const node = resolveSpec(spec);
    if (!node || !node.code) return null;
    const source = ensureExport(node.code, node.label);
    const path = /\.(ts|tsx|js|jsx)$/.test(spec) ? spec : `${spec}.ts`;
    return { path, source };
  };
}

/** Ensure a vendored module EXPORTS `name` for the bootstrap/importer to bind: verbatim when it already
 *  declares any `export`, else the code plus a trailing `export { <name> };` (the bare-function safety net). */
function ensureExport(code: string, name: string): string {
  if (/\bexport\b/.test(code)) return code;
  return `${code.replace(/\s*$/, "")}\nexport { ${name} };\n`;
}

/** One LIBRARY NODE a Design Studio component could RE-CODE instead of importing (#3118, epic #3114) — a
 *  candidate for the "compose, don't recreate" guardrail. `name` is the exact identifier a
 *  reimplementation would DECLARE (an algorithm's bare name); `segment` is the `@bsc/<segment>` import
 *  root the node lives under (always `algorithms` — see {@link libraryReimplTargets}); `importSpec` is the
 *  exact `@bsc/…` library import to compose instead. */
export interface LibraryReimplTarget {
  /** The identifier a reimplementation would declare — the match key against a declared symbol. */
  name: string;
  /** The node's `@bsc/<segment>` import root — `algorithms` (the only reimplementation segment). */
  segment: string;
  /** The exact library import to compose instead — `@bsc/<segment>/<name>`. */
  importSpec: string;
}

/** Is `s` a single valid JS identifier (so it COULD be a declared symbol)? Excludes empty, a leading
 *  digit, and any non-`[A-Za-z0-9_$]` char — so a library name that can never appear as `function <name>`
 *  (an extension-bearing algo id like `fibonacci.ts`) is not a reimplementation candidate. Kept in
 *  lockstep with the Rust twin `is_js_identifier`. */
function isJsIdentifier(s: string): boolean {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(s);
}

/**
 * The library nodes a component could RE-CODE (#3118) — the TYPESCRIPT algorithm kit's algorithm impls,
 * matched by their bare NAME. A node is listed IFF `@bsc/algorithms/<name>` resolves (via
 * {@link resolveLibrarySpec}), so the guardrail only ever steers to a real, vendorable library node.
 *
 * ALGORITHMS-ONLY BY DESIGN. Sounds are DELIBERATELY excluded even though `@bsc/sounds/<id>` resolves +
 * vendors (#3117 — that import path stays fully intact): a sound cue/voice id (`click`, `toggle`, `error`,
 * `success`, `pop`, `tick`, …) collides with extremely common handler/function names, so a component that
 * legitimately declares `function click()` would be wrongly flagged — and you don't "re-code" a cue as a
 * function anyway (the asymmetry: you inline an ALGORITHM like fibonacci/dijkstra, not a sound). The value
 * is asymmetric and the false-positive cost high, so the reimplementation detector matches algorithms only.
 *
 * Excluded from the algorithm set too: a primitive descriptor (a language built-in / raw source —
 * DESCRIBED, not re-coded, #2972; carries no `code`) and a non-identifier name (which can never be a
 * declared symbol). Pure; reads the packaged seed. Deduped by `importSpec`. Rust twin: `reimpl_targets`.
 */
export function libraryReimplTargets(): LibraryReimplTarget[] {
  const out: LibraryReimplTarget[] = [];
  const seen = new Set<string>();
  const add = (name: string, segment: string) => {
    if (!isJsIdentifier(name)) return;
    const importSpec = `${LIBRARY_ROOT}/${segment}/${name}`;
    if (seen.has(importSpec)) return;
    seen.add(importSpec);
    out.push({ name, segment, importSpec });
  };
  // Algorithms only (see the ALGORITHMS-ONLY note above): the TS kit's algorithm impls that ship real,
  // reusable `code` (a primitive is a language built-in — DESCRIBED, not re-coded, #2972 — so it has no
  // `code` and is excluded). Matched by the bare NAME a reimplementation declares (`fibonacci`), not the
  // extension-bearing id (`fibonacci.ts`).
  for (const im of KNOWLEDGE.implementations) {
    if (im.tech === "typescript" && im.role === "algorithm" && im.code?.trim()) add(im.name, LIBRARY_SEGMENT.algo);
  }
  return out;
}

/// Linear search — the index of the first element equal to `target`, else `None`.
pub fn linear_search<T: PartialEq>(xs: &[T], target: &T) -> Option<usize> {
    xs.iter().position(|x| x == target)
}

// Plan gap scanner (#528/#534 → #897). `findPlanGaps` flags empty files / unresolved
// placeholders in a stage's section content. Originally the lint-plan stage module's check; the
// stage engine + its dispatch wrapper were removed in #897 (Phase 4c/cleanup), and the
// placeholder check now lives in the declarative stage gate (Phase 4b — Planning computes a
// `hasPlanGaps` signal from this). Pure; no React/Tauri.

// Deliberate "fill this in later" markers a finished plan section shouldn't contain. Only the
// explicit dev markers — NOT ellipsis ("..."/"…") or the bare word "placeholder", which are normal
// prose and false-positived the gate (#918).
const PLACEHOLDER_RE = /\b(TODO|TBD|FIXME|XXX|TKTK)\b/i;

/** Gaps in a stage's artifacts: empty files or unresolved placeholders. Pure. */
export function findPlanGaps(artifacts: Record<string, string>): string[] {
  const gaps: string[] = [];
  for (const [file, content] of Object.entries(artifacts)) {
    const text = (content ?? "").trim();
    if (!text) gaps.push(`${file}: empty`);
    else if (PLACEHOLDER_RE.test(text)) gaps.push(`${file}: unresolved placeholder`);
  }
  return gaps;
}

tests.src:
import { describe, it, expect } from "vitest";
import { findPlanGaps } from "./lintPlan";

describe("lintPlan — findPlanGaps", () => {
  it("flags empty files and the deliberate fill-in markers (TODO/TBD/FIXME/XXX/TKTK)", () => {
    expect(findPlanGaps({ "goal.md": "Ship the thing." })).toEqual([]);
    expect(findPlanGaps({ "goal.md": "   " })).toEqual(["goal.md: empty"]);
    expect(findPlanGaps({ "scope.md": "In scope: TODO" })[0]).toMatch(/unresolved placeholder/);
    expect(findPlanGaps({ "x.md": "decide later — FIXME" })[0]).toMatch(/unresolved placeholder/);
  });
  it("does NOT flag normal prose: ellipsis or the word 'placeholder' (#918 — they false-positived the gate)", () => {
    expect(findPlanGaps({ "api.md": "describe the endpoints…" })).toEqual([]);
    expect(findPlanGaps({ "ui.md": "loading, error, empty states, etc..." })).toEqual([]);
    expect(findPlanGaps({ "ux.md": "show a placeholder image until the data loads" })).toEqual([]);
  });
  it("reports a gap per offending file", () => {
    const gaps = findPlanGaps({ "a.md": "", "b.md": "ok", "c.md": "TBD" });
    expect(gaps).toHaveLength(2);
  });
});

implementations.code:
// API-tier LLM provider config (#1085 / epic #1078) — which provider + model + key
// powers llm_complete-backed (planning / assistant) calls: the planning autopilot, the
// LLM grader, the cleanup-scan verifier. This is DISTINCT from the per-pane runtime
// model (ModelId / defaultModel / paneModels → `claude --model`), which the harness
// adapter owns (P0/P2) — do not conflate them.

import modelDefaultsEmbedded from "@data/console/model-defaults.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

export type LlmProvider = "anthropic" | "openai" | "gemini" | "local" | "ollama";

/** A selectable provider for the Settings UI: id + display label + API-key placeholder. */
export interface LlmProviderOption {
  id: LlmProvider;
  label: string;
  /** The key-field placeholder (empty for local providers, which need no key). */
  keyPlaceholder: string;
}

// The model-ID defaults (+ provider list) are externalized to `@data/console/model-defaults.json`
// (#2416) — the ONE source for every model default, editable without touching code + part of the
// exportable config bundle; the config-dir copy (#2047) overlays the embedded default via
// `overlayFile`. (The per-pane tier default in the same file is consumed by the model catalog,
// `@/app/console/lib/models` — a separate surface; see the note above about not conflating them.)
const MODEL_DEFAULTS = overlayFile("console/model-defaults.json", modelDefaultsEmbedded);

export interface LlmConfig {
  provider: LlmProvider;
  model: string;
  apiKey: string;
  /** OpenAI-compatible endpoint for the `local` / `ollama` provider (ignored by hosted ones). */
  baseUrl: string;
}

/** The store fields `resolveLlmConfig` reads — a structural subset of the app store,
 *  so the resolver is unit-testable with a plain object. */
export interface LlmConfigSource {
  llmProvider: LlmProvider;
  llmModel: string;
  claudeApiKey: string;
  openaiKey: string;
  geminiKey: string;
  localBaseUrl: string;
}

/** Default model for a local runtime (Ollama / OpenAI-compatible). A hosted `claude-*` model can
 *  never run locally, so a local provider falls back to this. (`ollama run qwen3-coder`.) */
export const DEFAULT_LOCAL_MODEL: string = MODEL_DEFAULTS.localModel;
/** The packaged Anthropic default, restored when switching back to a hosted provider. */
export const DEFAULT_ANTHROPIC_MODEL: string = MODEL_DEFAULTS.anthropicModel;
/** The default OpenAI-compatible endpoint for the `local`/`ollama` provider (Ollama's port). */
export const DEFAULT_LOCAL_BASE_URL: string = MODEL_DEFAULTS.localBaseUrl;
/** The selectable providers, in Settings display order. */
export const LLM_PROVIDERS: LlmProviderOption[] = MODEL_DEFAULTS.providers as LlmProviderOption[];

/** The model to actually send for a config. A `local`/`ollama` provider substitutes
 *  {@link DEFAULT_LOCAL_MODEL} when the stored model is empty or a hosted `claude-*` model (which
 *  404s on Ollama), so a stale Anthropic default never reaches the local runtime. */
export function resolveModel(provider: LlmProvider, model: string): string {
  if (providerNeedsBscAgent(provider) && (model.trim() === "" || /^claude/i.test(model))) {
    return DEFAULT_LOCAL_MODEL;
  }
  return model;
}

/** The model-field value after the user switches provider — keeps the field runnable on the new
 *  provider without clobbering a model the user explicitly typed:
 *   • → local/ollama: use {@link DEFAULT_LOCAL_MODEL} when the field is empty or a hosted `claude-*`.
 *   • → a hosted provider: restore {@link DEFAULT_ANTHROPIC_MODEL} when the field is empty or still
 *     holds the local default. Any other (custom) model is preserved as-is. */
export function modelOnProviderSwitch(provider: LlmProvider, currentModel: string): string {
  const m = currentModel.trim();
  if (providerNeedsBscAgent(provider)) {
    return m === "" || /^claude/i.test(m) ? DEFAULT_LOCAL_MODEL : currentModel;
  }
  return m === "" || m === DEFAULT_LOCAL_MODEL ? DEFAULT_ANTHROPIC_MODEL : currentModel;
}

/** Resolve the active provider + model and the API key for THAT provider.
 *  `local` & `ollama` (OpenAI-compatible, e.g. Ollama) need no key but carry a base URL. */
export function resolveLlmConfig(s: LlmConfigSource): LlmConfig {
  const apiKey =
    s.llmProvider === "openai" ? s.openaiKey :
    s.llmProvider === "gemini" ? s.geminiKey :
    (s.llmProvider === "local" || s.llmProvider === "ollama") ? "" :
    s.claudeApiKey;
  return {
    provider: s.llmProvider,
    model: resolveModel(s.llmProvider, s.llmModel),
    apiKey,
    baseUrl: s.localBaseUrl,
  };
}

/** Whether the config can make a call — a key is present, or it's `local`/`ollama` (no key). */
export function hasLlmKey(cfg: LlmConfig): boolean {
  return cfg.provider === "local" || cfg.provider === "ollama" || !!cfg.apiKey;
}

/** Providers Claude Code (the `claude` CLI) cannot drive — it only ever speaks to Anthropic. A
 *  SESSION (planner / worker / director) on one of these MUST run on the `bsc-agent` harness, so
 *  picking it implies bsc-agent regardless of the fleet-harness toggle. */
export function providerNeedsBscAgent(p: LlmProvider): boolean {
  return p === "local" || p === "ollama";
}

/** The harness a session should actually launch on. A provider Claude Code can't run (`local` /
 *  `ollama`) forces `bsc-agent` — otherwise selecting Ollama would silently launch Claude Code and
 *  ignore the choice. Every other provider honors the user's explicit `fleetHarness` toggle. So
 *  setting the provider to Ollama runs the planner, workers, and directors on Ollama with no second
 *  switch to flip. */
export function effectiveHarness(
  provider: LlmProvider,
  fleetHarness: "claude" | "bsc-agent",
): "claude" | "bsc-agent" {
  return providerNeedsBscAgent(provider) ? "bsc-agent" : fleetHarness;
}

/** The `BSC_AGENT_*` env a bsc-agent session needs to reach the configured LLM (#1078 P3b).
 *  The runtime reads provider/model/key (+ base URL for `local`/`ollama`) from these. */
export function bscAgentEnv(cfg: LlmConfig): Record<string, string> {
  const e: Record<string, string> = {
    BSC_AGENT_PROVIDER: cfg.provider,
    BSC_AGENT_MODEL: cfg.model,
  };
  if (cfg.apiKey) e.BSC_AGENT_API_KEY = cfg.apiKey;
  if (cfg.baseUrl) e.BSC_AGENT_BASE_URL = cfg.baseUrl;
  return e;
}

/** Map an {@link LlmConfig} to Aider's `--model` selector (#1172). Aider (via litellm) namespaces
 *  models by provider — `anthropic/…`, `gemini/…` — takes OpenAI models bare, and reaches a
 *  local / OpenAI-compatible endpoint through the `openai/…` prefix (paired with `OPENAI_API_BASE`,
 *  see {@link aiderEnv}). A model already carrying a `provider/` prefix is passed through untouched. */
export function aiderModelArg(cfg: LlmConfig): string {
  const m = cfg.model.trim();
  if (m.includes("/")) return m;
  switch (cfg.provider) {
    case "anthropic": return `anthropic/${m}`;
    case "gemini":    return `gemini/${m}`;
    case "openai":    return m;
    case "local":
    case "ollama":    return `openai/${m}`;
  }
}

/** The environment an Aider session needs to reach the configured LLM (#1172): the provider's API key
 *  under the variable Aider/litellm reads (`ANTHROPIC_API_KEY` / `OPENAI_API_KEY` / `GEMINI_API_KEY`),
 *  plus an `OPENAI_API_BASE` for a local / OpenAI-compatible endpoint. A local server needs no real
 *  key, so a placeholder satisfies the OpenAI client's non-empty check. Mirrors {@link bscAgentEnv}. */
export function aiderEnv(cfg: LlmConfig): Record<string, string> {
  const e: Record<string, string> = {};
  switch (cfg.provider) {
    case "anthropic": if (cfg.apiKey) e.ANTHROPIC_API_KEY = cfg.apiKey; break;
    case "openai":    if (cfg.apiKey) e.OPENAI_API_KEY = cfg.apiKey; break;
    case "gemini":    if (cfg.apiKey) e.GEMINI_API_KEY = cfg.apiKey; break;
    case "local":
    case "ollama":
      if (cfg.baseUrl) e.OPENAI_API_BASE = cfg.baseUrl;
      // A keyless local server still needs a non-empty OPENAI_API_KEY for the client to init.
      e.OPENAI_API_KEY = cfg.apiKey || "sk-local-none";
      break;
  }
  return e;
}

/** Wh per 1k tokens by model tier — directional coefficients, not metered readings. */
const WH_PER_1K: Record<"large" | "medium" | "small" | "local", { in: number; out: number }> = {
  large: { in: 0.05, out: 0.9 },
  medium: { in: 0.03, out: 0.4 },
  small: { in: 0.01, out: 0.15 },
  local: { in: 0, out: 0 },
};

/** Classify a model name into an energy tier by name pattern; unknown hosted models fall to medium. */
function tier(model: string): keyof typeof WH_PER_1K {
  const m = model.toLowerCase();
  if (/local|ollama|llama|mistral|qwen|deepseek|phi/.test(m)) return "local";
  if (/opus|ultra|gpt-4(?!o)|gpt4(?!o)/.test(m)) return "large";
  if (/haiku|mini|flash|nano|small|lite/.test(m)) return "small";
  return "medium";
}

/** Estimated Wh for an input/output token split at the model's tier. Directional, not metered. */
export function estimateEnergyWh(model: string, inputTokens: number, outputTokens: number): number {
  const k = WH_PER_1K[tier(model)];
  return (inputTokens / 1000) * k.in + (outputTokens / 1000) * k.out;
}

// LlmSettingsSlice — the API-tier LLM provider config (#1085): the anthropic/openai/gemini keys,
// the local endpoint, and the provider/model that back llm_complete calls. Split out of the former
// `core` grab-bag (#2715) — these are settings, not project state. Typed Pick<AppStore, …>.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import { modelOnProviderSwitch, DEFAULT_ANTHROPIC_MODEL, DEFAULT_LOCAL_BASE_URL } from "@/shared/lib/core/llmConfig";

type LlmSettingsSlice = Pick<AppStore,
  "claudeApiKey" | "setClaudeApiKey" | "llmProvider" | "setLlmProvider" | "llmModel" | "setLlmModel" | "openaiKey" | "setOpenaiKey" | "geminiKey" | "setGeminiKey" | "localBaseUrl" | "setLocalBaseUrl"
>;

export const createLlmSettingsSlice: StateCreator<AppStore, [], [], LlmSettingsSlice> = (set) => ({
      claudeApiKey: "",
      setClaudeApiKey: (key) => set({ claudeApiKey: key }),

      // API-tier LLM provider config (#1085). claudeApiKey is the anthropic key.
      llmProvider: "anthropic",
      // Switch the model field to the new provider's default when it still holds another provider's
      // default (a hosted `claude-*` model can't run on Ollama, and vice-versa) — a model the user
      // typed is preserved. So picking Ollama lands on `qwen3-coder` instead of a 404 on the Claude id.
      setLlmProvider: (p) => set((s) => ({ llmProvider: p, llmModel: modelOnProviderSwitch(p, s.llmModel) })),
      llmModel: DEFAULT_ANTHROPIC_MODEL,
      setLlmModel: (m) => set({ llmModel: m }),
      openaiKey: "",
      setOpenaiKey: (k) => set({ openaiKey: k }),
      geminiKey: "",
      setGeminiKey: (k) => set({ geminiKey: k }),
      localBaseUrl: DEFAULT_LOCAL_BASE_URL,
      setLocalBaseUrl: (u) => set({ localBaseUrl: u }),
});

// API-tier LLM provider config (#1085) — the keys + provider/model that back llm_complete calls.
// Split from store/types (#1634).
import type { LlmProvider } from "@/shared/lib/core/llmConfig";

/** LLM-provider slice of {@link AppStore}. */
export interface LlmState {
  claudeApiKey: string;
  setClaudeApiKey: (key: string) => void;

  // API-tier LLM provider config (#1085) — powers llm_complete-backed calls (planning
  // autopilot, grader, cleanup verifier). `claudeApiKey` doubles as the anthropic key.
  // Distinct from the per-pane runtime model (defaultModel/paneModels).
  llmProvider: LlmProvider;
  setLlmProvider: (p: LlmProvider) => void;
  llmModel: string;
  setLlmModel: (m: string) => void;
  openaiKey: string;
  setOpenaiKey: (k: string) => void;
  geminiKey: string;
  setGeminiKey: (k: string) => void;
  /** OpenAI-compatible endpoint for the `local` provider (default Ollama). */
  localBaseUrl: string;
  setLocalBaseUrl: (u: string) => void;
}

// Local published inventory (#2445, epic #2444) — the offline entry point for published projects.
//
// Published projects used to exist in the UI only as live `projectsV2` query results: logged out of
// GitHub, `fetchProjects` never runs and `buildDrafts` drops published hubs, so a published project
// appeared in NEITHER Projects column (and a restored fleet ran with no reachable surface). The
// on-disk hubs already carry everything the column needs — the `.published` marker and the `.title`
// display name — so the published column renders from THIS local selection first, and the GitHub
// records OVERLAY it when the query returns: a hub matched by a fetched board drops out of the local
// list (the board's `ProjectRow` — status/progress/url/counts — is the richer rendering of the same
// project).
//
// Matching mirrors the `mark_published` reconcile in ProjectsList (#922/#2409): a board covers a hub
// when the hub's folder key equals the board's name-derived `projectSlug(title)` (today's keys) or
// the legacy `sanitizeProjectKey(title)` (grandfathered title-keyed hubs), or when the titles match
// case-insensitively.

import { projectSlug, sanitizeProjectKey } from "@/shared/lib/core/projectPaths";
import type { LocalProjectLite } from "@/features/planner/list/drafts";

/** A published hub rendered from the local inventory — key is the identity (the hub folder key). */
export interface LocalPublishedRow { key: string; title: string; updatedAt: number }

/**
 * Select the local published hubs NOT covered by a fetched GitHub board.
 *
 * @param localProjects on-disk hubs from `list_local_projects` (carry `.published` + `.title`).
 * @param ghProjects    the fetched (visible) GitHub boards — empty while logged out / before the
 *                      query lands, so every published hub renders locally until the overlay arrives.
 * @returns local-only published rows, unsorted (caller sorts).
 */
export function buildLocalPublished(
  localProjects: LocalProjectLite[],
  ghProjects: Array<{ title: string }>,
): LocalPublishedRow[] {
  const safeLocals = Array.isArray(localProjects) ? localProjects : [];
  const ghTitles = new Set(ghProjects.map((p) => p.title.toLowerCase()));
  const ghKeys = new Set(ghProjects.flatMap((p) => [projectSlug(p.title), sanitizeProjectKey(p.title)]));
  return safeLocals
    .filter((lp) => lp?.published && !ghKeys.has(lp.key) && !ghTitles.has(lp.title.toLowerCase()))
    .map((lp) => ({ key: lp.key, title: lp.title, updatedAt: lp.updatedAt }));
}

// The top-left "you are here" location crumb (#3036) — the sub-page detail appended after the
// Workspace name (from `registry.ts`) in the titlebar (`App.tsx` → `Titlebar`). Pure + unit-tested so
// EVERY navigable page is reflected, not just a few.
//
// Every workspace's active page IS in the store: an uncontrolled `<Screen>` persists it at
// `activePageTab[pageKey]` (`usePageTabs`), the controlled ones use a dedicated field
// (`projectsPageMode` / `githubTab` / `settingsSection`), and the console uses its own tab array.
//
// The page-label maps below MIRROR each feature's TabItem labels (glance `GLANCE_TABS`, skills
// `SKILL_TABS`, automations `defs`, mcp `tabDefs`, security `agentDefs`, github `GITHUB_TABS`, planner
// `PROJECT_MODES`, settings `SECTIONS`). They live here (not imported) so the shell doesn't reach into
// every feature's internals; an id with no entry Title-Cases gracefully, so a newly-added tab is still
// labeled (never blank), just less pretty than a curated name.

import { workspaceLabel, type Workspace } from "@/app/registry";

/** Title-case a page id as a graceful fallback for an unmapped tab: `hook-analytics` → `Hook Analytics`. */
export function titleCasePageId(id: string): string {
  return id.split(/[-_]/).filter(Boolean).map((w) => w[0].toUpperCase() + w.slice(1)).join(" ");
}

/** Per-workspace page-id → label for the UNCONTROLLED Screens (active id in `activePageTab[pageKey]`). */
const PAGES: Partial<Record<Workspace, Record<string, string>>> = {
  glance:     { network: "Network", fleet: "Fleet" },
  skills:     { library: "Library", lessons: "Lessons", runs: "Runs" },
  automation: { schedules: "Schedules", history: "History", hooks: "Hooks", analytics: "Hook Analytics" },
  mcp:        { installed: "Installed", catalog: "Catalog", analytics: "Analytics" },
  security:   { profiles: "Profiles", assignments: "Assignments", activity: "Activity", flow: "Flow" },
};
/** Planner sub-page (`projectsPageMode`) → label (mirrors `PROJECT_MODES`). */
const PLANNER_PAGES: Record<string, string> = { projects: "Projects", teams: "Teams", designs: "Components", algorithms: "Algorithms", sounds: "Sounds" };
/** GitHub tab (`githubTab`) → label (mirrors `GITHUB_TABS`). */
const GITHUB_TABS: Record<string, string> = { summary: "Summary", projects: "Projects", repos: "Repositories" };
/** GitHub board-drill (`githubBoardTab`) → label. */
const GITHUB_BOARD: Record<string, string> = { board: "Board", roadmap: "Roadmap", issues: "Issues", insights: "Insights" };
/** Settings section (`settingsSection`) → label (mirrors `SECTIONS`). */
const SETTINGS_SECTIONS: Record<string, string> = { general: "General", planner: "Planner", skills: "Skills", automations: "Automations", mcp: "MCP", github: "GitHub", security: "Security" };

/** The `activePageTab` key when it differs from the Workspace key (only automations does). */
const PAGE_KEY: Partial<Record<Workspace, string>> = { automation: "automations" };
/** The default first tab per uncontrolled workspace — so the crumb shows the current page even before
 *  the user has ever selected one (`activePageTab` is empty until the first click). Mirrors each feature's
 *  first `TabItem` id. */
const DEFAULT_PAGE: Partial<Record<Workspace, string>> = {
  glance: "network", skills: "library", automation: "schedules", mcp: "installed", security: "profiles",
};

const label = (map: Record<string, string>, id: string | undefined): string =>
  id ? (map[id] ?? titleCasePageId(id)) : "";

/** The store fields the crumb reads — kept explicit (a subset of `AppStore`) so it's trivially testable. */
export interface CrumbState {
  activeWorkspace: Workspace;
  activePageTab: Record<string, string>;
  /** The navigated ENTITY per graph, keyed by page id (`glance`/`teams`/`designs`/`algorithms`),
   *  reported by each graph via `useCrumbEntity` (#3041). Appended after the page name. */
  crumbEntity: Record<string, string>;
  projectsPageMode: string;
  projectsView: string;
  githubTab: string;
  githubBoardOpen: boolean;
  githubBoardTab: string;
  activeRepoName?: string;
  settingsSection: string;
  /** The active console tab's name (`tabs[activeTabIdx]?.name`). */
  consoleTab?: string;
  focusedAgentName?: string;
}

/**
 * The full "you are here" crumb: the Workspace's canonical name (`registry.ts`) followed by its active
 * PAGE label — and, where meaningful, one more detail (the focused console agent, the GitHub repo, the
 * planning session). Every workspace's page is reflected. Parts are joined with " — ".
 */
export function locationCrumb(s: CrumbState): string {
  const w = s.activeWorkspace;
  const parts: string[] = [workspaceLabel(w)];
  switch (w) {
    case "console":
      if (s.consoleTab) parts.push(s.consoleTab);
      if (s.focusedAgentName) parts.push(s.focusedAgentName);
      break;
    case "glance":
      parts.push(label(PAGES.glance ?? {}, s.activePageTab.glance ?? DEFAULT_PAGE.glance));
      if (s.crumbEntity.glance) parts.push(s.crumbEntity.glance); // the drilled project
      break;
    case "skills":
    case "mcp":
    case "security":
    case "automation":
      parts.push(label(PAGES[w] ?? {}, s.activePageTab[PAGE_KEY[w] ?? w] ?? DEFAULT_PAGE[w]));
      break;
    case "projects":
      parts.push(label(PLANNER_PAGES, s.projectsPageMode));
      if (s.projectsPageMode === "projects") {
        // Inside the Projects tab, a live planning session is a distinct place worth naming.
        if (s.projectsView === "planning") parts.push("Planning");
      } else if (s.crumbEntity[s.projectsPageMode]) {
        // Teams / Components / Algorithms → the entered team, active kit, active language.
        parts.push(s.crumbEntity[s.projectsPageMode]);
      }
      break;
    case "github":
      // A full-page board drill (Board/Roadmap/Issues/Insights) sits OVER the tabs when open.
      parts.push(s.githubBoardOpen ? label(GITHUB_BOARD, s.githubBoardTab) : label(GITHUB_TABS, s.githubTab));
      if (s.activeRepoName) parts.push(s.activeRepoName);
      break;
    case "settings":
      parts.push(label(SETTINGS_SECTIONS, s.settingsSection));
      break;
  }
  return parts.filter(Boolean).join(" — ");
}

// Text-log retention config (#1060). Split from the former store/types monolith (#1634).
/** Retention for the text log streams (#1060). 0 disables a cap. */
export interface LogConfig {
  /** Trim a text log to its newest N lines on enforcement. 0 = no line cap. */
  maxLines: number;
  /** Trim a text log to its newest bytes if it exceeds this many MB. 0 = no size cap. */
  maxSizeMb: number;
}

export const DEFAULT_LOG_CONFIG: LogConfig = {
  maxLines: 10_000,
  maxSizeMb: 20,
};

// In-process log-stream reads (#3630) — the perf-critical replacement for polling the unified log
// streams through the `bsc` bridge, which SPAWNED a `bsc.exe` subprocess per read (`console::bsc`).
// The always-on fleet/console pumps (`useCoordLog`, `useWorkerAutoEnd`, the pane-activity poll) hit
// these every ~1s; at 5–10 spawns/sec the Tauri invoke backlog grew without bound and the app froze.
// These native commands (`observability::logs::logs_*`) read the SAME files in-process via the `logs`
// crate — a file read, not a process — so the hot polls stop saturating the backend.
//
// Same JSON shape the `bsc logs …` subcommands emitted (the native commands return the same serde
// types), so these are drop-ins for the prior `bscJson(null, ["logs", …])` calls. Low-frequency
// `bsc logs …` reads (cost, analytics one-shots) stay on the `bsc` bridge.

import { safeInvoke } from "@/shared/lib/core/safeInvoke";

/** One pane's latest turn-boundary state — the `logs::PaneActivity` shape (`bsc logs pane-activity`). */
export interface PaneActivityRow {
  pane: string;
  state: string;
  at: number;
}

/**
 * Newest `limit` raw lines of a unified log stream (`coord`/`audit`/`skill`/`hook`/`mcp`/`ui`/…),
 * read in-process. `oldest` keeps chronological (oldest-first) order — pass `true` for the coord/ui
 * logs the replayers walk forward. An unknown/missing stream resolves to `fallback` (default `[]`);
 * pass `null` where a caller must distinguish "read failed → skip this tick" from an empty log.
 */
export function logsTail(stream: string, limit: number, oldest?: boolean): Promise<string[]>;
export function logsTail<F>(stream: string, limit: number, oldest: boolean, fallback: F): Promise<string[] | F>;
export function logsTail(stream: string, limit: number, oldest = false, fallback: unknown = []): Promise<unknown> {
  return safeInvoke("logs_tail", { stream, limit, oldest }, fallback);
}

/** The latest turn-boundary state per pane (`run`/`idle`), newest pane first — `bsc logs pane-activity`.
 *  Generic `T` lets a caller keep its own row type; the wire shape is always `{ pane, state, at }`. */
export function logsPaneActivity<T = PaneActivityRow>(): Promise<T[]> {
  return safeInvoke<T[]>("logs_pane_activity", undefined, []);
}

/** The deduped set of panes that self-reported `done` (#1379), newest first — `bsc logs done-panes`. */
export function logsDonePanes(): Promise<string[]> {
  return safeInvoke<string[]>("logs_done_panes", undefined, []);
}

/**
 * The canonical stream key for a read alias — mirrors Rust `logs::canonical_stream`. The UI reads a few
 * streams by alias (`audit`→`tool`, `skills`→`skill`); everything else is already canonical. Used to
 * line a read alias up with the backend's `logs://<canonical>` change event (#3638), so a subscriber
 * never misses an emit because it named the stream differently than the watcher did.
 */
export function canonicalStream(alias: string): string {
  switch (alias) {
    case "audit":
    case "tools":
      return "tool";
    case "skills":
      return "skill";
    default:
      return alias;
  }
}

/** The Tauri event the backend log watcher (`observability::log_watch`) emits when `stream` changes —
 *  the event `useLogStream` subscribes to. Accepts a read alias (canonicalized). MUST stay in sync with
 *  the Rust `event_name` (#3638). */
export function logEventName(stream: string): string {
  return `logs://${canonicalStream(stream)}`;
}

// manifest.ts — the introspectable registry of the shared UI kit (#2060).
//
// A serialisable catalogue of every composable primitive and its prop schema, so an agent (or the
// in-app visual editor, v1.0.5) can ENUMERATE and COMPOSE the kit instead of hand-writing JSX. This
// module is pure data — no React, no component references — so it can be shipped to JSON verbatim
// (`manifestJson()`). The runtime render-map that turns a `PrimitiveName` back into a component lives
// alongside it in `registry.tsx`; a `PrimitiveName` union keeps the two in sync at compile time (the
// registry is a `Record<PrimitiveName, …>`, so a missing/extra component is a type error).
//
// Adding a primitive: add its name to `PrimitiveName`, a spec here, and a row in `registry.tsx`.
// The `manifest.test.ts` sync test then guards that the three stay aligned.
//
// Consciously EXCLUDED from the kit (#2421): `overlay/promptDialog` (usePromptDialog /
// useConfirmDialog) — an imperative hook API (an async fn + a `dialog` node to render), not a
// composable primitive; a builder cannot instantiate a hook from a manifest node. Compose the
// registered `Dialog` instead.

// The authored-motion shape (#2867, epic #2865) — carried through to each emitted `ComponentRecord`'s
// `animations` and compiled to live `@keyframes` by the render engine (`@/shared/ui/kit`). Imported
// type-only (erased at compile time) so this module stays pure, JSON-serialisable data.

/** Every primitive the kit exposes to the builder. Also the key type of the render-map registry. */
export type PrimitiveName =
  // layout
  | "Box" | "Stack" | "Row" | "Spacer" | "Slot" | "Grid" | "SectionHeader" | "SectionLabel" | "Dialog" | "ModalScrim" | "ModalCard"
  // typography
  | "Text"
  // controls
  | "Button" | "IconButton" | "Checkbox" | "Toggle" | "SegmentedControl" | "TextField" | "TextArea" | "SelectField" | "Option"
  | "BackButton" | "ColorSwatch" | "ConfirmButton"
  // data
  | "Card" | "Chip" | "StatTile" | "FillBar" | "Code"
  | "Avatar" | "IconBox" | "CardListRow" | "DataTableRow" | "RoleTierChips"
  // data · charts (analytics primitives)
  | "StatCard" | "LineArea" | "Bars" | "Donut" | "HBars" | "Swimlane" | "Spark" | "Legend" | "StackedDayBars"
  // feedback
  | "Banner" | "InlineError" | "EmptyState" | "StatusDot" | "Skeleton" | "PageBoundary"
  // #2421 gap-fill — data chips/feeds, the overlay pane, and the telemetry chart trio
  | "LabelChip" | "ActivityFeed" | "Pane" | "TelemetryPanel" | "ItemBars" | "SplitBar"
  // #2475 — the key-value record rendering (the property-list archetype of the row vocabulary)
  | "KeyValueList"
  // layouts — the page-skeleton templates tier (#2197)
  | "MasterDetail" | "SplitView" | "GraphCanvas" | "PaneGrid" | "Tree" | "Sequence"
  // pages — the complete data-driven page compositions tier (#2505)
  | "TablePage" | "TreeExplorerPage" | "PipelinePage" | "NetworkPage" | "DashboardPage" | "CollectionPage" | "RecordPage";

export type PrimitiveGroup = "layout" | "typography" | "controls" | "data" | "feedback" | "layouts" | "pages";

/** The kind of a prop's value — drives how a builder renders an editor control for it. */
export type PropType =
  | "string"
  | "number"
  | "boolean"
  | "enum"      // a fixed set of string values (see `values`)
  | "node"      // ReactNode / slot
  | "function"  // event handler / callback
  | "style"     // a CSSProperties object
  | "array"     // a list of structured items (see `note`)
  | "object"    // a single structured object (shape in the description)
  | "space"     // a spacing rung (SPACE_RUNGS) or a raw px number
  | "fontSize"  // a type rung (FONT_RUNGS) or a raw px number
  | "tracks"    // grid tracks: a number → repeat(n, 1fr), or a template string
  | "color";    // a CSS color / design token string

/** The spacing rungs (`--sp-*`) a `space`-typed prop accepts by name; raw px is also legal. */
export const SPACE_RUNGS = ["xs", "sm", "md", "lg", "xl"] as const;
/** The type-scale rungs (`--fs-*`) a `fontSize`-typed prop accepts by name; raw px is also legal. */
export const FONT_RUNGS = ["xxs", "xs", "sm", "md", "lg", "xl"] as const;

export interface PropSpec {
  name: string;
  type: PropType;
  /** True for props the component cannot render without. */
  required?: boolean;
  /** Allowed values for `type: "enum"` (and the semantic set for tone-like props). */
  values?: readonly string[];
  /** The default the component applies when the prop is omitted. */
  default?: string | number | boolean;
  description: string;
}

export interface PrimitiveSpec {
  name: PrimitiveName;
  group: PrimitiveGroup;
  /** The `@/…` import specifier the component is exported from. */
  importPath: string;
  description: string;
  props: PropSpec[];
  /** True when arbitrary extra DOM props (className, style, data-attrs, handlers) pass through to the root. */
  passthrough?: boolean;
  /** MOTION references (#2942, #3451) — the NAMES of the animations this primitive plays. The full
   *  defs live in the `base` kit's motion library (`shared/ui/kit/baseAnimations.ts`), NOT here: a base
   *  motion is owned in ONE place and every consumer references it by name, so an edit propagates to all
   *  (the resolver falls back to the `base` kit — `resolveComponentAnimationDefs`). Emitted verbatim onto
   *  the generated `ComponentRecord.animations`. Absent ⇒ no motion. */
  animations?: string[];
}

// Shared prop fragments reused across the layout primitives.
const GAP: PropSpec = { name: "gap", type: "space", description: "Gap between children — a rung (xs…xl) or raw px." };
const ALIGN = (dflt: string): PropSpec => ({ name: "align", type: "enum", values: ["start", "center", "end", "baseline", "stretch"], default: dflt, description: "Cross-axis alignment." });
const JUSTIFY: PropSpec = { name: "justify", type: "enum", values: ["start", "center", "end", "between", "around", "evenly"], description: "Main-axis distribution." };
const WRAP: PropSpec = { name: "wrap", type: "boolean", description: "Allow children to wrap onto multiple lines." };
const PAD: PropSpec = { name: "pad", type: "space", description: "Inner padding — a rung/px, or a [block, inline] pair." };
const INLINE = (kind: string): PropSpec => ({ name: "inline", type: "boolean", description: `Render as inline-${kind} instead of ${kind}.` });
const CHILDREN: PropSpec = { name: "children", type: "node", required: true, description: "Content." };

// Shared prop fragments for the Pages tier (#2505) — the titled header bar + the house selection idiom.
const PAGE_TITLE: PropSpec = { name: "title", type: "node", required: true, description: "Page title (the header bar)." };
const PAGE_HINT: PropSpec = { name: "hint", type: "node", description: "Dimmed inline hint after the title." };
const PAGE_TOOLBAR: PropSpec = { name: "toolbar", type: "node", description: "Right-aligned header controls (search, filters, actions)." };
const SELECTED_ID = (what: string): PropSpec => ({ name: "selectedId", type: "string", description: `Controlled selection — the selected ${what} id (pair with onSelect). Omit for uncontrolled.` });
