}

export interface ComponentRecord {
  id: string;
  name: string;
  kitId: string;
  role: Role;
  /** The component's FOLDER PATH within the kit (#3048/#3579) — a nested, `/`-delimited path
   *  (`shared/ui/controls`, `features/github`) that organizes the kit like a completed project's
   *  folders, DERIVED from `src` (`folder_from_src`, shared with the algorithms library since #4107;
   *  the harvest seeds it and `bsc ui refolder` re-derives it for the whole store). ORTHOGONAL to
   *  {@link role} (the architectural tier that drives the composition swimlanes): `folder` answers
   *  "where does this live in the project",
   *  `role` answers "what tier is it". ORGANIZATIONAL only — `composes` still resolves across the WHOLE
   *  kit, so components in DIFFERENT folders compose freely (kits never cross). Absent ⇒ the kit's
   *  trailing "unfoldered" bucket (`kitGroups.ts`). OPTIONAL and NEVER defaulted — like
   *  {@link Kit.tech}/`style`, an absent `folder` must stay absent (never `""`) so a store copy keeps
   *  hashing to its recorded `seedHash` and the #2483 reconcile can refresh it. */
  folder?: string;
  version: string;
  /** Times this component is used across the codebase (a reuse signal). */
  used: number;
  tags: string[];
  /** Named visual/behavioral variants (the preview + generate loop cycle these). */
  variants: string[];
  /** Names of the components this one composes (its dependencies). */
  composes: string[];
  props: PropSpec[];
  whenUse: string[];
  whenNot: string[];
  /** Source file path (shown above the source). */
  src: string;
  /** Representative source text — a short USAGE snippet (`import { Card } … <Card>…</Card>`), NOT the
   *  implementation. For the emittable implementation see {@link source}. */
  srcText: string;
  /** The component's verbatim implementation source (#2794) — the actual `.tsx` file contents, bundled
   *  into the packaged kit ARTIFACT at generation time so `bsc ui … emit` (the vendored-source
   *  distribution, epic #2793) has real code to write. Distinct from the usage-snippet {@link srcText}.
   *  Present only in the packaged/released kit artifact, NOT in the mutable component store (the seed +
   *  `bsc ui set` write-through deliberately omit it — the store is a contract catalog); absent ⇒ a
   *  component with no standalone source file (a pure stub). */
  source?: string;
  /** A packaged built-in (re-seeded into the store on hydrate). Absent ⇒ user-authored. */
  builtin?: boolean;
  /** The component's analytics EVENTS manifest (#3810, epic #3809) — the events it emits, as DATA (not
   *  code): a Button declares `click`, a CollectionPage `item_selected`/`filter_changed`. The per-node
   *  instrumentation CONTRACT, sibling of the behavior/motion a node carries, so an app composed from
   *  these nodes is instrumented by construction. Absent/empty ⇒ uninstrumented — the `no-analytics` doctor
   *  finding flags an INTERACTIVE component that lacks one. A shipped runtime does the emitting (slice 2). */
  analytics?: AnalyticsEvent[];
  /** The component's TESTS (#3878) — carried as data on the node, like its analytics manifest. Absent/empty
   *  ⇒ untested, which the `no-tests` doctor finding flags for a node that HAS an implementation (a
   *  spec-only node is skipped: it already earns `no-implementation`, and one cause should not raise two
   *  findings). What EXECUTES a graph-held test is deliberately still open — vitest reads files, so either
   *  the graph emits them at test time or a runner compiles them the way the component loader does. */
  tests?: ComponentTest[];
  /** A SUPPRESSION tombstone (#3725) — `true` marks this id as a PERMANENTLY removed packaged builtin, not
   *  a real component. `reconcileSeed` skips re-seeding it (the tombstone occupies the id) and the library
   *  excludes it; the Rust doctor skips it; `bsc ui suppress`/`unsuppress` write/clear it. Absent on every
   *  real record. */
  suppressed?: boolean;
  /** WHAT replaced this retired builtin (#a-tombstone-can-name-what-superseded-it) — the id named by
   *  `bsc ui suppress <id> --superseded-by <new-id>`. Only ever set alongside `suppressed`.
   *
   *  It lives on the TOMBSTONE because the tombstone is the one record `reconcileSeed` never overwrites,
   *  so the fact outlives every hydrate — which is exactly what a consolidation (45 card wrappers into
   *  composed widgets) needs to stay readable months later. The CLI refuses a dangling or self pointer,
   *  so a value here always names a record that existed at the time it was written. */
  supersededBy?: string;
  /** LITE record (#4072) — hydrated from `bsc ui list --graph`, so it carries only what the graph
   *  renders: the node card + `composes`. Its `srcText`/`props`/`variants` are EMPTY DEFAULTS, not
   *  real values.
   *
   *  It exists so the Studio page can paint off a 33 KB read instead of blocking up to 8s on the
   *  1.72 MB `--full` one. The marker is load-bearing rather than cosmetic: without it an empty
   *  `srcText` is indistinguishable from a component that genuinely has none, so the preview would
   *  claim "no implementation source yet" and the build scan would silently skip every component.
   *  Cleared when the full read lands and replaces the record. */
  lite?: boolean;
  /** The raw intrinsic this component REPLACES (`"button"`, `"input"`) — the authoring hint that
   *  derives the flagship anti-duplication lint rule ("use <Name> not a raw <wraps>"). Absent ⇒ none. */
  wraps?: string;
  /** The registered PLATFORM module specifier this graph component OVERRIDES (#3660, epic #3604) — e.g.
   *  `@/shared/ui/layout/Spacer`. When present, the runtime loader vendors THIS component's `srcText` in
   *  place of the bundled module wherever a graph component imports that specifier, so a shared/ui
   *  primitive renders from the graph (DATA) rather than code. Absent ⇒ the component provides no platform
   *  override (a normal graph component, imported only as a `@/components/<id>` sibling). Graph-first with a
   *  code fallback: an unmatched specifier stays external (→ the registry), exactly as before. */
  provides?: string;
  /** WHY this record's body deliberately differs from the file its {@link src} names — or why it has no
   *  {@link src} at all (`record-src-reconcile`).
   *
   *  A record and its file disagree far more often than they are out of sync, and almost always ON PURPOSE:
   *  a record is mounted by the Design Studio with NO props, so it gives its parameters demo defaults (and
   *  often loading/error states) that the file — always called with real props — has no use for. Absent the
   *  reason, the next sweep reads that as staleness and "refreshes" the record from the file, discarding
   *  the richer copy. So the reason lives HERE, on the record, where a sweep reads it — never only in a
   *  commit message. Present ⇒ the reconcile reports the record as `intentional` rather than `drifted`.
   *
   *  Reasons written by `scripts/reconcile-record-src.cjs --annotate` carry a trailing marker naming the
   *  script, which is what lets a re-run refresh its OWN wording without ever clobbering a hand-written one. */
  srcDivergence?: string;
  /** The file this record USED to be backed by, once that file has been retired (`record-src-reconcile`).
   *
   *  A migrated page's file is deleted when the record supersedes it, at which point {@link src} must go
   *  null — a pointer to a file that is not there makes `bsc ui backing` answer "not backed" for paths it
   *  genuinely cannot see (#4223). But nulling alone throws away WHICH file this record came from, which is
   *  the one fact a later reader needs to check the record against history. So the path moves here rather
   *  than being dropped: `src` null says "no live file backs this", `srcRetired` says "and here is what
   *  used to". Never set alongside a live {@link src}. */
  srcRetired?: string;
  /** What KIND of page this record is, when {@link role} is `"page"` (shadow-catalogue-guard-over-reaches).
   *
   *  `role: "page"` was doing two jobs. Twelve records are APP SCREENS the shell navigates to — the shadow
   *  catalogue pairs each with its file and `lazyWorkspaces.tsx` says whether it renders from the graph or
   *  the file. Ten more are page-shaped KIT COMPOSITIONS: the shared Pages tier (#2505 — CollectionPage,
   *  TablePage, RecordPage, DashboardPage, PipelinePage, TreeExplorerPage), the `KeptMountedPage` wrapper,
   *  and the `TelemetryGalleryPage` / `TeamsPage` galleries. They have no workspace and no host feature, so
   *  a catalogue entry for one could never be filled in — its `ensurePlatform` would import nothing.
   *
   *  `"kit"` says so ON THE RECORD, which is the point: the alternative was excluding them from the guard
   *  by id, and the next kit page would have joined that list silently. Absent ⇒ an app screen, and (like
   *  `provides` / `themeSystem`) an absent value must stay ABSENT rather than be defaulted, so a store copy
   *  keeps hashing to its `seedHash`. */
  pageKind?: "kit";
  /** Which THEME SYSTEM this component renders under (#3715). `"css"` (default, absent) — the component
   *  consumes the theme through the CSS cascade (`--card-*` etc. resolved by `:root` / `<ThemeScope>`), as
   *  every component does today. `"js"` — the component renders to a NON-CSS surface (canvas / WebGL / a
   *  non-web runtime) that can't see the cascade, so the runtime loader wraps it in a `<ThemeProvider>` and
   *  it reads the resolved token VALUES via `useResolvedTheme()`. Opt-in + inert like {@link provides}: an
   *  absent / `"css"` value is byte-identical to today, and (like `group`/`provides`) an absent value must
   *  stay absent — never defaulted to `"css"` — so a store copy keeps hashing to its `seedHash`. */
  themeSystem?: "css" | "js";
  /** Author-declared lint rules this component contributes to its kit's preset (in addition to the
   *  ones derived from `wraps`). Absent ⇒ none. */
  rules?: KitRule[];
  /** The data shapes this component is an IDEAL rendering for (#2475) — the axis `bsc ui shapes` /
   *  `bsc ui list --shape` picks layouts by. Meaningful on layout-role components and the
   *  data-rendering composites (rows, feeds, property lists); absent ⇒ not shape-indexed (chrome,
   *  controls, chrome-level layouts that host arbitrary panes rather than render a data collection). */
  shapes?: DataShape[];
  /** The renderable STRUCTURE of a `page`/`layout`-role component as a validated data tree (#3569),
   *  rendered by `KitRenderer`. This is what makes a page's skeleton editable IN THE GRAPH: the host
   *  (e.g. `Fleet.tsx`) renders the store node's `spec` — its hand-authored const is only the
   *  seed/fallback — so editing the node in the Design Studio reflects on the real page. Absent ⇒ the
   *  component has no data-tree layout (a leaf primitive, or a page not migrated to a spec yet). */
  spec?: GeneralNode;
  /** Content hash of the seed copy this record came from (#2483) — see {@link Kit.seedHash}. */
  seedHash?: string;
  /** MOTION binding (#2942/#3065) — each entry is EITHER a kit-animation NAME (resolved from the owning
   *  {@link Kit}'s `animations` library — SHARED/reusable motion the kit owns) OR an INLINE def (a full
   *  {@link KitAnimation} object used directly — COMPONENT-SPECIFIC one-off motion, e.g. a d3-chart
   *  draw-in or a component-scoped `selector` animation not worth lifting to the kit). Resolved by
   *  {@link resolveComponentAnimations}. Absent ⇒ no motion. */
  animations?: (string | KitAnimation)[];
  /** Provenance stamp (#3164) — the store bumps `rev` and records who/when on every write. Absent on a
   *  legacy record never written since the stamp landed (reads as rev 0). */
  rev?: number;
  updatedAt?: string;
  updatedBy?: string;
  /** Change history (#3568) — one capped entry per write, stored NEWEST-LAST. `bsc ui log <id>` reads
   *  them newest-first; the inspector's History tab renders them. Absent ⇒ never written since #3568. */
  history?: ChangeEntry[];
}

/** The shared zero-state title — Design Studio and the Planner Components pane must say the same
 *  thing about the same empty library (#2420). */
export const NO_COMPONENTS_TITLE = "No components yet";

/** Role → accent color, mapped to app design tokens (not the prototype's raw palette). */
export const ROLE_COLOR: Record<Role, string> = {
  primitive: "var(--info)",
  composite: "var(--accent)",
  layout: "var(--violet)",
  page: "var(--success)",
  service: "var(--state-wait)",
};

/** Does a component match a free-text query (name / role / folder / tag, case-insensitive)? The `group`
 *  folder path (#3579) matches too, so a query like `charts` or `features/github` filters the rail to a
 *  folder. Empty query → all. */
export function matchesQuery(c: ComponentRecord, query: string): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return (
    c.name.toLowerCase().includes(q) ||
    c.role.includes(q) ||
    (c.folder ?? "").toLowerCase().includes(q) ||
    c.tags.some((t) => t.toLowerCase().includes(q))
  );
}

/** The components `c` composes, each paired with its resolved record (or `undefined` if not in the kit). */
export function resolveComposes(
  c: ComponentRecord,
  all: ComponentRecord[],
): { name: string; comp?: ComponentRecord }[] {
  return c.composes.map((name) => ({ name, comp: all.find((x) => x.name === name) }));
}

/** The components that compose `c` (its "used by" set). */
export function resolveUsedBy(c: ComponentRecord, all: ComponentRecord[]): ComponentRecord[] {
  return all.filter((x) => x.composes.includes(c.name));
}

/** Is `e` a valid INLINE animation def (#3065) — a full {@link KitAnimation} object carried directly on
 *  a component (component-specific one-off motion), as opposed to a NAME string that resolves from the
 *  kit's shared library? Requires a non-null object with a non-empty string `name` AND a non-null object
 *  `keyframes`, so a malformed object is DROPPED rather than compiled into junk CSS. */
function isInlineAnim(e: unknown): e is KitAnimation {
  const a = e as KitAnimation | null;
  return (
    typeof a === "object" &&
    a !== null &&
    typeof a.name === "string" &&
    a.name.length > 0 &&
    typeof a.keyframes === "object" &&
    a.keyframes !== null
  );
}

/** Resolve EVERY animation a component binds (#2942/#3065) into the flat, kit-scoped {@link AnimationDef}s
 *  — the FULL set, with ALL {@link KitAnimation.group} variations kept (both the default and its
 *  alternatives). Each entry is EITHER a NAME — looked up in the owning kit's `animations` library
 *  (shared/reusable motion) — OR an INLINE def (a full {@link KitAnimation} object used directly, for
 *  component-specific one-off motion). Names that don't resolve, and malformed inline objects, are
 *  dropped. It does NOT bail when the kit's library is empty (an inline-only component must still
 *  resolve); every resolved def is stamped with the component's `kitId`, preserving first-appearance
 *  order. Empty when the component binds nothing. Pure (React-free). This is what the right-pane
 *  AnimationsMenu lists so the user can see + switch each slot's variations; the RENDER path
 *  ({@link resolveComponentAnimations}) narrows it to the one-per-group set that actually plays.
 *
 *  CROSS-KIT (#3451): a NAME the component's own kit doesn't define falls back to the shared `base`
 *  kit's library — the app's foundational motion (`lift`/`fade-in`/`pulse`) is owned there once and
 *  REFERENCED by every kit, so editing it propagates to all of them. A base-resolved def keeps
 *  `kit: BASE_KIT_ID` (it is NOT restamped to the consumer): that field names both the compiled
 *  `@keyframes bsc-base-<name>` and the `.base-anim-<name>` hook the preview stamps, so every consumer
 *  shares ONE keyframes block instead of duplicating it per kit. A kit's OWN def always wins, so a kit
 *  can still override a base motion by declaring the same name. */
export function resolveComponentAnimationDefs(comp: ComponentRecord, kits: Kit[]): AnimationDef[] {
  const entries = comp.animations ?? [];
  if (!entries.length) return [];
  const own = new Map((kits.find((k) => k.id === comp.kitId)?.animations ?? []).map((a) => [a.name, a] as const));
  const base =
    comp.kitId === BASE_KIT_ID
      ? null
      : new Map((kits.find((k) => k.id === BASE_KIT_ID)?.animations ?? []).map((a) => [a.name, a] as const));
  const out: AnimationDef[] = [];
  for (const e of entries) {
    if (typeof e === "string") {
      const mine = own.get(e);
      if (mine) { out.push({ ...mine, kit: comp.kitId }); continue; }
      const shared = base?.get(e);
      if (shared) out.push({ ...shared, kit: BASE_KIT_ID });
      continue;
    }
    if (isInlineAnim(e)) out.push({ ...e, kit: comp.kitId });
  }
  return out;
}

/** Resolve an animation by NAME to its playable def (#3071) — the SELECTED component's OWN animations
 *  first (inline defs + resolved kit refs, all variations), then the kit's generic shelf. This is what
 *  the preview's TRY-ON uses, so clicking a component animation replays it; a kit-only lookup misses the
 *  now-inline component animations (the kit library is empty after the component-owned migration) → no
 *  `extraAnimation` → no rebuild-key change → no replay. Returns `null` when nothing matches. Pure. */
export function resolveNamedAnimation(
  comp: ComponentRecord | null,
  kit: Kit | undefined,
  kits: Kit[],
  name: string,
): AnimationDef | null {
  if (!name) return null;
  const own = comp ? resolveComponentAnimationDefs(comp, kits) : [];
  const shelf = kit ? (kit.animations ?? []).map((a) => ({ ...a, kit: kit.id })) : [];
  // #3451: the shared `base` shelf is reachable from EVERY kit. react-ui's own library is empty now
  // (its base motions moved to `base`), so without this a base motion could not be tried on at all.
  const baseShelf =
    kit?.id === BASE_KIT_ID
      ? []
      : (kits.find((k) => k.id === BASE_KIT_ID)?.animations ?? []).map((a) => ({ ...a, kit: BASE_KIT_ID }));
  return [...own, ...shelf, ...baseShelf].find((x) => x.name === name) ?? null;
}

/** The animations the render-preview should COMPILE. A try-on ISOLATES the clicked animation — the
 *  preview plays ONLY it, so clicking each animation in the menu previews THAT one; with no try-on the
 *  component's full bound motion plays. (#3075: before, the try-on was APPENDED to the full bound set,
 *  so every click compiled the identical set and the preview never changed — "always the same one".)
 *  Pure (React-free). */
export function previewAnimDefs(boundDefs: AnimationDef[], tryOn: AnimationDef | null | undefined): AnimationDef[] {
  return tryOn ? [tryOn] : boundDefs;
}

/** Resolve a component's MOTION bindings into the flat, kit-scoped {@link AnimationDef}s that ACTUALLY
 *  PLAY (#2942/#3065/#3069) — the set the render engine compiles. Resolves every binding
 *  ({@link resolveComponentAnimationDefs}), then applies VARIATION selection (#3069): a def with NO
 *  {@link KitAnimation.group} always plays (unchanged); defs sharing a `group` are alternatives of ONE
 *  slot and only ONE plays — the one marked {@link KitAnimation.default}, else the FIRST in appearance
 *  order — occupying the group's first-appearance position (so switching the slot default never reorders
 *  the played set). First-appearance order is preserved. A component whose bindings carry NO `group`
 *  (today's data) resolves to exactly the same list as before — zero regression. Pure (React-free). */
export function resolveComponentAnimations(comp: ComponentRecord, kits: Kit[]): AnimationDef[] {
  const resolved = resolveComponentAnimationDefs(comp, kits);
  // The playing def per group: the one marked `default`, else the first seen (appearance order).
  const chosen = new Map<string, AnimationDef>();
  for (const d of resolved) {
    if (!d.group) continue;
    const cur = chosen.get(d.group);
    if (!cur || (d.default && !cur.default)) chosen.set(d.group, d);
  }
  // Emit in first-appearance order: an ungrouped def as-is; a group ONCE, at its first slot, holding its pick.
  const out: AnimationDef[] = [];
  const emitted = new Set<string>();
  for (const d of resolved) {
    if (!d.group) { out.push(d); continue; }
    if (emitted.has(d.group)) continue;
    emitted.add(d.group);
    out.push(chosen.get(d.group)!);
  }
  return out;
}

/** The ACTIVE animation defs of the siblings a component COMPOSES (#3130) — pair each rendered import
 *  with its motion. For every name in `comp.composes`, find that same-kit component in `comps` and take
 *  its {@link resolveComponentAnimations} (the one-per-group active set). Each composed def is NAMESPACED
 *  by its owning sibling (#3163, `AnimationDef.component = sib.name`) so two composed pieces that name an
 *  animation the same (`draw-in`) compile to DISTINCT keyframes instead of one clobbering the other; a
 *  genuinely SHARED animation (byte-identical content across siblings — a kit's chart primitives all using
 *  the same `fade-in`) still contributes exactly ONCE (deduped by content, not by name). The preview
 *  UNIONS these with the component's own motion — the composed pieces (a chart's ChartFrame / Axis) then
 *  animate in too, not just the top component's own marks. Composes nothing ⇒ `[]`. Pure (React-free). */
export function resolveComposedAnimations(
  comp: ComponentRecord,
  comps: ComponentRecord[],
  kits: Kit[],
): AnimationDef[] {
  const byName = new Map(comps.map((c) => [c.name, c] as const));
  const seen = new Set<string>();
  const out: AnimationDef[] = [];
  for (const name of comp.composes) {
    const sib = byName.get(name);
    if (!sib || sib.kitId !== comp.kitId) continue;
    for (const def of resolveComponentAnimations(sib, kits)) {
      // Dedup by CONTENT (the def sans-`component`), so a shared animation across siblings contributes
      // once — but keep two DIFFERENT animations that merely share a name (they'll be namespaced apart).
      const key = JSON.stringify(def);
      if (seen.has(key)) continue;
      seen.add(key);
      out.push({ ...def, component: sib.name });
    }
  }
  return out;
}

/** The canonical motion PRESET group (#3083). A component's motion is presented as a pick-one list of
 *  PRESETS — each binding is a composed alternative and only the chosen one plays. Folding every inline
 *  binding into ONE group makes "the entire component's animation" a single selectable value. */
export const MOTION_PRESET_GROUP = "motion";

/** Rewrite a component's `animations` so `name` becomes the ACTIVE preset (#3083): every INLINE def joins
 *  {@link MOTION_PRESET_GROUP} and the def named `name` is its `default`, so it's the ONE that plays
 *  ({@link resolveComponentAnimations} emits one-per-group). NAME-ref entries (strings) are left as-is —
 *  a shared-motion binding carries no component-level default. Pure; the studio persists the result. */
export function selectAnimationPreset(
  animations: (string | KitAnimation)[],
  name: string,
): (string | KitAnimation)[] {
  return animations.map((e) =>
    typeof e === "string" ? e : { ...e, group: MOTION_PRESET_GROUP, default: e.name === name },
  );
}

// Shared LLM-model catalog (#…) — the single source of truth for the console's selectable model
// tiers, so the console (PaneMenu / PaneShell), Settings, and the planner's Permissions stage all
// reference one list instead of duplicating it. Each id maps to a Claude CLI tier alias at launch
// (`opus-4.5` → `claude --model opus`), so a tier tracks the latest model in that family.
import modelsEmbedded from "@data/console/models.json";
import modelDefaultsEmbedded from "@data/console/model-defaults.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

/** A selectable model tier. The trailing version is cosmetic — the harness maps it to a CLI tier
 *  alias (`opus`/`sonnet`/`haiku`), which always resolves to the latest model in that tier. */
export type ModelId = "haiku-4.5" | "sonnet-4.5" | "opus-4.5";

export interface ModelOption {
  id: ModelId;
  /** One-word character of the tier (fast / balanced / deep). */
  tone: string;
  /** Relative-cost glyph. */
  price: string;
}

// The tier DATA is externalized to `@data/console/models.json` (#2146, epic #2027 tail) — editable
// without touching code + part of the exportable config bundle; the config-dir copy (#2047) overlays
// the embedded default via `overlayFile`. This module keeps the TYPES + accessor/derivation helpers.
/** The model tiers offered in the UI, cheapest → most capable. */
export const MODELS: ModelOption[] = overlayFile("console/models.json", modelsEmbedded as ModelOption[]);

export const MODEL_IDS: ModelId[] = MODELS.map((m) => m.id);

/** The default per-pane tier (the store's `defaultModel` seed + PaneShell's fallback), sourced from
 *  `@data/console/model-defaults.json` (#2416) — ONE default instead of scattered `"sonnet-4.5"`
 *  literals. Falls back to the catalog's middle tier if a config-dir edit names an unknown tier. */
export const DEFAULT_MODEL_ID: ModelId =
  MODEL_IDS.find((id) => id === overlayFile("console/model-defaults.json", modelDefaultsEmbedded).defaultTier) ??
  MODEL_IDS[Math.floor(MODEL_IDS.length / 2)];

/** The bare tier name a ModelId maps to ("opus-4.5" → "opus") — also the CLI alias. */
export function modelTier(id: ModelId): string {
  return id.split("-")[0];
}

/** Resolve a tier name back to its ModelId ("opus" → "opus-4.5"); undefined for an unknown tier. */
export function tierToModelId(tier: string): ModelId | undefined {
  return MODELS.find((m) => modelTier(m.id) === tier)?.id;
}

// The runtime module registry (#3605, epic #3604) — the bridge that lets graph-loaded code run INSIDE the
// live app instead of in the preview's isolated sandbox.
//
// A component loaded from the components graph is real React source with real imports — `import { useApp
// Store } from "@/store"`, `import { jsx } from "react/jsx-runtime"`. For its hooks to fire and its store
// reads to be LIVE, those imports must resolve to the app's OWN running modules — the SAME React instance
// (a second copy silently breaks hooks: "Invalid hook call") and the SAME Zustand store. This registry is
// how: the shell registers each platform module by its import specifier at boot, and the loader's runtime
// `require` reads them back here. Everything NOT registered is either a graph sibling (loaded from the
// graph) or an honest "unresolved platform module" error — never a stub.
//
// Pure + framework-free (a Map) so it's unit-testable and has no import cycle with the shell.

const registry = new Map<string, unknown>();

/** Register the app's LIVE module for an import specifier (e.g. `"react"`, `"@/store"`). Idempotent —
 *  a re-register replaces (an HMR re-eval must not double up). */
export function registerAppModule(specifier: string, mod: unknown): void {
  registry.set(specifier, mod);
}

/** The registered live module for a specifier, or `undefined` if none — the loader's `require` lookup. */
export function resolveAppModule(specifier: string): unknown | undefined {
  return registry.get(specifier);
}

/** Is this specifier backed by a real app module? Drives the loader's import classification. */
export function isAppModule(specifier: string): boolean {
  return registry.has(specifier);
}

/** Every registered specifier — for diagnostics + a loader error that names what IS available. */
export function registeredSpecifiers(): string[] {
  return [...registry.keys()].sort();
}

/** Clear the registry (tests only — the app registers once at boot and never clears). */
export function __resetRegistry(): void {
  registry.clear();
}

// The Glance morph GRID (#3361, directional placement #3367) — pure, React-free geometry + placement
// for the in-graph terminal morphs, so the layout is unit-testable without rendering a terminal.
//
// THE MODEL: morphs stay IN the graph (a node grows into its live session in place — that is the whole
// point of the morph, #2534). What changes is that a morph no longer free-floats at its own node's
// coords, where two open morphs would sit on top of each other. Instead each occupies a discrete cell of
// a lattice, so non-overlap is guaranteed by construction rather than by a soft push-apart relaxation.
//
// THE FIRST OPENED NODE DEFINES THE GRID. Its morph lands exactly where a single morph lands today —
// centred on its own node — and that box becomes cell (0,0). The origin is derived from the ANCHOR NODE
// (an id) rather than frozen as raw coords, so the grid tracks the graph if the layout recomputes (the
// live-status overlays rebuild the model every poll).
//
// THE LATTICE IS SIGNED (#3367). Cells extend every way from the anchor — (-1,0) is one cell LEFT,
// (0,-1) one cell UP.
//
// PLACEMENT IS UNIFORMITY-FIRST, DIRECTION SECOND (#3525). #3367 placed each node in the free cell whose
// direction from the anchor best matched its node's direction. That kept a lone node on its own side but
// let the block spread into a sparse, non-square arrangement — three left-hand nodes could sit in a
// 1×3 column with gaps rather than collapsing into a tight tile. A newly opened node now first looks for
// the cell that keeps the OPEN BLOCK most uniform — a compact, near-square rectangle with no interior
// holes — and only uses direction to break ties BETWEEN equally-compact cells. So the block still leans
// toward the side its nodes sit on (a left-heavy graph opens a left-leaning block), but it always reads
// as a tidy tile grid rather than a scatter. The trade is deliberate: an individual left-hand node may
// land in the anchor's own column when that is what completes the square, because a uniform block beats
// a strictly-sided but ragged one.
import type { MorphRect } from "@/features/glance/lib/glancePush";
import { NW, NH } from "@/features/glance/lib/glanceGraph";

/** A cell's DEFAULT size, in WORLD units (it renders at world-size × the current zoom). Matches the
 *  pre-grid single-morph card, so opening one node is visually unchanged. */
export const CELL_W = 760, CELL_H = 520;
/** Resize bounds for the shared cell (world units). A resize drives EVERY cell — a per-morph size would
 *  break the non-overlap guarantee the grid exists to provide. */
export const CELL_MIN_W = 380, CELL_MIN_H = 280, CELL_MAX_W = 1600, CELL_MAX_H = 1100;
/** Gutter between cells, world units — wide enough that two cards read as separate panels. */
export const GRID_GAP = 28;
/** How far out the placement search looks for a free cell. Ring 6 spans 169 cells — far past any
 *  plausible number of simultaneously open sessions, so this is a termination guard, not a cap. */
export const MAX_RING = 6;
/** The most cells a compact block can be off a perfect square before direction stops mattering — unused
 *  as a tunable now that compactness is lexicographically primary (#3525); kept exported for callers/tests
 *  that referenced the old direction-vs-distance trade. */
export const RING_PENALTY = 0.35;

/** The shared cell size — mutated as one by any morph's resize handles. */
export interface CellSize { w: number; h: number }

export const DEFAULT_CELL: CellSize = { w: CELL_W, h: CELL_H };

/** A lattice position. SIGNED: a negative col is LEFT of the anchor, a negative row is ABOVE it. */
export interface GridCell { col: number; row: number }

/** Which node holds which cell. */
export interface MorphPlacement extends GridCell { nodeId: string }

/** As much of a node as the grid geometry needs. */
export interface GridAnchorNode { x: number; y: number }

/**
 * Cell (0,0)'s top-left, in world coords: the cell CENTRED on the anchor node — byte-identical to the
 * pre-grid morph's own box (`node.x + NW/2 - CARD_W/2`). This is what makes opening the first node look
 * exactly as it always has; the grid only becomes visible from the second morph on.
 */
export function gridOrigin(anchor: GridAnchorNode, cell: CellSize = DEFAULT_CELL): { x: number; y: number } {
  return { x: anchor.x + NW / 2 - cell.w / 2, y: anchor.y + NH / 2 - cell.h / 2 };
}

/** The world box of a lattice cell. Signed, so `col: -1` sits one full cell + gap to the LEFT. */
export function cellRect(anchor: GridAnchorNode, at: GridCell, cell: CellSize = DEFAULT_CELL): MorphRect {
  const o = gridOrigin(anchor, cell);
  return {
    left: o.x + at.col * (cell.w + GRID_GAP),
    top: o.y + at.row * (cell.h + GRID_GAP),
    w: cell.w,
    h: cell.h,
  };
}

/** Every cell at Chebyshev distance `r` from the origin — the square "ring" at radius r. Ring 0 is the
 *  origin itself; ring 1 is the eight neighbours. Deterministically ordered (by col, then row). */
export function ringCells(r: number): GridCell[] {
  if (r <= 0) return [{ col: 0, row: 0 }];
  const out: GridCell[] = [];
  for (let col = -r; col <= r; col++) {
    for (let row = -r; row <= r; row++) {
      if (Math.max(Math.abs(col), Math.abs(row)) === r) out.push({ col, row });
    }
  }
  return out;
}

/** How well a cell's direction from the origin matches the unit vector (ux,uy): the cosine of the angle
 *  between them, in [-1, 1]. The origin cell has no direction, so it scores 0. */
function alignment(at: GridCell, ux: number, uy: number): number {
  const len = Math.hypot(at.col, at.row);
  if (len === 0) return 0;
  return (at.col * ux + at.row * uy) / len;
}

const key = (at: GridCell) => `${at.col},${at.row}`;

/** The two numbers that make a placement UNIFORM (#3525), for the occupied set INCLUDING the candidate.
 *  Compared lexicographically, smaller = more uniform:
 *   1. `maxDim` — the longer side of the bounding box. Minimising it caps how far the block can stretch
 *      in any one direction, so N cells collapse toward a √N-square instead of a long strip.
 *   2. `holes` — empty cells inside that box (`area − filled`). With `maxDim` fixed, the fewest holes
 *      wins, so a candidate that fills a gap always beats one that opens the block up. */
function uniformity(cells: readonly GridCell[]): { maxDim: number; holes: number } {
  let minC = Infinity, maxC = -Infinity, minR = Infinity, maxR = -Infinity;
  for (const c of cells) {
    if (c.col < minC) minC = c.col;
    if (c.col > maxC) maxC = c.col;
    if (c.row < minR) minR = c.row;
    if (c.row > maxR) maxR = c.row;
  }
  const w = maxC - minC + 1, h = maxR - minR + 1;
  return { maxDim: Math.max(w, h), holes: w * h - cells.length };
}

/**
 * Place `nodeId` in the free cell that keeps the open block most UNIFORM, breaking ties by `delta` — its
 * node's world offset FROM THE ANCHOR NODE (#3525, was direction-first in #3367).
 *
 * For each free cell the candidate occupied set is scored by {@link uniformity} (compact, hole-free
 * first); among equally-uniform cells the one whose direction best matches `delta` wins, so the block
 * still leans toward the side its nodes sit on. This is what makes N morphs collapse into a tidy tile
 * grid (a 2×2, then 3×3, …) rather than the sparse strips direction-first could leave — while a
 * left-heavy graph still opens a left-leaning block.
 *
 * The FIRST placement is always the anchor itself at (0,0). A `delta` of zero — the anchor node itself
 * re-opening — takes (0,0) back when free; every other node is scored, so a freed centre is filled only
 * when it is also the most uniform choice.
 *
 * Placed morphs are NEVER moved: placement decides where a morph goes when it OPENS. Re-ranking every
 * morph on each open would make a terminal being read jump, which is worse than an imperfect
 * arrangement. Re-placing an already-placed node is a no-op.
 */
export function placeByDirection(
  placements: readonly MorphPlacement[],
  nodeId: string,
  delta: { dx: number; dy: number },
  maxRing: number = MAX_RING,
): MorphPlacement[] {
  if (placements.some((p) => p.nodeId === nodeId)) return placements.slice();
  if (placements.length === 0) return [{ nodeId, col: 0, row: 0 }];

  const taken = new Set(placements.map(key));
  const len = Math.hypot(delta.dx, delta.dy);

  // The anchor node re-opening (zero delta) belongs at the centre when it is free — the block was built
  // around (0,0). Otherwise it falls through to the uniform scoring like any node.
  if (len === 0 && !taken.has(key({ col: 0, row: 0 }))) {
    return [...placements, { nodeId, col: 0, row: 0 }];
  }
  const ux = len === 0 ? 0 : delta.dx / len;
  const uy = len === 0 ? 0 : delta.dy / len;
  const occupied = placements.map((p) => ({ col: p.col, row: p.row }));

  // Score every free cell out to `maxRing`. Compactness is lexicographically PRIMARY: a smaller longer
  // side wins, then fewer holes, so the block collapses toward a square with no gaps. Direction only
  // separates cells that are equally uniform, and a deterministic (col,row) order settles the rest so
  // the same graph always lays out identically.
  // From ring 0: the origin is a candidate too, so a centre freed by the anchor's morph closing gets
  // filled when that keeps the block compact (it is normally `taken`, hence skipped). The zero-delta
  // anchor re-open above already claimed a free (0,0), so this only reconsiders it for other nodes.
  let best: { cell: GridCell; maxDim: number; holes: number; align: number } | null = null;
  for (let r = 0; r <= maxRing; r++) {
    for (const c of ringCells(r)) {
      if (taken.has(key(c))) continue;
      const { maxDim, holes } = uniformity([...occupied, c]);
      const align = alignment(c, ux, uy);
      const better =
        !best
        || maxDim < best.maxDim
        || (maxDim === best.maxDim && holes < best.holes)
        || (maxDim === best.maxDim && holes === best.holes && align > best.align + 1e-9)
        || (maxDim === best.maxDim && holes === best.holes && Math.abs(align - best.align) <= 1e-9
            && (c.col < best.cell.col || (c.col === best.cell.col && c.row < best.cell.row)));
      if (better) best = { cell: c, maxDim, holes, align };
    }
  }
  // Every ring out to maxRing is full — refuse rather than overlap. Unreachable in practice (169 cells).
  return best ? [...placements, { nodeId, ...best.cell }] : placements.slice();
}

/** Drop `nodeId`'s placement. The survivors keep their cells — closing one morph never moves another. */
export function releaseCell(placements: readonly MorphPlacement[], nodeId: string): MorphPlacement[] {
  return placements.filter((p) => p.nodeId !== nodeId);
}

/** The node ids currently holding a cell, in placement order. */
export function occupants(placements: readonly MorphPlacement[]): string[] {
  return placements.map((p) => p.nodeId);
}

/**
 * The bounding box of every open morph — the single region the graph parts around. Null when none are
 * open (so the neighbours snap back).
 *
 * Unions the boxes the morphs REPORT rather than deriving them from placements: a morph releases its box
 * the instant it starts collapsing, several hundred ms before it unmounts, so the graph parts back in
 * step with the shrink instead of lagging a full exit animation behind it.
 */
export function unionRects(rects: readonly MorphRect[]): MorphRect | null {
  if (rects.length === 0) return null;
  const left = Math.min(...rects.map((r) => r.left));
  const top = Math.min(...rects.map((r) => r.top));
  const right = Math.max(...rects.map((r) => r.left + r.w));
  const bottom = Math.max(...rects.map((r) => r.top + r.h));
  return { left, top, w: right - left, h: bottom - top };
}

/** Clamp a proposed shared cell size to the resize bounds. */
export function clampCell(w: number, h: number): CellSize {
  return {
    w: Math.min(Math.max(w, CELL_MIN_W), CELL_MAX_W),
    h: Math.min(Math.max(h, CELL_MIN_H), CELL_MAX_H),
  };
}

// navigateBridge (#3274, epic #3260) — the PURE half of `bsc navigate`: resolve a request into store
// mutations and report the view that landed.
//
// Split from `useNavigateBridge.ts` so the decisions (what a request resolves to, what is an error, what
// the resulting view is) are unit-testable without Tauri or a rendered app. The hook is a thin adapter.
//
// CONTRACT
// - A request is INTENTS, not steps: `component` implies its workspace + page. A caller asking for a
//   component should not need to know which Workspace hosts the Design Studio this week.
// - Unknown ids are ERRORS, not silent no-ops. A capture against a view that never landed is exactly the
//   failure this surface exists to prevent, so "I couldn't" must be louder than "sure".
// - The ack reports what ACTUALLY landed — RE-READ from the store after applying, never echoed from the
//   request and never read off a pre-mutation snapshot (zustand hands out a new object per update, so a
//   captured `getState()` goes stale the moment you set anything). An ack that reports the view you asked
//   for rather than the one you got would defeat the whole surface: the caller would capture confidently
//   against the wrong screen.
import type { AppStore } from "@/store/types";
import type { Workspace } from "@/app/registry";
import { dispatchPage } from "@/app/navigate";
import { blanketDismissable, refuseDismissal } from "@/app/chrome/banners";

/** The `--dismiss` value that clears every non-decision notice. */
const ALL_NOTICES = "all";

/** The preview DATA-STATES `--state` navigates to (#3717) — the navigable subset of the Design Studio's
 *  state axis (`error` is a render OUTCOME, not something you request). Kept in lockstep with the Rust
 *  `NAV_STATES` in `bsc-navigate`'s CLI. `as const` so the values narrow to a union assignable to the
 *  store's `PreviewState` without a cross-feature type import. */
const NAV_STATES = ["loaded", "empty", "loading"] as const;

/** What `bsc navigate` asks for. Every field optional; absent ⇒ leave it alone. Mirrors Rust `NavRequest`. */
export interface NavRequest {
  /** A human asked for this steer, so the presence gate does not apply (#4248). */
  force?: boolean;
  workspace?: string;
  page?: string;
  kit?: string;
  component?: string;
  theme?: string;
  state?: string;
  /** #54 — clear an app NOTICE (a banner id, or `all`). Banners dismiss through local React state, so a
   *  session driving the app from a shell could see one in a capture and had no way to clear it. */
  dismiss?: string;
}

/** What we send back to Rust. Mirrors Rust `NavAck`. */
export interface NavAck {
  id?: string;
  error?: string;
  /** INTERNAL, never sent to Rust — the adapter strips it (#navigate-answers-from-a-stale-app-snapshot).
   *
   *  Set when the error is a miss that a RE-READ could plausibly fix: this resolves against the app's
   *  hydrated copy of the store, and an external `bsc ui set` only reaches that copy while the Design
   *  Studio is visible (`useUiActivity` is mounted there and gated on it). So a session writing a
   *  component from a shell, with the app showing Console, gets "unknown component" for a record that
   *  demonstrably exists — request #55.
   *
   *  This function stays PURE, so it only says the miss is retryable; `useNavigateBridge` owns the
   *  async hydrate and the single retry. */
  retryAfterHydrate?: boolean;
  /** Set when a `component` intent focused the record but did NOT switch the view (#3599/#4248).
   *
   *  Without it the ack reports the CURRENT view and reads as an ordinary success — so a caller that
   *  asked for a component, saw `workspace: "github"` come back, and had nothing to photograph concluded
   *  the navigate had failed and forced the view with `navigate page designs`. That escalation, fired
   *  every ~7s by the designer loop, IS the yank. Saying "declined, and why" is what makes the refusal
   *  legible instead of looking like a bug to route around. */
  declined?: string;
  /** INTERNAL, never sent to Rust — the adapter strips it after using it.
   *
   *  The component id whose preview frame is expected to REBUILD because of this navigate. Set only when
   *  the Studio is actually the visible page, so a declined or human-blocked navigate never waits for a
   *  mount that will not happen.
   *
   *  This module stays PURE: it says what to wait for, and `useNavigateBridge` owns the bounded wait and
   *  fills in `mounted`/`mountError`. Deliberately NOT a buildability check here — re-deriving that
   *  predicate is exactly how the doctor and the preview came to disagree. The frame registry reports
   *  what actually happened, including failures the predicate cannot see (a bundle that threw). */
  awaitMount?: string;

  /** What the preview frame is actually SHOWING once it settled. Absent when nothing was expected to
   *  mount, or when the frame did not settle inside the budget — `mountError` then says which. */
  mounted?: string;
  /** Why the selected component is not on screen. */
  mountError?: string;
  /** #54 — the notices this request actually cleared. Reported so `dismiss all` is auditable rather than
   *  a silent sweep, and so a caller can tell "nothing was showing" from "it worked". */
  dismissed?: string[];

  workspace?: string;
  page?: string;
  kit?: string;
  component?: string;
  theme?: string;
  state?: string;
}

/** The vocabulary the resolver validates against.
 *
 *  `read` is a LIVE getter, not a snapshot — see the contract note above. Passed in so this module stays
 *  pure and testable with a fake store. */
export interface NavVocab {
  /** Is a human at the keyboard right now (#4248)? Injected rather than imported so this module stays
   *  pure and a test can drive both worlds. Defaults to "nobody is here" when omitted, which keeps every
   *  existing caller (and the unattended loop) behaving exactly as before. */
  humanPresent?: () => boolean;
  read: () => AppStore;
  workspaces: Workspace[];
  pages: string[];
}

/** The Workspace hosting the Design Studio, and the page within it. Resolved here (not by the caller) so
 *  `bsc navigate component` keeps working if the Studio moves. */
const DESIGNS_WORKSPACE: Workspace = "projects";
const DESIGNS_PAGE = "designs";

/**
 * Apply `req` and return the ack. Never throws for a *bad request* — an unknown id becomes `error`,
 * because the caller needs a reason it can act on, not an exception.
 */
export function applyNavigate(req: NavRequest, vocab: NavVocab): NavAck {
  const { read, workspaces, pages } = vocab;
  const s = read();
  // #3599: was the Design Studio ALREADY on screen before this navigate? A designer follow-along focus
  // (`bsc navigate component`, fired before each `bsc shot preview`) must not YANK the user off whatever
  // page they're on — so the component intent below only folds to the Studio when it's already showing.
  const wasShowingStudio = s.activeWorkspace === DESIGNS_WORKSPACE && s.projectsPageMode === DESIGNS_PAGE;

  // ── Validate EVERYTHING before mutating anything ──────────────────────────────────────────────
  // A half-applied navigation is worse than a refused one: the caller gets an error AND a view that
  // partially moved, so the next capture is wrong in a way nothing reported. Validate, then commit.
  if (req.workspace !== undefined && !workspaces.includes(req.workspace as Workspace)) {
    return { error: `unknown workspace '${req.workspace}' — one of: ${workspaces.join(", ")}` };
  }
  if (req.page !== undefined && !pages.includes(req.page)) {
    return { error: `unknown page '${req.page}' — one of: ${pages.join(", ")}` };
  }
  if (req.kit !== undefined && !s.kits.some((k) => k.id === req.kit)) {
    return { error: `unknown kit '${req.kit}' — one of: ${s.kits.map((k) => k.id).join(", ")}`, retryAfterHydrate: true };
  }
  if (req.theme !== undefined && !s.kitThemes.some((t) => t.id === req.theme)) {
    return { error: `unknown theme '${req.theme}' — one of: ${s.kitThemes.map((t) => t.id).join(", ")}` };
  }
  if (req.state !== undefined && !(NAV_STATES as readonly string[]).includes(req.state)) {
    return { error: `unknown state '${req.state}' — one of: ${NAV_STATES.join(", ")}` };
  }
  // #54 — validated with the rest, BEFORE anything mutates: a half-applied navigation that also refused
  // a dismissal would leave the caller guessing which half happened.
  if (req.dismiss !== undefined && req.dismiss !== ALL_NOTICES) {
    const refusal = refuseDismissal(req.dismiss);
    if (refusal) return { error: refusal };
  }
  // A component is only meaningful inside a kit: resolve against the requested kit, else the current one.
  // Naming a component without a kit is ambiguous the moment two kits share a component name.
  let comp: { id: string; kitId: string } | undefined;
  if (req.component !== undefined) {
    const kitId = req.kit ?? s.designsKitId ?? "";
    comp = s.components.find((c) => c.id === req.component && c.kitId === kitId);
    if (!comp) {
      const inKit = s.components.filter((c) => c.kitId === kitId).map((c) => c.id);
      return {
        error: kitId
          ? `unknown component '${req.component}' in kit '${kitId}'` +
            (inKit.length ? ` — one of: ${inKit.join(", ")}` : " (the kit has no components)")
          : `unknown component '${req.component}' — name a kit: bsc navigate component <kit> ${req.component}`,
        retryAfterHydrate: true,
      };
    }
  }

  // ── Commit ────────────────────────────────────────────────────────────────────────────────────
  // A blanket dismiss clears everything that does not ASK something. `session-recovery` ("restore or
  // discard?") is excluded by the registry: hiding it does not answer it, it removes the only place the
  // answer can be given, and those sessions stay unrestored with nothing on screen to say so.
  const dismissed: string[] = [];
  if (req.dismiss !== undefined) {
    for (const id of req.dismiss === ALL_NOTICES ? blanketDismissable() : [req.dismiss]) {
      s.dismissNotice(id);
      dismissed.push(id);
    }
  }
  if (req.theme !== undefined) s.setKitTheme(req.theme);
  // The preview DATA-STATE the Studio renders (#3717) — drives the same store value the state control
  // sets, so a `--state` navigate captures the intended render. Validated above, so the cast is sound.
  if (req.state !== undefined) s.setDesignsPreviewState(req.state as (typeof NAV_STATES)[number]);
  // #4248: a view change is REFUSED while a person is using the app. #3599 gated only the `component`
  // intent and honoured an explicit `--workspace`/`--page` as "a deliberate steer" — but an agent's
  // background loop is made of explicit commands, so that line separated nothing. The designer simply
  // followed its declined `navigate component` with `navigate page designs`, every ~7s.
  //
  // Presence is the line that does separate them: steering is right unattended (the overnight loop this
  // was built for) and wrong when someone is working. `--force` remains for a human driving the app from
  // their own terminal — explicit, and visible in the ack.
  const steering = req.workspace !== undefined || req.page !== undefined;
  const blockedByHuman = steering && !req.force && (vocab.humanPresent?.() ?? false);
  if (blockedByHuman) {
    // The focus still lands, so the Studio shows the right component the moment the user opens it —
    // the same shape #3599 chose. Only the VIEW is left alone.
    if (comp) {
      s.setDesignsKit(comp.kitId);
      s.setDesignsComp(comp.id);
    } else if (req.kit !== undefined) {
      s.setDesignsKit(req.kit);
    }
    if (req.theme !== undefined) s.setKitTheme(req.theme);
    return landed(
      read,
      "view unchanged: someone is using the app right now, and a background steer does not take the " +
        "screen from them (#4248). The focus is set, so it is there when they open the Studio. Pass " +
        "--force only for a steer a HUMAN asked for.",
    );
  }
  if (req.workspace !== undefined) s.setWorkspace(req.workspace as Workspace);
  // Dispatch the page through the SAME per-workspace mechanism the UI uses (#3602) instead of hard-coding
  // one workspace's setter. The page vocab is still PROJECT_MODES (validated above), so for the projects
  // workspace this is exactly the old `setProjectsPageMode`; a page with no target workspace defaults to
  // the Studio's (projects), preserving today's behavior.
  if (req.page !== undefined) dispatchPage(s, (req.workspace as Workspace) ?? DESIGNS_WORKSPACE, req.page);

  // `component` implies its workspace + page — the intent is "show me this", not "set a field". But
  // (#3599) a designer follow-along must not steal the user's current page: only SWITCH to the Studio
  // when it's already showing, or when the request EXPLICITLY asked for a workspace/page (a deliberate
  // steer, not a background focus). Off-Studio, we still set the focus so it's there when the user opens
  // the Studio themselves — their current view is untouched.
  let declined: string | undefined;
  let awaitMount: string | undefined;
  if (comp) {
    if (wasShowingStudio || req.workspace !== undefined || req.page !== undefined) {
      s.setWorkspace(DESIGNS_WORKSPACE);
      s.setProjectsPageMode(DESIGNS_PAGE as AppStore["projectsPageMode"]);
      // The Studio is the visible page, so its frame WILL rebuild for this selection. Anywhere else,
      // nothing rebuilds and waiting would only burn the caller's ack budget.
      awaitMount = comp.id;
    } else {
      // The #3599 refusal, stated (#4248). It is deliberate, so it must not read as a failure.
      declined =
        "focus set, view unchanged: the Design Studio is not the visible page and a background " +
        "follow-along does not steal the user's view (#3599). Nothing is on screen to capture. Do not " +
        "force it with `navigate page` while someone is working.";
    }
    // setDesignsKit CLEARS the component (a component belongs to one kit), so the kit must come first.
    s.setDesignsKit(comp.kitId);
    s.setDesignsComp(comp.id);
  } else if (req.kit !== undefined) {
    s.setDesignsKit(req.kit);
  }

  return landed(read, declined, awaitMount, dismissed);
}

/** Read the resulting view back OUT of the store — a FRESH read, never the pre-mutation snapshot. */
function landed(read: () => AppStore, declined?: string, awaitMount?: string, dismissed?: string[]): NavAck {
  const s = read();
  return {
    awaitMount,
    dismissed: dismissed && dismissed.length > 0 ? dismissed : undefined,
    workspace: s.activeWorkspace,
    page: s.projectsPageMode,
    kit: s.designsKitId || undefined,
    component: s.designsCompId ?? undefined,
    theme: s.kitTheme || undefined,
    state: s.designsPreviewState || undefined,
    declined,
  };
}

// navigate (#3602) — ONE place that turns "go here" into the right store mutations, so navigation can
// never forget the page.
//
// WHY THIS EXISTS
// A Workspace switch (`setWorkspace`) and the PAGE within it (which tab/section) are set through
// DIFFERENT mechanisms per workspace — tabbed screens persist an uncontrolled `activePageTab[key]`,
// the rest each own a dedicated field (`projectsPageMode`, `githubTab`, `automationsTab`,
// `settingsSection`). So a caller that just did `setWorkspace("glance")` lands on whatever tab was last
// open, not the one it meant — #3598 was FOUR separate one-off fixes for exactly this (triage-complete
// landing on Glance but not the Network tab / not the project, GitHub-connect banner landing on the
// last settings section, …). `navigate({ workspace, page, drill })` makes "specify the page" STRUCTURAL:
// you name the page in the same call that switches the workspace, and this module knows which knob each
// workspace turns.
import type { AppStore } from "@/store/types";
import type { Workspace } from "@/app/registry";

/** A navigation target: WHERE (workspace) + WHICH page within it + an optional entity to focus.
 *  `workspace` is required — the whole point is that you cannot switch screens without saying which
 *  page, so "land on glance" can never silently mean "…on whatever tab happened to be open". */
export interface NavLoc {
  workspace: Workspace;
  /** The page/tab within the workspace. Omit only for a workspace with no pages (console — its tabs are
   *  index-switched, not a string page) or when the workspace's default page is genuinely what you want. */
  page?: string;
  /** An entity to focus on the landing screen (currently only Glance, which drills into a project). Pass
   *  `null` to clear a drill; omit to leave it untouched. */
  drill?: string | null;
}

/** How each workspace sets its current PAGE — the single source of truth for a workspace's page knob.
 *  Tabbed screens (glance/skills/mcp/security) persist an uncontrolled `activePageTab[key]`; the rest own
 *  a dedicated field. `console` is intentionally absent: its "pages" are indexed tabs switched by
 *  `setActiveTab(idx)`, not a string page — a `navigate` to console carries no `page`. */
const WORKSPACE_PAGE: Partial<Record<Workspace, (s: AppStore, page: string) => void>> = {
  glance: (s, page) => s.setActivePageTab("glance", page),
  skills: (s, page) => s.setActivePageTab("skills", page),
  mcp: (s, page) => s.setActivePageTab("mcp", page),
  security: (s, page) => s.setActivePageTab("security", page),
  projects: (s, page) => s.setProjectsPageMode(page as AppStore["projectsPageMode"]),
  github: (s, page) => s.setGithubTab(page),
  automation: (s, page) => s.setAutomationsTab(page as AppStore["automationsTab"]),
  settings: (s, page) => s.setSettingsSection(page),
};

/** How each workspace focuses an ENTITY. Only Glance drills today; the map keeps the door open. */
const WORKSPACE_DRILL: Partial<Record<Workspace, (s: AppStore, id: string | null) => void>> = {
  glance: (s, id) => s.setGlanceDrill(id),
};

/** Set the page for `workspace` through its own mechanism. Exported so the `bsc navigate` bridge routes
 *  through the SAME map instead of hard-coding one workspace's setter. A workspace with no page
 *  mechanism (console) is a no-op. */
export function dispatchPage(s: AppStore, workspace: Workspace, page: string): void {
  WORKSPACE_PAGE[workspace]?.(s, page);
}

/**
 * Apply a navigation: focus the entity, set the page, THEN switch the workspace — in that order, so the
 * target screen mounts already showing the right page/entity rather than flashing its last-viewed one.
 * Pure over the store (every mutation is a store setter), so it is unit-testable with a fake store.
 */
export function applyNavigation(s: AppStore, loc: NavLoc): void {
  if (loc.drill !== undefined) WORKSPACE_DRILL[loc.workspace]?.(s, loc.drill);
  if (loc.page !== undefined) dispatchPage(s, loc.workspace, loc.page);
  s.setWorkspace(loc.workspace);
}

// Network layout (#2505) — the pure (React-free) model behind NetworkPage. A general directed graph
// rides EXACTLY the shared graph stack the Tree layered variant established (treeLayout.ts, #2476):
// `findBackEdges` (#2217) breaks cycles so layering can't diverge, `layerDag` (#2214) assigns depths,
// `orderLayers` (#2418) runs the shared barycenter sweep (neighbors = every edge endpoint, both
// directions — the Glance discipline), and this module owns only the layer→pixel PLACEMENT
// (centered rows, top-down). Nothing here forks graph logic; it only feeds the shared pieces
// arbitrary node/edge input.
import { findBackEdges } from "@/shared/lib/graph/cycles";
import { layerDag } from "@/shared/lib/graph/layers";
import { orderLayers } from "@/shared/lib/graph/order";
import type { GraphEdge } from "@/shared/lib/graph/types";

/** One network node — the page renders label + optional meta on its card. */
export interface NetworkNodeData {
  id: string;
  label: string;
  /** Optional dimmed mono meta under the label (a kind, a count, a rate). */
  meta?: string;
}

/** One directed edge; `id` is derived (`from->to`) when omitted. */
export interface NetworkEdgeData {
  id?: string;
  from: string;
  to: string;
}

/** Node card box (world coords) — shared with NetworkPage's node + edge rendering. */
export const NET_NODE_W = 156;
export const NET_NODE_H = 46;

export interface NetworkLayoutMetrics {
  nodeW: number;
  nodeH: number;
  /** Horizontal clearance between nodes in a row. */
  hGap: number;
  /** Vertical clearance between layers (the gap the edges cross). */
  vGap: number;
  /** World padding around the whole layout. */
  pad: number;
}

export const DEFAULT_NET_METRICS: NetworkLayoutMetrics = {
  nodeW: NET_NODE_W, nodeH: NET_NODE_H, hGap: 30, vGap: 78, pad: 48,
};

export interface NetworkLayout {
  /** Node id → its card's top-left corner in world coords. */
  pos: Map<string, { x: number; y: number }>;
  /** Every edge (incl. cycle-closing ones — they still DRAW; they just don't layer). */
  edges: GraphEdge[];
  /** World (design-space) size — the GraphCanvas `world` box. */
  world: { w: number; h: number };
  /** Node id → its layer (0 = sources). Exposed for tests + callers. */
  layer: Record<string, number>;
}

/** Normalize the page's edges into the shared GraphEdge shape (derive missing ids). */
export function networkEdges(edges: readonly NetworkEdgeData[]): GraphEdge[] {
  return edges.map((e) => ({ id: e.id ?? `${e.from}->${e.to}`, from: e.from, to: e.to }));
}

/**
 * Top-down network placement: cycle-safe `layerDag` depth → row, shared barycenter ordering within
 * each row (neighbors = both endpoints of every edge), rows centered — the same discipline as
 * `layoutTree`, generalized to any directed graph.
 */
export function layoutNetwork(
  nodes: readonly NetworkNodeData[],
  edgeData: readonly NetworkEdgeData[],
  metrics: NetworkLayoutMetrics = DEFAULT_NET_METRICS,
): NetworkLayout {
  const m = metrics;
  const ids = nodes.map((n) => n.id);
  const edges = networkEdges(edgeData);
  const { backEdgeIds } = findBackEdges(ids, edges);
  const layer = layerDag(ids, edges, backEdgeIds);

  // Barycenter neighbors: every edge endpoint, in both directions (multiplicity counts).
  const neighbors = new Map<string, string[]>(ids.map((id) => [id, []]));
  for (const e of edges) {
    if (e.from === e.to) continue;
    neighbors.get(e.from)?.push(e.to);
    neighbors.get(e.to)?.push(e.from);
  }
  const rows = orderLayers(ids, (id) => layer[id] ?? 0, (id) => neighbors.get(id) ?? []);

  const rowWidth = (n: number) => n * m.nodeW + Math.max(0, n - 1) * m.hGap;
  const maxRow = Math.max(0, ...[...rows.values()].map((r) => r.length));
  const w = Math.max(320, 2 * m.pad + rowWidth(maxRow));

  const pos = new Map<string, { x: number; y: number }>();
  let bottom = m.pad;
  for (const [l, row] of [...rows.entries()].sort(([a], [b]) => a - b)) {
    const y = m.pad + l * (m.nodeH + m.vGap);
    const x0 = (w - rowWidth(row.length)) / 2; // center each row — hubs sit toward the middle
    row.forEach((id, i) => pos.set(id, { x: x0 + i * (m.nodeW + m.hGap), y }));
    bottom = y + m.nodeH;
  }
  const h = Math.max(240, bottom + m.pad);

  return { pos, edges, world: { w, h }, layer };
}

// Cross-graph node addressing (#3115, epic #3114) — the universal "part number" that lets a node in one
// kit graph (Algorithms / Designs / Sounds) reference a node in ANOTHER. Today the three graphs are
// siloed: `composes` only resolves inside one kit of one pillar, so a UI component that needs `fibonacci`
// re-codes it. This module is the pure, feature-agnostic substrate that makes a cross-graph reference
// EXPRESSIBLE — the URN grammar + the reserved import-namespace mapping. Resolution + the `requires` edge
// live in ./crossGraph; the feature wiring (which store to look in) lives in the consuming features.
//
// React/Tauri-free and it imports NO feature code (this is `shared/`) — the three pillars stay decoupled
// from each other; each just adapts its own store to the generic resolver in ./crossGraph.

/** The three kit-graph pillars a node can live in. The URN's leading token. */
export type NodeGraph = "algo" | "ui" | "sound";

/** All graphs, in display order. */
export const NODE_GRAPHS: NodeGraph[] = ["algo", "ui", "sound"];

/** The reserved npm-style root for a library import (`@bsc/<segment>/<name>`). Chosen so it can never
 *  collide with a real package a user installs, and so the existing import resolver can key on it. */
export const LIBRARY_ROOT = "@bsc";

/** graph → the `@bsc/<segment>` path segment used in a library import specifier. */
export const LIBRARY_SEGMENT: Record<NodeGraph, string> = { algo: "algorithms", ui: "ui", sound: "sounds" };

/** The reverse of {@link LIBRARY_SEGMENT} — an import path segment back to its graph. */
const SEGMENT_GRAPH: Record<string, NodeGraph> = { algorithms: "algo", ui: "ui", sounds: "sound" };

/** The decomposed parts of a node URN `<graph>:<kit>/<id>`. */
export interface NodeUrnParts {
  graph: NodeGraph;
  /** The kit the node lives in — a language for algorithms (`typescript`), a kit id for designs/sounds.
   *  MAY contain `/`: sound kits are scoped (`acme/neon`). */
  kit: string;
  /** The node's in-kit id (`fibonacci.ts`, `Sparkline`, `click`). Must NOT contain `/` — see
   *  {@link parseNodeUrn} for which side of the `<kit>/<id>` ambiguity the grammar takes. */
  id: string;
}

/** Is `g` one of the known graphs? (Type guard.) */
export function isNodeGraph(g: string): g is NodeGraph {
  return (NODE_GRAPHS as string[]).includes(g);
}

/**
 * Format a node URN — `<graph>:<kit>/<id>`, e.g. `algo:typescript/fibonacci.ts`, `ui:react-ui/Sparkline`,
 * `sound:default/click`. Returns null if any component is empty (so callers can't mint a malformed URN).
 */
export function formatNodeUrn(graph: NodeGraph, kit: string, id: string): string | null {
  if (!isNodeGraph(graph) || !kit || !id) return null;
  return `${graph}:${kit}/${id}`;
}

/**
 * Parse a node URN back into its parts, or null when it doesn't match `<graph>:<kit>/<id>` with a known
 * graph and non-empty kit + id. Tolerant: never throws (malformed input → null).
 *
 * `<kit>/<id>` is ambiguous when either half contains a `/`, so the split has to pick a side. It splits
 * on the LAST `/`: the KIT may contain slashes, the id may not.
 *
 * This reversed the original choice (#3514). Splitting on the FIRST `/` was chosen so an id could
 * contain slashes — with the caveat, written right here, "though today none do". Meanwhile kit ids
 * demonstrably DO: a sound kit is scoped (`acme/neon`), which is the exact form #3412 taught blueprints
 * to pin. So `sound:acme/neon/zap` parsed as kit `acme` + id `neon/zap`, missed every lookup, and a
 * pinned sound kit resolved NOTHING — silently, because a miss is indistinguishable from "no such cue".
 * The grammar was guarding a case that has never existed at the cost of one that ships.
 */
export function parseNodeUrn(urn: string): NodeUrnParts | null {
  if (typeof urn !== "string") return null;
  const colon = urn.indexOf(":");
  if (colon <= 0) return null;
  const graph = urn.slice(0, colon);
  if (!isNodeGraph(graph)) return null;
  const rest = urn.slice(colon + 1);
  const slash = rest.lastIndexOf("/");
  if (slash <= 0) return null; // need a non-empty kit before the last '/'
  const kit = rest.slice(0, slash);
  const id = rest.slice(slash + 1);
  if (!kit || !id) return null;
  return { graph, kit, id };
}

/** Is `s` a well-formed node URN? */
export function isNodeUrn(s: string): boolean {
  return parseNodeUrn(s) !== null;
}

/** A library import specifier `@bsc/<segment>/<name>` — the KIT-LESS reference a component author writes
 *  (`import { fibonacci } from "@bsc/algorithms/fibonacci"`). The consuming store picks the kit (a TS
 *  component resolves an algorithm in the `typescript` kit), so a spec carries only graph + name. */
export interface LibrarySpec {
  graph: NodeGraph;
  /** The node name/id as written in the import (`fibonacci` or `fibonacci.ts` — the resolver accepts both). */
  name: string;
}

/** Is `spec` under the reserved `@bsc/…` library root? A cheap pre-check before {@link parseLibrarySpec}. */
export function isLibrarySpec(spec: string): boolean {
  return typeof spec === "string" && spec.startsWith(LIBRARY_ROOT + "/");
}

/**
 * Parse a library import specifier `@bsc/<segment>/<name>` into `{ graph, name }`, or null when it isn't
 * a `@bsc/…` spec with a known segment and a non-empty name. `name` keeps any remaining path (e.g. a
 * hypothetical `@bsc/ui/forms/Field` → name `forms/Field`) so ids with `/` survive. Never throws.
 */
export function parseLibrarySpec(spec: string): LibrarySpec | null {
  if (!isLibrarySpec(spec)) return null;
  const after = spec.slice(LIBRARY_ROOT.length + 1); // drop "@bsc/"
  const slash = after.indexOf("/");
  if (slash <= 0) return null;
  const segment = after.slice(0, slash);
  const name = after.slice(slash + 1);
  const graph = SEGMENT_GRAPH[segment];
  if (!graph || !name) return null;
  return { graph, name };
}

/**
 * The canonical library import specifier for a node URN — `@bsc/<segment>/<id>`. The inverse of routing a
 * spec to a node; used to REWRITE an inline reimplementation into a library import (#3118) and to label a
 * cross-graph edge. Returns null for a malformed URN.
 */
export function urnToImportSpec(urn: string): string | null {
  const parts = parseNodeUrn(urn);
  if (!parts) return null;
  return `${LIBRARY_ROOT}/${LIBRARY_SEGMENT[parts.graph]}/${parts.id}`;
}

// Opt-in notification-sound mapping (#3082, epic #3071 P4a) — the CONSUMER side of the Sounds pillar:
// map a fleet COORDINATION event to the Signal-kit cue that voices it. Pure (no Web Audio, no React) so
// the mapping + batch selection are unit-testable; the app-wide hook (useNotificationSounds) plays them.
import { parseCoordLine, type CoordEvent } from "@/shared/lib/fleet/coordination";

/** The three Signal-kit cues these notifications use (ids in `src-tauri/data/sounds/signal.json`). */
export type NotifyCue = "success" | "error" | "notify";

/**
 * Map one coordination event to the cue that should sound, or null if the event isn't voiced.
 * A landing/merge → `success`, a failure → `error`, a worker pausing for the user (`bsc-wait`) → `notify`.
 * (`closed`, `ask`, `assign`, … are intentionally silent — they aren't user-facing completions/pauses.)
 */
export function coordEventCue(ev: CoordEvent): NotifyCue | null {
  switch (ev.type) {
    case "landed":
    case "merged":
      return "success";
    case "failed":
      return "error";
    case "waiting":
      return "notify";
    default:
      return null;
  }
}

/**
 * Map a batch of NEW coord-log lines (oldest-first, the tail since the last poll) to the cues they
 * should sound, in order. Unparseable + non-voiced lines are dropped. Pure — the caller decides how to
 * play (and may de-duplicate to avoid stacking identical cues in one tick).
 */
export function cuesForLines(lines: string[]): NotifyCue[] {
  const cues: NotifyCue[] = [];
  for (const line of lines) {
    const ev = parseCoordLine(line);
    if (!ev) continue;
    const cue = coordEventCue(ev);
    if (cue) cues.push(cue);
  }
  return cues;
}

import type { ConsoleProvider } from "@/app/console/lib/providers/types";

const DEFAULT_MODEL = "llama3";

export const ollamaProvider: ConsoleProvider = {
  id: "ollama",
  displayName: "Ollama",
  buildLaunchCmd: (config) => `ollama run ${config?.model ?? DEFAULT_MODEL}`,
  prereqProbe: "which ollama",
};

/**
 * Sort items by a DECLARED priority ranking of a category — an order that is deliberately NOT the
 * category's natural or alphabetical one.
 *
 * The everyday case is an "attention queue": items fall into a few states and the useful order is by
 * urgency, which no property of the state gives you. Written by hand it becomes a bare comparator with
 * the ranking buried in a chain of ternaries (`s === "blocked" ? 0 : s === "running" ? 1 : …`) — the
 * priority is real domain knowledge but exists only as magic numbers inside a sort, where it cannot be
 * read as a list, reused, or reordered without recounting.
 *
 * Here the ranking is DATA: an array, first = highest priority. That array is the decision; the sort
 * is mechanical. A category not in the ranking sorts AFTER every ranked one (rather than silently
 * becoming rank 0 and jumping the queue) — an unranked value is "no stated priority", not "top
 * priority". The sort is STABLE, so items of equal rank keep their input order.
 *
 * Harvested from the Fleet page's merge queue (#3462/#3465).
 */

/**
 * A stable copy of `items` ordered by the priority of each item's category.
 *
 * `ranking[0]` is highest priority. An item whose category is not in `ranking` sorts after every
 * ranked item, in input order among its unranked peers.
 */
export function orderByRank<T, R>(
  items: readonly T[],
  categoryOf: (item: T) => R,
  ranking: readonly R[],
): T[] {
  const rankOf = new Map<R, number>(ranking.map((r, i) => [r, i]));
  // Unranked → after everything ranked. `ranking.length` sits past the last real rank.
  const rank = (item: T) => rankOf.get(categoryOf(item)) ?? ranking.length;
  // Decorate-sort-undecorate keeps it stable AND calls `categoryOf` once per item rather than O(n log n)
  // times — the naive `.sort((a,b) => rank(a) - rank(b))` re-derives the category on every comparison.
  return items
    .map((item, i) => ({ item, i, r: rank(item) }))
    .sort((a, b) => a.r - b.r || a.i - b.i)
    .map((d) => d.item);
}

// Barycenter layer ordering (#2418, graph-core epic #2214) — the ONE crossing-reduction sweep the
// layered graphs share. Given a layer assignment (from `layerDag` or any layerer), order the nodes
// WITHIN each layer so each sits near the mean in-layer index of its neighbors — the classic Sugiyama
// barycenter heuristic. What VARIES per graph is tunable: the neighbor gathering (org pulls only from
// cross-layer hierarchy parents/children; Glance from every edge endpoint), the pass count, and the
// sweep discipline. Pure; the caller owns the layer→pixel placement.

export interface OrderLayersOpts {
  /** Barycenter sweeps over the whole layer set. Default 4. */
  passes?: number;
  /** How fresh the neighbor indexes are within one pass:
   *   • "sequential" (default) — sorting layer L reads the ALREADY re-sorted order of the layers
   *     sorted earlier in the same pass, so an improvement propagates immediately (org's discipline).
   *   • "snapshot" — every layer sorts against the order at the START of the pass (Glance's). */
  sweep?: "sequential" | "snapshot";
}

/**
 * Order the nodes within each layer by the barycenter heuristic: each layer is sorted by the mean
 * in-layer index of each node's neighbors; a node with no (known) neighbors keeps its current index.
 * The initial order is `nodeIds` order filtered per layer; ties keep the pre-sort order (stable sort).
 *
 * @param nodeIds Every node, in the initial (seed) order.
 * @param layerOf The layer assignment (e.g. `layerDag`'s).
 * @param neighborsOf The ids whose in-layer positions pull on a node — the caller's neighbor
 *   gathering. Multiplicity counts (a doubly-connected neighbor pulls twice); ids outside `nodeIds`
 *   are ignored.
 * @returns layer → its node ids in final order (layers in ascending order).
 */
export function orderLayers(
  nodeIds: readonly string[],
  layerOf: (id: string) => number,
  neighborsOf: (id: string) => readonly string[],
  opts: OrderLayersOpts = {},
): Map<number, string[]> {
  const passes = opts.passes ?? 4;
  const sweep = opts.sweep ?? "sequential";
  const layers = [...new Set(nodeIds.map(layerOf))].sort((a, b) => a - b);
  const order = new Map<number, string[]>(layers.map((l) => [l, nodeIds.filter((n) => layerOf(n) === l)]));
  const idx = new Map<string, number>();
  const reindex = (l: number) => order.get(l)!.forEach((n, i) => idx.set(n, i));
  layers.forEach(reindex);

  const bary = (n: string): number => {
    const neigh = neighborsOf(n).filter((m) => idx.has(m));
    if (neigh.length === 0) return idx.get(n)!;
    return neigh.reduce((s, m) => s + idx.get(m)!, 0) / neigh.length;
  };
  const sortLayer = (l: number, b: Map<string, number>) => {
    order.get(l)!.sort((x, y) => b.get(x)! - b.get(y)!);
    reindex(l);
  };

  for (let pass = 0; pass < passes; pass++) {
    if (sweep === "snapshot") {
      const b = new Map(nodeIds.map((n) => [n, bary(n)] as const));
      for (const l of layers) sortLayer(l, b);
    } else {
      for (const l of layers) sortLayer(l, new Map(order.get(l)!.map((n) => [n, bary(n)] as const)));
    }
  }
  return order;
}

// The frontend ↔ teams store bridge (#2193, verb renamed org → teams in #2700). The desktop Team
// designer and every live console session + the planner share ONE global store
// (`~/.base-studio-code/orgs/<id>.json` — the on-disk dir keeps its `orgs/` name so existing data is
// not orphaned), reached here — and from a session's own shell — through the SAME `bsc teams …` CLI
// (with `bsc org` still a deprecated alias), over the generic `bsc` bridge (#2114). Teams are GLOBAL
// (no project key) so every call passes `null` as the projectKey. This is the only place the teams
// feature touches Tauri, so the pure model in `team.ts` stays React/Tauri-free. Mirrors
// personaBridge.ts exactly; the store is a write-through cache over this.
import { bsc, bscRun, bscWrite } from "@/shared/lib/core/bsc";
import type { Team } from "@/features/teams/lib/team";

/**
 * Load every org from the store via `bsc org list --full`. Returns `null` when the bridge is
 * unreachable (no Tauri host — tests, the web shell, or an old binary) so the caller keeps its seeded
 * in-memory built-ins rather than blanking the library. NOT `bscJson` (its degrade-to-fallback would
 * return an empty array, which would then blank the seeded set).
 */
export async function loadOrgs(): Promise<Team[] | null> {
  try {
    const out = await bsc(null, ["teams", "list", "--full"]);
    const rows = JSON.parse(out.trim() || "[]") as Partial<Team>[];
    // Defensive: keep only well-formed rows (id present), defaulting the rest so an odd file never
    // crashes hydration.
    return (rows ?? [])
      .filter((o): o is Team => typeof o.id === "string" && !!o.id)
      .map((o) => ({
        id: o.id, name: o.name ?? "Untitled", blurb: o.blurb ?? "",
        positions: o.positions ?? [], relationships: o.relationships ?? [], builtin: o.builtin,
      }));
  } catch {
    return null;
  }
}

/** Write-through a team upsert (`bsc teams set` reads the JSON on stdin). Fire-and-forget; never throws,
 *  so an old bundled `bsc` without the `teams` subcommand degrades to store-only silently. */
export async function pushOrg(org: Team): Promise<void> {
  try { await bscWrite(null, ["teams", "set"], org); } catch { /* store unreachable — cache-only */ }
}

/** Write-through a team removal (`bsc teams remove <id>`). Never throws (see {@link pushOrg}). */
export async function dropOrg(id: string): Promise<void> {
  try { await bscRun(null, ["teams", "remove", id]); } catch { /* store unreachable — cache-only */ }
}

// Team canvas geometry (#2193) — pure math for the relationship graph, ported from the Claude Design
// prototype. Kept React-free so it's unit-testable and the canvas component stays a thin renderer.
// The graph lives in a fixed 1120×800 design space; the canvas scales it by a zoom factor.
import { forceSimulation, forceLink, forceManyBody, forceX, forceCollide, type SimulationNodeDatum } from "d3-force";
import { graphEdge } from "@/shared/lib/graph/edgePath";
import { layerDag } from "@/shared/lib/graph/layers";
import { findBackEdges } from "@/shared/lib/graph/cycles";
import { orderLayers } from "@/shared/lib/graph/order";
import type { GraphEdge } from "@/shared/lib/graph/types";
import type { Team, Position, PositionKind } from "@/features/teams/lib/team";

/** The fixed design coordinate space every node's x/y is authored in. */
export const CANVAS_W = 1120;
export const CANVAS_H = 800;

/** Node box size per kind (design-space px) — person cards are the largest; resource/external smaller.
 *  The agent card carries the persona blurb, so it's sized to fit ~4 clamped lines comfortably (#3335,
 *  was 190×96) — longer blurbs ellipsis rather than overflow (see AgentFace). */
export const NODE_SIZE: Record<PositionKind, { w: number; h: number }> = {
  agent: { w: 206, h: 116 },
  resource: { w: 156, h: 82 },
  external: { w: 152, h: 80 },
};

export interface Box { x: number; y: number; w: number; h: number }

/** The design-space box for a position (its authored x/y + the size for its kind; 0,0 if unplaced). */
export function nodeBox(pos: Position): Box {
  const { w, h } = NODE_SIZE[pos.kind];
  return { x: pos.x ?? 0, y: pos.y ?? 0, w, h };
}

/** The tight bounding box around every placed node in `positions` (design-space), or null when there are
 *  none. Framing (fit / saved-zoom restore) centers on THIS — where the nodes actually are — instead of
 *  the fixed CANVAS box, so the graph isn't parked high / clipped when the layout fills only part of (or
 *  overflows) the canvas (#2673). Pure. */
export function contentBounds(positions: Position[]): Box | null {
  if (positions.length === 0) return null;
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const p of positions) {
    const b = nodeBox(p);
    minX = Math.min(minX, b.x);
    minY = Math.min(minY, b.y);
    maxX = Math.max(maxX, b.x + b.w);
    maxY = Math.max(maxY, b.y + b.h);
  }
  return { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
}

export interface EdgeGeometry {
  /** SVG cubic-bezier path `d`. */
  d: string;
  /** The midpoint where the edge label pill sits. */
  lx: number;
  ly: number;
}

/** The bezier path + label point between two boxes, bowed by `bow` px off the straight line so parallel
 *  edges fan apart. The end is pulled back 9px to leave room for the arrowhead. Ported from `_geom`. */
export function edgeGeometry(A: Box, B: Box, bow = 0): EdgeGeometry {
  // The shared graph line-type (#2222); Team keeps its own arrowhead markers, so it only takes the
  // curve + the label midpoint. Byte-identical to the previous inline geometry.
  const { d, labelX, labelY } = graphEdge(A, B, { bow });
  return { d, lx: labelX, ly: labelY };
}

/** SVG dash-array for an archetype line style. */
export function styleDash(style: string): string {
  switch (style) {
    case "dashed": return "7 5";
    case "gated": return "3 5";
    case "dotted": return "1 6";
    case "resource": return "4 6";
    default: return "0"; // solid
  }
}

// ── Auto-organize ────────────────────────────────────────────────────────────
/** Archetypes that impose a top-down hierarchy (a parent → child flow); peers/consults are lateral and
 *  don't drive layering. */
const HIERARCHY_ARCHETYPES = new Set(["manages", "serves", "oversees", "stewards"]);

const AUTO_COL = 230; // seed horizontal spacing between nodes in a layer (before force refinement)
/** Vertical gap between hierarchy layers (fixed once assigned — keeps rows clean). Exported for the
 *  #2451 row-alignment regression tests (center-y deltas between laid-out nodes are multiples of it). */
export const AUTO_ROW = 200;

// Force-refinement tuning (fixed; the user never tunes these — #2199 follow-up). y is pinned per layer,
// so the simulation only moves nodes HORIZONTALLY: repulsion spreads a crowded row, link springs pull
// related nodes together, and a weak x-centering keeps the whole graph framed.
const LINK_DIST = 210;   // preferred edge length (a spring rest length)
const LINK_STR = 0.35;   // how hard edges pull (0–1) — gentle, so repulsion can still spread siblings
const CHARGE = -1600;    // many-body repulsion (negative = push apart) — the readability "breathing room"
const X_STR = 0.08;      // weak pull toward the horizontal center (keeps rows from drifting off-canvas)
const COLLIDE_PAD = 16;  // extra gap enforced around each card so nothing visually overlaps
const TICKS = 320;       // headless ticks to convergence (d3-force's seeded LCG makes this deterministic)
// These are tuned so a typical fleet settles well inside the 1120×800 design space (the default fleet
// lands at ~978×536) — no user knobs by design (#2199 follow-up); the graph just finds its own shape.

interface LayerResult { layer: Map<string, number>; order: Map<number, string[]> }

/** Assign each node a hierarchy layer (longest path from a root, cycle-guarded) and a crossing-reduced
 *  order within its layer (barycenter passes). The shared skeleton both the seed placement and the
 *  fixed-y force refinement build on. Exported for the #2418 layer-parity tests.
 *
 *  Since #2418 this delegates to the shared graph core: `layerDag` (longest-path layering, #2214) over
 *  the hierarchy edges with `findBackEdges` (#2217) as the cycle-break set, then `orderLayers` (the
 *  shared barycenter sweep) with org's tunables — 4 sequential passes, cross-layer hierarchy neighbors.
 *  Acyclic layer assignments are identical to the old private layerer; a cycle now breaks by DROPPING
 *  the DFS back-edge (the forward edge still layers parent-above-child) instead of the old zero-the-
 *  on-stack-parent artifact. */
export function layerNodes(org: Team): LayerResult {
  const ids = org.positions.map((p) => p.nodeId);
  const idSet = new Set(ids);
  // The hierarchy sub-graph: only top-down archetypes drive layering; parent → child is exactly
  // layerDag's "from → deeper" convention.
  const hierarchy: GraphEdge[] = org.relationships
    .filter((r) => HIERARCHY_ARCHETYPES.has(r.archetype) && idSet.has(r.from) && idSet.has(r.to))
    .map((r) => ({ id: r.id, from: r.from, to: r.to }));

  const { backEdgeIds } = findBackEdges(ids, hierarchy);
  const layerRec = layerDag(ids, hierarchy, backEdgeIds);
  const layer = new Map<string, number>(ids.map((n) => [n, layerRec[n]]));

  // Crossing reduction: a node's pull comes from its hierarchy parents+children in OTHER layers
  // (lateral archetypes don't reorder rows; back-edges still pull, as before).
  const parents = new Map<string, string[]>(ids.map((n) => [n, []]));
  const children = new Map<string, string[]>(ids.map((n) => [n, []]));
  for (const e of hierarchy) { parents.get(e.to)!.push(e.from); children.get(e.from)!.push(e.to); }
  const order = orderLayers(
    ids,
    (n) => layer.get(n)!,
    (n) => { const l = layer.get(n)!; return [...parents.get(n)!, ...children.get(n)!].filter((m) => layer.get(m) !== l); },
    { passes: 4 },
  );
  return { layer, order };
}

interface SimNode extends SimulationNodeDatum { id: string; w: number; h: number }

/** A deterministic hierarchical FORCE layout (#2199): every node is pinned to its hierarchy row (so the
 *  manager-above-reports structure stays razor-clean and same-layer nodes share an exact y), then a
 *  d3-force pass moves nodes only HORIZONTALLY — many-body repulsion gives each node breathing room,
 *  link springs pull related nodes together, and a weak centering keeps the graph framed. The result is
 *  the "natural structure" the graph finds on its own, so the user never has to hand-place a node.
 *
 *  Deterministic: d3-force seeds a fixed LCG (not `Math.random`) and the seed positions are computed, so
 *  re-running "Auto organize" reproduces the same layout. Returns fresh top-left `{x,y}` per nodeId.
 *
 *  `sizes` optionally overrides a node's box per nodeId (#2451): a synthetic pool node in a collapsed
 *  org renders as a STACKED card (agent card + shadow-stack overhang), so the collision pass must see
 *  that real footprint — not the plain agent size its `kind` implies. */
export function autoLayout(org: Team, sizes?: Record<string, { w: number; h: number }>): Record<string, { x: number; y: number }> {
  const { layer, order } = layerNodes(org);
  const rowY = (l: number) => 60 + l * AUTO_ROW;

  // Seed each node at its row (center coords), spread horizontally by its in-layer order so the force
  // pass starts from a sane, crossing-reduced arrangement rather than a random cloud.
  const nodes: SimNode[] = org.positions.map((p) => {
    const l = layer.get(p.nodeId)!;
    const row = order.get(l)!;
    const idx = row.indexOf(p.nodeId);
    const { w, h } = sizes?.[p.nodeId] ?? NODE_SIZE[p.kind];
    return {
      id: p.nodeId,
      w, h,
      x: CANVAS_W / 2 + (idx - (row.length - 1) / 2) * AUTO_COL,
      y: rowY(l),
      fy: rowY(l), // pin y to the layer row — the simulation only optimizes x
    };
  });
  const byId = new Map(nodes.map((n) => [n.id, n]));
  const links = org.relationships
    .filter((r) => byId.has(r.from) && byId.has(r.to))
    .map((r) => ({ source: r.from, target: r.to }));

  const sim = forceSimulation<SimNode>(nodes)
    .force("link", forceLink<SimNode, { source: string; target: string }>(links).id((d) => d.id).distance(LINK_DIST).strength(LINK_STR))
    .force("charge", forceManyBody<SimNode>().strength(CHARGE))
    .force("x", forceX<SimNode>(CANVAS_W / 2).strength(X_STR))
    .force("collide", forceCollide<SimNode>((d) => Math.max(d.w, d.h) / 2 + COLLIDE_PAD))
    .stop();
  for (let i = 0; i < TICKS; i++) sim.tick();

  // Convert sim centers → top-left boxes, then shift the whole graph into a padded positive space.
  const boxes = nodes.map((n) => ({ id: n.id, x: (n.x ?? 0) - n.w / 2, y: (n.y ?? 0) - n.h / 2 }));
  const minX = Math.min(...boxes.map((b) => b.x));
  const minY = Math.min(...boxes.map((b) => b.y));
  const out: Record<string, { x: number; y: number }> = {};
  for (const b of boxes) out[b.id] = { x: Math.round(b.x - minX + 60), y: Math.round(b.y - minY + 48) };
  return out;
}

// Team pools (#2199, #2436, #3143) — consolidating a swarm of agents into ONE stacked node so large
// graphs stay readable. A POOL is positions on the same STACKABLE persona: `pooled`, or worker-role by
// default (explicit `pooled:false` opts out) — the org graph is the SCAFFOLD (director · reviewer ·
// auditor · intake · anchors) plus a stacked engineer slot per worker persona. The planner owns how many
// engineers exist (#2388), so a WORKER-role (planner-sized) slot collapses to a stack even from ONE
// placement and its card shows NO count (#3143) — a single engineer node still means "the planner
// creates however many". Other stackable personas need a real swarm (≥2) to collapse and show `×N`.
// Per-engineer wiring detail belongs in the DRILL-IN, not the top view. Heterogeneous external wiring no longer prevents stacking (#2436 — it kept Fleet Alpha's own
// engineers from ever collapsing): the collapse UNIONS external edges onto the stack, and the pool's
// `homogeneous` flag records whether members are truly interchangeable (identical external relationship
// signatures) so the UI can mark mixed-wiring stacks. Edges among members (a peer mesh) are internal —
// they show on drill-in. Pure model (React-free) so it's unit-testable, canvas stays thin.
import type { Team, Position, Relationship } from "@/features/teams/lib/team";
import { autoLayout, NODE_SIZE } from "@/features/teams/lib/orgLayout";
import { BUILTIN_PERSONAS, type Persona } from "@/features/personas";

/** Whether a persona's positions stack. An explicit (hydrated) `pooled` always wins — a user who
 *  un-pooled a persona is respected. Otherwise: the PACKAGED built-in's flag (covers a store copy
 *  seeded before the field existed — reconcile #2220 fixes it on next boot, this shows the pool
 *  WITHOUT a restart), and worker-role personas stack BY DEFAULT (#2436 — the engineer slot; the
 *  scaffold roles stay singletons). */
const BUILTIN_POOLED = new Map(BUILTIN_PERSONAS.map((p) => [p.id, !!p.pooled]));
function isStackable(p: Persona): boolean {
  if (p.pooled !== undefined) return p.pooled;
  return (BUILTIN_POOLED.get(p.id) ?? false) || p.role === "worker";
}

export interface Pool {
  /** Synthetic node id for the collapsed group in the parent graph (`pool:<personaId>`). */
  nodeId: string;
  /** The pooled persona every member embodies. */
  personaId: string;
  /** The member position nodeIds (the real positions the pool stands in for). */
  memberNodeIds: string[];
  /** How many instances (= memberNodeIds.length). Not shown for a `plannerSized` slot (#3143). */
  count: number;
  /** True when every member has the identical external relationship signature (truly interchangeable);
   *  false = mixed wiring, unioned onto the stack — the drill-in shows who has what. */
  homogeneous: boolean;
  /** A WORKER-role (planner-sized) slot: the planner owns the count (#2388), so the card renders as a
   *  countless "planner-sized" stack rather than `×N` — and it collapses even from a SINGLE member. */
  plannerSized: boolean;
}

/** The external relationship signature of a position: every edge to a node OUTSIDE `memberSet`, as a
 *  sorted `dir|archetype|counterpart` string. Members with equal signatures are interchangeable; edges
 *  among members (a peer mesh) are excluded. */
function externalSignature(org: Team, nodeId: string, memberSet: Set<string>): string {
  const parts: string[] = [];
  for (const r of org.relationships) {
    if (r.from === nodeId && !memberSet.has(r.to)) parts.push(`out|${r.archetype}|${r.to}`);
    else if (r.to === nodeId && !memberSet.has(r.from)) parts.push(`in|${r.archetype}|${r.from}`);
  }
  return parts.sort().join("~");
}

/** Detect the pools: every STACKABLE persona (pooled, or worker-role — the engineer stack, #2436)
 *  placed ≥2× collapses. Mixed external wiring doesn't block the stack; it only clears `homogeneous`
 *  (e.g. Fleet Alpha's engineers — one overseen by the reviewer, one by the auditor — now stack, with
 *  both oversee edges unioned onto the stack node). Non-worker singletons (the scaffold) never stack.
 *  Deterministic (positions in author order). */
export function detectPools(org: Team, personas: Persona[]): Pool[] {
  const stackable = new Set(personas.filter(isStackable).map((p) => p.id));
  // Planner-sized personas (worker role — the planner owns the count, #2388/#3143): their slot collapses
  // to a countless stack even from ONE placement, since a single engineer node still means "the planner
  // creates however many". Every OTHER stackable persona needs a real swarm (≥2) to collapse.
  const plannerSizedIds = new Set(personas.filter((p) => p.role === "worker").map((p) => p.id));
  const byPersona = new Map<string, Position[]>();
  for (const p of org.positions) {
    if (p.kind === "agent" && p.personaId && stackable.has(p.personaId)) {
      (byPersona.get(p.personaId) ?? byPersona.set(p.personaId, []).get(p.personaId)!).push(p);
    }
  }
  const pools: Pool[] = [];
  for (const [personaId, members] of byPersona) {
    const plannerSized = plannerSizedIds.has(personaId);
    if (members.length < 2 && !plannerSized) continue;
    const memberSet = new Set(members.map((m) => m.nodeId));
    const sig0 = externalSignature(org, members[0].nodeId, memberSet);
    const homogeneous = members.every((m) => externalSignature(org, m.nodeId, memberSet) === sig0);
    pools.push({ nodeId: `pool:${personaId}`, personaId, memberNodeIds: members.map((m) => m.nodeId), count: members.length, homogeneous, plannerSized });
  }
  return pools;
}

export interface CollapsedOrg {
  /** The parent graph with each pool's members replaced by one synthetic pool node. */
  org: Team;
  /** Pool metadata keyed by the synthetic pool nodeId — the canvas renders these as stacked cards. */
  poolInfo: Record<string, Pool>;
}

const avg = (xs: number[]): number => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : 0);

/** Collapse an org for the parent view: each pool's members become ONE synthetic pool position at the
 *  members' centroid; external edges are rerouted to the pool node and deduped (by from|to|archetype);
 *  internal edges (both endpoints inside one pool) are dropped. A no-op when there are no pools. */
export function collapseOrg(org: Team, pools: Pool[]): CollapsedOrg {
  if (!pools.length) return { org, poolInfo: {} };
  const memberToPool = new Map<string, Pool>();
  for (const pool of pools) for (const m of pool.memberNodeIds) memberToPool.set(m, pool);

  const positions: Position[] = org.positions.filter((p) => !memberToPool.has(p.nodeId));
  const poolInfo: Record<string, Pool> = {};
  for (const pool of pools) {
    const members = org.positions.filter((p) => memberToPool.get(p.nodeId) === pool);
    positions.push({
      nodeId: pool.nodeId, kind: "agent", personaId: pool.personaId,
      x: Math.round(avg(members.map((m) => m.x ?? 0))), y: Math.round(avg(members.map((m) => m.y ?? 0))),
    });
    poolInfo[pool.nodeId] = pool;
  }

  const remap = (nodeId: string) => memberToPool.get(nodeId)?.nodeId ?? nodeId;
  const seen = new Set<string>();
  const relationships: Relationship[] = [];
  for (const r of org.relationships) {
    const from = remap(r.from), to = remap(r.to);
    if (from === to) continue; // an internal edge, folded away
    const key = `${from}|${to}|${r.archetype}`;
    if (seen.has(key)) continue; // duplicate collapsed edge (N members → one pool edge)
    seen.add(key);
    relationships.push({ ...r, id: `pool-edge:${key}`, from, to });
  }
  return { org: { ...org, positions, relationships }, poolInfo };
}

/** The pool's OWN graph, shown when you drill in: the members, every edge touching a member (the internal
 *  peer mesh + their edges out), and the boundary neighbor nodes those edges reach (context). Positions
 *  are the members' real stored coords, so drilling reads as zooming into that cluster. */
export function poolSubgraph(org: Team, pool: Pool): Team {
  const memberSet = new Set(pool.memberNodeIds);
  const relationships = org.relationships.filter((r) => memberSet.has(r.from) || memberSet.has(r.to));
  const nodeIds = new Set<string>(pool.memberNodeIds);
  for (const r of relationships) { nodeIds.add(r.from); nodeIds.add(r.to); }
  return { ...org, id: `${org.id}::${pool.nodeId}`, positions: org.positions.filter((p) => nodeIds.has(p.nodeId)), relationships };
}

// ── Auto-organize over pools (#2451) ─────────────────────────────────────────
// `autoLayout(org)` on the FULL org laid out every pooled member as an individual node while the
// canvas renders the COLLAPSED org — so the pool card (drawn at the members' centroid) landed at the
// row center, or BETWEEN hierarchy rows when mixed wiring (#2436) put members on different layers,
// and no collision pass ever saw the stacked card. The fix: lay out the graph the user is LOOKING AT
// (the collapsed org, with the pool node carrying its real stacked-card footprint), then write back
// through the pool abstraction — translate each member cluster so its centroid is the pool's
// laid-out spot, preserving the members' relative arrangement for drill-in (#2439).

/** The stacked card's shadow-card offset (design px) — TeamsCanvas renders the outermost shadow card
 *  at `translate(POOL_STACK_OFFSET, POOL_STACK_OFFSET)`, so a pool's true render footprint is the
 *  agent card plus this overhang in each axis. The layout must see THAT size (via `poolLayoutSizes`)
 *  so collision spaces the stack like the card the user actually sees. */
export const POOL_STACK_OFFSET = 11;

/** Per-node size overrides for `autoLayout` over a COLLAPSED org: each synthetic pool node takes the
 *  stacked card's real footprint (agent card + shadow-stack overhang). */
export function poolLayoutSizes(pools: Pool[]): Record<string, { w: number; h: number }> {
  const size = { w: NODE_SIZE.agent.w + POOL_STACK_OFFSET, h: NODE_SIZE.agent.h + POOL_STACK_OFFSET };
  return Object.fromEntries(pools.map((p) => [p.nodeId, size]));
}

// The degenerate-cluster spread: when every member sits on the SAME point (typically all unplaced at
// 0,0), a pure translation would keep them exactly coincident — so instead they get a small
// deterministic grid around the pool's laid-out spot (centroid still lands ON the spot). Steps are
// deliberately smaller than a card: the parent view shows one stack either way, and the drill-in's
// own auto-organize is the real untangler.
const SPREAD_X = 60;
const SPREAD_Y = 44;

/** Write a collapsed-org layout back onto the FULL org's positions (#2451). Non-pooled nodes take
 *  their laid-out spot directly. Each pool's members are TRANSLATED by one shared delta so their
 *  centroid — where the stacked card renders (`collapseOrg`) — equals the pool node's laid-out spot,
 *  preserving the members' relative arrangement (the #2439 drill-in contract). A coincident/unplaced
 *  member cluster gets a small deterministic spread around the spot instead (see above). Pure +
 *  deterministic; returns a fresh positions array. */
export function applyPoolLayout(org: Team, pools: Pool[], layout: Record<string, { x: number; y: number }>): Position[] {
  const moved = new Map<string, { x: number; y: number }>();
  for (const pool of pools) {
    const target = layout[pool.nodeId];
    if (!target) continue; // pool absent from the laid-out graph — leave its members untouched
    const members = org.positions.filter((p) => pool.memberNodeIds.includes(p.nodeId));
    const xs = members.map((m) => m.x ?? 0);
    const ys = members.map((m) => m.y ?? 0);
    if (xs.every((x) => x === xs[0]) && ys.every((y) => y === ys[0])) {
      // Degenerate: all members coincident — deterministic compact grid, centered so centroid = target.
      const cols = Math.ceil(Math.sqrt(members.length));
      const offs = members.map((_, i) => ({ x: (i % cols) * SPREAD_X, y: Math.floor(i / cols) * SPREAD_Y }));
      const cx = avg(offs.map((o) => o.x)), cy = avg(offs.map((o) => o.y));
      members.forEach((m, i) => moved.set(m.nodeId, { x: Math.round(target.x + offs[i].x - cx), y: Math.round(target.y + offs[i].y - cy) }));
    } else {
      // One shared delta for the whole cluster (integer inputs keep relative offsets EXACT through
      // the rounding, since every member rounds with the same fractional part).
      const dx = target.x - avg(xs), dy = target.y - avg(ys);
      members.forEach((m, i) => moved.set(m.nodeId, { x: Math.round(xs[i] + dx), y: Math.round(ys[i] + dy) }));
    }
  }
  return org.positions.map((p) => {
    const next = moved.get(p.nodeId) ?? layout[p.nodeId];
    return next ? { ...p, ...next } : p;
  });
}

/** Auto-organize INSIDE a drilled pool (#2451): re-lay out ONLY the members (over their internal peer
 *  mesh), then anchor the new cluster at the members' previous centroid so the surrounding context
 *  doesn't jump. Boundary neighbors belong to the PARENT view and are never moved — chosen over
 *  layering members against pinned boundary nodes because the members are one persona (a flat
 *  row/grid near their old spot reads well) and "context stays put" is the simplest honest contract
 *  from inside a drill. Returns the full org's positions with only the members changed. */
export function organizeDrilledPool(org: Team, pool: Pool): Position[] {
  const memberSet = new Set(pool.memberNodeIds);
  const members = org.positions.filter((p) => memberSet.has(p.nodeId));
  if (!members.length) return org.positions;
  const sub: Team = {
    ...org,
    positions: members,
    relationships: org.relationships.filter((r) => memberSet.has(r.from) && memberSet.has(r.to)),
  };
  const layout = autoLayout(sub);
  const dx = avg(members.map((m) => m.x ?? 0)) - avg(members.map((m) => layout[m.nodeId].x));
  const dy = avg(members.map((m) => m.y ?? 0)) - avg(members.map((m) => layout[m.nodeId].y));
  const moved = new Map(members.map((m) => [m.nodeId, { x: Math.round(layout[m.nodeId].x + dx), y: Math.round(layout[m.nodeId].y + dy) }]));
  return org.positions.map((p) => {
    const next = moved.get(p.nodeId);
    return next ? { ...p, ...next } : p;
  });
}

// Team view models (#2193) — pure presentation helpers that turn the org graph + the persona library +
// the vocabulary into the shapes the canvas + inspector render. React-free + unit-testable; the design
// prototype's per-role glyph/department metadata lives here (presentation only, not in the data model).
import type { SessionRole } from "@/shared/lib/session/sessionRoles";
import { roleCapability } from "@/shared/lib/session/sessionRoles";
import type { Persona } from "@/features/personas";
import { archetypeById, deriveCommunication, type CommunicationForm, type Team, type Position } from "@/features/teams/lib/team";

/** Per-role display metadata — the department bucket (left-rail grouping) + a glyph. Presentation-only
 *  (the role gate itself carries no glyph); a role not listed falls back to a neutral default.
 *  Intentionally inline: a view-layer glyph/label map, not seed library state — kept here by design
 *  rather than externalized to `data/` (reviewed in #2912; config-vs-presentation golden rule). */
export const ROLE_META: Record<string, { dept: string; glyph: string }> = {
  planner:    { dept: "Leadership",  glyph: "◆" },
  director:   { dept: "Leadership",  glyph: "◆" },
  worker:     { dept: "Engineering", glyph: "●" },
  issuer:     { dept: "Support",     glyph: "◇" },
  triage:     { dept: "Support",     glyph: "◇" },
  reviewer:   { dept: "Quality",     glyph: "◈" },
  tester:     { dept: "Quality",     glyph: "◈" },
  juror:      { dept: "Quality",     glyph: "▲" },
};

const KIND_GLYPH = { resource: "⬢", external: "◍" } as const;

export interface PositionDisplay {
  name: string;
  glyph: string;
  dept: string;
  /** The role tag (agents) — undefined for resource/external nodes. */
  role?: SessionRole;
  blurb: string;
  kind: Position["kind"];
}

/** Resolve a position's display fields, reading through to its persona for agent nodes. */
export function positionDisplay(pos: Position, personas: Persona[]): PositionDisplay {
  if (pos.kind !== "agent") {
    return {
      name: pos.label ?? pos.nodeId,
      glyph: KIND_GLYPH[pos.kind],
      dept: pos.kind === "resource" ? "Resource" : "External",
      blurb: pos.kind === "resource" ? "A shared resource the org stewards." : "An actor outside the org.",
      kind: pos.kind,
    };
  }
  const persona = personas.find((p) => p.id === pos.personaId);
  const role = persona?.role;
  const meta = (role && ROLE_META[role]) || { dept: "Team", glyph: "●" };
  return {
    name: pos.label ?? persona?.name ?? pos.nodeId,
    glyph: meta.glyph,
    dept: meta.dept,
    role,
    blurb: persona?.blurb ?? "",
    kind: "agent",
  };
}

export interface TierChip { label: string; tier: string }

/** The capability tiers a role carries, as `git·write`-style labels — omitting the `none` capabilities
 *  but always stating net as on/off (mirrors the design's node-card tier row). */
export function tierChips(role: SessionRole): TierChip[] {
  const cap = roleCapability(role);
  const out: TierChip[] = [];
  for (const k of ["git", "github", "code"] as const) {
    if (cap[k] !== "none") out.push({ label: `${k}·${cap[k]}`, tier: cap[k] });
  }
  out.push({ label: `net·${cap.net === "none" ? "off" : "on"}`, tier: cap.net === "none" ? "off" : "on" });
  return out;
}

export interface CommSummary {
  /** The relationship's other end. */
  counterpartNode: string;
  counterpartName: string;
  archetype: string;
  archetypeLabel: string;
  hue: number;
  /** Forms this position SENDS across the edge. */
  sends: CommunicationForm[];
  /** Forms this position RECEIVES across the edge. */
  receives: CommunicationForm[];
}

/** The per-relationship communication summary for a position — `deriveCommunication` grouped by
 *  counterpart+archetype, so the inspector shows one card per relationship (head = who, then the forms
 *  sent/received). This is the auto-derived "who I talk to and how", the generate-from-facets payoff. */
export function positionComms(org: Team, pos: Position, personas: Persona[]): CommSummary[] {
  const byKey = new Map<string, CommSummary>();
  for (const edge of deriveCommunication(org, pos.nodeId)) {
    const key = `${edge.withNode}:${edge.archetype}`;
    let sum = byKey.get(key);
    if (!sum) {
      const arch = archetypeById(edge.archetype);
      const other = org.positions.find((p) => p.nodeId === edge.withNode);
      sum = {
        counterpartNode: edge.withNode,
        counterpartName: other ? positionDisplay(other, personas).name : edge.withNode,
        archetype: edge.archetype,
        archetypeLabel: arch?.label ?? edge.archetype,
        hue: arch?.hue ?? 0,
        sends: [],
        receives: [],
      };
      byKey.set(key, sum);
    }
    (edge.dir === "out" ? sum.sends : sum.receives).push(edge.form);
  }
  return [...byKey.values()];
}

/** A CSS color for an archetype hue (oklch, so it sits in the same space as the app's tokens). */
export function hueColor(hue: number, l = 0.72, c = 0.13): string {
  return `oklch(${l} ${c} ${hue})`;
}

/** The accent color for a communication form, by its semantics (mirrors the design): authority-bearing
 *  forms are amber, blocking/advisory forms blue, the review gate purple, the rest neutral. */
export function formColor(form: CommunicationForm): string {
  if (form.id === "review") return hueColor(300, 0.75, 0.12);
  if (form.authority) return hueColor(70, 0.78, 0.12);
  if (form.id === "escalation" || form.id === "consult") return hueColor(250, 0.75, 0.12);
  return "var(--fg-dim)";
}

/** The direction glyph shown on a form chip (↓ down · ↑ up · ↔ lateral · → in/out · ⊘ the review gate). */
export function formArrow(form: CommunicationForm): string {
  if (form.id === "review") return "⊘";
  switch (form.direction) {
    case "down": return "↓";
    case "up": return "↑";
    case "lateral": return "↔";
    default: return "→";
  }
}

// Outline diff (#4169, epic #3604) — compare the element tree the FILE copy of a page renders against the
// one its GRAPH node renders, and answer the question shadow mode exists to answer: is this page
// graph-identical, and if not, how far off is it?
//
// The comparison is a MULTISET difference over element PATHS (`Screen>TabBar>Chip`), not a tree-edit
// distance. A path carries nesting, so a moved element shows up; multiplicity carries repetition, so a
// dropped one of three `<Chip>`s shows up as one differing node rather than as "identical". Edit distance
// would give a prettier number and needs an alignment pass that has to guess which node matched which —
// this cannot be wrong about what it reports, only coarse.
import { outlinePaths, countNodes, type OutlineNode } from "@/shared/lib/runtime/shadow/jsxOutline";

/** The structural verdict for ONE module (a page record or one of its tab-body siblings). */
export interface OutlineDiff {
  /** No structural difference at all — the graph node renders the same element tree as the file. */
  identical: boolean;
  /** Nodes present in one copy and not the other (counted with multiplicity) — the "N nodes differ". */
  differing: number;
  /** Total elements in the FILE copy, so `differing` reads against a denominator. */
  fileNodes: number;
  /** Total elements in the GRAPH copy. */
  graphNodes: number;
  /** Element paths the file renders and the graph node does not (capped — this is a signal, not a report). */
  onlyInFile: string[];
  /** Element paths the graph node renders and the file does not. */
  onlyInGraph: string[];
}

/** How many example paths each side reports. The count is the metric; the samples are for the worklist. */
const SAMPLE_CAP = 12;

/** Diff two element outlines. Order-independent within a parent (the paths are a multiset), so a
 *  reordering of siblings is NOT drift — only a changed shape is. */
export function diffOutlines(fileTree: OutlineNode[], graphTree: OutlineNode[]): OutlineDiff {
  const filePaths = outlinePaths(fileTree);
  const graphPaths = outlinePaths(graphTree);
  const onlyInFile = multisetMinus(filePaths, graphPaths);
  const onlyInGraph = multisetMinus(graphPaths, filePaths);
  const differing = onlyInFile.length + onlyInGraph.length;
  return {
    identical: differing === 0,
    differing,
    fileNodes: countNodes(fileTree),
    graphNodes: countNodes(graphTree),
    onlyInFile: onlyInFile.slice(0, SAMPLE_CAP),
    onlyInGraph: onlyInGraph.slice(0, SAMPLE_CAP),
  };
}

/** The entries of `a` not matched one-for-one by an entry of `b` (multiset difference, order preserved). */
function multisetMinus(a: string[], b: string[]): string[] {
  const remaining = new Map<string, number>();
  for (const path of b) remaining.set(path, (remaining.get(path) ?? 0) + 1);
  const out: string[] = [];
  for (const path of a) {
    const left = remaining.get(path) ?? 0;
    if (left > 0) remaining.set(path, left - 1);
    else out.push(path);
  }
  return out;
}

// Page binding analysis (#4169, epic #3604) — given a graph page's source, work out WHICH BEHAVIOURS it
// needs from the app and which of those are not registered.
//
// This is the half of shadow mode that matters for the epic. "Presentation is data, behavior stays code":
// a page node carries the skeleton, and everything it does — store reads, hooks, `usePoll`, `bscJson`,
// feature libs — arrives as a REGISTERED module the loader's `require` hands back (`moduleRegistry`). An
// import with no registration does not fail quietly: `makeRequire` throws by name, the error boundary
// catches it, and the page shows its fallback. So "is this page ready to render from the graph?" is
// exactly "is every specifier it requires registered?" — and today that is a judgement call. This makes it
// a list.
//
// It mirrors what the loader does at runtime, statically: `routeImport` consults the graph resolver FIRST
// (a sibling by id, or a component whose `provides` matches the specifier) and vendors that source into
// the same compile; anything else stays external and goes through the registry. So the walk below vendors
// what the loader would vendor, recurses into it, and collects what is left over — the exact set of
// `require()` calls the compiled module will make. No esbuild needed, which is why this runs in a node
// test as happily as in the app.

/** One `… from "specifier"` in a source: the module and the symbols taken from it. */
export interface ImportRef {
  specifier: string;
  /** Imported names (the ORIGINAL name, not the local alias) — the "behaviour names" of a report. A
   *  namespace import is `*`; a default import is `default`; a bare side-effect import has none. */
  symbols: string[];
}

/** A specifier the loaded page will `require()` at runtime, and which of its modules asked for it. */
export interface ExternalImport extends ImportRef {
  /** The graph module ids whose source imports this specifier (the page itself, or a vendored sibling). */
  importedBy: string[];
}

/** Resolve a specifier to another graph component's source, exactly as the app's `resolveGraphSource`
 *  does — `@/components/<id>` for a sibling, or a record whose `provides` matches (#3660). `null` when the
 *  specifier is not a graph node, in which case it stays external and must be registered. */
export type SiblingResolver = (specifier: string) => { id: string; source: string } | null;

/** `import`/`export … from "x"`, capturing the clause so its symbols (and its `type` marker) can be read.
 *  The re-export form is included deliberately: esbuild compiles `export { X } from "./y"` to the same
 *  `require("./y")` an import produces, so an unregistered re-export breaks the loader identically —
 *  the gap that shipped `projectspage` broken (#3874). */
//  The clause is `[^"';]*?` — it may span lines (a multi-line named-import list) but may cross neither a
//  quote nor a statement end, so the scan cannot run past a side-effect import or an `export function`
//  into the next `from "…"` and invent an import that is not there.
const FROM_IMPORT = /^[ \t]*(import|export)\s+([^"';]*?)\s*from\s*["']([^"']+)["']/gm;

/** A side-effect import (`import "./x.css"`) — no clause, still a `require` at runtime. */
const BARE_IMPORT = /^[ \t]*import\s*["']([^"']+)["']/gm;

/** Every module specifier a source imports, with the symbols it takes.
 *
 *  TYPE-ONLY imports are excluded: esbuild erases them, so they never become a `require` and an
 *  unregistered one cannot break anything. Reporting them would pad the worklist with work that is not
 *  work. A clause with even one value binding is kept — that module IS required. */
export function parseImports(source: string): ImportRef[] {
  const refs: ImportRef[] = [];
  for (const m of source.matchAll(FROM_IMPORT)) {
    const clause = m[2];
    if (/^type\s/.test(clause)) continue; // `import type { X } from …` — erased
    const symbols = clauseSymbols(clause);
    // `import { type A, type B } from …` — every binding erased, so the whole import goes with them.
    if (symbols.length > 0 && symbols.every((s) => s.startsWith("type "))) continue;
    refs.push({ specifier: m[3], symbols: symbols.map((s) => s.replace(/^type\s+/, "")) });
  }
  for (const m of source.matchAll(BARE_IMPORT)) refs.push({ specifier: m[1], symbols: [] });
  return refs;
}

/** The names an import clause binds, as written on the MODULE's side (`{ a as b }` → `a`), with an inline
 *  `type ` marker preserved so [`parseImports`] can spot an all-type clause. */
function clauseSymbols(clause: string): string[] {
  const names: string[] = [];
  const braced = /\{([\s\S]*)\}/.exec(clause);
  const head = clause.slice(0, braced ? clause.indexOf("{") : undefined).replace(/,\s*$/, "").trim();
  if (head) names.push(head.startsWith("*") ? "*" : "default"); // `* as ns` / `export *` vs a default import
  if (braced) {
    for (const part of braced[1].split(",")) {
      const name = part.trim().split(/\s+as\s+/)[0].trim();
      if (name) names.push(name);
    }
  }
  return names;
}

/** The full binding picture for one graph page. */
export interface BindingReport {
  /** Graph modules pulled into the page's compile (the page id first, then vendored siblings). */
  vendored: string[];
  /** Specifiers the compiled page will `require()` from the app. */
  external: ExternalImport[];
  /** The subset of `external` with no registered module — every one of these throws when the page loads. */
  unbound: ExternalImport[];
}

/**
 * Walk a graph page's source the way the loader compiles it — vendoring graph siblings, recursing into
 * them, and collecting every specifier that stays external — then split those by whether the app has
 * registered them.
 *
 * `isRegistered` is injected (the live `isAppModule`, or a fake in a test) so this stays pure. It is read
 * at CALL time, which matters: a feature's platform surface registers when its module loads, so a report
 * taken before that reads as unbound. The runner loads a page's feature before analysing it.
 */
export function analyzeBindings(
  page: { id: string; source: string },
  resolveSibling: SiblingResolver,
  isRegistered: (specifier: string) => boolean,
): BindingReport {
  const vendored: string[] = [];
  const seen = new Set<string>();
  const bySpecifier = new Map<string, ExternalImport>();
  const queue: { id: string; source: string }[] = [page];

  while (queue.length) {
    const module = queue.shift() as { id: string; source: string };
    if (seen.has(module.id)) continue; // a sibling cycle must not spin the walk
    seen.add(module.id);
    vendored.push(module.id);
    for (const ref of parseImports(module.source)) {
      const sibling = resolveSibling(ref.specifier);
      if (sibling) {
        queue.push(sibling);
        continue;
      }
      const existing = bySpecifier.get(ref.specifier);
      if (existing) {
        for (const s of ref.symbols) if (!existing.symbols.includes(s)) existing.symbols.push(s);
        if (!existing.importedBy.includes(module.id)) existing.importedBy.push(module.id);
      } else {
        bySpecifier.set(ref.specifier, { specifier: ref.specifier, symbols: [...ref.symbols], importedBy: [module.id] });
      }
    }
  }

  const external = [...bySpecifier.values()].sort((a, b) => a.specifier.localeCompare(b.specifier));
  return { vendored, external, unbound: external.filter((e) => !isRegistered(e.specifier)) };
}

// The theme try-on palette strip's model (#2834) — the semantic base-palette tokens a theme retints,
// grouped for display (surfaces · text · borders · accent · status). These are exactly the keys every
// packaged palette theme overrides; the strip shows each as the theme's override value when set, else
// the live base token default. Pure (React-free) → unit-testable.

export interface PaletteToken {
  /** Short display name under the swatch. */
  name: string;
  /** The CSS custom property the swatch reflects. */
  token: string;
}

export interface PaletteGroup {
  label: string;
  tokens: PaletteToken[];
}

/** The semantic palette, grouped — the 14 base-palette tokens every packaged theme retints. */
export const PALETTE_GROUPS: PaletteGroup[] = [
  { label: "Surfaces", tokens: [
    { name: "canvas", token: "--bg-canvas" },
    { name: "panel", token: "--bg-panel" },
    { name: "elev", token: "--bg-elev" },
    { name: "elev2", token: "--bg-elev2" },
  ] },
  { label: "Text", tokens: [
    { name: "fg", token: "--fg" },
    { name: "muted", token: "--fg-muted" },
    { name: "dim", token: "--fg-dim" },
  ] },
  { label: "Borders", tokens: [
    { name: "border", token: "--border" },
    { name: "soft", token: "--border-soft" },
  ] },
  { label: "Accent", tokens: [
    { name: "accent", token: "--accent" },
    { name: "dim", token: "--accent-dim" },
  ] },
  { label: "Status", tokens: [
    { name: "success", token: "--success" },
    { name: "info", token: "--info" },
    { name: "danger", token: "--danger" },
  ] },
];

/** The swatch colour for a token under a theme: the theme's literal override if it sets it, else the
 *  live base token via `var()` (so a base-look theme with no overrides shows the app defaults). */
export function swatchColor(vars: Record<string, string>, token: string): string {
  return vars[token] ?? `var(${token})`;
}

// Per-pane turn-activity gating for the console status dot (#1184).
//
// The status dot's only per-turn signal is a 1.5s silence timer (`QUIET_MS` in TerminalView),
// which can't tell "done" from "working but silent" — so a worker that's thinking, running a long
// silent tool call, or backing off false-idles mid-turn. The fix drives authoritative turn
// boundaries from Claude Code hooks: `bsc-activity run` on UserPromptSubmit (a turn opens) and
// `bsc-activity idle` on Stop/SubagentStop (the turn closes), recorded to `activity.log`.
// `bsc logs pane-activity` (over the `bsc` bridge, #2144) returns the latest state per pane;
// TerminalView polls it and uses the pure helpers here to decide whether a pane's turn is still open.
//
// ADDITIVE / SAFE: the gate only PREVENTS a wrongful idle — a pane whose turn is still open is kept
// "run" past the silence timeout. It never forces idle on its own; a pane still goes idle on the
// authoritative Stop (which records `idle`, closing the turn) or, for non-bash / never-launched
// panes that emit no activity at all, on the silence timer exactly as before (no regression).

/** One pane's latest turn-boundary state, as serialized by `bsc logs pane-activity`
 *  (`logs::PaneActivity` — plain snake_case, no serde rename, so the keys match the struct). */
export interface PaneActivity {
  pane: string;
  /** `"run"` — a turn is open (the agent is working); `"idle"` — the turn closed at a Stop;
   *  `"attn"` (#4005) — Claude Code fired `Notification`, i.e. it is STOPPED waiting on the user
   *  (a permission prompt, or a long input idle). */
  state: "run" | "idle" | "attn";
  /** Epoch-ms timestamp of the event. */
  at: number;
}

/**
 * Whether this pane's turn is still OPEN — i.e. the silence timer must NOT idle it.
 *
 * True only when the latest recorded activity is a `run` (UserPromptSubmit with no following Stop).
 * `undefined` (no activity recorded — a non-bash session, or a pane that hasn't taken a turn yet)
 * is NOT a turn-open signal, so the silence timer stays authoritative and behavior is unchanged.
 */
export function isTurnOpen(activity: PaneActivity | undefined): boolean {
  return activity?.state === "run";
}

/**
 * Is this pane STOPPED waiting on the user (#4005)?
 *
 * Distinct from idle in the way that matters: an idle pane is finished, an `attn` pane is blocked and
 * will stay blocked until a person acts. That is the most actionable state in the cockpit and, before
 * this, the least visible one — a pane awaiting a permission prompt looked exactly like a quiet one.
 *
 * Deliberately NOT turn-open ({@link isTurnOpen} stays false): the agent is not working, so the
 * silence timer should be free to settle the status dot as it always has. This adds a signal; it does
 * not re-gate the existing one.
 */
export function needsAttention(activity: PaneActivity | undefined): boolean {
  return activity?.state === "attn";
}

/**
 * Pick this pane's latest activity record out of the flat per-pane list `bsc logs pane-activity`
 * returns. A small helper so the predicate above and the poller in TerminalView agree on the lookup
 * (and so the gating logic is unit-testable end-to-end without a running poll).
 */
export function paneActivityFor(rows: PaneActivity[] | undefined, paneId: string): PaneActivity | undefined {
  return rows?.find((r) => r.pane === paneId);
}

/** Grace window after an `idle` event during which the turn is still treated as open (#1184).
 *
 *  The original reason was the `bsc-defer` Stop hook: a worker recorded `idle`, the hook refused the
 *  stop, and the next turn reopened `run` a moment later — so the dot blinked idle→run between them.
 *  That hook is GONE (#session-stop-is-honoured) and a worker's `idle` now means it is finished.
 *
 *  The grace is kept because the same gap remains wherever a session legitimately takes back-to-back
 *  turns — the designer LOOP pump (#3292) driving a session turn-by-turn, or a user sending a
 *  follow-up straight after a reply. It is safe by construction: it only ever DELAYS the silence
 *  timer, never forces an idle, so at worst a finished pane settles 2.5s later than it could. */
export const ACTIVITY_IDLE_GRACE_MS = 2500;

/**
 * Debounced turn-open check for the poller. Like {@link isTurnOpen}, but a freshly-`idle` pane is
 * still treated as open for `graceMs` after the idle event — smoothing the worker flicker above.
 * A genuinely done pane (its `idle` older than the grace) releases the gate, so the silence timer
 * idles it as normal. `run` is always open; no activity is never open (non-bash fallback unchanged).
 */
export function isTurnOpenDebounced(
  activity: PaneActivity | undefined,
  now: number,
  graceMs: number = ACTIVITY_IDLE_GRACE_MS,
): boolean {
  if (!activity) return false;
  if (activity.state === "run") return true;
  return now - activity.at < graceMs;
}

// Pane identity (#1176). Pane state, the PTY, and crash recovery must key off a STABLE identity
// id, not the positional `t{tabIdx}p{paneIdx}` — positional keys get reused when a tab is closed
// and a new one lands on the index, so the new pane inherits persisted state (paneWasClaude, cwd,
// restoreRequested) and resumes a previous session.
//
// Identity is minted where a pane is created:
//   - MANUAL console ("+" button): an ephemeral id unique to the tab — `man:<tabId>:p<idx>`. The
//     tab already carries a stable uuid `id`, so a fresh manual tab can never collide into an old
//     one's state, and (because the id isn't a `project:…` identity) it is excluded from recovery.
//   - FLEET / TRIAGE panes: a meaningful id minted by project planning / triage launch
//     (`<projectKey>:<streamId>`, `<projectKey>:director`, `<projectKey>:<repo>:triage`), recorded
//     on the tab's `paneIds[]`. Recovery reconnects only the exact identity it belongs to.
//
// Stage 1 wires the MANUAL path; fleet/triage tabs (those with `kind`) keep the positional id until
// Stage 2 mints their `paneIds`.

export interface PaneIdentityTab {
  id?: string;
  /** Fleet ("build") / "triage" tabs are app-created; absence ⇒ a manually-created console. */
  kind?: "build" | "triage";
  /** Per-cell identity ids minted at fleet/triage launch (Stage 2). */
  paneIds?: string[];
}

/** The legacy positional id — still used for fleet/triage tabs until Stage 2. */
export function positionalPaneId(tabIdx: number, paneIdx: number): string {
  return `t${tabIdx}p${paneIdx}`;
}

/** A manual console pane's ephemeral, per-tab id. */
export function manualPaneId(tabId: string, paneIdx: number): string {
  return `man:${tabId}:p${paneIdx}`;
}

/** Fleet worker / director identity ids. */
export function fleetPaneId(projectKey: string, streamId: string): string {
  return `${projectKey}:${streamId}`;
}
export function directorPaneId(projectKey: string): string {
  return `${projectKey}:director`;
}

/** A per-repo triage pane's identity id. */
export function triagePaneId(projectKey: string, repo: string): string {
  return `${projectKey}:${repo}:triage`;
}

/** Whether an id is a manual console pane — manual panes are never auto-recovered (#1176). */
export function isManualPaneId(id: string): boolean {
  return id.startsWith("man:");
}

/**
 * Whether an id is the dedicated PLANNER pane — `planning_<key>` (Planning.tsx), the intentional
 * exception to the `<key>:<stream>` identity scheme. A planning session is re-entered via the
 * Projects page, not restored from the crash-recovery banner, so it's excluded from recovery (#1579).
 */
export function isPlanningPaneId(id: string): boolean {
  return id.startsWith("planning_");
}

/**
 * Resolve a pane's identity id from its tab + grid position. A minted `paneIds[idx]` (fleet/triage,
 * Stage 2) wins; otherwise a fleet/triage tab keeps the positional id (Stage 1), a manual tab with a
 * stable `id` gets a `man:` id, and an id-less legacy tab falls back to positional.
 */
export function paneIdFor(tab: PaneIdentityTab | undefined, tabIdx: number, paneIdx: number): string {
  const minted = tab?.paneIds?.[paneIdx];
  if (minted) return minted;
  if (tab?.kind) return positionalPaneId(tabIdx, paneIdx);
  if (tab?.id) return manualPaneId(tab.id, paneIdx);
  return positionalPaneId(tabIdx, paneIdx);
}

/**
 * Whether `paneId` is one of the cells `tab` (at grid index `tabIdx`) owns — the inverse of
 * `paneIdFor`. A minted id matches when it is in the tab's `paneIds[]`; a `man:<tabId>:…` id
 * matches when the tab's stable `id` matches; a legacy positional `t<idx>p…` id matches when
 * the tab index matches. Director / worker / triage identity ids only ever belong via `paneIds`.
 *
 * This is the identity-aware replacement for parsing a positional key out of a pane id: a status
 * rollup or a stale-status clear must work for manual (`man:`) and minted fleet/triage ids too,
 * not just the legacy positional shape (#1176).
 */
export function paneBelongsToTab(paneId: string, tab: PaneIdentityTab, tabIdx: number): boolean {
  if (tab.paneIds?.includes(paneId)) return true;
  const parsed = parsePaneIdentity(paneId);
  if (!parsed) return false;
  if (parsed.kind === "manual") return !!tab.id && parsed.tabId === tab.id;
  if (parsed.kind === "positional") return parsed.tabIdx === tabIdx;
  return false;
}

/**
 * Find the tab that owns `paneId` (and its index), or null. Scans by identity (`paneBelongsToTab`)
 * so a manual (`man:…`) or minted fleet/triage id resolves to its real tab — the positional
 * `parsePaneKey` could only ever resolve legacy `t<idx>p…` ids, which silently dropped the rollup
 * for every identity-keyed pane (#1176).
 */
export function findPaneOwnerTab<T extends PaneIdentityTab>(
  tabs: readonly T[],
  paneId: string,
): { tab: T; tabIdx: number } | null {
  for (let i = 0; i < tabs.length; i++) {
    if (paneBelongsToTab(paneId, tabs[i], i)) return { tab: tabs[i], tabIdx: i };
  }
  return null;
}

// ── Parsing identity ids back into meaning (#1266) ──────────────────────────────
//
// The id grammar is self-describing, so a session can be recovered from its NAME alone —
// the key to scanning durable, store-independent sources (the pty ledger, the worktree tree)
// and rebuilding the session topology when the persisted store has lost it.

/** The shape a pane identity id encodes. `positional` is the legacy `t{idx}p{idx}` form. */
export type PaneIdentityKind = "director" | "worker" | "triage" | "manual" | "positional";

export interface ParsedPaneIdentity {
  kind: PaneIdentityKind;
  /** The id as given. */
  raw: string;
  /** Present for director / worker / triage. */
  projectKey?: string;
  /** Present for a worker — its stream id. */
  streamId?: string;
  /** Present for a triage pane — the repo (`owner/name`). */
  repo?: string;
  /** Present for a manual console — its owning tab's stable id. */
  tabId?: string;
  /** Present for manual / positional — the grid cell index. */
  paneIdx?: number;
  /** Present for positional — the tab index. */
  tabIdx?: number;
}

/**
 * Parse a pane identity id back into its structured meaning — the inverse of the minting
 * helpers above (#1266). The grammar:
 *
 *   man:<tabId>:p<idx>          → manual console (ephemeral; never auto-recovered)
 *   t<idx>p<idx>                → legacy positional id
 *   <projectKey>:<repo>:triage  → per-repo triage pane
 *   <projectKey>:director       → a project's director
 *   <projectKey>:<streamId>     → a fleet worker
 *
 * Project keys are sanitized to `[A-Za-z0-9-]` (no colons), so colons are purely structural
 * separators and repo full names carry `/`, never `:`. Returns `null` for an unrecognized
 * shape. Known ambiguity: a worker whose stream id were literally `director` (or a 2-part
 * `<key>:triage`) would classify as director/worker respectively — real planner stream ids
 * never collide with those reserved tails.
 */
export function parsePaneIdentity(id: string): ParsedPaneIdentity | null {
  // Manual: man:<tabId>:p<idx>. The tabId may contain hyphens but no colon; the :p<n> tail is fixed.
  const manual = /^man:(.+):p(\d+)$/.exec(id);
  if (manual) {
    return { kind: "manual", raw: id, tabId: manual[1], paneIdx: Number(manual[2]) };
  }
  // Legacy positional: t<idx>p<idx>.
  const positional = /^t(\d+)p(\d+)$/.exec(id);
  if (positional) {
    return { kind: "positional", raw: id, tabIdx: Number(positional[1]), paneIdx: Number(positional[2]) };
  }
  const parts = id.split(":");
  // Triage: <key>:<repo>:triage — a "triage" tail with the repo in between (repo has no colon).
  if (parts.length >= 3 && parts[parts.length - 1] === "triage" && parts[0]) {
    return { kind: "triage", raw: id, projectKey: parts[0], repo: parts.slice(1, -1).join(":") };
  }
  // Director: <key>:director.
  if (parts.length === 2 && parts[1] === "director" && parts[0]) {
    return { kind: "director", raw: id, projectKey: parts[0] };
  }
  // Worker: <key>:<streamId> — both parts non-empty.
  if (parts.length >= 2 && parts[0] && parts.slice(1).join(":")) {
    return { kind: "worker", raw: id, projectKey: parts[0], streamId: parts.slice(1).join(":") };
  }
  return null;
}

/**
 * The identity to provision a per-agent sandbox Linux USER for (#1994), or `null` when this pane must
 * keep the sealed distro's shared default user.
 *
 * Per-agent filesystem isolation: a sandboxed FLEET pane — a `<projectKey>:<streamId>` worker or the
 * `<projectKey>:director`, running INSIDE the sealed WSL2 distro (`distro` set) — runs as its OWN
 * non-root Linux user with a locked-down (`700`) home, so co-located agents can't read or tamper with
 * its files even via raw Bash. Every other pane (manual / triage / planner / positional) and every
 * non-sandboxed pane (no `distro`) keep the distro's shared default user.
 *
 * The DIRECTOR gets its own user too (#4260): the issue's requirement is that worker↔director be
 * isolated by the OS rather than by the `bsc-scope` write hook alone. It costs the director nothing —
 * its cwd is the project hub, which lives in the group-shared base (`SHARED_BASE`) that every agent
 * user reaches, not in any one home.
 *
 * Returns the pane id itself — the agent's STABLE identity (`fleetPaneId` / `directorPaneId`) — so a
 * relaunch re-derives (via the Rust `agent_user_name`) and reuses the SAME Linux user + home. Pure (no
 * invoke) so the "which pane gets a user" decision is unit-testable; the caller provisions it with
 * `ensure_sandbox_user` and threads the returned username to `pty_create`'s `wslUser`.
 */
export function sandboxUserIdentity(paneId: string, distro: string | undefined): string | null {
  if (!distro) return null;
  const kind = parsePaneIdentity(paneId)?.kind;
  return kind === "worker" || kind === "director" ? paneId : null;
}

/**
 * The Rust command + args that resolve a pane's on-disk dir from its identity (#1819 hardening) — for
 * a claude pane whose configured cwd came back EMPTY (the async `bscBaseDir` mirror wasn't loaded when
 * the pane's cwd was set, so `projectRepoCwd`/`projectHubCwd` returned ""). The launch can then recover
 * an authoritative absolute path from the backend instead of running permission-less.
 *
 * `triage` → its repo clone dir (`repo_dir_path`); `director` → the project hub (`project_dir_path`).
 * Returns `null` for an id whose dir can't be derived from the id alone — manual/positional panes, or a
 * `worker` (its cwd is a worktree keyed by the agent id, which `ensure_worktree` already supplies). Pure
 * (no invoke) so it's unit-testable; the caller runs the returned command.
 */
export function paneCwdRecovery(
  paneId: string,
): { cmd: "repo_dir_path" | "project_dir_path"; args: Record<string, string> } | null {
  const id = parsePaneIdentity(paneId);
  if (!id?.projectKey) return null;
  if (id.kind === "triage" && id.repo) {
    return { cmd: "repo_dir_path", args: { projectKey: id.projectKey, repo: id.repo } };
  }
  if (id.kind === "director") {
    return { cmd: "project_dir_path", args: { projectKey: id.projectKey } };
  }
  return null;
}

// Shared app-to-agent message injection (#375). We deliver coordination messages by typing
// into a live claude pane's stdin; doing that naively dumps the text character-by-character
// into the TUI input box, where it interleaves with the TUI's own rendering and reads as a
// garbled wall of text. Wrapping it in BRACKETED PASTE markers makes the terminal hand the
// whole string to the TUI as a single atomic paste (Claude Code shows a "[Pasted text]"
// chip), after which Enter submits it cleanly. Built from char codes so no literal escape
// bytes live in the source. Used by the director pump, CI watcher, and coordinator wakes.
import { safeInvoke } from "@/shared/lib/core/safeInvoke";

const ESC = String.fromCharCode(27);
const CR = String.fromCharCode(13);
const PASTE_START = ESC + "[200~";
const PASTE_END = ESC + "[201~";

/** How long to let the TUI settle after ESC before pasting. The dialog tears down and the composer
 *  re-renders; pasting into that gap puts the text nowhere. Same order as the paste→Enter gap below. */
const DISMISS_SETTLE_MS = 80;

/**
 * Inject `text` into a pane as one atomic bracketed paste, then submit with a SEPARATE Enter.
 * The two must be separate writes with a small gap: Claude Code debounces a paste, so a CR
 * glued onto the same write is swallowed as content (a trailing newline) instead of being
 * treated as the submit keypress — which left the message sitting in the input box unsent.
 *
 * `clearPending` (#4253) sends ESC first, for a pane that may be STOPPED on a permission dialog.
 * Everything above assumes the pane is sitting in its composer; a blocked one is not. The paste
 * lands in the dialog instead, and the Enter CONFIRMS WHATEVER OPTION IS HIGHLIGHTED — so a
 * director redirect was swallowed while the coordination log recorded it as delivered, and the
 * submit keypress could answer a permission question nobody read. ESC returns Claude Code to its
 * composer, after which the normal path works as designed.
 *
 * It is OPT-IN rather than the default because ESC on a pane mid-turn INTERRUPTS that turn. That is
 * exactly right for a redirect and wrong for a passive coordination message, so the two cannot share
 * one default — see `injectRedirect` for the interrupting form.
 */
export async function injectPrompt(
  paneId: string,
  text: string,
  opts?: { clearPending?: boolean },
): Promise<void> {
  if (opts?.clearPending) {
    await safeInvoke("pty_write", { paneId, data: ESC }, undefined);
    await new Promise((r) => setTimeout(r, DISMISS_SETTLE_MS));
  }
  await safeInvoke("pty_write", { paneId, data: PASTE_START + text + PASTE_END }, undefined);
  await new Promise((r) => setTimeout(r, 60));
  await safeInvoke("pty_write", { paneId, data: CR }, undefined);
}

/**
 * Inject work that must LAND — dismissing a pending permission dialog (and interrupting a running
 * turn) first. The form for a director redirect or a wake: the point is to change what the session is
 * doing, so leaving it parked on its old prompt defeats the delivery.
 *
 * Use plain {@link injectPrompt} for a passive message that should queue behind the current turn.
 */
export async function injectRedirect(paneId: string, text: string): Promise<void> {
  return injectPrompt(paneId, text, { clearPending: true });
}

// Pure logic for the chained-digit console pane selector (Ctrl+Shift + digits).

/**
 * Commit window after the last digit while Ctrl+Shift is held (ms). The buffer
 * also commits immediately when Ctrl/Shift is released, so single-digit
 * selections feel instant — this timeout only matters if the modifier is held.
 */
export const PANE_SELECT_COMMIT_MS = 800;

/**
 * Resolve a typed digit buffer (accumulated while Ctrl+Shift is held) to a
 * 0-based pane index, or null when it doesn't name a real pane in the grid.
 *
 * Pane numbers are 1-based as typed (1 → first pane), so "13" → index 12. A
 * leading zero is rejected so "0"/"01" never select pane 0, and numbers beyond
 * the active grid are ignored.
 *
 * @param buffer digits typed so far, e.g. "1" or "13".
 * @param paneCount number of panes in the active tab's grid.
 */
export function resolvePaneFromBuffer(buffer: string, paneCount: number): number | null {
  if (!/^\d+$/.test(buffer)) return null;
  if (buffer[0] === "0") return null;       // leading zero → no pane 0
  const idx = parseInt(buffer, 10) - 1;     // 1-based → 0-based
  if (idx < 0 || idx >= paneCount) return null;
  return idx;
}

// Canonical pane activity status (#435), shared by the console grid, the per-tab
// fleet rollup, and the tunnel's desktop→mobile status mapping. ONE vocabulary so
// the dot in a pane, the dot on a tab, and the phone mirror can never disagree:
//   • "run"  — a session is actively working (its turn is in flight).
//   • "on"   — a session is attached/connected but at rest (at its prompt).
//   • "idle" — no live session in the cell.
//
// The pure helpers here are the single decision surface for how those per-pane
// states roll up to a tab, which panes count, and when a stale status is dropped —
// extracted from the console so the rules are unit-testable in isolation.
//
// Pane ids are the STABLE identity ids minted by `paneIdFor` (#1176) — `man:<tabId>:p<n>` for a
// manual tab, the minted `paneIds[]` for fleet/triage — NOT the legacy positional `t<idx>p<n>`.
// So the rollup/clear here resolve cells through `paneIdFor` / `paneBelongsToTab` rather than
// reconstructing positional keys, which only ever matched the legacy shape.
import { paneIdFor, paneBelongsToTab, type PaneIdentityTab } from "@/app/console/lib/paneIdentity";

export type PaneStatus = "run" | "on" | "idle";

/** A tab as the status helpers need it: its layout (cell count) + identity (to mint pane ids). */
export type StatusTab = PaneIdentityTab & { layout: string; state?: PaneStatus };

/** Legacy positional pane key for a (tab, pane) cell — only valid for positional/legacy tabs. */
export function paneKey(tabIdx: number, paneIdx: number): string {
  return `t${tabIdx}p${paneIdx}`;
}

/** Parse a legacy positional pane id back into its (tab, pane) indices, or null when malformed. */
export function parsePaneKey(pid: string): { tabIdx: number; paneIdx: number } | null {
  const m = /^t(\d+)p(\d+)$/.exec(pid);
  return m ? { tabIdx: Number(m[1]), paneIdx: Number(m[2]) } : null;
}

/** Pane-cell count for a "C×R" layout string; falls back to 1 on a malformed layout. */
export function paneCountForLayout(layout: string): number {
  const [c, r] = layout.split("×").map(Number);
  return (c || 1) * (r || 1);
}

/**
 * Roll a tab's per-pane statuses up to a single tab-level status (#435).
 *
 * Only panes that are IN the current grid AND not disabled contribute — so shrinking
 * the layout drops the trimmed cells, and disabling a busy pane immediately stops it
 * counting as "run". Precedence: any live "run" ⇒ "run"; else any "on" ⇒ "on"; else
 * "idle". A pane that paused mid-turn (one cell idle) never pulls a tab out of "run"
 * while another cell is still working — the rollup is over the whole live set.
 *
 * Always computed from the FULL current set, never mutated incrementally, so a stale
 * "run" left by a closed or remounted pane cannot strand the tab in the running state.
 */
export function aggregateTabState(
  tab: StatusTab,
  tabIdx: number,
  statuses: Readonly<Record<string, PaneStatus>>,
  disabledPanes: Readonly<Record<string, boolean>> = {},
): PaneStatus {
  const count = paneCountForLayout(tab.layout);
  let result: PaneStatus = "idle";
  for (let i = 0; i < count; i++) {
    const pid = paneIdFor(tab, tabIdx, i); // the SAME id the pane's PTY + status are keyed by
    if (disabledPanes[pid]) continue; // disabled cell — no live session
    const s = statuses[pid] ?? "idle";
    if (s === "run") return "run"; // any running pane dominates the tab
    if (s === "on") result = "on";
  }
  return result;
}

/**
 * Drop every per-pane status belonging to `tab` (at grid index `tabIdx`) (#435).
 *
 * Used when a tab's panes remount (a runId bump relaunches the sessions) or the tab
 * closes, so a previous session's "run"/"on" never lingers as a stale activity dot on
 * the fresh panes. Membership is by identity (`paneBelongsToTab`), so a manual or minted
 * fleet/triage pane is cleared too — the old positional parse silently kept them. Returns
 * a new map; the input is not mutated.
 */
export function clearTabStatuses(
  statuses: Readonly<Record<string, PaneStatus>>,
  tab: PaneIdentityTab,
  tabIdx: number,
): Record<string, PaneStatus> {
  const next: Record<string, PaneStatus> = {};
  for (const [pid, s] of Object.entries(statuses)) {
    if (!paneBelongsToTab(pid, tab, tabIdx)) next[pid] = s;
  }
  return next;
}

/**
 * Rolling byte buffer for PTY output that arrives while a TerminalView is
 * hidden (background tab, fullscreen-of-another-pane, view switched off
 * "console"). Drops oldest chunks once over `maxBytes` so a long-streaming
 * background pane can't grow the JS heap without bound — matching what xterm
 * does to its own scrollback for visible terminals.
 *
 * Flushed in one `term.write` call when the pane becomes visible, so background
 * panes pay zero render cost while hidden and the user sees everything still
 * within the cap when they switch back. Part of #52's "make each pane cheaper"
 * direction (the other lever besides WebGL + per-slice selectors).
 */
export class PendingPtyData {
  private chunks: string[] = [];
  private bytes = 0;
  constructor(private readonly maxBytes: number) {}

  /** Append a PTY chunk. Drops oldest chunks first to stay under `maxBytes`. */
  push(s: string): void {
    if (s.length === 0) return;
    this.chunks.push(s);
    this.bytes += s.length;
    // Keep at least one chunk so a single oversized payload survives intact;
    // dropping it would lose data the user might still want to see on flush.
    while (this.bytes > this.maxBytes && this.chunks.length > 1) {
      const dropped = this.chunks.shift()!;
      this.bytes -= dropped.length;
    }
  }

  /** Return everything buffered as one string and clear. Empty string when nothing pending. */
  flush(): string {
    if (this.chunks.length === 0) return "";
    const out = this.chunks.join("");
    this.chunks = [];
    this.bytes = 0;
    return out;
  }

  /** Current byte count. Used by callers that want to skip a no-op flush. */
  size(): number { return this.bytes; }
}

// The frontend ↔ persona store bridge (#2094). The desktop Personas library and every live console
// session + the planner share ONE global store (`~/.base-studio-code/personas/<id>.json`), reached
// here — and from a session's own shell — through the SAME `bsc persona …` CLI, over the generic `bsc`
// bridge (#2114). Personas are GLOBAL (no project key) so every call passes `null` as the projectKey.
// This is the only place the personas feature touches Tauri, so the pure model in `persona.ts` stays
// React/Tauri-free.
//
// Source-of-truth: the persona store. The Zustand slice is a write-through cache — `loadPersonas`
// hydrates it on boot (then `reconcilePersonas` re-seeds the packaged built-ins), and each library
// mutation pushes through here. Written verbatim: the store never imposes a schema, so a persona
// round-trips byte-for-byte.
import { bsc, bscRun, bscWrite } from "@/shared/lib/core/bsc";
import { log } from "@/shared/lib/core/log";
import type { Persona } from "@/features/personas/lib/persona";

/**
 * Load every persona from the store via `bsc persona list --full`. Returns `null` when the bridge is
 * unreachable (no Tauri host — tests, the web shell, or an old binary) so the caller keeps its seeded
 * in-memory built-ins rather than blanking the library. NOT `bscJson` (its degrade-to-fallback would
 * return an empty array, which would then blank the seeded set).
 */
export async function loadPersonas(): Promise<Persona[] | null> {
  try {
    const out = await bsc(null, ["persona", "list", "--full"]);
    const rows = JSON.parse(out.trim() || "[]") as Partial<Persona>[];
    // Defensive: keep only well-formed rows (id + name + role), defaulting the rest so an odd file
    // never crashes hydration.
    return (rows ?? [])
      .filter((p): p is Persona => typeof p.id === "string" && !!p.id)
      .map((p) => ({
        id: p.id, name: p.name ?? "Untitled", blurb: p.blurb ?? "",
        role: p.role ?? "reviewer", startPrompt: p.startPrompt ?? "", skills: p.skills ?? [],
        responsibilities: p.responsibilities, model: p.model, pooled: p.pooled, builtin: p.builtin,
        // The CAPABILITY half. Rebuilding a persona field-by-field silently dropped these, so a
        // persona that round-tripped through the app lost its floor — and the next `pushPersona`
        // wrote the floorless copy back over the store. Anything added to `Persona` that matters at
        // launch has to be listed HERE too; the projection is allow-list shaped by design (an odd
        // file must not crash hydration), which makes omission the default failure.
        floor: p.floor, derivesFrom: p.derivesFrom,
      }));
  } catch {
    return null;
  }
}

/** Write-through a persona upsert (`bsc persona set` reads the JSON on stdin). Fire-and-forget; never
 *  throws, so an old bundled `bsc` without the `persona` subcommand degrades to store-only silently. */
export async function pushPersona(persona: Persona): Promise<void> {
  try {
    await bscWrite(null, ["persona", "set"], persona);
  } catch (err) {
    // Deliberately NOT silent any more. This used to swallow everything as "store unreachable —
    // cache-only", which was true for an old binary without the subcommand and WRONG for the case
    // that now exists: the narrow-only floor clamp REFUSING a write. A refused write means the
    // in-memory library and the store disagree about what an agent may do, and the disagreement
    // resolves toward the store at the next launch — so it has to be visible.
    log.warn(`persona push refused for '${persona.id}': ${String(err)}`);
  }
}

/** Write-through a persona removal (`bsc persona remove <id>`). Never throws (see {@link pushPersona}). */
export async function dropPersona(id: string): Promise<void> {
  try { await bscRun(null, ["persona", "remove", id]); } catch { /* store unreachable — cache-only */ }
}

// The personas feature's graph-platform surface (register-the-feature-logic-surface) — the modules a
// graph-loaded record imports from this feature but does NOT redraw.
//
// Registered HERE, inside the feature, because the shell must not reach a feature's internals (#1545)
// and eager-importing them from `app/` would de-lazy the whole feature at boot. The feature's BARREL
// calls this at module load, so the shadow catalogue's `ensurePlatform: () => import("@/features/personas")`
// is what registers them — the same shape `registerAutomationsPlatform` already uses.
//
// These files STAY on disk: registration is not migration. It makes a record that imports them
// loadable, which is the prerequisite for migrating the modules that import THEM.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as Persona from "@/features/personas/lib/persona";

let done = false;

/** Register this feature's injected graph-platform modules by the specifiers a record imports. Idempotent. */
export function registerPersonasPlatform(): void {
  if (done) return;
  done = true;
  registerAppModule("@/features/personas/lib/persona", Persona);
}

// The shadow catalogue registers this feature's graph-platform modules by importing
// `./graphPlatform` DIRECTLY and calling its register function (see `shadowPages.ts`). This barrel
// therefore has NO import-time side effect — it is re-exports only, which is what lets it be a
// record rather than a file that must run to be correct.

// Personas feature (#2094) — the CRUD-able agent-identity library (behavior: start prompt + skills +
// model, over a referenced role). Public API barrel.
export { PersonasPanel } from "@/features/personas/PersonasPanel";
export { PersonaEditor } from "@/features/personas/PersonaEditor";
export { PersonaSummary } from "@/features/personas/PersonaSummary";
export { createPersonasSlice, type PersonasSlice } from "@/features/personas/store";
export { BUILTIN_PERSONAS, blankPersona, personaSlug, reconcilePersonas, type Persona } from "@/features/personas/lib/persona";

// Personas feature store slice (#2094) — the CRUD-able agent-identity library, a WRITE-THROUGH cache
// over the global persona store (`~/.base-studio-code/personas/`, reached via `bsc persona` — see
// personaBridge.ts). The desktop UI, live sessions, and the planner share ONE store. On boot
// `hydratePersonas` loads through the bridge + reconciles the packaged built-ins; every mutation below
// pushes through. The persisted `personas` in app-state is just a fast first-paint cache; hydrate is
// authoritative. Behavior identity only: the ROLE it references (permissions) lives in `sessionRoles.ts`.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import type { SessionRole } from "@/shared/lib/session/sessionRoles";
import type { ModelId } from "@/app/console/lib/models";
import { BUILTIN_PERSONAS, blankPersona, personaSlug, reconcilePersonas, type Persona } from "@/features/personas/lib/persona";
import { loadPersonas, pushPersona, dropPersona } from "@/features/personas/lib/personaBridge";

export interface PersonasSlice {
  /** The persona library — packaged built-ins (reconciled on load) + user-authored. */
  personas: Persona[];
  /** Hydrate the library from the global persona store on boot (#2094): load via the bridge, reconcile
   *  the packaged built-ins, and push any newly-seeded built-in back so the store has it. No-op (keeps
   *  the seeded set) when the bridge is unreachable — tests, the web shell, or an old binary. */
  hydratePersonas: () => Promise<void>;
  /** Create a user persona (optionally on a given role) and return its new id. */
  addPersona: (role?: SessionRole) => string;
  /** Clone any persona (incl. a built-in) into a new editable user persona; returns the new id. */
  clonePersona: (id: string) => string;
  /** Patch a persona's editable fields (name/blurb/prompt/skills/model/role). Built-ins keep their
   *  builtin identity; only user personas can be deleted. */
  updatePersona: (id: string, patch: Partial<Omit<Persona, "id" | "builtin">>) => void;
  /** Remove a USER persona (built-ins are not deletable — no-op). */
  removePersona: (id: string) => void;
  /** Adopt a persona onto a console PANE (#2094 wire-up): stamp its role (the permission floor),
   *  model, and start prompt onto the pane so the pane's NEXT launch runs as that persona, and mark
   *  perms stale so the "relaunch to apply" nudge shows. Skills are attached to the persona but not
   *  applied here yet (the per-session skill-override path is a refinement). No-op for an unknown id. */
  applyPersonaToPane: (paneId: string, personaId: string) => void;
}

/** Mint a fresh, collision-free user-persona id from a name (or a generic seed). */
function mintPersonaId(existing: Persona[], name: string): string {
  const base = `persona-${personaSlug(name)}`;
  if (!existing.some((p) => p.id === base)) return base;
  let n = 2;
  while (existing.some((p) => p.id === `${base}-${n}`)) n++;
  return `${base}-${n}`;
}

export const createPersonasSlice: StateCreator<AppStore, [], [], PersonasSlice> = (set, get) => ({
  personas: BUILTIN_PERSONAS,

  hydratePersonas: async () => {
    const loaded = await loadPersonas();
    if (!loaded) return; // bridge unreachable — keep the seeded built-ins
    const reconciled = reconcilePersonas(loaded);
    set({ personas: reconciled });
    // Converge the store — the source of truth a session/planner reads — with the reconciled library.
    // Push a built-in that the store lacks (first run / a newly-packaged persona) OR whose stored copy
    // drifted from the packaged prose (the #2185 upgrade path: worker/director seeded empty by an older
    // app now carry their real fleet protocol). User edits are preserved by reconcile, so only genuine
    // drift re-pushes.
    const loadedById = new Map(loaded.map((p) => [p.id, p]));
    for (const p of reconciled) {
      const before = loadedById.get(p.id);
      if (!before || (p.builtin && before.startPrompt !== p.startPrompt)) void pushPersona(p);
    }
  },

  addPersona: (role = "reviewer") => {
    const id = mintPersonaId(get().personas, "new persona");
    const persona = blankPersona(id, role);
    set((s) => ({ personas: [...s.personas, persona] }));
    void pushPersona(persona);
    return id;
  },

  clonePersona: (id) => {
    const src = get().personas.find((p) => p.id === id);
    if (!src) return id;
    const name = `${src.name} copy`;
    const newId = mintPersonaId(get().personas, name);
    const clone: Persona = { ...src, id: newId, name, builtin: false };
    set((s) => ({ personas: [...s.personas, clone] }));
    void pushPersona(clone);
    return newId;
  },

  updatePersona: (id, patch) => {
    let updated: Persona | undefined;
    set((s) => ({
      personas: s.personas.map((p) => {
        if (p.id !== id) return p;
        updated = { ...p, ...patch, id: p.id, builtin: p.builtin };
        return updated;
      }),
    }));
    if (updated) void pushPersona(updated);
  },

  removePersona: (id) => {
    const target = get().personas.find((p) => p.id === id);
    if (!target || target.builtin) return; // built-ins are not deletable
    set((s) => ({ personas: s.personas.filter((p) => p.id !== id) }));
    void dropPersona(id);
  },

  applyPersonaToPane: (paneId, personaId) => {
    const persona = get().personas.find((p) => p.id === personaId);
    if (!persona) return;
    set((s) => ({
      paneRoles: { ...s.paneRoles, [paneId]: persona.role },
      // The persona ITSELF, not just its role. The role alone was lossy: a persona derived from
      // `worker` with a narrowed floor launched with the full worker capability, because the
      // narrowing lives on the persona and only the role name was being stored.
      panePersonas: { ...s.panePersonas, [paneId]: persona.id },
      paneModels: persona.model ? { ...s.paneModels, [paneId]: persona.model as ModelId } : s.paneModels,
      paneStartupPromptText: persona.startPrompt
        ? { ...s.paneStartupPromptText, [paneId]: persona.startPrompt }
        : s.paneStartupPromptText,
      // Settings.json (the role gate) is read at session start — flag the pane so it shows the
      // "relaunch to apply" nudge, exactly like a profile edit (#799).
      panePermsStale: { ...s.panePermsStale, [paneId]: true },
    }));
  },
});

// Planning autopilot runner (#682, Phase 1b) — the live loop that drives a real planning
// session with the simulated user, built on the pure core (planAutopilot.ts).
//
// `autopilotTick` runs ONE step (read state → decide → execute) and is pure of timers/React,
// so it's unit-testable with injected deps. `usePlanAutopilot` runs it on a guarded interval
// and is the thin, manual-test wiring. Publish is MOCKED via deps — the harness never mutates
// real GitHub.

import { useEffect, useRef, useState } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import {
  decideAutopilotAction, buildUserSimPrompt, staticReply, type AutopilotResult, type AutopilotStrategy,
} from "@/features/planner/session/planAutopilot";

/** The live planning state the runner reads each tick (computed by the host component). */
export interface AutopilotSnapshot {
  planReady: boolean;
  /** Active stage's confirmable section keys — non-empty only when the stage is ready. */
  confirmKeys: string[];
  /** Planner finished its turn and is awaiting input (idle-detected by the host). */
  plannerAwaiting: boolean;
  /** The planner produced new output since the last tick — forward progress, resets idle. */
  working: boolean;
  /** (Mock-)publish on completion vs stop at a publishable plan for review (#682). */
  autoPublish: boolean;
  progress: { done: number; total: number; fraction: number };
}

/** Injected effects — the host wires these to the real session/store (or fakes, in tests). */
export interface AutopilotDeps {
  pitch: string;
  /** How the simulated user answers: `llm` (Claude), or `scripted`/`random`/`none` (Phase 2). */
  strategy: AutopilotStrategy;
  snapshot: () => AutopilotSnapshot;
  /** The planner's output since the last reply (for the user-sim). */
  pendingOutput: () => string;
  /** Generate a simulated-user reply (the llm strategy → a Claude completion). */
  userSim: (system: string, user: string) => Promise<string>;
  /** Send a line of input to the planner session. */
  sendReply: (text: string) => void;
  /** Confirm the given sections + advance the stage. */
  confirm: (keys: string[]) => void;
  /** MOCKED publish — record only; never touch real GitHub. */
  mockPublish: () => void;
  log: (e: AutopilotLogEntry) => void;
}

export interface AutopilotLogEntry { tick: number; action: string; detail?: string }

export interface AutopilotRunState {
  iteration: number;
  idleStreak: number;
  published: boolean;
  finished: boolean;
  result?: AutopilotResult;
}

export const initRunState = (): AutopilotRunState =>
  ({ iteration: 0, idleStreak: 0, published: false, finished: false });

/** Runaway + stall guards. */
export const MAX_ITERATIONS = 60;
export const MAX_IDLE = 6;

const finish = (state: AutopilotRunState, snap: AutopilotSnapshot, completed: boolean, stalledReason?: string): AutopilotResult =>
  ({ completed, published: state.published, iterations: state.iteration, progress: snap.progress, stalledReason });

/**
 * Run one autopilot tick: snapshot the plan → decide → execute the action. Returns the next
 * run state. Timer-/React-free so it's directly unit-testable with injected {@link AutopilotDeps}.
 */
export async function autopilotTick(state: AutopilotRunState, deps: AutopilotDeps): Promise<AutopilotRunState> {
  if (state.finished) return state;
  const snap = deps.snapshot();
  // Active planner output is forward progress — never count it as idle.
  const idle = snap.working ? 0 : state.idleStreak;
  const action = decideAutopilotAction({
    planReady: snap.planReady,
    published: state.published,
    confirmKeys: snap.confirmKeys,
    plannerAwaiting: snap.plannerAwaiting,
    iteration: state.iteration,
    maxIterations: MAX_ITERATIONS,
    idleStreak: idle,
    maxIdle: MAX_IDLE,
    autoPublish: snap.autoPublish,
  });
  const next: AutopilotRunState = { ...state, iteration: state.iteration + 1, idleStreak: idle };

  switch (action.kind) {
    case "reply": {
      // `llm` asks Claude; the other strategies use a canned reply (`none` sends nothing,
      // which lets idle climb to a stall — the "no response" test). (#682, Phase 2)
      let reply: string | null;
      if (deps.strategy === "llm") {
        const { system, user } = buildUserSimPrompt(deps.pitch, deps.pendingOutput());
        reply = await deps.userSim(system, user);
      } else {
        reply = staticReply(deps.strategy, state.iteration);
      }
      if (reply !== null) {
        deps.sendReply(reply);
        deps.log({ tick: state.iteration, action: "reply", detail: reply.slice(0, 80) });
        next.idleStreak = 0;
      } else {
        deps.log({ tick: state.iteration, action: "reply", detail: "(none — sent nothing)" });
        next.idleStreak = idle + 1;
      }
      break;
    }
    case "confirm":
      deps.confirm(action.keys);
      deps.log({ tick: state.iteration, action: "confirm", detail: action.keys.join(", ") });
      next.idleStreak = 0;
      break;
    case "publish":
      deps.mockPublish();
      deps.log({ tick: state.iteration, action: "publish (mocked)" });
      next.published = true;
      break;
    case "done":
      next.finished = true;
      next.result = finish(state, snap, true);
      deps.log({ tick: state.iteration, action: "done" });
      break;
    case "stall":
      next.finished = true;
      next.result = finish(state, snap, false, action.reason);
      deps.log({ tick: state.iteration, action: "stall", detail: action.reason });
      break;
    case "wait":
      next.idleStreak = idle + 1;
      break;
  }
  return next;
}

/**
 * The thin React wiring: while `enabled`, runs {@link autopilotTick} on a guarded interval
 * (no overlapping ticks) until the run finishes/stalls. Driven entirely by the Settings
 * toggle — enabling it kicks off the planner from wherever it currently is; disabling stops
 * it; re-enabling starts a fresh run. Manual-test-only — the testable logic lives in
 * `autopilotTick`.
 */
export function usePlanAutopilot(deps: AutopilotDeps, opts: { enabled: boolean; tickMs?: number }) {
  const { enabled, tickMs = 3500 } = opts;
  const [state, setState] = useState<AutopilotRunState>(initRunState());
  const stateRef = useRef(state);
  const depsRef = useRef(deps);
  const ticking = useRef(false);
  const wasEnabled = useRef(false);
  stateRef.current = state;
  depsRef.current = deps;

  // A fresh enable starts a fresh run (resets the autopilot's counters; the planner stays
  // wherever it is, so the run picks up from any point in the planning process).
  useEffect(() => {
    if (enabled && !wasEnabled.current) setState(initRunState());
    wasEnabled.current = enabled;
  }, [enabled]);

  // No immediate first tick: the interval-only original waited `tickMs` before the first step, so
  // `{ immediate: false }`. The reentrancy/finished guard stays inside the callback (no overlapping
  // ticks); disabling stops the run (the callback no-ops until deps re-subscribe on re-enable).
  usePoll(() => {
    if (!enabled || ticking.current || stateRef.current.finished) return;
    ticking.current = true;
    void autopilotTick(stateRef.current, depsRef.current)
      .then(setState)
      .catch((e) => {
        depsRef.current.log({ tick: stateRef.current.iteration, action: "error", detail: String(e) });
      })
      .finally(() => { ticking.current = false; });
  }, tickMs, [enabled, tickMs], { immediate: false });

  return { running: enabled && !state.finished, state };
}

// Planning autopilot (#682, Phase 1) — the PURE decision core that drives a planning
// session to a complete plan with a SIMULATED user. The live runner (PTY + Claude + store
// actions) wires these into the real session; this module is React/Tauri-free and fully
// unit-testable.
//
// The planning loop has three actors: the planner (Claude, autonomous), the user (simulated
// here), and the app (confirms sections, advances, publishes). The driver decides, each
// tick, what the user/app should do next given the planning state.

import type { Stage } from "@/features/planner/stages/focusedPlan";
import autopilotSimEmbedded from "@data/planner/autopilot-sim.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";
import { fillTemplate } from "@/shared/lib/core/template";

// The simulated-user PROSE (system prompt, user-turn template, canned replies) is externalized to
// `@data/planner/autopilot-sim.json` (#2416) — editable without touching code + part of the exportable
// config bundle; the config-dir copy (#2047) overlays the embedded default via `overlayFile`. This
// module keeps only the interpolation (`{{PITCH}}` / `{{PLANNER_OUTPUT}}`) and the strategy logic.
const SIM_PROSE = overlayFile("planner/autopilot-sim.json", autopilotSimEmbedded);

/** How the simulated user answers the planner. Phase 1 wires `llm`; the rest are Phase 2. */
export type AutopilotStrategy = "llm" | "scripted" | "random" | "none";

/** The next thing the driver should do. */
export type AutopilotAction =
  | { kind: "publish" }                  // the plan is complete → publish (MOCKED in the harness)
  | { kind: "done" }                     // finished (already published / nothing left)
  | { kind: "confirm"; keys: string[] }  // confirm the active stage's sections → advances its gate
  | { kind: "reply" }                    // planner is awaiting input → send a simulated-user reply
  | { kind: "wait" }                     // planner is still working → poll again next tick
  | { kind: "stall"; reason: string };   // no progress / cap hit → stop

/** Everything the driver needs to decide, computed by the runner from the live plan state. */
export interface AutopilotContext {
  /** Whole plan is publishable (planStagesComplete over the blueprint). */
  planReady: boolean;
  /** Whether publish has already fired (so we don't loop on it). */
  published: boolean;
  /** The active stage's confirmable section keys, NON-EMPTY only when the stage has produced
   *  enough to confirm (its required content exists). Empty ⇒ the stage still needs work. */
  confirmKeys: string[];
  /** The planner finished its turn and is waiting for input (idle-detected by the runner). */
  plannerAwaiting: boolean;
  /** Tick counter + hard cap — the ultimate runaway guard. */
  iteration: number;
  maxIterations: number;
  /** Consecutive ticks with no forward progress while idle — the stall guard. */
  idleStreak: number;
  maxIdle: number;
  /** Whether to (mock-)publish on completion. The Settings FEATURE stops at a publishable
   *  plan for review (false); the dev harness mock-publishes (true). (#682) */
  autoPublish: boolean;
}

/**
 * Decide the next autopilot action from the current planning state. Priority:
 * cap → publish/done → (while the planner waits) confirm-if-ready else reply → stall-if-stuck
 * → wait. Pure + deterministic.
 */
export function decideAutopilotAction(ctx: AutopilotContext): AutopilotAction {
  if (ctx.iteration >= ctx.maxIterations) {
    return { kind: "stall", reason: `hit the ${ctx.maxIterations}-iteration cap` };
  }
  if (ctx.planReady) {
    if (!ctx.autoPublish) return { kind: "done" }; // feature: stop at a publishable plan for review
    return ctx.published ? { kind: "done" } : { kind: "publish" };
  }
  // Stall on no forward progress — checked BEFORE the await branch so a non-responding user
  // (the `none` strategy) stalls instead of replying-with-nothing forever (#682, Phase 2).
  if (ctx.idleStreak >= ctx.maxIdle) {
    return { kind: "stall", reason: `no progress for ${ctx.idleStreak} ticks` };
  }
  if (ctx.plannerAwaiting) {
    // Stage has its required content → confirm it (which advances the gate). Otherwise the
    // planner's turn is done but the stage isn't ready, so answer its questions to continue.
    return ctx.confirmKeys.length > 0 ? { kind: "confirm", keys: ctx.confirmKeys } : { kind: "reply" };
  }
  return { kind: "wait" };
}

/**
 * The system + user prompt for the simulated-user (`llm` strategy): a product owner being
 * interviewed by the planner. Decisive, concrete, consistent with the pitch, no questions back.
 */
export function buildUserSimPrompt(pitch: string, plannerOutput: string): { system: string; user: string } {
  return {
    system: SIM_PROSE.system,
    user: fillTemplate(SIM_PROSE.userTemplate, {
      PITCH: pitch.trim(),
      PLANNER_OUTPUT: plannerOutput.trim(),
    }),
  };
}

/** Canned fuzz replies for the `random` strategy (Phase 2) — deliberately noisy/terse. */
const RANDOM_REPLIES: string[] = SIM_PROSE.randomReplies;

/**
 * A non-LLM simulated-user reply (Phase 2 strategies). `none` sends nothing (stall test);
 * `random` returns canned fuzz; `scripted` is a generic affirmative; `llm` is handled async
 * by the runner via {@link buildUserSimPrompt} and returns null here.
 */
export function staticReply(strategy: AutopilotStrategy, seed: number): string | null {
  switch (strategy) {
    case "none": return null;
    case "random": return RANDOM_REPLIES[Math.abs(Math.trunc(seed)) % RANDOM_REPLIES.length];
    case "scripted": return SIM_PROSE.scriptedReply;
    case "llm": return null;
  }
}

/** Progress fraction (0..1) over the visible stages — how far the plan got. */
export function autopilotProgress(stages: Stage[]): { done: number; total: number; fraction: number } {
  const total = stages.length;
  const done = stages.filter((p) => p.status === "complete" || p.status === "ahead").length;
  return { done, total, fraction: total ? done / total : 0 };
}

/** Outcome of an autopilot run — what the runner reports + the transcript inspector shows. */
export interface AutopilotResult {
  completed: boolean;
  published: boolean;
  iterations: number;
  progress: { done: number; total: number; fraction: number };
  stalledReason?: string;
}

// planBoardProjection (#2498) — the pure builder behind the `plan` store_state domain: the
// stage/gate board the mobile Planner page renders. COMPLEMENTS the existing `plan_state`
// frame (files + transcript, usePlannerTunnelSync) rather than duplicating it: this payload
// carries the DERIVED board — the focused-pane stage list with per-stage status + unmet gate
// reasons (the same `stagesFrom` output the desktop stepper renders), confirmed/skipped sets,
// the fleet streams, and the deploy/market summaries. Pure (no React/Tauri) so the shape is
// unit-testable from fixtures.

import type { Stage } from "@/features/planner/stages/focusedPlan";
import type { FleetPlan } from "@/features/planner/fleet/planFleet";
import { deploymentDefined, type DeployConfig } from "@/features/planner/lib/deployConfig";
import { marketDefined, type MarketConfig } from "@/features/planner/lib/marketConfig";

export interface PlanBoardStage {
  key: string;
  name: string;
  glyph: string;
  status: Stage["status"];
  /** Gate fill 0..1. */
  fraction: number;
  optional?: boolean;
  /** The still-unmet gate requirements (empty once the gate passes). */
  unmet: { label: string; detail?: string }[];
}

export interface PlanBoardStream {
  id: string;
  name: string;
  repo: string;
  issues: number;
  dependsOn: string[];
  persona?: string;
}

export interface PlanBoardPayload {
  projectId: string;
  title: string;
  currentStage: string;
  /** "complete" | "in_progress" | "starting" — the same label plan_status carries. */
  statusLabel: string;
  /** The active stage's gate passed — the user-only confirm is what advances it. */
  gateReady: boolean;
  planComplete: boolean;
  stages: PlanBoardStage[];
  confirmed: string[];
  skipped: string[];
  streams: PlanBoardStream[];
  directorEnabled: boolean;
  deploy: { defined: boolean; services: { id: string; repo: string; platform: string; workload: string }[] };
  market: { defined: boolean; summary: string; recommendation?: string };
}

export function buildPlanBoardPayload(input: {
  projectId: string;
  title: string;
  currentStage: string;
  statusLabel: string;
  gateReady: boolean;
  planComplete: boolean;
  stages: Stage[];
  confirmed: ReadonlySet<string> | string[];
  skipped: ReadonlySet<string> | string[];
  fleet?: FleetPlan;
  deploy?: DeployConfig;
  market?: MarketConfig;
}): PlanBoardPayload {
  return {
    projectId: input.projectId,
    title: input.title,
    currentStage: input.currentStage,
    statusLabel: input.statusLabel,
    gateReady: input.gateReady,
    planComplete: input.planComplete,
    stages: input.stages.map((s) => ({
      key: s.key, name: s.name, glyph: s.glyph, status: s.status,
      fraction: s.fraction, optional: s.optional, unmet: s.unmet ?? [],
    })),
    confirmed: [...input.confirmed].sort(),
    skipped: [...input.skipped].sort(),
    streams: (input.fleet?.streams ?? []).map((st) => ({
      id: st.id, name: st.name, repo: st.repo,
      issues: st.issues.length, dependsOn: st.dependsOn, persona: st.persona,
    })),
    directorEnabled: input.fleet?.director?.enabled ?? false,
    deploy: {
      defined: deploymentDefined(input.deploy),
      services: (input.deploy?.services ?? []).map((sv) => ({
        id: sv.id, repo: sv.repo, platform: sv.platform, workload: sv.workload,
      })),
    },
    market: {
      defined: marketDefined(input.market),
      summary: input.market?.summary ?? "",
      recommendation: input.market?.verdict?.recommendation,
    },
  };
}

// MCP-server assignment from the planner (#174). The planner assigns an MCP server to a project via
// `bsc plan mcp add <name>` (plan.db); the section poll resolves each assigned catalog name into the
// MCP-servers subsystem (`applyMcpAssign` → `resolveMcpServers` → `paneMcpServers` → `.mcp.json` at
// build/triage launch), so the SAME launch wiring that powers the MCP screen loads it with no extra
// glue. Pure (no React/Tauri) so the catalog mapping is unit-testable and shared with its tests.
// (The old `<mcp_assign>` stream tag + its parser were removed in the tag→bsc migration, #2012.)

import { mcpFromCatalog, type McpServer } from "@/features/mcp";
import { resolveMcpInstallDir, catalogLink } from "@/features/mcp";

/**
 * The {@link McpServer} (minus id) a `<mcp_assign name>` resolves to: the catalog
 * template for `name`, **enabled** and **scoped to `projectId`** so it applies to that
 * project's build/triage sessions. An unknown name yields a blank stdio server the user
 * completes; required env values stay blank (never invent secrets).
 *
 * For a downloadable (first-party) server, `baseDir` resolves the `{dir}` placeholder in
 * the run config to its on-disk install path (`~/.base-studio-code/mcp/<repo>`). Without
 * this the launched config keeps a literal `--directory {dir}` and the server never starts.
 */
export function mcpAssignToServer(name: string, projectId: string, baseDir = ""): Omit<McpServer, "id"> {
  const def = resolveMcpInstallDir(mcpFromCatalog(name), name, baseDir);
  return { ...def, enabled: true, projects: projectId ? [projectId] : [] };
}

/** Whether a `<mcp_assign>` name is a downloadable first-party server (has a catalog
 *  download link) — i.e. assigning it should also clone its repo. */
export function isDownloadableMcp(name: string): boolean {
  return !!catalogLink(name);
}

export interface McpStoreLike {
  mcpServers: McpServer[];
  addMcpServer: (def: Omit<McpServer, "id">) => void;
  updateMcpServer: (id: string, patch: Partial<McpServer>) => void;
}

/**
 * Idempotently apply one `<mcp_assign>` to the MCP-servers store: if a server with this
 * name already exists, just ensure it's enabled and scoped to the project (a global
 * server — `projects: []` — is left global); otherwise add a fresh catalog-derived def.
 * Returns whether a NEW server was added (vs. an existing one updated), for callers that
 * want to report it. Keeping this here (not in the React component) makes the dedup/scope
 * rule unit-testable.
 */
export function applyMcpAssign(store: McpStoreLike, name: string, projectId: string, baseDir = ""): boolean {
  const existing = store.mcpServers.find(
    (e) => e.name.toLowerCase() === name.toLowerCase(),
  );
  if (existing) {
    const projects =
      existing.projects.length === 0 || existing.projects.includes(projectId)
        ? existing.projects
        : [...existing.projects, projectId];
    store.updateMcpServer(existing.id, { enabled: true, projects });
    return false;
  }
  store.addMcpServer(mcpAssignToServer(name, projectId, baseDir));
  return true;
}

// Per-repo feature plans (#177). The planner's per-repo pass can now go down to the
// FEATURE level: for each repo it writes one plan section per feature, namespaced
// `repo__{short}__feat__{slug}`, carrying the feature's approach and (optionally)
// acceptance criteria. At publish each feature section becomes one real GitHub issue.
//
// Rather than thread a parallel "feature" object through the structure builder and the
// publisher, a feature section is converted into a synthetic {@link PlanIssue}: it then
// flows through the exact same granular-issue machinery (#311) — structure nodes,
// milestone pinning, labels, and the GitHub-link overlay — with no special-casing
// downstream.
//
// Pure (no React/Tauri) so the parsing is unit-testable and shared between Planning.tsx
// and its tests.

import { parseTopicKey } from "@/features/planner/stages/planTopics";
import type { PlanIssue } from "@/features/planner/issues/planIssues";

/** The repo-tier topic prefix that marks a section as a feature (`feat__{slug}`). */
export const FEATURE_PREFIX = "feat__";

/** Label applied to every feature-derived issue so they're filterable on GitHub. */
export const FEATURE_LABEL = "type:feature";

/** True when a section key is a per-repo feature section (`repo__{short}__feat__{slug}`). */
export function isFeatureKey(key: string): boolean {
  const info = parseTopicKey(key);
  return info.tier === "repo" && info.repo !== null && info.topic.startsWith(FEATURE_PREFIX)
    && info.topic.length > FEATURE_PREFIX.length;
}

/** The feature slug for a feature key, or null when the key isn't a feature section. */
export function featureSlug(key: string): string | null {
  if (!isFeatureKey(key)) return null;
  return parseTopicKey(key).topic.slice(FEATURE_PREFIX.length);
}

/** Title-case a slug (`login-form` → "Login form") as the fallback feature title. */
function humanizeSlug(slug: string): string {
  const words = slug.split(/[-_\s]+/).filter(Boolean);
  if (words.length === 0) return "Feature";
  return words.map((w, i) => (i === 0 ? w.charAt(0).toUpperCase() + w.slice(1) : w)).join(" ");
}

export interface ParsedFeature {
  /** Feature title — the section's first heading, else the humanized slug. */
  title: string;
  /** The feature's approach/body, with the leading title heading stripped. */
  body: string;
  /** Acceptance items pulled from `- [ ]` checkbox lines, if any. */
  acceptance: string[];
}

/**
 * Parse a feature section's markdown into its structured parts. Tolerant of how the
 * planner writes it:
 *
 * - **Title** — the first markdown heading (`# …`), else the humanized `slug`. A
 *   leading heading used as the title is dropped from the body (a deeper/later heading
 *   is kept).
 * - **Acceptance** — every `- [ ]` / `- [x]` checkbox line becomes an acceptance item
 *   and is lifted out of the body (so {@link renderIssueBody} renders one clean
 *   checklist instead of duplicating it).
 *
 * Everything else is preserved as the body (the approach).
 */
export function parseFeatureSection(content: string, slug: string): ParsedFeature {
  let title = "";
  const acceptance: string[] = [];
  const bodyLines: string[] = [];
  let sawContent = false;

  for (const raw of content.split(/\r?\n/)) {
    const line = raw.trim();

    // The FIRST heading, before any other content, is the feature title.
    const hm = line.match(/^#{1,6}\s+(.+?)\s*$/);
    if (hm && !title && !sawContent) {
      title = hm[1].trim();
      continue;
    }

    const am = line.match(/^[-*]\s+\[[ xX]?\]\s+(.+?)\s*$/);
    if (am) {
      acceptance.push(am[1].trim());
      continue;
    }

    if (line) sawContent = true;
    bodyLines.push(raw);
  }

  if (!title) title = humanizeSlug(slug);
  return { title, body: bodyLines.join("\n").trim(), acceptance };
}

// ── Discovery rubric (#490) ────────────────────────────────────────────────────

/**
 * Result of the per-feature behavior discovery rubric (#490). The hard gate is
 * `complete` — a feature with `complete = false` is not converted to issues.
 * `missingEdgeCases` is a softer warning: the body has content but lacks any
 * signals of edge/error/empty-state handling.
 */
export interface DiscoveryResult {
  /** true when the hard-gate requirements are met (behavior + acceptance). */
  complete: boolean;
  /** true when the feature body is absent or too brief to carry behavioral intent. */
  missingBehavior: boolean;
  /** true when no acceptance criteria are present. */
  missingAcceptance: boolean;
  /** true when the body lacks keywords suggesting edge/error/empty handling. */
  missingEdgeCases: boolean;
}

const EDGE_RE =
  /\b(error|empty|invalid|fail|edge|missing|not found|no results|loading|cancel|timeout|conflict|reject|403|404|500)\b/i;

/**
 * Score a parsed feature against the behavior-discovery rubric (#490).
 * Hard gate (blocks issue generation): `missingBehavior || missingAcceptance`.
 * Soft warning: `missingEdgeCases` (encouraged but not blocking).
 */
export function featureDiscoveryComplete(feature: ParsedFeature): DiscoveryResult {
  const missingBehavior    = feature.body.trim().length === 0;
  const missingAcceptance  = feature.acceptance.length === 0;
  const missingEdgeCases   = !missingBehavior && !EDGE_RE.test(feature.body);
  const complete           = !missingBehavior && !missingAcceptance;
  return { complete, missingBehavior, missingAcceptance, missingEdgeCases };
}

/** A section as the converter needs it — just its key and raw content. */
export interface FeatureSectionInput {
  k: string;
  content: string;
}

/**
 * Resolve a repo short name (`web`, the name without its owner) to the matching full
 * `owner/repo` from `repos`, case-insensitively. Returns undefined when none matches —
 * the synthetic issue then has no `repo` and publish files it under the default repo.
 */
function resolveRepo(short: string, repos: string[]): string | undefined {
  const lc = short.toLowerCase();
  return repos.find((full) => (full.split("/")[1] ?? full).toLowerCase() === lc);
}

/**
 * Convert every per-repo feature section into a synthetic {@link PlanIssue}. The hard
 * discovery gate (#490) is applied: features missing behavior or acceptance are skipped
 * and do NOT become issues. Use {@link incompleteFeatureSections} to surface the blocked
 * features in the UI. Non-feature sections are ignored.
 */
export function featureSectionsToIssues(sections: FeatureSectionInput[], repos: string[]): PlanIssue[] {
  const out: PlanIssue[] = [];
  for (const s of sections) {
    const slug = featureSlug(s.k);
    if (!slug) continue;
    const short = parseTopicKey(s.k).repo as string; // isFeatureKey guarantees non-null
    const parsed = parseFeatureSection(s.content, slug);
    // Hard gate: no issues for features that haven't completed behavior discovery.
    if (!featureDiscoveryComplete(parsed).complete) continue;
    out.push({
      ref: `feat:${short}:${slug}`,
      title: parsed.title,
      acceptance: parsed.acceptance,
      owns: [],
      dependsOn: [],
      labels: [FEATURE_LABEL],
      repo: resolveRepo(short, repos),
      body: parsed.body || undefined,
    });
  }
  return out;
}

/** One feature that failed the discovery gate — surfaced as a UI warning. */
export interface IncompleteFeature {
  key: string;
  title: string;
  reasons: string[];
}

/**
 * Return feature sections that failed the discovery gate (#490), with human-readable
 * reasons. Use this to surface "N features are blocking issue generation" in the UI.
 */
export function incompleteFeatureSections(sections: FeatureSectionInput[]): IncompleteFeature[] {
  const out: IncompleteFeature[] = [];
  for (const s of sections) {
    const slug = featureSlug(s.k);
    if (!slug) continue;
    const parsed = parseFeatureSection(s.content, slug);
    const result = featureDiscoveryComplete(parsed);
    if (result.complete) continue;
    const reasons: string[] = [];
    if (result.missingBehavior)    reasons.push("no approach / behavior described");
    if (result.missingAcceptance)  reasons.push("no acceptance criteria");
    out.push({ key: s.k, title: parsed.title, reasons });
  }
  return out;
}

// The parallel-execution (fleet) plan — the agent streams, director, topology, and
// relationship graph a project's fleet describes, plus the parser that turns the
// planner-written JSON (stored in plan.db, #1805) into a typed {@link FleetPlan}.
//
// Pure (no React / xterm / Tauri) so it can be unit-tested in isolation and shared
// between the planner UI, the store, and the fleet helpers. Split out of the former
// planStages.ts (#1615), which conflated this fleet machinery with the discovery
// topic-file helpers; those now live in stages/planTopics.ts.

import type { AgentFlow } from "@/features/planner/fleet/agentFlow";
import { flowOrUndefined } from "@/features/planner/fleet/agentFlow";
import { MODEL_IDS, type ModelId } from "@/app/console/lib/models";
import { type DirectorDrive, normalizeDirectorDrive, DEFAULT_DIRECTOR_DRIVE } from "@/features/planner/fleet/directorDrive";
import { type IntegrationStrategy, normalizeStrategy } from "@/features/planner/lib/integrationStrategy";
import {
  type Topology, type RelationshipArtifact, type AgentRelationship,
  type EdgeKind, type Hardness, type Via, type ArtifactKind,
} from "@/features/planner/relationship/relationshipGraph";

const TOPOLOGIES: Topology[] = ["director", "peer", "hybrid"];
const EDGE_KINDS: EdgeKind[] = ["handoff", "blocking", "sequence", "review", "notify", "mutex", "shared"];
const HARDNESSES: Hardness[] = ["blocking", "soft", "notify"];
const ARTIFACT_KINDS: ArtifactKind[] = ["schema", "contract", "types", "tokens", "fixture", "other"];

/** Coerce a raw fleet.json `topology` value (default "hybrid"). */
export function normalizeTopology(raw: unknown): Topology {
  return typeof raw === "string" && (TOPOLOGIES as string[]).includes(raw.trim().toLowerCase())
    ? (raw.trim().toLowerCase() as Topology) : "hybrid";
}

function parseArtifacts(raw: unknown): RelationshipArtifact[] {
  if (!Array.isArray(raw)) return [];
  const out: RelationshipArtifact[] = [];
  for (const a of raw) {
    if (!a || typeof a !== "object") continue;
    const o = a as Record<string, unknown>;
    const id = typeof o.id === "string" ? o.id.trim() : "";
    const producer = typeof o.producer === "string" ? o.producer.trim() : "";
    if (!id || !producer) continue;
    const kind = typeof o.kind === "string" && (ARTIFACT_KINDS as string[]).includes(o.kind) ? o.kind as ArtifactKind : "other";
    out.push({
      id, producer, kind,
      name: typeof o.name === "string" && o.name.trim() ? o.name.trim() : id,
      consumers: Array.isArray(o.consumers) ? o.consumers.filter((c): c is string => typeof c === "string") : [],
      status: o.status === "ready" ? "ready" : o.status === "pending" ? "pending" : undefined,
    });
  }
  return out;
}

function parseEdges(raw: unknown): AgentRelationship[] {
  if (!Array.isArray(raw)) return [];
  const out: AgentRelationship[] = [];
  for (const e of raw) {
    if (!e || typeof e !== "object") continue;
    const o = e as Record<string, unknown>;
    const from = typeof o.from === "string" ? o.from.trim() : "";
    const to = typeof o.to === "string" ? o.to.trim() : "";
    if (!from || !to) continue;
    out.push({
      id: typeof o.id === "string" && o.id.trim() ? o.id.trim() : `${from}>${to}`,
      from, to,
      kind: typeof o.kind === "string" && (EDGE_KINDS as string[]).includes(o.kind) ? o.kind as EdgeKind : "blocking",
      hardness: typeof o.hardness === "string" && (HARDNESSES as string[]).includes(o.hardness) ? o.hardness as Hardness : "blocking",
      via: o.via === "director" ? "director" : ("direct" as Via),
      artifact: typeof o.artifact === "string" && o.artifact.trim() ? o.artifact.trim() : undefined,
      note: typeof o.note === "string" && o.note.trim() ? o.note.trim() : undefined,
    });
  }
  return out;
}

/** The fleet section key. The fleet plan is DB-owned (plan.db, #1018/#1805) — surfaced by the poll
 *  under this stem (NOT a `fleet.json` file), not a rendered plan topic; parsed into the fleet store
 *  and shown in its own Fleet card. See {@link parseFleetFile}. */
export const FLEET_KEY = "fleet";

/**
 * One parallel work stream — a single Claude session with a focused role, a repo,
 * the files/globs it OWNS (its conflict boundary), the issues it owns, the streams
 * it must follow (interface-first), and the kickoff script that seeds it.
 */
export interface AgentStream {
  id: string;
  name: string;
  repo: string;
  /** Path globs this stream owns; no other stream should write inside them. */
  owns: string[];
  /** Issue refs this stream owns (e.g. `#12`). */
  issues: string[];
  /** Ids of streams that must land before this one starts. */
  dependsOn: string[];
  /** Shell commands this stream's session may auto-run without prompting (#1572) — the
   *  toolchain the planner grants it (e.g. `["cargo", "wasm-pack"]`), on top of the
   *  posture-scaled safe baseline. Seeds the generated profile's `commands`; written as
   *  `Bash(<cmd> *)` allow rules at launch. Unset/empty ⇒ baseline + mandatory only. */
  commands?: string[];
  /** Relpath of the kickoff script the fleet launch seeds this session with. */
  prompt?: string;
  /** Id of the AgentProfile this stream's session launches under (#289). */
  profile?: string;
  /** Id of the PERSONA this stream launches as (#2094): a live reference resolved at fleet launch to
   *  the stream's ROLE (overriding the default `worker`), start prompt, skills, and model. Unset ⇒ a
   *  plain worker (the historical default). Lets a fleet mix e.g. a documentor / reviewer stream with
   *  workers — the persona is the behavioral identity, the role it references is the permission floor. */
  persona?: string;
  /** Per-agent execution flow (#297): autonomy + GitHub push policy. Unset ⇒ DEFAULT_FLOW at launch. */
  flow?: AgentFlow;
  /** Per-agent LLM model (#…) — launches this stream's session under `claude --model <tier>`.
   *  Unset ⇒ the global `defaultModel` (so the director/baseline stays on the global choice). */
  model?: ModelId;
  /** Per-stream integration-strategy override (#378). Unset ⇒ the fleet default. */
  strategy?: IntegrationStrategy;
  /** GitHub login this stream's issues are assigned to at publish (#847). A worker is an
   *  agent session, not a GitHub user, so this maps the stream to a human/collaborator
   *  login. Unset ⇒ the publishing account (viewer). The `stream:<id>` label remains the
   *  agent-ownership marker; this is the first-class GitHub assignee. */
  assignee?: string;
  /** MCP servers (catalog names) the planner assigned to THIS worker (#1054). At fleet launch
   *  the worker gets these (case-insensitive) on top of any global servers; the planner + director
   *  always see every installed server. Unset/empty ⇒ the worker gets only global servers. */
  mcp?: string[];
  /** Skill task-group ids the planner assigned to THIS stream (#1338, parallel to {@link mcp}).
   *  At fleet launch the group ids are expanded (via the global skills.db) into this worker's
   *  skill set, on top of the project-resolved skills and any groups toggled onto the session.
   *  Unset/empty ⇒ the worker gets only its project-resolved skills. */
  groupIds?: string[];
}

/** Optional async-integrator session that coordinates the fleet from the project root. */
export interface FleetDirector { enabled: boolean; role?: string; drive?: DirectorDrive; }

/** The full parallel-execution plan for a project (persisted in plan.db, #1805). */
export interface FleetPlan {
  /** Optimal number of worker sessions to run concurrently. */
  recommended: number;
  /** Why that many — the planner's justification. */
  reasoning: string;
  streams: AgentStream[];
  director: FleetDirector;
  /** Project-default integration strategy (#378). Unset ⇒ DEFAULT_STRATEGY. */
  strategy?: IntegrationStrategy;
  /**
   * The app-owned SYSTEM SESSIONS this project uses — `designer` · `librarian` · `architect` ·
   * `sound-designer` · `integrator` (the fixed singletons named in `shared/lib/session/systemSessions`).
   * They serve the project's planner and render left of it in Glance.
   *
   * Named "system sessions", NOT "studios": a **Studio** is already the export/import unit for the whole
   * app library (studio snapshots), so overloading the word would make two unrelated things share a name
   * in the same codebase.
   *
   * DECLARED, not derived. The obvious inference — a `ui.kit` pairing implies a designer, integrations
   * imply an integrator, a feature's `requires` implies a librarian — reads EMPTY on the live studio-code
   * plan (no ui pairing, no integrations, 0 of 40 features carrying `requires`), so it would show zero
   * sessions on the one project that demonstrably uses all of them. Absent means "not declared", never
   * "not used": an empty list renders no session nodes rather than guessing.
   */
  systemSessions?: string[];
  /** Coordination topology (#…): director-orchestrated, peer mesh, or hybrid (per-edge). */
  topology?: Topology;
  /** Produced contracts/schemas one stream hands to others. */
  artifacts?: RelationshipArtifact[];
  /** Typed relationship edges between streams (beyond plain `dependsOn`). */
  edges?: AgentRelationship[];
}

/** An empty fleet — the default before the planner has designed one. */
export function emptyFleet(): FleetPlan {
  return { recommended: 0, reasoning: "", streams: [], director: { enabled: false, drive: DEFAULT_DIRECTOR_DRIVE } };
}

/**
 * Enrich each stream's `issues` from the plan.db issues that name it as their owning `stream` (#2615),
 * when the stream itself carries none. `AgentStream.issues` and `PlanIssue.stream` are meant to MIRROR
 * each other, but a stream can reach launch with an empty `issues[]` — so a worker gets a placeholder
 * kickoff instead of its real work. Deriving from the issues at launch means a worker always launches
 * with its concrete task list. A stream that already lists its issues is untouched (its authored order
 * wins). Pure + generic over the issue shape (`{ ref, stream }`) so it's unit-testable.
 */
export function withDerivedStreamIssues<T extends { id: string; issues: string[] }>(
  streams: T[],
  issues: ReadonlyArray<{ ref?: string; stream?: string }>,
): T[] {
  const byStream = new Map<string, string[]>();
  for (const iss of issues) {
    if (!iss.stream || !iss.ref) continue;
    const arr = byStream.get(iss.stream);
    if (arr) arr.push(iss.ref); else byStream.set(iss.stream, [iss.ref]);
  }
  return streams.map((s) => (s.issues.length > 0 ? s : { ...s, issues: byStream.get(s.id) ?? [] }));
}

/** Coerce a JSON value into a string[]. Accepts an array (strings kept, others
 *  stringified) or a single comma-separated string; anything else → []. */
function toStringArray(v: unknown): string[] {
  if (Array.isArray(v)) {
    return v.map(x => (typeof x === "string" ? x : String(x))).map(s => s.trim()).filter(Boolean);
  }
  if (typeof v === "string") {
    return v.split(",").map(s => s.trim()).filter(Boolean);
  }
  return [];
}

/** Coerce a JSON value into a non-negative integer; non-numeric → 0. */
function coerceNum(v: unknown): number {
  const n = typeof v === "number" ? v : typeof v === "string" ? Number(v) : NaN;
  return Number.isFinite(n) && n >= 0 ? Math.floor(n) : 0;
}

/**
 * Parse the FleetPlan JSON (the planner writes it to plan.db, #1805; surfaced by the poll
 * as stem {@link FLEET_KEY}) into a {@link FleetPlan}. Tolerant of partial/malformed
 * input: returns `null` only when the text is blank or not a JSON object; otherwise
 * fills sensible defaults. A stream missing an `id` (genuinely unkeyable) is dropped; a repo-less
 * stream DEFAULTS to the project's sole repo (`repos`, when there's exactly one) and otherwise stays
 * VISIBLE with an empty `repo` so it isn't silently hidden from the plan (#2611). `dependsOn`
 * accepts either `dependsOn` or `depends_on`.
 */
export function parseFleetFile(raw: string, repos: string[] = []): FleetPlan | null {
  if (!raw || !raw.trim()) return null;
  let obj: unknown;
  try { obj = JSON.parse(raw); } catch { return null; }
  if (!obj || typeof obj !== "object" || Array.isArray(obj)) return null;
  const o = obj as Record<string, unknown>;

  const streams: AgentStream[] = [];
  const rawStreams = Array.isArray(o.streams) ? o.streams : [];
  for (const s of rawStreams) {
    if (!s || typeof s !== "object") continue;
    const so = s as Record<string, unknown>;
    const id   = typeof so.id === "string" ? so.id.trim() : "";
    if (!id) continue;  // no id ⇒ genuinely unkeyable, drop
    // #2611: default a repo-less stream to the project's SOLE repo (the common single-repo case). If the
    // repo still can't be resolved (multi-repo / unassigned), KEEP the stream with an empty repo so it
    // stays VISIBLE in the planner graph flagged as needing a repo — silently dropping it hid streams
    // from the plan AND from launch. The launch path (usePlanPublish) skips a repo-less stream so it
    // never aborts the fleet or spawns a broken worktree.
    let repo = typeof so.repo === "string" ? so.repo.trim() : "";
    if (!repo && repos.length === 1) repo = repos[0];
    const prompt = typeof so.prompt === "string" && so.prompt.trim() ? so.prompt.trim() : undefined;
    // MCP servers (catalog names) the planner assigned to this worker (#1054); undefined when none
    // so the field round-trips cleanly. Carried through to fleetStartProject's per-worker resolution.
    const mcp = toStringArray(so.mcp);
    // Per-agent flow (#297) arrives in EITHER shape (#1804): NESTED as `so.flow`
    // ({autonomy,push,trigger,gate} — the canonical `bsc-plan fleet set` / fleet.json
    // form, matching the store model) OR FLAT as top-level `so.autonomy`/`so.push`/
    // `so.trigger`/`so.gate` (what the `<agent_assign>` tag attrs and legacy flat
    // fleet.json emit). Prefer a named nested object; else assemble from the flat
    // fields; else leave undefined so genuinely-unset streams still get DEFAULT_FLOW
    // at launch (we must NOT silently materialize a flow here).
    const nestedFlow = so.flow && typeof so.flow === "object" && !Array.isArray(so.flow)
      ? (so.flow as Record<string, unknown>) : null;
    const flow = flowOrUndefined(nestedFlow)
      ?? flowOrUndefined({ autonomy: so.autonomy, push: so.push, trigger: so.trigger, gate: so.gate });
    streams.push({
      id,
      name: typeof so.name === "string" && so.name.trim() ? so.name.trim() : id,
      repo,
      owns:      toStringArray(so.owns),
      issues:    toStringArray(so.issues),
      dependsOn: toStringArray(so.dependsOn ?? so.depends_on),
      commands:  ((cs) => cs.length ? cs : undefined)(toStringArray(so.commands)),
      prompt,
      mcp: mcp.length ? mcp : undefined,
      profile: typeof so.profile === "string" && so.profile.trim() ? so.profile.trim() : undefined,
      // Persona reference (#2094) — the stream's behavioral identity, resolved to role/prompt/skills/
      // model at fleet launch. Kept verbatim (an id); an unknown id just resolves to no persona.
      persona: typeof so.persona === "string" && so.persona.trim() ? so.persona.trim() : undefined,
      flow,
      // Per-agent model (#…) — the tier this stream's session launches under (`claude --model`).
      // Round-trips through plan.db (the planner / agent editor / `bsc-plan fleet set` may set it);
      // validated against the known tiers so a stray value falls back to the global default rather
      // than being passed verbatim to the CLI. Without this parse the selection is dropped on reload.
      model: (typeof so.model === "string" && (MODEL_IDS as readonly string[]).includes(so.model.trim()))
        ? (so.model.trim() as ModelId) : undefined,
      strategy: normalizeStrategy(so.strategy),
      assignee: typeof so.assignee === "string" && so.assignee.trim() ? so.assignee.trim() : undefined,
    });
  }

  const dir = (o.director && typeof o.director === "object" && !Array.isArray(o.director))
    ? (o.director as Record<string, unknown>) : {};
  const director: FleetDirector = {
    enabled: dir.enabled === true || dir.enabled === "true",
    role: typeof dir.role === "string" && dir.role.trim() ? dir.role.trim() : undefined,
    drive: normalizeDirectorDrive(dir.drive),
  };

  return {
    recommended: coerceNum(o.recommended),
    reasoning: typeof o.reasoning === "string" ? o.reasoning : "",
    streams,
    director,
    strategy: normalizeStrategy(o.strategy),
    // Carried through explicitly: this parser builds its result field-by-field, so a field that is not
    // named here is silently dropped — which is exactly what made a declared list unable to render no
    // matter what plan.db held. Filtered to strings and de-duplicated at the boundary; the graph drops
    // ids it does not know, and doing the cheap half here keeps the stored value clean.
    systemSessions: Array.isArray(o.systemSessions)
      ? [...new Set(o.systemSessions.filter((s): s is string => typeof s === "string" && !!s.trim()).map((s) => s.trim()))]
      : undefined,
    topology: o.topology !== undefined ? normalizeTopology(o.topology) : undefined,
    artifacts: parseArtifacts(o.artifacts),
    edges: parseEdges(o.edges),
  };
}

// Planner provenance gate (#1107). Scans the planner's AUTHORED artifacts (the section files it
// writes from reviewed repos/web) for injection markers, and turns the findings into a gate the
// user crosses before the plan seeds the fleet. Two modes:
//
//   - default (acknowledge-to-clear): findings are surfaced; the user reviews and acknowledges them
//     to proceed (a flag can be a false positive — kickoffs/sections legitimately contain
//     instructions — so the gate is on REVIEW, not on zero-flags).
//   - hard gate (Settings toggle `injectionHardGate`): any finding BLOCKS promotion until the
//     flagged content is removed — no acknowledge bypass.
//
// Pure; no React/Tauri. The detection lives in the shared lib/security/injectionScan.

import { scanArtifacts, type InjectionFinding } from "@/shared/lib/security/injectionScan";

export type { InjectionFinding };

/** Scan the planner-authored section files for injection markers. */
export function findPlanInjections(sections: Record<string, string>): InjectionFinding[] {
  return scanArtifacts(sections);
}

/** A stable, order-independent signature of a finding set. A user's "reviewed" acknowledgement is
 *  keyed by this, so adding new injected content (a new finding) invalidates the ack and re-gates. */
export function injectionSignature(findings: InjectionFinding[]): string {
  return findings.map((f) => `${f.file}:${f.line}:${f.category}`).sort().join("|");
}

export type InjectionGateMode = "clear" | "review" | "blocked";

export interface InjectionGate {
  findings: InjectionFinding[];
  /** `clear` = nothing flagged; `review` = flagged, acknowledge-to-clear available; `blocked` = the
   *  hard gate is on, so the flagged content must be removed (no acknowledgement bypass). */
  mode: InjectionGateMode;
  /** Whether plan → fleet promotion may proceed. */
  cleared: boolean;
}

/** Resolve the gate from findings + the hard-gate setting + the user's acknowledged signature. */
export function injectionGate(
  findings: InjectionFinding[],
  opts: { hardGate: boolean; ackSig?: string },
): InjectionGate {
  if (findings.length === 0) return { findings, mode: "clear", cleared: true };
  if (opts.hardGate) return { findings, mode: "blocked", cleared: false };
  return { findings, mode: "review", cleared: opts.ackSig === injectionSignature(findings) };
}

// Granular, agent-ready issues (#311). The planner decomposes each phase into
// self-contained issues, and each carries everything an agent needs to execute
// WITHOUT asking: a concrete title, acceptance criteria (the done-when), the
// files/dirs it owns, its dependencies, labels, and its milestone. These drive
// the GitHub-structure view and the publish flow (one real issue each), replacing
// the bare one-tracker-per-phase model.
//
// Written by the planner as `issues.json` (a JSON array) and via inline
// <plan_issue .../> tags. Pure (no React/Tauri) so it's unit-testable and shared
// by the parser, validator, structure builder, and publisher.

/** Execution-status lifecycle (#plan-db), mirrored from plan.db. A worker moves its issue
 *  open → in_progress → complete (pushed/PR'd); the director then checks CI and moves it
 *  complete → verified (green) or failed (red). `blocked` ⇒ waiting on an unmet dependency.
 *  Mirrors the Rust `STATUSES` in `crates/plandb`. */
export type PlanIssueStatus = "open" | "in_progress" | "blocked" | "complete" | "verified" | "failed";

export const PLAN_ISSUE_STATUSES: PlanIssueStatus[] = ["open", "in_progress", "blocked", "complete", "verified", "failed"];

/** One decomposed unit of work — becomes exactly one GitHub issue. */
export interface PlanIssue {
  /** Stable planner-local ref (e.g. "F1", "auth-login"). Used for dependsOn links
   *  and dedup; NOT the GitHub number (assigned at publish). */
  ref: string;
  /** Concrete, imperative title (e.g. "Add POST /sessions endpoint"). */
  title: string;
  /** Acceptance criteria — the done-when checklist an agent verifies against. */
  acceptance: string[];
  /** Files/dirs this issue owns, so the agent knows exactly where to work. */
  owns: string[];
  /** Refs of issues that must land before this one starts. */
  dependsOn: string[];
  /** Labels to apply (e.g. "scope:core", "area:api"). */
  labels: string[];
  /** Repo (owner/name) for a multi-repo project; undefined ⇒ the default repo. */
  repo?: string;
  /** Owning fleet stream id, if assigned (mirrors AgentStream.issues). */
  stream?: string;
  /** Ref of the parent feature this is a sub-issue of (#…). A feature is a parent issue; its
   *  decomposed work items carry the feature's ref here. Undefined ⇒ a top-level issue (a
   *  feature parent, or an unparented issue). Published as a GitHub sub-issue under its parent. */
  parent?: string;
  /** Extra prose/context beyond the acceptance list. */
  body?: string;
  /** Execution status from plan.db (#plan-db) — set by workers/director during the build.
   *  Absent on a freshly-planned issue (treated as "open"). */
  status?: PlanIssueStatus;
  /** The GitHub issue number this ref was published as; absent when it never was.
   *
   *  The durable plan↔GitHub link, mirrored from plan.db's `gh_number`. Publish and sync own it;
   *  a content edit never touches it. Its ABSENCE is meaningful — that is what marks an issue as
   *  still needing creation — so treat `undefined` as "unpublished", never coerce it to 0. */
  ghNumber?: number;
  /** GraphQL node id of the same issue — what the board / sub-issue mutations address it by. */
  ghNodeId?: string;
  /** Unix seconds of the last successful reconcile with GitHub; absent if never synced. */
  syncedAt?: number;
}

const toStr = (v: unknown): string => (typeof v === "string" ? v.trim() : "");
const toStrArray = (v: unknown): string[] =>
  Array.isArray(v) ? v.map(toStr).filter(Boolean) : [];

/** A positive integer, or `undefined` for anything else — including 0.
 *
 *  Zero is rejected on purpose: GitHub issue numbers start at 1, so a 0 can only be a placeholder or
 *  a coerced null, and letting one through would make an unpublished issue claim an identity and be
 *  skipped by the sync that exists to create it. Same reason the SQLite column is nullable rather
 *  than `DEFAULT 0`. */
const toPositiveInt = (v: unknown): number | undefined =>
  typeof v === "number" && Number.isInteger(v) && v > 0 ? v : undefined;

/**
 * Parse the planner's `issues.json` (a JSON array of issue objects) into a clean
 * {@link PlanIssue}[]. Tolerant: bad JSON ⇒ `[]`; entries missing `ref` or `title`
 * are dropped (the minimum an issue needs to be addressable). Mirrors
 * {@link parseFleetFile}'s defensiveness.
 */
export function parseIssuesFile(raw: string): PlanIssue[] {
  if (!raw || !raw.trim()) return [];
  let data: unknown;
  try { data = JSON.parse(raw); } catch { return []; }
  const arr = Array.isArray(data) ? data : Array.isArray((data as { issues?: unknown })?.issues) ? (data as { issues: unknown[] }).issues : [];
  const out: PlanIssue[] = [];
  for (const item of arr) {
    if (!item || typeof item !== "object") continue;
    const o = item as Record<string, unknown>;
    const ref = toStr(o.ref) || toStr(o.id);
    const title = toStr(o.title);
    if (!ref || !title) continue;
    out.push({
      ref,
      title,
      acceptance: toStrArray(o.acceptance),
      owns:       toStrArray(o.owns),
      dependsOn:  toStrArray(o.dependsOn ?? o.depends_on),
      labels:     toStrArray(o.labels),
      repo:       toStr(o.repo) || undefined,
      stream:     toStr(o.stream) || undefined,
      parent:     toStr(o.parent) || undefined,
      body:       toStr(o.body) || undefined,
      status:     (PLAN_ISSUE_STATUSES as string[]).includes(toStr(o.status)) ? (toStr(o.status) as PlanIssueStatus) : undefined,
      // Identity carries through the projection so a round-trip (plan.db → issues.json → parse)
      // does not silently un-publish every row. Snake_case is accepted alongside camelCase for the
      // same reason `dependsOn` is: a hand-authored or older file may use either.
      ghNumber:   toPositiveInt(o.ghNumber ?? o.gh_number),
      ghNodeId:   toStr(o.ghNodeId ?? o.gh_node_id) || undefined,
      syncedAt:   toPositiveInt(o.syncedAt ?? o.synced_at),
    });
  }
  return out;
}

export interface IssueTreeNode {
  issue: PlanIssue;
  children: PlanIssue[];
}

/**
 * Group issues into the feature → sub-issue tree (#…). A root is an issue with no `parent`, or
 * whose `parent` doesn't resolve to another issue (orphans degrade to roots, never lost). Every
 * other issue nests under its parent's `ref`. Children keep their `issues.json` order.
 */
export function issueTree(issues: PlanIssue[]): IssueTreeNode[] {
  const byRef = new Map(issues.map((i) => [i.ref, i]));
  const roots: PlanIssue[] = [];
  const childrenOf = new Map<string, PlanIssue[]>();
  for (const i of issues) {
    if (i.parent && i.parent !== i.ref && byRef.has(i.parent)) {
      const list = childrenOf.get(i.parent) ?? [];
      list.push(i);
      childrenOf.set(i.parent, list);
    } else {
      roots.push(i);
    }
  }
  return roots.map((issue) => ({ issue, children: childrenOf.get(issue.ref) ?? [] }));
}

/**
 * The parent→child GitHub node-id pairs to link as sub-issues (#…), given the node ids known by
 * issue ref (created or pre-existing). Only pairs where BOTH ends resolve are returned — an
 * unresolved end (parent/child not created this run) is simply not linked. Self-parents skipped.
 */
export function subIssueLinks(
  issues: PlanIssue[],
  nodeByRef: Record<string, string>,
): { parent: string; child: string }[] {
  const out: { parent: string; child: string }[] = [];
  for (const i of issues) {
    if (!i.parent || i.parent === i.ref) continue;
    const child = nodeByRef[i.ref];
    const parent = nodeByRef[i.parent];
    if (child && parent) out.push({ parent, child });
  }
  return out;
}

export interface IssueValidation {
  ok: boolean;
  /** Refs used more than once (ambiguous dependency targets). */
  duplicateRefs: string[];
  /** `{ ref, dependsOn }` where the dependency ref doesn't exist. */
  danglingDependencies: { ref: string; dependsOn: string }[];
  /** Issues with no acceptance criteria — not agent-ready (a warning, not fatal). */
  missingAcceptance: string[];
}

/**
 * Validate a decomposed issue set. `ok` is true when there are no duplicate refs and
 * no dangling dependencies — the agent-ready gate (missing acceptance is surfaced but
 * doesn't fail validation).
 */
export function validateIssues(issues: PlanIssue[]): IssueValidation {
  const seen = new Map<string, number>();
  for (const i of issues) seen.set(i.ref, (seen.get(i.ref) ?? 0) + 1);
  const duplicateRefs = [...seen.entries()].filter(([, n]) => n > 1).map(([r]) => r);

  const refs = new Set(issues.map((i) => i.ref));
  const danglingDependencies: { ref: string; dependsOn: string }[] = [];
  for (const i of issues) {
    for (const dep of i.dependsOn) {
      if (!refs.has(dep)) danglingDependencies.push({ ref: i.ref, dependsOn: dep });
    }
  }

  const missingAcceptance = issues.filter((i) => i.acceptance.length === 0).map((i) => i.ref);

  return {
    ok: duplicateRefs.length === 0 && danglingDependencies.length === 0,
    duplicateRefs,
    danglingDependencies,
    missingAcceptance,
  };
}

/**
 * Render a {@link PlanIssue} as a GitHub issue body — the agent-facing contract:
 * the acceptance checklist, the owned paths, and the dependency list, so whoever
 * picks it up has everything without re-deriving it from the plan.
 */
export function renderIssueBody(issue: PlanIssue): string {
  const parts: string[] = [];
  if (issue.body) parts.push(issue.body.trim());
  if (issue.acceptance.length) {
    parts.push("## Acceptance criteria\n" + issue.acceptance.map((a) => `- [ ] ${a}`).join("\n"));
  }
  if (issue.owns.length) {
    parts.push("## Owns\n" + issue.owns.map((o) => `- \`${o}\``).join("\n"));
  }
  if (issue.dependsOn.length) {
    parts.push("## Depends on\n" + issue.dependsOn.map((d) => `- ${d}`).join("\n"));
  }
  parts.push("---\n_Auto-generated by the base-studio-code planner._");
  // Hidden ref marker (#plan-db) — see {@link refMarker}.
  parts.push(refMarker(issue.ref));
  return parts.join("\n\n");
}

/**
 * The hidden HTML-comment marker that carries an issue's planner-local `ref` through a publish.
 * Invisible in GitHub's rendered issue view, but present in the raw body — so the GitHub→plan.db
 * recovery path can reconstruct the ref (and therefore the `dependsOn` links, which reference
 * planner refs), which GitHub doesn't persist natively. The single enabler for lossless recovery.
 */
export function refMarker(ref: string): string {
  return `<!-- bsc:ref=${ref} -->`;
}

/** Extract the planner-local ref from a published issue body's {@link refMarker}, or undefined. */
export function parseRefMarker(body: string): string | undefined {
  const m = /<!--\s*bsc:ref=([^\s>]+)\s*-->/.exec(body ?? "");
  return m ? m[1].trim() : undefined;
}

// Modular planning stages (#512/#515). The registry is the single source of
// truth for the canonical, ordered stage set and each stage's stable `id` — what
// the config/ordering layer (defaultStageConfig / enabledOrderedStages) and the
// blueprint seeder key off.
//
// Gating is NOT here. A stage's "done-ness" and applicability are declarative DATA
// — the `gateRule` / `appliesWhen` carried by each stage's prompt JSON
// (`src-tauri/data/stages/*.json`), evaluated by {@link evalGate} in stageGate.ts
// against the flat signal bag {@link planStateToSignals} publishes. That makes a
// stage authorable, shareable, and WAN-distributable as data; the executable code
// gates that used to live here (#1598) were dead duplicates that had drifted from
// the authoritative JSON, so they were removed.
//
// Everything here is pure — no React/Tauri — so the registry + config logic stays
// unit-testable, and both the bar and the Rust prompt assembler key off the same ids.
//
// The registry DATA (the ordered stage set + each stage's label/optional/deps/defaultEnabled) is
// externalized to `@data/planner/stage-registry.json` (#2027 P1) — editable without touching code and
// part of the exportable app-config bundle. (It lives OUTSIDE `@data/stages/`, whose per-stage prompt
// JSONs are loaded by a `@data/stages/*.json` glob that would otherwise grab the registry.) This
// module keeps the TYPES + the config logic (defaultStageConfig / enabledOrderedStages / STAGE_BY_ID).

import stageRegistryEmbedded from "@data/planner/stage-registry.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

// The config-dir copy (#2047) overlays the embedded default — editable without a rebuild.
const stageRegistry = overlayFile("planner/stage-registry.json", stageRegistryEmbedded);

/** All valid stage identifiers, in pipeline order.
 *  `load` is signal-only — it has no PLAN_STAGES entry and is never shown in the bar,
 *  but exists in the union so other stages and signal consumers can reference it by name. */
export type StageId =
  | "discovery"
  | "market"
  | "transformations"
  | "deployment"
  | "source"
  | "features"
  | "ui"
  | "streams"
  | "automations"
  | "skills"
  | "load";

/**
 * Normalized snapshot of live plan progress. A later slice builds this from the live
 * plan data (sections, repos, fleet, …) via {@link buildPlanStageState}, and
 * {@link planStateToSignals} (planStageDerive.ts) flattens it into the serializable
 * {@link PlanSignals} bag the declarative JSON gates read. Use buildPlanStageState to
 * construct one with safe defaults for any field not yet known.
 */
export interface PlanStageState {
  /** Discovery progress (#1019/#1028): required topics written (`resolved`) vs required total, plus
   *  `requiredDiscoveryReady` — every REQUIRED topic's file generated (≥1 required). No confirmation. */
  discovery: { resolved: number; total: number; requiredDiscoveryReady: boolean };
  /** Repositories linked to the project. */
  repoCount: number;
  /** Whether the project needs a UI at all — drives the UI stage's applicability. */
  requiresUi: boolean;
  /** Required screens approved vs total (only meaningful when requiresUi). `routed` is set
   *  when the user routes dropped design files to the project — an alternative completion to
   *  approving screen previews (#837). */
  ui: { approved: number; total: number; routed?: boolean };
  /** Features: how many user-facing capabilities are defined, and whether all are
   *  confirmed. Each feature becomes a fleet stream; the Plan stage reads them. */
  features: { count: number; allConfirmed: boolean };
  /** Dependencies (#1111/#1191): how many libraries the planner has locked in the dependency manifest
   *  (plan.db, via `bsc-plan deps set`). The Dependencies gate passes once ≥1 is defined. */
  dependencies: { count: number };
  issueCount: number;
  /** Fleet: streams defined, and each has a profile/flow set. */
  fleet: { streams: number; profilesComplete: boolean };
  /** Automations reviewed/acknowledged (may legitimately be zero). */
  automationsAck: boolean;
  /** Skills assigned/acknowledged (may legitimately be zero). */
  skillsAck: boolean;
  /** Whether a migration source pipeline is active for this project — drives the source
   *  stage's applicability. False for projects with no data migration component. */
  migrationSourceEnabled: boolean;
  /** Data Model progress signals, derived from the live source-scan state (#1446 — the canonical
   *  Data Model itself lives in the project's DuckDB store). Absent signals read as all-false. */
  dataModel: {
    sourceReachable: boolean;
    modelInferred: boolean;
    schemaRefined: boolean;
    mappingComplete: boolean;
    loadVerified: boolean;
  };
}

export interface Stage {
  id: StageId;
  /** Short display label shown in the PlanStageBar. */
  label: string;
  /** One-line description of what this stage produces (shown in Blueprint editor). */
  description: string;
  /** Whether the stage can be toggled off in a Blueprint.
   *  Only `discovery` is required (optional: false). All other stages — including
   *  `structure` — can be omitted by blueprints that don't need them (e.g. a
   *  refactor/cleanup blueprint skips the feature workshop). */
  optional: boolean;
  /** Whether this stage produces a visible output file the app polls for
   *  (e.g. phases.json, fleet.json). Informational only — drives tooltip copy. */
  hasOutputFile: boolean;
  /** Prerequisite stages (documentation of the canonical ordering). Live dependency
   *  gating is the blueprint section's declarative `deps`, not this field. */
  dependsOn: StageId[];
  defaultEnabled: boolean;
}

/** Per-project (or per-blueprint) on/off + ordering of the stages (#512). */
export interface StageConfig {
  enabled: Record<StageId, boolean>;
  order: StageId[];
}

// ── The canonical stage registry ─────────────────────────────────────────────
// From `@data/planner/stage-registry.json`. Ordering rationale baked into that file's order: `ui`
// sits after `features` so its Claude Design kickoff can reference the defined capabilities
// (#825/#1404); `deployment`/`streams` are the collapsed repos+deploy / structure+permissions stages
// (#1914). `dependsOn` DOCUMENTS the real prerequisites — runtime gating reads each stage's
// declarative `@data/stages/<id>.json` `gateRule`/`deps`, not this registry. (The signal-only `load`
// sibling has NO registry entry — it never shows in the bar — but exists in the StageId union.)
export const PLAN_STAGES: Stage[] = stageRegistry as Stage[];

export const STAGE_BY_ID: Record<StageId, Stage> = Object.fromEntries(
  PLAN_STAGES.map((s) => [s.id, s]),
) as Record<StageId, Stage>;

/** All-on config in the registry's default order — reproduces today's behavior. */
export function defaultStageConfig(): StageConfig {
  return {
    enabled: Object.fromEntries(PLAN_STAGES.map((s) => [s.id, s.defaultEnabled])) as Record<StageId, boolean>,
    order: PLAN_STAGES.map((s) => s.id),
  };
}

/**
 * The dynamic-stages seed (#1395 phase 1): ONLY Discovery is enabled; every other
 * stage starts OFF and lights up additively as Discovery's classification signals select it.
 * The full registry order is preserved so an additively-enabled stage slots into its place.
 * Distinct from {@link defaultStageConfig} (all-on), which reproduces the legacy blueprint behavior;
 * this is the source-of-truth seed a new project gets once blueprints stop hand-picking the set.
 */
export function discoveryOnlyStageConfig(): StageConfig {
  return {
    enabled: Object.fromEntries(PLAN_STAGES.map((s) => [s.id, s.id === "discovery"])) as Record<StageId, boolean>,
    order: PLAN_STAGES.map((s) => s.id),
  };
}

/** Fill a partial snapshot with safe defaults so callers needn't specify every field. */
export function buildPlanStageState(p: Partial<PlanStageState> = {}): PlanStageState {
  return {
    discovery: p.discovery ?? { resolved: 0, total: 0, requiredDiscoveryReady: false },
    repoCount: p.repoCount ?? 0,
    requiresUi: p.requiresUi ?? false,
    ui: p.ui ?? { approved: 0, total: 0, routed: false },
    features: p.features ?? { count: 0, allConfirmed: false },
    dependencies: p.dependencies ?? { count: 0 },
    issueCount: p.issueCount ?? 0,
    fleet: p.fleet ?? { streams: 0, profilesComplete: false },
    automationsAck: p.automationsAck ?? false,
    skillsAck: p.skillsAck ?? false,
    migrationSourceEnabled: p.migrationSourceEnabled ?? false,
    dataModel: p.dataModel ?? {
      sourceReachable: false,
      modelInferred: false,
      schemaRefined: false,
      mappingComplete: false,
      loadVerified: false,
    },
  };
}

/** The enabled stages, in the configured order (what the bar renders). */
export function enabledOrderedStages(cfg: StageConfig): Stage[] {
  return cfg.order.filter((id) => cfg.enabled[id]).map((id) => STAGE_BY_ID[id]).filter(Boolean);
}

// Substep resolution (#…). Pure helpers over the blueprint section model: which substep the
// conductor injects next. No React/Tauri — fully unit-testable.
import type { SubStep } from "@/features/planner/stages/blueprints";

/** A substep is done when: (static) its artifact key is confirmed; (loop) the conductor says
 *  the loop is finished — the model can't know per-item completion, so `loopDone` is supplied. */
export function substepDone(s: SubStep, confirmed: Set<string>, loopDone: boolean): boolean {
  return s.loop ? loopDone : confirmed.has(s.key);
}

/** The active substep = the first not-yet-done one, in order. Undefined ⇒ all substeps done
 *  (the conductor falls back to the stage's own gate). */
export function activeSubstep(
  substeps: SubStep[] | undefined,
  confirmed: Set<string>,
  loopDone = false,
): SubStep | undefined {
  return (substeps ?? []).find((s) => !substepDone(s, confirmed, loopDone));
}

// PlanSlice — extracted from the store implementation (store split, stage 2).
// Typed Pick<AppStore, …> so AppStore stays whole in types.ts while the create() composes slices.
import type { StateCreator } from "zustand";
import { bscRun, bscWrite } from "@/shared/lib/core/bsc";
import { hashString } from "@/shared/lib/core/hashString";
import type { AppStore } from "@/store/types";
import { makeBlueprints, mkStage, cloneStages, DEFAULT_BLUEPRINT_ID, type Blueprint } from "@/features/planner/stages/blueprints";
import { packagedUiKitPin, resolveBlueprintUiKit } from "@/features/planner/blueprints/uiKitPin";
import { packagedSoundKitPin, resolveBlueprintSoundKit } from "@/features/planner/blueprints/soundKitPin";
import { canonicalTopicKey, FEATURES_KEY } from "@/features/planner/stages/planTopics";
import { emptyFleet } from "@/features/planner/fleet/planFleet";
import { defaultStageConfig, discoveryOnlyStageConfig, enabledOrderedStages } from "@/features/planner/stages/planStages";
import { normalizeFlow, resolveFlow } from "@/features/planner/fleet/agentFlow";
import { setMapEntry } from "@/store/updateHelpers";
import { dropProjectScoped } from "@/store/slices/projectScopedMaps";
/** The `repoPublic` key for one repo within a project (#1227): `<projectKey>::<repoFullName>`,
 *  the repo-scoped convention used elsewhere (e.g. repoStartupPromptDoc). */
export function repoVisibilityKey(projectKey: string, repoId: string): string {
  return `${projectKey}::${repoId}`;
}

/**
 * Resolve a repo's create-time GitHub visibility (#1227): the per-repo override if set, else the
 * project-level default (`reposPublic`), else **private**. Used at the Repos card + at publish so
 * the UI and the create call agree.
 */
export function resolveRepoPublic(
  repoPublic: Record<string, boolean>,
  reposPublic: Record<string, boolean>,
  projectKey: string,
  repoId: string,
): boolean {
  const k = repoVisibilityKey(projectKey, repoId);
  if (k in repoPublic) return repoPublic[k];
  return reposPublic[projectKey] ?? false;
}

/** Record the project→kit consumer-index edge for a blueprint bind (#2277). If the blueprint declares a
 *  component `kit`, the seeded project is a CONSUMER of it, so `addKitUsage` files the edge (idempotent by
 *  (projectKey, kitId), write-through to `bsc ui usage`). A blueprint with no `kit` is a no-op — so
 *  this fills the consumer index automatically at every blueprint bind (creation + switch). */
function recordBlueprintKit(get: () => AppStore, projectId: string, blueprintId: string): void {
  const kit = get().blueprints.find((b) => b.id === blueprintId)?.kit;
  if (kit) get().addKitUsage(projectId, kit);
}

