// Planner introduction kickoff selection (#1240). Pure helpers so mode selection + pitch
// composition are unit-testable; the Rust `planner_intro_prompt` command returns the per-mode
// template text, and the launch bakes the composed result as a fresh-only startup prompt.

import type { BlueprintMode } from "@/features/planner/stages/blueprints";

export type PlannerIntroMode = "new" | "existing";

/**
 * Whether the planner should take the "existing repos" orientation — for BOTH the intro greeting
 * and the generated CLAUDE.md spec (`setup_workspaces`). True when the project is already saved OR
 * the blueprint's lifecycle is `operate` (transform / harden / maintain — work against existing
 * repos). #1286: keying off the blueprint **mode**, not just save-state, fixes an operate-mode
 * project on a fresh draft — or right after a greenfield→transform lifecycle switch — being
 * mis-oriented as a new greenfield one. (A saved greenfield project is unchanged: still "existing".)
 */
export function plannerTreatAsExisting({ isSaved, mode }: { isSaved: boolean; mode?: BlueprintMode }): boolean {
  return isSaved || mode === "operate";
}

/** Pick the intro mode from the session signals — mirrors the planner.rs CLAUDE.md branch
 *  (an existing project, else a new greenfield project). */
export function plannerIntroMode({ isExisting }: { isExisting: boolean }): PlannerIntroMode {
  return isExisting ? "existing" : "new";
}

/** Compose the startup prompt: the mode's intro, plus the user's pitch for a NEW project so the
 *  planner acknowledges it instead of asking what they're building, plus (for the one-shot
 *  `bsc-agent` runtime) the FIRST active stage's directive so a weak local model actually BEGINS the
 *  stage instead of greeting and then waiting to be advanced (#qwen). An empty intro (e.g. the
 *  command failed) yields `""` so the launch falls back to its plain `initCmd`.
 *
 *  `firstStageDirective` is omitted for Claude Code, which receives each stage's directive via the
 *  app's runtime injection as it advances — there the greeting is deliberately greeting-only. */
export function composePlannerIntro(
  intro: string, mode: PlannerIntroMode, pitch: string, firstStageDirective?: string,
): string {
  if (!intro.trim()) return "";
  let out = intro;
  if (mode === "new" && pitch.trim()) {
    out += `\n\n---\nThe user has already shared this pitch — acknowledge it and reflect your understanding back instead of asking what they're building:\n\n${pitch.trim()}`;
  }
  if (firstStageDirective?.trim()) {
    out += `\n\n---\nThe app drives this plan one stage at a time. Your FIRST stage is below — after you greet the user, BEGIN it now (don't wait to be advanced):\n\n${firstStageDirective.trim()}`;
  }
  return out;
}

// plannerLaunch — how the PLANNER session launches under the selected LLM provider / fleet harness.
//
// The planner is plan-only (role gate #219) and, like the fleet, can run on either Claude Code or the
// model-agnostic `bsc-agent` runtime (#1078). When the effective harness is bsc-agent — because the
// user chose it, OR because the provider is local/ollama which Claude Code can't drive — the planner
// launches `bsc-agent` with the SAME context, prompt, state, and permissions a Claude planner gets:
//   • context — `bsc-agent` composes its system prompt from the planning dir's CLAUDE.md chain +
//     CLAUDE.local.md + skills (compose_system), identical to what Claude Code loads.
//   • state   — the per-session BSC_* env (plan.db / data.db / skills.db + their CLIs) is wired by
//     pty_create's wire_bsc_env for every pane regardless of harness.
//   • prompt  — the planner intro is baked as the agent's task (BscAgentAdapter.launch_command).
//   • perms   — BSC_AGENT_PERMS carries the plan-only role gate (its analogue of the claude
//     settings.json deny rules), and BSC_AGENT_MCP the planner's MCP servers.
//
// Pure + React-free so both planner launch sites (initial mount + restart) share one definition.

import { resolveLlmConfig, bscAgentEnv, effectiveHarness } from "@/shared/lib/core/llmConfig";
import { roleCapability, bscAgentPerms, sessionScopes } from "@/shared/lib/session/sessionRoles";
import { resolveAllInstalledMcp, toBscAgentMcp, toSessionPayloads } from "@/features/mcp";
import type { AppStore } from "@/store/types";

/** The harness-dependent fields of the planner's `pty_create` call. */
export interface PlannerLaunch {
  /** Console provider id passed to pty_create — `"bsc-agent"` selects the runtime + its session
   *  file; `undefined` keeps Claude Code, the default. */
  providerId?: string;
  /** The fallback init command (used only if no startup prompt is baked). */
  initCmd: string;
  /** GH token env + the planner role's `BSC_SCOPES` store-scope doc (#2470) plus, for bsc-agent,
   *  the BSC_AGENT_* provider/model/base-url/perms/MCP vars. */
  env: Record<string, string>;
  /** Whether the intro is suppressed on a resumed session (#1240). Claude keeps the fresh-only
   *  greeting; bsc-agent (a one-shot agent loop, not a REPL) always bakes the intro as its task. */
  startupPromptFreshOnly: boolean;
  /** Request conversation resume — the backend ANDs it with "history actually exists", so a fresh
   *  project is unaffected (Claude resumes via `--continue`; bsc-agent via its $BSC_AGENT_SESSION
   *  continuity). */
  continueSession?: boolean;
}

/**
 * Resolve how the planner session launches for the current provider + fleet harness.
 *
 * @param s      the app-store snapshot (reads `llmProvider`, `fleetHarness`, `mcpServers`)
 * @param ghEnv  the GitHub token env already resolved for the planner (`GH_TOKEN` / `GITHUB_TOKEN`)
 */
export function plannerLaunchConfig(s: AppStore, ghEnv: Record<string, string>): PlannerLaunch {
  const harness = effectiveHarness(s.llmProvider, s.fleetHarness ?? "claude");
  // Store scopes (#2470, defense-in-depth): the planner role's per-store access tiers (ui: read) for
  // the store CLIs' runtime write check — on BOTH harnesses (the launch-time deny rules are the
  // boundary; this guards accidents + the bsc-agent runtime).
  const scopes = JSON.stringify(sessionScopes(roleCapability("director")));
  if (harness !== "bsc-agent") {
    return {
      providerId: undefined,
      initCmd: "claude --continue 2>/dev/null || claude",
      env: { ...ghEnv, BSC_SCOPES: scopes },
      startupPromptFreshOnly: true,
      // Defensive (#2396): request resume explicitly. With the fresh-only intro guard a baked prompt
      // only ever fires when there's no history (where resume is a no-op), but if a caller ever bakes
      // a prompt onto a cwd WITH history this resumes it instead of silently forking a fresh session.
      continueSession: true,
    };
  }
  // The planner sees every installed MCP server (#1054); pass them to the runtime as $BSC_AGENT_MCP.
  const plannerMcp = toSessionPayloads(resolveAllInstalledMcp(s.mcpServers), []).mcp;
  const bscMcp = toBscAgentMcp(plannerMcp);
  const env: Record<string, string> = {
    ...ghEnv,
    ...bscAgentEnv(resolveLlmConfig(s)),
    // Plan-only role gate (#219) for the bsc-agent runtime: deny code writes + the mutating git/gh
    // commands the planner role forbids — the runtime's analogue of the claude settings.json denies.
    BSC_AGENT_PERMS: JSON.stringify(bscAgentPerms(roleCapability("director"))),
    BSC_SCOPES: scopes,
  };
  if (bscMcp.length > 0) env.BSC_AGENT_MCP = JSON.stringify(bscMcp);
  return {
    providerId: "bsc-agent",
    initCmd: "bsc-agent", // fallback only; the baked intro prompt always wins
    env,
    startupPromptFreshOnly: false,
    continueSession: true,
  };
}

// plannerSandbox (#1988) — the opt-in WSL2-sandbox launch overrides shared by BOTH planner launch
// sites (the initial mount in usePlannerTerminal AND the restart in usePlanningSession), so they can't
// drift apart (the restart path used to skip the sandbox entirely). When the sandbox toggle is on AND
// the planner runs on bsc-agent — the only runtime baked into the sealed distro — the hub is relocated
// into the distro (setup_sandbox_hub) and the session spawns INSIDE it; otherwise it's the host launch.
//
// The launch reads the toggle only at spawn time, so flipping it while a planner is OPEN does nothing
// to the live session — Planning.tsx restarts the open planner on a flip so it converts.

import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { useAppStore } from "@/store";

/** Whether a planner `pty_create` should spawn into the sandbox: the toggle is on, the harness is
 *  bsc-agent (baked into the distro), and there's a host hub to relocate. Pure — unit-testable. */
export function wantsSandboxLaunch(
  sandboxConsoles: boolean,
  providerId: string | undefined,
  planningDir: string,
): boolean {
  return sandboxConsoles && providerId === "bsc-agent" && !!planningDir;
}

/** Resolve the `cwd` + `wslDistro` for a planner `pty_create`. When the sandbox is wanted, relocate the
 *  hub into the distro (`setup_sandbox_hub`) and spawn at the distro cwd; on failure — or when not
 *  wanted — fall back to the host hub (no distro). Reads the current `sandboxConsoles` from the store. */
export async function resolvePlannerSandbox(
  providerId: string | undefined,
  planningDir: string,
  projectKey: string,
): Promise<{ cwd: string; wslDistro: string | undefined }> {
  const wants = wantsSandboxLaunch(useAppStore.getState().sandboxConsoles, providerId, planningDir);
  const sandboxHub = wants
    ? await safeInvoke<string | null>(
        "setup_sandbox_hub", { key: projectKey }, null,
        (e: unknown) => console.error("sandbox hub setup failed (falling back to host):", e),
      )
    : null;
  return { cwd: sandboxHub ?? planningDir, wslDistro: sandboxHub ? "bsc-agent-sandbox" : undefined };
}

export { hubToCanonical, applyPush, isPlanFile } from "@/features/planner/lib/plannerSync/bridge";
export type { HubSnapshot, CanonicalBuild } from "@/features/planner/lib/plannerSync/bridge";
export { loadSnapshot, saveSnapshot, clearSnapshot } from "@/features/planner/lib/plannerSync/snapshot";

// Pure helpers for the planner's section-by-section discovery loop.
//
// Free of React / xterm / Tauri imports so the message building can be unit-tested in isolation.
// All planner stream-tag PARSING has been removed — every planner artifact is now written via a
// `bsc plan …` command and reflected by the section poll (the tag→bsc migration, #2007–#2017).

// The `<plan_focus>` stream tag was removed (#2017): the "active topic" card-highlight it drove was
// dropped in the focused-pane redesign (#652), so it fed a discarded state value. The stepper follows
// the live session off the section files the planner writes, not a tag.

/**
 * The message injected into Claude's PTY when the user confirms a section in the
 * UI. It is the "advance to the next section" signal for the discovery loop.
 */
export function buildSectionConfirmMessage(sectionTitle: string): string {
  return `[The user confirmed the "${sectionTitle}" section in the planner UI — continue to the next section.]`;
}

/**
 * The message injected into Claude's PTY when the user deliberately SKIPS an optional stage in the
 * planner UI (#921). It tells the planner to stop any work on that stage and move on — the stage is
 * optional and the user chose not to do it.
 */
export function buildSectionSkipMessage(sectionTitle: string): string {
  return `[The user chose to SKIP the optional "${sectionTitle}" section in the planner UI — do not work on it; continue to the next section.]`;
}

// Startup scripts moved to plan.db (#2010) — the planner records per-repo kickoff/triage prompt
// docs with `bsc plan startup add`; the section poll resolves each `path` via `scriptDocRelpath`
// (below) and auto-assigns it. (The `<startup_script>` stream tag + its parser are gone.)

/**
 * Build the unified-store relpath for a script the planner wrote to its project
 * dir. `sanitizedKey` is the on-disk project folder (sanitize_project_key). A
 * path already rooted at `projects/` is returned untouched; otherwise it is
 * resolved under the project hub. Backslashes are normalized to posix and any
 * leading slashes stripped so the result satisfies read_document's path guards.
 */
export function scriptDocRelpath(sanitizedKey: string, path: string): string {
  const clean = path.replace(/\\/g, "/").replace(/^\/+/, "");
  if (clean.startsWith("projects/")) return clean;
  return `projects/${sanitizedKey}/${clean}`;
}

// Planner terminal/ANSI helpers, split out of Planning.tsx (#1332): the ANSI-escape stripper and
// a viewport-content probe used to avoid re-sending an already-pasted prompt. (The xterm TERM_THEME
// lives in @/app/console/lib/terminalConstants — the single home shared by every terminal, #3246.)
import type { Terminal } from "@xterm/xterm";

// Covers all common VT/ANSI escape sequences:
//   CSI  \x1b [ <0x20-0x3f>* <0x40-0x7e>   — includes private ?/>/< params
//   OSC  \x1b ] <text> (\x07 | \x1b\)       — BEL or ST terminator
//   Char-set  \x1b [()][…]
//   Other C1  \x1b <any single byte>         — fallback: ESC + one char
// eslint-disable-next-line no-control-regex
const ANSI_RE = /\x1b(?:\[[\x20-\x3f]*[\x40-\x7e]|\][^\x07\x1b]*(?:\x07|\x1b\\)|[()][0-9A-Za-z]|[\x40-\x7e])/g;

export function stripAnsi(s: string): string {
  return (
    s
      .replace(ANSI_RE, "")  // remove escape sequences
      .replace(/\r/g, "")    // remove lone carriage returns (spinner overwrites)
      // eslint-disable-next-line no-control-regex -- intentional: strip bare ESC bytes from PTY output
      .replace(/\x1b/g, "")  // remove any leftover bare ESC bytes
  );
}

// Read the visible terminal rows (where Claude's input bar lives) and report whether they already
// contain `snippet` — so a re-send doesn't duplicate a prompt that was pasted but never submitted.
// Heuristic: a normalized substring match over the viewport. Best-effort; never throws.
export function terminalShows(term: Terminal | null, snippet: string): boolean {
  if (!term || !snippet.trim()) return false;
  try {
    const buf = term.buffer.active;
    let text = "";
    for (let i = 0; i < term.rows; i++) {
      text += " " + (buf.getLine(buf.baseY + i)?.translateToString(true) ?? "");
    }
    const norm = (s: string) => s.replace(/\s+/g, " ").trim().toLowerCase();
    return norm(text).includes(norm(snippet));
  } catch {
    return false;
  }
}

// The DECLARED BOUNDARY, frontend side (#3897; maintainer decision 2026-08-12, see `closure.rs`).
//
// A record's dependency may be a RECORD, or a module the platform registry DECLARES — anything else is
// unresolved. `@data/ui/platform-modules.json` is that registry, generated from the real runtime module
// registry (guarded by `platformModules.gen.test.ts`) and embedded verbatim by the Rust twin.
//
// The two halves are supplied differently on purpose, and each runner supplies them as far as it can:
// the closure runner ALIASES a declared specifier to the app's real file; the browser preview cannot
// (separate realm, and the app ships compiled rather than as source) so it supplies a local STUB — the
// same treatment every non-curated bare specifier already gets (#3696).
//
// This module exists so there is exactly ONE such set on the frontend. It previously lived privately in
// `graphHealth.ts`, which meant the doctor honoured the boundary and the preview did not: doctor called a
// component healthy, the preview refused to build it, and `navigate` acked a mount that never happened.
// That is precisely the asymmetry `isPreviewBuildable`'s own contract forbids — *the doctor must never be
// more permissive than the thing it reports on.* Importing the set from here keeps them in lockstep by
// construction rather than by vigilance.
import platformModules from "@data/ui/platform-modules.json";

/** Every specifier the runtime module registry resolves. Matched LITERALLY, exactly as the loader's
 *  `isAppModule` does — no prefix or directory matching, so an unregistered `@/…` sibling stays an
 *  honest failure. */
export const PLATFORM_MODULES: ReadonlySet<string> = new Set<string>(platformModules as string[]);

/** Is `spec` a registered platform module — the second half of the declared boundary? */
export function isPlatformModule(spec: string): boolean {
  return PLATFORM_MODULES.has(spec);
}

// The plan for request debugger sessions (#one-request-one-debug-session) — decides, each poll, which
// requests need a session started, which sessions to close, and the reconciled live set.
//
// THE MODEL: 1:1. Every request the app has claimed gets exactly ONE session, bound to it and named for
// it (`debug-studio:req-<id>`), and that session is closed when THAT request resolves. There is no pool,
// no cap, no pacing and no reaper.
//
// WHAT THIS REPLACES, AND WHY EACH PIECE WENT. #3535 ran a WARM POOL: generic sessions that claimed work
// after launching, paced one-at-a-time and capped at three total.
//   * The CLAIM RACE is gone because the app claims first and spawns for what it got, so a session never
//     competes for its own work. `bsc request claim` takes the OLDEST open request and is atomic, which
//     is what makes "claim, then spawn for the id it returned" safe against the standing debug session
//     doing the same thing — whoever claims first has it, and the other simply sees it held.
//   * The REAPER (`pollsWarming`/`MAX_WARM_POLLS`) is gone with it. It existed solely to clean up a
//     session that launched, lost the race and would otherwise idle forever with nothing to do. An
//     assigned session always has work.
//   * The PACING is gone: it throttled how fast the pool grew toward a cap, and there is no cap.
//   * The CAP is gone BY DECISION, not by oversight. #3535's cap existed so "a never-resolving request
//     must never be able to fill the machine with debuggers"; at 1:1 the concurrency IS the number of
//     unresolved claimed requests, which the maintainer accepted on the grounds that this queue stays
//     small (44 requests all-time, 4 open when this shipped). If it ever grows, the fix is a queue in
//     front of the spawn — not a return to claiming, which is what made a session's identity meaningless.
//
// PURE and separate from the launcher (mirrors #3498's planner/launcher split): every rule that bounds
// blast radius is here and exhaustively testable without starting a single session. The mount obeys it.

import { autoSpawnDecision, AUTO_SPAWNABLE_ROLE } from "@/shared/lib/session/autoSpawn";
// ABSOLUTE, not `./requestSpawn`: that module has no file — it is a graph record with `provides`, and
// only the `@/…` specifier resolves to it (through tsconfig paths + the emitted record cache).
import { requestPaneId, requestIdFromPaneId } from "@/shared/lib/session/requestSpawn";

/** A request row as `bsc request list --json` returns it (the fields the plan reads). */
export interface RequestRow {
  id: number;
  /** `open` (nobody holds it) · `claimed` (a session holds it) · `resolved` (done). */
  status: string;
  /** The pane id of the session holding a claimed request (#3535 `claimed_by`). */
  claimedBy?: string | null;
}

/** One live request session. Its `paneId` encodes the request, so the id is not stored twice. */
export interface RequestSession {
  paneId: string;
}

export interface RequestSessionPlanInput {
  /** The full request list (`bsc request list --json`), any status. */
  requests: RequestRow[];
  /** The sessions currently launched. */
  sessions: RequestSession[];
  /** The Settings toggle (`autoSpawnDebugSessions`). Anything but `true` is off. */
  enabled: boolean | null | undefined;
}

export interface RequestSessionPlan {
  /** Requests that are claimed for us and have no session yet — start one per id, all of them, now. */
  start: number[];
  /** Pane ids to CLOSE: their request resolved, vanished, or the gate turned off. */
  close: string[];
  /** Every still-live session. The mount replaces its tracked set with this, then appends what it starts. */
  sessions: RequestSession[];
  /** When starting nothing, why — so a stalled queue is diagnosable, never a silent non-decision. */
  reason?: string;
}

/**
 * Plan the request sessions for one cycle. Pure — starts and stops nothing.
 *
 * @param input the queue, the live sessions, and the auto-spawn gate.
 * @returns which requests need a session, which panes to close, and the reconciled live set.
 *
 * Steps:
 *  1. **Gate.** Auto-spawn off ⇒ start nothing and CLOSE every session, carrying the gate's own reason.
 *  2. **Reconcile.** A session survives only while its request is still unresolved and still present; a
 *     session whose request resolved (or was removed outright) is closed.
 *  3. **Start.** Every CLAIMED request with no live session gets one. All of them in the same cycle —
 *     there is nothing to pace against.
 *
 * `open` requests are deliberately NOT started: an unclaimed request is one nobody holds, and the app
 * claims it (atomically, obtaining the id) BEFORE asking for a session. Planning off `claimed` is what
 * keeps this pure — the claim is the side effect, and it stays in the mount.
 */
export function planRequestSessions(input: RequestSessionPlanInput): RequestSessionPlan {
  const gate = autoSpawnDecision({ role: AUTO_SPAWNABLE_ROLE, enabled: input.enabled });
  if (!gate.allowed) {
    return { start: [], close: input.sessions.map((s) => s.paneId), sessions: [], reason: gate.reason };
  }

  // The requests still worth holding a session for: claimed, not resolved. A request that VANISHED from
  // the list (`bsc request remove`, or a prune) is absent here too, which is what closes its session —
  // an unknown id must not keep a session alive forever.
  const liveIds = new Set(input.requests.filter((r) => r.status === "claimed").map((r) => r.id));

  const kept: RequestSession[] = [];
  const close: string[] = [];
  for (const s of input.sessions) {
    const id = requestIdFromPaneId(s.paneId);
    if (id != null && liveIds.has(id)) kept.push(s);
    else close.push(s.paneId);
  }

  const held = new Set(kept.map((s) => requestIdFromPaneId(s.paneId)));
  const start = [...liveIds].filter((id) => !held.has(id)).sort((a, b) => a - b);

  return {
    start,
    close,
    sessions: kept,
    reason: start.length === 0 ? (liveIds.size === 0 ? "no claimed requests" : "every claimed request already has a session") : undefined,
  };
}

/** The pane a request's session runs in — re-exported so the mount has one import for the plan + its ids. */
export { requestPaneId };

/**
 * Resolve ONE state from N independent signal sources, by a declared precedence order.
 *
 * The everyday shape of "which status is this thing in?" when several sources can each claim it at
 * once and the answer must be single-valued and stable. The ordering is DATA, not control flow: the
 * common alternative is a chain of `if` returns, where the precedence exists only in the sequence of
 * the statements and cannot be read, tested, or changed without editing the branch order.
 *
 * The first source (in order) that claims the subject wins. Sources are consulted lazily, so an
 * expensive predicate placed low in the order is not paid for when something above it already matched.
 *
 * Harvested from the Fleet page's per-worker status (#3462/#3465), where coordination signals
 * (asking / waiting / blocked) outrank the raw run/idle sample, which in turn outranks a parked
 * maintenance worker — an order chosen so a worker that needs a human is never hidden behind a
 * mechanical "running".
 */

/** One candidate state and the test that claims it. `when` is only called until one matches. */
export interface PrecedenceRule<TSubject, TState> {
  /** The state this rule resolves to when it claims the subject. */
  state: TState;
  /** Does this source claim the subject? */
  when: (subject: TSubject) => boolean;
}

/**
 * The first rule (in order) whose `when` claims `subject`, else `fallback`.
 *
 * Total by construction — a `fallback` is required rather than optional, so there is no "resolved to
 * nothing" case for a caller to forget. That matters here: the states this resolves are rendered, and
 * an undefined status is a blank badge rather than a visible problem.
 */
export function resolveByPrecedence<TSubject, TState>(
  subject: TSubject,
  rules: ReadonlyArray<PrecedenceRule<TSubject, TState>>,
  fallback: TState,
): TState {
  for (const rule of rules) {
    if (rule.when(subject)) return rule.state;
  }
  return fallback;
}

/**
 * The rules that claimed `subject`, in precedence order — every match, not just the winner.
 *
 * The winner alone answers "what is it?"; this answers "what else was true?", which is what an
 * explanation needs. A worker resolving to `running` while also matching `maintenance` is a different
 * situation from one that matches `running` only, and a UI that can say so is more use than one that
 * silently discards the runners-up.
 */
export function matchingPrecedence<TSubject, TState>(
  subject: TSubject,
  rules: ReadonlyArray<PrecedenceRule<TSubject, TState>>,
): TState[] {
  return rules.filter((r) => r.when(subject)).map((r) => r.state);
}

// Preview-data bindings (#2940): which librarian ALGORITHM feeds which component's preview data prop —
// the studio-network payoff (a component's preview renders real algorithm-generated data instead of the
// `[]`/trivial sample). Deliberately DECOUPLED from the generated `react-ui.json` kit descriptor (no
// drift-guard / generator entanglement): a binding is a designer-authored render concern, resolved at
// preview time by `usePreviewData` (run the impl's `vizCode` in the sandbox → `vizRunToDataset` → the
// adapter → the prop value). The runtime `bsc ui` authoring verb is a fast-follow; this seeds the exemplar.
import type { VizDataset } from "@/features/algorithms";

/** An adapter maps the algorithm's normalized {@link VizDataset} to the VALUE a component's data prop
 *  expects — the ONLY per-component shape glue, kept tiny + pure + named so each is unit-tested. */
export type PreviewAdapterKind = "grid" | "graph" | "values" | "cells";

/** One binding: a component's data prop is fed by an algorithm impl, its output shaped by an adapter. */
export interface PreviewBinding {
  /** Kit id the component belongs to (e.g. `react-d3`). */
  kitId: string;
  /** Component name (matched case-insensitively against {@link ComponentRecord.name}). */
  component: string;
  /** The data prop to feed. */
  prop: string;
  /** The algorithm impl id whose `vizCode` is run to generate the data (e.g. `sort.ts`). */
  algorithm: string;
  /** How to shape the run's dataset into the prop's value. */
  adapter: PreviewAdapterKind;
}

/** The seeded bindings. The exemplar (#2940): the react-d3 **Heatmap**'s `data` prop is fed by the
 *  **insertion sort** (`sort.ts`) — its sorted `number[]` output laid into a weekly `HeatDatum[]` grid,
 *  so the preview shows a real generated matrix instead of the built-in sample. */
export const PREVIEW_BINDINGS: readonly PreviewBinding[] = [
  { kitId: "react-d3", component: "Heatmap", prop: "data", algorithm: "sort.ts", adapter: "grid" },
];

/** The binding for `comp` (kit + name match), or undefined. */
export function bindingFor(kitId: string, componentName: string): PreviewBinding | undefined {
  const name = componentName.toLowerCase();
  return PREVIEW_BINDINGS.find((b) => b.kitId === kitId && b.component.toLowerCase() === name);
}

/** A `HeatDatum` — the react-d3 Heatmap's cell shape (`data: HeatDatum[]`). */
interface HeatDatum { x: string; y: string; value: number }

const WEEK = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"];

/**
 * Shape a run's dataset into the component prop's value. Pure + total: an unusable dataset for the
 * requested adapter returns `null` (the caller then falls back to the component's own sample).
 */
export function adaptDataset(ds: VizDataset | undefined, adapter: PreviewAdapterKind): unknown {
  // A run with no bindable dataset (a stack/scalar program, #4162) adapts to nothing — the same `null`
  // every shape mismatch below returns, so the caller's existing empty-data path handles it unchanged.
  if (!ds) return null;
  switch (adapter) {
    case "values":
      return ds.kind === "array" ? ds.data : null;
    case "graph":
      return ds.kind === "graph" ? { nodes: ds.nodes, edges: ds.edges } : null;
    case "cells":
      // matrix → one HeatDatum per cell (row index → y, col index → x).
      return ds.kind === "matrix"
        ? ds.data.flatMap((row, y) => row.map((value, x): HeatDatum => ({ x: String(x), y: String(y), value })))
        : null;
    case "grid": {
      // array → a weekly grid: successive values fill columns (weekday) then wrap to the next row.
      if (ds.kind !== "array") return null;
      return ds.data.map((value, i): HeatDatum => ({ x: WEEK[i % WEEK.length], y: String(Math.floor(i / WEEK.length)), value }));
    }
  }
}

// previewDataset (#3439) — a SYNCHRONOUS, real dataset for a target STRUCTURE, sourced from a canonical
// in-app trace program (NOT the sandbox `vizCode` path — these programs are trusted app code that runs on
// the main thread). This is what lets the Design Studio's SHAPE tier feed a component that declares a
// `DataShape` with real algorithm-GENERATED data, with no per-component `PREVIEW_BINDINGS` row.
//
// Structures with BOTH a `VizDataset` kind and registered programs are offered — `array` (the sorts),
// `graph` (the traversals), and `tree` (a BST, #3790). Pure + deterministic (a fixed program + seed) so
// a preview never flickers between renders.
import { runAlgorithm, runGraphAlgorithm } from "@/features/algorithms/lib/tracer";
import { TRACE_PROGRAMS } from "@/features/algorithms/viz/examples/sorts";
import { GRAPH_PROGRAMS } from "@/features/algorithms/viz/examples/graphAlgos";
import { bstShape, TREE_PROGRAMS } from "@/features/algorithms/viz/examples/treeAlgos";
import { vizRunToDataset, type VizDataset, type TreeDatasetNode } from "@/features/algorithms/viz/vizDataset";

/** The structures the shape tier can source a real dataset for. */
export type PreviewStructure = "array" | "graph" | "tree";

/** Nest a `bstShape` (flat parent-pointer nodes + left/right child maps) into a `{ id, label, children }`
 *  forest node — the shared Tree component's `nodes` shape. Recurses left then right. */
function nestBst(shape: ReturnType<typeof bstShape>, id: string): TreeDatasetNode {
  const node = shape.nodes.find((n) => n.id === id);
  const children: TreeDatasetNode[] = [];
  const l = shape.left[id];
  if (l) children.push(nestBst(shape, l));
  const r = shape.right[id];
  if (r) children.push(nestBst(shape, r));
  return { id, label: String(node?.value ?? id), ...(children.length ? { children } : {}) };
}

/**
 * A real, algorithm-GENERATED dataset for `structure`, normalized to the shape a component preview binds
 * to: a sorted array, a traversed graph, or a BST forest (#3790). `undefined` only if no program is
 * registered (never in practice). Deterministic: a fixed program on its default seed, on the main thread.
 */
export function datasetForStructure(structure: PreviewStructure): VizDataset | undefined {
  if (structure === "array") {
    const program = Object.values(TRACE_PROGRAMS)[0];
    if (!program) return undefined;
    const frames = [...runAlgorithm(program.run, program.defaultInput)()];
    return vizRunToDataset({ datatype: "array", input: [...program.defaultInput], frames, source: "" });
  }
  if (structure === "graph") {
    const program = Object.values(GRAPH_PROGRAMS)[0];
    if (!program) return undefined;
    const frames = [...runGraphAlgorithm(program.run, program.defaultInput)()];
    return vizRunToDataset({ datatype: "graph", input: program.defaultInput, frames, source: "" });
  }
  // tree: the BST the tree programs produce, as PURE data (`bstShape` — no tracer/frames), nested.
  const program = TREE_PROGRAMS["bst-insert"] ?? Object.values(TREE_PROGRAMS)[0];
  if (!program) return undefined;
  const shape = bstShape(program.defaultInput);
  if (!shape.rootId) return undefined;
  return { kind: "tree", roots: [nestBst(shape, shape.rootId)] };
}

// Renderer registry and handle interfaces for the preview feed consumer (#581).
// Each renderer is keyed by one or more RenderableKinds. The registry is module-level
// so renderers self-register on import; the shell calls getRenderer(kind) to dispatch.

import type { RenderableKind, RenderableChunk, PreviewStatus } from '@/features/planner/preview/types';

/**
 * An imperative handle to a mounted renderer surface. The shell holds this ref and
 * calls update() for every arriving chunk — zero React re-renders on the hot path.
 */
export interface RendererHandle {
  /** Deliver a new chunk to the surface imperatively (no React setState). */
  update(chunk: RenderableChunk): void;
  /** Subscribe to renderer-reported status changes (called once after mount). */
  onStatus(cb: (s: PreviewStatus) => void): void;
  /** Remove the surface from the container and clean up all listeners. */
  teardown(): void;
}

/**
 * A pluggable renderer: declares the kind(s) it handles, mounts a surface into a
 * container element, and returns a handle for imperative updates.
 */
export interface PreviewRenderer {
  kind: RenderableKind | RenderableKind[];
  mount(container: HTMLElement, initial: RenderableChunk): RendererHandle;
}

const REGISTRY = new Map<RenderableKind, PreviewRenderer>();

/** Register a renderer for its declared kind(s). Last registration wins (idempotent). */
export function registerRenderer(renderer: PreviewRenderer): void {
  const kinds: RenderableKind[] = Array.isArray(renderer.kind) ? renderer.kind : [renderer.kind];
  for (const k of kinds) REGISTRY.set(k, renderer);
}

/** Look up the renderer for a kind. Returns undefined when none is registered. */
export function getRenderer(kind: RenderableKind): PreviewRenderer | undefined {
  return REGISTRY.get(kind);
}

/** True when a renderer is registered for the given kind. */
export function hasRenderer(kind: RenderableKind): boolean {
  return REGISTRY.has(kind);
}

/** Test helper — reset the registry between cases. */
export function _resetRegistry(): void {
  REGISTRY.clear();
}

// Preview review loop (#2623 slice 5) — the PURE decision core. During the in-graph preview the user
// walks the finished app; each captured SHOT (a screenshot + a label of what they navigated to) is sent
// to Claude, which returns FINDINGS. Findings land in a CONFIRM-GATED inbox: nothing is routed to the
// fleet until the USER confirms it (the reviewer PROPOSES, the user DISPOSES — mirrors user-only-confirms).
// A confirmed finding becomes a director DISPATCH (bsc-issue → bsc-assign), the same path faultTriage
// (#2265) routes runtime faults, so the maintenance fleet fixes it.
//
// Kept React/Tauri-free so the loop's guarantees are unit-tested in isolation:
//   • DEDUP    — the same finding for the same shot never enters the inbox twice (idempotent re-review).
//   • GATE     — only USER-confirmed findings are dispatchable; pending/dismissed never route.
//   • PARSE    — Claude's reply is coerced tolerantly (code fences / stray prose can't crash the loop).

export type ReviewSeverity = "polish" | "issue" | "blocker";

/** One screen the user captured during the preview walkthrough. */
export interface PreviewShot {
  id: string;
  /** What the user was looking at — a route/path or a free label. */
  label: string;
  /** The captured frame as a data URL (`data:image/png;base64,…`); the multimodal review attaches it. */
  image: string;
}

/** One thing Claude flagged about a shot. `status` is the confirm gate — the finding is inert until the
 *  user confirms it. */
export interface ReviewFinding {
  id: string;
  shotId: string;
  severity: ReviewSeverity;
  title: string;
  detail: string;
  status: "pending" | "confirmed" | "dismissed" | "routed";
}

const SEVERITY_RANK: Record<ReviewSeverity, number> = { polish: 1, issue: 2, blocker: 3 };
function rank(s: ReviewSeverity): number {
  return SEVERITY_RANK[s] ?? 0;
}

/** The stable identity of a finding — its shot + its normalized title. Two reviews of the same shot that
 *  surface the same problem collapse to one inbox row (so re-reviewing doesn't duplicate). */
export function findingKey(f: Pick<ReviewFinding, "shotId" | "title">): string {
  return `${f.shotId}::${f.title.trim().toLowerCase().replace(/\s+/g, " ")}`;
}

/**
 * Fold freshly-parsed findings into the existing inbox. Pure + order-stable.
 *  - DEDUP: a finding whose {@link findingKey} already exists is dropped (the existing row — and its
 *    user-set status — wins), so re-reviewing a shot never resurrects a dismissed finding or duplicates a
 *    confirmed one.
 *  - New findings are appended in arrival order with `status: "pending"`.
 */
export function mergeFindings(existing: ReviewFinding[], incoming: ReviewFinding[]): ReviewFinding[] {
  const seen = new Set(existing.map(findingKey));
  const fresh: ReviewFinding[] = [];
  for (const f of incoming) {
    const key = findingKey(f);
    if (seen.has(key)) continue;
    seen.add(key);
    fresh.push({ ...f, status: "pending" });
  }
  return [...existing, ...fresh];
}

/** Transition one finding's confirm-gate status (confirm / dismiss / re-open). Pure — returns a new list. */
export function setFindingStatus(
  findings: ReviewFinding[],
  id: string,
  status: ReviewFinding["status"],
): ReviewFinding[] {
  return findings.map((f) => (f.id === id ? { ...f, status } : f));
}

/** Findings still awaiting the user's decision (worst first). */
export function pendingFindings(findings: ReviewFinding[]): ReviewFinding[] {
  return findings.filter((f) => f.status === "pending").sort((a, b) => rank(b.severity) - rank(a.severity));
}

/** The user-confirmed findings — the ONLY ones eligible to dispatch to the fleet. Once routed they move
 *  to `routed` (see {@link routedFindings}) so they drop out here and can't be dispatched twice. */
export function confirmedFindings(findings: ReviewFinding[]): ReviewFinding[] {
  return findings.filter((f) => f.status === "confirmed").sort((a, b) => rank(b.severity) - rank(a.severity));
}

/** Findings already routed to the fleet (dispatched) — surfaced as a tally, never re-dispatched. */
export function routedFindings(findings: ReviewFinding[]): ReviewFinding[] {
  return findings.filter((f) => f.status === "routed");
}

/** The system prompt for the one-shot review call — a terse UI reviewer that MUST answer as strict JSON. */
export function reviewSystemPrompt(): string {
  return [
    "You are a meticulous UI/UX reviewer looking at one screen of a finished application the user is",
    "previewing. Report only concrete, actionable problems you can SEE in the screenshot — layout breaks,",
    "misalignment, contrast/legibility, overflow/clipping, inconsistent spacing, obvious broken or empty",
    "states. Do not invent behavior you can't observe. Prefer few high-signal findings over many nits.",
    "",
    'Answer with ONLY a JSON array (no prose, no code fence): [{"severity","title","detail"}]. severity is',
    'one of "polish" | "issue" | "blocker". title ≤ 8 words. detail is one sentence naming the fix. Return',
    "[] when the screen looks good.",
  ].join("\n");
}

/** The user-message text for the review of one shot (the screenshot image is attached alongside it by the
 *  multimodal caller — slice 5c). */
export function reviewUserPrompt(shot: Pick<PreviewShot, "label">): string {
  return `Screen: ${shot.label || "(app)"}. Review this screen and report findings as the JSON array.`;
}

/** Parse Claude's review reply into findings for `shotId`. Tolerant: strips a ```json fence, finds the
 *  first JSON array, and coerces each entry — an unparseable / non-array reply yields `[]` (never throws),
 *  so a bad review can't break the loop. `idFor(i)` mints each finding's id (pass a stable minter). */
export function parseFindings(raw: string, shotId: string, idFor: (i: number) => string): ReviewFinding[] {
  const arr = extractJsonArray(raw);
  if (!arr) return [];
  const out: ReviewFinding[] = [];
  for (const entry of arr) {
    if (!entry || typeof entry !== "object") continue;
    const e = entry as Record<string, unknown>;
    const title = typeof e.title === "string" ? e.title.trim() : "";
    if (!title) continue;
    out.push({
      id: idFor(out.length),
      shotId,
      severity: coerceSeverity(e.severity),
      title,
      detail: typeof e.detail === "string" ? e.detail.trim() : "",
      status: "pending",
    });
  }
  return out;
}

function coerceSeverity(v: unknown): ReviewSeverity {
  return v === "blocker" || v === "issue" || v === "polish" ? v : "issue";
}

/** Find the first top-level JSON array in a model reply (handles a leading code fence or stray prose). */
function extractJsonArray(raw: string): unknown[] | null {
  const start = raw.indexOf("[");
  const end = raw.lastIndexOf("]");
  if (start === -1 || end <= start) return null;
  try {
    const parsed = JSON.parse(raw.slice(start, end + 1));
    return Array.isArray(parsed) ? parsed : null;
  } catch {
    return null;
  }
}

/** The director-facing message routing the user-confirmed findings to the fleet — one paste covers the
 *  batch; the director runs `bsc-issue` (capture) → `bsc-assign` (route to the owning worker) per its
 *  protocol, exactly like the fault-triage dispatch (#2265). `shotLabel` maps a shotId → its screen label. */
export function reviewDispatchPrompt(
  confirmed: ReviewFinding[],
  shotLabel: (shotId: string) => string,
): string {
  const lines = confirmed
    .map((f) => `• [${f.severity}] ${f.title} — ${f.detail} (screen: ${shotLabel(f.shotId) || "app"})`)
    .join("\n");
  return [
    "[preview-review] The user reviewed the running app and CONFIRMED these UI findings — route a fix for each:",
    lines,
    "For each finding: capture it with `bsc-issue` (the title + detail above), then `bsc-assign <session>` " +
      "the worker whose `owns` lane covers that screen (open a GitHub issue first if it should be tracked). " +
      "Close the loop when the fix merges to develop.",
  ].join("\n");
}

// Preview module resolution — dynamic + supply-chain-safe (#3696, request #41).
//
// The Design Studio + planner previews bundle a component/skeleton with esbuild-wasm and mount it in a
// sandboxed iframe. Bare imports are resolved two ways, and ONLY these two — there is no "any other bare →
// esm.sh at large" path, because that is an open supply-chain door (arbitrary CDN code execution):
//
//   1. EXTERNAL — a curated, version-pinned allowlist (`@data/ui/preview-importmap.json`: react, react-dom,
//      three, d3, lucide, …). These are the ONLY specifiers fetched from esm.sh, and the iframe CSP
//      (`PREVIEW_CSP`) confines even a compromised one (no `connect-src`, so it can render but never
//      exfiltrate or escape the sandbox).
//   2. LOCAL SHIM — everything else resolves to a module BUNDLED IN LOCALLY (no network): the two fidelity
//      shims below (`react-native` → real flex-column layout, `react-native-svg` → real SVG DOM), or the
//      UNIVERSAL STUB — a "black-hole" module that safely satisfies ANY import shape from ANY package. So a
//      harvested component NEVER fails with "Failed to resolve module specifier" (dynamic + always works),
//      and the long tail of native/npm packages costs zero CDN surface (safe).
//
// The doctor reads the SAME resolution rule: a bare import is always resolvable now (external or stub), so
// it is never flagged unresolvable.

// ── The universal stub ──────────────────────────────────────────────────────────────────────────────────
// `makeStub(name)` — a "black-hole" value that safely stands in for ANY export of a package the preview
// doesn't implement. No React dependency: a component stub (a Capitalized name) renders its children
// directly; a hook stub (`use[A-Z]`) returns another black-hole (safe to destructure, index, call, or
// coerce to a primitive). Every trap React / a bundler / a style serializer might probe is handled so it
// can never throw. This helper is INLINED into a generated ESM module whose named exports are exactly the
// names the component imports (see `scanStubImports` + `universalStub`) — a real ESM export list, so
// esbuild resolves the named imports directly (a CJS-Proxy module can't: esbuild's interop copies OWN keys,
// which a Proxy can't enumerate, so every named import came back `undefined`).
export const STUB_HELPER = `function makeStub(name) {
  var isHook = typeof name === "string" && /^use[A-Z]/.test(name);
  var target = function () {};
  return new Proxy(target, {
    get: function (t, k) {
      if (k === "__esModule") return true;
      if (k === "then") return undefined;                 // never thenable (await / React.lazy safe)
      if (k === "prototype") return undefined;             // a function component, never a class
      if (k === "$$typeof" || k === "defaultProps" || k === "propTypes" || k === "contextTypes") return undefined;
      if (k === Symbol.toPrimitive) return function (hint) { return hint === "number" ? 0 : ""; };
      if (k === Symbol.iterator) return function () { var i = 0; return { next: function () { return i++ < 8 ? { value: makeStub(""), done: false } : { value: undefined, done: true }; } }; };
      if (k === "displayName") return name || "Stub";
      if (typeof k === "symbol") return undefined;
      if (k in t) return t[k];                             // real function props (name, length, call, …)
      return makeStub(k);                                  // any other property → a fresh stub (classified by ITS name)
    },
    apply: function (t, thisArg, args) {
      if (isHook) return makeStub("");                     // useX() → a black-hole value
      var props = args && args[0];                         // <Comp .../> → render its children
      return props && props.children != null ? props.children : null;
    },
    construct: function () { return {}; },                 // new X() → an empty object (defensive)
  });
}`;

/** Is `name` a legal JS identifier we can emit as `export const <name>`? (Import bindings always are; this
 *  guards against a malformed scan.) */
function isIdent(name: string): boolean {
  return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name);
}

/** A generated ESM universal-stub module exporting EXACTLY `exportNames` (each a black-hole) plus a default.
 *  A real static export list, so esbuild resolves the component's named imports directly. */
export function universalStub(exportNames: string[]): string {
  const named = Array.from(new Set(exportNames))
    .filter((n) => n !== "default" && isIdent(n))
    .map((n) => `export const ${n} = makeStub(${JSON.stringify(n)});`)
    .join("\n");
  return `${STUB_HELPER}\n${named}\nexport default makeStub("Default");\n`;
}

// ── react-native → real DOM layout ──────────────────────────────────────────────────────────────────────
// A local shim so harvested React Native components lay out correctly (RN's default box is a flex COLUMN,
// unlike a DOM block) with StyleSheet/Platform/Animated present. No react-native-web CDN dependency.
const REACT_NATIVE_SHIM = `import { createElement as h } from "react";
const flatten = (s) => Array.isArray(s) ? Object.assign({}, ...s.flat(Infinity).filter(Boolean)) : (s || {});
