/** Bare specifiers that get a DEDICATED fidelity shim (real layout / real SVG) instead of the universal
 *  stub. Everything else bare (that isn't a curated external) falls through to `UNIVERSAL_STUB`. */
export const DEDICATED_SHIMS: Record<string, string> = {
  "react-native": REACT_NATIVE_SHIM,
  "react-native-svg": REACT_NATIVE_SVG_SHIM,
};

/** The esbuild namespace a locally-shimmed bare import is loaded from. */
export const PREVIEW_SHIM_NAMESPACE = "preview-shim";

/**
 * Scan `files` for the NAMED bindings each universal-stubbed package is imported with — so a generated stub
 * can export exactly those names. A specifier is universal-stubbed when it's bare (not relative / `@/` /
 * `@bsc/`), NOT a curated external, and NOT a dedicated shim (those have static exports, no scan needed).
 * Pure; over-collection is harmless (an extra export never hurts). Returns spec → the union of its imported
 * names across all files.
 *
 * `isFirstPartyStub` widens that to the caller's declared boundary (#3897): a `@/…` the caller stubs rather
 * than vendors is scanned too, so its stub exports the bindings it is imported with instead of failing the
 * build on a missing export. It defaults to none — a `@/…` is a mem-filesystem lookup unless a caller says
 * otherwise, and `@bsc/…` is never stubbed (an unvendored one is an honest unresolvable-import).
 */
export function scanStubImports(
  files: Record<string, string>,
  isExternal: (spec: string) => boolean,
  isFirstPartyStub: (spec: string) => boolean = () => false,
): Map<string, string[]> {
  const importRe = /import\s+([^;'"]*?)\s+from\s*['"]([^'"]+)['"]/g;
  const acc = new Map<string, Set<string>>();
  for (const src of Object.values(files)) {
    importRe.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = importRe.exec(src))) {
      const [, clause, spec] = m;
      if (/^[./]/.test(spec) || spec.startsWith("@bsc/")) continue;                           // relative / library
      if (spec.startsWith("@/") && !isFirstPartyStub(spec)) continue;                         // first-party, vendored
      if (isExternal(spec) || spec in DEDICATED_SHIMS) continue;                              // real resolution, not a stub
      const set = acc.get(spec) ?? new Set<string>();
      const braces = /\{([^}]*)\}/.exec(clause);
      if (braces) {
        for (const part of braces[1].split(",")) {
          const name = part.trim().replace(/^type\s+/, "").split(/\s+as\s+/)[0].trim();
          if (name) set.add(name);
        }
      }
      acc.set(spec, set);
    }
  }
  return new Map(Array.from(acc, ([spec, set]) => [spec, Array.from(set)]));
}

/** The local module source a bare specifier resolves to when it is NOT a curated external — its dedicated
 *  fidelity shim, else a universal stub exporting the `exportNames` the component imports it with. Bundled
 *  in (no network), so resolution can never fail. */
export function shimModuleFor(spec: string, exportNames: string[] = []): string {
  return DEDICATED_SHIMS[spec] ?? universalStub(exportNames);
}

// ── The preview iframe CSP ───────────────────────────────────────────────────────────────────────────────
/**
 * Content-Security-Policy for the preview iframe (embedded as a `<meta http-equiv>` in the srcdoc, on TOP of
 * `sandbox="allow-scripts"`). The sandbox already blocks same-origin access (a compromised dependency can't
 * read the host app); this CLOSES THE EXFILTRATION + EXECUTION channels:
 *   - `connect-src 'none'`  — no fetch / XHR / WebSocket / sendBeacon: a compromised esm.sh dependency can
 *     render but can never phone home with anything it sees.
 *   - `script-src 'unsafe-inline' https://esm.sh` — runs the inlined bundle + our shims, and the curated
 *     esm.sh externals, and NOTHING else (no `data:` scripts, no other host).
 *   - `default-src 'none'` — every other fetch class (frames, workers, manifest, media) is denied.
 * Images/fonts allow `data:`/`https:` so previews still show art. All local stubs are bundled (not `data:`
 * URLs), which is what lets `script-src` stay this tight.
 */
export const PREVIEW_CSP =
  "default-src 'none'; " +
  "script-src 'unsafe-inline' https://esm.sh; " +
  "style-src 'unsafe-inline'; " +
  "img-src data: https:; " +
  "font-src data: https://esm.sh; " +
  "connect-src 'none'";

/** The `<meta http-equiv>` CSP tag for a preview srcdoc `<head>`. */
export function previewCspMeta(): string {
  return `<meta http-equiv="Content-Security-Policy" content="${PREVIEW_CSP}" />`;
}

// PreviewSource (#2623) — the TARGET-AGNOSTIC contract between the verify-build (which builds + serves a
// finished application) and the preview node in the graph (which RENDERS it in place). The build picks
// the `kind` from the project's stack; the node switches on `kind`. Decoupling "how it's built/served"
// from "how it renders" means a new render target slots in behind the seam WITHOUT touching the node. A
// wgpu/`wasm32` Rust 3D app compiles to a canvas → the SAME iframe as a web app (the `bundle`/`web` kinds),
// so only a pure native-window binary needs the `native` kind — which the verify-build builds and launches
// as its OWN desktop window (host-native, or a Linux GUI passed through WSLg). In-graph frame capture is a
// future render surface behind this same seam (slice 5+); v1 renders native as a launched external window.
// Pure (no React/Tauri) so it's unit-testable and shared by both features (planner build · glance render).

/** What the verify-build produced for a completed project to preview. */
export type PreviewSource =
  | { kind: "web"; url: string }        // a served local dev/preview URL — a Node web app
  | { kind: "bundle"; srcDoc: string }  // a static HTML/JS/WASM bundle — rendered as an iframe srcdoc
  | { kind: "native"; label: string };  // a native binary launched as its own desktop window (WSLg/host)

/** How a {@link PreviewSource} renders — the descriptor the preview node's frame reads. `iframe` covers
 *  a web URL, a static bundle, AND a wgpu/wasm app compiled to the web; `external` is a native app running
 *  as its own OS window (WSLg / host) — it renders on the desktop, not inside the node. */
export type PreviewRender =
  | { mode: "iframe"; src?: string; srcDoc?: string }
  | { mode: "external"; label: string };

/** Map a {@link PreviewSource} to its render descriptor — the one place `kind` is switched on. Pure. */
export function previewRender(source: PreviewSource): PreviewRender {
  switch (source.kind) {
    case "web":    return { mode: "iframe", src: source.url };
    case "bundle": return { mode: "iframe", srcDoc: source.srcDoc };
    case "native": return { mode: "external", label: source.label };
  }
}

/** Whether a source renders in the sandboxed iframe (web / bundle / wasm) vs on the desktop as its own
 *  native window — the split the preview node uses to pick its render surface. */
export function isIframeSource(source: PreviewSource): boolean {
  return source.kind !== "native";
}

// Core types for the modular streaming preview feed consumer (#581).

/** The set of renderable content kinds the registry dispatches on. */
export type RenderableKind =
  | 'react-bundle'
  | 'html'
  | 'gltf'
  | 'scene'
  | 'image'
  | 'video-frame';

/**
 * A chunk arriving from the preview feed. One-shots are streams of length 1
 * (`final: true`). The `payload` is opaque to the shell; each renderer knows
 * its own payload shape.
 */
export interface RenderableChunk {
  kind: RenderableKind;
  /** Opaque label identifying the producer; chrome-only, never affects routing. */
  source?: string;
  /** Display mode hint, passed to the pane chrome (e.g. "2d" | "3d"). */
  mode?: string;
  /** Monotonically increasing sequence number for ordering. */
  seq?: number;
  /** True when this is the final chunk in the stream. */
  final?: boolean;
  /** Renderer-specific payload (opaque to the shell). */
  payload: unknown;
}

/** Renderer-reported surface status, forwarded to the pane chrome. */
export interface PreviewStatus {
  status: 'building' | 'ready' | 'error';
  message?: string;
}

// Agents — profile → session-settings bridge (#255).
//
// Translates an editable `AgentProfile` (base mode + command allowlist + per-tool
// tri-states + path globs) into the exact inputs `ensure_session_settings` consumes —
// the SAME channel the role gate (#219) uses (allowedCommands / deniedCommands /
// allowToolRules / denyToolRules). Assigning a profile to a console pane therefore
// enforces it for real at session launch, not just in the UI. Pure + unit-testable.

import type { AgentProfile, ToolKey, Tier } from "@/features/security/lib/agentProfiles";
import { editPathRule } from "@/shared/lib/session/sessionRoles";

/** The Claude Code tool name(s) each profile capability maps to (bare, whole-tool rules). `edit`
 *  covers the in-place edit tools; `write` is creation; `web` is both fetch + search. No `MultiEdit`
 *  — it was removed from Claude Code (#3534). */
const TOOL_NAMES: Record<ToolKey, string[]> = {
  read: ["Read"],
  grep: ["Grep"],
  glob: ["Glob"],
  edit: ["Edit", "NotebookEdit"],
  write: ["Write"],
  bash: ["Bash"],
  web: ["WebFetch", "WebSearch"],
  task: ["Task"],
};

/** Settings-rule inputs for `ensure_session_settings`, identical to the role gate's. */
export interface ProfileSessionSettings {
  /** Shell prefixes auto-approved (wrapped as `Bash(<cmd> *)` by the backend). */
  allowedCommands: string[];
  /** Command prefixes to deny (the role gate supplies git/gh denies; profiles add none). */
  deniedCommands: string[];
  /** Verbatim tool-permission allows (`Read`, `Edit(src/**)`, …). */
  allowToolRules: string[];
  /** Verbatim tool-permission denies (deny wins over allow). */
  denyToolRules: string[];
  /** The catch-all shell disposition (the profile's bash tier) the backend uses to scale how
   *  generous the auto-approve baseline is (#1572): `allow` doers get the read-only + build
   *  baselines, `ask` coordinators get read-only only, `deny` gets neither. */
  bashPosture: Tier;
}

const dedupe = (xs: string[]): string[] => [...new Set(xs)];

/**
 * Map a profile to session settings.
 *
 * - **commands** → `allowedCommands` (auto-approve those shell prefixes).
 * - **tools** tri-states → `allow` (tier `allow`) / `deny` (tier `deny`) tool rules;
 *   `ask` is left unlisted so Claude Code prompts (the default).
 * - **paths** → file-write tool rules scoped per glob (`Edit(<glob>)` etc.); deny wins.
 *
 * Two deliberate edges:
 * - **`bash` is never blanket-denied.** A bare `Bash` deny would also kill the
 *   guaranteed `gh`/`git`; shell control flows through the command allowlist + the
 *   role gate instead. (Bash `allow` is harmless — the backend already allows it.)
 * - **`mode`** (the base policy) and **`net`** are advisory here: every capability the
 *   gate can express is enumerated by the per-tool tiers + paths, and host-level
 *   network limits aren't expressible via `settings.json`.
 */
export function resolveProfileSettings(profile: AgentProfile): ProfileSessionSettings {
  const allowToolRules: string[] = [];
  const denyToolRules: string[] = [];

  for (const [key, tier] of Object.entries(profile.tools) as [ToolKey, Tier][]) {
    if (tier === "deny") {
      if (key === "bash") continue; // see docstring — never blanket-deny Bash
      denyToolRules.push(...TOOL_NAMES[key]);
    } else if (tier === "allow") {
      allowToolRules.push(...TOOL_NAMES[key]);
    }
  }

  // Path-scoped file rules are `Edit(<glob>)` ONLY (#3534): Claude Code matches file-permission rules
  // on the Edit tool alone, and that one rule covers every file-editing tool. `Write(<glob>)` etc. were
  // never enforced — a silent no-op for an allow, an unenforced deny for a deny.
  for (const g of profile.paths.allow) allowToolRules.push(editPathRule(g));
  for (const g of profile.paths.deny) denyToolRules.push(editPathRule(g));

  return {
    allowedCommands: dedupe(profile.commands),
    deniedCommands: [],
    allowToolRules: dedupe(allowToolRules),
    denyToolRules: dedupe(denyToolRules),
    bashPosture: profile.tools.bash,
  };
}

// ── GraphQL query ─────────────────────────────────────────────────────────────

