import { invoke } from "@tauri-apps/api/core";
import { DEFAULT_MAX_AGE_SECS } from "@/shared/lib/github/github";

/** Minimal shape of a ProjectV2 item needed to resolve its repository. */
export interface ProjectItemNode {
  content?: { repository?: { nameWithOwner?: string } | null } | null;
}

/**
 * Unique `owner/name` repositories referenced by a project's items.
 *
 * Repos are derived from the issues on the project board rather than the
 * project-level `repositories` field: that field only reflects repos a user has
 * explicitly linked in the GitHub UI and is therefore frequently incomplete,
 * whereas every issue carries the repository it lives in.
 */
export function reposFromItems(nodes: ReadonlyArray<ProjectItemNode>): string[] {
  return [...new Set(
    nodes
      .map(n => n.content?.repository?.nameWithOwner)
      .filter((r): r is string => !!r),
  )];
}

// Lightweight query — only the fields needed to resolve repos, so the tab-open
// scan stays cheap even when the heavier board view isn't mounted.
const PROJECT_REPOS_QUERY = `
query($id: ID!) {
  node(id: $id) {
    ... on ProjectV2 {
      items(first: 100) {
        nodes { content { ... on Issue { repository { nameWithOwner } } } }
      }
    }
  }
}`;

interface ReposQueryResult {
  node?: { items?: { nodes?: ProjectItemNode[] } } | null;
}

/**
 * Resolves the full set of repositories linked to a GitHub Project by scanning
 * its items. Returns `owner/name` strings (empty if the project has no issues).
 *
 * @param token - GitHub token for the GraphQL request.
 * @param projectId - ProjectV2 node id.
 */
export async function scanProjectRepos(token: string, projectId: string): Promise<string[]> {
  // `maxAgeSecs` routes the read through the backend TTL cache (#2447) so re-opening the tab
  // within the window doesn't re-POST the items scan. Raw invoke (not `githubGraphql`) because
  // this lib takes its token explicitly instead of reaching into the store.
  const data = await invoke<ReposQueryResult>("github_graphql", {
    token, query: PROJECT_REPOS_QUERY, variables: { id: projectId }, maxAgeSecs: DEFAULT_MAX_AGE_SECS,
  });
  return reposFromItems(data.node?.items?.nodes ?? []);
}

/**
 * Reads the on-disk plan sections for a project (the markdown the planner's
 * Claude session writes), keyed by section name. Mirrors the planner's own poll
 * so the plan can be refreshed without entering the planner.
 *
 * @param projectKey - the planning session key (the project title for projects
 *   opened from the list), matching the directory where plan files are stored.
 */
export async function scanPlanStages(projectKey: string): Promise<Record<string, string>> {
  return invoke<Record<string, string>>("read_plan_stages", { projectKey });
}

// Project-scoped store-map registry (#2712).
//
// The same long list of per-project store maps (`Record<projectKey, …>`) used to be hand-enumerated
// at THREE sites that had to stay in sync:
//   - `deleteLocalProject`        (slices/projects.ts) — drop a SET of project keys from every map
//   - `rekeyProjectData`          (slices/projects.ts) — move oldKey → newKey (target-wins)
//   - `clearPlan`                 (slices/plan.ts)     — drop ONE project key
//
// The three sites cover **slightly different subsets** — e.g. `clearPlan` resets the plan maps but not
// the per-project preference maps (`autoTriage`, drafts, …); only `rekeyProjectData` touches
// `planFleetTopology`; only the plan.ts `clearPlan` site touches `reposPublic` / `stagePreview`.
// This file is the ONE source of truth: each map declares exactly which of the three operations it
// participates in, and the generic helpers below drive all three ops from it — so the subsets can no
// longer drift, while each op's exact set is preserved byte-for-byte.

import type { AppStore } from "@/store/types";
import { deleteMapEntry, deleteMapEntries } from "@/store/updateHelpers";

/** The three project-scoped mutations, each with its own subset of the maps below. */
export type ProjectMapOp = "delete" | "rekey" | "clearPlan";

// A map is opaque here — the values differ per map, but every op is key-only (drop/move by
// projectKey), so the value type is irrelevant to this module.
type AnyMap = Record<string, unknown>;

/**
 * Per-project maps keyed by the bare `projectKey`, with the set of operations that touch each.
 * Cross-check against the four call sites; add none, drop none. The union of these keys is the
 * complete set of `Record<projectKey, …>` maps any of the four project-scoped ops mutates.
 */
const PROJECT_MAP_OPS: Partial<Record<keyof AppStore, ProjectMapOp[]>> = {
  planStages:              ["delete", "rekey", "clearPlan"],
  planConfirmedStages:     ["delete", "rekey", "clearPlan"],
  planDeployConfig:        ["delete", "rekey", "clearPlan"],
  planMarketConfig:        ["delete", "rekey", "clearPlan"],
  planTransformations:     ["delete", "rekey", "clearPlan"],
  planSkippedStages:       ["delete", "rekey", "clearPlan"],
  planAutomations:         ["delete", "rekey", "clearPlan"],
  uiScreens:               ["delete", "rekey", "clearPlan"],
  uiApproved:              ["delete", "rekey", "clearPlan"],
  planFleet:               ["delete", "rekey", "clearPlan"],
  pinnedContext:           ["delete", "rekey", "clearPlan"],
  issueLinks:              ["delete", "rekey", "clearPlan"],
  projectLocalRepos:       ["delete", "rekey", "clearPlan"],
  // planStageConfig / projectBlueprintId are DROPPED by all three ops (delete/rekey/clearPlan).
  planStageConfig:         ["delete", "rekey", "clearPlan"],
  projectBlueprintId:      ["delete", "rekey", "clearPlan"],
  planClassification:      ["delete", "rekey", "clearPlan"],
  // Plan-config maps the plan.ts site resets; rekey also moves them, delete drops them via… no —
  // planSourceConfig is NOT in deleteLocalProject's set (only rekey + the plan.ts clearPlan reset).
  planSourceConfig:        ["rekey", "clearPlan"],
  // Only the plan.ts clearPlan reset touches these (never delete/rekey).
  reposPublic:             ["clearPlan"],
  planInjectionAck:        ["clearPlan"],
  stagePreview:            ["clearPlan"],
  stageRuns:               ["clearPlan"],
  // Per-project preference / doc maps — deleteLocalProject + rekeyProjectData only (the plan.ts
  // reset sites deliberately leave these alone).
  projectStartupPromptDoc: ["delete", "rekey"],
  autoTriage:              ["delete", "rekey"],
  glanceOff:               ["delete", "rekey"], // #3239: drop a deleted project's off flag; move it on rename

  triagedProjects:         ["delete", "rekey"],
  autoKitDispatch:         ["delete", "rekey"],
  localDraftProjects:      ["delete", "rekey"],
  // rekeyProjectData-only maps (delete already covers everything it needs; the plan.ts sites don't
  // reach these fleet/verification maps).
  planFleetTopology:       ["rekey"],
  planFleetDirectorDrive:  ["rekey"],
};

/**
 * Repo-scoped maps keyed by `<projectKey>::<repo>`, with the ops that touch each. Same registry,
 * different key shape (the prefix before `::` is the project key).
 */
const REPO_MAP_OPS: Partial<Record<keyof AppStore, ProjectMapOp[]>> = {
  repoStartupPromptDoc: ["delete", "rekey"],
  repoTriagePromptDoc:  ["delete", "rekey"],
  repoPublic:           ["clearPlan"],
};

const projectMapNames = (op: ProjectMapOp): (keyof AppStore)[] =>
  (Object.keys(PROJECT_MAP_OPS) as (keyof AppStore)[]).filter((k) => PROJECT_MAP_OPS[k]!.includes(op));
const repoMapNames = (op: ProjectMapOp): (keyof AppStore)[] =>
  (Object.keys(REPO_MAP_OPS) as (keyof AppStore)[]).filter((k) => REPO_MAP_OPS[k]!.includes(op));

/** Every per-project (bare-key) map name in the registry — the full union across the four ops. */
export const PROJECT_SCOPED_MAPS = Object.keys(PROJECT_MAP_OPS) as (keyof AppStore)[];
/** Every repo-scoped (`<key>::<repo>`) map name in the registry. */
export const REPO_SCOPED_MAPS = Object.keys(REPO_MAP_OPS) as (keyof AppStore)[];

// Read a store map by name as an opaque record (the `?? {}` guards a slice missing/null in a
// long-lived persisted store — `Object.entries(undefined)` would throw and crash the app, #874).
const readMap = (s: AppStore, name: keyof AppStore): AnyMap =>
  ((s as unknown as Record<string, AnyMap>)[name] ?? {});

/** Drop the first `::`-delimited segment of `k`; the bare project key otherwise. */
const projectKeyOf = (k: string): string => {
  const idx = k.indexOf("::");
  return idx < 0 ? k : k.slice(0, idx);
};

/**
 * deleteLocalProject: drop every entry whose key (bare project maps) or key-prefix (repo maps) is in
 * `keySet`, for exactly the maps registered under the `"delete"` op.
 */
export function deleteProjectScoped(s: AppStore, keySet: Set<string>): Partial<AppStore> {
  const out: Record<string, AnyMap> = {};
  for (const name of projectMapNames("delete")) {
    out[name] = deleteMapEntries(readMap(s, name), keySet);
  }
  for (const name of repoMapNames("delete")) {
    out[name] = Object.fromEntries(
      Object.entries(readMap(s, name)).filter(([k]) => !keySet.has(projectKeyOf(k))),
    );
  }
  return out as Partial<AppStore>;
}

/**
 * rekeyProjectData: move each entry from `oldKey` → `newKey` (target-wins: an entry already under
 * `newKey` is kept, the old one dropped), for exactly the maps registered under the `"rekey"` op.
 * Repo maps re-prefix `<oldKey>::<repo>` → `<newKey>::<repo>`.
 */
export function rekeyProjectScoped(s: AppStore, oldKey: string, newKey: string): Partial<AppStore> {
  const moveKey = (m: AnyMap): AnyMap => {
    if (!(oldKey in m)) return m;
    const { [oldKey]: moved, ...rest } = m;
    return newKey in m ? rest : { ...rest, [newKey]: moved };
  };
  const moveRepo = (m: AnyMap): AnyMap => {
    const next: AnyMap = {};
    for (const [k, v] of Object.entries(m)) {
      const idx = k.indexOf("::");
      if (idx < 0 || k.slice(0, idx) !== oldKey) { next[k] = v; continue; }
      const nk = newKey + k.slice(idx);
      if (!(nk in m)) next[nk] = v;
    }
    return next;
  };
  const out: Record<string, AnyMap> = {};
  for (const name of projectMapNames("rekey")) out[name] = moveKey(readMap(s, name));
  for (const name of repoMapNames("rekey")) out[name] = moveRepo(readMap(s, name));
  return out as Partial<AppStore>;
}

/**
 * clearPlan: drop the single `key` from every map registered under the single-key reset op.
 * Repo maps drop every `<key>::<repo>` entry.
 */
export function dropProjectScoped(
  s: AppStore,
  op: "clearPlan",
  key: string,
): Partial<AppStore> {
  const prefix = `${key}::`;
  const out: Record<string, AnyMap> = {};
  for (const name of projectMapNames(op)) out[name] = deleteMapEntry(readMap(s, name), key);
  for (const name of repoMapNames(op)) {
    out[name] = Object.fromEntries(Object.entries(readMap(s, name)).filter(([k]) => !k.startsWith(prefix)));
  }
  return out as Partial<AppStore>;
}

// GitHub-project resolution for publish/sync + the triage launch gate (#444).
//
// Publishing/syncing must land on ONE board: when a project isn't linked yet, creation
// used to fire blindly and mint a *second* board on every re-sync of a same-titled
// project. `ensureGithubProject` adopts an existing same-title board before creating.
// The GraphQL executor is injected so the adopt-vs-create decision is unit-testable
// without a live GitHub. Triage is gated until the project is actually published.

import { findByTitle } from "@/shared/lib/core/projectPaths";

/** A GitHub Projects v2 board, as the owner lookup returns it. */
export interface GithubProjectRef {
  id: string;
  number: number;
  title: string;
  url: string;
}

/** The desktop's `github_graphql` bridge, injected so callers (and tests) supply it. */
export type Gql = (query: string, variables: unknown) => Promise<Record<string, unknown>>;

/**
 * First board whose title matches `title` (case/whitespace-insensitive), or null.
 * The dedupe guard that stops publish from creating a duplicate board; shares the one
 * title matcher (#380) so "a project with this title exists" is judged consistently.
 */
export function findProjectByTitle(
  boards: readonly GithubProjectRef[],
  title: string,
): GithubProjectRef | null {
  return findByTitle(boards, title, (b) => b.title);
}

/** How `ensureGithubProject` resolved the board to publish into. */
export type EnsureProjectResult =
  | { action: "linked"; id: string }                                  // already linked (activeProjectId)
  | { action: "adopted"; id: string; number: number; url: string }    // found an existing same-title board
  | { action: "created"; id: string; number: number; url: string };   // created a fresh board

const OWNER_PROJECTS_QUERY = `query($login:String!){
  repositoryOwner(login:$login){
    id
    ... on ProjectV2Owner { projectsV2(first:100){ nodes { id number title url } } }
  }
}`;

const CREATE_PROJECT_MUTATION = `mutation($ownerId:ID!,$title:String!){
  createProjectV2(input:{ownerId:$ownerId,title:$title}){ projectV2 { id number url } }
}`;

/**
 * Resolve the GitHub Project board a publish/sync should use — adopt-or-create, never a
 * blind duplicate (#444).
 *
 * Order: an already-linked board (`activeProjectId`) wins untouched; otherwise the
 * owner's existing boards are fetched and a title match is ADOPTED; only when none
 * exists is a new board created. The single round-trip resolves the owner id and its
 * boards together. Throws if the owner can't be resolved or creation returns nothing.
 */
export async function ensureGithubProject(
  gql: Gql,
  args: { activeProjectId: string | null; ownerLogin: string; title: string },
): Promise<EnsureProjectResult> {
  if (args.activeProjectId) return { action: "linked", id: args.activeProjectId };

  const data = (await gql(OWNER_PROJECTS_QUERY, { login: args.ownerLogin })) as {
    repositoryOwner?: { id?: string; projectsV2?: { nodes?: GithubProjectRef[] } };
  };
  const ownerId = data.repositoryOwner?.id;
  if (!ownerId) throw new Error(`could not resolve owner '${args.ownerLogin}'`);

  const existing = findProjectByTitle(data.repositoryOwner?.projectsV2?.nodes ?? [], args.title);
  if (existing) {
    return { action: "adopted", id: existing.id, number: existing.number, url: existing.url };
  }

  const created = (await gql(CREATE_PROJECT_MUTATION, { ownerId, title: args.title })) as {
    createProjectV2?: { projectV2?: { id: string; number: number; url: string } };
  };
  const pv = created.createProjectV2?.projectV2;
  if (!pv) throw new Error("project not created");
  return { action: "created", id: pv.id, number: pv.number, url: pv.url };
}

/** Inputs to the triage launch gate (#444, #551). */
export interface TriageGateState {
  /** The project is published to GitHub — a board exists (activeProjectId set). */
  published: boolean;
  /** At least one repository is linked. */
  hasRepos: boolean;
  /** A fleet with at least one stream is planned. */
  hasFleet: boolean;
  /** A launch is already in flight. */
  busy: boolean;
  /** Every enabled planning stage is complete or N/A (#551). */
  planReady: boolean;
}

/**
 * Whether "Triage →" may launch (#444/#551): plan must be complete, the project must be
 * published (so issues exist to triage), have repos + a planned fleet, and not be starting.
 */
export function canLaunchTriage(s: TriageGateState): boolean {
  return s.planReady && s.published && s.hasRepos && s.hasFleet && !s.busy;
}

/** Why triage is locked (tooltip), or null when it can launch (#444/#551). */
export function triageLockReason(s: TriageGateState): string | null {
  if (s.busy) return "starting…";
  if (!s.planReady) return "Finish the plan first";
  if (!s.published) return "Publish the project to GitHub first";
  if (!s.hasRepos) return "Link at least one repository first";
  if (!s.hasFleet) return "Plan the agent fleet first";
  return null;
}

/**
 * Why Publish can't proceed, or null when it can (#969). Publish used to return SILENTLY when there
 * was no token or no linked repo, so the user believed they'd published when nothing happened — and
 * the fleet-launch button then stayed locked with no explanation. The common trigger is a blueprint
 * with no Repos stage (e.g. a user-authored `maintain` one): nothing ever prompts a repo link.
 */
export function publishBlockReason(s: { hasToken: boolean; repoCount: number }): string | null {
  if (!s.hasToken) return "Can't publish — connect a GitHub token in Settings first.";
  if (s.repoCount === 0) return "Can't publish — no repository is linked. This blueprint has no Repos stage, so add one (or link a repo) before publishing.";
  return null;
}

/** The project's display title — used for the fleet/triage tab name and the published GitHub
 *  structure. Resolution order:
 *  1. an explicit planning title,
 *  2. a published project's real name (`activeProjectName`) — a named/published project should
 *     show its NAME, not a heuristic derived from its goal prose,
 *  3. the first real sentence of the goal prose, with markdown heading lines (e.g. `# Goal`)
 *     skipped so the heading never leaks as the title (was naming triage tabs "# Goal"),
 *  4. a default.
 *
 *  Single source of truth for the two call sites (`Planning.tsx` + `usePlanPublish.ts`) that used
 *  to hand-roll this and drift. */
export function deriveProjectTitle(
  planningTitle: string,
  goalContent: string,
  activeProjectName: string,
): string {
  const goalSentence = goalContent
    .replace(/^\s*#.*$/gm, "")            // drop markdown heading lines (e.g. "# Goal")
    .split(/[.!?\n]/)
    .map((s) => s.trim())
    .find(Boolean) ?? "";
  return planningTitle || activeProjectName || goalSentence || "New project";
}

