// Shared ProjectV2 (GitHub Projects) GraphQL response parsing (#1529). The planner/github screens
// (Issues, ProjectBoard, Insights) each fetch a `projectsV2` node and walk its fields + items the
// same way: read the Status single-select options, then iterate items, skip non-Issue content, and
// map each issue into a screen-specific row. This factors that walk; each screen supplies its own
// `mapIssue`.

/** A ProjectV2 item field-value node — we only read single-select (Status) values. */
export interface ProjectV2FieldValue {
  name?: string;
  optionId?: string;
  field?: { name: string };
}

/** A ProjectV2 item. `content` is the underlying Issue/PR/draft, typed loosely so each screen
 *  narrows it via its own `mapIssue` (it always carries `__typename`). */
export interface ProjectV2Item {
  id: string;
  fieldValues: { nodes: ProjectV2FieldValue[] };
  content?: ({ __typename?: string } & Record<string, unknown>) | null;
}

/** A single-select option — the Status column values. */
export interface ProjectV2StatusOption {
  id: string;
  name: string;
  color: string;
}

interface ProjectV2Field {
  id?: string;
  name?: string;
  options?: ProjectV2StatusOption[];
}

/** The `node` of a `projectsV2` GraphQL response (the `data.node` returned by `github_graphql`). */
export interface ProjectV2Node {
  fields?: { nodes: ProjectV2Field[] };
  items: { nodes: ProjectV2Item[] };
}

/** The Status single-select field's options in board order (`[]` when there's no Status field). */
export function parseProjectV2Fields(node: ProjectV2Node | undefined): ProjectV2StatusOption[] {
  const statusField = node?.fields?.nodes?.find((f) => f.name === "Status" && f.options);
  return statusField?.options ?? [];
}

/** An item's Status field-value (its single-select `name` + `optionId`), if any. */
export function statusFieldValue(item: ProjectV2Item): ProjectV2FieldValue | undefined {
  return item.fieldValues.nodes.find((fv) => fv.field?.name === "Status");
}

/**
 * Walk a ProjectV2 node's items, keep only `Issue` content, and map each surviving item via
 * `mapIssue` — which receives the narrowed issue content (type `C`, supplied by the caller) plus
 * the raw item (for `item.id` and `item.fieldValues`).
 */
export function parseProjectV2Items<C, T>(
  node: ProjectV2Node | undefined,
  mapIssue: (content: C, item: ProjectV2Item) => T,
): T[] {
  if (!node?.items?.nodes) return [];
  const out: T[] = [];
  for (const item of node.items.nodes) {
    const content = item.content;
    if (!content || content.__typename !== "Issue") continue;
    out.push(mapIssue(content as unknown as C, item));
  }
  return out;
}

// The Projects page ↔ `bsc project db` bridge (#2995) — drafts get a durable home in the projects DB,
// reached through the generic `bsc` bridge, so a draft survives a restart even when the fragile
// `localDraftProjects` cache misses. Mirrors projectLinksBridge/graphBridge discipline: `listDbProjects`
// returns `null` when the bridge is unreachable (the web shell, the tests, or an OLD bundled `bsc`
// without the `project db` verb) so the page keeps its persisted cache rather than blanking it, and
// every read is shape-gated before it's trusted. The write helpers are fire-and-forget (they degrade
// to cache-only when the bridge/binary is absent) — this is a strictly ADDITIVE, dual-write layer over
// the existing store draft map, never a replacement for it.
import { bscJson, bscWrite, bscRun } from "@/shared/lib/core/bsc";

/** A row of the durable projects DB (`bsc project db list`). `blueprint`/`category` may be null;
 *  `state` ∈ `drafted|planning|published|created`. */
export interface DbProject {
  key: string;
  title: string;
  pitch: string;
  blueprint: string | null;
  category: string | null;
  state: string;
  createdAt: number;
  updatedAt: number;
  /** When the project was TRIAGED (epoch ms), `null` if never, ABSENT on a pre-#4088 binary (#4088).
   *  Gates the Glance network — `projects.db` is the source; the store keeps an in-memory cache
   *  hydrated from here. Optional so an older sidecar's payload still shape-gates cleanly. */
  triagedAt?: number | null;
  /** The ARCHITECT persona id that OWNS this project (#architects-own-projects), `null`/ABSENT when
   *  unassigned (or on a pre-#architects-own-projects binary). Set only by `bsc project architect
   *  set` -- there is no UI that writes it, by design. Drives which architect a project edges to on
   *  the Glance network. */
  architect?: string | null;
}

/** Shape-gate ONE raw list row into a {@link DbProject}, or `null` to drop it. `key` + `state` are the
 *  load-bearing identity/lifecycle fields (a row missing either is garbage); the rest are coerced with
 *  safe defaults so a partial payload can't crash the caller. */
function toDbProject(raw: unknown): DbProject | null {
  if (!raw || typeof raw !== "object") return null;
  const o = raw as Record<string, unknown>;
  if (typeof o.key !== "string" || !o.key) return null;
  if (typeof o.state !== "string" || !o.state) return null;
  return {
    key: o.key,
    title: typeof o.title === "string" ? o.title : "",
    pitch: typeof o.pitch === "string" ? o.pitch : "",
    blueprint: typeof o.blueprint === "string" ? o.blueprint : null,
    category: typeof o.category === "string" ? o.category : null,
    state: o.state,
    createdAt: typeof o.createdAt === "number" ? o.createdAt : 0,
    updatedAt: typeof o.updatedAt === "number" ? o.updatedAt : 0,
    // Absent on a pre-#4088 binary — `null` reads as "not triaged", which is the safe default: it
    // hides an unknown project from Glance rather than inventing a triage that never happened.
    triagedAt: typeof o.triagedAt === "number" ? o.triagedAt : null,
    // Absent on a pre-#architects-own-projects binary — `null` reads as "unassigned", which is the
    // honest default: an unknown owner is not an owner, and the graph's unassigned rule handles it.
    architect: typeof o.architect === "string" && o.architect ? o.architect : null,
  };
}

/**
 * Read every row via `bsc project db list --json`. Returns `null` on ANY failure — an unreachable
 * bridge, an old `bsc` without the verb, non-JSON output, or a payload that isn't an array — so a
 * degraded environment keeps rendering the persisted draft cache rather than blanking it. Each row is
 * shape-gated; unrecognizable rows are silently dropped.
 */
export async function listDbProjects(): Promise<DbProject[] | null> {
  try {
    const rows = await bscJson<unknown>(null, ["project", "db", "list", "--json"], null);
    if (!Array.isArray(rows)) return null;
    return rows.map(toDbProject).filter((r): r is DbProject => r !== null);
  } catch {
    return null;
  }
}

/**
 * Upsert a draft into the projects DB (`bsc project db add`, one JSON object on stdin). Idempotent by
 * key (an existing key is updated), fire-and-forget, and degrades silently when the bridge/binary is
 * absent — the caller has already written the store draft map, so this is the durable mirror.
 */
export async function addDbProject(p: {
  key: string;
  title: string;
  pitch?: string;
  blueprint?: string | null;
  category?: string | null;
  state?: string;
}): Promise<void> {
  await bscWrite(null, ["project", "db", "add"], p);
}

/** Remove a draft from the projects DB (`bsc project db remove <key>`). Fire-and-forget; degrades
 *  silently (the store draft map is cleared separately by the caller). */
export async function removeDbProject(key: string): Promise<void> {
  await bscRun(null, ["project", "db", "remove", key]);
}

/** Advance a DB row's lifecycle state (`bsc project db state <key> <state>`). Fire-and-forget;
 *  degrades silently. (Provided for completeness; the Phase-1 draft flow uses add/remove.) */
export async function setDbProjectState(key: string, state: string): Promise<void> {
  await bscRun(null, ["project", "db", "state", key, state]);
}

/** Stamp a project TRIAGED in the durable store (#4088) — `bsc project triaged set`. Idempotent: an
 *  already-triaged project keeps its first timestamp. Fire-and-forget; degrades silently when the
 *  bridge or an older binary can't serve it, exactly like the other writers here. */
export async function setDbTriaged(key: string): Promise<void> {
  if (!key) return;
  try {
    await bscRun(null, ["project", "triaged", "set", key]);
  } catch {
    /* bridge unreachable — the in-memory marker still gates this session */
  }
}

// Pure facet / filter / sort logic for the Projects page (#3802) — the Projects-tab twin of the
// Skills library's `lib/skillsFilter.ts`. It folds the FOUR project sources (GitHub boards, local
// published hubs, in-progress drafts, bare drafts) into ONE unified `ProjectItem` list, then filters
// (search + a Status facet + an application-architecture Type facet) and sorts it. Free of React /
// Tauri so it's unit-testable in isolation; the composer (`ProjectsList`) owns the state + the
// open/delete handlers and the surrounding chrome.

import { projStatus, projectProgress, type GhProject } from "@/features/planner/list/published/publishedModel";
import { projectSlug } from "@/shared/lib/core/projectPaths";
import type { DraftRow } from "@/features/planner/list/drafts";
import type { LocalPublishedRow } from "@/features/planner/list/localPublished";
import type { ChipTone } from "@/shared/ui/data/Chip";
import { type AppType, APP_TYPES, type ClassifyConfig } from "@/features/planner/lib/classifyConfig";
import { serviceMode, type DeployConfig, type DeployService } from "@/features/planner/lib/deployServices";

/** The lifecycle bucket a project lands in — the Status facet's four values (#3802). */
export type ProjectStatus = "active" | "shipped" | "in-progress" | "draft";

/** Which of the four sources a card came from — drives its open action + card affordances. */
export type ProjectSource = "board" | "local" | "draft";

/** Re-export the application-architecture type axis (#3802) so callers reach it via this module. */
export type { AppType } from "@/features/planner/lib/classifyConfig";

/** A presentation-ready project row, unified across all four sources. Carries the raw source ref
 *  (`gh` / `draft`) so the composer routes the correct open/delete handler without re-deriving it. */
export interface ProjectItem {
  /** Stable React key (gh node id, or `local:<key>` / `draft:<key>`). */
  id: string;
  /** The name-derived slug key (#2409) — the project's on-disk identity. */
  key: string;
  title: string;
  description: string;
  status: ProjectStatus;
  /** The project's APPLICATION ARCHITECTURE (#3802) — the Type facet axis. */
  appType: AppType;
  source: ProjectSource;
  /** GitHub project #number (boards only). */
  number?: number;
  /** Short repo names (boards only). */
  repos: string[];
  itemsTotal: number;
  open: number;
  /** Progress fraction 0..1 (closed / total items; boards only). */
  pct: number;
  running: number;
  paused: number;
  /** Recency key (epoch ms). */
  updatedAt: number;
  /** The raw board project (source "board") — for the reopen / board / delete handlers. */
  gh?: GhProject;
  /** The raw draft row (source "draft") — for reopen / delete-draft. */
  draft?: DraftRow;
}

export type SortKey = "recency" | "name";
export const SORTS: { value: SortKey; label: string }[] = [
  { value: "recency", label: "Recently updated" },
  { value: "name", label: "Name (A–Z)" },
];

/** Card / list density. */
export type Density = "cards" | "list";

/** The Status facet's option set — value, label, dot colour, and the Chip tone the card uses. */
export interface StatusFacet {
  value: ProjectStatus;
  label: string;
  dot: string;
  tone: ChipTone;
}
export const STATUS_FACETS: StatusFacet[] = [
  { value: "active",      label: "active",      dot: "var(--success)", tone: "success" },
  { value: "shipped",     label: "shipped",     dot: "var(--fg-dim)",  tone: "neutral" },
  { value: "in-progress", label: "in progress", dot: "var(--violet)",  tone: "info" },
  { value: "draft",       label: "draft",       dot: "var(--accent)",  tone: "accent" },
];

/** Status → display meta, indexed for O(1) lookup in the card. */
export const STATUS_META: Record<ProjectStatus, StatusFacet> =
  Object.fromEntries(STATUS_FACETS.map((f) => [f.value, f])) as Record<ProjectStatus, StatusFacet>;

/** The Type (application-architecture) facet — label + accent colour per {@link AppType} (#3802). */
export interface TypeFacet { value: AppType; label: string; color: string }
export const TYPE_FACETS: TypeFacet[] = [
  { value: "application", label: "application", color: "var(--accent)" },
  { value: "api",         label: "api",         color: "var(--success)" },
  { value: "serverless",  label: "serverless",  color: "var(--danger)" },
  { value: "static",      label: "static site", color: "color-mix(in oklch, var(--info), var(--success))" },
  { value: "desktop",     label: "desktop app", color: "var(--violet)" },
  { value: "mobile",      label: "mobile app",  color: "var(--info)" },
  { value: "cli",         label: "cli",         color: "color-mix(in oklch, var(--accent), var(--violet))" },
  { value: "library",     label: "library",     color: "var(--fg-dim)" },
];
export const TYPE_META: Record<AppType, TypeFacet> =
  Object.fromEntries(TYPE_FACETS.map((f) => [f.value, f])) as Record<AppType, TypeFacet>;

/** Map ONE deploy service's mode/workload/localKind onto an application-architecture {@link AppType}. */
function appTypeOfService(s: DeployService): AppType {
  if (serviceMode(s) === "local") {
    if (s.localKind === "library") return "library";
    // A local build-and-run app: a desktop installer, else a generic local application / CLI.
    return /desktop|installer/i.test(s.buildTargets ?? "") ? "desktop" : "application";
  }
  switch (s.workload) {
    case "static": return "static";
    case "serverless": return "serverless";
    case "service":
    case "container": return "api";
    default: return "application";
  }
}

/** Derive a project's architecture from its deploy config (the first service), or undefined if none. */
export function appTypeFromDeploy(deploy: DeployConfig | undefined): AppType | undefined {
  const first = deploy?.services?.[0];
  return first ? appTypeOfService(first) : undefined;
}

/** Resolve a project's application architecture (#3802): the explicit classification wins (the
 *  planner sets it at discovery via `bsc plan classify`), else it's derived from the deploy plan,
 *  else the neutral default "application". Pure + exported for direct testing. */
export function resolveAppType(classification: ClassifyConfig | undefined, deploy: DeployConfig | undefined): AppType {
  return classification?.appType ?? appTypeFromDeploy(deploy) ?? "application";
}

export interface BuildProjectItemsArgs {
  /** The visible GitHub boards (`visibleProjects`) — the live/persisted board rows. */
  boards: GhProject[];
  /** Local published hubs NOT covered by a board (`buildLocalPublished`) — the offline published set. */
  localPublished: LocalPublishedRow[];
  /** Every draft row (on-disk hubs ∪ store draft map ∪ DB drafts) — split by `dbStateByKey`. */
  drafts: DraftRow[];
  /** key → durable lifecycle state (`created`/`planning` ⇒ in-progress, else a bare draft). */
  dbStateByKey: Record<string, string>;
  /** Live fleet counts per board node id. */
  fleetByProject: Record<string, { running: number; paused: number }>;
  /** plan key → the project's classification blob (`planClassification`) — carries `appType` (#3802). */
  classificationByKey?: Record<string, ClassifyConfig>;
  /** plan key → the project's deploy plan (`planDeployConfig`) — the architecture fallback. */
  deployByKey?: Record<string, DeployConfig>;
}

/** Fold the four project sources into one unified, presentation-ready list. Pure. */
export function buildProjectItems(a: BuildProjectItemsArgs): ProjectItem[] {
  const items: ProjectItem[] = [];
  const classBy = a.classificationByKey ?? {};
  const deployBy = a.deployByKey ?? {};
  const typeOf = (planKey: string): AppType => resolveAppType(classBy[planKey], deployBy[planKey]);

  for (const p of a.boards) {
    const { open, pct } = projectProgress(p);
    const fleet = a.fleetByProject[p.id] ?? { running: 0, paused: 0 };
    items.push({
      id: p.id,
      key: p.id,
      title: p.title,
      description: p.shortDescription ?? "",
      status: projStatus(p),
      appType: typeOf(projectSlug(p.title)),
      source: "board",
      number: p.number,
      repos: (p.repositories?.nodes ?? []).map((r) => r.nameWithOwner.split("/")[1] ?? r.nameWithOwner),
      itemsTotal: p.items?.totalCount ?? 0,
      open,
      pct,
      running: fleet.running,
      paused: fleet.paused,
      updatedAt: new Date(p.updatedAt).getTime(),
      gh: p,
    });
  }

  for (const lp of a.localPublished) {
    items.push({
      id: "local:" + lp.key,
      key: lp.key,
      title: lp.title,
      description: "",
      // A published hub without board data is presumed active (the offline published set, #2445).
      status: "active",
      appType: typeOf(lp.key),
      source: "local",
      repos: [],
      itemsTotal: 0,
      open: 0,
      pct: 0,
      running: 0,
      paused: 0,
      updatedAt: lp.updatedAt,
    });
  }

  for (const d of a.drafts) {
    const st = a.dbStateByKey[d.key];
    const inProgress = st === "created" || st === "planning";
    items.push({
      id: "draft:" + d.key,
      key: d.key,
      title: d.title,
      description: d.pitch,
      status: inProgress ? "in-progress" : "draft",
      appType: typeOf(d.key),
      source: "draft",
      repos: [],
      itemsTotal: 0,
      open: 0,
      pct: 0,
      running: 0,
      paused: 0,
      updatedAt: d.sort,
      draft: d,
    });
  }

  return items;
}

/** Live per-status counts over the unified list — the rail facet badges. */
export function statusCounts(items: ProjectItem[]): Record<ProjectStatus, number> {
  const c: Record<ProjectStatus, number> = { active: 0, shipped: 0, "in-progress": 0, draft: 0 };
  for (const i of items) c[i.status]++;
  return c;
}

/** Live per-type (application-architecture) counts — the rail's Type facet badges (#3802). */
export function typeCounts(items: ProjectItem[]): Record<AppType, number> {
  const c = Object.fromEntries(APP_TYPES.map((k) => [k, 0])) as Record<AppType, number>;
  for (const i of items) c[i.appType]++;
  return c;
}

export interface FilterProjectsArgs {
  query: string;
  /** Selected status facet values; empty ⇒ all statuses. */
  statusSel: Set<ProjectStatus>;
  /** Selected type (application-architecture) facet values; empty ⇒ all types. */
  typeSel?: Set<AppType>;
  sort: SortKey;
}

/** Apply the Status + Type facets (OR within a facet, AND across facets), the free-text query
 *  (title · description · key · repos), then sort. Returns a fresh array; `items` is never mutated. */
export function filterProjects(items: ProjectItem[], { query, statusSel, typeSel, sort }: FilterProjectsArgs): ProjectItem[] {
  const q = query.trim().toLowerCase();
  let pool = items;
  if (statusSel.size) pool = pool.filter((i) => statusSel.has(i.status));
  if (typeSel && typeSel.size) pool = pool.filter((i) => typeSel.has(i.appType));
  if (q) pool = pool.filter((i) => (i.title + " " + i.description + " " + i.key + " " + i.repos.join(" ")).toLowerCase().includes(q));
  return [...pool].sort((a, b) =>
    sort === "name" ? a.title.toLowerCase().localeCompare(b.title.toLowerCase()) : b.updatedAt - a.updatedAt,
  );
}

// Pure parsing + derivation for the Portfolio summary (ProjectsSummary.tsx).
// React-free so it can be unit-tested directly; the components consume the shapes
// returned here. Everything derives from the Projects-v2 GraphQL data — the per-repo
// issue/milestone/event derivations were dropped with their cards (#3675).

// ── Types ─────────────────────────────────────────────────────────────────────

/** A viewer Projects V2 node, as returned by PROJECTS_SUMMARY_QUERY. */
export interface GhProject {
  id: string;
  number: number;
  title: string;
  shortDescription: string | null;
  closed: boolean;
  updatedAt: string;
  items: { totalCount: number };
  repositories: { nodes: Array<{ nameWithOwner: string }> };
}

// ── Palette ───────────────────────────────────────────────────────────────────

export const PROJECT_COLORS = [
  "oklch(0.78 0.14 70)",
  "oklch(0.7 0.10 220)",
  "oklch(0.7 0.12 145)",
  "oklch(0.6 0.06 50)",
  "oklch(0.7 0.12 290)",
  "oklch(0.45 0 0)",
];

// ── Project allocation ────────────────────────────────────────────────────────

export interface AllocationItem { n: string; pct: number; c: string }

/** Share of in-progress work (by item count) across active projects. */
export function computeAllocation(projects: GhProject[]): AllocationItem[] {
  const active = projects.filter(p => !p.closed && p.items.totalCount > 0);
  const total = active.reduce((s, p) => s + p.items.totalCount, 0);
  return active.map((p, i) => ({
    n: p.title,
    pct: total > 0 ? Math.round(p.items.totalCount / total * 100) : 0,
    c: PROJECT_COLORS[i % PROJECT_COLORS.length],
  }));
}

// ── Projects grid stats ───────────────────────────────────────────────────────

export type ProjectStatus = "shipped" | "drafting" | "active";

export interface ProjectStat {
  p: GhProject;
  c: string;
  status: ProjectStatus;
  repo: string;
}

/** Per-project card stats: color, status, lead repo — all from the project data (#3675). */
export function computeProjectStats(projects: GhProject[]): ProjectStat[] {
  return projects.map((p, i) => {
    const c = PROJECT_COLORS[i % PROJECT_COLORS.length];
    const status: ProjectStatus = p.closed ? "shipped" : p.items.totalCount === 0 ? "drafting" : "active";
    const repo = p.repositories.nodes[0]?.nameWithOwner ?? "(no repo)";
    return { p, c, status, repo };
  });
}

/** Distinct repo count linked across all projects (header stat). */
export function countLinkedRepos(projects: GhProject[]): number {
  return new Set(projects.flatMap(p => p.repositories.nodes.map(r => r.nameWithOwner))).size;
}

// GraphQL queries backing the Portfolio summary (ProjectsSummary.tsx). Kept as TS
// string constants so the data hook can pass them straight to `githubGraphql`.

/** Viewer's Projects V2 with item counts + linked repos — the portfolio overview. */
export const PROJECTS_SUMMARY_QUERY = `{
  viewer {
    projectsV2(first: 20) {
      nodes {
        id number title shortDescription closed updatedAt
        items { totalCount }
        repositories(first: 5) { nodes { nameWithOwner } }
      }
    }
  }
}`;

