      // entry already under `newKey` is kept and the old one dropped (never clobbered). Console
      // tab/pane state is deliberately NOT rewritten (pane ids embed the key; a relinked project
      // relaunches its fleet, which rebuilds tabs under the new key).
      rekeyProjectData: (oldKey, newKey) =>
        set((s) => {
          if (!oldKey || !newKey || oldKey === newKey) return {};
          // Every per-project + repo-scoped map to move is registered in projectScopedMaps.ts
          // (#2712) — `rekeyProjectScoped` moves `oldKey` → `newKey` (target-wins) across exactly
          // the maps in the `"rekey"` op set, guarding `?? {}` per persisted slice (#874).
          // Extension/skill scope lists: swap the key in place (dedup if both forms were present).
          const scoped = <E extends { projects?: string[] }>(list: E[]): E[] =>
            (list ?? []).map((e) => ({
              ...e,
              projects: [...new Set((e.projects ?? []).map((p) => (p === oldKey ? newKey : p)))],
            }));
          return {
            ...rekeyProjectScoped(s, oldKey, newKey),
            mcpServers:             scoped(s.mcpServers),
            hooks:                  scoped(s.hooks),
            skills:                 scoped(s.skills),
          };
        }),
      issueLinks: {},
      setIssueLinks: (projectKey, links) =>
        set((s) => ({ issueLinks: setMapEntry(s.issueLinks, projectKey, { ...(s.issueLinks[projectKey] ?? {}), ...links }) })),
      bscBaseDir: "",
      setBscBaseDir: (dir) => set({ bscBaseDir: dir }),
      projectLocalRepos: {},
      localDraftProjects: {},
      addProjectRepo: (projectId, fullName) =>
        set((s) => {
          const existing = s.projectLocalRepos[projectId] ?? [];
          if (existing.includes(fullName)) return {};
          return { projectLocalRepos: setMapEntry(s.projectLocalRepos, projectId, [...existing, fullName]) };
        }),
      // Tab identity keys off the ONE name-derived project key (#2409) — the node-id branch of the
      // old canonicalProjectKey is gone (recovery/reuse is derivation, not lookup).
      findTriageTabIdx: (projectName) =>
        findProjectTabIdx(get().tabs, sanitizeProjectKey(projectName), "triage"),
      // #1004: prepare a triage re-run from plan.db — for each repo read the last-run marker and the
      // issues changed since it, render a one-line resume lead (renderTriageDelta), then STAMP a fresh
      // marker so the next run's "since" is now (read-before-write order). Returns fullName → lead for
      // triageStartProject's `deltas`. Failures are per-repo and non-fatal (omitted ⇒ full prompt).
      prepareTriageRun: async (projectKey, repos) => {
        const deltas: Record<string, string> = {};
        await Promise.all(repos.map(async (repo) => {
          try {
            const lastRun = await bscJson<number | null>(projectKey, ["plan", "triage", "last", repo], null);
            const changed = lastRun != null
              ? await bscJson<PlanIssue[]>(projectKey, ["plan", "triage", "changed", repo, "--since", String(lastRun)], [])
              : [];
            deltas[repo] = renderTriageDelta(
              changed.map((c) => ({ ref: c.ref, title: c.title, status: c.status ?? "open" })),
              lastRun ?? null,
            );
            await bscJson<number>(projectKey, ["plan", "triage", "record", repo], 0);
          } catch (e) {
            console.error(`triage delta prep ${repo} failed:`, e);
          }
        }));
        // #2097 — route the design files that CHANGED since the last route as part of triage. Read
        // the project's design manifest, diff content hashes, and if any changed: sync the skeleton,
        // prepend the route lead to the first repo's triage prompt (the routePrompt itself sends UI
        // assets to the owning repo), and stamp the routed hashes. Nothing changed ⇒ no-op (no
        // reroute, no prompt). Non-fatal.
        try {
          const files = await invoke<[string, string][]>("read_project_files", { projectKey, subdir: INTAKE_DIR });
          const manifest = files.find(([rel]) => rel === "intake.json")?.[1];
          const entries = manifest ? parseIntake(manifest) : [];
          const changed = changedDesignFiles(entries);
          if (changed.length > 0 && repos.length > 0) {
            const first = repos[0];
            deltas[first] = renderDesignDelta(changed, STAGE_DEFS.ui.routePrompt ?? "") + (deltas[first] ?? "");
            await invoke("sync_design_to_skeleton", { projectKey });
            await invoke("write_project_file", { projectKey, relpath: INTAKE_MANIFEST, contents: serializeIntake(markRouted(entries)) });
          }
        } catch (e) {
          console.error("triage design-route prep failed:", e);
        }
        return deltas;
      },
      triageStartProject: (projectName, repos, projectId = "", deltas, clonePaths) =>
        set((s) => {
          // A triage tab for this project may already exist (re-run): rebuild it in
          // place at the same index. The caller kills the old panes' sessions first
          // and the bumped runId remounts them, so pty_create launches fresh
          // (resuming via --continue + the checkpoint) instead of reconnecting.
          // Match on the STABLE projectKey (the name-derived key, #2409 — never the node
          // id), so a project rename relabels the tab in place instead of forking a
          // duplicate (#457).
          const tabName = `${projectName} · triage`;
          const tabKey = sanitizeProjectKey(projectName);
          const existingIdx = findProjectTabIdx(s.tabs, tabKey, "triage");
          if (repos.length === 0) return {};
          const newTabIdx = existingIdx >= 0 ? existingIdx : s.tabs.length;
          const runId = existingIdx >= 0 ? (s.tabs[existingIdx].runId ?? 0) + 1 : 0;
          const addedAutos = activateAutomations(s, projectId, tabName);
          const count = Math.min(repos.length, 16);
          const { cols, rows } = gridLayout(count);
          const layout = `${cols}×${rows}`;
          const newPaneCwds     = { ...s.paneCwds };
          const newPaneInitCmds = { ...s.paneInitCmds };
          const newPaneStartupPromptDocs = { ...s.paneStartupPromptDocs };
          const newPaneStartupPromptText = { ...s.paneStartupPromptText };
          const newPaneCheckpointDocs    = { ...s.paneCheckpointDocs };
          const newPaneContinue          = { ...s.paneContinue };
          const newPaneMcpServers        = { ...s.paneMcpServers };
          const newPaneHooks             = { ...s.paneHooks };
          const newPaneSkills            = { ...s.paneSkills };
          const newPaneRoles             = { ...s.paneRoles };
          const newPaneRepos             = { ...s.paneRepos };
          const triageMcp                = resolveMcpServers(s.mcpServers, projectId);
          const triageHooks              = resolveHooks(s.hooks, projectId);
          // Checkpoint docs live beside the repo clones, under the project-name
          // key (always present; projectId defaults to "" for ad-hoc triage).
          const projKey = sanitizeProjectKey(projectName);
          const newDisabledPanes = { ...s.disabledPanes };
          const tabPaneNames: Record<number, string> = {};
          const paneIds: string[] = [];
          const paneCount = cols * rows;
          const assignments = buildAssignments(s);
          for (let i = 0; i < paneCount; i++) {
            // Stable pane identity (#1176): each triage pane is `<projKey>:<repo>:triage`, so a
            // re-run resumes the exact repo's session; an empty cell keeps a positional id.
            const key = i >= count ? positionalPaneId(newTabIdx, i) : triagePaneId(projKey, repos[i] ?? `p${i}`);
            paneIds[i] = key;
            if (i < count) {
              const fullName = repos[i];
              // A real repo — launch claude in its clone, ensure it's enabled. Prefer the
              // Rust-resolved absolute clone dir (#1819, `repo_dir_path`) so the launch never
              // depends on the async-loaded `bscBaseDir` mirror — empty at crash-recovery startup,
              // which yielded an empty cwd → the settings.json writer skipped → permission-less
              // session. Falls back to the `bscBaseDir`-derived path when an entry is absent.
              newPaneCwds[key]     = clonePaths?.[fullName ?? ""] || projectRepoCwd(s.bscBaseDir, projectName, fullName, !!s.activeProjectId);
              newPaneInitCmds[key] = "claude";
              tabPaneNames[i]      = fullName?.split("/")[1] ?? `pane-${i + 1}`;
              // The startup prompt is baked into the claude launch by the backend
              // (reliable). A per-repo triage script (planner-authored,
              // auto-assigned) wins as a document; otherwise the verbatim shared
              // TRIAGE_PROMPT text (which TerminalView prefers over the dev doc
              // chain), with a doc-based fallback (repo→project→global→built-in;
              // "" = built-in default) for if the text is later cleared.
              const triageDoc = s.repoTriagePromptDoc[repoPromptKey(projectId, fullName ?? "")];
              if (triageDoc) {
                newPaneStartupPromptDocs[key] = triageDoc;
              } else {
                // Secure default (#738): triage only bsc-authored issues unless the user opts out.
                // #1004: lead with this repo's since-last-run delta (if prepareTriageRun supplied one)
                // so a re-run resumes from what changed rather than re-ingesting the whole project.
                // #3281 local-first: triage the plan.db items via `bsc plan`, not `gh issue list`.
                //
                // The trigger used to be `!s.githubToken` alone, which read a token's EXISTENCE as
                // consent to write to GitHub — so any project with a token got the `gh` variant and
                // its triage session ran `gh issue edit --add-label` / `gh label create`, creating
                // GitHub state on a project that integrates locally. A token is what lets us READ
                // GitHub; the project's STRATEGY is what says whether we write to it.
                //
                // So local now means either: no token at all, or a strategy that never reaches a
                // remote. Fail-closed on the strategy — an unset one resolves to the default, which
                // is `local`.
                const triageStrategy = resolveStrategy(undefined, s.planFleet[projKey]?.strategy);
                const triageLocal = !s.githubToken || triageStrategy === "local";
                newPaneStartupPromptText[key] = buildTriagePrompt(s.restrictToBscIssues, deltas?.[fullName ?? ""], triageLocal);
                // Resolution moved to the assignments module (#324/#326): startup
                // prompt is the override cascade; reference context accumulates.
                const doc = resolveStartupPrompt(assignments, { projectId, repo: fullName ?? "" });
                newPaneStartupPromptDocs[key] = doc ?? "";
              }
              // Triage resumes the repo's prior conversation (claude --continue)
              // so each pass builds on the last instead of starting cold.
              newPaneContinue[key] = true;
              // Per-repo checkpoint doc: the session writes "where we left off" to
              // it via bsc-checkpoint; the next triage launch composes it onto the
              // prompt. Stable per (project, repo) so successive passes accumulate.
              newPaneCheckpointDocs[key] = checkpointDocRelpath(projKey, fullName ?? "");
              newPaneMcpServers[key] = triageMcp;
              newPaneHooks[key] = triageHooks;
              // Per-session skills (#1056): the project-resolved set, layered with this session's
              // override + any task groups toggled onto it (#skills-groups), keyed by the stable
              // triage identity id.
              newPaneSkills[key] = effectiveSessionSkills(
                s.skills, projectId, s.sessionSkillOverrides[key],
                new Set(expandGroups(s.sessionSkillGroups[key] ?? [], s.skillGroups)),
              );
              newPaneRoles[key] = "triage";
              // Bind the triage pane to its repo so its session GH_TOKEN is scoped to it
              // (#158); a repo with an assigned credential triages with that token only.
              if (fullName) newPaneRepos[key] = fullName;
              delete newDisabledPanes[key];
            } else {
              // Empty grid cell (more cells than repos) — start it disabled so it
              // doesn't spawn an idle shell or add rendering load.
              newDisabledPanes[key] = true;
              delete newPaneRepos[key];
            }
          }
          const newTab: Tab = { id: newTabId(), name: tabName, layout, state: "idle", runId, projectKey: tabKey, kind: "triage", seq: 0, paneIds };
          return {
            tabs: existingIdx >= 0
              ? s.tabs.map((t, i) => (i === existingIdx ? newTab : t))
              : [...s.tabs, newTab],
            activeTabIdx: newTabIdx,
            focusedPaneIdx: -1,
            fullscreenPaneIdx: -1,
            paneMenuOpenIdx: -1,
            paneCwds:     newPaneCwds,
            paneInitCmds: newPaneInitCmds,
            paneStartupPromptDocs: newPaneStartupPromptDocs,
            paneStartupPromptText: newPaneStartupPromptText,
            paneCheckpointDocs: newPaneCheckpointDocs,
            paneContinue: newPaneContinue,
            paneMcpServers: newPaneMcpServers,
            paneHooks: newPaneHooks,
            paneSkills: newPaneSkills,
            paneRoles: newPaneRoles,
            paneRepos: newPaneRepos,
            disabledPanes: newDisabledPanes,
            // Bumped runId remounts this tab's panes; clear their old statuses so a
            // prior pass's "run"/"on" doesn't stick on the fresh sessions (#435). Clear by
            // the (reused) tab's identity so its minted triage ids drop too (#1176).
            paneStatus: clearTabStatusesPure(s.paneStatus, existingIdx >= 0 ? s.tabs[existingIdx] : newTab, newTabIdx),
            paneNames: setMapEntry(s.paneNames, newTabIdx, tabPaneNames),
            automations: [...s.automations, ...addedAutos],
            activeWorkspace: "console" as Workspace,
            // TRIAGED (#2541): launching triage marks the project WORKING → it now appears on Glance.
            ...(projectId || tabKey ? { triagedProjects: { ...s.triagedProjects, [projectId || tabKey]: s.triagedProjects[projectId || tabKey] ?? Date.now() } } : {}),
          };
        }),

      findFleetTabIdx: (projectKey) =>
        findProjectTabIdx(get().tabs, sanitizeProjectKey(projectKey), "build", 0),
      fleetStartProject: (projectName, fleet, projectKey, paths) => {
        // Roster rows (paneId/stream/repo/branch/role) collected during the build below and
        // written to the project hub as fleet.roster.tsv so the director's `bsc-fleet` helper
        // can enumerate the fleet + each worker's state (#734).
        const rosterRows: string[] = [];
        set((s) => {
          // The fleet launches into "· build" tabs (plus "· build 2", "· build 3"…
          // when it overflows a tab). A tab holds up to 16 panes (the 4×4 layout
          // limit); there is no fleet-wide cap, so larger fleets spill into more tabs.
          // Each (re-)launch rebuilds its tab(s) in place with a bumped runId (the
          // caller kills the old panes first), like triageStartProject.
          const baseTabName = `${projectName} · build`;
          const hasDirector = fleet.director.enabled;

          // The commons + integration LANES (#851, retasked by #funnel-commons-and-integration-streams):
          // derive the repo-root commons set from the project's stack (`stack.md`), then (a) strip
          // those paths from every feature stream's `owns` so no worker owns `.gitignore`/
          // `package.json`/CI config, (b) gate every feature stream on its repo's commons lane so the
          // commons land first (Phase 0), and (c) materialize the commons + integration lanes as real
          // streams with real worktrees.
          //
          // NOT conditioned on a director any more. It was, because the DIRECTOR used to own the
          // commons and a director-less fleet therefore had no steward; the owner is now a worker, so
          // the commons exist — and have an owner — whether or not this fleet runs a director.
          const commonsGlobs = commonsGlobsForStack(stackTagsFromSection(s.planStages[projectKey]?.stack ?? ""));
          const plan = commonsGlobs.length ? applyCommonsGate(fleet, commonsGlobs) : fleet;
          // #1854 Phase b: the seeding blueprint's fleet POLICY — the DEFAULT per-stream profile +
          // flow this project type declares. Resolved from the project's blueprint (keyed like
          // planStages, above); absent policy ⇒ today's launch defaults apply byte-for-byte. A
          // stream's own profile/flow still wins over the policy (see the resolvers below).
          const fleetPolicy = s.blueprints.find(
            (b) => b.id === (s.projectBlueprintId[projectKey] ?? DEFAULT_BLUEPRINT_ID),
          )?.fleetPolicy;
          const newPaneDirectorDrive     = { ...s.paneDirectorDrive };
          const newPaneDirectorMode      = { ...s.paneDirectorMode };
          const newPaneStream            = { ...s.paneStream };

          // Independents first so the launched wave is what can run now.
          // ALL intended workers are launched across however many build tabs are needed
          // (#479 — no silent drop past the recommended count; recommended is advisory).
          const ordered = [...plan.streams].sort(
            (a, b) => (a.dependsOn.length ? 1 : 0) - (b.dependsOn.length ? 1 : 0),
          );
          const workers = ordered;

          // Flat session list, chunked into tabs of ≤16. `null` marks the director slot.
          const sessions: (AgentStream | null)[] = [...(hasDirector ? [null] : []), ...workers];
          if (sessions.length === 0) return {};

          const CAP = 16;
          const numTabs = Math.ceil(sessions.length / CAP);

          const newPaneCwds              = { ...s.paneCwds };
          const newPaneInitCmds          = { ...s.paneInitCmds };
          const newPaneStartupPromptDocs = { ...s.paneStartupPromptDocs };
          const newPaneStartupPromptText = { ...s.paneStartupPromptText };
          const newPaneContinue          = { ...s.paneContinue };
          const newPaneCheckpointDocs    = { ...s.paneCheckpointDocs };
          const newPaneMcpServers        = { ...s.paneMcpServers };
          const newPaneHooks             = { ...s.paneHooks };
          const newPaneSkills            = { ...s.paneSkills };
          const newDisabledPanes         = { ...s.disabledPanes };
          const newPaneNames             = { ...s.paneNames };
          const newPaneRoles             = { ...s.paneRoles };
          const newPaneProfiles             = { ...s.paneProfiles };
          // Unified role→profile model: every session gets its ROLE's default profile (director →
          // Read-only review, worker → Autonomous trusted), resolved from {@link roleProfileId}. No
          // per-stream profile generation — a stream may still pin an explicit `profile` id.
          const newPaneProviders            = { ...s.paneProviders };
          const newPaneWslDistro            = { ...s.paneWslDistro };
          const newFleetPaneStreams      = { ...s.fleetPaneStreams };
          const newPaneRoleGlobs            = { ...s.paneRoleGlobs };
          const newPaneRepos                = { ...s.paneRepos };
          const newPaneFlows                = { ...s.paneFlows };
          const newPaneModels               = { ...s.paneModels };
          let   newPaneStatus               = { ...s.paneStatus };

          const safeKey = sanitizeProjectKey(projectKey);
          // MCP exposure is role-aware (#1054): the director sees every installed server (it
          // coordinates the whole fleet), while each worker gets the global servers plus only the
          // servers its stream was assigned. Hooks/skills still share the project scope.
          // Which harness the fleet runs on (#1078 P5): "claude" (default) or "bsc-agent" (any LLM).
          // A local/ollama provider forces bsc-agent (Claude Code can't drive it), so selecting
          // Ollama runs the workers + director on Ollama without the separate harness toggle.
          const fleetHarness = effectiveHarness(s.llmProvider, s.fleetHarness ?? "claude");
          const fleetAllMcp = resolveAllInstalledMcp(s.mcpServers);
          const fleetHooks = resolveHooks(s.hooks, projectKey);

          let tabs = s.tabs;
          let firstTabIdx = -1;

          for (let t = 0; t < numTabs; t++) {
            const chunk = sessions.slice(t * CAP, t * CAP + CAP);
            const tabName = t === 0 ? baseTabName : `${baseTabName} ${t + 1}`;
            // Match on the STABLE (projectKey, kind, seq), not the derived name, so a
            // project rename relabels the build tab(s) in place instead of forking a
            // duplicate "· build" tab with its own director — the "two directors" bug (#457).
            const existingIdx = findProjectTabIdx(tabs, safeKey, "build", t);
            const tabIdx = existingIdx >= 0 ? existingIdx : tabs.length;
            if (firstTabIdx < 0) firstTabIdx = tabIdx;
            const runId = existingIdx >= 0 ? (tabs[existingIdx].runId ?? 0) + 1 : 0;
            // Reused tab → bumped runId remounts its panes; clear their old statuses so
            // a prior run's "run"/"on" doesn't persist on the fresh sessions (#435). Clear
            // by the existing tab's identity so its minted director/worker ids drop (#1176) —
            // the per-cell delete below only covers the NEW layout's ids.
            const reusedTab = existingIdx >= 0 ? tabs[existingIdx] : undefined;
            if (reusedTab) newPaneStatus = clearTabStatusesPure(newPaneStatus, reusedTab, tabIdx);
            // Resume only on re-run. Each worker has its OWN worktree (a distinct
            // cwd), so `claude --continue` is unambiguous even for several agents in
            // one repo — the old shared-cwd hazard is gone.
            const resume = existingIdx >= 0;
            const count = chunk.length;
            const { cols, rows } = gridLayout(count);
            const layout = `${cols}×${rows}`;
            const paneCount = cols * rows;
            const tabPaneNames: Record<number, string> = {};
            const paneIds: string[] = [];

            for (let i = 0; i < paneCount; i++) {
              // Stable pane identity (#1176): director / worker get a project-scoped id so state +
              // recovery bind to the exact session, not the grid slot; an empty cell keeps a
              // positional id.
              const sess0 = i < count ? chunk[i] : undefined;
              const key = sess0 === undefined ? positionalPaneId(tabIdx, i)
                : sess0 === null ? directorPaneId(safeKey) : fleetPaneId(safeKey, sess0.id);
              paneIds[i] = key;
              // Clear any stale wiring (and status) from a prior run of this session.
              delete newPaneStatus[key];
              delete newPaneStartupPromptText[key];
              delete newPaneStartupPromptDocs[key];
              delete newPaneCheckpointDocs[key];
              delete newPaneMcpServers[key];
              delete newPaneHooks[key];
              delete newPaneRoles[key];
              delete newPaneProviders[key];
              delete newPaneWslDistro[key];
              delete newPaneProfiles[key];
              delete newFleetPaneStreams[key];
              delete newPaneRoleGlobs[key];
              delete newPaneRepos[key];
              delete newPaneFlows[key];
              delete newPaneModels[key];
              delete newPaneDirectorDrive[key];
              delete newPaneDirectorMode[key];
              delete newPaneStream[key];
              if (i < count) {
                const sess = chunk[i];
                // #2094: a worker stream may launch AS a persona — resolve it (a live reference to the
                // shared library) so its role/prompt/skills/model drive this pane below. Unknown/unset
                // id ⇒ undefined ⇒ the historical plain-worker defaults.
                const persona = sess?.persona ? s.personas.find((p) => p.id === sess.persona) : undefined;
                if (sess === null) {
                  // Director session at the project root — sees every repo + worktree.
                  // Prefer the Rust-resolved absolute hub path (#905) so the launch never
                  // depends on the async-loaded `bscBaseDir` mirror (empty/malformed → user root).
                  newPaneCwds[key]     = paths?.hubPath || projectHubCwd(s.bscBaseDir, projectKey, !!s.activeProjectId);
                  newPaneInitCmds[key] = "claude";
                  newPaneStartupPromptDocs[key] = scriptDocRelpath(safeKey, "prompts/director-kickoff.md");
                  newPaneCheckpointDocs[key] = agentCheckpointDocRelpath(safeKey, "director");
                  tabPaneNames[i] = "director";
                  newPaneDirectorDrive[key] = resolveDirectorDrive(plan.director.drive);
                  newPaneDirectorMode[key] = strategySettings(resolveStrategy(undefined, plan.strategy)).director;
                  // NO commons carve-out for the director (#funnel-commons-and-integration-streams).
                  // It used to launch with the commons set as its scoped writeGlobs — the one place a
                  // `code: "none"` role could still write. The commons lane owns those globs now, so
                  // the director keeps the full `code: none` deny and ROUTES a commons change to that
                  // lane with `bsc-assign` instead of applying it. Leaving the carve-out here would
                  // give the commons two writers, which is the collision #851 exists to prevent.
                } else {
                  // A REPO-LESS stream is a team-derived hub role-actor (#3103: curator/documentor/…) —
                  // it runs PROJECT-WIDE at the hub (like the director), not in a per-repo worktree. A
                  // repo'd worker runs in its own git worktree on its own branch: prefer the absolute
                  // path ensure_worktree returned (#905) over the bscBaseDir-derived mirror, so an
                  // empty/malformed base dir can't drop the worker at user root.
                  newPaneCwds[key]     = sess.repo
                    ? (paths?.worktreePaths?.[sess.id] || agentWorktreeCwd(s.bscBaseDir, projectKey, sess.repo, sess.id))
                    : (paths?.hubPath || projectHubCwd(s.bscBaseDir, projectKey, !!s.activeProjectId));
                  newPaneInitCmds[key] = "claude";
                  if (sess.prompt) {
                    newPaneStartupPromptDocs[key] = scriptDocRelpath(safeKey, sess.prompt);
                  } else if (persona) {
                    // A persona stream gets its persona-identity kickoff (role-aware), not the
                    // worker-only buildStreamPrompt — so a reviewer/documentor stream isn't briefed
                    // as a code-writing worker (#2094).
                    newPaneStartupPromptText[key] = personaStreamPrompt(persona, sess, resolveStrategy(sess.strategy, plan.strategy));
                  } else {
                    newPaneStartupPromptText[key] = buildStreamPrompt(sess, resolveStrategy(sess.strategy, plan.strategy));
                  }
                  // Per-agent checkpoint doc (keyed by stream id) so each agent keeps
                  // its own "where we left off" note.
                  newPaneCheckpointDocs[key] = agentCheckpointDocRelpath(safeKey, sess.id);
                  newPaneStream[key] = { repo: sess.repo, branch: worktreeSlug(sess.id) };
                  tabPaneNames[i] = sess.name;
                  // Bridge pane id → stream so the coordinator can resolve which pane
                  // produces a contract/issue/file (#199 AC#7).
                  newFleetPaneStreams[key] = sess;
                }
                newPaneContinue[key] = resume;
                // Director (sess === null) sees every installed server; a worker gets the
                // fleet-wide baseline plus its stream's assigned servers (#1054).
                newPaneMcpServers[key] = sess === null ? fleetAllMcp : resolveStreamMcp(s.mcpServers, sess.mcp, projectKey);
                newPaneHooks[key] = fleetHooks;
                // Per-session skills (#1056): project-resolved set + this session's override + any
                // task groups toggled onto it (#skills-groups), keyed by the worker/director's
                // stable identity id. The stream's planner-assigned groups (#1338, `sess.groupIds`)
                // are unioned with the session's manually-toggled groups before expansion, so a
                // worker inherits the skill groups the planner picked for its stream.
                newPaneSkills[key] = effectiveSessionSkills(
                  s.skills, projectKey, s.sessionSkillOverrides[key],
                  // #2094: a persona's attached skills (direct skill ids) join the stream's resolved
                  // set alongside the expanded task-groups + session toggles.
                  new Set([
                    ...expandGroups([...(s.sessionSkillGroups[key] ?? []), ...(sess?.groupIds ?? [])], s.skillGroups),
                    ...(persona?.skills ?? []),
                  ]),
                );
                // #2094: a persona stream launches AS its persona's role (documentor/reviewer/…),
                // overriding the default worker; no persona ⇒ the historical worker/director.
                newPaneRoles[key] = sess === null ? "director" : (persona?.role ?? "worker");
                newPaneProviders[key] = fleetHarness;
                // #1988: when the launch is sandboxed, this pane spawns INSIDE the sealed distro —
                // its cwd (from `paths`) is already distro-native; record the distro so pty_create
                // wraps the spawn in `wsl -d <distro>`. Only meaningful with the bsc-agent harness.
                if (paths?.wslDistro) newPaneWslDistro[key] = paths.wslDistro;
                // One roster row per live session (#734). Director has no repo/branch.
                rosterRows.push(sess === null
                  ? [key, "director", "-", "-", "director"].join("\t")
                  : [key, sess.id, sess.repo, worktreeSlug(sess.id), "worker"].join("\t"));
                // Bind the worker pane to its repo so its session GH_TOKEN is scoped to
                // it (#158). The director spans every repo, so it keeps the global token.
                if (sess && sess.repo) newPaneRepos[key] = sess.repo;
                // Bind the pane to its ROLE's default profile: director → Read-only review,
                // worker → Autonomous (trusted) — unless the stream pins an explicit profile. #1854
                // Phase b: a blueprint's fleetPolicy.profile seeds the WORKER default (never the
                // director, sess===null) between the stream's own pin and the role default.
                newPaneProfiles[key] = resolveStreamProfile(
                  sess?.profile,
                  sess === null ? undefined : fleetPolicy?.profile,
                  roleProfileId(newPaneRoles[key]),
                );
                // The worker's owned paths become its role write boundary so edits in
                // its lane auto-approve (dir/ -> dir/** so the subtree matches). #2094: only for a
                // code-WRITING role — a read-only persona stream (reviewer/juror/…) must NOT get a
                // write carve-out from its owns, or the read-only floor would leak.
                if (sess && sess.owns.length && roleCapability(newPaneRoles[key]).code === "write")
                  newPaneRoleGlobs[key] = sess.owns.map((g) => (g.endsWith("/") ? g + "**" : g));
                // #1854 Phase b: the stream's own flow wins; else the blueprint fleetPolicy.flow
                // default; else undefined so the launch path applies DEFAULT_FLOW downstream (only
                // workers carry a flow — the director, sess===null, never does).
                const effFlow = resolveStreamFlow(sess?.flow, fleetPolicy?.flow);
                if (sess && effFlow) newPaneFlows[key] = effFlow;
                // Per-agent model (#…) → the pane's `claude --model` at launch. Director (sess===null)
                // and unset workers fall back to the global `defaultModel` (resolved at pane mount).
                // #2094: the stream's own model wins; else its persona's model (validated as a tier).
                const streamModel = sess?.model ?? (persona?.model && (MODEL_IDS as readonly string[]).includes(persona.model) ? persona.model as ModelId : undefined);
                if (sess && streamModel) newPaneModels[key] = streamModel;
                delete newDisabledPanes[key];
              } else {
                // Empty grid cell — start disabled so it doesn't spawn an idle shell.
                newDisabledPanes[key] = true;
              }
            }

            const newTab: Tab = { id: newTabId(), name: tabName, layout, state: "idle", runId, projectKey: safeKey, kind: "build", seq: t, paneIds };
            tabs = existingIdx >= 0
              ? tabs.map((tb, i) => (i === existingIdx ? newTab : tb))
              : [...tabs, newTab];
            newPaneNames[tabIdx] = tabPaneNames;
          }

          const addedAutos = activateAutomations(s, s.activeProjectId ?? "", baseTabName);
          // #459: structure-aware auto-focus — set focusTarget based on fleet shape:
          // director present → only the director surfaces (workers run dark);
          // no director → all fleet panes queue (fall back to fleet-wide focus).
          const structureFocusTarget = hasDirector ? "director" : "fleet";
          return {
            tabs,
            activeTabIdx: firstTabIdx,
            focusTarget: structureFocusTarget,
            automations: [...s.automations, ...addedAutos],
            focusedPaneIdx: -1,
            fullscreenPaneIdx: -1,
            paneMenuOpenIdx: -1,
            paneCwds: newPaneCwds,
            paneInitCmds: newPaneInitCmds,
            paneStartupPromptDocs: newPaneStartupPromptDocs,
            paneStartupPromptText: newPaneStartupPromptText,
            paneContinue: newPaneContinue,
            paneCheckpointDocs: newPaneCheckpointDocs,
            paneMcpServers: newPaneMcpServers,
            paneHooks: newPaneHooks,
            paneSkills: newPaneSkills,
            paneRoles: newPaneRoles,
            paneProviders: newPaneProviders,
            paneWslDistro: newPaneWslDistro,
            paneProfiles: newPaneProfiles,

            fleetPaneStreams: newFleetPaneStreams,
            paneRoleGlobs: newPaneRoleGlobs,
            paneRepos: newPaneRepos,
            paneFlows: newPaneFlows,
            paneModels: newPaneModels,
            paneDirectorDrive: newPaneDirectorDrive,
            paneDirectorMode: newPaneDirectorMode,
            paneStream: newPaneStream,
            disabledPanes: newDisabledPanes,
            paneStatus: newPaneStatus,
            paneNames: newPaneNames,
            activeWorkspace: "console" as Workspace,
            // TRIAGED (#2541): launching the fleet marks the project WORKING → it now appears on Glance.
            ...(projectKey ? { triagedProjects: { ...s.triagedProjects, [projectKey]: s.triagedProjects[projectKey] ?? Date.now() } } : {}),
          };
        });
        // The caller persists these to the hub (publishFleetRoster) — the store stays
        // Tauri-free. Rows: paneId/stream/repo/branch/role, one per live session (#734).
        return rosterRows;
      },
});

// Kit-change propagation (#2277) — the pure decision spine. A kit is a shared dependency; changing a
// component is a *release*, and every app built on the kit is a consumer that may need to adopt it. This
// module owns the model + the fan-out logic ONLY (no storage, no delivery): classify a change, and turn
// { change × consumers } into a per-consumer dispatch plan. The consumer index (who uses the kit), the
// change origin (`bsc ui set` emitting a change), and the delivery (`bsc-assign` into the consumer's
// live director → the UI worker re-runs `bsc ui emit sync`, #2806) are follow-up slices that ride on
// this. The GitHub-issue rail was dropped (#2806): a dormant consumer holds until its fleet is live.
import type { ComponentRecord } from "@/features/designs/lib/model";

/** How much a change forces on consumers — drives whether it's a mandatory adopt or a heads-up. */
export type ChangeClass = "additive" | "breaking" | "fix";

/** One released change to a kit component — the signal fanned out to consumers. */
export interface KitChange {
  /** Deterministic fingerprint (the dedup key). */
  id: string;
  kitId: string;
  /** The changed component's name. */
  component: string;
  from?: string;
  to?: string;
  class: ChangeClass;
  summary: string;
  /** Migration note for a breaking change (shown in the issue/dispatch). */
  migration?: string;
}

/** A project that consumes a kit — one edge of the consumer index (the `kit_usage` graph, a later slice). */
export interface KitConsumer {
  projectKey: string;
  kitId: string;
  /** The project's fleet is live / in maintenance posture (→ can dispatch straight to a stream). */
  live?: boolean;
  /** Per-consumer opt-in to auto-dispatch. Absent/false ⇒ notify-only (the safe default). */
  auto?: boolean;
}

/** How a change reaches one consumer: a surfaced heads-up, or a live-fleet stream assignment (#2806 —
 *  the GitHub-issue rail was dropped; adoption is the UI worker re-running `bsc ui emit sync`). */
export type DispatchKind = "notify" | "assign";

/** The planned action for one consumer of a change. */
export interface Dispatch {
  projectKey: string;
  kind: DispatchKind;
  change: KitChange;
  /** Why this kind was chosen (for the audit/log surface). */
  reason: string;
}

/** A deterministic change fingerprint — the dedup key, shared shape with any future producer. */
export function changeId(kitId: string, component: string, to: string | undefined, cls: ChangeClass): string {
  return `${kitId}:${component}:${to ?? ""}:${cls}`;
}

/** A consumer-index edge id — one edge per (project, kit). Byte-identical to the Rust `usage_id`
 *  (`crates/bsc-component/src/usage.rs`) so the frontend and `bsc ui usage` agree. */
export function kitUsageId(projectKey: string, kitId: string): string {
  return `${projectKey}>${kitId}`;
}

/** Classify a before→after component diff (author-declared class overrides this, see {@link makeChange}).
 *  Breaking wins: a prop removed, a prop that became required, or a prop whose type changed, or a variant
 *  removed. Additive: a new prop or variant. Otherwise a fix. */
export function classifyChange(before: ComponentRecord, after: ComponentRecord): ChangeClass {
  const afterProps = new Map(after.props.map((p) => [p.name, p]));
  for (const bp of before.props) {
    const ap = afterProps.get(bp.name);
    if (!ap) return "breaking"; // removed
    if (!bp.req && ap.req) return "breaking"; // became required
    if (bp.type !== ap.type) return "breaking"; // type changed
  }
  if (before.variants.some((v) => !after.variants.includes(v))) return "breaking"; // variant removed
  const beforeProps = new Set(before.props.map((p) => p.name));
  if (after.props.some((p) => !beforeProps.has(p.name))) return "additive"; // new prop
  if (after.variants.some((v) => !before.variants.includes(v))) return "additive"; // new variant
  return "fix";
}

function defaultSummary(after: ComponentRecord, before: ComponentRecord | undefined, cls: ChangeClass): string {
  const ver = before?.version && after.version ? ` (${before.version} → ${after.version})` : after.version ? ` (${after.version})` : "";
  const verb = cls === "breaking" ? "changed breaking" : cls === "additive" ? "extended" : "fixed";
  return `${after.name}${ver} ${verb}`;
}

/** Build a {@link KitChange} from an after-component (and an optional before, to classify + diff). An
 *  explicit `override.class`/`summary`/`migration` wins over the derived ones (author-declared change). */
export function makeChange(
  after: ComponentRecord,
  before?: ComponentRecord,
  override?: Partial<Pick<KitChange, "class" | "summary" | "migration">>,
): KitChange {
  const cls = override?.class ?? (before ? classifyChange(before, after) : "additive");
  return {
    id: changeId(after.kitId, after.name, after.version, cls),
    kitId: after.kitId,
    component: after.name,
    from: before?.version,
    to: after.version,
    class: cls,
    summary: override?.summary ?? defaultSummary(after, before, cls),
    migration: override?.migration,
  };
}

/** Fan a change out over the consumer index: one {@link Dispatch} per consumer OF THE CHANGED KIT.
 *  Gated notify-only by default — a consumer only gets an `assign` when it opted into `auto` AND the
 *  change is `breaking`. Liveness does NOT change the KIND (it gates DELIVERY in {@link planKitDrain}):
 *  a breaking+auto consumer is `assign` whether or not its fleet is live now. Additive/fix (and every
 *  non-opted-in consumer) are notify-only, so a wide blast never auto-dispatches N sessions. */
export function planPropagation(change: KitChange, consumers: KitConsumer[]): Dispatch[] {
  return consumers
    .filter((c) => c.kitId === change.kitId)
    .map((c) => {
      const dispatch = !!c.auto && change.class === "breaking";
      const kind: DispatchKind = dispatch ? "assign" : "notify";
      const reason = dispatch
        ? "breaking + auto → assign the UI stream to re-run `bsc ui emit sync`"
        : "notify-only (default / non-breaking / not opted-in)";
      return { projectKey: c.projectKey, kind, change, reason };
    });
}

/** Drop dispatches already delivered — dedup by (projectKey, change.id), so a re-run of the same change
 *  never re-issues/re-assigns. `seen` holds the delivered keys; the returned array is the fresh work. */
export function dispatchKey(d: Dispatch): string {
  return `${d.projectKey}:${d.change.id}`;
}
export function dedupeDispatches(dispatches: Dispatch[], seen: Set<string>): Dispatch[] {
  return dispatches.filter((d) => !seen.has(dispatchKey(d)));
}

// ── Delivery (#2277) — draining the planned dispatches to the rails ────────────
// planPropagation decides the intent; this decides what to actually FIRE this cycle. Kept pure (no
// store/Tauri) so the three delivery guarantees are unit-tested in isolation, exactly like faultTriage:
//   • GATE       — the per-project auto-dispatch toggle. OFF (default) ⇒ deliver nothing (surface-only).
//   • DEDUP      — a (consumer, change) delivered once never re-fires while it stays queued.
//   • RATE-LIMIT — a wide blast (one change × N consumers, or a burst of changes) is capped per cycle.

/** How an actionable change reaches a consumer at delivery time (#2806): assigned into its LIVE fleet's
 *  director (bsc-issue → bsc-assign → the UI worker re-runs `bsc ui emit sync`). The only rail — a
 *  consumer with no live fleet HOLDS (see {@link planKitDrain}) rather than opening a GitHub issue. */
export type KitRail = "assign";

/** One change to actually deliver to one consumer this cycle. */
export interface KitDelivery {
  projectKey: string;
  change: KitChange;
  rail: KitRail;
}

/** Per-consumer drain policy, evaluated at delivery time — so `live` reflects the fleet's CURRENT state,
 *  not whatever it was when the change was queued (the kind baked by planPropagation can go stale). */
export interface KitDrainConfig {
  /** The per-project auto-dispatch toggle. `false` (default) ⇒ surface-only: nothing is delivered. */
  enabled: boolean;
  /** The consumer's fleet is live now ⇒ assign to its director; else open a kit-update issue. */
  live: boolean;
  /** Storm guard: at most this many deliveries fired for the consumer in one cycle. */
  maxPerCycle: number;
}

export interface KitDrainPlan {
  /** Changes to deliver THIS cycle. */
  deliver: KitDelivery[];
  /** The (consumer, change) keys now delivered — carry back as `delivered` next cycle so nothing re-fires. */
  nextDelivered: string[];
}

/** Conservative default: ≤3 deliveries per consumer per cycle (a slow poll spreads a wide blast). */
export const DEFAULT_KIT_DRAIN: Omit<KitDrainConfig, "enabled" | "live"> = { maxPerCycle: 3 };

/** The delivered-ledger key for a (consumer, change) — same shape as {@link dispatchKey}. */
export function deliveryKey(projectKey: string, changeId: string): string {
  return `${projectKey}:${changeId}`;
}

/**
 * Decide which of a consumer's queued dispatches to DELIVER this cycle. Pure + deterministic.
 * Only BREAKING changes auto-fire (a mandatory adopt); additive/fix stay surface-only (notify).
 *
 * @param dispatches  the consumer's queued {@link Dispatch}es (the fan-out records for one project).
 * @param delivered   (consumer, change) keys already fired (the dedup ledger; carry `nextDelivered`).
 * @param cfg         the per-consumer policy (gate + liveness + rate cap).
 *
 * Guarantees:
 *  - GATE: `cfg.enabled === false` ⇒ `deliver` is empty.
 *  - DEDUP: a (consumer, change) already in `delivered` is never re-fired.
 *  - RATE-LIMIT: `deliver.length ≤ maxPerCycle`.
 * The only rail is `assign`; a non-live consumer HOLDS (delivers nothing) — no GitHub-issue fallback (#2806).
 */
export function planKitDrain(dispatches: Dispatch[], delivered: Iterable<string>, cfg: KitDrainConfig): KitDrainPlan {
  const already = new Set(delivered);
  // GATE + assign-only HOLD (#2806): deliver only when enabled AND the fleet is LIVE. A dormant consumer
  // holds its queue (nothing marked delivered → carried forward), adopting on its next launch — never
  // via a GitHub issue.
  if (!cfg.enabled || !cfg.live) return { deliver: [], nextDelivered: [...already] };
  const chosen = dispatches
    .filter((d) => d.change.class === "breaking" && !already.has(deliveryKey(d.projectKey, d.change.id)))
    // Deterministic order so a capped cycle picks a stable subset.
    .sort((a, b) => deliveryKey(a.projectKey, a.change.id).localeCompare(deliveryKey(b.projectKey, b.change.id)))
    .slice(0, Math.max(0, cfg.maxPerCycle))
    .map((d): KitDelivery => ({ projectKey: d.projectKey, change: d.change, rail: "assign" }));
  return { deliver: chosen, nextDelivered: [...already, ...chosen.map((c) => deliveryKey(c.projectKey, c.change.id))] };
}

/** The director-facing message routing a kit change into a live fleet (the `assign` rail). The director
 *  captures + assigns adoption via the coordination emitters, exactly like the fault-triage prompt. */
export function kitDispatchPrompt(change: KitChange): string {
  const ver = change.from && change.to ? ` (${change.from} → ${change.to})` : "";
  const mig = change.migration ? `\nMigration: ${change.migration}` : "";
  const breaking = change.class === "breaking";
  return [
    `[kit-update] The \`${change.kitId}\` kit released a ${change.class} change to \`${change.component}\`${ver}` +
      " — adopt it in this app:",
    change.summary + mig,
    "`bsc-assign` the UI worker (the stream whose `owns` lane covers the vendored kit dir) to re-run:",
    "  bsc ui emit sync <kit-dir>",
    breaking
      ? "That re-emits the managed vendored files from the updated kit; then reconcile any now-broken " +
        "call sites — the migration note + the type/eslint errors point at them."
      : "That re-emits the managed vendored files (no hand-edits; a diverged file is skipped, not clobbered).",
    "Capture it with `bsc-issue` first, then `bsc-assign <session>`.",
  ].join("\n");
}

// The console PROVIDER surface — public API only. The built-in set is seeded by `./registry`, the
// module that owns the map, so this barrel has NO import-time side effect and can be a record
// (providers-register-in-the-registry-that-owns-them).
export type { ConsoleProvider, ProviderLaunchConfig } from "@/app/console/lib/providers/types";
export { registerProvider, getProvider, listProviders } from "@/app/console/lib/providers/registry";

import type { ConsoleProvider } from "@/app/console/lib/providers/types";
import { claudeProvider } from "@/app/console/lib/providers/providers/claude";
import { geminiProvider } from "@/app/console/lib/providers/providers/gemini";
import { codexProvider } from "@/app/console/lib/providers/providers/codex";
import { aiderProvider } from "@/app/console/lib/providers/providers/aider";
import { ollamaProvider } from "@/app/console/lib/providers/providers/ollama";
import { amazonQProvider } from "@/app/console/lib/providers/providers/amazonq";
import { bscAgentProvider } from "@/app/console/lib/providers/providers/bscAgent";

const REGISTRY = new Map<string, ConsoleProvider>();

export function registerProvider(p: ConsoleProvider): void {
  REGISTRY.set(p.id, p);
}

export function getProvider(id: string): ConsoleProvider | undefined {
  return REGISTRY.get(id);
}

export function listProviders(): ConsoleProvider[] {
  return [...REGISTRY.values()];
}

// The built-in provider set, seeded HERE — in the module that owns the map — rather than in the
// barrel (providers-register-in-the-registry-that-owns-them).
//
// Two things this buys. Anyone reaching `getProvider` necessarily loads THIS module, so the built-ins
// are guaranteed present; when the barrel seeded them, a consumer importing `./registry` directly got
// an empty map, and the guarantee rested on which path you happened to take. And the barrel becomes
// re-exports only, which is what lets it be a record rather than a file that must RUN to be correct.
//
// This module cannot be a record either way: it holds REGISTRY, a live map. Seeding it here therefore
// costs nothing that was not already spent.
registerProvider(claudeProvider);
registerProvider(geminiProvider);
registerProvider(codexProvider);
registerProvider(aiderProvider);
registerProvider(ollamaProvider);
registerProvider(amazonQProvider);
registerProvider(bscAgentProvider);

// Publish steps (#1749) — the six sequential phases of `handlePublish`, extracted from
// usePlanPublish.ts so each is independently unit-testable. The logic is verbatim; the only change is
// that the GitHub API (`gql/rest/post/put/patch`), the per-node status callback (`upd`), and the
// store/`invoke` side-effects are INJECTED rather than captured from the hook's closure. The hook
// (usePlanPublish) is now a thin orchestrator that wires these together.
//
// Every step is fail-soft in the same places it was inline: a per-node failure records an "error"
// status via `upd` and continues; fail-CLOSED branches (couldn't verify existing milestones/issues)
// are preserved exactly so a transient read failure never risks duplicate creation.

import { resolveRepoPublic } from "@/store/slices/plan";
import type { GhStatusMap, GhItemState } from "@/features/planner/session/GitHubStructureCard";
import { parseFeaturesFile, featuresToPlanIssues } from "@/features/planner/issues/featureList";
import { depsForRepo, mergeIntoPackageJson, mergeIntoCargoToml, buildNpmrc, buildCargoConfig, type parseDependencyManifest } from "@/features/planner/issues/dependencies";
import { resolveIssueAssignee } from "@/features/planner/fleet/fleetAssignee";
import type { AgentStream } from "@/features/planner/fleet/planFleet";
import { deriveTopics, buildReadme, communityFiles, type ScaffoldFile } from "@/features/planner/lib/repoScaffold";
import { renderIssueBody, subIssueLinks, type PlanIssue } from "@/features/planner/issues/planIssues";
import { BSC_ISSUE_LABEL, BSC_ISSUE_LABEL_COLOR, withProvenanceLabel } from "@/shared/lib/github/issueProvenance";

/** The injected GitHub transport — the same closures handlePublish built over `invoke`. */
export interface GhApi {
  gql: (query: string, variables: unknown) => Promise<Record<string, unknown>>;
  rest: <T>(path: string) => Promise<T>;
  post: <T>(path: string, body: unknown) => Promise<T>;
  put: (path: string, body: unknown) => Promise<unknown>;
  patch: (path: string, body: unknown) => Promise<unknown>;
}

/** Patch a single GitHub-structure node's live status (drives the GitHubStructureCard). */
export type Upd = (id: string, patch: Partial<GhItemState>) => void;

type DepManifest = ReturnType<typeof parseDependencyManifest>;

// ── 1. Repositories — verify each exists; create if missing ───────────────────
export async function publishRepositories(
  api: GhApi,
  upd: Upd,
  opts: {
    repos: string[];
    projectDesc: string;
    repoPublic: Parameters<typeof resolveRepoPublic>[0];
    reposPublic: Parameters<typeof resolveRepoPublic>[1];
    effectiveProjectId: string;
  },
): Promise<{ repoNodeIds: Record<string, string>; viewerLogin: string }> {
  const { repos, projectDesc, repoPublic, reposPublic, effectiveProjectId } = opts;
  const repoNodeIds: Record<string, string> = {};
  let viewerLogin = "";
  try {
    const v = await api.gql(`{ viewer { login } }`, null) as { viewer?: { login?: string } };
    viewerLogin = v.viewer?.login ?? "";
  } catch { /* non-fatal: fall back to org repo path */ }

  for (const fullName of repos) {
    const id = `repo:${fullName}`;
    const [owner, name] = fullName.split("/");
    upd(id, { status: "running" });
    try {
      const existing = await api.rest<{ node_id: string; html_url: string }>(`repos/${fullName}`).catch(() => null);
      if (existing?.node_id) {
        repoNodeIds[fullName] = existing.node_id;
        upd(id, { status: "exists", detail: "on github", url: existing.html_url });
      } else {
        const path = owner.toLowerCase() === viewerLogin.toLowerCase() ? "user/repos" : `orgs/${owner}/repos`;
        const created = await api.post<{ node_id: string; html_url: string }>(path, {
          // Per-repo visibility (#1227): the repo's own toggle wins, else the project default,
          // else private. Existing repos are detected above and never re-created, so this
          // governs creation only.
          name, private: !resolveRepoPublic(repoPublic, reposPublic, effectiveProjectId, fullName), description: projectDesc,
        });
        repoNodeIds[fullName] = created.node_id;
        upd(id, { status: "created", detail: "created", url: created.html_url });
      }
    } catch (e) {
      upd(id, { status: "error", detail: String(e) });
    }
  }
  return { repoNodeIds, viewerLogin };
}

// ── 1b. Repo presentation (#848, #1114): description (every repo), stack topics, a plan-built
//        README with CI/version badges, community-health files, and the locked dependency
//        manifests/registry config. Files are created only when ABSENT; failures are surfaced
//        in the card detail, not fatal. ──
export async function scaffoldRepositories(
  api: GhApi,
  upd: Upd,
  opts: {
    repos: string[];
    projectDesc: string;
    projectTitle: string;
    goalContent: string;
    stackText: string;
    scopeText: string;
    archText: string;
    features: { name: string; behavior?: string }[];
    planDependencies: DepManifest["dependencies"];
    registries: DepManifest["registries"];
  },
): Promise<void> {
  const { repos, projectDesc, projectTitle, goalContent, stackText, scopeText, archText, features, planDependencies, registries } = opts;
  const topics = deriveTopics(stackText);
  for (const fullName of repos) {
    const id = `scaffold:${fullName}`;
    upd(id, { status: "running" });
    try {
      // Always (re)apply the description — a create sets it, but a pre-existing repo never had it.
      let descOk = true;
      if (projectDesc) await api.patch(`repos/${fullName}`, { description: projectDesc }).catch(() => { descOk = false; });
      let topicsOk = true;
      if (topics.length) await api.put(`repos/${fullName}/topics`, { names: topics }).catch(() => { topicsOk = false; });
      // CI badges reference the repo's actual workflow files (graceful — none yet ⇒ none).
      const wfs = await api.rest<{ name: string }[]>(`repos/${fullName}/contents/.github/workflows`).catch(() => []);
      const workflows = (Array.isArray(wfs) ? wfs : []).map(w => w.name).filter(n => /\.ya?ml$/i.test(n));
      const files: ScaffoldFile[] = [
        { path: "README.md", content: buildReadme({
          fullName, description: projectDesc, goal: goalContent, scope: scopeText,
          architecture: archText, features, stackText, workflows,
        }) },
        ...communityFiles(projectTitle),
      ];
      let wrote = 0;
      for (const f of files) {
        const path = `repos/${fullName}/contents/${f.path}`;
        const exists = await api.rest<{ sha?: string }>(path).then(r => !!r?.sha).catch(() => false);
        if (exists) continue; // don't clobber an existing file
        const content = btoa(unescape(encodeURIComponent(f.content)));
        await api.put(path, { message: `docs: scaffold ${f.path}`, content }).catch(() => {});
        wrote++;
      }

      // Dependency manifests (#1111/#1127): seed package.json / Cargo.toml from the locked manifest —
      // and the registry config (.npmrc / .cargo/config.toml) for any private SOURCE — so the fleet
      // inherits identical, complete, fetchable deps from the base branch and never adds its own. An
      // ADDITIVE MERGE for the manifests — a pre-existing pinned version always wins, so we read the
      // current file, merge, and only write on a real change.
      let manifests = 0;
      const repoDeps = depsForRepo(planDependencies, fullName);
      if (repoDeps.length) {
        const shortRepo = fullName.split("/")[1] ?? fullName;
        const seedManifest = async (file: string, merge: (existing: string | null) => string | null) => {
          const path = `repos/${fullName}/contents/${file}`;
          const cur = await api.rest<{ sha?: string; content?: string }>(path).catch(() => null);
          const existing = cur?.content ? decodeURIComponent(escape(atob(cur.content.replace(/\s/g, "")))) : null;
          const merged = merge(existing);
          if (merged === null || merged === existing) return; // nothing to add / no change
          const content = btoa(unescape(encodeURIComponent(merged)));
          await api.put(path, { message: `chore: seed ${file} from the locked dependency manifest`, content, ...(cur?.sha ? { sha: cur.sha } : {}) }).catch(() => {});
          manifests++;
        };
        await seedManifest("package.json", (e) => mergeIntoPackageJson(e, shortRepo, repoDeps));
        await seedManifest("Cargo.toml", (e) => mergeIntoCargoToml(e, shortRepo, repoDeps));
        // Registry config for private sources — generated wholesale (not merged): create it only when
        // absent so a hand-tuned .npmrc / .cargo config is never clobbered.
        await seedManifest(".npmrc", (e) => (e === null ? buildNpmrc(registries, repoDeps) : null));
        await seedManifest(".cargo/config.toml", (e) => (e === null ? buildCargoConfig(registries, repoDeps) : null));
      }

      const bits = [
        projectDesc ? (descOk ? "description" : "description failed") : null,
        topics.length ? (topicsOk ? `${topics.length} topics` : "topics failed") : null,
        wrote ? `${wrote} file${wrote === 1 ? "" : "s"}` : null,
        manifests ? `${manifests} manifest${manifests === 1 ? "" : "s"}` : null,
      ].filter(Boolean);
      upd(id, (wrote || manifests)
        ? { status: "created", detail: bits.join(" · ") }
        : { status: "exists", detail: bits.length ? `${bits.join(" · ")} · files present` : "already scaffolded" });
    } catch (e) {
      upd(id, { status: "error", detail: String(e) });
    }
  }
}

// ── 2. Project board — reuse existing or create a Projects v2 board ───
// Returns the resolved projectId and, when a board was newly created, the `created` board so the
// caller can perform the store writes (setActiveProjectMeta / key alias / mark_published / draft drop).
export async function ensureProjectBoard(
  api: GhApi,
  upd: Upd,
  opts: {
    activeProjectId: string | null;
    activeProjectNumber: number | null | undefined;
    repos: string[];
    viewerLogin: string;
    projectTitle: string;
    repoNodeIds: Record<string, string>;
  },
): Promise<{ projectId: string | undefined; created?: { id: string; number: number; url: string } }> {
  const { activeProjectId, activeProjectNumber, repos, viewerLogin, projectTitle, repoNodeIds } = opts;
  let projectId: string | undefined = activeProjectId ?? undefined;
  let created: { id: string; number: number; url: string } | undefined;
  const id = "project";
  upd(id, { status: "running" });
  try {
    if (projectId) {
      upd(id, { status: "exists", detail: activeProjectNumber ? `#${activeProjectNumber}` : "linked" });
    } else {
      const ownerLogin = repos[0]?.split("/")[0] || viewerLogin;
      if (!ownerLogin) throw new Error("no owner to create project under");
      const ownerData = await api.gql(
        `query($login:String!){ repositoryOwner(login:$login){ id } }`,
        { login: ownerLogin },
      ) as { repositoryOwner?: { id?: string } };
      const ownerId = ownerData.repositoryOwner?.id;
      if (!ownerId) throw new Error(`could not resolve owner '${ownerLogin}'`);
      const createdRes = await api.gql(
        `mutation($ownerId:ID!,$title:String!){
             createProjectV2(input:{ownerId:$ownerId,title:$title}){ projectV2 { id number url } }
           }`,
        { ownerId, title: projectTitle },
      ) as { createProjectV2?: { projectV2?: { id: string; number: number; url: string } } };
      const pv = createdRes.createProjectV2?.projectV2;
      if (!pv) throw new Error("project not created");
      projectId = pv.id;
      created = pv;
      upd(id, { status: "created", detail: `#${pv.number}`, url: pv.url });
    }
    // Link every repo to the board (idempotent server-side).
    for (const fullName of repos) {
      const repoNodeId = repoNodeIds[fullName];
      if (projectId && repoNodeId) {
        await api.gql(
          `mutation($p:ID!,$r:ID!){ linkProjectV2ToRepository(input:{projectId:$p,repositoryId:$r}){ repository { id } } }`,
          { p: projectId, r: repoNodeId },
        ).catch(() => { /* already linked — ignore */ });
      }
    }
  } catch (e) {
    upd(id, { status: "error", detail: String(e) });
  }
  return { projectId, created };
}

// ── 3. Issues — generated from the FEATURES (one issue per feature, #plan-db): added to the board,
//      assigned to its stream's login, with feature sub-issues nested. No milestones (#1912).
//      Idempotent, fail-CLOSED on a repo whose existing-issue fetch fails. ──
/**
 * The LOCAL half of publish (#3280): parse the features section into `PlanIssue`s and materialize them
 * into plan.db, so the fleet/director have issues to coordinate on WITHOUT any GitHub round-trip. Used
 * both by `createIssues` (before the GitHub push) and by the GitHub-less commit path.
 *
 * Idempotent — `upsertIssue` keys on `ref`, so committing locally and later publishing over the same
 * rows never duplicates. Returns the parsed issues for the caller (createIssues then pushes them).
 */
export async function materializeIssues(
  featuresContent: string,
  hooks: { upsertIssue: (iss: PlanIssue) => Promise<void> },
): Promise<PlanIssue[]> {
  const planIssues = featuresToPlanIssues(parseFeaturesFile(featuresContent));
  for (const iss of planIssues) {
    await hooks.upsertIssue(iss);
  }
  return planIssues;
}

export async function createIssues(
  api: GhApi,
  upd: Upd,
  opts: {
    repos: string[];
    featuresContent: string;
    projectId: string | undefined;
    streams: AgentStream[];
    viewerLogin: string;
  },
  hooks: {
    upsertIssue: (iss: PlanIssue) => Promise<void>;
    /** Record the GitHub identity a create (or a legacy title match) established for `ref`. */
    setIssueIdentity: (ref: string, ghNumber: number, ghNodeId?: string) => Promise<void>;
    /** The CURRENT plan.db rows, read back after materialize so their stored `ghNumber` is in hand.
     *  The parsed feature list cannot supply it — features carry no publish state — so without this
     *  read every publish would look at freshly-derived rows and think nothing had ever shipped. */
    loadIssues: () => Promise<PlanIssue[]>;
  },
): Promise<void> {
  const { repos, featuresContent, projectId, streams, viewerLogin } = opts;
  // The LOCAL half — materialize into plan.db — is shared with the GitHub-less commit path (#3280).
  const materialized = await materializeIssues(featuresContent, hooks);
  // Re-read so each issue carries the identity plan.db holds for it. `upsert` preserves `gh_number`
  // across a content edit, so this read is what turns "the features say F1 exists" into "F1 is
  // already issue #3898".
  const stored = new Map((await hooks.loadIssues().catch(() => [] as PlanIssue[])).map(i => [i.ref, i]));
  const planIssues = materialized.map(iss => {
    const s = stored.get(iss.ref);
    return s?.ghNumber ? { ...iss, ghNumber: s.ghNumber, ghNodeId: s.ghNodeId } : iss;
  });

  for (const [repoIdx, fullName] of repos.entries()) {
    // Check what already exists BEFORE creating so a re-sync never duplicates. Fail CLOSED: if we
    // can't fetch the repo's issues, skip creating here.
    let existingNumbers: Set<number>;
    // title → the first row carrying it, so the legacy title match resolves a NUMBER from the one
    // fetch above. Re-querying per issue would be the N-per-item fan-out this codebase has paid for
    // repeatedly (#3908/#3912/#3944/#3954) — and it would be worse here, once per issue per publish.
    let existingByTitle: Map<string, { number: number; node_id?: string }>;
    try {
      const existing = await api.rest<{ number: number; title: string; node_id?: string }[]>(`repos/${fullName}/issues?state=all&per_page=100`);
      existingNumbers = new Set(existing.map(i => i.number).filter(n => typeof n === "number"));
      existingByTitle = new Map();
      for (const r of existing) {
        if (r.title && !existingByTitle.has(r.title)) existingByTitle.set(r.title, { number: r.number, node_id: r.node_id });
      }
    } catch {
      for (const iss of planIssues) upd(`issue:${fullName}:${iss.ref}`, { status: "error", detail: "couldn't verify existing issues — skipped" });
      continue;
    }

    // Issues for THIS repo: its declared `repo`, or the default (first) repo.
    const mine = planIssues.filter(iss => iss.repo ? iss.repo === fullName : repoIdx === 0);
    // Ensure every label this repo uses exists (422 if present — harmless).
    // Provenance label first (#738) — every app-created issue carries it.
    await api.post(`repos/${fullName}/labels`, { name: BSC_ISSUE_LABEL, color: BSC_ISSUE_LABEL_COLOR }).catch(() => {});
    for (const name of [...new Set(mine.flatMap(iss => iss.labels))]) {
      await api.post(`repos/${fullName}/labels`, { name, color: "0e8a16" }).catch(() => {});
    }
    // Ensure each owning stream's `stream:<id>` label up front so issues are created ALREADY tagged
    // (#2397). Labeling at creation — where the real GitHub number is in hand — avoids the fragile
    // post-hoc "label by the plan's predicted number" pass, whose numbers 404 when an issue failed to
    // post or the numbering drifted.
    for (const label of new Set(mine.map(iss => iss.stream).filter(Boolean).map(s => `stream:${s}`))) {
      await api.post(`repos/${fullName}/labels`, { name: label, color: "5319e7" }).catch(() => {});
    }
    // ref → created GitHub node id, so feature parents + their sub-issues can be linked.
    const nodeByRef: Record<string, string> = {};
    for (const iss of mine) {
      const id = `issue:${fullName}:${iss.ref}`;
      // IDENTITY FIRST. A row that knows its number is settled — no title comparison, so renaming an
      // issue no longer makes publish believe it is new and open a duplicate.
      if (iss.ghNumber && existingNumbers.has(iss.ghNumber)) {
        upd(id, { status: "exists", detail: `#${iss.ghNumber}` });
        continue;
      }
      // Title match stays ONLY for rows published before the identity column existed. When it hits we
      // backfill the number, so a legacy row is matched by title exactly once and by identity forever
      // after — the migration happens as a side effect of the next publish, with no separate pass.
      const byTitle = existingByTitle.get(iss.title);
      if (byTitle) {
        // Only link when the match actually yielded a usable number. "Exists" is still the right
        // answer without one — the issue is there and must not be re-created — but writing an
        // undefined/0 number would fabricate an identity that points at nothing, which is worse than
        // having none: the next publish would trust it and skip the issue forever.
        if (byTitle.number > 0) {
          await hooks.setIssueIdentity(iss.ref, byTitle.number, byTitle.node_id).catch(() => {});
          upd(id, { status: "exists", detail: `#${byTitle.number} · linked` });
        } else {
          upd(id, { status: "exists", detail: "already exists" });
        }
        continue;
      }
      upd(id, { status: "running" });
      try {
        const body: Record<string, unknown> = { title: iss.title, body: renderIssueBody(iss) };
        // Tag the owning stream at creation (#2397) so ownership is correct without a number-matching
        // pass. Provenance stamp (#738) rides along.
        const labels = iss.stream ? [...iss.labels, `stream:${iss.stream}`] : iss.labels;
        body.labels = withProvenanceLabel(labels);
        const issue = await api.post<{ number: number; node_id: string; html_url: string }>(`repos/${fullName}/issues`, body);
        if (issue.node_id) nodeByRef[iss.ref] = issue.node_id;
        // Record the link IMMEDIATELY, before the board-add / assignee / sub-issue calls below. Those
        // are all best-effort and any of them can throw; if the identity were written after them, a
        // failure there would leave a real GitHub issue that plan.db has no record of — and the next
        // publish would create it again. The write that must not be lost goes first.
        if (issue.number) {
          await hooks.setIssueIdentity(iss.ref, issue.number, issue.node_id).catch(() => {});
        }
        if (projectId && issue.node_id) {
          await api.gql(`mutation($p:ID!,$c:ID!){ addProjectV2ItemById(input:{projectId:$p,contentId:$c}){ item { id } } }`, { p: projectId, c: issue.node_id }).catch(() => {});
        }
        // Assign the issue to its owning stream's GitHub login (#847), defaulting to the publishing
        // account. Done AFTER the issue exists, so an invalid / no-access login (a 422) is skipped
        // gracefully and never loses the issue.
        const assignee = resolveIssueAssignee(iss.stream, streams, viewerLogin);
        if (assignee) {
          await api.post(`repos/${fullName}/issues/${issue.number}/assignees`, { assignees: [assignee] }).catch(() => {});
        }
        upd(id, { status: "created", detail: `#${issue.number}`, url: issue.html_url });
      } catch (e) {
        upd(id, { status: "error", detail: String(e) });
      }
    }
    // Nest each feature's sub-issues under their parent (#…) via GraphQL addSubIssue. Best-effort +
    // idempotent: only links pairs created in THIS run; an already-linked pair (or an API that
    // doesn't support sub-issues) errors harmlessly.
    for (const { parent, child } of subIssueLinks(mine, nodeByRef)) {
      await api.gql(
        `mutation($p:ID!,$c:ID!){ addSubIssue(input:{issueId:$p,subIssueId:$c}){ issue { id } } }`,
        { p: parent, c: child },
      ).catch(() => {});
    }
  }
}

// ── 4. Stream labels — a best-effort RECONCILIATION pass (#2397). Issues created in this publish are
//      already tagged `stream:<id>` at creation (createIssues); this pass re-applies the label to any
//      PRE-EXISTING issues the stream owns, resolvable by number. Resilient: a plan-ref number that
//      never became a real issue (a post that failed, or numbering that drifted) 404s — that issue is
//      SKIPPED, never aborting the stream or surfacing the 404 as a publish error. Idempotent. ──
export async function applyStreamLabels(
  api: GhApi,
  upd: Upd,
  opts: { streams: AgentStream[] },
): Promise<void> {
  for (const st of opts.streams) {
    const id    = `stream:${st.id}`;
    const label = `stream:${st.id}`;
    upd(id, { status: "running" });
    try {
      // Create the label (the request 422s if it already exists — harmless).
      await api.post(`repos/${st.repo}/labels`, { name: label, color: "5319e7" }).catch(() => {});
      const nums = st.issues
        .map(ref => parseInt(ref.replace(/[^0-9]/g, ""), 10))
        .filter(n => Number.isFinite(n) && n > 0);
      let applied = 0;
      let skipped = 0;
      for (const n of nums) {
        // Per-issue resilience: a 404 (the number isn't a real issue) skips just that one.
        const ok = await api.post(`repos/${st.repo}/issues/${n}/labels`, { labels: [label] })
          .then(() => true).catch(() => false);
        if (ok) applied++; else skipped++;
      }
      const skipNote = skipped > 0 ? ` · ${skipped} skipped (no matching issue)` : "";
      upd(id, applied > 0
        ? { status: "created", detail: `${applied} issue${applied === 1 ? "" : "s"} labeled${skipNote}` }
        : { status: "exists",  detail: `label ready${nums.length ? skipNote : " · no numbered issues"}` });
    } catch (e) {
      upd(id, { status: "error", detail: String(e) });
    }
  }
}

/** Seed every GitHub-structure node as "planned" so the card shows the full structure upfront. */
export function seedPublishStatus(opts: { repos: string[]; streams: AgentStream[] }): GhStatusMap {
  const { repos, streams } = opts;
  const status: GhStatusMap = {};
  status["project"] = { status: "planned" };
  repos.forEach(r => { status[`repo:${r}`] = { status: "planned" }; });
  streams.forEach(st => { status[`stream:${st.id}`] = { status: "planned" }; });
  return status;
}

// A published project's lifecycle, derived from GitHub state: open ⇒ active, closed ⇒ shipped.
// (Local, not-yet-on-GitHub work lives in the separate Drafts section.)
export type ProjStatus = "active" | "shipped";
export const STATUS_META: Record<ProjStatus, { label: string; cls: string; dot: string }> = {
  active:   { label: "active",   cls: "green", dot: "var(--success)" },
  shipped:  { label: "shipped",  cls: "",      dot: "var(--fg-dim)" },
};
export function projStatus(p: { closed: boolean }): ProjStatus {
  return p.closed ? "shipped" : "active";
}

interface GhProjectItem { content: { __typename?: string; state?: string } | null }
export interface GhProject {
  id: string;
  number: number;
  title: string;
  shortDescription: string | null;
  url: string;
  closed: boolean;
  updatedAt: string;
  items: { totalCount: number; nodes: GhProjectItem[] };
  repositories: { nodes: Array<{ nameWithOwner: string }> };
}

// Open count + closed fraction from the fetched item states (capped at 100 items;
// totalCount is the true item count, used for the headline number).
export function projectProgress(p: GhProject): { open: number; pct: number } {
  let open = 0, closed = 0;
  for (const n of p.items?.nodes ?? []) {
    const s = n.content?.state;
    if (s === "OPEN") open++;
    else if (s === "CLOSED" || s === "MERGED") closed++;
  }
  const total = open + closed;
  return { open, pct: total ? closed / total : 0 };
}

export const PROJECTS_QUERY = `{
