/** A manifest prop's type rendered as a short human/TS-ish string for the props table. */
function mapType(p: ManifestProp): string {
  if (p.type === "enum" && p.values) return p.values.map((v) => `"${v}"`).join(" | ");
  switch (p.type) {
    case "node": return "ReactNode";
    case "function": return "(…) => void";
    case "space": return "Space";
    case "fontSize": return "FontSize";
    case "tracks": return "Tracks";
    case "color": return "Color";
    case "style": return "CSSProperties";
    case "array": return "T[]";
    default: return p.type; // string | number | boolean
  }
}

const mapProps = (specs: readonly ManifestProp[]): PropSpec[] =>
  specs.map((p) => ({ name: p.name, type: mapType(p), req: !!p.required, desc: p.description }));

/** Variants: the overlay's set, else the `variant` enum's values (else "default"), plus "loading"
 *  when the component registers a `loading` prop (#2302). */
function deriveVariants(spec: PrimitiveSpec, g: Guidance): string[] {
  let base = g.variants;
  if (!base) {
    const variantProp = spec.props.find((p) => p.name === "variant" && p.type === "enum" && p.values);
    base = variantProp?.values ? [...variantProp.values] : ["default"];
  }
  const hasLoading = spec.props.some((p) => p.name === "loading");
  return hasLoading && !base.includes("loading") ? [...base, "loading"] : base;
}

/** A minimal, generated usage snippet for a component without an authored `srcText`. */
function stubSrc(spec: PrimitiveSpec): string {
  const req = spec.props.filter((p) => p.required && p.name !== "children");
  const attrs = req.map((p) => ` ${p.name}={…}`).join("");
  const hasChildren = spec.props.some((p) => p.name === "children");
  const body = hasChildren ? `<${spec.name}${attrs}>…</${spec.name}>` : `<${spec.name}${attrs} />`;
  return `import { ${spec.name} } from "${spec.importPath}";\n\n${body}`;
}

function toRecord(spec: PrimitiveSpec): ComponentRecord {
  const g = GUIDANCE[spec.name] ?? {};
  return {
    id: spec.name.toLowerCase(),
    name: spec.name,
    kitId: REACT_UI_KIT_ID,
    role: g.role ?? GROUP_ROLE[spec.group],
    version: g.version ?? "1.0.0",
    used: g.used ?? 0,
    tags: g.tags ?? [spec.group],
    variants: deriveVariants(spec, g),
    composes: g.composes ?? [],
    props: mapProps(spec.props),
    whenUse: g.whenUse ?? [],
    whenNot: g.whenNot ?? [],
    src: `${spec.importPath.replace(/^@\//, "")}.tsx`,
    srcText: g.srcText ?? stubSrc(spec),
    builtin: true,
    ...(g.wraps ? { wraps: g.wraps } : {}),
    ...(g.shapes ? { shapes: g.shapes } : {}),
    // Motion BINDING (#2942/#3451) — the manifest spec already carries NAME references; the defs
    // themselves are owned by the `base` kit (`shared/ui/kit/baseAnimations.ts`) and resolved from
    // there. Only emitted when present so animation-free records stay byte-identical.
    ...(spec.animations?.length ? { animations: [...spec.animations] } : {}),
  };
}

/** The `react-ui` kit — the app's own shared-UI primitives. `tech`/`style` are the #2487 rail
 *  hierarchy axes: react technology, and "studio" — the app's neutral house visual language (the
 *  structural component set; palettes/themes are a separate axis and never name a style).
 *
 *  Its motion library is deliberately EMPTY (#3451): the base motions its primitives play
 *  (`lift`/`fade-in`/`pulse`) are owned by the `base` kit (`shared/ui/kit/baseAnimations.ts`) and
 *  resolved from there by name, so ONE definition serves every consuming kit and a base-motion edit
 *  propagates to all of them. react-ui REFERENCES that shared motion; it no longer owns it. (A kit
 *  may still author its OWN motion here — the resolver prefers a kit's own def over the base one.) */
export const REACT_UI_KIT: Kit = {
  id: REACT_UI_KIT_ID, name: "react-ui", tech: "react", style: "studio", stack: "React · TypeScript",
  dot: "var(--info)", builtin: true, animations: [],
};

/** Every registered primitive as a component record — generated from the manifest, so this is exactly
 *  `UI_KIT` (guarded by `reactUiKit.test.ts`), never a drifting hand-list. */
export const REACT_UI_COMPONENTS: ComponentRecord[] = UI_KIT.map(toRecord);

// Shared readiness-check shape (#1625) — one home for the byte-identical
// `{ id, label, ok, detail }` row used by the deploy / integration / source stage
// banners. Each `*Checks` builder returns these; every row `ok` ⇒ the stage gate passes.

/** A single readiness row driving an in-pane stage banner. */
export interface ReadinessCheck {
  /** stable row id (also the React key). */
  id: string;
  /** human label for the requirement. */
  label: string;
  /** whether this requirement is satisfied. */
  ok: boolean;
  /** a short value/explanation shown beside the label. */
  detail: string;
}

// Blueprint design reconciliation (#2646, epic #2606) — the PURE diff behind the sharing layer. When a
// blueprint is downloaded, its design contribution (the categories it introduces + a theme ref) is
// reconciled against the LOCAL design contract: categories the contract doesn't define are gaps a
// dedicated confirm-list (5b) offers to fill via the generator (#2636), so a shared blueprint brings its
// look with NO holes. This module is the DIFF only — no download/confirm/generation wiring. Kept in
// shared/ (feature-agnostic, structural inputs) so the planner + a future reconciliation UI both use it.
import DESCRIPTOR from "@data/ui/style-descriptor.json";
import { slugify } from "@/shared/lib/core/format";

interface DomainDescriptor {
  domain?: { group: string; tokens?: { key: string }[] }[];
}

/** The graph CATEGORY keys the local contract defines (the `graph-category` domain group): greenfield,
 *  transform, harden, maintain, data, script. A blueprint category outside this set is a gap the
 *  generator fills. Computed once from the descriptor. */
export const KNOWN_GRAPH_CATEGORIES: ReadonlySet<string> = (() => {
  const d = DESCRIPTOR as DomainDescriptor;
  const group = (d.domain ?? []).find((g) => g.group === "graph-category");
  return new Set((group?.tokens ?? []).map((t) => t.key));
})();

/** A blueprint's design contribution — the reconcilable shape (structural; the planner's `BlueprintDesign`
 *  is assignable to it, keeping shared/ free of a feature import). */
export interface DesignContribution {
  categories?: string[];
  theme?: string;
}

export interface DesignReconcile {
  /** Categories the blueprint introduces that the local contract does NOT define — the gaps to fill. */
  missingCategories: string[];
  /** The theme ref carried through (a `bsc ui theme` id), for the confirm-list to resolve/import (5b). */
  themeRef?: string;
  /** True when nothing needs reconciling (no missing categories). */
  complete: boolean;
}

/** Diff a blueprint's design contribution against the local contract (#2646). Pure. `known` defaults to
 *  the contract's graph-category keys; missing categories are slugified, deduped + sorted.
 *
 *  Each category is normalized to a slug FIRST (#2663) so the token derived downstream —
 *  `--graph-category-<key>` — is always a valid custom property. A non-slug key like `"Simulation"` or
 *  `"ui_ux"` would otherwise be dropped SILENTLY when `compileContributionsCss` rejects it against
 *  `SAFE_TOKEN` — a hole the fall-loudly principle forbids. Slugging here also means a capitalized KNOWN
 *  category (e.g. `"Greenfield"`) matches the contract instead of being wrongly flagged missing. Empty
 *  slugs (e.g. from `"!!!"`) are dropped. */
export function reconcileDesign(
  design: DesignContribution | undefined,
  known: ReadonlySet<string> = KNOWN_GRAPH_CATEGORIES,
): DesignReconcile {
  const categories = (design?.categories ?? []).map((c) => slugify(c)).filter(Boolean);
  const missingCategories = [...new Set(categories.filter((c) => !known.has(c)))].sort();
  return { missingCategories, themeRef: design?.theme, complete: missingCategories.length === 0 };
}

// GitHub → plan.db recovery (#plan-db). The mirror of the publish flow: where publish maps each
// PlanIssue to a GitHub issue (body = acceptance/owns/dependsOn, `stream:<id>` label, hidden ref
// marker), recovery inverts it — reconstructing PlanIssue[] from a repo's issues so a lost or
// machine-switched plan.db can be rehydrated from the durable GitHub store.
//
// Pure (no React/Tauri) so the reverse-parse is unit-testable and round-trips against
// renderIssueBody. The orchestration (gh fetch + `bsc plan add`) lives in Planning.tsx.

import { parseRefMarker, type PlanIssue, type PlanIssueStatus } from "@/features/planner/issues/planIssues";

/** The subset of a GitHub REST issue object recovery reads (`GET repos/{repo}/issues`). */
export interface GitHubIssueLike {
  number: number;
  title: string;
  body?: string | null;
  /** "open" | "closed". */
  state?: string;
  labels?: Array<{ name?: string } | string>;
  /** Present ⇒ this row is a pull request, not an issue (the /issues endpoint returns both). */
  pull_request?: unknown;
}

/**
 * Reverse of {@link renderIssueBody}: pull the prose body + acceptance/owns/dependsOn back out of a
 * published issue body. Tolerant of formatting drift — unknown sections are ignored, the `---`
 * footer and the hidden ref marker are stripped, and a bare body with no sections still recovers.
 */
function parseIssueBody(raw: string): Pick<PlanIssue, "body" | "acceptance" | "owns" | "dependsOn"> {
  const text = (raw ?? "").replace(/<!--\s*bsc:ref=[^>]*-->/g, "").trim();
  const acceptance: string[] = [];
  const owns: string[] = [];
  const dependsOn: string[] = [];
  const prose: string[] = [];
  let section: "body" | "acceptance" | "owns" | "depends" | "other" = "body";

  for (const lineRaw of text.split(/\r?\n/)) {
    const line = lineRaw.trim();
    const heading = /^##\s+(.+)$/.exec(line);
    if (heading) {
      const t = heading[1].toLowerCase();
      section = t.startsWith("acceptance") ? "acceptance"
        : t.startsWith("owns") ? "owns"
        : t.startsWith("depends") ? "depends"
        : "other";
      continue;
    }
    // The auto-gen footer ends the meaningful content.
    if (line === "---" || line.startsWith("_Auto-generated")) { section = "other"; continue; }

    const bullet = /^[-*]\s+(.*)$/.exec(line);
    if (section === "acceptance" && bullet) {
      acceptance.push(bullet[1].replace(/^\[[ xX]\]\s*/, "").trim()); // drop the checkbox
    } else if (section === "owns" && bullet) {
      owns.push(bullet[1].replace(/`/g, "").trim());                  // drop the code ticks
    } else if (section === "depends" && bullet) {
      dependsOn.push(bullet[1].trim());
    } else if (section === "body") {
      prose.push(lineRaw);
    }
  }

  const body = prose.join("\n").trim();
  return {
    body: body || undefined,
    acceptance: acceptance.filter(Boolean),
    owns: owns.filter(Boolean),
    dependsOn: dependsOn.filter(Boolean),
  };
}

/**
 * Reconstruct one {@link PlanIssue} from a GitHub issue. Ref comes from the hidden marker (falling
 * back to `#<number>` so it stays addressable); stream from the `stream:<id>` label;
 * acceptance/owns/dependsOn from the body. GitHub is only open/closed, so a
 * closed issue maps to `verified` (merged + CI green at close) and an open one to `open` — the
 * director can refine an open issue via its linked PR + CI later (the same live-verify signal).
 */
export function recoverIssue(gh: GitHubIssueLike, repoFullName: string): PlanIssue {
  const labelNames = (gh.labels ?? [])
    .map((l) => (typeof l === "string" ? l : l?.name ?? ""))
    .filter(Boolean);
  const streamLabel = labelNames.find((n) => n.startsWith("stream:"));
  const stream = streamLabel ? streamLabel.slice("stream:".length) || undefined : undefined;
  const labels = labelNames.filter((n) => !n.startsWith("stream:"));

  const rawBody = gh.body ?? "";
  const ref = parseRefMarker(rawBody) ?? `#${gh.number}`;
  const status: PlanIssueStatus = gh.state === "closed" ? "verified" : "open";

  return {
    ref,
    title: (gh.title ?? "").trim(),
    stream,
    labels,
    repo: repoFullName,
    status,
    // Record the identity we already have in hand. Recovery is the one path that reads a real GitHub
    // issue, so a rehydrated plan.db comes back ALREADY linked rather than looking freshly-drafted —
    // which would make the next publish offer to create a second issue for every row it just restored.
    ghNumber: gh.number > 0 ? gh.number : undefined,
    ...parseIssueBody(rawBody),
  };
}

/**
 * Recover every PlanIssue from a repo's GitHub issues. Pull requests (the /issues endpoint returns
 * them too) and titleless rows are dropped.
 */
export function recoverIssues(ghIssues: GitHubIssueLike[], repoFullName: string): PlanIssue[] {
  return (ghIssues ?? [])
    .filter((g) => g && !g.pull_request && (g.title ?? "").trim())
    .map((g) => recoverIssue(g, repoFullName));
}

// The recovery ladder — the versions of a record's source the runtime may fall back to when the current
// one does not work.
//
// WHY THE EXISTING GATE WAS NOT ENOUGH. `renderGate`'s `lastGood` already prefers "the last version that
// rendered" over an empty surface, and that is the right instinct — but its memory is per SESSION, and a
// session that has only just booted has none. That is exactly the shape of the 02:00 incident: a designer
// rewrote five rendering-critical records at 01:39, the app was restarted, and on the fresh boot the first
// version of each record the gate ever saw was the broken one. Nothing had rendered yet, so there was
// nothing to fall back TO, and 8 of 9 workspaces render from these records.
//
// The rungs come from the record's own change history, which the Rust stamp boundary now populates with
// the `srcText` each write replaced. That is durable — it is in the store, not in a module-level Map — so
// it survives the restart that empties `lastGood`, and it is the same data `bsc ui revert` restores from.
// Together they mean a bad write degrades the surface it broke instead of the whole app, and the way back
// exists whether or not the record was ever packaged with a seed.
import type { ChangeEntry } from "@/features/designs/lib/model";

/** A record's retained earlier sources, NEWEST-FIRST — the versions to try after the current one fails.
 *
 *  Deduped, because a metadata-only write between two source edits leaves the same bytes reachable twice
 *  and re-compiling an identical source cannot produce a different outcome. Empty when the record has no
 *  history, no retained content, or has only ever been written once.
 *
 *  `current` is excluded when supplied: the ladder is what to try INSTEAD, and offering back the version
 *  that just failed would spend a compile to reach the same error. */
export function recoveryLadder(history: ChangeEntry[] | undefined, current?: string): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  // History is stored oldest-first; walk it backwards so the most recent rung is tried first.
  for (let i = (history?.length ?? 0) - 1; i >= 0; i--) {
    const prev = history?.[i]?.prevSrc;
    if (typeof prev !== "string" || !prev.trim()) continue;
    if (prev === current || seen.has(prev)) continue;
    seen.add(prev);
    out.push(prev);
  }
  return out;
}

/** Does this record have any way back at all? The question the Design Studio asks to warn BEFORE a write,
 *  rather than after: a record with no rung and no packaged seed is one whose next bad write is
 *  unrecoverable, which is the state `graphprimitive` / `kitrenderer` / `insights` were in. */
export function hasRecoveryPath(record: { history?: ChangeEntry[]; builtin?: boolean }): boolean {
  return Boolean(record.builtin) || recoveryLadder(record.history).length > 0;
}

export function reflect(m: number[][]): number[][] {
  const a = m.map((r) => [...r]);
  const n = a[0].length;
  for (const r of a)
    for (let c = 0; c < Math.floor(n / 2); c++) [r[c], r[n - 1 - c]] = [r[n - 1 - c], r[c]];
  return a;
}

