// Agent-relationship graph (#…) — the typed coordination graph over the fleet's
// streams: who produces which artifact, who consumes it, and how each relationship
// is coordinated (director-relayed vs direct peer). Pure (no React/Tauri) so the
// layering + cycle detection are unit-testable; the visualization lives in
// RelationshipGraphView.tsx and the authoring controls in the Structure/Permissions
// focused panes. Mirrors the design prototype (design/bsc · model()).
import { neighborSpotlight } from "@/shared/lib/graph/spotlight";
import { findBackEdges } from "@/shared/lib/graph/cycles";
import { layerDag } from "@/shared/lib/graph/layers";

/** Fleet coordination topology. `director` = hub-and-spoke (every edge routes through
 *  the director), `peer` = mesh (every edge is a direct handoff), `hybrid` = per-edge. */
export type Topology = "director" | "peer" | "hybrid";

/** Relationship kind. The "ordering" kinds (handoff/blocking/sequence/review) impose a
 *  build order and participate in cycle detection + layering; the rest are annotations. */
export type EdgeKind = "handoff" | "blocking" | "sequence" | "review" | "notify" | "mutex" | "shared";

/** Hardness of a relationship: hard wait · proceed-against-a-stub · fire-and-forget. */
export type Hardness = "blocking" | "soft" | "notify";

/** How a relationship is coordinated. */
export type Via = "director" | "direct";

export type ArtifactKind = "schema" | "contract" | "types" | "tokens" | "fixture" | "other";

/** A produced contract/schema/types another stream consumes — the coord `contract:<id>` ref. */
export interface RelationshipArtifact {
  id: string;
  name: string;
  kind: ArtifactKind;
  producer: string;           // stream id
  consumers: string[];        // stream ids
  status?: "pending" | "ready";
}

/** A typed relationship edge between two streams. */
export interface AgentRelationship {
  id: string;
  from: string;               // upstream stream id
  to: string;                 // downstream stream id
  kind: EdgeKind;
  artifact?: string;          // RelationshipArtifact.id for handoff/shared
  hardness: Hardness;
  via: Via;
  note?: string;
}

/** Minimal stream shape the graph needs (a projection of AgentStream). */
export interface RelStream {
  id: string;
  role?: string;
  repo?: string;
  owns?: string[];
}

/** An edge with its effective `via` resolved against the fleet topology. */
export interface ResolvedEdge extends AgentRelationship { viaEff: Via }

export interface RelationshipGraph {
  streams: RelStream[];
  artifacts: RelationshipArtifact[];
  edges: ResolvedEdge[];
  /** Stream ids, in declaration order. */
  sids: string[];
  /** Topological layer per stream id (0 = a source). Back-edges are excluded so a cycle
   *  doesn't blow up the layering. */
  layerOf: Record<string, number>;
  /** True when an ordering-edge cycle exists (a coordination deadlock). */
  hasCycle: boolean;
  /** Ids of the edges that close a cycle (the back-edges) — rendered red + block the gate. */
  cycleEdgeIds: Set<string>;
}

/** Ordering kinds — they impose build order, so they drive cycle detection + layering. */
const ORDERING: ReadonlySet<EdgeKind> = new Set<EdgeKind>(["handoff", "blocking", "sequence", "review"]);

/** Resolve an edge's effective `via` against the topology (director/peer force it; hybrid keeps it). */
export function effectiveVia(topology: Topology, via: Via): Via {
  return topology === "director" ? "director" : topology === "peer" ? "direct" : via;
}

/**
 * Build the relationship graph from the fleet's streams, declared artifacts, and edges,
 * under a coordination topology. Detects ordering cycles (DFS back-edges) and assigns
 * topological layers (shared longest-path layerer, excluding back-edges so a cycle can't
 * explode the layout).
 */
export function buildRelationshipGraph(
  streams: RelStream[],
  artifacts: RelationshipArtifact[],
  edges: AgentRelationship[],
  topology: Topology,
): RelationshipGraph {
  const sids = streams.map((s) => s.id);
  const resolved: ResolvedEdge[] = edges.map((e) => ({ ...e, viaEff: effectiveVia(topology, e.via) }));

  // ── cycle detection FIRST (DFS back-edges over ordering edges) — shared graph-core primitive (#2217) ──
  const { backEdgeIds: cycleEdgeIds, hasCycle } = findBackEdges(sids, resolved.filter((e) => ORDERING.has(e.kind)));

  // ── layering over ordering edges, EXCLUDING back-edges (keeps it a DAG) — shared layerer (#2214) ──
  const layerOf = layerDag(sids, resolved.filter((e) => ORDERING.has(e.kind)), cycleEdgeIds);

  return { streams, artifacts, edges: resolved, sids, layerOf, hasCycle, cycleEdgeIds };
}

// ── display metadata (shared by the view + the inspector) ──────────────────────

export const EDGE_KIND_META: Record<EdgeKind, { color: string; label: string; glyph: string }> = {
  handoff:  { color: "var(--accent)",        label: "handoff",  glyph: "⤚" },
  blocking: { color: "var(--info)",          label: "blocking", glyph: "⏸" },
  sequence: { color: "var(--fg-dim)",        label: "sequence", glyph: "→" },
  notify:   { color: "var(--fg-muted)",      label: "notify",   glyph: "◇" },
  mutex:    { color: "var(--danger)",        label: "mutex",    glyph: "⚠" },
  shared:   { color: "var(--violet)",        label: "shared",   glyph: "↔" },
  review:   { color: "oklch(0.70 0.14 350)", label: "review",   glyph: "✓" },
};

export const ARTIFACT_COLOR: Record<ArtifactKind, string> = {
  schema: "var(--success)", contract: "var(--info)", types: "var(--violet)",
  tokens: "var(--accent)", fixture: "var(--fg-muted)", other: "var(--fg-muted)",
};

export const DIRECTOR_COLOR = "oklch(0.70 0.14 350)";

export const ROLE_COLOR: Record<string, string> = {
  worker: "var(--accent)", tester: "var(--success)", reviewer: "var(--violet)",
  planner: "var(--info)", director: DIRECTOR_COLOR,
};

/** Dash + width per hardness (solid hard, dashed soft, dotted notify). */
export function hardStyle(h: Hardness): { dash: string; w: number } {
  return h === "blocking" ? { dash: "", w: 2.0 } : h === "soft" ? { dash: "6 4", w: 1.6 } : { dash: "2 4", w: 1.4 };
}

/** Human label for a hardness (the inspector + tooltips). */
export function hardLabel(h: Hardness): string {
  return h === "blocking" ? "hard wait" : h === "soft" ? "stub & reconcile" : "fire & forget";
}

/** Resting opacity per edge kind — handoff/blocking read bold, quieter kinds recede (swimlanes). */
export function restOpacity(kind: EdgeKind): number {
  return kind === "handoff" || kind === "blocking" ? 0.95 : kind === "sequence" ? 0.55 : kind === "notify" ? 0.4 : 0.5;
}

/** The one-line runtime note for an edge — how the relationship is enforced at fleet time. */
export function runtimeNote(e: ResolvedEdge): string {
  const map: Record<EdgeKind, string> = {
    // #3931: these used to advertise `bsc-blocked --on`, a command removed with #1039 and never
    // replaced — an agent that tried to run it got "command not found". Enforcement is now the LAUNCH
    // gate: `${e.to}` is not started until `${e.from}` lands, and a started worker never parks.
    handoff:  `${e.to} starts once ${e.from} lands contract:${e.artifact ?? "…"} (launch gate).`,
    blocking: `${e.to} is held at launch until ${e.from}'s work lands (launch gate).`,
    shared:   "co-owned interface — both streams notified on change.",
    review:   `${e.to}'s output reviewed before merge (role/flow gate).`,
    notify:   `event only — pings ${e.to}, never blocks.`,
    mutex:    "serialized — validated against owns[] glob overlap.",
    sequence: "pure ordering via dependsOn.",
  };
  return (e.viaEff === "director" ? "[via director] " : "[peer latch] ") + (map[e.kind] || "");
}

/** What the user is focused on — a stream lane, an edge, or an artifact. */
export type RelFocus = { type: "agent" | "edge" | "art"; id: string } | null;

export interface Spotlight {
  active: boolean;
  focusId?: string;
  focusType?: "agent" | "edge" | "art";
  /** Stream ids drawn bright; everything else dims. */
  brightStreams: Set<string>;
  /** Edge ids drawn lit. */
  litEdges: Set<string>;
  /** Artifact ids drawn lit. */
  litArtifacts: Set<string>;
}

/**
 * Resolve the spotlight for a focus (hover or pinned): which streams/edges/artifacts to
 * brighten and which to dim. An agent focus lights itself + its neighbors and every edge it
 * touches; an edge lights its endpoints; an artifact lights its producer + consumers and its
 * handoff edges. Pure — drives the swimlane opacities and is unit-testable.
 */
export function computeSpotlight(g: RelationshipGraph, focus: RelFocus): Spotlight {
  if (!focus) return { active: false, brightStreams: new Set(), litEdges: new Set(), litArtifacts: new Set() };
  const brightStreams = new Set<string>();
  const litEdges = new Set<string>();
  const litArtifacts = new Set<string>();
  if (focus.type === "agent") {
    const sp = neighborSpotlight(g.edges, focus.id);
    sp.litNodes.forEach((n) => brightStreams.add(n));
    sp.litEdges.forEach((id) => litEdges.add(id));
    for (const a of g.artifacts) if (a.producer === focus.id || a.consumers.includes(focus.id)) litArtifacts.add(a.id);
  } else if (focus.type === "edge") {
    const e0 = g.edges.find((e) => e.id === focus.id);
    if (e0) { brightStreams.add(e0.from); brightStreams.add(e0.to); litEdges.add(e0.id); if (e0.kind === "handoff" && e0.artifact) litArtifacts.add(e0.artifact); }
  } else {
    const a0 = g.artifacts.find((a) => a.id === focus.id);
    if (a0) {
      brightStreams.add(a0.producer); a0.consumers.forEach((c) => brightStreams.add(c)); litArtifacts.add(a0.id);
      for (const e of g.edges) if (e.kind === "handoff" && e.artifact === focus.id) litEdges.add(e.id);
    }
  }
  return { active: true, focusId: focus.id, focusType: focus.type, brightStreams, litEdges, litArtifacts };
}

// Relay self-test — the "Test relay" probe behind Settings → Mobile tunnel (#930).
//
// Pairing depends on three independent things working, and a single pass/fail hides
// WHICH one is broken. So the probe runs three distinct legs and reports each:
//   1. reach — the relay answers `GET /health` and identifies itself (DNS/TLS/HTTP +
//      "is this actually a tunnel relay?").
//   2. join  — a WebSocket upgrade to `/connect` is accepted into a room (the Durable
//      Object path, not just the static health endpoint).
//   3. relay — two peers in the same room can exchange a frame end-to-end (the blind
//      pipe the Noise handshake itself rides on). We can't run a real Noise IK handshake
//      solo — that needs the phone — so we loopback a nonce host→guest, which exercises
//      exactly the forwarding path the handshake uses.
//
// Transport-free: `fetch` and the WebSocket factory are injected, so the orchestration
// is unit-testable without a live relay (see relayProbe.test.ts).

/**
 * Map a user-entered relay URL (any of `http(s)://` / `ws(s)://`, with or without a
 * scheme or trailing slash) to its `https` `/health` probe endpoint. The relay serves
 * `/health` over plain HTTPS GET (the `wss://` form is only for the tunnel upgrade), so
 * the Test button normalizes to `https` before probing.
 */
export function relayHealthUrl(relayUrl: string): string {
  const trimmed = relayUrl.trim().replace(/\/+$/, "");
  const normalized = trimmed
    .replace(/^wss:\/\//i, "https://")
    .replace(/^ws:\/\//i, "http://");
  const withScheme = /^https?:\/\//i.test(normalized) ? normalized : `https://${normalized}`;
  return `${withScheme}/health`;
}

/** Normalize a relay URL to its `wss`/`ws` base (no path) for the `/connect` upgrade. */
export function relayWsBase(relayUrl: string): string {
  const trimmed = relayUrl.trim().replace(/\/+$/, "");
  const normalized = trimmed
    .replace(/^https:\/\//i, "wss://")
    .replace(/^http:\/\//i, "ws://");
  return /^wss?:\/\//i.test(normalized) ? normalized : `wss://${normalized}`;
}

/** Build a `/connect?room=&role=` upgrade URL for a probe peer. */
export function relayConnectUrl(relayUrl: string, room: string, role: "host" | "guest"): string {
  return `${relayWsBase(relayUrl)}/connect?room=${encodeURIComponent(room)}&role=${role}`;
}

/**
 * A throwaway, well-formed room id (base64url, within the relay's 16–64 char window).
 * High-entropy so the probe never collides with a live pairing room; the room idle-times
 * out on its own and we close our sockets immediately, so it leaves nothing behind.
 */
export function freshRoomId(): string {
  const bytes = new Uint8Array(24);
  crypto.getRandomValues(bytes);
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

export type LegStatus = "pending" | "running" | "ok" | "fail" | "skip";
export interface ProbeLeg {
  status: LegStatus;
  detail?: string;
}
export interface ProbeLegs {
  reach: ProbeLeg;
  join: ProbeLeg;
  relay: ProbeLeg;
}
export interface ProbeResult {
  legs: ProbeLegs;
  /** Relay version reported by `/health`, when reachable. */
  version?: string;
}

/** The legs at the moment the probe starts: reachability running, the rest queued. */
export function emptyLegs(): ProbeLegs {
  return { reach: { status: "running" }, join: { status: "pending" }, relay: { status: "pending" } };
}

/** The minimal WebSocket surface the probe uses — the browser `WebSocket` satisfies it. */
export interface MinimalSocket {
  onopen: ((ev: unknown) => void) | null;
  onmessage: ((ev: { data: unknown }) => void) | null;
  onerror: ((ev: unknown) => void) | null;
  onclose: ((ev: unknown) => void) | null;
  send(data: string): void;
  close(code?: number, reason?: string): void;
}

export interface ProbeDeps {
  fetchFn: typeof fetch;
  makeSocket: (url: string) => MinimalSocket;
  /** Per-leg deadline. */
  timeoutMs: number;
  /** Override for tests; defaults to {@link freshRoomId}. */
  genId?: () => string;
  /** Fired after every leg-status change so the UI can update progressively. */
  onLeg?: (legs: ProbeLegs) => void;
}

const SERVICE_ID = "msc-tunnel-relay";

/**
 * Run the three-leg relay probe against `target`. Resolves once a leg fails (skipping the
 * rest) or all three pass; never rejects — every failure is reported as a leg detail.
 */
export async function runRelayProbe(target: string, deps: ProbeDeps): Promise<ProbeResult> {
  const genId = deps.genId ?? freshRoomId;
  const legs = emptyLegs();
  const emit = () => deps.onLeg?.({ reach: { ...legs.reach }, join: { ...legs.join }, relay: { ...legs.relay } });

  // Leg 1 — reachability + identity via /health.
  let version: string | undefined;
  const reachOk = await (async (): Promise<boolean> => {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), deps.timeoutMs);
    try {
      const res = await deps.fetchFn(relayHealthUrl(target), { signal: ctrl.signal });
      if (!res.ok) {
        legs.reach = { status: "fail", detail: `relay returned HTTP ${res.status}` };
        return false;
      }
      const body = (await res.json().catch(() => null)) as { service?: string; version?: string } | null;
      if (body?.service !== SERVICE_ID) {
        legs.reach = { status: "fail", detail: "reachable, but not a tunnel relay" };
        return false;
      }
      version = body.version;
      legs.reach = { status: "ok", detail: version ? `v${version}` : undefined };
      return true;
    } catch (e) {
      const aborted = e instanceof DOMException && e.name === "AbortError";
      legs.reach = { status: "fail", detail: aborted ? "timed out" : "could not reach relay" };
      return false;
    } finally {
      clearTimeout(timer);
    }
  })();
  emit();
  if (!reachOk) {
    legs.join = { status: "skip" };
    legs.relay = { status: "skip" };
    emit();
    return { legs, version };
  }

  // Legs 2 & 3 — open a host socket (join), then a guest socket in the same room and
  // loopback a nonce through the relay (relay). Both sockets are closed when we settle.
  legs.join = { status: "running" };
  emit();
  await new Promise<void>((resolve) => {
    const room = genId();
    const nonce = genId();
    const host = deps.makeSocket(relayConnectUrl(target, room, "host"));
    let guest: MinimalSocket | null = null;
    let done = false;

    const timer = setTimeout(() => {
      if (legs.join.status === "running") {
        legs.join = { status: "fail", detail: "room join timed out" };
        legs.relay = { status: "skip" };
      } else if (legs.relay.status === "running") {
        legs.relay = { status: "fail", detail: "no relayed frame (timed out)" };
      }
      settle();
    }, deps.timeoutMs);

    const settle = () => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      try { host.close(1000); } catch { /* already closing */ }
      try { guest?.close(1000); } catch { /* already closing */ }
      emit();
      resolve();
    };

    host.onerror = () => {
      if (legs.join.status === "running") {
        legs.join = { status: "fail", detail: "room join failed" };
        legs.relay = { status: "skip" };
      }
      settle();
    };
    host.onopen = () => {
      legs.join = { status: "ok" };
      legs.relay = { status: "running" };
      emit();
      guest = deps.makeSocket(relayConnectUrl(target, room, "guest"));
      guest.onerror = () => {
        legs.relay = { status: "fail", detail: "second peer couldn't join the room" };
        settle();
      };
      guest.onmessage = (ev) => {
        if (typeof ev.data === "string" && ev.data === nonce) {
          legs.relay = { status: "ok" };
          settle();
        }
      };
      guest.onopen = () => {
        try {
          host.send(nonce);
        } catch {
          legs.relay = { status: "fail", detail: "could not send a probe frame" };
          settle();
        }
      };
    };
  });

  return { legs, version };
}

// Rename a PUBLISHED project (#1226) — the pure decision + the apply step, extracted from
// Planning.tsx so the guard + the GitHub-board update are unit-testable. Renaming updates the
// board title + the local display name but KEEPS the frozen session key / on-disk folder (#2409:
// renames are display-only — the folder keeps its birth-slug; reopening under the new name goes
// through the reopen-mismatch modal, which can do the real on-disk move).

import { projectSlug } from "@/shared/lib/core/projectPaths";

/** Update a published GitHub Project (V2) board title; leaves milestones/issues untouched. */
export const RENAME_PROJECT_MUTATION = `
  mutation RenameProject($projectId: ID!, $title: String!) {
    updateProjectV2(input: { projectId: $projectId, title: $title }) {
      projectV2 { id title }
    }
  }
`;

export type RenamePlan =
  | { kind: "noop" }
  | { kind: "error"; message: string }
  | { kind: "rename"; title: string };

/**
 * Decide what a rename commit should do, given the raw input, the current name + project id, and
 * the OTHER projects' frozen keys (for the duplicate guard). Trimmed empty / unchanged / no-id all
 * no-op; a name that slugifies onto another project's key is an error; otherwise rename.
 */
export function planRename(
  raw: string,
  currentName: string,
  projectId: string | null,
  otherKeys: ReadonlySet<string>,
): RenamePlan {
  const next = raw.trim();
  if (!next || next === currentName || !projectId) return { kind: "noop" };
  // Keys are name-derived slugs (#2409): a rename whose slug lands on another project's key would
  // make the two names resolve to ONE hub at reopen — block it here.
  if (otherKeys.has(projectSlug(next))) {
    return { kind: "error", message: "Another project already uses that name." };
  }
  return { kind: "rename", title: next };
}

export interface RenameDeps {
  /** The GitHub GraphQL bridge (injected for tests). */
  graphql: (query: string, variables: Record<string, unknown>) => Promise<unknown>;
  /** Update local project meta (name/repo/number/repos). */
  setMeta: (id: string, name: string, repo: string, number: number, repos: string[]) => void;
  repo: string;
  number: number;
  repos: string[];
}

/**
 * Apply a planned rename: update LOCAL state first (graceful — the planner reflects the rename even
 * if GitHub is unreachable, mirroring how delete removes locally on a GitHub failure), then push the
 * board title. Returns an error message when the GitHub update failed (local is already updated and
 * the rename is retryable), else `null`.
 */
export async function applyRename(projectId: string, title: string, deps: RenameDeps): Promise<string | null> {
  deps.setMeta(projectId, title, deps.repo, deps.number, deps.repos);
  try {
    await deps.graphql(RENAME_PROJECT_MUTATION, { projectId, title });
    return null;
  } catch {
    return "Renamed locally; the GitHub board update failed — edit again to retry.";
  }
}

// render-preview pipeline (#528/#531) — the flagship builtin. Reads the UI stage's
// skeleton artifacts, bundles them (previewBundle #530), and surfaces the iframe
// srcdoc so PlanPreviewPane renders the mock UI live in the planning page.
//
// 2D and 3D share one transport: a 3D skeleton just renders an r3f <Canvas>
// (react-three-fiber is externalized + resolved via esm.sh), so `mode` only tunes the
// pane chrome. The dispatch glue runs the stage module through the engine (#529) and
// writes the result to the store; #533 wires the triggers (tag / watch / manual).

import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { bundleSkeleton, buildPreviewSrcDoc } from "@/features/planner/preview/previewBundle";
import { type StageContext, type StageRunResult } from "@/features/planner/preview/stageRun";
import { registerStageModule } from "@/features/planner/preview/stageCommands";

export type PreviewMode = "2d" | "3d";
export interface PreviewOutput { srcDoc: string; mode: PreviewMode; screen?: string }

export const RENDER_PREVIEW_ID = "render-preview";

/** Pick the screen entry: ctx.entry if it's a real file, else the first source file. */
export function resolveEntry(artifacts: Record<string, string>, entry?: string): string | null {
  if (entry && artifacts[entry] != null) return entry;
  const src = Object.keys(artifacts).filter((k) => /\.(jsx|tsx|js|ts)$/.test(k));
  return src[0] ?? null;
}

/** The render-preview stage helper: bundle the UI skeleton into an iframe srcDoc. Runs by
 *  direct dispatch (#897 Phase 4c removed the generic engine); never throws. */
export async function renderPreviewHandler(ctx: StageContext): Promise<StageRunResult> {
  const artifacts = ctx.artifacts as Record<string, string>;
  const entry = resolveEntry(artifacts, ctx.entry);
  if (!entry) return { status: "fail", message: "render-preview: no screen file in the skeleton" };
  const mode: PreviewMode = ctx.mode === "3d" ? "3d" : "2d";
  const js = await bundleSkeleton(artifacts, entry);
  const srcDoc = buildPreviewSrcDoc(js);
  return { status: "ok", output: { srcDoc, mode } satisfies PreviewOutput };
}

/**
 * Run render-preview for a project and reflect the result in the store: the bundled
 * srcdoc (→ the preview pane) and the run status. Calls the handler directly.
 */
export async function dispatchRenderPreview(args: {
  projectKey: string; stageId?: string; artifacts: Record<string, string>; entry?: string; mode?: PreviewMode; screen?: string;
}): Promise<StageRunResult> {
  const store = useAppStore.getState();
  store.setStageRun(args.projectKey, RENDER_PREVIEW_ID, { status: "running", lastRun: null });
  const ctx: StageContext = {
    projectKey: args.projectKey, stageId: args.stageId ?? "ui", artifacts: args.artifacts,
    entry: args.entry, mode: args.mode,
  };
  let result: StageRunResult;
  try { result = await renderPreviewHandler(ctx); }
  catch (e) { result = { status: "fail", message: String(e) }; }
  if (result.status === "ok" && result.output) {
    // Tag the stored preview with the screen so the pane's approve button targets it (#546).
    store.setStagePreview(args.projectKey, { ...(result.output as PreviewOutput), screen: args.screen ?? args.entry });
  }
  store.setStageRun(args.projectKey, RENDER_PREVIEW_ID, { status: result.status, lastRun: Date.now(), message: result.message });
  return result;
}

// Register render-preview as the first command module. Its `run` reads the project's
// .ui-skeleton and dispatches a render for the requested screen/mode — the behavior the
// <ui_preview> tag triggers today. Richer commands (save/confirm/persist, navigation)
// are render-preview's OWN later behavior; the bus stays generic. Idempotent on import.
registerStageModule({
  id: RENDER_PREVIEW_ID,
  async command(cmd, ctx) {
    if (cmd !== "run") return; // other commands are this stage module's future behavior
    const screen = ctx.args.screen || undefined;
    const mode: PreviewMode = ctx.args.mode === "3d" ? "3d" : "2d";
    const files = await invoke<[string, string][]>("read_ui_skeleton", { projectKey: ctx.projectKey });
    if (files.length === 0) return;
    await dispatchRenderPreview({
      projectKey: ctx.projectKey, artifacts: Object.fromEntries(files), entry: screen, mode, screen,
    });
  },
});

// The tree layout (#3270) — a pure, deterministic placement of parent-pointer nodes for the SVG TreeView.
// Split out of the renderer so the renderer file exports only its component (fast-refresh) and the layout
// is unit-testable on its own. Works for any tree shape (a BST, or a complete binary heap): each LEAF takes
// the next horizontal slot; each internal node is CENTERED over its children; depth (distance from the
// root) drives the vertical position. Both axes are scaled + padded to fit a TREE_VIEW × TREE_VIEW viewBox.

/** The svg viewBox is VIEW × VIEW. */
export const TREE_VIEW = 320;
const PAD = 34; // inset so nodes don't touch the frame edge

/** The layout input — a node's stable id + its parent id (absent / out-of-set ⇒ a root). */
export interface LayoutNode {
  id: string;
  parent?: string;
}

/**
 * Place every node at `{ x, y }` in the viewBox. Leaves are laid left→right in child order; a parent sits
 * centered over the span of its children; `y` grows with depth from the root. Pure + deterministic — a
 * missing / dangling `parent` makes a node a root (multiple roots lay out left-to-right in one row band).
 * An empty input yields an empty map.
 */
export function treeLayout(nodes: readonly LayoutNode[]): Record<string, { x: number; y: number }> {
  const pos: Record<string, { x: number; y: number }> = {};
  if (nodes.length === 0) return pos;

  const ids = new Set(nodes.map((n) => n.id));
  const children = new Map<string, string[]>();
  for (const n of nodes) children.set(n.id, []);
  const roots: string[] = [];
  for (const n of nodes) {
    if (n.parent !== undefined && ids.has(n.parent)) children.get(n.parent)!.push(n.id);
    else roots.push(n.id);
  }

  const depth = new Map<string, number>();
  const rawX = new Map<string, number>();
  let slot = 0;
  // Iterative post-order (an explicit stack avoids recursion-depth limits on a degenerate chain).
  const place = (rootId: string): void => {
    const stack: { id: string; d: number; phase: 0 | 1 }[] = [{ id: rootId, d: 0, phase: 0 }];
    while (stack.length) {
      const top = stack[stack.length - 1];
      const kids = children.get(top.id) ?? [];
      if (top.phase === 0) {
        depth.set(top.id, top.d);
        top.phase = 1;
        // Descend into children first (they claim their x before the parent centers over them).
        for (let i = kids.length - 1; i >= 0; i--) stack.push({ id: kids[i], d: top.d + 1, phase: 0 });
      } else {
        stack.pop();
        if (kids.length === 0) rawX.set(top.id, slot++);
        else rawX.set(top.id, (rawX.get(kids[0])! + rawX.get(kids[kids.length - 1])!) / 2);
      }
    }
  };
  for (const r of roots) place(r);

  const maxX = Math.max(1, slot - 1);
  const maxD = Math.max(1, ...depth.values());
  const inner = TREE_VIEW - 2 * PAD;
  for (const n of nodes) {
    const rx = rawX.get(n.id) ?? 0;
    const d = depth.get(n.id) ?? 0;
    pos[n.id] = {
      x: slot <= 1 ? TREE_VIEW / 2 : PAD + (rx / maxX) * inner,
      y: PAD + (d / maxD) * inner,
    };
  }
  return pos;
}

// Reopen a published project by DERIVATION, not lookup (#2409). A project's key is the slug of its
// name — so opening a board project resolves its local hub as `projectSlug(title)` directly, with no
// node-id → key alias table (the bridge that got the raw title in the "video game" bug and made
// recovery read the wrong hub). When no hub sits at that key, the ONE job the alias used to do is an
// explicit one-time choice instead: link an existing local project (a real on-disk move onto the
// name key, `relink_project_hub`) or start fresh. Pure — the modal + invoke live in
// ReopenProjectModal.tsx.

import { projectSlug, sanitizeProjectKey } from "@/shared/lib/core/projectPaths";
import type { LocalProjectLite } from "@/features/planner/list/drafts";

/** The derivation result for reopening a board project named `title` (#2409). */
export interface ReopenResolution {
  /** The canonical name-derived key — `projectSlug(title)`. */
  key: string;
  /** The local hub already at that key, when it exists (open directly — the normal case). */
  hub: LocalProjectLite | null;
  /**
   * When `hub` is null: every local hub as a link candidate, best-first — the legacy
   * title-sanitized key (`sanitizeProjectKey(title)`, the pre-#1741 folder key) first, then
   * case-insensitive title matches, then the rest by recency.
   */
  candidates: LocalProjectLite[];
  /**
   * The candidate to preselect in the link modal: an exact legacy-key or title match, else null
   * (never auto-suggest an unrelated hub).
   */
  suggested: LocalProjectLite | null;
}

/**
 * Resolve where a board project named `title` lives locally. Recovery is derivation: the key IS
 * `projectSlug(title)`; a hub at that key means open-in-place. Anything else is the reopen-mismatch
 * case the modal resolves (#2409).
 */
export function resolveReopen(title: string, locals: LocalProjectLite[]): ReopenResolution {
  const key = projectSlug(title);
  const safe = Array.isArray(locals) ? locals : [];
  const hub = safe.find((lp) => lp.key === key) ?? null;
  if (hub) return { key, hub, candidates: [], suggested: null };

  const legacyKey = sanitizeProjectKey(title);
  const titleNorm = title.trim().toLowerCase();
  const score = (lp: LocalProjectLite): number =>
    lp.key === legacyKey ? 0 : lp.title.trim().toLowerCase() === titleNorm ? 1 : 2;
  const candidates = [...safe].sort((a, b) => score(a) - score(b) || b.updatedAt - a.updatedAt);
  const suggested = candidates.length > 0 && score(candidates[0]) < 2 ? candidates[0] : null;
  return { key, hub: null, candidates, suggested };
}

// Repo-scoped GitHub credentials (#158) — the GitHub-proxy axis of per-session
// isolation. A session for repo A, given a repo-A-scoped token, makes its GitHub API
// calls with that token (not the global PAT), so it can't act on other repos via the
// proxy. The resolution is purely a function of the request path + the assigned tokens,
// so it's transport-free and unit-testable. (Filesystem/git confinement is separate.)

/**
 * The `owner/name` a GitHub REST path targets, or `null` when it isn't repo-scoped
 * (e.g. `user/repos`, `users/x/events`). Tolerates a leading slash and a query string.
 */
export function repoFromGitHubPath(path: string): string | null {
  const m = /^\/?repos\/([^/]+)\/([^/?#]+)/.exec(path);
  return m ? `${m[1]}/${m[2]}` : null;
}

/**
 * Resolve the token for a request: the repo-scoped credential when the path targets a
 * repo that has one assigned, otherwise the global token. Matching is case-insensitive
 * on the `owner/name` (GitHub repo names are case-insensitive).
 */
export function resolveGithubToken(
  path: string,
  repoTokens: Record<string, string>,
  globalToken: string,
): string {
  const repo = repoFromGitHubPath(path);
  return tokenForRepo(repo, repoTokens, globalToken);
}

/**
 * Resolve the token for a session bound to a specific `owner/name` repo: the
 * repo-scoped credential when one is assigned, otherwise the global token. This is
 * the session axis of #158 — a worker/triage pane is launched with this token as its
 * `GH_TOKEN`, so its `gh`/`git` operations carry a fine-grained, repo-scoped credential
 * (when assigned) and can't act on sibling repos. Matching is case-insensitive on the
 * `owner/name` (GitHub repo names are case-insensitive). A null/empty `repo` (a console
 * with no bound repo, the director) falls back to the global token.
 */
export function tokenForRepo(
  repo: string | null | undefined,
  repoTokens: Record<string, string>,
  globalToken: string,
): string {
  if (!repo) return globalToken;
  const lower = repo.toLowerCase();
  for (const [k, v] of Object.entries(repoTokens)) {
    if (v && k.toLowerCase() === lower) return v;
  }
  return globalToken;
}

// Live GitHub → Repo Pulse data (#413). PURE mappers from GitHub REST payloads to
// the typed Pulse shapes (data/repoPulse.ts) — no fleet inference, just what the
// API returns. The fetch orchestration lives in hooks/useRepoPulse.ts; these
// functions are framework-free and unit-tested with payload fixtures.
//
// Bot vs human is GitHub's own signal (account `type === "Bot"` / `[bot]` login),
// NOT fleet-agent attribution (that's the Fleet page, #412).

import type {
  VelocitySlice, ChurnArea, ChurnFile, Contributor, Workflow, Branch, BranchStatusKey,
} from "@/shared/data/repoPulse";
import { dayWindow, windowedTally, type DayWindow } from "@/shared/lib/algorithms/windowedTally";
import { loginColor } from "@/shared/lib/core/format";

// ── GitHub payload shapes (subset of the fields we use) ──────────────────────
export interface GhAccount { login: string; type?: string }
export interface GhCommitItem {
  sha: string;
  commit: { message: string; author: { name: string; date: string } | null };
  author: GhAccount | null;
}
export interface GhCommitFile { filename: string; additions: number; deletions: number; changes: number; status?: string }
export interface GhCommitDetail extends GhCommitItem {
  stats?: { additions: number; deletions: number; total: number };
  files?: GhCommitFile[];
}
export interface GhPull {
  number: number;
  title: string;
  user: GhAccount | null;
  created_at: string;
  merged_at: string | null;
  draft: boolean;
  state: string;
  head: { ref: string };
}
export interface GhBranchItem { name: string; commit: { sha: string } }
export interface GhWorkflowItem { id: number; name: string; path: string; state: string }
export interface GhRun {
  id: number; name: string; conclusion: string | null; status: string;
  created_at: string; updated_at: string; workflow_id: number;
}
export interface GhCompare { ahead_by: number; behind_by: number }

// ── bot detection (GitHub's own signal) ──────────────────────────────────────
export function isBot(acct: GhAccount | null, fallbackName = ""): boolean {
  const login = acct?.login ?? fallbackName;
  return acct?.type === "Bot" || /\[bot\]$/i.test(login);
}

// ── day bucketing ─────────────────────────────────────────────────────────────
// Both live in `shared/lib/algorithms/windowedTally` since #3465 — the generic, dependency-free
// version the algorithms graph also ships as a node. Re-exported here so this module's long-standing
// public surface (and `repoPulseLive.test.ts`) is unchanged; there is one implementation, not two.
export { dayWindow, tallyByDay, type DayWindow } from "@/shared/lib/algorithms/windowedTally";
/** Sum values bucketed by their day — the SUM counterpart to `tallyByDay`'s count. Kept here because it
 *  aggregates a per-event value, not timestamps, so it is not the same algorithm as the shared tally. */
export function sumByDay(win: DayWindow, entries: Array<{ date: string; value: number }>): number[] {
  const idx = new Map(win.keys.map((k, i) => [k, i]));
  const out = new Array(win.keys.length).fill(0);
  for (const e of entries) {
    const i = idx.get(e.date.slice(0, 10));
    if (i !== undefined) out[i] += e.value;
  }
  return out;
}

// ── velocity (commits + PRs per day) ──────────────────────────────────────────
export function mapVelocity(
  commits: GhCommitItem[], pulls: GhPull[], details: GhCommitDetail[], days: number, now: Date,
): VelocitySlice {
  // The three COUNT series share one window (#3465) — that is what makes them aligned by construction
  // rather than by three separate calls happening to agree.
  const { labels, series } = windowedTally(
    {
      commits: commits.map(c => c.commit.author?.date),
      opened: pulls.map(p => p.created_at),
      merged: pulls.map(p => p.merged_at),
    },
    days,
    now,
  );
  // adds/dels are SUMS of a per-event value, not counts, so they keep `sumByDay` over the same window.
  const win = dayWindow(days, now);
  const adds = sumByDay(win, details.flatMap(d => d.commit.author?.date && d.stats ? [{ date: d.commit.author.date, value: d.stats.additions }] : []));
  const dels = sumByDay(win, details.flatMap(d => d.commit.author?.date && d.stats ? [{ date: d.commit.author.date, value: d.stats.deletions }] : []));
  return { labels, commits: series.commits, opened: series.opened, merged: series.merged, adds, dels };
}

// ── churn by top-level area + hottest files (from bounded commit details) ─────
/** Group a file path into a display "area": `crates/<x>` two deep, else `<top>/`. */
export function areaOf(path: string): string {
  const seg = path.split("/");
  if (seg[0] === "crates" && seg.length > 1) return `crates/${seg[1]}`;
  if (seg.length > 1) return `${seg[0]}/`;
  return "(root)";
}
const AREA_COLORS = ["var(--accent)", "var(--info)", "var(--success)", "oklch(0.7 0.12 290)", "oklch(0.7 0.06 90)", "var(--fg-dim)"];

export function mapChurnAreas(details: GhCommitDetail[]): ChurnArea[] {
  const acc = new Map<string, { add: number; del: number; files: Set<string> }>();
  for (const d of details) for (const f of d.files ?? []) {
    const a = areaOf(f.filename);
    const e = acc.get(a) ?? { add: 0, del: 0, files: new Set<string>() };
    e.add += f.additions; e.del += f.deletions; e.files.add(f.filename);
    acc.set(a, e);
  }
  return [...acc.entries()]
    .map(([area, e]) => ({ area, add: e.add, del: e.del, files: e.files.size, color: "" }))
    .sort((a, b) => (b.add + b.del) - (a.add + a.del))
    .slice(0, 6)
    .map((a, i) => ({ ...a, color: AREA_COLORS[i % AREA_COLORS.length] }));
}

export function mapHottestFiles(details: GhCommitDetail[], topN = 16): ChurnFile[] {
  const acc = new Map<string, number>();
  for (const d of details) for (const f of d.files ?? []) {
    acc.set(f.filename, (acc.get(f.filename) ?? 0) + f.additions + f.deletions);
  }
  return [...acc.entries()]
    .map(([p, w]) => ({ p, w }))
    .sort((a, b) => b.w - a.w)
    .slice(0, topN);
}

// ── contributors (bot vs human, GitHub-attributed) ───────────────────────────
export function mapContributors(commits: GhCommitItem[], details: GhCommitDetail[]): Contributor[] {
  const acc = new Map<string, { bot: boolean; commits: number; add: number; del: number }>();
  const keyOf = (c: GhCommitItem) => c.author?.login ?? c.commit.author?.name ?? "unknown";
  for (const c of commits) {
    const k = keyOf(c);
    const e = acc.get(k) ?? { bot: isBot(c.author, c.commit.author?.name), commits: 0, add: 0, del: 0 };
    e.commits += 1;
    acc.set(k, e);
  }
  for (const d of details) {
    const k = keyOf(d);
    const e = acc.get(k);
    if (e && d.stats) { e.add += d.stats.additions; e.del += d.stats.deletions; }
  }
  return [...acc.entries()]
    .map(([name, e]) => ({ name, bot: e.bot, commits: e.commits, add: e.add, del: e.del, color: e.bot ? "var(--accent)" : loginColor(name) }))
    .sort((a, b) => b.commits - a.commits);
}

// ── CI health + per-workflow pass rate ────────────────────────────────────────
export interface CiHealth { passRate: number; runs: number; passed: number; failed: number; cancelled: number; avgMin: number }
const FAIL = new Set(["failure", "timed_out", "startup_failure"]);
export function mapCI(runs: GhRun[], workflows: GhWorkflowItem[]): { ci: CiHealth; workflows: Workflow[] } {
  const done = runs.filter(r => r.status === "completed");
  const passed = done.filter(r => r.conclusion === "success").length;
  const failed = done.filter(r => r.conclusion && FAIL.has(r.conclusion)).length;
  const cancelled = done.filter(r => r.conclusion === "cancelled").length;
  const decisive = passed + failed;
  const durMin = (r: GhRun) => (new Date(r.updated_at).getTime() - new Date(r.created_at).getTime()) / 60000;
  const avgMin = done.length ? round1(done.reduce((s, r) => s + durMin(r), 0) / done.length) : 0;
  const ci: CiHealth = {
    passRate: decisive ? Math.round((passed / decisive) * 100) : 0,
    runs: done.length, passed, failed, cancelled, avgMin,
  };
  const byWf = new Map<number, { name: string; runs: number; pass: number; mins: number[] }>();
  const wfName = new Map(workflows.map(w => [w.id, w.name]));
  for (const r of done) {
    const w = byWf.get(r.workflow_id) ?? { name: wfName.get(r.workflow_id) ?? r.name, runs: 0, pass: 0, mins: [] };
    w.runs += 1;
    if (r.conclusion === "success") w.pass += 1;
    w.mins.push(durMin(r));
    byWf.set(r.workflow_id, w);
  }
  const wf: Workflow[] = [...byWf.values()]
    .map(w => ({ name: w.name, runs: w.runs, pass: w.runs ? Math.round((w.pass / w.runs) * 100) : 0, min: w.mins.length ? round1(w.mins.reduce((a, b) => a + b, 0) / w.mins.length) : 0 }))
    .sort((a, b) => b.runs - a.runs);
  return { ci, workflows: wf };
}
function round1(n: number): number { return Math.round(n * 10) / 10; }

// ── review latency (merged PR open→merge) ─────────────────────────────────────
export function mapReviewLatency(pulls: GhPull[]): Array<{ label: string; v: number }> {
  const buckets = [
    { label: "<30m", v: 0 }, { label: "30m–1h", v: 0 }, { label: "1–3h", v: 0 },
    { label: "3–8h", v: 0 }, { label: "8h+", v: 0 },
  ];
  for (const p of pulls) {
    if (!p.merged_at) continue;
    const h = (new Date(p.merged_at).getTime() - new Date(p.created_at).getTime()) / 3_600_000;
    const i = h < 0.5 ? 0 : h < 1 ? 1 : h < 3 ? 2 : h < 8 ? 3 : 4;
    buckets[i].v += 1;
  }
  return buckets;
}
/** Median merge latency (hours) over merged PRs, or 0. */
export function medianLatencyH(pulls: GhPull[]): number {
  const hs = pulls.filter(p => p.merged_at)
    .map(p => (new Date(p.merged_at as string).getTime() - new Date(p.created_at).getTime()) / 3_600_000)
    .sort((a, b) => a - b);
  if (!hs.length) return 0;
  const mid = Math.floor(hs.length / 2);
  return round1(hs.length % 2 ? hs[mid] : (hs[mid - 1] + hs[mid]) / 2);
}

// ── active branches ───────────────────────────────────────────────────────────
const BRANCH_COLORS = ["var(--accent)", "var(--info)", "var(--success)", "oklch(0.7 0.12 290)", "oklch(0.7 0.06 90)", "var(--fg-dim)"];
export function mapBranches(
  branches: GhBranchItem[], pulls: GhPull[], compares: Record<string, GhCompare>, defaultBranch: string,
): Branch[] {
  const prByRef = new Map<string, GhPull>();
  for (const p of pulls) if (p.state === "open" && !prByRef.has(p.head.ref)) prByRef.set(p.head.ref, p);
  return branches.map((b, i) => {
    const pr = prByRef.get(b.name);
    const cmp = compares[b.name];
    const owner = pr?.user?.login ?? "";
    const status: BranchStatusKey =
      b.name === defaultBranch ? "integration"
      : pr ? (pr.draft ? "draft" : "open-pr")
      : "commit-only";
    return {
      n: b.name, owner, bot: isBot(pr?.user ?? null),
      ahead: cmp?.ahead_by ?? 0, behind: cmp?.behind_by ?? 0,
      status, age: "", color: BRANCH_COLORS[i % BRANCH_COLORS.length],
    };
  });
}

// ── KPIs ──────────────────────────────────────────────────────────────────────
export interface PulseKpis {
  commitsWeek: number; prsMerged: number; netLines: number; passRate: number;
  reviewLatencyH: number; contributors: number; botShare: number;
}
export function deriveKpis(
  velocity: VelocitySlice, ci: CiHealth, pulls: GhPull[], contributors: Contributor[], now: Date,
): PulseKpis {
  // Last-7-day slices of the (up to 14-day) velocity series.
  const last7 = <T,>(a: T[]) => a.slice(-7);
  const sum = (a: number[]) => a.reduce((s, v) => s + v, 0);
  const within7 = (iso: string | null) => !!iso && (now.getTime() - new Date(iso).getTime()) <= 7 * 86_400_000;
  const botCommits = contributors.filter(c => c.bot).reduce((s, c) => s + c.commits, 0);
  const allCommits = contributors.reduce((s, c) => s + c.commits, 0);
  return {
    commitsWeek: sum(last7(velocity.commits)),
    prsMerged: pulls.filter(p => within7(p.merged_at)).length,
    netLines: sum(last7(velocity.adds)) - sum(last7(velocity.dels)),
    passRate: ci.passRate,
    reviewLatencyH: medianLatencyH(pulls.filter(p => within7(p.merged_at))),
    contributors: contributors.length,
    botShare: allCommits ? Math.round((botCommits / allCommits) * 100) : 0,
  };
}

