// README generation (#848 / #1710): turn whatever plan content exists at publish into a thorough,
// badge-topped README. Pure + unit-tested; `handlePublish` applies the output (a planner that
// authored a richer README is preferred over this at publish). Stack-aware Getting-started commands
// come from the shared matcher in `stackTopics.ts`.

import { gettingStartedCmds } from "@/features/planner/lib/stackTopics";

/** The repo's short name — the segment after the last `/`. */
function shortName(fullName: string): string {
  const i = fullName.lastIndexOf("/");
  return i >= 0 ? fullName.slice(i + 1) : fullName;
}

/** A planned feature, reduced to what the README renders. */
export interface ReadmeFeature {
  name: string;
  behavior?: string;
}

export interface ReadmeOpts {
  /** `owner/repo`. */
  fullName: string;
  /** Concise repo description / tagline (the project goal's first line). */
  description: string;
  /** The full goal prose → the Overview section (falls back to `description`). */
  goal?: string;
  /** The scope section text → a Scope section (omitted when absent). */
  scope?: string;
  /** The architecture section text → an Architecture section (omitted when absent). */
  architecture?: string;
  /** The planned features → a bulleted Features section (omitted when empty). */
  features?: ReadmeFeature[];
  /** The stack section text (verbatim, for the Tech stack section). */
  stackText?: string;
  /** Workflow filenames under `.github/workflows/` (e.g. `["ci.yml"]`) → CI status badges. */
  workflows?: string[];
  /** Default branch the badges point at. */
  defaultBranch?: string;
}

/**
 * Build a thorough README with badges, driven by whatever plan content is available at publish.
 * Sections render only when their input is present (graceful fallbacks), in this order: Overview
 * (full goal), Scope, Features, Tech stack, Architecture, Getting started, Contributing, License.
 * Badges: one CI status badge per workflow file, plus license + last-commit shields.
 */
export function buildReadme(opts: ReadmeOpts): string {
  const { fullName, description, goal, scope, architecture, features = [], stackText, workflows = [], defaultBranch = "main" } = opts;
  const [owner, repo] = fullName.split("/");
  const name = shortName(fullName);
  const clean = (s?: string) => (s ?? "").trim();

  const badges: string[] = [];
  for (const wf of workflows) {
    const label = wf.replace(/\.ya?ml$/i, "");
    badges.push(`[![${label}](https://github.com/${owner}/${repo}/actions/workflows/${wf}/badge.svg)](https://github.com/${owner}/${repo}/actions/workflows/${wf})`);
  }
  badges.push(`![License](https://img.shields.io/github/license/${owner}/${repo})`);
  badges.push(`![Last commit](https://img.shields.io/github/last-commit/${owner}/${repo})`);

  const lines = [
    `# ${name}`,
    "",
    badges.join(" "),
    "",
    description || "_A base-studio-code project._",
    "",
    "## Overview",
    "",
    clean(goal) || description || "Describe what this project does and who it's for.",
    "",
  ];

  if (clean(scope)) {
    lines.push("## Scope", "", clean(scope), "");
  }

  const feats = features.filter((f) => f && f.name && f.name.trim());
  if (feats.length) {
    lines.push("## Features", "");
    for (const f of feats) {
      const b = clean(f.behavior);
      lines.push(b ? `- **${f.name.trim()}** — ${b}` : `- **${f.name.trim()}**`);
    }
    lines.push("");
  }

  if (clean(stackText)) {
    lines.push("## Tech stack", "", clean(stackText), "");
  }

  if (clean(architecture)) {
    lines.push("## Architecture", "", clean(architecture), "");
  }

  lines.push(
    "## Getting started",
    "",
    "```bash",
    `git clone https://github.com/${owner}/${repo}.git`,
    `cd ${name}`,
    ...gettingStartedCmds(clean(stackText)),
    "```",
    "",
    "## Contributing",
    "",
    "See [CONTRIBUTING.md](CONTRIBUTING.md) and our [Code of Conduct](CODE_OF_CONDUCT.md).",
    "",
    "## License",
    "",
    "See [LICENSE](LICENSE).",
    "",
    "---",
    "",
    "_Scaffolded by base-studio-code._",
  );
  void defaultBranch; // reserved for branch-pinned badges if needed later
  return lines.join("\n");
}

// The charter a request session launches with (#one-request-one-debug-session) — kept out of the
// component file so it is directly testable and so the mount stays a component-only module.
export { requestPaneId } from "@/shared/lib/session/requestSpawn";

// ── The debug-session constants (#debug-nodes-hang-off-the-session-that-filed-them) ────────────────
//
// These used to live in `DebugSessionMount`, the STANDING debug session's component. That session and
// its node are gone — every request draws its own — but the two constants below are not about the
// standing session at all: they are what ANY debug session launches with. They moved here, beside the
// only thing that still uses them, rather than being kept alive by a component that no longer mounts.
//
// `DEBUG_START_PROMPT` did NOT move. It was the standing session's queue-serving half ("claim the next
// request"), and a per-request session must never claim — the app claimed for it, and a second claim
// would take a request another session already holds.

export const DEBUG_INIT_CMD = "claude";

/** The shared DEBUG-session prose: who the session is, what it may touch, and the workflow + git rules
 *  every one of them follows. It deliberately says NOTHING about how the session gets its work — the
 *  charter below supplies that, naming the one request this session was spawned for. */
export const DEBUG_ROLE_PROMPT =
  "You are the base-studio-code DEBUG session. You have full read/write access to THIS repository and " +
  "run the normal dev workflow. Your job: improve the `bsc ui` surface so the Design Studio's designer " +
  "session never needs permissions outside it. Reproduce the cited `bsc` command, " +
  "implement the fix in the owning crate with tests, verify the gate (cargo check + clippy --all-targets " +
  "+ typecheck/lint for any frontend), then `bsc request resolve <id> --note \"<what changed>\"` and " +
  "rebuild the sidecar with " +
  "`cargo build --bin bsc` (the DEV profile — release is the slow one and nothing local needs it). The app " +
  "re-stages that binary and retires its warm `bsc` on its own the moment your request resolves, so the fix " +
  "is live for the next call with NO restart — do not ask for one. Do your work in a git worktree under " +
  "`.claude/worktrees/<branch>/` on a branch off develop and open a PR — NEVER commit/push to develop or " +
  "main directly, and never switch the main checkout off develop.";

/** What a request session needs to know about the request it was spawned for. A subset of the
 *  `bsc request` row (snake_case from the Rust store), so a caller passes the row through. */
export interface RequestBrief {
  id: number;
  /** WHO filed it — the filing session's pane id (#debug-request-carries-its-origin), e.g.
   *  `designer-studio:react`. Absent when the request was filed outside a session. */
  origin?: string | null;
  /** The label form of the request, always populated by the store (explicit `--title`, else derived
   *  from the text). */
  display_title?: string | null;
}

/** The ROLES a studio pane id can name, longest first so `sound-designer` is matched before `designer`
 *  could ever claim its tail. Each maps to how the charter says it in prose. */
const ORIGIN_ROLES: readonly (readonly [string, string])[] = [
  ["sound-designer", "sound designer"],
  ["designer", "designer"],
  ["librarian", "librarian"],
  ["architect", "architect"],
  ["integrator", "integrator"],
];

/** The human name for a filing session's pane id — `design-studio:designer-react` → "the react designer".
 *
 *  READ THE TAIL, NOT THE STUDIO. The first version of this split on `:` and treated the left half as the
 *  role (`<role>-studio`), which is wrong for every session: the studio is named for the SURFACE
 *  (`design-studio`, `algorithms-studio`, `teams-studio`, `sound-studio`, `integration-studio`) and the
 *  role lives in the tail (`designer-react`, `librarian-typescript`, `architect`). It cost nothing to
 *  write and would have mislabelled every request, because the tests quoted the same invented shape.
 *
 *  Derived rather than looked up: the id is the only thing the request carries, and importing the session
 *  registry here would make the charter depend on a store-touching module to phrase one sentence. An
 *  unrecognised shape falls back to the raw id — a project director's `myproject:director` reads as
 *  itself, which is more use to a debug session than no attribution at all. */
export function originLabel(origin: string): string {
  const tail = (origin ?? "").split(":")[1] ?? "";
  for (const [role, human] of ORIGIN_ROLES) {
    if (tail === role) return `the ${human}`;
    if (tail.startsWith(`${role}-`)) return `the ${tail.slice(role.length + 1)} ${human}`;
  }
  return origin;
}

/**
 * The charter for the session working request `req`.
 *
 * It names the request instead of telling the session to go and find one. Under #3535 every pool
 * session launched generic and ran `bsc request claim` on startup, because a slot had no request until
 * it won the race; now the APP claims first and spawns a session for what it got, so the session starts
 * already knowing its job. That removes the whole warming/losing-the-race state — and with it the
 * reaper that existed to clean up after it.
 *
 * The session does NOT claim: its request is already `claimed` (the app did that atomically to obtain
 * the id), and one session exists per request by construction, so there is nothing left to race for.
 *
 * IT ALSO NAMES WHO FILED IT (#debug-request-carries-its-origin). A debug session is spawned BY a
 * studio session hitting a gap, and the fix is only right if it unblocks THAT session's actual workflow
 * — a `bsc ui` gap the React designer hit is a different fix from the same message arriving from
 * nowhere. The origin is on the request, so the charter states it and tells the session it may reply on
 * the thread; without that the relationship exists only in the graph, where the session working the
 * request cannot see it.
 *
 * The closing instruction is deliberate and carried over unchanged: a request must never be left open
 * with no explanation — "filed and silently unworked" is the failure this whole feature exists to
 * remove — and the resolve note IS the change log the maintainer reads back.
 */
export function requestCharter(req: RequestBrief): string {
  const { id } = req;
  const title = req.display_title?.trim();
  const origin = req.origin?.trim();
  const heading = title ? `YOUR REQUEST IS #${id} — "${title}".` : `YOUR REQUEST IS #${id}.`;
  const filedBy = origin
    ? `It was filed by ${originLabel(origin)} (\`${origin}\`) — a session that hit this gap in real work, ` +
      `not a hypothetical. Fix it so THAT session is unblocked: the failing command on the request is what ` +
      `it actually tried. If you need something from them, or the fix changes how the surface is used, ` +
      `reply on the request's thread — \`bsc request note ${id} "<what you found>" --from debugger\` — which ` +
      `they read back with \`bsc request get ${id}\`.\n\n`
    : "";
  return (
    `${DEBUG_ROLE_PROMPT}\n\n` +
    `${heading} It is already claimed for you — do not run \`bsc request claim\`. ` +
    `Read it, then work ONLY that one:\n` +
    `  bsc request get ${id}\n\n` +
    filedBy +
    `Reproduce the failing command, implement the fix in the owning crate with tests, verify the gate, ` +
    `then:\n` +
    `  bsc request resolve ${id} --note "<what you changed>"\n\n` +
    `The note is the change log — always leave one, even if it turns out NOT to be a defect (resolve it ` +
    `anyway with a note saying why; a request must never be left open with no explanation). Then STOP — ` +
    `your session is done and will be closed once #${id} reads resolved.`
  );
}

// RequestSessionsMount (#one-request-one-debug-session) — one debug session per request, bound to it.
//
// Each cycle: CLAIM every open request (atomically, one `bsc request claim` per request), then hold one
// session per claimed request, named for it (`debug-studio:req-<id>`), and close each when ITS request
// resolves. There is no pool, no cap, no pacing and no reaper — see `poolPlan.ts` for what each of those
// was for and why 1:1 removes the need.
//
// WHY THE MOUNT CLAIMS, rather than the session. `bsc request claim` takes the OLDEST open request; it
// cannot be pointed at a specific id. So the only way to bind a session to a KNOWN request is to claim
// first and spawn for whatever came back. That the claim is atomic is what makes this safe beside the
// standing debug session, which self-serves the same queue: whoever claims first holds it, and the other
// simply never sees it as open. No charter change was needed there, and none was made.
//
// It obeys a plan and decides nothing: `planRequestSessions` owns the gate and the reconcile. This mount
// is mechanics — claim, apply the plan (seed each session's charter, close finished ones, publish the
// live ids for the Glance graph).
//
// ── WHAT MAKES THIS SAFE TO SHIP ────────────────────────────────────────────────────────────────────
//  * UNCONDITIONAL (#debug-nodes-hang-off-the-session-that-filed-them) — the `autoSpawnDebugSessions`
//    toggle is gone. It defaulted OFF, which shipped this whole 1:1 machinery switched off: a request
//    was filed and then waited for someone to notice. The one remaining gate is not a preference —
//    `debug_repo_root` must resolve, because a shipped binary with no source tree cannot run these.
//  * EVERY session is a VISIBLE NODE in the Glance graph, labelled with its request and edged to the
//    session that filed it. That is what makes an app-started session supervisable: the user can see
//    it, open it, and stop it. It is the reason the ids are published below.
//  * The only role it can start is the plan's — `debugger` — and every pane is under the
//    `debug-studio:` prefix, so it is full-capability + role-less (#3520).
//  * Sessions launch FRESH (`claude`, never `--continue`) with `paneContinue: false` (#3497): each is
//    bound to one request and must never inherit another conversation.
//  * NOT bounded by a cap any more — a deliberate trade, recorded in `poolPlan.ts`. Concurrency is the
//    number of unresolved claimed requests.
import { useEffect, useRef, useState } from "react";
import { useAppStore } from "@/store";
import { bscJson, bscRun } from "@/shared/lib/core/bsc";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { usePoll } from "@/shared/hooks/usePoll";
import { Box } from "@/shared/ui/layout/Box";
import { TerminalSlot } from "@/app/console/terminal/TerminalSlot";
import { planRequestSessions, type RequestSession, type RequestRow } from "@/shared/lib/session/poolPlan";
import { requestPaneId, requestIdFromPaneId } from "@/shared/lib/session/requestSpawn";
import { requestCharter, DEBUG_INIT_CMD } from "@/features/debug/requestSession";

/** How often to reconcile against the queue. Slow on purpose: a request is not urgent, and a session
 *  that is already working one is not waiting on this loop. */
const POLL_MS = 20_000;

/** A raw row from `bsc request list --json` (snake_case from the Rust store). */
interface RawRequest {
  id: number;
  status: string;
  claimed_by?: string | null;
  /** WHO filed it (#debug-request-carries-its-origin) — the filing session's pane id. Carried through
   *  to the charter so the spawned session knows whose workflow it is unblocking, and read by the
   *  Glance graph to hang this session's node off that session. */
  origin?: string | null;
  /** Always populated by the store (explicit `--title`, else derived from the text). */
  display_title?: string | null;
}

/**
 * Holds one session per open request. Renders nothing visible; each session's terminal is shown by
 * opening its node in the Glance graph.
 */
export function RequestSessionsMount() {
  // undefined = still resolving; null = no source tree (shipped binary — never launch into a missing
  // cwd); string = the repo root these sessions work in.
  const [repoRoot, setRepoRoot] = useState<string | null | undefined>(undefined);
  // The request sessions this mount tracks. Kept in a ref too so the poll reconciles against the latest
  // set without re-subscribing the interval (the ref is synced in an effect, never during render).
  const [sessions, setSessions] = useState<RequestSession[]>([]);
  const sessionsRef = useRef<RequestSession[]>([]);
  useEffect(() => { sessionsRef.current = sessions; }, [sessions]);
  // The last queue read, kept so the published node specs carry each request's origin + title.
  const [rows, setRows] = useState<RawRequest[]>([]);

  useEffect(() => {
    let alive = true;
    void safeInvoke<string | null>("debug_repo_root", undefined, null, () => {}).then((root) => {
      if (alive) setRepoRoot(root);
    });
    return () => { alive = false; };
  }, []);

  // #3522: review the queue ONCE per app start and drop completed (resolved) requests, so a long-dead
  // row cannot linger as a node. Keyed to mount rather than to a toggle transition (there is no toggle
  // any more) and never to the poll; `bscRun` is fire-and-forget (a missing binary is a no-op).
  useEffect(() => { void bscRun(null, ["request", "prune"]); }, []);

  // The reconcile loop, once per poll. `bscJson`/`bscRun` swallow a missing binary or verb and return the
  // fallback, so a machine without a working `bsc` simply never spawns rather than erroring in a loop.
  usePoll(
    async () => {
      if (!repoRoot) return;

      // 1 — CLAIM every open request, one atomic claim each, so that by the time the plan runs each has
      // a definite id to be bound to. Bounded by the open count read first, so a request the claim loop
      // itself creates could never spin it.
      //
      // NO `--by`. It stamps the holder at claim time, and the holder here is a pane named FOR the
      // request the claim is about to return — the id is not known until after. Nothing needs the stamp:
      // the binding is the pane name (`requestIdFromPaneId`), which is derived rather than recorded and
      // so cannot go stale. A `null` claim means the queue drained under us (the standing debug session
      // took the last one), which is exactly the race the atomic claim exists to make safe.
      const open = (await bscJson<RawRequest[]>(null, ["request", "list", "--json"], []))
        .filter((r) => r.status === "open");
      for (let i = 0; i < open.length; i += 1) {
        const claimed = await bscJson<RawRequest | null>(null, ["request", "claim", "--json"], null);
        if (!claimed) break;
      }

      // 2 — PLAN + APPLY against the post-claim queue.
      const raw = await bscJson<RawRequest[]>(null, ["request", "list", "--json"], []);
      const requests: RequestRow[] = raw.map((r) => ({ id: r.id, status: r.status, claimedBy: r.claimed_by ?? null }));
      const plan = planRequestSessions({ requests, sessions: sessionsRef.current, enabled: true });

      // Free the store fields of every closed pane, so a stopped session leaves nothing behind.
      if (plan.close.length) {
        useAppStore.setState((st) => {
          const prompts = { ...st.paneStartupPromptText };
          const cont = { ...st.paneContinue };
          for (const paneId of plan.close) { delete prompts[paneId]; delete cont[paneId]; }
          return { paneStartupPromptText: prompts, paneContinue: cont };
        });
      }

      // A CLOSE means a request just resolved, and a resolved `bsc` request means the session very
      // likely rebuilt the binary. Re-stage it and retire the warm child so the fix is LIVE for the next
      // `bsc` call — the last mile of "a designer's request gets processed live", which without this
      // ends in a manual app restart no matter how fast the fix was.
      //
      // Fire-and-forget: a failed reload must not stop the mount reconciling. It is also safe to call
      // when nothing was rebuilt (staging is an idempotent copy) and in a release bundle (a no-op), so
      // it does not need to know WHY the session closed.
      if (plan.close.length) {
        void safeInvoke<[string, string | null][]>("reload_sidecars", undefined, [], () => {});
      }

      if (plan.start.length) {
        // The rows by id, so the charter can name the request and the session that filed it
        // (#debug-request-carries-its-origin). Read from `raw` — the post-claim list — because that is
        // the read that already happened; a session started without its origin would be told nothing
        // about whose workflow it is unblocking, and the relationship would exist only in the graph.
        const byId = new Map(raw.map((r) => [r.id, r]));
        // Seed the launch fields TerminalView reads: the charter naming THIS request (baked as
        // --initial-message) and paneContinue=false (#3497 — never resume; each session is bound to one
        // request and must not inherit another conversation).
        useAppStore.setState((st) => {
          const prompts = { ...st.paneStartupPromptText };
          const cont = { ...st.paneContinue };
          for (const id of plan.start) {
            const row = byId.get(id);
            prompts[requestPaneId(id)] = requestCharter({
              id,
              origin: row?.origin ?? null,
              display_title: row?.display_title ?? null,
            });
            cont[requestPaneId(id)] = false;
          }
          return { paneStartupPromptText: prompts, paneContinue: cont };
        });
      }
      setSessions([...plan.sessions, ...plan.start.map((id) => ({ paneId: requestPaneId(id) }))]);
      // Publish the ROWS, not just the ids (#debug-nodes-hang-off-the-session-that-filed-them): the
      // graph needs each request's origin and title to label its node and edge it to the session that
      // filed it, and this poll is the only place that already holds them.
      setRows(raw);
    },
    POLL_MS,
    [repoRoot],
  );

  // Publish the live REQUESTS so the Glance graph can render a node per request. Without this the
  // sessions run with no node — unopenable, unsupervisable, unstoppable.
  //
  // The published value carries the ORIGIN and TITLE alongside the id
  // (#debug-nodes-hang-off-the-session-that-filed-them), because the node is labelled `debug - <title>`
  // and edged to the session that filed it. A bare id could do neither, which is why every request node
  // used to be called `debugger-req-<n>` and drawn to the designer regardless of who actually filed it.
  const setActiveDebugRequests = useAppStore((s) => s.setActiveDebugRequests);
  useEffect(() => {
    const live = new Map(rows.map((r) => [r.id, r]));
    setActiveDebugRequests(
      sessions
        .map((s) => requestIdFromPaneId(s.paneId))
        .filter((n): n is number => n != null)
        .map((id) => ({ id, origin: live.get(id)?.origin ?? null, title: live.get(id)?.display_title ?? null })),
    );
  }, [sessions, rows, setActiveDebugRequests]);

  if (!repoRoot || !sessions.length) return null;
  return (
    <Box
      aria-hidden
      style={{
        position: "absolute", left: -99999, top: 0, width: 800, height: 600,
        overflow: "hidden", pointerEvents: "none", display: "flex", flexDirection: "column",
      }}
    >
      {sessions.map((s) => (
        <TerminalSlot
          key={s.paneId}
          paneId={s.paneId}
          primary
          parked
          visible={false}
          initialCwd={repoRoot}
          initCmd={DEBUG_INIT_CMD}
        />
      ))}
    </Box>
  );
}

// Request-session identity (#one-request-one-debug-session). A debug session is bound 1:1 to the
// REQUEST it was spawned for, so the request id IS its identity: one number names the request, its PTY
// pane, and its node on the Glance graph.
//
// It used to name a POOL SLOT (#3535): sessions launched generic and claimed a request only after
// starting, so a slot — a small stable integer with no meaning — was the only identity available before
// the claim landed. Assignment removes that gap. The slot existed to paper over a race that no longer
// happens, and a stable-but-meaningless integer is exactly what made a running session hard to connect
// back to the work it was doing.
//
// The spawn DECISION lives in `poolPlan.ts` (pure, tested); this module is only identity, imported by the
// mount (`RequestSessionsMount`), the Glance graph (`studioProject`), and the team augment (`team.ts`) —
// none of which may reach into the others — so it sits here in shared.

/** The PTY pane id for the session working request `id`. Under the `debug-studio:` prefix so it is
 *  full-capability like the standing debug session (`isFullCapabilitySession`, #3520) — the prefix, not
 *  the singleton id, is what that predicate keys on. */
export function requestPaneId(id: number): string {
  return `debug-studio:req-${id}`;
}

/** The Glance node id for request `id` — distinct from the pane id because the Studio Network's node ids
 *  are team-position ids; {@link requestIdFromNodeId} is the inverse the graph uses to open the session. */
export function requestNodeId(id: number): string {
  return `debugger-req-${id}`;
}

/** The request behind a graph node, or null when the node is not a request session. */
export function requestIdFromNodeId(nodeId: string): number | null {
  const m = /^debugger-req-(\d+)$/.exec(nodeId);
  return m ? Number(m[1]) : null;
}

/** The request behind a PANE id, or null when the pane is not a request session. The mount tracks
 *  sessions by pane id and needs the request back to reconcile them against the queue. */
export function requestIdFromPaneId(paneId: string): number | null {
  const m = /^debug-studio:req-(\d+)$/.exec(paneId);
  return m ? Number(m[1]) : null;
}

// The resolver (#2637, epic #2606) — the SEAM that composes a theme's overrides over the token
// contract with PROVENANCE + LOUD diagnostics. The applied `vars` are byte-identical to `themeVars`
// today: the contract defaults already live on `:root` via `tokens.css`, so a scope only carries the
// overrides — ZERO visual change. The value it adds is OBSERVABILITY: which tokens a theme governs, and
// any HOLE — a theme var whose value references a `var(--token)` the contract does NOT define, a silent
// no-op the CSS cascade would swallow. `ThemeScope` calls this so a malformed theme YELPS in the log
// instead of failing silently (the fall-loudly principle). The generated + user-override layers slot in
// here in later slices; today the composition is theme-over-default.
import type { CSSProperties } from "react";
import DESCRIPTOR from "@data/ui/style-descriptor.json";
import { themeById, themeVars } from "@/shared/ui/kit/theme";

interface DescriptorShape {
  base?: { name: string }[];
  components?: { tokens?: { name: string }[]; variants?: { tokens?: { name: string }[] }[] }[];
  domain?: { tokens?: { name: string }[] }[];
}

/** Every token NAME the style-descriptor defines (base + component + per-variant + domain) — the set a
 *  theme value may legitimately reference. A `var(--X)` outside it is an uncontracted hole. Computed once. */
export const CONTRACT_TOKENS: ReadonlySet<string> = (() => {
  const d = DESCRIPTOR as DescriptorShape;
  const names = new Set<string>();
  for (const b of d.base ?? []) names.add(b.name);
  for (const c of d.components ?? []) {
    for (const t of c.tokens ?? []) names.add(t.name);
    for (const v of c.variants ?? []) for (const t of v.tokens ?? []) names.add(t.name);
  }
  for (const g of d.domain ?? []) for (const t of g.tokens ?? []) names.add(t.name);
  return names;
})();

/** The `var(--token)` names a CSS value references. */
export function referencedTokens(value: string): string[] {
  const out: string[] = [];
  const re = /var\(\s*(--[a-z0-9-]+)/gi;
  for (let m = re.exec(value); m; m = re.exec(value)) out.push(m[1]);
  return out;
}

/** The HOLES in a theme's `vars` (#2606 fall-loudly): every `var(--X)` a value references where `--X`
 *  is NOT a contract token — a silent no-op the cascade swallows. Sorted + deduped; pure. */
export function themeHoles(vars: Record<string, unknown>): string[] {
  const holes = new Set<string>();
  for (const value of Object.values(vars)) {
    for (const ref of referencedTokens(String(value))) {
      if (!CONTRACT_TOKENS.has(ref)) holes.add(ref);
    }
  }
  return [...holes].sort();
}

export interface ResolvedTheme {
  /** The overrides to apply on a scope / `:root` — byte-identical to `themeVars(id)` (zero visual change). */
  vars: CSSProperties;
  /** Each token the theme governs → "theme". Tokens absent here resolve from the contract default via
   *  the cascade (provenance "default"), so the map is exactly the theme's override set. */
  provenance: Record<string, "theme">;
  /** Uncontracted tokens referenced by the theme's values (holes) — empty when the theme is clean. */
  holes: string[];
}

/** Resolve `themeId` into its applied vars + provenance + holes. Pure. */
export function resolveTheme(themeId: string | undefined): ResolvedTheme {
  const raw = (themeById(themeId).vars ?? {}) as Record<string, unknown>;
  const provenance: Record<string, "theme"> = {};
  for (const token of Object.keys(raw)) provenance[token] = "theme";
  return { vars: themeVars(themeId), provenance, holes: themeHoles(raw) };
}

// ── The JS projection (#3711) — the active theme flattened to CONCRETE values ───────────────────────────
// A component that renders to a NON-CSS surface (canvas / WebGL / a non-web runtime) can't see the CSS
// cascade, so it needs the theme as a plain-JS object of concrete values. `resolveThemeTokens` composes the
// contract defaults with the theme's overrides and dereferences every `var(--x)` chain. Pure + off-DOM (NOT
// `getComputedStyle`), so it is unit-testable in vitest AND portable to any runtime. Colors stay CSS strings
// (oklch / hex / color-mix); a numeric-rgb layer for WebGL is a follow-up slice.

interface DescriptorValues {
  base?: { name: string; value?: string }[];
  components?: { tokens?: { name: string; default?: string }[]; variants?: { tokens?: { name: string; default?: string }[] }[] }[];
  domain?: { tokens?: { name: string; value?: string }[] }[];
}

/** The contract's DEFAULT value for every token — base `value` · component/variant `default` · domain
 *  `value` — the `:root` layer a theme composes over. Computed once. */
const CONTRACT_DEFAULTS: Readonly<Record<string, string>> = (() => {
  const d = DESCRIPTOR as DescriptorValues;
  const m: Record<string, string> = {};
  for (const b of d.base ?? []) if (b.value != null) m[b.name] = b.value;
  for (const c of d.components ?? []) {
    for (const t of c.tokens ?? []) if (t.default != null) m[t.name] = t.default;
    for (const v of c.variants ?? []) for (const t of v.tokens ?? []) if (t.default != null) m[t.name] = t.default;
  }
  for (const g of d.domain ?? []) for (const t of g.tokens ?? []) if (t.value != null) m[t.name] = t.value;
  return m;
})();

/** Dereference every `var(--x[, fallback])` in `value` against `map`, recursively — so a reference nested
 *  inside another value (e.g. a `var(--danger)` inside a `color-mix(…)`) flattens too. A cycle, or an
 *  unknown token with no fallback, leaves the `var(…)` literal in place — a hole the cascade would no-op
 *  (`themeHoles` reports contract holes separately; `--mono` and other globals live outside the descriptor). */
function deepDeref(value: string, map: Readonly<Record<string, string>>, seen: ReadonlySet<string>): string {
  return value.replace(/var\(\s*(--[a-z0-9-]+)\s*(?:,\s*([^)]*))?\)/gi, (whole: string, name: string, fallback?: string) => {
    if (seen.has(name)) return fallback != null ? deepDeref(fallback.trim(), map, seen) : whole;
    const next = map[name];
    if (next == null) return fallback != null ? deepDeref(fallback.trim(), map, seen) : whole;
    return deepDeref(next, map, new Set([...seen, name]));
  });
}

/** The active theme flattened to CONCRETE token values — the JS projection a non-CSS component consumes.
 *  Composes {@link CONTRACT_DEFAULTS} with the theme's `vars` overrides, then dereferences every `var(--x)`
 *  chain to a literal. Pure. Colors remain CSS strings (oklch / hex / color-mix). */
export function resolveThemeTokens(themeId: string | undefined): Record<string, string> {
  const merged: Record<string, string> = { ...CONTRACT_DEFAULTS, ...(themeById(themeId).vars ?? {}) };
  const out: Record<string, string> = {};
  for (const name of Object.keys(merged)) out[name] = deepDeref(merged[name], merged, new Set<string>());
  return out;
}

/**
 * Decide which command (if any) to bake into a fresh PTY shell at pane mount.
 *
 * Inputs cover the three layered intents:
 *  - `explicit`: a per-pane `initCmd` override (used by the triage flow before
 *    it moved to `startupPrompt`, and still legal for internal callers).
 *  - `startupPrompt`: when set (triage / fleet kickoff), `pty_create`'s backend
 *    handles the claude launch with the baked prompt — we must NOT also inject
 *    `claude --continue` as init_cmd, or we'd race two claude invocations.
 *  - `paneWasClaude` + `autoResumeClaude` + `wasUncleanShutdown` + `restoreRequested`:
 *    the resume path (#36/#1041). Mount the pane straight into `claude --continue` so
 *    the prior conversation resumes — but ONLY as crash recovery: a clean quit leaves
 *    sessions dormant. Resume when the user clicked "restore" in the crash banner
 *    (`restoreRequested`), OR when they've opted into silent auto-resume
 *    (`autoResumeClaude`) AND the last shutdown was unclean (`wasUncleanShutdown`).
 *    #3937: the `--continue` is emitted with a `|| claude` SHELL fallback. The Rust-side history
 *    guard (#124) lives on `plan_launch`'s PROMPT arm only — the INIT arm (which is what an init
 *    cmd like this takes) passes the string verbatim, so the guard never applied here despite this
 *    doc once claiming it did. A `claude --continue` with no conversation exits 1 having written
 *    ZERO bytes to stdout, which is why a resumed pane looked like a dead `$` prompt rather than a
 *    failed command. The fallback starts a fresh session instead, and works regardless of who is
 *    right about whether history exists.
 */

// #3998: the command itself now lives in `shared/lib/session/ensureClaudeRunning`, because a resume
// can reach a pane by either of two routes — this mount-time launch path, or a direct write into an
// already-live shell (the launch path is unreachable for a pane whose PTY exists). Both must emit the
// byte-identical command, so there is one definition.
import { CONTINUE_OR_FRESH } from "@/shared/lib/session/ensureClaudeRunning";
export function resolveInitCmd(args: {
  explicit: string | undefined;
  startupPrompt: string | undefined;
  /** The pane was launched by a fleet/triage RESUME (`paneContinue`, #3928) — it should pick its
   *  conversation back up. Distinct from the crash-recovery flags below: this is an explicit,
   *  user-initiated resume of a session we know existed, not a guess after an unclean shutdown. */
  continueSession: boolean;
  paneWasClaude: boolean;
  autoResumeClaude: boolean;
  wasUncleanShutdown: boolean;
  restoreRequested: boolean;
}): string {
  const { explicit, startupPrompt, continueSession, paneWasClaude, autoResumeClaude, wasUncleanShutdown, restoreRequested } = args;
  // Explicit overrides win unconditionally — caller knows best.
  if (explicit && explicit.length > 0) return explicit;
  // Triage / fleet launches claude via the prompt-baked path; layering an
  // init_cmd on top would spawn a second claude before the first finishes
  // initialising.
  if (startupPrompt !== undefined) return "";
  // #3928: an explicit fleet/triage RESUME. Without this the flag died in the gap between layers —
  // `fleetStartProject` set `paneContinue`, `TerminalView` forwarded it as `continueSession`, and
  // `plan_launch` then discarded it, because it only reads that flag on the PROMPT arm. A resume
  // carries no startup prompt (that's a kickoff), so the plan fell through to `None` and the pane
  // came up as a bare bash shell: `has_history=true · resumed=false`. Every fleet relaunch was
  // silently starting cold. Placed AFTER the startupPrompt branch so a kickoff still wins.
  // #3986: `continueSession` ALONE. This used to require `paneWasClaude` too, which deadlocked: that
  // flag is set only when claude actually starts (the `claude()` wrapper's OSC 100 `run`), so a pane
  // where claude had never started could never be resumed INTO claude — the gate blocked the launch,
  // the launch was what would have set the flag. Measured: 77 of 78 fleet panes had no
  // `paneWasClaude`, i.e. Resume could not start an agent in any of them, which is the whole of the
  // "sessions come up as bare shells" thread.
  //
  // Safe to drop on both sides. `continueSession` comes from `paneContinue`, set by
  // `fleetStartProject` for FLEET panes, and the call site already forces it false for a manual
  // console (`manual ? false : …`) — so the guard excluded nothing a manual pane needed. And
  // CONTINUE_OR_FRESH degrades on its own (`--continue … || claude`, #3937), so a pane with no prior
  // conversation starts fresh rather than failing: `paneWasClaude` was guarding a case the command
  // already handles.
  if (continueSession) return CONTINUE_OR_FRESH;
  // The resume path — crash recovery only (#1041): a clean quit does NOT auto-resume.
  if (paneWasClaude && (restoreRequested || (autoResumeClaude && wasUncleanShutdown))) {
    return CONTINUE_OR_FRESH;
  }
  return "";
}

// resumeProjectFleet (#glance-resume) — one-click "bring this project's fleet back to life" from the
// Glance graph. It is the progress-gated relaunch the Planner runs (usePlanPublish.launchTriage),
// distilled to what a RESUME of an already-published, already-launched project needs — no publish, no
// sandbox, no quarantine dialog, no UI-pairing re-seed. A project only reaches the Glance network once
// its fleet/triage has launched (useGlanceProjects.filterTriaged), so its worktrees + each worker's
// CLAUDE.local.md already exist on disk; the resume therefore does NOT re-run ensure_worktree (which
// would overwrite the worker scope with a thinner one) — it lets fleetStartProject derive each worker's
// cwd from the existing worktree and resumes the session via `claude --continue` (fleetStartProject
// sets paneContinue on a re-run of an existing build tab).
//
// fleetStartProject itself navigates to the Console and focuses the build tab, so the caller doesn't.

import { useAppStore } from "@/store";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { log } from "@/shared/lib/core/log";
import { bscJson } from "@/shared/lib/core/bsc";
import { bscJsonShared } from "@/shared/lib/core/bscShared";
import { parseFleetFile, withDerivedStreamIssues, type FleetPlan } from "@/features/planner/fleet/planFleet";
import { pruneCompletedStreams, doneIssueRefs } from "@/shared/lib/fleet/streamCompletion";
import { resolveClosedRefs } from "@/features/glance/lib/fleetIssueState";
import { publishFleetRoster } from "@/shared/lib/fleet/fleetRoster";
import type { PlanIssue } from "@/features/planner/issues/planIssues";
import { buildWorkerScope } from "@/features/planner/fleet/workerScope";
import { isAgentWorktreeCwd } from "@/shared/lib/core/projectPaths";
import { parseDependencyManifest, depsForRepo } from "@/features/planner/issues/dependencies";
import { partitionByDeps, heldReason, sessionDoneStreams, type LandedEvidence } from "@/shared/lib/fleet/streamGate";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import { ensureClaudeRunning } from "@/shared/lib/session/ensureClaudeRunning";

export interface ResumeResult {
  ok: boolean;
  /** A user-facing failure reason when `ok` is false. */
  error?: string;
  /** An informational summary of what was (or wasn't) launched — maintenance/no-repo streams. */
  note?: string;
  /** Sessions deliberately NOT relaunched, with why (#3916). The caller SURFACES these — opens their
   *  nodes so the user sees the problem — rather than resuming past them silently. */
  blocked?: BlockedStream[];
  /** Streams HELD by the dependency gate (#3931) — not started because an upstream hasn't landed.
   *  Distinct from `blocked`: nothing is wrong with these, they are simply not their turn yet, so the
   *  caller reports them without opening error nodes. */
  held?: BlockedStream[];
}

/** A session a resume refused to relaunch, and why (#3916). */
export interface BlockedStream {
  streamId: string;
  paneId: string;
  reason: string;
}

/**
 * Is there genuinely NOTHING for a project resume to start (#3923)? True only when every pane is already
 * live or is quarantined — the two states a resume must not touch (a live one is running; a quarantined
 * one is surfaced, never relaunched, #3916).
 *
 * This replaced a guard that bailed on the FIRST live pane, which made ▶ Resume permanently inert once a
 * single node had been resumed on its own: the "turn them all back on" button just switched screens. A
 * live pane is safe to include in the relaunch — `pty_create` reconnects to an existing session and
 * returns before spawning, so it never re-sends `claude --continue` to a running agent.
 */
export function nothingToResume(
  paneIds: readonly string[],
  livePaneIds: ReadonlySet<string>,
  quarantined: Record<string, unknown>,
): boolean {
  if (paneIds.length === 0) return false; // no tab yet ⇒ there IS work (build it)
  return paneIds.every((pid) => livePaneIds.has(pid) || !!quarantined[pid]);
}

/**
 * Split the streams a resume WOULD launch into those that can actually run and those that cannot (#3916).
 * Pure — the IO (worktree existence) is probed by the caller and injected — so the whole rule is
 * exhaustively testable, like {@link planResumeLaunch} beside it.
 *
 * Two blocking conditions, both of which must SURFACE rather than be silently worked around:
 *  · QUARANTINED — the warden hard-paused this worker. Resume used to call `clearProjectQuarantine`,
 *    wiping the warden floor so a prior run's denied command couldn't re-pause it; that discarded the
 *    exact signal the user needs. A quarantined worker now stays quarantined and becomes visible.
 *  · WORKTREE MISSING — #3614: the boot-GC reclaims a merged+clean worktree and the boot reconcile marks
 *    that worker ended. Relaunching it would spawn a session into a NON-EXISTENT cwd — the burst of
 *    doomed sessions that jams the backend. Never launch it; report it.
 */
/**
 * The panes that FINISHED (#4029) — the two ways a worker ends well:
 *   · `bsc-maintain` → `paneMaintaining` (declared: everything I own is done, standing by)
 *   · `bsc-done` → `endedPanes` with a `done` VERDICT, which comes from plan.db owned-issue status
 *     rather than the worker's say-so.
 *
 * `needs-attention` / `blocked` endings are deliberately NOT here: those are endings that want a
 * person, so they stay resumable and keep reporting themselves.
 *
 * Exported so both the project resume and the single-node resume ask the same question — the
 * single-node path had its own hole, and two independent notions of "finished" would drift.
 */
export function completedPanes(store: {
  paneMaintaining: Record<string, boolean>;
  endedPanes: Record<string, { state: string } | undefined>;
}): ReadonlySet<string> {
  const out = new Set<string>();
  for (const [paneId, on] of Object.entries(store.paneMaintaining)) if (on) out.add(paneId);
  for (const [paneId, info] of Object.entries(store.endedPanes)) if (info?.state === "done") out.add(paneId);
  return out;
}

export function partitionResumable(
  streams: Array<{ id: string }>,
  projectKey: string,
  probes: {
    quarantined: Record<string, { summary?: string } | undefined>;
    missingWorktreePanes: ReadonlySet<string>;
    /** Panes that FINISHED (#4029) — declared maintenance, or auto-ended with a `done` verdict. */
    completePanes?: ReadonlySet<string>;
  },
): { resumable: Array<{ id: string }>; blocked: BlockedStream[]; complete: Array<{ id: string }> } {
  const resumable: Array<{ id: string }> = [];
  const blocked: BlockedStream[] = [];
  const complete: Array<{ id: string }> = [];
  for (const st of streams) {
    const paneId = `${projectKey}:${st.id}`;
    const q = probes.quarantined[paneId];
    if (q) {
      blocked.push({ streamId: st.id, paneId, reason: q.summary?.trim() || "quarantined by the warden" });
      continue;
    }
    if (probes.missingWorktreePanes.has(paneId)) {
      blocked.push({ streamId: st.id, paneId, reason: "its worktree is gone and could not be rebuilt (no repo clone?)" });
      continue;
    }
    // FINISHED (#4029) — left alone. Relaunching a worker that has completed everything it owns undoes
    // the reclaim (#4025) and puts an agent back on the model for no reason. It is woken by the thing
    // that has actual work for it: a director `bsc-assign`, which relaunches with the assignment baked
    // in. That is the point of reclaiming it — it comes back FOR A REASON, not because a button was
    // pressed.
    //
    // Its OWN bucket, not `blocked`: blocked means "needs attention" and is reported to the user as
    // such, so filing completions there would make a healthy finished fleet look broken.
    if (probes.completePanes?.has(paneId)) {
      complete.push(st);
      continue;
    }
    resumable.push(st);
  }
  return { resumable, blocked, complete };
}

/**
 * Decide, from a project's fleet plan and its current plan.db issue statuses, exactly which streams to
 * (re)launch on a resume — the SAME progress-gated rule the Planner uses (#1004/#1957): a stream whose
 * every owned issue is done relaunches into MAINTENANCE (stays alive, ready for the director) rather than
 * being skipped; a stream with outstanding work relaunches ACTIVE; a stream with no resolvable repo can't
 * spawn a worktree so it's dropped with a note. Pure (no IO) so it's exhaustively unit-testable.
 */
export function planResumeLaunch(
  fleet: FleetPlan,
  dbIssues: Array<{ ref?: string; stream?: string; status?: string }>,
  /** Refs some OTHER evidence source reports finished — today the GitHub overlay (#4103), in each
   *  stream's own ref spelling. Unioned with plan.db's terminal rows: either source calling a ref done
   *  makes it done, because neither is complete on its own. plan.db knows only what a planner run
   *  authored (nothing, for a hand-assembled fleet); GitHub knows only what a token could reach.
   *  Optional so this stays PURE and exhaustively unit-testable. */
  extraDone: ReadonlySet<string> = new Set(),
): { launchPlan: FleetPlan; maintenanceIds: Set<string>; noRepo: string[]; note?: string } {
  const done = new Set([...doneIssueRefs(dbIssues as PlanIssue[]), ...extraDone]);
  const { active, maintenance } = pruneCompletedStreams(fleet.streams, done);
  const maintenanceIds = new Set(maintenance.map((s) => s.id));
  // A stream with no repo stays visible in the plan but can't get a worktree — drop it here and report it.
  const withRepo = [...active, ...maintenance].filter((st) => st.repo);
  const noRepo = [...active, ...maintenance].filter((st) => !st.repo).map((st) => st.id);
  // Enrich each launched stream's issue list from plan.db (a stream can reach launch with an empty
  // issues[] even though issues name it as their owning stream) so its worker/kickoff sees its tasks.
  const launchable = withDerivedStreamIssues(withRepo, dbIssues);
  const launchPlan: FleetPlan = { ...fleet, streams: launchable };

  const notes: string[] = [];
  if (noRepo.length > 0) {
    notes.push(`${noRepo.length} stream${noRepo.length === 1 ? "" : "s"} (${noRepo.join(", ")}) skipped — no repo assigned`);
  }
  if (maintenance.length > 0) {
    notes.push(`${maintenance.length} completed worker${maintenance.length === 1 ? "" : "s"} `
      + `(${maintenance.map((s) => s.id).join(", ")}) relaunching into maintenance`
      + (active.length > 0 ? `; ${active.length} active` : ""));
  }
  return { launchPlan, maintenanceIds, noRepo, note: notes.length ? notes.join(". ") + "." : undefined };
}

/**
 * Resume a project's whole fleet from the Glance graph. Loads the fleet (a caller-supplied plan when
 * available, else the store mirror, else the project's plan.db), progress-gates it against plan.db issue
 * statuses, clears a stale warden quarantine floor, ensures the director has its standing protocol, and
 * relaunches via `fleetStartProject` — which reopens the `· build` tab (director + one pane per
 * outstanding stream, resuming each with `claude --continue`) and switches to the Console.
 *
 * `fleet` lets the drilled-project caller pass the fleet it already loaded (useProjectFleet) so the
 * resume doesn't re-read plan.db for it. Returns a ResumeResult; a false `ok` carries a user-facing reason.
 */
export async function resumeProjectFleet(opts: {
  projectName: string;
  projectKey: string;
  fleet?: FleetPlan | null;
}): Promise<ResumeResult> {
  const { projectName, projectKey } = opts;
  const store = useAppStore.getState();

  // Guard the #905/#1819 hazard: with no base dir loaded, fleetStartProject would derive every worker's
  // cwd as the user's home. It's loaded well before the user reaches Glance, so this only trips on a
  // race — surface it rather than launch sessions at the wrong dir.
  if (!store.bscBaseDir) {
    return { ok: false, error: "Workspace is still loading — try Resume again in a moment." };
  }

  // 1. Resolve the fleet: caller-supplied → store mirror → the project's own plan.db.
  let fleet: FleetPlan | null = opts.fleet ?? store.planFleet[projectKey] ?? null;
  if (!fleet || fleet.streams.length === 0) {
    const raw = await bscJson<unknown | null>(projectKey, ["plan", "fleet", "get", "--full", "--json"], null);
    fleet = raw ? parseFleetFile(JSON.stringify(raw)) : null;
  }
  if (!fleet || (fleet.streams.length === 0 && !fleet.director.enabled)) {
    return { ok: false, error: "No planned fleet to resume for this project." };
  }
  // Capture the narrowed fleet in a const so its non-null type survives the awaits below.
  const resolvedFleet = fleet;

  // 2. Progress-gate against plan.db.
  // TTL 0 on purpose (#five-callers-one-spawn-for-the-same-plan-read): a resume is a deliberate user
  // action, not a poll, so it must read the plan as it is NOW — a 20-second-old view could relaunch a
  // worker for an issue that has since landed. It still JOINS an in-flight read, which is free and
  // cannot serve stale data.
  const dbIssues = await bscJsonShared<PlanIssue[]>(projectKey, ["plan", "list", "--full", "--json"], [], 0);
  // #4103: plan.db's `issues` table is EMPTY for a fleet assembled outside a full planner run (measured:
  // 40 streams, 0 issue rows), so `doneIssueRefs` returned nothing and NO stream ever read as complete —
  // a relaunch restarted finished workers and maintenance mode (#1957) never engaged. The stream's own
  // refs are the ownership record; GitHub says which are closed. One batched query per repo.
  const closedRefs = await resolveClosedRefs(resolvedFleet.streams);
  const { launchPlan, maintenanceIds, noRepo, note: gateNote } =
    planResumeLaunch(resolvedFleet, dbIssues ?? [], closedRefs);
  if (launchPlan.streams.length === 0 && !launchPlan.director.enabled) {
    return {
      ok: false,
      error: noRepo.length > 0
        ? `No workers to resume — ${noRepo.length} stream${noRepo.length === 1 ? "" : "s"} (${noRepo.join(", ")}) need a repo assigned.`
        : "No workers to resume.",
    };
  }

  // 2b. THE DEPENDENCY GATE (#3931). Until now a resume started every stream at once — 38 simultaneous
  //     `claude --continue` sessions on the live fleet, which is both the lag the user feels and simply
  //     wrong: a stream whose upstream hasn't landed has nothing to build against. `dependsOn` already
  //     carries the graph (plan.db, 37 of 38 populated); this is the launch-time consumer #1039 left
  //     missing. Nothing PARKS — a held stream is never started, and a started one never waits — so
  //     #1039's objection (a parked worker is a worker not working) still stands.
  //
  //     `fleet_landed_streams` is the durable evidence: one `git branch --merged HEAD` per repo. See
  //     streamGate.ts for why the issue-keyed and session-keyed latches are BOTH empty on every live
  //     project and would hang the fleet if trusted alone.
  const [mergedBranches, coord] = await Promise.all([
    safeInvoke<string[]>("fleet_landed_streams", { projectKey }, []),
    readCoordState(),
  ]);
  const evidence: LandedEvidence = {
    doneIssues: new Set([...doneIssueRefs((dbIssues ?? []) as PlanIssue[]), ...closedRefs]),
    mergedBranches: new Set(mergedBranches ?? []),
    // Tier 3: a worker that finished its lane parks in MAINTENANCE (#1957, `bsc-maintain`) — the one
    // per-session completion signal that is actually populated in the live log (34 events, each keyed
    // `<projectKey>:<streamId>`). `readCoordState` returns null on a read failure, in which case tier 3
    // contributes nothing and tiers 1-2 still decide: a failed read must withhold evidence, never
    // fabricate it, or a transient log error would release the whole fleet at once.
    sessionDone: sessionDoneStreams(coord?.state.maintaining ?? [], projectKey),
  };
  const gate = partitionByDeps(launchPlan.streams, evidence);
  // A landed stream relaunches into MAINTENANCE rather than build. This is the same rule
  // `pruneCompletedStreams` applies via issues — extended with branch evidence, which is what makes it
  // work at all on a 0-issue fleet (where nothing was ever routed to maintenance and every stream
  // relaunched into a build it had already finished).
  for (const st of gate.landed) maintenanceIds.add(st.id);
  const heldIds = new Set(gate.held.map((h) => h.streamId));
  const held: BlockedStream[] = gate.held.map((h) => ({
    streamId: h.streamId, paneId: `${projectKey}:${h.streamId}`, reason: heldReason(h),
  }));
  launchPlan.streams = launchPlan.streams.filter((st) => !heldIds.has(st.id));
  if (launchPlan.streams.length === 0 && !launchPlan.director.enabled) {
    const cycle = gate.held.some((h) => h.deadlocked);
    return {
      ok: false,
      error: cycle
        ? "Nothing can start — the fleet's dependsOn graph has a cycle."
        : `Nothing can start yet — all ${held.length} stream${held.length === 1 ? " is" : "s are"} waiting on an upstream.`,
      held,
    };
  }

  // 3. Partition (#3916). Resume relaunches what can actually RUN and SURFACES what cannot, instead of
  //    steamrolling both. This deliberately replaces the old `clearProjectQuarantine` call, which wiped
  //    the warden floor so a prior run's denied command couldn't re-pause a worker — that silently
  //    discarded the one signal the user has to act on.
  const candidateStreams = launchPlan.streams;
  const paneOf = (id: string) => `${projectKey}:${id}`;
  // RECREATE a reclaimed worktree rather than refuse it (#3920). #3614's boot-GC reclaims a merged+clean
  // worktree and the boot reconcile marks that worker ended; #3916 then (correctly) refused to spawn into
  // the missing cwd, which meant a project whose worktrees had all been reclaimed could never resume at
  // all. But nothing is lost in that state: the repo clone and every stream BRANCH still exist, and
  // `ensure_worktree` explicitly reuses a leftover branch — so the worker comes back on its own history.
  // Seed the SAME scope the Planner's launch seeds (`buildWorkerScope` + the repo's locked deps, #1111),
  // or the rebuilt worker would return with a thinner CLAUDE.local.md than it had.
  const depManifest = parseDependencyManifest(
    JSON.stringify(await bscJson<unknown>(projectKey, ["plan", "deps", "get", "--json"], {}) ?? {}),
  ).dependencies;
  const worktreePaths: Record<string, string> = {};
  const unrecoverable = new Set<string>();
  await Promise.all(candidateStreams.map(async (st) => {
    const paneId = paneOf(st.id);
    if (store.quarantinedPanes[paneId]) return;          // quarantine is surfaced, never rebuilt
    const cwd = store.paneCwds[paneId];
    // #3937: reuse a persisted cwd ONLY when it still looks like this agent's own worktree. "The
    // directory exists" is not enough: while a worktree was missing the pane's shell sat in the
    // fallback ancestor (`worktrees/<key>`) and OSC 7 reported that ancestor back into `paneCwds`,
    // so the stored path became one that both exists and is wrong — and an existence check passes
    // for it forever. The shape check re-derives instead, which repairs an already-poisoned pane.
    if (cwd && st.repo && !isAgentWorktreeCwd(cwd, st.repo, st.id)) {
      log.warn(`resume: ${paneId} had a cwd outside its own worktree (${cwd}) — re-deriving (#3937)`);
    } else if (cwd && await safeInvoke<boolean>("dir_exists", { path: cwd }, true)) {
      worktreePaths[st.id] = cwd;                        // still there and still ours — reuse verbatim
      return;
    }
    if (!st.repo) { unrecoverable.add(paneId); return; } // no repo ⇒ no worktree is possible
    const scopeMd = buildWorkerScope(st, depsForRepo(depManifest, st.repo), maintenanceIds.has(st.id));
    const path = await safeInvoke<string>("ensure_worktree",
      { projectKey, repo: st.repo, agentId: st.id, scopeMd }, "");
    if (path) worktreePaths[st.id] = path;
    else unrecoverable.add(paneId);                      // clone missing / git failed — surface it
  }));
  const { resumable, blocked, complete } = partitionResumable(candidateStreams, projectKey, {
    quarantined: store.quarantinedPanes,
    missingWorktreePanes: unrecoverable,
    completePanes: completedPanes(store),
  });
  if (resumable.length === 0 && !launchPlan.director.enabled) {
    return {
      ok: false,
      error: blocked.length > 0
        ? `Nothing resumable — ${blocked.length} session${blocked.length === 1 ? "" : "s"} need attention.`
        : complete.length > 0
          // Not an error state dressed as one: everything finished. Say that, and say what wakes them.
          ? `Nothing to resume — all ${complete.length} worker(s) are complete. The director wakes one when it dispatches work.`
          : "No workers to resume.",
      blocked,
      held,
    };
  }
  // Only the resumable streams launch; the blocked ones keep their quarantine/ended state untouched.
  const resumableIds = new Set(resumable.map((st) => st.id));
  launchPlan.streams = launchPlan.streams.filter((st) => resumableIds.has(st.id));

  // 3b. Clear the ENDED flag for exactly the panes we are relaunching (#3916). Without this the whole
  //     resume was a no-op: `TerminalView` bails before `pty_create` when `endedPanes[paneId]` is set,
  //     and `endedPanes` is persisted — so a worker ended by completion (#920) or by the boot-GC
  //     worktree reconcile (#3614) could never be revived by a project resume. Cleared BEFORE
  //     `fleetStartProject` so the remount it triggers already sees a clean flag.
  store.clearEndedPanes([...resumableIds].map(paneOf));

  // 4. Give the director its standing protocol (bsc-fleet roster + worker Q&A) at the hub.
  if (launchPlan.director.enabled) {
    await safeInvoke("ensure_director_protocol", { projectKey }, undefined, (e) => console.error("director protocol failed:", e));
  }

  // 5. Relaunch. The director's cwd is the hub (resolved authoritatively); each worker's cwd is derived
  //    by fleetStartProject from the EXISTING worktree (no ensure_worktree re-seed — that would overwrite
  //    the worker's CLAUDE.local.md). fleetStartProject reuses the project's build tab in place, bumps its
  //    runId to remount, and switches to the Console.
  const hubPath = await safeInvoke<string>("project_dir_path", { projectKey }, "");
  // #905: hand the AUTHORITATIVE cwds (hub + each rebuilt/reused worktree) to the launch so no pane
  // falls back to a bscBaseDir-derived guess.
  const roster = store.fleetStartProject(projectName, launchPlan, projectKey, { hubPath: hubPath || undefined, worktreePaths });
  publishFleetRoster(projectKey, roster);

  // 6. Revive any pane whose PTY is still alive but idle (#3998).
  //
  //    `fleetStartProject` issues no Tauri commands — it bumps the tab's `runId` and rewrites store
  //    state. That re-keys the pane SLOTS, but `TerminalView` is portal-hosted by `paneId`, so a pane
  //    that never left the tab does not remount, never calls `pty_create`, and never runs the
  //    `claude --continue` this resume just resolved for it. Panes that DID unmount (ended/dormant,
  //    cleared in 3b above) remount and are handled by the reconnect branch in `TerminalView`.
  //
  //    Awaited so the caller's `ok` genuinely means the resume was attempted; the probe itself is one
  //    batched call regardless of how many panes are listed.
  await ensureClaudeRunning([...resumableIds].map(paneOf));
  const notes = [gateNote, complete.length > 0
    ? `${complete.length} complete worker${complete.length === 1 ? "" : "s"} left alone — the director wakes them on dispatch`
    : undefined, held.length > 0
    ? `${held.length} stream${held.length === 1 ? "" : "s"} held — waiting on an upstream to land`
    : undefined].filter(Boolean);
  return { ok: true, note: notes.length ? notes.join(". ") + "." : undefined, blocked, held };
}

// reviewShot (#2623 slice 5c) — the I/O actuator that turns one captured preview shot into review
// findings. It composes the pure review prompts + parser (slice 5a, previewReview.ts) with the multimodal
// LLM call (oneShotVision): send the screenshot to Claude, parse the JSON reply into ReviewFinding[]. The
// caller (the inbox, slice 5d) folds the result into the confirm-gated inbox via mergeFindings. Kept thin
// so the pure logic stays in previewReview.ts and the only side effect here is the model call.

import type { LlmConfig } from "@/shared/lib/core/llmConfig";
import { oneShotVision } from "@/shared/lib/core/claudeComplete";
import {
  reviewSystemPrompt,
  reviewUserPrompt,
  parseFindings,
  type PreviewShot,
  type ReviewFinding,
} from "@/shared/lib/preview/previewReview";

/** Mint a stable-enough id for a finding of `shot` — the inbox dedups by shot+title (findingKey), so this
 *  only needs to be unique per (shot, review pass). `seq` disambiguates a batch that lands in one pass. */
function findingId(shot: PreviewShot, index: number, seq: number): string {
  return `${shot.id}:${seq}:${index}`;
}

/**
 * Review one captured shot with the vision model → its findings (all `status: "pending"`). Throws only on
 * a call failure (no key / unsupported provider / network) — a well-formed-but-unparseable reply yields
 * `[]` (parseFindings is tolerant), so a bad review surfaces as "no findings", never a crash.
 *
 * @param seq  a per-pass discriminator for the minted finding ids (default `0`); pass the shot index when
 *             reviewing several shots so their ids don't collide.
 */
export async function reviewShot(cfg: LlmConfig, shot: PreviewShot, seq = 0): Promise<ReviewFinding[]> {
  const reply = await oneShotVision(cfg, reviewSystemPrompt(), reviewUserPrompt(shot), [shot.image]);
  return parseFindings(reply, shot.id, (i) => findingId(shot, i, seq));
}

// Pure Gantt/timeline model for the Projects → Roadmap tab.
//
// Kept free of React / Tauri imports so the windowing and bar math can be unit
// tested in isolation. The Roadmap view feeds it GitHub milestones plus a
// selected time window; it returns positioned rows and the axis scale.

// The milestone shape is the canonical one in shared/lib/github/types (#1528); re-exported here so
// existing importers (Roadmap.tsx, the tests) keep their `from "@/features/planner/github/roadmapGantt"` import.
import type { GhMilestone } from "@/shared/lib/github/types";
export type { GhMilestone };

const WEEK_MS = 7 * 24 * 3600 * 1000;

export interface GanttRow {
  id: string;
  title: string;
  startWeek: number;
  lengthWeeks: number;
  pct: number;
  state: "done" | "doing" | "upcoming" | "backlog";
  creator: string;
  dueLabel: string;
}

export interface GanttModel {
  rows: GanttRow[];
  totalWeeks: number;
  todayWeek: number;
  origin: Date;
}

/** Time-window presets for the Roadmap filter. `weeks: null` = all time. */
export const WINDOW_PRESETS: { label: string; weeks: number | null }[] = [
  { label: "8w",  weeks: 8 },
  { label: "28w", weeks: 28 },
  { label: "1y",  weeks: 52 },
  { label: "all", weeks: null },
];

/** Default window — bounds the timeline on first load so it isn't spread across
 *  the project's entire history. */
export const DEFAULT_WINDOW_WEEKS = 28;

export function weeksBetween(a: Date, b: Date): number {
  return Math.max(0, Math.ceil((b.getTime() - a.getTime()) / WEEK_MS));
}

/** The start of a window `weeks` before `now`, or null for all-time. */
export function windowStartFrom(weeks: number | null, now: Date = new Date()): Date | null {
  return weeks == null ? null : new Date(now.getTime() - weeks * WEEK_MS);
}

export function tickIntervalWeeks(totalWeeks: number): number {
  if (totalWeeks <= 16)  return 1;
  if (totalWeeks <= 52)  return 4;
  if (totalWeeks <= 130) return 8;
  return 13;
}

export function tickLabel(weekIndex: number, origin: Date, interval: number): string {
  if (interval <= 1) return `w${weekIndex + 1}`;
  const d = new Date(origin.getTime() + weekIndex * WEEK_MS);
  return d.toLocaleDateString("en-US", { month: "short", year: "2-digit" });
}

function milestoneEnd(m: GhMilestone): Date {
  return m.due_on ? new Date(m.due_on) : new Date(new Date(m.created_at).getTime() + 14 * 24 * 3600 * 1000);
}

/**
 * Build the Gantt model for the given milestones, scaled to a time window.
 *
 * `windowStart` (from {@link windowStartFrom}) clamps the timeline's left edge:
 * milestones whose end falls entirely before it are dropped, and the axis origin
 * is pinned to the window edge (or the earliest kept milestone, whichever is
 * later) so a few far-apart due dates can't squash everything into slivers. Bars
 * that began before the window are clamped to start at the edge. Pass `null` for
 * all time. `now` is injectable for testing.
 */
export function buildGantt(
  milestones: GhMilestone[],
  windowStart: Date | null,
  now: Date = new Date(),
): GanttModel {
  const items = milestones.map(m => ({ m, start: new Date(m.created_at), end: milestoneEnd(m) }));
  const kept = windowStart
    ? items.filter(x => x.end.getTime() >= windowStart.getTime())
    : items;

  if (kept.length === 0) return { rows: [], totalWeeks: 8, todayWeek: 0, origin: now };

  const earliestStart = kept.reduce((a, b) => (a.start < b.start ? a : b)).start;
  // Pin the origin to the window edge when it's later than the earliest kept
  // start; otherwise start at the earliest milestone (no empty left margin).
  const origin = windowStart && windowStart.getTime() > earliestStart.getTime() ? windowStart : earliestStart;
  const horizon = kept.reduce((a, b) => (a.end > b.end ? a : b)).end;
  const totalWeeks = Math.max(weeksBetween(origin, horizon) + 1, 8);
  const todayWeek = weeksBetween(origin, now);

  const rows: GanttRow[] = kept.map(({ m, start, end }) => {
    // Clamp a bar that began before the window to the visible left edge.
    const effStart = start.getTime() < origin.getTime() ? origin : start;
    const startWeek = weeksBetween(origin, effStart);
    const lengthWeeks = Math.max(1, weeksBetween(effStart, end));
    const total = m.open_issues + m.closed_issues;
    const pct = total > 0 ? m.closed_issues / total : 0;
    const state: GanttRow["state"] =
      m.state === "closed" ? "done"
      : pct > 0 ? "doing"
      : startWeek <= todayWeek ? "upcoming"
      : "backlog";
    const dueLabel = m.due_on
      ? new Date(m.due_on).toLocaleDateString("en-US", { month: "short", day: "numeric" })
      : "no due date";

    return { id: String(m.number), title: m.title, startWeek, lengthWeeks, pct, state, creator: m.creator?.login ?? "", dueLabel };
  });

  return { rows, totalWeeks, todayWeek, origin };
}

// Role-scoped session capabilities (#219) — the TYPES + role→capability data + core accessors.
// This is the foundation layer of the role gate: the `SessionRole` union, the `RoleCapability`
// shape, the externalized role→capability TABLE, and the derivations that read that table
// (`roleCapability`, `hasScopedWriteCarveOut`). Command classification, write-path scoping, and
// the launch-wiring rules build on top of these (see `commandGate.ts`, `writeScope.ts`,
// `launchRules.ts`); the public surface is re-exported from `sessionRoles.ts`.
//
// THE TABLE NOW COMES FROM THE PERSONAS (epic `the-persona-is-the-whole-agent`). It used to be
// `@data/permissions/role-capabilities.json`, which is DELETED — a persona carries its own `floor`, so
// that file was a second copy of the same fact, and the copy was the one nothing could clamp at write
// time (`bsc persona set` is a store write; a JSON file in the bundle is not). Rust still does not
// duplicate any of it: TS computes each session's permissions here and passes them to
// `ensure_session_settings`.
//
// The two lists in that file that were never per-role — the DB-owned plan files and the dependency
// manifests — moved to `@data/permissions/write-locks.json` rather than being folded onto a role they
// never belonged to.
//
// Deriving the table here rather than in `persona.ts` keeps the dependency pointing one way: this
// module reads the persona JSON *data*, and `persona.ts` imports this module for its types. Reading
// the assembled persona library instead would close a cycle.

import writeLocksEmbedded from "@data/permissions/write-locks.json";
import { overlayFile, overlayGlob } from "@/shared/lib/core/configOverrides";

/** Every packaged persona, as authored. Only `role` and `floor` are read here. */
const personaFloorModules = import.meta.glob<{ default: { role?: string; floor?: Record<string, unknown> } }>(
  "@data/personas/*.json",
  { eager: true },
);

/** One packaged persona, as far as this module cares. */
interface PersonaFloorDef { role?: string; floor?: Record<string, unknown> }

/** role → capability, projected from the persona floors. A persona whose floor is absent contributes
 *  nothing (rather than an empty row that would read as "denied everything" and mask a real grant).
 *
 *  Takes `unknown` values because it is fed from two shapes: `import.meta.glob` hands back
 *  `{ default: def }` modules, while `overlayGlob` has already unwrapped to the def. Narrowing here
 *  keeps ONE projection for both instead of two that could drift. */
function tableFromPersonas(mods: Record<string, unknown>) {
  const out: Record<string, Record<string, unknown>> = {};
  for (const mod of Object.values(mods)) {
    const wrapper = mod as { default?: PersonaFloorDef } | PersonaFloorDef | undefined;
    const def = (wrapper && "default" in wrapper ? wrapper.default : wrapper) as PersonaFloorDef | undefined;
    if (!def?.role || !def.floor) continue;
    // First writer wins, so a user persona derived from a packaged one can never redefine the ROLE's
    // capability out from under every other persona on it. Packaged ids sort first by filename.
    out[def.role] ??= { role: def.role, writeGlobs: [], ...def.floor };
  }
  return out;
}

// The EMBEDDED table (packaged personas only) and the OVERLAID one (config-dir copies layered on),
// kept separate so the floor-merge below has a real floor to hold against. See `mergeRoleDefaults`.
const embeddedRoleDefaults = tableFromPersonas(personaFloorModules);
const overlaidRoleDefaults = tableFromPersonas(
  Object.fromEntries(overlayGlob<PersonaFloorDef>("personas", personaFloorModules)),
);

// The config-dir copy (#2047) overlays the embedded default — editable without a rebuild.
const writeLocks = overlayFile("permissions/write-locks.json", writeLocksEmbedded);

// Floor-merge on the EMBEDDED sets (#2325). `overlayFile` FULLY REPLACES the file with the config-dir
// copy, so a STALE override — seeded on a first run BEFORE the shipped default gained a role/list — would
// silently drop it. When code then reads that role at module load (e.g. `DOC_GLOBS =
// ROLE_DEFAULTS.documentor.writeGlobs`, #1555), the missing role is `undefined` and it throws
// `TypeError reading writeGlobs`, taking down the WHOLE UI. Basing every field on the embedded default
// guarantees each `SessionRole` (and each list) the code knows about is always present; the overlay
// still customizes/adds entries on top.
const roleDefaultsMerged = mergeRoleDefaults(embeddedRoleDefaults, overlaidRoleDefaults);

/** Floor-merge role-default tables (#2325): `embedded` is the base (every shipped role), `overlaid` (the
 *  config-dir copy) customizes/adds on top. Exported so the regression test can prove a stale override
 *  MISSING a role still yields that role from the embedded floor (rather than `undefined` → the
 *  module-load `TypeError reading writeGlobs` that took down the UI). */
export function mergeRoleDefaults<T>(embedded: Record<string, T>, overlaid: Record<string, T>): Record<string, T> {
  const out: Record<string, T> = { ...embedded };
  for (const [role, over] of Object.entries(overlaid)) {
    const base = embedded[role];
    if (!base || typeof base !== "object" || typeof over !== "object" || !over) {
      out[role] = over;              // a role the shipped app doesn't know — the overlay owns it whole
      continue;
    }
    // FIELD-level floor, not role-level (#4108). The role-level `{...embedded, ...overlaid}` above meant
    // a mirror that HAS the role replaced its entry wholesale — so a mirror written before a field
    // existed silently dropped it.
    out[role] = { ...base, ...over, ...floorLists(base, over), ...clampTiers(base, over) } as T;
  }
  return out;
}

/**
 * CEILING on the access tiers: a config-dir mirror may NARROW a tier but never exceed the tier the
 * shipped app grants. The precise inverse of {@link floorLists}, and it exists for the same reason —
 * `config/` is seeded ONCE and never refreshed, so every existing install is frozen at whatever
 * shipped the day it first ran.
 *
 * The consequence without this clamp is not cosmetic. When the director's shipped tiers were narrowed
 * to `git: read` / `github: read`, every install carrying a mirror written before that change kept
 * `write` on both — so the narrowing shipped, passed its tests, and applied to nobody. A security
 * default that a stale file can silently revert is not a default.
 *
 * Narrowing is deliberately still allowed: the documented contract is that a user may tighten a role,
 * and tightening is safe by construction. Only the widening direction is clamped.
 *
 * `writeGlobs` is handled here too, in the one direction that matters: an EMPTY overlay list falls
 * back to the shipped globs. An empty list is indistinguishable from a mirror written before the role
 * had a boundary at all, and that is exactly the case that bites — the director gained `code: "write"`
 * plus its plan-file globs in the same change, so a mirror supplying `[]` would leave it able to write
 * with no boundary defined. A NON-empty overlay list still wins, so a user's real narrowing survives.
 */
function clampTiers(base: object, over: object): Record<string, unknown> {
  // Declared INSIDE the function on purpose. `mergeRoleDefaults` is called at module load (the
  // `roleDefaultsMerged` const above), which is before any module-scope `const` below it has
  // initialized — hoisting the two tables out would reintroduce a `ReferenceError: Cannot access
  // 'TIER_FIELDS' before initialization` that takes the whole role table (and so the UI) down at boot.
  // `floorLists` escapes this only because it has no const dependencies. Do not "tidy" these upward.
  const TIER_RANK: Record<string, number> = { none: 0, read: 1, write: 2 };
  const TIER_FIELDS = ["github", "git", "code", "net", "ui"] as const;
  const b = base as Record<string, unknown>;
  const o = over as Record<string, unknown>;
  const out: Record<string, unknown> = {};
  for (const f of TIER_FIELDS) {
    const bv = b[f], ov = o[f];
    if (typeof bv !== "string" || typeof ov !== "string") continue;
    if ((TIER_RANK[ov] ?? 0) > (TIER_RANK[bv] ?? 0)) out[f] = bv;
  }
  const bg = b.writeGlobs, og = o.writeGlobs;
  if (Array.isArray(bg) && bg.length > 0 && Array.isArray(og) && og.length === 0) out.writeGlobs = bg;
  // `allow` is floored in BOTH directions a stale mirror can break it, because its absence is the
  // widest value rather than the narrowest (see RoleCapability.allow). A config-dir copy written
  // before a role gained its confined surface would otherwise silently promote that session from
  // "may auto-run exactly `bsc ui`" to "may auto-run the whole baseline allow-list" — the widening
  // this whole clamp exists to make impossible, arriving through the one field where doing nothing
  // is the dangerous option.
  const ba = b.allow, oa = o.allow;
  if (Array.isArray(ba) && ba.length > 0 && (!Array.isArray(oa) || oa.length === 0)) out.allow = ba;
  return out;
}

/** Fields where the SHIPPED value is a floor a stale mirror must not be able to revoke (#4108).
 *
 *  `config/` is seeded ONCE — `ensure_seeded` writes "only files that are ABSENT so a user edit is never
 *  clobbered" — and never refreshed. So on every existing install the mirror is frozen at whatever the
 *  app shipped the day it was first run, and a later capability grant is invisible forever. That is not
 *  hypothetical: the librarian's `projects` harvest root (#4108) landed in the packaged default and was
 *  dropped by a mirror still carrying `['app-repo']`, which is the whole reason the Algorithms studio
 *  could not see `mobile-studio-code`.
 *
 *  UNION rather than replace, and ONLY for `harvestRoots`: a harvest root widens READ-only scan reach
 *  that the shipped app decides (there is no UI to edit it), so a mirror can ADD one but never revoke
 *  one. Write-bearing fields — `writeGlobs`, the access tiers — are deliberately NOT floored here: those
 *  a user may legitimately narrow, and silently widening them would be the opposite mistake. */
function floorLists(base: object, over: object): Record<string, unknown> {
  const b = (base as { harvestRoots?: string[] }).harvestRoots;
  const o = (over as { harvestRoots?: string[] }).harvestRoots;
  if (!b?.length) return {};
  return { harvestRoots: [...b, ...(o ?? []).filter((r) => !b.includes(r))] };
}

export type SessionRole =
  | "planner" | "worker" | "director" | "triage"
  // Pipeline-stage roles (#220): tester runs build/tests, reviewer reads + reviews.
  // All are least-privilege (read-only, no code writes).
  | "tester" | "reviewer"
  // Issuer (#376): intake-only — shapes user requests into issues and may open GitHub
  // issues, but never touches code or git; routing is the director's job.
  | "issuer"
  // Juror (#394): a scoped reviewer that independently judges a landing against an
  // anchor (acceptance criteria / lens / subsystem slice). Read-only, like reviewer.
  | "juror"
  // Documentor (#1555): a post-refactor lifecycle actor that reconciles the project's PROSE
  // documentation (the CLAUDE.md structure tree, architecture docs, README) after a change lands.
  // It reads for context and writes ONLY prose docs — `code: "none"` with a DOC_GLOBS write
  // carve-out (like the director's commons, #851), so it can never touch feature code.
  | "documentor"
  // Designer (#2471): the Design Studio's heavily-restricted UI-kit session. Its ENTIRE surface is
  // the `bsc ui` CLI (kits live in the store, not files) — `none` on every axis: no git, no
  // GitHub, no file writes, no web. Launched with `restrictedAllow`, so the baseline command
  // tiers are suppressed and only `bsc ui` (+ the deprecated `bsc component` alias) auto-runs.
  | "designer"
  // Architect (#2755, retasked as the funnel's front door): tier 1 — the ONLY session that talks to
  // the user. It runs DISCOVERY (goal, users, scope, stack, … one topic at a time) and captures the
  // AUTHORITY the tiers below cite when they decide unattended, then hands both down to a director.
  // Its capability row is UNCHANGED by that retasking, which is why this role was reused rather than a
  // new one minted: `none` on every axis (no git, no GitHub, no file writes, no web) with `ui: none`,
  // launched `restrictedAllow` so the baseline command tiers stay suppressed. That is not merely
  // convenient — the front door ingests raw user prose, so it is the highest prompt-injection surface
  // in the system, and being the LEAST capable session is a property worth keeping deliberately.
  // Its auto-runnable surface is exactly its grant list below: `bsc plan requirement` (the one thing it
  // writes), `bsc plan brief` (its one outbound channel, director-only), plus the transitional
  // `bsc teams`/`bsc persona` it still holds until team design moves to the director.
  | "architect"
  // Librarian (#2787): the Algorithms tab's heavily-restricted knowledge-store session. Like the
  // designer/architect it is `none` on every axis (no git, no GitHub, no file writes, no web) and
  // `ui: none`. Launched with `restrictedAllow`, so the baseline command tiers are suppressed and only
  // `bsc graph` auto-runs. The Algorithms graph stays the read-only viewer; the librarian stores +
  // curates the knowledge graph (nodes, relationships, the reality lens) via that one CLI.
  | "librarian"
  // Sound-designer (#3369, epic #3071 phase 4): the Sounds tab's heavily-restricted sound-kit
  // authoring session. Like the designer/architect/librarian it is `none` on every axis (no git, no
  // GitHub, no file writes, no web) and `ui: none` — a sound is a synthesis DESCRIPTOR in the store,
  // not a file, and not a UI kit. Launched with `restrictedAllow`, so the baseline command tiers are
  // suppressed and only `bsc sound` auto-runs. The Sounds graph stays the read-only viewer; the
  // sound-designer authors primitives, voices, cues and kits through that one CLI.
  // NOTE the name shares a word with `designer` but is a DISTINCT role — nothing may treat the two
  // as interchangeable (a `startsWith`/`includes` check on the role would silently conflate them).
  | "sound-designer"
  // Debugger (#3322): the app's OWN full-capability maintenance session — fixes the `bsc ui` tooling the
  // designer reports via `bsc request` (#3298). Broad app-maintenance caps (git+github+code+ui write); the
  // session actually launches full-cap/bypass on TerminalHost via `DebugSessionMount` (the always-bypass
  // `isFullCapabilitySession` carve-out, role-less — #3326), so this table entry backs its graph identity +
  // any generic role→profile surface, not the live session's gate.
  | "debugger"
  // Marketer (#2431): the opt-in marketing persona's role — takes the market-research stage's
  // artifacts and drafts in-repo collateral (landing/README copy, launch posts, SEO content,
  // release announcements). Least-privilege like `documentor`: `code: "none"` with a marketing-content
  // write carve-out (markdown/mdx under `marketing/`/`content/` + README/CHANGELOG), so it can never
  // touch feature code; outward (third-party) publishing is out of v1.
  | "marketer"
  // Curator (#3092, epic #3087): the reusable-library lifecycle actor — the library analog of the
  // `documentor`. After a change lands it HARVESTS the reusable components/algorithms the fleet built
  // into the GLOBAL stores (not already present), then OPTIMIZES the graph via the command
  // (`bsc ui doctor --fix`). Scoped write to the STORES only — `ui: "write"` (the component/kit store)
  // + `bsc graph` via the restricted allow-list — with `code: "none"` and `git: "read"` (to read the
  // landed repo it harvests from). It never touches project files or GitHub. Distinct from the
  // `librarian` (the standing Algorithms-Studio session): the curator is a FLEET post-landing actor.
  | "curator"
  // Integrator (#4023): the Integration Studio's session — builds and MAINTAINS an integration with an
  // existing application or API. Its store surface is `bsc data connector` (the runtime REST connector
  // presets), so like its studio siblings it is `none` on git/GitHub/code/ui with a `scratch/**` carve-out
  // and launches `restrictedAllow`. THE ONE DIFFERENCE: `net: "read"`. Every other studio is `net: "none"`,
  // but this role's work STARTS at the vendor's documentation — it cannot author a manifest for an API it
  // is not allowed to read about. That widening is deliberate and is the only one: it reads docs and probes
  // endpoints read-only, and still cannot write a repo file, reach git, or touch GitHub.
  | "integrator";

/** Access to a capability: none < read < write. */
export type AccessTier = "none" | "read" | "write";

export interface RoleCapability {
  role: SessionRole;
  /** GitHub: `gh` writes / API mutations. */
  github: AccessTier;
  /** Local git: commit/push/merge are writes; status/log are reads. */
  git: AccessTier;
  /** Editing files on disk (outside any dedicated plan channel). */
  code: AccessTier;
  /** Network/web tools (`WebFetch`, `WebSearch`) — a live prompt-injection vector (#1107). `none`
   *  denies them outright at launch; `read` permits fetching, whose RESULTS the session must treat
   *  as untrusted data (the planner template frames this). This is the gate the per-agent `net`
   *  profile (#289) ties into; `write` is unused (there's no "network write" tool to grant). */
  net: AccessTier;
  /** The `bsc ui` component/kit store (#2470): `read` lets a session use the kit it builds against
   *  but never redefine it (the mutating verbs — `bsc ui set`/`remove`/`kit set`/`kit remove` and
   *  the deprecated `bsc component` alias — are denied at launch, {@link roleDeniedCommands});
   *  `none` denies `bsc ui` outright; `write` is the designer's tier. Same philosophy as the
   *  dep-manifest lock (#1111): nobody but the designated role mutates the shared contract. */
  ui: AccessTier;
  /** Path globs this role/assignment may write. Empty ⇒ no code writes. */
  writeGlobs: string[];
  /** SYMBOLIC roots this role may HARVEST from (#3509) — read-only, and deliberately NOT paths: a role
   *  is machine-independent, so it declares INTENT (`app-repo`) and the launch resolves it. Widens only
   *  what `bsc ui harvest` / `bsc graph harvest` may SCAN; it grants no write anywhere, which is the
   *  whole point — a kit-only session can mine a repo it may not write to. Empty ⇒ harvest stays bound
   *  to the session's own confinement root, exactly as before. */
  harvestRoots?: string[];
  /**
   * The CONFINED store-CLI surface — the only commands this role auto-runs, suppressing the baseline
   * tiers (`restrictedAllow` at launch). Formerly the `RESTRICTED_ROLE_COMMANDS` const in this file;
   * it is data now because it is half of what a permission floor MEANS, and the maintainer's framing is
   * that the only things worth restricting are location and the command surface.
   *
   * ITS PRESENCE IS THE SWITCH. `isRestrictedRole` is "has a non-empty list", so absent and `[]` are
   * NOT the same thing: absent means UNCONFINED — the broad baseline allow-list — which is the widest
   * value this field takes. That inversion is why {@link clampTiers} floors it rather than letting an
   * overlay drop it, and it is the same asymmetry the persona store's own clamp encodes.
   */
  allow?: string[];
}

/** The symbolic harvest root meaning "the base-studio-code source tree this app was built from". The
 *  only token today; resolution is the launch's job ({@link buildAgentEnv}), since a role cannot know
 *  a machine's paths. */
export const HARVEST_ROOT_APP_REPO = "app-repo";

/** The symbolic harvest root meaning "the `~/.base-studio-code/projects/` tree — every downloaded
 *  project repo". Resolved by the launch to `<bscBaseDir>/projects` (#3664), so a UI/logic session can
 *  mine components from the OTHER repos, not just the app's own source. Read-only like every harvest
 *  root — the whole `projects/` tree is readable, but writes stay confined to the session's workspace. */
export const HARVEST_ROOT_PROJECTS = "projects";

// The role→capability table + the write-glob / db-owned / dep-manifest lists load from
// `@data/permissions/role-capabilities.json` (#2027 P1) — see the file's `_comment` for the policy.
// The exported names below keep the SAME semantics they always had:
//
// - ROLE_DEFAULTS — default capability per role. `writeGlobs` are filled per assignment (a worker
//   owns its stream's globs); the defaults are empty so a session with no assigned boundary can't
//   write code. The **planner is plan-only** — read-only git/GitHub; its code writes are scoped to
//   plan-section files ({@link PLAN_WRITE_GLOBS}) so it never needs a prompt to write goal.md /
//   phases.json / fleet.json / prompts/*. `net: "read"` across the board preserves today's behavior
//   (WebFetch allowed via the broad Bash grant); a per-agent `net` profile (#289) or a planner
//   "no web" toggle (#1107) can set `none` to deny WebFetch/WebSearch at launch.
// - PLAN_WRITE_GLOBS (#509) — the section files the planner writes directly (md sections, JSON
//   manifests, prompts/ + discovery/ #807). Derived from the planner role so the glob list lives once.
// - DB_OWNED_PLAN_FILES (#1070) — structured plan state that lives in plan.db, written ONLY via the
//   `bsc plan` CLI. {@link roleWriteRules} denies their FILE forms for the planner (deny > allow) so
//   its `*.md`/`*.json` glob can't auto-approve them; section files (goal.md, …) stay writable.
// - DEP_MANIFEST_FILES (#1111) — dependency manifests + lockfiles a WORKER must not hand-edit (a new
//   dep routes through the director). {@link roleWriteRules} denies the Edit/Write TOOLS on these
//   even inside the worker's owned globs; `npm install` / `cargo build` via Bash still regenerate them.
export const ROLE_DEFAULTS: Record<SessionRole, RoleCapability> = roleDefaultsMerged as unknown as Record<SessionRole, RoleCapability>;

/** The plan-section files the PLANNING session writes directly (md sections, JSON manifests,
 *  `prompts/`, `discovery/`). Derived from the **director** row, which now carries the planning
 *  surface: planning and directing were the same actor at different phases of one project, so the
 *  capability moved rather than being duplicated. Renamed from `PLANNER_WRITE_GLOBS` because the
 *  globs are no longer the planner role's. */
export const PLAN_WRITE_GLOBS: string[] = ROLE_DEFAULTS.director?.writeGlobs ?? [];
export const DB_OWNED_PLAN_FILES: string[] = writeLocks.dbOwnedPlanFiles ?? writeLocksEmbedded.dbOwnedPlanFiles;
export const DEP_MANIFEST_FILES: string[] = writeLocks.depManifestFiles ?? writeLocksEmbedded.depManifestFiles;
// DOC_GLOBS (#1555) — the prose-documentation paths the DOCUMENTOR may write: top-level and nested
// markdown, the `docs/` tree, and README/CHANGELOG variants (incl. extension-less / .rst). Derived
// from the documentor role so the list lives once. Path-granular by design (see the boundary note in
// {@link hasScopedWriteCarveOut}): it grants markdown + docs and NOTHING with a code extension, so a
// documentor can reconcile structural/architectural docs but never edit `src/*.ts` / `*.rs` source.
export const DOC_GLOBS: string[] = ROLE_DEFAULTS.documentor?.writeGlobs ?? [];

/** A role capability, optionally narrowed/widened per assignment (e.g. writeGlobs).
 *
 *  Field-level floor (#2470, the per-FIELD companion to the per-ROLE floor-merge #2325):
 *  `mergeRoleDefaults` floors missing ROLES, but an overlaid role OBJECT fully replaces the embedded
 *  one — so a STALE config-dir override seeded before a field shipped (e.g. `ui`) leaves that field
 *  `undefined` on the merged entry. Defaults are prepended here so every capability handed to the
 *  launch wiring carries a value; the table (and any explicit `override`) still wins when present. */
export function roleCapability(role: SessionRole, override: Partial<RoleCapability> = {}): RoleCapability {
  const merged = { ...ROLE_DEFAULTS[role], ...override };
  return { ...merged, ui: merged.ui ?? "read" };
}

/** The `code: "none"` roles that carry an explicit, scoped write carve-out (a narrow allow layered
 *  onto an otherwise write-denied capability): the **director** (its commons globs, #851), the
 *  **documentor** (its DOC_GLOBS prose docs, #1555), and the **marketer** (its marketing-content globs,
 *  #2431). Every OTHER `code: "none"` role (triage, tester, reviewer, juror, issuer, designer) stays
 *  fully write-denied even if handed globs — the stewardship can't be accidentally granted to a
 *  non-carve-out role. */
const CARVE_OUT_ROLES: ReadonlySet<SessionRole> = new Set<SessionRole>([
  // The DIRECTOR was removed here (#funnel-planning-moves-to-director). Its commons carve-out existed
  // only because the director was the one non-worker session holding a project hub, so the repo-root
  // commons had nowhere else to live. The commons are now a worker STREAM with an owner, a branch and
  // a worktree — and the director itself is `code: "write"` scoped to plan files, so it no longer
  // qualifies for a `code: "none"` carve-out at all.
  "documentor", "marketer",
  // The RESTRICTED studio sessions (#3373). Their carve-out is not project content at all — it is a
  // single sealed SCRATCH dir inside their own workspace (`scratch/**`), the staging area for a payload
  // they then apply with `bsc <store> set --file <name>`. They need it because a heredoc cannot be
  // allow-listed (newlines are command separators), which left them unable to author anything.
  //
  // This is a NARROWER grant than it looks: `bsc-confine` already pins their file tools to the session
  // cwd (their own workspace), `bsc-scope` then pins writes to `scratch/**` within it, `--file` reads
  // only bare names from that same dir, and the dir is wiped at every launch. They still cannot touch
  // project code, their own `CLAUDE.md`, or `.claude/**` (denied on every pane).
  "designer", "architect", "librarian", "sound-designer",
]);

/**
 * Whether a capability has an explicit, scoped write carve-out (#851 / #1555): a `code: "none"` role
 * (no feature-code writes) that is nonetheless allowed to write EXACTLY the globs it owns and nothing
 * else — the **director** writes the commons globs (`.gitignore`, manifests, CI config, …) assigned to
 * it, the **documentor** writes its DOC_GLOBS prose docs. This mirrors the #304 precedent of a scoped
 * role-gate carve-out. Scoped to {@link CARVE_OUT_ROLES} on purpose: every OTHER `code: "none"` role
 * stays fully write-denied even if handed globs. An empty `writeGlobs` ⇒ no carve-out, full deny stands
 * (so a director without assigned commons keeps the full deny; the documentor ships DOC_GLOBS by
 * default, so its carve-out is active as launched).
 */
export function hasScopedWriteCarveOut(cap: RoleCapability): boolean {
  return CARVE_OUT_ROLES.has(cap.role) && cap.code === "none" && cap.writeGlobs.length > 0;
}

/** Roles whose launch grants a FIXED store-CLI auto-run surface on top of the profile — the bundled
 *  `bsc` subcommands they drive, regardless of the project (#3095, epic #3087). A non-empty entry ALSO
 *  drives `restrictedAllow` (#3098): the wrapped commands become the session's ONLY auto-run Bash
 *  surface (the baseline git/build/read-only tiers are suppressed).
 *
 *  THE ROLE IS THE SOURCE OF TRUTH for a restricted session's confinement. The standing-tab studio
 *  sessions (designer / librarian / architect) used to pin their surface inside their own launch hooks,
 *  which meant the SAME role produced a different (much wider) gate on any other launch path — moving
 *  them here makes the confinement travel with the role wherever the session is launched from (the
 *  bespoke hook, a fleet launch, or the shared TerminalHost).
 *   • designer   — the `bsc ui` component surface (+ the deprecated `bsc component` alias), the
 *                  preview-only screenshot, the design loop, and the designer→debug request channel.
 *   • librarian  — the algorithms graph store, plus READ-ONLY lookup into the component store (#4090).
 *   • sound-designer — the sound-kit store (synthesis descriptors: primitives, voices, cues, kits).
 *   • architect  — the teams + persona (agent-identity) stores.
 *   • curator    — the post-landing harvest + graph-optimize actor (fleet-launched). */
/**
 * The loop verbs a studio surface may run as a PARTICIPANT in a `bsc loop` (#3262) — every studio can
 * open a loop and converse in it.
 *
 * `bsc loop stop` is deliberately ABSENT. It is the only way to halt an `--until false` (infinite) loop,
 * and the CLI withholds it from participants on purpose — a separate verb from `say` precisely so a
 * participant cannot reach it. Granting the bare `"bsc loop"` prefix would expand to `Bash(bsc loop *)`
 * and match `bsc loop stop`, handing the session the halt verb and letting it end the very loop it is
 * supposed to run forever. Enumerating the participant verbs keeps the CLI's invariant intact through
 * the permission layer; halting stays with the user and the debug session.
 */
// The loop verbs themselves are listed on each participating persona's floor now, not spread from a
// const here — one place per role, which is the point of the move.

// `RESTRICTED_ROLE_COMMANDS` LIVED HERE and is gone (epic `the-persona-is-the-whole-agent`). The
// confined command surface is now `RoleCapability.allow`, carried by each persona's floor in
// `@data/personas/*.json` — so a role's capability is described in ONE place instead of split between
// a JSON table (tiers, write scope) and a TS const (the surface). Everything that read this const now
// reads the floor; see `restrictedRoleCommands` below.

/** The global tooling-request queue (`crates/bsc-request`, #3295) — the designer->debug channel,
 *  drained by a FULL-CAPABILITY session that edits base-studio-code itself. */
export const TOOLING_REQUEST_COMMAND = "bsc request";

/**
 * May this role reach the global tooling-request queue (#4000)?
 *
 * DERIVED from the grant table above rather than listed separately, so the allow and the deny cannot
 * drift apart: a role that is granted `bsc request …` is allowed it, everything else is denied it.
 * Adding the grant to a new role therefore lifts its deny automatically, and removing the grant
 * re-denies it — there is no second list to remember.
 *
 * `debugger` is the one addition: it is the queue's CONSUMER (it reads, claims and resolves), and it
 * has no `RESTRICTED_ROLE_COMMANDS` entry because it launches full-capability rather than confined.
 *
 * Everything else — `worker`, `director`, `triage`, `planner`, … — is a PROJECT role. Its lane is
 * `bsc plan request`, which is scoped to its own project's plan.db. Escalation from there to the
 * tooling queue is the director's move, made explicitly, not a side effect of any agent being able to
 * run `bsc`.
 */
export function mayFileToolingRequest(role: SessionRole | null | undefined): boolean {
  // The two roles named explicitly, because neither has a `RESTRICTED_ROLE_COMMANDS` entry to derive
  // from — they are not confined roles:
  //   · `debugger` is the queue's CONSUMER (reads, claims, resolves); it launches full-capability.
  //   · `director` is the sanctioned ESCALATION point (#4001). A worker files a PROJECT request
  //     (`bsc plan request`); when the director judges one to be a genuine tooling gap rather than
  //     something it can fix, it forwards it here. That promotion is the whole reason the project lane
  //     can stay closed to workers — and it is safe because the director is `code: none`, so it can
  //     ASK for an app change but never make one. #4000 denied it as well; this is the deliberate
  //     refinement that makes the two-lane design actually work end to end.
  if (role === "debugger" || role === "director") return true;
  return restrictedRoleCommands(role).some((c) => c.startsWith(TOOLING_REQUEST_COMMAND));
}

/**
 * The fixed store-CLI command prefixes a role auto-runs at launch, in ADDITION to its profile's
 * `allowedCommands` (#3095). Empty for a role with no fixed store surface. Returns a fresh array so
 * callers can spread/mutate freely.
 */
export function restrictedRoleCommands(role: SessionRole | null | undefined): string[] {
  return role ? [...(ROLE_DEFAULTS[role]?.allow ?? [])] : [];
}

/**
 * Whether a role is CONFINED to a fixed store-CLI surface — i.e. it has a {@link restrictedRoleCommands}
 * entry, so `restrictedAllow` suppresses the Bash baselines and those commands are its whole auto-run
 * surface.
 *
 * Such a role must NEVER be flipped to the bypass posture: bypass makes Claude auto-run everything and
 * ignores `permissions.deny`, which would hand a deliberately-confined session (the designer is limited
 * to `bsc ui`) a general shell. So the global `bypassPermissions` toggle is overridden to `false` for
 * these roles — the inverse of the full-capability carve-out (`isFullCapabilitySession`, the debug
 * session, which is always bypass). Derived from the role, so the guarantee travels with it.
 */
export function isRestrictedRole(role: SessionRole | null | undefined): boolean {
  return restrictedRoleCommands(role).length > 0;
}

// Role → default permission profile — the unified model. Every session's ROLE decides which
// profile it launches under, so a director / worker / triage gets the right profile WITHOUT a
// per-stream generated profile or a manual assignment. The planner only LAYERS extra commands on
// top (it adds abilities, never replaces the role's profile). Profile ids match the packaged role
// JSON (`src-tauri/data/roles/`); kept as bare strings so this stays free of the agents feature
// (shared/ may not import features/).

import type { SessionRole } from "@/shared/lib/session/sessionRoles";

/** The Sandboxed profile — the default for an ungated / manual pane (no role). */
export const DEFAULT_PROFILE_ID = "pf_sandbox";

/** Each session role's default profile id. Worker → Autonomous (trusted); director + the
 *  read-only coordination / observer roles → Read-only review; planner → its application role.
 *  Documentor (#1555) → Autonomous too: like the worker it must actually WRITE (its DOC_GLOBS prose
 *  docs), so it needs a write-permitting profile — the read-only profile's whole-tool write deny would
 *  mask the role gate's DOC_GLOBS carve-out (deny > allow). The role gate + the bsc-scope hook confine
 *  those writes to DOC_GLOBS, exactly as the worker's writes are confined to its owned lane. */
const ROLE_PROFILE: Record<SessionRole, string> = {
  worker: "pf_auto",
  director: "pf_review",
  triage: "pf_review",
  tester: "pf_review",
  reviewer: "pf_review",
  issuer: "pf_review",
  juror: "pf_review",
  documentor: "pf_auto",
  // Marketer (#2431): like the documentor it must actually WRITE (its marketing-content carve-out), so
  // it launches under the write-permitting Autonomous profile; the role gate + bsc-scope hook confine
  // its writes to the marketing globs.
  marketer: "pf_auto",
  planner: "sys_planner",
  // Designer (#2471) / Architect (#2755) / Librarian (#2787): the three app-owned studio sessions.
  // Read-only review is the closest packaged floor, but this mapping ONLY backs the generic role→profile
  // UI surfaces — it is NOT applied at launch. Their real launch (`StudioSessionMount` on TerminalHost,
  // #3357) sets `paneRoles` and deliberately NO `paneProfiles` entry, because `buildSessionSettings` ADDS
  // a profile's allowedCommands to the role's `restrictedAllow` surface — i.e. assigning a profile here
  // would WIDEN a session confined to one store CLI. Don't wire this into a launch path.
  designer: "pf_review",
  architect: "pf_review",
  librarian: "pf_review",
  "sound-designer": "pf_review",
  // Integrator (#4023): the same studio treatment — read-only review is the closest packaged floor, and
  // this mapping likewise only backs the generic role→profile UI surfaces. Its `net: "read"` widening
  // comes from the ROLE capability, not from a profile, so nothing here needs to grant it.
  integrator: "pf_review",
  // Debugger (#3322): the app's full-cap maintenance session WRITES code, so like the worker it launches
  // under the write-permitting Autonomous profile; its real launch (`DebugSessionMount` on TerminalHost,
  // #3326) renders bypass directly via the `isFullCapabilitySession` carve-out, so this only backs the
  // generic role→profile surfaces.
  debugger: "pf_auto",
  // Curator (#3092, epic #3087): the reusable-library post-landing actor. Read-only review is the
  // closest packaged floor; its real launch (P2b) renders the role gate + `restrictedAllow` (`bsc ui` +
  // `bsc graph`) directly. Its store writes go through `bsc ui`/`bsc graph` (Bash + the `ui` write-scope),
  // not the file-write tools, so the review profile's whole-tool write deny doesn't mask them.
  curator: "pf_review",
};

/** The default profile id for a role (or the Sandboxed default when there's no role). */
export function roleProfileId(role: SessionRole | undefined | null): string {
  return role ? ROLE_PROFILE[role] : DEFAULT_PROFILE_ID;
}

export function rotate90(m: number[][]): number[][] {
  const a = m.map((r) => [...r]);
  const n = a.length;
  for (let l = 0; l < Math.floor(n / 2); l++) {
    const f = l, e = n - 1 - l;
    for (let i = f; i < e; i++) {
      const o = i - f, t = a[f][i];
      a[f][i] = a[e - o][f];
      a[e - o][f] = a[e][e - o];
      a[e][e - o] = a[i][e];
      a[i][e] = t;
    }
  }
  return a;
}

// Kit lint rules → eslint preset (#2279) — the auto-firing enforcement a kit ships so an agent building
// an app on it can't quietly re-invent a component. This is the pure spine: the rule model lives in
// model.ts; here are the derivation (from each component's `wraps` hint), the author-declared merge, and
// the emitter that turns a kit's rules into plain eslint config (NO custom plugin — the dogfooded 80%).
//
// Config-level ONLY for now: `forbid-element` → `no-restricted-syntax` (the exact pattern this repo uses
// to force `<Box>`/`<Button>` over raw elements), `forbid-import` → `no-restricted-imports`. The
// generated app extends the emitted preset; every rule message carries the escape hatch so it teaches
// but allows a justified exception. Custom AST plugins, token rules, and non-eslint linters are follow-ups.
import type { ComponentRecord, KitRule } from "@/features/designs/lib/model";

/** The escape-hatch clause every rule message ends with — enforce, but allow a justified exception. */
export const ESCAPE_HATCH = "If truly required, add `// eslint-disable-next-line <rule> -- <reason>`.";

/** The human message for a rule (its own `message`, else a default that names `use` + the escape hatch). */
export function ruleMessage(r: KitRule): string {
  if (r.message) return r.message;
  const base =
    r.kind === "forbid-element"
      ? `Use the kit's <${r.use}> instead of a raw <${r.target}>.`
      : `Import ${r.use} from the kit instead of "${r.target}".`;
  return `${base} ${ESCAPE_HATCH}`;
}

/** Derive the flagship anti-duplication rules from the kit: one `forbid-element` per component that
 *  declares what raw intrinsic it `wraps` ("use <Button> not a raw <button>"). */
export function deriveRules(components: ComponentRecord[]): KitRule[] {
  return components
    .filter((c) => c.wraps)
    .map((c) => ({
      id: `derived:forbid-element:${c.wraps}`,
      kind: "forbid-element" as const,
      target: c.wraps!,
      use: c.name,
      componentId: c.id,
      derived: true,
    }));
}

/** The dedup key for a rule — a kit shouldn't forbid the same target twice. */
const ruleKey = (r: KitRule) => `${r.kind}:${r.target}`;

/** Merge derived + author-declared rules: an authored rule OVERRIDES a derived one for the same
 *  (kind, target), and adds any new ones. Authored wins so a kit can refine a derived message/target. */
export function mergeRules(derived: KitRule[], authored: KitRule[]): KitRule[] {
  const byKey = new Map(derived.map((r) => [ruleKey(r), r]));
  for (const a of authored) byKey.set(ruleKey(a), { ...a, derived: false });
  return [...byKey.values()];
}

/** The full ruleset for a kit's components: the derived anti-duplication rules merged with every
 *  component's author-declared `rules`. */
export function kitRules(components: ComponentRecord[]): KitRule[] {
  const authored = components.flatMap((c) => c.rules ?? []);
  return mergeRules(deriveRules(components), authored);
}

/** The rules a SINGLE component contributes/enforces — its derived `wraps` rule (if any) merged with
 *  its author-declared `rules`. Drives the pane's per-component Rules tab. */
export function componentRules(component: ComponentRecord): KitRule[] {
  return mergeRules(deriveRules([component]), component.rules ?? []);
}

/** The eslint `rules` fragment a kit's ruleset compiles to (only the rules that have entries appear). */
export interface EslintRulesConfig {
  "no-restricted-syntax"?: unknown[];
  "no-restricted-imports"?: unknown[];
}

/** Compile a ruleset into a plain eslint `rules` object — `forbid-element` rules fold into one
 *  `no-restricted-syntax` array (each a JSX-element selector + message); `forbid-import` rules into one
 *  `no-restricted-imports` `paths` list. */
export function toEslintRules(rules: KitRule[]): EslintRulesConfig {
  const syntax = rules
    .filter((r) => r.kind === "forbid-element")
    .map((r) => ({ selector: `JSXOpeningElement[name.name='${r.target}']`, message: ruleMessage(r) }));
  const imports = rules
    .filter((r) => r.kind === "forbid-import")
    .map((r) => ({ name: r.target, message: ruleMessage(r) }));

  const out: EslintRulesConfig = {};
  if (syntax.length) out["no-restricted-syntax"] = ["error", ...syntax];
  if (imports.length) out["no-restricted-imports"] = ["error", { paths: imports }];
  return out;
}

/** The eslint preset a kit ships — a flat-config fragment the generated app extends
 *  (`{ rules: { … } }`). Empty `rules` when the kit declares/derives nothing. */
export function toEslintPreset(components: ComponentRecord[]): { rules: EslintRulesConfig } {
  return { rules: toEslintRules(kitRules(components)) };
}

// Runtime-fault instrumentation adapters (#2262, epic #2258) — the per-environment registry + shim
// renderer the planner uses to bake fault instrumentation into every generated app at the Deployment
// stage. Each app ships ALREADY INSTRUMENTED for its target environment: `local` is implemented (the
// shim POSTs the fault/heartbeat envelope to the bsc localhost collector, #2261); `aws`/`vercel`/`fly`/
// `docker` are declared-but-PLANNED seams so the coverage gap is explicit, never silent.
//
// DATA is externalized to `@data/runtime-fault/*` (#2027 P1): the registry (`adapters.json`) + the
// per-stack shim TEMPLATES (`shims/*.tmpl`). This module keeps only the TYPES + the accessors + the
// pure renderer. Pure (no React/Tauri) — import from `@/features/planner/lib/runtimeFault`.

import adaptersEmbedded from "@data/runtime-fault/adapters.json";
import jsShim from "@data/runtime-fault/shims/js.tmpl?raw";
import pythonShim from "@data/runtime-fault/shims/python.tmpl?raw";
import rustShim from "@data/runtime-fault/shims/rust.tmpl?raw";
import goShim from "@data/runtime-fault/shims/go.tmpl?raw";
import { overlayFile, overlayRaw } from "@/shared/lib/core/configOverrides";

/** Whether an environment's instrumentation is built (`implemented`) or a declared future seam (`planned`). */
export type AdapterStatus = "implemented" | "planned";

/** One environment's runtime-fault instrumentation adapter. `shims` (lang → template key) is present
 *  only on an `implemented` adapter that ships shim templates (today: `local`). */
export interface RuntimeFaultAdapter {
  status: AdapterStatus;
  label: string;
  transport: string;
  description: string;
  shims?: Record<string, string>;
}

export interface RuntimeFaultRegistry {
  heartbeatSeconds: number;
  envelope: { endpoint: string; contentType: string; fields: Record<string, string> };
  adapters: Record<string, RuntimeFaultAdapter>;
}

// The config-dir copy (#2047) overlays the embedded default — editable without a rebuild.
const registry = overlayFile("runtime-fault/adapters.json", adaptersEmbedded) as unknown as RuntimeFaultRegistry;

// Shim templates by template KEY (the `shims` map's values), each overlaid so a config-dir edit takes
// effect without a rebuild (parity with the deploy taxonomy / role-caps overlays).
const SHIM_TEMPLATES: Record<string, string> = {
  js: overlayRaw("runtime-fault/shims/js.tmpl", jsShim),
  python: overlayRaw("runtime-fault/shims/python.tmpl", pythonShim),
  rust: overlayRaw("runtime-fault/shims/rust.tmpl", rustShim),
  go: overlayRaw("runtime-fault/shims/go.tmpl", goShim),
};

/** The whole registry (heartbeat cadence + envelope contract + adapters). */
export function runtimeFaultRegistry(): RuntimeFaultRegistry {
  return registry;
}

/** Every environment → adapter (implemented + planned), so the UI/directive can list them WITH their
 *  status — no silent omission of the not-yet-built ones (an acceptance requirement of #2262). */
export function runtimeFaultAdapters(): Record<string, RuntimeFaultAdapter> {
  return registry.adapters;
}

/** The adapter for an environment, or `undefined` if the environment isn't in the registry. */
export function selectAdapter(env: string): RuntimeFaultAdapter | undefined {
  return registry.adapters[env];
}

/** Whether an environment's instrumentation is actually built (vs a planned seam). */
export function isImplemented(env: string): boolean {
  return selectAdapter(env)?.status === "implemented";
}

/** The stack languages an environment ships shim templates for (`[]` for a planned/unknown env). */
export function shimLanguages(env: string): string[] {
  return Object.keys(selectAdapter(env)?.shims ?? {});
}

/** The per-project values baked into a shim at generation. */
export interface ShimVars {
  ingestPort: number | string;
  projectKey: string;
  ingestToken: string;
  release: string;
}

/**
 * Render the shim for an environment + stack language with the per-project values substituted, ready
 * to write into the generated app. Returns `null` when the environment/language has no IMPLEMENTED shim
 * (a planned env, an unknown env, or a language the adapter doesn't cover) so the caller can degrade
 * gracefully. Throws if any `{{PLACEHOLDER}}` is left unsubstituted — a hard guard so a generated app
 * never ships a literal `{{…}}` (a broken shim that silently reports nothing).
 */
export function renderShim(env: string, lang: string, vars: ShimVars): string | null {
  const adapter = selectAdapter(env);
  if (!adapter || adapter.status !== "implemented" || !adapter.shims) return null;
  const key = adapter.shims[lang];
  if (!key) return null;
  const template = SHIM_TEMPLATES[key];
  if (template === undefined) return null;

  const hb = registry.heartbeatSeconds;
  const subs: Record<string, string> = {
    INGEST_PORT: String(vars.ingestPort),
    PROJECT_KEY: vars.projectKey,
    INGEST_TOKEN: vars.ingestToken,
    RELEASE: vars.release,
    HEARTBEAT_SECONDS: String(hb),
    HEARTBEAT_MS: String(hb * 1000),
  };
  const out = template.replace(/\{\{(\w+)\}\}/g, (whole, name: string) =>
    Object.prototype.hasOwnProperty.call(subs, name) ? subs[name] : whole,
  );
  const leftover = out.match(/\{\{\w+\}\}/);
  if (leftover) {
    throw new Error(`runtime-fault shim (${env}/${lang}) left an unsubstituted placeholder: ${leftover[0]}`);
  }
  return out;
}

// safeInvoke / fireInvoke (#1497) — typed wrappers for the ubiquitous ad-hoc Tauri error handling.
// The codebase has 100+ `invoke(...).catch(...)` sites with inconsistent conventions (silent
// swallow, fallback return, log). These two cover the common cases so the intent is explicit and a
// failed command degrades the same way everywhere.

import { invoke, type InvokeArgs } from "@tauri-apps/api/core";
import { startInvokeTimer } from "@/shared/lib/core/invokeTiming";

/**
 * `invoke()` that resolves to `fallback` instead of rejecting — for the `invoke(...).catch(() =>
 * <fallback>)` reads. Pass `undefined` for a command with no args. `onError` observes the swallowed
 * error (e.g. to log it) without changing the fallback. Round-trip is timed (#3626) — a slow call
 * gets a `[invoke]` line in the app log's perf scope.
 */
export async function safeInvoke<T>(
  cmd: string,
  args: InvokeArgs | undefined,
  fallback: T,
  onError?: (e: unknown) => void,
): Promise<T> {
  const done = startInvokeTimer(cmd);
  try {
    return await invoke<T>(cmd, args);
  } catch (e) {
    onError?.(e);
    return fallback;
  } finally {
    done();
  }
}

/** Fire-and-forget `invoke()` whose rejection is swallowed (optionally observed via `onError`).
 *  Round-trip is timed (#3626) like `safeInvoke`. */
export function fireInvoke(cmd: string, args?: InvokeArgs, onError?: (e: unknown) => void): void {
  const done = startInvokeTimer(cmd);
  void invoke(cmd, args).catch((e) => { onError?.(e); }).finally(done);
}

// SCALAR / accumulate trace-programs (#3220, epic #3215) — the algorithms whose whole state is a handful
// of NAMED VARIABLES rather than a container: no array, no graph, just counters rolling forward. Fibonacci
// is the family's proof, and it is the shape the seeded `fibonacci.rs` / `fibonacci.ts` impls (two impls,
// ONE algorithm — both the iterative bottom-up form) already ship.
//
// Written over a TracedScalar, so the animation is DERIVED from the recurrence's real execution: the `add`
// verb IS `b += a` (the recurrence itself, as an accumulation), and the `set` verbs are the roll-forward.
// This is the first caller of `runScalarAlgorithm` — the `<ScalarView>` renderer previously only appeared
// as a scene panel.
import type { TracedScalar } from "@/features/algorithms/lib/tracer";

/** A visualizable scalar algorithm — its real logic over a {@link TracedScalar} + the initial variable map
 *  to seed it (the algorithm reads its parameters straight out of that state). */
export interface ScalarProgram {
  run: (s: TracedScalar) => void;
  defaultInput: Record<string, number | string>;
}

/** The fibonacci seed — big enough that the accumulation visibly runs, small enough to stay watchable. */
const FIB_MOCK: Record<string, number | string> = { n: 10 };

/**
 * The nth Fibonacci number (0-indexed: F0 = 0, F1 = 1), iterated bottom-up — the same algorithm the seeded
 * `fibonacci.rs` / `fibonacci.ts` impls ship, expressed in the two-variable in-place form:
 *
 *   `b += a` (the recurrence, emitted as the `add` accumulate verb) then `a ←` the previous `b`.
 *
 * Reads `n` from the traced state; leaves the answer in `fib`. `n < 2` returns `n` immediately (F0 = 0,
 * F1 = 1), which is a legitimately short trace — the base case really is one step.
 */
export function fibonacci(s: TracedScalar): void {
  const n = Number(s.get("n") ?? 0);
  if (!Number.isFinite(n) || n < 2) {
    s.set("fib", Number.isFinite(n) ? Math.max(0, n) : 0);
    return;
  }
  s.set("a", 0); // F(i-2)
  s.set("b", 1); // F(i-1)
  for (let i = 2; i <= n; i++) {
    s.set("i", i);
    const a = Number(s.get("a"));
    const b = Number(s.get("b"));
    s.add("b", a); // b ← a + b — the recurrence, as an accumulation
    s.set("a", b); // a ← the previous b
  }
  s.set("fib", Number(s.get("b")));
}

/** The visualizable scalar algorithms, keyed by base name (#3220). */
export const SCALAR_PROGRAMS: Record<string, ScalarProgram> = {
  fibonacci: { run: fibonacci, defaultInput: FIB_MOCK },
};

/** Serialize a scalar seed to the "your input" text form — just `n` (the family's single parameter). */
export function scalarToText(input: Record<string, number | string>): string {
  return String(input.n ?? "");
}

/**
 * Serialize an ARBITRARY scalar seed to `name=value` pairs — the seam a STORED trace-program uses (#4162).
 *
 * Deliberately not {@link scalarToText}: that renders `input.n` alone, which is right for the in-app
 * fibonacci (whose single parameter IS n) and silently wrong for any other seed — a stored program seeded
 * `{ start: 3, limit: 9 }` would render an EMPTY field and parse back as `{ n }`, animating something its
 * author never wrote. A stored program can seed any variables, so its seam names them.
 */
export function scalarSeedToText(input: Record<string, number | string>): string {
  return Object.entries(input)
    .map(([k, v]) => `${k}=${v}`)
    .join(", ");
}

/**
 * Parse `name=value` pairs into a scalar seed — the generic counterpart to {@link scalarSeedToText}.
 * Numeric-looking values become numbers; everything else stays a string (a `TracedScalar` holds both).
 * An EMPTY seed is valid — an algorithm may set every variable it uses.
 *
 * @throws Error (shown under the "your input" field) when a pair has no `=` or an empty name.
 */
export function parseScalarSeed(text: string): Record<string, number | string> {
  const t = text.trim();
  if (t.length === 0) return {};
  const out: Record<string, number | string> = {};
  for (const part of t.split(",")) {
    const eq = part.indexOf("=");
    if (eq < 0) throw new Error(`"${part.trim()}" must be name=value (e.g. n=10)`);
    const name = part.slice(0, eq).trim();
    const raw = part.slice(eq + 1).trim();
    if (!name) throw new Error(`"${part.trim()}" has no variable name`);
    const num = Number(raw);
    out[name] = raw !== "" && Number.isFinite(num) ? num : raw;
  }
  return out;
}

/**
 * Parse the "your input" text into a scalar seed — a single non-negative integer `n`. Throws a helpful
 * `Error` (shown under the field) on empty, non-numeric, negative, fractional, or unwatchably-large input.
 */
export function parseScalarInput(text: string): Record<string, number | string> {
  const t = text.trim();
  if (t.length === 0) throw new Error("Enter n, e.g. 10");
  const n = Number(t);
  if (!Number.isFinite(n)) throw new Error(`"${t}" is not a number`);
  if (!Number.isInteger(n) || n < 0) throw new Error("n must be a whole number, 0 or greater");
  if (n > 40) throw new Error("Keep n at 40 or less so the animation stays watchable");
  return { n };
}

// The `scalar` viz kit's MOTION wiring (#3268, epic #3220/#2942) — injects the compiled motion CSS
// (set / add / compare) into the live ScalarView. The animation DATA lives in a SHARED, feature-agnostic
// home (`@/shared/ui/kit/scalarVizAnimations`) so BOTH consumers read ONE definition: this renderer AND a
// (later) `scalar-viz` Designs builtin kit. `ScalarView`'s root carries the applying classes ({@link
// SCALAR_VIZ_ANIM_CLASSES}); its chips only stamp `data-op`. Mirrors stackViewMotion / arrayViewMotion.
import { animClassName, compileAnimationsCss, kitAnimations } from "@/shared/ui/kit";
import { SCALAR_VIZ_KIT_ID, SCALAR_VIZ_ANIMATIONS } from "@/shared/ui/kit/scalarVizAnimations";

// Re-export the shared data so this renderer's public surface (and the algorithms barrel) is unchanged.
export { SCALAR_VIZ_KIT_ID, SCALAR_VIZ_ANIMATIONS };

/** The applying classes the renderer's root carries so the state-scoped rules match its chips. */
export const SCALAR_VIZ_ANIM_CLASSES: string = SCALAR_VIZ_ANIMATIONS.map((a) =>
  animClassName({ kit: SCALAR_VIZ_KIT_ID, name: a.name }),
).join(" ");

/** The compiled motion CSS — produced ONCE from {@link SCALAR_VIZ_ANIMATIONS}. Pure. */
export const SCALAR_VIZ_MOTION_CSS: string = compileAnimationsCss(
  kitAnimations([{ id: SCALAR_VIZ_KIT_ID, animations: SCALAR_VIZ_ANIMATIONS }]),
);

const STYLE_ID = "bsc-scalar-viz-animations";

/** Inject the compiled scalar motion CSS into a dedicated managed `<style>` (idempotent). `doc` param'd for
 *  tests. Mirrors `ensureStackViewMotion` on its own style id. */
export function ensureScalarViewMotion(doc: Document = document): void {
  if (!SCALAR_VIZ_MOTION_CSS) return;
  let el = doc.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!el) {
    el = doc.createElement("style");
    el.id = STYLE_ID;
    doc.head.appendChild(el);
  }
  if (el.textContent !== SCALAR_VIZ_MOTION_CSS) el.textContent = SCALAR_VIZ_MOTION_CSS;
}

// The `scalar-viz` kit's MOTION library as DATA (#3268, epic #3171/#2942) — the set / add / compare
// animations for the scalar-state renderer (counters, accumulators, the current pointer), authored as
// {@link KitAnimation} data and compiled by the kit-motion engine. The scalar twin of the
// array/matrix/graph/stack motion sets.
//
// ── WHY THIS LIVES IN shared/ui/kit ──────────────────────────────────────────────────────────────────
// Like the array (#3194) + matrix/graph (#3242) + stack (#3266) sets: two consumers in two features, one
// definition — the Algorithms ScalarView renderer (`features/algorithms/.../scalarViewMotion.ts`) injects
// the compiled CSS, and the Designs seed can register `scalar-viz` as a recoverable builtin kit (a later
// slice). Feature-agnostic viz-motion, so it lives HERE to avoid a designs↔algorithms cycle.
//
// STATE-TRIGGER SEAM (#3058): each selector IS the data-state ScalarView stamps on the touched variable's
// chip (`[data-op="set"]`, …) — so a rule fires exactly when a variable changes.

import type { KitAnimation } from "@/shared/ui/kit/animations";

/** The scalar-visualization motion kit id — `.scalar-viz-anim-<name>` + `@keyframes bsc-scalar-viz-<name>`. */
export const SCALAR_VIZ_KIT_ID = "scalar-viz";

