// Multi-structure SCENE programs (#3259, epic #3171) — algorithms whose mechanics live across several
// structures, authored against a `TracedScene` so they animate as synchronized panels. This is the
// multi-structure twin of the single-datatype programs (sorts.ts / matrixTransforms.ts / graphAlgos.ts):
// each program declares NAMED panels (`scene.graph`, `scene.array`) and drives them with the ordinary
// tracer verbs; the scene folds every op into a `PanelsFrame` and the player lays the panels side by side.
import { type TracedScene, type TracedTree, type GraphInput } from "@/features/algorithms/lib/tracer";
import { WEIGHTED_GRAPH, DEFAULT_GRAPH, graphToText, parseGraphInput } from "@/features/algorithms/viz/examples/graphAlgos";
import { SORT_MOCK, parseSortInput } from "@/features/algorithms/viz/examples/sort";

/** A scene's INPUT SEAM (#3284) — its default seed plus how to render/parse that seed as the editable "your
 *  input" text. A scene declares its own seam so it can seed on a graph, a number array, … (not just a
 *  graph); `serialize`/`parse` round-trip the seed to/from the field text. */
export interface SceneSeed<I> {
  default: I;
  hint: string;
  serialize: (input: I) => string;
  parse: (text: string) => I;
}

/** A multi-structure scene program keyed by BASE NAME. `run` drives the scene from the seed input; `seed`
 *  carries the default + its input seam. The input type is ERASED to `unknown` in the stored form (so
 *  `SCENE_PROGRAMS` is one uniform map across graph- and array-seeded scenes) — {@link defineScene} keeps
 *  authoring type-safe and does the erasing cast in ONE place. */
export interface SceneProgram {
  run: (scene: TracedScene, input: unknown) => void;
  seed: SceneSeed<unknown>;
}

/** Pair a typed scene `run` with a matching typed {@link SceneSeed}, erasing the input type so the result
 *  drops into the uniform `SCENE_PROGRAMS` map. The one cast site — authoring stays fully typed. */
function defineScene<I>(run: (scene: TracedScene, input: I) => void, seed: SceneSeed<I>): SceneProgram {
  return { run: run as (scene: TracedScene, input: unknown) => void, seed: seed as SceneSeed<unknown> };
}

/** A graph seed seam — the adjacency-list "your input" field (Dijkstra / BFS). */
function graphSeed(def: GraphInput): SceneSeed<GraphInput> {
  return { default: def, hint: "An adjacency list — one node per line: a: b, c", serialize: graphToText, parse: parseGraphInput };
}

/** A number-array seed seam — the comma/space field (the sorts). */
function arraySeed(def: readonly number[]): SceneSeed<readonly number[]> {
  return { default: def, hint: "Comma- or space-separated numbers", serialize: (a) => a.join(", "), parse: parseSortInput };
}

/** The ∞ sentinel for the distance array — the array panel holds numbers, so an unreached node reads as a
 *  large value (every real distance in the sample graph is well under it). */
const INF = 99;

/** One priority-queue entry — a node and its tentative distance (the heap key). */
interface HeapEntry {
  dist: number;
  node: string;
}

/**
 * A binary MIN-heap (keyed by `dist`) that mirrors itself into a {@link TracedTree} panel (#3270) — this is
 * Dijkstra's real priority queue drawn as a heap tree. Node id = the entry's array index (`h<i>`), parent =
 * `h<floor((i-1)/2)>`, so the heap-as-array IS a complete binary tree. A `push` sifts up; a `pop` swaps
 * root↔last, removes the last, then sifts down (the canonical heap ops) — each reflected as insert / swap /
 * remove on the tree, so the sift animates. Used with LAZY DELETION: Dijkstra pushes a fresh entry per
 * improvement and skips a popped entry whose node is already settled.
 */
class HeapPanel {
  private readonly h: HeapEntry[] = [];
  constructor(private readonly tree: TracedTree) {}

  get size(): number {
    return this.h.length;
  }

  private id(i: number): string {
    return `h${i}`;
  }
  private label(e: HeapEntry): string {
    return `${e.node}:${e.dist}`;
  }

  /** Enqueue `(dist, node)` — insert at the back, then sift up. */
  push(dist: number, node: string): void {
    let i = this.h.length;
    const entry = { dist, node };
    this.h.push(entry);
    this.tree.insert(this.id(i), this.label(entry), i === 0 ? undefined : this.id(Math.floor((i - 1) / 2)));
    while (i > 0) {
      const p = Math.floor((i - 1) / 2);
      if (this.h[p].dist <= this.h[i].dist) break;
      [this.h[i], this.h[p]] = [this.h[p], this.h[i]];
      this.tree.swap(this.id(i), this.id(p)); // exchange the two nodes' values (the sift)
      i = p;
    }
  }

  /** Extract the min — swap root↔last, drop the last node, then sift down. */
  pop(): HeapEntry | undefined {
    if (this.h.length === 0) return undefined;
    const last = this.h.length - 1;
    this.tree.visit(this.id(0)); // highlight the min sitting at the root
    if (last > 0) {
      [this.h[0], this.h[last]] = [this.h[last], this.h[0]];
      this.tree.swap(this.id(0), this.id(last)); // move the min to the last slot
    }
    const min = this.h.pop()!; // remove the min (now at the end)
    this.tree.remove(this.id(last)); // drop the last tree node
    let i = 0;
    const nn = this.h.length;
    for (;;) {
      const l = 2 * i + 1;
      const r = 2 * i + 2;
      let s = i;
      if (l < nn && this.h[l].dist < this.h[s].dist) s = l;
      if (r < nn && this.h[r].dist < this.h[s].dist) s = r;
      if (s === i) break;
      [this.h[i], this.h[s]] = [this.h[s], this.h[i]];
      this.tree.swap(this.id(i), this.id(s));
      i = s;
    }
    return min;
  }
}

/**
 * Dijkstra as a SCENE (#3259 · #3268 · #3270) — FOUR panels animating TOGETHER: a `graph`, its priority-queue
 * `heap` (a min-heap tree), a `distance` array, and a `state` SCALAR readout. This is the canonical
 * multi-structure example, now with Dijkstra's *complete* mechanics on screen: you watch the graph get
 * explored (current → visit → relax) WHILE the heap sifts each frontier entry into place and pops the
 * smallest, the distance array fills in, and the scalar state ticks. Real lazy-deletion Dijkstra over the
 * SAME `TracedGraph` — the heap is the actual priority queue driving the selection, not a mirror.
 */
export function dijkstraScene(scene: TracedScene, input: GraphInput): void {
  const g = scene.graph("graph", input);
  const ids = g.ids();
  const n = ids.length;
  const idx = new Map(ids.map((id, i) => [id, i]));

  const distVals: number[] = ids.map((_, i) => (i === 0 ? 0 : INF)); // start at 0, everything else ∞
  const heap = new HeapPanel(scene.tree("heap")); // the priority queue, drawn as a min-heap tree
  const dist = scene.array("distance", distVals);
  const state = scene.scalar("state", { current: "—", dist: 0, settled: 0 }); // the running state readout
  const visited = new Array<boolean>(n).fill(false);

  g.mark(ids[0], "start");
  heap.push(0, ids[0]); // enqueue the start
  g.frontier(ids[0]);
  while (heap.size > 0) {
    const top = heap.pop()!; // extract the min-distance frontier entry
    const u = idx.get(top.node);
    if (u === undefined || visited[u]) continue; // stale entry (lazy deletion) — already settled

    visited[u] = true;
    g.current(ids[u]);              // point at the node being settled
    dist.mark(u, "min");            // lock in its distance cell
    state.set("current", ids[u]);   // which node we're finalizing
    state.set("dist", distVals[u]); // its now-final shortest distance
    state.add("settled", 1);        // one more node done
    g.visit(ids[u]);                // finish it

    for (const nb of g.neighbours(ids[u])) {
      const v = idx.get(nb.to);
      if (v === undefined || visited[v]) continue;
      g.relax(ids[u], nb.to); // light the edge being considered
      const cand = distVals[u] + nb.weight;
      if (cand < distVals[v]) {
        distVals[v] = cand;
        dist.set(v, cand);       // the improved distance lands — the array cell flashes
        heap.push(cand, nb.to);  // enqueue the improved entry into the priority queue
        g.frontier(nb.to);       // (re-)enter the frontier
      }
    }
  }
}

/**
 * BFS as a SCENE (#3266) — a `graph` panel + a FIFO `queue` panel animating TOGETHER. The frontier queue
 * is the structure that MAKES it breadth-first: neighbours are enqueued (push to the back) as they're
 * discovered, and the FRONT is dequeued to visit next, so nodes come out in distance-from-start order.
 * Real BFS over the SAME `TracedGraph`; the queue mirrors its frontier faithfully (push/pop = enqueue/
 * dequeue). This is the honest fit for the stack/queue renderer — unlike Dijkstra's PRIORITY queue (a heap).
 */
export function bfsScene(scene: TracedScene, input: GraphInput): void {
  const g = scene.graph("graph", input);
  const q = scene.stack("queue", "queue"); // FIFO frontier — front dequeues, back enqueues
  const start = g.ids()[0];
  if (!start) return;
  const seen = new Set<string>([start]);

  g.mark(start, "start");
  q.push(start);        // enqueue the start
  g.frontier(start);
  while (q.size > 0) {
    const u = q.pop() as string; // dequeue the FRONT
    g.current(u);
    g.visit(u);
    for (const nb of g.neighbours(u)) {
      if (seen.has(nb.to)) continue;
      seen.add(nb.to);
      g.relax(u, nb.to); // light the tree edge to the newly discovered node
      q.push(nb.to);     // enqueue it
      g.frontier(nb.to);
    }
  }
}

/**
 * Merge sort as a SCENE (#3284 · #3286) — an `array` panel (sorted in place) plus the two runs as SEPARATE
 * `leftRun` / `rightRun` panels, extracted from the array each merge. `scene.compareAcross(leftRun, i,
 * rightRun, j)` flashes both run fronts in ONE beat (the merge decision), and `scene.move(winner, …, array,
 * k)` slides the winner into the output — the merge decision AND the placement are now CROSS-PANEL, one beat
 * each. This is the demonstrator for the cross-panel verbs: the two runs live in different panels, exactly
 * the shape a single-array trace hid.
 */
export function mergeSortScene(scene: TracedScene, input: readonly number[]): void {
  const n = input.length;
  const arr = scene.array("array", input); // sorted in place — the winners land here

  for (let width = 1; width < n; width *= 2) {
    for (let lo = 0; lo < n; lo += 2 * width) {
      const mid = Math.min(lo + width, n);
      const hi = Math.min(lo + 2 * width, n);
      if (mid >= hi) continue; // a lone tail run — already sorted, nothing to merge

      // Extract the two runs into their own panels (silent reads of the array's current values).
      const leftVals: number[] = [];
      const rightVals: number[] = [];
      for (let k = lo; k < mid; k++) leftVals.push(arr.get(k));
      for (let k = mid; k < hi; k++) rightVals.push(arr.get(k));
      const leftRun = scene.array("leftRun", leftVals);
      const rightRun = scene.array("rightRun", rightVals);

      // Merge the two run panels back into arr[lo..hi), comparing + moving ACROSS panels.
      let i = 0;
      let j = 0;
      let k = lo;
      while (i < leftVals.length && j < rightVals.length) {
        leftRun.cursor("i", i); // the two front-pointers walk their runs
        rightRun.cursor("j", j);
        if (scene.compareAcross(leftRun, i, rightRun, j) <= 0) scene.move(leftRun, i++, arr, k++);
        else scene.move(rightRun, j++, arr, k++);
      }
      while (i < leftVals.length) scene.move(leftRun, i++, arr, k++); // drain the remaining run
      while (j < rightVals.length) scene.move(rightRun, j++, arr, k++);
    }
  }
  arr.markSorted();
}

/** The scene programs, keyed by base name (merged LAST into the registry, so a scene supersedes any
 *  single-structure program of the same name — e.g. `dijkstra` → graph+dist, `bfs` → graph+queue,
 *  `merge-sort` → array+buffer). Each carries its own input {@link SceneSeed} (graph or number-array). */
export const SCENE_PROGRAMS: Record<string, SceneProgram> = {
  dijkstra: defineScene(dijkstraScene, graphSeed(WEIGHTED_GRAPH)),
  bfs: defineScene(bfsScene, graphSeed(DEFAULT_GRAPH)),
  "merge-sort": defineScene(mergeSortScene, arraySeed(SORT_MOCK)),
};

// Pure scheduler core for Automations (#142). No React / no Tauri here — just the
// data model and the deterministic logic (next-run computation, target
// resolution, payload building) so it can be unit-tested in isolation. The tick
// loop and PTY dispatch live in useScheduler; CRUD lives in the store.

import { nextCronRun } from "@/features/automations/lib/cron";
import { clamp } from "@/shared/lib/core/math";

export type Every = "minute" | "hour" | "day" | "weekday";
export type AutomationActionKind = "command";
export type RunStatus = "ok" | "skipped" | "fail";

export interface SimpleWhen {
  kind: "simple";
  every: Every;
  /** "HH:MM" for day/weekday; ":MM" or "MM" for hour; ignored for minute. */
  at: string;
}
export interface CronWhen {
  kind: "cron";
  /** Standard 5-field cron expression. */
  expr: string;
}
export type AutomationWhen = SimpleWhen | CronWhen;

export interface AutomationRun {
  at: number;        // epoch ms
  status: RunStatus;
  note: string;
}

export interface Automation {
  id: string;
  name: string;
  armed: boolean;
  when: AutomationWhen;
  /** Tab resolved at fire time by name (survives reordering); pane by index. */
  targetTab: string;
  targetPaneIdx: number;
  action: AutomationActionKind;
  command?: string;   // action === "command"
  lastRunAt: number | null;
  nextRunAt: number | null;
  runs: AutomationRun[];
}

/** Keep at most this many run records per automation. */
export const MAX_RUNS = 25;

/** Parse the minute component out of an hour spec ("15", ":15", "x:15"). */
function parseMinute(at: string): number {
  const m = at.replace(/^.*:/, "").trim();
  const n = parseInt(m, 10);
  return Number.isFinite(n) ? clamp(n, 0, 59) : 0;
}

/** Parse "HH:MM" into [hours, minutes], clamped; missing parts default to 0. */
function parseHourMinute(at: string): [number, number] {
  const [h, m] = at.split(":");
  const hh = clamp(parseInt(h ?? "0", 10) || 0, 0, 23);
  const mm = clamp(parseInt(m ?? "0", 10) || 0, 0, 59);
  return [hh, mm];
}

function isWeekend(d: Date): boolean {
  const day = d.getDay();
  return day === 0 || day === 6; // Sun or Sat
}

/**
 * The next fire time strictly after `fromMs`, in local time, or null if the
 * spec is unsupported. v1 supports minute/hour/day/weekday; week/month are a
 * follow-up.
 */
export function computeNextRun(when: AutomationWhen, fromMs: number): number | null {
  if (when.kind === "cron") return nextCronRun(when.expr, fromMs);

  const from = new Date(fromMs);

  if (when.every === "minute") {
    // Next whole-minute boundary after `from`.
    return Math.floor(fromMs / 60000) * 60000 + 60000;
  }

  if (when.every === "hour") {
    const mm = parseMinute(when.at);
    const c = new Date(from);
    c.setSeconds(0, 0);
    c.setMinutes(mm);
    if (c.getTime() <= fromMs) c.setHours(c.getHours() + 1);
    return c.getTime();
  }

  if (when.every === "day" || when.every === "weekday") {
    const [hh, mm] = parseHourMinute(when.at);
    const c = new Date(from);
    c.setSeconds(0, 0);
    c.setHours(hh, mm);
    if (c.getTime() <= fromMs) c.setDate(c.getDate() + 1);
    if (when.every === "weekday") {
      while (isWeekend(c)) c.setDate(c.getDate() + 1);
    }
    return c.getTime();
  }

  return null;
}

export interface TabLike { name: string; layout: string }

/** Pane count for a "C×R" layout string. */
export function paneCount(layout: string): number {
  const [c, r] = layout.split("×").map(n => parseInt(n, 10));
  return (c || 0) * (r || 0);
}

/**
 * Resolve an automation's (tab name, pane index) target to a live pane id
 * `t{tabIdx}p{paneIdx}`, or null when the target tab is gone, the pane index is
 * outside the tab's layout, or the pane is disabled. The tab is matched by name
 * so it tracks renamed/reordered tabs.
 */
export function resolveTargetPane(
  targetTab: string,
  targetPaneIdx: number,
  tabs: TabLike[],
  disabledPanes: Record<string, boolean>,
): string | null {
  const tabIdx = tabs.findIndex(t => t.name === targetTab);
  if (tabIdx < 0) return null;
  if (targetPaneIdx < 0 || targetPaneIdx >= paneCount(tabs[tabIdx].layout)) return null;
  const paneId = `t${tabIdx}p${targetPaneIdx}`;
  if (disabledPanes[paneId]) return null;
  return paneId;
}

/**
 * The text payload to write into the target pane for an automation, or null if
 * the command is empty. A trailing carriage return is the caller's responsibility.
 */
export function dispatchPayload(a: Automation): string | null {
  const cmd = (a.command ?? "").trim();
  return cmd.length > 0 ? cmd : null;
}

/** Armed automations whose nextRunAt is due (non-null and ≤ now). */
export function dueAutomations(automations: Automation[], nowMs: number): Automation[] {
  return automations.filter(a => a.armed && a.nextRunAt != null && a.nextRunAt <= nowMs);
}

/** Append a run (capped to MAX_RUNS, newest first). */
export function appendRun(runs: AutomationRun[], run: AutomationRun): AutomationRun[] {
  return [run, ...runs].slice(0, MAX_RUNS);
}

/**
 * Map a planning automation suggestion (#174) to a scheduler {@link Automation} input.
 * A cron `schedule` becomes an **armed** cron trigger; an on-demand suggestion (no
 * schedule) is a saved-but-**unarmed** command the user can arm or run. The command fires
 * into `targetTab`, pane 0 (the project's launched tab).
 */
export function suggestionToAutomation(
  s: { name: string; command: string; schedule?: string },
  targetTab: string,
): Omit<Automation, "id" | "lastRunAt" | "nextRunAt" | "runs"> {
  const when: AutomationWhen = s.schedule
    ? { kind: "cron", expr: s.schedule }
    : { kind: "simple", every: "day", at: "09:00" };
  return {
    name: s.name,
    armed: !!s.schedule,
    when,
    targetTab,
    targetPaneIdx: 0,
    action: "command",
    command: s.command,
  };
}

// Array SEARCH trace-programs (#3220, epic #3215) — the real search algorithms written over a TracedArray,
// so the animation is DERIVED from each search's own execution: linear search walks every cell left to
// right; binary search halves its window, probing only the midpoints. There are no hand-drawn frames — the
// tracer records exactly what the code does, and the two look completely different because they ARE.
//
// THE OP VOCABULARY (#3220): a search examines ONE cell against an EXTERNAL target, so it emits `probe`
// (single-cell) rather than the sorts' pairwise `compare` — see the `ArrayOp` doc in lib/trace.ts. The hit
// is the terminal `found` mark (`TracedArray.found`), the search-family twin of the sorts' `markSorted`.
//
// Keyed by base name (`binary-search`, `linear-search`) like the sorts, so the seeded Rust impls
// (`binary-search.rs` / `linear-search.rs`) animate via their JS trace-program.
import type { TracedArray } from "@/features/algorithms/lib/tracer";
import { parseSortInput } from "@/features/algorithms/viz/examples/sort";

/** A search's input — the cells to search plus the target being looked for (the value that is NOT in the
 *  array's own vocabulary, which is exactly why a search probes rather than compares). */
export interface SearchInput {
  values: number[];
  target: number;
}

/** A visualizable search algorithm — its real logic over a {@link TracedArray} + the array/target to seed
 *  it. `run` returns the found index (`-1` when absent), so the program is a genuine search, not a
 *  frame-emitter. */
export interface SearchProgram {
  run: (a: TracedArray, target: number) => number;
  defaultInput: SearchInput;
}

/** The linear-search seed — deliberately UNSORTED (a linear scan needs no order) with the target late in
 *  the array, so the walk is visible before the hit. */
const LINEAR_MOCK: SearchInput = { values: [5, 2, 9, 1, 6, 3, 8, 4, 7], target: 3 };

/** The binary-search seed — SORTED (binary search's precondition), with a target that takes several
 *  halvings to reach, so the shrinking window reads clearly. */
const BINARY_MOCK: SearchInput = { values: [1, 3, 4, 7, 9, 12, 15, 18, 21], target: 15 };

/**
 * Linear search — walk left to right, probing each cell against the target, and stop at the FIRST hit.
 * Returns that index, or `-1` when the target is absent. Every cell it looks at emits a `probe`; the hit
 * ends on a terminal `found` mark.
 */
export function linearSearch(a: TracedArray, target: number): number {
  for (let i = 0; i < a.length; i++) {
    a.cursor("i", i);
    if (a.probe(i) === target) {
      a.found(i);
      return i;
    }
  }
  return -1;
}

/**
 * Binary search over a SORTED array — halve the live window `[lo, hi)` each step, probing its midpoint and
 * discarding the half that cannot contain the target. Returns the index of the hit, or `-1` when absent.
 * The `lo` / `mid` / `hi` cursors ride each frame, so the window visibly closes in.
 *
 * The array is searched AS GIVEN (the program never sorts it first) — instrumented execution shows what
 * the real algorithm does, including on input that breaks its sorted precondition.
 */
export function binarySearch(a: TracedArray, target: number): number {
  let lo = 0;
  let hi = a.length; // exclusive — the window is [lo, hi)
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    a.cursor("lo", lo);
    a.cursor("hi", hi - 1); // the pill points at the last cell still in the window
    a.cursor("mid", mid);
    const v = a.probe(mid);
    if (v === target) {
      a.found(mid);
      return mid;
    }
    if (v < target) lo = mid + 1;
    else hi = mid;
  }
  return -1;
}

/** The visualizable search algorithms, keyed by base name (#3220). */
export const SEARCH_PROGRAMS: Record<string, SearchProgram> = {
  "linear-search": { run: linearSearch, defaultInput: LINEAR_MOCK },
  "binary-search": { run: binarySearch, defaultInput: BINARY_MOCK },
};

/** Serialize a search input to the "your input" text form — the values, then the target after a `|`. */
export function searchToText(input: SearchInput): string {
  return `${input.values.join(", ")} | ${input.target}`;
}

/**
 * Parse the "your input" text into a {@link SearchInput} — the values (comma/whitespace separated, via
 * {@link parseSortInput}) then the target after a single `|`. Throws a helpful `Error` (shown under the
 * field) when the separator or the target is missing or non-numeric.
 */
export function parseSearchInput(text: string): SearchInput {
  const parts = text.split("|");
  if (parts.length !== 2) throw new Error("Put the target after a single '|', e.g. 1, 3, 5 | 3");
  const values = parseSortInput(parts[0]);
  const targetText = parts[1].trim();
  if (targetText.length === 0) throw new Error("Add the target after the '|', e.g. 1, 3, 5 | 3");
  const target = Number(targetText);
  if (!Number.isFinite(target)) throw new Error(`"${targetText}" is not a number`);
  return { values, target };
}

