// The Agents SCREEN is not here — it is the `securitypage` RECORD, mounted by `SecurityGraphHost`,
// which is what `lazyWorkspaces` resolves `SecurityWorkspace` to. Both shells already render the
// graph copy, so the duplicate that used to sit here was dead code: nothing imported it. What
// remains is the feature's public API — re-exports only, hence .ts rather than .tsx.

// Hash-based built-in seed refresh (#2483) — the pure decision spine that replaced the frozen
// seed-and-keep reconcile. The store wins ONLY for records the user actually edited; a pristine
// built-in copy tracks the packaged seed release-to-release (the react-ui kit is GENERATED from the
// app's own source, so every release drifts the seed).
//
// The mechanism: every packaged built-in carries a `seedHash` — a small content hash of its
// seed-relevant fields, stamped at seed-assembly time (`makeBuiltinKits`). A store copy whose
// current content still hashes to its recorded `seedHash` is UNMODIFIED (safe to refresh/delete);
// one that no longer does was edited by the user (kept, with an "updated upstream" notice when the
// seed moved too).
//
// Hash exclusions (the "volatile" set, `SEED_HASH_EXCLUDED`):
//   - `seedHash`  — the stamp itself can never feed its own hash.
//   - `builtin`   — provenance, not content (stamped on assembly AND carried by the bridge).
//   - `used`      — the runtime reuse counter; it drifts without a user edit.
//   - `rev` / `updatedAt` / `updatedBy` / `history` (#3606) — SERVER-MANAGED provenance the Rust stamp
//     boundary writes on every `bsc ui set` (a component write-through stamps them). `componentBridge`
//     projects them for the inspector's History tab, so they ride into the loaded record — but they are
//     NOT seed content, so hashing them would make a pristine SEEDED component (pushed → stamped → loaded
//     with a fresh `rev`) mis-hash as user-modified forever. Kits/themes never projected them, so this is
//     the component-seed case the empty `SEED_COMPONENTS` had never exercised.
// Everything else on the record IS seed content — a change to any other field is a user edit (store
// copy) or a new release (seed copy).
//
// THE ROUND-TRIP CONTRACT (#2514). A stamp is only meaningful if the record's seed-relevant content
// survives the push→store→load round-trip byte-for-byte: `bsc ui … set` persists the JSON verbatim
// (key order aside), `… list --full` returns it verbatim, and the bridge projections
// (componentBridge/themeBridge `loadX`) must carry every seed-relevant field WITHOUT normalizing it —
// an absent optional field must stay absent (never defaulted to `""`/`[]`), or the reloaded copy
// hashes differently from its stamp and the reconcile mis-judges a pristine record as user-modified
// forever. This invariant is EXECUTED, not assumed: `seedRoundTrip.test.ts` pushes every packaged
// seed record through the real bridge mapping over a faithful store emulation and asserts the
// reloaded content still hashes to its stamp.
//
// Defense in depth for a stamp that rots anyway (an older hasher, a byte-mangling round-trip in some
// past build): a mismatched `builtin` copy gets a second chance against the CURRENT seed — content
// identical to the seed ⇒ the stamp itself was wrong, re-judged pristine and re-stamped (see the
// verdict table on `reconcileSeed`). Silent keep-forever is impossible: every KEEP of a diverged
// copy surfaces a notice.
//
// Deliberately GENERIC over `{ id, name, builtin?, seedHash? }` (components AND kits today) so the
// same helper can be extracted for the other seed-and-keep stores (personas, orgs, blueprints) later
// — it has no component-specific knowledge beyond the volatile-field list above.

/** The minimum shape the reconcile needs; components, kits, and themes (#2488) all satisfy it. */
export interface SeedRecord {
  id: string;
  /** Display name for the notices — components/kits carry `name`; themes carry `label` instead. */
  name?: string;
  /** Theme display name (#2488) — the notices fall back name → label → id. */
  label?: string;
  /** A packaged built-in. Absent/false ⇒ user-authored (never touched by the reconcile). */
  builtin?: boolean;
  /** A SUPPRESSION tombstone (#3725) — `true` marks this id as a PERMANENTLY removed packaged builtin.
   *  The reconcile skips it (not a record to render) and its presence blocks the seed from re-adding it. */
  suppressed?: boolean;
  /** The content hash stamped when this copy was seeded (#2483). Absent ⇒ a legacy pre-#2483 copy. */
  seedHash?: string;
}

/** The display name a notice carries: `name` (components/kits) → `label` (themes) → the id. */
function displayName(rec: SeedRecord): string {
  return rec.name ?? rec.label ?? rec.id;
}

/** Fields excluded from the seed hash — see the module doc for why each. */
export const SEED_HASH_EXCLUDED = ["seedHash", "builtin", "used", "rev", "updatedAt", "updatedBy", "history"] as const;

/** Deterministic JSON: keys sorted recursively, `undefined` properties dropped (so an absent
 *  optional field and an explicitly-undefined one hash identically). */
export function stableStringify(v: unknown): string {
  if (v === null || typeof v !== "object") return JSON.stringify(v) ?? "null";
  if (Array.isArray(v)) return `[${v.map((x) => (x === undefined ? "null" : stableStringify(x))).join(",")}]`;
  const o = v as Record<string, unknown>;
  const keys = Object.keys(o).filter((k) => o[k] !== undefined).sort();
  return `{${keys.map((k) => `${JSON.stringify(k)}:${stableStringify(o[k])}`).join(",")}}`;
}

/** FNV-1a 32-bit over the text, as 8 hex digits. Not cryptographic — a drift detector, not a
 *  security boundary (the store is the user's own local files). */
export function fnv1a(text: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}

/** The seed hash of a record's CURRENT content (volatile fields excluded). */
export function seedHashOf(record: SeedRecord): string {
  const rest: Record<string, unknown> = { ...record };
  for (const k of SEED_HASH_EXCLUDED) delete rest[k];
  return fnv1a(stableStringify(rest));
}

/** Stamp a record with its own content hash — what `makeBuiltinKits` applies to every packaged
 *  built-in at seed-assembly time (the packaged JSON files do NOT bake the field in). */
export function stampSeedHash<T extends SeedRecord>(record: T): T {
  return { ...record, seedHash: seedHashOf(record) };
}

/** What a notice is about. */
export type SeedNoticeType = "component" | "kit" | "theme";

/** A reconcile outcome the user should see (the propagation-surface record, #2483). */
export interface SeedNotice {
  /** `updated-upstream`: the packaged built-in changed but the user's customized copy was kept.
   *  `orphaned`: the built-in left the seed but the user's customized copy was kept.
   *  `reset-to-seed`: a SEED-AUTHORITATIVE record (an import-based page spec, #3723) had a diverged
   *  store copy FORCED back to the packaged seed. The store never wins for these, so a divergence is a
   *  bug (a designer self-contained it for the preview sandbox), not a user edit — surfaced, not silent.
   *  `unstamped`: the store copy carries NO `builtin` flag but a packaged seed of that id EXISTS, so the
   *  reconcile treats it as user-authored and never refreshes it — while the app renders it (#4216). The
   *  record is left exactly as it is (changing 44 pages at once is not a reconcile's call); this makes
   *  the state visible so it can be judged per record. */
  kind: "updated-upstream" | "orphaned" | "reset-to-seed" | "unstamped" | "refreshed";
  type: SeedNoticeType;
  id: string;
  name: string;
}

/** The reconcile verdicts: the final collection + the write-through work to converge the store. */
export interface SeedReconcile<T extends SeedRecord> {
  /** The reconciled collection (loaded order, refreshed in place; missing seeds appended). */
  records: T[];
  /** Records to write through (`bsc ui set` / `kit set`): refreshed + newly-added built-ins. */
  pushes: T[];
  /** Ids to remove from the store (`bsc ui remove` / `kit remove`): deleted built-ins. */
  drops: string[];
  /** The "kept but diverged" outcomes to surface. */
  notices: SeedNotice[];
}

/**
 * Reconcile the store's loaded records with the packaged seed (#2483). Verdict table — for a loaded
 * record with `builtin: true` ("modified" = its content no longer hashes to its recorded `seedHash`;
 * a record with NO `seedHash` is a legacy pre-#2483 copy, grandfathered as UNMODIFIED — all three
 * real rot incidents were pristine copies, so this heals every existing install once):
 *
 * | in seed? | modified? | seed moved (`seed.seedHash !== record.seedHash`)? | verdict |
 * |---|---|---|---|
 * | yes | no  | yes (incl. legacy no-hash) | REFRESH — take the new seed copy, push it |
 * | yes | no  | no                         | keep the store copy (already current) |
 * | yes | yes | yes (incl. legacy… n/a)    | KEEP + `updated-upstream` notice |
 * | yes | yes | no                         | keep (customized, seed unchanged) |
 * | no  | no  |                            | DELETE (drop from store) |
 * | no  | yes |                            | KEEP + `orphaned` notice |
 *
 * Tolerant re-stamp (#2514): before the "modified" KEEP fires for an in-seed record, its content is
 * compared against the CURRENT seed copy's content hash. Identical content ⇒ only the recorded stamp
 * is wrong (an older hasher / a byte-mangling round-trip in a past build stamped it) — the record is
 * re-judged PRISTINE and refreshed to the seed copy (same content, corrected stamp), no notice. A
 * retired record with a wrong stamp has no seed copy to compare against, so it stays on the
 * conservative KEEP + `orphaned` branch — kept, but never silently (the notice is the surface).
 *
 * Non-builtin (user-authored) loaded records pass through untouched, always. Seed records the store
 * lacks are appended + pushed (the original seed-and-keep add).
 *
 * @param loaded the store's records (from the bridge).
 * @param seed   the packaged built-ins, seedHash-stamped (`makeBuiltinKits`).
 * @param type   what the records are (for the notices).
 * @param opts   `seedAuthoritative` (#3723) — records for which the SEED wins unconditionally (an
 *               import-based page spec): a diverged store copy is a bug, not a user edit, so it is
 *               FORCED back to the seed with a `reset-to-seed` notice instead of the customized-KEEP the
 *               verdict table above would apply. Records it doesn't match keep the normal verdicts.
 */
export function reconcileSeed<T extends SeedRecord>(
  loaded: T[],
  seed: T[],
  type: SeedNoticeType,
  opts?: { seedAuthoritative?: (rec: T) => boolean },
): SeedReconcile<T> {
  const seedById = new Map(seed.map((s) => [s.id, s]));
  const records: T[] = [];
  const pushes: T[] = [];
  const drops: string[] = [];
  const notices: SeedNotice[] = [];

  for (const rec of loaded) {
    // #3725: a SUPPRESSION tombstone — a marker that a packaged builtin of this id is permanently removed.
    // It is not a record to render (skip it from `records`), and its presence in `loaded` (hence `have`
    // below) makes the re-seed step SKIP that id, so the builtin never comes back. It stays in the store
    // (never dropped) so the block persists; `unsuppress` (remove it) lets the next hydrate re-seed.
    if (rec.suppressed) continue;
    if (!rec.builtin) {
      // #4216: an unstamped record with a packaged seed of the same id is NOT user-authored — it is a
      // built-in whose stamp was lost (a pre-#4197 partial `bsc ui set` dropped `builtin`/`seedHash`).
      // The reconcile has been skipping it ever since, so it never refreshes — while the app renders it,
      // because this branch pushes the store copy straight into `records`. Say so.
      //
      // Behaviour is deliberately UNCHANGED: the store copy still wins. Deciding which side is right is
      // a per-record judgement (the drift runs both ways — some store copies are far smaller than their
      // seed, some far larger), and a reconcile that silently replaced 44 pages would be the worse bug.
      if (seedById.has(rec.id)) {
        notices.push({ kind: "unstamped", type, id: rec.id, name: displayName(rec) });
      }
      records.push(rec); // user-authored (or unstamped) — never touched
      continue;
    }
    const seeded = seedById.get(rec.id);
    // Legacy pre-#2483 copies (no seedHash) are grandfathered as unmodified.
    const contentHash = rec.seedHash === undefined ? undefined : seedHashOf(rec);
    let modified = contentHash !== undefined && contentHash !== rec.seedHash;
    if (seeded) {
      const seedContentHash = seeded.seedHash ?? seedHashOf(seeded);
      // Seed-authoritative records (#3723): the store NEVER wins. A store copy whose CONTENT differs
      // from the seed is a divergence bug — e.g. a designer self-contained an import-based page spec so
      // it would render in the preview sandbox, which then silently shadowed the real page (#3658 →
      // #3723) — not a user edit. Force the seed copy back (push it), surfaced via a `reset-to-seed`
      // notice so the override is never silent. A copy already matching the seed is left untouched.
      if (opts?.seedAuthoritative?.(rec)) {
        if (seedHashOf(rec) !== seedContentHash) {
          records.push(seeded);
          pushes.push(seeded);
          notices.push({ kind: "reset-to-seed", type, id: rec.id, name: displayName(rec) });
        } else {
          records.push(rec); // already matches the seed
        }
        continue;
      }
      // Tolerant re-stamp (#2514): content identical to the CURRENT seed ⇒ the recorded stamp is the
      // broken part, not the content — re-judge pristine (the refresh below adopts the seed copy,
      // which is the same content with the corrected stamp).
      if (modified && contentHash === seedContentHash) modified = false;
      const seedMoved = seedContentHash !== rec.seedHash;
      if (!modified && seedMoved) {
        records.push(seeded); // pristine + stale → refresh to the new seed copy
        pushes.push(seeded);
        // SAY SO WHEN IT ACTUALLY REPLACED SOMETHING (#a-reseed-must-not-silently-overwrite-a-designer-edit).
        //
        // This branch was the one verdict that changed a record and reported nothing. A designer's only
        // signal was noticing their fix had stopped working — which is how request #63 was found, twice,
        // mid-task. The banner's own rule already covers this case: `reset-to-seed` is carried as
        // actionable because "it means a store copy was OVERWRITTEN, which is the most actionable verdict
        // there is". A content-replacing refresh is the same event.
        //
        // Only when the CONTENT differs. A refresh whose seed copy is byte-identical is a stamp
        // correction — the tolerant re-stamp path (#2514) routes through here — and reporting those would
        // bury the real ones, which is exactly why plain divergence is not surfaced either.
        if (seedHashOf(seeded) !== seedHashOf(rec)) {
          notices.push({ kind: "refreshed", type, id: rec.id, name: displayName(rec) });
        }
      } else {
        records.push(rec); // current, or customized (store wins)
        if (modified && seedMoved) notices.push({ kind: "updated-upstream", type, id: rec.id, name: displayName(rec) });
      }
    } else if (modified) {
      records.push(rec); // customized copy of a retired built-in — keep, but say so
      notices.push({ kind: "orphaned", type, id: rec.id, name: displayName(rec) });
    } else {
      drops.push(rec.id); // pristine copy of a retired built-in → delete
    }
  }

  // Built-ins the store lacks entirely (first run / newly packaged) — append + push.
  const have = new Set(loaded.map((r) => r.id));
  for (const s of seed) {
    if (have.has(s.id)) continue;
    records.push(s);
    pushes.push(s);
  }

  return { records, pushes, drops, notices };
}

/** One record the re-stamp declines to touch, and why (#4207). */
export interface RestampDeferral {
  id: string;
  name: string;
  /** `seed-authoritative`: stamping would let the seed OVERWRITE the store copy on the next hydrate
   *  (the `seedAuthoritative` branch of {@link reconcileSeed} fires before any content comparison), so
   *  the repair would silently change what the app renders. That is a per-record judgement, not a
   *  repair's call. */
  reason: "seed-authoritative";
}

/** What {@link planRestamp} would do (#4207). */
export interface RestampPlan<T extends SeedRecord> {
  /** Records to write through, each carrying `builtin: true` + the SEED's content hash. Content is
   *  otherwise untouched. */
  stamps: T[];
  /** Records left alone, with the reason. */
  deferred: RestampDeferral[];
}

/**
 * Plan the repair for the `unstamped` verdict (#4207): store records carrying NO `builtin` flag that a
 * packaged seed of the same id exists for. A pre-#4197 partial `bsc ui set` dropped the flag, and
 * `reconcileSeed` has treated them as user-authored ever since — so they never refresh, never surface a
 * drift notice, and never received the #4107 `group`→`folder` migration, while the app renders them.
 *
 * **The stamp carries the SEED's hash, not the record's own** — that choice is the whole design, because
 * it decides which side wins on the very next hydrate:
 *
 * - Stamped with its OWN content hash, the record reads as PRISTINE (`contentHash === seedHash`) and
 *   STALE (`seedContentHash !== seedHash`), which is the REFRESH verdict: the seed copy replaces the
 *   store copy. On this repo that would discard real content — the store's `automations-history` carries
 *   the post-rename `HistoryTab`, its seed still says `AutomationsHistory`.
 * - Stamped with the SEED's content hash, it reads as EDITED (content differs from the stamp) against an
 *   UNMOVED seed — the "customized, seed unchanged" verdict, which keeps the store copy. Then the moment
 *   the packaged seed genuinely moves, `updated-upstream` fires and the drift is visible from then on.
 *
 * So the repair is non-destructive by construction: it restores the record's MEMBERSHIP in the reconcile
 * without adjudicating its content. Which side is right stays a per-record question — this only makes it
 * a question the machinery can still ask.
 *
 * A record with no packaged seed is never stamped: that is the signature of a genuinely user-authored (or
 * harvested) record, and mislabelling one as a built-in would hand its content to a future seed.
 *
 * @param loaded the store's records (from the bridge).
 * @param seed   the packaged built-ins, seedHash-stamped.
 * @param opts   `seedAuthoritative` — the same predicate {@link reconcileSeed} takes. Matching records
 *               are DEFERRED rather than stamped; see {@link RestampDeferral}.
 */
/**
 * Apply a {@link planRestamp} result to the in-memory list — replace each stamped record by id.
 *
 * Exists so the repair can run BEFORE the reconcile in a single hydrate pass. The alternative, stamping
 * the store and re-reading, costs a second full-fidelity load and a second reconcile; worse, done from
 * inside `hydrateComponents` a re-hydrate would re-enter itself.
 *
 * Returns `loaded` unchanged (same reference) when there is nothing to stamp, so the common case adds no
 * allocation and a caller can cheaply tell whether anything happened.
 */
export function applyStamps<T extends SeedRecord>(loaded: T[], stamps: T[]): T[] {
  if (stamps.length === 0) return loaded;
  const byId = new Map(stamps.map((s) => [s.id, s]));
  return loaded.map((rec) => byId.get(rec.id) ?? rec);
}

export function planRestamp<T extends SeedRecord>(
  loaded: T[],
  seed: T[],
  opts?: { seedAuthoritative?: (rec: T) => boolean },
): RestampPlan<T> {
  const seedById = new Map(seed.map((s) => [s.id, s]));
  const stamps: T[] = [];
  const deferred: RestampDeferral[] = [];

  for (const rec of loaded) {
    // A tombstone, or a record the reconcile ALREADY handles correctly.
    //
    // The `builtin` half used to be unqualified, commented "already in the reconcile path"
    // (#a-builtin-that-lost-its-stamp-falls-between-both-guards). That is only true of a record whose
    // stamp is INTACT. A builtin that has lost its `seedHash` falls between the two guards: restamp
    // skipped it because `builtin` was set, and the reconcile refreshed it because `contentHash` is
    // undefined when `seedHash` is — so `modified` reads false, the seed has moved, and the packaged
    // copy is adopted. Each guard assumed the other covered the case.
    //
    // That cost 38 records on 2026-08-14 (designer request #63): a `--graph` LITE `--replace` push
    // strips the stamp (that projection carries no `seedHash`) and the next hydrate overwrote a
    // designer's fixes with the seed. Claiming it here restores the stamp with the SEED's hash, which
    // reads as edited-against-an-unmoved-seed — the verdict that KEEPS the store copy.
    if (rec.suppressed || (rec.builtin && rec.seedHash)) continue;
    const seeded = seedById.get(rec.id);
    if (!seeded) continue; // no packaged seed ⇒ genuinely user-authored — never claim it
    if (opts?.seedAuthoritative?.(rec)) {
      deferred.push({ id: rec.id, name: displayName(rec), reason: "seed-authoritative" });
      continue;
    }
    stamps.push({ ...rec, builtin: true, seedHash: seeded.seedHash ?? seedHashOf(seeded) });
  }

  return { stamps, deferred };
}

// Selection neighborhood (#2523, promoted to shared #2719) — a pure graph query used by every graph
// canvas that highlights a selection: given the edge set and a selected node id, return the edges
// incident to it and the nodes on the far end of those edges. React-free and layout-agnostic (it
// only needs `from`/`to`/`id` on each edge), so it lives alongside the other shared graph model
// helpers rather than in any one feature.
import type { GraphEdge } from "@/shared/lib/graph/types";

export interface SelectionNeighborhood {
  /** Edge ids incident to the selected node (`from === selId || to === selId`). */
  incidentEdges: Set<string>;
  /** Node ids directly connected to the selected node — the selection itself is never included. */
  relatedNodes: Set<string>;
}

/** The selection neighborhood of a node: the edges touching it and the nodes on the far end. A
 *  GraphView highlights the incident edges in accent and softly rings the related nodes. Empty when
 *  `selId` is falsy (nothing selected). A self-loop never marks the selection as its own relation. */
export function selectionNeighborhood(edges: readonly GraphEdge[], selId: string): SelectionNeighborhood {
  const incidentEdges = new Set<string>();
  const relatedNodes = new Set<string>();
  if (!selId) return { incidentEdges, relatedNodes };
  for (const e of edges) {
    if (e.from === selId) { incidentEdges.add(e.id); relatedNodes.add(e.to); }
    else if (e.to === selId) { incidentEdges.add(e.id); relatedNodes.add(e.from); }
  }
  relatedNodes.delete(selId); // a self-loop must not mark the selection as its own relation
  return { incidentEdges, relatedNodes };
}

// Assemble a session's backend config from its resolved MCP servers + hooks.
// The two feature models stay independent; they meet only here, where the lists are
// converted to the payload shapes `ensure_session_settings` writes into a session's
// `.mcp.json` (servers) and `.claude/settings.json` (hooks).

import { type McpServer, type McpServerPayload, toMcpPayload } from "@/features/mcp/lib/mcpServers";
import { type Hook, type HookPayload, toHookPayload } from "@/features/mcp/lib/hooks";

/** Resolved servers + hooks → the two backend payload lists, dropping incomplete entries. */
export function toSessionPayloads(
  mcpServers: McpServer[],
  hooks: Hook[],
): { mcp: McpServerPayload[]; hooks: HookPayload[] } {
  return {
    mcp: mcpServers.map(toMcpPayload).filter((p): p is McpServerPayload => p !== null),
    hooks: hooks.map(toHookPayload).filter((p): p is HookPayload => p !== null),
  };
}

/**
 * Auto-allow permission rules (`mcp__<server>`) for a set of resolved MCP payloads. Listing a
 * server in `enabledMcpjsonServers` only lets Claude Code LOAD it without the trust prompt — in the
 * default permission mode each tool CALL still prompts unless an allow rule covers it. `mcp__<name>`
 * with no `__tool` suffix is Claude Code's "all tools from this server" form, so a session that
 * trusts these servers also auto-approves their tool calls (e.g. the planner running the Research
 * MCP while authoring a skill). Pass the rules into `ensure_session_settings`' `allowToolRules`.
 */
export function mcpAllowRules(mcp: McpServerPayload[]): string[] {
  return mcp.map((m) => `mcp__${m.name}`);
}

// Session-launch composition for TerminalView (#1645). Pure, React-free builders that turn the
// current app-store snapshot into the exact payloads the PTY launch path feeds to the Tauri
// commands (`pty_create` env, `ensure_session_settings`, and the resolved init command). Extracted
// verbatim from TerminalView's mount effect so the renderer stays a lean terminal host while the
// provider/MCP/skills/permissions/init-cmd assembly lives here.
//
// BEHAVIOR CONTRACT: each builder reads the store via the snapshot it's handed and is called at the
// SAME point in the launch sequence as the inline code it replaced. Every read in the original blocks
// was synchronous (no `await` between them), so a single snapshot is identical to the original's
// repeated `useAppStore.getState()` calls. Do not change what is computed, only where it lives.

import { resolveLlmConfig, bscAgentEnv, aiderEnv } from "@/shared/lib/core/llmConfig";
import { resolveMcpServers, toBscAgentMcp, resolveHooks, toSessionPayloads } from "@/features/mcp";
import { effectiveSessionSkills, expandGroups, toSkillCfgs } from "@/features/skills";
import { resolveInitCmd } from "@/app/console/lib/resumeClaude";
import { isManualPaneId } from "@/app/console/lib/paneIdentity";
import { roleCapability, roleDeniedCommands, roleWriteRules, roleDeniedTools, bscAgentPerms, scopeWriteGlobs, sessionScopes, restrictedRoleCommands, isRestrictedRole, editPathRule, HARVEST_ROOT_APP_REPO, HARVEST_ROOT_PROJECTS, type SessionRole, type RoleCapability } from "@/shared/lib/session/sessionRoles";
import { isFullCapabilitySession, isStudioSessionPaneId } from "@/shared/lib/session/systemSessions";
import { TURN_ACCOUNTING_HOOKS } from "@/shared/lib/session/turnHooks";
import { studioRoleForPaneId } from "@/features/studio-sessions";
import { resolveProfileSettings } from "@/features/security";
import { flowPermissionRules, flowGrantedPushCommands } from "@/features/planner";
import type { ConsoleProvider, ProviderLaunchConfig } from "@/app/console/lib/providers";
import type { AppStore } from "@/store/types";

/**
 * Base session env for `pty_create`. Carries `GH_TOKEN` for gh/git-over-https; the write-scope globs
 * (`BSC_SCOPE_GLOBS`) for the `bsc-scope` PreToolUse hook on any gated pane; the role's per-store
 * access scopes (`BSC_SCOPES`, #2470) for the store CLIs' runtime write check; and, for a bsc-agent
 * session, the selected LLM provider/model/key, role-derived perms (`BSC_AGENT_PERMS`) and resolved
 * MCP servers (`BSC_AGENT_MCP`). Returns undefined when nothing needs to be injected.
 *
 * @param s        store snapshot taken at the launch point (after the claude-launch gate)
 * @param paneId   the pane being launched
 * @param providerId  the resolved provider id (default "claude")
 * @param ghToken  the repo-scoped or global GitHub token already resolved for this pane
 */
/** Sentinel `BSC_SCOPE_GLOBS` value meaning "deny ALL file writes" — set for a `code:none` role with
 *  no write globs so the `bsc-scope` PreToolUse hook hard-blocks every Edit/Write (a write-block that
 *  survives `bypassPermissions`, #1916 Step 3.5). MUST match the literal in `bsc-scope` (shell_rc.rs). */
export const SCOPE_DENY_ALL = "__bsc_deny_all__";

/**
 * The pane's role gate. Prefers the store, then DERIVES it from the pane id for an app-owned studio
 * session (#3423).
 *
 * The store entry is written by `seedStudioLaunchState`, which only runs when `StudioSessionMount`
 * renders — and that happens only for a studio in `wantedStudios`, a transient set (absent from
 * `partialize`) that is empty after every app restart. A studio opened in that window reached this
 * function with NO role, and a missing role means no role gate, no `restrictedAllow` and no denies: a
 * fully unconfined shell on the most restricted surface in the app. A studio's pane id is stable and
 * app-owned, so it is sufficient on its own — confinement now travels with the session's identity
 * rather than with setup order. Any other pane keeps the store as its only authority.
 */
function paneRole(s: AppStore, paneId: string): SessionRole | undefined {
  return s.paneRoles[paneId] ?? studioRoleForPaneId(paneId) ?? undefined;
}

/**
 * The pane's CAPABILITY — its persona's own floor when it has one, else its role's row.
 *
 * This is the point of `personas-are-the-launch-primitive`. `roleCapability(role)` answers "what may
 * this KIND of session do"; a persona may be narrower than its kind, and before this the narrowing was
 * discarded exactly here. A user persona derived from `worker` with a tighter floor was assigned to a
 * pane, `applyPersonaToPane` stored `persona.role`, and the launch read the full worker row — the one
 * moment the narrowing had to survive was the one place it did not.
 *
 * The role remains the FALLBACK, not a second source: a plain console, a fleet pane seeded before any
 * persona existed, and a studio whose id resolves through `studioRoleForPaneId` all still launch
 * exactly as they did. `role` is carried on the returned capability either way, because the launch
 * rules downstream branch on it (`hasScopedWriteCarveOut`, the director/planner file denies).
 */
function paneCapability(
  s: AppStore,
  paneId: string,
  override: Partial<RoleCapability> = {},
): RoleCapability | null {
  const persona = s.personas?.find((p) => p.id === s.panePersonas?.[paneId]);
  if (persona?.floor) {
    // A persona's floor is the whole capability; `role` comes along so downstream branching still
    // works, and the caller's override (a worker's owned globs) still wins, as it does for a role.
    // Converted FIELD BY FIELD, with no cast. `writeGlobs` is REQUIRED on RoleCapability and OPTIONAL
    // on a floor — the packaged floors omit it whenever it is empty, so `worker` genuinely has no such
    // key. The `as Omit<RoleCapability, "role">` this replaced ASSERTED the required shape without
    // supplying it, handing `roleWriteRules` / `hasScopedWriteCarveOut` / `scopeWriteGlobs` an
    // `undefined` the type says cannot occur — and silencing the one check that would have said so.
    // Spelling the conversion out makes a missing required field a compile error instead.
    const f = persona.floor;
    return {
      role: persona.role,
      github: f.github, git: f.git, code: f.code, net: f.net, ui: f.ui,
      writeGlobs: f.writeGlobs ?? [],
      harvestRoots: f.harvestRoots,
      allow: f.allow,
      ...override,
    };
  }
  const role = paneRole(s, paneId);
  return role ? roleCapability(role, override) : null;
}

export function buildAgentEnv(
  s: AppStore,
  paneId: string,
  providerId: string,
  ghToken: string,
): Record<string, string> | undefined {
  const e: Record<string, string> = {};
  // The pane's role capability, resolved up-front: it gates both the write-scope env below AND whether
  // this session is handed a GitHub credential at all.
  const scopeRole = paneRole(s, paneId);
  const roleGlobs = s.paneRoleGlobs[paneId] ?? [];
  const scopeCap = paneCapability(s, paneId, { writeGlobs: roleGlobs });
  // GH_TOKEN carries gh / git-over-https auth. A role denied BOTH axes has no use for it: the app-owned
  // studio sessions (designer/librarian/architect — `none` on every axis, #3357) cannot run git or gh at
  // all, so placing a GitHub credential in the environment of the app's MOST restricted sessions would
  // widen them for nothing. Before #3357 these launched via a bespoke hook that passed no token; keep it
  // that way now that they run through the generic path. An ungated pane (no role) is unaffected, as is
  // any role with real git/gh access (a triage pane is `git:none` but `github:write`, so it keeps it).
  const noGitOrGithub = !!scopeCap && scopeCap.git === "none" && scopeCap.github === "none";
  if (ghToken && !noGitOrGithub) e.GH_TOKEN = ghToken;
  // Role-declared READ-only harvest roots (#3509). The ROLE names intent (`app-repo`) because a role is
  // machine-independent; the launch resolves it to a real path. This widens only what `bsc ui harvest`
  // / `bsc graph harvest` may SCAN — it grants no write anywhere, which is the point: the designer is
  // `code: none` with `scratch/**` its only writable glob, yet must be able to mine the app's own UI
  // (#3451/#3471). A token that resolves to nothing contributes nothing, mirroring the CLI's rule that
  // an unresolvable allow-list entry is skipped rather than widening access.
  const harvestRoots = (scopeCap?.harvestRoots ?? [])
    .map((token) => {
      if (token === HARVEST_ROOT_APP_REPO) return s.appRepoRoot;
      // The whole downloaded-repos tree (#3664), resolved to `<base>/projects` — read-only, so the
      // designer can mine other repos' UI. An empty `bscBaseDir` (pre-hydration) contributes nothing.
      if (token === HARVEST_ROOT_PROJECTS) return s.bscBaseDir ? `${s.bscBaseDir}/projects` : null;
      return null;
    })
    .filter((p): p is string => !!p);
  // Newline-separated to match the CLI parser (a Windows path contains both `;` and a `:`).
  if (harvestRoots.length) e.BSC_HARVEST_ROOTS = harvestRoots.join("\n");
  // Write-scope gate (#1297): hand the session its allowed write globs so the `bsc-scope`
  // PreToolUse hook hard-blocks any write outside them — the hard deny the role gate's
  // allow-only rules lack. Applies to every gated pane.
  if (scopeRole && scopeCap) {
    const sg = scopeWriteGlobs(scopeRole, roleGlobs);
    if (sg.length > 0) {
      e.BSC_SCOPE_GLOBS = sg.join(" ");
    } else if (scopeCap.code === "none") {
      // code:none with no write globs ⇒ DENY ALL writes (#1916 Step 3.5). The sentinel makes bsc-scope
      // hard-block every Edit/Write — surviving bypassPermissions, where the role's permissions.deny
      // write rule is ignored. (A code:none role WITH globs — e.g. a director's commons — is scoped
      // above; an ungated pane has no scopeRole, so it stays allow-all.)
      e.BSC_SCOPE_GLOBS = SCOPE_DENY_ALL;
    }
    // Store scopes (#2470, defense-in-depth): the role's per-store access tiers (currently just `ui`)
    // for the store CLIs — `bsc ui` refuses its mutating verbs when scoped read-only. Guards accidents
    // + non-Claude runtimes; the launch-time deny rules (sessionDeniedCommands) are the boundary.
    e.BSC_SCOPES = JSON.stringify(sessionScopes(scopeCap));
  }
  // Deny-list (#1916): the session's role/user/profile deny patterns for the `bsc-deny` PreToolUse
  // hook (newline-separated; the dangerous floor itself is compiled into `bsc hook bash-deny`). This
  // carries the role/user denies through the bypassPermissions flip.
  const denies = sessionDeniedCommands(s, paneId);
  if (denies.length > 0) e.BSC_DENY_BASH = denies.join("\n");
  // Per-stream plan scoping (#3279): a WORKER pane owns exactly one fleet stream, so scope its
  // `bsc plan` to that stream — it reads + touches only its own issues (the plandb CLI enforces it).
  // `fleetPaneStreams[paneId]` is set only for worker panes at fleet launch; coordinating roles
  // (director/planner/triage/reviewer/…) get NO $BSC_STREAM and keep full cross-stream access, which
  // they need to integrate + judge. Gate on the worker role too, so a non-worker stream pane (a
  // reviewer/juror that judges another stream's landing) isn't accidentally boxed into its own.
  const streamId = s.fleetPaneStreams[paneId]?.id;
  if (streamId && paneRole(s, paneId) === "worker") e.BSC_STREAM = streamId;
  if (providerId === "bsc-agent") {
    Object.assign(e, bscAgentEnv(resolveLlmConfig(s)));
    // Gate the runtime by the pane's role (least-privilege parity with Claude); no role ⇒ permissive.
    const bscRole = paneRole(s, paneId);
    if (bscRole) {
      const cap = paneCapability(s, paneId, { writeGlobs: s.paneRoleGlobs[paneId] ?? [] })!;
      // Reconcile role ↔ flow (#304): the flow owns git push / gh pr create, so lift them from
      // the role denies when it permits pushing/PRing.
      const granted = flowGrantedPushCommands(s.paneFlows[paneId]);
      e.BSC_AGENT_PERMS = JSON.stringify(bscAgentPerms(cap, granted));
    }
    // MCP: pass the resolved stdio servers so bsc-agent's client connects them ($BSC_AGENT_MCP).
    const { mcp } = toSessionPayloads(s.paneMcpServers[paneId] ?? resolveMcpServers(s.mcpServers, ""), []);
    const bscMcp = toBscAgentMcp(mcp);
    if (bscMcp.length > 0) e.BSC_AGENT_MCP = JSON.stringify(bscMcp);
  }
  if (providerId === "aider") {
    // Aider (#1172): inject the provider's API key env (ANTHROPIC_/OPENAI_/GEMINI_API_KEY, or an
    // OPENAI_API_BASE for a local/ollama OpenAI-compatible endpoint) so the `--model` selected in
    // `buildAiderCommand` can actually reach the configured LLM. GH_TOKEN (added above) lets an Aider
    // worker push + open its PR, exactly like the other providers.
    Object.assign(e, aiderEnv(resolveLlmConfig(s)));
  }
  return Object.keys(e).length > 0 ? e : undefined;
}

/**
 * The per-provider launch config handed to a non-Claude provider's `buildLaunchCmd`. Only Aider
 * (#1172) needs one today: it maps the pane's resolved LLM config, its startup prompt, and a worker's
 * `CLAUDE.local.md` scope into `aider --model … --read … --message …`. Every other provider ignores
 * the config (returns undefined so they launch unchanged).
 */
export function providerLaunchConfig(
  s: AppStore,
  paneId: string,
  provider: ConsoleProvider,
  startupPrompt: string | undefined,
): ProviderLaunchConfig | undefined {
  if (provider.id !== "aider") return undefined;
  return {
    llm: resolveLlmConfig(s),
    startupPrompt: startupPrompt && startupPrompt.trim() ? startupPrompt : undefined,
    // A worker's plan scope (CLAUDE.local.md, copied into the worktree by ensure_worktree) — handed to
    // Aider read-only since it does no ancestor-CLAUDE.md walk. Only workers have one.
    readFiles: paneRole(s, paneId) === "worker" ? ["CLAUDE.local.md"] : undefined,
  };
}

/**
 * The session's denied Bash command patterns (#1916): the user's global denies + the role's denied
 * commands (minus the pushes the flow grants back) + the profile's denies. The SINGLE source for both
 * the `permissions.deny` rules (buildSessionSettings) and the `$BSC_DENY_BASH` env the `bsc-deny`
 * PreToolUse hook enforces — so role/user denies survive `bypassPermissions`, where `permissions.deny`
 * is ignored but the hook still fires + blocks.
 */
export function sessionDeniedCommands(s: AppStore, paneId: string): string[] {
  const cap = paneCapability(s, paneId, { writeGlobs: s.paneRoleGlobs[paneId] ?? [] });
  const profileId = s.paneProfiles[paneId];
  const profile = profileId ? s.agentProfiles.find((p) => p.id === profileId) : undefined;
  const prof = profile ? resolveProfileSettings(profile) : null;
  const granted = flowGrantedPushCommands(s.paneFlows[paneId]);
  const roleDenies = (cap ? roleDeniedCommands(cap) : []).filter((d) => !granted.includes(d));
  return [...s.deniedCommands, ...roleDenies, ...(prof?.deniedCommands ?? [])];
}

/**
 * The permission + extension payload for `ensure_session_settings` (everything except `cwd` and
 * `replacePermissions`, which the caller adds). Composes the role gate (#219), the per-agent profile
 * (#255), the per-agent flow (#297/#304), resolved MCP servers + hooks, skills (#636), and the audit
 * /confine/scope/taint/defer/skill/activity hooks. Spread the result straight into the invoke args.
 *
 * @param s       store snapshot taken at the settings-composition point
 * @param paneId  the pane being launched
 */
export function buildSessionSettings(s: AppStore, paneId: string) {
  // Role gate (#219): a planner/worker/triage session has its mutating git/gh commands denied at
  // launch (deny > the broad gh/git allow), plus a write-tool guard (#238). Absent role ⇒ unrestricted.
  const role = paneRole(s, paneId);
  // The worker's write boundary (its owned globs) makes roleWriteRules auto-approve Edit/Write within
  // its lane; without it a worker (code:write, empty writeGlobs) prompts on every edit.
  //
  // The empty case must FLOOR to the role table rather than override it (#3428) — `roleCapability` is a
  // plain spread, so passing `{ writeGlobs: [] }` REPLACES the role's own default boundary. `paneRoleGlobs`
  // is a fleet concept (only `fleetStartProject` writes it), so every non-fleet pane arrives here empty:
  // that erased the restricted studios' `scratch/**` carve-out (#3373), collapsing `hasScopedWriteCarveOut`
  // to false and denying the bare write tools — leaving a designer unable to stage the payload file that
  // `bsc ui set --file` exists to read. Mirrors `scopeWriteGlobs` (writeScope.ts), which floors it the same
  // way so the launch settings and the bsc-scope hook agree on one boundary.
  const roleGlobs = s.paneRoleGlobs[paneId] ?? [];
  const cap = paneCapability(s, paneId, roleGlobs.length ? { writeGlobs: roleGlobs } : {});
  const write = cap ? roleWriteRules(cap) : { allow: [], deny: [] };
  // Agents gate (#255): the profile assigned to this pane is the SOLE source of auto-approved
  // commands (#1457), plus its per-tool/path rules, on top of the role gate (deny wins for both).
  const profileId = s.paneProfiles[paneId];
  const profile = profileId
    ? s.agentProfiles.find((p) => p.id === profileId)
    : undefined;
  const prof = profile ? resolveProfileSettings(profile) : null;
  // Per-agent flow (#297): narrow the GitHub-propagation writes per the stream's push policy + gate.
  const paneFlow = s.paneFlows[paneId];
  const flowRules = flowPermissionRules(paneFlow);
  // The role's fixed store-CLI surface (#3095): a curator pane always auto-runs `bsc ui`/`bsc graph`
  // (its harvest + graph-optimize channels) whether or not a profile assigned them. Empty for every
  // other role, so this is a no-op elsewhere.
  const restrictedCommands = restrictedRoleCommands(role);
  const allowedCommands = [...(prof?.allowedCommands ?? []), ...restrictedCommands];
  // Tighten a role with a fixed store surface to `restrictedAllow` (#3098): suppress the Bash baseline
  // tiers entirely (git/build/read-only), so the curator's WHOLE auto-run command surface is exactly
  // the two store CLIs above — mirroring the standing-tab designer/librarian/architect. Bash-only:
  // the verbatim tool rules (Read/Edit/…) still apply, so `Read` (added below) keeps the curator able
  // to read generated source to `bsc ui set` it.
  const restrictedAllow = restrictedCommands.length > 0;
  // Shell posture (#1572): the profile's bash tier scales the backend's auto-approve baseline.
  // No profile ⇒ the broad default ("allow").
  const bashPosture = prof?.bashPosture ?? "allow";
  // Denied commands (#304/#1916): user + role (minus the flow-granted pushes) + profile denies — the
  // SAME set wired into `$BSC_DENY_BASH` for the bsc-deny hook (see sessionDeniedCommands).
  const denied = sessionDeniedCommands(s, paneId);
  // A restricted role (#3098) suppresses the Bash baselines, so grant the `Read` tool explicitly —
  // the curator reads generated component source before harvesting it via `bsc ui set`. Mirrors the
  // designer hook's `[...write.allow, "Read"]`. The backend dedupes, so a redundant Read is harmless.
  const allowToolRules = [...write.allow, ...(prof?.allowToolRules ?? []), ...(restrictedAllow ? ["Read"] : [])];
  // Confinement self-protection (#1916): the agent must not disable the FS-confinement hook or its own
  // permission set by editing them. Deny file writes on `.claude/**` — the in-repo config the
  // bsc-confine hook itself can't catch (it only blocks paths OUTSIDE the repo root). The app stays
  // authoritative regardless (it re-writes `.claude/settings.json` at every launch). On EVERY pane.
  // ONE `Edit(.claude/**)` rule (#3534): Claude Code matches file-permission rules on the Edit tool
  // alone and it covers every file-editing tool — the former `Write/MultiEdit/NotebookEdit(.claude/**)`
  // rules were NEVER enforced (MultiEdit is not even a tool), so this deny was silently a no-op.
  const confinementConfigDeny = [editPathRule(".claude/**")];
  // Worker sub-agent block (#1036): deny the Task tool for workers. Deny wins over any profile allow.
  const denyToolRules = [...confinementConfigDeny, ...write.deny, ...(cap ? roleDeniedTools(cap) : []), ...(prof?.denyToolRules ?? []), ...flowRules.denyToolRules];
  const askToolRules = flowRules.askToolRules;
  // MCP servers + hooks resolved for this session — pre-resolved per pane at tab creation; fall back
  // to globals for ad-hoc consoles.
  const mcpServers = s.paneMcpServers[paneId]
    ?? resolveMcpServers(s.mcpServers, "");
  const hookDefs = s.paneHooks[paneId]
    ?? resolveHooks(s.hooks, "");
  const { mcp, hooks } = toSessionPayloads(mcpServers, hookDefs);
  // Skills resolved for this session — pre-resolved per pane at tab creation (fleet/triage snapshot).
  // Fall back to the global set for an ad-hoc console, still honoring this pane's override (#1056).
  const skillDefs = s.paneSkills[paneId]
    ?? effectiveSessionSkills(
         s.skills, "", s.sessionSkillOverrides[paneId],
         new Set(expandGroups(s.sessionSkillGroups[paneId] ?? [], s.skillGroups)),
       );
  const skills = toSkillCfgs(skillDefs);
  // Agents audit (#257): on a gated pane (role or profile assigned), install PreToolUse hooks: log
  // each tool attempt (bsc-audit), time MCP calls (bsc-mcp), enforce the write-scope gate (bsc-scope,
  // #1297) and the tainted-turn gate (bsc-taint, #1167). FS confinement (bsc-confine, #158) is NOT
  // gated — it's defaulted onto every pane below (#1916).
  //
  // NO SESSION GETS A STOP BOUNCE ANY MORE (#session-stop-is-honoured). A worker used to carry
  // `bsc-defer` (#369) here — a Stop hook that REFUSED the stop and sent it back to work. #4021 widened
  // it from bouncing once to bouncing while any work remained, and the measured result was a session
  // that could not end: one worker emitted `maintain` 66 times on a ~90s cadence, trying to stop and
  // being pushed back each time. `maintain` became the most common event in the whole coordination log.
  //
  // Nothing was polling to wake those sessions; they were PREVENTED FROM STOPPING, which looks identical
  // from outside — which is why two separate sweeps of the app's injection sites missed it. Resuming a
  // finished session is the user's click now, so the hook has no successor: the comment above used to
  // say "it bounces ONCE per stop, so a finished worker is never trapped", and that stopped being true
  // in #4021 without the comment changing, which is most of why it survived review.
  //
  // The restricted STUDIO sessions never had one (#3580) — their keep-going is the LOOP pump
  // (useDesignerLoopPump, #3292), which drives a session turn-by-turn ONLY while an open loop exists.
  // That remains the one sanctioned way a session is kept going, and it is bounded by an explicit loop.
  // A fleet WORKER also gets the superseded gate (bsc-superseded, #4240): two actors can land the same
  // issue — a director closes one directly, two streams overlap — and today the second worker finds out
  // at MERGE time, after writing code and opening a conflicting PR. The completion is already ON the
  // coordination wire (`bsc-landed`/`merged`/`closed`, each pane-tagged); it was just never delivered
  // back INTO a session. This reads it before an edit and blocks ONCE per issue, then latches — so the
  // worker is informed and moves on. Worker-only: a director coordinating is not doing the work.
  const workerGates = role === "worker"
    ? [{ event: "PreToolUse", matcher: "Edit|Write|MultiEdit|NotebookEdit", command: "bsc-superseded" }]
    : [];
  const gatedHooks = (cap || prof)
    ? [...hooks,
       { event: "PreToolUse", matcher: "", command: "bsc-audit" },
       { event: "PreToolUse", matcher: "mcp__.*", command: "bsc-mcp" },
       { event: "PostToolUse", matcher: "mcp__.*", command: "bsc-mcp" },
       { event: "PreToolUse", matcher: "Edit|Write|MultiEdit|NotebookEdit", command: "bsc-scope" },
       { event: "PreToolUse", matcher: "", command: "bsc-taint" },
       // Supply-chain add gate (bsc-supply, #3799): block an install that ADDS a malicious/known-vulnerable
       // dependency (OSV via `bsc cve`). GATED (agent panes only) — the threat is compromised agents, not
       // the maintainer's manual console — and FAIL-OPEN, so an OSV outage never blocks the fleet.
       { event: "PreToolUse", matcher: "Bash", command: "bsc-supply" },
       // Fork visibility (bsc-fork, #4106): a subagent is the ONE actor in this system with no pane,
       // no roster row, no worktree and no branch — so a director that forks to do a worker's job does
       // it entirely off the coordination channel. `audit.log` already records the call, but nothing
       // reads that channel; this puts the fork where the inbox and Glance are looking. OBSERVE ONLY —
       // it always exits 0. The boundary on what a fork may do is the role gate (a director is
       // `code: none`), not this hook; making forks legible is a separate job from restricting them.
       { event: "PreToolUse", matcher: "Agent|Task", command: "bsc-fork" },
       ...workerGates]
    : hooks;
  // Skill telemetry (#406) follows the SKILLS, not the role gate: install the bsc-skill Pre/Post hooks
  // whenever skills are present (incl. an ungated console with a per-session skill, #1056).
  const skillHooks = skills.length > 0
    ? [...gatedHooks,
       { event: "PreToolUse", matcher: "Skill", command: "bsc-skill" },
       { event: "PostToolUse", matcher: "Skill", command: "bsc-skill" }]
    : gatedHooks;
  // Turn-activity hooks (#1184): authoritative turn boundaries for the status dot, on EVERY
  // claude-launching pane. Ordering no longer matters here — the Stop bounce that used to precede
  // these is gone, so nothing can block the stop before the accounting hooks record it.
  const sessionHooks = [
    ...skillHooks,
    // FS confinement (#158/#1916): the DEFAULT, un-gated deny — confine the AI's file tools to this
    // session's repo root ($BSC_REPO_ROOT, set per-pane in pty_create) on EVERY claude-launching pane,
    // role/profile or not. The deny every session starts with; the OS sandbox (WSL2/Seatbelt) extends
    // the same boundary to Bash (the one tool a PreToolUse hook can't fully confine).
    { event: "PreToolUse", matcher: "Edit|Write|MultiEdit|NotebookEdit|Read", command: "bsc-confine" },
    // Dangerous-command floor (#1916): the DEFAULT deny — `bsc-deny` hard-blocks (exit 2) any Bash
    // command hitting the shared dangerous floor (`bsc_util::dangerous`), enforced via the `bsc`
    // binary so it survives `bypassPermissions` (where `permissions.deny` is ignored but PreToolUse
    // hooks still fire+block). The foundation the deny-list switch builds on; reads `$BSC_DENY_BASH`
    // for the per-session role/user denies wired in at the bypass flip.
    { event: "PreToolUse", matcher: "Bash", command: "bsc-deny" },
    // Turn accounting (bsc-activity + bsc-tokens, #1184/#416) — the un-gated observability floor, from
    // the ONE shared constant every launch path spreads (#3452 fleet / #3455 planner both silently lost
    // this set when it was inlined per-path). bsc-tokens is the ONLY per-session token source, so it
    // must fire on Stop, and now nothing can refuse that Stop — these are the only Stop hooks left.
    ...TURN_ACCOUNTING_HOOKS,
  ];
  return {
    allowedCommands,
    deniedCommands: denied,
    mcpServers: mcp,
    hooks: sessionHooks,
    allowToolRules,
    denyToolRules,
    askToolRules,
    skills,
    bashPosture,
    // Restricted allow-list (#3098): when set, `build_allow_rules` emits ONLY the wrapped
    // allowedCommands — no Bash baselines/mandatory tier. True only for a role with a fixed store
    // surface (curator today); false-y leaves the normal posture-scaled baselines intact.
    restrictedAllow,
    // Permission posture (#1916): bypass=true ⇒ deny-list (auto-run; the PreToolUse hooks gate); false ⇒
    // allow-list (Claude's `default` mode — require approval). User-toggled in Settings; default true.
    // Two role/session-derived carve-outs override the global toggle in OPPOSITE directions:
    //   • A full-capability app-owned session (the DEBUG session, #3326) is ALWAYS bypass — it's the
    //     unrestricted maintenance session by definition (preserves its old bespoke posture).
    //   • A RESTRICTED role (designer/librarian/architect/curator) is NEVER bypass: bypass auto-runs
    //     everything and ignores `permissions.deny`, which would hand a session deliberately confined to
    //     its store CLI (the designer is `bsc ui`-only) a general shell. The confinement travels with the
    //     role, so it holds on every launch path.
    bypass: isFullCapabilitySession(paneId) ? true : isRestrictedRole(role) ? false : s.bypassPermissions,
  };
}

/**
 * Resolve the effective `init_cmd` for `pty_create`.
 * - Claude panes: explicit initCmd wins, then the startup-prompt baking path (pty_create handles it —
 *   don't also inject an init_cmd), then ad-hoc auto-resume (`claude --continue`). Manual consoles are
 *   never auto-recovered (#1176) — their crash-resume signals are suppressed.
 * - Non-Claude providers: explicit initCmd wins; otherwise the provider's own launch command.
 *
 * @param s        store snapshot taken at the init-cmd resolution point
 * @param paneId   the pane being launched
 * @param isClaudeProvider  whether the resolved provider is Claude
 * @param initCmd  the pane's explicit init command, if any
 * @param startupPrompt  the composed startup prompt, if any (drives the baking path)
 * @param provider the resolved provider (for its `buildLaunchCmd`)
 */
export function resolveEffectiveInitCmd(
  s: AppStore,
  paneId: string,
  isClaudeProvider: boolean,
  initCmd: string | undefined,
  startupPrompt: string | undefined,
  provider: ConsoleProvider,
): string {
  const manual = isManualPaneId(paneId);
  if (isClaudeProvider) {
    return resolveInitCmd({
      explicit: initCmd,
      startupPrompt,
      // #3928: the fleet/triage resume flag — a manual console never sets it, so #1041's
      // "a clean quit does NOT auto-resume" stays intact for those.
      // #3934: optional-chained — this sits directly on the pane-launch path, where a missing map
      // does not degrade the launch, it ABORTS it. The real store always populates both; a caller
      // holding a partial slice used to throw here before the launch command was ever resolved.
      continueSession: manual ? false : !!s.paneContinue?.[paneId],
      paneWasClaude: !!s.paneWasClaude?.[paneId],
      autoResumeClaude: manual ? false : s.autoResumeClaude,
      // Crash recovery (#1041): resume only after an unclean shutdown (silent, if opted in) or a
      // banner "restore" click — never on a clean restart, and never for a manual console.
      wasUncleanShutdown: s.uncleanShutdown,
      restoreRequested: manual ? false : !!s.restoreRequested[paneId],
    });
  }
  // Non-Claude: an explicit initCmd wins; otherwise the provider builds its own launch command from
  // the per-provider config (Aider maps LLM/model/prompt/worker-scope → flags, #1172; others ignore it).
  if (initCmd && initCmd.length > 0) return initCmd;
  return provider.buildLaunchCmd(providerLaunchConfig(s, paneId, provider, startupPrompt));
}

/**
 * Whether a Claude pane's baked startup prompt must be SUPPRESSED when it resumes a prior
 * conversation on a crash-restore remount (#2052). Keyed off the transient per-pane
 * `restoreRequested` flag set by `restoreSessionsFromCrash` — so it is true ONLY on the
 * crash-recovery relaunch, never on an intentional launch (a fresh triage/fleet kickoff, a
 * manual console, or a tab-switch reconnect all leave it false, so their prompts deliver as
 * usual). The backend's `fresh_only` only bites when the resumed session actually has history
 * (`fresh_only && has_history`), so a prompt still fires on a genuinely fresh launch.
 *
 * Without this, the crash-restore remount re-bakes the pane's persisted startup prompt /
 * checkpoint note as `claude --continue`'s initial message, which Claude then SUBMITS into the
 * already-resumed conversation — re-running (or, if that persisted text was a slash command like
 * `/clear`, WIPING) the restored history. Mirrors the planner's `startupPromptFreshOnly`
 * (`plannerLaunch`).
 */
export function resolveStartupPromptFreshOnly(s: AppStore, paneId: string, isClaudeProvider: boolean): boolean {
  if (!isClaudeProvider || isManualPaneId(paneId)) return false;
  // EVERY app-owned studio session (the DEBUG session #3326, and the designer/librarian/architect since
  // #3357) resumes with `claude --continue` across app restarts, so its baked charter/persona kickoff must
  // be fresh-only — delivered on the first launch (no history) but suppressed when it resumes an existing
  // conversation, so returning isn't re-greeted (or, worse, re-instructed). The backend's
  // `fresh_only && has_history` guard makes this exact: a genuinely fresh launch still fires. Reproduces
  // the old `useScreenSession` launches' hardcoded `startupPromptFreshOnly: true`.
  return !!s.restoreRequested[paneId] || isFullCapabilitySession(paneId) || isStudioSessionPaneId(paneId);
}

// Per-session log drill-down — pure shaping for the `bsc logs` reads (#1607 slice 3).
//
// The unified log engine lives in `crates/logs` and is reached the SAME way every other frontend log
// surface reaches it: `bsc logs …` over the `bsc` bridge (#2144), never a per-verb Tauri command. This
// module owns only the pure (React-free, unit-testable) shaping of two of those reads —
// `bsc logs sessions --json` (the session picker) and `bsc logs session <id> --json` (one session's
// full, time-merged story across tools/skills/mcp/hooks/perm/coord/activity/done + its cost rollup) —
// so the drill-down card stays a thin renderer. The JSON shapes mirror the crate's serde structs
// (snake_case field names, no `rename_all`): `SessionRow`, `LogEvent`, `Cost`, and the `session`
// command's `{ session, role, events, cost }` envelope.

/** One row of `bsc logs sessions --json` — the crate's `SessionRow` (snake_case). */
export interface LogSessionRow {
  session: string;
  role: string;
  tools: number;
  skills: number;
  mcp: number;
  coord: number;
  cost_usd: number;
  activity: string;
}

/** One normalized event — the crate's `LogEvent`. `stream` is the canonical category key. */
export interface SessionLogEvent {
  ts_ms: number;
  session: string;
  stream: string;
  summary: string;
  fields: string[];
}

/** The token/cost rollup — the crate's `Cost` (snake_case). */
export interface SessionCost {
  session: string;
  model: string;
  input: number;
  output: number;
  cache_creation: number;
  cache_read: number;
  cost_usd: number;
}

/** `bsc logs session <id> --json` — the merged story envelope. `cost` is null when untracked. */
export interface SessionStory {
  session: string;
  role: string;
  events: SessionLogEvent[];
  cost: SessionCost | null;
}

/** The event-category streams a session drill-down surfaces, in display order. Mirrors the crate's
 *  `canonical_stream` targets (minus the writer-only `tokens`, surfaced as the cost rollup instead). */
export const SESSION_STREAMS = [
  "tool",
  "skill",
  "mcp",
  "hook",
  "perm",
  "coord",
  "activity",
  "done",
] as const;
export type SessionStreamKey = (typeof SESSION_STREAMS)[number];

/** Short display label per stream key (the drill-down filter chips + timeline tag). */
export const STREAM_LABEL: Record<string, string> = {
  tool: "Tools",
  skill: "Skills",
  mcp: "MCP",
  hook: "Hooks",
  perm: "Denials",
  coord: "Coord",
  activity: "Activity",
  done: "Done",
};

/** A token per stream key so the timeline + chips read as one system. `perm` (a denial) reads as a
 *  warning; the rest map onto the shared semantic tokens. Unknown keys fall back to the muted tone. */
export const STREAM_TONE: Record<string, string> = {
  tool: "var(--accent)",
  skill: "var(--info)",
  mcp: "var(--success)",
  hook: "var(--fg-muted)",
  perm: "var(--danger)",
  coord: "var(--warning)",
  activity: "var(--fg-dim)",
  done: "var(--success)",
};

export function streamLabel(key: string): string {
  return STREAM_LABEL[key] ?? key;
}

export function streamTone(key: string): string {
  return STREAM_TONE[key] ?? "var(--fg-muted)";
}

/** `ts_ms` → `HH:MM:SS` (UTC), matching the crate CLI's lean-TSV `hms`. A negative/NaN ts clamps to
 *  `00:00:00` rather than throwing, so a malformed row still renders. */
export function eventTime(tsMs: number): string {
  // `trunc` (toward zero), not `floor`, so a small negative ts matches the crate CLI's Rust integer
  // division (`ms/1000`) exactly rather than wrapping to 23:59:59.
  const total = Math.trunc((Number.isFinite(tsMs) ? tsMs : 0) / 1000);
  const s = ((total % 86400) + 86400) % 86400;
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${pad(Math.floor(s / 3600))}:${pad(Math.floor((s % 3600) / 60))}:${pad(s % 60)}`;
}

/** Count events per stream key (every `SESSION_STREAMS` key present, zero-filled). Drives the filter
 *  chip badges + the header summary. */
export function streamCounts(events: SessionLogEvent[]): Record<string, number> {
  const out: Record<string, number> = {};
  for (const k of SESSION_STREAMS) out[k] = 0;
  for (const e of events) out[e.stream] = (out[e.stream] ?? 0) + 1;
  return out;
}

/** Events for the selected stream, newest first (a drill-down reads top-down); `null` ⇒ all streams.
 *  The crate emits ascending-by-time, so we reverse a shallow copy without mutating the input. */
export function filterEvents(events: SessionLogEvent[], stream: string | null): SessionLogEvent[] {
  const kept = stream ? events.filter((e) => e.stream === stream) : events.slice();
  return kept.reverse();
}

/** Total tokens (in + out + both cache buckets) for the cost rollup, or 0 when untracked. */
export function totalTokens(cost: SessionCost | null): number {
  if (!cost) return 0;
  return cost.input + cost.output + cost.cache_creation + cost.cache_read;
}

/** A one-glance rollup of a story: role, total event count, per-stream counts, and USD cost. */
export function summarizeStory(story: SessionStory | null): {
  role: string;
  total: number;
  byStream: Record<string, number>;
  costUsd: number;
  tokens: number;
} {
  const events = story?.events ?? [];
  return {
    role: story?.role ?? "session",
    total: events.length,
    byStream: streamCounts(events),
    costUsd: story?.cost?.cost_usd ?? 0,
    tokens: totalTokens(story?.cost ?? null),
  };
}

// Session recovery (#1266). The backend scans durable, store-independent sources and returns the
// sessions it found (S2, `discover_sessions`); this module reconciles that list against the OPEN
// tabs so only the *unrepresented* sessions — the ones the store has lost or never had — are
// surfaced for the user to act on (S3). Manual scratch shells are flagged reap-only (never
// restored, per #1176).
import { invoke } from "@tauri-apps/api/core";
import { paneIdFor, parsePaneIdentity, isPlanningPaneId, type PaneIdentityKind } from "@/app/console/lib/paneIdentity";
import { isStudioSessionPaneId } from "@/shared/lib/session/systemSessions";

/** A session reconstructed by the backend from durable sources (#1266 S2 `discover_sessions`). */
export interface DiscoveredSession {
  paneId: string;
  /** Where it was found: any of "ledger", "fleet", "worktree". */
  sources: string[];
  /** The live shell pid, when a running process currently owns this pane. */
  livePid?: number | null;
  /**
   * "running" (a live pid) · "dormant" (on disk, not running) · "planned" (in the plan.db fleet,
   * never launched) · "orphaned" (a live pid whose project was deleted — unrestorable; recovery
   * reaps it, #1279).
   */
  status: "running" | "dormant" | "planned" | "orphaned" | string;
  projectKey?: string | null;
  repo?: string | null;
  /** A cwd to reopen the session at — worktree for a worker, hub for the director. */
  cwd?: string | null;
}

/** A discovered session that is NOT currently open, enriched for the recovery UI (#1266 S3). */
export interface RecoverableSession extends DiscoveredSession {
  /** Parsed from the id grammar (`director` / `worker` / `triage` / `manual` / `positional`). */
  kind: PaneIdentityKind | "unknown";
  /**
   * The session is reap-only — killed, never restored. True for manual scratch shells (#1176) and
   * for `orphaned` shells of a deleted project (no plan to rehydrate, no project to attribute, #1279).
   */
  reapOnly: boolean;
}

/** The minimal tab shape needed to compute open pane ids (a structural subset of the store `Tab`). */
export interface ReconcileTab {
  id?: string;
  kind?: "build" | "triage";
  paneIds?: string[];
  layout?: string;
}

/** Call the backend scan (#1266 S2). Read-only — never mutates anything on disk. */
export async function discoverSessions(): Promise<DiscoveredSession[]> {
  return invoke<DiscoveredSession[]>("discover_sessions");
}

/** Number of grid cells a tab renders — from its minted `paneIds`, else its `cols×rows` layout. */
function cellCount(tab: ReconcileTab): number {
  if (tab.paneIds && tab.paneIds.length > 0) return tab.paneIds.length;
  const m = /^(\d+)\s*[×x]\s*(\d+)$/.exec(tab.layout ?? "");
  return m ? Number(m[1]) * Number(m[2]) : 1;
}

/** Every pane id currently open across all tabs — each cell's resolved identity id. */
export function openPaneIds(tabs: ReconcileTab[]): Set<string> {
  const ids = new Set<string>();
  tabs.forEach((tab, tabIdx) => {
    const cells = cellCount(tab);
    for (let p = 0; p < cells; p++) ids.add(paneIdFor(tab, tabIdx, p));
  });
  return ids;
}

/**
 * Reconcile the backend's discovered sessions against the open tabs (#1266 S3): keep only the
 * sessions NOT currently represented by an open pane, each enriched with its parsed `kind` and a
 * `reapOnly` flag. Reap-only sessions are killed, never restored: manual scratch shells (#1176)
 * and `orphaned` shells of a deleted project (unrestorable — no plan, no project, #1279). The
 * dedicated PLANNER pane (`planning_<key>`) is dropped entirely — a planning session is re-entered
 * from the Projects page, not the recovery banner (#1579). The app-owned STUDIO sessions (designer /
 * librarian / architect, `isStudioSessionPaneId`, #3137) are dropped for the same reason: their ids share
 * the `<key>:<tail>` worker grammar, so without this they'd be surfaced as restorable workers, but they're
 * app-owned singletons re-created when their workspace opens. This is the gap the recovery UI presents
 * for the user to decide on.
 */
export function reconcileSessions(discovered: DiscoveredSession[], tabs: ReconcileTab[]): RecoverableSession[] {
  const open = openPaneIds(tabs);
  return discovered
    .filter((d) => !open.has(d.paneId) && !isPlanningPaneId(d.paneId) && !isStudioSessionPaneId(d.paneId))
    .map((d) => {
      const kind = parsePaneIdentity(d.paneId)?.kind ?? "unknown";
      return { ...d, kind, reapOnly: kind === "manual" || d.status === "orphaned" };
    });
}

// Role-scoped session capabilities (#219) — least-privilege per session type. A
// session's abilities are bounded by its ROLE, so the planner can shape the plan but
// can't mutate the repo or GitHub, and any out-of-scope action is blocked (or
// escalated to an explicit user confirmation) rather than run freely.
//
// This is the pure enforcement core (command classification + path scoping); the
// gate that USES it is the role's denied-command set plus a write-path guard on the
// write tool, applied alongside the per-agent profile (#1457). Free of React / xterm /
// Tauri imports so it's unit-testable in isolation.
//
// This file is the PUBLIC BARREL (#2151): the enforcement core was decomposed into colocated,
// concern-scoped modules, layered types/data ← rules ← derivations to avoid cycles —
//   - `roleModel.ts`   — types (SessionRole/AccessTier/RoleCapability) + the externalized
//                        role→capability data (ROLE_DEFAULTS + the write-glob / db-owned /
//                        dep-manifest lists) + core accessors (roleCapability, hasScopedWriteCarveOut).
//   - `commandGate.ts` — command classification (classifyCommand) + the role command check (checkCommand).
//   - `writeScope.ts`  — glob matching (matchGlob) + write-path/boundary scoping (canWritePath, scopeWriteGlobs).
//   - `launchRules.ts` — launch wiring: write-tool rules (roleWriteRules), whole-tool denies
//                        (roleDeniedTools), command-prefix denies (roleDeniedCommands), and the
//                        bsc-agent-native permission doc (bscAgentPerms).
// The full public API is re-exported here unchanged, so every importer keeps working.
//
// The role→capability TABLE + the write-glob / db-owned / dep-manifest lists are externalized to
// `@data/permissions/role-capabilities.json` (#2027 P1) — the single source (Rust does NOT duplicate
// it: TS computes each session's permissions here and passes them to `ensure_session_settings`).

export type { SessionRole, AccessTier, RoleCapability } from "@/shared/lib/session/roleModel";
export {
  ROLE_DEFAULTS,
  PLAN_WRITE_GLOBS,
  DOC_GLOBS,
  DB_OWNED_PLAN_FILES,
  DEP_MANIFEST_FILES,
  roleCapability,
  hasScopedWriteCarveOut,
  restrictedRoleCommands,
  mayFileToolingRequest,
  TOOLING_REQUEST_COMMAND,
  isRestrictedRole, HARVEST_ROOT_APP_REPO, HARVEST_ROOT_PROJECTS,
} from "@/shared/lib/session/roleModel";

export type { CommandClass, CommandDecision } from "@/shared/lib/session/commandGate";
export { classifyCommand, checkCommand } from "@/shared/lib/session/commandGate";

export { matchGlob, canWritePath, scopeWriteGlobs } from "@/shared/lib/session/writeScope";

export type { ToolPermissionRules, BscAgentPerms } from "@/shared/lib/session/launchRules";
export {
  roleWriteRules,
  roleDeniedTools,
  roleDeniedCommands,
  bscAgentPerms,
  sessionScopes,
  editPathRule,
} from "@/shared/lib/session/launchRules";

// SessionSlice — extracted from the store implementation (store split, stage 2).
// Typed Pick<AppStore, …> so AppStore stays whole in types.ts while the create() composes slices.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import { DEFAULT_AUTO_FOCUS_MODE } from "@/app/console/lib/focusQueue";
import { DEFAULT_MODEL_ID } from "@/app/console/lib/models";
import { setMapEntry } from "@/store/updateHelpers";

// NOTE: skills moved to the Skills feature slice (@/features/skills/store) and MCP servers + hooks
// to the MCP feature slice (@/features/mcp/store) (#1309). The standalone
// allowed-command tiers were retired (#1457) — profiles own command auto-approval. This slice
// keeps the global denied-command block-list and the session-wide flags/models.
type SessionSlice = Pick<AppStore,
  "deniedCommands" | "addDeniedCommand" | "removeDeniedCommand" | "setDeniedCommands" | "autoFocusMode" | "setAutoFocusMode" | "autoAdvanceOnReply" | "setAutoAdvanceOnReply" | "autoResumeClaude" | "setAutoResumeClaude" | "injectionHardGate" | "setInjectionHardGate" | "bypassPermissions" | "setBypassPermissions" | "sandboxConsoles" | "setSandboxConsoles" | "activeDebugRequests" | "setActiveDebugRequests" | "appRepoRoot" | "setAppRepoRoot" | "showConsolePage" | "setShowConsolePage" | "autoPlanWithClaude" | "setAutoPlanWithClaude" | "autoCompleteGates" | "setAutoCompleteGates" | "allowGateOverride" | "setAllowGateOverride" | "restrictToBscIssues" | "setRestrictToBscIssues" | "coordAutoWake" | "setCoordAutoWake" | "defaultModel" | "setDefaultModel" | "fleetHarness" | "setFleetHarness" | "paneModels" | "setPaneModel" | "activeStudioTargets" | "setActiveStudioTargets"
>;

export const createSessionSlice: StateCreator<AppStore, [], [], SessionSlice> = (set) => ({
      deniedCommands: [],
      addDeniedCommand: (cmd) =>
        set((s) => {
          const c = cmd.trim().toLowerCase();
          if (!c || s.deniedCommands.includes(c)) return {};
          return { deniedCommands: [...s.deniedCommands, c] };
        }),
      removeDeniedCommand: (cmd) =>
        set((s) => ({ deniedCommands: s.deniedCommands.filter((c) => c !== cmd) })),
      setDeniedCommands: (commands) => set({ deniedCommands: commands }),

      autoFocusMode: DEFAULT_AUTO_FOCUS_MODE,
      setAutoFocusMode: (mode) => set({ autoFocusMode: mode, autoAdvanceOnReply: mode !== "off" }),
      autoAdvanceOnReply: true,
      // Back-compat: syncs to autoFocusMode.
      setAutoAdvanceOnReply: (v) => set({ autoAdvanceOnReply: v, autoFocusMode: v ? "cycle-on-reply" : "off" }),

      // OFF by default (#restart-does-not-resume-sessions). The mechanism is intact and the Settings
      // toggle still turns it back on — this is a default change, not a removal.
      //
      // It defaulted TRUE, which meant that after any unclean shutdown (a kill or force-quit, i.e. the
      // normal case during development) every pane that had ever run Claude relaunched itself with
      // `--continue`, with no click involved. The same flag ALSO suppressed the crash banner, on the
      // reasoning that auto-resume had already handled things — so it started the sessions and hid the
      // control that would have let the user start them. Off, the banner comes back and the restore is
      // a button. Re-enable once the session lifecycle is trusted end-to-end.
      autoResumeClaude: false,
      setAutoResumeClaude: (v) => set({ autoResumeClaude: v }),
      // #1107: when ON, a detected prompt-injection marker in the plan HARD-blocks publish (must be
      // resolved). Default OFF = acknowledge-to-clear (findings surfaced; the user reviews + proceeds).
      injectionHardGate: false,
      setInjectionHardGate: (v) => set({ injectionHardGate: v }),
      // Safe-by-default posture (#2050): sessions run the ALLOW-LIST (Claude's `default` mode enforces
      // the enumerated allow/deny lists — anything unlisted prompts), NOT bypass. The broad base
      // allow-list (base.json) covers the typical dev toolchains so it isn't prompt-spammy, and the
      // deny-hook floor still blocks the dangerous set. Bypass (auto-run-everything) is the opt-in
      // power-user posture via Settings → Security.
      bypassPermissions: false,
      setBypassPermissions: (v) => set({ bypassPermissions: v }),
      sandboxConsoles: false,
      setSandboxConsoles: (v) => set({ sandboxConsoles: v }),
      // BOTH DEBUG TOGGLES REMOVED (#debug-nodes-hang-off-the-session-that-filed-them):
      // `debugSession` gated the standing debugger node (gone with it) and `autoSpawnDebugSessions`
      // gated the per-request sessions, which shipped the whole feature switched off. A filed request
      // is worked now; the only remaining gate is that a source tree must resolve.
      // #3498: which requests have a live session — read by the Glance graph so each one is a visible,
      // openable node rather than a hidden background actor.
      activeDebugRequests: [],
      setActiveDebugRequests: (requests) => set({ activeDebugRequests: requests }),
      // #3509: resolved once at boot; null on a shipped binary with no source tree.
      appRepoRoot: null,
      setAppRepoRoot: (p) => set({ appRepoRoot: p }),
      showConsolePage: false,
      setShowConsolePage: (v) => set({ showConsolePage: v }),

      autoPlanWithClaude: false,
      setAutoPlanWithClaude: (v) => set({ autoPlanWithClaude: v }),

      autoCompleteGates: false,
      setAutoCompleteGates: (v) => set({ autoCompleteGates: v }),

      allowGateOverride: false,
      setAllowGateOverride: (v) => set({ allowGateOverride: v }),

      restrictToBscIssues: true, // secure by default (#738)
      setRestrictToBscIssues: (v) => set({ restrictToBscIssues: v }),
      coordAutoWake: false,
      setCoordAutoWake: (v) => set({ coordAutoWake: v }),

      defaultModel: DEFAULT_MODEL_ID,
      setDefaultModel: (m) => set({ defaultModel: m }),
      fleetHarness: "claude",
      setFleetHarness: (h) => set({ fleetHarness: h }),
      paneModels: {},
      setPaneModel: (paneId, m) =>
        set((s) => ({ paneModels: setMapEntry(s.paneModels, paneId, m) })),

      // Studio network (#2940): which app-owned studio sessions the pump wants reachable right now
      // (targets with open commissions). Transient (NOT persisted) — it drives the lazy-mount hosts
      // in ConsoleWorkspace, which launch the designer/librarian session on demand and tear it down
      // when the list empties.
      activeStudioTargets: [],
      setActiveStudioTargets: (t) => set({ activeStudioTargets: t }),
});

// Rung-4 proof (#2570, part of #2553) — the "Sessions & console behavior" settings card authored as a
// node spec (data), rendered to REAL components by KitRenderer with REAL host (store) wiring. This is
// the composition renderer's honesty check on a low-stakes host screen: the card the user sees is
// produced from a validated spec, not hand-written control JSX. Kept in its own module (not the card
// file) so the card stays component-only (react-refresh) and the spec is directly importable by tests.
//
// Migrated to the GENERAL node vocabulary in #3500 — the closed set of hardcoded kinds is gone, so this
// spec now names REAL primitives (`Card`/`Row`/`Text`/`Toggle`) and every prop it sets is one the
// manifest declares. Three things the `toggle` kind did invisibly are now written down:
//   - `binds` reads the store boolean INTO `on` (was a hardcoded `ctx.values[bind]` read);
//   - `actions` names the host callback that writes it back (was a derived `onBind(bind, !isOn)` —
//     deriving the write required the renderer to know `on` pairs with `onClick`, a pairing the
//     manifest never declared, so the host now exposes the intent as a named action);
//   - `role`/`ariaChecked` are stated, not injected — the accessible-switch semantics are part of the
//     spec rather than a favour the renderer did for one kind.
import type { GeneralNode } from "@/shared/ui/spec";

/** One labelled toggle row: prose on the left, the bound switch on the right — the layout the legacy
 *  `row` + `toggle` kinds hardcoded, now stated as the primitives it always rendered. `ariaChecked`
 *  binds to the SAME state key as `on` so the accessible state can never drift from the visual one. */
function toggleRow(label: string, stateKey: string, action: string): GeneralNode {
  return {
    type: "Row",
    props: { gap: "sm", justify: "between" },
    children: [
      { type: "Text", children: label },
      {
        type: "Toggle",
        props: { role: "switch" },
        binds: { on: stateKey, ariaChecked: stateKey },
        actions: { onClick: action },
      },
    ],
  };
}

/** Body prose under a row — the dim/small treatment the legacy `text` kind applied. */
function note(text: string): GeneralNode {
  return { type: "Text", props: { tone: "dim", size: "sm" }, children: text };
}

/** The two behavior toggles + their prose, as a spec. The `binds` keys are the store booleans the card
 *  wires (`autoResumeClaude` / `autoAdvanceOnReply`); the `actions` names are the host callbacks that
 *  flip them. Everything here is expressible as spec nodes, so no host "slot" is needed. */
export const SESSIONS_BEHAVIOR_SPEC: GeneralNode = {
  type: "Card",
  props: { title: "Sessions & console behavior" },
  children: [
    {
      type: "Stack",
      props: { gap: "sm" },
      children: [
        toggleRow("Auto-resume Claude on restart", "autoResumeClaude", "toggleAutoResumeClaude"),
        note(
          "OFF by default. When on, panes that had Claude running at an UNCLEAN shutdown relaunch it with --continue when the app reopens — no click — and the crash-recovery banner is hidden, since the resume already happened. Off, that banner appears instead and its Restore button is what brings the sessions back, so restarting is always your decision.",
        ),
        toggleRow("Cycle to next console on reply", "autoAdvanceOnReply", "toggleAutoAdvanceOnReply"),
        note(
          "When you send a response to a console, jump focus to the next one waiting in the queue (Ctrl+Shift+N cycles manually). Works while maximized.",
        ),
      ],
    },
  ],
};

// The settings feature's graph-platform surface (register-the-feature-logic-surface) — the modules a
// graph-loaded record imports from this feature but does NOT redraw.
//
// Registered HERE, inside the feature, because the shell must not reach a feature's internals (#1545)
// and eager-importing them from `app/` would de-lazy the whole feature at boot. The feature's BARREL
// calls this at module load, so the shadow catalogue's `ensurePlatform: () => import("@/features/settings")`
// is what registers them — the same shape `registerAutomationsPlatform` already uses.
//
// These files STAY on disk: registration is not migration. It makes a record that imports them
// loadable, which is the prerequisite for migrating the modules that import THEM.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as ToolPresets from "@/features/settings/lib/toolPresets";
import * as Appearance from "@/features/settings/lib/appearance";
import * as ClaudeConfigHelpers from "@/features/settings/cards/claudeConfig.helpers";
import * as UseGithubConnect from "@/features/settings/lib/useGithubConnect";
import * as Shortcuts from "@/features/settings/lib/shortcuts";
import * as Keybindings from "@/features/settings/lib/keybindings";
import * as SessionsBehaviorSpec from "@/features/settings/cards/sessionsBehaviorSpec";

let done = false;

/** Register this feature's injected graph-platform modules by the specifiers a record imports. Idempotent. */
export function registerSettingsPlatform(): void {
  if (done) return;
  done = true;
  registerAppModule("@/features/settings/lib/toolPresets", ToolPresets);
  registerAppModule("@/features/settings/lib/appearance", Appearance);
  registerAppModule("@/features/settings/cards/claudeConfig.helpers", ClaudeConfigHelpers);
  registerAppModule("@/features/settings/lib/useGithubConnect", UseGithubConnect);
  registerAppModule("@/features/settings/lib/shortcuts", Shortcuts);
  registerAppModule("@/features/settings/lib/keybindings", Keybindings);
  registerAppModule("@/features/settings/cards/sessionsBehaviorSpec", SessionsBehaviorSpec);
}

// sha256 over text (#2465) — the frontend's half of the kit-store integrity contract. The global
// UI-kit store keys immutable `id@version` artifacts by the sha256 of their bytes (lowercase hex);
// this must produce the SAME digest as the Rust store (`crates/bsc-ui/src/kit.rs::sha256_hex`) and
// the generator sidecar (node:crypto in reactUiKit.gen.test.ts) so a pin verified here is the pin
// the store enforces. WebCrypto (async) — available in the WebView and in Node ≥ 20.

/** Lowercase hex sha256 of `text` (UTF-8 bytes). */
export async function sha256Hex(text: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

// The shadow report (#4169, step 1 of the graph-renders-the-app reframe) — assemble, per page, the answer
// to "could this page render from the graph, and is the graph copy still the same page?"
//
// Shadow mode renders NOTHING. The app keeps rendering whatever it renders today; this builds each page
// from the graph ALONGSIDE that — resolving its siblings, walking its bindings, diffing its skeleton
// against the file copy — and reports. That is the point of doing it first: the coverage data does not
// exist today, so "is this page ready?" is a judgement call, and the registry work that follows (step 3)
// would be guesswork. This turns both into a list.
//
// Two independent signals per page, and they answer different questions:
//   • STRUCTURAL (`status` / `differingNodes`) — has the graph copy drifted from the file it was
//     transcribed from? A page that renders from the graph today and differs has already lost whatever
//     the file gained; a page that still renders from files and differs is not safe to flip.
//   • BINDING (`unbound`) — every behaviour the page needs that the app has not registered. Each one
//     throws in `makeRequire` the moment the page loads, so a page with any unbound import must NOT be
//     flipped: it renders its fallback, not "most of the page". This is the step-3 worklist.
//
// `readyForGraph` is the conjunction, and is exactly the predicate step 2's resolution chain will ask.
import type { OutlineDiff } from "@/shared/lib/runtime/shadow/outlineDiff";
import type { ExternalImport } from "@/shared/lib/runtime/shadow/pageBinding";

/** The structural verdict for one module of a page. */
export type ModuleStatus =
  | "identical" //        the graph node renders the same element tree as its file
  | "differs" //          the trees diverge — the graph copy has drifted (or the file has moved on)
  | "no-graph-node" //    the file exists; nothing in the graph carries it
  | "no-file-baseline"; // the graph node is the ONLY copy — the file was deleted (fleet, #3636)

/** One module of a page: its page record, its file, and how the two compare. */
export interface ModuleShadow {
  recordId: string;
  /** The file this record was transcribed from, or `null` once that file is gone. */
  file: string | null;
  status: ModuleStatus;
  /** The structural diff — `null` when one side is missing and there is nothing to compare. */
  diff: OutlineDiff | null;
}

/** The page-level verdict — the worst of its modules'. */
export type PageStatus = "graph-identical" | "differs" | "no-graph-node" | "no-file-baseline";

/** What the app renders for this page TODAY. Shadow mode does not change it; it is reported so the
 *  numbers read against reality (a `differs` page already rendering from the graph is a live problem;
 *  the same verdict on a file-rendered page is a not-yet). */
export type RenderSource = "graph" | "file";

/** The shadow verdict for one page. */
export interface PageShadow {
  /** The graph page node's id (`automationspage`). */
  pageId: string;
  label: string;
  rendersFrom: RenderSource;
  status: PageStatus;
  /** Element paths present in one copy and not the other, summed over the page's modules. */
  differingNodes: number;
  /** Elements in the file copy of the page's modules — the denominator for `differingNodes`. */
  fileNodes: number;
  /** Behaviours the page requires that the app has not registered. Non-empty ⇒ loading it throws. */
  unbound: ExternalImport[];
  modules: ModuleShadow[];
  /** True when the page's source resolves and every behaviour it needs is bound — the predicate step 2's
   *  resolution chain asks before it may render this page from the graph. Structural drift does NOT clear
   *  it: a drifted page still renders, it just renders the older skeleton. */
  readyForGraph: boolean;
  /** A compile failure, when the runner verified the source through esbuild (browser-only, so absent from
   *  a node run). A page that will not compile can never mount, whatever its bindings say. */
  compileError?: string;
}

/** Assemble one page's verdict from its per-module diffs and its binding walk. Pure — the runner does the
 *  I/O (store reads, raw file loads, the optional compile) and hands the results here. */
export function buildPageShadow(input: {
  pageId: string;
  label: string;
  rendersFrom: RenderSource;
  modules: ModuleShadow[];
  unbound: ExternalImport[];
  hasGraphNode: boolean;
  compileError?: string;
}): PageShadow {
  const { modules, unbound, hasGraphNode, compileError } = input;
  const differingNodes = modules.reduce((n, m) => n + (m.diff?.differing ?? 0), 0);
  const fileNodes = modules.reduce((n, m) => n + (m.diff?.fileNodes ?? 0), 0);
  const status: PageStatus = !hasGraphNode
    ? "no-graph-node"
    : modules.some((m) => m.status === "no-graph-node") || differingNodes > 0
      ? "differs"
      : modules.every((m) => m.status === "no-file-baseline")
        ? "no-file-baseline"
        : "graph-identical";
  return {
    pageId: input.pageId,
    label: input.label,
    rendersFrom: input.rendersFrom,
    status,
    differingNodes,
    fileNodes,
    unbound,
    modules,
    readyForGraph: hasGraphNode && unbound.length === 0 && !compileError,
    ...(compileError ? { compileError } : {}),
  };
}

/** One line per page, for the log — the format the report is READ in. Terse on purpose: this lands in
 *  `base-studio-code.log` next to the `graph-loader` lines that report what actually mounted. */
export function formatShadowLine(page: PageShadow): string {
  const verdict =
    page.status === "graph-identical"
      ? "graph-identical"
      : page.status === "differs"
        ? `differs in ${page.differingNodes} of ${page.fileNodes} nodes`
        : page.status === "no-file-baseline"
          ? "graph-only (no file baseline)"
          : "NO graph node";
  const bindings = page.unbound.length
    ? `unbound: ${page.unbound.map((u) => u.specifier).join(", ")}`
    : "all behaviors bound";
  const compile = page.compileError ? ` · COMPILE FAILED: ${page.compileError.slice(0, 120)}` : "";
  return `${page.pageId} [renders from ${page.rendersFrom}] — ${verdict} · ${bindings}${compile}`;
}

/** The one-line roll-up: how much of the app the graph could render today. */
export function formatShadowSummary(pages: PageShadow[]): string {
  const identical = pages.filter((p) => p.status === "graph-identical" || p.status === "no-file-baseline").length;
  const ready = pages.filter((p) => p.readyForGraph).length;
  const unbound = new Set(pages.flatMap((p) => p.unbound.map((u) => u.specifier))).size;
  return `${pages.length} pages · ${identical} structurally identical · ${ready} fully bound · ${unbound} distinct unbound specifiers`;
}

// shapePreview (#3439 / #3790) — the SHAPE tier of component preview data. A component that declares a
// `DataShape` (e.g. `shapes: ["list"]`) is fed REAL algorithm-generated data with NO per-component
// `PREVIEW_BINDINGS` row. It sits BETWEEN the curated binding and `samplePropValue`:
//
//     curated binding  →  shape-mock (here)  →  samplePropValue
//
// Supported are the shapes whose data can be both PRODUCED (a `datasetForStructure`) and LANDED on a real
// data prop: `list` (an array prop, filled with generic objects that render across the feed / collection
// components), `graph` (NetworkPage's `nodes`[+`edges`] arrays), and `tree` (#3790 — the Tree /
// TreeExplorerPage `nodes` nested forest, from a BST). Layout composites with no data-array prop
// (GraphCanvas `world:object`, MasterDetail render-props) find no target and fall through to
// `samplePropValue`, as #3439's acceptance requires; `linked-list`/`key-value` have no tracer and also fall
// through. Pure + synchronous (the programs run on the main thread) and strictly FAIL-SOFT: any gap returns
// `{}` so the component's own sample shows and a preview is never broken.
import type { VizDataset, PreviewStructure } from "@/features/algorithms";
import { isCollectionProp } from "@/features/designs/lib/componentPreview";
import type { ComponentRecord, DataShape, PropSpec } from "@/features/designs/lib/model";

/** Fetches a real dataset for a structure. INJECTED (not imported) so this module holds no runtime
 *  dependency on the `@/features/algorithms` barrel — importing the barrel value here pulls its
 *  crossGraphAdapter ↔ designs libraryComposition module-init cycle into every unit test. `usePreviewData`
 *  passes the real `datasetForStructure`; tests pass the real one via the deep (barrel-free) path or a stub. */
export type DatasetForStructure = (structure: PreviewStructure) => VizDataset | undefined;

/** Shape → how to source its dataset + how to land it on the component's props. */
interface ShapeTierEntry {
  structure: PreviewStructure;
  /** Map the dataset onto the component's props → `{ propName: value }`, or `null` when the component
   *  has no prop this shape can land on (then the shape falls through). */
  fill: (ds: VizDataset, props: PropSpec[]) => Record<string, unknown> | null;
}

/** Prop names that conventionally hold the primary data collection — preferred over any other array prop
 *  so a component with an incidental array prop (e.g. `columns`) still gets its DATA prop filled. */
const DATA_PROP_NAMES = ["items", "rows", "data", "entries", "records", "list"];

/** The first array-typed prop, preferring the conventional data-prop names. */
function firstArrayProp(props: PropSpec[]): PropSpec | undefined {
  const arrays = props.filter(isCollectionProp);
  return arrays.find((p) => DATA_PROP_NAMES.includes(p.name.toLowerCase())) ?? arrays[0];
}

function arrayProp(props: PropSpec[], name: string): PropSpec | undefined {
  return props.find((p) => p.name.toLowerCase() === name && isCollectionProp(p));
}

export const SHAPE_TIER: Partial<Record<DataShape, ShapeTierEntry>> = {
  list: {
    structure: "array",
    fill: (ds, props) => {
      if (ds.kind !== "array") return null;
      const prop = firstArrayProp(props);
      if (!prop) return null; // render-prop layout (MasterDetail, CardListRow) → fall through
      // Generic, render-SAFE objects: the UNION of the fields the real list components read, so each
      // renders fully and none crashes — CollectionItem { id, title } AND ActivityItem { login, action,
      // target, repo, createdAt } (its Avatar needs a `login`). The algorithm's value rides along as
      // `value`. Fixed strings keep it deterministic (no `new Date()` → no per-render flicker).
      const items = ds.data.map((value, i) => ({
        id: `n${i}`,
        title: `Item ${i + 1}`,
        label: `Item ${i + 1}`,
        login: `user${(i % 8) + 1}`,
        action: "updated",
        target: `item ${i + 1}`,
        repo: "demo/app",
        createdAt: "2026-01-01T00:00:00.000Z",
        value,
      }));
      return { [prop.name]: items };
    },
  },
  graph: {
    structure: "graph",
    fill: (ds, props) => {
      if (ds.kind !== "graph") return null;
      const nodesProp = arrayProp(props, "nodes");
      if (!nodesProp) return null; // GraphCanvas (world:object, children) has no nodes array → fall through
      const out: Record<string, unknown> = {
        // NetworkNodeData { id, label } — label defaults to the id so it always renders.
        [nodesProp.name]: ds.nodes.map((n) => ({ id: n.id, label: n.label ?? n.id })),
      };
      const edgesProp = arrayProp(props, "edges");
      // NetworkEdgeData { from, to }.
      if (edgesProp) out[edgesProp.name] = ds.edges.map((e) => ({ from: e.from, to: e.to }));
      return out;
    },
  },
  tree: {
    structure: "tree",
    fill: (ds, props) => {
      if (ds.kind !== "tree") return null;
      const nodesProp = arrayProp(props, "nodes");
      if (!nodesProp) return null; // a tree layout with no nodes array → fall through
      // ds.roots are already the nested `{ id, label, children }` forest the Tree/TreeExplorerPage nodes prop wants.
      return { [nodesProp.name]: ds.roots };
    },
  },
};

/** The shape-tier preview-data override for `comp` (`{ prop: JS-source literal }`), or `{}` when it
 *  declares no supported shape, its shape can't land on a real prop, or the dataset is unavailable.
 *  `getDataset` sources the real per-structure dataset (see {@link DatasetForStructure}). */
export function shapePreviewData(comp: ComponentRecord, getDataset: DatasetForStructure): Record<string, string> {
  for (const shape of comp.shapes ?? []) {
    const entry = SHAPE_TIER[shape];
    if (!entry) continue;
    const ds = getDataset(entry.structure);
    if (!ds) continue;
    const filled = entry.fill(ds, comp.props);
    if (filled && Object.keys(filled).length > 0) {
      return Object.fromEntries(Object.entries(filled).map(([k, v]) => [k, JSON.stringify(v)]));
    }
  }
  return {};
}

// Console shell selection + persistence (#447).
//
// The host can launch agent sessions under a specific shell. This module owns
// the selectable shell catalog and the localStorage read/write for the user's
// choice — the I/O half split out of `diagnostics.ts` (#1711) so the verdict
// interpretation there stays pure and React/Tauri-free.
//
// Free of React/Tauri imports so it can be unit-tested and shared.

/**
 * A console shell the host can launch sessions under. `auto` defers to the
 * backend's `resolve_shell` fallback (Git Bash on Windows, login `$SHELL`
 * elsewhere); the explicit kinds force a specific shell. `powershell` and `cmd`
 * are Windows-only — the bsc-* helpers run with reduced functionality there
 * (see the backend's per-shell rc), surfaced in the selector.
 */
export type ShellKind = "auto" | "bash" | "powershell" | "cmd";

/** Selectable shells with a label and whether bsc-* helpers are fully supported. */
export const SHELL_OPTIONS: ReadonlyArray<{
  kind: ShellKind;
  label: string;
  /** False when the bsc-* helpers are degraded under this shell (#447). */
  helpersFull: boolean;
  note: string;
}> = [
  { kind: "auto",       label: "Auto (recommended)", helpersFull: true,  note: "Git Bash on Windows; login shell elsewhere." },
  { kind: "bash",       label: "Bash / Git Bash",    helpersFull: true,  note: "Full bsc-* helper support." },
  { kind: "powershell", label: "PowerShell",          helpersFull: false, note: "Windows only. bsc-* helpers run in degraded mode." },
  { kind: "cmd",        label: "Command Prompt",      helpersFull: false, note: "Windows only. bsc-* helpers run in degraded mode." },
];

/** The default shell selection when nothing is persisted. */
export const DEFAULT_SHELL: ShellKind = "auto";

const SHELL_KEY = "bsc.diagnostics.shell.v1";

/** Narrow an arbitrary string to a known `ShellKind`, falling back to `auto`. */
export function coerceShellKind(value: string | null | undefined): ShellKind {
  return SHELL_OPTIONS.some((o) => o.kind === value) ? (value as ShellKind) : DEFAULT_SHELL;
}

/**
 * Read the persisted console-shell selection. Safe to call in any environment —
 * returns the default when storage is unavailable (e.g. unit tests, SSR).
 */
export function loadShellKind(): ShellKind {
  try {
    return coerceShellKind(globalThis.localStorage?.getItem(SHELL_KEY));
  } catch {
    return DEFAULT_SHELL;
  }
}

/** Persist the console-shell selection. Best-effort; ignores storage failures. */
export function saveShellKind(kind: ShellKind): void {
  try {
    globalThis.localStorage?.setItem(SHELL_KEY, kind);
  } catch {
    /* storage unavailable — selection is also synced to the backend separately */
  }
}

// ShellSlice — app-CHROME state: the active automations/settings sub-tab, per-page tab order,
// detached tabs/sections, and perf + log config. The residual of the former `github` grab-bag after
// GitHub state moved to the GitHub feature slice and tunnel state to the Tunnel feature slice
// (#1309); the chrome fields belong to app/ eventually. Typed Pick<AppStore, …>.
import type { StateCreator } from "zustand";
import { type AppStore, DEFAULT_PERF_CONFIG, DEFAULT_LOG_CONFIG } from "@/store/types";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { setMapEntry } from "@/store/updateHelpers";
import { pickDemoable, mergeSnapshotInto } from "@/store/appState";

type ShellSlice = Pick<AppStore,
  "automationsTab" | "setAutomationsTab" | "pageTabOrder" | "setPageTabOrder" | "activePageTab" | "setActivePageTab" | "crumbEntity" | "setCrumbEntity" | "detachedTabIds" | "setTabDetached" | "detachedSections" | "setSectionDetached" | "settingsSection" | "setSettingsSection" | "dismissedNotices" | "dismissNotice" | "sandboxNudgeDismissCount" | "dismissSandboxNudge" | "perfConfig" | "setPerfConfig" | "logConfig" | "setLogConfig" | "demoActive" | "demoBackup" | "loadDemoState" | "clearDemoState"
>;

export const createShellSlice: StateCreator<AppStore, [], [], ShellSlice> = (set) => ({
      automationsTab: "schedules",
      setAutomationsTab: (tab) => set({ automationsTab: tab }),
      pageTabOrder: {},
      setPageTabOrder: (page, order) =>
        set((s) => ({ pageTabOrder: setMapEntry(s.pageTabOrder, page, order) })),
      activePageTab: {},
      // Idempotent: return state unchanged when the id is already current so the
      // no-op writes from usePageTabs's validity effect don't churn subscribers.
      setActivePageTab: (page, id) =>
        set((s) => (s.activePageTab[page] === id ? s : { activePageTab: setMapEntry(s.activePageTab, page, id) })),
      crumbEntity: {},
      // Idempotent (same guard as setActivePageTab) — the reporting effects fire on every render, so
      // skip the write when the label is unchanged to avoid churning subscribers.
      setCrumbEntity: (key, label) =>
        set((s) => (s.crumbEntity[key] === label ? s : { crumbEntity: setMapEntry(s.crumbEntity, key, label) })),
      detachedTabIds: [],
      setTabDetached: (id, detached) =>
        set((s) => ({
          detachedTabIds: detached
            ? (s.detachedTabIds.includes(id) ? s.detachedTabIds : [...s.detachedTabIds, id])
            : s.detachedTabIds.filter((x) => x !== id),
        })),
      detachedSections: {},
      setSectionDetached: (page, id, detached) =>
        set((s) => {
          const cur = s.detachedSections[page] ?? [];
          const next = detached
            ? (cur.includes(id) ? cur : [...cur, id])
            : cur.filter((x) => x !== id);
          return { detachedSections: setMapEntry(s.detachedSections, page, next) };
        }),

      settingsSection: "github",
      setSettingsSection: (section) => set({ settingsSection: section }),

      dismissedNotices: [],
      dismissNotice: (id) =>
        set((s) => (s.dismissedNotices.includes(id) ? s : { dismissedNotices: [...s.dismissedNotices, id] })),

      sandboxNudgeDismissCount: 0,
      dismissSandboxNudge: () => set((s) => ({ sandboxNudgeDismissCount: s.sandboxNudgeDismissCount + 1 })),

      perfConfig: DEFAULT_PERF_CONFIG,
      setPerfConfig: (config) => {
        set({ perfConfig: config });
        // Push the new config to the Rust backend so the sampler respects it.
        fireInvoke("perf_set_config", {
          enabled: config.enabled,
          intervalSecs: config.intervalSecs,
          retentionHours: config.retentionHours,
          maxDbMb: config.maxDbMb,
          trackProcess: config.trackProcess,
          trackFrontend: config.trackFrontend,
        });
      },

      logConfig: DEFAULT_LOG_CONFIG,
      setLogConfig: (config) => {
        set({ logConfig: config });
        // Push the cap to the Rust backend so "Enforce now" and the next startup respect it.
        fireInvoke("log_set_config", {
          maxLines: config.maxLines,
          maxSizeMb: config.maxSizeMb,
        });
      },

      // Demo app-state (#2272). Loading MERGES the demo onto the demoable slices (additive — arrays
      // union by id, objects by key; #2288) so it augments the built-in libraries instead of wiping
      // them, and stashes the pre-demo values (once — a re-load keeps the ORIGINAL backup); clearing
      // restores them exactly (removing the demo's additions).
      demoActive: false,
      demoBackup: null,
      loadDemoState: (snapshot) =>
        set((s) => ({
          ...mergeSnapshotInto(s as unknown as Record<string, unknown>, snapshot),
          demoActive: true,
          demoBackup: s.demoActive ? s.demoBackup : pickDemoable(s),
        })),
      clearDemoState: () =>
        set((s) => (s.demoActive && s.demoBackup
          ? { ...s.demoBackup, demoActive: false, demoBackup: null }
          : { demoActive: false, demoBackup: null })),
});

