// The frontend ↔ global skills.db bridge (#1338 ph2). The desktop Skills library and every live
// console session share ONE global store (`~/.base-studio-code/skills.db`), reached here — and from a
// session's own shell — through the SAME `bsc skill …` CLI, over the generic `bsc` bridge (#2114/#2142;
// it replaced the parallel per-verb `skill_store_*`/`skill_group_*` Tauri commands). Skills are GLOBAL
// (no project key) so every call passes `null` as the bridge's `projectKey`. This is the only place the
// skills feature touches Tauri, so the pure model in `skills.ts` stays React/Tauri-free.
//
// Source-of-truth: skills.db. The Zustand slice is a write-through cache — `loadLibrary` hydrates it
// on boot; each library mutation pushes through here. Per-session toggles (overrides / toggled-on
// groups) are NOT part of the global library and stay store-local; only skills + groups round-trip.
//
// Mapping: the Rust `Skill` omits the display-only telemetry (`invocations`/`success`/`avgTokensK`/
// `trend`), so a loaded skill is re-defaulted to a full {@link SkillDef} here; pushing a SkillDef is
// serde-safe because the Rust side ignores the extra telemetry fields. `list --full` (#2142) emits the
// COMPLETE skill objects (prompt + tools/profiles/packaged), matching the old `skill_store_list` shape
// — the lean paginated `list` would drop the `prompt` body that a write-through would then blank.

import { bsc, bscRun, bscWrite } from "@/shared/lib/core/bsc";
import type { SkillDef, SkillGroup } from "@/features/skills/lib/skills";
import type { SkillKind, SkillSource, SkillProfile } from "@/shared/data/skills";

/** The library as stored in skills.db (telemetry re-defaulted to zero on the way in). */
export interface Library {
  skills: SkillDef[];
  groups: SkillGroup[];
}

/** A skill row from the bridge → a full {@link SkillDef} (zero telemetry; packaged defaults false). */
function toDef(s: Partial<SkillDef> & { id: string; name: string }): SkillDef {
  return {
    id: s.id,
    name: s.name,
    kind: (s.kind as SkillKind) ?? "workflow",
    source: (s.source as SkillSource) ?? "first-party",
    desc: s.desc ?? "",
    prompt: s.prompt ?? "",
    tools: s.tools ?? [],
    profiles: (s.profiles as SkillProfile[]) ?? [],
    projects: s.projects ?? [],
    enabled: !!s.enabled,
    pinned: !!s.pinned,
    packaged: !!s.packaged,
    invocations: 0, success: 0, avgTokensK: 0, trend: [],
  };
}

/**
 * Hydrate the library from skills.db. Returns `null` when the bridge is unreachable (no Tauri host —
 * tests, the web shell, or an old binary), so the caller keeps its seeded in-memory set rather than
 * blanking the UI. Any single bad row is tolerated (the command itself either succeeds with the full
 * set or rejects).
 */
export async function loadLibrary(): Promise<Library | null> {
  // NOT `bscJson` here: its graceful degrade-to-fallback would return an EMPTY library when the bridge
  // is unreachable, and hydrate would then blank the seeded set. We need the explicit `null` (keep the
  // seeded set) the store depends on — so raw `bsc` + catch, exactly like the old per-command version.
  try {
    const [skillsOut, groupsOut] = await Promise.all([
      bsc(null, ["skill", "list", "--full"]), // full-fidelity array (incl. prompt) — the #2142 read
      bsc(null, ["skill", "group", "list"]),
    ]);
    const skills = JSON.parse(skillsOut.trim() || "[]") as Array<Partial<SkillDef> & { id: string; name: string }>;
    const groups = JSON.parse(groupsOut.trim() || "[]") as SkillGroup[];
    return { skills: (skills ?? []).map(toDef), groups: groups ?? [] };
  } catch {
    return null;
  }
}

/** Write-through a skill upsert (`bsc skill add` reads the JSON on stdin). Fire-and-forget; never throws. */
export async function pushSkill(skill: SkillDef): Promise<void> {
  await bscWrite(null, ["skill", "add"], skill);
}

/** Write-through a skill removal (`bsc skill remove <id>`). */
export async function dropSkill(id: string): Promise<void> {
  await bscRun(null, ["skill", "remove", id]);
}

/** Write-through a group upsert (`bsc skill group add` reads the JSON on stdin). */
export async function pushGroup(group: SkillGroup): Promise<void> {
  await bscWrite(null, ["skill", "group", "add"], group);
}

/** Write-through a group removal (`bsc skill group remove <id>`). */
export async function dropGroup(id: string): Promise<void> {
  await bscRun(null, ["skill", "group", "remove", id]);
}

// Task groups (#skills-groups): named, reusable bundles of skills toggled as one,
// their expansion into a member-id set, membership counting, and the planner's
// `skill_groups.json` parser.

import { skillSlug, type SkillDef } from "@/features/skills/lib/skillsModel";

// ── Task groups (#skills-groups) ────────────────────────────────────────────────
// A "task group" is a named, reusable bundle of skills (the redesign's ⬡). Many-to-many with
// skills (a skill can belong to several groups), keyed by stable skill id. A group is the unit of
// bulk toggling: toggle a group onto a session (manually, Workspace B) or onto a fleet stream (the
// planner) and every member skill is enabled at once. Groups are LIVE references — editing a
// group's membership updates every session/stream that has it on, rather than freezing the set.

/** A named bundle of skills, toggled as one. */
export interface SkillGroup {
  id: string;
  name: string;
  /** Accent hue (a `--token` ref or oklch literal) for the group's ⬡ chip/tile. */
  hue: string;
  /** Member skill ids (stable — never names, which can change). */
  skillIds: string[];
}

/** The DISTINCT member skill ids across a set of enabled group ids (order-stable, de-duped). An
 *  unknown group id contributes nothing. Used to expand a session's/stream's toggled-on groups
 *  into the `groupSkillIds` set that {@link effectiveSessionSkills} folds in. */
export function expandGroups(groupIds: readonly string[], groups: SkillGroup[]): string[] {
  const byId = new Map(groups.map((g) => [g.id, g]));
  const out = new Set<string>();
  for (const gid of groupIds) for (const sid of byId.get(gid)?.skillIds ?? []) out.add(sid);
  return [...out];
}

/** Membership count of a group whose member skills still exist in `all` (the chip count). */
export function groupSkillCount(group: SkillGroup, all: SkillDef[]): number {
  const ids = new Set(all.map((s) => s.id));
  return group.skillIds.filter((id) => ids.has(id)).length;
}

/** Parse the planner's `skill_groups.json` (a JSON array of `{name, hue?, skills?: string[]}`) into
 *  clean groups. `skills` may be skill ids OR name-slugs (the planner authors by name); they're
 *  resolved against the library here so the stored group keys by id. Tolerant: malformed input →
 *  []; a row without a usable name is dropped. Mirrors {@link parseSkillsFile}. */
export function parseSkillGroupsFile(raw: string, all: SkillDef[]): Array<Omit<SkillGroup, "id"> & { id?: string }> {
  let data: unknown;
  try { data = JSON.parse(raw); } catch { return []; }
  if (!Array.isArray(data)) return [];
  const bySlug = new Map(all.map((s) => [skillSlug(s.name), s.id]));
  const byId = new Set(all.map((s) => s.id));
  const out: Array<Omit<SkillGroup, "id"> & { id?: string }> = [];
  for (const row of data) {
    if (!row || typeof row !== "object") continue;
    const r = row as Record<string, unknown>;
    const name = typeof r.name === "string" ? r.name.trim() : "";
    if (!name) continue;
    const refs = Array.isArray(r.skills) ? r.skills.filter((x): x is string => typeof x === "string") : [];
    const skillIds = Array.from(new Set(
      refs.map((ref) => (byId.has(ref) ? ref : bySlug.get(skillSlug(ref)))).filter((x): x is string => !!x),
    ));
    out.push({
      id: typeof r.id === "string" && r.id ? r.id : undefined,
      name,
      hue: typeof r.hue === "string" && r.hue ? r.hue : "var(--accent)",
      skillIds,
    });
  }
  return out;
}

// Shared inline-style factories for the Skills screen (#1706). Pulled out of SkillsWorkspace.tsx so
// the screen, the view-mode renderers (SkillsViews.tsx), and the edit drawer all share one source
// of the pill / tile / scope-color styling. Pure CSSProperties builders (the only React coupling is
// the type import).

import type { CSSProperties } from "react";
import { KIND, type SkillKind, type SkillSource } from "@/shared/data/skills";

/** Success-rate → color: dim when unknown, success/accent/danger by threshold. */
export const successColor = (s: number | null): string =>
  s == null ? "var(--fg-dim)" : s >= 95 ? "var(--success)" : s >= 85 ? "var(--accent)" : "var(--danger)";

/** A translucent tint of `hue` (a `--token` ref or oklch literal). */
export function tintBg(hue: string, t = 88): string { return `color-mix(in oklch, ${hue}, transparent ${t}%)`; }

/** A small pill chip in `hue` (or a neutral "plain" chip). */
export function pill(hue: string, plain = false): CSSProperties {
  const base: CSSProperties = { fontFamily: "var(--mono)", fontSize: 9.5, padding: "2px 7px", borderRadius: 99, lineHeight: 1.1, whiteSpace: "nowrap", display: "inline-flex", alignItems: "center" };
  if (plain) return { ...base, background: tintBg("var(--fg-dim)"), border: "1px solid " + tintBg("var(--fg-dim)", 80), color: "var(--fg-muted)" };
  return { ...base, background: tintBg(hue), border: `1px solid ${tintBg(hue, 74)}`, color: hue };
}

/** A square glyph tile in an arbitrary hue (a `--token` ref or oklch literal). */
export function hueTile(c: string, lg = false): CSSProperties {
  const d = lg ? 30 : 22;
  return { width: d, height: d, flex: "0 0 auto", display: "flex", alignItems: "center", justifyContent: "center", borderRadius: 6, fontFamily: "var(--mono)", fontSize: lg ? 15 : 12, color: c, background: `color-mix(in oklch, ${c} 22%, var(--bg-elev))`, border: `1px solid ${tintBg(c, 70)}` };
}

/** A glyph tile colored by the skill kind. */
export function glyphTile(kind: SkillKind, lg = false): CSSProperties {
  return hueTile(KIND[kind].color, lg);
}

/** Source pill: info for team, accent for imported, neutral otherwise. */
export const sourcePill = (src: SkillSource): CSSProperties =>
  src === "team" ? pill("var(--info)") : src === "imported" ? pill("var(--accent)") : pill("", true);

/** Scope pill: info when project-scoped, neutral when global. */
export const scopePill = (projects: string[]): CSSProperties => (projects.length ? pill("var(--info)") : pill("", true));

// Skill-invocation telemetry — parse + aggregate the `skills.log` written by the
// `bsc-skill` hook on gated panes (see lib.rs). Each invocation appends a
// PreToolUse line; each success appends a PostToolUse line. Both are tagged with
// the skill name. Pure + unit-testable (the `now` clock is injected). (#406)
//
// Mirrors the Agents audit-log model (features/agents/lib/auditLog.ts): a flat TSV
// `ts \t pane \t event \t skill`, read newest-first via `bsc logs tail skill`.

import { skillSlug } from "@/features/skills/lib/skills";

/** One parsed `bsc-skill` line. `event` is the hook event name (PreToolUse =
 *  one per invocation; PostToolUse = one per success). `skill` is the raw
 *  `skill_name` from the hook payload. */
export interface SkillUsageRecord {
  ts: string;     // ISO-8601 (UTC, "Z")
  pane: string;   // paneId
  event: string;  // "PreToolUse" | "PostToolUse" | …
  skill: string;  // raw skill_name
}

/** Per-skill aggregates, keyed by skill-name slug. */
export interface SkillStats {
  /** total invocations (PreToolUse lines). */
  invocations: number;
  /** successful invocations (PostToolUse lines). */
  success: number;
  /** success rate 0–100 (0 when never invoked). */
  successRate: number;
  /** invocations whose timestamp falls on the current UTC day. */
  today: number;
  /** invocation counts per day for the last 7 UTC days, oldest→newest. */
  trend: number[];
}

/** Parse the TSV skill-usage log into records, skipping malformed lines. */
export function parseSkillLog(text: string): SkillUsageRecord[] {
  const out: SkillUsageRecord[] = [];
  for (const line of text.split("\n")) {
    if (!line.trim()) continue;
    const [ts, pane, event, ...rest] = line.split("\t");
    if (ts && pane && event) {
      out.push({ ts, pane, event, skill: rest.join("\t") });
    }
  }
  return out;
}

/** The UTC calendar day (YYYY-MM-DD) of an ISO timestamp. */
function dayKey(iso: string): string {
  return iso.slice(0, 10);
}

/** The 7 UTC day-keys ending today (oldest→newest). */
function last7Days(now: Date): string[] {
  const days: string[] = [];
  for (let i = 6; i >= 0; i--) {
    const d = new Date(now.getTime() - i * 86_400_000);
    days.push(d.toISOString().slice(0, 10));
  }
  return days;
}

/**
 * Aggregate usage records into per-skill stats, keyed by the skill-name slug so
 * a record's raw `skill_name` (whether the directory slug or the display name)
 * resolves to the same bucket as a {@link SkillDef} via {@link skillSlug}.
 */
export function aggregateSkillTelemetry(
  records: SkillUsageRecord[],
  now: Date,
): Record<string, SkillStats> {
  const today = now.toISOString().slice(0, 10);
  const days = last7Days(now);
  const dayIndex = new Map(days.map((d, i) => [d, i]));

  const acc: Record<string, { inv: number; ok: number; today: number; trend: number[] }> = {};
  const bucket = (key: string) => (acc[key] ??= { inv: 0, ok: 0, today: 0, trend: [0, 0, 0, 0, 0, 0, 0] });

  for (const r of records) {
    const key = skillSlug(r.skill);
    if (!key) continue;
    const b = bucket(key);
    if (r.event === "PreToolUse") {
      b.inv += 1;
      if (dayKey(r.ts) === today) b.today += 1;
      const di = dayIndex.get(dayKey(r.ts));
      if (di !== undefined) b.trend[di] += 1;
    } else if (r.event === "PostToolUse") {
      b.ok += 1;
    }
  }

  const out: Record<string, SkillStats> = {};
  for (const [key, b] of Object.entries(acc)) {
    // Clamp successes to invocations — a PostToolUse without a captured PreToolUse
    // (e.g. log truncation) must never push the rate above 100%.
    const success = Math.min(b.ok, b.inv);
    out[key] = {
      invocations: b.inv,
      success,
      successRate: b.inv > 0 ? Math.round((success / b.inv) * 100) : 0,
      today: b.today,
      trend: b.trend,
    };
  }
  return out;
}

/**
 * Status-bar KPIs for the Skills page, from the real telemetry (replaces the mock
 * `SKILL_KPIS`). `loaded` is the library size; `invToday` sums today's invocations across
 * skills; `worst` is the lowest-success-rate skill among those actually invoked (the quality
 * flag shown with a warning), or `null` when nothing has been invoked. Pure + unit-tested.
 */
export function skillStatusKpis(
  skillCount: number,
  stats: Record<string, SkillStats>,
): { loaded: number; invToday: number; worst: { skill: string; rate: number } | null } {
  let invToday = 0;
  let worst: { skill: string; rate: number } | null = null;
  for (const [skill, s] of Object.entries(stats)) {
    invToday += s.today;
    if (s.invocations > 0 && (worst == null || s.successRate < worst.rate)) {
      worst = { skill, rate: s.successRate };
    }
  }
  return { loaded: skillCount, invToday, worst };
}

// Pure facet / filter / sort logic for the Skills library screen (#1706). Extracted from
// SkillsWorkspace.tsx so the search + multi-facet filtering, the five sort orders, the facet
// definitions (with their live counts), the grouped/kind sectioning, and the telemetry merge
// are all unit-testable in isolation, free of React.
//
// Free of React / Tauri imports — mirrors lib/skills.ts.

import { KIND, type SkillKind, type SkillSource } from "@/shared/data/skills";
import { skillSlug, type SkillDef, type SkillGroup } from "@/features/skills/lib/skills";
import type { SkillStats } from "@/features/skills/lib/skillTelemetry";

const KIND_KEYS = Object.keys(KIND) as SkillKind[];
const SOURCE_KEYS: SkillSource[] = ["first-party", "team", "imported", "community"];

/** The four library densities (view modes). */
export type Density = "list" | "cards" | "grouped" | "kind";

/** The five library sort orders. */
export type SortKey = "Most invoked" | "Name (A–Z)" | "Success rate" | "Recently used" | "Recently added";

export const SORTS: SortKey[] = ["Most invoked", "Name (A–Z)", "Success rate", "Recently used", "Recently added"];

/** Stable pseudo-recency from the id so "Recently used/added" sort is deterministic in the demo. */
export const hashN = (s: string): number => {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
};

/** Merge the live telemetry (keyed by skill-name slug) over the library — a skill with no usage
 *  reads zero invocations / success / trend. */
export function mergeSkillStats(skills: SkillDef[], stats: Record<string, SkillStats>): SkillDef[] {
  return skills.map((s) => {
    const st = stats[skillSlug(s.name)];
    return st
      ? { ...s, invocations: st.invocations, success: st.successRate, trend: st.trend }
      : { ...s, invocations: 0, success: 0, trend: [] };
  });
}

/** Index of skillId → the task groups it belongs to (for the ⬡ membership badge). */
export function indexGroupsBySkill(skillGroups: SkillGroup[]): Map<string, SkillGroup[]> {
  const m = new Map<string, SkillGroup[]>();
  for (const g of skillGroups) for (const id of g.skillIds) {
    const a = m.get(id) ?? [];
    a.push(g);
    m.set(id, a);
  }
  return m;
}

export interface FacetOption {
  value: string;
  label: string;
  glyph: string;
  color: string;
  count: number;
  match: (s: SkillDef) => boolean;
}

export interface FacetDef {
  key: string;
  title: string;
  options: FacetOption[];
}

/** A facet selection: facet key → the set of selected option values. */
export type FacetSelection = Record<string, Set<string>>;

/** The facet column definitions, with each option's live count computed over `merged`. */
export function buildFacetDefs(merged: SkillDef[]): FacetDef[] {
  const c = (pred: (s: SkillDef) => boolean) => merged.filter(pred).length;
  return [
    { key: "kind", title: "Kind", options: KIND_KEYS.map((k) => ({ value: k, label: k, glyph: KIND[k].glyph, color: KIND[k].color, count: c((s) => s.kind === k), match: (s: SkillDef) => s.kind === k })) },
    { key: "source", title: "Source", options: SOURCE_KEYS.map((k) => ({ value: k, label: k, glyph: "", color: "", count: c((s) => s.source === k), match: (s: SkillDef) => s.source === k })) },
    { key: "scope", title: "Scope", options: [
      { value: "global", label: "global", glyph: "", color: "", count: c((s) => !s.projects.length), match: (s: SkillDef) => !s.projects.length },
      { value: "scoped", label: "project-scoped", glyph: "", color: "", count: c((s) => s.projects.length > 0), match: (s: SkillDef) => s.projects.length > 0 },
    ] },
    { key: "status", title: "Status", options: [
      { value: "enabled", label: "enabled", glyph: "", color: "", count: c((s) => s.enabled), match: (s: SkillDef) => s.enabled },
      { value: "disabled", label: "disabled", glyph: "", color: "", count: c((s) => !s.enabled), match: (s: SkillDef) => !s.enabled },
      { value: "pinned", label: "pinned", glyph: "", color: "", count: c((s) => s.pinned), match: (s: SkillDef) => s.pinned },
    ] },
    { key: "usage", title: "Usage", options: [
      { value: "used", label: "used · 7d", glyph: "", color: "", count: c((s) => s.invocations > 0), match: (s: SkillDef) => s.invocations > 0 },
      { value: "never", label: "never run", glyph: "", color: "", count: c((s) => s.invocations === 0), match: (s: SkillDef) => s.invocations === 0 },
    ] },
  ];
}

export interface FilterArgs {
  query: string;
  /** Selected task group id (single-select), or null for all. */
  groupFilter: string | null;
  skillGroups: SkillGroup[];
  facetDefs: FacetDef[];
  facetSel: FacetSelection;
  sort: SortKey;
}

/** Apply the group filter, free-text query, multi-facet filters (OR within a facet, AND across
 *  facets), then sort. Returns a fresh array; `merged` is never mutated. */
export function filterSkills(merged: SkillDef[], args: FilterArgs): SkillDef[] {
  const { query, groupFilter, skillGroups, facetDefs, facetSel, sort } = args;
  const q = query.trim().toLowerCase();
  let pool = merged;
  if (groupFilter) {
    const g = skillGroups.find((x) => x.id === groupFilter);
    const ids = new Set(g?.skillIds ?? []);
    pool = pool.filter((s) => ids.has(s.id));
  }
  if (q) pool = pool.filter((s) => (s.name + " " + s.desc + " " + s.tools.join(" ") + " " + s.source).toLowerCase().includes(q));
  for (const def of facetDefs) {
    const sel = facetSel[def.key];
    if (!sel?.size) continue;
    const opts = def.options.filter((o) => sel.has(o.value));
    pool = pool.filter((s) => opts.some((o) => o.match(s)));   // OR within a facet
  }
  const sorters: Record<SortKey, (a: SkillDef, b: SkillDef) => number> = {
    "Name (A–Z)": (a, b) => a.name.localeCompare(b.name),
    "Most invoked": (a, b) => b.invocations - a.invocations,
    "Success rate": (a, b) => (b.success || 0) - (a.success || 0),
    "Recently used": (a, b) => hashN(b.id + "u") - hashN(a.id + "u"),
    "Recently added": (a, b) => hashN(b.id + "a") - hashN(a.id + "a"),
  };
  return [...pool].sort(sorters[sort]);
}

export interface GroupedSection {
  id: string;
  label: string;
  glyph: string;
  hue: string;
  items: SkillDef[];
}

/** Section the filtered skills for the grouped / kind densities: by skill kind in "kind" density,
 *  else by task group (with an "Ungrouped" trailer for skills in no group). Empty sections drop. */
export function buildGroupedSections(density: Density, filtered: SkillDef[], skillGroups: SkillGroup[]): GroupedSection[] {
  if (density === "kind") {
    return KIND_KEYS
      .map((k) => ({ id: k, label: KIND[k].label, glyph: KIND[k].glyph, hue: KIND[k].color, items: filtered.filter((s) => s.kind === k) }))
      .filter((g) => g.items.length);
  }
  const sections: GroupedSection[] = skillGroups
    .map((g) => ({ id: g.id, label: g.name, glyph: "⬡", hue: g.hue, items: filtered.filter((s) => g.skillIds.includes(s.id)) }))
    .filter((g) => g.items.length);
  const grouped = new Set(skillGroups.flatMap((g) => g.skillIds));
  const ungrouped = filtered.filter((s) => !grouped.has(s.id));
  if (ungrouped.length) sections.push({ id: "__ungrouped__", label: "Ungrouped", glyph: "·", hue: "var(--fg-dim)", items: ungrouped });
  return sections;
}

// Derived KPIs computed from the live skills list (the Skills screen's header tiles).

import type { SkillDef } from "@/features/skills/lib/skillsModel";

// ── derived KPIs (from the live list) ──────────────────────────────────────────

export interface DerivedSkillKpis {
  total: number;
  pinned: number;
  /** sum of per-skill invocations (display telemetry). */
  invWeek: number;
  /** invocation-weighted success rate (0 when there are no invocations). */
  avgSuccess: number;
}

export function deriveSkillKpis(skills: SkillDef[]): DerivedSkillKpis {
  const totalInv = skills.reduce((a, s) => a + s.invocations, 0);
  const avgSuccess = totalInv > 0
    ? Math.round(skills.reduce((a, s) => a + s.success * s.invocations, 0) / totalInv)
    : 0;
  return {
    total: skills.length,
    pinned: skills.filter(s => s.pinned).length,
    invWeek: totalInv,
    avgSuccess,
  };
}

// The SkillDef model + the leaf helpers every other skills-lib module builds on:
// the directory-safe slug and the blank-form factory, plus the coercion key sets
// derived from the shared skills data.
//
// Free of React / Tauri imports so it can be unit-tested and shared between the
// store, the Skills screen, the planner ingestion, and TerminalView.

import {
  KIND, PROFILE_COLOR,
  type SkillKind, type SkillSource, type SkillProfile,
} from "@/shared/data/skills";

export const KIND_KEYS = Object.keys(KIND) as SkillKind[];
export const PROFILE_KEYS = Object.keys(PROFILE_COLOR) as SkillProfile[];
export const SOURCE_KEYS: SkillSource[] = ["first-party", "team", "imported", "community"];

/**
 * A user- or planner-configured skill: a reusable capability bundle (a prompt +
 * bundled tools + profile guardrails) any worker may invoke. Injected into a
 * launched session as a Claude Code Skill file. Scoped via {@link SkillDef.projects}.
 */
export interface SkillDef {
  id: string;
  name: string;
  kind: SkillKind;
  source: SkillSource;
  /** One-line description (the SKILL.md frontmatter `description` + the card). */
  desc: string;
  /** The reusable procedure, written as the SKILL.md body. */
  prompt: string;
  /** Tool names bundled with the skill → the SKILL.md `allowed-tools`. */
  tools: string[];
  /** Permission profiles allowed to invoke it. */
  profiles: SkillProfile[];
  /** `[]` = every project (global); otherwise the project ids it applies to. */
  projects: string[];
  enabled: boolean;
  /** Pinned skills are auto-available to the fleet. */
  pinned: boolean;
  /** Code-owned packaged skill (seeded from {@link seedSkills}). Lets a load-time
   *  refresh replace it from code and prune any packaged skill dropped from the
   *  library, while never touching user-created / imported / catalog skills. */
  packaged?: boolean;
  // ── display-only telemetry (not yet live; see #404 follow-up) ──
  invocations: number;
  success: number;
  avgTokensK: number;
  trend: number[];
}

/** Directory-safe slug for a skill name (matches the Rust slugger). */
export function skillSlug(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, "");
}

/** A stable content key over a skill's AUTHORED fields — the analogue of teams' `orgStructureKey`
 *  (#3330). `hydrateSkills` compares it (#3672) to re-push ONLY skills whose packaged content drifted
 *  (a code update) instead of re-writing every skill each boot. User/display state (enabled / pinned /
 *  projects / telemetry) is deliberately excluded — those write through via their own mutations, so a
 *  toggle never triggers a hydrate re-push. */
export function skillContentKey(s: SkillDef): string {
  return JSON.stringify([s.name, s.kind, s.source, s.desc, s.prompt, s.tools, s.profiles]);
}

/** A blank custom skill, ready for the new-skill form. */
export function blankSkill(): Omit<SkillDef, "id"> {
  return {
    name: "", kind: "workflow", source: "first-party",
    desc: "", prompt: "", tools: [], profiles: ["build"], projects: [],
    enabled: false, pinned: false,
    invocations: 0, success: 0, avgTokensK: 0, trend: [],
  };
}

// Planner channel (skills.json): the PlannerSkill entry shape and the tolerant
// parser that turns the planner's authored JSON array into clean, defaulted skills
// the caller upserts into the global library.

import { type SkillKind, type SkillSource, type SkillProfile } from "@/shared/data/skills";
import { KIND_KEYS, PROFILE_KEYS, SOURCE_KEYS, type SkillDef } from "@/features/skills/lib/skillsModel";

// ── Planner channel (skills.json) ──────────────────────────────────────────────

/** One entry the planner may write to `skills.json` (everything but id optional). */
export interface PlannerSkill extends Omit<SkillDef, "id"> { id?: string }

/**
 * Parse the planner's `skills.json` (a JSON array of skill objects) into clean,
 * defaulted {@link PlannerSkill}s. Tolerant of partial objects and malformed
 * input — anything unparseable yields `[]`, and a row without a usable name is
 * dropped. New planner skills are enabled + pinned by default (auto-available to
 * the fleet); the caller upserts them into the global library.
 */
export function parseSkillsFile(raw: string): PlannerSkill[] {
  let data: unknown;
  try { data = JSON.parse(raw); } catch { return []; }
  if (!Array.isArray(data)) return [];
  const out: PlannerSkill[] = [];
  for (const row of data) {
    if (!row || typeof row !== "object") continue;
    const r = row as Record<string, unknown>;
    const name = typeof r.name === "string" ? r.name.trim() : "";
    if (!name) continue;
    out.push({
      id: typeof r.id === "string" && r.id ? r.id : undefined,
      name,
      kind: coerceKind(r.kind),
      source: coerceSource(r.source) ?? "team",
      desc: typeof r.desc === "string" ? r.desc : typeof r.description === "string" ? r.description : "",
      prompt: typeof r.prompt === "string" ? r.prompt : "",
      tools: coerceStrings(r.tools),
      profiles: coerceProfiles(r.profiles),
      projects: coerceStrings(r.projects),
      enabled: r.enabled === undefined ? true : !!r.enabled,
      pinned: r.pinned === undefined ? true : !!r.pinned,
      invocations: 0, success: 0, avgTokensK: 0, trend: [],
    });
  }
  return out;
}

function coerceStrings(v: unknown): string[] {
  return Array.isArray(v) ? v.filter((x): x is string => typeof x === "string" && x.trim() !== "") : [];
}
function coerceKind(v: unknown): SkillKind {
  return typeof v === "string" && (KIND_KEYS as string[]).includes(v) ? v as SkillKind : "workflow";
}
function coerceSource(v: unknown): SkillSource | null {
  return typeof v === "string" && (SOURCE_KEYS as string[]).includes(v) ? v as SkillSource : null;
}
function coerceProfiles(v: unknown): SkillProfile[] {
  const arr = coerceStrings(v).filter(x => (PROFILE_KEYS as string[]).includes(x)) as SkillProfile[];
  return arr.length ? arr : ["build"];
}

// Backend payload: resolved SkillDefs → the SkillCfg shape handed to
// `ensure_session_settings` and written into a session's `.claude/skills/<slug>/SKILL.md`.

import { skillSlug, type SkillDef } from "@/features/skills/lib/skillsModel";

// ── Backend payload ─────────────────────────────────────────────────────────
// Shape handed to `ensure_session_settings` (field names match the Rust SkillCfg).

export interface SkillCfg {
  /** Stable skilldb id — carried so the backend can count an attach as a use (#A). */
  id: string;
  name: string;
  description: string;
  prompt: string;
  tools: string[];
}

/** Resolved skills → their `.claude/skills/<slug>/SKILL.md` payloads. Skips any
 *  skill whose name slugs to empty (nothing to key the directory on). Carries the
 *  stable id so the launch path can count an attach as a use (#A). */
export function toSkillCfgs(defs: SkillDef[]): SkillCfg[] {
  const out: SkillCfg[] = [];
  for (const s of defs) {
    if (!skillSlug(s.name)) continue;
    out.push({ id: s.id, name: s.name, description: s.desc, prompt: s.prompt, tools: s.tools });
  }
  return out;
}

// Catalog → SkillDef templates and the packaged-skill lifecycle: seeding the
// initial library from the sample set, reconstructing a def from a shared
// blueprint's embedded payload, and reconciling a persisted library with the
// code-owned packaged set on load.

import { SKILLS, type Skill, type SkillKind } from "@/shared/data/skills";
import { KIND_KEYS, type SkillDef } from "@/features/skills/lib/skillsModel";

/** Reconstruct a SkillDef from a shared blueprint's embedded skill payload (#897 Phase 5b).
 *  Keeps the original id (so the blueprint's refs resolve) + content; marks it `source:
 *  "imported"` and defaults everything else (kind falls back to the first known kind when the
 *  payload didn't carry one). Structural param so there's no import cycle with blueprintSkills. */
export function skillFromPayload(p: { id: string; name: string; content: string; desc?: string; skillKind?: SkillKind; tools?: string[] }): SkillDef {
  return {
    id: p.id,
    name: p.name,
    kind: p.skillKind && KIND_KEYS.includes(p.skillKind) ? p.skillKind : KIND_KEYS[0],
    source: "imported",
    desc: p.desc ?? "",
    prompt: p.content,
    tools: p.tools ?? [],
    profiles: [],
    projects: [],
    enabled: true,
    pinned: false,
    invocations: 0, success: 0, avgTokensK: 0, trend: [],
  };
}

/** A sample {@link Skill} → a full editable {@link SkillDef} (enabled + global).
 *  Telemetry (invocations/success/trend/avgTokensK) starts at zero — real usage
 *  is supplied later from the skill-usage log (#406), never seeded with samples. */
function fromSample(s: Skill): SkillDef {
  return {
    id: s.id,
    name: s.name,
    kind: s.kind,
    source: s.source,
    desc: s.desc,
    // Packaged skills carry a full authored procedure in `body`; fall back to the
    // description for any skill that doesn't (the user/planner can refine it).
    prompt: s.body ?? s.desc,
    tools: [...s.tools],
    profiles: [...s.profiles],
    projects: [],
    enabled: true,
    pinned: !!s.pinned,
    packaged: true,
    invocations: 0,
    success: 0,
    avgTokensK: 0,
    trend: [],
  };
}

/** The initial skills library — the sample set, made editable. */
export function seedSkills(): SkillDef[] {
  return SKILLS.map(fromSample);
}

/** Packaged skill ids retired before the {@link SkillDef.packaged} marker existed.
 *  An already-seeded store persisted these as plain skills with no way to tell they
 *  were code-owned — list them here so {@link refreshPackagedSkills} prunes them.
 *  (Going forward, removing a packaged skill needs no entry: the `packaged` flag
 *  prunes it automatically.) */
const RETIRED_PACKAGED_SKILL_IDS = new Set([
  "scaffold-tauri-cmd", "add-screen-slice", "open-pr", "triage-failing-test",
  "bump-dep-safely", "wire-mcp-tool", "security-review", "api-docs", "rename-symbol",
]);

/**
 * Reconcile a persisted skills library with the code-owned packaged set on load
 * (mirrors blueprints' `refreshBuiltIns`, #677). The packaged skills are code-owned
 * but `skills` is persisted, so a store seeded before the library changed would keep
 * the old set forever. This:
 *   • refreshes each current packaged skill from code (preserving the user's
 *     enabled / pinned / project-scoping toggles),
 *   • prunes packaged skills dropped from the library (by the `packaged` flag or the
 *     retired-id list), and
 *   • leaves user-created / imported / catalog-added skills untouched.
 */
export function refreshPackagedSkills(persisted: SkillDef[]): SkillDef[] {
  const fresh = seedSkills();
  const seedIds = new Set(fresh.map((s) => s.id));
  const packaged = fresh.map((f) => {
    const prev = persisted.find((s) => s.id === f.id);
    return prev ? { ...f, enabled: prev.enabled, pinned: prev.pinned, projects: prev.projects } : f;
  });
  const user = persisted.filter(
    (s) => !seedIds.has(s.id) && !s.packaged && !RETIRED_PACKAGED_SKILL_IDS.has(s.id),
  );
  return [...packaged, ...user];
}

// Per-session skill resolution: which library skills apply to a project, and the
// per-session override layer (#1056 follow-up) — force a skill ON/OFF for one
// session over its inherited project resolution, with the reason label the UI shows.

import type { SkillDef } from "@/features/skills/lib/skillsModel";

/**
 * The enabled skills that apply to a session in `projectId`: a def applies when it
 * is enabled AND either global (`projects` empty) or scoped to this project. An
 * empty `projectId` (no project) yields only global defs.
 */
export function resolveSkills(all: SkillDef[], projectId: string): SkillDef[] {
  return all.filter(
    s => s.enabled && (s.projects.length === 0 || (!!projectId && s.projects.includes(projectId))),
  );
}

// ── Per-session assignment (#1056 follow-up) ────────────────────────────────────
// A session (a console pane, a fleet worker, a triage pane) INHERITS the skills that
// resolve for its project (enabled + global/project-scoped — see resolveSkills). On top
// of that the user can choose, per session, to force a skill ON (even one out of the
// session's project scope) or OFF (one it would otherwise inherit). The choice is keyed by
// the session's STABLE identity id so it survives a relaunch. The Skills UI (per-session
// surface) renders sessionSkillState per row; the launch path writes effectiveSessionSkills
// into the session's `.claude/skills/<slug>/SKILL.md`.

/** A user's per-session skill choices, layered over the inherited resolution. Both are
 *  skill ids; a skill in neither list inherits its project-resolved state. */
export interface SessionSkillOverride {
  /** Force ON for this session (incl. an enabled skill outside the session's project scope). */
  add: string[];
  /** Force OFF for this session (a skill it would otherwise inherit). */
  remove: string[];
}

/** Why a skill is on/off for a session — drives the per-session row label. */
export type SessionSkillReason =
  | "global"        // on: enabled + global (applies to every project)
  | "project"       // on: enabled + scoped to this session's project
  | "pinned"        // on (inherited) + pinned (auto-available to the fleet)
  | "group"         // on: enabled via a task group toggled onto this session/stream
  | "added"         // on: a user override turned it on for this session
  | "removed"       // off: a user override turned it off for this session
  | "out-of-scope"  // off: enabled but scoped to other projects (and not added)
  | "disabled";     // off: disabled in the library (never written to any session)

export interface SessionSkillState {
  skill: SkillDef;
  /** Whether this skill is written into the session (its `.claude/skills/<slug>`). */
  on: boolean;
  reason: SessionSkillReason;
  /** True when the effective state DIFFERS from what the session would inherit — i.e. a
   *  live user override (added / removed). */
  overridden: boolean;
}

/**
 * The effective on/off state + reason for one skill in one session, given the override and the
 * skills enabled via the session's task groups (`groupSkillIds`). `disabled` wins over everything
 * (a disabled skill is never invocable). The baseline is "inherited by project scope OR enabled by
 * a toggled-on group"; a remove/add per-skill override beats that baseline. An override that matches
 * the baseline is a no-op (`overridden: false`) so the UI never flags a redundant choice.
 */
export function sessionSkillState(
  skill: SkillDef, projectId: string, override?: SessionSkillOverride, groupSkillIds?: ReadonlySet<string>,
): SessionSkillState {
  if (!skill.enabled) return { skill, on: false, reason: "disabled", overridden: false };
  const inScope = skill.projects.length === 0 || (!!projectId && skill.projects.includes(projectId));
  const viaGroup = groupSkillIds?.has(skill.id) ?? false;
  const baseOn = inScope || viaGroup;            // `enabled` already guaranteed above
  const removed = override?.remove?.includes(skill.id) ?? false;
  const added = override?.add?.includes(skill.id) ?? false;
  const on = removed ? false : added ? true : baseOn;
  const overridden = on !== baseOn;
  let reason: SessionSkillReason;
  if (overridden) reason = on ? "added" : "removed";
  else if (on) reason = inScope ? (skill.pinned ? "pinned" : skill.projects.length === 0 ? "global" : "project") : "group";
  else reason = "out-of-scope";
  return { skill, on, reason, overridden };
}

/** The skills written into a session: every library skill whose {@link sessionSkillState} is `on`
 *  for this project + override + toggled-on groups. With no override/groups this equals
 *  {@link resolveSkills}. */
export function effectiveSessionSkills(
  all: SkillDef[], projectId: string, override?: SessionSkillOverride, groupSkillIds?: ReadonlySet<string>,
): SkillDef[] {
  return all.filter(s => sessionSkillState(s, projectId, override, groupSkillIds).on);
}

/** Layer a user choice onto a session's override (pure). "on" forces the skill on, "off"
 *  forces it off, "inherit" clears any override for it. Returns a fresh override; the caller
 *  drops it from the map when both lists are empty (back to pure inheritance). */
export function applySessionSkillChoice(
  override: SessionSkillOverride | undefined, skillId: string, choice: "on" | "off" | "inherit",
): SessionSkillOverride {
  const add = new Set(override?.add ?? []);
  const remove = new Set(override?.remove ?? []);
  add.delete(skillId);
  remove.delete(skillId);
  if (choice === "on") add.add(skillId);
  else if (choice === "off") remove.add(skillId);
  return { add: [...add], remove: [...remove] };
}

import { useEffect, useState } from "react";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { Box } from "@/shared/ui/layout/Box";
import { useAppStore } from "@/store";
import { parseSkillLog, aggregateSkillTelemetry, skillStatusKpis, type SkillStats } from "@/features/skills/lib/skillTelemetry";

/**
 * Live Skills KPIs for the app status bar (Skills page) — replaces the old hardcoded
 * `SKILL_KPIS` mock. Reads the real skill-usage telemetry (`bsc logs tail skill`, the same source
 * the Skills screen uses) plus the live library size.
 */
export function SkillsStatus() {
  const skillCount = useAppStore((s) => s.skills.length);
  const [stats, setStats] = useState<Record<string, SkillStats>>({});

  useEffect(() => {
    let cancelled = false;
    logsTail("skill", 4000)
      .then((lines) => {
        if (!cancelled) setStats(aggregateSkillTelemetry(parseSkillLog((lines ?? []).join("\n")), new Date()));
      });
    return () => { cancelled = true; };
  }, []);

  const { loaded, invToday, worst } = skillStatusKpis(skillCount, stats);
  return (
    <>
      <Box as="span" className="s"><i /> {loaded} {loaded === 1 ? "skill" : "skills"} loaded</Box>
      <Box as="span" className="s"><i /> {invToday} {invToday === 1 ? "invocation" : "invocations"} today</Box>
      {worst && <Box as="span" className="s"><i className="warn" /> {worst.skill} {worst.rate}%</Box>}
    </>
  );
}

// Skills feature store slice (#1309) — extracted from the former `session` grab-bag slice. Owns the
// skill library, the resolved per-pane set, per-session overrides, and task groups. Composed into
// the single app store by store/index.ts.
//
// Source of truth is the GLOBAL skills.db (#1338 ph2): this slice is a write-through cache. On boot
// `hydrateSkills` loads the library through the `bsc skill` bridge (#2142) and reconciles the
// code-owned packaged set; every library mutation below pushes through to the bridge so the desktop
// UI, the planner, and every live `bsc skill` session see ONE shared library. Per-session toggles
// (`sessionSkillOverrides` / `sessionSkillGroups`) are pane-local and stay store-only — they are not
// part of the global library. The persisted copy is just a fast first-paint cache; hydrate reconciles.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import type { SkillPayload } from "@/features/planner/blueprints/blueprintSkills";
import {
  seedSkills, refreshPackagedSkills, skillFromPayload, applySessionSkillChoice, skillSlug, skillContentKey,
  type SkillDef, type SessionSkillOverride, type SkillGroup,
} from "@/features/skills/lib/skills";
import { loadLibrary, pushSkill, dropSkill, pushGroup, dropGroup } from "@/features/skills/lib/skillBridge";
import { deleteMapEntry } from "@/store/updateHelpers";

export interface SkillsSlice {
  // Skills — reusable capability bundles (prompt + bundled tools + profile guardrails) the fleet can
  // invoke, each scoped via its `projects` ([] = global). Written into a launched session's
  // .claude/skills/<slug>/SKILL.md. Seeded from the sample library; persisted as a cache. (#404)
  skills: SkillDef[];
  /** Hydrate the library from the global skills.db on boot (#1338): load + reconcile the packaged
   *  set, then seed/refresh the db with the reconciled set. No-op (keeps the seeded set) when the
   *  bridge is unreachable — tests, the web shell, or an old binary. */
  hydrateSkills: () => Promise<void>;
  /** Lightweight re-read of the global skills.db into the cache (#1419): like {@link hydrateSkills}
   *  but WITHOUT the boot-time push-back of the whole set — cheap enough to poll while the planner
   *  runs, so skills the planner authors via `bsc-skill add` (and their session-group membership)
   *  appear live. No-op when the bridge is unreachable. */
  refreshSkills: () => Promise<void>;
  /** Reconstitute a shared blueprint's embedded skills into the library (#897 Phase 5b). */
  installBundledSkills: (payloads: SkillPayload[]) => void;
  addSkill: (def: Omit<SkillDef, "id">) => string;
  updateSkill: (id: string, patch: Partial<SkillDef>) => void;
  removeSkill: (id: string) => void;
  toggleSkill: (id: string) => void;
  toggleSkillPin: (id: string) => void;
  setSkillProjects: (id: string, projects: string[]) => void;
  /** Upsert planner-authored skills (skills.json), by id then name-slug, refining in place. */
  upsertSkills: (defs: Array<Omit<SkillDef, "id"> & { id?: string }>) => void;
  // Resolved per-pane skills (transient): set at session creation, read by TerminalView before
  // launch. Computed via effectiveSessionSkills so it already reflects overrides + groups.
  paneSkills: Record<string, SkillDef[]>;
  // Per-session skill choices, keyed by the session's STABLE identity id; persisted (#1056).
  sessionSkillOverrides: Record<string, SessionSkillOverride>;
  setSessionSkill: (sessionKey: string, skillId: string, choice: "on" | "off" | "inherit") => void;
  /** Drop ALL per-session overrides AND group toggles for a session — back to pure inheritance. */
  resetSessionSkills: (sessionKey: string) => void;
  // Task groups (#skills-groups) — named, reusable skill bundles toggled as one. Persisted as a cache.
  skillGroups: SkillGroup[];
  addSkillGroup: (name: string, hue?: string) => string;
  updateSkillGroup: (id: string, patch: Partial<Omit<SkillGroup, "id">>) => void;
  removeSkillGroup: (id: string) => void;
  toggleSkillGroupMember: (groupId: string, skillId: string) => void;
  upsertSkillGroups: (groups: Array<Omit<SkillGroup, "id"> & { id?: string }>) => void;
  /** Ensure the per-project planning session group exists with a fixed `id` and the given `name`
   *  (#1419): creates it (empty) if absent, else just renames it when the project title changed —
   *  never clobbering the members the planner has paired into it. */
  ensureSessionGroup: (id: string, name: string, hue?: string) => void;
  // Per-session enabled groups, keyed by the session's stable identity id; persisted.
  sessionSkillGroups: Record<string, string[]>;
  setSessionSkillGroup: (sessionKey: string, groupId: string, on: boolean) => void;
}

export const createSkillsSlice: StateCreator<AppStore, [], [], SkillsSlice> = (set, get) => ({
  skills: seedSkills(),
  hydrateSkills: async () => {
    const lib = await loadLibrary();
    if (!lib) return; // bridge unreachable — keep the seeded in-memory set
    // Reconcile the code-owned packaged skills over whatever the db held (first run: db empty →
    // just the packaged set; later: packaged refreshed from code + the user's skills preserved).
    const skills = refreshPackagedSkills(lib.skills);
    set({ skills, skillGroups: lib.groups });
    // Push ONLY skills the db is missing or whose authored content drifted (a packaged code update),
    // mirroring hydrateOrgs (#3672). A normal boot re-writes NOTHING — this used to unconditionally
    // re-push all ~40 packaged skills, a `bsc skill add` subprocess-spawn burst that jammed the backend
    // every boot. User-state edits (enabled/pinned/projects) still write through via their own actions.
    const dbKeys = new Map(lib.skills.map((s) => [s.id, skillContentKey(s)]));
    for (const s of skills) {
      const prior = dbKeys.get(s.id);
      if (prior === undefined || prior !== skillContentKey(s)) void pushSkill(s);
    }
  },
  refreshSkills: async () => {
    const lib = await loadLibrary();
    if (!lib) return; // bridge unreachable — keep the current cache
    // Re-read only; no push-back (that's hydrate's job). The db is the source of truth, and every
    // local edit already wrote through, so overwriting the cache from it can't lose anything.
    set({ skills: refreshPackagedSkills(lib.skills), skillGroups: lib.groups });
  },
  addSkill: (def) => {
    const id = `skill_${Math.random().toString(36).slice(2, 8)}`;
    const full = { ...def, id } as SkillDef;
    set((s) => ({ skills: [...s.skills, full] }));
    void pushSkill(full);
    return id;
  },
  installBundledSkills: (payloads) =>
    set((s) => {
      const haveSkill = new Set(s.skills.map((x) => x.id));
      const newSkills: SkillDef[] = [];
      for (const p of payloads) {
        if (haveSkill.has(p.id) || !p.id) continue;
        haveSkill.add(p.id);
        const def = skillFromPayload(p);
        newSkills.push(def);
        void pushSkill(def);
      }
      if (newSkills.length === 0) return {};
      return { skills: [...s.skills, ...newSkills] };
    }),
  updateSkill: (id, patch) => {
    set((s) => ({ skills: s.skills.map((sk) => (sk.id === id ? { ...sk, ...patch } : sk)) }));
    const updated = get().skills.find((sk) => sk.id === id);
    if (updated) void pushSkill(updated);
  },
  removeSkill: (id) => {
    set((s) => ({ skills: s.skills.filter((sk) => sk.id !== id) }));
    void dropSkill(id);
  },
  toggleSkill: (id) => {
    set((s) => ({ skills: s.skills.map((sk) => (sk.id === id ? { ...sk, enabled: !sk.enabled } : sk)) }));
    const updated = get().skills.find((sk) => sk.id === id);
    if (updated) void pushSkill(updated);
  },
  toggleSkillPin: (id) => {
    set((s) => ({ skills: s.skills.map((sk) => (sk.id === id ? { ...sk, pinned: !sk.pinned } : sk)) }));
    const updated = get().skills.find((sk) => sk.id === id);
    if (updated) void pushSkill(updated);
  },
  setSkillProjects: (id, projects) => {
    set((s) => ({ skills: s.skills.map((sk) => (sk.id === id ? { ...sk, projects } : sk)) }));
    const updated = get().skills.find((sk) => sk.id === id);
    if (updated) void pushSkill(updated);
  },
  upsertSkills: (defs) => {
    set((s) => {
      const skills = [...s.skills];
      for (const def of defs) {
        const slug = skillSlug(def.name);
        const idx = skills.findIndex(
          (sk) => (def.id && sk.id === def.id) || skillSlug(sk.name) === slug,
        );
        if (idx >= 0) {
          const rest = { ...def };
          delete rest.id;
          skills[idx] = { ...skills[idx], ...rest };
        } else {
          skills.push({ ...def, id: def.id ?? `skill_${Math.random().toString(36).slice(2, 8)}` });
        }
      }
      return { skills };
    });
    // Push the resolved (post-merge) rows for the affected names so the db mirrors the store.
    const bySlug = new Map(get().skills.map((sk) => [skillSlug(sk.name), sk] as const));
    for (const def of defs) {
      const merged = bySlug.get(skillSlug(def.name));
      if (merged) void pushSkill(merged);
    }
  },
  paneSkills: {},

  sessionSkillOverrides: {},
  setSessionSkill: (sessionKey, skillId, choice) =>
    set((s) => {
      const next = applySessionSkillChoice(s.sessionSkillOverrides[sessionKey], skillId, choice);
      const map = { ...s.sessionSkillOverrides };
      if (next.add.length === 0 && next.remove.length === 0) delete map[sessionKey];
      else map[sessionKey] = next;
      return { sessionSkillOverrides: map };
    }),
  resetSessionSkills: (sessionKey) =>
    set((s) => {
      const hadOverride = !!s.sessionSkillOverrides[sessionKey];
      const hadGroups = !!s.sessionSkillGroups[sessionKey];
      if (!hadOverride && !hadGroups) return {};
      return {
        sessionSkillOverrides: deleteMapEntry(s.sessionSkillOverrides, sessionKey),
        sessionSkillGroups: deleteMapEntry(s.sessionSkillGroups, sessionKey),
      };
    }),

  // ── Task groups (#skills-groups) ──────────────────────────────────────
  skillGroups: [],
  addSkillGroup: (name, hue) => {
    const id = `grp_${Math.random().toString(36).slice(2, 8)}`;
    const group: SkillGroup = { id, name, hue: hue ?? "var(--accent)", skillIds: [] };
    set((s) => ({ skillGroups: [...s.skillGroups, group] }));
    void pushGroup(group);
    return id;
  },
  updateSkillGroup: (id, patch) => {
    set((s) => ({ skillGroups: s.skillGroups.map((g) => (g.id === id ? { ...g, ...patch } : g)) }));
    const updated = get().skillGroups.find((g) => g.id === id);
    if (updated) void pushGroup(updated);
  },
  removeSkillGroup: (id) => {
    set((s) => {
      const sessionSkillGroups: Record<string, string[]> = {};
      for (const [k, ids] of Object.entries(s.sessionSkillGroups)) {
        const kept = ids.filter((g) => g !== id);
        if (kept.length) sessionSkillGroups[k] = kept;
      }
      return { skillGroups: s.skillGroups.filter((g) => g.id !== id), sessionSkillGroups };
    });
    void dropGroup(id);
  },
  ensureSessionGroup: (id, name, hue) => {
    // Lazy session group (#1616): never PRE-CREATE. `bsc-skill add --group <id>` creates the group on
    // the planner's FIRST authored skill (placeholder name = its id, empty hue); here we only ADOPT it
    // once it exists — rename the placeholder to the project name (and on later title changes) and fill
    // the empty placeholder hue, never clobbering members or a user-set color. A project that authors
    // no skills never gets an empty group written to skills.db.
    const existing = get().skillGroups.find((g) => g.id === id);
    if (!existing) return;
    const patch: Partial<Omit<SkillGroup, "id">> = {};
    if (name && existing.name !== name) patch.name = name;
    if (!existing.hue) patch.hue = hue ?? "var(--violet)";
    if (Object.keys(patch).length > 0) get().updateSkillGroup(id, patch);
  },
  toggleSkillGroupMember: (groupId, skillId) => {
    set((s) => ({
      skillGroups: s.skillGroups.map((g) => {
        if (g.id !== groupId) return g;
        const has = g.skillIds.includes(skillId);
        return { ...g, skillIds: has ? g.skillIds.filter((x) => x !== skillId) : [...g.skillIds, skillId] };
      }),
    }));
    const updated = get().skillGroups.find((g) => g.id === groupId);
    if (updated) void pushGroup(updated);
  },
  upsertSkillGroups: (groups) => {
    set((s) => {
      const next = [...s.skillGroups];
      for (const g of groups) {
        const slug = skillSlug(g.name);
        const idx = next.findIndex((x) => (g.id && x.id === g.id) || skillSlug(x.name) === slug);
        if (idx >= 0) {
          const rest = { ...g }; delete rest.id;
          next[idx] = { ...next[idx], ...rest };
        } else {
          next.push({ ...g, id: g.id ?? `grp_${Math.random().toString(36).slice(2, 8)}` });
        }
      }
      return { skillGroups: next };
    });
    const bySlug = new Map(get().skillGroups.map((g) => [skillSlug(g.name), g] as const));
    for (const g of groups) {
      const merged = bySlug.get(skillSlug(g.name));
      if (merged) void pushGroup(merged);
    }
  },
  sessionSkillGroups: {},
  setSessionSkillGroup: (sessionKey, groupId, on) =>
    set((s) => {
      const cur = s.sessionSkillGroups[sessionKey] ?? [];
      const next = on ? (cur.includes(groupId) ? cur : [...cur, groupId]) : cur.filter((g) => g !== groupId);
      const map = { ...s.sessionSkillGroups };
      if (next.length) map[sessionKey] = next;
      else delete map[sessionKey];
      return { sessionSkillGroups: map };
    }),
});

// Per-project base-snapshot persistence for the planner-sync reconcile loop.
//
// The base snapshot is the last manifest the desktop transmitted to mobile.
// On reconnect, the desktop diffs its current manifest against the base snapshot
// to decide which local changes are "new" (and should be announced) vs. already
// known. Stored in localStorage keyed by stable projectId.

import type { PlanManifest } from "@/features/planner/lib/plannerCore/types";

function storageKey(projectId: string): string {
  return `planner-sync:snapshot:${projectId}`;
}

/** Load the persisted base snapshot for a project. Returns null if none exists. */
export function loadSnapshot(projectId: string): PlanManifest | null {
  if (typeof localStorage === "undefined") return null;
  const raw = localStorage.getItem(storageKey(projectId));
  if (!raw) return null;
  try {
    const v = JSON.parse(raw) as unknown;
    if (!v || typeof v !== "object") return null;
    const o = v as Record<string, unknown>;
    if (typeof o.projectId !== "string" || !o.projectId) return null;
    if (!o.files || typeof o.files !== "object" || Array.isArray(o.files)) return null;
    return v as PlanManifest;
  } catch { return null; }
}

/** Persist the base snapshot for a project. */
export function saveSnapshot(manifest: PlanManifest): void {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(storageKey(manifest.projectId), JSON.stringify(manifest));
}

/** Remove the base snapshot (e.g. after a fresh full-sync or project deletion). */
export function clearSnapshot(projectId: string): void {
  if (typeof localStorage === "undefined") return;
  localStorage.removeItem(storageKey(projectId));
}

// The seeded array-sort proof (#3177, epic #3171) — the in-app example that proves the whole
// visualization seam end to end: a step-yielding generator → the streaming <TracePlayer> (#3176) →
// the <ArrayView> renderer (#3178) → `data-op` states → the designed compare/swap/set animations.
//
// GENERATOR-AS-SOURCE (#3171 decision 3): the algorithm's implementation IS the trace. `sortSteps`
// mutates its array in place and yields a snapshot `ArrayFrame` per step; the plain `sort` DRAINS the
// same generator to order the array (one source of truth), and the visualizer animates the yields.
//
// PURITY / REPLAY CONTRACT: `sortSteps` MUTATES the array it is handed (that is what lets `sort` drain
// it). The streaming engine (`makeTraceStream`) requires a factory that yields the IDENTICAL sequence on
// every call — it re-invokes the factory for deterministic scrub/replay. So a replaying call site must
// hand `sortSteps` a FRESH COPY of its fixed input, never a shared array. The viz registry does exactly
// that (`() => sortSteps([...SORT_MOCK])`), keeping the module-level {@link SORT_MOCK} immutable.

import type { ArrayFrame } from "@/features/algorithms/lib/trace";

/** A small, watchable mock input for the sort proof — short enough to teach, unsorted enough that the
 *  compare/swap animations have visible work to do. Treated as IMMUTABLE: hand `sortSteps` a copy of it
 *  (the generator mutates in place), or replay would start from an already-sorted array. */
export const SORT_MOCK: readonly number[] = [5, 2, 9, 1, 6, 3, 8, 4, 7];

/**
 * Insertion sort authored as a step-yielding generator (#3171 generator-as-source). MUTATES `a` in place
 * and yields one snapshot {@link ArrayFrame} per step:
 * - a `compare` verb on the two neighbours before each comparison,
 * - a `swap` verb on the pair after each out-of-order exchange,
 * - the `i` / `j` cursors so the renderer can draw the outer/inner pointers,
 * - and a terminal frame that `mark`s every cell `sorted`.
 *
 * The yielded sequence is non-worsening by inversion count and terminates fully sorted — each `swap`
 * removes exactly one inversion, every other frame preserves the order — which is what the `sortSteps`
 * test asserts. Snapshots are fresh copies (`[...a]`) so each frame is an immutable view of that step.
 */
export function* sortSteps(a: number[]): Generator<ArrayFrame> {
  yield { structure: "array", data: [...a] };
  for (let i = 1; i < a.length; i++) {
    let j = i;
    while (j > 0) {
      // The transient `compare` verb on the two neighbours (j-1, j).
      yield { structure: "array", data: [...a], ops: [{ op: "compare", at: [j - 1, j] }], cursors: { i, j } };
      if ((a[j - 1] as number) <= (a[j] as number)) break;
      // Out of order → exchange, then emit the `swap` verb on the same pair.
      const t = a[j - 1];
      a[j - 1] = a[j];
      a[j] = t;
      yield { structure: "array", data: [...a], ops: [{ op: "swap", at: [j - 1, j] }], cursors: { i, j } };
      j--;
    }
  }
  // Terminal frame: every cell has reached its sorted position (a durable `sorted` mark on each).
  yield {
    structure: "array",
    data: [...a],
    ops: a.map((_, k) => ({ op: "mark", at: k, as: "sorted" as const })),
  };
}

/**
 * Parse the fullscreen custom-state field (#3199) into a number array — the "provide your own state"
 * input for the sort visualization. Accepts values separated by commas and/or whitespace. Throws a
 * helpful `Error` (message shown under the field) on empty input, a non-numeric token, or an
 * unwatchably-long list — so the fullscreen view surfaces the problem and keeps the last good run.
 */
export function parseSortInput(text: string): number[] {
  const tokens = text.split(/[\s,]+/).map((t) => t.trim()).filter((t) => t.length > 0);
  if (tokens.length === 0) throw new Error("Enter at least one number, e.g. 5, 2, 9, 1");
  const nums = tokens.map((t) => {
    const n = Number(t);
    if (!Number.isFinite(n)) throw new Error(`"${t}" is not a number`);
    return n;
  });
  if (nums.length > 40) throw new Error("Keep it under 40 values so the animation stays watchable");
  return nums;
}

/**
 * Sort `input` ascending by DRAINING {@link sortSteps} (generator-as-source, #3171) — the same generator
 * that animates the visualization also computes the result, so there is one source of truth. PURE:
 * operates on a copy and never mutates `input`.
 */
export const sort = (input: readonly number[]): number[] => {
  const a = [...input];
  const steps = sortSteps(a);
  // Draining the generator runs every step; `sortSteps` mutates `a` in place as it goes.
  while (!steps.next().done) {
    /* drain */
  }
  return a;
};

