implementations.code:
// The sort family as REAL trace-programs (#3216, epic #3215) — each is the genuine algorithm written
// against a TracedArray, so its animation is DERIVED from its own execution and looks distinct: bubble's
// adjacent swaps, insertion's shifting prefix, quick's partitions, heap's sift-downs, merge's writes.
// There are no hand-drawn frames — the tracer records what the code does.
//
// Keyed by the algorithm's BASE NAME (`merge-sort`, not `merge-sort.rs`), so a Rust reference impl and any
// TypeScript twin share one visualization (the JS trace-program is the visualizable form; the Rust stays
// shown in the code panel). `programForImpl` normalizes an impl id to that key.
import { TracedArray } from "@/features/algorithms/lib/tracer";
import { SORT_MOCK } from "@/features/algorithms/viz/examples/sort";

/** A visualizable algorithm — its real logic over a {@link TracedArray} + the default input to seed it. */
export interface AlgoProgram {
  /** The algorithm, written against the traced structure (its ops become the animation). */
  run: (a: TracedArray) => void;
  /** The default input the inline preview + "your input" field seed from. */
  defaultInput: readonly number[];
}

// ── the sort family (each the real algorithm) ──

/** Bubble sort — repeatedly swap adjacent out-of-order pairs; stop early once a pass makes no swap. */
export function bubbleSort(a: TracedArray): void {
  for (let i = 0; i < a.length; i++) {
    let swapped = false;
    for (let j = 0; j < a.length - i - 1; j++) {
      a.cursor("j", j);
      if (a.compare(j, j + 1) > 0) {
        a.swap(j, j + 1);
        swapped = true;
      }
    }
    if (!swapped) break;
  }
  a.markSorted();
}

/** Insertion sort — grow a sorted prefix, swapping each new element down into place. */
export function insertionSort(a: TracedArray): void {
  for (let i = 1; i < a.length; i++) {
    a.cursor("i", i);
    let j = i;
    while (j > 0 && a.compare(j - 1, j) > 0) {
      a.swap(j - 1, j);
      j--;
    }
  }
  a.markSorted();
}

/** Quick sort — Lomuto partition around the last element, recurse each side. */
export function quickSort(a: TracedArray): void {
  const part = (lo: number, hi: number): void => {
    if (lo >= hi) return;
    a.mark(hi, "pivot"); // the pivot for this partition
    let i = lo;
    for (let j = lo; j < hi; j++) {
      a.cursor("j", j);
      if (a.compare(j, hi) < 0) {
        a.swap(i, j);
        i++;
      }
    }
    a.swap(i, hi); // drop the pivot into its final slot
    part(lo, i - 1);
    part(i + 1, hi);
  };
  part(0, a.length - 1);
  a.markSorted();
}

/** Heap sort — build a max-heap in place (sift-down), then swap the root to the end and re-sift. */
export function heapSort(a: TracedArray): void {
  const n = a.length;
  const siftDown = (start: number, end: number): void => {
    let root = start;
    while (root * 2 + 1 <= end) {
      let child = root * 2 + 1;
      if (child + 1 <= end && a.compare(child, child + 1) < 0) child += 1; // larger child
      if (a.compare(root, child) < 0) {
        a.swap(root, child);
        root = child;
      } else return;
    }
  };
  for (let start = Math.floor((n - 2) / 2); start >= 0; start--) siftDown(start, n - 1);
  for (let end = n - 1; end > 0; end--) {
    a.swap(0, end); // largest to the end
    siftDown(0, end - 1);
  }
  a.markSorted();
}

/** Merge sort — bottom-up: merge adjacent runs of growing width, writing the merged result back with
 *  `set` (so the animation shows the merge writes, distinct from the swap-based sorts). */
export function mergeSort(a: TracedArray): void {
  const n = a.length;
  for (let width = 1; width < n; width *= 2) {
    for (let lo = 0; lo < n; lo += 2 * width) {
      const mid = Math.min(lo + width, n);
      const hi = Math.min(lo + 2 * width, n);
      // Snapshot the two runs (silent reads), then write the merged order back into place.
      const left: number[] = [];
      const right: number[] = [];
      for (let k = lo; k < mid; k++) left.push(a.get(k));
      for (let k = mid; k < hi; k++) right.push(a.get(k));
      let i = 0;
      let j = 0;
      let k = lo;
      while (i < left.length && j < right.length) {
        if (left[i] <= right[j]) a.set(k++, left[i++]);
        else a.set(k++, right[j++]);
      }
      while (i < left.length) a.set(k++, left[i++]);
      while (j < right.length) a.set(k++, right[j++]);
    }
  }
  a.markSorted();
}

/** The visualizable algorithms, keyed by BASE NAME. The generic `sort` (the TypeScript kit's insertion
 *  sort) maps to insertion. Grows as more algorithms are authored as trace-programs (or, #3215 slice B,
 *  loaded from the impl's stored code). */
export const TRACE_PROGRAMS: Record<string, AlgoProgram> = {
  "bubble-sort": { run: bubbleSort, defaultInput: SORT_MOCK },
  "insertion-sort": { run: insertionSort, defaultInput: SORT_MOCK },
  "quick-sort": { run: quickSort, defaultInput: SORT_MOCK },
  "heap-sort": { run: heapSort, defaultInput: SORT_MOCK },
  "merge-sort": { run: mergeSort, defaultInput: SORT_MOCK },
  sort: { run: insertionSort, defaultInput: SORT_MOCK },
};

/** Normalize an impl id/name to its base-algorithm key — strip the extension, lowercase, and unify
 *  separators — so `merge-sort.rs`, `merge_sort`, and `merge-sort.ts` all resolve to `merge-sort`. */
export function programKey(impl: { id: string; name?: string }): string {
  return impl.id
    .replace(/\.[a-z0-9]+$/i, "") // drop the extension (".rs"/".ts")
    .toLowerCase()
    .replace(/[_\s]+/g, "-");
}

/** The trace-program for an implementation, or `undefined` when the algorithm has none yet (so it simply
 *  shows no animation — never a wrong category one). */
export function programForImpl(impl: { id: string; name?: string }): AlgoProgram | undefined {
  return TRACE_PROGRAMS[programKey(impl)];
}

// The Sounds store bridge (#3080) — reads/writes the durable `bsc-sound` store through the generic
// `bsc` command (#2114), so the desktop Sounds library and a live session's shell share one store. A
// GLOBAL store (no per-project key), exactly like the persona bridge.
import { bscJson, bscRun, bscWrite } from "@/shared/lib/core/bsc";
import type { SoundKit } from "@/features/sounds/lib/soundDescriptor";

/** Every kit from the durable store (full objects), or `[]` if the store/CLI is unavailable. */
export async function loadKits(): Promise<SoundKit[]> {
  const rows = await bscJson<SoundKit[]>(null, ["sound", "list", "--full"], []);
  return Array.isArray(rows) ? rows : [];
}

/** Upsert a kit into the durable store (verbatim JSON on stdin, keyed by its `id`). */
export async function pushKit(kit: SoundKit): Promise<void> {
  await bscWrite(null, ["sound", "set"], kit);
}

/** Delete a kit from the durable store (no-op if absent). */
export async function dropKit(id: string): Promise<void> {
  await bscRun(null, ["sound", "remove", id]);
}

// The Sounds pillar's data model (#3072, epic #3071) — a sound is SYNTHESIZED from a descriptor, not a
// binary file, so it's diffable, seedable, and live-playable (Web Audio), exactly like a component's
// srcText or an algorithm's concept-IS-impl. The model is a composition graph mirroring the sibling
// pillars: Primitive → Voice → Cue.
//
//   Primitive — the base sound SOURCE (an oscillator or noise). The graph's Fundamentals band.
//   Voice     — a playable PATCH built on ONE primitive: pitch (+ optional sweep), an ADSR envelope,
//               an optional filter, and a peak gain. The Composables band; `primitive` is a composes edge.
//   Cue       — a UI-mapped SOUND: one or more voices LAYERED/SEQUENCED (each at an offset). The
//               "components" of this pillar; `layers[].voice` are composes edges.
//   SoundKit  — a cohesive named set a project adopts wholesale (its primitives + voices + cues).
//
// This module is PURE (no Web Audio, no React) — the synth compiler (`synth.ts`) turns a Cue into a flat
// schedule, and only the thin `playCue` touches the browser audio graph.

/** Oscillator wave shapes — the Web Audio `OscillatorNode` types. */
export type Waveform = "sine" | "square" | "sawtooth" | "triangle";

/** Where a cue sits in the library — drives the rail grouping (and, later, the graph swimlanes). */
export type SoundCategory = "ui" | "notify" | "transition" | "ambient" | "musical";

export const SOUND_CATEGORIES: readonly SoundCategory[] = ["ui", "notify", "transition", "ambient", "musical"];

/** Human labels for the categories (rail headers + inspector). */
export const CATEGORY_LABEL: Record<SoundCategory, string> = {
  ui: "UI feedback",
  notify: "Notifications",
  transition: "Transitions",
  ambient: "Ambient",
  musical: "Musical",
};

/** An ADSR-style one-shot envelope. Times in SECONDS; `sustain` is a 0..1 level (no sustain-hold time —
 *  a cue is one-shot, so release begins right after decay). A voice's duration = attack + decay + release. */
export interface Envelope {
  attack: number;
  decay: number;
  /** Level (0..1) held at the decay→release junction. */
  sustain: number;
  release: number;
}

/** A base sound source. `waveform` applies to `kind: "osc"`; `noise` is white noise (waveform ignored). */
export interface Primitive {
  id: string;
  name: string;
  kind: "osc" | "noise";
  waveform?: Waveform;
}

/** A tone filter applied to a voice. */
export interface VoiceFilter {
  type: "lowpass" | "highpass" | "bandpass";
  /** Cutoff / center frequency in Hz. */
  cutoff: number;
}

/** A playable patch built on exactly one primitive. */
export interface Voice {
  id: string;
  name: string;
  /** Primitive.id this voice is built on (the `composes` edge). */
  primitive: string;
  /** Base frequency in Hz (ignored for a noise primitive). */
  freq: number;
  /** Optional end frequency — the voice GLIDES freq→pitchTo over its life (a sweep/zap). */
  pitchTo?: number;
  /** Fine detune in cents. */
  detune?: number;
  env: Envelope;
  filter?: VoiceFilter;
  /** Peak gain, 0..1. */
  gain: number;
}

/** One voice within a cue, started at `at` seconds from the cue's start (0 = together = a layer). */
export interface CueLayer {
  /** Voice.id (the `composes` edge). */
  voice: string;
  at: number;
}

/** A UI-mapped sound: layered/sequenced voices. */
export interface Cue {
  id: string;
  name: string;
  category: SoundCategory;
  layers: CueLayer[];
}

/** A cohesive named library of sounds a project adopts wholesale. */
export interface SoundKit {
  id: string;
  name: string;
  primitives: Primitive[];
  voices: Voice[];
  cues: Cue[];
}

/**
 * Dangling-reference check for a kit — the dependency-integrity guard behind the playable UI (and, later,
 * a `bsc sound doctor`). Returns a human-readable problem per broken `composes` edge (a voice on a missing
 * primitive, a cue layer on a missing voice) or an empty layer; empty ⇒ the kit compiles + plays cleanly.
 */
export function validateKit(kit: SoundKit): string[] {
  const problems: string[] = [];
  const primIds = new Set(kit.primitives.map((p) => p.id));
  const voiceIds = new Set(kit.voices.map((v) => v.id));
  for (const v of kit.voices) {
    if (!primIds.has(v.primitive)) problems.push(`voice "${v.id}" composes a missing primitive "${v.primitive}"`);
  }
  for (const c of kit.cues) {
    if (c.layers.length === 0) problems.push(`cue "${c.id}" has no layers`);
    for (const l of c.layers) {
      if (!voiceIds.has(l.voice)) problems.push(`cue "${c.id}" layers a missing voice "${l.voice}"`);
    }
  }
  return problems;
}

// The Sounds composition graph (#3077, Phase 2) — turns a SoundKit into a node/edge graph laid out in
// tier COLUMNS, the same shape as the Algorithms kit graph (`layoutKitGraph`) and the Designs graph:
// Primitives at the base (left), Voices next, Cues last (right), wired by `composes` edges
// (Cue→Voice→Primitive). Pure + deterministic — the canvas/rail/inspector all read this.
import type { Cue, SoundCategory, SoundKit } from "@/features/sounds/lib/soundDescriptor";

export type SoundNodeKind = "primitive" | "voice" | "cue";

/** A graph node. `id` is namespaced by kind (`p:`/`v:`/`c:`) so a primitive + cue sharing a raw id never
 *  collide; `refId` is the original id for kit lookups + playback. */
export interface SoundNode {
  id: string;
  kind: SoundNodeKind;
  label: string;
  refId: string;
  /** Cues only — drives the node tint + rail grouping. */
  category?: SoundCategory;
}

/** A `composes` edge, from the composer to the composed (Cue→Voice, Voice→Primitive). */
export interface SoundEdge { id: string; from: string; to: string }

export interface SoundGraph { nodes: SoundNode[]; edges: SoundEdge[] }

export interface NodePos { x: number; y: number }
export interface SoundLayout {
  pos: Map<string, NodePos>;
  world: { w: number; h: number };
  bounds: { x: number; y: number; w: number; h: number };
}

/** Node box size (world px) — shared by the layout and the canvas card (matches the Algorithms graph). */
export const NODE_W = 172;
export const NODE_H = 58;
const COL_PITCH = NODE_W + 208;
const ROW_PITCH = NODE_H + 22;
const PAD = 48;

/** Namespaced node ids — kept in one place so build + edge wiring agree. */
export const primNodeId = (id: string) => `p:${id}`;
export const voiceNodeId = (id: string) => `v:${id}`;
export const cueNodeId = (id: string) => `c:${id}`;

/** Column tier: primitives are the base (0), voices 1, cues 2 — so the graph flows base→product, L→R. */
export function nodeTier(kind: SoundNodeKind): number {
  return kind === "primitive" ? 0 : kind === "voice" ? 1 : 2;
}

/** Build the composition graph for a kit — every primitive/voice/cue a node, every `composes` an edge. */
export function buildSoundGraph(kit: SoundKit): SoundGraph {
  const nodes: SoundNode[] = [
    ...kit.primitives.map((p): SoundNode => ({ id: primNodeId(p.id), kind: "primitive", label: p.name, refId: p.id })),
    ...kit.voices.map((v): SoundNode => ({ id: voiceNodeId(v.id), kind: "voice", label: v.name, refId: v.id })),
    ...kit.cues.map((c): SoundNode => ({ id: cueNodeId(c.id), kind: "cue", label: c.name, refId: c.id, category: c.category })),
  ];
  const edges: SoundEdge[] = [];
  const seen = new Set<string>();
  const add = (from: string, to: string) => {
    const id = `${from}~${to}`;
    if (seen.has(id)) return; // a cue layering the same voice twice draws one edge
    seen.add(id);
    edges.push({ id, from, to });
  };
  for (const v of kit.voices) add(voiceNodeId(v.id), primNodeId(v.primitive));
  for (const c of kit.cues) for (const l of c.layers) add(cueNodeId(c.id), voiceNodeId(l.voice));
  return { nodes, edges };
}

/** Lay the graph out in tier columns (primitives→voices→cues, L→R), stacked in seed order within a
 *  column. Keyed by node id so the shared canvas/viewport draw it. Pure + deterministic. */
export function layoutSoundGraph(graph: SoundGraph): SoundLayout {
  const pos = new Map<string, NodePos>();
  const rowByCol = [0, 0, 0];
  for (const n of graph.nodes) {
    const col = nodeTier(n.kind);
    const row = rowByCol[col]++;
    pos.set(n.id, { x: PAD + col * COL_PITCH, y: PAD + row * ROW_PITCH });
  }
  const maxRows = Math.max(0, ...rowByCol);
  const world = {
    w: PAD * 2 + 2 * COL_PITCH + NODE_W,
    h: PAD * 2 + Math.max(maxRows - 1, 0) * ROW_PITCH + NODE_H,
  };
  const bounds = { x: PAD, y: PAD, w: world.w - PAD * 2, h: world.h - PAD * 2 };
  return { pos, world, bounds };
}

/**
 * The cue to PLAY for a node: a cue node plays its cue; a voice node plays an ephemeral single-layer cue
 * (hear the patch in isolation); a primitive has no envelope/pitch of its own, so it's not playable alone
 * (null). The ephemeral cue references only kit voices, so `compileCue` resolves it.
 */
export function playableCueForNode(node: SoundNode, kit: SoundKit): Cue | null {
  if (node.kind === "cue") return kit.cues.find((c) => c.id === node.refId) ?? null;
  if (node.kind === "voice") {
    const v = kit.voices.find((x) => x.id === node.refId);
    if (!v) return null;
    return { id: `_voice_${v.id}`, name: v.name, category: "ui", layers: [{ voice: v.id, at: 0 }] };
  }
  return null;
}

// Sound-kit pins (#3372, epic #3071 phase 4) — the blueprint↔sound-kit-store link, the sounds twin of
// `uiKitPin.ts` (#2465). A blueprint REFERENCES a sound kit as a lockfile entry
// (`Blueprint.soundKit = { id, version, hash, source? }`, exact pins only) against the GLOBAL versioned
// release store (`~/.base-studio-code/sound-kits/<id>/<version>/`, the Rust `bsc sound release` CLI,
// #3371), so one copy serves every blueprint that pins it and the same kit is never downloaded twice.
//
//  · packagedSoundKitPin — the packaged `bsc/signal` kit's pin (id/version/hash read from the generated
//    `@data/sound/signal-kit.meta.json` sidecar). Default-pinned onto every NEW blueprint
//    (`addBlueprint`); it resolves against the store's embedded fallback, so it needs no fetch.
//  · resolveSoundKitPin — the resolve flow on blueprint open/import: local store lookup → fetch the
//    typed gist ONLY when `id@version` is missing → verify sha256 BEFORE the store write (a mismatch is
//    rejected loudly and nothing is stored). Never re-fetches an existing id@version.
//  · importSoundKitByGistUrl — the authoring picker's import path: fetch a `sound-kit` gist, derive its
//    store identity, add it to the store (trust-on-first-import; the returned pin then locks the exact
//    bytes for everyone downstream).
//
// ONE DELIBERATE DIVERGENCE FROM THE UI TWIN — the artifact is UNWRAPPED. The UI store keeps whatever
// bytes it was handed (`resolveUiKitPin` stores the fetched envelope verbatim), because a UI kit's
// artifact is a `{ id, version, kit, components }` wrapper either way. A SOUND kit is SELF-CONTAINED —
// the artifact IS the `{ id, name, primitives, voices, cues }` object — and the Rust store ENFORCES it
// (`validate_artifact` refuses anything without a non-empty top-level `cues`, so an envelope would be
// rejected outright). So the share envelope carries the kit as its `payload`, and what lands in the
// store is that payload alone, re-serialized through {@link canonicalSoundArtifact} — matching the
// Rust `assemble_artifact` byte form, so a `--from-store` release and a gist import of the same kit
// agree. The pin's `hash` is therefore the hash of the ARTIFACT, never of the fetched envelope, and a
// consumer parses a pinned artifact directly as a SoundKit with NO unwrap step.
//
// SCOPE — this is the pin as CONFIG. Making the pin the RESOLUTION target for `@bsc/sounds/<id>`
// imports (today they resolve against the first packaged built-in, `libraryModules.ts`) is the
// explicit follow-up #3412, not an oversight: that resolver is a module-level const over packaged
// seeds while a pin resolves asynchronously through the bridge, and the Rust twin must move with it.
//
// Pure of React; store access goes through the generic `bsc` bridge (#2114), the same surface a live
// session reaches with `bsc sound release …` from its own shell.

import packagedKitMeta from "@data/sound/signal-kit.meta.json";
import { bsc, bscJson } from "@/shared/lib/core/bsc";
import { sha256Hex } from "@/shared/lib/core/sha256";
import { log } from "@/shared/lib/core/log";
import { fetchGistManifestText } from "@/features/planner/lib/gist/gist";
import { parseManifest } from "@/features/planner/lib/gist/manifest";
import type { Blueprint, BlueprintSoundKit } from "@/features/planner/stages/blueprints";

/** A sound-kit-store entry's manifest, as `bsc sound release list|get|add` emit it. */
export interface SoundKitStoreManifest {
  id: string;
  version: string;
  sha256: string;
  kind: "sound-kit";
  /** The typed-gist URL it was fetched from, or `"packaged"` for the embedded default. */
  source?: string;
}

/** The packaged default kit's pin — a FRESH object per call (pins live inside blueprint JSON, so
 *  handing out one shared instance would alias state across blueprints). */
export function packagedSoundKitPin(): BlueprintSoundKit {
  return { id: packagedKitMeta.id, version: packagedKitMeta.version, hash: packagedKitMeta.sha256 };
}

/** `id@version` — the store ref a pin resolves as. */
export function soundKitRef(pin: Pick<BlueprintSoundKit, "id" | "version">): string {
  return `${pin.id}@${pin.version}`;
}

/**
 * The canonical release-artifact bytes for a sound kit — the Rust `assemble_artifact` twin
 * (`crates/bsc-sound/src/release.rs`): pretty JSON, 2-space indent, one trailing newline. The hash a
 * pin records is the hash of THESE bytes, so the artifact's identity depends on the kit's CONTENT
 * rather than on however a publisher happened to format its gist.
 */
export function canonicalSoundArtifact(kit: unknown): string {
  return `${JSON.stringify(kit, null, 2)}\n`;
}

/** Every sound kit in the local release store (incl. the packaged default). Empty when the bridge is
 *  absent. */
export async function listStoreSoundKits(): Promise<SoundKitStoreManifest[]> {
  return bscJson<SoundKitStoreManifest[]>(null, ["sound", "release", "list"], []);
}

/** One store entry's manifest, or null when `id@version` isn't in the store. */
export async function getStoreSoundKit(
  pin: Pick<BlueprintSoundKit, "id" | "version">,
): Promise<SoundKitStoreManifest | null> {
  return bscJson<SoundKitStoreManifest | null>(null, ["sound", "release", "get", soundKitRef(pin)], null);
}

export type SoundKitResolution =
  /** `cached` — the id@version was already in the store (zero downloads). */
  | { ok: true; cached: boolean }
  | { ok: false; error: string };

/**
 * Resolve a blueprint's sound-kit pin against the local store (#3372): store hit ⇒ done (an existing
 * `id@version` is NEVER re-fetched — immutable versions make the local copy valid forever); miss ⇒
 * fetch the typed gist at `pin.source`, unwrap its payload to the canonical artifact, verify that
 * artifact's sha256 against `pin.hash` BEFORE anything is written, and only then add it to the store. A
 * hash mismatch (or a missing source, or a gist that isn't a sound kit) is a loud `{ ok: false }` and
 * the store is untouched. The `--sha256` handed to `bsc sound release add` makes the Rust store
 * re-verify, so the no-write-on-mismatch guarantee holds even if this caller is wrong.
 */
export async function resolveSoundKitPin(pin: BlueprintSoundKit, token = ""): Promise<SoundKitResolution> {
  if (await getStoreSoundKit(pin)) return { ok: true, cached: true };
  if (!pin.source) {
    return {
      ok: false,
      error: `sound kit ${soundKitRef(pin)} is not in the local sound-kit store and the pin has no source to fetch it from`,
    };
  }
  const raw = await fetchGistManifestText(pin.source, token);
  if (!raw.ok) return raw;
  const artifact = artifactFromGistText(raw.text);
  if (!artifact.ok) return artifact;
  const hash = await sha256Hex(artifact.text);
  if (hash !== pin.hash.toLowerCase()) {
    return {
      ok: false,
      error: `sound kit ${soundKitRef(pin)} REJECTED: fetched content hashes to ${hash} but the pin expects ${pin.hash} — refusing to store it`,
    };
  }
  try {
    await bsc(
      null,
      ["sound", "release", "add", pin.id, pin.version, "--kind", "sound-kit", "--sha256", pin.hash, "--source", pin.source],
      artifact.text,
    );
  } catch (e) {
    return { ok: false, error: `sound kit ${soundKitRef(pin)} could not be stored: ${String(e)}` };
  }
  return { ok: true, cached: false };
}

/**
 * Fire-and-forget resolve for a blueprint being OPENED or IMPORTED — the store-slice wire point.
 * No pin ⇒ no-op (blueprints without one are unaffected); a failure is logged loudly (the authoring
 * picker additionally surfaces it inline).
 */
export function resolveBlueprintSoundKit(bp: Pick<Blueprint, "name" | "soundKit"> | undefined, token = ""): void {
  const pin = bp?.soundKit;
  if (!pin) return;
  void resolveSoundKitPin(pin, token).then(
    (res) => {
      if (!res.ok) log.error(`blueprint "${bp?.name ?? "?"}": ${res.error}`);
    },
    // Fire-and-forget: an unexpected throw must land in the log, never as an unhandled rejection (#2515).
    (e) => log.error(`blueprint "${bp?.name ?? "?"}": sound-kit resolve failed: ${String(e)}`),
  );
}

/** The store-identity block a published sound-kit gist carries. Unlike the UI twin's `payload.store`,
 *  this rides the ENVELOPE (`manifest.store`) — the payload IS the artifact, so stamping a foreign
 *  `store` key inside it would corrupt the SoundKit the store validates and a consumer parses. */
export interface SoundKitStoreIdentity {
  id: string;
  version: string;
}

const STORE_ID_RE = /^[a-z0-9][a-z0-9-]*\/[a-z0-9][a-z0-9-]*$/;
const slug = (s: string): string =>
  s.toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, "") || "kit";

/** Derive a fetched sound-kit gist's store identity: the stamped envelope-level `store` when present +
 *  valid, else `<gist-owner>/<kit-id>` slugs with the envelope's own version. Exported for tests. */
export function deriveSoundKitIdentity(
  manifest: { id?: unknown; version?: unknown; store?: unknown; payload?: unknown },
  owner?: string,
): SoundKitStoreIdentity {
  const store = manifest.store as { id?: unknown; version?: unknown } | undefined;
  const stamped = typeof store?.id === "string" ? store.id : "";
  // The kit's OWN id names it best (`signal`); the envelope id is the fallback for a gist that
  // wrapped a kit without one.
  const kitId = (manifest.payload as { id?: unknown } | undefined)?.id;
  const name = typeof kitId === "string" && kitId ? kitId : typeof manifest.id === "string" ? manifest.id : "kit";
  const id = STORE_ID_RE.test(stamped) ? stamped : `${slug(owner ?? "gist")}/${slug(name)}`;
  const version =
    (typeof store?.version === "string" && store.version) ||
    (typeof manifest.version === "string" && manifest.version) ||
    "1.0.0";
  return { id, version };
}

type ArtifactResult = { ok: true; text: string } | { ok: false; error: string };

/** Validate a fetched gist as a `sound-kit` envelope and unwrap its payload into canonical artifact
 *  bytes. The one place the envelope→artifact step lives, so the import and resolve paths can never
 *  disagree about what gets hashed and stored. */
function artifactFromGistText(text: string): ArtifactResult {
  const parsed = parseManifest(text);
  if (!parsed.ok) return parsed;
  if (parsed.manifest.kind !== "sound-kit") {
    return { ok: false, error: `that gist holds a '${parsed.manifest.kind}', not a sound kit` };
  }
  const payload = parsed.manifest.payload as { cues?: unknown } | undefined;
  // Fall loudly rather than storing a hollow kit: the Rust store refuses a cue-less artifact anyway,
  // so catching it here turns an opaque CLI error into an actionable one.
  if (!payload || typeof payload !== "object" || !Array.isArray(payload.cues) || payload.cues.length === 0) {
    return { ok: false, error: "that sound-kit gist carries no cues — a kit with no cues maps to no UI sound" };
  }
  return { ok: true, text: canonicalSoundArtifact(payload) };
}

export type SoundKitImportResult =
  | { ok: true; pin: BlueprintSoundKit }
  | { ok: false; error: string };

/**
 * Import a sound kit by gist URL into the global store, returning the pin to record on the blueprint
 * (#3372, the authoring picker's import path). Fetch → validate it IS a `sound-kit` envelope → unwrap
 * to the canonical artifact → derive the store identity → add to the store (the store enforces
 * id@version immutability — a conflict with different content is surfaced, not overwritten) → pin
 * `{ id, version, hash, source }`.
 */
export async function importSoundKitByGistUrl(url: string, token = ""): Promise<SoundKitImportResult> {
  const raw = await fetchGistManifestText(url, token);
  if (!raw.ok) return raw;
  const artifact = artifactFromGistText(raw.text);
  if (!artifact.ok) return artifact;
  const parsed = parseManifest(raw.text);
  if (!parsed.ok) return parsed;
  const { id, version } = deriveSoundKitIdentity(parsed.manifest, raw.owner);
  const hash = await sha256Hex(artifact.text);
  try {
    await bsc(null, ["sound", "release", "add", id, version, "--kind", "sound-kit", "--source", url], artifact.text);
  } catch (e) {
    return { ok: false, error: `could not add ${id}@${version} to the sound-kit store: ${String(e)}` };
  }
  return { ok: true, pin: { id, version, hash, source: url } };
}

// Sound-kit RESOLUTION for the Design Studio (#3412, epic #3071) — the step that turns a blueprint's
// `soundKit` PIN (config, #3372) into the kit a `@bsc/sounds/<id>` import actually resolves against.
//
// #3372 shipped the pin and its store resolution; until now `libraryModules.ts` still resolved every sound
// reference against the first packaged built-in, so a component referencing `@bsc/sounds/click` played the
// STARTER kit's click even when its project pinned a different kit. The picker said the pin took effect and
// it silently did not — a correctness gap whose failure mode is INAUDIBLE, which is why the policy below
// never degrades quietly.
//
// The read side of the pin: the artifact already lives in the global versioned release store (written by
// `resolveSoundKitPin` on blueprint open/import, #3372), so this only READS it —
// `bsc sound release get <id@version> --artifact` — and never fetches, verifies, or writes. A pin whose
// artifact is missing is therefore a genuine, reportable breakage (the resolve step failed or the store was
// tampered with), not a cache miss to paper over.
//
// Pure of React; store access goes through the generic `bsc` bridge (#2114), the same surface a live
// session reaches with `bsc sound release …` from its own shell.
import { bsc } from "@/shared/lib/core/bsc";
import { validateKit, type SoundKit } from "@/features/sounds";
import type { BlueprintSoundKit } from "@/features/planner/stages/blueprints";
import { DEFAULT_SOUND_KIT, type SoundKitSelection } from "@/features/designs/lib/libraryModules";

/** `id@version` — the store ref a pin resolves as. Mirrors `soundKitRef` (planner `soundKitPin.ts`); kept
 *  local so the designs feature reads a pin without reaching into the planner's internals. */
export function pinRef(pin: Pick<BlueprintSoundKit, "id" | "version">): string {
  return `${pin.id}@${pin.version}`;
}

/**
 * Resolve a blueprint's sound-kit pin into the {@link SoundKitSelection} the Design Studio's library
 * resolvers run under (#3412). ONE DEFAULT, TWO LOUD FAILURES:
 *
 *  · no pin ⇒ `{ kind: "default" }` — the packaged starter kit, exactly as before #3412. An unpinned
 *    project's resolution is unchanged.
 *  · pin present + its artifact reads + parses as a valid kit ⇒ `{ kind: "pinned" }`.
 *  · pin present but UNRESOLVABLE — missing artifact, malformed JSON, a structurally invalid kit, or a
 *    bridge failure ⇒ `{ kind: "unresolved" }`, which drops the sound arm entirely so every
 *    `@bsc/sounds/…` surfaces as an unresolvable import. NEVER a silent degrade to the starter kit: the
 *    user cannot hear that the wrong kit loaded.
 *
 * Never throws — a bridge rejection becomes the `unresolved` arm, so a caller wires one code path.
 */
export async function selectSoundKit(pin: BlueprintSoundKit | undefined): Promise<SoundKitSelection> {
  if (!pin) return DEFAULT_SOUND_KIT;
  const ref = pinRef(pin);
  let raw: string;
  try {
    raw = (await bsc(null, ["sound", "release", "get", ref, "--artifact"])).trim();
  } catch (e) {
    return { kind: "unresolved", ref, error: `sound kit ${ref} could not be read from the store: ${String(e)}` };
  }
  // The CLI prints `null` (or nothing) for a ref the store doesn't hold — the pin resolved to no artifact.
  if (!raw || raw === "null") {
    return {
      kind: "unresolved",
      ref,
      error: `sound kit ${ref} is pinned but is not in the local sound-kit store — reopen the blueprint to resolve its pin`,
    };
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    return { kind: "unresolved", ref, error: `sound kit ${ref} artifact is not valid JSON: ${String(e)}` };
  }
  const kit = asSoundKit(parsed);
  if (!kit) {
    return { kind: "unresolved", ref, error: `sound kit ${ref} artifact is not a sound kit (no id / cues)` };
  }
  // A kit whose voices/cues reference missing parts would resolve imports that then fail INSIDE the player
  // module — catch it here so the breakage is reported at the pin, where it can be fixed.
  const problems = validateKit(kit);
  if (problems.length > 0) {
    return { kind: "unresolved", ref, error: `sound kit ${ref} is structurally invalid: ${problems.join("; ")}` };
  }
  return { kind: "pinned", ref, kit };
}

/** Narrow a parsed artifact to a {@link SoundKit} — the shape the store's `validate_artifact` already
 *  enforces on write (a non-empty top-level `cues`), re-checked here because the artifact crossed a
 *  process boundary. Missing optional collections normalize to `[]` so `validateKit` can run. */
function asSoundKit(v: unknown): SoundKit | null {
  if (!v || typeof v !== "object") return null;
  const o = v as Partial<SoundKit>;
  if (typeof o.id !== "string" || !o.id) return null;
  if (!Array.isArray(o.cues) || o.cues.length === 0) return null;
  return {
    ...(o as SoundKit),
    primitives: Array.isArray(o.primitives) ? o.primitives : [],
    voices: Array.isArray(o.voices) ? o.voices : [],
    cues: o.cues,
  };
}

