  toggleReveal: (uid: string) => void;
  /** Connect a source — OAuth flow or save-secrets-then-scan for credential connectors. */
  connect: (uid: string) => void;
  /** Reset an errored source back to declared so the user can retry. */
  retry: (uid: string) => void;
  /** Revoke a source's on-device secrets (called when the source is removed, #1194). */
  revokeSecrets: (uid: string) => void;
}

/**
 * The per-source connection state machine + secret-masking state for the Source body.
 *
 * @param pid     the project key (store + keychain scope)
 * @param cfg     the current SourceConfig (the render-time snapshot the actions close over)
 * @param persist writes a new SourceConfig back to the store
 */
export function useSourceConnection(
  pid: string,
  cfg: SourceConfig,
  persist: (next: SourceConfig) => void,
): SourceConnection {
  const [revealed, setRevealed] = useState<Set<string>>(new Set());
  // Secret field values — LOCAL ONLY, keyed by source uid → field key. Never persisted.
  const [secrets, setSecrets] = useState<Record<string, Record<string, string>>>({});

  // Patch one source by uid, reading the latest config from the store (safe across timeouts).
  const patchSource = (uid: string, patch: Partial<DeclaredSource>) => {
    const latest = useAppStore.getState().planSourceConfig[pid] ?? cfg;
    persist({ ...latest, sources: latest.sources.map((s) => (s.uid === uid ? { ...s, ...patch } : s)) });
  };

  function setField(uid: string, key: string, v: string) {
    patchSource(uid, { fields: { ...(cfg.sources.find((s) => s.uid === uid)?.fields ?? {}), [key]: v } });
  }
  function setSecret(uid: string, key: string, v: string) {
    setSecrets((p) => ({ ...p, [uid]: { ...(p[uid] ?? {}), [key]: v } }));
  }
  function toggleReveal(uid: string) {
    setRevealed((p) => { const n = new Set(p); if (n.has(uid)) n.delete(uid); else n.add(uid); return n; });
  }

  function revokeSecrets(uid: string) {
    // Revoke any on-device secrets for this source's connector fields (#1194).
    const src = cfg.sources.find((s) => s.uid === uid);
    if (src) {
      for (const f of connector(src.connectorId).spec.fields) {
        if (f.secret) fireInvoke("source_delete_secret", { project: pid, sourceUid: uid, field: f.key });
      }
    }
  }

  // Run the live read-only scan; on a non-live result or error, fall back to the sample shape so
  // the pane stays demonstrable until every connector's live transport / OAuth app is in place.
  async function runScan(uid: string, connectorId: string, fields: Record<string, string>, fallbackHandle: string) {
    try {
      const res = await invoke<{ live: boolean; instance?: string; handle?: string; objects?: { name: string; count: number; fields?: DiscoveredField[] }[]; behaviors?: { label: string }[]; platform?: PlatformScanView }>(
        "data_platform_scan",
        { connectorId, project: pid, sourceUid: uid, fields },
      );
      if (res?.live) {
        patchSource(uid, {
          status: "scanned",
          handle: res.handle || fallbackHandle,
          ...(res.instance ? { instance: res.instance } : {}),
          objects: res.objects ?? [],
          behaviors: res.behaviors ?? [],
          platform: res.platform,
        });
        return;
      }
    } catch { /* fall through to the sample shape */ }
    const scan = sampleScan(connectorId);
    patchSource(uid, { status: "scanned", objects: scan.objects, behaviors: scan.behaviors });
  }

  // OAuth connect: kick off the browser authorization-code flow, then scan once the token lands in
  // the keychain. If OAuth isn't configured (no client id) the begin call returns no URL and we
  // degrade to the sample shape so the pane still works.
  function oauthConnect(uid: string, src: DeclaredSource, c: ReturnType<typeof connector>) {
    const fallbackHandle = redactedHandle({ ...src, instance: src.instance || c.name });
    patchSource(uid, { status: "connecting" });
    void (async () => {
      let begin: { authorizeUrl?: string } | null = null;
      try {
        begin = await invoke<{ authorizeUrl: string }>("source_oauth_begin", {
          connectorId: src.connectorId, project: pid, sourceUid: uid, env: src.env ?? "production",
        });
      } catch { /* not configured / unavailable */ }
      if (!begin?.authorizeUrl) {
        patchSource(uid, { status: "scanning", secretSaved: false, handle: fallbackHandle, instance: src.instance || c.name });
        void runScan(uid, src.connectorId, { ...(src.fields ?? {}) }, fallbackHandle);
        return;
      }
      await openUrl(begin.authorizeUrl).catch(() => {});
      const unlisten = await listen<{ sourceUid: string; ok: boolean; instance?: string; realm?: string; error?: string }>(
        "source-oauth-complete",
        (ev) => {
          const p = ev.payload;
          if (p.sourceUid !== uid) return;
          unlisten();
          if (!p.ok) { patchSource(uid, { status: "error", error: p.error ?? "authorization failed" }); return; }
          // Capture non-secret instance metadata into the config (the token stays in the keychain).
          const fields = { ...(useAppStore.getState().planSourceConfig[pid]?.sources.find((s) => s.uid === uid)?.fields ?? {}) };
          if (p.instance) fields.instanceUrl = p.instance;
          if (p.realm) fields.realm = p.realm;
          const handle = redactedHandle({ ...src, instance: p.instance || c.name });
          patchSource(uid, { status: "scanning", secretSaved: true, instance: p.instance || c.name, handle, fields });
          void runScan(uid, src.connectorId, fields, handle);
        },
      );
    })();
  }

  // Connect: OAuth connectors run the browser flow; credential connectors save each secret to the
  // OS keychain (#1194) — it leaves component state for the device's secure store, never written to
  // the config or shared with the planner — then scan.
  function connect(uid: string) {
    const src = cfg.sources.find((s) => s.uid === uid);
    if (!src) return;
    const c = connector(src.connectorId);
    if (c.spec.auth === "oauth") { oauthConnect(uid, src, c); return; }

    const fallbackHandle = redactedHandle({ ...src, instance: src.instance || c.name });
    const fieldsSnapshot = { ...(src.fields ?? {}) };
    const draft = secrets[uid] ?? {};
    const saved = Object.entries(draft).filter(([, v]) => v.trim());
    const saves = saved.map(([field, value]) =>
      safeInvoke("source_save_secret", { project: pid, sourceUid: uid, field, value }, undefined)
    );

    patchSource(uid, { status: "connecting" });
    // Drop the local secret draft — it's on the device keychain now, never re-shown.
    setSecrets((p) => { const n = { ...p }; delete n[uid]; return n; });
    setRevealed((p) => { const n = new Set(p); n.delete(uid); return n; });

    void Promise.all(saves).then(() => {
      patchSource(uid, { status: "scanning", secretSaved: saved.length > 0, handle: fallbackHandle, instance: src.instance || c.name });
      void runScan(uid, src.connectorId, fieldsSnapshot, fallbackHandle);
    });
  }
  function retry(uid: string) {
    patchSource(uid, { status: "declared", error: undefined });
  }

  return { secrets, revealed, patchSource, setField, setSecret, toggleReveal, connect, retry, revokeSecrets };
}

// Discovery-declared integrations → the Source pane's proposals (#4054).
//
// The pane's "Confirm N sources" banner used to be seeded by scanning the PITCH for keywords
// (`proposeFromPitch`). That was the best signal available when it was written, and it no longer is:
// since #4024 the planner records the integrations the user actually CONFIRMED in conversation, each
// with a `direction`, and `direction: "source"` means exactly "data migrates FROM this" — which is what
// the Source pane exists to offer.
//
// Guessing from keywords when the answer has been stated is the wrong input: the scan can omit a system
// the user named and propose one they never mentioned. These helpers are pure so the precedence and the
// direction filter are unit-testable without the pane.

/** One declared integration as `bsc plan discovery integration list --json` emits it (camelCase wire,
 *  matching the Rust `PlanIntegration`). Every field but `id` may be absent. */
export interface DeclaredIntegration {
  id: string;
  name?: string;
  /** `source` = data migrates FROM it | `runtime` = the built app talks to it while running. */
  direction?: string;
  docs?: string;
  baseUrl?: string;
  /** The auth SCHEME in prose ("OAuth2 client credentials"). Never a secret. */
  auth?: string;
  purpose?: string;
}

/** The `direction` the Source pane cares about — a migration source, not a runtime dependency. */
export const SOURCE_DIRECTION = "source";

/**
 * The migration sources among `rows`, in declaration order.
 *
 * Filters defensively rather than trusting the caller's `--direction` flag: a runtime integration must
 * NEVER reach the Source pane. That is the entire point of the split — a payment API is not something
 * you migrate off, and offering it as one sends the user down a pointless connect-and-scan path.
 * Rows without a usable `id` are dropped (they cannot be keyed), and duplicate ids collapse to the
 * first, so a re-declared integration proposes once.
 */
export function migrationSources(rows: readonly DeclaredIntegration[]): DeclaredIntegration[] {
  const seen = new Set<string>();
  const out: DeclaredIntegration[] = [];
  for (const r of rows ?? []) {
    const id = (r?.id ?? "").trim();
    if (!id || r?.direction !== SOURCE_DIRECTION || seen.has(id)) continue;
    seen.add(id);
    out.push({ ...r, id });
  }
  return out;
}

/**
 * The connector ids to seed the pre-declare banner with, and where they came from.
 *
 * **Discovery wins.** The pitch scan survives only as the fallback for a project whose Discovery
 * predates #4024 (or that never worked the `integrations` topic) — so a proposal is traceable to a
 * decision whenever one exists, and the older behaviour is preserved exactly where it isn't. Pure.
 */
export function proposedSourceIds(
  declared: readonly DeclaredIntegration[],
  fromPitch: readonly string[],
): { ids: string[]; origin: "discovery" | "pitch" | "none" } {
  const sources = migrationSources(declared);
  if (sources.length > 0) return { ids: sources.map((s) => s.id), origin: "discovery" };
  const pitch = (fromPitch ?? []).filter(Boolean);
  return pitch.length > 0 ? { ids: [...pitch], origin: "pitch" } : { ids: [], origin: "none" };
}

/**
 * The non-secret connect fields Discovery already captured for `id`, ready to seed a newly declared
 * source — so an agent authoring its connector starts from the vendor reference the user gave instead
 * of a blank form.
 *
 * ONLY `baseUrl` and `docs` cross: both are plain URLs. `auth` is deliberately excluded even though it
 * is a prose scheme rather than a credential — `DeclaredSource.fields` is the connect-form's value bag,
 * and a scheme string is not a field value. Nothing secret exists on this path to begin with.
 */
export function connectFieldsFor(
  id: string,
  declared: readonly DeclaredIntegration[],
): Record<string, string> {
  const row = migrationSources(declared).find((r) => r.id === id);
  if (!row) return {};
  const fields: Record<string, string> = {};
  const baseUrl = (row.baseUrl ?? "").trim();
  const docs = (row.docs ?? "").trim();
  if (baseUrl) fields.baseUrl = baseUrl;
  if (docs) fields.docs = docs;
  return fields;
}

// Migration SOURCE gate (#source-pane) — the pure readiness/gate helpers that drive the Source
// stage: connection counts + readiness checks, the `sourcesConnected` gate signal, and the
// Data Model gate signals derived from the live scan state (so the gate reflects scan progress
// without a round-trip to the store). Split out of sourceValidate.ts (#1712); the Data Model derivation
// lives in dataModelDerivation.ts and the type model in sourceSpecs.ts.

import type { ReadinessCheck } from "@/features/planner/lib/readiness";
import { deriveDataModel } from "@/features/planner/lib/dataModelDerivation";
import type { DeclaredSource, SourceConfig } from "@/features/planner/lib/sourceSpecs";

/** A source counts as "connected" once it is scanning or fully scanned (authorized, secret on device). */
export function isConnected(s: DeclaredSource): boolean {
  return s.status === "scanning" || s.status === "scanned";
}

/** How many declared sources are connected. */
export function connectedCount(cfg: SourceConfig): number {
  return cfg.sources.filter(isConnected).length;
}

/** The `sourcesConnected` gate signal: ≥1 source declared and EVERY one fully scanned (no pending or
 *  errored source). An empty set can't pass (nothing to migrate from ⇒ the stage shouldn't apply). */
export function allSourcesConnected(cfg: SourceConfig | undefined): boolean {
  return !!cfg && cfg.sources.length > 0 && cfg.sources.every((s) => s.status === "scanned");
}

/** Readiness checks driving the in-pane banner: every declared source scanned, none errored. */
export function sourceChecks(cfg: SourceConfig): ReadinessCheck[] {
  const total = cfg.sources.length;
  const scanned = cfg.sources.filter((s) => s.status === "scanned").length;
  const errored = cfg.sources.filter((s) => s.status === "error").length;
  return [
    { id: "declared", label: "Declare the systems you're migrating from", ok: total > 0, detail: `${total} source${total !== 1 ? "s" : ""}` },
    { id: "connected", label: "Connect & scan every source", ok: total > 0 && scanned === total, detail: `${scanned}/${total} connected` },
    { id: "healthy", label: "No connection errors", ok: errored === 0, detail: errored ? `${errored} failed` : "all healthy" },
  ];
}

/** Whether a migration source is active for the project (≥1 declared source) — drives the `source`
 *  stage's `migrationSourceEnabled` so the stage applies. */
export function migrationActive(cfg: SourceConfig | undefined): boolean {
  return !!cfg && cfg.sources.length > 0;
}

/** The Data Model gate signals derived from the live scan state (feeds derivePlanStageState), so the
 *  source stage's gate reflects scan progress without reading back the canonical model. The canonical
 *  Data Model itself lives in the project's DuckDB store (`bsc data model get`, #1446) — these are
 *  progress booleans about the scan, not a read of that store. */
export function dataModelSignals(cfg: SourceConfig | undefined): { sourceReachable: boolean; modelInferred: boolean; schemaRefined: boolean } {
  if (!cfg) return { sourceReachable: false, modelInferred: false, schemaRefined: false };
  return {
    sourceReachable: cfg.sources.some((s) => s.status === "scanning" || s.status === "scanned"),
    modelInferred: cfg.sources.some((s) => s.status === "scanned"),
    schemaRefined: allSourcesConnected(cfg),
  };
}

/** The downstream-impact recap: what the scanned sources seed into features + structure. */
export function downstreamImpact(cfg: SourceConfig): { entities: number; fields: number; behaviors: number } {
  const m = deriveDataModel(cfg);
  const behaviors = cfg.sources.reduce((n, s) => {
    const p = s.platform;
    return n + (p ? p.automations.length + p.businessProcesses.length + p.derivedLogic.length : s.behaviors?.length ?? 0);
  }, 0);
  return { entities: m.entities.length, fields: m.entities.reduce((n, e) => n + e.fields.length, 0), behaviors };
}

// Migration SOURCE scan visualizations (#1209) — the view-models behind the Source pane's Graph /
// List / Process views: the entities (with record counts, source provenance, fields + inferred refs)
// the Graph + List views render, the ref edges for the Graph, the aggregated structured behaviors the
// Process view renders, and the multi-source provenance flag. Built from the derived Data Model and
// the scanned objects. Split out of sourceValidate.ts (#1712); the derivation lives in
// dataModelDerivation.ts and the per-source colors in sourceCatalog.ts.

import type { FieldType } from "@/features/planner/data/dataModel";
import { deriveDataModel, safeKey } from "@/features/planner/lib/dataModelDerivation";
import { connectorColor } from "@/features/planner/lib/sourceCatalog";
import type { PlatformScanView, SourceConfig } from "@/features/planner/lib/sourceSpecs";

export interface ScanViewField { key: string; type: FieldType; required: boolean; identity: boolean; ref?: string; refLabel?: string; enumValues?: string[] }
export interface ScanViewEntity { key: string; label: string; count: number; source: string; srcColor: string; fields: ScanViewField[] }

/** The entities (with record counts, source provenance, fields + inferred refs) the Graph + List
 *  views render — built from the derived model and the scanned objects. */
export function scanEntities(cfg: SourceConfig): ScanViewEntity[] {
  const model = deriveDataModel(cfg);
  const labelByKey = new Map(model.entities.map((e) => [e.key, e.label ?? e.key]));
  const meta = new Map<string, { count: number; source: string }>();
  for (const s of cfg.sources) {
    if (s.status !== "scanned") continue;
    for (const o of s.objects ?? []) {
      const k = safeKey(o.name) || "entity";
      if (!meta.has(k)) meta.set(k, { count: o.count, source: s.connectorId }); // first wins (matches dedup)
    }
  }
  return model.entities.map((e) => {
    const m = meta.get(e.key) ?? { count: 0, source: "" };
    return {
      key: e.key,
      label: e.label ?? e.key,
      count: m.count,
      source: m.source,
      srcColor: connectorColor(m.source),
      fields: e.fields.map((f) => ({
        key: f.key, type: f.type, required: !!f.required, identity: e.identity.includes(f.key),
        ref: f.ref, refLabel: f.ref ? labelByKey.get(f.ref) ?? f.ref : undefined,
        enumValues: f.enum_values,
      })),
    };
  });
}

/** All ref relationships as edges for the Graph view. */
export function scanEdges(entities: ScanViewEntity[]): { from: string; to: string; label: string }[] {
  const keys = new Set(entities.map((e) => e.key));
  const edges: { from: string; to: string; label: string }[] = [];
  for (const e of entities) {
    for (const f of e.fields) {
      if (f.ref && keys.has(f.ref)) edges.push({ from: e.key, to: f.ref, label: `${f.key} → ${f.refLabel ?? f.ref}` });
    }
  }
  return edges;
}

/** The aggregated structured behaviors (across scanned sources) the Process view renders. */
export function aggregatePlatform(cfg: SourceConfig): PlatformScanView {
  const out: PlatformScanView = { automations: [], businessProcesses: [], derivedLogic: [] };
  for (const s of cfg.sources) {
    if (s.status !== "scanned" || !s.platform) continue;
    out.automations.push(...s.platform.automations);
    out.businessProcesses.push(...s.platform.businessProcesses);
    out.derivedLogic.push(...s.platform.derivedLogic);
  }
  return out;
}

/** Whether ≥2 distinct connector sources fed the scan (drives per-source provenance badges). */
export function isMultiSource(cfg: SourceConfig): boolean {
  return new Set(cfg.sources.filter((s) => s.status === "scanned").map((s) => s.connectorId)).size > 1;
}

// Migration SOURCE specs (#source-pane) — the pure type model behind the planner's Source stage:
// the per-connector connection contract (auth + form fields), the discovered inventory shape a scan
// returns, the structured behavior scan, and the per-project SourceConfig the Source pane edits.
// Split out of sourceConfig.ts (#1638); the connector catalog lives in sourceCatalog.ts and the
// gate/derivation/scan-view helpers in sourceGate.ts / dataModelDerivation.ts / sourceScanViews.ts.
// sourceConfig.ts re-exports them all.
//
// SECURITY BOUNDARY: a connector's SECRET field values NEVER live in this config (they go to the OS
// keychain on the device and are never persisted here or shared with the planning agent). The config
// keeps only non-secret fields, a redacted `handle`, and the discovered (not extracted) inventory.

import type { FieldType } from "@/features/planner/data/dataModel";

/** How a connector authenticates — drives which card the per-source ConnectionSpec renders. */
export type AuthMethod = "oauth" | "token" | "password" | "basic" | "apiKey" | "open" | "upload";

/** One input a connector's form collects. A `secret` field is masked, kept on-device, and never
 *  written into {@link DeclaredSource.fields}. */
export interface SpecField {
  key: string;
  label: string;
  /** Masked + keychain-bound; never persisted to the config or shared with the planner. */
  secret?: boolean;
  /** Optional field — absence doesn't block connecting (e.g. an app id that just scopes the scan). */
  optional?: boolean;
  hint?: string;
  placeholder?: string;
}

/** The per-connector connection contract — the same surface renders a different page from this. */
export interface ConnectionSpec {
  auth: AuthMethod;
  /** Form fields for token/password/basic/apiKey connectors (empty for oauth/upload). */
  fields: SpecField[];
  /** OAuth button label, e.g. "Connect to Salesforce" (oauth connectors only). */
  oauthLabel?: string;
  /** Show a Production / Sandbox environment toggle (oauth connectors). */
  envs?: boolean;
  /** One-line "will contribute →" summary of what a scan pulls in (objects + behaviors). */
  contributes: string;
}

/** A catalog connector the user can declare as a source. */
export interface Connector {
  id: string;
  name: string;
  /** Two/three-char mono badge, e.g. "QB". */
  badge: string;
  /** Catalog auth blurb, e.g. "OAuth" / "token" / "API key". */
  authLabel: string;
  spec: ConnectionSpec;
  /** Coarse grouping for the catalog UI (#1288) — `crm`, `erp`, `work`, … ; absent for the
   *  dedicated core connectors. */
  category?: string;
  /** A packaged generic-REST vendor preset (#1288), vs a dedicated connector. */
  preset?: boolean;
}

/** A discovered field: name + an inferred type + (for enums) the observed values (#1219). */
export interface DiscoveredField { name: string; type?: FieldType; enumValues?: string[]; ref?: string }
/** An object/table the scan discovered in a connected source (a count, not extracted rows).
 *  `fields` accepts bare column names (older fixtures) or typed {@link DiscoveredField}s (the live
 *  scan) — used to seed the derived Data Model's entity fields + types. */
export interface DiscoveredObject { name: string; count: number; fields?: (string | DiscoveredField)[] }
/** A behavior (business rule / automation) the scan found — these shape the target app, not just data. */
export interface SourceBehavior { label: string }

// ── Structured behavior scan (the Process visualization, #1209) ──────────────────────────────
// Mirrors the Rust `bsc_data::PlatformScan` (serde camelCase). The scan returns this alongside the
// flat `behaviors` labels; the Process view renders the detail (trigger → condition → actions, etc.).
export type ScanAutomationKind = "validation" | "workflow" | "flow" | "processBuilder" | "recurring" | "other";
export interface ScanAutomation {
  source: string; kind: ScanAutomationKind; name: string; object: string;
  active: boolean; trigger: string; condition: string; actions: string[];
}
export interface ScanBusinessProcess { source: string; name: string; object: string; active: boolean; steps: string[] }
export type ScanDerivedKind = "formula" | "code";
export interface ScanDerivedLogic { source: string; kind: ScanDerivedKind; name: string; object?: string; expression: string }
export interface PlatformScanView {
  automations: ScanAutomation[];
  businessProcesses: ScanBusinessProcess[];
  derivedLogic: ScanDerivedLogic[];
}

/** The lifecycle of one declared source. `declared` = chosen, not yet authorized; `connecting` =
 *  validating credentials; `scanning` = authorized, discovering objects; `scanned` = inventory in
 *  hand; `error` = auth/connection failed (holds the gate). */
export type SourceStatus = "declared" | "connecting" | "scanning" | "scanned" | "error";

/** A source the user declared they're migrating from. */
export interface DeclaredSource {
  uid: string;
  connectorId: string;
  /** Friendly instance label once connected, e.g. "Acme Co". */
  instance?: string;
  env?: "production" | "sandbox";
  status: SourceStatus;
  /** Non-secret field values (keyed by ConnectionSpec field key). SECRETS ARE NEVER STORED HERE. */
  fields: Record<string, string>;
  /** Redacted handle the planner is allowed to see ("Acme Co · Production · held by app"). */
  handle?: string;
  /** A secret was saved to the device keychain (we keep the flag, never the value). */
  secretSaved?: boolean;
  objects?: DiscoveredObject[];
  behaviors?: SourceBehavior[];
  /** The structured behavior scan (automations / processes / derived logic) for the Process view (#1209). */
  platform?: PlatformScanView;
  /** Failure reason for the error state, e.g. "token rejected (401)". */
  error?: string;
}

export interface SourceConfig {
  /** The canonical Data Model every connected source feeds, e.g. "Acme Core". */
  dataModelName: string;
  /** Connector ids the planner proposed from the pitch (the pre-declare ★ banner); cleared once acted on. */
  proposed: string[];
  sources: DeclaredSource[];
}

/** A fresh, empty source config. */
export function defaultSourceConfig(): SourceConfig {
  return { dataModelName: "", proposed: [], sources: [] };
}

/** A new declared source for `connectorId` (status `declared`, no fields yet). */
export function newDeclaredSource(connectorId: string, uid: string): DeclaredSource {
  return { uid, connectorId, status: "declared", fields: {} };
}

// space.ts — the shared vocabulary the layout kit (Stack/Row/Spacer) is built on (#2056).
//
// One spacing scale, one alignment mapping. The named `Space` sizes mirror the `--sp-*` CSS
// tokens in tokens.css (xs=4 … xl=24) so the kit and the stylesheet speak the same scale — but
// a raw pixel number is always legal too (the very common `gap:10` stays `gap={10}`), which
// keeps mechanical `<div style>` → primitive conversions lossless.

import type { CSSProperties } from "react";

/** A spacing value: a named scale rung, or a raw pixel number for the off-scale cases. */
export type Space = number | "xs" | "sm" | "md" | "lg" | "xl";

/** Cross-axis / main-axis alignment, friendly names (map to their flexbox values). */
export type Align = "start" | "center" | "end" | "baseline" | "stretch";
export type Justify = "start" | "center" | "end" | "between" | "around" | "evenly";

const SCALE: Record<Exclude<Space, number>, number> = { xs: 4, sm: 8, md: 12, lg: 16, xl: 24 };

const ALIGN: Record<Align, CSSProperties["alignItems"]> = {
  start: "flex-start",
  center: "center",
  end: "flex-end",
  baseline: "baseline",
  stretch: "stretch",
};

const JUSTIFY: Record<Justify, CSSProperties["justifyContent"]> = {
  start: "flex-start",
  center: "center",
  end: "flex-end",
  between: "space-between",
  around: "space-around",
  evenly: "space-evenly",
};

/** Resolve a `Space` to a pixel number (named rung → scale, number → itself). */
export function space(v: Space | undefined): number | undefined {
  if (v == null) return undefined;
  return typeof v === "number" ? v : SCALE[v];
}

/** Resolve a friendly `Align` to its CSS box-alignment value. Shared by the flex + grid kit. */
export function alignValue(a: Align): CSSProperties["alignItems"] {
  return ALIGN[a];
}

/** Resolve a friendly `Justify` to its CSS distribution value. Shared by the flex + grid kit. */
export function justifyValue(j: Justify): CSSProperties["justifyContent"] {
  return JUSTIFY[j];
}

/** Resolve a padding shorthand: a single `Space` (all sides) or `[block, inline]`. */
export function pad(v: Space | [Space, Space] | undefined): CSSProperties["padding"] {
  if (v == null) return undefined;
  if (Array.isArray(v)) return `${space(v[0])}px ${space(v[1])}px`;
  const n = space(v);
  return n == null ? undefined : `${n}px`;
}

export interface FlexOptions {
  gap?: Space;
  align?: Align;
  justify?: Justify;
  wrap?: boolean;
}

/** Build the flex-layout portion of a style object shared by Stack and Row. */
export function flexStyle({ gap, align, justify, wrap }: FlexOptions): CSSProperties {
  const s: CSSProperties = {};
  const g = space(gap);
  if (g != null) s.gap = g;
  if (align) s.alignItems = ALIGN[align];
  if (justify) s.justifyContent = JUSTIFY[justify];
  if (wrap) s.flexWrap = "wrap";
  return s;
}

// The spec-first UI SDK (#1852 Phase 2) — public barrel. An AI emits a node tree as data;
// `validateGeneralNode` checks it against the shared primitive contract (`@data/ui/primitives.json`,
// generated from `shared/ui/manifest.ts` and also served + enforced by `bsc ui schema` / `validate`);
// `KitRenderer` renders it through the real kit primitives, wiring `binds` (host state in) and
// `actions` (host behaviour out). See `demoSpec` for a real end-to-end example.
//
// #3500 collapsed the closed `KitNode` vocabulary — the 8 hardcoded kinds (card/header/field/button/
// row/toggle/tag/text) and the hand-written renderer branch behind each — into this ONE open node
// over the whole manifest. A spec now names real components, so adding a primitive makes it
// authorable with no edit to the renderer, the validator, or the contract.

export type { GeneralNode } from "@/shared/ui/spec/generalNode";
export { validateGeneralNode, PRIMITIVE_NAMES, VALIDATION_COVERAGE } from "@/shared/ui/spec/generalNode";
export { KitRenderer } from "@/shared/ui/spec/KitRenderer";
export type { KitRendererProps, KitBindings } from "@/shared/ui/spec/KitRenderer";
export { SelfWiredKitRenderer } from "@/shared/ui/spec/SelfWiredKitRenderer";
export type { SelfWiredKitRendererProps } from "@/shared/ui/spec/SelfWiredKitRenderer";
export { visitNodes, collectActions } from "@/shared/ui/spec/specWalk";
export { demoSpec } from "@/shared/ui/spec/demoSpec";

// Pure node-tree helpers (#2868) — depth-first traversal + derived collections over a spec tree.
// No React; the interaction-defaults host (SelfWiredKitRenderer) and future behavior slices read from
// here.
//
// Generalised in #3500. The old walk descended two hardcoded kinds (`card`'s header + children, and
// `row`'s children) and treated everything else as a leaf — so a node nested in ANY other slot was
// invisible to it. The general vocabulary has no fixed set of container types, so the walk now
// descends STRUCTURALLY: any prop value that is (or contains) a node is followed, as is the
// node-level `children` sugar. A spec that renders is therefore a spec that walks — the two can no
// longer disagree about where the children are.

import { UI_KIT } from "@/shared/ui/manifest";
import type { GeneralNode } from "@/shared/ui/spec/generalNode";

/** Primitive name → the set of its props the manifest declares as handlers. */
const FUNCTION_PROPS = new Map(
  UI_KIT.map((p) => [
    p.name as string,
    new Set(p.props.filter((x) => x.type === "function").map((x) => x.name)),
  ]),
);

/** Is this a node? Structural, matching what the renderer will actually descend into. */
function isNode(v: unknown): v is GeneralNode {
  return (
    typeof v === "object" && v !== null && !Array.isArray(v) &&
    typeof (v as { type?: unknown }).type === "string"
  );
}

/** Follow a slot value: a node, a list of them, or plain text (a leaf). */
function visitSlot(value: unknown, fn: (n: GeneralNode) => void): void {
  if (Array.isArray(value)) {
    for (const v of value) visitSlot(v, fn);
    return;
  }
  if (isNode(value)) visitNodes(value, fn);
}

/** Visit every node in a tree depth-first (self, then every node found in its props and children).
 *  Pure — the visitor sees each node exactly once. */
export function visitNodes(node: GeneralNode, fn: (n: GeneralNode) => void): void {
  fn(node);
  for (const value of Object.values(node.props ?? {})) visitSlot(value, fn);
  if (node.children !== undefined) visitSlot(node.children, fn);
}

/** Every distinct action name in a spec (#2868) — the actions a self-wiring host must resolve so a
 *  nested control's click never no-ops. Order is first-seen; duplicates collapse.
 *
 *  BOTH routes count, because the renderer honours both: the node-level `actions` map, and a
 *  `function`-typed prop whose value is an action name. A host that resolved only one of them would
 *  leave the other half of its own specs dead. */
export function collectActions(node: GeneralNode): string[] {
  const out = new Set<string>();
  visitNodes(node, (n) => {
    for (const name of Object.values(n.actions ?? {})) {
      if (typeof name === "string" && name) out.add(name);
    }
    const handlers = FUNCTION_PROPS.get(n.type);
    if (!handlers) return;
    for (const [prop, value] of Object.entries(n.props ?? {})) {
      if (handlers.has(prop) && typeof value === "string" && value) out.add(value);
    }
  });
  return [...out];
}

// App-owned text-to-speech (#3804, a11y epic #2725 Tier 1) — a thin wrapper over the WebView's
// SpeechSynthesis API (`window.speechSynthesis`). This is DISTINCT from #3770's ARIA live region
// (`announcer.ts`): that pushes text to a live region the user's OWN screen reader speaks; this is the
// app speaking with its own voice, for the streaming-fleet surfaces a screen reader handles badly.
// Every entry guards for absence so it's a safe no-op in a stripped WebView or the jsdom test env.

export interface SpeakOpts {
  /** Speech rate, 0.1–10 (default 1). */
  rate?: number;
  /** A `SpeechSynthesisVoice.voiceURI` to select; falls back to the platform default when absent/unknown. */
  voiceURI?: string;
}

/** How much of the fleet stream is spoken: `terse` = only the needs-you / went-wrong events; `verbose`
 *  = those plus the progress events (a PR landed, a gate is ready). */
export type TtsVerbosity = "terse" | "verbose";

/** The live `SpeechSynthesis` object, or `null` when the environment has none (SSR / jsdom / a stripped
 *  WebView). Coalesces a present-but-undefined value to `null` so `isSpeechSupported` reads correctly. */
function synth(): SpeechSynthesis | null {
  if (typeof window === "undefined") return null;
  return window.speechSynthesis ?? null;
}

/** Whether the WebView exposes SpeechSynthesis (false in tests / a stripped WebView). */
export function isSpeechSupported(): boolean {
  return synth() !== null && typeof SpeechSynthesisUtterance !== "undefined";
}

/** The voices the platform offers (empty when unsupported or the list hasn't loaded yet). */
export function listVoices(): SpeechSynthesisVoice[] {
  return synth()?.getVoices() ?? [];
}

/** Speak `text` at the given rate/voice. No-op when unsupported or the text is blank. Utterances QUEUE
 *  (coord events shouldn't cut each other off); call [`cancelSpeech`] to flush. */
export function speak(text: string, opts: SpeakOpts = {}): void {
  const s = synth();
  if (!s || !isSpeechSupported() || !text.trim()) return;
  const u = new SpeechSynthesisUtterance(text);
  if (opts.rate != null) u.rate = opts.rate;
  if (opts.voiceURI) {
    const v = s.getVoices().find((voice) => voice.voiceURI === opts.voiceURI);
    if (v) u.voice = v;
  }
  s.speak(u);
}

/** Stop + flush any queued or in-flight speech. */
export function cancelSpeech(): void {
  synth()?.cancel();
}

// Neighbor spotlight (#2215, graph-core epic #2214) — the shared "focus dims the rest" primitive. Given
// a node in focus (hovered/selected), it returns the node itself + its direct neighbors (in either
// direction) and every edge touching it, so the view can brighten those and dim everything else. Both
// Glance (focusSets) and the agent-relationship graph (computeSpotlight) resolve their node/agent focus
// this way; each layers its own domain extras on top (Glance's edge/cycle branches; the relationship
// graph's artifact lighting).
import type { GraphEdge } from "@/shared/lib/graph/types";

export interface Spotlight {
  /** The focused node + its direct neighbors. */
  litNodes: Set<string>;
  /** Every edge incident to the focused node. */
  litEdges: Set<string>;
}

/** The node in focus + its neighbors (either direction) + the edges touching it. Pure. */
export function neighborSpotlight(edges: readonly GraphEdge[], focusId: string): Spotlight {
  const litNodes = new Set<string>([focusId]);
  const litEdges = new Set<string>();
  for (const e of edges) {
    if (e.from === focusId) { litNodes.add(e.to); litEdges.add(e.id); }
    if (e.to === focusId) { litNodes.add(e.from); litEdges.add(e.id); }
  }
  return { litNodes, litEdges };
}

// STACK trace-programs (#3220, epic #3215) — the algorithms whose whole state IS the stack: the structure
// is not a container the algorithm happens to use, it is the thing being watched. Both are written over a
// TracedStack, so the animation is DERIVED from real execution — `push`/`pop` are the algorithm's own calls,
// not a replayed script.
//
// WHY THESE EXIST: `TracedStack`, `<StackView>`, its motion file and its tests all shipped with the tracer
// work, but the example registry only merged array/search/scalar/matrix/graph/scene programs — so a stack
// could only ever be MET inside a multi-structure scene (bfs's frontier, dijkstra's queue), never SELECTED
// as an algorithm in its own right. The renderer was finished and unreachable; these two programs are the
// keys that open it.
import type { TracedStack, StackMode } from "@/features/algorithms/lib/tracer";

/**
 * A visualizable stack algorithm — its real logic over a {@link TracedStack}, plus its own input seam.
 *
 * The seam is PER-PROGRAM here, unlike the array/matrix/graph families which share one parser. That is not
 * an inconsistency to tidy away: the two stack algorithms read genuinely different input languages (a
 * bracket string vs an RPN expression), so a single family parser could only validate the intersection of
 * the two — which is "a non-empty string", i.e. no validation at all. Each program owning its parser is
 * what lets the field reject `3 4 &` with a real message instead of failing mid-trace.
 */
export interface StackProgram {
  run: (s: TracedStack, input: string) => void;
  /** The TracedStack mode to run under — both current programs are LIFO stacks. */
  mode: StackMode;
  defaultInput: string;
  /** Placeholder text shown under the "your input" field. */
  hint: string;
  /** Parse the field text into this program's input, throwing a helpful Error the field can show. */
  parse: (text: string) => string;
}

/** Openers → their matching closer. The single source of truth for both the scan and the validator. */
const PAIRS: Record<string, string> = { "(": ")", "[": "]", "{": "}" };
const CLOSERS = new Set(Object.values(PAIRS));

/**
 * Are the brackets in `text` balanced? The canonical stack algorithm: every opener is PUSHED, every closer
 * POPS and must match the top. Returns the verdict; the trace is the point.
 *
 * An unbalanced input is a legitimate, interesting trace — a closer with an empty stack, or a mismatched
 * pair, ends the scan early and leaves the animation sitting on the failure. Characters outside the bracket
 * alphabet are skipped silently, so `f(x[0])` traces the brackets and ignores the rest.
 */
export function balancedParens(s: TracedStack, input: string): boolean {
  for (const ch of input) {
    if (PAIRS[ch]) {
      s.push(ch);
      continue;
    }
    if (!CLOSERS.has(ch)) continue; // not a bracket — not this algorithm's business
    if (s.size === 0) return false; // a closer with nothing open
    const open = s.pop();
    if (typeof open !== "string" || PAIRS[open] !== ch) return false; // wrong pair
  }
  return s.size === 0; // anything still open ⇒ unbalanced
}

/** Reject anything that would trace to nothing, so the field explains itself before the animation runs. */
export function parseParensInput(text: string): string {
  const t = text.trim();
  if (t.length === 0) throw new Error("Enter a bracket expression, e.g. {[()()]}");
  if (t.length > 40) throw new Error("Keep it to 40 characters so the animation stays watchable");
  if (![...t].some((c) => PAIRS[c] || CLOSERS.has(c))) {
    throw new Error(`"${t}" has no brackets — try {[()()]}`);
  }
  return t;
}

const OPS: Record<string, (a: number, b: number) => number> = {
  "+": (a, b) => a + b,
  "-": (a, b) => a - b,
  "*": (a, b) => a * b,
  "/": (a, b) => (b === 0 ? 0 : a / b),
};

/**
 * Evaluate a postfix (RPN) expression — the other canonical stack algorithm, and the one that shows the
 * stack SHRINKING under an operator rather than just unwinding. Operands are pushed; each operator pops two
 * and pushes the result, so the final `pop` is the answer.
 *
 * `a` is popped SECOND (it is the deeper operand), which is what makes `-` and `/` come out the right way
 * round. Division by zero yields 0 rather than Infinity — the trace stays renderable, and RPN has no
 * meaningful error frame to show.
 */
export function postfixEval(s: TracedStack, input: string): number {
  for (const tok of input.trim().split(/\s+/)) {
    const op = OPS[tok];
    if (!op) {
      s.push(Number(tok));
      continue;
    }
    if (s.size < 2) return 0; // malformed — not enough operands
    const b = Number(s.pop());
    const a = Number(s.pop()); // deeper operand ⇒ the LEFT-hand side
    s.push(op(a, b));
  }
  return s.size ? Number(s.pop()) : 0;
}

/** Validate an RPN expression: numbers + the four operators, and enough operands to reduce to one value. */
export function parsePostfixInput(text: string): string {
  const t = text.trim();
  if (t.length === 0) throw new Error("Enter a postfix expression, e.g. 3 4 + 2 *");
  const toks = t.split(/\s+/);
  if (toks.length > 25) throw new Error("Keep it to 25 tokens so the animation stays watchable");
  let depth = 0;
  for (const tok of toks) {
    if (OPS[tok]) {
      depth -= 1; // pops two, pushes one
      if (depth < 1) throw new Error(`"${tok}" has no two operands before it`);
      continue;
    }
    if (!Number.isFinite(Number(tok))) throw new Error(`"${tok}" is not a number or one of + - * /`);
    depth += 1;
  }
  if (depth !== 1) throw new Error("Expression must reduce to exactly one value");
  return t;
}

/** The visualizable stack algorithms, keyed by base name (#3220). */
export const STACK_PROGRAMS: Record<string, StackProgram> = {
  "balanced-parens": {
    run: balancedParens,
    mode: "stack",
    defaultInput: "{[()()]}",
    hint: "A bracket expression (e.g. {[()()]})",
    parse: parseParensInput,
  },
  "postfix-eval": {
    run: postfixEval,
    mode: "stack",
    defaultInput: "3 4 + 2 *",
    hint: "A postfix expression, space-separated (e.g. 3 4 + 2 *)",
    parse: parsePostfixInput,
  },
};

/** Serialize a stack seed to the "your input" text form — the input already IS its text. */
export function stackToText(input: string): string {
  return input;
}

/**
 * Parse the "your input" text for a STORED stack program (#4162) — the generic seam, which can only check
 * that there is something to trace.
 *
 * This is the same reasoning that made {@link StackProgram} carry a per-program `parse`, applied to the
 * stored case: a shared parser could only ever validate the INTERSECTION of every stack language, and for
 * brackets vs RPN that intersection is "a non-empty string". A stored program's own validation lives inside
 * its `run`, which is the only place that knows which language it reads.
 *
 * @throws Error (shown under the field) when the text is blank.
 */
export function parseStackText(text: string): string {
  const t = text.trim();
  if (t.length === 0) throw new Error("Enter an expression to trace");
  return t;
}

// Stack detection (#848 / #1710): the single regex-based matcher over a project's stack-section
// prose. Two consumers share it — `deriveTopics` (→ GitHub repo topics) and `gettingStartedCmds`
// (→ the README's install/run commands). Kept as TS (RegExp literals, not JSON) so the patterns
// stay first-class and case-insensitive whole-word matching is expressible.

/**
 * Test a stack-pattern against already-lowercased stack text. Centralizes the match step so both
 * the topic map and the getting-started toolchains run through one place.
 */
function matchesStack(lowerText: string, re: RegExp): boolean {
  return re.test(lowerText);
}

// Curated stack-keyword → GitHub-topic-slug map. Matched case-insensitively as whole words
// against the stack section text, so prose like "React 18 + TypeScript, Rust (Tauri)" yields
// `react`, `typescript`, `rust`, `tauri`. Lowercase-hyphenated per the topic-hygiene guide.
export const STACK_TOPICS: [RegExp, string][] = [
  [/\breact\b/, "react"], [/\bnext\.?js\b/, "nextjs"], [/\bvue\b/, "vue"], [/\bsvelte\b/, "svelte"],
  [/\bangular\b/, "angular"], [/\btypescript\b/, "typescript"], [/\bjavascript\b/, "javascript"],
  [/\bnode(\.?js)?\b/, "nodejs"], [/\bdeno\b/, "deno"], [/\bbun\b/, "bun"], [/\bvite\b/, "vite"],
  [/\brust\b/, "rust"], [/\btauri\b/, "tauri"], [/\bgo(lang)?\b/, "go"], [/\bpython\b/, "python"],
  [/\bdjango\b/, "django"], [/\bflask\b/, "flask"], [/\bfastapi\b/, "fastapi"], [/\bruby\b/, "ruby"],
  [/\brails\b/, "rails"], [/\bjava\b/, "java"], [/\bspring\b/, "spring-boot"], [/\bkotlin\b/, "kotlin"],
  [/\bswift\b/, "swift"], [/\bc\+\+\b/, "cpp"], [/\bc#\b/, "csharp"], [/\b\.net\b/, "dotnet"],
  [/\bpostgres(ql)?\b/, "postgresql"], [/\bmysql\b/, "mysql"], [/\bsqlite\b/, "sqlite"],
  [/\bmongo(db)?\b/, "mongodb"], [/\bredis\b/, "redis"], [/\bduckdb\b/, "duckdb"],
  [/\bgraphql\b/, "graphql"], [/\bdocker\b/, "docker"], [/\bkubernetes\b|\bk8s\b/, "kubernetes"],
  [/\btailwind\b/, "tailwindcss"], [/\bexpo\b/, "expo"], [/\breact native\b/, "react-native"],
];

// Toolchain → install/run commands, matched against the stack text the same way as STACK_TOPICS.
// First entry whose pattern hits contributes its commands; multiple may match (e.g. Tauri → both
// npm and cargo). Falls back to a generic comment when nothing is recognized.
const STACK_TOOLCHAINS: [RegExp, string[]][] = [
  [/\bnode(\.?js)?\b|\bnpm\b|\bvite\b|\breact\b|\bnext\b|\btypescript\b|\btauri\b/, ["npm install", "npm run dev"]],
  [/\bcargo\b|\brust\b|\btauri\b/, ["cargo build", "cargo run"]],
  [/\bpython\b|\bdjango\b|\bflask\b|\bfastapi\b/, ["pip install -r requirements.txt"]],
  [/\bgo(lang)?\b/, ["go mod download", "go run ."]],
];

/**
 * Derive GitHub repo topics from the stack section text, plus any explicit extras. Whole-word,
 * case-insensitive; deduped; lowercase-hyphenated; capped at GitHub's 20-topic limit. NB: these
 * are GitHub *repo topics*, distinct from the planner's discovery "topics".
 */
export function deriveTopics(stackText: string, extra: string[] = []): string[] {
  const found: string[] = [];
  const text = stackText.toLowerCase();
  for (const [re, topic] of STACK_TOPICS) {
    if (matchesStack(text, re)) found.push(topic);
  }
  const clean = (t: string) => t.trim().toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, "");
  const all = [...found, ...extra.map(clean)].filter(Boolean);
  return [...new Set(all)].slice(0, 20);
}

/**
 * A stack-aware Getting-started body. Detects the toolchain from the stack text and emits the
 * right install/run commands (npm / cargo / pip / go), falling back to a generic comment when
 * nothing is recognized. Returns the lines *inside* the ```bash fence (clone is added by the caller).
 */
export function gettingStartedCmds(stackText: string): string[] {
  const s = stackText.toLowerCase();
  const out: string[] = [];
  for (const [re, cmds] of STACK_TOOLCHAINS) {
    if (matchesStack(s, re)) out.push(...cmds);
  }
  return out.length ? out : ["# install dependencies and run the project's build/test/dev commands"];
}

// The `stack` viz kit's MOTION wiring (#3266, epic #3220/#2942) — injects the compiled motion CSS
// (push / pop / peek) into the live StackView. The animation DATA lives in a SHARED, feature-agnostic home
// (`@/shared/ui/kit/stackVizAnimations`) so BOTH consumers read ONE definition: this renderer AND a
// (later) `stack-viz` Designs builtin kit. `StackView`'s root carries the applying classes ({@link
// STACK_VIZ_ANIM_CLASSES}); its cells only stamp `data-op`. Mirrors matrixViewMotion / arrayViewMotion.
import { animClassName, compileAnimationsCss, kitAnimations } from "@/shared/ui/kit";
import { STACK_VIZ_KIT_ID, STACK_VIZ_ANIMATIONS } from "@/shared/ui/kit/stackVizAnimations";

// Re-export the shared data so this renderer's public surface (and the algorithms barrel) is unchanged.
export { STACK_VIZ_KIT_ID, STACK_VIZ_ANIMATIONS };

/** The applying classes the renderer's root carries so the state-scoped rules match its cells. */
export const STACK_VIZ_ANIM_CLASSES: string = STACK_VIZ_ANIMATIONS.map((a) =>
  animClassName({ kit: STACK_VIZ_KIT_ID, name: a.name }),
).join(" ");

/** The compiled motion CSS — produced ONCE from {@link STACK_VIZ_ANIMATIONS}. Pure. */
export const STACK_VIZ_MOTION_CSS: string = compileAnimationsCss(
  kitAnimations([{ id: STACK_VIZ_KIT_ID, animations: STACK_VIZ_ANIMATIONS }]),
);

const STYLE_ID = "bsc-stack-viz-animations";

/** Inject the compiled stack motion CSS into a dedicated managed `<style>` (idempotent). `doc` param'd for
 *  tests. Mirrors `ensureArrayViewMotion` on its own style id. */
export function ensureStackViewMotion(doc: Document = document): void {
  if (!STACK_VIZ_MOTION_CSS) return;
  let el = doc.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!el) {
    el = doc.createElement("style");
    el.id = STYLE_ID;
    doc.head.appendChild(el);
  }
  if (el.textContent !== STACK_VIZ_MOTION_CSS) el.textContent = STACK_VIZ_MOTION_CSS;
}

// The `stack-viz` kit's MOTION library as DATA (#3266, epic #3171/#2942) — the push / pop / peek
// animations for the stack/queue/deque renderer, authored as {@link KitAnimation} data and compiled by
// the kit-motion engine. The FIFO/LIFO twin of the array/matrix/graph motion sets.
//
// ── WHY THIS LIVES IN shared/ui/kit ──────────────────────────────────────────────────────────────────
// Like the array (#3194) + matrix/graph (#3242) sets: two consumers in two features, one definition — the
// Algorithms StackView renderer (`features/algorithms/.../stackViewMotion.ts`) injects the compiled CSS,
// and the Designs seed can register `stack-viz` as a recoverable builtin kit (a later slice). Feature-
// agnostic viz-motion, so it lives HERE to avoid a designs↔algorithms cycle.
//
// STATE-TRIGGER SEAM (#3058): each selector IS the data-state StackView stamps on the active-end cell
// (`[data-op="push"]`, …) — so a rule fires exactly when a cell enters/leaves the active end.

import type { KitAnimation } from "@/shared/ui/kit/animations";

/** The stack-visualization motion kit id — `.stack-viz-anim-<name>` + `@keyframes bsc-stack-viz-<name>`. */
export const STACK_VIZ_KIT_ID = "stack-viz";

/** The stack kit's animations as DATA — push (a cell drops in at the active end), pop (the cell leaving
 *  flashes as it goes), peek (a ring on the inspected cell). Token-based; the engine wraps each in
 *  `prefers-reduced-motion: no-preference`. The single source the StackView renderer + the (later)
 *  `stack-viz` Designs kit both consume. */
export const STACK_VIZ_ANIMATIONS: KitAnimation[] = [
  // push — a new entry drops in at the active end (scales up + fades in from the top).
  {
    name: "push",
    selector: '[data-op="push"]',
    duration: "420ms",
    easing: "cubic-bezier(0.34, 1.4, 0.5, 1)",
    set: { "z-index": "2" },
    keyframes: {
      "0%": { transform: "translateY(-10px) scale(0.7)", opacity: "0.25", "border-color": "var(--accent)" },
      "100%": { transform: "translateY(0) scale(1)", opacity: "1" },
    },
  },
  // pop — the entry now exposed at the active end flashes as the top one leaves.
  {
    name: "pop",
    selector: '[data-op="pop"]',
    duration: "400ms",
    easing: "var(--ease-standard)",
    keyframes: {
