// ── mcp ──────────────────────────────────────────────────────────────────────────
// The MCP server list + which are installed (runnable config present — the same
// `resolveAllInstalledMcp` set the desktop page derives). Env vars stay desktop-side
// (they can carry secrets).

export interface McpCard {
  id: string;
  name: string;
  enabled: boolean;
  transport: string;
  projects: string[];
  url?: string;
  /** The server has a runnable config (in the installed set). */
  installed: boolean;
}

export interface McpPayload {
  servers: McpCard[];
}

export function buildMcpPayload(input: {
  servers: McpServer[];
  /** Ids of the installed set (from `resolveAllInstalledMcp`, which includes built-ins). */
  installedIds: string[];
}): McpPayload {
  const installed = new Set(input.installedIds);
  return {
    servers: input.servers.map((s) => ({
      id: s.id, name: s.name, enabled: s.enabled, transport: s.transport,
      projects: s.projects, url: s.url, installed: installed.has(s.id),
    })),
  };
}

// ── security (#2530 / #3754) ───────────────────────────────────────────────────────
// The least-privilege picture the mobile Security page (#223) renders, READ-ONLY: the always-on
// application roles + the assignable agent profiles (#289 — the permission CONFIG: base policy ·
// command allowlist · per-tool tri-states · write-path scope · network HOST allowlist), a live
// console/pane model, the per-pane role + profile assignments, and recent audit activity (bsc-audit,
// #257). No secrets cross — `net` is a host allowlist (not credentials), and each audit row is a
// short/redacted display row, never a full tool input.
//
// #3754 closes the last mobile-Security gap: the audit `decision` (allow/ask/block) and the
// pane→console join are computed by the DESKTOP's single source of truth (buildAuditRows / the
// launch-gate rules) in the projector, so mobile never re-derives a security verdict.

/** Recent audit rows in the security payload — the desktop log keeps more; mobile shows a phone-sized
 *  window. Sized so the payload (re-pushed every 15s, each row now a full display row rather than a raw
 *  record) stays comfortably under the Noise transport's per-message cap (#3754). */
export const SECURITY_AUDIT_CAP = 50;

export interface SecurityProfileCard {
  id: string;
  name: string;
  category: string;
  desc: string;
  /** Base policy for anything not explicitly listed (deny | ask | allow). */
  mode: string;
  commands: string[];
  /** tool → tier (read/edit/bash/… → deny|ask|allow). */
  tools: Record<string, string>;
  paths: { allow: string[]; deny: string[] };
  /** Allowed network hosts — NOT credentials. */
  net: string[];
  builtin?: boolean;
  /** Swatch colour for the profile chip (#3754). */
  color: string;
  /** "built-in" | "user-defined" | "generated by Planner" — the origin chip (#3754). */
  origin?: string;
  // Application-role only (#3754): present on {@link SecurityPayload.appRoles}, undefined (dropped from
  // the wire JSON) on a plain assignable profile.
  surface?: string;
  surfaceGlyph?: string;
  session?: string;
  owns?: string;
}

/** A console summary (#3754): the INPUTS mobile needs to render "console / pane" and compute a pane's
 *  effective allowlist locally (guaranteed ∪ profile ∪ project ∪ repo — a plain set-merge, not policy
 *  logic). We send the inputs, not the resolved list; only the audit `decision` is desktop-authoritative. */
export interface SecurityConsoleCard {
  id: string;
  name: string;
  repo: string;
  projectAllow: string[];
  repoAllow?: string[];
  panes: { id: string; profileId: string }[];
}

export interface SecurityPayload {
  /** The always-on application singletons (Project Planner, …) the desktop lists FIRST. */
  appRoles: SecurityProfileCard[];
  profiles: SecurityProfileCard[];
  /** Live console/pane model — lets mobile resolve pane→console and the effective allowlist locally. */
  consoles: SecurityConsoleCard[];
  /** paneId → the SessionRole it launched under. Transient — empty before any fleet launch. */
  paneRoles: Record<string, string>;
  /** paneId → assigned agent-profile id. */
  paneProfiles: Record<string, string>;
  /** Recent audit DISPLAY rows (bsc-audit #257 → buildAuditRows), newest first, capped at
   *  {@link SECURITY_AUDIT_CAP}. Each carries the desktop-computed `decision` (allow/ask/block). */
  audit: AuditDisplayRow[];
}

/** Map an AgentProfile to its wire card — the permission config plus the swatch/origin and the
 *  app-role-only fields (undefined on a plain profile, so `JSON.stringify` drops them). */
function toSecurityProfileCard(p: AgentProfile): SecurityProfileCard {
  return {
    id: p.id, name: p.name, category: p.category, desc: p.desc, mode: p.mode,
    commands: p.commands,
    tools: Object.fromEntries(Object.entries(p.tools)),
    paths: { allow: p.paths.allow, deny: p.paths.deny },
    net: p.net.allow,
    builtin: p.builtin,
    color: p.color,
    origin: p.origin,
    surface: p.surface,
    surfaceGlyph: p.surfaceGlyph,
    session: p.session,
    owns: p.owns,
  };
}

export function buildSecurityPayload(input: {
  /** APP_ROLES — the always-on application singletons (rendered first). */
  appRoles: AgentProfile[];
  /** The assignable permission profiles (`s.agentProfiles`). */
  profiles: AgentProfile[];
  /** The live console/pane model, `deriveConsoles(...)` in the projector. */
  consoles: ConsoleSession[];
  paneRoles: Record<string, string>;
  paneProfiles: Record<string, string>;
  /** Pre-computed display rows (`buildAuditRows(...)` in the projector) — carry the desktop `decision`. */
  auditRows: AuditDisplayRow[];
}): SecurityPayload {
  return {
    appRoles: input.appRoles.map(toSecurityProfileCard),
    profiles: input.profiles.map(toSecurityProfileCard),
    consoles: input.consoles.map((c) => ({
      id: c.id, name: c.name, repo: c.repo,
      projectAllow: c.projectAllow,
      repoAllow: c.repoAllow,
      panes: c.panes.map((p) => ({ id: p.id, profileId: p.profileId })),
    })),
    paneRoles: input.paneRoles,
    paneProfiles: input.paneProfiles,
    audit: input.auditRows.slice(0, SECURITY_AUDIT_CAP),
  };
}

// ── alerts ───────────────────────────────────────────────────────────────────────

export interface AlertsPayload {
  alerts: ReadonlyArray<AlertEvent>;
}

export function buildAlertsPayload(inbox: ReadonlyArray<AlertEvent>): AlertsPayload {
  return { alerts: inbox };
}

// Opt-in store resets for tests (#3836).
//
// The suite has no GLOBAL store reset, and it cannot have one: statically importing `@/store` into
// `setup.ts` pulls the store into all ~670 test files' module graphs and breaks 28 tests by
// load-order side effect alone (measured — keeping the import with the reset disabled reproduces
// every one). So resets are opt-in, and live here so a test file pays for the store import only if
// it already uses the store.
//
// Reach for these in a `beforeEach`. They exist because the recurring order-dependence bug is
// always the same shape: the file resets SOME store fields but not the one the test reads, so a
// sibling test's mutation leaks forward. `--sequence.shuffle` is what exposes it.

import { useAppStore } from "@/store";

/**
 * Reset the PAGE-TAB state `usePageTabs` persists — the active tab per page key, the user's tab
 * order, and which sections are torn off.
 *
 * Any test that clicks a page tab mutates `activePageTab[pageKey]`, and every later test in the
 * file then renders THAT page instead of the default one — so an assertion about the default page
 * silently measures the wrong surface. A workspace test should call this in its `beforeEach` even
 * if it never clicks a tab itself, since a sibling might.
 */
export function resetPageTabs(): void {
  useAppStore.setState({ activePageTab: {}, pageTabOrder: {}, detachedSections: {} });
}

/**
 * Reset the per-pane fleet derivations a launch writes — the write-scope globs, the launched-stream
 * roster, and the per-pane skill/MCP assignments.
 *
 * A test that launches a fleet leaves these populated; a later test asserting on the globs of a
 * DIFFERENT project then reads the earlier launch's entries.
 */
export function resetFleetPanes(): void {
  useAppStore.setState({ paneRoleGlobs: {}, fleetPaneStreams: {}, paneSkills: {}, paneMcpServers: {} });
}

// The store's shape — re-export barrel for the per-domain store type modules.
//
// Formerly a ~817-line monolith (the AppStore interface + every value/config type). Split into
// focused per-domain modules under `store/types/` (#1634); this barrel re-exports them all so every
// existing `@/store/types` (and `../types`) import keeps resolving unchanged. Types-only; no runtime
// change — `AppStore` still `extends` the per-feature slice interfaces exactly as before.
export * from "@/store/types/github";
export * from "@/store/types/perf";
export * from "@/store/types/log";
export * from "@/store/types/console";
export * from "@/store/types/shell";
export * from "@/store/types/llm";
export * from "@/store/types/projects";
export * from "@/store/types/plan";
export * from "@/store/types/session";
export * from "@/store/types/appStore";

// Progress-gated relaunch (#1004): a triage / fleet re-run reads each issue's status from plan.db and
// must NOT restart a worker whose work is already done. These pure helpers decide, from the current
// issue statuses, which streams have finished and which still have outstanding work to (re)launch.

import type { AgentStream } from "@/features/planner/fleet/planFleet";
import type { PlanIssue } from "@/features/planner/issues/planIssues";

/** Refs of issues a worker has nothing left to do on — `complete` (landed) or `verified` (accepted). */
export function doneIssueRefs(issues: PlanIssue[]): Set<string> {
  return new Set(
    issues.filter((i) => i.status === "complete" || i.status === "verified").map((i) => i.ref),
  );
}

/**
 * Whether a project's BUILD is complete (#2619) — it has planned issues and EVERY one is done
 * (`complete` = landed, `verified` = accepted). The signal the "application complete" banner fires on:
 * all the planned work has landed, so the user can do a verify/preview run. An empty issue set is not
 * "complete" (nothing was planned yet). Pure.
 */
export function projectComplete(issues: PlanIssue[]): boolean {
  return issues.length > 0 && issues.every((i) => i.status === "complete" || i.status === "verified");
}

/**
 * A stream is complete when it owns at least one issue and EVERY one is done — so a relaunch puts its
 * worker into maintenance, not back to building (it already finished). A stream that owns no issues is
 * never "complete" (there's no
 * evidence of finished work; let it launch — e.g. a standing / open-ended worker).
 */
export function streamComplete(stream: AgentStream, done: Set<string>): boolean {
  return stream.issues.length > 0 && stream.issues.every((r) => done.has(r));
}

/**
 * Partition a fleet's streams for a progress-gated relaunch: `active` still have outstanding work and
 * (re)launch to keep building; `maintenance` already finished every owned issue and relaunch INTO the
 * maintenance posture (#1957) — they stay alive + ready for the director to dispatch new lane work,
 * rather than being skipped/ended. Order is preserved.
 */
export function pruneCompletedStreams(
  streams: AgentStream[],
  done: Set<string>,
): { active: AgentStream[]; maintenance: AgentStream[] } {
  const active: AgentStream[] = [];
  const maintenance: AgentStream[] = [];
  for (const st of streams) (streamComplete(st, done) ? maintenance : active).push(st);
  return { active, maintenance };
}

/**
 * Of the live worker panes (`fleetPaneStreams`: pane id → its stream), the ones whose stream has
 * finished every owned issue — so the always-on warden must NOT quarantine them: they're in
 * maintenance (#1957), not building, so post-completion activity is expected, not drift. The warden
 * also lifts any existing quarantine on these. `doneFor(paneId)` yields that pane's project's
 * done-issue refs (the warden reads issue statuses from plan.db per project). Pure (no IPC/store).
 */
export function completedWorkerPanes(
  fleetPaneStreams: Record<string, AgentStream>,
  doneFor: (paneId: string) => Set<string> | undefined,
): Set<string> {
  const out = new Set<string>();
  for (const [paneId, stream] of Object.entries(fleetPaneStreams)) {
    const done = doneFor(paneId);
    if (done && streamComplete(stream, done)) out.add(paneId);
  }
  return out;
}

// The dependency gate (#3931) — decide, from a fleet's `dependsOn` graph, which streams may START.
//
// #199 built a lost-wakeup-safe readiness model; #1039 removed its only producer (`bsc-blocked --on`),
// leaving half a circuit: workers still DECLARE COMPLETION, nothing declares DEPENDENCE. This reconnects
// it at LAUNCH rather than mid-task, which is what makes it compatible with #1039 — that issue's
// objection was that a PARKED worker is a worker not working, and nothing here ever parks a started
// session. A stream is simply not started until its upstreams have landed, and once started it never
// waits again.
//
// The launcher is also a better producer than the shell helper ever was: it reads `dependsOn` from
// plan.db, so dependence comes from the PLAN rather than from an agent remembering to run a command.
//
// ── What counts as "landed" ────────────────────────────────────────────────────────────────────────
// Measured on both live fleets before this was written, because the obvious answers are empty:
//
//   | signal                          | network-monitor | cli-typer |
//   |---------------------------------|-----------------|-----------|
//   | issues in plan.db               | 0               | 0         |
//   | coord-log events for the project| 0               | free-text refs, never `session:` |
//   | stream branches merged into HEAD| 38 / 38         | 3 / 10    |
//
// So an issue-keyed latch never satisfies, and a session latch is worse than useless — it HANGS: with
// zero coord events, `network-monitor` would start its 1 root stream and leave the other 37 dark
// forever. Branch-merge state is the signal that actually exists, so the rule is three tiers OR'd —
// each is independent positive evidence that the work is done, and requiring all three reproduces the
// hang this is meant to avoid:
//
//   1. ISSUES DONE   — owns issues and every one is complete/verified. Strongest; needs issues.
//   2. BRANCH MERGED — its branch is an ancestor of the clone's HEAD. The durable floor (#3931).
//   3. SESSION LATCH — a landed/merged/closed coord event on its session, or it is `maintaining`.
//
// Pure (no IO, no store) so the whole rule is exhaustively unit-testable; the callers probe the three
// signals and inject them.

/** The slice of a fleet stream this module reasons about. */
export interface GateStream {
  id: string;
  /** Upstream stream ids. Planning-time sequencing (#1039) — now also the launch gate. */
  dependsOn?: string[];
  /** Issue refs this stream owns. */
  issues?: string[];
}

/** The three landing signals, probed by the caller. */
export interface LandedEvidence {
  /** Issue refs that are `complete`/`verified` (see {@link doneIssueRefs}). */
  doneIssues: ReadonlySet<string>;
  /** Stream ids whose branch is merged into its clone's HEAD (`fleet_landed_streams`). */
  mergedBranches: ReadonlySet<string>;
  /** Stream ids whose SESSION reported done — a coord latch or the maintenance posture. */
  sessionDone: ReadonlySet<string>;
}

/** A stream held back by the gate, and what it is waiting for. */
export interface HeldStream {
  streamId: string;
  /** The unlanded upstreams it is waiting on. Empty only when `deadlocked`. */
  waitingOn: string[];
  /** True when the stream sits in a `dependsOn` CYCLE — it can never become ready on its own. */
  deadlocked: boolean;
}

export interface GatePartition {
  /** Every dep landed — start these now. */
  ready: GateStream[];
  /** Already landed — these relaunch into MAINTENANCE, not build. */
  landed: GateStream[];
  /** Not started; registered as waiters until their upstreams land. */
  held: HeldStream[];
}

/**
 * Which streams have LANDED — tier 1 OR tier 2 OR tier 3 (see the module header for why it is an OR).
 *
 * Tier 1 mirrors `streamComplete`: a stream must own at least one issue for its issue set to be
 * evidence — a stream with no issues has nothing to be "all done", so an empty `issues[]` is NOT
 * vacuous completion. Without that guard every stream on a 0-issue fleet would read as finished.
 */
export function landedStreams(streams: readonly GateStream[], ev: LandedEvidence): Set<string> {
  const out = new Set<string>();
  for (const s of streams) {
    const issues = s.issues ?? [];
    const byIssues = issues.length > 0 && issues.every((r) => ev.doneIssues.has(r));
    if (byIssues || ev.mergedBranches.has(s.id) || ev.sessionDone.has(s.id)) out.add(s.id);
  }
  return out;
}

/**
 * The stream ids that can never become ready because they sit in (or downstream of) a `dependsOn`
 * cycle among UNLANDED streams. A landed stream breaks a cycle — its dep edges no longer matter — so
 * the search runs over the unlanded subgraph only.
 *
 * Iterative Kahn peel rather than an SCC pass: repeatedly remove unlanded streams whose deps are all
 * satisfiable, and whatever cannot be peeled is either in a cycle or downstream of one. Both cases are
 * equally stuck and equally worth surfacing, so they are reported together (#3931 slice 4 renders them).
 */
export function deadlockedStreams(streams: readonly GateStream[], landed: ReadonlySet<string>): Set<string> {
  const unlanded = streams.filter((s) => !landed.has(s.id));
  const known = new Set(streams.map((s) => s.id));
  // Seed with everything already satisfiable: landed streams, plus any dep naming a stream that isn't
  // in this fleet at all (a dangling id can never land, but it also isn't a CYCLE — treating it as a
  // cycle would mislabel a plan typo as a deadlock, so it stays a plain unmet dep).
  const settled = new Set<string>(landed);
  let progressed = true;
  const remaining = new Map(unlanded.map((s) => [s.id, s.dependsOn ?? []]));
  while (progressed) {
    progressed = false;
    for (const [id, deps] of remaining) {
      // A dep outside the fleet is not resolvable here — it blocks, but it is not a cycle. Skip it
      // for the peel so it doesn't make its dependents look deadlocked.
      if (deps.every((d) => settled.has(d) || !known.has(d))) {
        settled.add(id);
        remaining.delete(id);
        progressed = true;
      }
    }
  }
  return new Set(remaining.keys());
}

/**
 * Partition a fleet for launch: what starts now, what is already done, and what waits.
 *
 * Readiness does NOT cascade within one pass — a stream is ready only when every dep has actually
 * LANDED, never when a dep is merely *about to start*. That is the whole point of the gate: `B` waits
 * for `A` to finish, not for `A` to launch. Order is preserved within each bucket.
 */
export function partitionByDeps(streams: readonly GateStream[], ev: LandedEvidence): GatePartition {
  const landedIds = landedStreams(streams, ev);
  const deadlocked = deadlockedStreams(streams, landedIds);
  const ready: GateStream[] = [];
  const landed: GateStream[] = [];
  const held: HeldStream[] = [];
  for (const s of streams) {
    if (landedIds.has(s.id)) { landed.push(s); continue; }
    const waitingOn = (s.dependsOn ?? []).filter((d) => !landedIds.has(d));
    if (waitingOn.length === 0) { ready.push(s); continue; }
    held.push({ streamId: s.id, waitingOn, deadlocked: deadlocked.has(s.id) });
  }
  return { ready, landed, held };
}

/** A user-facing reason for why a stream is held — the string the Glance node overlay shows (#3931). */
export function heldReason(h: HeldStream): string {
  const list = h.waitingOn.join(", ");
  if (h.deadlocked) return `dependency cycle — cannot start (waiting on ${list})`;
  return h.waitingOn.length === 1
    ? `waiting on ${list} to land`
    : `waiting on ${h.waitingOn.length} upstreams to land (${list})`;
}

/**
 * Tier 3's producer: the stream ids of a project's sessions that reported DONE (#3931 slice 3).
 *
 * A worker that finishes its lane parks in maintenance (#1957) by emitting `bsc-maintain`, which the
 * coord replay folds into `CoordState.maintaining`. That is the one per-session completion signal that
 * is actually populated in the live log — unlike `landed`, whose payload refs are free text and whose
 * emitting session is dropped by the parse. Entries are pane ids (`<projectKey>:<streamId>`), so this
 * keeps only the rows for THIS project and strips the prefix back to a stream id.
 *
 * Matching is on the exact `<projectKey>:` prefix, and only the FIRST separator is consumed — a triage
 * pane (`<key>:<repo>:triage`) therefore yields `<repo>:triage`, which is not a stream id and simply
 * never matches a `dependsOn` entry. Pure.
 */
export function sessionDoneStreams(
  maintaining: ReadonlyArray<{ session: string }>,
  projectKey: string,
): Set<string> {
  const prefix = `${projectKey}:`;
  const out = new Set<string>();
  for (const m of maintaining) {
    if (m.session.startsWith(prefix)) {
      const id = m.session.slice(prefix.length);
      if (id) out.add(id);
    }
  }
  return out;
}

/**
 * Merge K differently-shaped event streams into ONE recent-first feed, with a distinguished class
 * pinned ABOVE the time sort, plus a count per kind.
 *
 * The shape behind every "activity" / "what needs attention" panel that draws from several sources at
 * once (errors, warnings, denials, …). Three things it gets right that the hand-written version gets
 * wrong under maintenance:
 *
 * 1. **Heterogeneous in, homogeneous out.** Each stream has its OWN shape and its own projection to a
 *    common item; the merge never sees the source shapes. Adding a stream is adding a `(source,
 *    project)` pair, not editing a growing sort.
 * 2. **A pinned class outranks recency.** Some items are LIVE ("this is happening now") and must sit
 *    at the top regardless of timestamp — a currently-stalled worker above yesterday's resolved error.
 *    Modelled as a real flag (`pinned`), not the sentinel `sortKey: Infinity` the original used, which
 *    silently breaks the moment a second pinned item needs ordering among its peers.
 * 3. **Counts come from the merged feed, not recomputed.** One pass, so the badge can never disagree
 *    with the list it summarises.
 *
 * Sort is STABLE within a rank: pinned-vs-unpinned first, then `sortKey` descending, ties keeping
 * input order — so equal-timestamp items don't reshuffle between renders. Harvested from the Fleet
 * page's health panel (#3462/#3465).
 */

/** One normalized feed entry. `kind` is the caller's classification (counted); `pinned` lifts it above
 *  the time sort; `sortKey` orders the rest (a timestamp, descending = newest first). */
export interface FeedItem<TKind extends string> {
  kind: TKind;
  pinned: boolean;
  sortKey: number;
}

/** One input stream: its raw items plus how to project each to a {@link FeedItem}. Generic over the
 *  source shape AND the extra payload `P` the projection carries through (label, detail, …). */
export interface FeedStream<TKind extends string, P> {
  items: readonly unknown[];
  project: (raw: unknown) => (FeedItem<TKind> & P) | null;
}

/** Build one typed stream — a small helper so the source type is inferred rather than cast at the
 *  call site (each stream keeps its own element type until `project` normalizes it). */
export function feedStream<TRaw, TKind extends string, P>(
  items: readonly TRaw[],
  project: (raw: TRaw) => (FeedItem<TKind> & P) | null,
): FeedStream<TKind, P> {
  return { items, project: (raw) => project(raw as TRaw) };
}

/** The merged result: the ordered feed and a count per kind (every kind in `kinds` present, zeros
 *  included, so a caller can render a fixed set of badges without guarding for missing keys). */
export interface MergedFeed<TKind extends string, P> {
  items: Array<FeedItem<TKind> & P>;
  counts: Record<TKind, number>;
  total: number;
  hasItems: boolean;
}

/**
 * Merge the streams into one ordered feed with per-kind counts.
 *
 * `kinds` is the closed set of classifications, passed IN so `counts` has a zero for every one — the
 * feed alone can only count kinds that occurred, and a badge row that appears and disappears with the
 * data is worse than one that reads `0`.
 *
 * A stream's `project` returning null drops that raw item (a "done" verdict is not an error), so
 * filtering is part of the projection rather than a separate pass the caller has to remember.
 */
export function mergeFeeds<TKind extends string, P>(
  streams: ReadonlyArray<FeedStream<TKind, P>>,
  kinds: readonly TKind[],
): MergedFeed<TKind, P> {
  const items: Array<FeedItem<TKind> & P> = [];
  for (const stream of streams) {
    for (const raw of stream.items) {
      const item = stream.project(raw);
      if (item) items.push(item);
    }
  }
  // Stable: pinned first, then newest first, ties keeping insertion order (Array.sort is stable).
  items.sort((a, b) => (a.pinned === b.pinned ? b.sortKey - a.sortKey : a.pinned ? -1 : 1));

  const counts = Object.fromEntries(kinds.map((k) => [k, 0])) as Record<TKind, number>;
  for (const it of items) counts[it.kind] += 1;

  return { items, counts, total: items.length, hasItems: items.length > 0 };
}

// Stream ⇄ persona resolution (#2094) — a fleet stream may reference a PERSONA (its behavioral
// identity); at launch the persona resolves the stream's role (overriding the default `worker`),
// start prompt, skills, and model. This module is the pure resolution: look up the persona and build
// its role-aware kickoff. `buildStreamPrompt` (the historical worker kickoff) stays for persona-less
// streams; a persona stream gets THIS kickoff instead, so a read-only reviewer/documentor stream isn't
// handed the worker's "own your globs, open a PR" prose.
import type { Persona } from "@/features/personas";
import { roleCapability, hasScopedWriteCarveOut } from "@/shared/lib/session/sessionRoles";
import { resolveFlow } from "@/features/planner/fleet/agentFlow";
import { flowKickoffText } from "@/features/planner/fleet/flowKickoff";
import { strategySettings, DEFAULT_STRATEGY, type IntegrationStrategy } from "@/features/planner/lib/integrationStrategy";
import type { AgentStream } from "@/features/planner/fleet/planFleet";
import personaKickoffEmbedded from "@data/fleet/persona-kickoff.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";
import { fillTemplate } from "@/shared/lib/core/template";

// The kickoff PROSE (the role-agnostic scope paragraph, the read-only closing, and the owns/issues
// fallbacks) is externalized to `@data/fleet/persona-kickoff.json` (#2416) — editable without touching
// code + part of the exportable config bundle; the config-dir copy (#2047) overlays the embedded
// default via `overlayFile`. This module keeps only the interpolation (`{{STREAM_NAME}}`/`{{BRANCH}}`/
// `{{ISSUES}}`/`{{OWNS}}`/`{{CLOSING}}`) and the role/flow resolution that computes the closing.
const KICKOFF_PROSE = overlayFile("fleet/persona-kickoff.json", personaKickoffEmbedded);

/** The persona a stream references, or `undefined` (no reference, or an unknown/stale id). */
export function resolveStreamPersona(personas: Persona[], stream: AgentStream): Persona | undefined {
  return stream.persona ? personas.find((p) => p.id === stream.persona) : undefined;
}

/** Whether a role may write files or push — drives whether the kickoff carries the worker autonomy/push
 *  prose or the read-only "report, don't commit" instruction. Includes the scoped-write carve-out
 *  (#851/#1555) so a documentor (code:"none" + DOC_GLOBS) is briefed to WRITE its docs and open a
 *  flow-governed docs PR, not treated as a read-only reviewer. */
function roleWrites(role: Persona["role"]): boolean {
  const cap = roleCapability(role);
  return cap.code === "write" || cap.git === "write" || hasScopedWriteCarveOut(cap);
}

/**
 * The kickoff for a persona stream: the persona's own start prompt (its identity/behavior) followed by
 * the role-AGNOSTIC scope facts every stream needs (its worktree branch, assigned issues, owned paths,
 * contracts + checkpoint discipline), then either the worker autonomy/push paragraph (writing roles) or
 * the read-only reporting instruction (reviewer/juror/…). So a documentor/reviewer stream is briefed as
 * itself, not as a code-writing worker.
 */
export function personaStreamPrompt(
  persona: Persona, stream: AgentStream, strategy?: IntegrationStrategy,
): string {
  const owns   = stream.owns.length   ? stream.owns.join(", ")   : KICKOFF_PROSE.ownsFallback;
  const issues = stream.issues.length ? stream.issues.join(", ") : KICKOFF_PROSE.issuesFallback;
  const intro = persona.startPrompt.trim();
  const strat = strategy ?? DEFAULT_STRATEGY;
  const closing = roleWrites(persona.role)
    ? (() => {
        const effFlow = { ...resolveFlow(stream.flow), push: stream.flow?.push ?? strategySettings(strat).integrate };
        const kick = flowKickoffText(effFlow, stream.id);
        return `${kick.autonomy} ${kick.push}`;
      })()
    : KICKOFF_PROSE.readOnlyClosing;
  return (
    (intro ? `${intro}\n\n` : "") +
    fillTemplate(KICKOFF_PROSE.scope, {
      STREAM_NAME: stream.name,
      BRANCH: stream.id,
      ISSUES: issues,
      OWNS: owns,
      CLOSING: closing,
    })
  );
}

// Per-stream issue progress (#4050) — how far through its owned work each fleet worker is.
//
// ── WHY ISSUES, AND NOT "PROGRESS THROUGH THE CURRENT ISSUE" ─────────────────────────────────────
// Because `done / owned` is a FACT. An agent does not emit a percentage-complete, so a bar measuring
// progress within a task would be an estimate dressed as a measurement — and a confidently wrong one,
// which is worse than no bar at all.
//
// ── ONE READ, PARTITIONED IN MEMORY ─────────────────────────────────────────────────────────────
// `OwnedIssue` carries its `stream`, and its own doc names this use: read a project's issues ONCE and
// partition by stream here, rather than querying per stream. Per-node reads are the N-per-pane fan-out
// shape that has repeatedly cost real time in this app (#3908 / #3912 / #3944 / #3954).

import { TERMINAL_GOOD, type OwnedIssue } from "@/shared/lib/fleet/workerEnd";

/** One stream's completion, as counts — never a pre-computed ratio, so a caller can render "3/7" as
 *  readily as a bar and neither has to reconstruct the other. */
export interface StreamProgress {
  done: number;
  total: number;
}

/**
 * Partition a project's issues into per-stream `done / total`.
 *
 * Issues with no `stream` are skipped: unowned work belongs to no worker, so counting it would make
 * every node's denominator wrong in the same invisible way.
 *
 * Done-ness is `TERMINAL_GOOD` (`complete` | `verified`) — the SAME set `classifyWorkerEnd` uses for
 * its verdict. A second definition here would eventually disagree with the card that says "finished".
 */
export function streamProgress(issues: readonly OwnedIssue[]): Map<string, StreamProgress> {
  const out = new Map<string, StreamProgress>();
  for (const i of issues) {
    const stream = i.stream?.trim();
    if (!stream) continue;
    const cur = out.get(stream) ?? { done: 0, total: 0 };
    cur.total += 1;
    if (TERMINAL_GOOD.has(i.status)) cur.done += 1;
    out.set(stream, cur);
  }
  return out;
}

/**
 * Refs of the issues plan.db considers FINISHED (#4102).
 *
 * Same `TERMINAL_GOOD` definition `streamProgress` counts with, exposed as refs so plan.db's evidence
 * can be unioned with the GitHub overlay into one done-set (`unionDone`). Deliberately NOT a second
 * notion of done-ness — `streamCompletion.ts` already made the point that a divergent definition
 * eventually disagrees with the card that says "finished".
 */
export function planDbDoneRefs(issues: readonly OwnedIssue[]): Set<string> {
  const out = new Set<string>();
  for (const i of issues) if (TERMINAL_GOOD.has(i.status)) out.add(i.ref);
  return out;
}

/**
 * Per-ref closed-ness from plan.db — `ref → true` when finished, `false` when it demonstrably is not.
 *
 * The distinction from {@link planDbDoneRefs} is the FALSE, and it is the whole point: a done-set can
 * only say "finished" or "not in the set", and "not in the set" conflates *this issue is open* with
 * *I have never heard of this issue*. The Plan dock has to tell those apart, because the first is a
 * state worth rendering and the second is the only one worth asking the user to connect GitHub for.
 *
 * Same `TERMINAL_GOOD` definition every other done-count uses — a second notion of done-ness here
 * would eventually let the node's bar and its issue list disagree, which is exactly the bug this fixes.
 */
export function planDbClosedByRef(issues: readonly OwnedIssue[]): Map<string, boolean> {
  const out = new Map<string, boolean>();
  for (const i of issues) out.set(i.ref, TERMINAL_GOOD.has(i.status));
  return out;
}

/** The fill fraction, clamped to 0..1. `total === 0` ⇒ 0 (and the caller should render NO bar at all —
 *  an empty bar and a zero-progress bar say different things, and only one of them is true). */
export function progressFraction(p: StreamProgress | undefined): number {
  if (!p || p.total <= 0) return 0;
  return Math.max(0, Math.min(1, p.done / p.total));
}

/**
 * Attach each node's stream progress. A fleet node's id IS its stream id, which is what lets this be a
 * plain map lookup rather than another join.
 *
 * Returns the SAME array when nothing matched, so a project with no plan store (or a read that has not
 * landed yet) does not invalidate the memo that renders the graph.
 */
export function withStreamProgress<T extends { id: string; progress?: StreamProgress }>(
  nodes: readonly T[],
  byStream: ReadonlyMap<string, StreamProgress>,
): T[] {
  if (byStream.size === 0) return [...nodes];
  return nodes.map((n) => {
    const p = byStream.get(n.id);
    return p ? { ...n, progress: p } : n;
  });
}

/**
 * The project's progress across EVERY issue — including those no stream owns.
 *
 * `glance-progress-ref-namespace-split`. {@link streamProgress} deliberately SKIPS unowned issues,
 * because attributing them to a worker would make that worker's denominator wrong. But the project as a
 * whole owns all of them, so summing the per-stream rows is not the project's number and never was:
 * `studio-code` reads 24 issues here and 56 stream-owned refs there, and the two levels of the graph
 * showed those two numbers side by side with nothing to say they measured different things.
 *
 * Deliberately the SAME `complete | verified` definition as every other done-count in this file, and the
 * same one `bsc project progress` uses for the L0 node — so the director's bar and the project node's
 * bar are the same fact rather than two estimates that happen to agree.
 */
export function projectProgress(issues: readonly OwnedIssue[]): StreamProgress {
  let done = 0;
  for (const i of issues) if (TERMINAL_GOOD.has(i.status)) done += 1;
  return { done, total: issues.length };
}

// Thin resident in-frame runtimes for streaming renderers (#581 PV-stream / PV-gltf).
// Each runtime is a self-contained HTML string baked into a persistent iframe.
// The host sends commands via postMessage; the runtime signals back via parent.postMessage.
//
// Delivery contract:
//   host → frame: { __preview_cmd: 'render_bundle', bundleJs: string, importmap?: Record<string,string> }
//                 { __preview_cmd: 'render_gltf',   url?: string, base64?: string }
//   frame → host: { __preview: 'ready' | 'error' | 'runtime_ready', message?: string }

import { DEFAULT_IMPORTMAP } from '@/features/planner/preview/previewBundle';

/**
 * Builds the srcdoc for the streaming html/react-bundle iframe. The thin runtime:
 * - Signals `{ __preview: 'runtime_ready' }` once loaded.
 * - On `render_bundle`: clears #root, creates a blob URL from bundleJs, dynamically
 *   imports it (React + esm.sh externals resolved via import-map), then signals ready.
 * - Falls back to `render_srcdoc` for a full document replace (legacy support).
 */
export function buildStreamingFrameHtml(importmap: Record<string, string> = DEFAULT_IMPORTMAP): string {
  const im = JSON.stringify({ imports: importmap });
  return `<!doctype html><html><head><meta charset="utf-8"/>
<style>html,body,#root{margin:0;height:100%;background:var(--bg,#0d0d0f);font-family:Inter,system-ui,sans-serif;color:#eee}</style>
<script type="importmap">${im}</script>
</head><body><div id="root"></div>
<script>
var _bscRoot=null;
window.addEventListener('message',async function(e){
  var d=e.data;
  if(!d)return;
  if(d.__preview_cmd==='render_bundle'){
    try{
      if(_bscRoot){try{_bscRoot.unmount();}catch(_){}_bscRoot=null;}
      document.getElementById('root').innerHTML='';
      var blob=new Blob([d.bundleJs],{type:'text/javascript'});
      var url=URL.createObjectURL(blob);
      await import(url);
      URL.revokeObjectURL(url);
      parent.postMessage({__preview:'ready'},'*');
    }catch(err){
      parent.postMessage({__preview:'error',message:String(err)},'*');
    }
  }
  // Legacy full-document replace — for srcDoc payloads without extracted bundleJs.
  if(d.__preview_cmd==='render_srcdoc'){
    try{document.open();document.write(d.html);document.close();}catch(err){
      parent.postMessage({__preview:'error',message:String(err)},'*');
    }
  }
});
parent.postMessage({__preview:'runtime_ready'},'*');
</script></body></html>`;
}

/**
 * Builds the srcdoc for the streaming glTF iframe. The thin runtime:
 * - Loads three.js + GLTFLoader from esm.sh and sets up a scene with orbit controls.
 * - On `render_gltf`: loads the model from a URL or base64 data URI, auto-fits the
 *   camera, and auto-rotates. Replaces the previous model on each call.
 */
export function buildGltfRuntimeHtml(): string {
  const threeUrl = DEFAULT_IMPORTMAP['three'] ?? 'https://esm.sh/three@0.169.0';
  const loaderUrl = `${threeUrl.replace(/\?.*$/, '')}/examples/jsm/loaders/GLTFLoader.js`;
  const controlsUrl = `${threeUrl.replace(/\?.*$/, '')}/examples/jsm/controls/OrbitControls.js`;
  const im = JSON.stringify({ imports: { three: threeUrl } });
  return `<!doctype html><html><head><meta charset="utf-8"/>
<style>html,body,canvas{margin:0;width:100%;height:100%;display:block;background:#0d0d0f;overflow:hidden}</style>
<script type="importmap">${im}</script>
</head><body>
<canvas id="c"></canvas>
<script type="module">
import*as THREE from 'three';
import{GLTFLoader}from'${loaderUrl}';
import{OrbitControls}from'${controlsUrl}';

const canvas=document.getElementById('c');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});
renderer.setPixelRatio(devicePixelRatio);
renderer.setSize(innerWidth,innerHeight);
renderer.outputColorSpace=THREE.SRGBColorSpace;

const scene=new THREE.Scene();
scene.background=new THREE.Color(0x0d0d0f);
const camera=new THREE.PerspectiveCamera(45,innerWidth/innerHeight,0.001,1000);
camera.position.set(0,1.5,3);

const ambient=new THREE.AmbientLight(0xffffff,0.8);
const dir=new THREE.DirectionalLight(0xffffff,1.2);
dir.position.set(2,4,3);
scene.add(ambient,dir);

const controls=new OrbitControls(camera,renderer.domElement);
controls.enableDamping=true;
controls.dampingFactor=0.05;

let model=null;
const loader=new GLTFLoader();

window.addEventListener('message',function(e){
  const d=e.data;
  if(d?.__preview_cmd!=='render_gltf')return;
  const url=d.url||('data:model/gltf+json;base64,'+d.base64);
  loader.load(url,function(gltf){
    if(model)scene.remove(model);
    model=gltf.scene;
    scene.add(model);
    const box=new THREE.Box3().setFromObject(model);
    const size=box.getSize(new THREE.Vector3()).length();
    const center=box.getCenter(new THREE.Vector3());
    model.position.sub(center);
    camera.near=size/100;camera.far=size*100;
    camera.position.set(0,size*0.4,size*1.2);
    camera.updateProjectionMatrix();
    controls.update();
    parent.postMessage({__preview:'ready'},'*');
  },undefined,function(err){
    parent.postMessage({__preview:'error',message:String(err)},'*');
  });
});

window.addEventListener('resize',function(){
  renderer.setSize(innerWidth,innerHeight);
  camera.aspect=innerWidth/innerHeight;
  camera.updateProjectionMatrix();
});

(function animate(){requestAnimationFrame(animate);controls.update();renderer.render(scene,camera);})();
parent.postMessage({__preview:'runtime_ready'},'*');
</script></body></html>`;
}

// Studio gist transport (#2891, slice 2 of the Studio epic #2889) — export/import a saved STUDIO (the
// app-library snapshot bundle from slice #2890) as a typed GitHub gist, reusing the SAME
// extension-manifest envelope + gist transport blueprints and component-kits already ship in
// (#598/#2305). A studio is already a self-contained JSON bundle, so distribution is one file: wrap it
// in the `studio` envelope, publish it as a gist (or read one back by URL/id). Pure envelope helpers
// (unit-testable) + Tauri-backed transport, mirroring `designs/lib/kitGist.ts`. Imports the manifest +
// gist helpers via the planner's PUBLIC barrel (`@/features/planner`), respecting the #1545 boundary.
import { wrapExtension, installFromGist, publishGist, type ExtensionManifest } from "@/features/planner";

/** The manifest kind a studio ships as. */
export const STUDIO_KIND = "studio" as const;

/**
 * A **Studio** — a self-contained, shareable snapshot of the app's library state. Mirrors the Rust
 * `bsc-studio` bundle: identity (`id` = a slug of `name`) + the extensible `snapshot` map, keyed by
 * system name (teams · personas · components · variants · themes · blueprints) → that store's records.
 */
export interface Studio {
  id: string;
  name: string;
  description?: string;
  version?: string;
  /** The captured library state, keyed by system → its records. Extensible; never trusted on import. */
  snapshot: Record<string, unknown[]>;
}

const str = (v: unknown, d = ""): string => (typeof v === "string" ? v : d);

/** Coerce an untrusted payload's `snapshot` into a plain object of arrays. A non-object (or an array —
 *  which JSON.parse yields for `[]`) ⇒ `{}`; each key keeps only the entries whose value is an array,
 *  and every element stays an opaque `unknown` (the snapshot is never structurally trusted). */
function coerceSnapshot(v: unknown): Record<string, unknown[]> {
  if (!v || typeof v !== "object" || Array.isArray(v)) return {};
  const out: Record<string, unknown[]> = {};
  for (const [key, val] of Object.entries(v as Record<string, unknown>)) {
    if (Array.isArray(val)) out[key] = val;
  }
  return out;
}

/** Wrap a studio in the typed extension envelope for publishing/sharing. */
export function studioToManifest(studio: Studio): ExtensionManifest<Studio> {
  return wrapExtension(STUDIO_KIND, studio.id, studio.name, studio.version ?? "1.0.0", studio, {
    description: studio.description,
  });
}

/** Reconstruct a sanitized Studio from a validated manifest, or an error when it's not a studio. Never
 *  trusts the payload shape: requires a non-empty `id` + `name`; a missing/malformed `snapshot` becomes
 *  `{}`. `description`/`version` ride when present. Mirrors blueprintShare's `manifestToBlueprint`. */
export function manifestToStudio(
  m: ExtensionManifest,
): { ok: true; studio: Studio } | { ok: false; error: string } {
  if (m.kind !== STUDIO_KIND) return { ok: false, error: `expected a studio, got '${m.kind}'` };
  const p = (m.payload ?? {}) as Record<string, unknown>;
  const id = str(p.id) || str(m.id);
  const name = str(p.name) || str(m.name);
  if (!id || !name) return { ok: false, error: "studio payload is malformed (need id and name)" };
  const studio: Studio = { id, name, snapshot: coerceSnapshot(p.snapshot) };
  const description = str(p.description) || str(m.description);
  if (description) studio.description = description;
  const version = str(p.version) || str(m.version);
  if (version) studio.version = version;
  return { ok: true, studio };
}

/**
 * Export a studio as a GitHub gist (needs a token with the `gist` scope). `public` makes it a shareable
 * public gist; the default is a secret gist. Returns the gist's web URL + id. Rejects are surfaced as
 * `{ ok: false, error }` so the caller never has to try/catch.
 */
export async function exportStudioToGist(
  studio: Studio,
  token: string,
  opts: { public?: boolean } = {},
): Promise<{ ok: true; url: string; id: string } | { ok: false; error: string }> {
  try {
    const res = await publishGist(token, studioToManifest(studio), { public: opts.public });
    return { ok: true, url: res.htmlUrl, id: res.id };
  } catch (e) {
    return { ok: false, error: String(e) };
  }
}

/**
 * Import a studio from a gist URL/id (public/secret gists need no auth; `token` raises the rate limit /
 * reads a private gist). `installFromGist` fetches AND validates the envelope (it returns a
 * `ValidateResult`); a valid envelope is then coerced into the studio payload.
 */
export async function importStudioFromGist(
  urlOrCode: string,
  token = "",
): Promise<{ ok: true; studio: Studio } | { ok: false; error: string }> {
  const res = await installFromGist(urlOrCode, token);
  return res.ok ? manifestToStudio(res.manifest) : res;
}

// Public API of the studio feature (#2889) — a Studio is the top-level shareable bundle: a
// self-contained snapshot of the app's library state (teams · personas · components · variants ·
// themes · blueprints). Slice #2891 adds gist export/import over the shared extension-manifest
// envelope, mirroring blueprints + component-kits. Cross-feature, import ONLY through this barrel.
export {
  STUDIO_KIND,
  studioToManifest,
  manifestToStudio,
  exportStudioToGist,
  importStudioFromGist,
  type Studio,
} from "@/features/studio/lib/studioGist";

// The studio-network pump's PURE decision core (#2940). The app-owned studio sessions
// (planner · designer · librarian) commission artifacts from each other over `coord.log`
// (the `commission`/`deliver` edge, slice 1). This module turns the folded `CoordState.commissions`
// into the two actuations the pump performs — with NO React, Tauri, or timers — so every routing
// rule is unit-tested. The thin actuator (`useStudioNetworkPump`) owns polling, `injectPrompt`,
// the once-guards, and the lazy-mount store flag.
//
// The two actuations:
//   1. AUTHOR TASK — an open, undelivered commission's spec is injected into the TARGET studio
//      session (designer → `bsc ui`, librarian → `bsc graph`), once the target has been reachable
//      long enough to accept input (the settle gate; Claude queues input typed mid-turn).
//   2. DELIVER-BACK — once a `deliver` stamps `delivered` on a commission, the authored artifact id
//      is injected back into the REQUESTER's pane (which is the live planning/designer session).
import type { OpenCommission } from "@/shared/lib/fleet/coordination.types";
import { refKey } from "@/shared/lib/fleet/coordinationState";
import { designerSessionId, librarianSessionId } from "@/shared/lib/session/systemSessions";

/** The commissionable studio nodes. The planner is a requester, never a target (plan-only). */
export type StudioTarget = "designer" | "librarian";

/** Target → its app-owned studio session pane id (where the author task is injected).
 *
 *  #system-sessions-are-per-technology made these per-tech, but a COMMISSION does not carry a
 *  technology — the planner asks for "a component" or "an algorithm", not "a react component". So each
 *  target resolves to its DEFAULT technology: the one the app itself is built in, which is also what
 *  the overwhelming majority of generated apps use.
 *
 *  KNOWN LIMITATION, stated rather than hidden: a commission for a react-native component or a rust
 *  algorithm lands on the wrong session's queue. Fixing it properly means putting a `tech` on the
 *  commission (a coordination.types change + the emitters that write one), which is its own item —
 *  not something to smuggle into the registry split. */
export const STUDIO_PANE: Record<StudioTarget, string> = {
  designer: designerSessionId("react"),
  librarian: librarianSessionId("typescript"),
};

/** Human label + the store CLI a target authors into — for the injected task prose. */
const TARGET_KIT: Record<StudioTarget, { noun: string; list: string; deliver: string }> = {
  designer:  { noun: "component", list: "bsc ui list",         deliver: "bsc ui" },
  librarian: { noun: "algorithm", list: "bsc graph impl list", deliver: "bsc graph impl set" },
};

export function isStudioTarget(t: string): t is StudioTarget {
  return t === "designer" || t === "librarian";
}

/** A commission is "open" until a `deliver` stamps its artifact id. */
export function isOpen(c: OpenCommission): boolean {
  return c.delivered === undefined;
}

/** A stable per-commission key for the pump's once-guards (the commission id already is one). */
export function commissionKey(c: OpenCommission): string {
  return c.id;
}

/** Distinct studio targets that have at least one OPEN commission — the set of sessions the pump
 *  must keep reachable (drives the lazy-mount hosts). Unknown targets (a stray/bad line) are ignored. */
export function activeTargets(commissions: OpenCommission[]): StudioTarget[] {
  const out: StudioTarget[] = [];
  for (const c of commissions) {
    if (isOpen(c) && isStudioTarget(c.target) && !out.includes(c.target)) out.push(c.target);
  }
  return out;
}

/** The prompt injected into a target studio session to author (or reuse) the commissioned artifact.
 *  Reuse-first is baked in (slice 3 makes the requester check too); the deliver line closes the loop
 *  so the pump can route the id back. */
export function authorTaskPrompt(c: OpenCommission, target: StudioTarget): string {
  const t = TARGET_KIT[target];
  const ref = c.ref ? ` (ref: ${refKey(c.ref)})` : "";
  return (
    `A planning session commissioned a ${t.noun}${ref}: ${c.body}\n` +
    `First reuse-check with \`${t.list}\` — if an existing ${t.noun} fits, use it. ` +
    `Otherwise author it with \`${t.deliver}\`. ` +
    `When done, run \`bsc-deliver ${c.id} <${t.noun}Id>\` so the requester receives it.`
  );
}

/** The prompt injected back into the REQUESTER's pane once the target delivers. */
export function deliverBackPrompt(c: OpenCommission): string {
  const noun = isStudioTarget(c.target) ? TARGET_KIT[c.target].noun : "artifact";
  return (
    `The ${c.target} delivered the ${noun} you commissioned ("${c.body}"): ` +
    `\`${c.delivered}\`. You can bind/reference it now.`
  );
}

/** One actuation the pump should perform this tick. */
export interface Injection {
  paneId: string;
  prompt: string;
  /** Once-guard key (`author:<id>` / `deliver:<id>`) so the same message is never re-injected. */
  key: string;
}

/** AUTHOR-TASK injections due now: open, undelivered commissions to a known target whose session has
 *  been reachable for at least `settleMs` (so `pty_create` + boot are past) and which have not been
 *  injected yet. `activatedAt` maps target → the ms the pump first saw it active. */
export function authorInjections(
  commissions: OpenCommission[],
  activatedAt: Partial<Record<StudioTarget, number>>,
  now: number,
  settleMs: number,
  alreadyInjected: ReadonlySet<string>,
): Injection[] {
  const out: Injection[] = [];
  for (const c of commissions) {
    if (!isOpen(c) || !isStudioTarget(c.target)) continue;
    const key = `author:${c.id}`;
    if (alreadyInjected.has(key)) continue;
    const since = activatedAt[c.target];
    if (since === undefined || now - since < settleMs) continue;
    out.push({ paneId: STUDIO_PANE[c.target], prompt: authorTaskPrompt(c, c.target), key });
  }
  return out;
}

/** DELIVER-BACK injections due now: commissions whose `delivered` is set and whose result has not
 *  been surfaced to the requester yet. The requester (`from`) is a live session (the planner/designer
 *  that emitted the commission), so no settle gate is needed. */
export function deliverBackInjections(
  commissions: OpenCommission[],
  alreadySurfaced: ReadonlySet<string>,
): Injection[] {
  const out: Injection[] = [];
  for (const c of commissions) {
    if (c.delivered === undefined) continue;
    const key = `deliver:${c.id}`;
    if (alreadySurfaced.has(key)) continue;
    out.push({ paneId: c.from, prompt: deliverBackPrompt(c), key });
  }
  return out;
}

// The app's OWN sessions in the Glance graph — the STUDIO NETWORK team (`org-planning-studio`, #3317)
// rendered through the existing Team→Glance adapter (`buildOrgFleetData`), plus one node per LIVE
// request session edged to whoever filed it (#debug-nodes-hang-off-the-session-that-filed-them).
// Pure + React-free so it's unit-testable.
//
// THE SYNTHETIC PROJECT NODE IS GONE (#the-app-drills-into-a-project-that-was-deleted). #3319 invented a
// fixed L0 node, `app:base-studio-code`, because the app had no project row of its own to hang these
// sessions off. It has one now: the `base-studio-code` hub was migrated into `studio-code` and deleted,
// so the phantom had become a SECOND node for the same app — and it was the one every studio session and
// every live debug session hung off, i.e. the deleted one. {@link withStudioSessions} folds them into the
// real project's drill instead, and nothing points at a key with no hub.
import { augmentStudioNetworkForRequests, requestNodeLabel, studioNetworkForArchitect, STUDIO_NETWORK_ID, type Team, type RequestNodeSpec, type OriginHostResolver } from "@/features/teams";
import { requestIdFromNodeId, requestNodeId, requestPaneId } from "@/shared/lib/session/requestSpawn";
import type { Persona } from "@/features/personas";
import {
  TEAMS_STUDIO_SESSION_ID, SOUND_STUDIO_SESSION_ID,
  INTEGRATION_STUDIO_SESSION_ID, LIBRARIAN_TECHS, DESIGNER_TECHS,
  librarianSessionId, designerSessionId,
} from "@/shared/lib/session/systemSessions";
import { buildOrgFleetData } from "@/features/glance/lib/glanceFleet";
import type { GlanceData } from "@/features/glance/lib/glanceData";
import type { GHealth, GActivity, GRawNode } from "@/features/glance/lib/glanceGraph";

/**
 * The plan key of the project THIS APP is developed in — the one whose drill also shows the app-owned
 * studio sessions ({@link withStudioSessions}).
 *
 * A real key, with a hub on disk, replacing the synthetic `app:base-studio-code` that had none. It is
 * still a constant rather than something derived, and deliberately so: nothing in the model says which
 * of a user's projects IS the app, and inventing a derivation (match a linked repo against the app's
 * source root, slugify the repo's folder name) would be a guess dressed as a rule — the app repo is
 * `base-studio-code` and the project is `studio-code`, so the obvious derivations are already wrong.
 * Making it user-designated is the next slice; recorded, not built.
 *
 * On an install with no such project this simply never matches, and the app-owned sessions stay reachable
 * through the ARCHITECT node's drill ({@link buildArchitectFleetData}), which renders the same team.
 */
export const APP_PROJECT_KEY = "studio-code";

/** Whether a drilled project key is the app's own — the one drill that also draws the studio sessions. */
export function isAppProject(key: string | null | undefined): boolean {
  return !!key && key === APP_PROJECT_KEY;
}

/**
 * The base-studio-code project's drilled graph — the Studio Network team's positions (the app-owned
 * studio sessions) as nodes and its relationships as edges, plus one node per LIVE request session,
 * each hanging off the session that filed its request. Returns `null` when the team isn't present (so
 * the caller falls back to the empty/sample graph rather than crashing). Pure.
 *
 * There is no standing `debugger` node any more (#debug-nodes-hang-off-the-session-that-filed-them) and
 * so no toggle parameter: debug work appears exactly when there is some, named for what it is.
 */
export function buildStudioFleetData(
  teams: readonly Team[],
  personas: Persona[],
  /** The live request sessions — each becomes its own labelled, openable node. */
  requests: readonly RequestNodeSpec[] = [],
): GlanceData | null {
  const team = teams.find((t) => t.id === STUDIO_NETWORK_ID);
  if (!team) return null;
  return buildOrgFleetData(augmentStudioNetworkForRequests(team, requests, studioNodeForOrigin), personas);
}

/**
 * Fold the app-owned SESSIONS (and the live request sessions hanging off them) into a project's fleet
 * graph (#the-app-drills-into-a-project-that-was-deleted) — so the app's own project drills into one
 * graph holding both its plan.db workers and the studios that build it, instead of the app owning a
 * second, synthetic project node beside it.
 *
 * ONLY the nodes that resolve to an app-owned pane are folded. That is exactly "a session you can open",
 * and it is also what makes the fold safe: the studio team's RESOURCE nodes are named for domains
 * (`algorithms`, `sounds`, `integrations`) and the app's own fleet has streams with those very ids, so
 * folding them would either be dropped as a collision or, worse, hand a studio's edges to an unrelated
 * worker. The libraries already have their own L0 home in the fenced band (#2571/#3133); the sessions
 * did not, which is the gap this closes. The team's `planner` position drops out by the same rule — it
 * has no fixed session, so it would draw a node that does nothing.
 *
 * An id already present in the fleet graph is left ALONE rather than merged over: a fleet stream that
 * happens to share a studio node's id is a different thing with the same name, and the fleet owns its
 * own drill. An edge survives only when BOTH its ends were folded, so a skipped node can never leave a
 * studio relationship pointing at a fleet cell.
 *
 * Idempotent, and a no-op when the Studio Network team is absent. Pure.
 */
export function withStudioSessions(
  data: GlanceData,
  teams: readonly Team[],
  personas: Persona[],
  requests: readonly RequestNodeSpec[] = [],
): GlanceData {
  const studio = buildStudioFleetData(teams, personas, requests);
  if (!studio) return data;
  const present = new Set(data.rawNodes.map((n) => n.id));
  const nodes = studio.rawNodes.filter((n) => !present.has(n.id) && !n.resource && !!studioPaneIdForNode(n.id));
  if (!nodes.length) return data;
  const folded = new Set(nodes.map((n) => n.id));
  return {
    ...data,
    rawNodes: [...data.rawNodes, ...nodes],
    rawEdges: [...data.rawEdges, ...studio.rawEdges.filter((e) => folded.has(e.from) && folded.has(e.to))],
  };
}

/** The node id a project's DIRECTOR carries in its own fleet drill. Mirrors `directorPaneId`'s tail —
 *  the drill's node ids are stream ids, and the director's is the reserved `director`. */
const DIRECTOR_NODE = "director";

/**
 * Add a node per live request session that THIS project's director filed
 * (#debug-nodes-hang-off-the-session-that-filed-them).
 *
 * A director is the one non-studio session allowed to file a global `bsc request` (workers are denied
 * the queue on purpose — director-protocol.md), so its requests have an origin like
 * `myproject:director` that resolves to no Studio Network position. Rendering them on the studio graph
 * would leave them unparented, and an unparented node reads as a bug; dropping them would make an
 * app-started session invisible, which is the one thing every request node exists to prevent. They
 * belong HERE, against the director that filed them, resolved by the same origin rule.
 *
 * Idempotent, and a no-op for a project whose director filed nothing. Pure.
 */
export function withProjectRequestNodes(
  data: GlanceData,
  projectKey: string,
  requests: readonly RequestNodeSpec[] = [],
): GlanceData {
  if (!projectKey || !requests.length) return data;
  const present = new Set(data.rawNodes.map((n) => n.id));
  if (!present.has(DIRECTOR_NODE)) return data; // no director drawn ⇒ nothing to hang them off
  const mine = requests.filter(
    (r) => (r.origin ?? "").trim() === `${projectKey}:${DIRECTOR_NODE}` && !present.has(requestNodeId(r.id)),
  );
  if (!mine.length) return data;
  const nodes: GRawNode[] = mine.map((r) => ({
    id: requestNodeId(r.id),
    slug: requestNodeLabel(r.title),
    role: "infra",
    roleLabel: "debugger",
    health: "healthy" as GHealth,
    activity: "building" as GActivity,
  }));
  return {
    ...data,
    rawNodes: [...data.rawNodes, ...nodes],
    // A Glance edge is "FROM depends on TO", which is the INVERSE of the org relationship it comes from
    // — `buildOrgFleetData` reverses every one. So the studio graph draws `designer → debugger-req-N`
    // (the designer is blocked on that fix), and this must match: `director → debugger-req-N`. Authored
    // by hand rather than through the org adapter, this was the one edge pointing the other way, and only
    // running it against real rows showed it.
    rawEdges: [...data.rawEdges, ...mine.map((r) => ({ from: DIRECTOR_NODE, to: requestNodeId(r.id), kind: "api" as const }))],
  };
}

/**
 * The ARCHITECT node's drilled graph (#architect-node-expands-into-system-sessions) — the system
 * sessions it commands, rendered through the SAME Team→Glance adapter the base-studio-code node uses.
 *
 * Re-pointed machinery, not a second one: `buildOrgFleetData` already turns a team into a Glance
 * graph, and `studioNetworkForArchitect` is a plain team transform (the shape the request-session
 * augmentation shares). Everything downstream — node opening
 * (`studioPaneIdForNode`), live status (`applyStudioLiveStatus`), the morph — works unchanged,
 * because the node ids are the same Studio Network position ids in both graphs.
 *
 * Returns `null` when the team is absent, so the caller falls back to the empty graph rather than
 * crashing. Pure.
 */
export function buildArchitectFleetData(teams: readonly Team[], personas: Persona[]): GlanceData | null {
  const team = teams.find((t) => t.id === STUDIO_NETWORK_ID);
  if (!team) return null;
  // NOT augmented with the request sessions: they are not reachable from an architect verb, so they do
  // not belong in the graph of what the architect commands.
  return buildOrgFleetData(studioNetworkForArchitect(team), personas);
}

/**
 * The stable, app-owned session pane id for each base-studio-code studio graph node (#3319) — the studio
 * analogue of `fleetPaneId`. The node ids are the Studio Network team position ids
 * (`data/teams/orgs/planning-studio.json`), and each maps to its ONE app-owned session's fixed id
 * (`systemSessions.ts`). Because these ids are STABLE, opening a node re-uses the SAME session (its host
 * re-mounts it, `claude --continue`) rather than spawning a duplicate — the "reuse if it exists, create
 * if not" the studio sessions want. The `resource` nodes (libraries) and the dynamic `planner` session
 * have no fixed session, so they return null. Pure.
 */
const STUDIO_NODE_SESSION: Record<string, string> = {
  // #system-sessions-are-per-technology: one node per per-tech session, so each is a COMPLETELY
  // NORMAL node — openable, morphable and live-status-reporting exactly like every other, with no
  // special case anywhere downstream. `studioNodeHome` derives from this map, so adding a technology
  // here makes its node openable in the same edit.
  ...Object.fromEntries(DESIGNER_TECHS.map((t) => [`designer-${t}`, designerSessionId(t)])),
  ...Object.fromEntries(LIBRARIAN_TECHS.map((t) => [`librarian-${t}`, librarianSessionId(t)])),
  // The base-studio-code drill renders the PACKAGED team, which describes ROLES — its positions are
  // still the singular `designer` / `librarian` (see `studioNetworkForArchitect` for why the per-tech
  // expansion lives in the transform rather than the JSON). Those role nodes stay openable, and open
  // their DEFAULT technology: the one the app itself is built in. Without these two entries the
  // base-studio drill's designer and librarian nodes would draw and do nothing — the exact failure
  // #system-sessions-are-per-technology's own `studioNodeHome` fix was written to end.
  designer: designerSessionId("react"),
  librarian: librarianSessionId("typescript"),
  architect: TEAMS_STUDIO_SESSION_ID,
  "sound-designer": SOUND_STUDIO_SESSION_ID,
  integrator: INTEGRATION_STUDIO_SESSION_ID,
  // No `debugger` entry (#debug-nodes-hang-off-the-session-that-filed-them): the standing session is
  // gone, and a per-request session is DYNAMIC — resolved below from its node id, not from this map.
};
/**
 * The INVERSE of {@link STUDIO_NODE_SESSION} — a filing session's pane id → the graph node it is
 * (#debug-nodes-hang-off-the-session-that-filed-them).
 *
 * Built by inverting the table rather than by parsing the pane id, and that is the whole point. The
 * first version pattern-matched `<role>-studio:<tech>` and resolved EVERY studio origin to null,
 * because the real ids are `design-studio:designer-react` and `algorithms-studio:librarian-typescript`
 * — the studio is named for the SURFACE (design / algorithms / teams / sound / integration), not for
 * the role, and the role sits in the tail. Nothing caught it: tsc, eslint, 6823 vitest and clippy were
 * all green, because the tests asserted the same invented shape the code assumed. Only running the
 * binary did.
 *
 * An inverted map cannot drift from the map it inverts. If a technology is added to
 * `STUDIO_NODE_SESSION`, its origin resolves in the same edit.
 */
const STUDIO_NODES_BY_SESSION: Record<string, string[]> = (() => {
  const out: Record<string, string[]> = {};
  // MANY node ids per session id, not one. `designer-react` and the packaged ROLE node `designer` both
  // map to `design-studio:designer-react`, so a plain `Object.fromEntries` inversion silently keeps only
  // whichever came last in the literal and drops the other — which is exactly what happened, and the
  // per-technology node was the one lost. Collect every candidate and let `present` choose.
  for (const [nodeId, sessionId] of Object.entries(STUDIO_NODE_SESSION)) {
    (out[sessionId] ??= []).push(nodeId);
  }
  return out;
})();

/**
 * Which node a request filed by `origin` should hang off, or null when this graph has none.
 *
 * `present` is the node set actually drawn, because the two studio drills render DIFFERENT ids for the
 * same session: the base-studio-code drill draws the packaged ROLE nodes (`designer`), the architect
 * drill draws per-technology ones (`designer-react`). The per-tech node is preferred where it exists —
 * it is the session that actually filed the request — and the role node is the fallback, so the same
 * request lands correctly in either graph instead of only one.
 *
 * Null for a pane that is not a studio session at all: a project director's `myproject:director` is a
 * legitimate origin whose request belongs in that project's drill (see {@link withProjectRequestNodes}),
 * and attaching it to a default node here would assert a relationship that does not exist.
 */
export const studioNodeForOrigin: OriginHostResolver = (origin, present) => {
  const o = (origin ?? "").trim();
  if (!o) return null;
  const candidates = STUDIO_NODES_BY_SESSION[o];
  if (!candidates) return null;
  // Declaration order picks the winner, and the per-technology entries are declared first, so the
  // per-tech node wins where it is drawn (the architect drill).
  const drawn = candidates.find((nodeId) => present.has(nodeId));
  if (drawn) return drawn;
  // Otherwise fall back to the ROLE node the per-tech one expands from (`librarian-rust` → `librarian`),
  // which is what the packaged team draws. This is NOT covered by the candidate list: the role node maps
  // to ONE technology's session (`librarian` → the typescript librarian), so a rust librarian's request
  // has no candidate on the base-studio-code drill and would vanish from it entirely without this.
  for (const nodeId of candidates) {
    const role = nodeId.replace(/-[^-]+$/, "");
    if (role !== nodeId && present.has(role)) return role;
  }
  return null;
};

export function studioPaneIdForNode(nodeId: string): string | null {
  // #3535: an overflow-pool session is DYNAMIC — one node per live pool slot — so it cannot live in the
  // fixed map above. Without this branch such a node resolves to no pane, which means it cannot be
  // opened, cannot report live status, and is a session the user can neither watch nor stop.
  const requestId = requestIdFromNodeId(nodeId);
  if (requestId !== null) return requestPaneId(requestId);
  return STUDIO_NODE_SESSION[nodeId] ?? null;
}

/** Where a studio node's session is HOSTED, so the graph can open/reveal it (#glance-resume). Since #3357
 *  the app-owned studio sessions live on the shared TerminalHost — the request sessions via
 *  `RequestSessionsMount`, the designer/librarian/architect via `StudioSessionHosts` — so every one of them is
 *  openable INLINE via the Glance `morph`: the host re-parents the single live terminal into the morph and
 *  hands it back to the studio's page dock on close, never spawning a second session. (Before #3357 the
 *  three studios ran their own single-mount xterm, which could not be re-parented, so they had to open on
 *  their workspace page instead — the `page` variant, kept for a future non-morphable node.) Null for a
 *  node with no openable session (the libraries, the dynamic planner). Pure. */
export type StudioNodeHome =
  | { kind: "morph" }
  | { kind: "page"; pageMode: "designs" | "algorithms" | "teams" };
export function studioNodeHome(nodeId: string): StudioNodeHome | null {
  // #3535: an overflow-pool session opens exactly like the studios it is one of.
  if (requestIdFromNodeId(nodeId) !== null) return { kind: "morph" };
  // DERIVED from `studioPaneIdForNode`, not a second hand-maintained list
  // (#architect-node-expands-into-system-sessions). This used to be a `switch` enumerating the studio
  // node ids, and it had silently fallen one behind: the INTEGRATOR (#4023) was added to
  // `STUDIO_NODE_SESSION` — so it had a pane and reported live status — but never to this switch, so
  // its node returned null and could not be opened at all. A node that draws and does nothing is the
  // worst failure mode here, and it was invisible because nothing asserted the two lists agreed.
  //
  // The rule is exactly "a node that resolves to an app-owned pane opens as a morph", which is true by
  // construction since #3357 put every studio session on the shared TerminalHost. Deriving it means a
  // studio added to the registry is openable the same day.
  return studioPaneIdForNode(nodeId) ? { kind: "morph" } : null;
}

/**
 * Whether a base-studio-code studio node's session is currently ACTIVE (#glance-resume) — so the node
 * reflects a running session rather than a planned position. The DEBUGGER is live while the Settings
 * `debugSession` flag is on (its node only exists then anyway); the designer/librarian/architect are live
 * while their stable-id session is mounted + running (a live `paneClaudeActive` or a `run`/`on`
 * paneStatus). Pure so the liveness rule is unit-testable; the workspace passes the store signals.
 */
export function studioSessionLive(
  nodeId: string,
  signals: { paneClaudeActive: Record<string, boolean>; paneStatus: Record<string, string | undefined> },
): boolean {
  const sid = studioPaneIdForNode(nodeId);
  if (!sid) return false;
  // A request session's node reports like every other one, off its own pane. It used to be special-cased
  // on the `debugSession` FLAG, which is gone with the standing node — and which was never the right
  // signal anyway: it said whether the toggle was on, not whether anything was running.
  return !!signals.paneClaudeActive[sid] || signals.paneStatus[sid] === "run" || signals.paneStatus[sid] === "on";
}

/** The store signals {@link applyStudioLiveStatus} reads — the same set {@link studioSessionLive} takes. */
export interface StudioLiveSignals {
  paneClaudeActive: Record<string, boolean>;
  paneStatus: Record<string, string | undefined>;
}

/**
 * Overlay the LIVE session state onto the base-studio-code project's studio nodes (#3421) — the studio
 * twin of `applyFleetLiveStatus`, and it exists because the two key their nodes DIFFERENTLY.
 *
 * A fleet node's pane id is `fleetPaneId(projectKey, nodeId)` (`<project>:<stream>`); a studio node's is
 * its STABLE app-owned session id from {@link studioPaneIdForNode} (`DESIGN_STUDIO_SESSION_ID`, …). Running
 * the fleet overlay over studio nodes therefore looked up `base-studio-code:designer`, which never exists,
 * so no studio node was ever found live. That mis-keying was invisible while an unmatched node fell through
 * to the raw `idle/idle` default (a plausible resting state) — #3415 made an unlaunched node read `off`,
 * which pinned every studio node `off` no matter what its session was doing.
 *
 * Health follows the #3415/#4042 model — existence AND work, not mere launch, on TWO independent axes:
 *
 *   - no session mounted                          → off · idle
 *   - mounted but quiet                           → healthy · idle
 *   - mounted + working (`paneStatus === "run"`)  → healthy · building
 *
 * The middle row is the one this got wrong for its whole life: BOTH the unmounted and the mounted-quiet
 * branch returned `off`, so {@link studioSessionLive} was dead weight and a studio the user was actively
 * talking to rendered dark unless `paneStatus` happened to read `run` at that exact instant. Its own doc
 * comment said otherwise, and so did the test's NAME — only the test's assertion agreed with the code,
 * which is what a test written from the implementation rather than the contract buys you. `healthy · idle`
 * is what the fleet twin (`applyFleetLiveStatus`) settled on in #4042 for the identical question, and
 * there is no reason for the two overlays to disagree about what a live-but-quiet session looks like.
 *
 * A node with NO fixed session (the `resource` libraries, the dynamic planner) is left untouched: it has no
 * runtime state of its own, so forcing it `off` would misreport a library as a dead session. Pure — apply to
 * `rawNodes` BEFORE `buildGraph` so the rollup recomputes over the live values.
 */
export function applyStudioLiveStatus(nodes: GRawNode[], signals: StudioLiveSignals): GRawNode[] {
  return nodes.map((n) => {
    if (n.preview) return n; // not a session node — its own state stands
    const sid = studioPaneIdForNode(n.id);
    if (!sid) return n; // a library/resource or the dynamic planner — no session to report on
    if (!studioSessionLive(n.id, signals)) {
      return { ...n, health: "off" as GHealth, activity: "idle" as GActivity };
    }
    return signals.paneStatus[sid] === "run"
      ? { ...n, health: "healthy" as GHealth, activity: "building" as GActivity }
      // Mounted and quiet. `healthy` is the EXISTENCE axis (a session is there and nothing is wrong);
      // `idle` is the ACTIVITY axis (it is not working right now). Saying `off` here collapsed the two
      // axes back into one and threw away the only signal that distinguishes a running studio from one
      // that was never launched.
      : { ...n, health: "healthy" as GHealth, activity: "idle" as GActivity };
  });
}

// The studio-sessions feature's graph-platform surface (register-the-feature-logic-surface) — the modules a
// graph-loaded record imports from this feature but does NOT redraw.
//
// Registered HERE, inside the feature, because the shell must not reach a feature's internals (#1545)
// and eager-importing them from `app/` would de-lazy the whole feature at boot. The feature's BARREL
// calls this at module load, so the shadow catalogue's `ensurePlatform: () => import("@/features/studio-sessions")`
// is what registers them — the same shape `registerAutomationsPlatform` already uses.
//
// These files STAY on disk: registration is not migration. It makes a record that imports them
// loadable, which is the prerequisite for migrating the modules that import THEM.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as UseStudioReaper from "@/features/studio-sessions/useStudioReaper";
import * as Store from "@/features/studio-sessions/store";
import * as StudioSessions from "@/features/studio-sessions/lib/studioSessions";

let done = false;

/** Register this feature's injected graph-platform modules by the specifiers a record imports. Idempotent. */
export function registerStudioSessionsPlatform(): void {
  if (done) return;
  done = true;
  registerAppModule("@/features/studio-sessions/useStudioReaper", UseStudioReaper);
  registerAppModule("@/features/studio-sessions/store", Store);
  registerAppModule("@/features/studio-sessions/lib/studioSessions", StudioSessions);
}

// The shadow catalogue registers this feature's graph-platform modules by importing
// `./graphPlatform` DIRECTLY and calling its register function (see `shadowPages.ts`). This barrel
// therefore has NO import-time side effect — it is re-exports only, which is what lets it be a
// record rather than a file that must run to be correct.

// Public API of the studio-sessions feature (#3357) — the app-owned designer / librarian / architect
// singleton SESSIONS, hosted on the shared TerminalHost. (Distinct from the neighbouring `studio` feature,
// #2889, which is the shareable snapshot BUNDLE of the app's library state — same word, unrelated
// concern; hence the plural, hyphenated name.) Before #3357 each studio ran its own single-mount xterm
// (`use*Terminal` → `useScreenSession`), which the host could not re-parent, so their Glance nodes could
// only "open the page" instead of morphing into the live terminal. They now launch through the generic
// TerminalView path like every fleet terminal, with a lazy start, survival across navigation, and a
// 30-minute idle reaper.
export { StudioSessionHosts } from "@/features/studio-sessions/StudioSessionHosts";
export { StudioSessionMount, seedStudioLaunchState, studioStartPrompt } from "@/features/studio-sessions/StudioSessionMount";
export { useStudioViewer, useStudioViewers } from "@/features/studio-sessions/useStudioViewer";
export { useStudioPageShowing, studioPageShowing } from "@/features/studio-sessions/useStudioPageShowing";
export { useStudioReaper, STUDIO_IDLE_MS, STUDIO_BUSY_RECHECK_MS } from "@/features/studio-sessions/useStudioReaper";
export { createStudiosSlice, orderedWantedStudios, type StudiosSlice } from "@/features/studio-sessions/store";
export {
  STUDIO_IDS, STUDIO_SESSIONS, STUDIO_INIT_CMD,
  isStudioId, studioForPaneId, studioRoleForPaneId, studioDetached, studioForTech, studioScopeDirective,
  type StudioId, type StudioSessionDef,
} from "@/features/studio-sessions/lib/studioSessions";

// Studios feature store slice (#3357) — the LIFECYCLE of the app-owned designer / librarian / architect
// sessions, now that all three live on the shared TerminalHost instead of a page-owned xterm.
//
// Two transient (NEVER persisted) fields, both keyed by StudioId:
//   • `wantedStudios` — which studios should have a WARM session. A studio enters the list the first time
//     something shows it (its page dock or the Glance morph, via `useStudioViewer`) and leaves it when the
//     idle reaper fires. `StudioSessionHosts` renders one persistent `TerminalSlot` per wanted studio, so
//     "wanted" is exactly "this studio has a terminal on the host". (The backend PTY is killed explicitly
//     by whoever drops the studio — the reaper, or an "End session" from the Glance morph — because
//     `TerminalView`'s unmount deliberately leaves the session alive for reconnect.)
//   • `studioViewers` — a REF COUNT of the surfaces currently SHOWING each studio. Two independent
//     surfaces can show the same session at once (the studio page dock and the Glance node morph), so a
//     boolean would let whichever closed first cancel the other. Counting means the reaper only arms when
//     the LAST viewer goes away.
//
// Nothing here launches or kills a PTY directly — `wantedStudios` is a declaration and the mount/TerminalHost
// pair is what acts on it. That keeps the whole lifecycle unit-testable as plain state transitions.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import { STUDIO_IDS, type StudioId } from "@/features/studio-sessions/lib/studioSessions";

export interface StudiosSlice {
  /** Studios whose session should be kept warm on TerminalHost. Transient — nothing launches at boot. */
  wantedStudios: StudioId[];
  /** studio id → number of mounted surfaces currently SHOWING it (page dock + Glance morph). Transient. */
  studioViewers: Record<string, number>;
  /** A launch DIRECTIVE waiting to be baked into a studio's next start, keyed by studio id.
   *
   *  Set by `bsc session ask` when it starts a session to serve a loop, and consumed (once) by
   *  `seedStudioLaunchState` as an appendix to the persona prompt — so the session comes up already
   *  running `bsc loop watch`. Transient like the rest of this slice: a directive that outlived the
   *  app restart it was written for would send a session to watch a loop nobody is waiting on. */
  studioPendingDirective: Partial<Record<StudioId, string>>;
  /** Queue a launch directive for a studio's NEXT start. Overwrites any unconsumed one — a second ask
   *  supersedes the first, and two directives in one launch prompt would have the session watching two
   *  loops and answering neither. */
  setStudioPendingDirective: (id: StudioId, directive: string) => void;
  /** Take the directive, clearing it — so it is baked in exactly once and a later relaunch of the same
   *  studio (a reaper reclaim, a user re-open) does not resurrect a stale request. */
  takeStudioPendingDirective: (id: StudioId) => string | undefined;
  /** Mark a studio as wanted — the lazy start. Idempotent, so every viewer can call it on mount. */
  openStudio: (id: StudioId) => void;
  /** Drop a studio from the wanted list → its persistent mount unmounts. Called by the idle reaper and by
   *  an explicit "End session" from the Glance morph, BOTH of which also `pty_kill` the session. */
  closeStudio: (id: StudioId) => void;
  /** A surface began showing this studio (cancels any armed reap). */
  addStudioViewer: (id: StudioId) => void;
  /** A surface stopped showing this studio (arms the reaper when the count reaches 0). */
  removeStudioViewer: (id: StudioId) => void;
}

export const createStudiosSlice: StateCreator<AppStore, [], [], StudiosSlice> = (set, get) => ({
  wantedStudios: [],
  studioViewers: {},
  studioPendingDirective: {},

  setStudioPendingDirective: (id, directive) =>
    set((s) => ({ studioPendingDirective: { ...s.studioPendingDirective, [id]: directive } })),

  // A GET-AND-CLEAR rather than a selector plus a separate clear: two callers reading before either
  // cleared would both bake the directive in, and the second launch would watch a loop already served.
  takeStudioPendingDirective: (id) => {
    const current = get().studioPendingDirective[id];
    if (current !== undefined) {
      set((s) => {
        const next = { ...s.studioPendingDirective };
        delete next[id];
        return { studioPendingDirective: next };
      });
    }
    return current;
  },

  openStudio: (id) =>
    set((s) => (s.wantedStudios.includes(id) ? {} : { wantedStudios: [...s.wantedStudios, id] })),

  closeStudio: (id) =>
    set((s) => (s.wantedStudios.includes(id) ? { wantedStudios: s.wantedStudios.filter((w) => w !== id) } : {})),

  addStudioViewer: (id) =>
    set((s) => ({ studioViewers: { ...s.studioViewers, [id]: (s.studioViewers[id] ?? 0) + 1 } })),

  // Clamp at 0: a double-unmount (StrictMode, a racing cleanup) must never drive the count negative —
  // a negative count would read as "still watched" forever and the reaper would never arm.
  removeStudioViewer: (id) =>
    set((s) => ({ studioViewers: { ...s.studioViewers, [id]: Math.max(0, (s.studioViewers[id] ?? 0) - 1) } })),
});

/** The studios currently WANTED, in canonical rail order (so the mounts render in a stable order). */
export function orderedWantedStudios(wanted: readonly StudioId[]): StudioId[] {
  return STUDIO_IDS.filter((id) => wanted.includes(id));
}

// The app-owned STUDIO sessions (#3357) — the one place that describes the designer / librarian /
// architect singleton sessions: their stable pane id, role, workspace-setup command, persona, tunnel
// roster entry, and the page they dock on. Pure + React-free so the registry is unit-testable and can be
// read from the store slice, the mount, the page docks, and the Glance wiring without a cycle.
//
// WHY A REGISTRY: before #3357 each studio owned a bespoke `use*Terminal` hook that mounted its OWN xterm
// via `useScreenSession`. That terminal could not be re-parented, so the Glance graph could not morph a
// studio node into its live session (only the debugger, already on TerminalHost, could). All three now
// launch through the SHARED TerminalHost like every fleet terminal — which means their launch inputs must
// live as DATA the generic launch path (`TerminalView` + `buildSessionSettings`) reads, not as a bespoke
// `pty_create` call. This file is that data.
import type { SessionRole } from "@/shared/lib/session/sessionRoles";
import {
  designerSessionId,
  librarianSessionId,
  TEAMS_STUDIO_SESSION_ID,
  SOUND_STUDIO_SESSION_ID,
  INTEGRATION_STUDIO_SESSION_ID,
} from "@/shared/lib/session/systemSessions";

/** The app-owned studio sessions. (The DEBUG session is app-owned too but is full-capability and
 *  Settings-toggled, so it keeps its own `DebugSessionMount` — see `@/features/debug`.)
 *
 *  PER TECHNOLOGY (#system-sessions-are-per-technology) for the two studios whose store is partitioned:
 *  the LIBRARIAN by `impl.tech` on the algorithms graph, the DESIGNER by `kit.tech` on the component
 *  store. The sound-designer and integrator stay single — their stores carry no tech facet at any
 *  level, and splitting a studio with nothing to split just doubles the sessions.
 *
 *  These are LITERALS, not generated, because a `StudioId` is a compile-time key: it types
 *  `wantedStudios`, `studioViewers`, every store map and the closed set `bsc session` resolves against.
 *  A runtime-materialised session would have none of those. */
export type StudioId =
  | "designerReact" | "designerReactNative"
  | "librarianRust" | "librarianTypescript" | "librarianPython"
  | "architect" | "soundDesigner" | "integrator";

/** Every studio id, in rail order. */
export const STUDIO_IDS: readonly StudioId[] = [
  "designerReact", "designerReactNative",
  "librarianRust", "librarianTypescript", "librarianPython",
  "architect", "soundDesigner", "integrator",
];

export interface StudioSessionDef {
  id: StudioId;
  /** The stable, app-owned pane id (`systemSessions.ts`) — so re-opening re-uses the SAME session. */
  paneId: string;
  /** The role gate (#219) the session launches under. Set as `paneRoles[paneId]` and NOTHING else:
   *  `restrictedRoleCommands(role)` then makes `buildSessionSettings` emit `restrictedAllow`, so the
   *  session's whole auto-run surface is its store CLI. A pane PROFILE must never be assigned — that
   *  would ADD auto-approved commands on top of the restricted surface. */
  role: SessionRole;
  /** Tauri command that creates the studio's global workspace dir + writes its spec CLAUDE.md. */
  setupCommand: string;
  /** Key on `setupCommand`'s return object holding the workspace dir (the session's cwd). */
  dirKey: string;
  /** The built-in persona whose `startPrompt` is baked into the launch as `claude --initial-message`. */
  personaId: string;
  /** Display name in the mobile session roster (#2497). */
  rosterName: string;
  /** `usePageTabs` page key + section id of the page this studio docks on — the tear-off signal
   *  (`detachedSections[pageKey]` containing `sectionId` ⇒ another WINDOW owns this studio's terminal). */
  pageKey: string;
  sectionId: string;
  /** The TECHNOLOGY this session curates (#system-sessions-are-per-technology), for the studios whose
   *  store is partitioned. Absent for a single-technology studio (architect / sound-designer /
   *  integrator). Drives {@link studioScopeDirective}, which is what actually makes a per-tech session
   *  behave differently from its siblings — without it, three librarians would launch identically and
   *  each would curate the whole graph, which is the state this split exists to end. */
