/** Where a failed `--continue` writes its reason. Under `$BSC_LOG_DIR` (set per-pane by `pty_create`,
 *  alongside the audit/coord/perf streams), so it sits with the rest of a session's diagnostics. */
export const STUDIO_RESUME_LOG = "studio-resume.log";

/**
 * Resume the prior studio conversation across app restarts, else launch a fresh session.
 *
 * The `|| claude` fallback is deliberate — a genuinely first launch has nothing to resume. What was
 * NOT deliberate is that the old form (`claude --continue 2>/dev/null || claude`) **discarded the
 * reason** and degraded silently: a session that failed to resume looked identical to one that had
 * never run, with no log line and nothing in the pane. That made #3374 — studios starting a fresh
 * conversation across restarts — impossible to diagnose, because the one signal that would explain it
 * was being thrown away on every launch.
 *
 * So stderr now APPENDS to `$BSC_LOG_DIR/studio-resume.log` instead of `/dev/null`, and the fallback
 * announces itself in the pane. Behaviour is otherwise unchanged: resume when there is something to
 * resume, start fresh when there isn't.
 *
 * `${BSC_LOG_DIR:-/tmp}` guards the (unexpected) case of an unset log dir — a missing diagnostic must
 * never stop the session launching.
 */
export const STUDIO_INIT_CMD =
  `claude --continue 2>>"\${BSC_LOG_DIR:-/tmp}/${STUDIO_RESUME_LOG}"` +
  ` || { echo "[studio] no prior session resumed — starting fresh (why: \${BSC_LOG_DIR:-/tmp}/${STUDIO_RESUME_LOG})"; claude; }`;

/**
 * The scoping line a per-technology studio launches with, appended to its persona prompt.
 *
 * THIS IS WHAT MAKES THE SPLIT REAL. Five sessions sharing one persona and one workspace would launch
 * identically and each would curate the whole store — the split would cost five processes and change
 * nothing. The directive names the session's technology AND the filtered read that scopes it, so the
 * session knows what it owns from its first turn.
 *
 * The two studios are scoped by DIFFERENT queries, because their stores carry `tech` at different
 * levels: an algorithms implementation carries it directly (`bsc graph impl list --tech <t>`), while a
 * component carries it via its KIT (`bsc ui kit list` → the kits whose tech matches → `--kit <id>`).
 * A single generic "filter by tech" would be wrong for one of them, so the two are written out.
 *
 * Empty for a studio with no `tech` — the architect, sound-designer and integrator curate everything
 * their store holds, and appending a scoping line that names no scope would be noise.
 */
export function studioScopeDirective(def: StudioSessionDef): string {
  if (!def.tech) return "";
  const read =
    def.role === "librarian"
      ? `Your partition is \`bsc graph impl list --tech ${def.tech}\`. Every implementation you curate, ` +
        `harvest or optimize is a ${def.tech} one.`
      : `Your partition is the kits whose \`tech\` is \`${def.tech}\` — list them with ` +
        `\`bsc ui kit list\`, then read each with \`bsc ui list --kit <kitId>\`. Every component you ` +
        `author or edit belongs to one of those kits.`;
  return (
    `## Your technology: ${def.tech}

` +
    `You are the ${def.tech} ${def.role}. ${read}

` +
    `Sibling sessions curate the other technologies — do NOT edit records outside your partition. ` +
    `A ${def.tech} artifact and its equivalent in another technology are different artifacts, not two ` +
    `copies of one, which is exactly why there is a session per technology rather than one over all ` +
    `of them.`
  );
}

/**
 * The studio session that curates `tech`, for a role whose store is partitioned
 * (#system-sessions-are-per-technology).
 *
 * This is how a PAGE follows its own selection: the Algorithms page's language rail and the Design
 * page's kit both already name a technology, so the dock resolves that to a session id rather than
 * holding a second selection of its own. Two selections for one concept is how they drift apart.
 *
 * Null for a technology with no session — a graph that grows a fourth language, or a kit whose `tech`
 * is not one this app ships a designer for. The dock then shows nothing rather than defaulting to
 * SOME session, because silently docking the rust librarian on a page showing go algorithms is worse
 * than an empty dock: it looks like it is working.
 */
export function studioForTech(role: "librarian" | "designer", tech: string): StudioId | null {
  return STUDIO_IDS.find((id) => STUDIO_SESSIONS[id].role === role && STUDIO_SESSIONS[id].tech === tech) ?? null;
}

/** Narrow an arbitrary string (a Glance node id, a persisted value) to a StudioId. */
export function isStudioId(value: string | null | undefined): value is StudioId {
  return !!value && (STUDIO_IDS as readonly string[]).includes(value);
}

/** The studio owning a pane id, or null for any other pane (fleet, planner, debug, manual). */
export function studioForPaneId(paneId: string): StudioId | null {
  return STUDIO_IDS.find((id) => STUDIO_SESSIONS[id].paneId === paneId) ?? null;
}

/**
 * The role gate a studio pane launches under, DERIVED from its pane id (#3423) — so confinement travels
 * with the session's identity instead of depending on setup having run first.
 *
 * `paneRoles[paneId]` is what makes a pane a designer, and it used to be written ONLY by
 * `seedStudioLaunchState` inside `StudioSessionMount`'s effect. That component renders only for studios in
 * `wantedStudios`, which is deliberately transient (absent from `partialize`), so after any app restart the
 * set is empty and nothing mounts. Opening a studio then created a terminal on a studio pane id with NO role
 * in the store — and `buildSessionSettings` applies no role gate, no `restrictedAllow` and no denies when it
 * finds none. The result was a fully UNCONFINED general shell on the app's most restricted surface.
 *
 * A studio's pane id is stable and app-owned, so it is sufficient on its own to establish the role. Null for
 * any other pane, where the store remains the only authority.
 */
export function studioRoleForPaneId(paneId: string): SessionRole | null {
  const id = studioForPaneId(paneId);
  return id ? STUDIO_SESSIONS[id].role : null;
}

/**
 * Whether this studio's page is TORN OFF into its own window (#430/#463). The detached window runs its
 * OWN React root + store + TerminalHost, so it becomes the sole owner of the studio's single terminal —
 * the main window must release it (not mount a second xterm onto the same PTY, which would fight over
 * `pty_resize`). `detachedSections` is transient per-window state, so the detached window itself always
 * reads `false` here and mounts the session normally. Pure.
 */
export function studioDetached(id: StudioId, detachedSections: Record<string, string[]>): boolean {
  const def = STUDIO_SESSIONS[id];
  return (detachedSections[def.pageKey] ?? []).includes(def.sectionId);
}

// studioVisibility (#3616) — is the Design Studio the page the user is actually LOOKING AT?
//
// DesignsWorkbench lives inside KeptMountedPage, which keeps it MOUNTED (CSS display:none) after the
// first visit so its state + PTY survive a page switch. That means its effects keep running while it's
// hidden — including `useComponentScan`, which esbuild-builds and hidden-iframe-probes all ~154
// components. Left ungated (`useComponentScan(true, …)`) that scan runs FOREVER in the background, pinning
// a WebView renderer near 40% CPU for a page nobody is looking at. Gating the scan on real visibility
// (the same condition the two KeptMountedPage wrappers use — App's `activeWorkspace === "projects"` AND
// the planner's `mode === "designs"`) pauses it when hidden and resumes it (sig-cache intact) on return.

/** True only when the Design Studio is the currently-shown page. `pageMode` is optional because
 *  `projectsPageMode` can be undefined before the projects workspace has picked a page. */
export function designStudioVisible(activeWorkspace: string, projectsPageMode: string | undefined): boolean {
  return activeWorkspace === "projects" && projectsPageMode === "designs";
}

// The design-system STYLE DESCRIPTOR (#2567) — the authoritative source of truth for the semantic
// token contract. `src-tauri/data/ui/tokens-contract.css` is GENERATED from
// `src-tauri/data/ui/style-descriptor.json` by {@link emitTokensContractCss} (guarded by
// `styleContract.gen.test.ts`), and later `bsc ui tokens` enumerates the same descriptor as the
// addressable surface for the designer LLM (#2568). One SoT feeds CSS emission AND discovery.
//
// Additive-first: a new token defaults to today's value, so growing the descriptor lands as a
// zero-visual-change commit. Types are deliberately coarse — "color" | "dimension" | "duration" |
// "easing" (motion, #2866) | "number" | "font" (#3394) — a discovery/label axis (what `bsc ui tokens`
// reports), not a full CSS type system: `bsc ui`'s closed value grammar is character-based and already
// accepts a time (`120ms`) or a timing-function (`cubic-bezier(...)`), so motion values need no
// grammar change. `number` (a unitless weight/opacity/multiplier) and `font` (a family stack) were
// added for the Button exhaust (#3394) for the same reason: they only widen what `bsc ui tokens`
// LABELS, and `is_safe_value` — a denylist over `;{}<>\`, `url(`, `expression(`, `@import`, `/*` —
// already admits `600`, `0.4` and a family stack unchanged.

export type TokenType = "color" | "dimension" | "duration" | "easing" | "number" | "font";

/** A base-palette token — an app-level default the semantic layer + themes compose from. */
export interface BaseToken {
  /** The CSS custom-property name, e.g. `--accent`. */
  name: string;
  type: TokenType;
  /** The literal default value (a raw colour/dimension; base tokens never reference other tokens). */
  value: string;
  /** One-line description surfaced by `bsc ui tokens`. */
  governs: string;
}

/** A semantic component token — what a kit component consumes and a theme overrides. */
export interface ComponentToken {
  /** The short key used for rung-2 addressing: `bsc ui component <c> set-token <key> [--variant v]`
   *  resolves to `--<component>[-<variant>]-<key>`. */
  key: string;
  /** The full CSS custom-property name, e.g. `--btn-primary-bg`. */
  name: string;
  type: TokenType;
  /** The default value (usually a `var(--base)` reference so a theme/accent composes through). */
  default: string;
  governs: string;
}

export interface StyleVariant {
  variant: string;
  governs: string;
  tokens: ComponentToken[];
}

export interface StyleComponent {
  component: string;
  governs: string;
  tokens: ComponentToken[];
  variants: StyleVariant[];
}

/** A domain / categorical token — a data-viz palette entry (graph status/kind/category/edge, #2607).
 *  Part of the contract vocabulary a kit consumes and a theme binds, but NOT a component: it carries
 *  a literal `value` (a concrete hue like base tokens), grouped by `group`, not owned by a component. */
export interface DomainToken {
  key: string;
  name: string;
  type: TokenType;
  value: string;
  governs: string;
}

export interface DomainGroup {
  group: string;
  governs: string;
  tokens: DomainToken[];
}

export interface StyleDescriptor {
  version: number;
  note: string;
  base: BaseToken[];
  components: StyleComponent[];
  /** Domain / categorical palettes (graph, …) — optional so older descriptors still parse (#2607). */
  domain?: DomainGroup[];
}

/** A flat, uniform view of every token in the descriptor — the shape `bsc ui tokens` will serialise
 *  and the resolver rung-2 addressing will search. `component`/`variant` are undefined for base tokens. */
export interface FlatToken {
  name: string;
  type: TokenType;
  /** The default (base tokens: their literal `value`; component tokens: their `default`). */
  default: string;
  governs: string;
  /** "base" for the palette, else the component name. */
  family: string;
  component?: string;
  variant?: string;
  key?: string;
}

/** Flatten the descriptor into one row per token (base → component → per-variant), preserving order. */
export function flattenTokens(d: StyleDescriptor): FlatToken[] {
  const out: FlatToken[] = [];
  for (const b of d.base) out.push({ name: b.name, type: b.type, default: b.value, governs: b.governs, family: "base" });
  for (const c of d.components) {
    for (const t of c.tokens) out.push({ name: t.name, type: t.type, default: t.default, governs: t.governs, family: c.component, component: c.component, key: t.key });
    for (const v of c.variants)
      for (const t of v.tokens) out.push({ name: t.name, type: t.type, default: t.default, governs: t.governs, family: c.component, component: c.component, variant: v.variant, key: t.key });
  }
  // Domain / categorical tokens — one row per token, family = the group (e.g. "graph-health"). They
  // are contract vocabulary (discoverable via `bsc ui tokens`) but not components, so no `component`.
  for (const g of d.domain ?? [])
    for (const t of g.tokens) out.push({ name: t.name, type: t.type, default: t.value, governs: t.governs, family: g.group, key: t.key });
  return out;
}

/**
 * Emit `tokens-contract.css` from the descriptor — the semantic token contract every kit component
 * consumes and `bsc ui emit-css` ships into a generated app as `tokens.css`. Declaration order:
 * base palette, then the semantic component tokens (each component's tokens, then its variants'),
 * matching the flatten order so the file reads top-to-bottom like the descriptor. Trailing newline
 * so the generated file is stable across platforms (the drift test normalises CRLF → LF).
 */
export function emitTokensContractCss(d: StyleDescriptor): string {
  const L: string[] = [];
  L.push("/* GENERATED from src-tauri/data/ui/style-descriptor.json — DO NOT EDIT BY HAND.");
  L.push("   Regenerate: `UPDATE_KITS=1 npx vitest run styleContract.gen`.");
  L.push(`   ${d.note} */`);
  L.push(":root {");
  L.push("  /* base palette — the app-level defaults the semantic layer (and the themes) compose from */");
  for (const b of d.base) L.push(`  ${b.name}: ${b.value};`);
  L.push("");
  L.push("  /* semantic component tokens — what kit components consume; what a theme overrides */");
  for (const c of d.components) {
    for (const t of c.tokens) L.push(`  ${t.name}: ${t.default};`);
    for (const v of c.variants) for (const t of v.tokens) L.push(`  ${t.name}: ${t.default};`);
  }
  if (d.domain?.length) {
    L.push("");
    L.push("  /* domain / categorical tokens — data-viz palettes (graph status/kind/category/edge); the contract vocabulary a kit consumes and a theme binds (#2607) */");
    for (const g of d.domain) for (const t of g.tokens) L.push(`  ${t.name}: ${t.value};`);
  }
  L.push("}");
  return L.join("\n") + "\n";
}

// The Sounds synth engine (#3072) — two halves, split so the logic is testable without a browser:
//   compileCue — PURE: resolves a Cue's composes edges (layer→voice→primitive) into a FLAT schedule of
//                voices with absolute start times + durations. No Web Audio; fully unit-tested.
//   playCue    — THIN: realizes that schedule on a Web Audio graph. No-op where AudioContext is absent
//                (SSR / jsdom), so it's safe to call from anywhere; not unit-tested (needs a real ctx).
import type { Cue, Envelope, SoundKit, VoiceFilter, Waveform } from "@/features/sounds/lib/soundDescriptor";

/** One voice of a cue, resolved to everything the player needs — no more kit lookups downstream. */
export interface CompiledVoice {
  source: "osc" | "noise";
  waveform: Waveform;
  freq: number;
  pitchTo?: number;
  detune: number;
  env: Envelope;
  filter?: VoiceFilter;
  gain: number;
  /** Seconds from the cue's start. */
  startAt: number;
  /** attack + decay + release. */
  duration: number;
}

export interface CompiledCue {
  voices: CompiledVoice[];
  /** Wall-clock length of the whole cue (max layer end). */
  duration: number;
}

/** A voice's one-shot length: attack → decay → release (sustain is a level, not a hold). */
export function voiceDuration(env: Envelope): number {
  return env.attack + env.decay + env.release;
}

/**
 * Resolve a cue into a flat, absolutely-timed schedule. Throws on a dangling composes edge (a missing
 * voice or primitive) — call `validateKit` first if the kit might be broken; the seed kits are
 * test-guarded, so a throw here is a real bug, not user data. Pure + deterministic.
 */
export function compileCue(cue: Cue, kit: SoundKit): CompiledCue {
  const voiceById = new Map(kit.voices.map((v) => [v.id, v]));
  const primById = new Map(kit.primitives.map((p) => [p.id, p]));
  const voices: CompiledVoice[] = [];
  let duration = 0;
  for (const layer of cue.layers) {
    const voice = voiceById.get(layer.voice);
    if (!voice) throw new Error(`cue "${cue.id}" layers a missing voice "${layer.voice}"`);
    const prim = primById.get(voice.primitive);
    if (!prim) throw new Error(`voice "${voice.id}" composes a missing primitive "${voice.primitive}"`);
    const dur = voiceDuration(voice.env);
    voices.push({
      source: prim.kind,
      waveform: prim.waveform ?? "sine",
      freq: voice.freq,
      pitchTo: voice.pitchTo,
      detune: voice.detune ?? 0,
      env: voice.env,
      filter: voice.filter,
      gain: voice.gain,
      startAt: layer.at,
      duration: dur,
    });
    duration = Math.max(duration, layer.at + dur);
  }
  return { voices, duration };
}

// ── Web Audio realization (thin; untested — needs a real AudioContext) ─────────────────────────────

let sharedCtx: AudioContext | null = null;
let noiseBuf: AudioBuffer | null = null;

type AudioCtor = typeof AudioContext;

/** The shared AudioContext, created lazily on first play (a user gesture) and resumed if suspended.
 *  Returns null where Web Audio is unavailable (SSR / jsdom) so callers degrade to a no-op. */
function getCtx(): AudioContext | null {
  if (typeof window === "undefined") return null;
  const Ctor: AudioCtor | undefined =
    window.AudioContext ?? (window as unknown as { webkitAudioContext?: AudioCtor }).webkitAudioContext;
  if (!Ctor) return null;
  if (!sharedCtx) sharedCtx = new Ctor();
  if (sharedCtx.state === "suspended") void sharedCtx.resume();
  return sharedCtx;
}

/** A one-second white-noise buffer, generated once and reused for every noise voice. */
function whiteNoise(ctx: AudioContext): AudioBuffer {
  if (noiseBuf && noiseBuf.sampleRate === ctx.sampleRate) return noiseBuf;
  const buf = ctx.createBuffer(1, ctx.sampleRate, ctx.sampleRate);
  const data = buf.getChannelData(0);
  for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
  noiseBuf = buf;
  return buf;
}

/** Schedule one compiled voice on the graph, starting at absolute time `t0`. */
function scheduleVoice(ctx: AudioContext, v: CompiledVoice, t0: number): void {
  const start = t0 + v.startAt;
  const { attack, decay, sustain, release } = v.env;
  const peak = Math.max(0.0001, v.gain);

  // Envelope on a GainNode: 0 →(attack)→ peak →(decay)→ sustain·peak →(release)→ 0.
  const amp = ctx.createGain();
  amp.gain.setValueAtTime(0.0001, start);
  amp.gain.linearRampToValueAtTime(peak, start + attack);
  amp.gain.linearRampToValueAtTime(Math.max(0.0001, sustain * peak), start + attack + decay);
  amp.gain.linearRampToValueAtTime(0.0001, start + attack + decay + release);

  let node: OscillatorNode | AudioBufferSourceNode;
  if (v.source === "noise") {
    const src = ctx.createBufferSource();
    src.buffer = whiteNoise(ctx);
    src.loop = true;
    node = src;
  } else {
    const osc = ctx.createOscillator();
    osc.type = v.waveform;
    osc.detune.setValueAtTime(v.detune, start);
    osc.frequency.setValueAtTime(v.freq, start);
    if (v.pitchTo != null && v.pitchTo !== v.freq) {
      osc.frequency.linearRampToValueAtTime(v.pitchTo, start + v.duration);
    }
    node = osc;
  }

  let tail: AudioNode = node;
  if (v.filter) {
    const f = ctx.createBiquadFilter();
    f.type = v.filter.type;
    f.frequency.setValueAtTime(v.filter.cutoff, start);
    tail.connect(f);
    tail = f;
  }
  tail.connect(amp);
  amp.connect(ctx.destination);

  node.start(start);
  node.stop(start + v.duration + 0.02);
}

/**
 * Play a cue NOW. Compiles it (throws only on a broken kit — guarded by validateKit/tests), then schedules
 * every voice on the shared AudioContext. Returns the cue's duration in seconds (0 where audio is
 * unavailable — a safe no-op). Fire-and-forget; there's no stop handle in Phase 1 (cues are short one-shots).
 */
export function playCue(cue: Cue, kit: SoundKit): number {
  const ctx = getCtx();
  if (!ctx) return 0;
  const compiled = compileCue(cue, kit);
  const t0 = ctx.currentTime + 0.02; // a hair ahead so the first envelope point isn't in the past
  for (const v of compiled.voices) scheduleVoice(ctx, v, t0);
  return compiled.duration;
}

// systemSessionBridge (#architect-starts-and-stops-system-sessions) — decide what a `bsc session
// start|stop` request does to the store.
//
// Pure on purpose: the DECISION (is it already running, what changed, what to report) is testable
// without Tauri or a rendered app, and the listener stays a thin adapter — the same split
// `fleetWakeBridge` and `navigateBridge` use.
//
// WHY THE OUTCOME IS FOUR-VALUED AND NOT A BOOLEAN
// A system session is a SINGLETON on a fixed pane id, so `start` on one that is already up changes
// nothing. Reporting that as a plain success is the #4025 shape: the caller believes it created
// something and waits on a session it did not. So the no-ops are named — `already-running` and
// `not-running` — and only `started`/`stopped` claim a change.
//
// WHY "RUNNING" IS `wanted || ptyLive` AND NOT EITHER ALONE
// `wantedStudios` is what the frontend has MOUNTED; a PTY is what is actually alive. They can
// disagree, because `TerminalView`'s unmount deliberately leaves the backend session alive so a
// tab-switch reconnects rather than respawns — so a stray PTY can outlive its mount. Deciding on
// `wanted` alone would report "not running" while a `claude` process was still up, and then `stop`
// would leave it there; deciding on `ptyLive` alone would miss a mount that has not spawned yet.
// Rust measures the PTY (the store cannot see one) and sends it along; this ORs the two.

import { isStudioId, type StudioId } from "@/features/studio-sessions";

/** The lifecycle request as it arrives from Rust (`bsc://session-lifecycle`). */
export interface LifecycleRequest {
  /** Correlates the ack. */
  id: string;
  /** The system session's id — already resolved against the closed registry, on BOTH sides. */
  sessionId: string;
  /** Its fixed, app-owned pane id. */
  paneId: string;
  action: "start" | "stop";
  /** Whether a PTY exists for `paneId`, measured in Rust just before the emit. */
  ptyLive: boolean;
  /** Present when this start exists to serve a `bsc session ask` — the launch directive that has the
   *  session come up already running `bsc loop watch`. Built in Rust so the prose has one authority. */
  askDirective?: string | null;
}

/** What we send back via `system_session_ack`. Kebab-case matches the Rust `LifecycleOutcome`. */
export type LifecycleOutcome = "started" | "already-running" | "stopped" | "not-running";

export interface LifecycleAck {
  id: string;
  error?: string;
  outcome?: LifecycleOutcome;
}

/**
 * The store surface this needs — narrowed so the pure fn stays decoupled from the slice.
 */
export interface LifecycleDeps {
  /** The studios currently mounted/warm (`wantedStudios`). */
  wantedStudios: readonly StudioId[];
  /** `openStudio` — marks it wanted; `StudioSessionHosts` mounts its TerminalSlot. */
  openStudio: (id: StudioId) => void;
  /** `closeStudio` — drops it from the wanted list, unmounting its host claim. */
  closeStudio: (id: StudioId) => void;
  /** Queue the ask directive for the launch `openStudio` is about to trigger. */
  setPendingDirective: (id: StudioId, directive: string) => void;
  /** `pty_kill` for the pane. A no-op when there is no PTY, which is why it is safe to call
   *  unconditionally rather than probing first — Rust already owns the liveness answer. */
  killPane: (paneId: string) => Promise<void>;
}

/**
 * Apply one lifecycle request. Never throws — every path produces an ack, because silence would
 * strand the Rust waiter until its timeout and surface as "the frontend did not apply the start",
 * sending someone to debug the wrong thing.
 *
 * The id is re-narrowed to a `StudioId` here even though Rust resolved it against the same closed
 * set: this is the last point where a string becomes a store action, and `isStudioId` is what keeps
 * the two registries honest at runtime as well as at gate time (`systemSessionRegistry.test.ts`
 * pins them statically).
 */
export async function applyLifecycle(req: LifecycleRequest, deps: LifecycleDeps): Promise<LifecycleAck> {
  const { id } = req;
  const sessionId = (req.sessionId ?? "").trim();
  if (!isStudioId(sessionId)) {
    return {
      id,
      error:
        `session lifecycle: '${sessionId}' is not a known system session in this app build — ` +
        `the CLI's registry and the app's have drifted apart.`,
    };
  }
  const studio: StudioId = sessionId;
  const running = deps.wantedStudios.includes(studio) || req.ptyLive;

  if (req.action === "start") {
    if (running) return { id, outcome: "already-running" };
    // ORDER IS LOAD-BEARING: queue the directive BEFORE `openStudio`. The mount's effect runs off the
    // wanted list and calls `seedStudioLaunchState`, which TAKES the directive — set afterwards, it
    // would arrive after the seed had already read an empty slot and the session would come up
    // without knowing which loop it was started for.
    if (req.askDirective) deps.setPendingDirective(studio, req.askDirective);
    // Otherwise nothing else is needed: `openStudio` is the whole start. The mount reads the studio's
    // launch inputs from `STUDIO_SESSIONS` and its stable pane id means the session RESUMES its
    // previous conversation rather than beginning blank.
    deps.openStudio(studio);
    return { id, outcome: "started" };
  }

  // STOP. The kill runs even when nothing is `wanted`, because a stray PTY that outlived its mount is
  // exactly the case a caller means to reclaim — and `pty_kill` on an absent session is a no-op. The
  // OUTCOME still reports what was true before, so "not-running" never hides a process that was
  // actually killed: `running` is the OR, so a stray PTY reads as running and reports `stopped`.
  await deps.killPane(req.paneId).catch(() => {});
  deps.closeStudio(studio);
  return { id, outcome: running ? "stopped" : "not-running" };
}

// App-owned "studio" sessions (#3137) — the single source of truth for the fixed pane ids of the
// dedicated, app-launched singleton terminal sessions: the DESIGNER (Design Studio), the LIBRARIAN
// (Algorithms), the ARCHITECT (Teams), and the SOUND-DESIGNER (Sounds). Each is a singleton session the app owns and re-creates on
// demand — NOT a fleet worker and NOT something the user restores. Since #3357 all three (like the DEBUG
// session, #3326) run on the shared TerminalHost via `@/features/studio-sessions`, not on their own page-owned
// xterm; their ids stay fixed here so the lifecycle, the Glance morph, and recovery all agree.
//
// Their ids follow the `<key>:<tail>` grammar, so `parsePaneIdentity` would otherwise classify them as
// fleet WORKERS and the crash-recovery banner would offer to restore them (#3137). This module names
// them in ONE feature-agnostic place so both the feature hooks (which import their `*_PANE_ID` from here)
// and the recovery reconcile (`reconcileSessions`, which excludes them) agree — a new studio added here
// is excluded everywhere at once. The PLANNER is the sibling app-owned session, but it has a DYNAMIC
// per-project id (`planning_<key>`) and its own `isPlanningPaneId` guard, so it isn't listed here.

/** The Design Studio's app-owned designer session, one per kit technology. */
export const designerSessionId = (tech: DesignerTech): string => `design-studio:designer-${tech}`;
/** The ALGORITHMS techs that get their own librarian (#system-sessions-are-per-technology) — the
 *  partition the algorithms graph already carries on every implementation (`impl.tech`), reachable as
 *  `bsc graph impl list --tech <t>`. One librarian per language kit, not one over all of them: a rust
 *  impl and a typescript impl of the same concept are different artifacts (concept-IS-impl, #2863), and
 *  curating both from one session means one context holding two languages' idioms.
 *
 *  A FOURTH tech appearing in the graph needs a fourth entry here — the list is declared rather than
 *  derived because these ids are compile-time `StudioId` literals, and a session that materialises at
 *  runtime would have no pane id, no role and no place in the closed set `bsc session` resolves against. */
export const LIBRARIAN_TECHS = ["rust", "typescript", "python"] as const;
export type LibrarianTech = (typeof LIBRARIAN_TECHS)[number];

/** The UI-KIT techs that get their own designer. The component store partitions on `tech` at the KIT
 *  level (`bsc ui kit list`), one level up from where the algorithms graph carries it — react today
 *  (base-studio-code · harvested · react-d3) and react-native (mobile-studio-code). */
export const DESIGNER_TECHS = ["react", "react-native"] as const;
export type DesignerTech = (typeof DESIGNER_TECHS)[number];

/** The Algorithms studio's app-owned librarian session, one per technology.
 *
 *  A HYPHEN, never a second colon: the pane-id grammar is `<key>:<tail>` and several call sites read
 *  the project key as `paneId.split(":")[0]`. A second colon would not break that read, but it changes
 *  what the TAIL means for anything that splits further — so the tech rides in the tail. */
export const librarianSessionId = (tech: LibrarianTech): string => `algorithms-studio:librarian-${tech}`;
/** The Teams studio's app-owned architect session. */
export const TEAMS_STUDIO_SESSION_ID = "teams-studio:architect";
/** The Sound studio's app-owned sound-designer session (#3369, epic #3071 phase 4). */
export const SOUND_STUDIO_SESSION_ID = "sound-studio:sound-designer";
/** The Integration studio's app-owned integrator session (#4023) — builds and maintains the app's
 *  integrations with existing applications/APIs through `bsc data connector`. */
export const INTEGRATION_STUDIO_SESSION_ID = "integration-studio:integrator";
/** The Debug studio's app-owned debugger session (#3298) — a full-capability session in the
 *  base-studio-code SOURCE tree that works the `bsc request` improvement queue (fixing `bsc ui`),
 *  hosted in its own OS window and toggled from Settings. */
export const DEBUG_STUDIO_SESSION_ID = "debug-studio:debugger";

/** The pane-id prefix shared by EVERY session in the debug studio: the standing debugger
 *  (`debug-studio:debugger`) and each auto-spawned per-request session (`debug-studio:req-<id>`,
 *  {@link poolPaneId}). Every one of them is the app's full-capability maintenance session in the
 *  source tree, so the prefix — not the singleton id — is what `isFullCapabilitySession` keys on. */
export const DEBUG_STUDIO_PANE_PREFIX = "debug-studio:";

/** Every fixed, app-owned studio session pane id. */
export const STUDIO_SESSION_PANE_IDS: readonly string[] = [
  ...DESIGNER_TECHS.map(designerSessionId),
  ...LIBRARIAN_TECHS.map(librarianSessionId),
  TEAMS_STUDIO_SESSION_ID,
  SOUND_STUDIO_SESSION_ID,
  INTEGRATION_STUDIO_SESSION_ID,
  DEBUG_STUDIO_SESSION_ID,
];

/** Whether `id` is a fixed, app-owned studio session (designer / librarian / architect / sound-designer /
 *  integrator) — excluded from
 *  crash recovery the way the planner (`isPlanningPaneId`) is: re-created when its workspace opens, never
 *  restored from the recovery banner. */
export function isStudioSessionPaneId(id: string): boolean {
  return STUDIO_SESSION_PANE_IDS.includes(id);
}

/** Whether `id` is a FULL-CAPABILITY app-owned session that must ALWAYS launch bypass + role-less,
 *  regardless of the global permission posture (`bypassPermissions`) — ANY session in the debug studio
 *  (#3326/#3520). Unlike a fleet/console pane, whose posture comes from the store (role/profile/flow + the
 *  global bypass toggle), a debug-studio session is BY DEFINITION the unrestricted maintenance session in
 *  the base-studio-code source tree; `buildSessionSettings` forces `bypass:true` for it. Role-less is
 *  automatic — no `paneRoles` entry is set for these panes and `studioRoleForPaneId` matches only the four
 *  fixed studios, so no role gate applies.
 *
 *  Matches the whole `debug-studio:` family, not just the singleton (#3520): the standing debugger AND each
 *  auto-spawned per-request session (`debug-studio:req-<id>`, #3498). A req session is the same kind of
 *  actor as the standing one — app-owned, in the source tree, working the request queue — and the control
 *  gate is the human reviewing its PR, not a per-tool permission prompt. Keying on the singleton id left
 *  the spawned sessions falling through to the global toggle, so they stopped to ask for every edit. */
export function isFullCapabilitySession(id: string): boolean {
  return id.startsWith(DEBUG_STUDIO_PANE_PREFIX);
}

// tabReorder -- pure helpers for moving a tab within the strip (#461).
//
// Tabs are identified by ARRAY INDEX, and a lot of state keys off that index
// (paneNames by tabIdx; paneCwds/paneStatus/disabledPanes/paneMcpServers/paneHooks
// by "t{tab}p{pane}"; focusQueue entries by {tab,pane}).
// Reordering the tabs array therefore has to remap every one of those keys or
// state bleeds onto the wrong tab. These functions are pure (no React/Tauri) so
// the remap is unit-testable; the store's `moveTab` action composes them.

import type { QueuedPane } from "@/app/console/lib/focusQueue";
// moveInArray now lives in shared/ (#1703 — a pure helper shouldn't force shared/
// to depend on app/). Re-exported here so existing consumers (the store's moveTab,
// the tab-reorder tests) keep their import path.
import { moveInArray } from "@/shared/lib/core/arrayMove";

export { moveInArray };

/** Map OLD tab index → NEW tab index after moving a tab from `from` to `to`
 *  (`result[oldIdx] = newIdx`). Identity for invalid/no-op moves. */
export function tabIndexMap(n: number, from: number, to: number): number[] {
  const order = moveInArray(Array.from({ length: n }, (_, i) => i), from, to); // order[newIdx] = oldIdx
  const newIndexOf = new Array<number>(n);
  order.forEach((oldIdx, newIdx) => { newIndexOf[oldIdx] = newIdx; });
  return newIndexOf;
}

/** Rekey a map keyed by tab index (number) through the index map. */
export function rekeyByTab<T>(map: Record<number, T>, newIndexOf: number[]): Record<number, T> {
  const out: Record<number, T> = {};
  for (const [k, v] of Object.entries(map)) {
    const oldTab = Number(k);
    out[newIndexOf[oldTab] ?? oldTab] = v;
  }
  return out;
}

/** Rekey a map keyed by "t{tab}p{pane}" through the index map. Keys that don't
 *  match that shape pass through untouched (so repo-/other-keyed maps are safe). */
export function rekeyByPaneId<T>(map: Record<string, T>, newIndexOf: number[]): Record<string, T> {
  const out: Record<string, T> = {};
  for (const [k, v] of Object.entries(map)) {
    const m = k.match(/^t(\d+)p(\d+)$/);
    if (!m) { out[k] = v; continue; }
    const newTab = newIndexOf[Number(m[1])] ?? Number(m[1]);
    out[`t${newTab}p${m[2]}`] = v;
  }
  return out;
}

/** Remap the tab index on each focus-queue entry. */
export function remapFocusQueue(queue: QueuedPane[], newIndexOf: number[]): QueuedPane[] {
  return queue.map((q) => ({ ...q, tab: newIndexOf[q.tab] ?? q.tab }));
}

// Team → fleet (#3101 / #3102): a project's TEAM (its persona-relationship graph, `blueprint.team`)
// seeds the fleet's ROLE-ACTOR streams. A team agent position bound to a lifecycle-role persona —
// curator, documentor, reviewer, tester, juror, issuer — becomes a fleet stream that launches WITH the
// fleet (at the project hub; the launch composition + hub cwd land in A-2), so "an actor is present if
// it's in the project's team" (#3101).
//
// WORKERS are deliberately NOT seeded here: a worker needs `owns` globs + `issues` only the planner can
// size, so worker/engineer positions stay planner-owned. The DIRECTOR is its own launch slot
// (`FleetDirector`), TRIAGE is per-repo, and the standing Studio roles (designer/architect/librarian) +
// the planner aren't fleet members — so none of those seed either. The MARKETER is opt-in (#2431): it
// only seeds when a team explicitly places one (Fleet Alpha does, #3143), never by default elsewhere.
//
// Pure (no React/Tauri) so it's unit-testable; the launch path (`usePlanPublish`, A-2) composes the
// result into the `FleetPlan` before `fleetStartProject`.
import type { BlueprintTeam } from "@/features/planner/stages/blueprintTypes";
import type { Persona } from "@/features/personas";
import type { SessionRole } from "@/shared/lib/session/sessionRoles";
import type { AgentStream } from "@/features/planner/fleet/planFleet";

/** The lifecycle role-actors a team position may seed into the fleet — project-wide singletons with no
 *  owned globs/issues (unlike a worker). One session each; deduped by role so a team never launches two
 *  curators/documentors/… and a planner-authored stream for a role always wins over the team's. */
export const SEEDABLE_TEAM_ROLES: ReadonlySet<SessionRole> = new Set<SessionRole>([
  "curator", "documentor", "reviewer", "tester", "juror", "issuer", "marketer",
]);

/** Slug a team position's `nodeId` into a fleet stream id: lowercase, `[a-z0-9-]`, collapsed — so it is
 *  safe as a pane-id tail (`<key>:<id>`) and a git branch name. Empty → `"role"`. */
function streamIdFromNode(nodeId: string): string {
  return (
    nodeId.toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/-{2,}/g, "-").replace(/^-+|-+$/g, "") || "role"
  );
}

/**
 * Derive the extra fleet streams a project's TEAM contributes — one per team agent position whose
 * persona is a {@link SEEDABLE_TEAM_ROLES} lifecycle actor, deduped by role against BOTH the planner's
 * existing streams and each other (these roles are singletons). Deterministic (positions in author
 * order). Returns `[]` for no team / no seedable positions.
 *
 * Each derived stream carries only its `persona` reference (which resolves role/prompt/skills/model at
 * launch) with empty `owns`/`issues`/`dependsOn` and an empty `repo` — a role-actor runs project-wide at
 * the hub, not inside a per-stream repo worktree (the launch routes it there in A-2).
 *
 * @param team      the project's blueprint team (positions + relationships), or undefined
 * @param personas  the persona library (resolves a position's `personaId` → its role/name)
 * @param existing  the planner's fleet streams — a role already covered by one is NOT re-seeded
 */
export function teamRoleStreams(
  team: BlueprintTeam | undefined,
  personas: Persona[],
  existing: ReadonlyArray<Pick<AgentStream, "persona">>,
): AgentStream[] {
  if (!team || team.positions.length === 0) return [];
  const byId = new Map(personas.map((p) => [p.id, p]));
  // Roles already present among the planner's streams (via each stream's persona) — never double a role.
  const covered = new Set<SessionRole>();
  for (const s of existing) {
    const role = s.persona ? byId.get(s.persona)?.role : undefined;
    if (role) covered.add(role);
  }
  const out: AgentStream[] = [];
  const seenIds = new Set<string>();
  for (const pos of team.positions) {
    if (pos.kind !== "agent" || !pos.personaId) continue;
    const persona = byId.get(pos.personaId);
    if (!persona || !SEEDABLE_TEAM_ROLES.has(persona.role)) continue;
    if (covered.has(persona.role)) continue; // a planner stream (or an earlier team position) owns this role
    covered.add(persona.role);
    let id = streamIdFromNode(pos.nodeId);
    while (seenIds.has(id)) id = `${id}-1`; // guard a pathological nodeId-slug collision
    seenIds.add(id);
    out.push({
      id,
      name: pos.label?.trim() || persona.name || persona.role,
      repo: "", // hub-scoped: runs at the project hub (A-2), not a repo worktree
      owns: [],
      issues: [],
      dependsOn: [],
      persona: persona.id,
    });
  }
  return out;
}

// The teams feature's graph-platform surface (register-the-feature-logic-surface) — the modules a
// graph-loaded record imports from this feature but does NOT redraw.
