// Teams-overview layout (#2742) — the NEW top graph level: every team is a card laid out in a grid, so
// the user navigates teams IN the graph (click a card to enter) instead of a header dropdown. Pure +
// deterministic (no Date/Math.random), so `teamsBounds` can drive the viewport fit exactly like the
// per-team `contentBounds`. Card boxes are in the same design space as position `nodeBox`es.
import type { Box } from "@/features/teams/lib/orgLayout";
import { positionDisplay } from "@/features/teams/lib/orgView";
import type { Team } from "@/features/teams/lib/team";
import type { Persona } from "@/features/personas";

export const TEAM_CARD_W = 288;
export const TEAM_CARD_H = 160;
const GAP_X = 40;
const GAP_Y = 44;
const ORIGIN_X = 60;
const ORIGIN_Y = 56;

/** Column count for `count` cards — a squarish grid, capped at 3 wide so cards stay readable. */
function columns(count: number): number {
  return Math.max(1, Math.min(3, Math.ceil(Math.sqrt(Math.max(1, count)))));
}

/** Grid boxes for `count` cells (team cards + the trailing "new team" card), row-major. */
export function teamsGrid(count: number): Box[] {
  const cols = columns(count);
  return Array.from({ length: count }, (_, i) => {
    const r = Math.floor(i / cols), c = i % cols;
    return {
      x: ORIGIN_X + c * (TEAM_CARD_W + GAP_X),
      y: ORIGIN_Y + r * (TEAM_CARD_H + GAP_Y),
      w: TEAM_CARD_W, h: TEAM_CARD_H,
    };
  });
}

/** The tight bounding box around all `count` cells — what the viewport fits/centers on (#2673-style). */
export function teamsBounds(count: number): Box | null {
  if (count <= 0) return null;
  const boxes = teamsGrid(count);
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const b of boxes) {
    minX = Math.min(minX, b.x); minY = Math.min(minY, b.y);
    maxX = Math.max(maxX, b.x + b.w); maxY = Math.max(maxY, b.y + b.h);
  }
  return { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
}

export interface TeamStats {
  positions: number;
  agents: number;
  resources: number;
  externals: number;
  /** Distinct departments present (from each position's `positionDisplay(...).dept`). */
  depts: string[];
}

/** Headline counts for a team card (positions by kind + the department spread). Pure. */
export function teamStats(team: Team, personas: Persona[]): TeamStats {
  const positions = team.positions.length;
  const agents = team.positions.filter((p) => p.kind === "agent").length;
  const resources = team.positions.filter((p) => p.kind === "resource").length;
  const externals = team.positions.filter((p) => p.kind === "external").length;
  const depts = [...new Set(team.positions.map((p) => positionDisplay(p, personas).dept))];
  return { positions, agents, resources, externals, depts };
}

// Team feature store slice (#2193) — the persona-relationship graph library, a WRITE-THROUGH cache over
// the global teams store (`~/.base-studio-code/orgs/`, reached via `bsc teams` — see orgBridge.ts). The
// desktop Team designer, live sessions, and the planner share ONE store. On boot `hydrateOrgs` loads
// through the bridge + reconciles the packaged built-ins; every mutation below pushes through. The
// persisted `teams` in app-state is just a fast first-paint cache; hydrate is authoritative.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import {
  BUILTIN_ORGS, blankOrg, orgSlug, reconcileOrgs, orgStructureKey,
  type Team, type Position, type Relationship,
} from "@/features/teams/lib/team";
import { loadOrgs, pushOrg, dropOrg } from "@/features/teams/lib/orgBridge";

export interface OrgSlice {
  /** The org library — packaged built-ins (reconciled on load) + user-authored. */
  teams: Team[];
  /** Last canvas zoom per org id (view state, persisted) so reopening an org restores its framing. */
  teamsZoom: Record<string, number>;
  /** Remember an org's canvas zoom. */
  setTeamsZoom: (orgId: string, zoom: number) => void;
  /** Hydrate the library from the global org store on boot (#2193): load via the bridge, reconcile the
   *  packaged built-ins, and push any newly-seeded built-in back so the store has it. No-op (keeps the
   *  seeded set) when the bridge is unreachable — tests, the web shell, or an old binary. */
  hydrateOrgs: () => Promise<void>;
  /** Create a user org and return its new id. */
  addOrg: () => string;
  /** Clone any org (incl. a built-in) into a new editable user org; returns the new id. */
  cloneOrg: (id: string) => string;
  /** Patch an org's editable fields. Built-ins keep their builtin identity; only user teams can be
   *  deleted. */
  updateOrg: (id: string, patch: Partial<Omit<Team, "id" | "builtin">>) => void;
  /** Remove a USER org (built-ins are not deletable — no-op). */
  removeOrg: (id: string) => void;
  /** Add a position (node) to an org. */
  addPosition: (orgId: string, position: Position) => void;
  /** Patch a position's fields (label, persona, x/y, …) by nodeId. */
  updatePosition: (orgId: string, nodeId: string, patch: Partial<Omit<Position, "nodeId">>) => void;
  /** Remove a position and every relationship touching it. */
  removePosition: (orgId: string, nodeId: string) => void;
  /** Add a relationship edge to an org. */
  addRelationship: (orgId: string, relationship: Relationship) => void;
  /** Patch a relationship (e.g. change its archetype) by id. */
  updateRelationship: (orgId: string, relationshipId: string, patch: Partial<Omit<Relationship, "id">>) => void;
  /** Remove a relationship by id. */
  removeRelationship: (orgId: string, relationshipId: string) => void;
}

/** Mint a fresh, collision-free user-org id from a name (or a generic seed). */
function mintOrgId(existing: Team[], name: string): string {
  const base = `org-${orgSlug(name)}`;
  if (!existing.some((o) => o.id === base)) return base;
  let n = 2;
  while (existing.some((o) => o.id === `${base}-${n}`)) n++;
  return `${base}-${n}`;
}

export const createOrgSlice: StateCreator<AppStore, [], [], OrgSlice> = (set, get) => {
  /** Patch one org in place, push the result through the bridge. Central so every mutation converges. */
  const mutate = (id: string, fn: (o: Team) => Team) => {
    let updated: Team | undefined;
    set((s) => ({
      teams: s.teams.map((o) => {
        if (o.id !== id) return o;
        updated = fn(o);
        return updated;
      }),
    }));
    if (updated) void pushOrg(updated);
  };

  return {
    teams: BUILTIN_ORGS,
    teamsZoom: {},

    setTeamsZoom: (orgId, zoom) => set((s) => ({ teamsZoom: { ...s.teamsZoom, [orgId]: zoom } })),

    hydrateOrgs: async () => {
      const loaded = await loadOrgs();
      if (!loaded) return; // bridge unreachable — keep the seeded built-ins
      const reconciled = reconcileOrgs(loaded);
      set({ teams: reconciled });
      // Refresh the on-disk store so `bsc teams` (sessions + the planner) sees the SAME reconciled library
      // the UI does (#3330). Push back any built-in that's MISSING (first run / a new packaged org) OR whose
      // on-disk copy has DRIFTED from the packaged def — the latter is the stale-seed fix: a built-in seeded
      // at an old version (frozen on disk) is re-pushed to the current packaged structure. User teams are
      // never touched here (they aren't in BUILTIN_ORGS / reconciled built-ins).
      const savedKey = new Map(loaded.map((o) => [o.id, orgStructureKey(o)]));
      for (const o of reconciled) {
        if (!o.builtin) continue;
        const prior = savedKey.get(o.id);
        if (prior === undefined || prior !== orgStructureKey(o)) void pushOrg(o);
      }
    },

    addOrg: () => {
      const id = mintOrgId(get().teams, "new team");
      const org = blankOrg(id);
      set((s) => ({ teams: [...s.teams, org] }));
      void pushOrg(org);
      return id;
    },

    cloneOrg: (id) => {
      const src = get().teams.find((o) => o.id === id);
      if (!src) return id;
      const name = `${src.name} copy`;
      const newId = mintOrgId(get().teams, name);
      const clone: Team = { ...src, id: newId, name, builtin: false };
      set((s) => ({ teams: [...s.teams, clone] }));
      void pushOrg(clone);
      return newId;
    },

    updateOrg: (id, patch) => mutate(id, (o) => ({ ...o, ...patch, id: o.id, builtin: o.builtin })),

    removeOrg: (id) => {
      const target = get().teams.find((o) => o.id === id);
      if (!target || target.builtin) return; // built-ins are not deletable
      set((s) => ({ teams: s.teams.filter((o) => o.id !== id) }));
      void dropOrg(id);
    },

    addPosition: (orgId, position) =>
      mutate(orgId, (o) => ({ ...o, positions: [...o.positions, position] })),

    updatePosition: (orgId, nodeId, patch) =>
      mutate(orgId, (o) => ({
        ...o,
        positions: o.positions.map((p) => (p.nodeId === nodeId ? { ...p, ...patch, nodeId: p.nodeId } : p)),
      })),

    removePosition: (orgId, nodeId) =>
      mutate(orgId, (o) => ({
        ...o,
        positions: o.positions.filter((p) => p.nodeId !== nodeId),
        // Drop every edge that touched the removed node so the graph stays well-formed.
        relationships: o.relationships.filter((r) => r.from !== nodeId && r.to !== nodeId),
      })),

    addRelationship: (orgId, relationship) =>
      mutate(orgId, (o) => ({ ...o, relationships: [...o.relationships, relationship] })),

    updateRelationship: (orgId, relationshipId, patch) =>
      mutate(orgId, (o) => ({
        ...o,
        relationships: o.relationships.map((r) => (r.id === relationshipId ? { ...r, ...patch, id: r.id } : r)),
      })),

    removeRelationship: (orgId, relationshipId) =>
      mutate(orgId, (o) => ({ ...o, relationships: o.relationships.filter((r) => r.id !== relationshipId) })),
  };
};

// `{{NAME}}` placeholder filling for `@data`-seeded prompt templates (#2416). The prompt PROSE lives
// in JSON under `src-tauri/data/` (editable without a rebuild via the config-dir overlay, #2047);
// TS keeps only the interpolation — this helper is that interpolation step.

/**
 * Substitute every `{{NAME}}` placeholder in `template` with `vars[NAME]`.
 *
 * Uses a replacer FUNCTION (not a replacement string), so `$`-sequences in a value are inserted
 * verbatim rather than interpreted as regex replacement patterns. A placeholder with no entry in
 * `vars` is left untouched — a visible `{{…}}` in rendered output beats silently dropping prose,
 * and callers that must guarantee full substitution can assert on it.
 */
export function fillTemplate(template: string, vars: Record<string, string>): string {
  return template.replace(/\{\{(\w+)\}\}/g, (whole, name: string) =>
    Object.prototype.hasOwnProperty.call(vars, name) ? vars[name] : whole,
  );
}

// Terminal clipboard (#3157) — copy-on-select + paste for the app's xterm terminals (both the console
// panes, `TerminalView`, and the app-owned screen sessions, `useScreenSession`). The terminals had NO
// clipboard handling: Ctrl+C is SIGINT (can't be copy), and Ctrl+Shift+C — the usual terminal copy chord —
// is claimed by the WebView2 DevTools "inspect" accelerator AND the app's broadcast-toggle. So:
//   • COPY-ON-SELECT — selecting text auto-copies (writeText, already proven in this app). No key needed,
//     which sidesteps the Ctrl+Shift+C conflict entirely.
//   • PASTE — Ctrl+Shift+V / Shift+Insert / right-click read the clipboard and `pty_write` it (these chords
//     don't collide with the DevTools accelerator, so paste works standalone).
// Feature-agnostic (shared/), so both terminal sites wire the identical behavior. Must be called AFTER
// `term.open()` — it needs `term.element` for the mouse listeners.
import type { Terminal } from "@xterm/xterm";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";

/**
 * Wire copy-on-select + paste onto an open xterm `term`, sending pasted text to the PTY `paneId`.
 * Returns a disposer to call on terminal teardown (removes the DOM listeners; xterm keeps a single custom
 * key handler that goes away when the terminal is disposed).
 */
export function attachTerminalClipboard(term: Terminal, paneId: string): () => void {
  const el = term.element;
  const disposers: Array<() => void> = [];

  // ── COPY-ON-SELECT ── on mouse-up, copy the current selection (one write per finished selection, vs
  // `onSelectionChange` which fires continuously during a drag). A no-selection mouse-up (a plain click,
  // or a click that clears a selection) writes nothing, so it never clobbers the clipboard with "".
  const onMouseUp = () => {
    const sel = term.getSelection();
    if (sel) void navigator.clipboard?.writeText(sel).catch(() => {});
  };
  el?.addEventListener("mouseup", onMouseUp);
  if (el) disposers.push(() => el.removeEventListener("mouseup", onMouseUp));

  // ── PASTE ── read the clipboard and send it to the PTY (the shell / TUI echoes it back). A blocked/denied
  // read is a silent no-op (the caller can escalate to a native clipboard plugin if a webview ever refuses).
  const paste = () => {
    const read = navigator.clipboard?.readText?.();
    if (!read) return;
    void read
      .then((text) => { if (text) fireInvoke("pty_write", { paneId, data: text }, console.error); })
      .catch(() => {});
  };

  // Right-click pastes (terminal convention); suppress the browser context menu so it doesn't also open.
  const onContextMenu = (e: MouseEvent) => { e.preventDefault(); paste(); };
  el?.addEventListener("contextmenu", onContextMenu);
  if (el) disposers.push(() => el.removeEventListener("contextmenu", onContextMenu));

  // Ctrl+Shift+V / Shift+Insert paste. Returning FALSE stops xterm from ALSO sending the keys to the PTY,
  // and `preventDefault` stops a native paste event from double-firing. Ctrl+Shift+C copy is deliberately
  // NOT bound here — copy-on-select covers it, and on Windows that chord is eaten by the DevTools
  // accelerator until the separate layer-1 fix disables the WebView2 browser accelerator keys.
  term.attachCustomKeyEventHandler((e) => {
    if (e.type !== "keydown") return true;
    const paste_v = e.ctrlKey && e.shiftKey && !e.altKey && !e.metaKey && (e.key === "V" || e.key === "v");
    const paste_ins = e.shiftKey && !e.ctrlKey && !e.altKey && !e.metaKey && e.key === "Insert";
    if (paste_v || paste_ins) {
      e.preventDefault();
      paste();
      return false;
    }
    return true;
  });

  return () => { for (const d of disposers) d(); };
}

// Terminal render/theme constants shared by the xterm PTY mount (TerminalView).
// Pure module-level values — no xterm/PTY/React coupling — extracted so the mount
// module stays focused on the effect wiring.

// Background-pane buffer cap. While a pane is hidden we skip xterm.write
// entirely and accumulate the PTY bytes here; on becoming visible we flush
// them in one go. 256 KB ≈ a few thousand lines of dense output — generous for
// realistic switch-away durations and far above what's likely useful before
// xterm's own scrollback truncates it anyway.
export const PENDING_BYTES_CAP = 256 * 1024;

// Grace before the automatic post-launch redraw nudge (#1221) — long enough for Claude's TUI to
// finish its first paint, so the nudge repaints a fully-drawn (and possibly jumbled) screen rather
// than an empty one. The nudge is idempotent + non-destructive, so an imprecise delay is harmless.
export const AUTO_NUDGE_DELAY_MS = 700;

// Mid-session jumble probe (#1250): at each Claude settle, sample the bottom input-box rows and
// auto-nudge when the box chrome is shattered. Hysteresis — two malformed samples (the settle + one
// quick re-check) before firing — so a lone mid-draw frame doesn't trigger a needless repaint.
// (#1239 reverted the input overlay/clip box, so these now guard Claude's own native input box.)
export const JUMBLE_CHROME_ROWS = 10; // bottom viewport rows that hold Claude's input box + hint lines
export const JUMBLE_STRIKES = 2;
export const JUMBLE_RECHECK_MS = 250;

// Hex equivalents of the oklch design tokens so xterm can use them
export const TERM_THEME: import("@xterm/xterm").ITheme = {
  background:          "#181a1f",
  foreground:          "#eeeae4",
  cursor:              "#c4923a",
  cursorAccent:        "#181a1f",
  selectionBackground: "#c4923a44",
  black:               "#181a1f", brightBlack:   "#44474f",
  red:                 "#d4554f", brightRed:     "#e06c75",
  green:               "#5fb467", brightGreen:   "#98c379",
  yellow:              "#c4923a", brightYellow:  "#e5c07b",
  blue:                "#5694c7", brightBlue:    "#61afef",
  magenta:             "#9b59b6", brightMagenta: "#c678dd",
  cyan:                "#4aabb5", brightCyan:    "#64d5e4",
  white:               "#939aa4", brightWhite:   "#eeeae4",
};

// Terminal key remapping (#4134) — the keys xterm's defaults get wrong for an agent TUI.
//
// SHIFT+ENTER. xterm.js maps Enter to a bare CR (`\r`) and ignores modifiers, so Shift+Enter is
// byte-identical to Enter: the prompt SUBMITS where the user meant to insert a newline. That is true of
// every terminal in this app — the docked Algorithms/Components sessions and Console panes all render the
// one `TerminalView` — so it reads as page-specific but never was.
//
// The remedy is the same one Claude Code's own `/terminal-setup` installs for hosts that don't emit it
// natively. Taken from the shipped binary rather than from memory:
//
//     VS Code   "args": { "text": "\u001b\r" }
//     iTerm2    chars = "\u001B\r"
//
// i.e. ESC + CR. (iTerm2, WezTerm, Ghostty, Kitty, Warp and Windows Terminal send it natively; xterm.js
// does not, which is why we send it here.)
//
// Pure + exported so the mapping is unit-testable without a terminal, and so there is ONE definition
// rather than a magic string inside an event handler.

/** ESC + CR — the "newline, don't submit" sequence an agent TUI expects for Shift+Enter. */
export const SHIFT_ENTER_BYTES = "\x1b\r";

/** A keyboard event, narrowed to what the mapping actually reads. */
export interface TerminalKeyEvent {
  type: string;
  key: string;
  shiftKey: boolean;
  ctrlKey: boolean;
  altKey: boolean;
  metaKey: boolean;
}

/**
 * The bytes this app sends INSTEAD of xterm's default for `e`, or `null` to let xterm handle it.
 *
 * Deliberately narrow: only an unmodified-apart-from-Shift **keydown** of Enter is remapped. Ctrl+Enter,
 * Alt+Enter and Meta+Enter keep whatever xterm does with them today — an agent TUI may bind those
 * separately, and silently swallowing them would trade one broken key for three.
 */
export function terminalKeyOverride(e: TerminalKeyEvent): string | null {
  if (e.type !== "keydown") return null; // the same event arrives again as keyup; remap once
  if (e.key !== "Enter") return null;
  if (!e.shiftKey || e.ctrlKey || e.altKey || e.metaKey) return null;
  return SHIFT_ENTER_BYTES;
}

// Resize-nudge sizing (#1221). Pure so the transient-then-restore PTY sizes are unit-testable
// without spinning up xterm in jsdom. The nudge forces the Claude CLI's TUI to repaint by briefly
// shrinking the PTY by one COLUMN — a guaranteed SIGWINCH — then settling back to the true fitted
// size; a column delta (not rows) avoids the #1158 growing-host input clip box.

export interface NudgeSizes {
  /** The transient size that triggers the SIGWINCH (one column narrower). */
  transient: { cols: number; rows: number };
  /** The real fitted size to settle back to — net dimensions unchanged after the nudge. */
  restore: { cols: number; rows: number };
}

/** The two PTY sizes a resize-nudge issues. Returns `null` when there's nothing safe to shrink
 *  (cols ≤ 1), so the caller skips the nudge rather than resizing to a zero/negative width. */
export function nudgeSizes(cols: number, rows: number): NudgeSizes | null {
  if (!Number.isFinite(cols) || !Number.isFinite(rows) || cols <= 1) return null;
  return { transient: { cols: cols - 1, rows }, restore: { cols, rows } };
}

// Terminal tuning shared across console panes.

import { clamp } from "@/shared/lib/core/math";

/**
 * Scrollback line budget for one pane, scaled down as the total mounted-pane
 * count across ALL tabs grows.
 *
 * xterm retains every scrollback line in renderer memory, so N panes each
 * holding a deep buffer multiplies fast — a 4×4 triage (16 panes) at a flat
 * 10k lines is ~160k buffered lines and a prime suspect for renderer OOM.
 * #187 made every tab's panes stay mounted (so xterm + scrollback survive tab
 * switches), which means a 2-tab × 16-pane workspace is now 32 mounted panes,
 * not 16. The buckets below preserve the single-tab budgets so existing
 * workflows don't regress, then extend downward for the cross-tab reality.
 *
 * @param paneCount total panes mounted across every tab in the workspace.
 */
export function scrollbackForPaneCount(paneCount: number): number {
  if (paneCount <= 1)  return 10000;
  if (paneCount <= 4)  return 6000;
  if (paneCount <= 9)  return 3000;
  if (paneCount <= 16) return 1500; // single 4×4 tab — unchanged
  if (paneCount <= 32) return 1000; // ~two heavy tabs
  return 500;                       // 33+ — large fleets across many tabs
}

/**
 * Sum every tab's `cols × rows` so {@link scrollbackForPaneCount} can size each
 * pane's buffer against the workspace-wide load, not just its own tab's grid.
 * Layout values that don't parse fall back to a 1×1 cell.
 */
export function totalMountedPaneCount(tabs: ReadonlyArray<{ layout: string }>): number {
  return tabs.reduce((sum, tab) => {
    const [c, r] = tab.layout.split("×").map(Number);
    return sum + (c || 1) * (r || 1);
  }, 0);
}

// ── Terminal font zoom (Ctrl++ / Ctrl+- / Ctrl+0) ──────────────────────────────

/** Default xterm font size (px) for console panes — matches the unzoomed baseline. */
export const DEFAULT_TERMINAL_FONT_SIZE = 12;
/** Legible floor: below this, rows fit but the text isn't worth reading. */
export const MIN_TERMINAL_FONT_SIZE = 8;
/** Practical ceiling so a single pane can't swallow the whole grid. */
export const MAX_TERMINAL_FONT_SIZE = 28;
/** Pixels added/removed per zoom step. */
export const TERMINAL_FONT_STEP = 1;

/**
 * Clamp a font size to the legible range, rounded to whole px. Non-finite input
 * (corrupt persisted value) falls back to the default rather than breaking xterm.
 */
export function clampFontSize(size: number): number {
  if (!Number.isFinite(size)) return DEFAULT_TERMINAL_FONT_SIZE;
  return clamp(Math.round(size), MIN_TERMINAL_FONT_SIZE, MAX_TERMINAL_FONT_SIZE);
}

/**
 * Resolve the next terminal font size when zooming by `steps` (e.g. +1 in, -1 out),
 * clamped to the legible range. Stepping past a bound is a no-op (stays clamped).
 */
export function adjustFontSize(current: number, steps: number): number {
  return clampFontSize(current + steps * TERMINAL_FONT_STEP);
}

// The frontend ↔ theme-store bridge (#2488) — the kit-theme collection is a GLOBAL store reached,
// from the UI AND from a live session's own shell, through the SAME `bsc ui theme …` CLI over the
// generic `bsc` bridge (#2114). Mirrors componentBridge.ts: `loadThemes` returns `null` when the
// bridge is unreachable (tests / web shell / an old bundled `bsc`) so the slice keeps its packaged
// seed rather than blanking it; the writes are fire-and-forget.
import { bsc, bscRun, bscWrite } from "@/shared/lib/core/bsc";
import type { KitThemeRecord } from "@/features/designs/lib/themes";
import type { VariantDef } from "@/shared/ui/kit";

/** Load every stored component-variant definition via `bsc ui variants` (#2569); `null` when the bridge
 *  is unreachable (an old bundled `bsc` without the verb) so the app keeps whatever it already applied.
 *  Defensive shape gate: a row must carry string `component`/`variant` and an object `tokens`. */
export async function loadVariants(): Promise<VariantDef[] | null> {
  try {
    const out = await bsc(null, ["ui", "variants"]);
    const rows = JSON.parse(out.trim() || "[]") as Partial<VariantDef>[];
    return (rows ?? []).filter(
      (v): v is VariantDef =>
        typeof v.component === "string" && typeof v.variant === "string" && !!v.tokens && typeof v.tokens === "object",
    );
  } catch {
    return null;
  }
}

/** Load every theme via `bsc ui theme list --full`; `null` when unreachable.
 *
 *  Defensive shape gate: a row must carry `id`, `label`, AND an object `vars`. An OLD bundled `bsc`
 *  (pre-#2488) ignores `--full` and prints the lean `{id, label, description}` projection — those
 *  var-less rows are dropped here, so the hydrate sees an empty store and re-seeds rather than
 *  caching themes whose override maps were lost. */
export async function loadThemes(): Promise<KitThemeRecord[] | null> {
  try {
    const out = await bsc(null, ["ui", "theme", "list", "--full"]);
    const rows = JSON.parse(out.trim() || "[]") as Partial<KitThemeRecord>[];
    return (rows ?? [])
      .filter(
        (t): t is KitThemeRecord =>
          typeof t.id === "string" && !!t.id && typeof t.label === "string" &&
          !!t.vars && typeof t.vars === "object",
      )
      .map((t) => ({
        id: t.id,
        // The design group (#2749) — required + seed-relevant, so it must ride the round-trip
        // verbatim (never defaulted for a current row, or the reloaded copy hashes differently from
        // its stamp). A legacy/pre-#2749 row with no `tech` predates the axis: React is the only
        // design group it could have belonged to, so it materializes under `react` (the reconcile
        // then refreshes a pristine built-in to the seed's `tech` anyway).
        tech: t.tech ?? "react",
        label: t.label,
        description: t.description ?? "",
        // `base` is seed-relevant content and must ride WITHOUT normalizing (#2514 round-trip
        // contract): absent stays absent (never defaulted) so a base-less theme still hashes to its
        // stamp. Spread so the key is omitted entirely when the source row has no `base`.
        ...(t.base !== undefined ? { base: t.base } : {}),
        vars: t.vars,
        builtin: t.builtin,
        seedHash: t.seedHash, // #2483 — must ride or the refresh baseline is lost on write-through
      }));
  } catch {
    return null;
  }
}

/** Write-through a theme upsert (`bsc ui theme set`, JSON on stdin). Never throws (an old bundled
 *  `bsc` without the theme store verbs degrades to cache-only). */
export async function pushTheme(theme: KitThemeRecord): Promise<void> {
  try { await bscWrite(null, ["ui", "theme", "set"], theme); } catch { /* store unreachable — cache-only */ }
}

/** Write-through a theme removal (`bsc ui theme remove <id>`). Never throws. */
export async function dropTheme(id: string): Promise<void> {
  try { await bscRun(null, ["ui", "theme", "remove", id]); } catch { /* store unreachable — cache-only */ }
}

// The kit THEME axis (#1852 Phase 3) — the third orthogonal axis of the UI kit (style × theme × spec).
// A theme is a map of overrides for the semantic component tokens (`--card-*`/`--btn-*`/`--field-*`/
// `--chip-*` in styles/tokens.css). Applying a theme just sets those CSS custom properties — globally
// on :root (`applyThemeToRoot`, the accent's mechanism) or scoped on a subtree (`<ThemeScope>`), so
// every `.card`/`.btn`/`.input`/`.chip` follows without touching any component's markup or a spec's
// structure.
//
// TWO sources compose here (#2488): the PACKAGED registry (`@data/ui/themes.json`, also embedded by
// `bsc ui theme`) is the boot fallback, and the designer-writable theme STORE (hydrated on boot by the
// components slice via `bsc ui theme list --full`) is the live set once reachable. The hydrate pushes
// the store's collection in through `setActiveKitThemes`, so every consumer of `themeById`/`themeVars`/
// `applyThemeToRoot`/`<ThemeScope>` resolves against the SAME set without importing the Zustand store
// (which would cycle: store → features → shared). Pure (the root apply takes the element as a param)
// → unit-testable.

import type { CSSProperties } from "react";
import THEMES_DATA from "@data/ui/themes.json";

export interface KitTheme {
  /** Stable id persisted in the store + used by `bsc ui theme get`. */
  id: string;
  /** The DESIGN GROUP this theme belongs to (#2749) — the lowercase `tech` slug a kit carries
   *  (`react`, `vue`, …). REQUIRED and 1:1 from the theme's side: a theme belongs to exactly one
   *  design group (a group hosts its own set of themes), so `bsc ui theme set`/`validate` reject a
   *  theme with no `tech` and the Themes page groups by it. Not optional — a theme is meaningless
   *  without the group whose token contract it is resolved and emitted against. */
  tech: string;
  label: string;
  description: string;
  /** The SURFACE the theme sits on (#2545). Absent ⇒ `"dark"` (the historical base). The Design
   *  Studio preview reads this to pick its sandbox surface, so light/dark is theme data (seeded in
   *  `@data/ui/themes.json`, then served by `bsc ui theme`) rather than a hardcoded toggle. */
  base?: "dark" | "light";
  /** Semantic-token overrides — CSS var name → value. Empty for the base look. */
  vars: Record<string, string>;
}

/** The PACKAGED built-in themes, in registry order (`default` first) — the boot fallback (#2488). */
export const KIT_THEMES: KitTheme[] = (THEMES_DATA as unknown as { themes: KitTheme[] }).themes;

export const DEFAULT_THEME = "default";

/** The live theme set: the hydrated store collection once `setActiveKitThemes` ran, else packaged. */
let activeThemes: KitTheme[] = KIT_THEMES;

/** Sync the hydrated store collection in (#2488). An empty array resets to the packaged registry, so
 *  a degenerate hydrate can never blank every theme. Called by the components slice's
 *  `hydrateThemes`; tests call it directly (and reset with `setActiveKitThemes([])`). */
export function setActiveKitThemes(themes: KitTheme[]): void {
  activeThemes = themes.length ? themes : KIT_THEMES;
}

/** The current theme set — hydrated store themes when available, else the packaged registry. */
export function activeKitThemes(): KitTheme[] {
  return activeThemes;
}

/** The theme for an id, falling back to `default` (so a corrupt persisted value can't blank the UI).
 *  Resolves against the live set first, then the packaged registry (the hydrated set always contains
 *  the built-ins — the reconcile re-seeds them — so the packaged hop is a belt-and-braces fallback). */
export function themeById(id: string | undefined): KitTheme {
  return (
    activeThemes.find((t) => t.id === id) ??
    activeThemes.find((t) => t.id === DEFAULT_THEME) ??
    KIT_THEMES.find((t) => t.id === DEFAULT_THEME) ??
    KIT_THEMES[0]
  );
}

/** A theme's overrides as a style object — spread onto a subtree's `style` for scoped application. */
export function themeVars(id: string | undefined): CSSProperties {
  return { ...themeById(id).vars } as CSSProperties;
}

/** The union of every token any PACKAGED theme touches. Kept for compatibility; the apply path uses
 *  {@link kitTokens}, which also covers store-authored themes. */
export const KIT_TOKENS: string[] = Array.from(
  new Set(KIT_THEMES.flatMap((t) => Object.keys(t.vars))),
);

/** The union of every token any CURRENT theme (live set ∪ packaged) touches — the set to CLEAR when
 *  switching, so a prior theme's overrides don't linger after moving to one that doesn't set them. */
export function kitTokens(): string[] {
  return Array.from(
    new Set([...activeThemes, ...KIT_THEMES].flatMap((t) => Object.keys(t.vars))),
  );
}

/**
 * Apply a theme GLOBALLY by writing its overrides to a root element's inline style — and clearing any
 * kit token a prior theme set that this one doesn't, so switching fully resets to the stylesheet
 * defaults. Mirrors the accent apply in `useAppBoot`.
 *
 * @param id - the theme id (falls back to `default`)
 * @param root - the element to write to (defaults to `document.documentElement`; param'd for tests)
 */
export function applyThemeToRoot(id: string | undefined, root: HTMLElement = document.documentElement): void {
  const { vars } = themeById(id);
  for (const token of kitTokens()) {
    if (token in vars) root.style.setProperty(token, vars[token]);
    else root.style.removeProperty(token);
  }
}

// The kit-theme collection's pure domain (#2488) — the store-record shape, the packaged seed, and the
// reconcile/ordering helpers. Themes became a designer-writable store collection (`bsc ui theme
// set/remove` over `~/.base-studio-code/themes/`): the PACKAGED registry (`@data/ui/themes.json`, via
// `KIT_THEMES`) seeds it, and the #2483 hash-based `reconcileSeed` keeps the built-ins fresh across
// releases while never clobbering a designer-edited copy. React/Tauri-free (the bridge lives in
// themeBridge.ts) → unit-testable.

import { KIT_THEMES, type KitTheme } from "@/shared/ui/kit";
import { reconcileSeed, stampSeedHash, type SeedReconcile } from "@/features/designs/lib/seedRefresh";

/** A theme as the STORE holds it: the packaged shape plus the seed-tracking provenance (#2483). */
export interface KitThemeRecord extends KitTheme {
  /** A packaged built-in. Absent/false ⇒ designer/user-authored (never touched by the reconcile). */
  builtin?: boolean;
  /** The content hash stamped when this copy was seeded (#2483). */
  seedHash?: string;
}

/** The packaged built-in themes as seed records — `builtin` + `seedHash` stamped at assembly time
 *  (the packaged JSON never bakes them in), mirroring `makeBuiltinKits`. */
export const SEED_THEMES: KitThemeRecord[] = KIT_THEMES.map((t) => stampSeedHash({ ...t, builtin: true }));

/** Reconcile the store's loaded themes with the packaged built-ins (#2483 — the full verdict table
 *  lives on {@link reconcileSeed}): a PRISTINE built-in copy tracks the seed (refreshed/deleted), a
 *  designer-EDITED one is kept (with a notice when the seed diverged), user-authored themes are never
 *  touched, and missing built-ins are re-seeded. `hydrateThemes` applies the pushes/drops. */
export function reconcileThemes(loaded: KitThemeRecord[]): SeedReconcile<KitThemeRecord> {
  return reconcileSeed(loaded, SEED_THEMES, "theme");
}

/** Deterministic display order for the pickers: the packaged registry order first (`default` leads),
 *  then every other (designer-authored) theme sorted by label. The store's on-disk listing order is
 *  filesystem-dependent, so the hydrate normalizes here. */
export function orderThemes(records: KitThemeRecord[]): KitThemeRecord[] {
  const seedRank = new Map(KIT_THEMES.map((t, i) => [t.id, i]));
  const packaged = records
    .filter((r) => seedRank.has(r.id))
    .sort((a, b) => seedRank.get(a.id)! - seedRank.get(b.id)!);
  const authored = records
    .filter((r) => !seedRank.has(r.id))
    .sort((a, b) => a.label.localeCompare(b.label));
  return [...packaged, ...authored];
}

/** The bucket a theme with no `tech` falls into (#2749). `tech` is required, but a corrupt persisted
 *  copy must never crash the page — it groups here, always ordered last. */
export const OTHER_GROUP = "other";

/** A design-group section on the Themes page (#2749): one `tech` group and the themes under it,
 *  mirroring how the Designs rail groups kits by their `tech` axis. */
export interface ThemeGroup {
  /** The design-group slug (`react`, …); {@link OTHER_GROUP} for a theme with no `tech`. */
  tech: string;
  /** The header label (the raw slug — the gallery uppercases it like the Designs `ds-grouphead`). */
  label: string;
  themes: KitThemeRecord[];
}

/** Group themes by their design group (#2749) for the grouped Themes page: one section per `tech`,
 *  themes kept in {@link orderThemes} order within a group, groups ordered by first appearance with
 *  the missing-`tech` bucket forced last. Pure → unit-tested. */
export function groupThemes(records: KitThemeRecord[]): ThemeGroup[] {
  const byTech = new Map<string, KitThemeRecord[]>();
  for (const t of orderThemes(records)) {
    const tech = (t.tech ?? "").trim() || OTHER_GROUP;
    const arr = byTech.get(tech);
    if (arr) arr.push(t);
    else byTech.set(tech, [t]);
  }
  const other = byTech.get(OTHER_GROUP);
  if (other && byTech.size > 1) {
    byTech.delete(OTHER_GROUP);
    byTech.set(OTHER_GROUP, other); // force the defensive bucket last
  }
  return [...byTech].map(([tech, themes]) => ({ tech, label: tech, themes }));
}

// Tool permission presets + the common-tool suggestion list for the Claude Config editor (#1709).
// Kept as typed TS data (NOT JSON, per project decision) so the shapes stay type-checked and the
// preset table reads as code alongside its consumers.

/** A one-click allow/deny pair applied to the tool-permission editor. */
export interface ToolPreset {
  label: string;
  allow: string[];
  deny: string[];
}

export const TOOL_PRESETS: ToolPreset[] = [
  { label: "read-only",  allow: ["Read", "Glob", "Grep"],                        deny: ["Write", "Edit", "MultiEdit", "Bash", "WebFetch", "WebSearch"] },
  { label: "no-bash",    allow: [],                                               deny: ["Bash"] },
  { label: "no-web",     allow: [],                                               deny: ["WebFetch", "WebSearch"] },
  { label: "full",       allow: [],                                               deny: [] },
];

/** Suggestions surfaced in the chip-input datalist when typing a tool name. */
