use std::collections::{HashMap, VecDeque};

/// Kahn's algorithm — a topological ordering of a DAG, or `None` if a cycle is present.
pub fn topological_sort(adj: &HashMap<String, Vec<(String, u32)>>) -> Option<Vec<String>> {
    let mut indegree: HashMap<String, usize> = HashMap::new();
    for (node, edges) in adj {
        indegree.entry(node.clone()).or_insert(0);
        for (next, _) in edges {
            *indegree.entry(next.clone()).or_insert(0) += 1;
        }
    }
    let mut queue: VecDeque<String> = indegree
        .iter()
        .filter(|(_, &d)| d == 0)
        .map(|(n, _)| n.clone())
        .collect();
    let mut order = Vec::new();
    while let Some(node) = queue.pop_front() {
        order.push(node.clone());
        if let Some(edges) = adj.get(&node) {
            for (next, _) in edges {
                let d = indegree.get_mut(next).unwrap();
                *d -= 1;
                if *d == 0 {
                    queue.push_back(next.clone());
                }
            }
        }
    }
    if order.len() == indegree.len() {
        Some(order)
    } else {
        None
    }
}

// The trace streaming engine (#3176, epic #3171) — a lazy, bounded, scrub-able cursor over a trace
// `Generator<Frame>`. PURE + React-free (the testable heart; `<TracePlayer>` is a thin React driver on top).
//
// The trace is a LAZY generator pulled at play speed (not pushed to a queue) — O(1) memory + automatic
// backpressure: the generator is suspended between yields and only produces the next frame when the
// player pulls it. A 100k-step run never materializes 100k frames — only the current frame + the
// generator's own suspended state (O(input)) are held.
//
//   • Scrub-back: a bounded RING BUFFER (~500 frames) keeps the recent window, so stepping back is free.
//   • Scrub OLDER than the window: DETERMINISTIC REPLAY — the trace is a pure function of the input, so
//     we re-run the factory from the start to the target index and rebuild the window. Cheap + exact.
//
// The real limit is watchability, not memory (cap mock-input size upstream; this engine just streams).

import type { Frame } from "@/features/algorithms/lib/trace";

/** Default recent-window size — how many trailing frames stay buffered for free scrub-back (#3171). */
export const DEFAULT_BUFFER_SIZE = 500;

export interface TraceStreamOptions {
  /** Ring-buffer capacity — the recent-window size for scrub-back. Default {@link DEFAULT_BUFFER_SIZE}.
   *  Scrubbing older than this replays the generator from the start (deterministic + cheap). */
  bufferSize?: number;
}

/**
 * A cursor over a trace. `next` advances one frame (pulling from the live generator at the frontier, or
 * re-reading the buffer after a scrub-back); `seek` jumps to an absolute index (buffered → free, older
 * than the window → deterministic replay, past the frontier → pulls forward, clamping at the end).
 * `current`/`index` read the cursor. Before the first advance the cursor is at -1 and `current` is null.
 */
export interface TraceStream {
  /** The frame at the cursor, or null before the first advance / when the trace is empty. */
  current(): Frame | null;
  /** Advance one frame and return it, or null at the end of the trace (the cursor stays put). */
  next(): Frame | null;
  /** Jump to absolute index `i` and return that frame (clamped to `[0, last]`; `i < 0` → null cursor). */
  seek(i: number): Frame | null;
  /** The current absolute frame index (-1 before the first advance). */
  index(): number;
  /** Whether the generator is exhausted AND the cursor sits on the last frame (nothing more to pull). */
  atEnd(): boolean;
}

/**
 * A fixed-capacity ring buffer keyed by ABSOLUTE frame index. Every absolute index `i` lives in slot
 * `i % capacity` (guaranteed because pushes are strictly sequential from `clear`), so `get(i)` is O(1)
 * and eviction is just advancing `start`. Holds the window `[start, start + count)`.
 */
class Ring {
  private buf: (Frame | undefined)[];
  private start = 0; // absolute index of the oldest retained frame
  private count = 0; // number retained (≤ capacity)

  constructor(readonly capacity: number) {
    this.buf = new Array(capacity);
  }

  /** Append the next sequential frame; evict the oldest once full. */
  push(frame: Frame): void {
    this.buf[(this.start + this.count) % this.capacity] = frame;
    if (this.count < this.capacity) this.count++;
    else this.start++; // full → evict the oldest by advancing the window
  }

  /** Absolute index of the oldest retained frame. */
  get firstIndex(): number {
    return this.start;
  }

  /** Absolute index the NEXT push will occupy (== count of frames ever produced this run). */
  get nextIndex(): number {
    return this.start + this.count;
  }

  /** Is absolute index `i` still in the window? */
  has(i: number): boolean {
    return i >= this.start && i < this.start + this.count;
  }

  /** The frame at absolute index `i`, or undefined if evicted / not yet produced. */
  get(i: number): Frame | undefined {
    return this.has(i) ? this.buf[i % this.capacity] : undefined;
  }

  /** Reset to empty at absolute index 0 (for a replay from the start). */
  clear(): void {
    this.start = 0;
    this.count = 0;
  }
}

/**
 * Build a {@link TraceStream} over a trace generator `factory`. The factory is called ONCE up front
 * (creating a suspended generator — no frames produced yet) and AGAIN on each deterministic replay, so
 * it must yield the identical frame sequence every call (a pure function of its captured input).
 *
 * @param factory  Produces a fresh `Generator<Frame>` from the algorithm's fixed input.
 * @param opts     {@link TraceStreamOptions} — the scrub-back window size.
 */
export function makeTraceStream(
  factory: () => Generator<Frame>,
  opts: TraceStreamOptions = {},
): TraceStream {
  const capacity = Math.max(1, Math.floor(opts.bufferSize ?? DEFAULT_BUFFER_SIZE));
  const ring = new Ring(capacity);
  let gen = factory(); // suspended — no body runs until the first pull
  let cursor = -1; // current absolute index; -1 before the first frame
  let exhausted = false; // the live generator has reported done

  /** Pull ONE frame from the live generator into the ring, or null when exhausted. */
  function pull(): Frame | null {
    if (exhausted) return null;
    const r = gen.next();
    if (r.done) {
      exhausted = true;
      return null;
    }
    ring.push(r.value);
    return r.value;
  }

  /** Re-run the factory from scratch and pull forward to absolute index `i` (deterministic replay),
   *  clamping the cursor to the last frame if the trace is shorter than `i`. */
  function replayTo(i: number): Frame | null {
    gen = factory();
    ring.clear();
    exhausted = false;
    for (let k = 0; k <= i; k++) {
      if (pull() == null) break; // trace shorter than i → stop at the end
    }
    cursor = ring.nextIndex - 1; // == min(i, produced-1)
    return current();
  }

  function current(): Frame | null {
    return cursor < 0 ? null : ring.get(cursor) ?? null;
  }

  function next(): Frame | null {
    const target = cursor + 1;
    // Already buffered (we had scrubbed back) → no pull.
    if (target < ring.nextIndex) {
      cursor = target;
      return current();
    }
    // At the frontier → pull exactly one fresh frame.
    const frame = pull();
    if (frame == null) return null; // end of trace — cursor stays put
    cursor = target;
    return frame;
  }

  function seek(i: number): Frame | null {
    if (i < 0) {
      cursor = -1;
      return null;
    }
    if (ring.has(i)) {
      cursor = i;
      return current();
    }
    // Older than the retained window → deterministic replay from the start.
    if (i < ring.firstIndex) return replayTo(i);
    // Past the frontier → pull forward, clamping at the end of the trace.
    while (ring.nextIndex <= i && !exhausted) pull();
    cursor = Math.min(i, ring.nextIndex - 1);
    return current();
  }

  return {
    current,
    next,
    seek,
    index: () => cursor,
    atEnd: () => exhausted && cursor === ring.nextIndex - 1,
  };
}

// The trace-frame contract (#3176, epic #3171) — the shared, typed skeleton every algorithm-visualization
// frame follows, and the vocabulary the librarian AI writes traces against + every per-structure renderer
// binds to. PURE + React-free (the tests, the streaming engine, and the renderers all share ONE model).
//
// A trace is a stream of FRAMES. Each frame names its `structure`, carries that structure's DATA (or
// topology), and OPTIONALLY carries transient `ops` (the per-frame VERBS the animation binds to),
// `cursors` (named pointers into the structure), and `marks` (durable per-element states). The renderer
// stamps each op/mark onto the element's `data-op` / `data-mark` (see `lib/binding.ts`), and a
// state-triggered kit animation (#3058) fires off that state — so changing the `swap` animation once
// updates every sort visualization, with no hand-coded CSS in any renderer.
//
// A multi-structure algorithm (Dijkstra → graph + heap + distances) yields a `{ panels }` frame whose
// values are per-structure frames animating in sync. `normalizeFrame` collapses the bare-vs-panels split
// so the player always deals with a named map of panels.

/** The data structures a renderer exists for (#3171). Same visual vocabulary as the components'
 *  `DataShape` — one language across both pillars. `tree` also renders heaps; `stack` also renders
 *  queues/deques (via its `mode`); `matrix` also renders grids/DP tables. */
/** WHERE in the trace-program's source the op that produced a frame came from (#3250) — a half-open
 *  character range into the program source, plus the 1-based line of `start` for a readable readout.
 *
 *  PROVENANCE, not a guess: the range is captured at COMPILE time by AST-instrumenting each tracer call
 *  (`viz/examples/vizInstrument.ts`), so a repeated op (quicksort's two `swap` branches) points at the
 *  call that actually ran — something a `.swap(` text search cannot disambiguate. Offsets index the
 *  `source` string the run reports (`VizRun.source`), which is the exact string that was parsed — so the
 *  code column and the highlight can never drift apart. */
export interface SourceRange {
  /** Inclusive start offset into the trace-program source. */
  start: number;
  /** Exclusive end offset. */
  end: number;
  /** 1-based line number of {@link start} — for the "line N" readout beside the animation. */
  line: number;
}

/** The metadata every frame may carry, independent of its structure (#3250). Kept as its own interface so
 *  each frame type opts in by `extends`-ing it — which preserves the discriminated union's narrowing on
 *  `structure` (an intersection over the union would not). */
export interface FrameMeta {
  /** The source range of the op that produced this frame, when the program was compiled with source
   *  instrumentation (stored `vizCode` only — an in-app TS program has no runtime source to point at). */
  loc?: SourceRange;
}

export type StructureName =
  | "array"
  | "matrix"
  | "graph"
  | "linked-list"
  | "tree"
  | "table"
  | "stack"
  | "scalar";

/* ─────────────────────────────── array (also sorts / scans) ─────────────────────────────── */

/** An array VERB (#3171) — the transient per-frame operation the `swap`/`compare`/`set` animations bind
 *  to. `mark` is durable-ish (a cell reaching a terminal state: `sorted`/`pivot`/`min`/`found`). `at` is
 *  the cell index, or the index PAIR a compare/swap spans.
 *
 *  `probe` (#3220) is the SEARCH verb: one cell examined against an EXTERNAL target. It is deliberately
 *  distinct from `compare`, which spans an index PAIR — a search has no second cell to compare with, so a
 *  self-pair `compare` would misrepresent it (and animate two cells for a one-cell read). Its terminal
 *  twin is the `found` mark: the cell the search landed on, emitted LAST (like `sorted`), so it survives
 *  as the trace's resting state rather than being superseded by a later verb. (Not to be confused with
 *  the unrelated {@link TableOp} `probe`, which addresses a hash BUCKET.) */
export type ArrayOp =
  | { op: "compare"; at: [number, number] }
  | { op: "probe"; at: number }
  | { op: "swap"; at: [number, number] }
  | { op: "set"; at: number }
  | { op: "mark"; at: number; as: "sorted" | "pivot" | "min" | "found" };

/** One frame of an array's evolution. `data` is the current cell values; `cursors` are named pointers
 *  (`{ i: 3, j: 5 }`) a renderer draws as carets under cells. */
export interface ArrayFrame extends FrameMeta {
  structure: "array";
  data: (number | string)[];
  ops?: ArrayOp[];
  cursors?: Record<string, number>;
}

/* ─────────────────────────────── matrix (also grids / DP tables) ─────────────────────────────── */

/** A matrix VERB (#3171) — a cell `read`/`write` (bound by the `cell-write` animation), or a rectangular
 *  `region` highlight (a DP window / submatrix), optionally labelled via `as`. `at` / `rows` / `cols` are
 *  `[row, col]` / inclusive `[start, end]` index pairs. */
export type MatrixOp =
  | { op: "read"; at: [number, number] }
  | { op: "write"; at: [number, number] }
  | { op: "region"; rows: [number, number]; cols: [number, number]; as?: string };

/** One frame of a 2-D grid's evolution. `heat` opts the renderer into a value→color heat map (magnitude
 *  visualization) rather than printing raw values — for changes-over-time / DP-fill traces. */
export interface MatrixFrame extends FrameMeta {
  structure: "matrix";
  data: (number | string)[][];
  ops?: MatrixOp[];
  cursors?: Record<string, [number, number]>;
  heat?: boolean;
}

/* ─────────────────────────────── graph (also networks) ─────────────────────────────── */

/** A graph VERB (#3171) — `visit`/`frontier` mark a node's search state (bound by the `visit` animation),
 *  `relax` fires on an edge (Dijkstra/Bellman-Ford, the `relax` animation), `path` lights a final route
 *  (the `path` animation). Nodes are addressed by `id`; edges by their `[from, to]` id pair. */
export type GraphOp =
  | { op: "visit"; node: string }
  | { op: "frontier"; node: string }
  | { op: "relax"; edge: [string, string] }
  | { op: "path"; nodes: string[] };

/**
 * One frame of a graph's evolution. `nodes`/`edges` are the topology; `cursors` are named node pointers
 * (`{ current: "b" }`).
 *
 * Durable per-node state is split across TWO fields (#3378), because "where the algorithm began" and "has
 * the walker been here" are DIFFERENT facts about a node — a node is routinely both:
 *  - `roles` — the anchors the algorithm assigns up front (`start` / `goal`). They outlive the traversal:
 *    every BFS/Dijkstra run eventually walks over its own start node, and the origin must still render as
 *    the origin afterwards.
 *  - `marks` — the WALKER's search state (`frontier` → `current` → `visited`), a lifecycle whose stages
 *    legitimately supersede one another.
 *
 * Keeping them in one field made a traversal state clobber the anchor, so a rendered BFS/Dijkstra could not
 * show its own origin or (once reached) its goal.
 */
export interface GraphFrame extends FrameMeta {
  structure: "graph";
  nodes: { id: string; label?: string; value?: number | string; x?: number; y?: number }[];
  edges: { from: string; to: string; weight?: number }[];
  ops?: GraphOp[];
  /** The WALKER's per-node search state — transient-lifecycle, each stage superseding the last. */
  marks?: Record<string, "visited" | "frontier" | "current">;
  /** The algorithm's durable per-node anchors — never overwritten by a traversal state (#3378). */
  roles?: Record<string, "start" | "goal">;
  cursors?: Record<string, string>;
}

/* ─────────────────────────────── linked-list ─────────────────────────────── */

/** A linked-list VERB (#3171) — `traverse` walks a node (the `visit` animation), `compare` spans a node
 *  pair, `insert`/`remove` splice at an index, `relink` re-points a `from → to` pointer (the pointer
 *  animation). Nodes are addressed by their positional index in `data`. */
export type ListOp =
  | { op: "traverse"; at: number }
  | { op: "compare"; at: [number, number] }
  | { op: "insert"; at: number }
  | { op: "remove"; at: number }
  | { op: "relink"; from: number; to: number };

/** One frame of a linked list's evolution. `data` is the node values in list order; `doubly` opts into
 *  rendering back-pointers. `cursors` are named pointers (`{ head: 0, cur: 2 }`). */
export interface ListFrame extends FrameMeta {
  structure: "linked-list";
  data: (number | string)[];
  ops?: ListOp[];
  cursors?: Record<string, number>;
  doubly?: boolean;
}

/* ─────────────────────────────── tree (also heaps / BSTs) ─────────────────────────────── */

/** A tree VERB (#3171) — `visit` (the `visit` animation), `compare` a node pair, `insert`/`remove` a
 *  node, `rotate` a subtree about a pivot (AVL/red-black, the `rotate` animation), `swap` a node pair
 *  (heap sift, the `swap` animation). Nodes are addressed by `id`. */
export type TreeOp =
  | { op: "visit"; node: string }
  | { op: "compare"; at: [string, string] }
  | { op: "insert"; node: string; parent: string }
  | { op: "remove"; node: string }
  | { op: "rotate"; pivot: string; dir: "left" | "right" }
  | { op: "swap"; at: [string, string] };

/** One frame of a tree/heap's evolution. `nodes` carry each node's `value` + its `parent` id (the root's
 *  is absent) — the renderer derives the layout. `marks` are durable per-node states (current/path/target). */
export interface TreeFrame extends FrameMeta {
  structure: "tree";
  nodes: { id: string; value: number | string; parent?: string }[];
  ops?: TreeOp[];
  marks?: Record<string, "current" | "path" | "target">;
  cursors?: Record<string, string>;
}

/* ─────────────────────────────── table (hash maps / sets) ─────────────────────────────── */

/** A table VERB (#3171) — `read`/`write` a key, `probe` a bucket (open addressing, the probe animation),
 *  `delete` a key. Keyed by the entry `key`; `probe` by bucket index. */
export type TableOp =
  | { op: "read"; key: string }
  | { op: "write"; key: string }
  | { op: "probe"; bucket: number }
  | { op: "delete"; key: string };

/** One frame of a hash table / map. `rows` are the entries (each optionally assigned to a `bucket`);
 *  `buckets` is the table's bucket count (so the renderer can draw empty slots). `cursors` are named
 *  key pointers. */
export interface TableFrame extends FrameMeta {
  structure: "table";
  rows: { key: string; value: number | string; bucket?: number }[];
  buckets?: number;
  ops?: TableOp[];
  cursors?: Record<string, string>;
}

/* ─────────────────────────────── stack (also queue / deque) ─────────────────────────────── */

/** A stack VERB (#3171) — `push`/`pop` at the active end (the push/pop animations), `peek` at an index.
 *  `push`/`pop` are position-less (the renderer knows the active end from `mode`); `peek` carries `at`. */
export type StackOp =
  | { op: "push" }
  | { op: "pop" }
  | { op: "peek"; at: number };

/** One frame of a LIFO/FIFO. `data` is bottom→top order; `mode` picks the discipline (default `stack`) so
 *  ONE renderer covers stacks, queues, and deques. `cursors` are named index pointers. */
export interface StackFrame extends FrameMeta {
  structure: "stack";
  data: (number | string)[];
  mode?: "stack" | "queue" | "deque";
  ops?: StackOp[];
  cursors?: Record<string, number>;
}

/* ─────────────────────────────── scalar (counters / accumulators) ─────────────────────────────── */

/** A scalar VERB (#3171) — `set` a value, `add` a delta (accumulators), `compare` against another value.
 *  Keyed (in the frame's `ops` record) by the variable NAME it applies to. */
export type ScalarOp =
  | { op: "set" }
  | { op: "add"; delta: number }
  | { op: "compare"; other: number };

/** One frame of the named scalar variables (counters, sums, min/max, flags). `values` is the current
 *  variable map; `ops` is a per-VARIABLE verb map (keyed by name, unlike the other structures' op arrays);
 *  `timeline` opts into a sparkline of each variable's history rather than a single readout. */
export interface ScalarFrame extends FrameMeta {
  structure: "scalar";
  values: Record<string, number | string>;
  ops?: Record<string, ScalarOp>;
  timeline?: boolean;
}

/* ─────────────────────────────── the union + the multi-structure frame ─────────────────────────────── */

/** The discriminated union of every single-structure frame — discriminated on `structure`. */
export type StructureFrame =
  | ArrayFrame
  | MatrixFrame
  | GraphFrame
  | ListFrame
  | TreeFrame
  | TableFrame
  | StackFrame
  | ScalarFrame;

/** A multi-structure frame (#3171) — a NAMED map of per-structure panels animating in sync (Dijkstra →
 *  `{ graph, heap, dist }`). The key is the panel's label; each value is a single-structure frame. */
export interface PanelsFrame extends FrameMeta {
  panels: Record<string, StructureFrame>;
}

/** A trace frame: EITHER a bare single-structure frame OR a multi-panel frame. */
export type Frame = StructureFrame | PanelsFrame;

/** The per-structure frame type for a given structure name — `FrameOf<"array">` is {@link ArrayFrame}.
 *  A renderer for structure `S` is a component over `FrameOf<S>`; the player narrows a panel to its
 *  registered renderer's frame type. */
export type FrameOf<S extends StructureName> = Extract<StructureFrame, { structure: S }>;

/** Type guard: is this frame a multi-panel frame (vs a bare single-structure frame)? */
export function isPanelsFrame(frame: Frame): frame is PanelsFrame {
  return "panels" in frame;
}

/**
 * Collapse the bare-vs-panels split so the player always deals with a NAMED map of panels: a bare
 * single-structure frame becomes `{ main: frame }`; a `{ panels }` frame yields its own map. Pure.
 */
export function normalizeFrame(frame: Frame): Record<string, StructureFrame> {
  return isPanelsFrame(frame) ? frame.panels : { main: frame };
}

// The instrumented-execution tracer (#3216, epic #3215) — the mechanism that makes the ACTUAL algorithm
// code drive the animation. Instead of hand-authoring a trace per algorithm, the algorithm runs against a
// TracedArray whose operations are observable: every `compare`/`swap`/`set`/`mark` records a
// StructureFrame, so the animation is DERIVED from the algorithm's real execution. Each algorithm looks
// different because it IS different (bubble's adjacent swaps vs merge's writes vs quick's partitions).
//
// The algorithm is its real logic written against this structure (see viz/examples/sorts.ts) — no `yield`,
// no hand-drawn frames. `runAlgorithm` seeds the structure, runs the algorithm, and exposes the recorded
// trace as a fresh generator per call (replay-safe for the streaming player). Reads via `get` are SILENT
// (the algorithm's internal logic); only meaningful operations record a frame.
//
// This is the array tracer; TracedMatrix / TracedGraph / TracedTree follow the same shape as their
// renderers land (#3179–#3185), so instrumented execution generalizes to every data type.
import type { ArrayFrame, ArrayOp, FrameMeta, Frame, GraphFrame, GraphOp, MatrixFrame, MatrixOp, PanelsFrame, ScalarFrame, ScalarOp, SourceRange, StackFrame, StackOp, StructureFrame, TreeFrame, TreeOp } from "@/features/algorithms/lib/trace";

/* ─────────────────────────────── source provenance (#3250) ─────────────────────────────── */

// WHERE the currently-executing tracer call came from in the trace-program's source. An AMBIENT STACK
// rather than a parameter on every verb, because the provenance must reach `emit` without changing a
// single tracer signature — the algorithm still calls `a.swap(i, j)`, and the instrumented program
// (`viz/examples/vizInstrument.ts`) wraps that call in `withSourceLoc` so the frame it emits knows its
// origin. It is a STACK, not a single slot, so a NESTED traced call (`a.set(i, a.get(j))`) restores the
// outer range when the inner one returns — a single slot would leave the outer frame wearing the inner
// call's location.
//
// Module-level state is safe here: the tracer is synchronous and single-threaded (each `run*` call runs
// the algorithm to completion before returning), and stored programs run in their own Worker. Nothing
// interleaves, and `withSourceLoc` pops in a `finally` so a throwing program cannot leak a stale entry.
const LOC_STACK: SourceRange[] = [];

/**
 * Run `fn` with `loc` as the ambient source location, so every frame it emits is stamped with it (#3250).
 *
 * @param loc the source range of the call being executed; `undefined` runs `fn` unstamped (an
 *   uninstrumented program), which keeps the instrumented and plain paths on one code path.
 * @param fn the traced call to execute.
 * @returns whatever `fn` returns (the tracer verbs' return values pass straight through).
 */
export function withSourceLoc<T>(loc: SourceRange | undefined, fn: () => T): T {
  if (!loc) return fn();
  LOC_STACK.push(loc);
  try {
    return fn();
  } finally {
    LOC_STACK.pop(); // popped even when the program throws — no stale provenance leaks into later runs
  }
}

/** The innermost ambient source location, or `undefined` outside any instrumented call. */
export function currentSourceLoc(): SourceRange | undefined {
  return LOC_STACK[LOC_STACK.length - 1];
}

/** Stamp the ambient source location onto a freshly built frame and return it. No-op (no `loc` key at
 *  all) when the program is uninstrumented, so plain traces stay byte-identical to before #3250. */
function stampLoc<F extends FrameMeta>(frame: F): F {
  const loc = currentSourceLoc();
  if (loc) frame.loc = loc;
  return frame;
}

/** A durable per-cell mark an algorithm can set (matches the ArrayOp `mark` vocabulary). */
export type ArrayMark = "sorted" | "pivot" | "min" | "found";

/**
 * An instrumented array — the algorithm operates on it, and every observable operation appends an
 * `ArrayFrame` to the trace. `get` is a silent read (internal logic); `compare`/`swap`/`set`/`mark` are
 * the visible verbs the `<ArrayView>` renderer animates. `cursor` moves a named pointer (drawn on the
 * next frame). Values are numbers (the sort family); the frame carries a fresh snapshot each op.
 */
export class TracedArray {
  private readonly a: number[];
  private readonly log: ArrayFrame[] = [];
  private readonly cur: Record<string, number> = {};

  constructor(input: readonly number[]) {
    this.a = [...input];
    this.emit(); // the initial frame — the input at rest
  }

  /** The length — read freely (no frame). */
  get length(): number {
    return this.a.length;
  }

  /** A silent read of index `i` (the algorithm's internal logic — records no frame). */
  get(i: number): number {
    return this.a[i];
  }

  /** Compare indices `i` and `j` — records a `compare` frame; returns sign(a[i] - a[j]) (`-1|0|1`). */
  compare(i: number, j: number): number {
    this.emit([{ op: "compare", at: [i, j] }]);
    return Math.sign(this.a[i] - this.a[j]);
  }

  /** Swap indices `i` and `j` in place — records a `swap` frame. */
  swap(i: number, j: number): void {
    const t = this.a[i];
    this.a[i] = this.a[j];
    this.a[j] = t;
    this.emit([{ op: "swap", at: [i, j] }]);
  }

  /** Examine ONE cell against an external target (the SEARCH verb, #3220) — records a `probe` frame and
   *  returns the value, so the caller does the target test itself. Distinct from {@link compare}, which
   *  spans an index pair: a search compares against a value that is not in the array. */
  probe(i: number): number {
    this.emit([{ op: "probe", at: i }]);
    return this.a[i];
  }

  /** Write `v` at index `i` — records a `set` frame. */
  set(i: number, v: number): void {
    this.a[i] = v;
    this.emit([{ op: "set", at: i }]);
  }

  /** Move a named cursor (an `i`/`j` pointer the renderer draws); `null` clears it. Rides the next frame. */
  cursor(name: string, i: number | null): void {
    if (i == null) delete this.cur[name];
    else this.cur[name] = i;
  }

  /** Mark one cell with a durable state (`pivot`/`min`/`sorted`/`found`) — records a `mark` frame. */
  mark(i: number, as: ArrayMark): void {
    this.emit([{ op: "mark", at: i, as }]);
  }

  /**
   * Terminal frame — the cell a SEARCH landed on (#3220). The search-family twin of {@link markSorted}:
   * a program calls it once, as its LAST act, so the mark is the trace's resting state and no later verb
   * can supersede it. Deliberately NOT a separate durable axis: unlike a graph's `start`/`goal` roles
   * (which the walker keeps moving over, #3378), nothing runs after a `found` — so there is no state to
   * clobber it, and the array frame keeps its single, simple op vocabulary.
   */
  found(i: number): void {
    this.mark(i, "found");
  }

  /** Terminal frame — mark every cell `sorted` (the settled resting state a sort ends on). */
  markSorted(): void {
    this.emit(this.a.map((_, k) => ({ op: "mark", at: k, as: "sorted" as const })));
  }

  /** The recorded trace (a fresh snapshot array). */
  trace(): ArrayFrame[] {
    return [...this.log];
  }

  /** Route emitted frames to a {@link TracedScene} (#3259) so this structure can fold into a synchronized
   *  panel. Set once, right after construction; unset ⇒ standalone (single-structure) behavior. */
  private sink?: (f: StructureFrame) => void;
  setSink(fn: (f: StructureFrame) => void): void { this.sink = fn; }

  private emit(ops?: ArrayOp[]): void {
    const frame: ArrayFrame = { structure: "array", data: [...this.a] };
    if (ops && ops.length) frame.ops = ops;
    if (Object.keys(this.cur).length) frame.cursors = { ...this.cur };
    this.log.push(stampLoc(frame));
    this.sink?.(frame);
  }
}

/**
 * Run an algorithm — a plain function over a {@link TracedArray} — on `input`, returning a factory that
 * yields its recorded trace as a FRESH generator each call. The factory is a stable identity (bind it once
 * at the call site) so the streaming player can replay it deterministically; each call re-runs the
 * algorithm from scratch (pure over `input`, which is never mutated).
 */
export function runAlgorithm(algo: (a: TracedArray) => void, input: readonly number[]): () => Generator<Frame> {
  return function* () {
    const a = new TracedArray(input);
    algo(a);
    yield* a.trace();
  };
}

// ── the matrix tracer (#3221) — the 2-D twin of TracedArray ──

/** A cell write for {@link TracedMatrix.writeMany} — a value landing at (row, col). */
export interface CellWrite {
  r: number;
  c: number;
  v: number;
}

/**
 * An instrumented 2-D grid — a matrix algorithm operates on it, and every observable op appends a
 * `MatrixFrame`. `get` is a silent read (internal logic); `read` highlights a cell, `writeMany`/`set`/`swap`
 * are the write verbs the `<MatrixView>` renderer animates, and `region` highlights a rectangular block.
 * A `swap`/rotation writes several cells in ONE frame so they move together.
 */
export class TracedMatrix {
  private readonly m: number[][];
  private readonly log: MatrixFrame[] = [];
  private readonly cur: Record<string, [number, number]> = {};

  constructor(input: readonly (readonly number[])[]) {
    this.m = input.map((row) => [...row]);
    this.emit(); // the grid at rest
  }

  get rows(): number {
    return this.m.length;
  }
  get cols(): number {
    return this.m[0]?.length ?? 0;
  }

  /** A silent read (no frame) — the algorithm's internal logic. */
  get(r: number, c: number): number {
    return this.m[r][c];
  }

  /** Highlight a cell being examined — records a `read` frame. */
  read(r: number, c: number): number {
    this.emit([{ op: "read", at: [r, c] as [number, number] }]);
    return this.m[r][c];
  }

  /** Write several cells in ONE frame (a swap / rotation moves together) — records a `write` op per cell. */
  writeMany(cells: readonly CellWrite[]): void {
    for (const { r, c, v } of cells) this.m[r][c] = v;
    this.emit(cells.map(({ r, c }) => ({ op: "write" as const, at: [r, c] as [number, number] })));
  }

  /** Write one cell — records a `write` frame. */
  set(r: number, c: number, v: number): void {
    this.writeMany([{ r, c, v }]);
  }

  /** Exchange two cells in one frame — the workhorse of transpose / reflect. */
  swap(a: readonly [number, number], b: readonly [number, number]): void {
    const va = this.m[a[0]][a[1]];
    const vb = this.m[b[0]][b[1]];
    this.writeMany([{ r: a[0], c: a[1], v: vb }, { r: b[0], c: b[1], v: va }]);
  }

  /** Highlight a rectangular block (a submatrix / layer), optionally labelled — records a `region` frame. */
  region(rows: [number, number], cols: [number, number], as?: string): void {
    const op: MatrixOp = as ? { op: "region", rows, cols, as } : { op: "region", rows, cols };
    this.emit([op]);
  }

  /** Move a named cursor (drawn on the next frame); `null` clears it. */
  cursor(name: string, at: readonly [number, number] | null): void {
    if (at == null) delete this.cur[name];
    else this.cur[name] = [at[0], at[1]];
  }

  /** The recorded trace (a fresh snapshot). */
  trace(): MatrixFrame[] {
    return [...this.log];
  }

  /** The current grid (fresh copy). */
  values(): number[][] {
    return this.m.map((row) => [...row]);
  }

  /** Route emitted frames to a {@link TracedScene} (#3259) — see {@link TracedArray.setSink}. */
  private sink?: (f: StructureFrame) => void;
  setSink(fn: (f: StructureFrame) => void): void { this.sink = fn; }

  private emit(ops?: MatrixOp[]): void {
    const frame: MatrixFrame = { structure: "matrix", data: this.m.map((row) => [...row]) };
    if (ops && ops.length) frame.ops = ops;
    if (Object.keys(this.cur).length) frame.cursors = { ...this.cur };
    this.log.push(stampLoc(frame));
    this.sink?.(frame);
  }
}

/**
 * Run a matrix algorithm — a plain function over a {@link TracedMatrix} — on `input`, returning a factory
 * that yields its recorded trace as a fresh generator each call (replay-safe; `input` is never mutated).
 */
export function runMatrixAlgorithm(
  algo: (m: TracedMatrix) => void,
  input: readonly (readonly number[])[],
): () => Generator<Frame> {
  return function* () {
    const m = new TracedMatrix(input);
    algo(m);
    yield* m.trace();
  };
}

// ── the graph tracer (#3224) — nodes + edges; traversal / shortest-path verbs ──

/** The topology an algorithm runs against — nodes (with optional coordinates) + (weighted) edges. */
export interface GraphInput {
  nodes: { id: string; label?: string; x?: number; y?: number }[];
  edges: { from: string; to: string; weight?: number }[];
}
/** The WALKER's per-node search state (matches the GraphFrame `marks` vocabulary) — a lifecycle whose
 *  stages legitimately supersede one another: `frontier` → `current` → `visited`. */
export type GraphMark = "visited" | "frontier" | "current";
/** A durable per-node ROLE the algorithm assigns up front (matches the GraphFrame `roles` vocabulary) —
 *  where the search began and where it is headed. Held in its OWN field (#3378) so the walker's state can
 *  never clobber it: every BFS/Dijkstra run visits its own start node, and reaching the goal is exactly
 *  when the goal marking matters most. */
export type GraphRole = "start" | "goal";
/** A neighbour of a node — the other endpoint + the edge weight + the directed edge for `relax`. */
export interface Neighbour {
  to: string;
  weight: number;
  edge: [string, string];
}

/**
 * An instrumented graph — a traversal / shortest-path algorithm operates on it, and every observable op
 * appends a `GraphFrame`. `neighbours` is a silent read (the algorithm's traversal); `frontier` / `visit` /
 * `current` advance the WALKER's durable node `marks` the renderer paints and `relax` fires on an edge —
 * each records a frame. Marks persist across frames; ops are the transient verb. Edges are treated as
 * UNDIRECTED for traversal.
 *
 * `mark()` is a different axis: it assigns a durable ROLE (`start`/`goal`) into the separate `roles` field,
 * so a node can be BOTH the origin and visited (#3378) — which every BFS/Dijkstra start node becomes.
 */
export class TracedGraph {
  private readonly nodes: { id: string; label?: string; x?: number; y?: number }[];
  private readonly edges: { from: string; to: string; weight?: number }[];
  private readonly adj = new Map<string, Neighbour[]>();
  private readonly marks: Record<string, GraphMark> = {};
  private readonly roles: Record<string, GraphRole> = {};
  private readonly cur: Record<string, string> = {};
  private readonly log: GraphFrame[] = [];

  constructor(input: GraphInput) {
    this.nodes = input.nodes.map((n) => ({ ...n }));
    this.edges = input.edges.map((e) => ({ ...e }));
    for (const n of this.nodes) this.adj.set(n.id, []);
    for (const e of this.edges) {
      const w = e.weight ?? 1;
      this.adj.get(e.from)?.push({ to: e.to, weight: w, edge: [e.from, e.to] });
      this.adj.get(e.to)?.push({ to: e.from, weight: w, edge: [e.from, e.to] }); // undirected
    }
    this.emit();
  }

  /** The node ids in declaration order (the algorithm picks a start). */
  ids(): string[] {
    return this.nodes.map((n) => n.id);
  }
  /** A node's coordinates for a spatial heuristic (A*), or `null` when it has none. Silent. */
  coord(id: string): { x: number; y: number } | null {
    const n = this.nodes.find((m) => m.id === id);
    return n && n.x !== undefined && n.y !== undefined ? { x: n.x, y: n.y } : null;
  }
  /** A silent read of a node's neighbours (traversal logic — no frame). UNDIRECTED (both endpoints). */
  neighbours(id: string): Neighbour[] {
    return this.adj.get(id) ?? [];
  }
  /** A silent read of a node's OUTGOING neighbours only (directed, `from → to`) — for topological sort. */
  outNeighbours(id: string): Neighbour[] {
    return this.edges
      .filter((e) => e.from === id)
      .map((e) => ({ to: e.to, weight: e.weight ?? 1, edge: [e.from, e.to] as [string, string] }));
  }
  /** The in-degree of every node (count of incoming directed edges) — Kahn's topological sort. Silent. */
  inDegrees(): Map<string, number> {
    const deg = new Map<string, number>(this.nodes.map((n) => [n.id, 0]));
    for (const e of this.edges) deg.set(e.to, (deg.get(e.to) ?? 0) + 1);
    return deg;
  }

  /** Assign a durable start / goal ROLE (no transient op). Lands in `roles`, a field the traversal verbs
   *  never write — so `visit`/`frontier`/`current` cannot erase it (#3378). */
  mark(id: string, as: GraphRole): void {
    this.roles[id] = as;
    this.emit();
  }
  /** Enqueue/discover a node — a `frontier` op + durable `frontier` mark. */
  frontier(id: string): void {
    this.marks[id] = "frontier";
    this.emit([{ op: "frontier", node: id }]);
  }
  /** Point the `current` cursor at the node being processed (a durable `current` mark). */
  current(id: string): void {
    this.cur.current = id;
    this.marks[id] = "current";
    this.emit();
  }
  /** Finish a node — a `visit` op + durable `visited` mark. */
  visit(id: string): void {
    this.marks[id] = "visited";
    this.emit([{ op: "visit", node: id }]);
  }
  /** Relax / traverse an edge — a `relax` op on `[from, to]`. */
  relax(from: string, to: string): void {
    this.emit([{ op: "relax", edge: [from, to] }]);
  }
  /** Light a final route — a `path` op over the node sequence. */
  path(nodes: string[]): void {
    this.emit([{ op: "path", nodes: [...nodes] }]);
  }

  trace(): GraphFrame[] {
    return [...this.log];
  }

  /** Route emitted frames to a {@link TracedScene} (#3259) — see {@link TracedArray.setSink}. */
  private sink?: (f: StructureFrame) => void;
  setSink(fn: (f: StructureFrame) => void): void { this.sink = fn; }

  private emit(ops?: GraphOp[]): void {
    const frame: GraphFrame = {
      structure: "graph",
      nodes: this.nodes.map((n) => ({ ...n })),
      edges: this.edges.map((e) => ({ ...e })),
    };
    if (ops && ops.length) frame.ops = ops;
    if (Object.keys(this.marks).length) frame.marks = { ...this.marks };
    if (Object.keys(this.roles).length) frame.roles = { ...this.roles };
    if (Object.keys(this.cur).length) frame.cursors = { ...this.cur };
    this.log.push(stampLoc(frame));
    this.sink?.(frame);
  }
}

/**
 * Run a graph algorithm — a plain function over a {@link TracedGraph} — on `input`, returning a factory
 * that yields its recorded trace as a fresh generator each call (replay-safe; `input` is never mutated).
 */
export function runGraphAlgorithm(algo: (g: TracedGraph) => void, input: GraphInput): () => Generator<Frame> {
  return function* () {
    const g = new TracedGraph(input);
    algo(g);
    yield* g.trace();
  };
}

// ── the stack tracer (#3266) — LIFO / FIFO / deque ──

/** The stack discipline — a stack (LIFO), a queue (FIFO), or a double-ended deque. Picks which END
 *  `pop` removes from; `push` always appends to the back/top. */
export type StackMode = "stack" | "queue" | "deque";

/**
 * An instrumented stack / queue / deque — an algorithm's frontier structure (BFS's queue, DFS's stack).
 * `push` appends, `pop` removes the active end (the TOP for a stack/deque, the FRONT for a queue), `peek`
 * reads an index. Every op appends a `StackFrame` the `<StackView>` renderer animates. Values may be
 * strings (e.g. `"b:3"`), so a scene can label frontier entries.
 */
export class TracedStack {
  private readonly s: (number | string)[];
  private readonly mode: StackMode;
  private readonly log: StackFrame[] = [];
  private readonly cur: Record<string, number> = {};

  constructor(mode: StackMode = "stack", initial: readonly (number | string)[] = []) {
    this.s = [...initial];
    this.mode = mode;
    this.emit(); // the structure at rest
  }

  /** The number of entries — read freely (no frame). */
  get size(): number {
    return this.s.length;
  }

  /** Append an entry at the back/top — records a `push` frame. */
  push(v: number | string): void {
    this.s.push(v);
    this.emit([{ op: "push" }]);
  }

  /** Remove + return the active end (the TOP for stack/deque, the FRONT for queue) — records a `pop` frame. */
  pop(): number | string | undefined {
    const v = this.mode === "queue" ? this.s.shift() : this.s.pop();
    this.emit([{ op: "pop" }]);
    return v;
  }

  /** Read the entry at `i` without removing it — records a `peek` frame. */
  peek(i: number): number | string {
    this.emit([{ op: "peek", at: i }]);
    return this.s[i];
  }

  /** Move a named index pointer (drawn on the next frame); `null` clears it. */
  cursor(name: string, i: number | null): void {
    if (i == null) delete this.cur[name];
    else this.cur[name] = i;
  }

  /** The recorded trace (a fresh snapshot array). */
  trace(): StackFrame[] {
    return [...this.log];
  }

  /** Route emitted frames to a {@link TracedScene} (#3259) — see {@link TracedArray.setSink}. */
  private sink?: (f: StructureFrame) => void;
  setSink(fn: (f: StructureFrame) => void): void { this.sink = fn; }

  private emit(ops?: StackOp[]): void {
    const frame: StackFrame = { structure: "stack", data: [...this.s] };
    if (this.mode !== "stack") frame.mode = this.mode;
    if (ops && ops.length) frame.ops = ops;
    if (Object.keys(this.cur).length) frame.cursors = { ...this.cur };
    this.log.push(stampLoc(frame));
    this.sink?.(frame);
  }
}

/**
 * Run a stack/queue algorithm — a plain function over a {@link TracedStack} — returning a factory that
 * yields its recorded trace as a fresh generator each call (replay-safe).
 */
export function runStackAlgorithm(algo: (s: TracedStack) => void, mode: StackMode = "stack"): () => Generator<Frame> {
  return function* () {
    const s = new TracedStack(mode);
    algo(s);
    yield* s.trace();
  };
}

// ── the scalar tracer (#3268) — named counters / accumulators / the current pointer ──

/**
 * Instrumented SCALAR state — the named variables (counters, running sums, min/max, the current pointer)
 * that ride alongside a main structure in almost every larger algorithm. `set`/`add`/`compare` are the
 * verbs the `<ScalarView>` renderer animates; each records a `ScalarFrame` whose `ops` map is keyed by the
 * touched variable NAME (unlike the other structures' positional op arrays). `get` is a silent read.
 * Values may be numbers (counters/sums) or strings (a current node id), mixed per variable.
 */
export class TracedScalar {
  private readonly vals: Record<string, number | string> = {};
  private readonly log: ScalarFrame[] = [];

  constructor(initial: Record<string, number | string> = {}) {
    Object.assign(this.vals, initial);
    this.emit(); // the initial frame — the variables at rest
  }

  /** A silent read of variable `name` (the algorithm's internal logic — records no frame). */
  get(name: string): number | string | undefined {
    return this.vals[name];
  }

  /** Set `name` to `v` — records a `set` frame stamped on that variable. */
  set(name: string, v: number | string): void {
    this.vals[name] = v;
    this.emit({ [name]: { op: "set" } });
  }

  /** Add `delta` to a numeric accumulator `name` (a non-numeric / absent value starts at 0) — records an
   *  `add` frame. */
  add(name: string, delta: number): void {
    const cur = typeof this.vals[name] === "number" ? (this.vals[name] as number) : 0;
    this.vals[name] = cur + delta;
    this.emit({ [name]: { op: "add", delta } });
  }

  /** Compare `name` against `other` — records a `compare` frame; returns sign(value - other) (`-1|0|1`),
   *  treating a non-numeric / absent value as 0. */
  compare(name: string, other: number): number {
    this.emit({ [name]: { op: "compare", other } });
    const cur = typeof this.vals[name] === "number" ? (this.vals[name] as number) : 0;
    return Math.sign(cur - other);
  }

  /** The recorded trace (a fresh snapshot array). */
  trace(): ScalarFrame[] {
    return [...this.log];
  }

  /** Route emitted frames to a {@link TracedScene} (#3259) — see {@link TracedArray.setSink}. */
  private sink?: (f: StructureFrame) => void;
  setSink(fn: (f: StructureFrame) => void): void { this.sink = fn; }

  private emit(ops?: Record<string, ScalarOp>): void {
    const frame: ScalarFrame = { structure: "scalar", values: { ...this.vals } };
    if (ops && Object.keys(ops).length) frame.ops = ops;
    this.log.push(stampLoc(frame));
    this.sink?.(frame);
  }
}

/**
 * Run a scalar-state algorithm — a plain function over a {@link TracedScalar} — returning a factory that
 * yields its recorded trace as a fresh generator each call (replay-safe).
 */
export function runScalarAlgorithm(
  algo: (s: TracedScalar) => void,
  initial: Record<string, number | string> = {},
): () => Generator<Frame> {
  return function* () {
    const s = new TracedScalar(initial);
    algo(s);
    yield* s.trace();
  };
}

// ── the tree tracer (#3270) — trees / heaps / BSTs (parent-pointer nodes) ──

/** A durable per-node tree state (matches the TreeFrame `marks` vocabulary). */
export type TreeMark = "current" | "path" | "target";
/** One tree node — a stable id, its value, and its parent id (absent for the root). */
export interface TreeNode {
  id: string;
  value: number | string;
  parent?: string;
}

/**
 * An instrumented tree (which also models a HEAP or BST) — a tree/heap algorithm operates on it and every
 * observable op appends a `TreeFrame`. Nodes are addressed by a STABLE id; the parent pointers give the
 * `<TreeView>` renderer the shape (it derives the layout). `insert` grows a node, `remove` drops one,
 * `swap` exchanges two nodes' VALUES (the heap sift — positions stay fixed, values move), `visit`/`mark`
 * set a durable state, `compare` fires a transient read. `value` is a silent read.
 */
export class TracedTree {
  private readonly nodes: TreeNode[] = [];
  private readonly byId = new Map<string, TreeNode>();
  private readonly marks: Record<string, TreeMark> = {};
  private readonly log: TreeFrame[] = [];

  constructor(initial: readonly TreeNode[] = []) {
    for (const n of initial) this.addNode(n);
    this.emit(); // the tree at rest
  }

  private addNode(n: TreeNode): void {
    const copy: TreeNode = { id: n.id, value: n.value, ...(n.parent !== undefined ? { parent: n.parent } : {}) };
    this.nodes.push(copy);
    this.byId.set(n.id, copy);
  }

  /** The node count — read freely (no frame). */
  get size(): number {
    return this.nodes.length;
  }

  /** A silent read of a node's value (the algorithm's internal logic — records no frame). */
  value(id: string): number | string | undefined {
    return this.byId.get(id)?.value;
  }

  /** Add a node under `parent` (omit `parent` for the root) — records an `insert` frame stamped on it. */
  insert(id: string, value: number | string, parent?: string): void {
    this.addNode({ id, value, parent });
    // TreeOp.insert requires a `parent`; a root names itself (the frame node's own `parent` stays absent).
    this.emit([{ op: "insert", node: id, parent: parent ?? id }]);
  }

  /** Remove a node (and any durable mark) — records a `remove` frame. */
  remove(id: string): void {
    const i = this.nodes.findIndex((n) => n.id === id);
    if (i >= 0) {
      this.nodes.splice(i, 1);
      this.byId.delete(id);
    }
    delete this.marks[id];
    this.emit([{ op: "remove", node: id }]);
  }

  /** Exchange the VALUES of two nodes (the heap sift — the tree shape is unchanged) — records a `swap`. */
  swap(a: string, b: string): void {
    const na = this.byId.get(a);
    const nb = this.byId.get(b);
    if (na && nb) {
      const t = na.value;
      na.value = nb.value;
      nb.value = t;
    }
    this.emit([{ op: "swap", at: [a, b] }]);
  }

  /** Compare two nodes' values — records a `compare` frame; returns sign(a - b) for numeric values. */
  compare(a: string, b: string): number {
    this.emit([{ op: "compare", at: [a, b] }]);
    const va = this.byId.get(a)?.value;
    const vb = this.byId.get(b)?.value;
    return typeof va === "number" && typeof vb === "number" ? Math.sign(va - vb) : 0;
  }

  /** Finish / touch a node — a `visit` op + durable `current` mark. */
  visit(id: string): void {
    this.marks[id] = "current";
    this.emit([{ op: "visit", node: id }]);
  }

  /** Set a durable node mark (`current`/`path`/`target`) with no transient op. */
  mark(id: string, as: TreeMark): void {
    this.marks[id] = as;
    this.emit();
  }

  /** The recorded trace (a fresh snapshot array). */
  trace(): TreeFrame[] {
    return [...this.log];
  }

  /** Route emitted frames to a {@link TracedScene} (#3259) — see {@link TracedArray.setSink}. */
  private sink?: (f: StructureFrame) => void;
  setSink(fn: (f: StructureFrame) => void): void { this.sink = fn; }

  private emit(ops?: TreeOp[]): void {
    const frame: TreeFrame = {
      structure: "tree",
      nodes: this.nodes.map((n) => ({ ...n })),
    };
    if (ops && ops.length) frame.ops = ops;
    if (Object.keys(this.marks).length) frame.marks = { ...this.marks };
    this.log.push(stampLoc(frame));
    this.sink?.(frame);
  }
}

/**
 * Run a tree/heap algorithm — a plain function over a {@link TracedTree} — returning a factory that yields
 * its recorded trace as a fresh generator each call (replay-safe).
 */
export function runTreeAlgorithm(
  algo: (t: TracedTree) => void,
  initial: readonly TreeNode[] = [],
): () => Generator<Frame> {
  return function* () {
    const t = new TracedTree(initial);
    algo(t);
    yield* t.trace();
  };
}

// ── the scene tracer (#3259) — MULTI-STRUCTURE decomposition ──
//
// A larger algorithm isn't one structure: Dijkstra is a graph + a distance array (+ a heap, later). A
// `TracedScene` hands the algorithm several NAMED structures backed by the same `Traced*` classes, folds
// their ops into ONE synchronized `PanelsFrame` stream, and the player lays the panels side by side. Each
// op on any panel advances a beat whose frame is that panel's op-state + every other panel at its current
// state — so you watch the structures move TOGETHER. `runScene` is the multi-structure `runAlgorithm`.

/** A structure the scene can attach — the existing `Traced*` classes, seen through the two hooks the scene
 *  needs: read the constructor's resting frame, and redirect subsequent frames to the scene. */
interface Sinkable {
  trace(): StructureFrame[];
  setSink(fn: (f: StructureFrame) => void): void;
}

/**
 * A multi-structure trace context (#3259). `scene.array("dist", …)` / `scene.graph("g", …)` return the
 * ordinary `Traced*` instance (so the algorithm uses the SAME `compare`/`swap`/`visit`/`relax` vocabulary),
 * but each op is folded into a synchronized {@link PanelsFrame} keyed by the panel name. The first op emits
 * a resting snapshot of every panel; each op after emits the acting panel's op-frame beside the others at
 * rest. Panels declared before the first op all appear in that resting frame.
 */
export class TracedScene {
  private readonly initial: Record<string, StructureFrame> = {};
  private readonly current: Record<string, StructureFrame> = {};
  private readonly log: PanelsFrame[] = [];
  private started = false;
  private batching = false; // while set, panel ops fold into ONE beat (a cross-panel verb) — see beginBatch

  private attach<T extends Sinkable>(name: string, s: T): T {
    const rest = s.trace()[0]; // the constructor's at-rest frame (structures emit one on creation)
    this.initial[name] = rest;
    this.current[name] = rest;
    s.setSink((f) => {
      this.current[name] = f;
      if (!this.batching) this.pushFrame(); // a batched op just updates `current`; endBatch pushes once
    });
    return s;
  }

  /** Push one synchronized beat — beat 0 (every declared panel at rest) on the first, then the current map. */
  private pushFrame(): void {
    if (!this.started) {
      this.started = true;
      this.log.push({ panels: { ...this.initial } }); // beat 0 — every declared panel at rest
    }
    // Beat 0 above is the at-rest snapshot — it precedes every op, so it is deliberately NOT stamped.
    // This beat IS an op, so it carries that op's source range (#3250); its inner panel frames were
    // already stamped by their own structure's emit.
    this.log.push(stampLoc<PanelsFrame>({ panels: { ...this.current } }));
  }

  /** Open a CROSS-PANEL beat (#3286): ops on several panels fold into ONE `PanelsFrame` until {@link
   *  endBatch}, so a move / cross-compare animates as a single synchronized step. */
  private beginBatch(): void {
    this.batching = true;
  }
  /** Close the cross-panel beat, emitting the accumulated panel changes as one synchronized frame. */
  private endBatch(): void {
    this.batching = false;
    this.pushFrame();
  }

  /** A named array panel (its `data`/ops render via `<ArrayView>`). */
  array(name: string, input: readonly number[]): TracedArray {
    return this.attach(name, new TracedArray(input));
  }
  /** A named matrix panel (renders via `<MatrixView>`). */
  matrix(name: string, input: readonly (readonly number[])[]): TracedMatrix {
    return this.attach(name, new TracedMatrix(input));
  }
  /** A named graph panel (renders via `<GraphView>`). */
  graph(name: string, input: GraphInput): TracedGraph {
    return this.attach(name, new TracedGraph(input));
  }
  /** A named stack / queue / deque panel (renders via `<StackView>`). */
  stack(name: string, mode: StackMode = "stack", initial: readonly (number | string)[] = []): TracedStack {
    return this.attach(name, new TracedStack(mode, initial));
  }
  /** A named scalar-state panel — counters / accumulators / the current pointer (renders via `<ScalarView>`). */
  scalar(name: string, initial: Record<string, number | string> = {}): TracedScalar {
    return this.attach(name, new TracedScalar(initial));
  }
  /** A named tree / heap / BST panel (parent-pointer nodes; renders via `<TreeView>`). */
  tree(name: string, initial: readonly TreeNode[] = []): TracedTree {
    return this.attach(name, new TracedTree(initial));
  }

  // ── cross-panel verbs (#3286) — operations that span two array panels animate as ONE beat ──

  /**
   * Compare a cell in array panel `a` against a cell in array panel `b` — BOTH cells flash in ONE
   * synchronized beat, returning `sign(a[i] - b[j])`. The cross-panel twin of a single array's `compare`:
   * the merge decision between two runs living in different panels.
   */
  compareAcross(a: TracedArray, i: number, b: TracedArray, j: number): number {
    this.beginBatch();
    a.compare(i, i); // highlight the front of `a` (a self-pair marks just cell i) …
    b.compare(j, j); // … and the front of `b`, in the same beat
    this.endBatch();
    return Math.sign(a.get(i) - b.get(j));
  }

  /**
   * Move the value at `from[i]` into `to[k]` — the source cell highlights and the destination write animate
   * TOGETHER in one beat, so the value visibly slides between panels.
   */
  move(from: TracedArray, i: number, to: TracedArray, k: number): void {
    const v = from.get(i);
    this.beginBatch();
    from.compare(i, i); // the source cell highlights as the value leaves …
    to.set(k, v); // … and lands in the destination, same beat
    this.endBatch();
  }

  /** The recorded synchronized panel trace — a resting snapshot when the program did no ops. */
  frames(): PanelsFrame[] {
    return this.started ? [...this.log] : [{ panels: { ...this.initial } }];
  }
}

/**
 * Run a MULTI-STRUCTURE algorithm against a {@link TracedScene} (#3259) — the scene twin of
 * {@link runAlgorithm}. The program declares its named panels from `input` and drives them; the returned
 * factory yields the synchronized `PanelsFrame` trace as a fresh generator each call (replay-safe).
 */
export function runScene<I>(program: (scene: TracedScene, input: I) => void, input: I): () => Generator<Frame> {
  return function* () {
    const scene = new TracedScene();
    program(scene, input);
    yield* scene.frames();
  };
}

// Transformations stage (#2509 slice a) — the pure data model behind the planner's transformations
// substrate: the modification counterpart to features. The planner decomposes a modification
// request into verb-shaped rows (`bsc plan transformation add`), the poll reflects the plan.db list
// into `planTransformations`, and the pane presents them as a BOTTOM-UP CONFIRM QUEUE (the settled
// presentation model): grouped by composition tier (0 = primitives … N = pages), only the lowest
// tier with pending work is actionable, and confirmation unlocks the next tier — so composites are
// generated against confirmed primitives and nothing is built on unreviewed foundations. An item is
// pending or confirmed, NOTHING ELSE (no rejections/exclusions — changes are described to the
// planner conversationally and the item re-presents). Pure (no React/Tauri) so it's unit-testable.
//
// The verb/recipe/tier TAXONOMY is `@data` (#2509 slice b, `@data/transformations/taxonomy.json`,
// per the config-externalization standard #2027): the SAME file `crates/plandb` embeds for the
// `bsc plan transformation` set-time enums, so the vocabulary can't drift between the CLI
// validator and the pane's display metadata (verbMeta tooltips, tierLabel headings).

import { visitNodes, type GeneralNode } from "@/shared/ui/spec";
import taxonomyEmbedded from "@data/transformations/taxonomy.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

/** The identified piece of the existing system a transformation modifies — discovered by
 *  scanning, never invented. */
export interface TransformationTarget {
  description: string;
  files?: string[];
}

/** Where a row came from: the generating recipe (e.g. migrate-to-kit) + the scanned evidence
 *  (the bespoke implementations it replaces/generalizes). */
export interface TransformationProvenance {
  recipe?: string;
  evidence?: string[];
}

/** One `bsc plan transformation list --json` row — the unit of modification (#2509):
 *  verb · target · delta · invariants · blast radius, plus the confirm-queue fields
 *  (`tier`/`confirmed`) and the optional live-render `spec` (a node tree). */
export interface TransformationRow {
  id: string;
  /** From the verb taxonomy (rename · extract · split · merge · …) — each has a known recipe. */
  verb: string;
  title: string;
  target: TransformationTarget;
  /** from-state → to-state. */
  delta: string;
  /** What must NOT change — the modification twin of acceptance criteria. */
  invariants: string[];
  /** Blast radius: owned globs (maps 1:1 onto stream partitioning). */
  owns: string[];
  /** Planning-time sequencing hint (never a runtime wait, #1039). */
  dependsOn?: string[];
  /** Composition tier: 0 = primitives … N = pages. Drives the bottom-up confirm order. */
  tier: number;
  provenance?: TransformationProvenance;
  /** A gap-fill that contributes a missing abstraction to the kit itself. */
  kitContribution?: boolean;
  /** A render spec (#1852, general node form since #3500) — rendered live through KitRenderer. */
  spec?: object;
  confirmed?: boolean;
}

const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);

// ── taxonomy (@data/transformations/taxonomy.json, #2509 slice b) ─────────────

/** One verb of the fixed taxonomy: display metadata + the one-line hint of how that verb's
 *  invariants are typically checked. */
export interface TransformationVerbMeta {
  id: string;
  label: string;
  blurb: string;
  verification: string;
}

/** One composite recipe (migrate-to-kit · extract-and-abstract): the canonical steps the
 *  Transformations stage prompt's playbooks expand. */
export interface TransformationRecipeMeta {
  id: string;
  label: string;
  blurb: string;
  steps: string[];
}

/** One composition tier of the bottom-up confirm queue (0 primitives … 3 pages). */
export interface TransformationTierMeta {
  tier: number;
  label: string;
  blurb: string;
}

export interface TransformationTaxonomy {
  verbs: TransformationVerbMeta[];
  recipes: TransformationRecipeMeta[];
  tiers: TransformationTierMeta[];
}

// The config-dir copy (#2047) overlays the embedded default — editable without a rebuild.
export const TRANSFORMATION_TAXONOMY: TransformationTaxonomy =
  overlayFile("transformations/taxonomy.json", taxonomyEmbedded as TransformationTaxonomy);

/** The taxonomy's display metadata for one verb (label/blurb/verification — the blurb is the verb
 *  chip's tooltip), tolerant of a stale taxonomy file (an unknown id echoes back bare). */
export function verbMeta(id: string): TransformationVerbMeta {
  return (
    TRANSFORMATION_TAXONOMY.verbs.find((v) => v.id === id) ?? { id, label: id, blurb: "", verification: "" }
  );
}

/**
 * The `transformationsConfirmed` gate signal (#2509): the queue is non-empty AND every row is
 * confirmed. (The final "Completed UI" sign-off is the normal stage confirm on top of this.)
 */
export function transformationsConfirmed(rows: TransformationRow[] | null | undefined): boolean {
  return !!rows && rows.length > 0 && rows.every((r) => r.confirmed === true);
}

/** One tier of the confirm queue: its number + its rows in original list order. */
export interface TierGroup {
  tier: number;
  rows: TransformationRow[];
}

/**
 * Group rows by tier, tiers ascending (0 = primitives first), rows POSITION-STABLE within each
 * tier (list order is the planner's order — never re-sorted).
 */
export function tierGroups(rows: TransformationRow[]): TierGroup[] {
  const byTier = new Map<number, TransformationRow[]>();
  for (const r of rows) {
    const t = Number.isFinite(r.tier) ? r.tier : 0;
    const bucket = byTier.get(t);
    if (bucket) bucket.push(r);
    else byTier.set(t, [r]);
  }
  return [...byTier.entries()]
    .sort(([a], [b]) => a - b)
    .map(([tier, tierRows]) => ({ tier, rows: tierRows }));
}

/**
 * The current actionable tier: the LOWEST tier containing an unconfirmed row. `null` when the
 * queue is empty or fully confirmed (nothing pending — the completion card shows).
 */
export function nextPendingTier(rows: TransformationRow[]): number | null {
  let lowest: number | null = null;
  for (const r of rows) {
    if (r.confirmed === true) continue;
    const t = Number.isFinite(r.tier) ? r.tier : 0;
    if (lowest === null || t < lowest) lowest = t;
  }
  return lowest;
}

/**
 * Display label for a tier heading, driven by the taxonomy's tier ladder (#2509 slice b —
 * primitives → composites → layouts → pages): tier 0 is always the floor (the first taxonomy
 * tier), the TOP tier (when above 0) is the last (pages), and a middle tier reads its taxonomy
 * label clamped to the middle band — "Tier 0 · primitives" → "Tier 1 · composites" →
 * "Tier 2 · layouts" → "Tier N · pages".
 */
export function tierLabel(tier: number, maxTier: number): string {
  const tiers = TRANSFORMATION_TAXONOMY.tiers;
  const last = tiers.length - 1;
  const idx = tier <= 0 ? 0 : tier >= maxTier ? last : Math.min(tier, last - 1);
  const kind = tiers[idx]?.label;
  return kind ? `Tier ${tier} · ${kind}` : `Tier ${tier}`;
}

/**
 * Coerce the `bsc plan transformation list --json` blob into typed rows — a light structural
 * check (the CLI validates hard at write, #2395): anything that isn't an array of objects with a
 * string `id` is rejected; a missing/invalid `tier` reads as 0 so a partial row never breaks the
 * queue grouping.
 */
export function coerceTransformationRows(raw: unknown): TransformationRow[] {
  if (!Array.isArray(raw)) return [];
  return raw
    .filter((r): r is Record<string, unknown> => isRecord(r) && typeof r.id === "string")
    .map((r) => {
      const row = r as unknown as TransformationRow;
      return Number.isFinite(row.tier) ? row : { ...row, tier: 0 };
    });
}

/** Count the nodes of a render spec tree — the "spec present (n nodes)" fallback figure shown when the
 *  live render is unavailable.
 *
 *  Delegates to the SDK's own `visitNodes` rather than re-walking the tree here. #3500 moved slots into
 *  `props` (a Card's `header` used to be a top-level field), so a local walk that only descended
 *  top-level fields silently undercounted every nested slot — and a count that disagrees with the
 *  renderer about how many nodes a spec has is worse than no count. A tree that is not a valid node
 *  counts 0, which is exactly when the caller wants the fallback anyway. */
export function specNodeCount(spec: unknown): number {
  if (!isRecord(spec) || typeof spec.type !== "string") return 0;
  let count = 0;
  visitNodes(spec as unknown as GeneralNode, () => { count += 1; });
  return count;
}

export function transpose(m: number[][]): number[][] {
  const a = m.map((r) => [...r]);
  const n = a.length;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++) [a[i][j], a[j][i]] = [a[j][i], a[i][j]];
  return a;
}

// TREE trace-programs (#3220, epic #3215) — the binary-search-tree pair, written over a TracedTree so the
// animation is DERIVED from the real walk: every `compare` frame IS the comparison that chose a branch.
//
// WHY THESE EXIST: same story as the stack programs. `TracedTree`, `<TreeView>`, `treeLayout.ts` and their
// tests all shipped, but no program was ever registered for the `tree` structure — so a tree could only be
// met inside a scene, never selected. These two open it, and they are a matched pair on purpose: BUILD the
// structure (insert, which is where the compares live) then READ it (in-order, which is what makes a BST
// worth building — the sorted walk).
import type { TracedTree, TreeNode } from "@/features/algorithms/lib/tracer";

/** A visualizable tree algorithm — its logic over a {@link TracedTree}, plus the nodes the tree STARTS with.
 *  `seed` is what separates the pair: insert starts from nothing and builds; in-order starts from a finished
 *  tree and walks it, so the build noise is not replayed as part of the traversal. */
export interface TreeProgram {
  run: (t: TracedTree, values: number[]) => void;
  /** The tree at rest before `run` — `[]` when the algorithm builds it itself. */
  seed: (values: number[]) => TreeNode[];
  defaultInput: number[];
}

/** A BST laid out as ids + child links. Ids are `n<i>` by INSERTION order, so a node's id is stable across
 *  both programs and the two animations are talking about the same tree. */
export interface BstShape {
  nodes: TreeNode[];
  left: Record<string, string | undefined>;
  right: Record<string, string | undefined>;
  rootId: string | undefined;
}

/**
 * Build the BST that `values` produces, as pure data — no tracer, no frames.
 *
 * Both programs need to know the tree's shape: insert walks it to find each landing spot, and in-order
 * needs the child links the tracer does not model (a {@link TreeNode} carries only a `parent`, which is
 * enough to LAY OUT a tree but not enough to walk one in order). Deriving the shape here once keeps the two
 * programs consistent by construction. Duplicates are dropped — a BST holds a set.
 */
export function bstShape(values: readonly number[]): BstShape {
  const nodes: TreeNode[] = [];
  const left: Record<string, string | undefined> = {};
  const right: Record<string, string | undefined> = {};
  const valueOf: Record<string, number> = {};
  let rootId: string | undefined;

  for (const v of values) {
    const id = `n${nodes.length}`;
    if (rootId === undefined) {
      rootId = id;
      nodes.push({ id, value: v });
      valueOf[id] = v;
      continue;
    }
    let cur = rootId;
    for (;;) {
      if (v === valueOf[cur]) break; // already present — a BST holds a set
      const goLeft = v < valueOf[cur];
      const next = goLeft ? left[cur] : right[cur];
      if (next === undefined) {
        if (goLeft) left[cur] = id;
        else right[cur] = id;
        nodes.push({ id, value: v, parent: cur });
        valueOf[id] = v;
        break;
      }
      cur = next;
    }
  }
  return { nodes, left, right, rootId };
}

/**
 * Insert each value into a BST, starting from an empty tree — the build half of the pair.
 *
 * The descent is the animation: each node the walk passes through takes a `path` mark, and the value lands
 * with an `insert` frame under the parent that trail chose.
 *
 * `compare` is deliberately NOT used. The tracer compares two EXISTING nodes by id, and the value being
 * placed has no node until it lands — so the only compare available during a descent is a node against
 * itself, which would render a decision frame that describes nothing. The path marks are the real trail;
 * an honest empty frame beats a decorative one.
 */
export function bstInsert(t: TracedTree, values: number[]): void {
  const shape = bstShape(values);
  const valueOf = new Map(shape.nodes.map((n) => [n.id, n.value as number]));
  for (const node of shape.nodes) {
    const v = node.value as number;
    if (node.parent === undefined) {
      t.insert(node.id, v); // the root names itself
      continue;
    }
    let cur = shape.rootId!;
    for (;;) {
      t.mark(cur, "path");
      if (cur === node.parent) break;
      const next = v < valueOf.get(cur)! ? shape.left[cur] : shape.right[cur];
      if (next === undefined) break;
      cur = next;
    }
    t.insert(node.id, v, node.parent);
    t.mark(node.id, "current");
  }
}

/**
 * Walk a finished BST in order (left · node · right) — the read half of the pair, and the reason a BST is
 * worth building: the visit sequence comes out SORTED.
 *
 * Iterative with an explicit stack rather than recursion, so the traversal's own pending set is a real data
 * structure the frames can reflect, and a deep tree cannot blow the JS stack.
 */
export function bstInorder(t: TracedTree, values: number[]): void {
  const shape = bstShape(values);
  const stack: string[] = [];
  let cur = shape.rootId;
  while (cur !== undefined || stack.length > 0) {
    while (cur !== undefined) {
      t.mark(cur, "path"); // descending the left spine
      stack.push(cur);
      cur = shape.left[cur];
    }
    const id = stack.pop()!;
    t.visit(id); // the in-order position — these fire in sorted order
    cur = shape.right[id];
  }
}

/** The default seed — an unbalanced-but-readable BST: root 50, both subtrees populated, 9 nodes. */
const TREE_MOCK = [50, 30, 70, 20, 40, 60, 80, 35, 65];

/** The visualizable tree algorithms, keyed by base name (#3220). */
export const TREE_PROGRAMS: Record<string, TreeProgram> = {
  "bst-insert": { run: bstInsert, seed: () => [], defaultInput: TREE_MOCK },
  "bst-inorder": { run: bstInorder, seed: (values) => bstShape(values).nodes, defaultInput: TREE_MOCK },
};

/** Serialize a tree seed to the "your input" text form — the insertion order, comma-separated. */
export function treeToText(input: readonly number[]): string {
  return input.join(", ");
}

/**
 * Parse the "your input" text into an insertion order — comma- or space-separated whole numbers. Throws a
 * helpful `Error` (shown under the field) on empty, non-numeric, or unwatchably-large input.
 */
export function parseTreeInput(text: string): number[] {
  const t = text.trim();
  if (t.length === 0) throw new Error("Enter numbers to insert, e.g. 50, 30, 70");
  const parts = t.split(/[\s,]+/).filter(Boolean);
  const out: number[] = [];
  for (const p of parts) {
    const n = Number(p);
    if (!Number.isFinite(n)) throw new Error(`"${p}" is not a number`);
    if (!Number.isInteger(n)) throw new Error("Use whole numbers so the nodes stay readable");
    out.push(n);
  }
  if (out.length > 15) throw new Error("Keep it to 15 values so the tree stays on screen");
  return out;
}

// Tree layout (#2476, Layouts tier #2197) — the pure (React-free) model behind the Tree template's
// LAYERED variant. A tree is a single-parent DAG, so the placement is exactly the shared graph
// stack: `layerDag` (#2214) assigns each node its depth (roots at layer 0), `orderLayers` (#2418)
// runs the shared barycenter sweep so subtrees stay grouped under their parent, and this module owns
// only the layer→pixel PLACEMENT (centered rows, top-down) — the same discipline as the Design
// Studio's `compositionLayout` (#2455). Nothing here forks graph logic; it only feeds the shared
// pieces tree-shaped input.
import { layerDag } from "@/shared/lib/graph/layers";
import { orderLayers } from "@/shared/lib/graph/order";
import type { GraphEdge } from "@/shared/lib/graph/types";

/** The recursive node the Tree template takes — ids must be unique across the whole tree. */
export interface TreeNodeData {
  id: string;
  label: string;
  /** Optional dimmed mono meta after the label (a count, a kind, a size). */
  meta?: string;
  children?: TreeNodeData[];
}

/** One node of the flattened tree, with its parent link and indentation depth. */
export interface FlatTreeNode {
  node: TreeNodeData;
  parentId?: string;
  depth: number;
}

/** Depth-first flatten (pre-order) — the indented variant's row order and the layout's seed order. */
export function flattenTree(nodes: readonly TreeNodeData[]): FlatTreeNode[] {
  const out: FlatTreeNode[] = [];
  const walk = (list: readonly TreeNodeData[], parentId: string | undefined, depth: number) => {
    for (const node of list) {
      out.push({ node, parentId, depth });
      if (node.children?.length) walk(node.children, node.id, depth + 1);
    }
  };
  walk(nodes, undefined, 0);
  return out;
}

/** The tree's parent→child edges in the shared `GraphEdge` shape. */
export function treeEdges(flat: readonly FlatTreeNode[]): GraphEdge[] {
  return flat
    .filter((f) => f.parentId !== undefined)
    .map((f) => ({ id: `${f.parentId}->${f.node.id}`, from: f.parentId as string, to: f.node.id }));
}

/** Node card box (world coords) — shared with the Tree component's node + edge rendering. */
export const TREE_NODE_W = 156;
export const TREE_NODE_H = 46;

export interface TreeLayoutMetrics {
  nodeW: number;
  nodeH: number;
  /** Horizontal clearance between siblings in a row. */
  hGap: number;
  /** Vertical clearance between layers (the gap the edges cross). */
  vGap: number;
  /** World padding around the whole layout. */
  pad: number;
}

export const DEFAULT_TREE_METRICS: TreeLayoutMetrics = {
  nodeW: TREE_NODE_W, nodeH: TREE_NODE_H, hGap: 26, vGap: 74, pad: 48,
};

export interface TreeLayout {
  /** Node id → its card's top-left corner in world coords. */
  pos: Map<string, { x: number; y: number }>;
  /** The parent→child edges (drawn with the shared edge grammar). */
  edges: GraphEdge[];
  /** World (design-space) size — the GraphCanvas `world` box. */
  world: { w: number; h: number };
  /** Node id → its layer (0 = roots). Exposed for tests + callers. */
  layer: Record<string, number>;
}

/**
 * Top-down tree placement: `layerDag` depth → row, shared barycenter ordering within each row
 * (neighbors = the hierarchy parent + children, sequential sweep — the Org discipline), rows
 * centered so parents sit over their subtrees.
 */
export function layoutTree(
  nodes: readonly TreeNodeData[],
  metrics: TreeLayoutMetrics = DEFAULT_TREE_METRICS,
): TreeLayout {
  const m = metrics;
  const flat = flattenTree(nodes);
  const ids = flat.map((f) => f.node.id);
  const edges = treeEdges(flat);
  const layer = layerDag(ids, edges);

  const parentOf = new Map<string, string>();
  const childrenOf = new Map<string, string[]>();
  for (const e of edges) {
    parentOf.set(e.to, e.from);
    const kids = childrenOf.get(e.from);
    if (kids) kids.push(e.to); else childrenOf.set(e.from, [e.to]);
  }
  const rows = orderLayers(
    ids,
    (id) => layer[id] ?? 0,
    (id) => {
      const p = parentOf.get(id);
      return p ? [p, ...(childrenOf.get(id) ?? [])] : childrenOf.get(id) ?? [];
    },
  );

  const rowWidth = (n: number) => n * m.nodeW + Math.max(0, n - 1) * m.hGap;
  const maxRow = Math.max(0, ...[...rows.values()].map((r) => r.length));
  const w = Math.max(320, 2 * m.pad + rowWidth(maxRow));

  const pos = new Map<string, { x: number; y: number }>();
  let bottom = m.pad;
  for (const [l, row] of [...rows.entries()].sort(([a], [b]) => a - b)) {
    const y = m.pad + l * (m.nodeH + m.vGap);
    const x0 = (w - rowWidth(row.length)) / 2; // center each row — parents sit over their subtree
    row.forEach((id, i) => pos.set(id, { x: x0 + i * (m.nodeW + m.hGap), y }));
    bottom = y + m.nodeH;
  }
  const h = Math.max(240, bottom + m.pad);

  return { pos, edges, world: { w, h }, layer };
}

// The `tree` viz kit's MOTION wiring (#3270, epic #3220/#2942) — injects the compiled motion CSS
// (insert / swap / visit / compare) into the live TreeView. The animation DATA lives in a SHARED,
// feature-agnostic home (`@/shared/ui/kit/treeVizAnimations`) so BOTH consumers read ONE definition: this
// renderer AND a (later) `tree-viz` Designs builtin kit. `TreeView`'s root carries the applying classes
// ({@link TREE_VIZ_ANIM_CLASSES}); its node circles only stamp `data-op`. Mirrors graphViewMotion.
import { animClassName, compileAnimationsCss, kitAnimations } from "@/shared/ui/kit";
import { TREE_VIZ_KIT_ID, TREE_VIZ_ANIMATIONS } from "@/shared/ui/kit/treeVizAnimations";

// Re-export the shared data so this renderer's public surface (and the algorithms barrel) is unchanged.
export { TREE_VIZ_KIT_ID, TREE_VIZ_ANIMATIONS };

/** The applying classes the renderer's root carries so the state-scoped rules match its node circles. */
export const TREE_VIZ_ANIM_CLASSES: string = TREE_VIZ_ANIMATIONS.map((a) =>
  animClassName({ kit: TREE_VIZ_KIT_ID, name: a.name }),
).join(" ");

/** The compiled motion CSS — produced ONCE from {@link TREE_VIZ_ANIMATIONS}. Pure. */
export const TREE_VIZ_MOTION_CSS: string = compileAnimationsCss(
  kitAnimations([{ id: TREE_VIZ_KIT_ID, animations: TREE_VIZ_ANIMATIONS }]),
);

const STYLE_ID = "bsc-tree-viz-animations";

/** Inject the compiled tree motion CSS into a dedicated managed `<style>` (idempotent). `doc` param'd for
 *  tests. Mirrors `ensureGraphViewMotion` on its own style id. */
export function ensureTreeViewMotion(doc: Document = document): void {
  if (!TREE_VIZ_MOTION_CSS) return;
  let el = doc.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!el) {
    el = doc.createElement("style");
    el.id = STYLE_ID;
    doc.head.appendChild(el);
  }
  if (el.textContent !== TREE_VIZ_MOTION_CSS) el.textContent = TREE_VIZ_MOTION_CSS;
}

// The `tree-viz` kit's MOTION library as DATA (#3270, epic #3171/#2942) — the insert / swap / visit /
// compare animations for the tree/heap renderer, authored as {@link KitAnimation} data and compiled by the
// kit-motion engine. SVG-safe properties only (stroke / stroke-width / opacity / transform), since TreeView
// draws nodes + edges as SVG — the tree twin of the graph motion set.
//
// ── WHY THIS LIVES IN shared/ui/kit ──────────────────────────────────────────────────────────────────
// Like the array (#3194) + matrix/graph (#3242) + stack/scalar (#3266/#3268) sets: two consumers in two
// features, one definition — the Algorithms TreeView renderer (`features/algorithms/.../treeViewMotion.ts`)
// injects the compiled CSS, and the Designs seed can register `tree-viz` as a recoverable builtin kit (a
// later slice). Feature-agnostic viz-motion, so it lives HERE to avoid a designs↔algorithms cycle.
//
// STATE-TRIGGER SEAM (#3058): each selector IS the transient data-op TreeView stamps on the node circle
// (`[data-op="insert"]`, …) — the DURABLE node states (current/path/target) are static colours in
// treeView.css; these are the one-shot transitions.

import type { KitAnimation } from "@/shared/ui/kit/animations";

/** The tree-visualization motion kit id — `.tree-viz-anim-<name>` + `@keyframes bsc-tree-viz-<name>`. */
export const TREE_VIZ_KIT_ID = "tree-viz";

/** The tree kit's animations as DATA — insert (a new node scales + fades in at its slot), swap (the two
 *  sift nodes flash their outline as their values exchange), visit (a pop as a node is touched/extracted),
 *  compare (a brief outline pulse on a read). SVG-safe; the engine wraps each in
 *  `prefers-reduced-motion: no-preference`. The single source the TreeView renderer + the (later) `tree-viz`
 *  Designs kit both consume. */
export const TREE_VIZ_ANIMATIONS: KitAnimation[] = [
  // insert — a new node scales up + fades in as it joins the tree.
  {
    name: "insert",
    selector: '[data-op="insert"]',
    duration: "420ms",
    easing: "cubic-bezier(0.34, 1.4, 0.5, 1)",
    keyframes: {
      "0%": { transform: "scale(0.4)", opacity: "0.2", stroke: "var(--accent)" },
      "100%": { transform: "scale(1)", opacity: "1" },
    },
  },
  // swap — the two nodes whose values exchange (the heap sift) flash their outline.
  {
    name: "swap",
    selector: '[data-op="swap"]',
    duration: "440ms",
    easing: "var(--ease-standard)",
    keyframes: {
      "0%": { stroke: "var(--accent)", "stroke-width": "3.5", transform: "scale(1.12)" },
      "100%": { "stroke-width": "1.5", transform: "scale(1)" },
    },
  },
  // visit — the node pops as it's touched / extracted as the min.
  {
    name: "visit",
    selector: '[data-op="visit"]',
    duration: "420ms",
    easing: "cubic-bezier(0.34, 1.4, 0.5, 1)",
    keyframes: {
      "0%": { transform: "scale(1.34)" },
      "100%": { transform: "scale(1)" },
    },
  },
  // compare — a brief outline pulse on a read that leaves the tree unchanged.
  {
    name: "compare",
    selector: '[data-op="compare"]',
    duration: "460ms",
    easing: "var(--ease-standard)",
    keyframes: {
      "0%": { "stroke-width": "1.5" },
      "45%": { "stroke-width": "4", stroke: "var(--state-wait)" },
      "100%": { "stroke-width": "1.5" },
    },
  },
];

// One-time triaged grandfather (#2548) — the pure backfill behind the persist migration.
//
// The Glance triaged filter (#2541) is FORWARD-LOOKING: `triagedProjects` is only stamped when a
// triage/fleet launches after the feature shipped. So on upgrade, every project worked BEFORE the
// filter has no marker and vanishes from Glance ("No project network yet"). This backfills the marker
// once, from the projects clearly already worked:
//   • every published GitHub project — its plan key is `projectSlug(board title)` (#2409), the same key
//     the Glance node + drill resolve against, and
//   • every project with a planned fleet (`planFleet` keys carrying streams).
//
// A fresh install has no persisted state, so the migration never runs for it — the strict rule holds
// (a genuinely new draft/published project stays hidden until it's actually triaged).
import { projectSlug } from "@/shared/lib/core/projectPaths";

/** The `githubState.records` fields the backfill reads (#2446 minimal record). */
interface RecordLite { title?: string }
/** The `planFleet` value fields the backfill reads. */
interface FleetLite { streams?: unknown[] }

/**
 * Compute the grandfathered `triagedProjects` map (plan key → `now`) from a persisted state's published
 * board + planned fleets. Pure + deterministic (caller passes `now`).
 */
export function grandfatherTriaged(
  records: RecordLite[] | undefined,
  planFleet: Record<string, FleetLite | undefined> | undefined,
  now: number,
): Record<string, number> {
  const out: Record<string, number> = {};
  for (const r of records ?? []) if (r?.title) out[projectSlug(r.title)] = now;
  for (const [key, fleet] of Object.entries(planFleet ?? {})) {
    if ((fleet?.streams?.length ?? 0) > 0) out[key] = now;
  }
  return out;
}

/**
 * Grandfather LOCAL published hubs into the triaged set (#2548 follow-up). The persist migration reads the
 * PERSISTED `githubState.records` + `planFleet`, but both are empty when the user is logged out or after a
 * state reset — so an existing user's on-disk published projects still vanished from Glance. The on-disk
 * published inventory (`list_local_projects`) is the RELIABLE "already worked" set. Stamp each local
 * published hub key not already marked, preserving existing timestamps. Keyed by the hub FOLDER key —
 * exactly the key the Glance node + `filterTriaged` resolve against. Pure + deterministic.
 */
export function grandfatherLocalPublished(
  localPublishedKeys: string[],
  existing: Record<string, number>,
  now: number,
): Record<string, number> {
  const out = { ...existing };
  for (const key of localPublishedKeys) if (key && out[key] === undefined) out[key] = now;
  return out;
}

// Mobile tunnel — Tauri command wrappers (#243).
//
// Thin typed bindings to the Rust relay client (`src-tauri/src/tunnel.rs`). Kept apart
// from `tunnel.ts` so that module stays free of Tauri imports and unit-testable; this
// one is the side-effecting boundary the Settings card and ConsoleWorkspace call.

import { invoke } from "@tauri-apps/api/core";
import type {
  PaneDescriptor, SessionMeta, TunnelStatus,
  PlanMessage, PlanPipelineRun, PlanEventKind,
} from "@/features/tunnel/lib/tunnel";
import type { CanonicalFile } from "@/features/planner";

/** Mint a room + pairing secret and dial the relay. Returns the updated status. */
export const tunnelStart = (relayUrl: string): Promise<TunnelStatus> =>
  invoke("tunnel_start", { relayUrl });

/** Stop the relay client and clear the pairing. */
export const tunnelStop = (): Promise<TunnelStatus> => invoke("tunnel_stop");

/** Current tunnel status (running, room, hostPubKey, client count, …). */
export const tunnelStatus = (): Promise<TunnelStatus> => invoke("tunnel_status");

/** Grant or revoke the paired phone's input control (#B-wan-viewonly). A paired phone is
 *  view-only until granted; revoking returns it to view-only. Returns the updated status. */
export const tunnelSetInputGranted = (granted: boolean): Promise<TunnelStatus> =>
  invoke("tunnel_set_input_granted", { granted });

/** Unpair the current device (#B-unpair-revoke): tear down the relay room, rotate the
 *  pairing secret (the old QR dies), and reconnect on a fresh room. Returns the updated
 *  status carrying the new room + QR. */
export const tunnelUnpair = (): Promise<TunnelStatus> => invoke("tunnel_unpair");

/** Push the current pane list to connected clients. */
export const tunnelSetPanes = (panes: PaneDescriptor[]): Promise<void> =>
  invoke("tunnel_set_panes", { panes });

/** Push per-pane session-state snapshots to connected clients. */
export const tunnelSetSessions = (sessions: SessionMeta[]): Promise<void> =>
  invoke("tunnel_set_sessions", { sessions });

/** Push the active project's canonical plan (files + manifest) to the relay so a paired
 *  mobile planner syncs over the tunnel instead of hitting the API (#801). `projectId` is
 *  the canonical `proj-<hex>` id from `hubToCanonical`. */
export const tunnelSetPlanState = (projectId: string, files: CanonicalFile[]): Promise<void> =>
  invoke("tunnel_set_plan_state", { projectId, files });

/** Acknowledge a plan push from mobile after the frontend applies the files to the hub directory
 *  (#3248). Broadcasts `plan_sync_ack` back to the mobile client so it learns the outcome. Called by
 *  {@link applyPushedPlanPush} — the `tunnel://plan-sync-push` listener path (Tunnel.tsx). */
export const tunnelAckPlanPush = (projectId: string, applied: boolean): Promise<void> =>
  invoke("tunnel_ack_plan_push", { projectId, applied });

/** Handle a `tunnel://plan-sync-push` (#3248): apply the plan files a mobile client pushed to the
 *  project's hub dir (a PATH-SAFE backend write — `apply_pushed_plan_files` refuses `..`/absolute
 *  paths), then ACK the outcome back to mobile via {@link tunnelAckPlanPush}. On ANY failure we ack
 *  `applied: false` rather than leave the phone hanging. Returns whether the push landed. */
export async function applyPushedPlanPush(projectId: string, files: CanonicalFile[]): Promise<boolean> {
  let applied = false;
  try {
    await invoke("apply_pushed_plan_files", { projectId, files });
    applied = true;
  } catch (e) {
    console.error("tunnel: applying a pushed plan failed:", e);
  }
  await tunnelAckPlanPush(projectId, applied).catch((e) => console.error("tunnel: plan-push ack failed:", e));
  return applied;
}

