// The app-wide store_state publisher (#2498) — the singleton the projector hook and the
// planner's plan-domain push share, bound to the real `tunnel_set_store_state` command.
// Kept apart from domainPublisher.ts so the engine stays Tauri-free and unit-testable.

import { createDomainPublisher } from "@/features/tunnel/lib/domainPublisher";
import { tunnelSetStoreState, type StoreDomain } from "@/features/tunnel/lib/tunnelClient";
import { log } from "@/shared/lib/core/log";

const publisher = createDomainPublisher({
  send: tunnelSetStoreState,
  onError: (domain, e) => log.error(`tunnel: store_state[${domain}] push failed: ${e}`),
});

/** Publish one domain's projection over the tunnel — debounced, deduped, rev-stamped.
 *  Safe to call on every derivation: an unchanged payload never reaches the wire. */
export function publishTunnelDomain(domain: StoreDomain, payload: unknown): void {
  publisher.publish(domain, payload);
}

/** Forget the last-sent cache (the next publish per domain re-sends). Called when the relay
 *  (re)starts so a fresh Rust-side store is repopulated even if the store didn't change. */
export function resetTunnelDomains(): void {
  publisher.reset();
}

// The tunnel feature's graph-platform surface (register-the-feature-logic-surface) — the modules a
// graph-loaded record imports from this feature but does NOT redraw.
//
// Registered HERE, inside the feature, because the shell must not reach a feature's internals (#1545)
// and eager-importing them from `app/` would de-lazy the whole feature at boot. The feature's BARREL
// calls this at module load, so the shadow catalogue's `ensurePlatform: () => import("@/features/tunnel")`
// is what registers them — the same shape `registerAutomationsPlatform` already uses.
//
// These files STAY on disk: registration is not migration. It makes a record that imports them
// loadable, which is the prerequisite for migrating the modules that import THEM.
import { registerAppModule } from "@/shared/lib/runtime/moduleRegistry";
import * as Tunnel from "@/features/tunnel/lib/tunnel";
import * as TunnelClient from "@/features/tunnel/lib/tunnelClient";
import * as RelayProbe from "@/features/tunnel/lib/relayProbe";
// `qrcode.react`, registered HERE and not in `appModules`: the pairing QR is the tunnel's own
// dependency and registration is EAGER, so putting it in the shell's set would pull the QR
// renderer into the boot bundle for every user who never pairs a phone.
import * as QrcodeReact from "qrcode.react";

let done = false;

/** Register this feature's injected graph-platform modules by the specifiers a record imports. Idempotent. */
export function registerTunnelPlatform(): void {
  if (done) return;
  done = true;
  registerAppModule("@/features/tunnel/lib/tunnel", Tunnel);
  registerAppModule("@/features/tunnel/lib/tunnelClient", TunnelClient);
  registerAppModule("@/features/tunnel/lib/relayProbe", RelayProbe);
  registerAppModule("qrcode.react", QrcodeReact);
}

