// Tunnel feature store slice (#1309) — the mobile-relay connection state. Extracted from the
// residual `shell` slice (formerly the `github` grab-bag). Composed by store/index.ts.
import type { StateCreator } from "zustand";
import type { AppStore } from "@/store/types";
import type { PaneDescriptor } from "@/features/tunnel/lib/tunnel";

export interface TunnelSlice {
  // The relay Worker URL is persisted (the user's BYO relay); `tunnelRunning` mirrors the Rust
  // client's connected state (transient) so ConsoleWorkspace knows whether to push live pane metadata.
  tunnelRelayUrl: string;
  setTunnelRelayUrl: (url: string) => void;
  tunnelRunning: boolean;
  setTunnelRunning: (v: boolean) => void;
  /** Ad-hoc session panes outside the Console tab grid, mirrored over the relay alongside the
   *  Console panes (#801/#2497), keyed by the REGISTERING SOURCE (`"planner"`, `"designer"`, …)
   *  so independent owners never clobber each other. Transient — not persisted. */
  tunnelExtraPanes: Record<string, PaneDescriptor[]>;
  /** Register (or replace) one source's mirrored panes; pass `[]` to unregister the source. */
  registerTunnelPanes: (source: string, panes: PaneDescriptor[]) => void;
}

export const createTunnelSlice: StateCreator<AppStore, [], [], TunnelSlice> = (set) => ({
  tunnelRelayUrl: "",
  setTunnelRelayUrl: (url) => set({ tunnelRelayUrl: url }),
  tunnelRunning: false,
  setTunnelRunning: (v) => set({ tunnelRunning: v }),
  tunnelExtraPanes: {},
  registerTunnelPanes: (source, panes) =>
    set((s) => {
      const next = { ...s.tunnelExtraPanes };
      if (panes.length === 0) delete next[source];
      else next[source] = panes;
      return { tunnelExtraPanes: next };
    }),
});

// Mobile tunnel — transport-agnostic protocol contract (#240, foundation of #210).
//
// The desktop owns the PTYs but not the pane *metadata* (names/cwds/statuses live in
// the Zustand store), so the frontend maps store state into the wire shapes the mobile
// client renders. This module is the pure contract + transforms; it has NO transport
// (the relay client lands in #242) and NO Tauri imports, so it's unit-testable.
//
// The wire schema is owned by the mobile client (`mobile-studio-code/src/lib/types.ts`)
// and carried unchanged inside the relay's Noise-encrypted envelope — the relay never
// sees these frames in plaintext. See `docs/tunnel-protocol.md`; the machine-readable
// contract is `tunnelProtocol.fixtures.json` (asserted in `src/__tests__/tunnel.test.ts`).

// The desktop's canonical per-pane status (#435), the input this module maps FROM.
import type { PaneStatus as DesktopPaneStatus } from "@/app/console/lib/paneStatus";
// Pane IDENTITY (#1176): the pane-id grammar + minting, a pure (React/Tauri-free) shell
// module. The roster keys panes by the SAME identity id the PTY/status/cwd are keyed by,
// so mobile's pane_input/pane_output target real PTY ids (#2497).
import { paneIdFor, parsePaneIdentity, isPlanningPaneId } from "@/app/console/lib/paneIdentity";
import type { CanonicalFile } from "@/features/planner";

/** The tunnel wire-contract version (#2497). Mirrors `bsc_tunnel::protocol::PROTOCOL_VERSION`
 *  (Rust owns the handshake; this constant exists TS-side for display/diagnostics only). */
export const TUNNEL_PROTOCOL_VERSION = 2;

/** Pane status as the mobile client models it (`PaneStatus`) — a distinct wire
 *  vocabulary the desktop's `DesktopPaneStatus` is mapped into by `mapStatus`. */
export type PaneStatus = "running" | "idle" | "awaiting_input" | "error";

/** What kind of session a mirrored pane is (#2497). The wire vocabulary is fixed —
 *  the fleet DIRECTOR rides as `worker` (a fleet session) and manual/positional console
 *  panes are `console`. Optional on the wire for backward compatibility (absent ⇒ console). */
// `soundDesigner` added #3369 (epic #3071 phase 4). ADDITIVE — no existing value changes meaning, so an
// older mobile build simply sees a kind it does not label rather than mis-labelling a session. Still a
// tunnel-contract change: mobile-studio-code should add the matching label in a follow-up.
export type PaneKind = "console" | "worker" | "planner" | "designer" | "architect" | "librarian" | "soundDesigner" | "integrator" | "triage";

/** One mirrored pane in the list the mobile client renders (`pane_list`). */
export interface PaneDescriptor {
  id: string;
  cwd: string;
  name: string;
  status: PaneStatus;
  /** Session kind (#2497); optional so a v1 peer's descriptor still parses. */
  kind?: PaneKind;
}

/** A per-pane session-state snapshot pushed to connected clients (`session_state`).
 *  Field names are camelCase on the wire to match the mobile client. */
export interface SessionMeta {
  paneId: string;
  status: PaneStatus;
  currentTask: string;
  lastActivity: string;
  prompt: string | null;
}

/** Live relay-tunnel status from the Rust client (relay-shaped — trust is via Noise,
 *  not a pinned cert). Mirrors `tunnel::TunnelStatus`. */
export interface TunnelStatus {
  running: boolean;
  /** The relay Worker URL this desktop dials (set once the transport connects). */
  relayUrl: string | null;
  /** The room id allocated for the current pairing. */
  room: string | null;
  /** base64 of the desktop's static Noise public key (mobile pins it via the QR). */
  hostPubKey: string;
  /** The pairing secret the mobile echoes to authenticate (carried only in the QR). */
  psk: string;
  clientCount: number;
  /** Whether the desktop has granted the paired phone input control. A freshly paired
   *  phone is view-only (`false`) until the desktop grants input (#B-wan-viewonly). */
  inputGranted: boolean;
}

/** The payload encoded into the pairing QR. The mobile dials `relayUrl`, joins `room`,
 *  authenticates the desktop by `hostPubKey` (Noise IK), and echoes `psk` to pair. */
export interface PairingPayload {
  relayUrl: string;
  room: string;
  hostPubKey: string;
  psk: string;
}

/** Build the QR/manual-entry payload from a status, or `null` if not yet pairable —
 *  the relay must be connected and a room + keys present. Pure (no transport). */
export function pairingPayload(s: TunnelStatus): PairingPayload | null {
  if (!s.running || !s.relayUrl || !s.room || !s.hostPubKey || !s.psk) return null;
  return { relayUrl: s.relayUrl, room: s.room, hostPubKey: s.hostPubKey, psk: s.psk };
}

// ── Planner-session frames (#934 / #985 / #986 / #987) ──────────────────────────
//
// The LIVE planning session projected to a paired phone, distinct from the async
// `plan_sync_*` file-reconciliation path (which stays as-is). The desktop is the single
// source of truth: it emits `plan_state` (full snapshot, replayed on connect), `plan_event`
// (transient deltas, fire-and-forget), and `plan_status` (cheap header, replayed); the phone
// mirrors them read-only and DRIVES via the inbound `plan_advance` / `plan_confirm` /
// `plan_chat` frames. Wire shapes are pinned in tunnelProtocol.fixtures.json and mirrored in
// mobile-studio-code; field names are camelCase, the `type` tag is snake_case.

/** One chat turn in the planning session, as the phone renders it. */
export interface PlanMessage {
  role: "user" | "assistant";
  text: string;
  /** Epoch ms. */
  at: number;
}

/** A pipeline run's live state (#220), projected to the phone. */
export interface PlanPipelineRun {
  id: string;
  stage: string;
  status: string;
}

/** Full live planning-session snapshot (server → phone). Replayed to a freshly-paired
 *  client, so it must stand alone. `files` is the canonical section set (via hubToCanonical). */
export interface PlanStateFrame {
  type: "plan_state";
  projectId: string;
  currentStage: string;
  confirmedSections: string[];
  files: CanonicalFile[];
  messages: PlanMessage[];
  pipelineRuns: PlanPipelineRun[];
}

export type PlanEventKind = "section_confirmed" | "stage_advanced" | "message_appended" | "pipeline_run";

/** A transient planning delta (server → phone). Fire-and-forget — NOT replayed (a late
 *  client gets the full picture from the replayed plan_state instead). The detail fields are
 *  populated per `kind`. */
export interface PlanEventFrame {
  type: "plan_event";
  projectId: string;
  kind: PlanEventKind;
  /** Epoch ms. */
  at: number;
  /** kind === "section_confirmed". */
  section?: string;
  /** kind === "stage_advanced". */
  stage?: string;
  /** kind === "message_appended". */
  message?: PlanMessage;
  /** kind === "pipeline_run". */
  run?: PlanPipelineRun;
}

/** Cheap header update (server → phone): the active stage + a short plan-status label.
 *  Replayed on connect. */
export interface PlanStatusFrame {
  type: "plan_status";
  projectId: string;
  currentStage: string;
  status: string;
}

/** Phone → desktop: advance to (or jump to) a stage. */
export interface PlanAdvanceFrame {
  type: "plan_advance";
  projectId: string;
  stageKey: string;
}

/** Phone → desktop: confirm a plan section. */
export interface PlanConfirmFrame {
  type: "plan_confirm";
  projectId: string;
  section: string;
}

/** Phone → desktop: send a chat message into the live planner session. */
export interface PlanChatFrame {
  type: "plan_chat";
  projectId: string;
  text: string;
}

// ── Store → wire mapping (pure) ─────────────────────────────────────────────────

/** Number of panes in a tab from its `"cols×rows"` layout string. */
export function paneCountForLayout(layout: string): number {
  const [cols, rows] = layout.split("×").map((n) => parseInt(n, 10));
  if (!Number.isFinite(cols) || !Number.isFinite(rows)) return 0;
  return cols * rows;
}

/** Map the desktop's per-pane status (`run|on|idle`) plus the awaiting-input set
 *  to the mobile `PaneStatus` vocabulary. A running pane stays `running` even if
 *  it is (also) flagged awaiting; otherwise an awaiting pane is `awaiting_input`. */
export function mapStatus(
  raw: DesktopPaneStatus | undefined,
  awaiting: boolean,
): PaneStatus {
  if (raw === "run") return "running";
  if (awaiting) return "awaiting_input";
  return "idle";
}

/** The tab fields the roster needs — the identity subset of the store's `Tab` (#1176):
 *  `paneIds` (minted fleet/triage identity ids), `kind` (app-created tab), `id` (manual tab). */
export interface RosterTab {
  layout: string;
  id?: string;
  kind?: "build" | "triage";
  paneIds?: string[];
}

/**
 * Session kind for a pane identity id (#2497) — maps the self-describing id grammar
 * (#1266) into the wire's fixed `kind` vocabulary. The fleet director rides as `worker`
 * (it's a fleet session; the wire vocabulary has no separate director slot); manual and
 * legacy positional console panes are `console`; the dedicated planner pane
 * (`planning_<key>`) is `planner`.
 */
export function paneKindFor(id: string): PaneKind {
  if (isPlanningPaneId(id)) return "planner";
  const parsed = parsePaneIdentity(id);
  switch (parsed?.kind) {
    case "worker":
    case "director":
      return "worker";
    case "triage":
      return "triage";
    default:
      return "console";
  }
}

export interface PanePayloadInput {
  tabs: RosterTab[];
  paneNames: Record<number, Record<number, string>>;
  paneCwds: Record<string, string>;
  paneStatuses: Record<string, DesktopPaneStatus>;
  disabledPanes: Record<string, boolean>;
  /** Identity pane ids currently awaiting user input (from the focus queue). */
  awaiting: ReadonlySet<string>;
  /** ISO timestamp stamped onto every session (injected for deterministic tests). */
  nowIso: string;
  /** Ad-hoc panes outside the Console tab grid (the planner's `planning_<key>` pane, the
   *  designer session, …), so they mirror over the relay too (#801/#2497). A disabled
   *  extra pane is omitted. An extra pane without an explicit `kind` gets one derived
   *  from its id grammar. */
  extraPanes?: PaneDescriptor[];
}

/** Pure transform: store pane state → the `{ panes, sessions }` the tunnel pushes down.
 *  Panes are keyed by their IDENTITY id (`paneIdFor`, #1176/#2497) — the same id the PTY,
 *  status, and cwd are keyed by — so mobile's `pane_input`/`pane_output` target real PTY
 *  ids for manual (`man:…`) and fleet (`<key>:<stream>`) panes, not just legacy positional
 *  tabs. Disabled panes (PTY killed) are omitted entirely. */
export function buildPanePayload(
  input: PanePayloadInput,
): { panes: PaneDescriptor[]; sessions: SessionMeta[] } {
  const panes: PaneDescriptor[] = [];
  const sessions: SessionMeta[] = [];

  input.tabs.forEach((tab, tabIdx) => {
    const count = paneCountForLayout(tab.layout);
    for (let paneIdx = 0; paneIdx < count; paneIdx++) {
      const id = paneIdFor(tab, tabIdx, paneIdx);
      if (input.disabledPanes[id]) continue;
      const name = input.paneNames[tabIdx]?.[paneIdx] ?? `console-${tabIdx + 1}-${paneIdx + 1}`;
      const cwd = input.paneCwds[id] ?? "";
      const status = mapStatus(input.paneStatuses[id], input.awaiting.has(id));
      panes.push({ id, cwd, name, status, kind: paneKindFor(id) });
      sessions.push({
        paneId: id,
        status,
        currentTask: name,
        lastActivity: input.nowIso,
        // The real prompt text isn't tracked desktop-side; mobile shows the
        // awaiting-input state without it. (user_request only fires with a prompt.)
        prompt: null,
      });
    }
  });

  for (const p of input.extraPanes ?? []) {
    if (input.disabledPanes[p.id]) continue;
    panes.push({ ...p, kind: p.kind ?? paneKindFor(p.id) });
    sessions.push({
      paneId: p.id,
      status: p.status,
      currentTask: p.name,
      lastActivity: input.nowIso,
      prompt: null,
    });
  }

  return { panes, sessions };
}

// Turn-accounting hooks (#3455) — the un-gated, pure-observability Claude Code hooks EVERY
// claude-launching session must register, kept in ONE place.
//
// WHY A SHARED CONSTANT. This exact set has now silently fallen out of a launch path TWICE:
//   · #3452 — the generic fleet/console path (`sessionLaunch.ts`) never registered `bsc-tokens`, so
//     tokens.log went dead for ~3 weeks and the whole cost subsystem read $0.
//   · #3455 — the bespoke planner launch passed `hooks: null`, so NO hook fired for the planner and
//     its (often large) planning cost was invisible.
// Both are the same failure mode: a session that logs nothing because the registration drifted out of
// one code path. A single exported constant that every launch path spreads makes that drift structural
// rather than silent — you cannot forget the list if there is only one list.
//
// SCOPE — observability only. These two hooks have NO behavioral effect (they only append a log line):
//   · bsc-activity (#1184) — authoritative turn boundaries (`run` on prompt, `idle` on Stop), so the
//     status dot doesn't false-idle a thinking session.
//   · bsc-tokens (#416) — `pane → session → transcript_path` to tokens.log at every turn end; the ONLY
//     per-session token source (Claude Code hooks don't expose usage), read by `bsc logs cost`, the
//     desktop cost UI, and `bsc metrics` (#3449).
// The GATING hooks (bsc-confine / bsc-deny / bsc-audit / bsc-scope / bsc-taint / bsc-defer) are NOT
// here — they change behavior and their per-path inclusion is a policy decision (the planner, plan-only
// in allow-list posture, deliberately omits them). This constant is the accounting floor, not the
// permission floor.

/** One Claude Code hook registration — `{event, matcher, command}`, the shape `ensure_session_settings`
 *  writes into `.claude/settings.json`. `matcher: ""` means "every tool / no matcher". */
export interface SessionHook {
  event: string;
  matcher: string;
  command: string;
}

/**
 * The turn-accounting hooks every claude session registers (see the module header). Spread into each
 * launch path's hook list — the generic `sessionHooks` (`sessionLaunch.ts`) AND the planner's two
 * `ensure_session_settings` calls (`usePlannerTerminal` / `usePlanMcpManagement`).
 *
 * A fresh array per read is not needed (the value is never mutated), but keep it readonly-in-spirit:
 * callers spread it, never push to it.
 */
export const TURN_ACCOUNTING_HOOKS: SessionHook[] = [
  { event: "UserPromptSubmit", matcher: "", command: "bsc-activity run" },
  // #4005 — Claude Code fires `Notification` when it needs the USER: most importantly "Claude needs
  // your permission to use <tool>", which under the default allow-list posture (#2050) is any command
  // outside `base.json`. That session is STOPPED, and until now nothing in the app could tell it apart
  // from one that was merely quiet — so the user had no way to know WHICH pane was asking.
  //
  // `Notification` also fires after a long input idle. That is likewise "needs you", so it is a
  // feature rather than a false positive. It is cleared by the ordinary turn boundaries below: the
  // next UserPromptSubmit records `run`, a Stop records `idle`. Without that a pane would stay
  // flagged forever after a single prompt.
  { event: "Notification", matcher: "", command: "bsc-activity attn" },
  { event: "Stop", matcher: "", command: "bsc-activity idle" },
  { event: "SubagentStop", matcher: "", command: "bsc-activity idle" },
  { event: "Stop", matcher: "", command: "bsc-tokens" },
  { event: "SubagentStop", matcher: "", command: "bsc-tokens" },
];

// type.ts — the shared vocabulary the Text primitive is built on (#2057).
//
// One type scale, one semantic tone mapping. The named `TextSize` rungs mirror the `--fs-*` CSS
// tokens in tokens.css (xxs=9 … xl=18) so the primitive and the stylesheet speak the same scale —
// chosen from the real fontSize distribution (11/10/12/14/18 dominate). But a raw pixel number is
// always legal too (the off-scale half-sizes 9.5/10.5/11.5/13 stay `size={10.5}`), which keeps
// mechanical `<span style={{ fontSize }}>` → primitive conversions lossless.

/** A font size: a named scale rung, or a raw pixel number for the off-scale cases. */
export type TextSize = number | "xxs" | "xs" | "sm" | "md" | "lg" | "xl";

/** A semantic tone: maps to a foreground color token. Omit to inherit (no color forced). */
export type Tone = "dim" | "muted" | "accent" | "danger" | "success";

const SCALE: Record<Exclude<TextSize, number>, number> = { xxs: 9, xs: 10, sm: 11, md: 12, lg: 14, xl: 18 };

const TONE: Record<Tone, string> = {
  dim: "var(--fg-dim)",
  muted: "var(--fg-muted)",
  accent: "var(--accent)",
  danger: "var(--danger)",
  success: "var(--success)",
};

/** Resolve a `TextSize` to a pixel number (named rung → scale, number → itself). */
export function fontSize(v: TextSize | undefined): number | undefined {
  if (v == null) return undefined;
  return typeof v === "number" ? v : SCALE[v];
}

/** Resolve a semantic `Tone` to its color token (undefined → inherit, no color set). */
export function toneColor(v: Tone | undefined): string | undefined {
  return v == null ? undefined : TONE[v];
}

import type { FirstRunInstall } from "@/app/console/lib/providers/providers/claudeInstall";
import type { LlmConfig } from "@/shared/lib/core/llmConfig";

export interface ProviderLaunchConfig {
  /** Optional model name, used by providers that accept a model arg (e.g. Ollama). */
  model?: string;
  /** Resolved LLM config (provider + model + key + base URL). Providers that map it to CLI flags /
   *  env (e.g. Aider's `--model` + key env) read it; others ignore it. (#1172) */
  llm?: LlmConfig;
  /** The composed startup prompt / kickoff to deliver to the CLI at launch (e.g. Aider's
   *  `--message`). Providers whose backend harness bakes the prompt (Claude / bsc-agent) don't use
   *  this — they receive it via `pty_create`'s `startupPrompt`. (#1172) */
  startupPrompt?: string;
  /** Files to load read-only at launch (e.g. Aider's `--read` for a worker's `CLAUDE.local.md`,
   *  since Aider does no ancestor-`CLAUDE.md` walk). (#1172) */
  readFiles?: string[];
}

/**
 * A console provider defines how to launch an AI CLI inside a PTY pane.
 * Each provider is registered once in the global registry and selected per-pane.
 */
export interface ConsoleProvider {
  id: string;
  displayName: string;
  /** Build the shell command string to launch this provider. */
  buildLaunchCmd(config?: ProviderLaunchConfig): string;
  /**
   * Shell command used to check whether the binary is available, e.g. `which gemini`.
   * When set and the probe exits non-zero, the pane can surface a missing-binary warning.
   */
  prereqProbe?: string;
  /**
   * True only for the Claude provider. Controls whether session setup paths specific
   * to Claude (ensure_session_settings, github_readiness, gateClaudeLaunch, startup-prompt
   * baking) are engaged. Absent/false → bare shell launch without Claude-specific wiring.
   */
  isClaude?: boolean;
  /**
   * For a proprietary CLI we install-on-first-run rather than bundle (#1277 — Claude Code): the
   * consented `npm i -g` descriptor a first-run flow uses when `prereqProbe` reports the CLI absent.
   * Absent for bundled/self-contained providers (e.g. `bsc-agent`).
   */
  firstRunInstall?: FirstRunInstall;
  /**
   * Human-readable caveats surfaced in the pane menu when this provider is selected (#1172) — e.g.
   * Aider has no permission gate, no MCP, and limited status/cost telemetry. The app's role gate /
   * MCP assignment don't apply to such a provider, so the picker FLAGS it rather than silently
   * degrading. Absent ⇒ a full-parity provider (Claude / bsc-agent) with nothing to warn about.
   */
  limitations?: string[];
}

// UI-activity live-focus (#2525) — the Design Studio's read side of the designer session's activity
// stream. When a designer session mutates the kit store (`bsc ui set/remove` — component / kit / theme),
// the Rust `emit_ui_activity` appends a `ui-touch` line to `ui-activity.log`; this tails that stream
// via the `logs_tail` bridge (the same shape `useCoordLog` uses for coord.log), parses it, and drives
// the observed touches into the store, which live-focuses the newest node, follows its kit, and
// re-hydrates the touched collections so the edits appear without a relaunch.
//
// It reads EVERY touch in the window, not only the newest (#live-focus-is-kit-filtered). The old
// `latestUiTouch`-only path could not represent concurrent work: N designer sessions collapsed to
// last-writer-wins, and two touches inside one poll window meant one was never displayed at all.
//
// DS-specific, so it lives in the components feature's lib (not shared/) — modeled on
// `shared/lib/fleet/coordinationLog.ts` `parseCoordLine` + `shared/lib/fleet/useCoordLog.ts`.
import { useRef } from "react";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { usePoll } from "@/shared/hooks/usePoll";
import { useAppStore } from "@/store";
import { AI_RING_MAX } from "@/features/designs/store";

/** One parsed designer activity line: which collection + record the AI just wrote (`ui-touch`) or is
 *  inspecting (`ui-focus`, #3545), and when. */
export interface UiTouch {
  /** `"touch"` = a WRITE (`bsc ui set/remove`) → focus + re-hydrate; `"focus"` = a READ
   *  (`bsc ui get`/`preview-props`, #3545) → focus only, no re-hydrate. */
  kind: "touch" | "focus";
  /** The touched store collection — `"component"` · `"kit"` · `"theme"` (drives which hydrate re-runs). */
  collection: string;
  /** The record id written/removed/read — the node the Design Studio focuses. */
  id: string;
  /** The kit the record belongs to — the line's OPTIONAL 6th column. Absent on a legacy 5-column line
   *  (and on collections that have no kit), in which case the consumer resolves the kit from the store.
   *  It rides the line at all because the store lookup MISSES exactly the newest work: a record written
   *  moments ago may not be hydrated yet, and that is the touch most worth following. */
  kitId?: string;
  /** Epoch-ms of the event (0 if the timestamp is unparseable). */
  at: number;
  /** The emitting pane (`$BSC_AUDIT_PANE`, or `?`). */
  pane: string;
}

/**
 * Parse one TSV `ui-activity.log` line into a {@link UiTouch}, or `null` if unrecognized.
 * Columns: `ts \t pane \t <ui-touch|ui-focus> \t <collection> \t <id> [\t <kitId>]` (the
 * `emit_ui_activity` / `emit_ui_focus` shape).
 *
 * The 6th column is OPTIONAL and the length check stays `>= 5`, so every line already on disk keeps
 * parsing — an existing `ui-activity.log` is not orphaned by the emitter gaining a column.
 */
export function parseUiActivityLine(line: string): UiTouch | null {
  const cols = line.replace(/\r?\n$/, "").split("\t");
  if (cols.length < 5) return null;
  const [ts, pane, kind, collection, id, kitId] = cols;
  const evKind = kind === "ui-touch" ? "touch" : kind === "ui-focus" ? "focus" : null;
  if (!evKind || !id) return null;
  const parsed = Date.parse(ts);
  const at = Number.isFinite(parsed) ? parsed : 0;
  return { kind: evKind, collection, id, at, pane, ...(kitId ? { kitId } : {}) };
}

/** Every parseable touch in a chronological (oldest-first) line list, in the same order. Junk lines are
 *  skipped rather than failing the batch — the log is append-only from several processes. */
export function parseUiTouches(lines: string[]): UiTouch[] {
  const out: UiTouch[] = [];
  for (const line of lines) {
    const touch = parseUiActivityLine(line);
    if (touch) out.push(touch);
  }
  return out;
}

/** The most-recent parseable touch in a chronological (oldest-first) line list, or `null`. */
export function latestUiTouch(lines: string[]): UiTouch | null {
  const all = parseUiTouches(lines);
  return all.length ? all[all.length - 1] : null;
}

/** A stable identity for an event, so a poll only re-fires the store on a genuinely NEW one. */
export const touchKey = (t: UiTouch) => `${t.at}:${t.kind}:${t.collection}:${t.id}`;

/**
 * The touches that arrived AFTER `sinceKey` — the poll's delta.
 *
 * Scans from the END because the marker is normally the last entry (a quiet tick sees nothing new).
 * When the marker is NOT found the window has rolled past it — more happened than the tail can show —
 * and everything visible is returned rather than nothing: under-reporting a burst is the failure this
 * function exists to prevent.
 */
export function touchesSince(all: UiTouch[], sinceKey: string): UiTouch[] {
  if (!sinceKey) return all;
  for (let i = all.length - 1; i >= 0; i--) {
    if (touchKey(all[i]) === sinceKey) return all.slice(i + 1);
  }
  return all;
}

/**
 * Poll the designer activity stream while `active`, folding each NEW touch into the store's ring — the
 * Design Studio live-focus (#2525). Gated: when `active` is false (the Studio is not the visible page)
 * the tick early-returns, so there's no bridge cost. Reads oldest-first, like the coord log.
 *
 * The FIRST tick primes the ring from history without re-hydrating: the tail is up to 50 lines of past
 * work, the boot hydrate has already loaded all of it, and paying a 590-record reload for it on every
 * visit to the Studio would be pure waste. Those entries still populate the strip — seeing recent
 * activity the moment you open the page is the point — they just don't trigger a reload, and the ring's
 * own staleness gate keeps them from steering the view.
 */
export function useUiActivity(active: boolean, ms = 1500): void {
  const pushAiTouches = useAppStore((s) => s.pushAiTouches);
  const lastRef = useRef<string>("");
  const primedRef = useRef(false);
  usePoll(
    async (isCancelled) => {
      if (!active) return;
      const lines = await logsTail("ui", 50, true, null);
      if (isCancelled() || !lines) return;
      const all = parseUiTouches(lines);
      if (!all.length) return;
      const fresh = touchesSince(all, lastRef.current);
      if (!fresh.length) return;
      lastRef.current = touchKey(all[all.length - 1]);
      const priming = !primedRef.current;
      primedRef.current = true;
      // Priming shows the tail END — the ring keeps the newest anyway, and handing it 50 entries to
      // discard 42 only makes the debug view harder to read.
      pushAiTouches(priming ? fresh.slice(-AI_RING_MAX) : fresh, { hydrate: !priming });
    },
    ms,
    [active],
  );
}

// UI-kit pins (#2465) — the blueprint↔kit-store link. A blueprint REFERENCES a UI kit as a
// lockfile entry (`Blueprint.uiKit = { id, version, hash, source? }`, exact pins only) against the
// GLOBAL versioned kit store (`~/.base-studio-code/kits/<id>/<version>/`, the Rust `bsc ui release`
// CLI), so one copy serves every blueprint that pins it and the same kit is never downloaded twice.
//
//  · PACKAGED_UI_KIT_PIN — the packaged `bsc/react-ui` kit's pin (id/version/hash read from the
//    generated `@data/ui/react-ui-kit.meta.json` sidecar). Default-pinned onto every NEW blueprint
//    (`addBlueprint`); it resolves against the store's embedded fallback, so it needs no fetch.
//  · resolveUiKitPin — the resolve flow on blueprint open/import: local store lookup → fetch the
//    typed gist ONLY when `id@version` is missing → verify sha256 BEFORE the store write (a
//    mismatch is rejected loudly and nothing is stored). Never re-fetches an existing id@version.
//  · importKitByGistUrl — the authoring picker's import path: fetch a `component-kit` gist, derive
//    its store identity, add it to the store (trust-on-first-import; the returned pin then locks
//    the exact bytes for everyone downstream).
//
// Pure of React; store access goes through the generic `bsc` bridge (#2114), the same surface a
// live session reaches with `bsc ui release …` from its own shell.

import packagedKitMeta from "@data/ui/react-ui-kit.meta.json";
import { bsc, bscJson } from "@/shared/lib/core/bsc";
import { sha256Hex } from "@/shared/lib/core/sha256";
import { log } from "@/shared/lib/core/log";
import { fetchGistManifestText } from "@/features/planner/lib/gist/gist";
import { parseManifest } from "@/features/planner/lib/gist/manifest";
import type { Blueprint, BlueprintUiKit } from "@/features/planner/stages/blueprints";

/** A kit-store entry's manifest, as `bsc ui release list|get|add` emit it. */
export interface KitStoreManifest {
  id: string;
  version: string;
  sha256: string;
  kind: "component-kit" | "design-files";
  /** The typed-gist URL it was fetched from, or `"packaged"` for the embedded default. */
  source?: string;
}

/** The packaged default kit's pin — a FRESH object per call (pins live inside blueprint JSON, so
 *  handing out one shared instance would alias state across blueprints). */
export function packagedUiKitPin(): BlueprintUiKit {
  return { id: packagedKitMeta.id, version: packagedKitMeta.version, hash: packagedKitMeta.sha256 };
}

/** `id@version` — the store ref a pin resolves as. */
export function kitRef(pin: Pick<BlueprintUiKit, "id" | "version">): string {
  return `${pin.id}@${pin.version}`;
}

/** Every kit in the local store (incl. the packaged default). Empty when the bridge is absent. */
export async function listStoreKits(): Promise<KitStoreManifest[]> {
  return bscJson<KitStoreManifest[]>(null, ["ui", "release", "list"], []);
}

/** One store entry's manifest, or null when `id@version` isn't in the store. */
export async function getStoreKit(pin: Pick<BlueprintUiKit, "id" | "version">): Promise<KitStoreManifest | null> {
  return bscJson<KitStoreManifest | null>(null, ["ui", "release", "get", kitRef(pin)], null);
}

export type UiKitResolution =
  /** `cached` — the id@version was already in the store (zero downloads). */
  | { ok: true; cached: boolean }
  | { ok: false; error: string };

/**
 * Resolve a blueprint's UI-kit pin against the local store (#2465): store hit ⇒ done (an existing
 * `id@version` is NEVER re-fetched — immutable versions make the local copy valid forever); miss ⇒
 * fetch the typed gist at `pin.source`, verify its sha256 against `pin.hash` BEFORE anything is
 * written, and only then add it to the store. A hash mismatch (or a missing source) is a loud
 * `{ ok: false }` and the store is untouched. The `--sha256` handed to `bsc ui release add` makes the
 * Rust store re-verify, so the no-write-on-mismatch guarantee holds even if this caller is wrong.
 */
export async function resolveUiKitPin(pin: BlueprintUiKit, token = ""): Promise<UiKitResolution> {
  if (await getStoreKit(pin)) return { ok: true, cached: true };
  if (!pin.source) {
    return { ok: false, error: `UI kit ${kitRef(pin)} is not in the local kit store and the pin has no source to fetch it from` };
  }
  const raw = await fetchGistManifestText(pin.source, token);
  if (!raw.ok) return raw;
  const hash = await sha256Hex(raw.text);
  if (hash !== pin.hash.toLowerCase()) {
    return {
      ok: false,
      error: `UI kit ${kitRef(pin)} REJECTED: fetched content hashes to ${hash} but the pin expects ${pin.hash} — refusing to store it`,
    };
  }
  try {
    await bsc(
      null,
      ["ui", "release", "add", pin.id, pin.version, "--kind", "component-kit", "--sha256", pin.hash, "--source", pin.source],
      raw.text,
    );
  } catch (e) {
    return { ok: false, error: `UI kit ${kitRef(pin)} could not be stored: ${String(e)}` };
  }
  return { ok: true, cached: false };
}

/**
 * Fire-and-forget resolve for a blueprint being OPENED or IMPORTED — the store-slice wire point.
 * No pin ⇒ no-op (blueprints without one are unaffected); a failure is logged loudly (the
 * authoring picker additionally surfaces it inline).
 */
export function resolveBlueprintUiKit(bp: Pick<Blueprint, "name" | "uiKit"> | undefined, token = ""): void {
  const pin = bp?.uiKit;
  if (!pin) return;
  void resolveUiKitPin(pin, token).then(
    (res) => {
      if (!res.ok) log.error(`blueprint "${bp?.name ?? "?"}": ${res.error}`);
    },
    // Fire-and-forget: an unexpected throw must land in the log, never as an unhandled rejection (#2515).
    (e) => log.error(`blueprint "${bp?.name ?? "?"}": UI-kit resolve failed: ${String(e)}`),
  );
}

/** The store-identity block a published kit gist carries in its payload (`payload.store`). */
export interface KitStoreIdentity {
  id: string;
  version: string;
}

const STORE_ID_RE = /^[a-z0-9][a-z0-9-]*\/[a-z0-9][a-z0-9-]*$/;
const slug = (s: string): string =>
  s.toLowerCase().replace(/[^a-z0-9-]+/g, "-").replace(/^-+|-+$/g, "") || "kit";

/** Derive a fetched kit gist's store identity: the stamped `payload.store` when present + valid
 *  (what `publishKitToGist` writes since #2465), else `<gist-owner>/<manifest-id>` slugs with the
 *  envelope's own version — so pre-#2465 kit gists stay importable. Exported for tests. */
export function deriveKitIdentity(
  manifest: { id?: unknown; version?: unknown; payload?: unknown },
  owner?: string,
): KitStoreIdentity {
  const store = (manifest.payload as { store?: { id?: unknown; version?: unknown } } | undefined)?.store;
  const stamped = typeof store?.id === "string" ? store.id : "";
  const id = STORE_ID_RE.test(stamped)
    ? stamped
    : `${slug(owner ?? "gist")}/${slug(typeof manifest.id === "string" ? manifest.id : "kit")}`;
  const version =
    (typeof store?.version === "string" && store.version) ||
    (typeof manifest.version === "string" && manifest.version) ||
    "1.0.0";
  return { id, version };
}

export type KitImportResult =
  | { ok: true; pin: BlueprintUiKit }
  | { ok: false; error: string };

/**
 * Import a kit by gist URL into the global store, returning the pin to record on the blueprint
 * (#2465, the authoring picker's import path). Fetch → validate it IS a `component-kit` manifest →
 * derive the store identity → add to the store (the store enforces id@version immutability — a
 * conflict with different content is surfaced, not overwritten) → pin `{ id, version, hash, source }`.
 */
export async function importKitByGistUrl(url: string, token = ""): Promise<KitImportResult> {
  const raw = await fetchGistManifestText(url, token);
  if (!raw.ok) return raw;
  const parsed = parseManifest(raw.text);
  if (!parsed.ok) return parsed;
  if (parsed.manifest.kind !== "component-kit") {
    return { ok: false, error: `that gist holds a '${parsed.manifest.kind}', not a component kit` };
  }
  const { id, version } = deriveKitIdentity(parsed.manifest, raw.owner);
  const hash = await sha256Hex(raw.text);
  try {
    await bsc(null, ["ui", "release", "add", id, version, "--kind", "component-kit", "--source", url], raw.text);
  } catch (e) {
    return { ok: false, error: `could not add ${id}@${version} to the kit store: ${String(e)}` };
  }
  return { ok: true, pin: { id, version, hash, source: url } };
}

// Pure, non-mutating immutable-update helpers for the Zustand slices (#1704).
//
// The slices repeat the same immutable idioms hundreds of times — `{ ...map, [key]: val }` to set a
// record entry, `const n = { ...map }; delete n[key]` to drop one, and `arr.map((x, i) => i === idx
// ? { ...x, ...patch } : x)` to patch one array item. These helpers name those idioms so the call
// sites read by intent. Each returns a NEW value and never mutates its argument, so they're safe to
// use directly inside a Zustand `set((s) => …)` updater.

/** Return a NEW record with `key` set to `value`; the input map is not mutated. */
export function setMapEntry<K extends PropertyKey, V>(
  map: Record<K, V>,
  key: K,
  value: V,
): Record<K, V> {
  return { ...map, [key]: value } as Record<K, V>;
}

/** Return a NEW record with `key` removed; the input map is not mutated. A missing key is a no-op. */
export function deleteMapEntry<K extends PropertyKey, V>(
  map: Record<K, V>,
  key: K,
): Record<K, V> {
  const next: Record<K, V> = { ...map };
  delete (next as Partial<Record<K, V>>)[key];
  return next;
}

/** Return a NEW record with every key in `keys` removed; the input map is not mutated. Missing keys
 *  are no-ops. */
export function deleteMapEntries<K extends PropertyKey, V>(
  map: Record<K, V>,
  keys: Iterable<K>,
): Record<K, V> {
  const next: Record<K, V> = { ...map };
  for (const key of keys) delete (next as Partial<Record<K, V>>)[key];
  return next;
}

/** Return a NEW array with the item at `index` shallow-merged with `patch`; the input array is not
 *  mutated. An out-of-range index leaves the array unchanged (a fresh copy with identical items). */
export function updateArrayItem<T extends object>(
  arr: T[],
  index: number,
  patch: Partial<T>,
): T[] {
  return arr.map((item, i) => (i === index ? { ...item, ...patch } : item));
}

// Shared active-project GitHub wiring (#1754) — the board screens (Issues / Insights /
// ProjectBoard / Roadmap) all assembled the same `ActiveProjectInfo` from the store and the
// node-query screens all hand-rolled the identical Projects-v2 `useGithubQuery` over the active
// project's node id, plus the same error banner. Extracted here so the four screens share one
// source.
import type { CSSProperties } from "react";
import { useAppStore } from "@/store";
import { rateLimitNote } from "@/shared/lib/github/github";
import { fetchBoardWithProbe } from "@/shared/lib/github/githubProbe";
import { useGithubQuery, type GithubQuery } from "@/shared/lib/github/useGithubQuery";
import { InlineError } from "@/shared/ui/feedback/InlineError";
import { Text } from "@/shared/ui/typography/Text";
import type { ActiveProjectInfo } from "@/features/planner/list/ProjectsHeader";

/** The active project's identity, assembled from the store — the `project` prop every board
 *  screen passes to <ProjectsHeader>. */
export function useActiveProject(): ActiveProjectInfo {
  const id     = useAppStore((s) => s.activeProjectId);
  const name   = useAppStore((s) => s.activeProjectName);
  const repo   = useAppStore((s) => s.activeProjectRepo);
  const repos  = useAppStore((s) => s.activeProjectRepos);
  const number = useAppStore((s) => s.activeProjectNumber);
  return { id: id ?? "", number, name, repo, repos, description: "" };
}

/**
 * Run a Projects-v2 GraphQL `query` against the active project's node id — the identical fetch the
 * Issues / Insights / ProjectBoard screens hand-rolled — and return the active project alongside the
 * `{ data, loading, error }` state. Skips while there's no active project (the `!!activeProjectId`
 * gate). Roadmap fetches milestones by repo instead, so it uses `useActiveProject` directly.
 */
export function useActiveProjectGithub<T = { node: Record<string, unknown> }>(
  query: string,
): { project: ActiveProjectInfo } & GithubQuery<T> {
  const project = useActiveProject();
  const activeProjectId = useAppStore((s) => s.activeProjectId);
  // fetchBoardWithProbe keeps the board reads on the backend TTL cache (#2447 — switching between
  // Board / Issues / Insights within the window re-serves the cached result) and gates the heavy
  // `items(first:100)` re-POST past the window behind the board's light updatedAt probe (#2448):
  // an unchanged board keeps serving the cached copy, a moved one fetches fresh.
  const state = useGithubQuery<T>(
    () => fetchBoardWithProbe<T>(query, activeProjectId!),
    [activeProjectId],
    !!activeProjectId,
  );
  return { project, ...state };
}

/** The shared banner the board screens render for a failed query. Renders nothing when there is no
 *  error; a rate-limited query (#2448) renders as a quiet dim note (the screens keep showing their
 *  cached data) instead of the red danger callout. `style` lets a screen keep its existing margin. */
export function QueryBanner({ error, style }: { error: string | null; style?: CSSProperties }) {
  if (!error) return null;
  const note = rateLimitNote(error);
  if (note) {
    return (
      <Text as="div" mono size={11} tone="dim" style={{ padding: "12px 16px", ...style }}>
        {note}
      </Text>
    );
  }
  return (
    <InlineError pad={[12, 16]} radius={6} style={style}>{error}</InlineError>
  );
}

// The ACTIVE sound-kit selection for the Design Studio (#3412) — the React edge that turns the current
// project's blueprint `soundKit` pin into the {@link SoundKitSelection} the library resolvers run under.
//
// Which blueprint's pin? The one the work is under: the ACTIVE PROJECT's blueprint (`projectBlueprintId`)
// when a project is open, else the blueprint being AUTHORED (`activeBlueprintId`) — so the Design Studio
// previews a kit the same way whether you reached it from a project or from the blueprint library.
//
// Resolution is async (a store read across the `bsc` bridge), so the selection starts at the packaged
// default and settles once the artifact lands. That start state is deliberate: it matches the pre-#3412
// behavior for the one frame before the pin resolves, rather than blanking every sound import.
import { useEffect, useState } from "react";
import { useAppStore } from "@/store";
import { log } from "@/shared/lib/core/log";
import { DEFAULT_SOUND_KIT, type SoundKitSelection } from "@/features/designs/lib/libraryModules";
import { selectSoundKit } from "@/features/designs/lib/soundKitSelection";

/**
 * The active blueprint's resolved sound-kit selection (#3412). Re-resolves when the pinned ref changes;
 * an unresolvable pin is logged LOUDLY here (once per ref) and returned as the `unresolved` arm, which
 * makes every `@bsc/sounds/…` fail to resolve rather than quietly playing the starter kit.
 */
export function useActiveSoundKit(): SoundKitSelection {
  const activeProjectId = useAppStore((s) => s.activeProjectId);
  const projectBlueprintId = useAppStore((s) => s.projectBlueprintId);
  const activeBlueprintId = useAppStore((s) => s.activeBlueprintId);
  const blueprints = useAppStore((s) => s.blueprints);

  const blueprintId = (activeProjectId ? projectBlueprintId[activeProjectId] : "") || activeBlueprintId;
  const pin = blueprints.find((b) => b.id === blueprintId)?.soundKit;
  // Key on the REF (not the object) so an unrelated blueprint edit doesn't re-read the store.
  const ref = pin ? `${pin.id}@${pin.version}` : "";

  // The resolved selection is stored WITH the ref it was resolved for, so no state has to be reset when the
  // pin changes or is removed — the read below simply stops matching. That keeps the effect free of a
  // synchronous setState (which would cascade a render on every unpinned mount).
  const [resolved, setResolved] = useState<{ ref: string; sel: SoundKitSelection } | null>(null);

  useEffect(() => {
    if (!pin) return;
    let cancelled = false;
    void selectSoundKit(pin).then((next) => {
      if (cancelled) return;
      if (next.kind === "unresolved") log.error(`Design Studio sound kit: ${next.error}`);
      setResolved({ ref, sel: next });
    });
    return () => { cancelled = true; };
    // `pin` is derived from `ref` — keyed on the ref so a re-read happens only when the PIN itself changes,
    // not on every unrelated blueprint edit.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ref]);

  // No pin ⇒ the packaged default. A pin whose resolution hasn't landed yet ⇒ also the default, for the one
  // frame before it settles (matching pre-#3412 behavior rather than blanking every sound import).
  return ref && resolved?.ref === ref ? resolved.sel : DEFAULT_SOUND_KIT;
}

import { useEffect, useRef } from "react";
import { invoke } from "@tauri-apps/api/core";
import { addDbProject, listDbProjects, setDbTriaged } from "@/features/planner";
import { markBoot, logStartupTrace } from "@/shared/lib/core/startupTrace";
import { startPerfMonitor, recordStoreWrite } from "@/shared/lib/core/perf";
import { log } from "@/shared/lib/core/log";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { worktreeChecks, reconcileMissingWorktrees } from "@/shared/lib/fleet/worktreeReconcile";
import { useAppStore } from "@/store";
import { accentVars } from "@/features/settings";
import { applyThemeToRoot } from "@/shared/ui/kit/theme";
import { applyContributionsToRoot } from "@/shared/ui/kit";

/** Delay (ms after hydration) before the perf monitor + store-write diagnostics start, so they don't
 *  load the cold-start window (#1033). Metrics during boot have no diagnostic value. */
const METRICS_GRACE_MS = 5000;

/**
 * The app-shell boot + lifecycle effects, pulled out of App so the shell reads as composition:
 * the accent CSS vars, the startup-timing trace, the one-shot base-dir / crash-flag / skills
 * hydration, and the deferred perf monitor + store-write diagnostics.
 */
export function useAppBoot() {
  const accent = useAppStore((s) => s.accent);
  const kitTheme = useAppStore((s) => s.kitTheme);
  const kitThemes = useAppStore((s) => s.kitThemes);
  const designContributions = useAppStore((s) => s.designContributions);
  const hasHydrated = useAppStore((s) => s.hasHydrated);
  const setBscBaseDir = useAppStore((s) => s.setBscBaseDir);
  // Guards the one-time draft→DB migration (#2995) so it fires exactly once per app session.
  const draftsMigratedToDb = useRef(false);
  const triagedSyncedToDb = useRef(false);
  const worktreeReconciled = useRef(false);

  // Apply the chosen accent to the design-token CSS vars at the document root,
  // live on change and after persisted state rehydrates. Inline vars on :root
  // override the stylesheet defaults; the default accent is a no-op restore.
  useEffect(() => {
    const { accent: a, accentDim } = accentVars(accent);
    const root = document.documentElement;
    root.style.setProperty("--accent", a);
    root.style.setProperty("--accent-dim", accentDim);
  }, [accent]);

  // Apply the chosen kit theme (#1852 Phase 3) to the semantic component tokens at the document root,
  // live on change and after rehydrate. A theme sets --card-*/--btn-*/--field-*/--chip-* overrides;
  // switching clears the prior theme's set first, so `default` restores the stylesheet look.
  // `kitThemes` is read as a dep (#2488) so the vars re-apply after the theme STORE hydrates — the
  // chosen theme may be designer-edited (or designer-authored) and differ from the packaged fallback.
  useEffect(() => { void kitThemes; applyThemeToRoot(kitTheme); }, [kitTheme, kitThemes]);

  // Apply the persisted downloaded-blueprint design overlays (#2656/#2663), live on add/remove AND after
  // the store rehydrates. Keyed on `designContributions` (NOT the one-shot mount effect) because persist
  // hydration is async: a mount-time read sees the default [] and would never re-apply the restored
  // overlays. Mirrors applyThemeToRoot above (compose-don't-mutate — a managed :root <style>).
  useEffect(() => { applyContributionsToRoot(designContributions); }, [designContributions]);

  // Startup timing trace (#perf): mark the gate commit, then the first paint of the
  // real UI once the store rehydrates — logStartupTrace emits the breakdown once.
  useEffect(() => { markBoot("mounted"); }, []);
  useEffect(() => {
    if (!hasHydrated) return;
    markBoot("hydrated");
    requestAnimationFrame(() => { markBoot("painted"); logStartupTrace(); });
  }, [hasHydrated]);

  // One-time draft → projects-DB migration (#2995): after the store rehydrates, upsert every entry in
  // the fragile `localDraftProjects` cache into the durable projects DB (`bsc project db add` is an
  // idempotent upsert), so drafts that only ever lived in the cache become restart-durable. Gated on
  // `hasHydrated` because persist is async — a mount-time read would see the pre-hydration empty map —
  // and ref-guarded so it runs exactly once. Each write is fire-and-forget and degrades silently when
  // the bridge/binary is absent.
  useEffect(() => {
    if (!hasHydrated || draftsMigratedToDb.current) return;
    draftsMigratedToDb.current = true;
    const drafts = useAppStore.getState().localDraftProjects;
    for (const [key, d] of Object.entries(drafts)) {
      void addDbProject({ key, title: d.title, pitch: d.pitch, state: "drafted" });
    }
  }, [hasHydrated]);

  // TRIAGED markers ↔ projects.db (#4088). The marker gates the whole Glance network (#2541), and it
  // used to live ONLY in app-state.json — unreachable from `bsc`, lost on an app-state reset, and
  // diagnosable only by reading a raw zustand blob. projects.db is the source now; this reconciles.
  //
  // BOTH directions, once, in this order:
  //   ① push any marker the cache still holds that the DB has not got — the upgrade path, so a user
  //     who triaged projects before #4088 does not watch them vanish from Glance on first launch;
  //   ② union the DB's markers into the cache — the durable set wins for everything else, and a
  //     marker set on another machine or repaired via `bsc project triaged set` shows up here.
  //
  // Gated on `hasHydrated` (persist is async — a mount-time read sees an empty map) and ref-guarded so
  // it runs exactly once. Degrades silently: with no bridge the in-memory cache still gates the session.
  useEffect(() => {
    if (!hasHydrated || triagedSyncedToDb.current) return;
    triagedSyncedToDb.current = true;
    void (async () => {
      const cached = useAppStore.getState().triagedProjects;
      const rows = await listDbProjects();
      if (!rows) return; // bridge unreachable — keep the cache as-is
      const fromDb: Record<string, number> = {};
      for (const r of rows) {
        if (typeof r.triagedAt === "number") fromDb[r.key] = r.triagedAt;
      }
      for (const key of Object.keys(cached)) {
        if (!(key in fromDb)) void setDbTriaged(key); // ① upgrade the pre-#4088 markers forward
      }
      useAppStore.getState().hydrateTriaged(fromDb); // ② durable set into the cache
    })();
  }, [hasHydrated]);

  // Fleet worktree reconciliation (#3614): after hydrate, mark any persisted fleet worker whose worktree
  // was reclaimed by the boot-GC (merged+clean = work landed) as ENDED — so its `<project> · build` tab
  // renders a resting card instead of relaunching the worker into a deleted directory. That relaunch
  // spawned a burst of doomed PTYs into missing cwds, jamming the backend event loop on EVERY boot. Gated
  // on `hasHydrated` (persist is async), ref-guarded to run once. `dir_exists` defaults to `true` on any
  // bridge/command miss, so a probe failure can never wrongly end a live worker.
  useEffect(() => {
    if (!hasHydrated || worktreeReconciled.current) return;
    worktreeReconciled.current = true;
    const s = useAppStore.getState();
    const checks = worktreeChecks(s.fleetPaneStreams, s.endedPanes, s.disabledPanes, s.paneCwds);
    if (checks.length === 0) return;
    void reconcileMissingWorktrees(
      checks,
      (cwd) => safeInvoke<boolean>("dir_exists", { path: cwd }, true),
      (paneId) => !!useAppStore.getState().endedPanes[paneId],
      (paneId, info) => {
        log.info(`worktree-reconcile: ${paneId} worktree gone → marking ended (${info.summary})`);
        useAppStore.getState().markPaneEnded(paneId, info);
      },
      () => Date.now(),
    );
  }, [hasHydrated]);

  // Fetch the app-managed base directory once so the rest of the UI can
  // compute repo local paths deterministically without round-tripping Rust.
  useEffect(() => {
    invoke<string>("get_base_dir")
      .then(setBscBaseDir)
      .catch((e) => log.error(`get_base_dir failed: ${e}`));
    // Crash recovery (#1041): learn once whether the previous shutdown was unclean — gates the
    // restore banner + session auto-resume (a clean quit leaves sessions dormant).
    invoke<boolean>("was_unclean_shutdown")
      .then((v) => {
        useAppStore.getState().setUncleanShutdown(v);
        // #3961: the same signal, asked of the LOOP store. A loop in flight when the app died is never
        // reconciled — nothing closes it, so it stays `open` forever and a participant's `bsc loop
        // watch` blocks on a turn that will never come. Only an UNCLEAN shutdown implies that; after a
        // clean quit an open loop is legitimately dormant, so this is gated exactly like the session
        // restore. `--dry-run` only COUNTS them; nothing is written until the user acts on the banner.
        if (v) void useAppStore.getState().probeInterruptedLoops();
      })
      .catch(() => { /* command absent (e.g. tests) — leave false */ });
    // Skills library (#1338 ph2): hydrate from the global skills.db so the desktop UI, the planner,
    // and every live `bsc-skill` session share ONE library. Reconciles the code-owned packaged set
    // and seeds the db on first run; a no-op when the bridge is absent (keeps the seeded set).
    void useAppStore.getState().hydrateSkills();
    // Persona library (#2094): hydrate from the global persona store (`bsc persona`) so the desktop
    // Personas tab, live sessions, and the planner share ONE library. Reconciles the packaged
    // built-ins + seeds the store on first run; a no-op when the bridge is absent (keeps the seed).
    void useAppStore.getState().hydratePersonas();
    // Org library (#2193): hydrate the persona-relationship graph from the global org store (`bsc org`)
    // so the desktop Org tab, live sessions, and the planner share ONE library. Reconciles the packaged
    // built-ins + seeds the store on first run; a no-op when the bridge is absent (keeps the seed).
    void useAppStore.getState().hydrateOrgs();
    // Component library (#2269): hydrate the proven-component library from the global `bsc ui`
    // store so the planner's test_ui pane + (later) the Design Studio share ONE library. A no-op that
    // keeps the typed seed when the bridge is unreachable (which is every build until the store lands).
    void useAppStore.getState().hydrateComponents();
    // The ALGORITHM impls (resolver-reads-the-algorithms-store) — the set `resolveGraphSource` matches a
    // module-granularity `provides` against, so a logic module authored as a record resolves like a
    // component does. Same contract as the components hydrate: a no-op when the read is unavailable, so
    // a degraded environment resolves nothing rather than failing boot.
    void useAppStore.getState().hydrateAlgorithms();
    // Kit-usage consumer index (#2277): hydrate which projects use which kit from the global
    // `bsc ui usage` store — the edges a kit change fans out over. No-op keeping the cache when
    // the bridge is absent.
    void useAppStore.getState().hydrateKitUsage();
    // Kit themes (#2488): hydrate the designer-writable theme collection from the global `bsc ui
    // theme` store — the Settings picker, the Design Studio preview switcher, and every ThemeScope
    // resolve against it. No-op keeping the packaged registry when the bridge is absent.
    void useAppStore.getState().hydrateThemes();
    // Data-defined component variants (#2569): compile the designer-authored `bsc ui variants` store
    // into the managed `<style>` so an LLM-authored variant renders on boot (re-applied on ui-touch).
    void useAppStore.getState().hydrateVariants();
    // (Design contributions are applied by the `designContributions`-keyed effect above, #2663 — a
    // one-shot mount read here saw the pre-hydration default [] and never re-applied the restored set.)
    // Project relationships (#2253): hydrate the Glance L1 network edges from the global `bsc project
    // link` store so the desktop, live sessions, and a restart share ONE set. A no-op when the bridge
    // is absent (keeps the persisted cache).
    void useAppStore.getState().hydrateProjectLinks();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Defer the perf monitor + store-write diagnostics past the cold-start window (#1033). Both run
  // every 2s and add IPC + sampling load that's pure overhead while the app is still booting (and
  // useless before it's interactive) — start them a few seconds after hydration instead of at mount.
  useEffect(() => {
    if (!hasHydrated) return;
    let unsub: (() => void) | undefined;
    const id = setTimeout(() => {
      // Watch the main thread for jank (logs `[perf] main thread blocked …`).
      startPerfMonitor();
      // Count how often each store key changes, so a re-render loop reveals which key drives it.
      unsub = useAppStore.subscribe((state, prev) => {
        const s = state as unknown as Record<string, unknown>;
        const p = prev as unknown as Record<string, unknown>;
        for (const k in s) {
          if (s[k] !== p[k]) recordStoreWrite(k);
        }
      });
    }, METRICS_GRACE_MS);
    return () => { clearTimeout(id); unsub?.(); };
  }, [hasHydrated]);
}

import { useEffect } from "react";
import { useAppStore } from "@/store";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";

/**
 * Resolves the base-studio-code source tree this app was built from, ONCE per app run (#3509).
 *
 * A role declares its harvest roots symbolically (`app-repo`) because a role is machine-independent;
 * turning that into a real path is the launch's job, and `buildAgentEnv` is synchronous. So the path
 * is resolved here at boot and parked in the store, where any later launch can read it without an
 * await. Returns null on a shipped binary (no source tree) — a role whose only declared root cannot
 * be resolved simply gets no harvest roots, which fails CLOSED.
 */
export function useAppRepoRoot(): void {
  const appRepoRoot = useAppStore((s) => s.appRepoRoot);
  const setAppRepoRoot = useAppStore((s) => s.setAppRepoRoot);

  useEffect(() => {
    if (appRepoRoot !== null) return;
    let cancelled = false;
    void safeInvoke<string | null>("debug_repo_root", undefined, null, () => {}).then((root) => {
      if (!cancelled && root) setAppRepoRoot(root);
    });
    return () => {
      cancelled = true;
    };
  }, [appRepoRoot, setAppRepoRoot]);
}

// The CI watcher (#373): closes the open-PR loop. A worker opens a PR and stops; CI runs
// unattended on GitHub. This hook polls each worker PR's check-run status and, when it
// reaches a terminal state, tells the worker to CONTINUE (passed -> next issue/stop;
// failed -> fix + push) and nudges the director to merge on green. App-side because CI is an
// external event no one can push -- something has to watch it; doing it here means the worker
// stops (no idle tokens) and is resumed only when there is something to do. Mounted once in
// ConsoleWorkspace. Pure rollup/prompts live in ciStatus.ts; this is the Tauri/React actuator.
//
// INERT since #app-stops-pushing-prompts. Its body polled check runs and typed CI outcomes into the director / owning worker. Under local-first there are no PRs to watch, and the director holds no GitHub write, so the signal it pushed had no action behind it.
//
// The export SURVIVES deliberately: this module is registered in graphPlatform/appModules so graph
// RECORDS can import it, and removing the export breaks record compilation at runtime — the shape
// useFleetGate took for the same reason.

// silently mis-resolved an identity id (the `p` in e.g. "my**p**roject") to a garbage pane, so the director
// never received the green-PR MERGE nudge and merged nothing (#2604). Both helpers handle either shape.

/** A fleet pane's project GROUP — its stable-identity project key, or a positional pane's tab prefix. */
export function ciGroupKey(paneId: string): string {
  return paneId.includes(":") ? paneId.split(":")[0] : paneId.slice(0, paneId.indexOf("p") + 1);
}
/** The DIRECTOR pane id for a worker pane — `<projectKey>:director`, or p0 of a legacy positional tab. */
export function ciDirectorPaneFor(paneId: string): string {
  return paneId.includes(":") ? `${paneId.split(":")[0]}:director` : `${paneId.slice(0, paneId.indexOf("p"))}p0`;
}

/** Does nothing. See the note above. */
export function useCiWatcher(): void {
  // Intentionally empty: no poll, no evaluation, no injection.
}

