import { useEffect, type RefObject } from "react";

/**
 * Dismiss a popover/menu on an outside `mousedown`. Listens only while `active`, and calls `onClose`
 * when the press lands outside `ref` (and outside `ignoreRef`, if given — use it for the toggle
 * button so its own click handler owns the open/close instead of double-firing). mousedown (not
 * click) so the menu doesn't unmount before an inner item's click fires. (Callers' inline `onClose`
 * is auto-memoized by react-compiler, so the listener isn't re-subscribed every render.)
 */
export function useClickOutside<E extends HTMLElement, I extends HTMLElement = HTMLElement>(
  ref: RefObject<E | null>,
  onClose: () => void,
  active: boolean,
  ignoreRef?: RefObject<I | null>,
): void {
  useEffect(() => {
    if (!active) return;
    const onDown = (e: MouseEvent) => {
      const t = e.target as Node;
      if (ignoreRef?.current?.contains(t)) return;
      if (!ref.current?.contains(t)) onClose();
    };
    document.addEventListener("mousedown", onDown);
    return () => document.removeEventListener("mousedown", onDown);
  }, [active, ref, ignoreRef, onClose]);
}

// useComponentScan (#2838, #2908) — the Design Studio's on-visit preview-error scan. While the Studio page
// is mounted (`active`; it lazily mounts on FIRST visit via KeptMountedPage, never at app boot), it
// esbuild-builds each buildable component in the active kit AND runs each build-clean one in a hidden
// iframe (#2908) — throttled to a small concurrency so it never hangs the app — recording
// ok/build-error/runtime-error per component in the store. The graph badges the errors.
//
// The pure spine (which components to scan, the throttle pool, build→run→status derivation) lives in
// `componentScan.ts` and is unit-tested with a mocked bundle + run; this hook only wires it to the real
// esbuild-wasm `bundleComponent` + the DOM `probeComponentRuntime` (neither runs under jsdom) and the
// store, with cancellation.
import { useEffect, useRef, useState } from "react";
import reactUiArtifact from "@data/components/react-ui.json";
import { useAppStore } from "@/store";
import { bundleComponent } from "@/shared/lib/preview/componentBundle";
import { probeComponentRuntime } from "@/shared/lib/preview/componentRuntimeProbe";
import { collectAppCss } from "@/shared/lib/preview/collectAppCss";
import { scannableComponents, pendingScans, scanComponents, durableLogSync, type ComponentScanResult, type ComponentBuildStatus } from "@/features/designs/lib/componentScan";
import { recordPreviewError, loadScanCache, saveScanCache, type CachedScan } from "@/features/designs/lib/componentBridge";
import { makeBatchWriter } from "@/shared/lib/core/batchWriter";
import { type KitArtifact, type LibraryModuleResolver } from "@/features/designs/lib/componentPreview";
import { libraryModuleResolver } from "@/features/designs/lib/libraryModules";
import type { ComponentRecord } from "@/features/designs/lib/model";

/** The packaged kit artifact (built-in `source` + `runtime` closure), same import the single-component
 *  `ComponentPreviewFrame` uses — its `source` survives here (the store SEED strips it, this raw import
 *  keeps it), so a built-in resolves its `@/…` closure at scan time. */
const ARTIFACT = reactUiArtifact as unknown as KitArtifact;

/** How many component builds run at once — a small pool so the sweep stays local + non-blocking. Each
 *  build is a synchronous-ish esbuild-wasm pass; 3 keeps the UI responsive on a large kit. */
const SCAN_CONCURRENCY = 3;

/** How long results buffer before one batched store commit (#4132). Long enough that a burst of builds
 *  collapses into a single render, short enough that badges still stream in visibly during a sweep. */
const SCAN_FLUSH_MS = 150;

/**
 * How long cache entries buffer before one DURABLE write.
 *
 * Deliberately far slower than {@link SCAN_FLUSH_MS}, because the two flushes pay different currencies.
 * The store flush is an in-memory setState, so 150ms is cheap and keeps badges streaming in visibly. The
 * cache flush is a PROCESS SPAWN, and hanging it on the same timer fired ~400 of them per sweep — 157
 * SECONDS of process churn, measured, each one re-reading and rewriting the whole file.
 *
 * THE TRADE: a crash mid-sweep loses at most one window of results, and those components are simply
 * re-scanned next visit. That is cheap by construction — this cache may only ever save work, never
 * withhold a scan — which is what makes a slow cadence the right call rather than a risky one.
 */
const CACHE_FLUSH_MS = 5_000;

/**
 * Scan the active kit's components for preview-build errors while `active`, recording each result in the
 * store (`setComponentBuildStatus`). Re-runs when `comps` changes (a designer edit), re-queuing only the
 * components whose build signature changed; a revisit with no edits is a no-op (all signatures cached).
 *
 * @param active whether the Studio page is currently mounted/visible — gates the scan so it runs on
 *               VISIT (KeptMountedPage first-mount), not at app boot.
 * @param comps  the active kit's components (the scan is kit-scoped, mirroring the graph).
 * @param artifact the packaged kit artifact; defaults to the bundled react-ui one (overridable for tests).
 */
export function useComponentScan(
  active: boolean,
  comps: ComponentRecord[],
  artifact: KitArtifact = ARTIFACT,
  // The library resolver the sweep builds with — the active blueprint's pinned sound kit (#3412) when the
  // caller has project context. It is part of the build, so a kit switch re-queues the affected components.
  libResolver: LibraryModuleResolver = libraryModuleResolver,
): void {
  const applyResults = useAppStore((s) => s.applyComponentScanResults);
  // The signature we last recorded a result for, per component id — survives kit switches + revisits, so
  // an already-built component is never re-bundled unless its source changed.
  const scannedSigs = useRef<Map<string, string>>(new Map());
  // Whether the durable cache has been read yet (#the-component-scan-remembers-what-it-already-built).
  // The sweep WAITS for this: starting before the cache lands would rebuild everything it was about to
  // learn it could skip, which is the whole cost this exists to remove.
  const cacheLoaded = useRef(false);
  const [cacheReady, setCacheReady] = useState(false);

  useEffect(() => {
    if (!active || cacheLoaded.current) return;
    let cancelled = false;
    void loadScanCache().then((cached) => {
      if (cancelled) return;
      // Seed BOTH halves from one read: the signatures the sweep may skip, and the statuses that badge
      // the graph. Without the statuses a cached visit would skip the work AND show no badges — worse
      // than scanning, because the graph would claim everything is healthy.
      const seeded: ComponentScanResult[] = [];
      for (const [id, e] of Object.entries(cached)) {
        scannedSigs.current.set(id, e.sig);
        seeded.push({ id, status: e.status, stateBlanks: e.stateBlanks });
      }
      if (seeded.length) applyResults(seeded);
      cacheLoaded.current = true;
      setCacheReady(true);
    });
    return () => { cancelled = true; };
  }, [active, applyResults]);

  useEffect(() => {
    if (!active || !cacheReady) return;
    const scannable = scannableComponents(comps, artifact, libResolver);
    const pending = pendingScans(scannable, scannedSigs.current);
    if (pending.length === 0) return;
    const sigById = new Map(pending.map((p) => [p.id, p.sig]));
    // App styles once per sweep (not per component) so each runtime probe renders faithfully.
    const appCss = collectAppCss();

    let cancelled = false;

    // #4132: BATCH the store writes. Results land one at a time (a throttled pool of esbuild passes), and
    // writing each straight through cost two commits per component — ~496 for this kit — every one of
    // which re-rendered the whole graph. Buffer them and flush on a short timer instead: the badges still
    // appear progressively (a sweep takes seconds, the flush window is 150ms) but a visit now costs
    // O(sweep-duration / 150ms) commits rather than O(2N).
    let buffer: ComponentScanResult[] = [];
    let flushTimer: ReturnType<typeof setTimeout> | null = null;
    // The DURABLE half runs on its OWN clock — see CACHE_FLUSH_MS. `makeBatchWriter` owns the three
    // parts of that rule (coalesce by id, fire on a slow window, lose nothing on teardown) and is tested
    // without React; this line is just the wiring.
    const cacheWriter = makeBatchWriter<CachedScan>((batch) => { void saveScanCache(batch); }, CACHE_FLUSH_MS);
    const flush = () => {
      flushTimer = null;
      if (cancelled || buffer.length === 0) return;
      const batch = buffer;
      buffer = [];
      applyResults(batch);
      // Queue the durable half — written on ITS own slower clock, not this one. Fire-and-forget: a
      // failed write costs a re-scan next visit, which is simply the behaviour before this cache existed.
      const entries: Record<string, CachedScan> = {};
      for (const r of batch) {
        const sig = scannedSigs.current.get(r.id);
        // No signature ⇒ nothing to key the entry on, so it could never be a hit. Skip rather than
        // queue a row that can only ever be dead weight.
        if (sig) entries[r.id] = { sig, status: r.status, stateBlanks: r.stateBlanks };
      }
      cacheWriter.queue(entries);
    };
    const enqueue = (result: ComponentScanResult) => {
      buffer.push(result);
      flushTimer ??= setTimeout(flush, SCAN_FLUSH_MS);
    };

    void scanComponents(
      pending,
      bundleComponent,
      SCAN_CONCURRENCY,
      (id, status, stateBlanks) => {
        if (cancelled) return;
        // Mark the signature only once its result lands, so a cancelled build is re-queued next run
        // (never marked-but-unscanned).
        scannedSigs.current.set(id, sigById.get(id) ?? "");
        // #3540: mirror the render result to the DURABLE log BEFORE overwriting the store status, so the
        // prior status is still readable — `durableLogSync` records a runtime throw and clears a
        // now-resolved error (fire-and-forget; a missing `bsc` no-ops it). This is what makes
        // `bsc ui doctor` see the COMPLETE errored set, not only components a human opened.
        // The durable-log diff still reads the PRIOR status, so it must consult the store PLUS anything
        // already buffered but not yet flushed — otherwise a component scanned twice within one flush
        // window would diff against a stale value.
        // (a manual reverse scan — `findLast` is past this project's tsc lib target)
        let pendingPrior: ComponentBuildStatus | undefined;
        for (let i = buffer.length - 1; i >= 0; i--) if (buffer[i].id === id) { pendingPrior = buffer[i].status; break; }
        const sync = durableLogSync(pendingPrior ?? useAppStore.getState().componentBuildStatus[id], status);
        if (sync !== null) void recordPreviewError(id, sync);
        // Both halves go in one batched entry. `stateBlanks` is always carried (even `[]`) so a fixed
        // component clears its prior blank badge on re-scan.
        enqueue({ id, status, stateBlanks });
      },
      () => cancelled,
      // Runtime probe (#2908): run each build-clean component in a hidden iframe to catch a throw the
      // build can't see (e.g. a d3-force tick). Inconclusive/infra failures resolve ok — never a false badge.
      (js) => probeComponentRuntime(js, appCss),
    );
    return () => {
      // Flush what already landed BEFORE cancelling — those builds really happened, and dropping them
      // would re-queue work whose signature was already marked scanned (a badge that never returns).
      if (flushTimer) clearTimeout(flushTimer);
      if (buffer.length) applyResults(buffer);
      buffer = [];
      // …and write whatever the slow clock has not reached yet. Those builds really happened, and their
      // signatures are already marked scanned — dropping them here would leave work that never re-queues
      // AND never reaches the cache.
      cacheWriter.flush();
      cancelled = true;
    };
  }, [active, comps, artifact, libResolver, applyResults]);
}

import { useState, useEffect } from "react";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { useAppStore } from "@/store";
import { paneIdFor } from "@/app/console/lib/paneIdentity";
import { openDetachedTab } from "@/app/console/lib/detachWindow";
import type { Tab } from "@/app/chrome/Tabstrip";
import { Dialog } from "@/shared/ui/overlay/Dialog";
import { Button } from "@/shared/ui/controls/Button";
import { NewTabDialog } from "@/app/console/NewTabDialog";

/** The next free `tab-N` name (the highest existing N + 1). */
function nextTabName(tabs: Tab[]): string {
  const nums = tabs
    .map((t) => t.name.match(/^tab-(\d+)$/)?.[1])
    .filter((n): n is string => n !== undefined)
    .map(Number);
  return `tab-${nums.length === 0 ? 1 : Math.max(...nums) + 1}`;
}

export interface ConsoleTabsApi {
  /** Props to spread onto the <Tabstrip>. */
  tabstripProps: {
    tabs: Tab[];
    activeIdx: number;
    onSelect: (idx: number) => void;
    onClose: (idx: number) => void;
    onAdd: () => void;
    onRename: (idx: number, name: string) => void;
    onChangeLayout: (idx: number, layout: string) => void;
    onReorder: (from: number, to: number) => void;
    hiddenIds: string[];
    onTearOff: (idx: number) => void;
  };
  /** The new-tab + close-confirm dialogs (mount once at the app root). */
  dialogs: React.ReactNode;
  /** Open the new-tab dialog (e.g. from the empty state's CTA). */
  openNewTab: () => void;
}

/**
 * Owns the console's tab management — the layer that used to live in App.tsx. The console (not the
 * shell) owns its tabs: create (layout picker), close (PTY teardown + a confirm when a session is
 * live), layout change (kills the panes that vanish), reorder, and tear-off. Returns props for the
 * <Tabstrip> + the dialogs + an `openNewTab` for the empty state.
 */
export function useConsoleTabs(): ConsoleTabsApi {
  const tabs = useAppStore((s) => s.tabs);
  const activeTabIdx = useAppStore((s) => s.activeTabIdx);
  const activeWorkspace = useAppStore((s) => s.activeWorkspace);
  const detachedTabIds = useAppStore((s) => s.detachedTabIds);
  const setActiveTab = useAppStore((s) => s.setActiveTab);
  const addTab = useAppStore((s) => s.addTab);
  const closeTab = useAppStore((s) => s.closeTab);
  const renameTab = useAppStore((s) => s.renameTab);
  const setTabLayout = useAppStore((s) => s.setTabLayout);
  const moveTab = useAppStore((s) => s.moveTab);
  const setTabDetached = useAppStore((s) => s.setTabDetached);

  const [confirmCloseIdx, setConfirmCloseIdx] = useState<number | null>(null);
  const [showNewTab, setShowNewTab] = useState(false);

  // ⌘T / Ctrl-T opens a new console tab (console screen only).
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if ((e.metaKey || e.ctrlKey) && e.key === "t" && activeWorkspace === "console") {
        e.preventDefault();
        setShowNewTab(true);
      }
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [activeWorkspace]);

  function killTabPtys(tabIdx: number, layout: string) {
    const [c, r] = layout.split("×").map(Number);
    const tab = tabs[tabIdx];
    for (let i = 0; i < c * r; i++) {
      // Kill the pane's RESOLVED identity id (#1176) — manual panes are `man:<tabId>:p<idx>`,
      // so the old positional `t{tabIdx}p{i}` would miss the real session and leak it.
      fireInvoke("pty_kill", { paneId: paneIdFor(tab, tabIdx, i) }, console.error);
    }
  }

  function handleLayoutChange(tabIdx: number, layout: string) {
    const tab = tabs[tabIdx];
    const [oldCols, oldRows] = tab.layout.split("×").map(Number);
    const [newCols, newRows] = layout.split("×").map(Number);
    const oldCount = oldCols * oldRows;
    const newCount = newCols * newRows;
    // Kill PTY sessions for panes that will no longer exist (resolved identity id, #1176).
    if (newCount < oldCount) {
      for (let i = newCount; i < oldCount; i++) {
        fireInvoke("pty_kill", { paneId: paneIdFor(tab, tabIdx, i) }, console.error);
      }
    }
    setTabLayout(tabIdx, layout);
  }

  function handleCloseRequest(idx: number) {
    const tab = tabs[idx];
    if (tab.state === "run" || tab.state === "on") {
      setConfirmCloseIdx(idx);
    } else {
      killTabPtys(idx, tab.layout);
      closeTab(idx);
    }
  }

  function confirmClose() {
    if (confirmCloseIdx !== null) {
      killTabPtys(confirmCloseIdx, tabs[confirmCloseIdx].layout);
      closeTab(confirmCloseIdx);
    }
    setConfirmCloseIdx(null);
  }

  function handleTearOff(idx: number) {
    const t = tabs[idx];
    if (!t?.id) return;
    openDetachedTab(t.id, t.name, () => setTabDetached(t.id!, false));
    setTabDetached(t.id, true);
    // If the active tab was the one torn off, move focus to the first tab still in
    // the bar so the window isn't left on a hidden tab.
    if (activeTabIdx === idx) {
      const next = tabs.findIndex((x, i) => i !== idx && !detachedTabIds.includes(x.id ?? ""));
      if (next >= 0) setActiveTab(next);
    }
  }

  const pendingTab = confirmCloseIdx !== null ? tabs[confirmCloseIdx] : null;
  const activeSessionCount = pendingTab ? /* placeholder until real session tracking */ 1 : 0;

  const dialogs = (
    <>
      {confirmCloseIdx !== null && pendingTab && (
        <Dialog
          title={`Close "${pendingTab.name}"?`}
          danger
          onDismiss={() => setConfirmCloseIdx(null)}
          actions={
            <>
              <Button onClick={() => setConfirmCloseIdx(null)}>cancel</Button>
              <Button danger onClick={confirmClose}>close tab</Button>
            </>
          }
        >
          {activeSessionCount === 1
            ? "1 active session is running in this tab and will be stopped."
            : `${activeSessionCount} active sessions are running in this tab and will be stopped.`}
          {" "}This cannot be undone.
        </Dialog>
      )}
      {showNewTab && (
        <NewTabDialog
          onConfirm={(layout) => { addTab({ name: nextTabName(tabs), layout, state: "idle" }); setShowNewTab(false); }}
          onDismiss={() => setShowNewTab(false)}
        />
      )}
    </>
  );

  return {
    tabstripProps: {
      tabs,
      activeIdx: activeTabIdx,
      onSelect: setActiveTab,
      onClose: handleCloseRequest,
      onAdd: () => setShowNewTab(true),
      onRename: renameTab,
      onChangeLayout: handleLayoutChange,
      onReorder: moveTab,
      hiddenIds: detachedTabIds,
      onTearOff: handleTearOff,
    },
    dialogs,
    openNewTab: () => setShowNewTab(true),
  };
}

// useCoordAnnouncer (#3770, a11y epic #2725) — announces NEW coordination events to the screen reader.
// App-level (the shell may import features); reuses the tunnel's `coordAlerts` derivation, whose `text`
// is already the human line ("api-stream paused and is waiting for you"), so the spoken status matches
// the CoordinatorInbox + the mobile alerts. It speaks the STRUCTURED events, never the raw terminal
// stream (screen readers drown in that). The mount backlog is seeded SILENT so a reader isn't buried in
// history on launch — only events that arrive after are announced.
import { useEffect, useRef } from "react";
import { useCoordLog } from "@/shared/lib/fleet/useCoordLog";
import { coordAlerts } from "@/features/tunnel";
import { announce } from "@/shared/lib/a11y/announcer";

export function useCoordAnnouncer(): void {
  const { state } = useCoordLog();
  const seen = useRef<Set<string>>(new Set());
  const seeded = useRef(false);

  useEffect(() => {
    const alerts = coordAlerts(state);
    if (!seeded.current) {
      // First read after mount: remember the existing backlog without speaking it.
      seeded.current = true;
      for (const a of alerts) seen.current.add(a.id);
      return;
    }
    for (const a of alerts) {
      if (seen.current.has(a.id)) continue;
      seen.current.add(a.id);
      // `fleet-failed` is the one that can't wait (a stalled chain); everything else queues politely.
      announce(a.text, { assertive: a.kind === "fleet-failed" });
    }
  }, [state]);
}

// useCoordLog (#1495) — one home for reading + replaying the coordination log. The
// `read coord log → ingestCoordLog(lines, emptyCoordState())` pair was hand-rolled in
// every fleet hook (the coordinator, the director pump, the worker auto-end, the live fleet view,
// the tunnel control). This centralizes the read so a change to the log format or the limit lands
// in one place. The read is `bsc logs tail coord --oldest` over the `bsc` bridge (#2144) — raw,
// chronological (oldest-first) lines, the same shape the old `read_coord_log` command returned.
//
//  - readCoordState(limit): the imperative read. Returns `null` on a read FAILURE (so the actuator
//    loops keep their "skip this tick, don't touch ref state" guard) and the full ingest result
//    otherwise. A successful read of an EMPTY log returns an empty-but-non-null result.
//  - useCoordLog({ limit }): the hook for views that just want the latest state — re-reads
//    event-driven on `logs://coord` changes and returns the latest `{ state, ready, answered }`,
//    keeping the last good result across a transient read failure.

import { useState } from "react";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { useLogStream } from "@/shared/hooks/useLogStream";
import { ingestCoordLog, emptyCoordState } from "@/shared/lib/fleet/coordination";

/** The replayed coord state (`state`/`ready`/`answered`) plus the raw `lines` — the director
 *  pump still needs the unparsed log for its cursor-based heartbeat. */
export type CoordResult = ReturnType<typeof ingestCoordLog> & { lines: string[] };

/** Read + replay the coordination log. `null` on a read failure; the replay + raw lines otherwise. */
export async function readCoordState(limit = 1000): Promise<CoordResult | null> {
  // In-process read (#3630) — `null` fallback preserves the "read failed → skip this tick" guard.
  const lines = await logsTail("coord", limit, true, null);
  if (!lines) return null;
  return { lines, ...ingestCoordLog(lines, emptyCoordState()) };
}

interface UseCoordLogOptions {
  /** Lines to read from the tail of the log (default 1000). */
  limit?: number;
}

/** Poll the coordination log and return the latest replay. Keeps the last good result on a
 *  transient read failure rather than blanking. */
export function useCoordLog(opts: UseCoordLogOptions = {}): CoordResult {
  const { limit = 1000 } = opts;
  const [result, setResult] = useState<CoordResult>(() => ({ lines: [], ...ingestCoordLog([], emptyCoordState()) }));
  // Event-driven (#3638): re-read + replay only when the coord log changes (plus mount + a slow
  // backstop), instead of polling on a fixed cadence — the `logs://coord` change event drives the read.
  useLogStream("coord", async (isCancelled) => {
    const res = await readCoordState(limit);
    if (isCancelled() || !res) return;
    setResult(res);
  }, [limit]);
  return result;
}

// useCoordSpeaker (#3804, a11y epic #2725 Tier 1) — SPEAKS new coordination events aloud via the
// app-owned TTS engine (`speechSynthesis`), so a blind developer can drive the fleet BY EAR. The
// sibling of `useCoordAnnouncer` (#3770): both read the SAME seam — `useCoordLog()` → `coordAlerts`,
// whose `text` is already the human line ("api-stream paused and is waiting for you") — but the
// announcer writes to an ARIA live region for the user's OWN screen reader, while this one speaks with
// the app's voice. It speaks only the STRUCTURED events, never the raw terminal stream.
//
// Opt-in + fully off by default; settings (enabled/rate/voice/verbosity) are read FRESH per event from
// the store, so toggling on mid-session takes effect immediately WITHOUT replaying history. The mount
// backlog is seeded SILENT, and every alert id is remembered whether or not it was spoken — so enabling
// TTS never buries the user under the events that were already on screen.
import { useEffect, useRef } from "react";
import { useCoordLog } from "@/shared/lib/fleet/useCoordLog";
import { coordAlerts } from "@/features/tunnel";
import { useAppStore } from "@/store";
import { speak } from "@/shared/lib/a11y/speech";
import { shouldSpeak } from "@/app/a11y/coordSpeech";

export function useCoordSpeaker(): void {
  const { state } = useCoordLog();
  const seen = useRef<Set<string>>(new Set());
  const seeded = useRef(false);

  useEffect(() => {
    const alerts = coordAlerts(state);
    const firstSeed = !seeded.current;
    seeded.current = true;
    for (const a of alerts) {
      if (seen.current.has(a.id)) continue;
      // Remember EVERY alert (even while off / on the initial backlog) so enabling never replays them.
      seen.current.add(a.id);
      if (firstSeed) continue;
      const st = useAppStore.getState();
      if (st.ttsEnabled && shouldSpeak(a.kind, st.ttsVerbosity)) {
        speak(a.text, { rate: st.ttsRate, voiceURI: st.ttsVoice || undefined });
      }
    }
  }, [state]);
}

// The always-on coordinator (#199, scoped down in #1039, and again in
// #coordinator-stops-waking-sessions): polls the coordination log, projects the maintenance set, and
// tells the HUMAN. It no longer resumes anything.
//
// WHAT IT USED TO DO, AND WHY THAT WAS WRONG. Two loops lived here: a `bsc-answer` fired `injectWake`
// into the asking worker, and a `bsc-assign` fired `actuateWake` (kill + relaunch with the prompt
// baked in) at the assignee. Both were recency-gated on FRESH_MS (15 minutes) — and that gate was the
// bug, not the safeguard it looked like. This hook re-derives from the WHOLE coord log on mount, so
// starting the app replayed a quarter-hour of coordination traffic as live wakes: five to nine panes
// opening a Claude turn within the same second, repeatedly, with nobody having clicked anything. That
// is the boot-time cause the maintainer reported as "sessions automatically start on app start".
//
// THE RULE NOW: the app never resumes a session. Only the user does — the Coordination inbox's Wake
// button, or a director running `bsc fleet wake <pane>` on purpose. Telling a person something
// happened is NOT waking a session, so both surviving paths stay:
//   • the maintenance projection (#4025) — the reaper needs it, and it moves no session;
//   • mobile push (#366) — a stuck/failed signal still reaches the human, deduped + once each.
//
// NOTHING IS LOST from the record: asks, answers and assignments are all still in the coord log and
// still reach the Coordination inbox. What changed is who acts on them.
//
// THE CONSEQUENCE IS REAL AND IS HANDLED IN PROSE, not left implicit: an assignment no longer resumes
// its worker, so the director/worker protocols that promised "resumes you automatically" were updated
// in the same change. A promise the code no longer keeps is how a fleet stalls silently, waiting on a
// wake that never comes.
import { useAppStore } from "@/store";
import { ingestCoordLog, coordNotifications, buildProducerOf, producesFromPaneStreams, refusalKey } from "@/shared/lib/fleet/coordination";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import { useLogStream } from "@/shared/hooks/useLogStream";
import type { SessionMeta } from "@/features/tunnel";
import { tunnelStatus, tunnelSetSessions } from "@/features/tunnel";
import { log } from "@/shared/lib/core/log";

// THE TWO ONCE-EACH GUARDS, anchored on `globalThis` (#coordinator-dedupe-refs-die-on-remount).
// `notified` is the mobile-push dedupe (#366); `warnedRefusals` is the cross-project refusal report
// (#the-refusal-warning-replays-the-whole-log-every-minute). Both loops below read state re-derived
// from the WHOLE coord.log tail on every read, and nothing prunes that tail, so these Sets are the only
// thing standing between one real event and an unbounded number of reports.
//
// THEY WERE REACT REFS, AND A REF LIVES AND DIES WITH THE MOUNT — not the lifetime anyone reading
// this hook assumes, because the hook is not mounted from a file. `useCoordinator()` is called from the
// `consolepage` graph RECORD, which `GraphComponent` remounts whenever that record recompiles. Measured
// over one app run: 28 `graph-loader: mounted "consolepage"` events, 28 bursts of the SAME 19 refusals,
// 532 warnings — bursts nine seconds apart, so recompiles, not restarts. The push half was the worse
// one: it re-delivered every current alert to a paired phone on each remount, breaking the "exactly
// once" its own comment promised.
//
// MODULE SCOPE IS NOT ENOUGH, AND THAT IS THE WHOLE REASON THIS LOOKS HEAVIER THAN IT SHOULD. In the app
// this module is NOT the bundled one: `resolveGraphSource` matches an algorithm impl by `provides`, and
// the `use-coordinator.ts` record provides `@/app/console/useCoordinator`, so the loader vendors its
// `code` INTO the consolepage closure and evaluates it fresh on every compile — `makeGraphRequire`
// builds a new `evaluated` map each load. A module-level `const` would therefore be re-created exactly
// as often as the ref was, fixing the vitest harness (which imports the bundled copy once) and NOTHING
// in the running app. Only a realm-global survives being re-evaluated.
//
// Same shape, same reason, as `ensureEsbuild`'s `Symbol.for("bsc.esbuildInit")` cache in
// `shared/lib/preview/componentBundle.ts`: a module-level binding is reset by re-execution (HMR there,
// a graph recompile here), and the registered symbol is what outlives it.
//
// Pruning coord.log is NOT the alternative fix: the cap is 10k lines / 20MB against a 445-line file, so
// it never self-trims, and trimming would hide the current burst rather than the class.
interface CoordDedupe { notified: Set<string>; warnedRefusals: Set<string> }
const COORD_DEDUPE = Symbol.for("bsc.coordinatorDedupe");
type DedupeHost = { [COORD_DEDUPE]?: CoordDedupe };

/** The app-run-lifetime dedupe guards, created on first use. Read THROUGH this on every pass rather than
 *  captured in a module binding — capturing it is the bug this replaced, one level up. */
function coordDedupe(): CoordDedupe {
  const host = globalThis as unknown as DedupeHost;
  const existing = host[COORD_DEDUPE];
  if (existing) return existing;
  const fresh: CoordDedupe = { notified: new Set<string>(), warnedRefusals: new Set<string>() };
  host[COORD_DEDUPE] = fresh;
  return fresh;
}

/**
 * Clear both dedupe Sets. TESTS ONLY — outliving every mount AND every re-evaluation is the entire
 * point of them, so no app path should call this. It exists because a realm-global, unlike the ref it
 * replaced, is not reset between test cases, and a case that inherits a previous one's keys silently
 * asserts nothing.
 */
export function resetCoordinatorDedupe(): void {
  const d = coordDedupe();
  d.notified.clear();
  d.warnedRefusals.clear();
}

export function useCoordinator(): void {
  useLogStream("coord", async (isCancelled) => {
    if (isCancelled()) return;
    const res = await readCoordState(1000);
    if (isCancelled() || !res) return;
    const { state, ready, refused } = res;
    const { notified, warnedRefusals } = coordDedupe();
    // CROSS-PROJECT REFUSALS (#coord-log-is-app-wide-answers-cross-projects) are REPORTED, not
    // dropped. A silently swallowed answer looks to the sending director exactly like a delivered
    // one, so it would go on believing it had unblocked a worker it never reached — and the worker's
    // real director would never know it still owed a reply.
    //
    // ONCE EACH, though (#the-refusal-warning-replays-the-whole-log-every-minute). `refused` is
    // re-derived from the WHOLE tail on every read and nothing prunes those lines out of it, so
    // reporting unguarded meant re-announcing the same fixed, months-old events on every change event
    // AND on `useLogStream`'s 60s backstop — measured at 1,729 warnings from 19 real refusals, a
    // block of 19 every minute for as long as the app ran. Keyed per EVENT (see `refusalKey`), so a
    // genuine recurrence still warns; the pruning of the LOG is not this hook's business.
    for (const r of refused) {
      const key = refusalKey(r);
      if (warnedRefusals.has(key)) continue;
      warnedRefusals.add(key);
      log.warn(
        `coordination: refused a cross-project ${r.kind} — ${r.from} tried to reach ${r.target}, ` +
        `which belongs to another project. Coordination is scoped to the project that raised it.`,
      );
    }
    // #4025 — project the declared-maintenance set into the store. This hook already reduces the
    // whole coord log, so the alternative was a SECOND poll of the same file in the reaper.
    useAppStore.getState().setPaneMaintaining(
      Object.fromEntries(state.maintaining.map((m) => [m.session, true])),
    );

    // Mobile push (#366): alerts to a paired phone, deduped + once each. This is the one thing that
    // still reaches OUT — to a person, not into a session.
    void pushNotifications(state, ready, notified).catch((e) =>
      log.error(`coordinator: notify failed: ${e}`),
    );
  }, []);
}

/**
 * Push the current coordination notifications to a paired phone, firing each alert once.
 * No-op unless the tunnel is running (no phone paired -> nothing to deliver). Flips each
 * affected pane to `awaiting_input` with the summary as its prompt so the existing relay
 * `user_request` -> FCM path delivers it (see tunnel_set_sessions in src-tauri/src/tunnel.rs).
 */
async function pushNotifications(
  state: ReturnType<typeof ingestCoordLog>["state"],
  ready: ReturnType<typeof ingestCoordLog>["ready"],
  notified: Set<string>,
): Promise<void> {
  const producerOf = buildProducerOf(
    producesFromPaneStreams(useAppStore.getState().fleetPaneStreams),
  );
  const fresh = coordNotifications(state, ready, producerOf).filter((n) => !notified.has(n.key));
  if (fresh.length === 0) return;
  const status = await tunnelStatus().catch(() => null);
  if (!status?.running) return; // no phone paired -> leave unmarked so it delivers once paired
  const nowIso = new Date().toISOString();
  const sessions: SessionMeta[] = fresh.map((n) => ({
    paneId: n.session,
    status: "awaiting_input",
    currentTask: "coordinator",
    lastActivity: nowIso,
    prompt: n.summary,
  }));
  await tunnelSetSessions(sessions);
  for (const n of fresh) notified.add(n.key);
}

import { useEffect } from "react";
import { useAppStore } from "@/store";

/**
 * Report the navigated ENTITY label for a graph to the titlebar location crumb (#3041) — the thing you're
 * INSIDE the graph: the drilled project (Glance), the entered team (Teams), the active kit (Components),
 * the active language (Algorithms). `key` is the page id (`glance`/`teams`/`designs`/`algorithms`);
 * `label` is the current entity name, `""` when none (e.g. a graph overview). `locationCrumb` appends it
 * after the page name, so the crumb reads e.g. "Planner — Components — react-ui".
 *
 * The graph resolves the label itself (it has the local selection + the data), so the store just carries
 * the resolved string — App.tsx needs no per-graph knowledge. The store write is idempotent, so calling
 * this every render is cheap.
 */
export function useCrumbEntity(key: string, label: string): void {
  const setCrumbEntity = useAppStore((s) => s.setCrumbEntity);
  // Block body (not `() => setCrumbEntity(...)`) so the effect returns undefined — an implicit return of
  // the action's value would be mistaken for a cleanup fn ("destroy is not a function" on unmount).
  useEffect(() => { setCrumbEntity(key, label); }, [key, label, setCrumbEntity]);
}

// useCtxRequired (#1775, extracted from Planning.tsx) — the dynamic Context required-set
// (#1019/#1028): polled from plan.db, baseline-seeded once per project/session. The Context gate
// reads it; context files gate on GENERATION (the file exists), not confirmation, so there's
// nothing to confirm/mirror. Returns the live required-topic list.
import { useState, useEffect, useRef } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { bscJson, bscRun } from "@/shared/lib/core/bsc";
import { DISCOVERY_BASELINE } from "@/features/planner/stages/planStageDerive";
import type { BlueprintStage } from "@/features/planner/stages/blueprints";

export function useCtxRequired(effectiveProjectId: string, planSecs: BlueprintStage[]): string[] {
  const [ctxRequired, setCtxRequired] = useState<string[]>([]);
  const ctxRequiredJsonRef = useRef<string>("");
  const ctxSeededRef = useRef<Set<string>>(new Set());

  // #1019: clear the cached manifest on a project switch so a stale set never bleeds across.
  useEffect(() => { setCtxRequired([]); ctxRequiredJsonRef.current = ""; }, [effectiveProjectId]);

  // #1028: poll the Context required-set from plan.db and seed the baseline once per project. The
  // gate reads it to check each required topic's `context/<topic>.md` exists.
  usePoll((isCancelled) => {
    if (!effectiveProjectId) return;
    const tick = async () => {
      try {
        // `bsc plan discovery list --json` emits the required-topic string array (the same `Vec<String>`
        // the old `plan_list_discovery` command returned); bscJson degrades to [] when plan.db is absent.
        const m = await bscJson<string[]>(effectiveProjectId, ["plan", "discovery", "list", "--json"], []);
        if (isCancelled()) return;
        // Seed the baseline once per project/session if the set is empty — a deterministic floor before
        // the planner runs `bsc-plan context require`. The blueprint's context section `requires`
        // overrides the universal baseline (blueprint seeding).
        if ((m?.length ?? 0) === 0 && !ctxSeededRef.current.has(effectiveProjectId)) {
          ctxSeededRef.current.add(effectiveProjectId);
          const requires = planSecs.find(s => s.key === "discovery")?.requires ?? DISCOVERY_BASELINE;
          for (const t of requires) {
            await bscRun(effectiveProjectId, ["plan", "discovery", "require", t]);
          }
          return; // next tick reads the seeded set
        }
        const j = JSON.stringify(m ?? []);
        if (j !== ctxRequiredJsonRef.current) {
          ctxRequiredJsonRef.current = j;
          setCtxRequired(m ?? []);
        }
      } catch { /* plan.db not created until the planner/seed touches context — ignore */ }
    };
    return tick();
  }, 2000, [effectiveProjectId, planSecs]);

  return ctxRequired;
}

// useDebugChannel (#3437, epic #3260) — answer `bsc debug` from the live view, and ACK it.
//
// THE ROUND TRIP
//   bsc debug → request file → Rust watcher → `bsc://debug` → HERE → inspect → `debug_ack` → reply
//
// This is the thin adapter: it supplies the real DOM capabilities and ALWAYS acks — success or a stated
// error. Silence would strand the Rust waiter until its timeout and surface as "the frontend did not
// answer", sending someone to debug the channel instead of their actual bug. The decisions live in the
// pure `debugBridge.ts`.
//
// SEEING INTO THE PREVIEW
// A preview iframe is an OPAQUE origin (`sandbox="allow-scripts"`, no `allow-same-origin`), so
// `contentDocument` is null and nothing here can read it. That is a real trust boundary and is not
// weakened: the pan/zoom engine is ASKED to describe itself over `postMessage` (`{__probe:1}`), and a
// preview that never answers is reported as silent — which is itself the diagnosis.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { mountedPreviewFrames } from "@/features/designs";
import { log } from "@/shared/lib/core/log";
import {
  inspectDebug, REPORTED_STYLES,
  type DebugRequest, type DebugResult, type EngineProbe, type InspectDeps,
} from "@/app/debugBridge";

/** How long to wait for one preview engine's `__probeReply`. Short: the engine answers in the same tick
 *  when it is alive, so anything longer only delays reporting a SILENT engine — the interesting case. */
const ENGINE_PROBE_MS = 250;

/** Ask one preview's engine to describe itself; `null` when it does not answer in time. */
function probeEngine(iframe: HTMLIFrameElement): Promise<EngineProbe | null> {
  const win = iframe.contentWindow;
  if (!win) return Promise.resolve(null);
  return new Promise((resolve) => {
    let done = false;
    const finish = (v: EngineProbe | null) => {
      if (done) return;
      done = true;
      window.removeEventListener("message", onMsg);
      clearTimeout(timer);
      resolve(v);
    };
    const onMsg = (e: MessageEvent) => {
      // Correlate by SOURCE WINDOW, as the preview frame + runtime probe already do (#2908): several
      // previews can be mounted, and taking the first reply would attribute one engine's state to another.
      if (e.source !== win) return;
      const d = e.data as { __probeReply?: EngineProbe } | null;
      if (d?.__probeReply) finish(d.__probeReply);
    };
    const timer = setTimeout(() => finish(null), ENGINE_PROBE_MS);
    window.addEventListener("message", onMsg);
    try {
      win.postMessage({ __probe: 1 }, "*");
    } catch {
      finish(null); // a cross-origin refusal is "no answer", not a crash
    }
  });
}

/** The real-DOM capability set handed to the pure inspector. */
function liveDeps(): InspectDeps {
  return {
    at: (x, y) => document.elementFromPoint(x, y),
    rectOf: (el) => {
      const r = el.getBoundingClientRect();
      return { x: r.x, y: r.y, width: r.width, height: r.height };
    },
    stylesOf: (el) => {
      const cs = getComputedStyle(el);
      const out: Record<string, string> = {};
      for (const k of REPORTED_STYLES) out[k] = cs.getPropertyValue(k) || "";
      return out;
    },
    query: (selector) => Array.from(document.querySelectorAll(selector)),
    frames: () => mountedPreviewFrames(),
    probeEngine,
  };
}

/**
 * Listen for `bsc://debug` and answer it. Mounted once by the shell.
 *
 * An invalid selector is a STATED error, not a crash: `querySelectorAll` throws on bad syntax, and the
 * caller needs "that selector is malformed" rather than a timeout.
 */
export function useDebugChannel(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<DebugRequest & { id: string }>("bsc://debug", (e) => {
      const { id, ...req } = e.payload;
      void (async () => {
        let result: DebugResult | null = null;
        let error: string | null = null;
        try {
          result = await inspectDebug(req as DebugRequest, liveDeps());
        } catch (err) {
          error = err instanceof Error ? err.message : String(err);
        }
        if (disposed) return;
        try {
          await invoke("debug_ack", { ack: { id, ...(error ? { error } : { result }) } });
        } catch (err) {
          // The waiter will time out; log so the failure is attributable rather than mysterious.
          log.error(`debug: could not ack ${id}: ${String(err)}`);
        }
      })();
    });
    return () => {
      disposed = true;
      void un.then((f) => f());
    };
  }, []);
}

// useDesignRouteState (#2121) — polls a project's staged design manifest (`design/intake.json`) and
// reports whether any files are staged (`hasFiles`) and whether any staged file has CHANGED since it
// was last routed (content-hash diff via `changedDesignFiles`). Drives the UI stage's conditional
// footer: it offers "route design to project" ONLY when files are staged and the design is
// missing/stale (#2860); with nothing staged it reverts to "approve & continue". Read-only +
// non-fatal — a missing manifest reports no files, nothing changed.
import { useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { usePoll } from "@/shared/hooks/usePoll";
import { parseIntake, changedDesignFiles, INTAKE_DIR } from "@/features/planner/lib/fileIntake";

/** The staged-design snapshot the UI stage footer reads (#2860). */
export interface DesignRouteState {
  /** At least one design file is staged in `design/intake.json`. */
  hasFiles: boolean;
  /** At least one staged file differs from its last-routed hash (new or edited since routed). */
  changed: boolean;
}

/**
 * Whether the UI stage's footer should offer "route design to project" (#2860). True only when the
 * project needs a UI, there ARE staged files to route (`hasFiles`), AND either the design isn't
 * routed yet (`ui` section unconfirmed) or a staged file changed since the last route. **No staged
 * files ⇒ false** — the fix for the dead route button on a fresh UI stage with nothing to route.
 * Pure — unit-tested.
 */
export function uiNeedsRouting(requiresUi: boolean, uiConfirmed: boolean, design: DesignRouteState): boolean {
  return requiresUi && design.hasFiles && (!uiConfirmed || design.changed);
}

/**
 * @param projectKey  the project hub key whose `design/intake.json` is polled.
 * @param active      only poll while the UI stage is relevant (blueprint enables `ui`); false → idle.
 * @returns whether any files are staged and whether any staged file is unrouted/stale.
 */
export function useDesignRouteState(projectKey: string, active: boolean): DesignRouteState {
  const [state, setState] = useState<DesignRouteState>({ hasFiles: false, changed: false });
  usePoll(async (isCancelled) => {
    if (!active || !projectKey) { setState({ hasFiles: false, changed: false }); return; }
    try {
      const files = await invoke<[string, string][]>("read_project_files", { projectKey, subdir: INTAKE_DIR });
      if (isCancelled()) return;
      const manifest = files.find(([rel]) => rel === "intake.json")?.[1];
      const entries = manifest ? parseIntake(manifest) : [];
      setState({ hasFiles: entries.length > 0, changed: changedDesignFiles(entries).length > 0 });
    } catch {
      if (!isCancelled()) setState({ hasFiles: false, changed: false });
    }
  }, 2500, [projectKey, active]);
  return state;
}

// The designer-loop PUMP (#3292/#3304, epic #3260) — the app-side driver that keeps the live Design Studio
// session iterating on a `bsc loop`. It is to a designer loop what `useDirectorPump` is to a fleet: poll →
// decide (a pure decider) → actuate. It drives the LIVE PTY (not a headless agent) because the designer
// live-restyles the RUNNING app — the actor has to be the running session.
//
// TWO MODES over one poll:
//  · INTERACTIVE (#3292, the default) — on the DRIVER's turn post "continue" and inject a GENERIC
//    next-change prompt; the human picks what gets worked on by talking to the session.
//  · OVERNIGHT / QUEUE (#3304) — opt-in, started from the banner. The run carries a ranked directive
//    queue built ONCE from the design system's own measured gaps (`buildDesignerQueue` over
//    `bsc ui components --coverage` + `bsc ui resolve`), and each driver turn captures a fresh
//    `bsc shot`, posts the directive as the driver's turn (shot attached), injects it, and advances the
//    cursor. It stops on the directive ceiling or when the queue drains.
//
// One tick: find the open `driver ↔ designer` loop (`bsc loop list`), read its turns (`bsc loop show`), and
// decide. On a stall either mode re-injects; otherwise it waits — the turn-flip the designer causes by
// recording is the "prompt me again" signal, so the pump never floods.
//
// STOPPING (the property that matters most for an unattended run). Four independent brakes, so no single
// failure leaves a loop spending money:
//  1. `bsc loop stop` — the banner's Stop pill, out-of-band, reachable at any time.
//  2. The pump's own ceiling — `decideOvernightAction` returns `stop` at the directive cap or on a drained
//     queue, and the pump then requests the halt. Because that verdict is recomputed every tick from
//     durable state, a swallowed CLI error simply RETRIES on the next tick rather than being lost.
//  3. The loop store's `--max-turns`/`--budget`, enforced inside `say` — durable, and it outlives this
//     process, so even a killed app cannot leave the loop runnable.
//  4. The run state is never persisted, so overnight mode cannot auto-start or survive a restart.
// The local run state is cleared only once the loop is OBSERVABLY gone, so a "stopping" run never silently
// hands its still-open loop back to the interactive path (which has no ceiling of its own).

//
// INERT since #app-stops-pushing-prompts. Its body drove the designer's iteration loop by typing each directive into the design-studio session. REMOVED WITH THE LOOP: the maintainer accepted that cost explicitly rather than carve out an exception, because an exception here is the app pushing prompts on a schedule, which is the whole of what this directive forbids.
//
// The export SURVIVES deliberately: this module is registered in graphPlatform/appModules so graph
// RECORDS can import it, and removing the export breaks record compilation at runtime — the shape
// useFleetGate took for the same reason.

/** Does nothing. See the note above. */
export function useDesignerLoopPump(): void {
  // Intentionally empty: no poll, no evaluation, no injection.
}

// The director pump (#366, #369, #371): drives the fleet's async-integrator "director"
// session so it does not just idle after its kickoff. Two delivery paths, injected via
// pty_write into the director pane:
//
//  1. PENDING WORKER QUESTIONS (state-based) -- unanswered `bsc-ask` questions are
//     re-derived from the FULL coord log every tick (ingestCoordLog -> state.asking), so a
//     question is delivered even if it was logged before the pump first saw the director or
//     across an app restart. Each (pane, ask) is surfaced once; the key is pruned when the
//     ask is answered/woken so a re-ask re-surfaces. Delivered when the director is idle, or
//     after ASK_FALLBACK_MS even if it is not (the TUI may never trip the 1.5s idle gate;
//     Claude Code queues input typed mid-turn). This is the must-not-drop case.
//  2. NOTIFICATIONS + HEARTBEAT (cursor-based) -- landed/blocked/failed activity and the
//     periodic sweep, via decideDirectorAction (idle-gated).
//
// Mounted once in ConsoleWorkspace (which stays mounted across screens). Pure logic lives in
// directorDrive.ts + coordination.ts; this is the thin Tauri/React actuator.
//
// INERT since #app-stops-pushing-prompts. Its body polled coord.log and typed pending asks, briefs, requests and routed actions into the director's pane. The events are still WRITTEN to coord.log by the bsc-* emitters; the director reads them on its own cadence instead of being poked.
//
// The export SURVIVES deliberately: this module is registered in graphPlatform/appModules so graph
// RECORDS can import it, and removing the export breaks record compilation at runtime — the shape
// useFleetGate took for the same reason.

import type { RefObject } from "react";

/** Does nothing. See the note above. */
export function useDirectorPump(_paneStatusesRef: RefObject<Record<string, "run" | "on" | "idle">>): void {
  // Intentionally empty: no poll, no evaluation, no injection.
}

// useDockBack (#3919) — the main window's half of "drag a torn-off tab home".
//
// A detached window cannot deliver its drop to this window's DOM: the tab drag is HTML5 drag-and-drop,
// scoped to one webview (#3917). So it emits over the Tauri app-global bus instead, and this clears the
// detached flag — which is what makes the tab reappear in its persisted place (`usePageTabs` filters the
// strip by `detachedSections`).
//
// Idempotent by construction: `setSectionDetached(..., false)` filters an id out of a list, so the event
// arriving alongside the window's own `tauri://destroyed` re-dock (the pre-existing backstop) is harmless.
import { useEffect } from "react";
import { useAppStore } from "@/store";
import { onDockBack } from "@/shared/lib/core/dockBack";

/** Install the dock-back listener. Main window only — a detached window must not re-dock its own page. */
export function useDockBack(enabled: boolean): void {
  const setSectionDetached = useAppStore((s) => s.setSectionDetached);
  useEffect(() => {
    if (!enabled) return;
    let unlisten: (() => void) | undefined;
    let cancelled = false;
    void onDockBack(({ page, section }) => setSectionDetached(page, section, false)).then((fn) => {
      // The listener resolves asynchronously; if the effect already tore down, drop it immediately rather
      // than leaking a subscription onto an unmounted shell.
      if (cancelled) fn();
      else unlisten = fn;
    });
    return () => { cancelled = true; unlisten?.(); };
  }, [enabled, setSectionDetached]);
}

// useDockEntrance (#2905) — the session dock's ENTRANCE GROW. Replaces the CSS slide/fade
// (`session-dock-in`, #2837), which animated only transform/opacity: it never changed layout size, so it
// never resized the xterm and needed a fragile post-animation "settle fit". This animates the dock's REAL
// height up into place via the caller's `useDragResize` setter, so the height change itself drives the
// terminal's ResizeObserver fit — no transform, no settle hack.
//
// Runs before paint (useLayoutEffect) so the grow starts small with no full-height flash, and steps by a
// frame COUNT rather than wall-clock so the synchronous `requestAnimationFrame` stub in tests terminates.
// A reduced-motion viewer jumps straight to the resting height.
import { useLayoutEffect } from "react";

/** easeOutCubic — fast start, gentle settle. */
const ease = (x: number): number => 1 - Math.pow(1 - x, 3);
/** Frames the grow spans (~340ms at 60fps). */
const FRAMES = 20;

/**
 * Animate `setSize` from a fraction of `target` up to `target` once, on mount — the dock entrance grow.
 * `setSize` is the `useDragResize` setter (unclamped) and `target` is the resting dock height (px).
 */
export function useDockEntrance(setSize: (n: number) => void, target: number): void {
  useLayoutEffect(() => {
    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches ?? false;
    const from = Math.round(target * 0.35);
    if (reduce || from >= target || typeof requestAnimationFrame !== "function") {
      setSize(target);
      return;
    }
    setSize(from); // before paint (useLayoutEffect) → the grow starts small, no full-height flash
    let frame = 0;
    let raf = 0;
    let cancelled = false;
    const step = () => {
      if (cancelled) return;
      frame += 1;
      const p = Math.min(1, frame / FRAMES);
      setSize(p >= 1 ? target : Math.round(from + (target - from) * ease(p)));
      if (p < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => { cancelled = true; cancelAnimationFrame(raf); };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps -- run once on mount
}

// useDraft (#1824) — the selection + draft-editor state every list+detail surface hand-rolls.
// One `selectedId`/`draft` pair drives a `<Pane>`: selecting an existing item edits it through to
// the store; starting a draft edits an in-memory copy until committed. Pairs with `<Pane>`.
//
//   const d = useDraft<Skill>({ items: skills, newDraft, onUpdate: updateSkill, onCreate });
//   d.selected   // draft ?? items.find(selectedId)   — the item the pane is editing (or null)
//   d.isDraft    // editing an uncommitted new item
//   d.select(id) // open an existing item (clears any draft)
//   d.startDraft()       // begin a new item (requires `newDraft`)
//   d.patch(partial)     // draft → in-memory merge; existing → onUpdate(id, partial)
//   d.commit()           // draft → onCreate(draft) then select the new id (requires `onCreate`)
//   d.close()            // clear selection + draft
import { useCallback, useState } from "react";

export interface UseDraftOptions<T extends { id: string }> {
  /** The live list of committed items (from the store). */
  items: T[];
  /** Factory for a fresh draft (with a sentinel id). Omit for selection-only surfaces. */
  newDraft?: () => T;
  /** Patch an existing committed item in the store. */
  onUpdate: (id: string, patch: Partial<T>) => void;
  /** Commit a draft → returns the new item's id. Required for `startDraft`/`commit`. */
  onCreate?: (draft: T) => string;
}

export interface Draft<T extends { id: string }> {
  selectedId: string | null;
  /** The draft, else the selected committed item, else null. */
  selected: T | null;
  isDraft: boolean;
  select: (id: string | null) => void;
  startDraft: () => void;
  patch: (patch: Partial<T>) => void;
  commit: () => void;
  close: () => void;
}

export function useDraft<T extends { id: string }>({ items, newDraft, onUpdate, onCreate }: UseDraftOptions<T>): Draft<T> {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [draft, setDraft] = useState<T | null>(null);

  const existing = selectedId ? items.find(i => i.id === selectedId) ?? null : null;
  const selected = draft ?? existing;
  const isDraft = !!draft;

  const select = useCallback((id: string | null) => { setDraft(null); setSelectedId(id); }, []);

  const startDraft = useCallback(() => {
    if (!newDraft) return;
    setSelectedId(null);
    setDraft(newDraft());
  }, [newDraft]);

  const patch = useCallback((p: Partial<T>) => {
    // Draft edits merge in memory (pure functional update); existing items patch through to the store.
    if (draft) setDraft(d => (d ? { ...d, ...p } : d));
    else if (selectedId) onUpdate(selectedId, p);
  }, [draft, selectedId, onUpdate]);

  const commit = useCallback(() => {
    if (!draft || !onCreate) return;
    const id = onCreate(draft);
    setDraft(null);
    setSelectedId(id);
  }, [draft, onCreate]);

  const close = useCallback(() => { setDraft(null); setSelectedId(null); }, []);

  return { selectedId, selected, isDraft, select, startDraft, patch, commit, close };
}

import { useCallback, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";
import { clamp } from "@/shared/lib/core/math";

interface DragResizeOptions {
  /** Starting size in px. */
  initial: number;
  /** Lower bound in px. */
  min: number;
  /** Upper bound in px. */
  max: number;
  /** Which axis the handle drags along. */
  axis: "x" | "y";
  /**
   * Invert the delta. Use when the resized panel sits *after* the handle along
   * the axis (e.g. a right-hand panel grows as the pointer moves left).
   */
  invert?: boolean;
}

/**
 * Drag-to-resize state for a splitter handle. Spread `handleProps` onto the
 * divider element; `size` is the live, clamped dimension to apply to the panel.
 *
 * Uses pointer capture on the handle so the drag keeps tracking even when the
 * cursor leaves the thin divider — no global listeners to register or clean up.
 */
export function useDragResize({ initial, min, max, axis, invert = false }: DragResizeOptions) {
  const [size, setSize] = useState(() => clamp(initial, min, max));
  // Pointer position + panel size captured at drag start; null when not dragging.
  const start = useRef<{ pos: number; size: number } | null>(null);

  const onPointerDown = useCallback((e: ReactPointerEvent) => {
    e.preventDefault();
    (e.currentTarget as Element).setPointerCapture?.(e.pointerId);
    start.current = { pos: axis === "x" ? e.clientX : e.clientY, size };
  }, [axis, size]);

  const onPointerMove = useCallback((e: ReactPointerEvent) => {
    if (!start.current) return;
    const cur = axis === "x" ? e.clientX : e.clientY;
    const delta = (cur - start.current.pos) * (invert ? -1 : 1);
    setSize(clamp(start.current.size + delta, min, max));
  }, [axis, invert, min, max]);

  const onPointerUp = useCallback((e: ReactPointerEvent) => {
    start.current = null;
    (e.currentTarget as Element).releasePointerCapture?.(e.pointerId);
  }, []);

  return { size, setSize, handleProps: { onPointerDown, onPointerMove, onPointerUp } };
}

import { useState, useCallback } from "react";

/** useExpandable — Set-based expand/collapse (toggle-membership) state. Replaces the hand-rolled
 *  `useState<Set<string>>` + toggle that every expandable list (focused bodies, blueprint stages,
 *  scan entities, …) re-declares. `toggle(id)` flips membership; `isOpen(id)` reads it; `open` and
 *  `setOpen` are exposed for direct use. */
export function useExpandable(initial?: Iterable<string>) {
  const [open, setOpen] = useState<Set<string>>(() => new Set(initial));
  const toggle = useCallback((id: string) => {
    setOpen((s) => {
      const n = new Set(s);
      if (n.has(id)) n.delete(id); else n.add(id);
      return n;
    });
  }, []);
  const isOpen = useCallback((id: string) => open.has(id), [open]);
  return { open, isOpen, toggle, setOpen };
}

// The runtime fault-fix loop actuator (#2265, part of #2258). Polls each live project's runtime-fault
// store (`bsc errors list --unresolved --json`, the errordb #2260) on a slow cadence and, when the
// per-project auto-triage toggle is ON, routes a bounded, deduped set of fixes into that project's
// DIRECTOR pane — which captures + assigns each via the existing coordination emitters (bsc-issue →
// bsc-assign) and resolves it on land. The gate/dedup/rate-limit decisions are the pure
// `planFaultDispatch` (shared/lib/fleet/faultTriage.ts); this is the thin Tauri/React poll+inject layer,
// mounted once in ConsoleWorkspace (stays mounted across screens) beside useDirectorPump / useCoordinator.
// It lives in app/console (not shared/) because it reads the app's pane-identity + director-drive state.
//
// Projects with the toggle OFF (the default) are SURFACE-ONLY here — nothing is dispatched; the fault
// count still shows on the Glance node (useGlanceFaults). A project with no live director pane is also
// effectively surface-only (there's nowhere to route), which is the correct degrade.
//
// INERT since #app-stops-pushing-prompts. Its entire body was a poll that dispatched threshold-crossing runtime faults into the owning lane's pane. The fault store (errordb) is unchanged and the director protocol already tells the director to read it on its own cadence with `bsc errors list --unresolved`.
//
// The export SURVIVES deliberately: this module is registered in graphPlatform/appModules so graph
// RECORDS can import it, and removing the export breaks record compilation at runtime. Inert-but-
// exported is the shape useFleetGate took for the same reason when its launch pump was killed —
// deleting the hook is not the fix, doing nothing is.

/** Does nothing. See the note above. */
export function useFaultTriage(): void {
  // Intentionally empty: no poll, no evaluation, no injection.
}

// useFleetDirectorBridge (#architect-creates-a-director-with-discovery) — apply a
// `bsc fleet director new` request and ACK it.
//
// THE ROUND TRIP
//   bsc fleet director new <key> → request file → Rust watcher (resolves the project, refuses a live
//   director, seeds prompts/director-kickoff.md) → `bsc://fleet-director` → HERE → fleetStartProject
//   → `fleet_director_ack`
//
// A thin adapter: the DECISION lives in `fleetDirectorBridge.ts`, unit-testable without Tauri.
//
// THIS IS NOT AN INJECTION PATH. The director's context arrives as its KICKOFF DOC, written to the hub
// before the launch reads it — the same way every fleet director has always received one. Nothing is
// typed into a running session, and `injectCallers.test.ts` stays green on its empty set.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { log } from "@/shared/lib/core/log";
import { applyDirectorNew, type DirectorRequest, type DirectorAck } from "@/app/fleetDirectorBridge";

/** Listen for `bsc://fleet-director` and launch it. Mounted once by the shell. */
export function useFleetDirectorBridge(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<DirectorRequest>("bsc://fleet-director", (e) => {
      const req = e.payload;
      let ack: DirectorAck;
      try {
        ack = applyDirectorNew(req, {
          // Read off a LIVE getState, not a captured snapshot — zustand hands out a new object per
          // update, so a stale closure could launch against an older tab list.
          fleetStartProject: (name, fleet, key, paths) =>
            useAppStore.getState().fleetStartProject(name, fleet, key, paths),
        });
      } catch (err) {
        ack = {
          id: req.id,
          error: `fleet director threw: ${err instanceof Error ? err.message : String(err)}`,
          created: false,
        };
        log.error(`fleet director ${req.id} threw: ${String(err)}`);
      }
      void invoke("fleet_director_ack", { ack: { ...ack, id: req.id } }).catch((e2) => {
        // Nothing left to do — the caller will time out. Log it so the cause isn't a mystery.
        log.error(`fleet_director_ack failed for ${req.id}: ${String(e2)}`);
      });
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}

// The launch pump (#3931 slice 3) — start a HELD stream once its upstreams land.
//
// The gate (streamGate.ts) decides at resume time which streams may start; without a pump the held ones
// would stay held until the user pressed Resume again. This closes the loop: when the evidence changes,
// re-evaluate and launch whatever just became ready.
//
// It is EVENT-DRIVEN on the coordination log, not polled. A worker finishing emits `bsc-maintain`
// (#1957) and the director's merge/close emits its own line, so every transition that can release a
// downstream stream writes to that log first — which `useLogStream("coord", …)` already surfaces for
// free. That matters: the alternative (polling `fleet_landed_streams`) is a git subprocess per repo per
// tick, and this app is already spawn-bound (#3871). The pump therefore costs ONE extra git probe per
// coord-log CHANGE, and nothing at all while the fleet is quiet.
//
// It never parks anything and never wakes a running session — the only action it can take is to launch a
// stream that was never started, which is exactly what #1039 left room for.

// The pump's own imports (the coord read, the landed-evidence probes, the partition) went with its body
// when it was disabled — see `useFleetGate` below. The PURE core above keeps only what it needs, so the
// helpers and their tests survive for whoever re-enables this.
import type { GateStream } from "@/shared/lib/fleet/streamGate";

/** Launch the streams that just became ready for one project. Injected so the pump is testable. */
export type GateLauncher = (projectKey: string) => Promise<unknown>;

/**
 * Which projects the pump should evaluate: those with a fleet roster in the store. A project with no
 * roster has never launched, so there is nothing to release. Pure.
 */
export function gatedProjects(fleetPaneStreams: Record<string, unknown>): string[] {
  const keys = new Set<string>();
  for (const paneId of Object.keys(fleetPaneStreams)) {
    const key = paneId.split(":")[0];
    if (key) keys.add(key);
  }
  return [...keys];
}

/**
 * Stream ids the pump should launch: every READY stream that isn't quarantined.
 *
 * #3971 — this used to also subtract "live" panes, which broke recovery at exactly the moment it was
 * needed. The liveness signal was tab membership (`in a tab && !ended && !disabled`), so at boot every
 * persisted pane counted as live — including the 25 that had come up as BARE SHELLS (`init=<none>`,
 * `LaunchPlan::None`, no agent). The pump skipped them as already-running and released 3 streams
 * against a fleet with 13 dependency-free roots.
 *
 * That definition is right where it came from — Glance's node colouring and #3954's warden scoping
 * both ask "does a session cell exist?" — and wrong here, where the question is "is an AGENT running?".
 * A bare shell answers no.
 *
 * Rather than teach the pump to detect a bare shell, drop the filter: `resumeProject.ts` settled this
 * in #3923 — "a live pane is safe to include in the relaunch: `pty_create` reconnects to an existing
 * session and returns before spawning, so it never re-sends `claude --continue` to a running agent."
 * The pump's actuator IS `resumeProjectFleet`, so it inherits that guarantee, and the caution I added
 * had already been deliberately removed from that path.
 *
 * Repeat-firing is owned by the caller's `lastFired` fingerprint, which is the honest mechanism for it
 * — not a liveness proxy that is wrong precisely when recovery matters. Quarantine still excludes: a
 * quarantined worker is surfaced, never relaunched (#3916). Pure.
 */
export function newlyLaunchable(
  ready: readonly GateStream[],
  projectKey: string,
  quarantined: Record<string, unknown>,
): string[] {
  return ready.map((s) => s.id).filter((id) => !quarantined[`${projectKey}:${id}`]);
}

/**
/**
 * DISABLED (#fleet-gate-stops-launching-on-its-own). Mounted, and does nothing.
 *
 * WHAT IT USED TO DO. Mounted once from the `consolepage` record, it re-evaluated each project's
 * dependency gate on every coord-log change and called `launch` — `resumeProjectFleet` — for any
 * project with a newly-released stream.
 *
 * WHY IT IS OFF. `useLogStream` READS ON MOUNT, and `lastFired` is a fresh ref each app run, so the
 * first evaluation could not be deduped against anything and always fired. Starting the app therefore
 * relaunched whole fleets: measured in the process table seconds after boot as
 * `claude --model sonnet --continue "You are the OPNsense adapter worker…"` — a fleetStartProject
 * kickoff, not a reconnect — with matching bursts of 6 and 13 panes in activity.log. Both of this
 * machine's projects arm it (37 of 38 and 27 of 40 streams carry `dependsOn`), and `planFleet` +
 * `fleetPaneStreams` are persisted, so the gate is loaded and ready the moment the app opens.
 *
 * The header above used to claim "the only action it can take is to launch a stream that was never
 * started". Its actuator relaunches the WHOLE fleet, and for any pane whose PTY did not survive the
 * app close that is a genuine cold start.
 *
 * NOTHING IS STRANDED. A user-initiated Resume still partitions by the SAME dependency gate
 * (`resumeProjectFleet` → `streamGate`), so a held stream is released the moment the user asks for
 * the fleet — it just is not released for them while they are not looking.
 *
 * Disabled rather than deleted, and the signature is kept, so the `consolepage` record's call site
 * (`useFleetGate(fleetGateLaunch)`) needs no edit and re-enabling is restoring one body. If it ever
 * comes back it must NOT act on the mount read — a gate release is an EVENT, and replaying it at boot
 * is the same defect the coordinator's freshness window had.
 *
 * @param _launch the actuator, retained for the signature; never called.
 */
export function useFleetGate(_launch: GateLauncher): void {
  // Intentionally empty: no subscription, no evaluation, no launch.
}

// Fleet GitHub-derived analytics (#415): throughput, merge queue, time-to-land,
// aggregated across the fleet's repos via the ETag-cached githubRequest. Pure
// mapping is in lib/fleetGithub; this is the fetch orchestration.
import { useState, useEffect } from "react";
import { githubRequest, isGithubAuthError } from "@/shared/lib/github/github";
import { useAppStore } from "@/store";
import {
  mapThroughput, mapMergeQueue, mapTimeToLand, deriveThroughputKpis,
  type ThroughputSlice, type MergeQueueRow, type FleetThroughputKpis,
  type GhIssueItem, type GhStatusState,
} from "@/shared/lib/github/fleetGithub";
import type { GhPull } from "@/shared/lib/github/repoPulseLive";

const WINDOW_DAYS = 14;
/** Cap on open PRs we fetch a CI status for (one call each). */
const STATUS_CAP = 12;

/** A PR with the head sha we need for the combined-status call. */
interface GhPullFull extends GhPull { head: { ref: string; sha: string } }

export interface FleetGithub {
  throughput: ThroughputSlice;
  mergeQueue: MergeQueueRow[];
  timeToLand: Array<{ label: string; v: number }>;
  medianLandH: number;
  kpis: FleetThroughputKpis;
  loading: boolean;
  error: string | null;
  /** how many repos were aggregated. */
  repoCount: number;
}

const EMPTY: FleetGithub = {
  throughput: { labels: [], landed: [], merged: [] },
  mergeQueue: [], timeToLand: [], medianLandH: 0,
  kpis: { landedToday: 0, prsMergedWeek: 0, avgLandH: 0 },
  loading: false, error: null, repoCount: 0,
};

export function useFleetGithub(repos: string[], refreshNonce = 0): FleetGithub {
  const githubToken = useAppStore(s => s.githubToken);
  const [data, setData] = useState<FleetGithub>(EMPTY);
  const key = repos.join(",");

  useEffect(() => {
    if (!githubToken || repos.length === 0) { setData(EMPTY); return; }
    let cancelled = false;
    setData(d => ({ ...d, loading: true, error: null }));

    (async () => {
      try {
        const since = new Date(Date.now() - WINDOW_DAYS * 86_400_000).toISOString();
        const get = <T,>(path: string, fallback: T): Promise<T> =>
          githubRequest<T>(path).catch((e) => { if (isGithubAuthError(e)) throw e; return fallback; });

        // Pulls (all states) + recently-closed issues, per repo.
        const perRepo = await Promise.all(repos.map(async slug => {
          const [pulls, issues] = await Promise.all([
            get<GhPullFull[]>(`repos/${slug}/pulls?state=all&per_page=100&sort=updated&direction=desc`, []),
            get<GhIssueItem[]>(`repos/${slug}/issues?state=closed&per_page=100&since=${since}`, []),
          ]);
          return { slug, pulls, issues };
        }));
        if (cancelled) return;

        const allPulls: GhPull[] = perRepo.flatMap(r => r.pulls);
        const allIssues: GhIssueItem[] = perRepo.flatMap(r => r.issues);

        // Open PRs → fetch combined CI status for the head sha (bounded).
        const open = perRepo.flatMap(r => r.pulls.filter(p => p.state === "open").map(p => ({ pr: p, repo: r.slug })));
        const capped = open.slice(0, STATUS_CAP);
        const statuses = await Promise.all(capped.map(({ pr, repo }) =>
          get<{ state: GhStatusState }>(`repos/${repo}/commits/${pr.head.sha}/status`, { state: null as unknown as GhStatusState })
            .then(s => ({ pr, repo, status: s?.state ?? null }))));
        if (cancelled) return;

        const now = new Date();
        const throughput = mapThroughput(allPulls, allIssues, WINDOW_DAYS, now);
        const live: FleetGithub = {
          throughput,
          mergeQueue: mapMergeQueue(statuses),
          timeToLand: mapTimeToLand(allPulls),
          medianLandH: deriveThroughputKpis(throughput, allPulls, now).avgLandH,
          kpis: deriveThroughputKpis(throughput, allPulls, now),
          loading: false, error: null, repoCount: repos.length,
        };
        if (!cancelled) setData(live);
      } catch (e) {
        if (cancelled) return;
        setData({ ...EMPTY, error: isGithubAuthError(e) ? "GitHub authorization failed — reconnect in Settings." : "Couldn't load fleet activity from GitHub." });
      }
    })();

    return () => { cancelled = true; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, githubToken, refreshNonce]);

  return data;
}

// useFleetHeld (#3931 slice 4) — which of a drilled project's streams the dependency gate is holding,
// so the Glance node can SAY SO instead of rendering as an anonymous dark node.
//
// Same probe the resume runs (`fleet_landed_streams` + the coord `maintaining` list + plan.db issues),
// evaluated read-only: this hook never launches anything. It is scoped to the DRILLED project and
// re-runs on coord-log changes, so a stream that gets released stops being marked held without a poll.

import { useState } from "react";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { bscJsonShared } from "@/shared/lib/core/bscShared";

/** How stale a plan read this hook accepts (#five-callers-one-spawn-for-the-same-plan-read). Matched to
 *  the other plan readers' 20s cadence so the five of them collapse onto ONE process launch per window;
 *  a held/blocked signal minutes old would be stale, seconds old is not. */
const HELD_TTL_MS = 20_000;
import { useLogStream } from "@/shared/hooks/useLogStream";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import { doneIssueRefs } from "@/shared/lib/fleet/streamCompletion";
import { resolveClosedRefs } from "@/features/glance/lib/fleetIssueState";
import { partitionByDeps, heldReason, sessionDoneStreams, type GateStream, type LandedEvidence } from "@/shared/lib/fleet/streamGate";
import type { PlanIssue } from "@/features/planner/issues/planIssues";

/** Stream id → why it is held. Empty when nothing is gated (the common case once a fleet is flowing). */
export type HeldMap = Record<string, { reason: string; deadlocked: boolean }>;

/**
 * Held streams for `projectKey`. Returns an empty map when there is no project, no fleet, or no stream
 * declares a `dependsOn` — the last check is what keeps this off the git probe entirely for the many
 * fleets that have no dependency graph at all.
 */
export function useFleetHeld(projectKey: string | null, streams: readonly GateStream[] | undefined): HeldMap {
  const [held, setHeld] = useState<HeldMap>({});
  const hasDeps = !!streams?.some((s) => (s.dependsOn ?? []).length > 0);

  useLogStream("coord", async (isCancelled) => {
    if (!projectKey || !streams || !hasDeps) { setHeld({}); return; }
    const [merged, dbIssues, coord, closedRefs] = await Promise.all([
      safeInvoke<string[]>("fleet_landed_streams", { projectKey }, []),
      bscJsonShared<PlanIssue[]>(projectKey, ["plan", "list", "--full", "--json"], [], HELD_TTL_MS),
      readCoordState(),
      // #4103: plan.db's issue rows are empty for a hand-assembled fleet, so the done-set was empty and
      // the gate held streams whose upstreams had actually landed. GitHub is the other evidence source.
      resolveClosedRefs(streams),
    ]);
    if (isCancelled()) return;
    const evidence: LandedEvidence = {
      doneIssues: new Set([...doneIssueRefs(dbIssues ?? []), ...closedRefs]),
      mergedBranches: new Set(merged ?? []),
      // A failed coord read contributes no session evidence rather than fabricating it — the same rule
      // the resume and the pump follow. Over-reporting held is safe here (it is display only); claiming
      // a stream landed when the log could not be read is not.
      sessionDone: sessionDoneStreams(coord?.state.maintaining ?? [], projectKey),
    };
    const { held: h } = partitionByDeps(streams, evidence);
    setHeld(Object.fromEntries(h.map((x) => [x.streamId, { reason: heldReason(x), deadlocked: x.deadlocked }])));
  }, [projectKey, hasDeps, streams?.length]);

  return held;
}

// The drilled fleet's issue states, overlaid from GitHub (#4102).
//
// Scoped to the DRILLED project and batched into ONE query per repo (see `issueStateQuery.ts`), so the
// cost is bounded by what the user is actually looking at and stops entirely when they leave the drill
// — the same discipline `useStreamProgress` documents.
//
// ── LOCAL-FIRST, NEVER TOKEN-GATED (#2444) ──────────────────────────────────────────────────────
// With no token this returns an empty map and NOTHING breaks: issue OWNERSHIP comes from the fleet
// plan, so the plan screen still lists every worker's issues and the progress bar simply shows no
// completions yet. The overlay adds state; it is never the reason the list is empty.
import { useMemo } from "react";
import { githubGraphql } from "@/shared/lib/github/github";
import { useGithubQuery } from "@/shared/lib/github/useGithubQuery";
import { groupRefsByRepo, buildIssueStateQuery, parseIssueStates, closedRefs } from "@/features/glance/lib/issueStateQuery";

/** Issue open/closed moves at human speed — a worker closing one is a minutes-scale event. Served from
 *  the backend's ETag cache within this window, so a re-drill costs no network call at all. */
const MAX_AGE_SECS = 120;

export interface FleetIssueState {
  /** ref (unprefixed, e.g. `3898`) → closed. Empty while loading, without a token, or on error. */
  states: Map<string, boolean>;
  /** Just the closed refs — what `fleetPlanProgress` consumes. */
  done: Set<string>;
  loading: boolean;
  /** Set when the overlay could not be fetched. The caller still renders the list; this only explains
   *  absent state chips, so a disconnected user is told why rather than shown a silent zero. */
  error: string | null;
}

/**
 * Resolve open/closed for every issue ref owned by `streams`.
 *
 * `streams` should be the drilled project's fleet (or empty when not drilled — then nothing is fetched).
 */
export function useFleetIssueState(
  streams: readonly { repo?: string; issues?: readonly string[] }[],
): FleetIssueState {
  // The query is derived, not stored, and keyed by its own text: two renders yielding the same refs
  // produce the same string, so `useGithubQuery` does not refetch on every parent re-render.
  const query = useMemo(() => buildIssueStateQuery(groupRefsByRepo(streams)), [streams]);

  const { data, loading, error } = useGithubQuery<unknown>(
    () => githubGraphql<unknown>(query!, null, { maxAgeSecs: MAX_AGE_SECS }),
    [query],
    // A fleet with no addressable refs must not spend a request — nor show a spinner for an answer
    // that would be empty either way.
    !!query,
  );

  return useMemo(() => {
    const states = parseIssueStates(data);
    return { states, done: closedRefs(states), loading, error };
  }, [data, loading, error]);
}

// Live Fleet view model (#412). Reads the running fleet from the store
// (`fleetPaneStreams` roster + live `paneStatus`) and polls the coordination log
// (`read_coord_log` → `ingestCoordLog`) for blocked/asking/waiting, then assembles
// the worker roster via the pure mappers in lib/fleetLive.
import { useMemo } from "react";
import { useAppStore } from "@/store";
import { useCoordLog } from "@/shared/lib/fleet/useCoordLog";
import { buildLiveWorkers, deriveFleetKpis, statusCounts, type LiveWorker, type FleetKpis } from "@/shared/lib/fleet/fleetLive";

export interface UseFleetLive {
  workers: LiveWorker[];
  kpis: FleetKpis;
  counts: Partial<Record<LiveWorker["status"], number>>;
  hasFleet: boolean;
}

export function useFleetLive(): UseFleetLive {
  const fleetPaneStreams = useAppStore(s => s.fleetPaneStreams);
  const paneStatus       = useAppStore(s => s.paneStatus);
  const tabs             = useAppStore(s => s.tabs);
  const disabledPanes    = useAppStore(s => s.disabledPanes);
  const profiles         = useAppStore(s => s.agentProfiles);

  // The coordination log is the fleet's own activity feed (blocked/asking/waiting,
  // landed/merged). Polled while the screen is mounted — no store wiring needed.
  const { state: coord } = useCoordLog({ limit: 1000 });

  const workers = useMemo(
    () => buildLiveWorkers({ fleetPaneStreams, paneStatus, coord, tabs, disabledPanes, profiles }),
    [fleetPaneStreams, paneStatus, coord, tabs, disabledPanes, profiles],
  );
  const kpis = useMemo(() => deriveFleetKpis(workers), [workers]);
  const counts = useMemo(() => statusCounts(workers), [workers]);

  return { workers, kpis, counts, hasFleet: workers.length > 0 };
}

// useFleetWakeBridge (#4101) — apply a `bsc fleet wake` request to the store and ACK it.
//
// WHY THIS EXISTS
// `bsc fleet list` (#4098) gave the director eyes on its workers; nothing gave it the one lever it
// actually needs — waking a parked one. A director that spots a stopped worker with open issues on its
// stream could only tell the user about it.
//
// THE ROUND TRIP
//   bsc fleet wake → request file → Rust watcher → `bsc://fleet-wake` → HERE → store → `fleet_wake_ack`
//
// The ack is load-bearing rather than ceremony: the wake KILLS the PTY before relaunching (see
// `applyWake`), so a wake that silently failed would leave a dead worker behind a caller that believes
// it is running. That is #4025 exactly. So this ALWAYS acks — success or a stated error.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { log } from "@/shared/lib/core/log";
import { applyWake, type WakeRequest, type WakeAck } from "@/app/fleetWakeBridge";

/**
 * Listen for `bsc://fleet-wake` and apply it. Mounted once by the shell.
 *
 * A thin adapter: the DECISION lives in `fleetWakeBridge.ts`, unit-testable without Tauri.
 */
export function useFleetWakeBridge(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<WakeRequest & { id: string }>("bsc://fleet-wake", async (e) => {
      const { id, ...req } = e.payload;
      let ack: WakeAck;
      try {
        // Read the action off a LIVE getState, not a captured snapshot: zustand hands out a new object
        // per update, so a stale closure could call a wakePane bound to an older tab list.
        ack = await applyWake(id, req, {
          wakePane: (p, t) => useAppStore.getState().wakePane(p, t),
          // Kill before the bump so the remount spawns instead of reconnecting to a live shell whose
          // agent has exited — the same order `actuateWake` uses. `fireInvoke` swallows the "no such
          // session" case, which is the normal one for an already-reaped pane.
          killPane: async (p) => { await safeInvoke("pty_kill", { paneId: p }, undefined); },
        });
      } catch (err) {
        // A throw here would strand the Rust waiter until its timeout. State it instead.
        ack = { id, error: `fleet wake threw: ${err instanceof Error ? err.message : String(err)}`, woke: false };
        log.error(`fleet wake ${id} threw: ${String(err)}`);
      }
      void invoke("fleet_wake_ack", { ack: { ...ack, id } }).catch((e2) => {
        // Nothing left to do — the caller will time out. Log it so the cause isn't a mystery.
        log.error(`fleet_wake_ack failed for ${id}: ${String(e2)}`);
      });
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}

// useGithubConnect (#1708) — the GitHub connection state machine, extracted out of the
// `ConnectCard` UI in settings/GitHub.tsx. It owns the two ways to connect — a Personal
// Access Token (the always-available fallback) and the OAuth Device Flow (#594) — plus the
// post-auth exchange (`finishConnect`) that turns a validated token into the user + repo
// list and flips the store to connected. The component that consumes this is pure render.
//
// The pure device-flow interpreter + driver lives in @/features/github/lib/githubDeviceFlow
// (`runDeviceFlow` / `mapDevicePoll`); this hook is the React-side wiring around it: the UI
// state, the generation-token cancellation, and the Tauri/store side effects.

import { useEffect, useRef, useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { openUrl } from "@tauri-apps/plugin-opener";
import { useAppStore, type GithubUser, type GithubRepo } from "@/store";
import { clearGithubCache } from "@/shared/lib/github/github";
import {
  runDeviceFlow,
  type DeviceStartInfo,
  type DevicePollResult,
} from "@/shared/lib/github/githubDeviceFlow";

/** Mirror of the backend `DeviceStart` struct (`github_device_start`). */
export type DeviceStart = DeviceStartInfo;

// `project` is required to read AND create GitHub Projects v2 (the Projects page
// + planning publish); without it the API returns "token lacks read:project".
// `gist` lets the app publish blueprints/extensions as gists (#598 M2).
const DEVICE_SCOPE = "repo read:org read:user project gist";

const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

/** Everything the ConnectCard UI needs to render + drive a connection. */
export interface GithubConnect {
  /** PAT input value + setter (controlled input). */
  token: string;
  setToken: (t: string) => void;
  /** A PAT connect (`handleConnect`) is in flight. */
  loading: boolean;
  /** The latest user-facing error from either path, or null. */
  error: string | null;
  /**
   * OAuth client id: `null` until probed; `""` means this build has no OAuth app
   * configured (offer the PAT path only); a non-empty id enables the device flow.
   */
  clientId: string | null;
  /** The active device-flow challenge (code + verification URL), or null. */
  device: DeviceStart | null;
  /** A device flow is starting/running. */
  deviceBusy: boolean;
  /** Validate + connect with the typed PAT. */
  handleConnect: () => Promise<void>;
  /** Start (or restart) the OAuth device flow. */
  handleDeviceConnect: () => Promise<void>;
  /** Abort the in-flight device flow and clear the challenge. */
  cancelDevice: () => void;
}

/**
 * The connection state machine behind the GitHub Settings ConnectCard.
 *
 * Cancellation uses a generation token (`runIdRef`), bumped each time a flow starts or is
 * cancelled, so a stale run never updates the UI and starting over supersedes the previous
 * loop — WITHOUT tying cancellation to unmount. Navigating away does NOT abort an in-flight
 * authorization (#594); the flow runs to completion and `finishConnect`'s store write lands
 * regardless of which screen is shown. (No mounted-ref guard: React 18 ignores setState after
 * unmount, and a mounted-ref stuck false under StrictMode's dev double-mount was itself a bug.)
 */
export function useGithubConnect(): GithubConnect {
  const { setGithubToken, setGithubUser, setGithubRepos, setActiveRepo, setGithubConnected } = useAppStore();

  const [token, setToken] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [clientId, setClientId] = useState<string | null>(null);
  const [device, setDevice] = useState<DeviceStart | null>(null);
  const [deviceBusy, setDeviceBusy] = useState(false);
  const runIdRef = useRef(0);

  useEffect(() => {
    invoke<string>("github_client_id").then(setClientId).catch(() => setClientId(""));
  }, []);

  // Exchange a validated token for the user + repo list and flip to connected.
  async function finishConnect(t: string) {
    // New token (possibly a different account) — drop any cached bodies first.
    await clearGithubCache().catch(() => {});
    const user = await invoke<GithubUser>("github_request", { token: t, path: "user" });
    const repos = await invoke<GithubRepo[]>("github_request", {
      token: t,
      path: "user/repos?per_page=100&sort=updated&affiliation=owner,collaborator,organization_member",
    });
    setGithubToken(t);
    setGithubUser(user);
    setGithubRepos(Array.isArray(repos) ? repos : []);
    if (Array.isArray(repos) && repos.length > 0) {
      setActiveRepo(repos[0].full_name);
    }
    setGithubConnected(true);
  }

  async function handleConnect() {
    const t = token.trim();
    if (!t) return;
    setLoading(true);
    setError(null);
    try {
      await finishConnect(t);
    } catch (e) {
      setError(String(e));
    } finally {
      setLoading(false);
    }
  }

  async function handleDeviceConnect() {
    const myRun = ++runIdRef.current;
    // Apply UI updates only for the current run (a restart bumps runIdRef and supersedes
    // a still-running older loop). finishConnect (the store write) is intentionally NOT
    // guarded — it must land even after navigating away.
    const ui = (fn: () => void) => { if (runIdRef.current === myRun) fn(); };
    ui(() => { setError(null); setDeviceBusy(true); });
    try {
      await runDeviceFlow({
        start: () => invoke<DeviceStart>("github_device_start", { scope: DEVICE_SCOPE }),
        poll: (deviceCode) => invoke<DevicePollResult>("github_device_poll", { deviceCode }),
        sleep,
        // Cancelled only when the user starts a new flow — never on unmount (#594).
        isCancelled: () => runIdRef.current !== myRun,
        onDevice: (start) => {
          ui(() => setDevice(start));
          openUrl(start.verification_uri).catch(() => { /* user can use the shown URL/code manually */ });
        },
        // The store write must complete even if the user navigated away — no ui() guard.
        onSuccess: (tok) => finishConnect(tok),
        onError: (message) => ui(() => { setError(message); setDevice(null); }),
      });
    } catch (e) {
      ui(() => { setError(String(e)); setDevice(null); });
    } finally {
      ui(() => setDeviceBusy(false));
    }
  }

  function cancelDevice() {
    // Bump the generation token so the in-flight flow's isCancelled() trips.
    runIdRef.current++;
    setDevice(null);
    setDeviceBusy(false);
  }

  return {
    token, setToken,
    loading, error,
    clientId, device, deviceBusy,
    handleConnect, handleDeviceConnect, cancelDevice,
  };
}

// useGithubQuery (#1496) — the GitHub fetch orchestration the planner/github screens hand-rolled:
// the `{ data, loading, error }` triple, the token gate, the cancel-guard, and the
// loading/error transitions. The screen-specific PARSE of the response stays in the screen (as a
// useMemo over `data`) — this hook only owns the fetch lifecycle.
//
// Mirrors the established pattern in useRepoPulse / useFleetGithub, generalized to any fetcher.

import { useEffect, useState, type DependencyList } from "react";
import { useAppStore } from "@/store";

export interface GithubQuery<T> {
  data: T | null;
  loading: boolean;
  error: string | null;
}

/**
 * Run `fetcher(token)` whenever `deps` (or the token) change, tracking `{ data, loading, error }`.
 * Skips while `enabled` is false or there's no token — leaving the last result in place, matching
 * the `if (!token || !x) return` gate the screens used. A stale in-flight request never lands
 * (cancel-guard), so rapid dep changes don't clobber the newest result.
 */
export function useGithubQuery<T>(
  fetcher: (token: string) => Promise<T>,
  deps: DependencyList,
  enabled = true,
): GithubQuery<T> {
  const githubToken = useAppStore((s) => s.githubToken);
  const [state, setState] = useState<GithubQuery<T>>({ data: null, loading: false, error: null });

  useEffect(() => {
    if (!githubToken || !enabled) return;
    let cancelled = false;
    setState((s) => ({ ...s, loading: true, error: null }));
    fetcher(githubToken)
      .then((data) => { if (!cancelled) setState({ data, loading: false, error: null }); })
      .catch((e) => { if (!cancelled) setState((s) => ({ ...s, loading: false, error: String(e) })); });
    return () => { cancelled = true; };
    // `fetcher` is intentionally not a dep — callers declare the inputs it closes over via `deps`.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [githubToken, enabled, ...deps]);

  return state;
}

// Data hook for the GitHub summary dashboard (#1644).
//
// Owns the fetch lifecycle (events + contribution calendar + per-repo PRs/languages/
// runs/contributors for the N most-recently-updated repos) and exposes the memoized
// derivations every card renders from. All the React-free shaping lives in
// `lib/githubSummary.ts`; this hook only wires fetch → state → derived view models.

import { useState, useEffect, useMemo } from "react";
import { useAppStore } from "@/store";
import { timeAgo } from "@/shared/lib/core/format";
import { githubRequest, githubGraphql } from "@/shared/lib/github/github";
import { languageStats } from "@/features/github/languageStats";
import type { GHEvent } from "@/shared/lib/github/types";
import {
  SUMMARY_REPO_SAMPLE,
  CONTRIB_QUERY,
  buildHeatmap,
  countMergedPRs,
  buildCrossRepoEvents,
  buildOpenPRs,
  buildContributors,
  buildCiMatrix,
  buildRepoGrid,
  ciPassingPercent,
  type GHPRItem,
  type GHRunItem,
  type GHContrib,
  type RepoData,
  type ContribDay,
} from "@/features/github/lib/githubSummary";

/** Raw fetched state, before the per-card derivations. */
function useGitHubSummaryData() {
  const { githubToken, githubUser, githubRepos } = useAppStore();
  const [loading, setLoading] = useState(false);
  const [events, setEvents] = useState<GHEvent[]>([]);
  const [repoData, setRepoData] = useState<Record<string, RepoData>>({});
  const [contribDays, setContribDays] = useState<ContribDay[]>([]);

  const slugKey = githubRepos.slice(0, SUMMARY_REPO_SAMPLE).map(r => r.full_name).join(",");

  useEffect(() => {
    if (!githubToken || !githubUser) return;
    const login = githubUser.login;
    const slugs = githubRepos.slice(0, SUMMARY_REPO_SAMPLE).map(r => r.full_name);
    if (slugs.length === 0 && !login) return;

    setLoading(true);

    const eventsP = githubRequest<GHEvent[]>(`users/${login}/events?per_page=100`).catch((): GHEvent[] => []);

    const contribP = githubGraphql<{
      viewer: { contributionsCollection: { contributionCalendar: { weeks: Array<{ contributionDays: Array<{ contributionCount: number; date: string; weekday: number }> }> } } }
    }>(CONTRIB_QUERY, null).then(d => {
      const weeks = d?.viewer?.contributionsCollection?.contributionCalendar?.weeks ?? [];
      const days: ContribDay[] = [];
      weeks.forEach(w => w.contributionDays.forEach(cd => days.push({ date: cd.date, weekday: cd.weekday, count: cd.contributionCount })));
      return days;
    }).catch((): ContribDay[] => []);

    const repoPs = slugs.map(slug =>
      Promise.all([
        githubRequest<GHPRItem[]>(`repos/${slug}/pulls?state=open&per_page=20`).catch((): GHPRItem[] => []),
        githubRequest<Record<string, number>>(`repos/${slug}/languages`).catch((): Record<string, number> => ({})),
        githubRequest<{ workflow_runs: GHRunItem[] }>(`repos/${slug}/actions/runs?per_page=30`)
          .catch(() => ({ workflow_runs: [] as GHRunItem[] })),
        githubRequest<unknown>(`repos/${slug}/stats/contributors`)
          .then(d => Array.isArray(d) ? d as GHContrib[] : []).catch((): GHContrib[] => []),
      ])
    );

    Promise.all([eventsP, contribP, ...repoPs]).then(([evts, days, ...rows]) => {
      const evtArr = Array.isArray(evts) ? evts : [];
      const rd: Record<string, RepoData> = {};
      slugs.forEach((slug, i) => {
        const [prs, langs, runsResp, contribs] = rows[i] as [
          GHPRItem[],
          Record<string, number>,
          { workflow_runs: GHRunItem[] },
          GHContrib[],
        ];
        rd[slug] = {
          prs: Array.isArray(prs) ? prs : [],
          langBytes: langs && typeof langs === "object" && !Array.isArray(langs) ? langs : {},
          runs: Array.isArray(runsResp?.workflow_runs) ? runsResp.workflow_runs : [],
          contribs: Array.isArray(contribs) ? contribs : [],
        };
      });
      setEvents(evtArr);
      setContribDays(Array.isArray(days) ? days : []);
      setRepoData(rd);
      setLoading(false);
    }).catch(() => setLoading(false));
  }, [githubToken, githubUser?.login, slugKey]); // eslint-disable-line react-hooks/exhaustive-deps

  return { loading, events, repoData, contribDays };
}

/**
 * The summary's full view model: the fetch state plus every per-card derivation
 * (heatmap, contributors, open PRs, CI matrix, repo grid, language mix, KPIs).
 */
export function useGithubSummary() {
  const githubRepos = useAppStore(s => s.githubRepos);
  const { loading, events, repoData, contribDays } = useGitHubSummaryData();

  const heatmap = useMemo(() => buildHeatmap(contribDays), [contribDays]);
  const totalMerged = useMemo(() => countMergedPRs(events), [events]);
  const crossRepoEvts = useMemo(() => buildCrossRepoEvents(events), [events]);
  const openPRs = useMemo(() => buildOpenPRs(repoData, timeAgo), [repoData]);
  const { totals: langTotals, repoCount: langRepoCount } = useMemo(() => languageStats(repoData), [repoData]);
  const contributors = useMemo(() => buildContributors(repoData), [repoData]);
  const ciMatrix = useMemo(() => buildCiMatrix(githubRepos, repoData), [githubRepos, repoData]);
  const repoGridData = useMemo(() => buildRepoGrid(githubRepos, repoData, events), [githubRepos, repoData, events]);

  // KPIs
  const kpiOpenPRs = Object.values(repoData).reduce((s, rd) => s + rd.prs.length, 0);
  const kpiContribs = contributors.length || "—";
  const kpiCIPassing = ciPassingPercent(githubRepos, repoData);

  return {
    loading,
    githubRepos,
    heatmap,
    totalMerged,
    crossRepoEvts,
    openPRs,
    langTotals,
    langRepoCount,
    contributors,
    ciMatrix,
    repoGridData,
    kpiOpenPRs,
    kpiContribs,
    kpiCIPassing,
  };
}

// useGlanceFaults (#2265) — the unresolved runtime-fault count per project, for the Glance node
// FAULT-health badge. Polls each project's errordb (`bsc errors list --unresolved --json`, #2260) on a
// slow cadence and returns a `{ projectKey → count }` map the workspace merges into the graph nodes.
// Orthogonal to the liveness "live/down" status (#2263): this reads `bsc errors`, that reads
// heartbeats, so the two merge into the node without touching each other.
//
// Degrades to an empty map when a project has no errordb yet (bscJson swallows the reject) — a project
// with zero faults simply shows no badge.
import { useEffect, useRef, useState } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { unresolvedCount, worstFault, type FaultLite } from "@/shared/lib/fleet/faultTriage";

const POLL_MS = 20_000;

interface FaultRow {
  fingerprint: string;
  level: string;
  title: string;
  count: number;
  resolved_at?: number | null;
}

/** The per-project fault summary the health axis reads (#2541): the total unresolved `count`, plus the
 *  worst open fault's `level` (drives the dot colour) and `title` (the bottom-right reason text). */
export interface GlanceFault { count: number; level: FaultLite["level"]; title: string }

/** Unresolved-fault summaries keyed by project plan key. `keys` is the current Glance project set; the
 *  map only carries projects with at least one unresolved fault (absent ⇒ healthy/idle). */
export function useGlanceFaults(keys: string[]): Record<string, GlanceFault> {
  const [counts, setCounts] = useState<Record<string, GlanceFault>>({});
  // Stable join so the poll re-subscribes only when the actual key SET changes, not every render (the
  // parent passes a fresh array each time).
  const keyList = keys.slice().sort();
  const joined = keyList.join("�");
  const keysRef = useRef(keyList);
  useEffect(() => { keysRef.current = keyList; }, [keyList]);

  usePoll(async (isCancelled) => {
    if (isCancelled()) return;
    const targets = keysRef.current;
    if (targets.length === 0) { setCounts({}); return; }
    // #3912: ONE in-process read for the whole set. This was a `Promise.all` of a `bsc errors list`
    // SUBPROCESS per project — at 28 projects on a 20s cadence, ~21 concurrent spawns three times a
    // minute, measured as the single largest consumer of the Tauri command queue (15,806s of invoke
    // time in 72 minutes, p50 8.4s). `src-tauri` already links `errordb`, so the spawns bought nothing.
    // A project absent from the map has no error.db or no open faults — the same "no badge" outcome
    // the per-project read produced by degrading to [].
    const byKey = await safeInvoke<Record<string, FaultRow[]>>("fault_rows_batch", { projectKeys: targets }, {});
    if (isCancelled()) return;
    const entries = targets.map((key): [string, GlanceFault | null] => {
      const faults: FaultLite[] = (byKey?.[key] ?? []).map((r) => ({
        fingerprint: r.fingerprint,
        level: r.level === "warn" || r.level === "fatal" ? r.level : "error",
        title: r.title,
        count: r.count,
        resolvedAt: r.resolved_at ?? null,
      }));
      const worst = worstFault(faults);
      return [key, worst ? { count: unresolvedCount(faults), level: worst.level, title: worst.title } : null];
    });
    setCounts(Object.fromEntries(entries.filter((e): e is [string, GlanceFault] => e[1] !== null)));
  }, POLL_MS, [joined]); // re-subscribe when the key SET changes (via the stable join)

  return counts;
}

// useGraphPage (#2719) — the small composition every graph PAGE hand-rolled: create a
// `useGraphViewport` and then re-fit it (deferred to the next animation frame) whenever the framed
// graph changes. It bundles the viewport plus the fit-on-key effect so a page only supplies the
// world, the fit key, and (optionally) the viewport options.
//
// ⚠️ THE FIT KEY MUST NOT BE THE POLLED GRAPH MODEL. Pass a STABLE value that changes ONLY when the
// graph should genuinely re-fit — a kit id, a drill target, a page name. Do NOT key on the graph
// `model`/`data` object itself: it gets a fresh reference on every data poll (liveness/fault/stall
// overlays recompute it), so keying on it re-fits every few seconds and wipes out the user's pan/zoom
// (#2554). `fit` reads the current world via a ref inside the viewport, so a deferred fit still
// frames the freshly-swapped graph even though the key, not the world, is the dependency.
//
// Bespoke fit logic stays in the page (Teams' saved-zoom restore, Glance's page-visibility guard,
// any centerOn focus move) — this hook owns only the plain rAF fit-on-key path.
import { useEffect } from "react";
import { useGraphViewport, type GraphViewport, type GraphViewportOpts } from "@/shared/ui/layouts/useGraphViewport";

/**
 * Create a graph viewport for `world` and rAF-fit it on mount and whenever any value in `fitKey`
 * changes. Returns the full {@link GraphViewport} (pan/zoom controls, `fit`, `centerOn`, …).
 *
 * @param world  Nominal world box for the viewport.
 * @param fitKey Dependency list whose changes trigger a deferred re-fit — see the model-keying trap above.
 * @param opts   Viewport options (min/max zoom, fit padding, content bounds provider).
 */
export function useGraphPage(
  world: { w: number; h: number },
  fitKey: React.DependencyList,
  opts?: GraphViewportOpts,
): GraphViewport {
  const vp = useGraphViewport(world, opts);
  const { fit } = vp;
  useEffect(() => {
    const id = requestAnimationFrame(() => fit());
    return () => cancelAnimationFrame(id);
    // fit is stable per-viewport; the caller-supplied fitKey drives re-fits.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [...fitKey, fit]);
  return vp;
}

// Shared graph viewport (#2208, epic #2197 slice 2) — the canonical pan+zoom hook for every graph
// canvas (Org designer, Glance network, and future graphs). Pan+zoom is a CSS `transform:
// translate() scale()` on a "world" layer, with zoom-about-cursor. This replaced Org's older
// scroll-based usePanZoom; the transform model is cheaper (one composited layer) and keeps the point
// under the cursor fixed without depending on scroll geometry. Node-drag stays local to each canvas
// (it needs node identity + a live preview); this hook owns only the viewport.
//
// A press that starts on a `[data-node]` element does NOT pan — the node owns that gesture — so a
// canvas with draggable nodes (Org) and one with static nodes (Glance) share the same hook.
import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { clamp } from "@/shared/lib/core/math";

export interface GraphView { tx: number; ty: number; scale: number }

/** A design-space box (top-left + size) — the content bounds a graph frames on fit/restore. */
export interface GraphBox { x: number; y: number; w: number; h: number }

export interface GraphViewportOpts {
  /** Min zoom. Default 0.28. */
  min?: number;
  /** Max zoom. Default 2.6. */
  max?: number;
  /** Viewport padding (px per side) left around the world when fitting. Default 70. */
  fitPad?: number;
  /** Cap on the scale `fit()` will zoom UP to (so a small graph isn't blown up). Default 1.05. */
  maxFitScale?: number;
  /** Optional provider of the ACTUAL content bounding box (design-space), read live at fit/restore time.
   *  When set, `fit()` and `zoomToCentered()` frame THIS box instead of the nominal world — so a graph
   *  whose nodes fill only part of (or overflow) the world box is still centered on the nodes, not on
   *  empty canvas (#2673). Return null to fall back to the world box (e.g. an empty graph). */
  contentBounds?: () => GraphBox | null;
}

/** The value returned by useGraphViewport — also the prop the GraphCanvas template + ZoomControls take. */
export interface GraphViewport {
  view: GraphView;
  /** Ref callback for the viewport (clipping) element — the wheel/pan target. */
  setVp: (el: HTMLDivElement | null) => void;
  /** Backdrop mousedown → pan. Bails on a `[data-node]` press (the node owns its gesture). */
  onCanvasDown: (e: React.MouseEvent) => void;
  /** Fit the whole world in the viewport and center it. */
  fit: () => void;
  /** Pan so world point (wx,wy) sits at the viewport center, KEEPING the current zoom — the
   *  least-disruptive "focus this node" move (Design Studio AI live-focus, #2525). No-op before the
   *  viewport element mounts. */
  centerOn: (wx: number, wy: number) => void;
  /** Zoom by a factor around the viewport center (the +/- buttons). */
  zoomBy: (factor: number) => void;
  /** Set an absolute zoom around the viewport center (e.g. Glance's zoom-to-100% snap). */
  zoomTo: (scale: number) => void;
  /** Set an absolute zoom with the world re-centered — the correct "restore a saved zoom" move, since
   *  it never depends on the pre-restore pan (which is the origin on a fresh mount). No-op before the
   *  viewport element mounts. (#2545) */
  zoomToCentered: (scale: number) => void;
  /** True during a pan-drag so the click that ends it doesn't select a node/edge. */
  dragMoved: React.MutableRefObject<boolean>;
  /** Pan by a screen-space delta (px) — for a pan gesture driven from OUTSIDE the viewport element
   *  (e.g. an iframe forwarding a non-interactive drag, #3190), where `onCanvasDown` never sees a
   *  mousedown of its own. */
  panBy: (dx: number, dy: number) => void;
  /** Zoom by `factor` (scale × factor, clamped) about a PAGE point (clientX,clientY) — for a wheel gesture
   *  forwarded from OUTSIDE the viewport (#3190). Same math as the native wheel: converts the page point to
   *  viewport-relative via the live bounding rect, so the anchor is exact regardless of the forwarder's
   *  own geometry. */
  zoomAtClient: (factor: number, clientX: number, clientY: number) => void;
  /** Ref callback for the WORLD LAYER element — the pan drag writes its transform directly (#4140).
   *  Attach it alongside {@link worldTransform}; the two apply the same string. */
  setWorld: (el: HTMLElement | null) => void;
  /** The `transform` style to spread onto the world layer. */
  worldTransform: React.CSSProperties;
  /** The viewport (clipping) element, for a consumer that must MEASURE it — viewport culling needs the
   *  visible size to invert the transform into world coords.
   *
   *  Read it in an EFFECT, never during render: the react-compiler rule forbids ref access on the render
   *  path, and the value is meaningless there anyway (the element has no size until it is laid out).
   *  Exposed rather than duplicated because this hook already owns the element — a consumer attaching a
   *  second ref to the same node would be a second source of truth for one measurement. */
  vpEl: React.MutableRefObject<HTMLDivElement | null>;
}

/**
 * Zoom `v` to scale `ns` (clamped to [min,max]) while keeping the world point currently under the
 * viewport-relative point (mx,my) fixed on screen. Pure — exported for testing the anchor invariant.
 */
export function zoomAboutPoint(v: GraphView, ns: number, mx: number, my: number, min: number, max: number): GraphView {
  const nz = clamp(ns, min, max);
  const k = nz / v.scale;
  return { scale: nz, tx: mx - (mx - v.tx) * k, ty: my - (my - v.ty) * k };
}

/**
 * Center a box `b` (design-space {x,y,w,h}) in a `cw`×`ch` viewport at an explicit `scale` (clamped to
 * [min,max]). Pure — exported for testing. Framing goes through here so the box's OWN extent is centered
 * and its origin offset out — i.e. the graph is centered on where its content actually is (#2673), not on
 * a nominal box pinned at the origin (which parked the org graph high / clipped it at the top).
 */
export function centeredBox(b: GraphBox, cw: number, ch: number, scale: number, min: number, max: number): GraphView {
  const s = clamp(scale, min, max);
  return { scale: s, tx: (cw - b.w * s) / 2 - b.x * s, ty: (ch - b.h * s) / 2 - b.y * s };
}

/**
 * Fit a box `b` into a `cw`×`ch` viewport: the largest scale (clamped to [min, maxFitScale] then
 * [min,max]) that leaves `fitPad` px per side, centered on the box. Pure — exported for testing.
 */
export function fitBox(b: GraphBox, cw: number, ch: number, min: number, max: number, fitPad: number, maxFitScale: number): GraphView {
  const s = Math.min((cw - fitPad * 2) / b.w, (ch - fitPad * 2) / b.h, maxFitScale);
  return centeredBox(b, cw, ch, s, min, max);
}

/** Center a `w`×`h` world — the box-at-origin case of {@link centeredBox}. Kept for callers that frame
 *  the nominal world (Glance) + the #2545 restore tests. */
export function centeredView(w: number, h: number, cw: number, ch: number, scale: number, min: number, max: number): GraphView {
  return centeredBox({ x: 0, y: 0, w, h }, cw, ch, scale, min, max);
}

/** Fit a `w`×`h` world — the box-at-origin case of {@link fitBox}. */
export function fitView(w: number, h: number, cw: number, ch: number, min: number, max: number, fitPad: number, maxFitScale: number): GraphView {
  return fitBox({ x: 0, y: 0, w, h }, cw, ch, min, max, fitPad, maxFitScale);
}

/**
 * Pan a `v.scale`d world so world point (wx,wy) sits at the center of a `cw`×`ch` viewport, keeping
 * `v.scale` unchanged. Pure — the least-disruptive "focus this node" move (#2525). Exported for testing.
 */
export function centerView(v: GraphView, cw: number, ch: number, wx: number, wy: number): GraphView {
  return { scale: v.scale, tx: cw / 2 - wx * v.scale, ty: ch / 2 - wy * v.scale };
}

/** Set on the viewport for the duration of a pan (#4144). Its rule (graphCanvas.css) forces the grabbing
 *  cursor across the whole subtree — a node's own `cursor: pointer` would otherwise win under the
 *  pointer, since CSS `cursor` resolves per element rather than inheriting from the dragged ancestor. */
export const PANNING_CLASS = "graph-panning";

/**
 * Is this wheel event over a descendant that can scroll in the wheel's direction?
 *
 * Walks target → viewport. An element qualifies only if it BOTH declares an overflow that scrolls and
 * actually overflows, and has somewhere left to go in this direction — so a pane scrolled to its bottom
 * hands the wheel back to the canvas rather than dead-ending the gesture, which is what makes a graph
 * containing a short log still feel like a canvas.
 *
 * Exported for testing: jsdom reports every layout metric as 0, so this cannot be observed through a
 * render — the unit test drives it with explicit element stubs instead.
 */
export function overScrollableChild(target: EventTarget | null, stopAt: Element, deltaY: number): boolean {
  let el = target instanceof Element ? target : null;
  while (el && el !== stopAt) {
    const style = typeof getComputedStyle === "function" ? getComputedStyle(el) : null;
    const overflowY = style?.overflowY ?? "";
    if ((overflowY === "auto" || overflowY === "scroll" || overflowY === "overlay")
      && el.scrollHeight > el.clientHeight) {
      const atTop = el.scrollTop <= 0;
      const atBottom = el.scrollTop + el.clientHeight >= el.scrollHeight - 1;
      // Room to move in the direction asked for. `deltaY === 0` (a horizontal wheel) is not ours either.
      if (deltaY < 0 ? !atTop : deltaY > 0 ? !atBottom : true) return true;
    }
    el = el.parentElement;
  }
  return false;
}

/** The `transform` a view renders as. Pure + exported so the imperative drag path and the React render
 *  path can never disagree on the string — they are the same function (#4140). */
export function viewTransform(v: GraphView): string {
  return `translate(${v.tx}px,${v.ty}px) scale(${v.scale})`;
}

export function useGraphViewport(world: { w: number; h: number }, opts: GraphViewportOpts = {}): GraphViewport {
  const min = opts.min ?? 0.28;
  const max = opts.max ?? 2.6;
  const fitPad = opts.fitPad ?? 70;
  const maxFitScale = opts.maxFitScale ?? 1.05;

  const [view, setView] = useState<GraphView>({ tx: 0, ty: 0, scale: 1 });
  const vpRef = useRef<HTMLDivElement | null>(null);
  const viewRef = useRef(view);
  useEffect(() => { viewRef.current = view; }, [view]);

  // #4140: the WORLD LAYER, driven imperatively during a pan.
  //
  // The drag used to `setView` on every mousemove, so each pan frame re-rendered the whole graph
  // subtree — 248 elements + 799 edges reconciled per EVENT, and mouse events outpace frames (a 500Hz
  // mouse is ~8 per frame). Now the drag writes `style.transform` straight to this element and leaves
  // React alone until mouseup.
  //
  // `viewRef` is the authority, not `view`: the layout effect below re-applies from it after EVERY
  // render, so a re-render triggered mid-drag by something else cannot snap the transform back to the
  // stale committed state. It runs before paint, so there is no flash.
  const worldElRef = useRef<HTMLElement | null>(null);
  const applyView = useCallback((v: GraphView) => {
    if (worldElRef.current) worldElRef.current.style.transform = viewTransform(v);
  }, []);
  const setWorld = useCallback((el: HTMLElement | null) => {
    worldElRef.current = el;
    if (el) el.style.transform = viewTransform(viewRef.current);
  }, []);
  useLayoutEffect(() => { applyView(viewRef.current); });
  const worldRef = useRef(world);
  useEffect(() => { worldRef.current = world; }, [world.w, world.h]);
  // Latest content-bounds provider (read live at fit/restore time). Seeded from the first render and
  // refreshed every commit — this hook is called before the consumer's own effects, so the ref is current
  // before a mount/org-change restore effect reads it (#2673).
  const boundsRef = useRef(opts.contentBounds);
  useEffect(() => { boundsRef.current = opts.contentBounds; });
  // Set true during a pan-drag so the click that ends it doesn't select a node/edge.
  const dragMoved = useRef(false);
  // True once the USER has positioned the viewport themselves (pan or zoom). Gates the initial auto-fit
  // below — a viewport the user placed is never yanked by a later layout change. Programmatic moves
  // (`fit`, `centerOn`, `zoomToCentered`) deliberately do NOT set it: those ARE the app framing the graph.
  const userMoved = useRef(false);

  /** The box to frame: the live content bounds when a provider gives them, else the nominal world. */
  const frameBox = (): GraphBox => boundsRef.current?.() ?? { x: 0, y: 0, ...worldRef.current };

  /** Zoom to `ns` keeping the world point under (mx,my) — viewport-relative client coords — fixed. */
  const zoomAbout = useCallback((ns: number, mx: number, my: number) => {
    userMoved.current = true;
    setView((v) => zoomAboutPoint(v, ns, mx, my, min, max));
  }, [min, max]);

  /** Fit the content (or the world, absent a content-bounds provider) in the viewport and center it. */
  const fit = useCallback(() => {
    const el = vpRef.current;
    if (!el) return;
    setView(fitBox(frameBox(), el.clientWidth, el.clientHeight, min, max, fitPad, maxFitScale));
  }, [min, max, fitPad, maxFitScale]);

  // Initial framing (#3433) — re-fit whenever the world's DIMENSIONS change, until the user takes over.
  //
  // A page's own fit is a mount effect, so it frames whatever model exists at mount — and every graph
  // page loads its data async, so that is the EMPTY model. `buildGraph` sizes the world tightly around its
  // content, so an empty graph is a small-but-valid box (Glance: 266x156): `fitBox` caps at `maxFitScale`
  // and centers it, parking world origin near the middle of the viewport. The real data then arrives, the
  // world grows, and nothing re-frames it — the graph renders from screen center off the bottom-right.
  //
  // Keyed on the NUMERIC w/h, not the model reference. That distinction is the whole point: #2554 dropped
  // `model` from Glance's fit deps because the status overlays hand back a fresh model object every poll,
  // which re-fit the graph every few seconds and wiped the user's pan/zoom. Those polls move no node, so
  // the world dimensions are byte-identical and this does not fire — #2554's intent is preserved, while a
  // layout that genuinely changed size gets framed.
  //
  // `userMoved` then makes it strictly an INITIAL framing: once the user has panned or zoomed, their
  // viewport is theirs. An explicit `fit()` (drill in/out, the toolbar button) still works — it is a
  // direct call, not gated on this.
  // Skipped while the viewport has no measurable size — a page that mounts HIDDEN (a background tab, the
  // Design Studio's center pane before its canvas view is chosen) reports 0x0, and fitting against that
  // yields a degenerate transform. The page's own fit effect already re-frames on the switch back, so
  // leaving `userMoved` false here just means the next real signal takes it.
  // (`fit` is stable — its deps are the scalar zoom options — so listing it cannot add a re-fire.)
  useEffect(() => {
    if (userMoved.current) return;
    const id = requestAnimationFrame(() => {
      const el = vpRef.current;
      if (userMoved.current || !el || !el.clientWidth || !el.clientHeight) return;
      fit();
    });
    return () => cancelAnimationFrame(id);
  }, [world.w, world.h, fit]);

  /** Pan world point (wx,wy) to the viewport center, keeping the current zoom (#2525). */
  const centerOn = useCallback((wx: number, wy: number) => {
    const el = vpRef.current;
    if (!el) return;
    setView((v) => centerView(v, el.clientWidth, el.clientHeight, wx, wy));
  }, []);

  /** Pan by a screen-space delta (px) — for a gesture forwarded from outside the viewport (#3190). */
  const panBy = useCallback((dx: number, dy: number) => {
    userMoved.current = true;
    setView((v) => ({ ...v, tx: v.tx + dx, ty: v.ty + dy }));
  }, []);

  /** Zoom by `factor` about a PAGE point — a wheel forwarded from outside the viewport (#3190). Mirrors
   *  `onWheel`: convert the page point to viewport-relative via the live rect, then zoom about it. */
  const zoomAtClient = useCallback((factor: number, clientX: number, clientY: number) => {
    const el = vpRef.current;
    if (!el) return;
    const r = el.getBoundingClientRect();
    zoomAbout(viewRef.current.scale * factor, clientX - r.left, clientY - r.top);
  }, [zoomAbout]);

  /** Zoom by a factor around the viewport center (the +/- buttons). */
  const zoomBy = useCallback((f: number) => {
    const el = vpRef.current;
    if (!el) return;
    zoomAbout(viewRef.current.scale * f, el.clientWidth / 2, el.clientHeight / 2);
  }, [zoomAbout]);

  /** Set an absolute zoom around the viewport center. */
  const zoomTo = useCallback((scale: number) => {
    const el = vpRef.current;
    if (!el) return;
    zoomAbout(scale, el.clientWidth / 2, el.clientHeight / 2);
  }, [zoomAbout]);

  /** Set an absolute zoom with the content (or world) re-centered (restoring a saved level, #2545/#2673). */
  const zoomToCentered = useCallback((scale: number) => {
    const el = vpRef.current;
    if (!el) return;
    setView(centeredBox(frameBox(), el.clientWidth, el.clientHeight, scale, min, max));
  }, [min, max]);

  // Wheel → zoom (native non-passive listener so we can preventDefault the page scroll).
  //
  // …unless the wheel belongs to a SCROLLABLE CHILD. The canvas used to `preventDefault()` every wheel
  // unconditionally, which meant anything scrollable rendered INSIDE the viewport could never scroll: in
  // Glance a live terminal morph (`GlanceStreamMorph` → `GlanceChatDock` → `TerminalSlot`) sits in the
  // world layer, so scrolling it zoomed the graph instead. The drag path has had this class of guard
  // since #4144 (`onCanvasDown` returns early for a node's own gesture); the wheel path had none.
  //
  // Detected by BEHAVIOUR, not by a marker class: an ancestor counts if it can actually scroll right now
  // (overflow auto/scroll AND real overflow). That covers xterm's own viewport without naming it, works
  // for every graph on this hook, and a child that cannot scroll still zooms the canvas — so the gesture
  // is unchanged wherever nothing else wants the wheel.
  const onWheel = useCallback((e: WheelEvent) => {
    const el = vpRef.current;
    if (!el) return;
    if (overScrollableChild(e.target, el, e.deltaY)) return; // no preventDefault — let the child scroll
    e.preventDefault();
    const r = el.getBoundingClientRect();
    zoomAbout(viewRef.current.scale * Math.exp(-e.deltaY * 0.0016), e.clientX - r.left, e.clientY - r.top);
  }, [zoomAbout]);

  /** Backdrop mousedown → pan (window-level move/up so a fast drag off the canvas still tracks). */
  const onCanvasDown = useCallback((e: React.MouseEvent) => {
    if ((e.target as HTMLElement).closest("[data-node]")) return; // the node owns its own gesture
    const v = viewRef.current;
    const start = { x: e.clientX, y: e.clientY, tx: v.tx, ty: v.ty };
    dragMoved.current = false;
    // #4144: the grabbing cursor has to cover the SUBTREE, not just the viewport. CSS `cursor` resolves
    // per element — an ancestor cannot override it — so every `.ds-node` under the pointer kept
    // resolving its own `cursor: pointer` and a drag across nodes read grabbing → pointer → grabbing.
    // The class carries a `*` rule (graphCanvas.css) that wins for the duration of the pan.
    // (Invisible before #4140: the per-mousemove re-render rewrote the style attribute and clobbered
    // `grabbing` straight back to `grab`, so the drag cursor barely applied at all.)
    if (vpRef.current) vpRef.current.classList.add(PANNING_CLASS);
    const mm = (ev: MouseEvent) => {
      const dx = ev.clientX - start.x, dy = ev.clientY - start.y;
      if (Math.abs(dx) + Math.abs(dy) > 4) { dragMoved.current = true; userMoved.current = true; }
      // #4140: NO setState here — mutate the authority and paint it directly. React learns the final
      // position once, on mouseup.
      viewRef.current = { ...viewRef.current, tx: start.tx + dx, ty: start.ty + dy };
      applyView(viewRef.current);
    };
    const mu = () => {
      if (vpRef.current) vpRef.current.classList.remove(PANNING_CLASS);
      window.removeEventListener("mousemove", mm);
      window.removeEventListener("mouseup", mu);
      // Commit the drag to React exactly once, so everything keyed on `view` (worldTransform, any
      // consumer memo) converges on where the pan actually ended.
      setView(viewRef.current);
      // Clear on the next tick so the click handler (which fires after mouseup) can still read it.
      setTimeout(() => { dragMoved.current = false; }, 0);
    };
    window.addEventListener("mousemove", mm);
    window.addEventListener("mouseup", mu);
  }, []);

  // The wheel listener is attached HERE, from the ref callback, not from a mount effect: a canvas
  // can mount long after the hook (Design Studio's center pane starts on the Library view), and a
  // mount effect keyed on stable deps never re-runs when the element finally arrives — leaving
  // scroll-zoom permanently dead (#2454). Detaching from the previous element keeps repeated
  // mount/unmount/replace cycles free of leaked or doubled listeners.
  const setVp = useCallback((el: HTMLDivElement | null) => {
    const prev = vpRef.current;
    if (prev === el) return;
    if (prev) prev.removeEventListener("wheel", onWheel);
    vpRef.current = el;
    if (el) el.addEventListener("wheel", onWheel, { passive: false });
  }, [onWheel]);

  return {
    view, setVp, setWorld, onCanvasDown, fit, centerOn, zoomBy, zoomTo, zoomToCentered, dragMoved, panBy, zoomAtClient,
    worldTransform: { transform: `translate(${view.tx}px,${view.ty}px) scale(${view.scale})`, transformOrigin: "0 0" },
    vpEl: vpRef,
  };
}

import { useEffect, useRef } from "react";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { computeBroadcastTargets } from "@/app/console/lib/broadcast";
import { adjustFontSize, DEFAULT_TERMINAL_FONT_SIZE } from "@/app/console/lib/terminal";
import { nextFullscreen } from "@/app/console/lib/consoleFocus";
import { CLEAR_INPUT_BYTES } from "@/app/console/lib/clearInput";
import { resolvePaneFromBuffer, PANE_SELECT_COMMIT_MS } from "@/app/console/lib/paneSelect";
import { paneIdFor } from "@/app/console/lib/paneIdentity";
import { paneCountForLayout } from "@/app/console/lib/paneStatus";
import { SCREEN_HOTKEYS } from "@/features/settings";
import { effectiveWorkspace } from "@/app/registry";
import {
  matchesBinding, matchesChord, matchesLeader, eventToLeader, effectiveLeader,
  type RebindableId,
} from "@/features/settings";
import { VIEW_ORDER } from "@/app/console/panes/viewDefs";
import { getPageNav } from "@/shared/ui/layouts/pageNav";
import type { Workspace } from "@/app/chrome/Rail";

/** If `e` matches a screen-navigation F-key (per the active bindings), return the target workspace, else
 *  null. Shared by the always-on global screen-nav listener (every page) and the Console pane-hotkey
 *  effect, so the F-key → screen map lives in exactly one place. */
function screenForEvent(e: KeyboardEvent, bindings: Parameters<typeof matchesBinding>[1]): Workspace | null {
  for (const h of SCREEN_HOTKEYS) {
    if (matchesBinding(e, bindings, `screen-${h.screen}` as RebindableId)) return h.screen;
  }
  return null;
}

/** The next index after stepping `delta` from `from`, wrapping at both ends. Wrapping is what every
 *  tabbed surface does; clamping would make "next" unreachable from the last page without reversing. */
export function stepIndex(from: number, delta: number, length: number): number {
  if (length <= 0) return -1;
  return (((from + delta) % length) + length) % length;
}

/** Ctrl+← / Ctrl+→ → step the active Workspace's PAGES (#4167). Returns true when it handled the event.
 *
 *  Reads the page model the mounted `Screen` publishes (`shared/` cannot match a keybinding itself —
 *  #1626/#1703 — so it hands over its tabs + selector and the shell does this half). It is a module ref,
 *  not store state (#4170): read at keydown time, it needs no reactivity, and routing it through the
 *  store made an unstable `select` identity into an infinite render loop. No-ops when there is no tabbed
 *  Workspace on screen, or when it holds fewer than two pages. */
function stepPage(e: KeyboardEvent, bindings: Parameters<typeof matchesBinding>[1]): boolean {
  const delta = matchesBinding(e, bindings, "page-next") ? 1
    : matchesBinding(e, bindings, "page-prev") ? -1
    : 0;
  if (delta === 0) return false;
  const nav = getPageNav();
  if (!nav || nav.ids.length < 2) return false;
  const from = nav.ids.indexOf(nav.active);
  // An active id that is not in the visible set (mid-update, or a page just torn off) steps from the
  // front rather than from -1, which would land on the LAST page for a "next".
  const next = nav.ids[stepIndex(from < 0 ? 0 : from, delta, nav.ids.length)];
  if (!next || next === nav.active) return false;
  nav.select(next);
  return true;
}

/** Ctrl+1–9 → select the Nth PAGE of the active Workspace. Returns true when it handled the event.
 *
 *  The same intent as the Console's tab switch — "go to tab N of whatever this screen shows" — so it
 *  shares that action's REBINDABLE LEADER rather than owning a second one: rebinding the leader moves
 *  both, because to the user they are one idea, not two.
 *
 *  Digits were rejected for page STEPPING (#4167) on the grounds that "every digit combination is already
 *  a console selector leader". True on the Console, where `Ctrl+Shift+<digits>` selects a pane and the
 *  view switchers take the rest — but this runs only in the OFF-Console effect, where that listener is
 *  never attached, so the digits are unclaimed there.
 *
 *  Out of range is a deliberate NO-OP: `Ctrl+7` on a four-page Workspace does nothing rather than
 *  clamping to the last page, so a mistyped digit never silently navigates somewhere. */
function pickPage(e: KeyboardEvent, bindings: Parameters<typeof matchesBinding>[1]): boolean {
  const digit = e.code.match(/^Digit([1-9])$/);
  if (!digit || !matchesLeader(e, bindings, "tab-switch")) return false;
  const nav = getPageNav();
  if (!nav) return false;
  const target = nav.ids[parseInt(digit[1], 10) - 1];
  if (!target || target === nav.active) return false;
  nav.select(target);
  return true;
}

function keyToTermBytes(e: KeyboardEvent): string | null {
  const { key, ctrlKey, altKey, shiftKey } = e;

  // Bare modifier keys — nothing to send
  if (["Shift", "Control", "Alt", "Meta", "CapsLock", "NumLock",
       "ScrollLock", "Pause", "ContextMenu", "Dead"].includes(key)) return null;

  // Ctrl+letter → ASCII control codes (skip Shift variants — those are separate hotkeys)
  if (ctrlKey && !altKey && !shiftKey && key.length === 1) {
    const c = key.toUpperCase().charCodeAt(0);
    if (c >= 64 && c <= 95) return String.fromCharCode(c - 64);
  }
  if (ctrlKey && !altKey && !shiftKey && key === " ") return "\x00";

  const esc = altKey ? "\x1b" : "";

  switch (key) {
    case "Enter":      return esc + "\r";
    case "Backspace":  return esc + "\x7f";
    case "Tab":        return shiftKey ? "\x1b[Z" : esc + "\t";
    case "Escape":     return "\x1b";
    case "Delete":     return esc + "\x1b[3~";
    case "ArrowUp":    return esc + "\x1b[A";
    case "ArrowDown":  return esc + "\x1b[B";
    case "ArrowRight": return esc + "\x1b[C";
    case "ArrowLeft":  return esc + "\x1b[D";
    case "Home":       return esc + "\x1b[H";
    case "End":        return esc + "\x1b[F";
    case "PageUp":     return esc + "\x1b[5~";
    case "PageDown":   return esc + "\x1b[6~";
    case "F1":  return "\x1bOP";  case "F2":  return "\x1bOQ";
    case "F3":  return "\x1bOR";  case "F4":  return "\x1bOS";
    case "F5":  return "\x1b[15~"; case "F6": return "\x1b[17~";
    case "F7":  return "\x1b[18~"; case "F8": return "\x1b[19~";
    case "F9":  return "\x1b[20~"; case "F10":return "\x1b[21~";
    case "F11": return "\x1b[23~"; case "F12":return "\x1b[24~";
  }

  // Printable single character (shift already reflected in e.key value)
  if (key.length === 1) return esc + key;

  return null;
}

export function useHotkeys() {
  const {
    activeWorkspace,
    setWorkspace,
    tabs,
    activeTabIdx,
    setActiveTab,
    focusedPaneIdx,
    fullscreenPaneIdx,
    setFocusedPane,
    setFullscreenPane,
    setPaneView,
    setAllPanesView,
    consoleBroadcast,
    setConsoleBroadcast,
    setTerminalFontSize,
    advanceFocus,
    showConsolePage,
  } = useAppStore();

  // Whether the Console page is actually the live surface. The console-pane hotkeys read the RAW store
  // `activeWorkspace`, but the legacy Console page is opt-in (#2372) and App redirects console→glance
  // when it's off — so without this the hotkeys (broadcast, view-switch, redraw…) would keep firing
  // while Glance is on screen. Gating both effects on the same effective workspace makes the hotkeys
  // follow the toggle, while F-key screen-nav still works on Glance (#3575).
  const onConsole = effectiveWorkspace(activeWorkspace, showConsolePage) === "console";

  // Chained-digit pane selector: digits accumulate while Ctrl+Shift is held,
  // then commit (resolve to a pane) on modifier release or after a short pause.
  const digitBufferRef = useRef("");
  const commitTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Screen-navigation F-keys switch rail workspaces, so they must fire on EVERY page — NOT just the
  // Console (the pane hotkeys below are Console-only per #1218, which accidentally made F-key nav
  // Console-only too — #2403). This always-on listener handles them OFF the Console page; on the Console
  // page the pane-hotkey effect below handles nav itself (after its broadcast intercept, so an F-key still
  // broadcasts in broadcast mode), so this one is gated off-Console to avoid double-firing.
  useEffect(() => {
    if (onConsole) return;
    function onKeyDown(e: KeyboardEvent) {
      const t = e.target as HTMLElement;
      // Don't yank focus away while the user is typing in a field (matches the Console effect's guard).
      // This is ALSO what keeps Ctrl+Arrow word-jump working in every embedded terminal: xterm focuses a
      // `textarea.xterm-helper-textarea`, so the Planner's live session and the studio panes are exempt.
      if (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable) return;
      const bindings = useAppStore.getState().keybindings;
      const navTo = screenForEvent(e, bindings);
      if (navTo) { e.preventDefault(); setWorkspace(navTo); return; }
      // Ctrl+← / Ctrl+→ step the active Workspace's PAGES (#4167) — arrows, not digits, because the
      // console selectors own every digit combination (Ctrl / Ctrl+Shift / Alt / Alt+Shift + a digit).
      // `pageNav` is published by the mounted `Screen`; it is null on a Workspace with no page bar.
      if (stepPage(e, bindings)) { e.preventDefault(); return; }
      // Ctrl+1–9 → jump straight to a page, the digit half of the same idea. Console-only until now, so
      // the shortcut read as broken from every other screen.
      if (pickPage(e, bindings)) e.preventDefault();
    }
    document.addEventListener("keydown", onKeyDown, true);
    return () => document.removeEventListener("keydown", onKeyDown, true);
  }, [onConsole, setWorkspace]);

  useEffect(() => {
    // #1218: the hotkeys are Console-only. Don't attach the document listeners at all unless the
    // Console page is active AND no pane is maximized — so every other screen, and a maximized
    // terminal, gets unobstructed native copy/paste, text selection, and browser shortcuts (the
    // capture-phase listener used to sit in front of all of them). Both gating values are in this
    // effect's dep array, so changing screen or maximizing/restoring re-runs the effect to
    // attach/detach. Exit maximize via the pane header button (the keyboard toggle is off here too).
    if (!onConsole || fullscreenPaneIdx >= 0) return;

    // Resolve the accumulated pane-number buffer and run the focus → fullscreen →
    // restore cycle on it. State is read fresh (the timer fires later) so a stale
    // closure can't mis-target.
    function commitDigitBuffer() {
      if (commitTimerRef.current) { clearTimeout(commitTimerRef.current); commitTimerRef.current = null; }
      const buf = digitBufferRef.current;
      digitBufferRef.current = "";
      if (!buf) return;
      const { tabs, activeTabIdx, focusedPaneIdx, fullscreenPaneIdx } = useAppStore.getState();
      const activeTab = tabs[activeTabIdx];
      if (!activeTab) return;
      const [cols, rows] = activeTab.layout.split("×").map(Number);
      const idx = resolvePaneFromBuffer(buf, cols * rows);
      if (idx === null) return;
      if (fullscreenPaneIdx === idx) {
        setFullscreenPane(-1);
        setFocusedPane(-1);
      } else if (focusedPaneIdx === idx) {
        setFullscreenPane(idx);
      } else {
        setFullscreenPane(-1);
        setFocusedPane(idx);
      }
    }

    function onKeyDown(e: KeyboardEvent) {
      const tag = (e.target as HTMLElement).tagName;
      const inInput = tag === "INPUT" || tag === "TEXTAREA" || (e.target as HTMLElement).isContentEditable;

      // Active custom keybindings (#771) — read fresh so a rebind takes effect
      // without re-subscribing the listener. Each rebindable action matches its
      // chord by id (custom override ?? built-in default).
      const bindings = useAppStore.getState().keybindings;

      // ── Ctrl+Shift+C: toggle broadcast mode ───────────────────────────────
      // Must come before the broadcast intercept and the inInput guard.
      if (matchesBinding(e, bindings, "broadcast-toggle")) {
        e.preventDefault();
        e.stopPropagation();
        setConsoleBroadcast(!consoleBroadcast);
        return;
      }

      // ── Ctrl+Shift+F: maximize / minimize the focused console pane ──────────
      // Before the broadcast intercept so it works in broadcast mode too, and
      // before the inInput guard so it fires while typing in a pane's terminal.
      if (matchesBinding(e, bindings, "fullscreen-toggle")) {
        e.preventDefault();
        e.stopPropagation();
        const next = nextFullscreen(focusedPaneIdx, fullscreenPaneIdx);
        if (next !== null) setFullscreenPane(next);
        return;
      }

      // ── Ctrl+Shift+R: redraw / fix display (#1221) ──────────────────────────
      // Nudge the focused pane's PTY size (a transient SIGWINCH) to force the Claude CLI's TUI to
      // repaint — the in-app equivalent of dragging the window to un-jumble it. Keys off the STABLE
      // pane id (paneIdFor), the same id the terminal watches.
      if (matchesBinding(e, bindings, "redraw-pane")) {
        if (!onConsole) return;
        e.preventDefault();
        e.stopPropagation();
        const idx = fullscreenPaneIdx >= 0 ? fullscreenPaneIdx : focusedPaneIdx;
        if (idx < 0) return;
        const st = useAppStore.getState();
        const tab = st.tabs[activeTabIdx];
        if (tab) st.requestPaneRedraw(paneIdFor(tab, activeTabIdx, idx));
        return;
      }

      // ── Ctrl+Shift+N: focus the next waiting pane (maximize-aware) ──────────
      // Steps through agents that finished a turn. If a pane is maximized it
      // swaps the maximized pane to the next one, so you stay full-screen.
      if (matchesBinding(e, bindings, "focus-next-waiting")) {
        e.preventDefault();
        e.stopPropagation();
        advanceFocus();
        return;
      }

      // ── Ctrl+Shift+Backspace: clear the focused pane's pending input ────────
      // Sends Ctrl+U to the PTY — kills cursor-to-start in bash readline (the
      // whole line when the cursor's at the end, the common case) and clears
      // claude's TUI input box. In broadcast mode mirrors to every pane on
      // the active tab — including the focused one, since we send the bytes
      // directly rather than via xterm.onData, so there's no double-write to
      // worry about (#192).
      if (matchesBinding(e, bindings, "clear-input")) {
        e.preventDefault();
        e.stopPropagation();
        if (consoleBroadcast) {
          const activeTab = tabs[activeTabIdx];
          if (!activeTab) return;
          // Key off the tab's STABLE pane ids (paneIdFor) — a manual tab's PTYs are
          // `man:<tabId>:p<n>`, so positional ids would clear nothing (#1176).
          const paneIds = Array.from({ length: paneCountForLayout(activeTab.layout) },
            (_, i) => paneIdFor(activeTab, activeTabIdx, i));
          invoke("pty_broadcast", { paneIds, data: CLEAR_INPUT_BYTES });
        } else if (focusedPaneIdx >= 0) {
          const activeTab = tabs[activeTabIdx];
          if (activeTab) invoke("pty_write", { paneId: paneIdFor(activeTab, activeTabIdx, focusedPaneIdx), data: CLEAR_INPUT_BYTES });
        }
        return;
      }

      // ── Zoom the console terminal font (all panes) ─────────────────────────
      // Before the broadcast intercept so it isn't mirrored as a literal key, and
      // before the inInput guard so it works while typing in a terminal. Rebindable
      // (#773): once a zoom action is overridden it matches its captured chord;
      // otherwise it keeps the default key-based match so BOTH Ctrl++ and Ctrl+=
      // zoom in (the "+" key is Shift+= on most layouts), and numpad +/-/0 fold in
      // via e.key.
      {
        const ctrlOnly = e.ctrlKey && !e.metaKey && !e.altKey;
        // Default zoom matches by e.key; an override matches its captured chord.
        const zoom = (id: RebindableId, dflt: boolean): boolean =>
          bindings[id] ? matchesChord(e, bindings[id]) : dflt;
        const zoomReset = zoom("zoom-reset", ctrlOnly && e.key === "0");
        const zoomOut   = zoom("zoom-out",   ctrlOnly && (e.key === "-" || e.key === "_"));
        const zoomIn    = zoom("zoom-in",    ctrlOnly && (e.key === "+" || e.key === "="));
        if (zoomReset || zoomOut || zoomIn) {
          e.preventDefault();
          e.stopPropagation();
          const cur = useAppStore.getState().terminalFontSize;
          if (zoomReset)     setTerminalFontSize(DEFAULT_TERMINAL_FONT_SIZE);
          else if (zoomOut)  setTerminalFontSize(adjustFontSize(cur, -1));
          else               setTerminalFontSize(adjustFontSize(cur, +1));
          return;
        }
      }

      // ── Broadcast intercept ────────────────────────────────────────────────
      // In broadcast mode keystrokes mirror to every console in the ACTIVE tab.
      // The focused pane handles its own keystroke through xterm — including it
      // in pty_broadcast would double-write and drop the first letter — so it is
      // excluded. computeBroadcastTargets reconstructs pane ids strictly from the
      // active tab, and only excludes a focus index that is actually within this
      // tab (a stale index from another tab must not skip one of these consoles).
      if (consoleBroadcast) {
        // Navigation hotkeys (switch tab / pane / view by number) must NOT be
        // broadcast as text — skip them here so they fall through to their handlers
        // below and keep working in broadcast mode (e.g. while driving a fleet).
        const lead = eventToLeader(e);
        const isNavHotkey =
          (/^Digit[0-9]$/.test(e.code) &&
            (lead === effectiveLeader(bindings, "tab-switch") ||
             lead === effectiveLeader(bindings, "pane-select"))) ||
          (/^Digit[1-9]$/.test(e.code) &&
            (lead === effectiveLeader(bindings, "view-switch") ||
             lead === effectiveLeader(bindings, "view-switch-all")));
        const bytes = isNavHotkey ? null : keyToTermBytes(e);
        if (bytes !== null) {
          const activeTab = tabs[activeTabIdx];
          if (activeTab) {
            const { paneIds, suppressDefault } =
              computeBroadcastTargets(activeTab, activeTabIdx, focusedPaneIdx);
            if (paneIds.length > 0) {
              invoke("pty_broadcast", { paneIds, data: bytes });
            }
            if (suppressDefault) {
              e.preventDefault();
              e.stopPropagation();
            }
          }
          return;
        }
      }

      // Plain typing in inputs is fine; modifier combos still fire
      if (inInput && !e.ctrlKey && !e.metaKey && !e.altKey) return;

      // Screen navigation (F-keys, rebindable per screen #773) — handled here too so it works on the
      // Console page. It sits AFTER the broadcast intercept above, so in broadcast mode an F-key is sent
      // to the panes rather than navigating (unchanged). Off-Console, the always-on effect above owns it.
      const navTo = screenForEvent(e, bindings);
      if (navTo) {
        e.preventDefault();
        setWorkspace(navTo);
        return;
      }

      // ── CTRL = SELECT ─────────────────────────────────────────────────────

      // Tab switch by index — Ctrl+1–9 by default; the leader is rebindable (#773).
      const tabDigit = e.code.match(/^Digit([1-9])$/);
      if (tabDigit && matchesLeader(e, bindings, "tab-switch")) {
        e.preventDefault();
        const targetIdx = parseInt(tabDigit[1], 10) - 1;
        if (targetIdx < tabs.length) setActiveTab(targetIdx);
        return;
      }

      // Ctrl+Shift+<digits>: select a console pane by number.
      //   Hold Ctrl+Shift and type one or more digits — they accumulate so panes
      //   10+ are reachable (e.g. 1 then 3 → pane 13). The number commits on a
      //   short pause or when Ctrl/Shift is released (see onKeyUp), so a single
      //   digit still feels instant. On the resolved pane the selection cycles
      //   focus → fullscreen → restore, exactly as a direct press did before.
      const paneDigit = e.code.match(/^Digit(\d)$/);
      if (paneDigit && matchesLeader(e, bindings, "pane-select")) {
        e.stopPropagation();
        e.preventDefault();
        digitBufferRef.current += paneDigit[1];
        if (commitTimerRef.current) clearTimeout(commitTimerRef.current);
        commitTimerRef.current = setTimeout(commitDigitBuffer, PANE_SELECT_COMMIT_MS);
        return;
      }

      // ── ALT = MODIFY ──────────────────────────────────────────────────────

      // Alt+Shift+Enter: broadcast Enter to every pane (one-shot, regardless of broadcast mode)
      if (matchesBinding(e, bindings, "send-all-enter")) {
        e.preventDefault();
        e.stopPropagation();
        const activeTab = tabs[activeTabIdx];
        if (!activeTab) return;
        // Stable pane ids (paneIdFor) so a manual tab's `man:` PTYs are actually hit (#1176).
        const paneIds = Array.from({ length: paneCountForLayout(activeTab.layout) },
          (_, i) => paneIdFor(activeTab, activeTabIdx, i));
        invoke("pty_broadcast", { paneIds, data: "\r" });
        return;
      }

      // Switch pane view by index — Alt+1–5 (focused) / Alt+Shift+1–5 (all) by
      // default; both leaders are rebindable (#773). The all-panes leader is
      // checked first so it wins when it's the more specific combo.
      const viewDigit = e.code.match(/^Digit([1-9])$/);
      if (viewDigit) {
        const allMatch = matchesLeader(e, bindings, "view-switch-all");
        const oneMatch = matchesLeader(e, bindings, "view-switch");
        if (allMatch || oneMatch) {
          // Digits map 1:1 onto VIEW_ORDER (console…telemetry); a digit past the last view is a
          // no-op rather than switching to `undefined`.
          const view = VIEW_ORDER[parseInt(viewDigit[1], 10) - 1];
          if (!view) return;
          e.preventDefault();
          if (allMatch) {
            setAllPanesView(view);
          } else if (focusedPaneIdx >= 0) {
            setPaneView(focusedPaneIdx, view);
          }
          return;
        }
      }
    }

    // Releasing any modifier commits a pending pane-number buffer immediately, so
    // single-digit selections don't wait out the timeout — regardless of which
    // modifier leader pane-select is bound to (#773).
    function onKeyUp(e: KeyboardEvent) {
      if (["Control", "Shift", "Alt", "Meta"].includes(e.key) && digitBufferRef.current) {
        commitDigitBuffer();
      }
    }

    // Capture phase: fires before element handlers (including xterm's textarea listener),
    // so pane/tab hotkeys are intercepted regardless of which element has focus.
    document.addEventListener("keydown", onKeyDown, true);
    document.addEventListener("keyup", onKeyUp, true);
    return () => {
      document.removeEventListener("keydown", onKeyDown, true);
      document.removeEventListener("keyup", onKeyUp, true);
      if (commitTimerRef.current) { clearTimeout(commitTimerRef.current); commitTimerRef.current = null; }
    };
  }, [
    onConsole, setWorkspace,
    tabs, activeTabIdx, setActiveTab,
    focusedPaneIdx, fullscreenPaneIdx,
    setFocusedPane, setFullscreenPane,
    setPaneView, setAllPanesView,
    consoleBroadcast, setConsoleBroadcast,
    setTerminalFontSize,
    advanceFocus,
  ]);
}

// The idle-reaper actuator (#849): on a slow tick, kill the PTY of each pane the pure
// `panesToReap` decision selects (idle, non-focused, role-eligible, past threshold) and mark
// it dormant. Mounted once in ConsoleWorkspace (which stays mounted across screens). The pure
// decision + thresholds live in idleReaper.ts; this is the thin Tauri/React side.

import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { useAppStore } from "@/store";
import { usePoll } from "@/shared/hooks/usePoll";
import { panesToReap, type ReaperPane } from "@/app/console/lib/idleReaper";
import type { SessionRole } from "@/shared/lib/session/sessionRoles";

const TICK_MS = 60_000;

export function useIdleReaper(): void {
  // Not immediate: panes must clear the grace window before the first reap pass.
  usePoll(() => {
    const s = useAppStore.getState();
    if (!s.idleReaper.enabled) return;
    const now = Date.now();
    // The pane the user is watching — never reaped.
    const focusedKey = s.focusedPaneIdx >= 0 ? `t${s.activeTabIdx}p${s.focusedPaneIdx}` : "";
    // Live panes are the ones carrying a status. An unknown role (a console with no fleet
    // role, e.g. a hand-opened one) defaults to "worker" — i.e. conservatively NOT reaped —
    // so we never surprise-kill something we can't classify.
    const panes: ReaperPane[] = Object.keys(s.paneStatus).map((paneId) => ({
      paneId,
      status: s.paneStatus[paneId],
      role: (s.paneRoles[paneId] ?? "worker") as SessionRole,
      lastActivityMs: s.paneLastActivity[paneId] ?? now,
      focused: paneId === focusedKey,
      dormant: !!s.dormantPanes[paneId],
      maintaining: !!s.paneMaintaining[paneId],
    }));
    for (const paneId of panesToReap(panes, s.idleReaper, now)) {
      fireInvoke("pty_kill", { paneId });
      useAppStore.getState().reapPane(paneId);
    }
  }, TICK_MS, [], { immediate: false });
}

// Kit-change propagation actuator (#2277). Drains the store's queued kit-change dispatches
// (`kitDispatches`, produced by setComponent's fan-out over the consumer index) and, for each CONSUMER
// project whose per-project auto-dispatch toggle is ON, delivers a bounded, deduped set of BREAKING
// changes to the ONE rail (#2806): a LIVE fleet → the project's director pane (bsc-issue → bsc-assign →
// the UI worker re-runs `bsc ui emit sync`). A consumer with NO live fleet HOLDS in the queue (carried
// forward, adopted on its next launch) — the GitHub-issue rail was dropped. Notify-only by default
// (toggle OFF ⇒ surface-only, rendered by KitChangesCard). The gate/dedup/rate-limit is the pure
// `planKitDrain`; this is the thin poll+deliver layer, mounted once in ConsoleWorkspace beside
// useFaultTriage. It lives in app/console (not shared/) because it reads the app's pane-identity +
// director-drive state.
//
// INERT since #app-stops-pushing-prompts. Its entire body was a poll that injected queued kit changes into a consumer's director. Nothing is lost: the same `kitDispatches` queue is rendered by the KitChangesBanner, and a kit change is now adopted by the DIRECTOR polling for it.
//
// The export SURVIVES deliberately: this module is registered in graphPlatform/appModules so graph
// RECORDS can import it, and removing the export breaks record compilation at runtime. Inert-but-
// exported is the shape useFleetGate took for the same reason when its launch pump was killed —
// deleting the hook is not the fix, doing nothing is.

/** Does nothing. See the note above. */
export function useKitDispatch(): void {
  // Intentionally empty: no poll, no evaluation, no injection.
}

// useKnowledgeGraph (#2856) — the Algorithms page's live graph. Starts on the packaged seed for an
// instant first paint, then hydrates from the writable store (`bsc graph dump`, #2853) so the knowledge
// librarian's `bsc graph set`/`link`/`remove` edits show — polled, since the page is kept-mounted and a
// live session can curate at any time. The seed is the fallback (persist/seed = cache, the store is the
// source of truth — the golden rule); a degraded environment (web shell, tests, old `bsc`) just keeps
// the seed because `loadGraph` returns null.
import { useRef, useState } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { KNOWLEDGE, type KnowledgeGraph } from "@/features/algorithms/lib/knowledge";
import { loadGraph } from "@/features/algorithms/lib/graphBridge";

/** How often to re-read the store. The dump is a fast local read; the librarian edits show within a tick. */
const HYDRATE_MS = 5000;

/** An order-independent content signature — so an unchanged store (serde may reorder JSON keys) does NOT
 *  churn a re-render every tick, while any implementation edit does. */
function graphSig(g: KnowledgeGraph): string {
  return g.implementations
    .map((im) => `${im.id}:${im.tech}:${im.role}:${im.name}:${im.summary ?? ""}:${im.composes.join(",")}`)
    .sort()
    .join("|");
}
const SEED_SIG = graphSig(KNOWLEDGE);

/** The live knowledge graph: the seed, hydrated + kept fresh from the writable store. */
export function useKnowledgeGraph(): KnowledgeGraph {
  const [graph, setGraph] = useState<KnowledgeGraph>(KNOWLEDGE);
  // The signature currently rendered — start on the seed so a store that still equals the seed never
  // triggers a redundant swap; only a real edit does.
  const appliedSig = useRef(SEED_SIG);
  usePoll(
    async (isCancelled) => {
      const g = await loadGraph();
      if (isCancelled() || !g) return; // unreachable / old bsc → keep the current graph
      const sig = graphSig(g);
      if (sig === appliedSig.current) return; // no change → no re-render
      appliedSig.current = sig;
      setGraph(g);
    },
    HYDRATE_MS,
  );
  return graph;
}

// useLogStream (#3638) — the event-driven replacement for `usePoll` over a `bsc logs` stream. The
// frontend used to poll each unified log stream every ~1s; instead, the backend watcher
// (`observability::log_watch`) emits `logs://<stream>` when a stream file changes, and this hook
// re-reads (via the in-process `logs_*` commands, #3630) ONLY on that event. So reads happen on
// CHANGE, not on a clock — an idle app makes zero log reads.
//
// It keeps `usePoll`'s callback contract (an `isCancelled()` guard) so the pump bodies move over
// unchanged. A slow safety-net interval (default 60s) is the sole remaining "poll", a backstop against
// a missed change event — 60× rarer than the ~1s polls it replaces, and effectively silent.

import { useEffect, useRef, type DependencyList } from "react";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import { usePoll } from "@/shared/hooks/usePoll";
import { logEventName } from "@/shared/lib/core/logsBridge";

interface LogStreamOptions {
  /** Safety-net re-read interval (ms) — a backstop against a missed change event. Default 60000. */
  safetyMs?: number;
  /** When false, don't subscribe or read at all — the caller-side gate (e.g. page visibility, #3627).
   *  Default true. */
  active?: boolean;
}

/**
 * Re-run `fn` when any of `streams` changes (the `logs://<stream>` event), plus once on mount and on a
 * slow safety-net interval. `fn` gets the same `isCancelled` guard as {@link usePoll}. Pass the read
 * alias(es) the body reads (`"coord"`, `"activity"`, `"audit"`, …) — canonicalized to match the emit.
 *
 * @param streams one stream alias, or several (a body that reads more than one stream re-runs on any).
 * @param fn the read/process body — identical shape to a `usePoll` callback.
 * @param deps re-subscribe deps (like `usePoll`'s).
 * @param opts `safetyMs` (backstop interval) and `active` (caller-side gate).
 */
export function useLogStream(
  streams: string | string[],
  fn: (isCancelled: () => boolean) => void | Promise<void>,
  deps: DependencyList = [],
  opts: LogStreamOptions = {},
): void {
  const { safetyMs = 60_000, active = true } = opts;
  const list = Array.isArray(streams) ? streams : [streams];
  const key = list.join(",");
  const fnRef = useRef(fn);
  useEffect(() => { fnRef.current = fn; });

  // Initial read on mount + a slow backstop poll. `immediate` gives the current state right away;
  // `active:false` short-circuits both this and the subscription below.
  usePoll((isCancelled) => (active ? fnRef.current(isCancelled) : undefined), safetyMs, [key, active, ...deps]);

  // Re-read on any watched stream's change event.
  useEffect(() => {
    if (!active) return;
    let cancelled = false;
    const isCancelled = () => cancelled;
    const uns: UnlistenFn[] = [];
    for (const s of list) {
      void listen(logEventName(s), () => { if (!cancelled) void fnRef.current(isCancelled); })
        .then((un) => { if (cancelled) un(); else uns.push(un); });
    }
    return () => { cancelled = true; uns.forEach((un) => un()); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, active, ...deps]);
}

// The MCP screen's install/version machinery (#885) lifted out of the screen: the per-server
// status map keyed by NAME, the version check on page open (mcp_check_update for each installed
// downloadable server), and the download (catalog) / update (installed) flows that drive it. Only
// downloadable first-party servers have this; built-in/remote servers carry no status.

import { useState, useEffect } from "react";
import { invoke } from "@tauri-apps/api/core";
import { catalogLink, repoNameFromLink, mcpRepoName } from "@/features/mcp/lib/mcpInstall";
import { type McpStat, type McpCheckResult, deriveCheckStat, installedDownloadableNames } from "@/features/mcp/lib/mcpVersioning";
import type { McpServer } from "@/features/mcp/lib/mcpServers";
import type { CatalogItem } from "@/shared/data/mcpCatalog";

export interface UseMcpInstallStatus {
  /** Per-server install/version status (#885), keyed by server NAME. */
  mcpStatus: Record<string, McpStat>;
  /** One-click install (#885): clone → `onCloned` (add to Installed silently) → build. */
  downloadFromCatalog(item: CatalogItem, onCloned: (item: CatalogItem) => void): Promise<void>;
  /** Update (or finish building) an installed downloadable server (#885): pull then rebuild. */
  updateInstalled(server: McpServer): Promise<void>;
}

export function useMcpInstallStatus(mcpServers: McpServer[]): UseMcpInstallStatus {
  // Keyed by server NAME. Refreshed on page open via mcp_check_update; advanced by the download
  // (catalog) and update (installed) actions.
  const [mcpStatus, setMcpStatus] = useState<Record<string, McpStat>>({});
  const setStat = (name: string, s: McpStat) => setMcpStatus(m => ({ ...m, [name]: s }));

  // Version check on every page open (#885): for each installed downloadable server, ask the
  // backend whether its clone is behind its remote (and whether it's built). Best-effort + async;
  // an in-flight download/update is left alone.
  useEffect(() => {
    const servers = installedDownloadableNames(mcpServers);
    if (servers.length === 0) return;
    let cancelled = false;
    for (const name of servers) {
      setMcpStatus(m => (m[name] ? m : { ...m, [name]: "checking" }));
      invoke<McpCheckResult>("mcp_check_update", { name: mcpRepoName(name) })
        .then(r => {
          if (cancelled) return;
          const next = deriveCheckStat(r);
          setMcpStatus(m => (m[name] === "downloading" || m[name] === "building" || m[name] === "updating" ? m : { ...m, [name]: next }));
        })
        .catch(() => {});
    }
    return () => { cancelled = true; };
    // Re-check when the set of installed downloadable servers changes (and on mount).
  }, [installedDownloadableNames(mcpServers).join(",")]); // eslint-disable-line react-hooks/exhaustive-deps

  /** One-click install (#885): clone → add to Installed silently (`onCloned`) → build. */
  async function downloadFromCatalog(item: CatalogItem, onCloned: (item: CatalogItem) => void) {
    if (!item.link) return;
    const repo = repoNameFromLink(item.link);
    setStat(item.name, "downloading");
    try {
      await invoke<string>("mcp_clone", { name: repo, url: item.link });
    } catch {
      setStat(item.name, "error");
      return;
    }
    onCloned(item);
    setStat(item.name, "building");
    try {
      const r = await invoke<{ ok: boolean }>("mcp_build", { name: repo });
      setStat(item.name, r.ok ? "current" : "needs-build");
    } catch {
      setStat(item.name, "needs-build");
    }
  }

  /** Update (or finish building) an installed downloadable server (#885): pull then rebuild. */
  async function updateInstalled(e: McpServer) {
    const link = catalogLink(e.name);
    if (!link) return;
    const repo = repoNameFromLink(link);
    setStat(e.name, "updating");
    try {
      await invoke("mcp_clone", { name: repo, url: link });
      setStat(e.name, "building");
      const r = await invoke<{ ok: boolean }>("mcp_build", { name: repo });
      setStat(e.name, r.ok ? "current" : "needs-build");
    } catch {
      setStat(e.name, "error");
    }
  }

  return { mcpStatus, downloadFromCatalog, updateInstalled };
}

// useModalDismiss (#1541) — the Escape-to-close + overlay-click-to-close pattern that was
// hand-rolled inline across the app's modals (`Dialog.tsx` is the reference implementation).
//
//  - useModalDismiss(onClose, { enabled }) — a window keydown Escape listener → onClose, with
//    cleanup on unmount / deps-change. `enabled` (default true) gates it, e.g. `{ enabled: !busy }`.
//  - overlayDismiss(onClose?) — an onMouseDown/onClick handler that fires onClose ONLY when the
//    event hits the overlay itself (`e.target === e.currentTarget`), so clicks on the inner card
//    don't dismiss. Pass `undefined` (e.g. while busy/deleting) to disable dismissal entirely.

import { useEffect, type MouseEvent } from "react";

export function useModalDismiss(onClose: () => void, opts?: { enabled?: boolean }): void {
  const enabled = opts?.enabled ?? true;
  useEffect(() => {
    if (!enabled) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose, enabled]);
}

/** An overlay click/mousedown handler that dismisses only when the overlay itself is the target.
 *  `onClose === undefined` makes it a no-op (use for a busy/locked modal). */
export function overlayDismiss(onClose?: () => void) {
  return (e: MouseEvent) => {
    if (onClose && e.target === e.currentTarget) onClose();
  };
}

// useNavHistory (#…, org drill + planner page #2492) — an app-wide back/forward navigation history bound
// to the mouse's BACK (X1) and FORWARD (X2) side buttons. A "location" is the active WORKSPACE plus the
// in-workspace navigation the store already tracks: the Planner page (Projects ↔ Org), the Glance drill
// target, and the Org designer's pool drill — so back/forward step through workspace switches, planner
// page switches, and drilling in/out of a project's fleet or an org pool.
// Mounted ONCE (App.tsx). The webview's own back/forward on those buttons is suppressed so this owns them.
import { useEffect, useRef } from "react";
import { useAppStore } from "@/store";
import type { Workspace } from "@/app/registry";
import { log } from "@/shared/lib/core/log";

interface NavLoc {
  workspace: Workspace;
  /** The Planner workspace's page (Projects ↔ Teams ↔ Designs ↔ Algorithms); null on every
   *  other workspace. */
  page: "projects" | "teams" | "designs" | "algorithms" | "sounds" | null;
  /** The Glance drill target; null outside Glance. */
  drill: string | null;
  /** The Org designer's pool drill; null unless the Planner's Org page is showing. */
  teamsDrill: string | null;
}
const eq = (a: NavLoc, b: NavLoc) =>
  a.workspace === b.workspace && a.page === b.page && a.drill === b.drill && a.teamsDrill === b.teamsDrill;

export function useNavHistory() {
  const workspace = useAppStore((s) => s.activeWorkspace);
  const pageMode = useAppStore((s) => s.projectsPageMode);
  const glanceDrill = useAppStore((s) => s.glanceDrill);
  const teamsDrill = useAppStore((s) => s.teamsDrill);
  const setWorkspace = useAppStore((s) => s.setWorkspace);
  const setProjectsPageMode = useAppStore((s) => s.setProjectsPageMode);
  const setGlanceDrill = useAppStore((s) => s.setGlanceDrill);
  const setTeamsDrill = useAppStore((s) => s.setTeamsDrill);

  // Each facet only matters where it is visible; elsewhere a location carries null so history doesn't
  // split on a stale value held by another workspace/page.
  const loc: NavLoc = {
    workspace,
    page: workspace === "projects" ? pageMode : null,
    drill: workspace === "glance" ? glanceDrill : null,
    teamsDrill: workspace === "projects" && pageMode === "teams" ? teamsDrill : null,
  };

  const stack = useRef<NavLoc[]>([loc]);
  const idx = useRef(0);
  // The location a back/forward is applying — so the store change it causes doesn't push a new entry.
  const pending = useRef<NavLoc | null>(null);

  // Record a new entry when the location changes by NORMAL navigation (not our own back/forward). While a
  // back/forward is in flight, skip every push until the target is reached (guards against a multi-`set`
  // apply rendering an intermediate location).
  useEffect(() => {
    if (pending.current) {
      if (eq(pending.current, loc)) pending.current = null;
      return;
    }
    if (eq(stack.current[idx.current], loc)) return;
    stack.current = stack.current.slice(0, idx.current + 1);
    stack.current.push(loc);
    idx.current = stack.current.length - 1;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loc.workspace, loc.page, loc.drill, loc.teamsDrill]);

  // Bind the mouse back/forward buttons (X1 = button 3, X2 = button 4). Refs keep the listener stable.
  useEffect(() => {
    const go = (dir: -1 | 1) => {
      const next = idx.current + dir;
      if (next < 0 || next >= stack.current.length) return;
      idx.current = next;
      const target = stack.current[next];
      pending.current = target;
      setWorkspace(target.workspace);
      if (target.page) setProjectsPageMode(target.page);
      setGlanceDrill(target.workspace === "glance" ? target.drill : null);
      setTeamsDrill(target.teamsDrill);
    };
    // #3946: CAPTURE phase. These were bubble-phase, so any `stopPropagation` between the target and
    // `window` silently swallowed the navigation — and the app has plenty of those (the Glance canvas,
    // the morph overlays, xterm). Capture runs before every one of them, so this hook sees the event
    // first no matter where the pointer is. `pointerup` is handled too: it carries the same `button`
    // values and fires for devices that route through the pointer stack rather than legacy mouse events.
    //
    // A press is LOGGED once per button whether or not it navigates. That is the whole diagnostic: if a
    // press produces no log line, the event never reached the DOM at all — Chromium can consume XBUTTON
    // as a browser-level history accelerator on Windows — and no DOM listener can ever fix it. That case
    // needs native input capture, which is a different fix, and this tells us which one we are in
    // without guessing. jsdom cannot answer it and Playwright cannot synthesize X1/X2.
    const seen = new Set<number>();
    const handled = (e: MouseEvent | PointerEvent): boolean => {
      if (e.button !== 3 && e.button !== 4) return false;
      if (!seen.has(e.button)) {
        seen.add(e.button);
        log.info(`nav: mouse button ${e.button} (${e.button === 3 ? "back" : "forward"}) reached the DOM — binding is live`);
      }
      e.preventDefault();
      return true;
    };
    const onUp = (e: MouseEvent) => { if (handled(e)) go(e.button === 3 ? -1 : 1); };
    // Suppress the webview's native history nav on the other phases so this hook owns the gesture.
    const suppress = (e: MouseEvent) => { handled(e); };
    const opts = true; // capture
    window.addEventListener("mouseup", onUp, opts);
    window.addEventListener("pointerup", onUp as EventListener, opts);
    window.addEventListener("mousedown", suppress, opts);
    window.addEventListener("pointerdown", suppress as EventListener, opts);
    window.addEventListener("auxclick", suppress, opts);
    return () => {
      window.removeEventListener("mouseup", onUp, opts);
      window.removeEventListener("pointerup", onUp as EventListener, opts);
      window.removeEventListener("mousedown", suppress, opts);
      window.removeEventListener("pointerdown", suppress as EventListener, opts);
      window.removeEventListener("auxclick", suppress, opts);
    };
  }, [setWorkspace, setProjectsPageMode, setGlanceDrill, setTeamsDrill]);
}

// useNavigateBridge (#3274, epic #3260) — apply a `bsc navigate` request to the store and ACK it.
//
// WHY THIS EXISTS
// `bsc shot` (#3261) gave bsc eyes; nothing gave it hands. The Design Studio's selection was local React
// state, so nothing outside the UI could select a component and an external session could only photograph
// whatever happened to be on screen. For the overnight loop (#3263) that is disqualifying: it needs
// "component X in theme Y", and without steering it would iterate on stale frames while every log line
// looked reasonable.
//
// THE ROUND TRIP
//   bsc navigate → request file → Rust watcher → `bsc://navigate` → HERE → store → `navigate_ack` → reply
//
// The ack is the point: it makes `bsc navigate … && bsc shot take` race-free rather than hoping the view
// landed first. So this ALWAYS acks — success or a stated error. Silence would strand the Rust waiter
// until its timeout and surface as "the frontend did not apply the navigation", sending someone to debug
// the wrong thing.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { WORKSPACES, type Workspace } from "@/app/registry";
import { PROJECT_MODES } from "@/features/planner";
import { mountedPreviewFrames, type PreviewFrameEntry } from "@/features/designs";
import { log } from "@/shared/lib/core/log";
import { applyNavigate, type NavRequest, type NavAck } from "@/app/navigateBridge";
import { installHumanPresence, humanPresent } from "@/app/humanPresence";

/** How long to wait for the preview frame to settle before acking. Well inside the Rust `ACK_TIMEOUT`
 *  (5s), with room left for the hydrate retry that can precede it — an ack that arrives late is a
 *  "the frontend did not apply the navigation" error, which sends the reader to debug the wrong thing. */
const MOUNT_BUDGET_MS = 1_800;
const MOUNT_POLL_MS = 40;

/** Wait for the preview frame showing `id` to SETTLE (built, or failed), or give up. Polls because the
 *  registry is deliberately React-free and module-level — it has no subscribe, and giving it one would
 *  make every frame's build path depend on a listener that only this bridge reads. A frame mid-rebuild is
 *  absent from the registry by construction, so "absent" here means "not settled yet", never "fine". */
async function settledFrame(id: string): Promise<PreviewFrameEntry | null> {
  const deadline = Date.now() + MOUNT_BUDGET_MS;
  for (;;) {
    const hit = mountedPreviewFrames().find((f) => f.component === id);
    if (hit) return hit;
    if (Date.now() >= deadline) return null;
    await new Promise((r) => setTimeout(r, MOUNT_POLL_MS));
  }
}

/**
 * Listen for `bsc://navigate` and apply it. Mounted once by the shell.
 *
 * Kept as a thin adapter: the DECISION (what a request resolves to, what errors) is pure and lives in
 * `navigateBridge.ts`, so it is unit-testable without Tauri or a rendered app.
 */
export function useNavigateBridge(): void {
  // #4248: the presence listeners live with the bridge that consults them, so a build cannot ship the
  // gate without the signal that feeds it (an always-absent human = the pre-#4248 behaviour, silently).
  useEffect(() => installHumanPresence(), []);

  useEffect(() => {
    let disposed = false;
    const un = listen<NavRequest & { id: string }>("bsc://navigate", (e) => {
      const { id, ...req } = e.payload;
      const resolve = (): NavAck =>
        applyNavigate(req, {
          // A LIVE getter, not `getState()` once: zustand hands out a new object per update, so a
          // captured snapshot would make the ack report the PRE-navigation view — a confident lie.
          read: () => useAppStore.getState(),
          workspaces: WORKSPACES.map((w) => w.key as Workspace),
          pages: PROJECT_MODES.map((p: { id: string }) => p.id),
          humanPresent,
        });

      void (async () => {
        let ack: NavAck;
        try {
          ack = resolve();
          // RE-READ ONCE ON A RESOLVABLE MISS (#navigate-answers-from-a-stale-app-snapshot).
          //
          // `applyNavigate` resolves against the app's HYDRATED copy of the component store, and that
          // copy only refreshes while the Design Studio is visible (`useUiActivity` is mounted there and
          // gated on it). A session that writes a component from a shell while the app shows Console
          // therefore gets "unknown component" for a record `bsc ui get` can print — request #55.
          //
          // A miss is the one moment the app has evidence its snapshot may be behind, so it is where the
          // re-read belongs. Bounded to a SINGLE retry by construction — there is no loop here — so a
          // genuinely unknown id still errors after one extra hydrate instead of spinning. Cheaper than
          // un-gating the activity watcher, which would poll in every workspace to serve a rare write.
          if (ack.retryAfterHydrate) {
            await useAppStore.getState().hydrateComponents();
            if (disposed) return;
            ack = resolve();
          }
        } catch (err) {
          // A throw here would silently strand the Rust waiter. Turn it into a stated error instead.
          ack = { id, error: `navigate threw: ${err instanceof Error ? err.message : String(err)}` };
          log.error(`navigate ${id} threw: ${String(err)}`);
        }
        // OBSERVE THE FRAME rather than trusting the selection. `landed()` reports the store value it
        // just wrote, so before this a component the preview REFUSED to build acked exactly like one
        // that rendered — and since the caller's next move is `bsc shot preview`, that produced a
        // capture of the previously-mounted component with nothing reporting it.
        if (ack.awaitMount) {
          const settled = await settledFrame(ack.awaitMount);
          if (disposed) return;
          if (!settled) {
            ack.mountError =
              `the preview had not settled on '${ack.awaitMount}' within ${MOUNT_BUDGET_MS}ms — do not ` +
              `capture yet; re-read with a bare \`bsc navigate\` before shooting`;
          } else if (settled.status === "error") {
            ack.mountError = `the preview refused to build '${ack.awaitMount}': ${settled.error ?? "no reason given"}`;
          } else {
            ack.mounted = settled.component;
          }
        }
        // `retryAfterHydrate` and `awaitMount` are OURS — strip them rather than shipping fields the
        // Rust `NavAck` never declared. (A field Rust does not declare is dropped SILENTLY, which is how
        // `declined` reached no caller for as long as it existed.)
        const { retryAfterHydrate: _retry, awaitMount: _await, ...wire } = ack;
        void invoke("navigate_ack", { ack: { ...wire, id } }).catch((e2) => {
          // Nothing left to do — the caller will time out. Log it so the cause isn't a mystery.
          log.error(`navigate_ack failed for ${id}: ${String(e2)}`);
        });
      })();
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}

// useNotificationSounds (#3082, epic #3071 P4a) — the app dogfooding its own Sounds library. When the
// opt-in `soundNotifications` flag is ON (default OFF, Settings → Appearance), watch the coordination
// log and play a Signal-kit cue on each NEW completion/wait event since mount: landing/merge → success,
// failure → error, a worker pausing (`bsc-wait`) → notify. Mounted once app-wide (App.tsx).
//
// Baseline discipline: we never voice the backlog. On mount (and each time the flag is re-enabled) the
// first successful read just records the current line count; only lines appended AFTER that sound. A
// shrunk/replaced log re-baselines rather than replaying. While OFF the poll is a no-op (no I/O).
import { useRef } from "react";
import { useAppStore } from "@/store";
import { usePoll } from "@/shared/hooks/usePoll";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import { playCue } from "@/features/sounds/lib/synth";
import { STARTER_KIT } from "@/features/sounds/lib/soundKits";
import { cuesForLines } from "@/features/sounds/lib/notifyCues";

/** Poll cadence for the coord-log watch (ms). Matches the coordinator's own 1 Hz read. */
const POLL_MS = 1000;

export function useNotificationSounds(): void {
  // Count of coord-log lines already accounted for; -1 = "not yet baselined" (re-baseline next read).
  const seen = useRef(-1);
  // Whether the flag was ON last tick — a false→true edge forces a re-baseline so enabling mid-session
  // starts from "now" instead of dumping the backlog.
  const wasOn = useRef(false);

  usePoll(async (isCancelled) => {
    const on = useAppStore.getState().soundNotifications;
    if (!on) { wasOn.current = false; return; }                     // OFF → no I/O
    if (!wasOn.current) { wasOn.current = true; seen.current = -1; } // just enabled → re-baseline

    const res = await readCoordState();
    if (isCancelled() || !res) return;                 // read failure → keep the baseline, retry next tick
    const n = res.lines.length;

    // First read after (re)baseline, or a shrunk/replaced log → set the baseline, voice nothing.
    if (seen.current < 0 || n < seen.current) { seen.current = n; return; }

    // De-dupe within the tick so a burst of e.g. merges doesn't stack identical cues over each other.
    const cues = [...new Set(cuesForLines(res.lines.slice(seen.current)))];
    seen.current = n;
    for (const id of cues) {
      const cue = STARTER_KIT.cues.find((c) => c.id === id);
      if (cue) playCue(cue, STARTER_KIT);
    }
  }, POLL_MS);
}

// usePageTabs -- the shared per-page tab model (#463). Every page's tab bar uses
// this so behavior is identical: the tab order is persisted per page, the page
// "opens the first tab" (so the user's preferred view = whatever they drag to the
// front), reordering persists, and tear-off is wired in by the page.

import { useCallback, useEffect, useMemo } from "react";
import { useAppStore } from "@/store";
import { moveInArray } from "@/shared/lib/core/arrayMove";
import { openDetachedSection } from "@/shared/lib/core/detachSection";
import type { TabItem } from "@/shared/ui/layouts/TabBar";

const EMPTY: string[] = [];

/**
 * Order `defs` by a persisted id list: known ids first (in persisted order),
 * then any defs not in the list (new tabs) appended in their canonical order;
 * stale ids in the list are ignored. Pure — unit-tested.
 */
export function orderTabs(defs: TabItem[], order: string[] | undefined): TabItem[] {
  if (!order || order.length === 0) return defs;
  const byId = new Map(defs.map((d) => [d.id, d]));
  const out: TabItem[] = [];
  for (const id of order) {
    const d = byId.get(id);
    if (d) { out.push(d); byId.delete(id); }
  }
  for (const d of defs) if (byId.has(d.id)) out.push(d);
  return out;
}

export interface PageTabs {
  /** Visible tabs (persisted order, detached sections filtered out). */
  tabs: TabItem[];
  activeId: string;
  select: (id: string) => void;
  reorder: (from: number, to: number) => void;
  /** Tear a section into its own window: opens it, hides it from the bar, and
   *  moves focus off it if it was active. Returns on close/restart. */
  tearOff: (id: string) => void;
}

/**
 * Drive a page's tab bar: returns the persisted-ordered, detached-filtered tabs,
 * the active id (defaults to the first/front visible tab — the user's
 * preference), and select/reorder/tearOff handlers. `pageKey` namespaces both
 * the persisted order and the (session-only) detached set.
 *
 * Pass `controlled` when the active tab lives in the store and is shared across
 * components (e.g. the Projects board, where the bar and the content are separate
 * components) — the hook then reads/writes that instead of the persisted map.
 *
 * The uncontrolled active page is **persisted** per `pageKey` (`activePageTab`), so a
 * workspace reopens on the Page the user last viewed — across an in-session workspace
 * switch and across restart — falling back to the front tab (#463) when there's no
 * memory. A stale persisted id self-heals to the front tab via the validity effect.
 */
export function usePageTabs(
  pageKey: string,
  defs: TabItem[],
  controlled?: { activeId: string; setActive: (id: string) => void },
): PageTabs {
  const order = useAppStore((s) => s.pageTabOrder[pageKey]);
  const setOrder = useAppStore((s) => s.setPageTabOrder);
  const detached = useAppStore((s) => s.detachedSections[pageKey]) ?? EMPTY;
  const setDetached = useAppStore((s) => s.setSectionDetached);
  const persistedActive = useAppStore((s) => s.activePageTab[pageKey]);
  const setPersistedActive = useAppStore((s) => s.setActivePageTab);

  const ordered = useMemo(() => orderTabs(defs, order), [defs, order]);
  const tabs = useMemo(() => ordered.filter((t) => !detached.includes(t.id)), [ordered, detached]);
  const setUncontrolled = useCallback((id: string) => setPersistedActive(pageKey, id), [pageKey, setPersistedActive]);
  const activeId = controlled ? controlled.activeId : (persistedActive ?? tabs[0]?.id ?? "");
  const setActiveId = controlled ? controlled.setActive : setUncontrolled;

  // Keep the active id valid if the visible set changes (order/defs/detach shift):
  // a persisted id that no longer resolves to a visible tab heals to the front tab.
  // Skip while there are no tabs yet so we don't persist an empty selection.
  useEffect(() => {
    if (tabs.length > 0 && !tabs.some((t) => t.id === activeId)) setActiveId(tabs[0].id);
  }, [tabs, activeId, setActiveId]);

  // Reorder operates on visible positions; translate to the full ordered list so
  // detached sections keep their place.
  const reorder = useCallback((from: number, to: number) => {
    const fullIds = ordered.map((t) => t.id);
    const fromFull = fullIds.indexOf(tabs[from]?.id);
    const toFull = fullIds.indexOf(tabs[to]?.id);
    if (fromFull < 0 || toFull < 0) return;
    setOrder(pageKey, moveInArray(fullIds, fromFull, toFull));
  }, [pageKey, ordered, tabs, setOrder]);

  const tearOff = useCallback((id: string) => {
    const def = ordered.find((t) => t.id === id);
    openDetachedSection(pageKey, id, def?.label, () => setDetached(pageKey, id, false));
    setDetached(pageKey, id, true);
    if (activeId === id) {
      const next = tabs.find((t) => t.id !== id);
      if (next) setActiveId(next.id);
    }
  }, [pageKey, ordered, tabs, activeId, setDetached, setActiveId]);

  return { tabs, activeId, select: setActiveId, reorder, tearOff };
}

// Per-pane token + cost telemetry (#1181). Reads the latest rollup keyed by pane id — each pane's
// latest Claude transcript parsed for its `usage` totals AND its `message.model`. Feeds two surfaces:
// the header model pill's "actual running model" (so it reflects what the CLI is really running, not
// just the configured model) and the Telemetry · cost view.
//
// IN-PROCESS since #4074 (`logs_usage`), not the `bsc` bridge. #3630 moved the hot pollers off the
// bridge and left this one on it as "low-frequency" — but it polls every 4s, which made it the app's
// single biggest process spawner (415 calls in a 27-minute window). Every spawn blocked Tauri's main
// thread, so the invoke queue backed up to 25s and unrelated commands waited behind it. Same rows:
// `logs_usage` calls the same `logs::cost::usage` the CLI's `cost` verb does.
//
// ONE POLLER FOR THE WHOLE APP (#one-poller-per-datum-not-one-per-consumer). The value is a map of
// EVERY pane, built from ONE `logs_usage` call — the data is global, so polling it per consumer is
// pure duplication. It was instantiated twice: `consolepage`, and `telemetryview`, which is a PANE
// VIEW rendered once per pane showing it. So every extra Telemetry pane added another 4s poll of the
// same app-wide rollup, and that read is the most expensive one in the app — it re-parses every
// referenced Claude transcript on each call (#the-cost-rollup-reparses-every-transcript-on-every-poll).
// Measured 655 calls / 324.8s in one session.
//
// The dedupe lives INSIDE the hook so the signature is unchanged and no consumer moves — the blast
// radius stays at this module. Deliberately NOT a new Zustand key: a store field rewritten every 4s
// wakes every subscriber, and `two-store-keys-drive-more-than-half-the-apps-jank` records what that
// already costs here. A shared subscription gives the same dedupe without adding a jank source.
import { useEffect, useState } from "react";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";

/** One pane's token + cost rollup, as serialized by `bsc logs cost --full` (`logs::cost::Usage` —
 *  plain snake_case, no serde rename, so the keys match the struct). */
export interface PaneTokenUsage {
  pane: string;
  session_id: string;
  /** The model the CLI recorded in the transcript (`message.model`) — the ACTUAL running model. */
  model: string;
  input_tokens: number;
  output_tokens: number;
  cache_creation_tokens: number;
  cache_read_tokens: number;
  cost_usd: number;
}

const EMPTY: Map<string, PaneTokenUsage> = new Map();

/** How often the ONE shared poller refreshes while the rollup keeps CHANGING — the working rate,
 *  matching the coordination/CI pollers. */
const INTERVAL_MS = 4000;
/** The slowest it backs off to while the answer is unchanged (#pollers-back-off-when-a-pane-is-idle).
 *
 *  This read is the most expensive one in the app — it re-parses every referenced Claude transcript on
 *  each call — and it was 655 calls / 324.8s in one session, much of it asking a quiet app the same
 *  question. The cap bounds how late a change can be noticed: a session that starts working is seen
 *  within this, then the rate snaps back to `INTERVAL_MS` on the very next tick. */
const IDLE_INTERVAL_MS = 32000;

type Listener = (m: Map<string, PaneTokenUsage>) => void;

/** Module-level, so every consumer in the process shares one interval and one in-flight invoke. */
const listeners = new Set<Listener>();
let timer: ReturnType<typeof setTimeout> | null = null;
/** The most recent rollup, replayed to a late subscriber so it renders immediately rather than
 *  waiting a full interval — mounting a Telemetry pane should not show empty for 4s. */
let latest: Map<string, PaneTokenUsage> = EMPTY;
/** The row cap the poller runs with — the largest any live consumer asked for, so one consumer's
 *  smaller limit can never truncate another's view of the same shared map. */
let activeLimit = 0;
/** Guards against a second fetch starting while one is in flight; a slow read must not stack up. */
let inFlight = false;
/** The current gap between reads — grows while nothing changes, resets the moment something does. */
let intervalMs = INTERVAL_MS;
/** A cheap signature of the last rollup, to tell "same answer" from "new answer" without deep-comparing
 *  a map on every tick. Rows are capped by `limit`, so this stays small. */
let lastSignature = "";

/** Re-arm the timer at `intervalMs`. `setInterval` cannot change its own period, so the poller uses a
 *  chained `setTimeout` — the alternative is a fixed fast interval that mostly decides to do nothing,
 *  which still wakes the main thread on every tick and is the thing being removed. */
function rearm(): void {
  if (timer) clearTimeout(timer);
  timer = setTimeout(() => void tickThenRearm(), intervalMs);
}

async function tickThenRearm(): Promise<void> {
  await fetchOnce();
  if (listeners.size > 0) rearm(); // a late unmount during the read must not resurrect the poller
}

async function fetchOnce(): Promise<void> {
  if (inFlight) return;
  inFlight = true;
  // Remember what this read asked for: a consumer wanting MORE rows can join while it is in flight,
  // and the shared map must converge on the larger limit rather than leaving that consumer with a
  // truncated view until the next tick.
  const limitUsed = activeLimit;
  try {
    const rows = await safeInvoke<PaneTokenUsage[]>("logs_usage", { limit: limitUsed }, []);
    const signature = JSON.stringify(rows ?? []);
    // UNCHANGED ⇒ ask less often. A quiet app is the common case, and this read is the app's most
    // expensive; a change resets to the working rate on the very next tick, so responsiveness while
    // something is actually happening is untouched.
    if (signature === lastSignature) {
      intervalMs = Math.min(intervalMs * 2, IDLE_INTERVAL_MS);
      return; // nothing moved: no new Map, no listener wake, no re-render
    }
    lastSignature = signature;
    intervalMs = INTERVAL_MS;
    const m = new Map<string, PaneTokenUsage>();
    for (const r of rows ?? []) m.set(r.pane, r);
    latest = m;
    for (const l of listeners) l(m);
  } finally {
    inFlight = false;
  }
  if (activeLimit > limitUsed && listeners.size > 0) await fetchOnce();
}

/**
 * Poll `logs_usage` and return the latest per-pane rollup, keyed by pane id. Errors and a missing log
 * degrade to an empty map so callers fall back to the configured model.
 *
 * Every caller shares ONE poller: mounting N consumers issues one invoke per interval, not N. The
 * poll starts with the first consumer and stops with the last, so nothing polls with nobody listening.
 */
export function usePaneTokenUsage(limit = 64): Map<string, PaneTokenUsage> {
  const [byPane, setByPane] = useState<Map<string, PaneTokenUsage>>(latest);

  useEffect(() => {
    const listener: Listener = setByPane;
    listeners.add(listener);
    // The shared poller runs at the LARGEST limit any live consumer wants. Recomputed on unmount too,
    // so a big consumer leaving does not leave the poll permanently over-fetching.
    const raised = limit > activeLimit;
    if (raised) activeLimit = limit;
    setByPane(latest); // replay, so a late mount is not blank until the next tick
    if (!timer) {
      intervalMs = INTERVAL_MS; // a fresh subscription starts at the working rate, never mid-back-off
      rearm();
      void fetchOnce(); // lead with a read rather than waiting one interval for the first value
    } else if (raised) {
      // Already polling, but for fewer rows than this consumer needs — refresh now instead of
      // showing it a truncated map for up to a full interval. `fetchOnce` folds this into the
      // in-flight read if one is running.
      void fetchOnce();
    }
    return () => {
      listeners.delete(listener);
      if (listeners.size === 0) {
        if (timer) clearTimeout(timer);
        timer = null;
        activeLimit = 0;
        intervalMs = INTERVAL_MS;
        lastSignature = "";
        // Drop the cache too: with nobody listening there is nothing refreshing it, so by the time a
        // consumer mounts again it could be arbitrarily stale — and cost is a number worth being
        // right. The first mount fetches immediately, so this costs one frame, not one interval.
        latest = EMPTY;
      }
    };
  }, [limit]);

  return byPane;
}

// usePlanConfirmations (#1775, extracted from Planning.tsx) — the stage gate-confirm/skip logic:
//   • pendingConfirm — the active stage's drafted sections that "approve & continue" confirms in one
//     click (plus the Features one-click once every feature is populated).
//   • confirmStageKeys — the single stage-completion primitive (#1068): confirm each pending section
//     + tell the planner to continue. Shared by the manual button, the autopilot, and auto-complete.
//   • auto-advance effect (#1068) — when the global flag is on, confirm the ready set after a beat.
//   • onSkipStage (#921) — skip the active optional stage + tell the planner to move on.
import { useMemo, useCallback, useEffect, useRef } from "react";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { titleForTopic, FEATURES_KEY } from "@/features/planner/stages/planTopics";
import { buildSectionConfirmMessage, buildSectionSkipMessage } from "@/features/planner/session/planningSession";
import { stageConfirmKeys } from "@/features/planner/stages/planStageDerive";
import { featuresAwaitingConfirm } from "@/features/planner/issues/featureList";
import { shouldAutoCompleteGate } from "@/features/planner/stages/focusedPlan";
import type { stagesFrom } from "@/features/planner/stages/focusedPlan";
import type { Section } from "@/features/planner/github/ghStructure";
import type { BlueprintStage } from "@/features/planner/stages/blueprints";

type Stages = ReturnType<typeof stagesFrom>;

export function usePlanConfirmations(opts: {
  stages: Stages;
  focusActiveIdx: number;
  sections: Section[];
  planSecs: BlueprintStage[];
  confirmedSet: Set<string>;
  featureState: Parameters<typeof featuresAwaitingConfirm>[0];
  featureCycle: string[];
  effectiveProjectId: string;
  paneId: string;
  confirmPlanStage: (projectId: string, key: string) => void;
  skipPlanStage: (projectId: string, key: string) => void;
  autoCompleteGates: boolean;
  /** autoPlanWithClaude && llmHasKey — the autopilot is running (and owns confirmation). */
  autoPlanActive: boolean;
}) {
  const {
    stages, focusActiveIdx, sections, planSecs, confirmedSet, featureState, featureCycle,
    effectiveProjectId, paneId, confirmPlanStage, skipPlanStage, autoCompleteGates, autoPlanActive,
  } = opts;

  // The active stage's drafted sections "approve & continue" confirms in one click (#807-followup)
  // — so the user approves a whole stage at once. Empty ⇒ nothing pending (the gate drives the button).
  const pendingConfirm = useMemo(() => {
    const activeKey = stages[focusActiveIdx]?.key;
    const activeSec = activeKey ? planSecs.find((s) => s.key === activeKey) : undefined;
    const base = stageConfirmKeys(activeKey, sections, !!activeSec?.gateRule, !!activeKey && confirmedSet.has(activeKey));
    // Features (#plan-db): once every feature in the roster is populated, offer the one-click confirm
    // that completes the stage. Until then the gate holds, so a single feature can't auto-advance.
    if (activeKey === FEATURES_KEY && featuresAwaitingConfirm(featureState, confirmedSet.has(FEATURES_KEY)) && featureCycle.length === 0) {
      return base.includes(FEATURES_KEY) ? base : [...base, FEATURES_KEY];
    }
    return base;
  }, [stages, focusActiveIdx, sections, planSecs, confirmedSet, featureState, featureCycle]);

  // The single stage-completion primitive (#1068): confirm each pending section + tell the planner to
  // continue. One path every gate advances through, so behaviour stays identical whether the user
  // clicks, the autopilot drives, or a gate self-advances.
  const confirmStageKeys = useCallback((keys: string[]) => {
    if (keys.length === 0) return;
    for (const k of keys) confirmPlanStage(effectiveProjectId, k);
    const name = keys.map((k) => titleForTopic(k)).join(", ") || "section";
    fireInvoke("pty_write", { paneId, data: buildSectionConfirmMessage(name) + "\r" }, console.error);
  }, [effectiveProjectId, paneId, confirmPlanStage]);

  // Auto-advance gates (#1068): when the global flag is on and the ACTIVE stage has drafted sections
  // awaiting confirmation, confirm them automatically after a short beat — the same action the
  // "approve & continue" button performs. Default off. Steps aside while the autopilot runs. The ref
  // stops a ready set from being re-confirmed on every render.
  const autoConfirmRef = useRef<string>("");
  useEffect(() => {
    if (!shouldAutoCompleteGate(autoCompleteGates, autoPlanActive, pendingConfirm)) return;
    const key = `${effectiveProjectId}|${pendingConfirm.join(",")}`;
    if (autoConfirmRef.current === key) return;
    const t = setTimeout(() => {
      autoConfirmRef.current = key;
      confirmStageKeys(pendingConfirm);
    }, 800);
    return () => clearTimeout(t);
  }, [autoCompleteGates, autoPlanActive, pendingConfirm, effectiveProjectId, confirmStageKeys]);

  // The user deliberately skips the active optional stage (#921): resolve its gate + tell the planner.
  const onSkipStage = useCallback(() => {
    const stage = stages[focusActiveIdx];
    if (!stage) return;
    skipPlanStage(effectiveProjectId, stage.key);
    fireInvoke("pty_write", { paneId, data: buildSectionSkipMessage(stage.name) + "\r" }, console.error);
  }, [stages, focusActiveIdx, skipPlanStage, effectiveProjectId, paneId]);

  return { pendingConfirm, confirmStageKeys, onSkipStage };
}

// usePlanFocusedPane (#1490/#652, extracted from Planning.tsx) — the focused-pane SELECTION and its
// derived advance-bar/pill/prompt-help. Owns `focusSel` (null = auto-follow the active stage; a
// number = a user-pinned selection), resets it on a project/blueprint switch, and derives:
//   • focusSelectedIdx — the clamped resolved index (selection ?? active).
//   • focusFooter — the advance-bar action (footerAction → resolveFooter); the primary is lit by
//     pendingConfirm, and a Skip control (skipEnabled) RENDERS only when the active stage is
//     skippable now (its `skipWhen` rule passes / it's optional) or gate-override is on (#2854).
//   • focusPill — the selected stage's gate pill.
//   • focusStagePrompt — the SINGLE current-step prompt for the SELECTED stage (the header "?"
//     helper), resolved from the stage's substep progress (#2859).
// The JSX wires `setFocusSel` into onSelect/onBack/onSkip/onPrimary. Behavior-preserving move — the
// state, reset effect, and derivations are verbatim; only their call-site moved below usePlanGates +
// usePlanConfirmations (whose `pendingConfirm` the footer reads). The skip/confirm/publish actions
// stay in the component (they close over usePlanConfirmations + usePlanPublish).
import { useState, useEffect, useMemo } from "react";
import { clampIndex, gatePill, footerAction, resolveFooter, type stagesFrom, isUserGated } from "@/features/planner/stages/focusedPlan";
import { activeStagePrompt } from "@/features/planner/session/plannerConductor";
import type { BlueprintStage } from "@/features/planner/stages/blueprints";

type Stages = ReturnType<typeof stagesFrom>;

export interface PlanFocusedPaneOpts {
  /** The blueprint-driven focused-pane stages (from usePlanGates). */
  stages: Stages;
  /** The live active-stage index (from usePlanGates). */
  focusActiveIdx: number;
  /** Whether the whole plan's gate is met (from usePlanGates). */
  planComplete: boolean;
  /** Whether the active stage's gate is satisfied (from usePlanGates). */
  focusGateReady: boolean;
  /** The active stage's drafted-but-unconfirmed sections (from usePlanConfirmations) — lights the
   *  "approve & continue" footer. */
  pendingConfirm: string[];
  /** Gate-override toggle (#1285) — allows force-advancing a blocking gate. */
  allowGateOverride: boolean;
  /** The blueprint's stages — resolves the selected stage's injectable prompts by key (#815). */
  planSecs: BlueprintStage[];
  /** #2859 — the substep keys already resolved for the current plan (a section file written or a
   *  step confirmed), so the "?" helper can pick the CURRENT-step prompt via `activeSubstep`. */
  stageDone: Set<string>;
  /** #2859 — whether the Features workshop loop is complete (every feature defined), the completion
   *  signal for the one loop substep the "?" helper can't infer from written section files. */
  featuresComplete: boolean;
  /** #2121 — the active UI stage's design is missing or stale (not routed / changed since routed),
   *  so its primary footer action becomes "route design" instead of "approve & continue". */
  uiNeedsRoute: boolean;
  /** Selection resets when either changes. */
  effectiveProjectId: string;
  effectiveBlueprintId: string;
}

export function usePlanFocusedPane(opts: PlanFocusedPaneOpts) {
  const {
    stages, focusActiveIdx, planComplete, focusGateReady, pendingConfirm,
    allowGateOverride, planSecs, effectiveProjectId, effectiveBlueprintId, uiNeedsRoute,
    stageDone, featuresComplete,
  } = opts;

  // The SELECTION — auto-follows the active stage (`focusSel` null) or pins to a user pick; reset on
  // project/blueprint switch. `stages`/`focusActiveIdx` come from usePlanGates.
  const [focusSel, setFocusSel] = useState<number | null>(null);
  useEffect(() => { setFocusSel(null); }, [effectiveProjectId, effectiveBlueprintId]);
  const focusSelectedIdx = clampIndex(focusSel ?? focusActiveIdx, stages.length);

  // Whether the active stage is SKIPPABLE right now (#2854) — its declarative `skipWhen` rule passes
  // (e.g. an empty Features stage) or it's intrinsically optional. This drives whether the footer
  // renders a Skip control AT ALL: a required stage like Discovery shows none (no disabled ghost).
  const activeSkippable = stages[focusActiveIdx]?.skippable === true;
  // #2121: on the active UI stage with missing/stale design, the primary action routes the design.
  const routeDesign = stages[focusActiveIdx]?.key === "ui" && uiNeedsRoute;
  // #funnel-ui-into-stores: does the ACTIVE stage still hold a user gate? Everything that does not
  // advances under the requirement's authority (#funnel-unattended-director), so its bar reports
  // progress instead of offering an approval the user no longer owns.
  const activeUserGated = isUserGated(stages[focusActiveIdx]?.key);
  const footerRaw = footerAction(
    focusSelectedIdx, focusActiveIdx, planComplete, focusGateReady, routeDesign, activeUserGated,
  );
  // Let "approve & continue" light up as soon as there are drafted sections to confirm (clicking
  // confirms them, see onPrimary); resolveFooter also sets `skipEnabled` from skippable + override.
  const focusFooter = resolveFooter(footerRaw, pendingConfirm.length, allowGateOverride, activeSkippable);
  const focusSelStage = stages[focusSelectedIdx];
  const focusPill = focusSelStage ? gatePill(focusSelStage) : "wait";
  // The SINGLE current-step prompt for the SELECTED stage — the header "?" helper shows one prompt at
  // a time (#2859), resolved from substep progress (`activeSubstep`). The only loop substep the helper
  // can't infer from written files is the Features workshop, so `loopDone` is fed only for that stage.
  // Resolve the section BY KEY (stages is a filtered subset of planSecs, #815).
  const selKey = focusSelStage?.key;
  const focusStagePrompt = useMemo(
    () => activeStagePrompt(planSecs.find(s => s.key === selKey), stageDone, selKey === "features" && featuresComplete),
    [planSecs, selKey, stageDone, featuresComplete]);

  return { setFocusSel, focusSelectedIdx, focusPill, focusFooter, focusStagePrompt };
}

// usePlanGates (#1474) — the planner's gate/`signals` derivation, extracted verbatim from
// Planning.tsx. Owns the live `stageState` snapshot, the lint/injection gates, the skip/confirm
// signal bags, the flat `signals` bag the declarative section gates read, and the focused-pane
// derivations (`stages`, active index, current-gate-ready, plan-complete, status label).
//
// Pure derivation, no side effects. `planSecs` (the blueprint sections) and the focused-pane
// SELECTION state (`focusSel`/`focusSelectedIdx`/`focusSelStage`) STAY in Planning and are passed
// in / read off this hook's outputs — only the auto-derived `stages`/`focusActiveIdx` move here.

import { useMemo } from "react";
import type { Section } from "@/features/planner/github/ghStructure";
import type { BlueprintStage } from "@/features/planner/stages/blueprints";
import { skippedSignal, confirmedSignal, planStagesComplete } from "@/features/planner/stages/blueprints";
import { derivePlanStageState, planStateToSignals } from "@/features/planner/stages/planStageDerive";
import { FEATURES_KEY } from "@/features/planner/stages/planTopics";
import { parseIssuesFile } from "@/features/planner/issues/planIssues";
import { featuresGateComplete, featuresSummary } from "@/features/planner/issues/featureList";
import { findPlanGaps } from "@/features/planner/lib/lintPlan";
import { findPlanInjections, injectionGate } from "@/features/planner/lib/planInjection";
import { deploymentDefined } from "@/features/planner/lib/deployConfig";
import { marketDefined } from "@/features/planner/lib/marketConfig";
import { transformationsConfirmed, type TransformationRow } from "@/features/planner/lib/transformations";
import { allSourcesConnected, migrationActive, dataModelSignals } from "@/features/planner/lib/sourceConfig";
import { unlockedSharedRepos } from "@/features/planner/issues/dependencies";
import { stagesFrom, activeIndex, currentGateReady } from "@/features/planner/stages/focusedPlan";
import { classifySignals, type ClassifyConfig } from "@/features/planner/lib/classifyConfig";

interface PlanGatesDeps {
  sections: Section[];
  /** The active blueprint's sections (stays in Planning; passed in as gate input). */
  planSecs: BlueprintStage[];
  ctxRequired: string[];
  publishRepos: string[];
  planFleet: Record<string, { streams: { id: string; repo: string }[] }>;
  planAutomations: Record<string, unknown[]>;
  featureIssues: unknown[];
  effectiveProjectId: string;
  requiresUi: boolean;
  uiCounts: { approved: number; total: number };
  featureState: ReturnType<typeof featuresSummary>;
  featureCycle: string[];
  confirmedSet: Set<string>;
  skippedSet: Set<string>;
  planDependencies: Parameters<typeof unlockedSharedRepos>[0];
  sourceCfg: Parameters<typeof migrationActive>[0];
  injectionHardGate: boolean;
  planInjectionAck: Record<string, string>;
  deployCfg: Parameters<typeof deploymentDefined>[0];
  /** The market-stage assessment (#2430) — drives the `marketDefined` gate signal. */
  marketCfg: Parameters<typeof marketDefined>[0];
  /** The transformations rows (#2509) — drive the `transformationsConfirmed` gate signal. */
  transformationRows: TransformationRow[];
  /** The planner's per-project classification (#3784) — drives the source/mcp/skills/automations
   *  visibility signals (all default OFF → those stages hidden until the planner opts in), plus the
   *  app-type / lifecycle signals (`appType:*`, `lifecycle:*`, `hasUserInterface`) a stage's
   *  `appliesWhen` keys on. */
  classifyCfg: ClassifyConfig | undefined;
  /** How many skills the project has (resolveSkills length) — the skills stage also shows when a
   *  project has >=1 skill even if the planner didn't pre-flag needsSkills (research -> skills). */
  projectSkillCount: number;
}

export function usePlanGates(deps: PlanGatesDeps) {
  const {
    sections, planSecs, ctxRequired, publishRepos, planFleet, planAutomations,
    featureIssues, effectiveProjectId, requiresUi, uiCounts, featureState, featureCycle,
    confirmedSet, skippedSet, planDependencies, sourceCfg, injectionHardGate, planInjectionAck,
    deployCfg, marketCfg, transformationRows, classifyCfg, projectSkillCount,
  } = deps;

  // The live snapshot the declarative section gates read.
  const stageState = useMemo(() => {
    const streams = planFleet[effectiveProjectId]?.streams ?? [];
    const issueCount =
      parseIssuesFile(sections.find(s => s.k === "issues")?.content ?? "").length + featureIssues.length;
    return derivePlanStageState({
      sections: sections.map(s => ({ k: s.k, state: s.state })),
      discoveryRequired: ctxRequired,
      repoCount: publishRepos.length,
      issueCount,
      fleetStreams: streams.length,
      // Unified role→profile model: every stream auto-gets its role's default profile at launch
      // (no per-stream generated profile to assign), so "profiles complete" simply means the fleet
      // has been planned — i.e. there are streams.
      fleetProfilesComplete: streams.length > 0,
      automationsAck: (planAutomations[effectiveProjectId]?.length ?? 0) > 0,
      // #3905: was hardcoded `false`, which made the Skills gate ("assign skills to the fleet")
      // UNSATISFIABLE — nothing ever set it true, so once the stage applied it blocked the plan
      // forever and triage became unreachable. Derived like `automationsAck` above: the fleet has
      // skills once the project resolves at least one. A project the planner flagged `needsSkills`
      // but assigned NO skills still blocks, which is exactly what the gate label means.
      skillsAck: projectSkillCount > 0,
      requiresUi,
      ui: uiCounts,
      // Routing dropped design files to the project completes the UI stage — recorded as a
      // confirmation of the `ui` section so it persists (#837).
      uiRouted: confirmedSet.has("ui"),
      // Features completes ONLY when every feature is populated AND the user has confirmed the set
      // (#plan-db) — `allConfirmed` (all-defined) alone used to auto-advance after a single feature.
      // Folding the user-confirm in here keeps the gate signal (`featuresConfirmed`) unchanged.
      features: { count: featureState.count, allConfirmed: featuresGateComplete(featureState, confirmedSet.has(FEATURES_KEY)) && featureCycle.length === 0 },
      // Dependencies (#1111/#1127): the Deploy gate passes once ≥1 library is locked in the manifest.
      dependencies: { count: planDependencies.length },
      // Source migration (#1205): the scan drives whether the source stage applies + its gate
      // signals, so the source-inferred schema can dictate features/structure.
      migrationSourceEnabled: migrationActive(sourceCfg),
      dataModelSignals: dataModelSignals(sourceCfg),
    });
  }, [sections, ctxRequired, publishRepos, planFleet, planAutomations, featureIssues, effectiveProjectId, requiresUi, uiCounts, featureState, featureCycle, confirmedSet, planDependencies, sourceCfg]);
  // lint-as-gate (#897 Phase 4b — lint-plan folded into the declarative gate). A WRITTEN section
  // (drafted/confirmed; pending ones aren't authored yet) must not carry a deliberate "fill this
  // in later" marker (TODO / TBD / FIXME / XXX / TKTK). Scanned ONLY over sections that belong to
  // the ACTIVE blueprint (so stale files from a prior blueprint can't block), and only those
  // markers — NOT ellipsis or the word "placeholder", which are normal prose and were
  // false-positiving (#918). Surfaced as `hasPlanGaps`; the gate requires it false, absent-safe.
  const hasPlanGaps = useMemo(() => {
    const enabled = new Set(planSecs.map((s) => s.key));
    const written: Record<string, string> = {};
    for (const s of sections) if (s.state !== "pending" && enabled.has(s.k)) written[`${s.k}.md`] = s.content ?? "";
    return findPlanGaps(written).some((g) => g.endsWith("unresolved placeholder"));
  }, [sections, planSecs]);
  // Plan-injection provenance gate (#1107): scan the planner-authored section prose for injected
  // instructions, then gate plan→fleet promotion. Acknowledge-to-clear by default; hard-block when
  // the `injectionHardGate` setting is on. Surfaced as a banner; `cleared` gates publish.
  const injectionGateState = useMemo(() => {
    const enabled = new Set(planSecs.map((s) => s.key));
    const written: Record<string, string> = {};
    for (const s of sections) if (s.state !== "pending" && enabled.has(s.k)) written[`${s.k}.md`] = s.content ?? "";
    return injectionGate(findPlanInjections(written), { hardGate: injectionHardGate, ackSig: planInjectionAck[effectiveProjectId] });
  }, [sections, planSecs, injectionHardGate, planInjectionAck, effectiveProjectId]);
  // User-skipped optional stages (#921) surface as `skipped:<key>` signals so the data-driven
  // gate model (`stageDone`) treats them as resolved.
  const skipSignals = useMemo(() => {
    const out: Record<string, boolean> = {};
    for (const k of skippedSet) out[skippedSignal(k)] = true;
    return out;
  }, [skippedSet]);
  // A gateless ("informational") section is done only once CONFIRMED (#664) — `stageDone` reads a
  // `confirmed:<key>` signal. Workspace those so a confirmed gateless stage (testing, cleanup, the data
  // stages, a user-authored stage, …) reads as complete and the frontier advances (#954).
  const confirmSignals = useMemo(() => {
    const out: Record<string, boolean> = {};
    for (const k of confirmedSet) out[confirmedSignal(k)] = true;
    return out;
  }, [confirmedSet]);
  const signals = useMemo(() => {
    // Shared-deps gate (#1429): every repo built by 2+ streams must have its deps locked; single-owner
    // repos (and no-fleet plans) auto-satisfy. Derived from the fleet streams' repos + the manifest.
    const repoStreams: Record<string, string[]> = {};
    for (const s of (planFleet[effectiveProjectId]?.streams ?? [])) { if (s.repo) (repoStreams[s.repo] ??= []).push(s.id); }
    const sharedDepsLocked = unlockedSharedRepos(planDependencies, repoStreams).length === 0;
    // The Structure/Plan gate (#1912): the feature DAG is defined (≥1 feature) and acyclic. This
    // replaced the old `featuresPhased` (every feature assigned a roadmap phase) — sequencing is now
    // expressed purely via feature `dependsOn`, with no milestone phases.
    const featuresDefined = featureState.count > 0 && featureCycle.length === 0;
    return { ...planStateToSignals(stageState), hasPlanGaps, featuresDefined, deploymentDefined: deploymentDefined(deployCfg), marketDefined: marketDefined(marketCfg), transformationsConfirmed: transformationsConfirmed(transformationRows), sharedDepsLocked, sourcesConnected: allSourcesConnected(sourceCfg), classified: classifyCfg !== undefined, needsMarket: !!classifyCfg?.needsMarket, needsSource: !!classifyCfg?.needsSource, needsMcp: !!classifyCfg?.needsMcp, needsAutomations: !!classifyCfg?.needsAutomations, needsSkills: !!classifyCfg?.needsSkills || projectSkillCount > 0, ...classifySignals(classifyCfg), ...skipSignals, ...confirmSignals };
  }, [stageState, hasPlanGaps, featureState, featureCycle, deployCfg, marketCfg, transformationRows, sourceCfg, skipSignals, confirmSignals, planFleet, effectiveProjectId, planDependencies, classifyCfg, projectSkillCount]);

  // Focused pane (#652): one stage at a time. `stages` derive from the blueprint sections +
  // signals; the active stage auto-follows the frontier (the user-pick SELECTION stays in Planning).
  const stages = useMemo(() => stagesFrom(planSecs, signals), [planSecs, signals]);
  const focusActiveIdx = useMemo(() => activeIndex(stages), [stages]);
  const focusGateReady = useMemo(() => currentGateReady(planSecs, signals), [planSecs, signals]);
  const planComplete = useMemo(() => planStagesComplete(planSecs, signals), [planSecs, signals]);
  const currentStage = stages[focusActiveIdx]?.key ?? "";
  const planStatusLabel = planComplete ? "complete" : currentStage ? "in_progress" : "starting";
  // Legacy alias kept for the publish/recovery readers (#854): the dynamic blueprint gate IS the
  // completion gate.
  const planReady = planComplete;

  return { injectionGateState, stages, focusActiveIdx, focusGateReady, planComplete, currentStage, planStatusLabel, planReady };
}

// usePlanMcpDownloads (#1474) — the planner's MCP download-confirmation queue, extracted verbatim
// from Planning.tsx. A blueprint / planner-assigned first-party MCP server can install from source;
// rather than cloning that third-party code silently, each not-yet-installed server is queued here
// and surfaced in a modal for the user to confirm. `enqueueMcpDownloads` is a stable callback safe
// to call from the blueprint effect AND the plan.db poll without staleness; `confirm` clones+builds
// the queue; `cancel` dismisses it (keeping the seen-set so skipped servers don't re-prompt).

import { useCallback, useRef, useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { catalogLink, repoNameFromLink } from "@/features/mcp";
import { type McpDownloadItem } from "@/features/planner/pane/McpDownloadModal";
import { MCP_CATALOG } from "@/shared/data/mcpCatalog";

export interface PlanMcpDownloads {
  /** Queue downloadable catalog servers (by name) for the confirmation modal, skipping any already
   *  installed or already queued. */
  enqueueMcpDownloads: (names: string[]) => Promise<void>;
  /** The pending download queue (rendered by McpDownloadModal). */
  mcpDownloads: McpDownloadItem[];
  /** Download (clone + build) every still-pending/failed queued server, advancing its row status. */
  confirmMcpDownloads: () => Promise<void>;
  /** Dismiss the modal: drop the queue but keep the seen-set so skipped servers don't re-prompt. */
  cancelMcpDownloads: () => void;
}

export function usePlanMcpDownloads(): PlanMcpDownloads {
  // Download-confirmation queue (#1055): the blueprint a project uses and the servers the planner
  // assigns can pull in first-party MCP servers that install from source. Instead of cloning that
  // third-party code silently, we queue each not-yet-installed server here and surface a modal with
  // its repo link; the user confirms before anything downloads. `mcpDownloadSeen` guards against
  // re-queuing the same server (so a re-applied blueprint / poll tick doesn't nag).
  const [mcpDownloads, setMcpDownloads] = useState<McpDownloadItem[]>([]);
  const mcpDownloadSeen = useRef<Set<string>>(new Set());

  // Queue downloadable catalog servers (by name) for the confirmation modal, skipping any already
  // installed or already queued. State-free (refs + functional setState) so it's a stable callback
  // safe to invoke from the blueprint effect AND the plan.db poll without staleness.
  const enqueueMcpDownloads = useCallback(async (names: string[]) => {
    const fresh: McpDownloadItem[] = [];
    for (const name of names) {
      const link = catalogLink(name);
      if (!link) continue; // not a downloadable first-party server
      const key = name.toLowerCase();
      if (mcpDownloadSeen.current.has(key)) continue;
      const repo = repoNameFromLink(link);
      try {
        const r = await invoke<{ downloaded: boolean; built: boolean }>("mcp_status", { name: repo });
        if (r.downloaded && r.built) { mcpDownloadSeen.current.add(key); continue; } // already installed
      } catch { /* not installed → prompt */ }
      mcpDownloadSeen.current.add(key);
      const cat = MCP_CATALOG.find((c) => c.name.toLowerCase() === key);
      fresh.push({ name, repo, link, desc: cat?.desc, install: cat?.install, status: "pending" });
    }
    if (fresh.length) setMcpDownloads((prev) => [...prev, ...fresh]);
  }, []);

  // Download (clone + build) every still-pending/failed queued server, advancing its row status.
  const confirmMcpDownloads = useCallback(async () => {
    const setStatus = (name: string, status: McpDownloadItem["status"]) =>
      setMcpDownloads((p) => p.map((d) => (d.name === name ? { ...d, status } : d)));
    const targets = mcpDownloads.filter((d) => d.status === "pending" || d.status === "error");
    await Promise.all(targets.map(async (it) => {
      setStatus(it.name, "downloading");
      try { await invoke("mcp_clone", { name: it.repo, url: it.link }); }
      catch { setStatus(it.name, "error"); return; }
      setStatus(it.name, "building");
      try {
        const r = await invoke<{ ok: boolean }>("mcp_build", { name: it.repo });
        setStatus(it.name, r.ok ? "ready" : "error");
      } catch { setStatus(it.name, "error"); }
    }));
  }, [mcpDownloads]);

  // Dismiss the modal: drop the queue but keep the seen-set so skipped servers don't immediately
  // re-prompt (the user can still install them later from the MCP screen).
  const cancelMcpDownloads = useCallback(() => setMcpDownloads([]), []);

  return { enqueueMcpDownloads, mcpDownloads, confirmMcpDownloads, cancelMcpDownloads };
}

// usePlanMcpManagement (#1474) — the planner's MCP install lifecycle, extracted verbatim from
// Planning.tsx (the download-confirmation queue is its own hook, usePlanMcpDownloads). Owns the
// disk-probe, the blueprint-attached-MCP scoping, the project + planner-session MCP context writes,
// and the toggle/add/build/remove handlers.
//
// `mcpInstallState` STAYS in Planning (it feeds the paneData memo); this hook only WRITES it via the
// passed `setMcpInstallState` (always functional updates), which breaks the paneData→probe render
// cycle with no behavior change. Call it immediately after paneData so `mcpServersUi` is available.

import { useCallback, useEffect, useMemo, type Dispatch, type SetStateAction } from "react";
import { invoke } from "@tauri-apps/api/core";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { useAppStore } from "@/store";
import { applyBlueprintMcp, collectBlueprintMcp } from "@/features/planner/blueprints/blueprintMcp";
import { writeProjectMcpContext } from "@/features/planner/lib/mcpContext";
import { catalogLink, repoNameFromLink, mcpRepoName } from "@/features/mcp";
import { applyMcpAssign } from "@/features/planner/lib/planExtensions";
import { MCP_CATALOG } from "@/shared/data/mcpCatalog";
import { roleCapability, roleWriteRules, roleDeniedCommands } from "@/shared/lib/session/sessionRoles";
import { TURN_ACCOUNTING_HOOKS } from "@/shared/lib/session/turnHooks";
import { resolveAllInstalledMcp, toSessionPayloads, mcpAllowRules } from "@/features/mcp";
import { type McpInstallState } from "@/features/planner/lib/mcpPaneData";
import { type Blueprint } from "@/features/planner/stages/blueprints";

type StoreMcpServers = Parameters<typeof resolveAllInstalledMcp>[0];
/** The probe only reads id/name/downloadable off paneData.mcpServers. */
interface ProbeServer { id: string; name: string; downloadable?: boolean }

interface McpManagementDeps {
  effectiveProjectId: string;
  effectiveBlueprintId: string;
  blueprints: Blueprint[];
  planningDir: string;
  /** paneData.mcpServers — the UI server list the probe filters for downloadable servers. */
  mcpServersUi: ProbeServer[] | undefined;
  /** The store's mcpServers value — drives the installed-server context writes. */
  mcpServers: StoreMcpServers;
  /** Writes install status (functional updates only — the value lives in Planning, feeding paneData). */
  setMcpInstallState: Dispatch<SetStateAction<McpInstallState>>;
  /** Queue first-party MCP servers for the download-confirmation modal (from usePlanMcpDownloads). */
  enqueueMcpDownloads: (names: string[]) => Promise<void>;
}

export interface PlanMcpManagement {
  onToggleMcp: (id: string) => void;
  onRemoveMcp: (id: string) => void;
  onAddMcp: (input: string) => void;
  onBuildMcp: (s: { id: string; name: string; status: string }) => Promise<void>;
}

export function usePlanMcpManagement(deps: McpManagementDeps): PlanMcpManagement {
  const { effectiveProjectId, effectiveBlueprintId, blueprints, planningDir, mcpServersUi, mcpServers, setMcpInstallState, enqueueMcpDownloads } = deps;

  // Probe each downloadable MCP server's on-disk state so the pane opens with real status
  // (downloaded? built?) instead of "available" for already-installed servers.
  useEffect(() => {
    const probe = mcpServersUi?.filter(s => s.downloadable) ?? [];
    if (probe.length === 0) return;
    let cancelled = false;
    Promise.all(probe.map(async (s) => {
      try {
        const r = await invoke<{ downloaded: boolean; built: boolean }>("mcp_status", { name: mcpRepoName(s.name) });
        return [s.id, r.built ? "ready" : r.downloaded ? "downloaded" : "available"] as const;
      } catch { return [s.id, "available"] as const; }
    })).then((rows) => {
      if (cancelled) return;
      setMcpInstallState((prev) => {
        const next = { ...prev };
        // Don't clobber an in-flight downloading/building status with a probe result.
        for (const [id, st] of rows) if (next[id] !== "downloading" && next[id] !== "building") next[id] = st;
        return next;
      });
    });
    return () => { cancelled = true; };
    // Re-probe only when the set of downloadable server ids changes.
  }, [mcpServersUi?.filter(s => s.downloadable).map(s => s.id).join(",")]); // eslint-disable-line react-hooks/exhaustive-deps

  // Scope the active blueprint's attached MCP servers to this project (#897 Phase 2), so the
  // planner + fleet get the tools the blueprint declares. Idempotent (applyMcpAssign enables +
  // scopes existing, or adds). The downloadable (first-party) ones are queued for the
  // download-confirmation modal (#1055) rather than cloned silently. Re-runs when the project or
  // the blueprint's attached-MCP set changes.
  const bpMcpKey = useMemo(() => {
    const bp = blueprints.find(b => b.id === effectiveBlueprintId);
    return bp ? collectBlueprintMcp(bp).join("\n") : "";
  }, [blueprints, effectiveBlueprintId]);
  useEffect(() => {
    if (!effectiveProjectId || !bpMcpKey) return;
    const store = useAppStore.getState();
    const bp = store.blueprints.find(b => b.id === effectiveBlueprintId);
    if (!bp) return;
    void enqueueMcpDownloads(applyBlueprintMcp(store, bp, effectiveProjectId, store.bscBaseDir));
  }, [bpMcpKey, effectiveProjectId, effectiveBlueprintId, enqueueMcpDownloads]);

  // Write the planner's live extensions.md — the installed MCP servers it can call + the per-worker
  // assignment directive (#1054). Supersedes the static catalogue setup_workspaces used to write;
  // re-runs whenever the installed-server set or the project changes.
  const installedMcpKey = useMemo(
    () => resolveAllInstalledMcp(mcpServers).map((e) => `${e.id}:${e.name}`).join("\n"),
    [mcpServers],
  );
  useEffect(() => {
    if (!effectiveProjectId) return;
    void writeProjectMcpContext({ projectKey: effectiveProjectId, servers: resolveAllInstalledMcp(useAppStore.getState().mcpServers) })
      .catch((e) => console.warn("writeProjectMcpContext failed:", e));
  }, [installedMcpKey, effectiveProjectId]);

  // Keep the planner session's .mcp.json current as servers are downloaded (#1054). Claude loads MCP
  // config at startup, so a newly downloaded server is picked up on the planner's next launch /
  // resume; this keeps the file ready. No-op until the planner dir is known.
  useEffect(() => {
    if (!planningDir) return;
    const cap = roleCapability("director");
    const write = roleWriteRules(cap);
    const mcp = toSessionPayloads(resolveAllInstalledMcp(useAppStore.getState().mcpServers), []).mcp;
    fireInvoke("ensure_session_settings", {
      cwd:             planningDir,
      allowedCommands: [],
      deniedCommands:  roleDeniedCommands(cap),
      mcpServers:      mcp,
      // Turn accounting (#3455): re-assert on the MCP refresh too. replacePermissions:true would
      // otherwise clear the launch-time turn hooks and re-blind the planner's cost.
      hooks:           TURN_ACCOUNTING_HOOKS,
      // Auto-approve every MCP server the planner is given (Research included) so calling them
      // while planning never hits a per-tool prompt — replacePermissions:true here would otherwise
      // drop the launch-time rules, so this refresh must re-assert them too.
      allowToolRules:  [...write.allow, "Read", "WebFetch", ...mcpAllowRules(mcp)],
      denyToolRules:   write.deny,
      replacePermissions: true,
    }, (e: unknown) => console.warn("planner mcp refresh failed:", e));
  }, [installedMcpKey, planningDir]);

  // ── MCP stage handlers (#878) ──────────────────────────────────────────────
  const onToggleMcp = useCallback((id: string) => useAppStore.getState().toggleMcpServer(id), []);
  const onRemoveMcp = useCallback((id: string) => useAppStore.getState().removeMcpServer(id), []);
  const onAddMcp = useCallback((input: string) => {
    const store = useAppStore.getState();
    // A bare catalog name maps to its template; anything with a scheme is a remote URL; else a
    // stdio command line. New servers are enabled + scoped to this project so the fleet gets them.
    const link = catalogLink(input);
    if (link || MCP_CATALOG.some(c => c.name.toLowerCase() === input.toLowerCase())) {
      const name = MCP_CATALOG.find(c => c.name.toLowerCase() === input.toLowerCase())?.name ?? input;
      applyMcpAssign(store, name, effectiveProjectId, store.bscBaseDir);
      if (link) fireInvoke("mcp_clone", { name: repoNameFromLink(link), url: link });
      return;
    }
    const isUrl = /^https?:\/\//i.test(input);
    store.addMcpServer({
      name: input.split(/\s+/)[0].slice(0, 40) || "server", enabled: true, projects: [effectiveProjectId],
      transport: isUrl ? "http" : "stdio",
      ...(isUrl ? { url: input } : { command: input.split(/\s+/)[0], args: input.split(/\s+/).slice(1).join(" ") }),
      env: [],
    });
  }, [effectiveProjectId]);
  const onBuildMcp = useCallback(async (s: { id: string; name: string; status: string }) => {
    const repo = mcpRepoName(s.name);
    const link = catalogLink(s.name);
    // Ensure it's downloaded, then build, tracking status so the pane reflects progress.
    if (link && (s.status === "available")) {
      setMcpInstallState(p => ({ ...p, [s.id]: "downloading" }));
      try { await invoke("mcp_clone", { name: repo, url: link }); }
      catch { setMcpInstallState(p => ({ ...p, [s.id]: "available" })); return; }
    }
    setMcpInstallState(p => ({ ...p, [s.id]: "building" }));
    try {
      const r = await invoke<{ ok: boolean }>("mcp_build", { name: repo });
      setMcpInstallState(p => ({ ...p, [s.id]: r.ok ? "ready" : "error" }));
    } catch {
      setMcpInstallState(p => ({ ...p, [s.id]: "error" }));
    }
  }, [setMcpInstallState]);

  return { onToggleMcp, onRemoveMcp, onAddMcp, onBuildMcp };
}

// usePlanPublish (#1490) — the publish → GitHub + triage-launch + GitHub→plan.db recovery cluster,
// extracted verbatim from Planning.tsx. Owns the triage/publish/recovery state (no render loop —
// just callbacks + a recovery probe effect); takes the plan data it reads as a params object so the
// bodies move unchanged. Returns the callbacks + the state the JSX consumes.

import { useState, useEffect } from "react";
import { invoke } from "@tauri-apps/api/core";
import { safeInvoke, fireInvoke } from "@/shared/lib/core/safeInvoke";
import { bscJson, bscWrite } from "@/shared/lib/core/bsc";
import { useAppStore } from "@/store";
import { useConfirmDialog } from "@/shared/ui/overlay/promptDialog";
import type { Section } from "@/features/planner/github/ghStructure";
import { type GhStatusMap } from "@/features/planner/session/GitHubStructureCard";
import { deriveProjectTitle } from "@/features/planner/session/projectTitle";
import { parseFeaturesFile } from "@/features/planner/issues/featureList";
import { parseDependencyManifest, depsForRepo } from "@/features/planner/issues/dependencies";
import { buildWorkerScope, toWorkerUiPairing } from "@/features/planner/fleet/workerScope";
import { effectiveHarness } from "@/shared/lib/core/llmConfig";
import { type PlanIssue } from "@/features/planner/issues/planIssues";
import { pruneCompletedStreams, doneIssueRefs } from "@/shared/lib/fleet/streamCompletion";
import { resolveClosedRefs } from "@/features/glance";
import { withDerivedStreamIssues } from "@/features/planner/fleet/planFleet";
import { teamRoleStreams } from "@/features/planner/fleet/teamFleet";
import { recoverIssues, type GitHubIssueLike } from "@/features/planner/issues/recoverIssues";
import { removeDbProject } from "@/features/planner/list/projectsDbBridge";
import { publishFleetRoster } from "@/shared/lib/fleet/fleetRoster";
import { canLaunchTriage, publishBlockReason } from "@/shared/lib/github/projectSync";
import {
  type GhApi, type Upd, seedPublishStatus,
  publishRepositories, scaffoldRepositories, ensureProjectBoard, createIssues, applyStreamLabels,
  materializeIssues,
} from "@/features/planner/session/publishSteps";

export type PublishPhase = "idle" | "running" | "done" | "error";

type Store = ReturnType<typeof useAppStore.getState>;

export interface PlanPublishDeps {
  githubToken: string;
  publishRepos: string[];
  injectionGateState: { cleared: boolean; findings: unknown[]; mode: string };
  sections: Section[];
  planningTitle: string;
  activeProjectName: string;
  planFleet: Store["planFleet"];
  effectiveProjectId: string;
  activeProjectId: Store["activeProjectId"];
  activeProjectNumber: Store["activeProjectNumber"];
  planFeatures: ReturnType<typeof parseFeaturesFile>;
  planDependencies: ReturnType<typeof parseDependencyManifest>["dependencies"];
  depManifest: ReturnType<typeof parseDependencyManifest>;
  repoPublic: Store["repoPublic"];
  reposPublic: Record<string, boolean>;
  projectTitle: string;
  planReady: boolean;
  visible: boolean;
  addProjectRepo: Store["addProjectRepo"];
  fleetStartProject: Store["fleetStartProject"];
}

export function usePlanPublish(deps: PlanPublishDeps) {
  const {
    githubToken, publishRepos, injectionGateState, sections, planningTitle,
    activeProjectName, planFleet, effectiveProjectId, activeProjectId, activeProjectNumber,
    planFeatures, planDependencies, depManifest, repoPublic, reposPublic,
    projectTitle, planReady, visible, addProjectRepo, fleetStartProject,
  } = deps;

  const [triaging, setTriaging] = useState(false);
  const [triageError, setTriageError] = useState<string | null>(null); // launch-failure surfacing (#551)
  const [triageNote, setTriageNote] = useState<string | null>(null);   // progress-gated relaunch summary (#1004)
  // GitHub→plan.db recovery (#plan-db): how many planner-published issues GitHub holds when the
  // local plan.db is empty (machine switch / data loss), and whether a recovery is in flight.
  const [recoverable, setRecoverable] = useState(0);
  const [recovering, setRecovering] = useState(false);
  const [publishPhase, setPublishPhase] = useState<PublishPhase>("idle");
  // Live status of each GitHub object, keyed by the ids in buildGhStructure.
  const [ghStatus, setGhStatus] = useState<GhStatusMap>({});
  // Confirm + clear stale warden quarantines before a triage relaunch (a denied command from a prior
  // run otherwise persists and immediately re-pauses the relaunched worker). `quarantineDialog` is the
  // self-rendering modal node the JSX mounts.
  const { confirm, dialog: quarantineDialog } = useConfirmDialog();

  async function launchTriage() {
    const fleet = planFleet[effectiveProjectId];
    // Pre-flight gate (#444/#551) — mirror the button's gate so a programmatic / Enter-key
    // path can't launch against an unpublished or plan-incomplete project. (Restored: the
    // refactor had weakened this to a repos/fleet-only check.)
    if (!canLaunchTriage({
      published: !!activeProjectId,
      hasRepos: publishRepos.length > 0,
      hasFleet: !!fleet && fleet.streams.length > 0,
      busy: triaging,
      planReady,
    })) return;
    // A stale warden quarantine from a PRIOR run persists (in quarantinedPanes + the bsc-audit log)
    // and would immediately re-pause the relaunched worker. On triage: show the user WHY each worker
    // was quarantined, then clear those flags and stamp a warden "since" floor so the relaunch is clean.
    const projQuarantines = Object.entries(useAppStore.getState().quarantinedPanes)
      .filter(([p]) => p.startsWith(`${effectiveProjectId}:`));
    if (projQuarantines.length > 0) {
      const reasons = projQuarantines.map(([, info]) => `${info.streamId} (${info.summary})`).join("; ");
      const ok = await confirm({
        title: projQuarantines.length === 1 ? "Clear worker quarantine?" : `Clear ${projQuarantines.length} worker quarantines?`,
        message: `${projQuarantines.length === 1 ? "A worker was" : `${projQuarantines.length} workers were`} `
          + `quarantined and paused — ${reasons}. Relaunching clears `
          + `${projQuarantines.length === 1 ? "it and resumes the worker" : "them and resumes the workers"}.`,
        confirmLabel: "Clear & relaunch",
        cancelLabel: "Cancel",
      });
      if (!ok) return;
    }
    // Always stamp the warden floor for the project's panes on relaunch (even with nothing currently
    // flagged) so a stale denied command that hasn't tripped the warden yet also can't re-pause.
    {
      const relaunchPanes = (fleet?.streams ?? []).map((st) => `${effectiveProjectId}:${st.id}`);
      useAppStore.getState().clearProjectQuarantine(effectiveProjectId, relaunchPanes, Date.now());
    }
    setTriageError(null);
    setTriageNote(null);
    setTriaging(true);
    try {
      // Materialize the project hub on disk (#2997 C, epic #2993): planning ran in an ephemeral
      // per-project workspace, so this creates projects/<key>/ and moves the planner's authored files
      // in — BEFORE any director/worker cwd (the hub dir or a worktree beneath it) resolves to it.
      // Idempotent: an already-materialized hub or a re-launch is a no-op. Fail-CLOSED — without the
      // hub the director + worktree cwds don't exist, so surface the failure and abort the launch
      // rather than dropping the fleet into a missing directory.
      try {
        await invoke("materialize_hub", { projectKey: effectiveProjectId });
      } catch (e) {
        setTriageError(`launch failed — could not materialize the project hub: ${String(e)}`);
        return;
      }
      // #1988: when the sandbox is on AND the fleet runs on the model-agnostic bsc-agent harness (the
      // only runtime baked into the sealed distro), the whole fleet launches INSIDE the WSL2 cage —
      // the hub is relocated to the distro's ext4, repos are cloned + worktrees created in-distro, and
      // every pane spawns via `wsl -d <distro>`. Otherwise it's the normal host launch.
      const store0 = useAppStore.getState();
      const sandbox = store0.sandboxConsoles === true
        && effectiveHarness(store0.llmProvider, store0.fleetHarness ?? "claude") === "bsc-agent";
      const SANDBOX_DISTRO = "bsc-agent-sandbox";
      // Host clones seed the on-disk repo list the UI reads; skip them for a sandboxed launch (repos
      // are git-cloned in-distro by ensure_sandbox_worktree — nothing lands on the Windows host).
      if (!sandbox) await Promise.all(publishRepos.map(fullName =>
        invoke<string>("clone_repo", { project: effectiveProjectId, fullName })
          .then(() => addProjectRepo(activeProjectId ?? effectiveProjectId, fullName))
          .catch(e => console.error(`clone ${fullName} failed:`, e)),
      ));
      // Each worker auto-runs under its ROLE's default profile at launch (worker → Autonomous,
      // director → Read-only review) — no per-stream profile to materialize here anymore.
      const fullPlan = useAppStore.getState().planFleet[effectiveProjectId] ?? fleet;
      // Progress-gated relaunch (#1004): read each issue's status from plan.db and DON'T restart a
      // worker whose issues are all complete/verified — it already finished. Prune those streams (their
      // worktrees/branches persist untouched); launch only the streams with outstanding work, plus the
      // director if enabled. On a first launch nothing is done, so every stream stays active.
      const dbIssues = await bscJson<PlanIssue[]>(effectiveProjectId, ["plan", "list", "--full", "--json"], []);
      // #1957: completed workers no longer skip — they relaunch INTO maintenance (alive + ready for the
      // director to dispatch new lane work), so launch BOTH active and maintenance streams. The
      // maintenance set drives a maintenance scope banner (buildWorkerScope) so they stand by, not rebuild.
      // #4103: plan.db's issue rows can be empty for a fleet assembled outside a full planner run, in
      // which case `doneIssueRefs` is empty and NO stream ever prunes as complete. GitHub's closed set
      // is the other evidence source; either one calling a ref done makes it done.
      const closedRefs = await resolveClosedRefs(fullPlan.streams);
      const done = new Set([...doneIssueRefs(dbIssues), ...closedRefs]);
      const { active, maintenance } = pruneCompletedStreams(fullPlan.streams, done);
      const maintenanceIds = new Set(maintenance.map(s => s.id));
      // #2611: a stream with no resolvable repo stays VISIBLE in the plan but can't spawn a worktree —
      // skip it here (rather than aborting the fail-closed launch on a broken ensure_worktree) and
      // surface which streams still need a repo assigned, so the gap is seen, not swallowed.
      // #2615: a stream can reach launch with an empty `issues[]` even though issues name it as their
      // owning `stream` — enrich each stream's issue list from the plan.db issues so a worker launches
      // with its concrete task list (feeding BOTH the scope below and the kickoff via fleetStartProject),
      // not the "(none yet — ask the director)" placeholder. A stream that already lists issues is kept.
      const launchable = withDerivedStreamIssues([...active, ...maintenance].filter(st => st.repo), dbIssues);
      const noRepo = [...active, ...maintenance].filter(st => !st.repo);
      // Team-driven fleet (#3101/#3103): a project's TEAM contributes its ROLE-ACTOR sessions (curator,
      // documentor, reviewer, tester, juror, issuer) — one per team position bound to such a persona,
      // deduped vs the planner's own streams. They run at the project HUB (no repo → no worktree; the
      // `fleetStartProject` repo-less branch routes them there), so they compose in AFTER `launchable`
      // and are deliberately NOT part of the worktree-creation loop below.
      const teamStore = useAppStore.getState();
      const projectTeam = teamStore.blueprints.find(b => b.id === teamStore.projectBlueprintId[effectiveProjectId])?.team;
      const roleStreams = teamRoleStreams(projectTeam, teamStore.personas, fullPlan.streams);
      const launchPlan = { ...fullPlan, streams: [...launchable, ...roleStreams] };
      if (launchPlan.streams.length === 0 && !launchPlan.director.enabled) {
        setTriageError(noRepo.length > 0
          ? `No workers to launch — ${noRepo.length} stream${noRepo.length === 1 ? "" : "s"} (${noRepo.map(s => s.id).join(", ")}) need a repo assigned.`
          : "No workers to launch.");
        return;
      }
      const launchNotes: string[] = [];
      if (noRepo.length > 0) {
        launchNotes.push(`${noRepo.length} stream${noRepo.length === 1 ? "" : "s"} `
          + `(${noRepo.map(s => s.id).join(", ")}) skipped — no repo assigned`);
      }
      if (maintenance.length > 0) {
        launchNotes.push(`${maintenance.length} completed worker${maintenance.length === 1 ? "" : "s"} `
          + `(${maintenance.map(s => s.id).join(", ")}) relaunching into maintenance`
          + (active.length > 0 ? `; ${active.length} active` : ""));
      }
      if (launchNotes.length > 0) setTriageNote(launchNotes.join(". ") + ".");
      // The project's {kit, theme} pairing (#2489): plan.db's `ui` blob (the planner's per-project
      // record, `bsc plan ui set` in the Test UI stage) with the project blueprint's pin filling
      // whatever it doesn't set — inlined into every worker's scope as the UI-palette lock block
      // (token layer read-only; palette = the swappable theme.css).
      const uiBlob = await bscJson<{ kit?: { id?: string; version?: string } | null; themeId?: string } | null>(
        effectiveProjectId, ["plan", "ui", "get", "--json"], null);
      const storeUi = useAppStore.getState();
      const uiPairing = toWorkerUiPairing(
        uiBlob, storeUi.blueprints.find(b => b.id === storeUi.projectBlueprintId[effectiveProjectId])?.uiKit);
      // Create each worker's git worktree FAIL-CLOSED (#551/#359): if any can't be created,
      // abort the launch so no agent starts in a fallback dir. (Restored: the refactor had
      // weakened this to a non-fatal .catch that let the launch continue.)
      // Only the repo'd WORKER streams get a worktree — the team's hub role-actors (repo-less) are
      // excluded (they run at the hub, no isolated tree). `launchable` is exactly those worker streams.
      const worktreeResults = await Promise.all(launchable.map(st => {
        // Seed each worktree's CLAUDE.local.md with the worker's SCOPE (owns/issues/deps) plus its
        // repo's LOCKED dependency manifest (#1111), not the full plan — the worktree lives outside
        // the hub so the planner spec is no longer an ancestor (#844). In-distro when sandboxed
        // (ensure_sandbox_worktree clones the repo + adds the worktree on the distro's ext4, #1988).
        const scopeMd = buildWorkerScope(st, depsForRepo(planDependencies, st.repo), maintenanceIds.has(st.id), uiPairing);
        const call = sandbox
          ? invoke<string>("ensure_sandbox_worktree", { projectKey: effectiveProjectId, repo: st.repo, agentId: st.id, scopeMd, token: githubToken })
          : invoke<string>("ensure_worktree", { projectKey: effectiveProjectId, repo: st.repo, agentId: st.id, scopeMd });
        return call
          .then(path => ({ id: st.id, path, err: null as string | null }))
          .catch(e => ({ id: st.id, path: null as string | null, err: String(e) }));
      }));
      const failed = worktreeResults.filter(r => r.err || !r.path);
      if (failed.length > 0) {
        setTriageError(`launch failed — ${failed[0].id}: ${failed[0].err ?? "empty path"}`);
        return;
      }
      // Carry the authoritative absolute paths into fleetStartProject (#905) so each pane's
      // cwd comes from the Rust backend, not the async-loaded `bscBaseDir` mirror (which, when
      // empty/malformed, silently drops every session at the user's home dir). Workers use the
      // worktree path ensure_worktree just returned; the director uses the hub dir.
      const worktreePaths: Record<string, string> = {};
      for (const r of worktreeResults) if (r.path) worktreePaths[r.id] = r.path;
      // The director's cwd is the hub. Sandboxed → relocate the host hub onto the distro's ext4 and use
      // its distro-native path (setup_sandbox_hub); otherwise the on-host hub dir (#905).
      const hubPath = sandbox
        ? await safeInvoke<string>("setup_sandbox_hub", { key: effectiveProjectId }, "")
        : await safeInvoke<string>("project_dir_path", { projectKey: effectiveProjectId }, "");
      // Give the director its standing protocol at the hub (#375) so it gets the bsc-fleet
      // roster instruction + answers worker questions (the refactor dropped this call; #734).
      if (launchPlan.director.enabled) {
        await safeInvoke("ensure_director_protocol", { projectKey: effectiveProjectId }, undefined,
          e => console.error("director protocol failed:", e));
      }
      const roster = fleetStartProject(projectTitle, launchPlan, effectiveProjectId, { hubPath, worktreePaths, wslDistro: sandbox ? SANDBOX_DISTRO : undefined });
      publishFleetRoster(effectiveProjectId, roster); // #734: hub fleet.roster.tsv for bsc-fleet
    } catch (e) {
      console.error("fleet launch failed:", e);
    } finally {
      setTriaging(false);
    }
  }

  /** The LOCAL commit (#3280) — materialize the plan's issues into plan.db and mark the project active,
   *  with NO GitHub round-trip. This is what lets the fleet launch offline: `activeProjectId` set to the
   *  local project key flips `published` true (`canLaunchTriage`) and works as a key everywhere; a later
   *  publish upgrades it to the GitHub node id over the SAME plan.db rows (upsert-by-ref, no dupes).
   *  Shares publish's injection gate — never promote unreviewed markers to the fleet. */
  async function commitLocal() {
    if (!injectionGateState.cleared) {
      const n = injectionGateState.findings.length;
      setTriageError(injectionGateState.mode === "blocked"
        ? `Commit blocked: ${n} possible prompt-injection marker${n !== 1 ? "s" : ""} in the plan must be removed (hard-block is on in Settings).`
        : `Review the ${n} possible prompt-injection marker${n !== 1 ? "s" : ""} flagged in the plan, then acknowledge them before committing.`);
      return;
    }
    setTriageError(null);
    const featuresContent = sections.find(s => s.k === "features")?.content ?? "";
    await materializeIssues(featuresContent, { upsertIssue: (iss) => bscWrite(effectiveProjectId, ["plan", "add"], iss) });
    const goalContent  = sections.find(s => s.k === "goal")?.content ?? "";
    const projectTitle = deriveProjectTitle(planningTitle, goalContent, activeProjectName);
    // The local key IS activeProjectId here (no GitHub number) — publish later overwrites it with the
    // ProjectV2 node id. Reopening from the board derives the hub key from the name, so nothing bridges.
    useAppStore.getState().setActiveProjectMeta(effectiveProjectId, projectTitle, publishRepos[0] ?? "", 0, publishRepos);
  }

  async function handlePublish() {
    // #3280 local-first: with no GitHub token, "publish" commits the plan LOCALLY (plan.db) instead of
    // erroring — the fleet can then launch offline. Publishing to GitHub stays the optional path when
    // connected. (publishBlockReason's no-token case is now unreachable from here; the no-repo case
    // below still fires when connected.)
    if (!githubToken) { await commitLocal(); return; }
    // Don't fail silently (#969): surface WHY publish can't proceed, so the user isn't left thinking
    // they published when nothing happened (which then leaves the fleet-launch button locked with no
    // explanation). The common case is a blueprint with no Repos stage ⇒ no repo ever linked.
    const blocked = publishBlockReason({ hasToken: !!githubToken, repoCount: publishRepos.length });
    if (blocked) { setTriageError(blocked); return; }
    // #1107: never promote a plan with unreviewed / hard-blocked injection markers to the fleet.
    if (!injectionGateState.cleared) {
      const n = injectionGateState.findings.length;
      setTriageError(injectionGateState.mode === "blocked"
        ? `Publish blocked: ${n} possible prompt-injection marker${n !== 1 ? "s" : ""} in the plan must be removed (hard-block is on in Settings).`
        : `Review the ${n} possible prompt-injection marker${n !== 1 ? "s" : ""} flagged in the plan, then acknowledge them before publishing.`);
      return;
    }
    setTriageError(null);
    const token = githubToken;

    const repos        = publishRepos;
    const goalContent  = sections.find(s => s.k === "goal")?.content ?? "";
    const projectTitle = deriveProjectTitle(planningTitle, goalContent, activeProjectName);
    const projectDesc  = goalContent.split(/\n/)[0].slice(0, 350);
    const fleet        = planFleet[effectiveProjectId];
    const streams      = fleet?.streams ?? [];

    // Seed every node as "planned" so the card shows the full structure upfront.
    const status = seedPublishStatus({ repos, streams });
    setGhStatus({ ...status });
    setPublishPhase("running");

    let anyError = false;
    const upd: Upd = (id, patch) => {
      status[id] = { ...(status[id] ?? { status: "planned" }), ...patch };
      if (patch.status === "error") anyError = true;
      setGhStatus({ ...status });
    };

    // The GitHub transport — the same closures the steps consume (injected so they're testable).
    const api: GhApi = {
      gql: (query, variables) => invoke<Record<string, unknown>>("github_graphql", { token, query, variables }),
      rest: <T,>(path: string) => invoke<T>("github_request", { token, path }),
      post: <T,>(path: string, body: unknown) => invoke<T>("github_post", { token, path, body }),
      put: (path, body) => invoke("github_put", { token, path, body }),
      patch: (path, body) => invoke("github_patch", { token, path, body }),
    };

    try {
      // 1. Repositories — verify/create.
      const { repoNodeIds, viewerLogin } = await publishRepositories(api, upd, {
        repos, projectDesc, repoPublic, reposPublic, effectiveProjectId,
      });

      // 1b. Repo presentation — description/topics/README/community files + locked dep manifests.
      await scaffoldRepositories(api, upd, {
        repos, projectDesc, projectTitle, goalContent,
        stackText: sections.find(s => s.k === "stack")?.content ?? "",
        scopeText: sections.find(s => s.k === "scope")?.content ?? "",
        archText:  sections.find(s => s.k === "architecture")?.content ?? "",
        features: planFeatures.map(f => ({ name: f.name, behavior: f.behavior })),
        planDependencies, registries: depManifest.registries,
      });

      // 2. Project board — reuse or create; the store writes for a new board happen here in the hook.
      const board = await ensureProjectBoard(api, upd, {
        activeProjectId, activeProjectNumber, repos, viewerLogin, projectTitle, repoNodeIds,
      });
      const projectId = board.projectId;
      if (board.created) {
        const pv = board.created;
        const store = useAppStore.getState();
        // Reflect in the store so the projects list + future syncs treat it as existing.
        store.setActiveProjectMeta(pv.id, projectTitle, repos[0] ?? "", pv.number, repos);
        // No node-id → key alias write anymore (#2409): reopening from the board DERIVES the hub
        // key from the project's name (`projectSlug(title)`), so publish records nothing to bridge.
        // Mark the hub published in place (#922) — the hub never moves, so --continue history survives.
        fireInvoke("mark_published", { projectKey: effectiveProjectId }, (e) => console.warn("mark_published failed (Projects page reconciles it):", e));
        // Drop the store's draft entry so the project can't linger as a ghost draft card, and mirror
        // that removal into the durable projects DB (#2995) so the published project doesn't re-surface
        // as a draft from the DB union. Fire-and-forget; degrades silently.
        store.removeDraftProject(effectiveProjectId);
        void removeDbProject(effectiveProjectId);
      }

      // 3. Issues — features → issues, on the board, assigned, sub-issues nested (no milestones, #1912).
      await createIssues(api, upd, {
        repos, featuresContent: sections.find(s => s.k === "features")?.content ?? "",
        projectId, streams, viewerLogin,
      }, {
        upsertIssue: (iss) => bscWrite(effectiveProjectId, ["plan", "add"], iss),
        setIssueIdentity: (ref, ghNumber, ghNodeId) =>
          bscWrite(effectiveProjectId, ["plan", "link", ref], { ghNumber, ghNodeId }),
        loadIssues: () => bscJson<PlanIssue[]>(effectiveProjectId, ["plan", "list", "--full", "--json"], []),
      });

      // 4. Stream labels.
      await applyStreamLabels(api, upd, { streams });

      setPublishPhase(anyError ? "error" : "done");
    } catch (e) {
      console.error("publish failed", e);
      setPublishPhase("error");
    }
  }

  // GitHub → plan.db recovery (#plan-db). The mirror of handlePublish: pull each repo's
  // planner-published issues back into the plan store so a lost or machine-switched plan.db
  // rehydrates from the durable GitHub copy. Paginates issues (state=all), drops PRs, and upserts
  // each reconstructed PlanIssue (ref/dependsOn from the hidden marker, stream from the label,
  // status from open/closed). The 2s section poll reflects the DB afterward.
  async function handleRecover() {
    if (!githubToken || publishRepos.length === 0 || recovering) return;
    setRecovering(true);
    setTriageError(null);
    const token = githubToken;
    const rest = <T,>(path: string) => invoke<T>("github_request", { token, path });
    try {
      let total = 0;
      for (const repo of publishRepos) {
        const rows: GitHubIssueLike[] = [];
        for (let page = 1; page <= 20; page++) {
          const batch = await rest<GitHubIssueLike[]>(`repos/${repo}/issues?state=all&per_page=100&page=${page}`)
            .catch(() => [] as GitHubIssueLike[]);
          if (!batch || batch.length === 0) break;
          rows.push(...batch);
          if (batch.length < 100) break; // last page
        }
        for (const iss of recoverIssues(rows, repo)) {
          await bscWrite(effectiveProjectId, ["plan", "add"], iss);
          total++;
        }
      }
      setRecoverable(0);
      if (total === 0) setTriageError("recover — GitHub had no planner-published issues for these repos");
    } catch (e) {
      setTriageError(`recover failed — ${String(e)}`);
    } finally {
      setRecovering(false);
    }
  }

  // Offer recovery when the local plan.db is empty but GitHub holds planner-published issues (the
  // machine-switch / data-loss case). Probes the first repo for issues carrying the ref marker and
  // surfaces the banner; the recovery itself stays user-initiated.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      if (!visible || !githubToken || publishRepos.length === 0) { setRecoverable(0); return; }
      const dbIssues = await bscJson<PlanIssue[]>(effectiveProjectId, ["plan", "list", "--full", "--json"], []);
      if (cancelled) return;
      if ((dbIssues?.length ?? 0) > 0) { setRecoverable(0); return; } // db already populated — nothing to recover
      const rows = await safeInvoke<GitHubIssueLike[]>("github_request", {
        token: githubToken, path: `repos/${publishRepos[0]}/issues?state=all&per_page=100`,
      }, []);
      if (cancelled) return;
      // Count only planner-published issues — those with a ref marker (a recovered ref isn't "#<n>").
      setRecoverable(recoverIssues(rows ?? [], publishRepos[0]).filter((i) => !i.ref.startsWith("#")).length);
    })();
    return () => { cancelled = true; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [visible, githubToken, publishRepos.join(","), effectiveProjectId]);

  return { handlePublish, launchTriage, handleRecover, triaging, triageError, triageNote, recoverable, recovering, publishPhase, setPublishPhase, ghStatus, quarantineDialog };
}

// usePlanSkillsManagement (#1474) — the planner's session skill-group + live skills refresh,
// extracted verbatim from Planning.tsx. Side-effect only (no state, no return).

import { useEffect } from "react";
import { useAppStore } from "@/store";
import { usePoll } from "@/shared/hooks/usePoll";

export function usePlanSkillsManagement(sessionGroupId: string, projectTitle: string): void {
  const ensureSessionGroup = useAppStore(s => s.ensureSessionGroup);
  const refreshSkills = useAppStore(s => s.refreshSkills);
  // Whether the per-project session group exists YET. It's created lazily by
  // `bsc-skill add --group "$BSC_SESSION_SKILL_GROUP"` the first time the planner authors a skill —
  // NOT on planner open, so a project that authors none never leaves an empty group behind (#1616).
  const groupExists = useAppStore(s => s.skillGroups.some(g => g.id === sessionGroupId));

  // Adopt the session group ONCE IT EXISTS (#1419/#1616): never pre-create it. When the planner authors
  // its first skill, bsc-skill creates the group (placeholder name = its id); the refresh poll below
  // surfaces it here, and we rename the placeholder to the project name — and again if the title later
  // changes — without clobbering members. Persistent: reopening the planner keeps collecting into it.
  useEffect(() => {
    if (groupExists && sessionGroupId && projectTitle) ensureSessionGroup(sessionGroupId, projectTitle);
  }, [groupExists, sessionGroupId, projectTitle, ensureSessionGroup]);

  // Re-read the global skills.db while planning so skills the planner authors with `bsc-skill add`
  // (and their session-group membership) surface live in the pane — the skills.json file-poll that
  // used to do this was retired (#1417/#1419). Cheap (no push-back); 2.5s ≈ the section-poll cadence.
  usePoll(() => { void refreshSkills(); }, 2500, [refreshSkills]);
}

// usePlanStagePoll (#1474) — the planner's 2-second plan.db + section-file poll, extracted
// verbatim from Planning.tsx. While the planning page is visible it reflects every DB-owned
// artifact (issues / features / repos / fleet / deploy / deps / mcp) plus the
// `read_plan_stages` file poll into the store, with per-artifact change-guards so an unchanged
// blob never churns state. Side-effect only — owns its guard refs internally and returns nothing.

import { useRef } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { invoke } from "@tauri-apps/api/core";
import { bscJson, bscRun, bscWrite } from "@/shared/lib/core/bsc";
import { hashString } from "@/shared/lib/core/hashString";
import { useAppStore, type AutomationSuggestion } from "@/store";
import { FLEET_KEY } from "@/features/planner/fleet/planFleet";
import { FEATURES_KEY, canonicalTopicKey } from "@/features/planner/stages/planTopics";
import { reconcileConfirmations, reconcileSkips, type ConfirmRow } from "@/features/planner/stages/confirmReconcile";
import { parseDependencyManifest, DEPENDENCIES_KEY } from "@/features/planner/issues/dependencies";
import { parseDeployConfigTag } from "@/features/planner/lib/deployConfig";
import { coerceMarketConfig } from "@/features/planner/lib/marketConfig";
import { coerceClassifyConfig } from "@/features/planner/lib/classifyConfig";
import { coerceTransformationRows } from "@/features/planner/lib/transformations";
import { applyMcpAssign } from "@/features/planner/lib/planExtensions";
import { catalogLink } from "@/features/mcp";
import { scriptDocRelpath } from "@/features/planner/session/planningSession";
import { sanitizeProjectKey } from "@/shared/lib/core/projectPaths";
import { wantsSandboxLaunch } from "@/features/planner/session/plannerSandbox";
import { plannerLaunchConfig } from "@/features/planner/session/plannerLaunch";

/** A per-repo startup script row from plan.db (`bsc plan startup`, #2010). */
interface StartupScriptRow { repo: string; mode: "dev" | "triage"; path: string }

interface StagePollDeps {
  visible: boolean;
  projectId: string;
  /** Linked repos, passed to the deploy-config coercion. */
  publishRepos: string[];
  /** Queue first-party MCP servers for the download-confirmation modal. */
  enqueueMcpDownloads: (names: string[]) => void;
  /** The host hub dir — non-empty once `setup_workspaces` resolves. Drives the sandbox-read decision
   *  (#1988): a planner launched into the WSL2 cage writes its sections into the distro hub. */
  planningDir: string;
}

export function usePlanStagePoll({ visible, projectId: effectiveProjectId, publishRepos, enqueueMcpDownloads, planningDir }: StagePollDeps): void {
  // Per-artifact change-guards: skip re-applying an unchanged DB blob each 2s tick. `depsImportedRef`
  // gates the one-time legacy dependencies.json import; `mcpAppliedRef` the per-name MCP resolve.
  const deployAppliedRef = useRef<Record<string, string>>({});
  const marketAppliedRef = useRef<Record<string, string>>({});
  const classifyAppliedRef = useRef<Record<string, string>>({});
  const transformationsAppliedRef = useRef<Record<string, string>>({});
  const depsAppliedRef = useRef<Record<string, string>>({});
  const depsImportedRef = useRef<Set<string>>(new Set());
  const mcpAppliedRef = useRef<Set<string>>(new Set());
  const autoAppliedRef = useRef<Record<string, string>>({});
  const startupAppliedRef = useRef<Record<string, string>>({});
  // Projects whose pre-#2256 app-state confirmations have already been forward-migrated into plan.db
  // (one-time per project, so the migration doesn't re-run every 2s tick).
  const confirmMigratedRef = useRef<Set<string>>(new Set());
  // The same one-time-per-project guard for the pre-#2267 app-state skips forward-migration.
  const skipMigratedRef = useRef<Set<string>>(new Set());

  // Poll the section files Claude writes every 2 seconds while visible. Each
  // documented topic is its own file ({key}.md / phases.json / _skipped.md);
  // read_plan_stages returns them all dynamically, keyed by file stem. Writing
  // to the store drives the derived `sections`/`skipped` — confirmed sections
  // stay frozen. This file poll is more reliable than the raw <plan_update>
  // stream and is what surfaces brand-new topics as their own cards.

  usePoll(() => {
    if (!visible) return;
    const poll = async () => {
      try {
        const store = useAppStore.getState();
        const saved = store.planStages[effectiveProjectId] ?? {};

        // Sandbox (#1988): a planner launched INSIDE the WSL2 cage writes plan.db + section files into
        // the distro hub. Mirror the in-distro plan.db back to the host FIRST, so the DB-owned reads
        // below (issues/features/fleet/deploy/deps/mcp/automations/startup/blueprint) — and publish +
        // fleet launch, which read the host plan.db — reflect the sandboxed planner's work. Sections
        // (file-based) are read from the distro directly further down.
        const sandboxed = wantsSandboxLaunch(store.sandboxConsoles, plannerLaunchConfig(store, {}).providerId, planningDir);
        if (sandboxed) {
          await invoke("sync_sandbox_plan_db", { key: effectiveProjectId }).catch(() => { /* no in-distro db yet — ignore */ });
        }

        // Every DB-owned artifact is reflected the SAME way: read it from plan.db, stringify it, and —
        // only when the serialized blob changed since the last tick — apply it to the store. The
        // per-artifact specifics (its `bsc plan` subcommand, its change-guard, its coercion, and its
        // store setter) live as one row per artifact in the descriptor TABLE below; `reflectArtifact`
        // runs one row. Semantics are identical to the former hand-rolled per-artifact blocks: the
        // stringify-compare change-guard, the silent "not created yet" try/catch, the same fetch/
        // stringify fallbacks, coercers, setters, and order. Three artifacts (repos / deps / mcp) don't
        // fit the shape (loop / one-time legacy import / per-name set) and stay as bespoke blocks below.
        // ── THE batched read (#3842) ──────────────────────────────────────────────────────────
        // One `bsc plan snapshot --json` — one process spawn, one SQLite open — replacing the 17
        // separate `bsc plan <noun>` spawns this tick used to make. At 150-660ms per spawn those cost
        // more than the 2s interval, so the Tauri command queue oversubscribed and the user's
        // keystrokes (`pty_write`) queued behind them. #3666 stopped ticks STACKING; this shrinks the
        // tick itself. An empty object on failure ⇒ every artifact falls back exactly as before.
        const snap = await bscJson<Record<string, unknown>>(
          effectiveProjectId, ["plan", "snapshot", "--json"], {},
        ) ?? {};

        interface ArtifactDescriptor {
          /** This artifact's key in the `bsc plan snapshot` payload (#3842). */
          key: string;
          /** Value used when the snapshot has no entry (bridge absent / plan.db not created yet).
           *  Identical to the `--json` fallback each artifact's standalone read used to pass. */
          fetchFallback: unknown;
          /** Skip the whole reflect on a null/empty read (the artifacts the old code wrapped in `if (db)`). */
          requireTruthy?: boolean;
          /** `db ?? this` before JSON.stringify (the non-`requireTruthy` artifacts' `?? []`). */
          stringifyFallback?: unknown;
          /** Current guard value — a per-project applied-ref, or the store-owned section blob. */
          applied: () => string | undefined;
          /** Record the applied guard value (no-op when the store write is itself the record). */
          setApplied: (raw: string) => void;
          /** Reflect the read into the store. */
          apply: (db: unknown, raw: string) => void;
        }
        const reflectArtifact = (d: ArtifactDescriptor): void => {
          try {
            // #3842: the value comes from the ONE snapshot read above, not a per-artifact spawn.
            // `?? fetchFallback` reproduces exactly what the standalone `--json` read returned when
            // plan.db had no such artifact, so every guard/coercer/setter below is unchanged.
            const db = snap[d.key] ?? d.fetchFallback;
            if (d.requireTruthy && !db) return;
            const raw = JSON.stringify(db ?? d.stringifyFallback);
            if (raw !== d.applied()) {
              d.setApplied(raw);
              d.apply(db, raw);
            }
          } catch { /* plan.db not created yet — ignore */ }
        };
        // One row per DB-owned artifact, in the same order the old blocks ran. (The bespoke shapes —
        // repos / deps / mcp — run just after as their own blocks; they're order-independent of these.)
        const ARTIFACTS: ArtifactDescriptor[] = [
          // Issues (#plan-db) → the "issues" section, so publish / structure card / grading / mobile mirror read unchanged.
          {
            key: "issues", fetchFallback: [], stringifyFallback: [],
            applied: () => saved["issues"] ?? "", setApplied: () => undefined,
            apply: (_db, raw) => store.setPlanStage(effectiveProjectId, "issues", raw),
          },
          // Features (#plan-db) → the "features" section (board + gate).
          {
            key: "features", fetchFallback: [], stringifyFallback: [],
            applied: () => saved[FEATURES_KEY] ?? "", setApplied: () => undefined,
            apply: (_db, raw) => store.setPlanStage(effectiveProjectId, FEATURES_KEY, raw),
          },
          // Fleet (#1018/#1805, plan.db is the SOLE fleet source) → the "fleet" section (parseFleetFile → setPlanFleet).
          {
            key: "fleet", fetchFallback: null, requireTruthy: true,
            applied: () => saved[FLEET_KEY] ?? "", setApplied: () => undefined,
            apply: (_db, raw) => store.setPlanStage(effectiveProjectId, FLEET_KEY, raw),
          },
          // Deploy config (#1020) → coerced through parseDeployConfigTag into planDeployConfig (the `deploy` gate).
          {
            key: "deploy", fetchFallback: null, requireTruthy: true,
            applied: () => deployAppliedRef.current[effectiveProjectId],
            setApplied: (raw) => { deployAppliedRef.current[effectiveProjectId] = raw; },
            apply: (_db, raw) => {
              const cfg = parseDeployConfigTag(raw, publishRepos);
              if (cfg) store.setPlanDeployConfig(effectiveProjectId, cfg);
            },
          },
          // Market assessment (#2430) → coerced into planMarketConfig (the `marketDefined` gate + Market body).
          {
            key: "market", fetchFallback: null, requireTruthy: true,
            applied: () => marketAppliedRef.current[effectiveProjectId],
            setApplied: (raw) => { marketAppliedRef.current[effectiveProjectId] = raw; },
            apply: (db) => {
              const cfg = coerceMarketConfig(db);
              if (cfg) store.setPlanMarketConfig(effectiveProjectId, cfg);
            },
          },
          // Classification (#3783/#3784) → the planner's discovery output: the UI mode (custom in-app
          // preview vs external drop-files) AND the source/mcp/skills/automations need-flags. Stored whole
          // into planClassification; FocusedBodies reads uiMode, usePlanGates derives the visibility signals.
          {
            key: "classify", fetchFallback: null, requireTruthy: true,
            applied: () => classifyAppliedRef.current[effectiveProjectId],
            setApplied: (raw) => { classifyAppliedRef.current[effectiveProjectId] = raw; },
            apply: (db) => {
              const cfg = coerceClassifyConfig(db);
              if (cfg) store.setPlanClassification(effectiveProjectId, cfg);
            },
          },
          // Transformations (#2509) → coerced rows into planTransformations (the bottom-up confirm queue + gate).
          {
            key: "transformations", fetchFallback: [], stringifyFallback: [],
            applied: () => transformationsAppliedRef.current[effectiveProjectId],
            setApplied: (raw) => { transformationsAppliedRef.current[effectiveProjectId] = raw; },
            apply: (db) => store.setPlanTransformations(effectiveProjectId, coerceTransformationRows(db)),
          },
          // Automations (#2009) → full replace of planAutomations (the `automations` gate).
          {
            key: "automations", fetchFallback: [], stringifyFallback: [],
            applied: () => autoAppliedRef.current[effectiveProjectId],
            setApplied: (raw) => { autoAppliedRef.current[effectiveProjectId] = raw; },
            apply: (db) => store.setPlanAutomations(effectiveProjectId, (db as AutomationSuggestion[] | null) ?? []),
          },
          // Startup scripts (#2010) → per-repo dev/triage startup prompt docs (each `path` resolved to a unified-store relpath).
          {
            key: "startup", fetchFallback: [], stringifyFallback: [],
            applied: () => startupAppliedRef.current[effectiveProjectId],
            setApplied: (raw) => { startupAppliedRef.current[effectiveProjectId] = raw; },
            apply: (db) => {
              const key = sanitizeProjectKey(effectiveProjectId);
              for (const sc of (db as StartupScriptRow[] | null) ?? []) {
                const relpath = scriptDocRelpath(key, sc.path);
                if (sc.mode === "triage") store.setRepoTriagePromptDoc(effectiveProjectId, sc.repo, relpath);
                else                      store.setRepoStartupPromptDoc(effectiveProjectId, sc.repo, relpath);
              }
            },
          },
        ];
        for (const d of ARTIFACTS) reflectArtifact(d);

        // Linked repos are DB-owned too (#1012) — restore them from the hub's plan.db into the store
        // so a zustand/app-state reset can't lose the links (the store-only persistence proved fragile).
        try {
          const dbRepos = (snap.repos as string[] | undefined) ?? [];
          for (const r of dbRepos ?? []) store.addProjectRepo(effectiveProjectId, r);
        } catch { /* plan.db not created until the first repo is linked — ignore */ }

        // Dependency manifest is DB-owned (#1191) — the planner records it with `bsc-plan deps set`
        // (was a raw `dependencies.json`). Reflect the stored blob into the DEPENDENCIES section so the
        // gate, DeployView, worker scope, and publish all read it from plan.db unchanged. When the DB is
        // still empty but a legacy `dependencies.json` exists in the section store, import it ONCE
        // (no data loss) so pre-#1191 projects migrate transparently; after that the DB is authoritative.
        try {
          const dbDeps = snap.deps ?? null;
          if (dbDeps) {
            const raw = JSON.stringify(dbDeps);
            if (raw !== depsAppliedRef.current[effectiveProjectId]) {
              depsAppliedRef.current[effectiveProjectId] = raw;
              if (raw !== (saved[DEPENDENCIES_KEY] ?? "")) store.setPlanStage(effectiveProjectId, DEPENDENCIES_KEY, raw);
            }
          } else if (!depsImportedRef.current.has(effectiveProjectId)) {
            // One-time legacy import: the file content surfaced as the DEPENDENCIES section by an earlier
            // `read_plan_stages` tick. Re-serialize through the tolerant parser so a bare-array (#1111)
            // file is normalized to the full manifest shape before it lands in plan.db.
            const legacy = saved[DEPENDENCIES_KEY] ?? "";
            const manifest = parseDependencyManifest(legacy);
            if (manifest.dependencies.length || Object.keys(manifest.registries).length) {
              depsImportedRef.current.add(effectiveProjectId);
              await bscWrite(effectiveProjectId, ["plan", "deps", "set"], manifest);
            }
          }
        } catch { /* plan.db not created until the planner sets deps — ignore */ }

        // MCP assignments are DB-owned (#1021) — resolve each assigned catalog name into the MCP-servers
        // store (idempotent). First-party servers are queued for the download-confirmation modal
        // (#1055) instead of cloned silently. The applied-set guards against re-applying the same name
        // every 2s tick (and the modal's seen-set guards against re-prompting).
        try {
          const dbMcp = (snap.mcp as string[] | undefined) ?? [];
          const toDownload: string[] = [];
          for (const name of dbMcp ?? []) {
            const key = `${effectiveProjectId}::${name.toLowerCase()}`;
            if (mcpAppliedRef.current.has(key)) continue;
            mcpAppliedRef.current.add(key);
            applyMcpAssign(store, name, effectiveProjectId, store.bscBaseDir);
            if (catalogLink(name)) toDownload.push(name);
          }
          if (toDownload.length) void enqueueMcpDownloads(toDownload);
        } catch { /* plan.db not created until the planner assigns an MCP server — ignore */ }

        // Section files: a planner launched INSIDE the WSL2 cage (#1988) writes them into the distro
        // hub, so read from there (via `read_sandbox_plan_stages`) when this session is sandboxed
        // (`sandboxed`, computed above) — else the host hub. Fall back to the host read if the distro
        // read is empty (e.g. the relocation fell back to host at launch), so sections never vanish.
        let result: Record<string, string>;
        if (sandboxed) {
          result = await invoke<Record<string, string>>("read_sandbox_plan_stages", { key: effectiveProjectId })
            .catch(() => ({} as Record<string, string>));
          if (Object.keys(result).length === 0) {
            result = await invoke<Record<string, string>>("read_plan_stages", { projectKey: effectiveProjectId });
          }
        } else {
          result = await invoke<Record<string, string>>("read_plan_stages", { projectKey: effectiveProjectId });
        }
        const entries = Object.entries(result);

        for (const [rawKey, content] of entries) {
          // Canonicalize the file stem (e.g. "Tech stack" → "stack") so a title-named file
          // still satisfies the gate (#…).
          const key = canonicalTopicKey(rawKey);
          if (key === "issues" || key === FEATURES_KEY || key === FLEET_KEY) continue; // DB-owned (#plan-db/#1018) — sourced from plan.db above, not a file
          // Dependencies are DB-owned (#1191): once plan.db has supplied the manifest, the DB blob wins
          // over any lingering legacy `dependencies.json`. Until then, let the file through so the
          // one-time legacy import (above) can read it.
          if (key === DEPENDENCIES_KEY && depsAppliedRef.current[effectiveProjectId]) continue;
          // A confirmed stage's content is NO LONGER frozen (#2256): let a changed section through so
          // the confirm-reconcile below can detect the change and reset just that one stage.
          if (content && content !== (saved[key] ?? "")) {
            store.setPlanStage(effectiveProjectId, key, content);
          }
        }

        // Stage confirmations (#2256) — plan.db is the durable store. Rehydrate the confirmed set on
        // revisit, RESET just the stages whose content changed since they were confirmed (fingerprint
        // mismatch), and forward-migrate any pre-#2256 app-state-only confirmations into plan.db once.
        // Runs AFTER all content writes above so the live fingerprints reflect this tick's sections.
        try {
          const rows = (snap.confirm as ConfirmRow[] | undefined) ?? [];
          const fresh = useAppStore.getState();
          const liveSections = fresh.planStages[effectiveProjectId] ?? {};
          const plan = reconcileConfirmations(
            rows, liveSections,
            new Set(fresh.planConfirmedStages[effectiveProjectId] ?? []),
            confirmMigratedRef.current.has(effectiveProjectId),
          );
          for (const k of plan.rehydrate) fresh.markStageConfirmedLocal(effectiveProjectId, k);
          for (const k of plan.reset) fresh.unconfirmPlanStage(effectiveProjectId, k);
          if (plan.migrate.length) {
            confirmMigratedRef.current.add(effectiveProjectId);
            for (const k of plan.migrate) {
              await bscRun(effectiveProjectId, ["plan", "confirm", "add", k, hashString(liveSections[k] ?? "")]);
            }
          }
        } catch { /* plan.db not created yet — ignore */ }

        // Skipped stages (#2267) — same durability as confirmations, minus the fingerprint/reset (a
        // skip is a plain decision, not content-based). Rehydrate the skipped set on revisit and
        // forward-migrate any pre-#2267 app-state-only skips into plan.db once.
        try {
          const rows = (snap.skip as string[] | undefined) ?? [];
          const fresh = useAppStore.getState();
          const plan = reconcileSkips(
            rows,
            new Set(fresh.planSkippedStages[effectiveProjectId] ?? []),
            skipMigratedRef.current.has(effectiveProjectId),
          );
          for (const k of plan.rehydrate) fresh.markStageSkippedLocal(effectiveProjectId, k);
          if (plan.migrate.length) {
            skipMigratedRef.current.add(effectiveProjectId);
            for (const k of plan.migrate) await bscRun(effectiveProjectId, ["plan", "skip", "add", k]);
          }
        } catch { /* plan.db not created yet — ignore */ }
      } catch {
        // plans dir may not exist yet — ignore
      }
    };
    return poll();
  }, 2000, [visible, effectiveProjectId]);
}

// usePlannerBlueprint (#1474) — the planner's blueprint lifecycle derivation (orientation),
// extracted verbatim from Planning.tsx.

import { useMemo } from "react";
import { type Blueprint } from "@/features/planner/stages/blueprints";
import { plannerTreatAsExisting } from "@/features/planner/session/plannerIntro";

interface BlueprintDeps {
  blueprints: Blueprint[];
  effectiveBlueprintId: string;
  /** Whether the project is published (activeProjectId set) — the save-state proxy. */
  isExisting: boolean;
}

export interface PlannerBlueprint {
  activeBlueprint: Blueprint | undefined;
  treatAsExisting: boolean;
}

export function usePlannerBlueprint(deps: BlueprintDeps): PlannerBlueprint {
  const { blueprints, effectiveBlueprintId, isExisting } = deps;

  const activeBlueprint = useMemo(() => blueprints.find(b => b.id === effectiveBlueprintId), [blueprints, effectiveBlueprintId]);
  // #1286: the planner's orientation (its intro greeting AND its generated CLAUDE.md spec) follows
  // the blueprint's lifecycle MODE — an operate-mode blueprint (transform/harden/maintain) takes the
  // "existing repos" orientation even on a fresh draft, where the bare `isExisting` (saved-project)
  // proxy would mis-greet it as a new greenfield project. Plain `isExisting` stays for the
  // drafting/expanding UI labels (genuinely about save-state).
  const treatAsExisting = plannerTreatAsExisting({ isSaved: isExisting, mode: activeBlueprint?.mode });

  return { activeBlueprint, treatAsExisting };
}

// usePlannerMessages (#1775, extracted from Planning.tsx) — while the relay is paired, poll the
// planner PTY's transcript (newest 50 turns) so a phone mirrors the real chat, not the raw terminal.
// Empty + inert when not paired. (#934/#987)
import { useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { usePoll } from "@/shared/hooks/usePoll";
import type { PlanMessage } from "@/features/tunnel";

export function usePlannerMessages(tunnelRunning: boolean, paneId: string): PlanMessage[] {
  const [plannerMessages, setPlannerMessages] = useState<PlanMessage[]>([]);
  usePoll((isCancelled) => {
    if (!tunnelRunning) return;
    return invoke<PlanMessage[]>("read_pane_messages", { paneId, limit: 50 })
      .then((m) => { if (!isCancelled()) setPlannerMessages(m ?? []); })
      .catch(() => {});
  }, 3000, [tunnelRunning, paneId]);
  return plannerMessages;
}

// Deliver a queued planner prompt into the live planning session (#1371). The focused pane
// queues an ad-hoc prompt via `requestPlannerPrompt` (e.g. the file-intake "Route to project"
// ROUTE_PROMPT, which tells the planner to route the dropped design/ files into the repo). That
// value used to be a dead drop — set in the store but never delivered — so design files were
// staged and the UI gate auto-completed, yet the planner was never told to route them.
//
// This hook closes that gap: when a prompt is queued for the active project, it injects it into
// the planner PTY (via the caller's `sendPrompt`) and clears it. Delivery is user-initiated (a
// button click queued it), so this does NOT resurrect the removed auto-injecting conductor.

import { useEffect } from "react";
import { useAppStore } from "@/store";

/**
 * Drain `pendingPlannerPrompt[projectId]` into the live planner session.
 * @param projectId  the active planning session key (`effectiveProjectId`)
 * @param sendPrompt injects one prompt into the planner PTY (Planning.tsx's `sendPrompt`)
 */
export function usePlannerPromptDelivery(projectId: string, sendPrompt: (prompt: string) => void) {
  const pending = useAppStore((s) => (projectId ? s.pendingPlannerPrompt[projectId] : undefined));
  const clearPlannerPrompt = useAppStore((s) => s.clearPlannerPrompt);
  useEffect(() => {
    if (!projectId || !pending) return;
    sendPrompt(pending);
    clearPlannerPrompt(projectId);
  }, [projectId, pending, sendPrompt, clearPlannerPrompt]);
}

// usePlannerRepoManagement (#1474) — the planner's headless repo auto-clone, extracted verbatim
// from Planning.tsx. Eagerly clones each linked repo into the project dir as it appears, persisting
// the link in plan.db. The linked set is DB-owned: the planner runs `bsc plan repo add owner/repo`,
// the section poll reflects `plan_list_repos` into `effectiveRepos`, and this effect clones each new
// entry. Side-effect only — returns nothing.

import { useEffect, useRef } from "react";
import { invoke } from "@tauri-apps/api/core";
import { bscRun } from "@/shared/lib/core/bsc";
import { useAppStore } from "@/store";

export function usePlannerRepoManagement(effectiveProjectId: string, effectiveRepos: string[]): void {
  // Eager auto-clone (#508): the visible repo strip was removed from the header, but its clone
  // engine lives on headlessly here. Each linked repo (surfaced via the plan.db poll) is cloned
  // into the project dir as soon as it appears, populating projectLocalRepos → linkedRepos →
  // setup_workspaces, so the planner can read repo contents during planning (triage launch
  // re-clones fail-soft, but that's too late for in-session context). Idempotent on the Rust side.
  const autoCloneRef = useRef<Set<string>>(new Set());
  useEffect(() => {
    if (!effectiveProjectId) return;
    const cloned = new Set(useAppStore.getState().projectLocalRepos[effectiveProjectId] ?? []);
    for (const fullName of effectiveRepos) {
      if (cloned.has(fullName) || autoCloneRef.current.has(fullName)) continue;
      autoCloneRef.current.add(fullName);
      invoke<string>("clone_repo", { project: effectiveProjectId, fullName })
        .then(() => {
          useAppStore.getState().addProjectRepo(effectiveProjectId, fullName);
          // Persist the link in the hub's plan.db (#1012) — durable across a store/app-state reset,
          // which the store-only persistence didn't survive.
          void bscRun(effectiveProjectId, ["plan", "repo", "add", fullName]);
        })
        .catch(e => console.error(`clone ${fullName} failed:`, e))
        .finally(() => autoCloneRef.current.delete(fullName));
    }
  }, [effectiveProjectId, effectiveRepos]);
}

// usePlannerTagStream (#1474) — the planner's PTY output buffer. Owns the two output buffers and a
// `processChunk` that, per PTY data chunk, strips ANSI, accumulates, and caps the buffer. The
// planner used to emit structured `<tag>`s parsed here; every one has since moved to plan.db via a
// `bsc plan …` command reflected by the section poll (the last, `<plan_focus>`, removed in #2017),
// so this hook no longer parses anything — it just maintains the buffers the autopilot reads.
//
//   bufRef         — the accumulated output buffer (the caller's restart clears it)
//   autopilotTxRef — an UN-consumed copy of the same output, read by the autopilot idle-detector
//
// Both refs are returned so the caller's restart (clears bufRef) and autopilot (reads
// autopilotTxRef) keep their existing access. `processChunk` is a stable callback, so the
// once-attached `pty_data` listener is set up a single time.

import { useCallback, useRef } from "react";
import { stripAnsi } from "@/features/planner/session/planningTerminal";

export interface PlannerTagStream {
  /** Feed one PTY data chunk: accumulate it and parse/dispatch any structured tags it completes. */
  processChunk: (payload: string) => void;
  /** The tag-scan buffer (the caller's restart clears it). */
  bufRef: React.MutableRefObject<string>;
  /** The un-consumed output copy the autopilot idle-detector reads. */
  autopilotTxRef: React.MutableRefObject<string>;
}

export function usePlannerTagStream(): PlannerTagStream {
  // Accumulated stripped output. Historically drained by the tag parsers as they consumed tags;
  // every planner tag now writes to plan.db via `bsc plan …` and is reflected by the section poll,
  // so nothing is parsed here anymore (the last, `<plan_focus>`, was removed in #2017). The buffer +
  // its un-consumed autopilot copy remain: the autopilot idle-detector (#746) reads them, and the
  // cap keeps them bounded.
  const bufRef = useRef("");
  // Autopilot (#746): an un-consumed copy of the planner's raw output, for idle-detection + user-sim.
  const autopilotTxRef = useRef("");

  const processChunk = useCallback((payload: string) => {
    bufRef.current += stripAnsi(payload);
    autopilotTxRef.current += stripAnsi(payload); // un-consumed copy for the autopilot (#746)

    // Cap buffer to prevent unbounded growth while preserving any partial
    // in-progress tag that hasn't received its closing counterpart yet.
    const MAX_BUF = 120_000;
    if (bufRef.current.length > MAX_BUF) {
      const lastTagStart = bufRef.current.lastIndexOf("<");
      bufRef.current = bufRef.current.slice(
        lastTagStart > 0 && lastTagStart > bufRef.current.length - MAX_BUF
          ? lastTagStart
          : bufRef.current.length - MAX_BUF
      );
    }
  }, []);

  return { processChunk, bufRef, autopilotTxRef };
}

// usePlannerTerminal (#1775, extracted from Planning.tsx) — owns the planner's xterm.js terminal
// and its PTY lifecycle:
//   • mount — create the terminal + fit addon, subscribe to pty_data/pty_exit, run setup_workspaces
//     (the isolated planning dir + CLAUDE.md), write the plan-only role gate into session settings,
//     and spawn `claude` with the fresh-only intro prompt. pty_kill on unmount ends it cleanly.
//   • re-fit — re-measure when the panel becomes visible (hidden → shown), after a short delay, and
//     once the mono font loads (cell metrics are wrong until then).
//   • re-sync — re-run setup_workspaces when a linked repo resolves after the initial mount.
// This is a behavior-preserving move out of the component; the once-effect deps (and the two
// eslint-disables they require) are reproduced exactly — NO logic change.
import { useEffect, type RefObject, type MutableRefObject } from "react";
import type { Terminal } from "@xterm/xterm";
import { invoke } from "@tauri-apps/api/core";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { useAppStore } from "@/store";
import { roleCapability, roleDeniedCommands, roleWriteRules } from "@/shared/lib/session/sessionRoles";
import { useScreenSession } from "@/shared/lib/session/useScreenSession";
import { TURN_ACCOUNTING_HOOKS } from "@/shared/lib/session/turnHooks";
import { resolveAllInstalledMcp, toSessionPayloads, mcpAllowRules } from "@/features/mcp";
import { plannerIntroMode, composePlannerIntro } from "@/features/planner/session/plannerIntro";
import { plannerLaunchConfig } from "@/features/planner/session/plannerLaunch";
import { resolvePlannerSandbox } from "@/features/planner/session/plannerSandbox";
import { TERM_THEME } from "@/app/console/lib/terminalConstants";
import type { Command, Schedule } from "@/shared/data/mock";

export interface PlannerTerminalOpts {
  paneId: string;
  /** Whether the planning panel is on-screen — drives the re-fit effect. */
  visible: boolean;
  effectiveProjectId: string;
  /** full_names linked + cloned for this project; drives the post-mount workspace re-sync. */
  linkedRepos: string[];
  treatAsExisting: boolean;
  activeProjectName: string;
  activeProjectNumber: number;
  planningPitch: string;
  /** The blueprint's enabled stage ids for a project key — scopes the planner CLAUDE.md (#A). */
  stageIdsFor: (key: string) => string[];
  /** Re-read the setup baseline after a workspace setup (#756). */
  refreshSetupSig: () => void;
  /** Parse structured <tag>s out of the stripped PTY output stream (#1474, usePlannerTagStream). */
  processChunk: (chunk: string) => void;
  commands: Command[];
  schedules: Schedule[];
  /** Write the resolved planner hub dir up to the owning component (read by the MCP + tunnel wiring,
   *  so the state cell lives in Planning where those earlier hooks can see it) (#801). */
  setPlanningDir: (dir: string) => void;
}

export interface PlannerTerminalHandle {
  /** Host element for the xterm canvas — attach to the terminal container div. */
  containerRef: RefObject<HTMLDivElement | null>;
  /** The live xterm instance (null before mount / after unmount) — read by sendPrompt + restart. */
  termRef: MutableRefObject<Terminal | null>;
}

export function usePlannerTerminal(opts: PlannerTerminalOpts): PlannerTerminalHandle {
  const {
    paneId, visible, effectiveProjectId, linkedRepos, treatAsExisting,
    activeProjectName, activeProjectNumber, planningPitch, stageIdsFor, refreshSetupSig,
    processChunk, commands, schedules, setPlanningDir,
  } = opts;

  // The whole xterm + PTY lifecycle (terminal literal, subscribe-before-create ordering,
  // ResizeObserver, refit, cleanup) lives in the shared hook; this wrapper owns only the PLANNER
  // launch path (workspace setup → role gate + MCP → intro → sandbox → pty_create), the tag-parse
  // onData hook, and the repo-resync effect below. pty_kill is called on unmount so navigating away
  // ends the session cleanly. The once-effect launch is a behavior-preserving move — NO logic change.
  const { containerRef, termRef } = useScreenSession({
    paneId,
    termTheme: TERM_THEME,
    visible,
    exitBanner: "\r\n\x1b[33m[session ended — navigate away and back to restart]\x1b[0m\r\n",

    // Parse structured tags out of the stripped output stream (#1474, usePlannerTagStream).
    onData: (payload) => processChunk(payload),

    // Capture state at mount time (synchronously, before the RAF) for workspace sync.
    snapshot: () => ({
      repoSnapshot:        linkedRepos, // string[] of full_names
      treatAsExistingSnap: treatAsExisting,
      projNameSnap:        activeProjectName,
      projNumberSnap:      activeProjectNumber,
      pitchSnap:           planningPitch,
      projIdSnap:          effectiveProjectId,
      ghLoginSnap:         useAppStore.getState().githubUser?.login ?? "",
      ghNameSnap:          useAppStore.getState().githubUser?.name  ?? "",
      automationsSnap: [
        ...commands.map(c => ({ id: c.id, name: c.name, command: c.cmd, schedule: null })),
        ...schedules.map(sc => ({ id: sc.id, name: sc.name, command: sc.detail, schedule: sc.when })),
      ],
    }),

    launch: async (term, snap) => {
      const {
        repoSnapshot, treatAsExistingSnap, projNameSnap, projNumberSnap,
        pitchSnap, projIdSnap, ghLoginSnap, ghNameSnap, automationsSnap,
      } = snap;

      // Create the isolated planning workspace directory with settings.json + CLAUDE.md.
      const paths = await safeInvoke<{ planning_dir: string } | null>(
        "setup_workspaces",
        {
          repoFullNames: repoSnapshot,
          automations:   automationsSnap,
          isExisting:    treatAsExistingSnap,
          projectName:   projNameSnap,
          projectNumber: projNumberSnap,
          pitch:         pitchSnap,
          projectKey:    projIdSnap,
          githubLogin:   ghLoginSnap,
          githubName:    ghNameSnap,
          enabledStages: stageIdsFor(projIdSnap), // scope the planner CLAUDE.md to the blueprint (#A)
        },
        null,
        (e: unknown) => console.error("workspace setup failed:", e),
      );
      refreshSetupSig(); // baseline updated (#756)
      if (paths) setPlanningDir(paths.planning_dir); // for the relay planner-pane mirror (#801)

      // Launch claude inside the isolated planning directory.
      // Inject the stored GitHub token so `gh` CLI and direct API calls work
      // without requiring the user to separately authenticate the gh CLI.
      const token = useAppStore.getState().githubToken;
      const ghEnv: Record<string, string> = token ? { GH_TOKEN: token, GITHUB_TOKEN: token } : {};
      // Role gate (#219): the planning session launches as the DIRECTOR — planning and directing
      // are one actor at two phases of a project, so the capability moved onto that role rather than
      // being duplicated. It stays plan-only: git/gh read, writes scoped to the plan files, so it can
      // read for context but neither edit project code nor mutate the repo/GitHub (publishing is an
      // explicit, separately-gated step).
      const planCap = roleCapability("director");
      const planWrite = roleWriteRules(planCap);
      // Expose EVERY installed MCP server to the planner (#1054), project scope ignored: the planner
      // is the assignment hub, so it sees all downloaded servers — it can call them while planning
      // (e.g. research sources for a skill) and assign them to the workers that need them.
      const plannerMcp = toSessionPayloads(resolveAllInstalledMcp(useAppStore.getState().mcpServers), []).mcp;
      // The role gate covers the planner's scoped plan-file writes + git/gh read-only.
      // WebFetch (docs / version / pricing lookups) and Read are added explicitly here so
      // this single role-launch path fully sources the planner's tools — replacing the
      // hardcoded settings.json literal that setup_workspaces used to write (#799).
      await safeInvoke("ensure_session_settings", {
        cwd:             paths?.planning_dir ?? "",
        allowedCommands: [],
        deniedCommands:  roleDeniedCommands(planCap),
        mcpServers:      plannerMcp,
        // Turn accounting (#3455): the planner's bespoke launch must ALSO register the observability
        // floor. bsc-tokens is the only per-session token source, so without it the planner's (often
        // large) planning cost is invisible to `bsc metrics`. Shared with the generic path.
        hooks:           TURN_ACCOUNTING_HOOKS,
        // Auto-approve every MCP server the planner sees (Research/Compliance + any downloaded one)
        // so it can call them while planning — e.g. the Research MCP when grounding a skill — without
        // a per-tool permission prompt. `enabledMcpjsonServers` only trusts the server to LOAD.
        allowToolRules:  [...planWrite.allow, "Read", "WebFetch", ...mcpAllowRules(plannerMcp)],
        denyToolRules:   planWrite.deny,
        replacePermissions: true,
      }, undefined, (e: unknown) => console.error("planner session settings failed:", e));
      // Planner introduction (#1240): a user-facing kickoff that has the planner OPEN the
      // conversation (introduce itself, sketch the stage journey, summarize capabilities, ask one
      // orienting question) instead of launching into a quiet terminal. Baked into the claude launch
      // arg as a FRESH-ONLY startup prompt — the backend (which knows the conversation history)
      // delivers it only on a genuinely new session and drops it on `--continue` resume, so a
      // returning user isn't re-greeted. For a new project the user's pitch rides along so the
      // planner acknowledges it rather than asking what they're building (replaces the old
      // idle-detection pitch-typing). On failure it's undefined → the launch falls back to initCmd.
      const introMode = plannerIntroMode({ isExisting: treatAsExistingSnap });
      const introText = await safeInvoke<string>("planner_intro_prompt", { mode: introMode }, "",
        (e: unknown) => console.error("planner intro prompt failed:", e));
      // Run the planner on the selected harness: Claude Code, or bsc-agent (any LLM) when chosen or
      // forced by a local/ollama provider Claude can't drive (#1078). bsc-agent gets the same plan-only
      // role gate, MCP, and provider/model/base-url via BSC_AGENT_* env; context + the intro prompt +
      // plan state come through identically.
      const launch = plannerLaunchConfig(useAppStore.getState(), ghEnv);
      // bsc-agent is a one-shot loop, so it never receives stage 1's directive via runtime injection
      // (Claude does). Bake the first active stage's directive into the intro so a weak local model
      // begins discovery instead of greeting and then waiting to be advanced (#qwen).
      let firstStageDirective: string | undefined;
      if (launch.providerId === "bsc-agent") {
        const firstStage = stageIdsFor(projIdSnap)[0];
        if (firstStage) {
          firstStageDirective = await safeInvoke<string>(
            "planner_stage_directive", { id: firstStage }, "",
            (e: unknown) => console.error("planner stage directive failed:", e),
          ) || undefined;
        }
      }
      const startupPrompt = composePlannerIntro(introText, introMode, pitchSnap ?? "", firstStageDirective) || undefined;
      // #1988: opt-in (off by default) — relocate the hub into the sealed WSL2 distro + spawn INSIDE
      // it when the sandbox toggle is on AND the planner runs on bsc-agent (shared with the restart
      // path so they can't drift; host fallback on failure). Toggling restarts the planner to convert.
      const sandbox = await resolvePlannerSandbox(launch.providerId, paths?.planning_dir ?? "", projIdSnap);
      await safeInvoke("pty_create", {
        paneId:  paneId,
        cols:    term.cols,
        rows:    term.rows,
        cwd:     sandbox.cwd,
        initCmd: launch.initCmd,
        startupPrompt,
        startupPromptFreshOnly: launch.startupPromptFreshOnly,
        continueSession: launch.continueSession,
        env:     launch.env,
        providerId: launch.providerId,
        wslDistro: sandbox.wslDistro,
      }, undefined, console.error);
    },
  });

  // Re-sync CLAUDE.md whenever a repo resolves after the initial mount.
  useEffect(() => {
    if (linkedRepos.length === 0) return;
    const { commands: cmds, schedules: scheds } = useAppStore.getState();
    invoke("setup_workspaces", {
      repoFullNames: linkedRepos,
      automations: [
        ...cmds.map(c => ({ id: c.id, name: c.name, command: c.cmd, schedule: null })),
        ...scheds.map(sc => ({ id: sc.id, name: sc.name, command: sc.detail, schedule: sc.when })),
      ],
      isExisting:    treatAsExisting,
      projectName:   activeProjectName,
      projectNumber: activeProjectNumber,
      pitch:         planningPitch,
      projectKey:    effectiveProjectId,
      githubLogin:   useAppStore.getState().githubUser?.login ?? "",
      githubName:    useAppStore.getState().githubUser?.name  ?? "",
      enabledStages: stageIdsFor(effectiveProjectId), // scope the planner CLAUDE.md (#A)
    }).then(() => refreshSetupSig()).catch(console.error); // baseline updated (#756)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [linkedRepos]);

  return { containerRef, termRef };
}

// usePlannerTunnelSync (#1775, extracted from Planning.tsx) — the mobile-relay (#801/#934/#987)
// projection of the live planning session. Owns the canonical-plan derivation, the message poll,
// and every tunnel emit/listen effect, all of which no-op unless the relay is live:
//   • canonicalPlan — the project's plan files + stable id, routed to their canonical relpaths.
//   • (1) file-sync — push the plan files so a paired mobile planner reconciles over the relay (E2E).
//   • (2) PTY mirror — expose the planner pane so a paired phone can view/drive the terminal.
//   • (1b) plan_state — debounced snapshot; plan_status — cheap, un-debounced header update.
//   • plan_event — transient confirmed-section / stage-advanced / message-appended deltas (the refs
//     diff prev vs current at the transition sites).
//   • inbound DRIVE — confirm a section / advance a stage / chat into the PTY from the phone (gated
//     Rust-side behind the input grant; a view-only phone can't steer).
// Behavior-preserving move out of the component; NO logic change.
import { useEffect, useMemo, useRef } from "react";
import { invoke } from "@tauri-apps/api/core";
import { listen } from "@tauri-apps/api/event";
import { useAppStore } from "@/store";
import { hubToCanonical } from "@/features/planner/lib/plannerSync";
import {
  tunnelSetPlanState, tunnelEmitPlanState, tunnelEmitPlanStatus, tunnelEmitPlanEvent,
  publishTunnelDomain, recordTunnelAlerts, gateReadyAlert, plannerWaitingAlert,
} from "@/features/tunnel";
import { usePlannerMessages } from "@/features/planner/session/usePlannerMessages";
import { SKIPPED_KEY, FEATURES_KEY } from "@/features/planner/stages/planTopics";
import { FLEET_KEY } from "@/features/planner/fleet/planFleet";
import { DEPENDENCIES_KEY } from "@/features/planner/issues/dependencies";
import { buildPlanBoardPayload } from "@/features/planner/session/planBoardProjection";
import type { Stage } from "@/features/planner/stages/focusedPlan";

export interface PlannerTunnelSyncOpts {
  effectiveProjectId: string;
  /** The per-project section bucket — the canonical plan is derived from it. */
  savedSections: Record<string, string>;
  confirmedSet: Set<string>;
  /** The active stage key (from usePlanGates) — emitted in plan_state/status/events. */
  currentStage: string;
  planStatusLabel: string;
  /** The planner hub dir (from usePlannerTerminal) — gates the PTY mirror. */
  planningDir: string;
  paneId: string;
  projectTitle: string;
  confirmPlanStage: (projectId: string, key: string) => void;
  /** The focused-pane stage board (from usePlanGates, #2498) — published as the `plan`
   *  store_state domain the mobile Planner page renders. */
  stages: Stage[];
  /** The active stage's gate passed (awaiting the user-only confirm). */
  focusGateReady: boolean;
  planComplete: boolean;
}

export function usePlannerTunnelSync(opts: PlannerTunnelSyncOpts) {
  const {
    effectiveProjectId, savedSections, confirmedSet, currentStage, planStatusLabel,
    planningDir, paneId, projectTitle, confirmPlanStage,
    stages, focusGateReady, planComplete,
  } = opts;
  const tunnelRunning = useAppStore((s) => s.tunnelRunning);

  // The active project's canonical plan (files + the stable proj-<hex> id). Route the JSON
  // manifests to their canonical relpaths; everything else is a `.md` section. commands.json/
  // features.json are outside the canonical-sync contract (isPlanFile), so they're excluded.
  // Shared by the file-sync path (1) and the live-frame emit (1b).
  const canonicalPlan = useMemo(() => {
    if (Object.keys(savedSections).length === 0) return null;
    const md: Record<string, string> = {};
    let phasesJson, issuesJson, fleetJson, reposJson, skippedContent: string | undefined;
    for (const [k, v] of Object.entries(savedSections)) {
      if (k === "phases") phasesJson = v;
      else if (k === "issues") issuesJson = v;
      else if (k === FLEET_KEY) fleetJson = v;
      // Legacy `repos` SECTION-CONTENT key (not the stage key, #1914) — the mobile canonical-sync
      // contract still routes a `reposJson` relpath via hubToCanonical, so keep reading it if present.
      else if (k === "repos") reposJson = v;
      else if (k === SKIPPED_KEY) skippedContent = v;
      else if (k === FEATURES_KEY || k === DEPENDENCIES_KEY) continue;
      else md[k] = v;
    }
    return hubToCanonical({
      projectTitle: effectiveProjectId,
      sections: md,
      confirmedSections: [...confirmedSet],
      phasesJson, issuesJson, fleetJson, reposJson, skippedContent,
    });
  }, [savedSections, confirmedSet, effectiveProjectId]);

  // The planner is a PTY running `claude`, so the structured conversation lives in Claude's
  // transcript — poll it (newest 50 turns) while paired so the phone renders the real chat,
  // not the raw terminal. pipelineRuns stays empty: the planner runs no pipelines (#220).
  const plannerMessages = usePlannerMessages(tunnelRunning, paneId);

  // (1) Plan-sync — push the canonical plan files so a paired mobile planner reconciles over
  // the relay (E2E) instead of the API. Unchanged async file-sync path.
  useEffect(() => {
    if (!tunnelRunning || !canonicalPlan) return;
    tunnelSetPlanState(canonicalPlan.meta.projectId, canonicalPlan.files).catch(() => {});
  }, [tunnelRunning, canonicalPlan]);

  // (2) PTY mirror — register the planner pane in the session roster (keyed source, #2497)
  // so a paired phone can view (and, if granted, drive) the live planner terminal.
  // Unregistered when the planner unmounts or the relay stops.
  useEffect(() => {
    const register = useAppStore.getState().registerTunnelPanes;
    if (!tunnelRunning || !planningDir) { register("planner", []); return; }
    register("planner", [{
      id: paneId, cwd: planningDir, name: `Planner — ${projectTitle}`,
      status: "running" as const, kind: "planner" as const,
    }]);
    return () => useAppStore.getState().registerTunnelPanes("planner", []);
  }, [tunnelRunning, planningDir, paneId, projectTitle]);

  // (1b) plan_state — debounced snapshot (replayed to newly-paired clients Rust-side).
  useEffect(() => {
    if (!tunnelRunning || !canonicalPlan) return;
    const id = setTimeout(() => {
      tunnelEmitPlanState(canonicalPlan.meta.projectId, currentStage, [...confirmedSet], canonicalPlan.files, plannerMessages, []).catch(() => {});
    }, 500);
    return () => clearTimeout(id);
  }, [tunnelRunning, canonicalPlan, currentStage, confirmedSet, plannerMessages]);

  // plan_status — cheap header update, un-debounced on stage/status change.
  useEffect(() => {
    if (!tunnelRunning || !canonicalPlan) return;
    tunnelEmitPlanStatus(canonicalPlan.meta.projectId, currentStage, planStatusLabel).catch(() => {});
  }, [tunnelRunning, canonicalPlan, currentStage, planStatusLabel]);

  // plan_event — transient deltas at the transition sites (refs diff prev vs current).
  const prevConfirmedRef = useRef<Set<string>>(new Set());
  useEffect(() => {
    if (tunnelRunning && canonicalPlan) {
      for (const k of confirmedSet) {
        if (!prevConfirmedRef.current.has(k)) {
          tunnelEmitPlanEvent(canonicalPlan.meta.projectId, { kind: "section_confirmed", at: Date.now(), section: k }).catch(() => {});
        }
      }
    }
    prevConfirmedRef.current = new Set(confirmedSet);
  }, [confirmedSet, tunnelRunning, canonicalPlan]);

  const prevStageRef = useRef("");
  useEffect(() => {
    if (tunnelRunning && canonicalPlan && currentStage && currentStage !== prevStageRef.current) {
      tunnelEmitPlanEvent(canonicalPlan.meta.projectId, { kind: "stage_advanced", at: Date.now(), stage: currentStage }).catch(() => {});
    }
    prevStageRef.current = currentStage;
  }, [currentStage, tunnelRunning, canonicalPlan]);

  const prevMsgCountRef = useRef(0);
  useEffect(() => {
    if (tunnelRunning && canonicalPlan && plannerMessages.length > prevMsgCountRef.current) {
      const last = plannerMessages[plannerMessages.length - 1];
      tunnelEmitPlanEvent(canonicalPlan.meta.projectId, { kind: "message_appended", at: last.at || Date.now(), message: last }).catch(() => {});
    }
    prevMsgCountRef.current = plannerMessages.length;
  }, [plannerMessages, tunnelRunning, canonicalPlan]);

  // (1c) The `plan` store_state domain (#2498): the stage/gate board the mobile Planner page
  // renders — the same `stagesFrom` output the desktop stepper shows, plus fleet streams and
  // the deploy/market gate summaries. COMPLEMENTS plan_state (files + transcript, above); the
  // shared domain publisher debounces, dedups unchanged payloads, and stamps the rev.
  const planFleet = useAppStore((s) => s.planFleet);
  const planSkippedStages = useAppStore((s) => s.planSkippedStages);
  const planDeployConfig = useAppStore((s) => s.planDeployConfig);
  const planMarketConfig = useAppStore((s) => s.planMarketConfig);
  useEffect(() => {
    if (!tunnelRunning || !effectiveProjectId) return;
    publishTunnelDomain("plan", buildPlanBoardPayload({
      projectId: effectiveProjectId,
      title: projectTitle,
      currentStage,
      statusLabel: planStatusLabel,
      gateReady: focusGateReady,
      planComplete,
      stages,
      confirmed: confirmedSet,
      skipped: planSkippedStages[effectiveProjectId] ?? [],
      fleet: planFleet[effectiveProjectId],
      deploy: planDeployConfig[effectiveProjectId],
      market: planMarketConfig[effectiveProjectId],
    }));
  }, [
    tunnelRunning, effectiveProjectId, projectTitle, currentStage, planStatusLabel,
    focusGateReady, planComplete, stages, confirmedSet,
    planSkippedStages, planFleet, planDeployConfig, planMarketConfig,
  ]);

  // gate-ready alert (#2498): the active stage's gate JUST passed — only the USER can confirm,
  // so this is exactly the "come back and advance the plan" moment. Fires only on an OBSERVED
  // not-ready→ready transition per stage: the first run just primes the ref, so remounting the
  // planner over an already-passed gate never re-alerts (each alert mints a fresh id).
  const prevGateRef = useRef<{ stage: string; ready: boolean } | null>(null);
  useEffect(() => {
    const prev = prevGateRef.current;
    if (prev && tunnelRunning && focusGateReady && currentStage &&
        !(prev.ready && prev.stage === currentStage)) {
      recordTunnelAlerts([gateReadyAlert(effectiveProjectId, currentStage, Date.now())]);
    }
    prevGateRef.current = { stage: currentStage, ready: focusGateReady };
  }, [tunnelRunning, focusGateReady, currentStage, effectiveProjectId]);

  // planner-waiting alert (#2498): the planner's newest transcript turn is an ASSISTANT turn —
  // it finished and is waiting on the user. The poll re-delivers the same transcript every few
  // seconds, so the turn key ref (its `at`, falling back to the text) guards re-derivation and
  // the alert hub's id dedup backstops it — one alert per turn.
  const lastPlannerTurnRef = useRef("");
  useEffect(() => {
    if (!tunnelRunning || plannerMessages.length === 0) return;
    const last = plannerMessages[plannerMessages.length - 1];
    if (last.role !== "assistant") return;
    const turnKey = last.at ? String(last.at) : last.text;
    if (turnKey === lastPlannerTurnRef.current) return;
    lastPlannerTurnRef.current = turnKey;
    recordTunnelAlerts([plannerWaitingAlert(effectiveProjectId, paneId, last.text, last.at || Date.now())]);
  }, [tunnelRunning, plannerMessages, effectiveProjectId, paneId]);

  // Inbound DRIVE from the phone (#934): confirm a section, advance a stage, or chat into the
  // planner PTY. Gated Rust-side behind the input grant (a view-only phone can't steer).
  useEffect(() => {
    const subs = [
      listen<{ section: string }>("tunnel://plan-confirm", (e) => confirmPlanStage(effectiveProjectId, e.payload.section)),
      listen<{ stageKey: string }>("tunnel://plan-advance", (e) => confirmPlanStage(effectiveProjectId, e.payload.stageKey)),
      listen<{ text: string }>("tunnel://plan-chat", (e) => { void invoke("pty_write", { paneId, data: e.payload.text + "\r" }); }),
    ];
    return () => { for (const s of subs) void s.then((off) => off()); };
  }, [effectiveProjectId, paneId, confirmPlanStage]);
}

// usePlanningModals (#1642) — the planner's modal open/close state, extracted verbatim from
// Planning.tsx. Owns the clear-plan confirmation flag and the blueprint-update modal, including the
// auto-open state machine (#827/#1296): reset the auto-shown latch on a project switch, then open the
// modal exactly once when a true blueprint/template VERSION mismatch is detected over an existing plan
// (`shouldAutoOpenBlueprintModal` compares only the `v{version}` signature prefix, NOT the broad
// `contextStale` flag — benign setup tweaks keep driving the quiet "context updated" badge instead).
//
// STRICTLY behaviour-preserving: the two effects and their dependency arrays are moved unchanged.

import { useState, useEffect, type Dispatch, type SetStateAction } from "react";
import { shouldAutoOpenBlueprintModal } from "@/features/planner/stages/blueprints";

export interface PlanningModalsDeps {
  effectiveProjectId: string;
  /** The live context signature (from compute_context_signature); null until resolved. */
  currentSig: string | null;
  /** The baseline signature setup_workspaces last wrote; null until read. */
  lastSetupSig: string | null;
  /** Whether the project already has plan sections (gates the destructive auto-open). */
  hasExistingPlan: boolean;
}

export interface PlanningModals {
  /** Clear-plan confirmation dialog (#664). */
  showClearConfirm: boolean;
  setShowClearConfirm: Dispatch<SetStateAction<boolean>>;
  /** Blueprint-update modal (#827). */
  showBlueprintModal: boolean;
  setShowBlueprintModal: Dispatch<SetStateAction<boolean>>;
}

export function usePlanningModals({
  effectiveProjectId, currentSig, lastSetupSig, hasExistingPlan,
}: PlanningModalsDeps): PlanningModals {
  const [showClearConfirm, setShowClearConfirm] = useState(false); // clear-plan confirmation modal (#…)

  // Blueprint-update modal (#827): when a project is opened whose blueprint/planner-template
  // VERSION differs from the one it was seeded with AND it already has a plan, surface a modal so
  // the user explicitly chooses go-back / restart / keep — rather than the old silent refresh,
  // which restarted the planner into a destructive reconciliation that deleted plan files.
  //
  // #1296: gate the auto-open on a true template-version mismatch (`shouldAutoOpenBlueprintModal`,
  // which compares only the `v{version}` prefix of the two signatures), NOT the broad `contextStale`
  // flag. `contextStale` also flips on benign setup tweaks (link a repo, enable/
  // disable a stage) — those must keep driving only the quiet "context updated · refresh" badge
  // below, never this destructive restart dialog.
  const [showBlueprintModal, setShowBlueprintModal] = useState(false);
  const [bpModalAutoShown, setBpModalAutoShown] = useState(false);
  useEffect(() => { setBpModalAutoShown(false); setShowBlueprintModal(false); }, [effectiveProjectId]);
  useEffect(() => {
    if (shouldAutoOpenBlueprintModal({ currentSig, baselineSig: lastSetupSig, hasExistingPlan, alreadyShown: bpModalAutoShown })) {
      setShowBlueprintModal(true);
      setBpModalAutoShown(true);
    }
  }, [currentSig, lastSetupSig, hasExistingPlan, bpModalAutoShown]);

  return { showClearConfirm, setShowClearConfirm, showBlueprintModal, setShowBlueprintModal };
}

// usePlanningSession (#1642) — the planner's session-lifecycle state machine, extracted verbatim
// from Planning.tsx. Owns the `restarting` flag and the four lifecycle operations:
//   • regenerateWorkspace — rewrite CLAUDE.md + the context baseline for the CURRENT blueprint
//     version WITHOUT touching plan section files (shared by restart + "keep files").
//   • handleRestart       — kill the PTY, regenerate, and re-spawn `claude`. Resume-capable by
//     default (#2396); the destructive ops pass `fresh: true` for a brand-new session (#1240).
//   • keepPlanFiles       — adopt the new blueprint/template version on disk, clearing the staleness
//     WITHOUT wiping plan files or restarting into a destructive reconciliation (#827).
//   • doClearPlan         — delete on-disk plan files FIRST (awaited), wipe the store, unlink repos,
//     then restart with a blank slate (#664).
//
// STRICTLY behaviour-preserving: the function bodies, the order of their awaited steps, and every
// store/invoke call are moved unchanged — only the closed-over values become hook parameters.

import { useState, type MutableRefObject } from "react";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import type { Terminal } from "@xterm/xterm";
import type { Dispatch, SetStateAction } from "react";
import { useAppStore } from "@/store";
import { plannerIntroMode, composePlannerIntro } from "@/features/planner/session/plannerIntro";
import { plannerLaunchConfig } from "@/features/planner/session/plannerLaunch";
import { resolvePlannerSandbox } from "@/features/planner/session/plannerSandbox";

export interface PlanningSessionDeps {
  termRef: MutableRefObject<Terminal | null>;
  /** The planner tag-scan buffer — cleared on restart so a stale tag can't replay. */
  bufRef: MutableRefObject<string>;
  paneId: string;
  linkedRepos: string[];
  /** Whether the planner runs in the "operate" (existing-system) intro mode (#1286). */
  treatAsExisting: boolean;
  activeProjectName: string;
  activeProjectNumber: number;
  planningPitch: string;
  effectiveProjectId: string;
  /** The blueprint's enabled stage ids — scopes the planner CLAUDE.md (#A). */
  stageIdsFor: (key: string) => string[];
  /** Re-read the baseline signature the backend last wrote (#756). */
  refreshSetupSig: () => void;
  setShowBlueprintModal: Dispatch<SetStateAction<boolean>>;
  setShowClearConfirm: Dispatch<SetStateAction<boolean>>;
}

export interface PlanningSession {
  restarting: boolean;
  handleRestart: (opts?: { fresh?: boolean }) => Promise<void>;
  keepPlanFiles: () => Promise<void>;
  doClearPlan: () => Promise<void>;
}

export function usePlanningSession(deps: PlanningSessionDeps): PlanningSession {
  const {
    termRef, bufRef, paneId, linkedRepos, treatAsExisting,
    activeProjectName, activeProjectNumber, planningPitch, effectiveProjectId,
    stageIdsFor, refreshSetupSig,
    setShowBlueprintModal, setShowClearConfirm,
  } = deps;

  const [restarting, setRestarting] = useState(false);

  // Regenerate the on-disk workspace (CLAUDE.md + the context baseline) for the CURRENT blueprint
  // version, WITHOUT touching the plan section files. Shared by the restart flow and the "keep
  // files" choice of the blueprint-update modal (#827). refreshSetupSig() rebaselines the
  // signature so the staleness clears.
  async function regenerateWorkspace(): Promise<{ planning_dir: string } | null> {
    const store = useAppStore.getState();
    const currentAutomations = [
      ...store.commands.map(c => ({ id: c.id, name: c.name, command: c.cmd, schedule: null })),
      ...store.schedules.map(sc => ({ id: sc.id, name: sc.name, command: sc.detail, schedule: sc.when })),
    ];
    const paths = await safeInvoke<{ planning_dir: string } | null>(
      "setup_workspaces",
      {
        repoFullNames: linkedRepos,
        automations: currentAutomations,
        isExisting: treatAsExisting,
        projectName: activeProjectName,
        projectNumber: activeProjectNumber,
        pitch: planningPitch,
        projectKey: effectiveProjectId,
        githubLogin: store.githubUser?.login ?? "",
        githubName:  store.githubUser?.name  ?? "",
        enabledStages: stageIdsFor(effectiveProjectId), // scope the planner CLAUDE.md (#A)
      },
      null,
      (e: unknown) => console.error("workspace setup failed:", e),
    );
    refreshSetupSig(); // baseline updated (#756)
    return paths;
  }

  // Relaunch the planner session (#2396). RESUME-CAPABLE by default — the launch mirrors the mount
  // path exactly (`claude --continue || claude` + the fresh-only intro guard + a resume request), so
  // a non-destructive relaunch (sandbox-toggle flip, reopening a project) continues the prior
  // conversation instead of starting over. The destructive clear-plan op passes `fresh: true` to
  // launch a genuinely NEW session — plain `claude`, re-greeted with the intro even
  // though history exists (#1240), since the plan that conversation referred to was just wiped.
  async function handleRestart(opts?: { fresh?: boolean }) {
    const fresh = opts?.fresh === true;
    const term = termRef.current;
    if (!term || restarting) return;
    setRestarting(true);
    bufRef.current = "";
    term.clear();
    await safeInvoke("pty_kill", { paneId: paneId }, undefined, console.error);
    const paths = await regenerateWorkspace();
    const token = useAppStore.getState().githubToken;
    const ghEnv: Record<string, string> = token ? { GH_TOKEN: token, GITHUB_TOKEN: token } : {};
    // The intro rides along on every restart: a `fresh` restart always fires it (#1240 — the user
    // wiped the plan, so re-greet even though history exists); the default resume restart keeps the
    // fresh-only guard, so a returning user with history resumes quietly instead of being re-greeted.
    const introMode = plannerIntroMode({ isExisting: treatAsExisting });
    const introText = await safeInvoke<string>("planner_intro_prompt", { mode: introMode }, "",
      (e: unknown) => console.error("planner intro prompt failed:", e));
    // Relaunch on the selected harness (Claude Code or bsc-agent for any LLM, incl. a forced
    // local/ollama provider), carrying the plan-only role gate + provider/model/MCP via BSC_AGENT_*
    // env so a restarted local-model planner keeps the same context, prompt, state, and permissions.
    const launch = plannerLaunchConfig(useAppStore.getState(), ghEnv);
    // bsc-agent (one-shot) never gets stage 1's directive via runtime injection — bake it into the
    // intro so a weak local model begins the stage instead of waiting to be advanced (#qwen).
    let firstStageDirective: string | undefined;
    if (launch.providerId === "bsc-agent") {
      const firstStage = stageIdsFor(effectiveProjectId)[0];
      if (firstStage) {
        firstStageDirective = await safeInvoke<string>(
          "planner_stage_directive", { id: firstStage }, "",
          (e: unknown) => console.error("planner stage directive failed:", e),
        ) || undefined;
      }
    }
    const startupPrompt = composePlannerIntro(introText, introMode, planningPitch ?? "", firstStageDirective) || undefined;
    // #1988: honor the sandbox toggle on a restart too — shared with the mount path (plannerSandbox).
    // This is the path a sandbox-toggle flip relaunches through, so it MUST convert into/out of the cage
    // (a restart used to always spawn on the host, silently dropping a planner out of the sandbox).
    const sandbox = await resolvePlannerSandbox(launch.providerId, paths?.planning_dir ?? "", effectiveProjectId);
    await safeInvoke("pty_create", {
      paneId: paneId,
      cols: term.cols,
      rows: term.rows,
      cwd: sandbox.cwd,
      // Default (resume): the harness's own launch — for Claude the `--continue || claude` chain —
      // with the fresh-only intro guard + resume request, exactly like the mount path (#2396).
      // Destructive (`fresh`): plain `claude` + an always-firing intro, so the session starts over.
      initCmd: fresh && launch.providerId !== "bsc-agent" ? "claude" : launch.initCmd,
      startupPrompt,
      startupPromptFreshOnly: fresh ? false : launch.startupPromptFreshOnly,
      continueSession: fresh ? false : launch.continueSession,
      env: launch.env,
      providerId: launch.providerId,
      wslDistro: sandbox.wslDistro,
    }, undefined, console.error);
    setRestarting(false);
  }

  // "Keep the previous plan files" (#827): adopt the new blueprint/template version on disk and
  // clear the staleness, WITHOUT wiping plan files and WITHOUT restarting the planner into a
  // destructive reconciliation (the prior silent refresh let a fresh planner delete plan files).
  async function keepPlanFiles() {
    setShowBlueprintModal(false);
    await regenerateWorkspace();
  }

  // Clear/reset the plan (#664/#B) — delete the on-disk plan files FIRST (awaited, so the 2s
  // file poll can't re-read + re-populate the store), wipe the store, unlink the repos, then
  // restart the planner with a blank slate. (Restored: the refactor dropped this flow.)
  // Confirmation is the Dialog below (#…), not a native window.confirm.
  async function doClearPlan() {
    setShowClearConfirm(false);
    const store = useAppStore.getState();
    await safeInvoke("clear_project_plan_files", { projectKey: effectiveProjectId }, undefined, console.error);
    store.clearPlan(effectiveProjectId);
    store.setActiveProjectRepos([]);
    store.setPlanningContext(planningPitch, "");
    void handleRestart({ fresh: true }); // destructive — the plan is gone, start a NEW session (#2396)
  }

  return { restarting, handleRestart, keepPlanFiles, doClearPlan };
}

// usePlanningTitle (#1775, extracted from Planning.tsx) — the editable project title for both
// lifecycles, KEEPING the frozen session key (#2409: renames are display-only — the folder keeps
// its birth-slug; a later reopen under the new name resolves via the reopen-mismatch modal):
//   • PUBLISHED rename (#1226) — commit updates the GitHub Project board title + local name.
//   • UNPUBLISHED draft (#1222) — commit persists to the draft record keyed by the frozen key.
import { useState, useCallback } from "react";
import { useAppStore } from "@/store";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { githubGraphql } from "@/shared/lib/github/github";
import { planRename, applyRename } from "@/features/planner/session/renameProject";
import { planDraftCommit } from "@/features/planner/session/draftTitle";

type Store = ReturnType<typeof useAppStore.getState>;

export function usePlanningTitle(opts: {
  activeProjectId: Store["activeProjectId"];
  activeProjectName: Store["activeProjectName"];
  activeProjectNumber: Store["activeProjectNumber"];
  activeProjectRepos: Store["activeProjectRepos"];
  planningTitle: Store["planningTitle"];
  setPlanningTitle: Store["setPlanningTitle"];
  effectiveProjectId: string;
}) {
  const {
    activeProjectId, activeProjectName, activeProjectNumber, activeProjectRepos,
    planningTitle, setPlanningTitle, effectiveProjectId,
  } = opts;

  // ── Rename a PUBLISHED project (#1226) ──────────────────────────────────────────
  const [titleEdit, setTitleEdit] = useState<string | null>(null);
  const [renameErr, setRenameErr] = useState<string | null>(null);
  const commitRename = useCallback(async () => {
    // The duplicate guard compares against OTHER projects' frozen keys — the draft-map keys
    // (name-derived slugs, #2409). Renames are display-only (the folder keeps its birth-slug), so
    // a rename that slugs onto another key would only surface later as a reopen collision — this
    // guard catches it up front where the store knows the other keys.
    const st0 = useAppStore.getState();
    const otherKeys = new Set(
      Object.keys(st0.localDraftProjects).filter((k) => k !== effectiveProjectId),
    );
    const plan = planRename(titleEdit ?? "", activeProjectName, activeProjectId, otherKeys);
    setTitleEdit(null);
    if (plan.kind === "noop") { setRenameErr(null); return; }
    if (plan.kind === "error") { setRenameErr(plan.message); return; }
    const st = useAppStore.getState();
    setRenameErr(
      await applyRename(activeProjectId!, plan.title, {
        graphql: githubGraphql,
        setMeta: st.setActiveProjectMeta,
        repo: st.activeProjectRepo,
        number: activeProjectNumber,
        repos: activeProjectRepos,
      }),
    );
    // Keep the on-disk hub title (`projects/<key>/.title`) in step with the rename so the durable
    // name — read by list_local_projects and the session skill-group naming — reflects the new title.
    fireInvoke("set_project_title", { projectKey: effectiveProjectId, title: plan.title });
  }, [titleEdit, activeProjectName, activeProjectId, activeProjectNumber, activeProjectRepos, effectiveProjectId]);

  // ── Persist a DRAFT title edit (#1222) ──────────────────────────────────────────
  const [draftTitleErr, setDraftTitleErr] = useState<string | null>(null);
  const commitDraftTitle = useCallback(() => {
    const st = useAppStore.getState();
    const draft = st.localDraftProjects[effectiveProjectId];
    if (!draft) { setDraftTitleErr(null); return; } // not an unpublished draft — nothing to persist
    const otherKeys = new Set<string>();
    for (const k of Object.keys(st.localDraftProjects)) if (k !== effectiveProjectId) otherKeys.add(k);
    const plan = planDraftCommit(planningTitle, draft.title, otherKeys);
    if (plan.kind === "revert") { setPlanningTitle(draft.title); setDraftTitleErr(null); return; }
    if (plan.kind === "noop") { setDraftTitleErr(null); return; }
    if (plan.kind === "error") { setDraftTitleErr(plan.message); return; } // keep the typed value to fix
    st.updateDraftProject(effectiveProjectId, { title: plan.title });
    // Mirror the draft rename into the durable hub title (`.title`) so the on-disk name doesn't fall
    // back to a key-derived placeholder once goal.md/the store drift out of view.
    fireInvoke("set_project_title", { projectKey: effectiveProjectId, title: plan.title });
    setDraftTitleErr(null);
  }, [planningTitle, effectiveProjectId, setPlanningTitle]);

  return { titleEdit, setTitleEdit, renameErr, setRenameErr, commitRename, draftTitleErr, setDraftTitleErr, commitDraftTitle };
}

// usePoll (#1494) — the one polling primitive. Replaces the ~identical
// `useEffect` + `setInterval` + `clearInterval` + cancelled-guard blocks scattered across the
// app (per-pane token usage, the idle reaper, worker audit, skills refresh, …).
//
// Contract, matching the hand-rolled blocks it replaces:
//  - runs `fn` once immediately, then every `ms` (pass `{ immediate: false }` to skip the first run
//    — e.g. the idle reaper, which must honor its grace window before the first tick);
//  - re-subscribes only when `ms` or `deps` change (the latest `fn` is always called via a ref, so
//    a fresh closure each render does NOT thrash the interval);
//  - on cleanup, clears the interval AND flips the `isCancelled()` the callback receives, so an
//    in-flight async `fn` can bail before it touches state after unmount.

import { useEffect, useRef, type DependencyList } from "react";

interface PollOptions {
  /** Run `fn` once immediately on mount / deps-change. Default true. */
  immediate?: boolean;
}

export function usePoll(
  fn: (isCancelled: () => boolean) => void | Promise<void>,
  ms: number,
  deps: DependencyList = [],
  opts: PollOptions = {},
): void {
  const { immediate = true } = opts;
  const fnRef = useRef(fn);
  useEffect(() => { fnRef.current = fn; });

  useEffect(() => {
    let cancelled = false;
    let running = false; // #3666: don't RE-ENTER while the previous async run is still pending.
    const isCancelled = () => cancelled;
    const tick = () => {
      // A run that outlasts `ms` must NOT stack: overlapping runs pile invokes into the backend queue
      // (the planner's ~13 `bsc plan` reads per 2s tick jammed every pty_write, #3666). Skip a tick
      // while the previous async run is in flight; a sync (void-returning) `fn` is unaffected.
      if (running) return;
      const r = fnRef.current(isCancelled);
      if (r && typeof (r as Promise<unknown>).then === "function") {
        running = true;
        void (r as Promise<unknown>).finally(() => { running = false; });
      }
    };
    if (immediate) tick();
    const id = setInterval(tick, ms);
    return () => { cancelled = true; clearInterval(id); };
    // `fn` is intentionally read via ref, not a dep; callers declare their own deps.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ms, immediate, ...deps]);
}

// usePreviewData (#2940 / #3439) — resolves a component's preview data into the override map
// `ComponentPreviewFrame` feeds `componentPreviewFiles`, in the resolution order
//
//     curated binding (#2940)  →  shape tier (#3439)  →  samplePropValue (the component's own sample)
//
// 1. A curated `PREVIEW_BINDINGS` row runs the bound librarian algorithm's `vizCode` in the sandbox,
//    normalizes it (`vizRunToDataset`), shapes it for the prop (`adaptDataset`) — ASYNC.
// 2. Otherwise, if the component declares a supported `DataShape`, the SHAPE TIER feeds it real
//    algorithm-generated data with no per-component row (`shapePreviewData`) — SYNC (the trace programs
//    run on the main thread).
// 3. Otherwise `{}` → the component's own sample shows.
//
// Fail-SOFT throughout: a missing impl/`vizCode`, a sandbox error, an unusable dataset, or a shape with
// no landable prop all resolve to `{}`, so a preview is never broken.
import { useEffect, useMemo, useState } from "react";
import { KNOWLEDGE, implById, runInSandbox, vizRunToDataset, datasetForStructure } from "@/features/algorithms";
import type { ComponentRecord } from "@/features/designs/lib/model";
import { bindingFor, adaptDataset } from "@/features/designs/lib/previewBindings";
import { shapePreviewData } from "@/features/designs/lib/shapePreview";

const EMPTY: Record<string, string> = {};

/** The preview-data override map for `comp` (`{ prop: JS-source literal }`), or `{}` until/unless a bound
 *  algorithm or a supported shape resolves. Safe to pass straight to `componentPreviewFiles(..., previewData)`. */
export function usePreviewData(comp: ComponentRecord): Record<string, string> {
  const binding = bindingFor(comp.kitId, comp.name);
  const [data, setData] = useState<Record<string, string>>(EMPTY);

  // Shape tier (#3439): SYNC — only when there is NO curated binding (that path wins). The trace programs
  // run on the main thread, so this needs no effect; memoized on the component identity that determines it.
  const shapeData = useMemo(
    () => (binding ? EMPTY : shapePreviewData(comp, datasetForStructure)),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- comp identity (kitId/name/shapes/props) determines it
    [binding, comp.kitId, comp.name],
  );

  // Key the resolve on the identity that determines the result — the bound algorithm + prop. A different
  // component (no binding) resets to EMPTY synchronously below via the early clear.
  const key = binding ? `${binding.algorithm}:${binding.prop}` : "";

  useEffect(() => {
    /* eslint-disable react-hooks/set-state-in-effect -- intentional reset: clear stale data when the
       bound component changes or its algorithm has no runnable vizCode (mirrors ComponentPreviewFrame). */
    if (!binding) { setData(EMPTY); return; }
    const impl = implById(KNOWLEDGE, binding.algorithm);
    const vizCode = impl?.vizCode?.trim();
    if (!vizCode) { setData(EMPTY); return; }
    /* eslint-enable react-hooks/set-state-in-effect */

    let cancelled = false;
    void runInSandbox(vizCode)
      .then((run) => {
        if (cancelled) return;
        const value = adaptDataset(vizRunToDataset(run), binding.adapter);
        setData(value == null ? EMPTY : { [binding.prop]: JSON.stringify(value) });
      })
      .catch(() => { if (!cancelled) setData(EMPTY); });

    return () => { cancelled = true; };
    // `key` captures the binding's algorithm+prop; `comp.kitId`/`comp.name` feed `binding` above.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  return binding ? data : shapeData;
}

// usePreviewReview (#2623 slice 5b) — the reviewer loop's actuator for the open preview node. Owns the
// display-capture stream, turns a "Capture & review" click into a shot → Claude review (5c) → findings
// merged into the confirm-gated inbox (5a store), and exposes confirm/dismiss. Findings live in the store
// keyed by project so the strip re-renders; the stream is a ref (one OS "share" pick, reused per shot).

import { useCallback, useEffect, useRef, useState } from "react";
import { useAppStore } from "@/store";
import { resolveLlmConfig } from "@/shared/lib/core/llmConfig";
import { startPreviewCapture, grabFrame, stopCapture, screenCaptureAvailable } from "@/shared/lib/preview/captureFrame";
import { reviewShot } from "@/shared/lib/preview/reviewShot";
import {
  mergeFindings,
  setFindingStatus,
  pendingFindings,
  confirmedFindings,
  routedFindings,
  type PreviewShot,
  type ReviewFinding,
} from "@/shared/lib/preview/previewReview";

const EMPTY: ReviewFinding[] = [];
const errText = (e: unknown): string => (e instanceof Error ? e.message : String(e));


export interface PreviewReview {
  findings: ReviewFinding[];
  pending: ReviewFinding[];
  confirmed: ReviewFinding[];
  /** Findings already routed to the fleet (a tally; they don't re-dispatch). */
  routed: ReviewFinding[];
  /** Screen capture is available in this webview (gate the capture button). */
  canCapture: boolean;
  /** A capture + review is in flight. */
  busy: boolean;
  /** The last capture/review/dispatch failure, or null. */
  error: string | null;
  /** Capture the current preview frame and review it — folds new findings into the inbox. */
  captureAndReview: () => Promise<void>;
  confirm: (id: string) => void;
  dismiss: (id: string) => void;
  /** Route all confirmed findings to the project's director (bsc-issue → bsc-assign) and mark them routed. */
  dispatch: () => Promise<void>;
}

export function usePreviewReview(projectKey: string | null): PreviewReview {
  const findings = useAppStore((s) => (projectKey ? s.reviewFindings[projectKey] : undefined) ?? EMPTY);
  const streamRef = useRef<MediaStream | null>(null);
  const seqRef = useRef(0);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // End the OS "sharing" stream when the preview closes / the hook unmounts.
  useEffect(() => () => { stopCapture(streamRef.current); streamRef.current = null; }, []);

  const captureAndReview = useCallback(async () => {
    if (!projectKey || busy) return;
    setError(null);
    setBusy(true);
    try {
      if (!streamRef.current) streamRef.current = await startPreviewCapture();
      const image = await grabFrame(streamRef.current);
      const seq = seqRef.current++;
      const shot: PreviewShot = { id: `${projectKey}:${seq}`, label: `Screen ${seq + 1}`, image };
      const found = await reviewShot(resolveLlmConfig(useAppStore.getState()), shot, seq);
      const store = useAppStore.getState();
      store.setReviewFindings(projectKey, mergeFindings(store.reviewFindings[projectKey] ?? [], found));
    } catch (e) {
      setError(errText(e));
      // A failure often means the user stopped sharing — drop the stream so the next try re-prompts.
      stopCapture(streamRef.current);
      streamRef.current = null;
    } finally {
      setBusy(false);
    }
  }, [projectKey, busy]);

  const setStatus = useCallback((id: string, status: ReviewFinding["status"]) => {
    if (!projectKey) return;
    const store = useAppStore.getState();
    store.setReviewFindings(projectKey, setFindingStatus(store.reviewFindings[projectKey] ?? [], id, status));
  }, [projectKey]);

  const dispatch = useCallback(async () => {
    if (!projectKey) return;
    const store = useAppStore.getState();
    const confirmed = confirmedFindings(store.reviewFindings[projectKey] ?? []);
    if (confirmed.length === 0) return;
    // #app-stops-pushing-prompts — this used to type the confirmed findings into the project's
    // director. The app pushes nothing now, so dispatch only MARKS them routed; a director picks them
    // up when it reads the review state. The maintainer accepted that these findings have no store the
    // director can poll today, so until they get one this is a local status change, not a delivery.
    setError(null);
    let next = store.reviewFindings[projectKey] ?? [];
    for (const f of confirmed) next = setFindingStatus(next, f.id, "routed");
    store.setReviewFindings(projectKey, next);
  }, [projectKey]);

  return {
    findings,
    pending: pendingFindings(findings),
    confirmed: confirmedFindings(findings),
    routed: routedFindings(findings),
    canCapture: screenCaptureAvailable(),
    busy,
    error,
    captureAndReview,
    confirm: useCallback((id: string) => setStatus(id, "confirmed"), [setStatus]),
    dismiss: useCallback((id: string) => setStatus(id, "dismissed"), [setStatus]),
    dispatch,
  };
}

// usePreviewStateCycle (#3555) — gently auto-cycle a SMALL preview through the states a component actually
// supports (loading → loaded → error; empty is skipped, see `previewCycleStates`). The cycling is the only
// React here; the "which states" decision is the pure `previewCycleStates`. The preview's own build
// opacity-dip reads as a soft crossfade between states, so no animation is needed here.
import { useEffect, useState } from "react";
import type { ComponentRecord } from "@/features/designs/lib/model";
import { previewCycleStates, type PreviewState } from "@/features/designs/lib/componentPreview";

/** Milliseconds each state holds before the cycle advances — calm, not flickery. */
export const PREVIEW_CYCLE_MS = 2800;

/**
 * The data-state a small preview should render right now, auto-advancing through the component's cyclable
 * states on a timer. A component with a single cyclable state (just `loaded`) never advances. Cycling
 * pauses while `paused` (e.g. the pointer is over the preview) so it holds still to be inspected, and
 * resets to the first state when the selected component changes.
 */
export function usePreviewStateCycle(comp: ComponentRecord, paused: boolean): PreviewState {
  const states = previewCycleStates(comp);
  // `comp.id` in the key restarts the cycle on a component switch even when two components share a state set.
  const cycleKey = `${comp.id}|${states.join(",")}`;
  const [st, setSt] = useState({ key: cycleKey, idx: 0 });
  // Reset to the first state when the component / its cyclable set changes — React's guarded
  // adjust-state-during-render pattern (NOT a setState-in-effect), so the cycle restarts cleanly.
  const idx = st.key === cycleKey ? st.idx : 0;
  if (st.key !== cycleKey) setSt({ key: cycleKey, idx: 0 });
  useEffect(() => {
    if (paused || states.length < 2) return undefined;
    const t = setInterval(() => setSt((s) => ({ key: s.key, idx: (s.idx + 1) % states.length })), PREVIEW_CYCLE_MS);
    return () => clearInterval(t);
  }, [cycleKey, paused, states.length]);
  return states[idx % states.length] ?? "loaded";
}

// useProjectComplete (#2623) — whether a project's BUILD has finished, for the fleet-drill's preview node.
// Polls the project's plan.db issues and derives `projectComplete` (every planned issue complete/verified).
// A null/empty key is never complete. The Glance workspace passes the DRILLED project so the ▷ preview node
// appears exactly when there's a finished app to render.
import { useState } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import { bscJsonShared } from "@/shared/lib/core/bscShared";
import { projectComplete } from "@/shared/lib/fleet/streamCompletion";
import type { PlanIssue } from "@/features/planner/issues/planIssues";

const POLL_MS = 20000;

export function useProjectComplete(projectKey: string | null): boolean {
  const [complete, setComplete] = useState(false);
  usePoll(async (isCancelled) => {
    if (!projectKey) { setComplete(false); return; }
    const issues = await bscJsonShared<PlanIssue[]>(projectKey, ["plan", "list", "--full", "--json"], [], POLL_MS);
    if (isCancelled()) return;
    setComplete(projectComplete(issues));
  }, POLL_MS, [projectKey]);
  return complete;
}

// useProjectFleet (#…) — load a project's fleet plan straight from ITS plan.db. The `bsc` bridge scopes
// $BSC_PLAN_DB by the project key, so this reads the SAME `bsc plan fleet get --full --json` blob the
// planner poll reads — but for ANY project, not just the active one the store's `planFleet` mirrors. That
// is what makes the Glance drill show a project's REAL fleet instead of the sample. Returns null while
// loading and when a project has no planned fleet. Parsed via the shared `parseFleetFile`.
import { useEffect, useState } from "react";
import { bscJson } from "@/shared/lib/core/bsc";
import { parseFleetFile, type FleetPlan } from "@/features/planner/fleet/planFleet";

export function useProjectFleet(projectKey: string | null): FleetPlan | null {
  // Store the loaded fleet WITH the key it's for, so a cleared/changed drill just returns null (no
  // stale fleet, no synchronous setState-in-effect reset).
  const [loaded, setLoaded] = useState<{ key: string; fleet: FleetPlan | null }>({ key: "", fleet: null });
  useEffect(() => {
    if (!projectKey) return;
    let cancelled = false;
    bscJson<unknown | null>(projectKey, ["plan", "fleet", "get", "--full", "--json"], null)
      .then((raw) => { if (!cancelled) setLoaded({ key: projectKey, fleet: raw ? parseFleetFile(JSON.stringify(raw)) : null }); })
      .catch(() => { if (!cancelled) setLoaded({ key: projectKey, fleet: null }); });
    return () => { cancelled = true; };
  }, [projectKey]);
  return projectKey && loaded.key === projectKey ? loaded.fleet : null;
}

// Every local project's issue completion (#4052) — the OPEN-ISSUES half of the L0 `modifying` health
// state.
//
// ONE SPAWN FOR ALL PROJECTS. `bsc project progress --json` walks the hubs and counts each plan.db
// inside a single process; the alternative — `bsc plan list` per project — is the N-per-pane fan-out
// shape that has cost this app whole seconds before (#3908 / #3912 / #3944 / #3954). With ~29 hubs
// locally that is 29 process spawns per poll versus one, which is the difference between a background
// read and a visible stall.
//
// Distinct from `useStreamProgress`, which reads ONE drilled project's issues and partitions them per
// STREAM for the L1 progress bars. This one is per PROJECT and spans all of them — different scope,
// different question, and it must keep working when nothing is drilled at all.
import { useEffect, useMemo, useState } from "react";
import { bscJson } from "@/shared/lib/core/bsc";
import { usePoll } from "@/shared/hooks/usePoll";

/** One project's issue counts, as the CLI reports them. */
export interface ProjectProgressRow {
  key: string;
  done: number;
  total: number;
}

/** Issue counts move at human speed — a worker closing one is a minutes-scale event — and this drives a
 *  colour, not a number on screen. A fast poll would spend a spawn to re-read an unchanged answer. */
export const PROJECT_PROGRESS_POLL_MS = 30_000;

/**
 * Project keys with at least one issue NOT yet done.
 *
 * A project the CLI omits (no plan.db, or a plan store with no issues table) is simply absent from the
 * set — never assumed to have open work. Guessing the busy state from a missing read would light up
 * every unplanned hub on the board, and a wrong signal here is worse than none: the whole point of the
 * state is that it means something.
 *
 * The read failing likewise keeps the LAST GOOD answer rather than clearing, so a transient spawn
 * failure doesn't make every project blink out of `modifying` and back.
 */
export function useProjectProgress(enabled = true): ReadonlySet<string> {
  return useProjectProgressRows(enabled).openKeys;
}

/** The same ONE read, exposing the COUNTS as well (#4118) — the L0 project nodes draw a `done/total`
 *  bar from them, where before this hook's only consumer was the `modifying` colour and the numbers
 *  were thrown away. Still one spawn for every project. */
export function useProjectProgressRows(enabled = true): {
  openKeys: ReadonlySet<string>;
  byKey: ReadonlyMap<string, { done: number; total: number }>;
} {
  const [rows, setRows] = useState<ProjectProgressRow[]>([]);

  // Stop accumulating when Glance is not mounted/enabled — and drop what we had, so a re-enable
  // re-reads rather than rendering a possibly-stale board.
  useEffect(() => {
    if (!enabled) setRows([]);
  }, [enabled]);

  usePoll(async (isCancelled) => {
    if (!enabled) return;
    const next = await bscJson<ProjectProgressRow[] | null>(null, ["project", "progress", "--json"], null);
    if (isCancelled() || !Array.isArray(next)) return;   // read failed ⇒ keep the last good answer
    setRows(next);
  }, PROJECT_PROGRESS_POLL_MS, [enabled]);

  return useMemo(
    () => ({
      openKeys: openIssueKeys(rows),
      // Only rows with real work: a `total` of 0 means "no data" as much as "nothing planned", and the
      // node treats an absent entry and a 0/0 entry identically (no bar) — so omitting them keeps the
      // map honest about what it actually knows.
      byKey: new Map(rows.filter((r) => r.total > 0).map((r) => [r.key, { done: r.done, total: r.total }])),
    }),
    [rows],
  );
}

/** The set of keys with unfinished work: `done < total`. `total === 0` is NOT open work — a planned
 *  project with zero issues has nothing in flight, and counting it would make the state meaningless for
 *  every hub that was scaffolded and abandoned. Pure + exported for direct unit testing. */
export function openIssueKeys(rows: readonly ProjectProgressRow[]): ReadonlySet<string> {
  const out = new Set<string>();
  for (const r of rows ?? []) {
    if (r && typeof r.key === "string" && r.total > 0 && r.done < r.total) out.add(r.key);
  }
  return out;
}

import { useEffect } from "react";
import { useAppStore } from "@/store";
import { scanProjectRepos, scanPlanStages } from "@/features/planner/list/projectScan";
import { canonicalTopicKey } from "@/features/planner/stages/planTopics";

/**
 * Refreshes the active project's linked repositories and plan whenever the
 * Projects tab is opened or the active project changes.
 *
 * Previously the full repo set was only derived when the board view mounted,
 * and the plan only when the planner ran — so opening a project elsewhere left
 * the stale ≤N repos from the projects-list query and an out-of-date plan. This
 * hook runs the resolution up front: repos are re-derived from project items
 * (the reliable source) and plan sections are re-read from disk. Both degrade
 * silently on error so an offline/empty state never clobbers existing data.
 *
 * Mount this once on the always-mounted Projects screen; the effect keys off
 * `activeWorkspace` + `activeProjectId`, so it fires on tab open and project switch
 * but is inert while other screens are showing.
 */
export function useProjectScan(): void {
  const activeWorkspace    = useAppStore(s => s.activeWorkspace);
  const activeProjectId = useAppStore(s => s.activeProjectId);

  useEffect(() => {
    if (activeWorkspace !== "projects" || !activeProjectId) return;
    let cancelled = false;

    // Clear the previously-open project's repos BEFORE scanning this one. `activeProjectRepos` is a
    // single global value that was never reset on switch — so one project's repos leaked into the
    // next project's auto-clone, cloning foreign repos into the wrong project dir (#…). The scan
    // below repopulates THIS project's repos; an empty result now correctly leaves it empty.
    useAppStore.getState().setActiveProjectRepos([]);

    void (async () => {
      // Read the rest from getState so a token/title change doesn't re-trigger
      // the scan — only a tab open or project switch should.
      const { githubToken, activeProjectName, setActiveProjectRepos, setPlanStage } =
        useAppStore.getState();

      // Repos — only overwrite when the scan found some, so a project with no
      // issues yet keeps whatever the projects-list query provided.
      if (githubToken) {
        try {
          const repos = await scanProjectRepos(githubToken, activeProjectId);
          if (!cancelled && repos.length > 0) setActiveProjectRepos(repos);
        } catch { /* offline / API error — keep existing repos */ }
      }

      // Plan — write only changed sections, mirroring the planner's poll. Keyed
      // by the project title, which is the planner's frozen session key.
      if (activeProjectName) {
        try {
          const sections = await scanPlanStages(activeProjectName);
          if (cancelled) return;
          const saved = useAppStore.getState().planStages[activeProjectName] ?? {};
          for (const [rawKey, content] of Object.entries(sections)) {
            // Canonicalize the file stem (e.g. a leftover "Tech stack.md" → "stack"), mirroring
            // the planner poll (Planning.tsx) — otherwise a title-named file is ingested as a
            // non-canonical section that blocks the Context gate (#803).
            const key = canonicalTopicKey(rawKey);
            if (content && content !== (saved[key] ?? "")) {
              setPlanStage(activeProjectName, key, content);
            }
          }
          // Collapse any pre-existing stale non-canonical keys already in the store (#803).
          useAppStore.getState().canonicalizePlanStages(activeProjectName);
        } catch { /* plans dir may not exist yet */ }
      }
    })();

    return () => { cancelled = true; };
  }, [activeWorkspace, activeProjectId]);
}

import { useState, useEffect } from "react";
import { useAppStore } from "@/store";
import { githubGraphql } from "@/shared/lib/github/github";
import { PROJECTS_SUMMARY_QUERY } from "@/features/planner/list/projectsSummaryQueries";
import type { GhProject } from "@/features/planner/list/projectsSummaryDerive";

// ── Data hook ─────────────────────────────────────────────────────────────────

/**
 * The Portfolio overview data — the GitHub Projects-v2 list via GraphQL, one round-trip.
 *
 * The per-repo issue/milestone fetches, the user-events feed, and the burndown iteration query were
 * dropped (#3675): they fed a project-detail flow that no longer exists, and cost 4+ slow REST
 * round-trips on every mount. The Portfolio now shows just the project data this one query provides.
 */
export function useProjectsSummaryData() {
  const { githubToken, githubUser } = useAppStore();
  const [loading, setLoading] = useState(false);
  const [projects, setProjects] = useState<GhProject[]>([]);

  useEffect(() => {
    if (!githubToken || !githubUser) return;
    setLoading(true);
    githubGraphql<{ viewer: { projectsV2: { nodes: GhProject[] } } }>(PROJECTS_SUMMARY_QUERY, null)
      .then(d => setProjects(d?.viewer?.projectsV2?.nodes ?? []))
      .catch(() => setProjects([]))
      .finally(() => setLoading(false));
  }, [githubToken, githubUser?.login]); // eslint-disable-line react-hooks/exhaustive-deps

  return { loading, projects };
}

// useRailSections (#2797) — the open/closed state for a left rail's collapsible sections, keyed by a
// stable section id. Sections default OPEN (the common case); toggling a key flips it. Shared so every
// graph rail (Algorithms, Teams, …) manages its sections identically. Pairs with `RailSection`.
import { useState } from "react";

export interface RailSections {
  /** Whether the section `key` is expanded (defaults to `defaultOpen`). */
  isOpen: (key: string) => boolean;
  /** Flip the section `key`. */
  toggle: (key: string) => void;
}

/** Collapsible-section open state for a rail. `defaultOpen` (default true) is the state before any
 *  toggle. See {@link RailSections}. */
export function useRailSections(defaultOpen = true): RailSections {
  const [open, setOpen] = useState<Record<string, boolean>>({});
  return {
    isOpen: (key) => open[key] ?? defaultOpen,
    toggle: (key) => setOpen((o) => ({ ...o, [key]: !(o[key] ?? defaultOpen) })),
  };
}

// Fetch orchestration for the live Repo Pulse page (#413). Pulls the GitHub data
// the Pulse panels need through the ETag-cached backend (lib/github), then runs
// the pure mappers in lib/repoPulseLive to assemble a view model. Side-effectful;
// the mapping logic it calls is unit-tested separately.
//
// Cheap+exact panels (velocity, CI, review latency, branches) use list endpoints.
// Diff-derived panels (lines/day, churn-by-area, hottest files, contributor
// ±lines) need per-commit detail calls — capped to the most recent N commits.
import { useState, useEffect } from "react";
import { githubRequest, isGithubAuthError } from "@/shared/lib/github/github";
import type { GithubRepo } from "@/store";
import {
  mapVelocity, mapChurnAreas, mapHottestFiles, mapContributors, mapCI,
  mapReviewLatency, mapBranches, deriveKpis,
  type GhCommitItem, type GhCommitDetail, type GhPull, type GhBranchItem,
  type GhWorkflowItem, type GhRun, type GhCompare, type CiHealth, type PulseKpis,
} from "@/shared/lib/github/repoPulseLive";
import type {
  VelocitySlice, ChurnArea, ChurnFile, Contributor, Workflow, Branch,
} from "@/shared/data/repoPulse";

/** How many recent commits to fetch full diffs for (the diff-derived panels). */
const DETAIL_CAP = 40;
/** How many branches to run a compare (ahead/behind) call for. */
const COMPARE_CAP = 8;
const WINDOW_DAYS = 14;

export interface RepoPulseLive {
  repo: { name: string; branch: string; desc: string; lang: string; pushedMin: number };
  velocity: VelocitySlice;
  churnAreas: ChurnArea[];
  hottestFiles: ChurnFile[];
  contributors: Contributor[];
  ci: CiHealth;
  workflows: Workflow[];
  branches: Branch[];
  reviewBuckets: Array<{ label: string; v: number }>;
  kpis: PulseKpis;
  /** True while diff-derived panels reflect only the most recent DETAIL_CAP commits. */
  partialDiffs: boolean;
}

export interface UseRepoPulse {
  data: RepoPulseLive | null;
  loading: boolean;
  error: string | null;
}

function minutesSince(iso: string): number {
  return Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 60000));
}

export function useRepoPulse(repo: GithubRepo | null): UseRepoPulse {
  const [data, setData] = useState<RepoPulseLive | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const slug = repo?.full_name ?? "";

  useEffect(() => {
    if (!repo || !slug) { setData(null); setError(null); return; }
    let cancelled = false;
    setLoading(true);
    setError(null);

    (async () => {
      try {
        const since = new Date(Date.now() - WINDOW_DAYS * 86_400_000).toISOString();
        const get = <T,>(path: string, fallback: T): Promise<T> =>
          githubRequest<T>(path).catch((e) => { if (isGithubAuthError(e)) throw e; return fallback; });

        const [commits, pulls, branches, wfResp, runResp] = await Promise.all([
          get<GhCommitItem[]>(`repos/${slug}/commits?per_page=100&since=${since}`, []),
          get<GhPull[]>(`repos/${slug}/pulls?state=all&per_page=100&sort=created&direction=desc`, []),
          get<GhBranchItem[]>(`repos/${slug}/branches?per_page=100`, []),
          get<{ workflows: GhWorkflowItem[] }>(`repos/${slug}/actions/workflows`, { workflows: [] }),
          get<{ workflow_runs: GhRun[] }>(`repos/${slug}/actions/runs?per_page=100`, { workflow_runs: [] }),
        ]);
        if (cancelled) return;

        // Per-commit diffs for the most recent N commits (bounded, cached).
        const detailShas = commits.slice(0, DETAIL_CAP).map(c => c.sha);
        const details = (await Promise.all(
          detailShas.map(sha => get<GhCommitDetail | null>(`repos/${slug}/commits/${sha}`, null)),
        )).filter((d): d is GhCommitDetail => !!d);
        if (cancelled) return;

        // ahead/behind for the default branch vs a capped set of other branches.
        const defaultBranch = repo.default_branch;
        const compareTargets = branches
          .filter(b => b.name !== defaultBranch)
          .slice(0, COMPARE_CAP);
        const compareResults = await Promise.all(
          compareTargets.map(b =>
            get<GhCompare>(`repos/${slug}/compare/${defaultBranch}...${b.name}`, { ahead_by: 0, behind_by: 0 })
              .then(r => [b.name, r] as const)),
        );
        if (cancelled) return;
        const compares = Object.fromEntries(compareResults);

        const now = new Date();
        const velocity = mapVelocity(commits, pulls, details, WINDOW_DAYS, now);
        const { ci, workflows } = mapCI(runResp.workflow_runs, wfResp.workflows);
        const contributors = mapContributors(commits, details);

        const live: RepoPulseLive = {
          repo: {
            name: repo.full_name,
            branch: defaultBranch,
            desc: repo.description ?? "",
            lang: repo.language ? repo.language.toLowerCase() : "—",
            pushedMin: minutesSince(repo.pushed_at),
          },
          velocity,
          churnAreas: mapChurnAreas(details),
          hottestFiles: mapHottestFiles(details),
          contributors,
          ci,
          workflows,
          branches: mapBranches(branches, pulls, compares, defaultBranch),
          reviewBuckets: mapReviewLatency(pulls),
          kpis: deriveKpis(velocity, ci, pulls, contributors, now),
          partialDiffs: commits.length > DETAIL_CAP,
        };
        if (!cancelled) { setData(live); setLoading(false); }
      } catch (e) {
        if (cancelled) return;
        setError(isGithubAuthError(e) ? "GitHub authorization failed — reconnect in Settings." : "Couldn't load repo data from GitHub.");
        setLoading(false);
      }
    })();

    return () => { cancelled = true; };
  }, [repo, slug]);

  return { data, loading, error };
}

// Shared OS-sandbox readiness + one-click install (#1916 / #1982 / #1988). Probes whether the Bash
// sandbox can engage on this host and drives its install (`provision_sandbox`), which streams
// `sandbox-install` progress events so callers can show live progress. On completion it re-probes so
// `sandbox.ready` reflects the result. Used by BOTH the Settings posture card and the first-run setup
// banner, so the detect + install logic lives in one place.
import { useCallback, useEffect, useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { listen } from "@tauri-apps/api/event";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";

/** Mirror of the Rust `SandboxReadiness` (#1982) — the OS-sandbox probe result. */
export interface SandboxReadiness {
  platform: string;
  needsWsl: boolean;
  wslInstalled: boolean;
  sandboxDistro: string | null;
  /** The app can install the missing piece itself (Linux package manager / WSL rootfs import). */
  autoInstallable: boolean;
  ready: boolean;
  detail: string;
  /** Which agent runtimes the imported sealed distro carries (#4260); null when it isn't imported. */
  agentSandboxRuntimes: SandboxRuntimes | null;
  /**
   * Set when the imported distro is missing runtimes it needs to host the fleet — a distro built
   * before #4260 has the sidecars but no `claude` (the DEFAULT harness) and no `gh`. Reported
   * separately from `ready`, which is about whether the Bash sandbox can engage at all: the two
   * are different axes and folding them would make "not ready" ambiguous.
   */
  agentSandboxGap: string | null;
}

/** Mirror of the Rust `SandboxRuntimes` (#4260) — what the sealed distro can actually run. */
export interface SandboxRuntimes {
  claude: boolean;
  bscAgent: boolean;
  gh: boolean;
  git: boolean;
}

export interface UseSandboxReadiness {
  sandbox: SandboxReadiness | null;
  installing: boolean;
  installLog: string[];
  installMsg: string | null;
  /** Run the one-click install (`provision_sandbox`), streaming progress, then re-probe. */
  install: () => Promise<void>;
}

/**
 * @param enabled — when `false`, skip the readiness probe entirely (the caller won't render the
 *   sandbox UI). Lets a posture-gated card avoid the `wsl_sandbox_status` probe in the allow-list
 *   posture, so it isn't paid on every mount of a page that hosts the card.
 */
export function useSandboxReadiness(enabled = true): UseSandboxReadiness {
  const [sandbox, setSandbox] = useState<SandboxReadiness | null>(null);
  const [installing, setInstalling] = useState(false);
  const [installLog, setInstallLog] = useState<string[]>([]);
  const [installMsg, setInstallMsg] = useState<string | null>(null);

  const probe = useCallback(async () => {
    setSandbox(await safeInvoke<SandboxReadiness | null>("wsl_sandbox_status", undefined, null));
  }, []);

  useEffect(() => {
    if (!enabled) return;
    let alive = true;
    void safeInvoke<SandboxReadiness | null>("wsl_sandbox_status", undefined, null).then((r) => {
      if (alive) setSandbox(r);
    });
    return () => {
      alive = false;
    };
  }, [enabled]);

  // Raw `invoke` (not safeInvoke) so the final Ok/Err text surfaces; `sandbox-install` events stream the
  // package manager / rootfs-import output live into `installLog`.
  const install = useCallback(async () => {
    setInstalling(true);
    setInstallMsg(null);
    setInstallLog([]);
    const unlisten = await listen<{ phase: string; line?: string }>("sandbox-install", (e) => {
      const { phase, line } = e.payload;
      if ((phase === "start" || phase === "log") && line) setInstallLog((prev) => [...prev, line]);
    });
    try {
      setInstallMsg(await invoke<string>("provision_sandbox"));
    } catch (e) {
      setInstallMsg(String(e));
    }
    unlisten();
    await probe();
    setInstalling(false);
  }, [probe]);

  return { sandbox, installing, installLog, installMsg, install };
}

import { useCallback, useEffect } from "react";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { usePoll } from "@/shared/hooks/usePoll";
import { dueAutomations } from "@/features/automations/lib/scheduler";
import { dispatchAutomation } from "@/features/automations/lib/dispatch";

/** How often the scheduler checks for due automations. */
const TICK_MS = 20_000;

/**
 * The Automations runtime (#142): a frontend tick that fires due, armed
 * automations and dispatches them into their target console pane via pty_write,
 * recording each run. Mounted once at the app root, so it runs regardless of the
 * active screen — but only while the app is open (which is also the only time
 * the target panes exist). Each fire reschedules itself (recordAutomationRun
 * recomputes nextRunAt), so a single tick fires a due automation exactly once.
 *
 * The per-automation dispatch is shared with the mobile "run now" path (#937) via
 * {@link dispatchAutomation}.
 */
export function useScheduler() {
  const tick = useCallback(async (isCancelled: () => boolean) => {
    const s = useAppStore.getState();
    const deps = {
      tabs: s.tabs,
      disabledPanes: s.disabledPanes,
      write: (paneId: string, data: string) => invoke<void>("pty_write", { paneId, data }),
      recordRun: s.recordAutomationRun,
      now: () => Date.now(),
    };
    for (const a of dueAutomations(s.automations, Date.now())) {
      if (isCancelled()) return;
      await dispatchAutomation(a, deps);
    }
  }, []);

  // A beat after mount (so the store has hydrated): the first tick. usePoll runs the rest on the
  // fixed interval (immediate:false — the grace tick covers mount, so the first interval tick is at TICK_MS).
  useEffect(() => {
    let cancelled = false;
    const initial = setTimeout(() => void tick(() => cancelled), 1000);
    return () => { cancelled = true; clearTimeout(initial); };
  }, [tick]);

  usePoll(tick, TICK_MS, [], { immediate: false });
}

// useScreenSession (#2707) — the shared xterm.js + PTY lifecycle behind the app's dedicated,
// app-owned terminal sessions. Its remaining user is the PLANNER (`usePlannerTerminal`): the debug
// session (#3326) and the designer/librarian/architect studios (#3357) were migrated onto the shared
// TerminalHost, precisely because a single-mount xterm CANNOT be re-parented into the Glance morph.
// The hooks it was extracted from were near-verbatim copies of the same skeleton:
//   • mount — create the `Terminal` (the shared theme/font/scrollback literal) + `FitAddon`, wire
//     `onData → pty_write`, then in a `requestAnimationFrame`: fit, subscribe `pty_data_<id>` /
//     `pty_exit_<id>` BEFORE spawning the PTY (so no early output is missed), and run the caller's
//     divergent launch path (workspace resolve → `ensure_session_settings` → `pty_create`).
//   • re-fit — re-measure when the surface becomes visible (hidden → shown), after a short delay, and
//     once the mono font loads (cell metrics are wrong until then).
//   • cleanup — unlisten×2, disconnect the ResizeObserver, dispose the term, null the refs, and
//     `pty_kill` the session.
// The LAUNCH path itself is deliberately NOT shared — the planner and designer differ in their
// workspace command, role gate, MCP/sandbox wiring, and env — so it stays a `launch` callback each
// wrapper owns, keeping every invoke/pty_create arg byte-identical to the pre-extraction hooks.
//
// TERM_THEME is passed IN as a param (never imported here): pulling the planner's theme leaf into
// `shared/` would invert the dependency direction (shared must stay feature-agnostic, #1626).
import { useEffect, useRef, type RefObject, type MutableRefObject } from "react";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";
import { Terminal, type ITheme } from "@xterm/xterm";
import { FitAddon } from "@xterm/addon-fit";
import { attachTerminalClipboard } from "@/shared/lib/session/terminalClipboard";

export interface ScreenSessionConfig<S = void> {
  /** Stable pane id — the pty_* event channel + write/resize/kill key. */
  paneId: string;
  /** xterm theme (passed in so `shared/` never imports a feature's theme leaf). */
  termTheme: ITheme;
  /** Whether the surface is on-screen — drives the re-fit effect. */
  visible: boolean;
  /** Text written to the terminal on `pty_exit` (include the leading/trailing CRLF + ANSI reset). */
  exitBanner: string;
  /** Called with each raw `pty_data` payload AFTER it is written to the term (e.g. tag parsing). */
  onData?: (payload: string) => void;
  /** Runs SYNCHRONOUSLY in the mount effect body (before the RAF), so callers can snapshot store /
   *  prop state at exactly mount time. Its return value is handed to `launch`. */
  snapshot?: () => S;
  /** Owns the divergent launch path — workspace resolve → session settings → `pty_create` (+ any
   *  post-launch registration). Runs inside the mount RAF, AFTER `pty_data`/`pty_exit` are
   *  subscribed. `term` gives `cols`/`rows`; `snap` is the `snapshot()` return. */
  launch: (term: Terminal, snap: S) => Promise<void>;
  /** Runs in cleanup, just before `pty_kill` (e.g. deregister a tunnel roster). */
  onUnmount?: () => void;
}

export interface ScreenSessionHandle {
  /** Host element for the xterm canvas — attach to the terminal container div. */
  containerRef: RefObject<HTMLDivElement | null>;
  /** The live xterm instance (null before mount / after unmount). */
  termRef: MutableRefObject<Terminal | null>;
}

export function useScreenSession<S = void>(config: ScreenSessionConfig<S>): ScreenSessionHandle {
  const { paneId, termTheme, visible, exitBanner } = config;

  const containerRef = useRef<HTMLDivElement>(null);
  const termRef      = useRef<Terminal | null>(null);
  const fitRef       = useRef<FitAddon | null>(null);
  const unlistenData = useRef<UnlistenFn | null>(null);
  const unlistenExit = useRef<UnlistenFn | null>(null);

  // Mount xterm.js and spawn the PTY (once per surface lifecycle). pty_kill runs only in this
  // cleanup so tearing the session down is tied to the surface unmounting.
  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const term = new Terminal({
      theme: termTheme,
      fontFamily: '"JetBrains Mono", monospace',
      fontSize: 12,
      lineHeight: 1.4,
      cursorBlink: true,
      cursorStyle: "bar",
      scrollback: 10000,
    });

    const fitAddon = new FitAddon();
    term.loadAddon(fitAddon);
    term.open(el);
    termRef.current = term;
    fitRef.current  = fitAddon;
    const disposeClipboard = attachTerminalClipboard(term, paneId); // copy-on-select + paste (#3157)

    term.onData((data) => {
      fireInvoke("pty_write", { paneId, data }, console.error);
    });

    // Snapshot mount-time state synchronously (before the RAF), so callers capture the same instant
    // the pre-extraction hooks did.
    const snap = (config.snapshot?.() as S);

    requestAnimationFrame(async () => {
      // Only fit when the host has real dimensions. Fitting a 0-size host — a KeptMountedPage surface
      // mounted before layout, or a collapsed/zero-height dock — sets the terminal to 0 rows, and the
      // first `pty_data` write to a 0-row terminal dereferences a non-existent buffer line and crashes
      // xterm ("Cannot set properties of undefined (setting 'isWrapped')"), taking the page down via the
      // ErrorBoundary (#2832). A fresh xterm defaults to 80×24, so skipping the fit keeps a valid buffer;
      // the ResizeObserver below fits it once the host is actually sized (e.g. when KeptMountedPage flips
      // it to display:flex). Same guard the ResizeObserver already applies.
      if (el.clientWidth > 0 && el.clientHeight > 0) fitAddon.fit();

      // Subscribe before creating the PTY so we never miss early output.
      unlistenData.current = await listen<string>(`pty_data_${paneId}`, (ev) => {
        term.write(ev.payload);
        config.onData?.(ev.payload);
      });
      unlistenExit.current = await listen<unknown>(`pty_exit_${paneId}`, () => {
        term.write(exitBanner);
      });

      // The divergent launch path (workspace → settings → pty_create) is owned by the caller.
      await config.launch(term, snap);
    });

    // DEBOUNCED refit (#2832): a resize DRAG fires the observer dozens of times per second. Calling
    // `fit()` — which resizes the terminal and REFLOWS its buffer — on every frame while the PTY is
    // streaming output races xterm's async write loop and corrupts the buffer, throwing
    // "Cannot set properties of undefined (setting 'isWrapped')" from a later write (an UNCAUGHT error
    // that takes the page down). Coalescing to a single fit ~90ms after the drag settles reflows once,
    // off the streaming path. A hidden (display:none) host is 0-size → skipped.
    let resizeTimer: ReturnType<typeof setTimeout> | undefined;
    const ro = new ResizeObserver(() => {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(() => {
        const t = termRef.current;
        if (!t || el.clientWidth === 0 || el.clientHeight === 0) return;
        fitAddon.fit();
        fireInvoke("pty_resize", { paneId, cols: t.cols, rows: t.rows }, console.error);
        t.refresh?.(0, t.rows - 1); // repaint the buffer cleanly at the settled size (#2837)
      }, 90);
    });
    ro.observe(el);

    // The dock's ENTRANCE GROW (#2905, `useDockEntrance`) animates the panel's REAL height up into place,
    // so the ResizeObserver above fires as it grows and its debounced fit lands the authoritative size
    // once the grow settles — no separate post-animation "settle fit" needed (that was the transform-only
    // slide's workaround, #2837, now removed).

    return () => {
      clearTimeout(resizeTimer);
      unlistenData.current?.();
      unlistenExit.current?.();
      ro.disconnect();
      disposeClipboard();
      term.dispose();
      termRef.current = null;
      fitRef.current  = null;
      config.onUnmount?.();
      fireInvoke("pty_kill", { paneId }, console.error);
    };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Re-fit when the surface becomes visible (hidden → shown): the collapsed host is display:none, so
  // the mount-time fit measured nothing. Re-fit on the frame, after a short delay, and once the mono
  // font loads (cell metrics are wrong until then) so it reliably fills the available space.
  useEffect(() => {
    if (!visible) return;
    const refit = (focusToo: boolean) => {
      const fit = fitRef.current, term = termRef.current, el = containerRef.current;
      if (!fit || !term || !el || el.clientWidth === 0 || el.clientHeight === 0) return;
      fit.fit();
      fireInvoke("pty_resize", { paneId, cols: term.cols, rows: term.rows }, console.error);
      term.refresh?.(0, term.rows - 1); // repaint cleanly at the shown size (#2837)
      if (focusToo) term.focus();
    };
    let cancelled = false;
    const raf = requestAnimationFrame(() => refit(true));
    const delayed = setTimeout(() => refit(false), 120);
    document.fonts?.ready?.then(() => { if (!cancelled) refit(false); }).catch(() => {});
    return () => { cancelled = true; cancelAnimationFrame(raf); clearTimeout(delayed); };
  }, [visible]); // eslint-disable-line react-hooks/exhaustive-deps

  return { containerRef, termRef };
}

// usePageSelection — the Pages-tier internal selection hook (#2505): the controlled/uncontrolled
// selection idiom the Layouts tier established (Tree/Sequence — controlled when the `selectedId`
// prop is PRESENT, may be null = none; else internal state seeded by `defaultSelectedId`), extracted
// once so the five selecting pages don't re-implement it.
import { useState } from "react";

export interface PageSelection {
  /** The live selected id — the prop when controlled, internal state otherwise. */
  selected: string | null;
  /** Select an id: updates internal state when uncontrolled; always notifies `onSelect`. */
  select: (id: string) => void;
}

export function usePageSelection(
  selectedId: string | null | undefined,
  defaultSelectedId: string | undefined,
  onSelect?: (id: string) => void,
): PageSelection {
  const [inner, setInner] = useState<string | null>(defaultSelectedId ?? null);
  const controlled = selectedId !== undefined;
  const selected = controlled ? selectedId : inner;
  const select = (id: string) => {
    if (!controlled) setInner(id);
    onSelect?.(id);
  };
  return { selected, select };
}

// useSetupSignature (#1775, extracted from Planning.tsx) — the "context updated · refresh" badge
// signal (#175/#756). `currentSig` is the live signature of the inputs (computed in Rust so its
// format can't drift from the baseline); `lastSetupSig` is the baseline setup_workspaces last wrote.
// When they diverge (a repo linked / blueprint changed mid-session, or the planner template bumped)
// `contextStale` is true. `refreshSetupSig` re-reads the baseline — call after every workspace setup.
import { useState, useEffect, useCallback } from "react";
import { invoke } from "@tauri-apps/api/core";

export function useSetupSignature(
  effectiveProjectId: string,
  linkedRepos: string[],
  stageIdsFor: (key: string) => string[],
): { currentSig: string | null; lastSetupSig: string | null; refreshSetupSig: () => void; contextStale: boolean } {
  const [currentSig, setCurrentSig] = useState<string | null>(null);
  const [lastSetupSig, setLastSetupSig] = useState<string | null>(null);
  useEffect(() => {
    let live = true;
    invoke<string>("compute_context_signature", {
      repoFullNames: linkedRepos,
      enabledStages: stageIdsFor(effectiveProjectId),
    }).then(sig => { if (live) setCurrentSig(sig); }).catch(() => { if (live) setCurrentSig(null); });
    return () => { live = false; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [linkedRepos, effectiveProjectId]);
  // Re-read the baseline the backend last wrote — called on open and after every workspace setup
  // (mount / link / restart), so the badge reflects the most recent regeneration.
  const refreshSetupSig = useCallback(() => {
    invoke<string>("get_context_signature", { projectKey: effectiveProjectId })
      .then(s => setLastSetupSig(s || null)).catch(() => {});
  }, [effectiveProjectId]);
  useEffect(() => { refreshSetupSig(); }, [refreshSetupSig]);
  const contextStale = !!currentSig && !!lastSetupSig && currentSig !== lastSetupSig;
  return { currentSig, lastSetupSig, refreshSetupSig, contextStale };
}

// useSoundKits (#3080) — the Sounds tab's kit source, seed-first: renders the packaged built-ins
// immediately, then hydrates from the durable `bsc-sound` store and seeds any built-in the store is
// missing (first run). Mirrors the Algorithms knowledge-graph hydration (`useKnowledgeGraph`, #2856):
// a hook, not a store slice, since the library is read-mostly here (authoring lands in Phase 4).
import { useEffect, useState } from "react";
import type { SoundKit } from "@/features/sounds/lib/soundDescriptor";
import { BUILTIN_KITS, mergeKits } from "@/features/sounds/lib/soundKits";
import { loadKits, pushKit } from "@/features/sounds/lib/soundBridge";

export function useSoundKits(): SoundKit[] {
  const [kits, setKits] = useState<SoundKit[]>(BUILTIN_KITS);
  useEffect(() => {
    let cancelled = false;
    void loadKits().then((rows) => {
      const { kits: merged, toSeed } = mergeKits(rows);
      // Push any built-in the store doesn't have yet, so `bsc sound get <id>` works from a session too.
      toSeed.forEach((k) => { void pushKit(k).catch(() => {}); });
      if (!cancelled && merged.length) setKits(merged);
    });
    return () => { cancelled = true; };
  }, []);
  return kits;
}

// useStoreProjector (#2498) — the generic mobile projector, mounted ONCE in App beside
// useTunnelSync. Subscribes to each scoped store_state domain's sources (the SAME data the
// desktop pages read — see the #2496 inventory) and pushes the pure projections
// (lib/storeProjections.ts) through the shared domain publisher, which debounces per domain,
// dedups unchanged payloads, and stamps monotonic revs. Everything no-ops while the relay is
// down. The `plan` domain is the one exception published elsewhere: the stage/gate board only
// exists inside the live planner (usePlannerTunnelSync), so the planner pushes it.
//
// Alerts: this hook also drives the app-wide alert pipeline — coord-log alerts (agent-paused /
// worker-question / fleet-failed / fleet-landed) from the polled CoordState, and prompt-waiting
// from the focus queue's awaiting set. The planner contributes gate-ready + planner-waiting
// from its own transitions. All converge on the alert hub (inbox domain + FCM push).

import { useEffect, useMemo, useRef, useState } from "react";
import { useAppStore } from "@/store";
import { usePoll } from "@/shared/hooks/usePoll";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { paneIdFor } from "@/app/console/lib/paneIdentity";
import { useGlanceProjects, useGlanceFaults, useProjectFleet } from "@/features/glance";
import { resolveKitLibraryRefs } from "@/features/designs";
import { loadPendingLessons } from "@/features/skills";
import { resolveAllInstalledMcp } from "@/features/mcp";
import { deriveConsoles, buildAuditRows, APP_ROLES } from "@/features/security";
import type { Lesson } from "@/features/skills/lib/lessons";
import {
  buildGlancePayload, buildOrgPayload, buildBlueprintsPayload, buildSkillsPayload,
  buildComponentsPayload, buildThemesPayload, buildAutomationsPayload, buildMcpPayload,
  buildSecurityPayload,
} from "@/features/tunnel/lib/storeProjections";
import { publishTunnelDomain, resetTunnelDomains } from "@/features/tunnel/lib/tunnelDomains";
import { recordTunnelAlerts, seedTunnelAlerts } from "@/features/tunnel/lib/alertHub";
import { coordAlerts, promptAlerts, type AwaitingPane } from "@/features/tunnel/lib/alerts";

const LESSONS_POLL_MS = 15_000;
const COORD_POLL_MS = 2_000;
// The audit log is a CLI read (no store slice); poll it modestly for the mobile mirror — the
// desktop Agents page polls faster (3s) but only while its Activity tab is open (#2530).
const AUDIT_POLL_MS = 15_000;

export function useStoreProjector(): void {
  const tunnelRunning = useAppStore((s) => s.tunnelRunning);

  // A relay (re)start forgets the last-sent cache so the fresh Rust-side store repopulates
  // even when the frontend store hasn't changed since the previous run.
  const wasRunning = useRef(false);
  useEffect(() => {
    if (tunnelRunning && !wasRunning.current) resetTunnelDomains();
    wasRunning.current = tunnelRunning;
  }, [tunnelRunning]);

  // Personas: read once, shared by the glance payload (stream-role resolution, #2530) + the org payload.
  const personas = useAppStore((s) => s.personas);

  // Components/kits/kit-usage: read once — shared by the glance kit + library BANDS (#3743) and the
  // `components` domain below. `libraryRefs` is the cross-graph algorithm/sound roll-up (#3133), the same
  // `resolveKitLibraryRefs(components)` the Glance workspace feeds `buildGlanceData`.
  const components = useAppStore((s) => s.components);
  const kits = useAppStore((s) => s.kits);
  const kitUsage = useAppStore((s) => s.kitUsage);
  const libraryRefs = useMemo(() => resolveKitLibraryRefs(components), [components]);

  // ── glance — projects + links + faults + drill + PER-PROJECT fleets + stream roles (#2530) ──
  const projects = useGlanceProjects(tunnelRunning);
  const faults = useGlanceFaults(tunnelRunning ? projects.map((p) => p.id) : []);
  const links = useAppStore((s) => s.projectLinks);
  const drill = useAppStore((s) => s.glanceDrill);
  const planFleet = useAppStore((s) => s.planFleet);
  // The active project's fleet is already mirrored in the store; any other drilled project's is
  // loaded from its own plan.db — the same preference the Glance workspace applies. Ship EVERY loaded
  // fleet keyed by project (not just the drilled one) so any project node drills on mobile (#2530),
  // merging the on-demand drilled fleet in when the store doesn't already hold it.
  const drillFleetLoaded = useProjectFleet(tunnelRunning ? drill : null);
  const fleets = useMemo(
    () => (drill && drillFleetLoaded && !planFleet[drill] ? { ...planFleet, [drill]: drillFleetLoaded } : planFleet),
    [planFleet, drill, drillFleetLoaded],
  );
  useEffect(() => {
    if (!tunnelRunning) return;
    // #3743: carry the kit + library bands (kitUsage/kits/libraryRefs) so mobile rebuilds the FULL cockpit.
    publishTunnelDomain(
      "glance",
      buildGlancePayload({ projects, links, faults, drill, fleets, personas, kitUsage, kits, libraryRefs }),
    );
  }, [tunnelRunning, projects, links, faults, drill, fleets, personas, kitUsage, kits, libraryRefs]);

  // ── org — the org library + pared persona refs ────────────────────────────────
  const teams = useAppStore((s) => s.teams);
  useEffect(() => {
    if (!tunnelRunning) return;
    // Wire domain + payload field stay "org"/`orgs` (mobile tunnel contract, #2700); only the store read renamed.
    publishTunnelDomain("org", buildOrgPayload({ orgs: teams, personas }));
  }, [tunnelRunning, teams, personas]);

  // ── blueprints — library cards + the active blueprint's team graph ────────────
  const blueprints = useAppStore((s) => s.blueprints);
  const activeBlueprintId = useAppStore((s) => s.activeBlueprintId);
  useEffect(() => {
    if (!tunnelRunning) return;
    publishTunnelDomain("blueprints", buildBlueprintsPayload({ blueprints, activeBlueprintId }));
  }, [tunnelRunning, blueprints, activeBlueprintId]);

  // ── skills — library + groups + the active project's pending lessons ──────────
  const skills = useAppStore((s) => s.skills);
  const skillGroups = useAppStore((s) => s.skillGroups);
  const activeKey = useAppStore((s) => s.planningSessionKey || s.activeProjectId || "");
  const [lessons, setLessons] = useState<{ project: string; pending: Lesson[] } | null>(null);
  usePoll(async (isCancelled) => {
    if (!tunnelRunning || !activeKey) {
      setLessons(null); // React bails out when already null
      return;
    }
    const pending = await loadPendingLessons(activeKey);
    if (isCancelled()) return;
    setLessons({ project: activeKey, pending });
  }, LESSONS_POLL_MS, [tunnelRunning, activeKey]);
  useEffect(() => {
    if (!tunnelRunning) return;
    publishTunnelDomain("skills", buildSkillsPayload({ skills, groups: skillGroups, lessons }));
  }, [tunnelRunning, skills, skillGroups, lessons]);

  // ── components + themes — kits/components summaries · the theme registry ──────
  // (components/kits/kitUsage are read once above — shared with the glance bands, #3743.)
  useEffect(() => {
    if (!tunnelRunning) return;
    publishTunnelDomain("components", buildComponentsPayload({ kits, components, usage: kitUsage }));
  }, [tunnelRunning, kits, components, kitUsage]);

  const kitThemes = useAppStore((s) => s.kitThemes);
  const kitTheme = useAppStore((s) => s.kitTheme);
  useEffect(() => {
    if (!tunnelRunning) return;
    publishTunnelDomain("themes", buildThemesPayload({ themes: kitThemes, active: kitTheme }));
  }, [tunnelRunning, kitThemes, kitTheme]);

  // ── automations + mcp ──────────────────────────────────────────────────────────
  const automations = useAppStore((s) => s.automations);
  const hooks = useAppStore((s) => s.hooks);
  useEffect(() => {
    if (!tunnelRunning) return;
    publishTunnelDomain("automations", buildAutomationsPayload({ automations, hooks }));
  }, [tunnelRunning, automations, hooks]);

  const mcpServers = useAppStore((s) => s.mcpServers);
  useEffect(() => {
    if (!tunnelRunning) return;
    const installedIds = resolveAllInstalledMcp(mcpServers).map((s) => s.id);
    publishTunnelDomain("mcp", buildMcpPayload({ servers: mcpServers, installedIds }));
  }, [tunnelRunning, mcpServers]);

  // ── security — application roles + assignable profiles + console model + per-pane assignments +
  // recent audit (#2530 / #3754) ──
  // Profiles + assignments are live store slices; the console model is derived from the workspace tabs
  // (the SAME deriveConsoles the desktop Security page uses), and the audit log is a CLI read (no store
  // slice), polled like lessons/coord. The audit `decision` + pane→console name are computed HERE via
  // buildAuditRows (the desktop's one source of truth) so mobile never re-derives a security verdict.
  const agentProfiles = useAppStore((s) => s.agentProfiles);
  const paneRoles = useAppStore((s) => s.paneRoles);
  const paneProfiles = useAppStore((s) => s.paneProfiles);
  const tabs = useAppStore((s) => s.tabs);
  const paneNames = useAppStore((s) => s.paneNames);
  const disabledPanes = useAppStore((s) => s.disabledPanes);
  const activeRepoName = useAppStore((s) => s.activeRepoName);
  const secConsoles = useMemo(
    () => deriveConsoles({ tabs, paneNames, disabledPanes, paneProfiles, activeRepoName }),
    [tabs, paneNames, disabledPanes, paneProfiles, activeRepoName],
  );
  const [auditLines, setAuditLines] = useState<string[]>([]);
  usePoll(async (isCancelled) => {
    if (!tunnelRunning) { setAuditLines([]); return; } // React bails when already []
    const lines = await logsTail("audit", 300);
    if (isCancelled()) return;
    setAuditLines(lines);
  }, AUDIT_POLL_MS, [tunnelRunning]);
  const auditRows = useMemo(
    () => buildAuditRows(auditLines, { consoles: secConsoles, profiles: agentProfiles, paneProfiles, paneRoles }),
    [auditLines, secConsoles, agentProfiles, paneProfiles, paneRoles],
  );
  useEffect(() => {
    if (!tunnelRunning) return;
    publishTunnelDomain("security", buildSecurityPayload({
      appRoles: APP_ROLES, profiles: agentProfiles, consoles: secConsoles, paneRoles, paneProfiles, auditRows,
    }));
  }, [tunnelRunning, agentProfiles, secConsoles, paneRoles, paneProfiles, auditRows]);

  // ── alerts — coord-log events + the focus queue's awaiting set ────────────────
  // Coord entries carry their own `at`, so re-derivation is idempotent (the hub dedups by id).
  // The FIRST successful read after the relay starts SEEDS the inbox without pushing — the
  // historical log fills the mobile inbox but never fires a burst of stale FCM notifications.
  const coordSeeded = useRef(false);
  useEffect(() => {
    if (!tunnelRunning) coordSeeded.current = false;
  }, [tunnelRunning]);
  usePoll(async (isCancelled) => {
    if (!tunnelRunning) return;
    const res = await readCoordState(1000);
    if (isCancelled() || !res) return;
    const candidates = coordAlerts(res.state);
    if (coordSeeded.current) {
      recordTunnelAlerts(candidates);
    } else {
      coordSeeded.current = true;
      seedTunnelAlerts(candidates);
    }
  }, COORD_POLL_MS, [tunnelRunning]);

  // Prompt-waiting is a transition (no durable log): diff the awaiting set against the previous
  // tick; a pane that resolves and awaits again re-alerts. (`tabs`/`paneNames` are read once above
  // for the security console model.)
  const focusQueue = useAppStore((s) => s.focusQueue);
  const prevAwaiting = useRef<AwaitingPane[]>([]);
  useEffect(() => {
    if (!tunnelRunning) {
      prevAwaiting.current = [];
      return;
    }
    const awaiting: AwaitingPane[] = focusQueue.map((q) => ({
      paneId: paneIdFor(tabs[q.tab], q.tab, q.pane),
      name: paneNames[q.tab]?.[q.pane] ?? `console-${q.tab + 1}-${q.pane + 1}`,
    }));
    recordTunnelAlerts(promptAlerts(prevAwaiting.current, awaiting, Date.now()));
    prevAwaiting.current = awaiting;
  }, [tunnelRunning, focusQueue, tabs, paneNames]);
}

// The drilled project's per-stream issue progress (#4050).
//
// ONE read per project on a slow cadence, partitioned in memory — never one read per node. That
// fan-out shape has cost real time in this app before (#3908 / #3912 / #3944 / #3954), and a graph of
// twenty workers would make twenty spawns of the same query.
//
// Scoped to the DRILLED project because that is the only fleet whose nodes are on screen: the cost is
// bounded by what the user is actually looking at, and it stops entirely when they leave the drill.
//
// It cannot piggyback on `useWorkerAutoEnd`'s read of the same data — that one is event-gated on panes
// that just went idle, so it says nothing while a fleet is steadily working, which is exactly when a
// progress bar is worth having.
import { useEffect, useState } from "react";
import { bscJsonShared } from "@/shared/lib/core/bscShared";
import { usePoll } from "@/shared/hooks/usePoll";
import type { OwnedIssue } from "@/shared/lib/fleet/workerEnd";
import { streamProgress, planDbDoneRefs, planDbClosedByRef, projectProgress, type StreamProgress } from "@/features/glance/lib/streamProgress";
import { knownRefAliases } from "@/features/glance/lib/fleetPlanProgress";

/** Issue counts move at human speed — a worker closing one is a minutes-scale event, so a fast poll
 *  would spend spawns to re-read an unchanged answer. */
export const PROGRESS_POLL_MS = 20_000;

/** What one poll of plan.db yields. #4102 added `doneRefs`: the same read now also feeds the
 *  ref-based progress path, which needs to know WHICH issues are finished rather than just how many —
 *  so plan.db statuses and the GitHub overlay can be unioned into one done-set. One read, two shapes;
 *  a second hook over the same query would be the fan-out this file's header warns about. */
export interface PlanDbProgress {
  byStream: Map<string, StreamProgress>;
  /** Refs of issues plan.db considers finished (`complete` | `verified`). */
  doneRefs: Set<string>;
  /** Per-ref closed-ness — `true` finished, `false` known-unfinished, ABSENT when plan.db has no such
   *  row. The Plan dock renders per-issue state from this, so a project that never uses GitHub still
   *  shows real states instead of "state unknown" on every row. */
  closedByRef: Map<string, boolean>;
  /** Every ref plan.db can be asked about, in each spelling it answers to (`knownRefAliases`).
   *
   *  `glance-progress-ref-namespace-split`: a fleet stream's `issues` are a SEPARATE ownership record
   *  and may be written in another namespace entirely — on `studio-code` they are bare GitHub numbers
   *  while plan.db is all slugs, so nothing matched and every owning node showed `0/N`. This is what
   *  lets the ref path tell "owned and unfinished" apart from "owned and unknowable", and stand aside
   *  for plan.db in the second case. */
  knownRefs: Set<string>;
  /** The project's progress across EVERY issue, stream-owned or not — the same `complete | verified`
   *  over the same rows that `bsc project progress` counts for the L0 project node.
   *
   *  `glance-progress-ref-namespace-split`: L0 and L1 disagreed (24 vs 56 on `studio-code`) because they
   *  counted different ownership records and neither said so. This gives the DIRECTOR — the one node
   *  accountable for the whole board rather than a lane — the same number L0 shows, from the same read,
   *  so the two levels agree by construction instead of by coincidence. */
  overall: StreamProgress;
}

const EMPTY: PlanDbProgress = {
  byStream: new Map(), doneRefs: new Set(), closedByRef: new Map(), knownRefs: new Set(),
  overall: { done: 0, total: 0 },
};

/** Per-stream `done / total` for `projectKey` plus its done refs, or empty when not drilled / no plan
 *  store. */
export function useStreamProgress(projectKey: string | null): PlanDbProgress {
  const [state, setState] = useState<PlanDbProgress>(EMPTY);

  // Clear on a project switch so the previous fleet's numbers never render against this one's nodes.
  useEffect(() => { setState(EMPTY); }, [projectKey]);

  usePoll(async (isCancelled) => {
    if (!projectKey) return;
    const issues = await bscJsonShared<OwnedIssue[] | null>(projectKey, ["plan", "list", "--full", "--json"], null, PROGRESS_POLL_MS);
    if (isCancelled() || !issues) return;   // read failed / no plan.db ⇒ keep the last good answer
    setState({
      byStream: streamProgress(issues),
      doneRefs: planDbDoneRefs(issues),
      closedByRef: planDbClosedByRef(issues),
      knownRefs: knownRefAliases(issues),
      overall: projectProgress(issues),
    });
  }, PROGRESS_POLL_MS, [projectKey]);

  return state;
}

// The studio-network pump (#2940): drives the app-owned studio-session network so a `bsc-commission`
// emitted by one session (the planner, or the designer) is fulfilled by another (designer/librarian)
// and the authored artifact id is delivered back — all while the user stays in the planning surface.
//
// Two actuations, both re-derived from the FULL coord log every tick (restart-safe), guarded so each
// message injects exactly once:
//   1. AUTHOR TASK  — an open commission's spec → the TARGET studio pane, once the target has been
//      reachable for the settle window (the lazy-mount host has had time to launch the session; Claude
//      queues input typed mid-boot). Pure decision: studioNetworkDrive.authorInjections.
//   2. DELIVER-BACK — a `deliver`-stamped commission's artifact id → the REQUESTER's pane (a live
//      session). Pure decision: studioNetworkDrive.deliverBackInjections.
//
// REACHABILITY is on-demand: the pump publishes `activeStudioTargets` (targets with open commissions)
// to the store; ConsoleWorkspace's <StudioNetworkHosts> lazy-mounts each target's terminal (launching
// the session) and unmounts it when the list empties (ending the session). No idle studio sessions.
//
// Mounted once in ConsoleWorkspace (stays mounted across screens). Pure logic lives in
// studioNetworkDrive.ts; this is the thin Tauri/React actuator, like useDirectorPump.
//
// INERT since #app-stops-pushing-prompts. Its entire body was a poll that injected studio commissions and deliver-backs — and it also LAZY-MOUNTED a commission target, which is the app launching a session, forbidden twice over.
//
// The export SURVIVES deliberately: this module is registered in graphPlatform/appModules so graph
// RECORDS can import it, and removing the export breaks record compilation at runtime. Inert-but-
// exported is the shape useFleetGate took for the same reason when its launch pump was killed —
// deleting the hook is not the fix, doing nothing is.

/** Does nothing. See the note above. */
export function useStudioNetworkPump(): void {
  // Intentionally empty: no poll, no evaluation, no injection.
}

// useStudioPageShowing (#3357) — is a studio's own page actually ON SCREEN right now?
//
// The studio pages are KEPT MOUNTED (`KeptMountedPage`): once visited they stay in the tree and are only
// CSS-hidden when the user switches away. So "my dock component is mounted" is NOT "the user is looking at
// this studio" — if the viewer ref-count keyed off mounting, it would stay ≥1 forever after the first visit
// and the idle reaper could never fire. This derives the real answer from the shell's page state.
import { useAppStore } from "@/store";
import { detachedSection } from "@/app/console/lib/detachWindow";
import { STUDIO_SESSIONS, type StudioId } from "@/features/studio-sessions/lib/studioSessions";

/** Pure rule: which page is showing, given the shell state and (for a tear-off) this window's identity. */
export function studioPageShowing(
  id: StudioId | null | undefined,
  s: { activeWorkspace: string; projectsPageMode: string },
  detached: { page: string; section: string } | null,
): boolean {
  // Null-tolerant for the same reason `useStudioViewer` is (#system-sessions-are-per-technology): a
  // per-technology dock resolves its session from the page's current selection, and a technology with
  // no session yields null. The rules of hooks require the call to be unconditional, so the NULL has to
  // be absorbed here rather than at the call site.
  //
  // UNRECOGNISED-tolerant too, which is a DIFFERENT case and the one that actually bit
  // (#a-stale-studio-id-in-a-record-must-not-kill-a-page). Callers include components compiled from
  // component RECORDS, whose source is data the type system never checked — so `id` can be a
  // non-null string naming a studio that no longer exists. `STUDIO_SESSIONS[retired]` is `undefined`,
  // and reading `.sectionId` off it threw all the way out to `GraphErrorBoundary`, which fell the
  // WHOLE page back: one stale id in one dock took down Algorithms entirely.
  //
  // A record is untrusted input by construction — the loader error-boundaries a render throw for
  // exactly that reason — so a helper it calls degrades instead of throwing. The dock shows nothing;
  // the page renders.
  const def = id ? STUDIO_SESSIONS[id] : undefined;
  if (!def) return false;
  // A torn-off section window renders exactly ONE page and has no rail — it is showing iff it IS this page.
  if (detached) return detached.page === def.pageKey && detached.section === def.sectionId;
  return s.activeWorkspace === "projects" && s.projectsPageMode === def.sectionId;
}

export function useStudioPageShowing(id: StudioId | null | undefined): boolean {
  const activeWorkspace = useAppStore((st) => st.activeWorkspace);
  const projectsPageMode = useAppStore((st) => st.projectsPageMode);
  return studioPageShowing(id, { activeWorkspace, projectsPageMode }, detachedSection());
}

// useStudioReaper (#3357) — the idle reaper for the app-owned studio sessions.
//
// A studio session deliberately OUTLIVES the surface that opened it: leaving the Design Studio page keeps
// the designer warm on TerminalHost so the Glance node can still morph into it. Something has to reclaim
// it eventually, or every studio ever opened runs a Claude process until the app quits.
//
// The rule: while a studio is wanted but NO surface is showing it (viewer count 0), a 30-minute timer runs.
// On expiry the session is killed and the studio leaves the wanted list, so its persistent mount unmounts
// with it. Anything that shows it again before expiry cancels the timer, and because the pane id is stable
// a later re-open resumes the same conversation (`claude --continue`) either way.
//
// NOTE: dropping the last TerminalHost claim is NOT itself a teardown — `TerminalView`'s cleanup keeps the
// backend PTY alive on purpose (a console tab-switch must reconnect, not respawn). So the reaper issues the
// `pty_kill` explicitly; the unmount only reclaims the xterm.
//
// ONE exception, checked at expiry rather than at arm time: if Claude is actively running in the session
// (`paneClaudeActive`), killing it would cut off work in flight. The reaper then RE-ARMS on a short recheck
// instead of reaping, so a busy session is deferred (indefinitely, while it stays busy) and reclaimed as
// soon as it goes quiet.
import { useEffect, useRef } from "react";
import { useAppStore } from "@/store";
import { fireInvoke } from "@/shared/lib/core/safeInvoke";
// The reaping policy is ONE user-facing setting (Settings → Planner → "Reap idle background sessions"),
// so the studio threshold lives alongside the console pane thresholds in `ReaperConfig` rather than in a
// second config the user would have to find separately. Pure leaf import, like `detachWindow` above.
import { DEFAULT_STUDIO_IDLE_MS, studioIdleMs } from "@/app/console/lib/idleReaper";
import { STUDIO_IDS, STUDIO_SESSIONS, type StudioId } from "@/features/studio-sessions/lib/studioSessions";

/** Default idle grace before an unwatched studio session is reclaimed. The EFFECTIVE value is the
 *  user's `idleReaper.studioIdleMs` setting; this is the packaged default (and the test baseline). */
export const STUDIO_IDLE_MS = DEFAULT_STUDIO_IDLE_MS;
/** Recheck interval while a due-to-be-reaped session still has Claude working in it. */
export const STUDIO_BUSY_RECHECK_MS = 60 * 1000;

export function useStudioReaper(): void {
  const wantedStudios = useAppStore((s) => s.wantedStudios);
  const studioViewers = useAppStore((s) => s.studioViewers);
  // The user's reaping policy (Settings → Planner). `enabled` is the master switch for ALL idle
  // reaping, so turning it off keeps studio sessions warm indefinitely too — one predictable rule.
  const reaperCfg = useAppStore((s) => s.idleReaper);
  const idleMs = studioIdleMs(reaperCfg);
  const enabled = reaperCfg.enabled;
  // studio id → its armed reap timer + the duration it was armed with. A ref (not state) so re-arming
  // never re-renders; the effect below reconciles it against the current wanted/viewer/config state.
  // The duration is tracked so a settings change re-arms rather than silently keeping the old clock.
  const timers = useRef<Map<StudioId, { t: ReturnType<typeof setTimeout>; ms: number; busy?: boolean }>>(new Map());

  useEffect(() => {
    const armed = timers.current;
    for (const id of STUDIO_IDS) {
      const idle = enabled && wantedStudios.includes(id) && (studioViewers[id] ?? 0) === 0;
      const timer = armed.get(id);
      if (!idle) {
        // Watched again, already reaped, or reaping switched off → cancel. This is the
        // "re-opening before expiry" path (and the master-switch-off path).
        if (timer) { clearTimeout(timer.t); armed.delete(id); }
        continue;
      }
      // Already counting down at the CURRENT threshold → leave it alone; an unrelated change (another
      // studio's churn) must not restart this clock. A changed threshold DOES re-arm, so editing the
      // setting takes effect immediately rather than only on the next idle transition. A BUSY deferral
      // is left alone either way: it is on the short recheck loop and re-evaluates itself, so treating
      // its recheck interval as a "changed threshold" would reset a working session to a full idle wait.
      if (timer && (timer.busy || timer.ms === idleMs)) continue;
      if (timer) { clearTimeout(timer.t); armed.delete(id); }

      const fire = () => {
        const st = useAppStore.getState();
        // Re-read at expiry: the arm-time snapshot is as stale as the configured threshold (30 min by
        // default, and the user can set it much longer).
        if (!st.wantedStudios.includes(id) || (st.studioViewers[id] ?? 0) > 0) { armed.delete(id); return; }
        if (!st.idleReaper.enabled) { armed.delete(id); return; } // switched off while counting down
        if (st.paneClaudeActive[STUDIO_SESSIONS[id].paneId]) {
          // Busy → defer, never cut off a turn. Re-armed at the RECHECK interval, so `ms` records that
          // (a settings change during a deferral re-arms it at the new threshold on the next reconcile).
          armed.set(id, { t: setTimeout(fire, STUDIO_BUSY_RECHECK_MS), ms: STUDIO_BUSY_RECHECK_MS, busy: true });
          return;
        }
        armed.delete(id);
        // Kill the PTY EXPLICITLY. Dropping the last TerminalHost claim only unmounts the <TerminalView>
        // (its cleanup deliberately leaves the backend session alive so a console tab-switch reconnects
        // rather than respawns) — so without this the xterm would go away while the `claude` process kept
        // running forever. Killing first, then dropping the mount, means the reclaim is complete.
        fireInvoke("pty_kill", { paneId: STUDIO_SESSIONS[id].paneId }, console.error);
        st.closeStudio(id);
      };
      armed.set(id, { t: setTimeout(fire, idleMs), ms: idleMs });
    }
  }, [wantedStudios, studioViewers, idleMs, enabled]);

  // Drop every pending timer when the host unmounts (app teardown / a test cleanup).
  useEffect(() => {
    const armed = timers.current;
    return () => { for (const { t } of armed.values()) clearTimeout(t); armed.clear(); };
  }, []);
}

// useStudioViewer (#3357) — the ONE way a surface says "I am showing this studio session".
//
// Both surfaces that can show a studio terminal call it: the studio page's `SessionDock` and the Glance
// node morph. On the first call the studio becomes WANTED (the lazy start — nothing launches at app boot),
// and for as long as the caller is showing it the studio's viewer count is held above zero, which keeps the
// idle reaper disarmed. When the last viewer goes away the reaper arms; the session stays warm on
// TerminalHost throughout, so re-opening inside the window reattaches to the SAME conversation.
import { useEffect } from "react";
import { useAppStore } from "@/store";
import type { StudioId } from "@/features/studio-sessions/lib/studioSessions";

/**
 * Register this component as a viewer of `id`'s studio session while `showing` is true.
 *
 * @param id      the studio, or null when this surface currently shows no studio (the hook then no-ops,
 *                so a caller with a conditional target — the Glance morph — can still call it
 *                unconditionally, as the rules of hooks require).
 * @param showing whether the surface is ACTUALLY on screen. A page dock stays MOUNTED but CSS-hidden when
 *                the user switches pages (`KeptMountedPage`), and a mounted-but-hidden dock must not pin
 *                the session alive forever — otherwise the reaper could never fire after a first visit.
 */
export function useStudioViewer(id: StudioId | null | undefined, showing = true): void {
  useEffect(() => {
    if (!id || !showing) return;
    const st = useAppStore.getState();
    // Showing it is what STARTS it: opening a studio page (or its Glance node) is the lazy launch.
    st.openStudio(id);
    st.addStudioViewer(id);
    return () => { useAppStore.getState().removeStudioViewer(id); };
  }, [id, showing]);
}

/**
 * The MANY form of {@link useStudioViewer} — register this surface as a viewer of every studio in `ids`.
 *
 * Needed since #3361, where several node morphs can be open at once: the single-id hook cannot be called
 * in a loop (a variable hook count breaks the rules of hooks), and calling it once with only the
 * most-recently-opened id would leave every other open studio unpinned — so the reaper could kill a
 * session the user is looking at in another morph.
 *
 * Keyed on the joined id list, so opening a second studio re-runs the effect: the cleanup decrements the
 * already-open studios and the body immediately re-increments them. That transient dip to 0 is harmless —
 * the reaper only ARMS a timer at 0 and re-checks the live count when it fires (tens of minutes later),
 * by which point the count is back up.
 */
export function useStudioViewers(ids: readonly StudioId[], showing = true): void {
  const key = ids.join(",");
  useEffect(() => {
    if (!showing || !key) return;
    const list = key.split(",") as StudioId[];
    const st = useAppStore.getState();
    for (const id of list) { st.openStudio(id); st.addStudioViewer(id); }
    return () => {
      const s = useAppStore.getState();
      for (const id of list) s.removeStudioViewer(id);
    };
  }, [key, showing]);
}

// useSystemSessionBridge (#architect-starts-and-stops-system-sessions) — apply a `bsc session
// start|stop` request to the store and ACK it.
//
// THE ROUND TRIP
//   bsc session start → request file → Rust watcher → `bsc://session-lifecycle` → HERE → store
//                     → `system_session_ack`
//
// A thin adapter: the DECISION lives in `systemSessionBridge.ts`, unit-testable without Tauri. Same
// shape as `useFleetWakeBridge`, deliberately — one more emit-and-ack verb on the one channel, not a
// second mechanism.
//
// THIS IS NOT AN INJECTION PATH. Nothing here writes text into a session: `openStudio` mounts a
// studio the user could have opened by clicking, and the started session keeps its own role gate.
// `injectCallers.test.ts` asserts `injectPrompt` has no callers, and this must never become one.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { log } from "@/shared/lib/core/log";
import { applyLifecycle, type LifecycleRequest, type LifecycleAck } from "@/app/systemSessionBridge";

/**
 * Listen for `bsc://session-lifecycle` and apply it. Mounted once by the shell.
 */
export function useSystemSessionBridge(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<LifecycleRequest>("bsc://session-lifecycle", async (e) => {
      const req = e.payload;
      let ack: LifecycleAck;
      try {
        // Read off a LIVE getState, not a captured snapshot: zustand hands out a new object per
        // update, so a stale closure could decide against an older `wantedStudios`.
        const st = useAppStore.getState();
        ack = await applyLifecycle(req, {
          wantedStudios: st.wantedStudios,
          openStudio: (id) => useAppStore.getState().openStudio(id),
          closeStudio: (id) => useAppStore.getState().closeStudio(id),
          setPendingDirective: (id, d) => useAppStore.getState().setStudioPendingDirective(id, d),
          // Killing is explicit, exactly as the idle reaper does it: dropping the host claim only
          // unmounts the <TerminalView> — its cleanup deliberately leaves the backend session alive
          // so a console tab-switch reconnects rather than respawns.
          killPane: async (p) => { await safeInvoke("pty_kill", { paneId: p }, undefined); },
        });
      } catch (err) {
        // A throw here would strand the Rust waiter until its timeout. State it instead.
        ack = {
          id: req.id,
          error: `session lifecycle threw: ${err instanceof Error ? err.message : String(err)}`,
        };
        log.error(`session lifecycle ${req.id} threw: ${String(err)}`);
      }
      void invoke("system_session_ack", { ack: { ...ack, id: req.id } }).catch((e2) => {
        // Nothing left to do — the caller will time out. Log it so the cause isn't a mystery.
        log.error(`system_session_ack failed for ${req.id}: ${String(e2)}`);
      });
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}

// Session-readiness state for a terminal pane (#1645). Owns the preflight verdict (#564) that
// TerminalView renders as the SessionFailure / SessionReadinessBanner, the critical/warning splits it
// derives, and the manual retry. The mount-effect launch path sets the verdict via `setReadinessVerdict`
// after its own preflight probe (which runs with the resolved GH token); this hook owns the same probe
// for the user-triggered retry. Kept here (not in lib/) because it carries React state.

import { useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { log } from "@/shared/lib/core/log";
import { interpretDiagnostics, sessionVerdictFromReport, type PrereqStatus, type SessionVerdict } from "@/shared/lib/core/diagnostics";
import { tokenForRepo } from "@/shared/lib/github/repoCredentials";
import { useAppStore } from "@/store";

export function useTerminalSession(paneId: string, initialCwd?: string) {
  // Session readiness verdict (#564). Set after the preflight probe runs in the mount effect (after
  // the GH token is resolved so gh-auth uses the right env), or by `retryReadiness` below.
  const [readinessVerdict, setReadinessVerdict] = useState<SessionVerdict | null>(null);

  // Derive critical + warning lists from the verdict for rendering.
  const criticalChecks = readinessVerdict?.failed.filter((c) => c.severity === "critical") ?? [];
  const warningChecks  = readinessVerdict?.failed.filter((c) => c.severity === "warning")  ?? [];

  function retryReadiness() {
    const cwd = initialCwd ?? "";
    // #3984: say so rather than returning silently. A no-op retry is indistinguishable from one that
    // ran and got the same verdict — which is exactly how the button read while the probe was failing
    // to spawn (#3984): it fired 15 times a boot and looked dead every time.
    if (!cwd) {
      log.warn(`console[${paneId}] readiness retry skipped — this pane has no cwd, so there is nothing to probe`);
      return;
    }
    const ghToken = tokenForRepo(
      useAppStore.getState().paneRepos[paneId],
      useAppStore.getState().repoGithubTokens,
      useAppStore.getState().githubToken,
    );
    const env = ghToken ? { GH_TOKEN: ghToken } : null;
    invoke<PrereqStatus[]>("preflight", { cwd, env })
      .then((prereqs) => setReadinessVerdict(sessionVerdictFromReport(interpretDiagnostics(prereqs))))
      .catch((e) => log.error(`console[${paneId}] preflight retry failed: ${e}`));
  }

  return { setReadinessVerdict, criticalChecks, warningChecks, retryReadiness };
}

// The automations tunnel surface (#937): project the automations store to a paired phone
// and accept its arm / disarm / run-now control. Mounted once at the app root.
//
// Outbound — push the list (id/name/schedule/armed/next-run/last-status) whenever it
//   changes; the relay replays the last push on connect.
// Inbound — route the phone's control through the SAME store + scheduler the desktop uses:
//   arm/disarm validates the cron (an invalid one is rejected back to the phone, never
//   silently armed); run-now fires the automation through the shared dispatch. The phone
//   never runs schedules itself — it only asks the desktop to.

import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { dispatchAutomation } from "@/features/automations";
import { automationToFrame, planArm } from "@/features/tunnel/lib/automationControl";
import { tunnelSetAutomations, tunnelAutomationFailed } from "@/features/tunnel/lib/tunnelClient";
import { log } from "@/shared/lib/core/log";

export function useTunnelAutomations(): void {
  const tunnelRunning = useAppStore((s) => s.tunnelRunning);
  const automations = useAppStore((s) => s.automations);

  // Outbound projection — re-push whenever the list changes (no-op until a phone is paired).
  useEffect(() => {
    if (!tunnelRunning) return;
    tunnelSetAutomations(automations.map(automationToFrame))
      .catch((e) => log.error(`tunnel: set_automations failed: ${e}`));
  }, [tunnelRunning, automations]);

  // Inbound control — arm/disarm + run-now from the phone.
  useEffect(() => {
    let cancelled = false;

    const onArm = async (id: string, armed: boolean): Promise<void> => {
      const s = useAppStore.getState();
      const decision = planArm(s.automations.find((a) => a.id === id), id, armed);
      if (!decision.ok) {
        log.warn(`tunnel: rejecting mobile arm of "${id}" — ${decision.error}`);
        // Workspace the rejection back to the phone (also FCM-pushed, A4).
        await tunnelAutomationFailed(decision.id, Date.now(), decision.error, decision.name).catch(() => {});
        return;
      }
      log.info(`tunnel: mobile ${decision.armed ? "armed" : "disarmed"} automation "${decision.id}"`);
      s.setAutomationArmed(decision.id, decision.armed);
    };

    const onRunNow = async (id: string): Promise<void> => {
      const s = useAppStore.getState();
      const a = s.automations.find((x) => x.id === id);
      if (!a) {
        log.warn(`tunnel: run-now for unknown automation "${id}"`);
        return;
      }
      log.info(`tunnel: mobile run-now of automation "${id}"`);
      await dispatchAutomation(a, {
        tabs: s.tabs,
        disabledPanes: s.disabledPanes,
        write: (paneId, data) => invoke<void>("pty_write", { paneId, data }),
        recordRun: s.recordAutomationRun,
        now: () => Date.now(),
      });
    };

    const subs = [
      listen<{ id: string; armed: boolean }>("tunnel://automation-arm", (e) => {
        if (!cancelled) void onArm(e.payload.id, e.payload.armed);
      }),
      listen<{ id: string }>("tunnel://automation-run-now", (e) => {
        if (!cancelled) void onRunNow(e.payload.id);
      }),
    ];
    return () => {
      cancelled = true;
      for (const s of subs) void s.then((off) => off());
    };
  }, []);
}

// Wire the tunnel's inbound coordination control into the desktop wake path (#935).
// src-tauri/src/tunnel.rs decodes a phone's wake/approve frames and re-emits them as
// Tauri events; without a listener they fell on the floor. This hook routes them through
// the SAME actuation the local Coordinator inbox uses, so a paired phone can wake a parked
// worker or approve a paused gate. Mount once at the app root (runs on any screen).

import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { useAppStore } from "@/store";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import { actuateWake, injectWake } from "@/shared/lib/fleet/coordinatorActuate";
import { planMobileResume, type CoordControlKind } from "@/features/tunnel/lib/coordControl";
import { log } from "@/shared/lib/core/log";

export function useTunnelCoordControl(): void {
  useEffect(() => {
    let cancelled = false;

    const handle = async (kind: CoordControlKind, session: string): Promise<void> => {
      const res = await readCoordState(1000);
      if (cancelled || !res) return;
      const { state, ready } = res;
      const plan = planMobileResume(kind, session, state, ready);
      if (!plan) {
        // The phone named a session that isn't parked — ignore rather than wake blindly.
        log.warn(`tunnel: ignoring mobile ${kind} for "${session}" — not a parked session`);
        return;
      }
      log.info(`tunnel: mobile ${kind} → ${plan.via} resume of "${plan.session}"`);
      if (plan.via === "fresh") {
        await actuateWake(plan.session, plan.prompt, useAppStore.getState().wakePane);
      } else {
        await injectWake(plan.session, plan.prompt);
      }
    };

    const subs = [
      listen<{ session: string }>("tunnel://coord-wake", (e) => void handle("wake", e.payload.session)),
      listen<{ session: string }>("tunnel://coord-approve", (e) => void handle("approve", e.payload.session)),
    ];
    return () => {
      cancelled = true;
      for (const s of subs) void s.then((off) => off());
    };
  }, []);
}

// The hook-telemetry tunnel surface (#937): project the desktop's aggregated hook-fire
// analytics to a paired phone. READ-ONLY — mobile displays the counts but never controls
// hooks (there is no inbound frame). Mounted once at the app root.
//
// The same summary the Hook Analytics tab renders (`aggregateHookTelemetry` over the
// `hooks.log` tail from `bsc logs tail hook`) is pushed whenever the tunnel comes up; the
// relay replays the last push on connect so a freshly-paired phone mirrors it immediately.

import { useEffect } from "react";
import { useAppStore } from "@/store";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { parseHookLog, aggregateHookTelemetry } from "@/features/mcp";
import { tunnelSetHookTelemetry, type HookTelemetryFrame } from "@/features/tunnel/lib/tunnelClient";
import { log } from "@/shared/lib/core/log";

// Match the Hook Analytics tab's window so the phone shows the same numbers.
const DAYS = 14;

/** Aggregate the hook-fire log into the read-only wire frame the phone renders. Pure over
 *  its inputs so it's unit-testable without Tauri. */
export function toHookTelemetryFrame(logLines: string[], now: Date): HookTelemetryFrame {
  const an = aggregateHookTelemetry(parseHookLog(logLines.join("\n")), now, DAYS);
  return {
    total: an.total,
    blocks: an.blocks,
    allows: an.allows,
    allowRate: an.allowRate,
    daily: an.daily.map((d) => ({ day: d.day, allows: d.allows, blocks: d.blocks })),
    perHook: an.perHook.map((h) => ({ hook: h.hook, event: h.event, fires: h.fires })),
  };
}

export function useTunnelHookTelemetry(): void {
  const tunnelRunning = useAppStore((s) => s.tunnelRunning);

  // Outbound projection — read + aggregate the hook log and push it whenever the tunnel
  // comes up (no-op until a phone is paired; the relay replays the last push on connect).
  useEffect(() => {
    if (!tunnelRunning) return;
    let cancelled = false;
    logsTail("hook", 8000)
      .then((lines) => {
        if (cancelled) return;
        const frame = toHookTelemetryFrame(lines ?? [], new Date());
        return tunnelSetHookTelemetry(frame);
      })
      .catch((e) => log.error(`tunnel: set_hook_telemetry failed: ${e}`));
    return () => {
      cancelled = true;
    };
  }, [tunnelRunning]);
}

// Always-on tunnel pane-sync (#801). Pushes the relay's pane list + session metadata
// from the store, regardless of which screen is mounted — previously this lived in
// Console.tsx, so the mirror went stale (and excluded the planner) the moment you left
// the Console screen. Mounted once in App. PTY *bytes* are teed in Rust; this is the
// low-volume names/cwds/statuses + every registered extra session (planner/designer,
// via the keyed `tunnelExtraPanes` registry, #2497).
//
// Roster identity (#2497): panes ride under their IDENTITY id (`paneIdFor`, #1176) — the
// same id their PTY/status/cwd are keyed by — with a `kind` derived from the id grammar,
// so fleet workers (`<key>:<stream>`), the director, triage panes, and manual consoles
// are all addressable from mobile.

import { useEffect } from "react";
import { useAppStore } from "@/store";
import { paneIdFor } from "@/app/console/lib/paneIdentity";
import { buildPanePayload } from "@/features/tunnel/lib/tunnel";
import { tunnelSetPanes, tunnelSetSessions } from "@/features/tunnel/lib/tunnelClient";
import { log } from "@/shared/lib/core/log";

export function useTunnelSync(): void {
  const tunnelRunning = useAppStore((s) => s.tunnelRunning);
  const tabs          = useAppStore((s) => s.tabs);
  const paneNames     = useAppStore((s) => s.paneNames);
  const paneCwds      = useAppStore((s) => s.paneCwds);
  const paneStatuses  = useAppStore((s) => s.paneStatus);
  const disabledPanes = useAppStore((s) => s.disabledPanes);
  const focusQueue    = useAppStore((s) => s.focusQueue);
  const extraPanes    = useAppStore((s) => s.tunnelExtraPanes);

  useEffect(() => {
    if (!tunnelRunning) return;
    // The focus queue is positional (tab/pane indices) — resolve each entry to the same
    // identity id the payload keys panes by.
    const awaiting = new Set(focusQueue.map((q) => paneIdFor(tabs[q.tab], q.tab, q.pane)));
    // Flatten the keyed extra-pane registry in stable (sorted-source) order so re-registration
    // by one source never reorders another's panes.
    const extras = Object.keys(extraPanes).sort().flatMap((source) => extraPanes[source]);
    const { panes, sessions } = buildPanePayload({
      tabs, paneNames, paneCwds, paneStatuses, disabledPanes, awaiting,
      nowIso: new Date().toISOString(),
      extraPanes: extras,
    });
    tunnelSetPanes(panes).catch((e) => log.error(`tunnel: set_panes failed: ${e}`));
    tunnelSetSessions(sessions).catch((e) => log.error(`tunnel: set_sessions failed: ${e}`));
  }, [tunnelRunning, tabs, paneNames, paneCwds, paneStatuses, disabledPanes, focusQueue, extraPanes]);
}

// useVisibleRect (#components-graph-culls-offscreen-nodes) — the live world-space rectangle a graph page
// can currently see, for mounting only the nodes inside it.
//
// WHEN IT RECOMPUTES, AND WHY THAT LIST IS SHORT. Panning is IMPERATIVE (#4140): the drag writes the world
// layer's transform straight to the DOM and commits to React state only on mouseup, precisely so a pan does
// not re-render a 459-node graph per mouse event. Culling must not undo that, so this deliberately does NOT
// track the drag — the rect follows `vp.view`, which changes when the view COMMITS (pan end, zoom, fit).
// Everything in between is covered by the margin baked into `visibleWorldRect`.
//
// ONLY THE SIZE IS STATE. The rect is DERIVED during render from `view` + the measured viewport size, and
// the size is the one genuinely external value here — it changes when the window, the rail or the
// inspector is resized, none of which React knows about. Deriving instead of storing the whole rect is
// what keeps a view commit to ONE render: storing it would setState inside an effect on every commit and
// cascade a second render, which is the cost this hook exists to avoid paying.
import { useEffect, useMemo, useState } from "react";
import { visibleWorldRect } from "@/shared/lib/graph/viewportCull";
import type { GraphBox, GraphViewport } from "@/shared/ui/layouts/useGraphViewport";

interface Size { w: number; h: number }

/**
 * The visible world rect for `vp`, or `null` while the viewport is unmeasured — which every consumer must
 * read as "cull nothing" (see `isNodeVisible`).
 *
 * `enabled: false` pins the result at `null` — the honest way for a page to turn culling off (during a
 * screenshot, say, or for a graph small enough that culling is pure overhead) without the caller having to
 * reimplement the render-everything default.
 */
export function useVisibleRect(vp: GraphViewport, enabled = true): GraphBox | null {
  const [size, setSize] = useState<Size | null>(null);
  const { view, vpEl } = vp;

  useEffect(() => {
    const el = vpEl.current;
    // No ResizeObserver (jsdom, an old shell) ⇒ never measured ⇒ culling stays off. Degrading to
    // "render everything" is the correct direction for a missing capability.
    if (!el || typeof ResizeObserver === "undefined") return;
    // observe() fires an initial callback with the current size, so the first measurement arrives
    // through the same path as every later one — no synchronous setState in the effect body, and so no
    // cascading render on mount.
    const ro = new ResizeObserver(() => {
      const next = { w: el.clientWidth, h: el.clientHeight };
      setSize((prev) => (prev && prev.w === next.w && prev.h === next.h ? prev : next));
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, [vpEl]);

  return useMemo(
    () => (enabled && size ? visibleWorldRect(view, size.w, size.h) : null),
    [enabled, size, view],
  );
}

// The visualization hook for an implementation (#3233). Resolving a viz is now ASYNC when the impl carries
// a stored `vizCode` (it is compiled + run in the sandbox Web Worker), so the sync `vizForImpl` became this
// hook: the in-app program (trusted, main-thread) shows IMMEDIATELY, and a stored `vizCode` — when the
// worker returns its frames — REPLACES it. A malformed / timed-out `vizCode` falls back to the program.

import { useEffect, useState } from "react";
import type { AlgoImpl } from "@/features/algorithms/lib/knowledge";
import { programVizForImpl, resolveVizExample, type VizExample } from "@/features/algorithms/viz/examples/registry";

/**
 * The {@link VizExample} to render for `impl`, or `undefined` when it has none.
 *
 * The in-app program is derived synchronously during render, so an algorithm with an in-app viz never
 * flashes empty. A stored `vizCode` resolves asynchronously via the sandbox and, once ready, replaces the
 * program (it is the durable per-algorithm form). The resolved code-viz is kept KEYED by its code string,
 * so switching implementations never shows a previous impl's stored viz. `null` impl → `undefined`.
 */
export function useVizForImpl(impl: Pick<AlgoImpl, "id" | "name" | "vizCode"> | null): VizExample | undefined {
  // The in-app program — synchronous, trusted, stable identity (a singleton per base name).
  const program = impl ? programVizForImpl(impl) : undefined;
  const vizCode = impl?.vizCode?.trim() ?? "";

  // The sandbox-resolved stored viz, tagged with the code it came from (so it's never used for a different
  // impl before its own resolves). Only the async callback sets state — no synchronous setState-in-effect.
  const [resolved, setResolved] = useState<{ code: string; viz: VizExample | undefined }>({ code: "", viz: undefined });

  useEffect(() => {
    if (!vizCode) return;
    let cancelled = false;
    void resolveVizExample(vizCode).then((viz) => {
      if (!cancelled) setResolved({ code: vizCode, viz });
    });
    return () => {
      cancelled = true;
    };
  }, [vizCode]);

  const codeViz = resolved.code === vizCode ? resolved.viz : undefined;
  return codeViz ?? program;
}

// The always-on warden (#1102): periodically checks every live WORKER against its trusted plan
// anchor and, on a trip, HARD-PAUSES it: kills the PTY, marks it quarantined, and fires a mobile
// push so the user is alerted even off the desktop. Two layers:
//   1. Deterministic (every tick, free): out-of-lane edit / gate-denied command → conformance.ts.
//   2. LLM judge (sampled, ~every JUDGE_EVERY ticks, needs an API key): a fuzzy "on-task?" second
//      opinion on ONE worker that catches semantic drift the rules can't see (wardenJudge.ts).
// Both feed the same hard-pause. Asymmetric by design — the watcher reads only structured, trusted
// telemetry (the plan, the git diff, the bsc-audit log), never the worker-ingested prose, so it
// can't itself be steered by an injection. Mount once at the app root so it runs on any screen.

import { useRef } from "react";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { bscJson } from "@/shared/lib/core/bsc";
import { logsTail } from "@/shared/lib/core/logsBridge";
import { useLogStream } from "@/shared/hooks/useLogStream";
import { useAppStore } from "@/store";
import { roleCapability } from "@/shared/lib/session/sessionRoles";
import { resolveLlmConfig, hasLlmKey, type LlmConfig } from "@/shared/lib/core/llmConfig";
import { oneShotComplete } from "@/shared/lib/core/claudeComplete";
import type { WorktreeChanges } from "@/shared/lib/fleet/worktreeChanges";
import { planWarden, parseAuditCommands, zipWorktreeChanges, wardenSweepTargets, livePaneIdsOf, type WardenSession } from "@/shared/lib/fleet/warden";
import { buildJudgePrompt, parseJudgeVerdict, selectForJudging } from "@/shared/lib/fleet/wardenJudge";
import { completedWorkerPanes, doneIssueRefs } from "@/shared/lib/fleet/streamCompletion";
import type { PlanIssue } from "@/features/planner/issues/planIssues";
import { log } from "@/shared/lib/core/log";

// #3643: event-driven now — re-checks when a worker attempts a tool (`tool`/audit, the write signal
// the warden already reads), takes/finishes a turn (`activity`), or self-reports done, instead of
// re-spawning a git diff per worker every 6s. A slow safety-net backstop covers plan-only changes.
const JUDGE_EVERY = 5;  // run the LLM spot-check ~every 5 ticks (~30s), one worker, round-robin

/** Panes mid-quarantine, so a slow kill+push doesn't double-fire across ticks. */
type InFlight = { current: Set<string> };

/** Gather one live worker's trusted activity + anchor, or null if it can't be evaluated.
 *
 *  #3908: PURE of I/O now — the two reads it used to make per pane are hoisted to ONE per sweep by
 *  {@link sweepInputs} and passed in. Both were fan-out waste at fleet scale: `read_worktree_changes`
 *  spawns two git subprocesses (~78 per sweep at 39 panes, stalling the command queue ~11s), and the
 *  audit tail takes no pane argument at all — every worker was re-reading the SAME log, filtered
 *  per-pane only afterwards by `parseAuditCommands`. */
function buildSession(paneId: string, auditLines: string[], changesByPane: Map<string, string[]>): WardenSession | null {
  const st = useAppStore.getState();
  const stream = st.fleetPaneStreams[paneId];
  if (!stream) return null;
  const role = st.paneRoles[paneId] ?? "worker";
  if (role !== "worker") return null; // the warden watches workers — the exposed attack surface
  const cwd = st.paneCwds[paneId];
  if (!cwd) return null;

  const changedFiles = changesByPane.get(paneId) ?? [];
  return {
    paneId,
    anchor: {
      streamId: stream.id,
      ownedGlobs: stream.owns,
      capability: roleCapability(role, { writeGlobs: stream.owns }),
      flow: stream.flow,
    },
    activity: {
      changedFiles: changedFiles ?? [],
      // Ignore audit commands from before this pane's warden floor (set on triage relaunch) so a
      // prior run's denied command doesn't re-quarantine the freshly relaunched worker.
      commands: parseAuditCommands(auditLines ?? [], paneId, st.wardenSince[paneId] ?? 0),
    },
  };
}

/**
 * The reads a whole warden sweep shares, fetched ONCE (#3908) — the fix for the fan-out that stalled
 * the command queue ~11s at 39 panes.
 *
 * `logsTail("audit", …)` takes no pane argument, so one read serves every worker (`parseAuditCommands`
 * does the per-pane filtering). `read_worktree_changes_batch` replaces N git-spawning invokes with one,
 * index-aligned to the cwds we send. Targets mirror `buildSession`'s own guards so the batch never
 * pays for a pane that would be discarded anyway.
 */
async function sweepInputs(paneIds: string[]): Promise<{ auditLines: string[]; changesByPane: Map<string, string[]> }> {
  const st = useAppStore.getState();
  const targets = paneIds.filter((p) => {
    const stream = st.fleetPaneStreams[p];
    return !!stream && (st.paneRoles[p] ?? "worker") === "worker" && !!st.paneCwds[p];
  });
  const cwds = targets.map((p) => st.paneCwds[p] as string);
  const [auditLines, changes] = await Promise.all([
    logsTail("audit", 500),
    cwds.length ? safeInvoke<WorktreeChanges[]>("read_worktree_changes_batch", { cwds }, []) : Promise.resolve<WorktreeChanges[]>([]),
  ]);
  // Index-aligned zip (pure + unit-tested in warden.ts): a short/failed batch degrades each missing
  // pane to "no file signal", exactly as a failed single read did — never another worker's files.
  return { auditLines: auditLines ?? [], changesByPane: zipWorktreeChanges(targets, changes ?? []) };
}

/** Hard-pause a worker: kill the PTY FIRST (a hijacked session can't be trusted to stop itself),
 *  then record the quarantine and fire the mobile push. Per-pane guarded so it fires once. */
async function quarantinePane(paneId: string, streamId: string, summary: string, inFlight: InFlight): Promise<void> {
  if (inFlight.current.has(paneId)) return;
  inFlight.current.add(paneId);
  try {
    await safeInvoke("pty_kill", { paneId }, undefined, (e) => log.error(`warden: pty_kill ${paneId} failed: ${e}`));
    useAppStore.getState().markQuarantine(paneId, { streamId, summary, at: Date.now() });
    // Mobile alert (#1102 slice 2a): a "quarantine" coord event → FCM push to paired phones.
    await safeInvoke("tunnel_emit_coord_event", { kind: "quarantine", session: paneId, refKey: summary, at: Date.now() },
      undefined, (e) => log.error(`warden: quarantine push ${paneId} failed: ${e}`));
    log.warn(`warden: quarantined ${paneId} (${streamId}) — ${summary}`);
  } finally {
    inFlight.current.delete(paneId);
  }
}

/** Escalate one worker to the LLM judge; quarantine it if the judge says it drifted. Fail-open:
 *  any error / unparseable reply leaves the worker running (the deterministic check is the gate). */
async function judgeAndMaybeQuarantine(session: WardenSession, cfg: LlmConfig, inFlight: InFlight): Promise<void> {
  const stream = useAppStore.getState().fleetPaneStreams[session.paneId];
  if (!stream) return;
  const { system, user } = buildJudgePrompt({
    streamId: session.anchor.streamId,
    ownedGlobs: session.anchor.ownedGlobs,
    issues: stream.issues,
    changedFiles: session.activity.changedFiles,
    commands: session.activity.commands,
  });
  const reply = await oneShotComplete(cfg, system, user).catch((e) => {
    log.error(`warden: judge call failed for ${session.paneId}: ${e}`);
    return "";
  });
  if (!reply) return;
  const verdict = parseJudgeVerdict(reply);
  if (verdict.drifted) {
    await quarantinePane(session.paneId, session.anchor.streamId, `LLM judge: ${verdict.reason}`, inFlight);
  }
}

export function useWarden(): void {
  const inFlight = useRef<Set<string>>(new Set());
  const tickCount = useRef(0);     // drives the judge cadence
  const judgeCursor = useRef(0);   // round-robin cursor for sampling
  const judging = useRef(false);   // one judge call in flight at a time

  useLogStream(["tool", "activity", "done"], async (isCancelled) => {
    if (isCancelled()) return;
    const st = useAppStore.getState();
    const panes = Object.keys(st.fleetPaneStreams);
    if (panes.length === 0) return;

    // A worker that finished every owned issue is in MAINTENANCE (#1957), not building — its
    // post-completion activity is expected, not drift, so the warden must NOT quarantine it, and any
    // existing quarantine on it is lifted. Read each project's issue statuses once per tick (deduped by
    // project key — a worker pane id is `<projectKey>:<streamId>`).
    const projectKeys = [...new Set(panes.map((p) => p.split(":")[0]).filter(Boolean))];
    const doneByProject = new Map<string, Set<string>>();
    await Promise.all(projectKeys.map(async (key) => {
      const issues = await bscJson<PlanIssue[]>(key, ["plan", "list", "--full", "--json"], []);
      doneByProject.set(key, doneIssueRefs(issues ?? []));
    }));
    if (isCancelled()) return;
    const completed = completedWorkerPanes(st.fleetPaneStreams, (paneId) => doneByProject.get(paneId.split(":")[0]));
    for (const paneId of completed) {
      if (st.quarantinedPanes[paneId]) {
        st.clearQuarantine(paneId);
        log.info(`warden: lifted quarantine for ${paneId} — its issues are complete (in maintenance)`);
      }
    }

    const fresh = useAppStore.getState();
    const quarantined = new Set([...Object.keys(fresh.quarantinedPanes), ...inFlight.current]);
    // #3954: probe only panes with a RUNNING session, and skip completed workers entirely (they must
    // not be (re)quarantined while standing by). `panes` is the PLANNED roster — after the resume
    // rebuilt network-monitor's worktrees that was 47 panes against 3 live terminals, and every pane
    // costs two git subprocesses. A pane with no session cannot be drifting.
    const liveIds = livePaneIdsOf(fresh.tabs, fresh.endedPanes, fresh.disabledPanes);
    const live = wardenSweepTargets(panes, liveIds, completed);
    // #3908: TWO invokes per sweep, not two per pane. Was `Promise.all(live.map(buildSession))`, which
    // fired N git-spawning `read_worktree_changes` plus N identical audit tails at once.
    const { auditLines, changesByPane } = await sweepInputs(live);
    if (isCancelled()) return;
    const sessions = live
      .map((p) => buildSession(p, auditLines, changesByPane))
      .filter((s): s is WardenSession => s !== null);

    // Layer 1 — deterministic hard-pause (every tick, free).
    for (const trip of planWarden(sessions, quarantined)) {
      void quarantinePane(trip.paneId, trip.streamId, trip.summary, inFlight);
    }

    // Layer 2 — LLM-judge spot-check (sampled, gated on an API key, one call at a time).
    tickCount.current += 1;
    if (tickCount.current % JUDGE_EVERY === 0 && !judging.current) {
      const cfg = resolveLlmConfig(st);
      if (hasLlmKey(cfg)) {
        const skip = new Set([...quarantined, ...Object.keys(useAppStore.getState().quarantinedPanes)]);
        const pick = selectForJudging(sessions.map((s) => s.paneId), judgeCursor.current++, skip);
        const session = pick ? sessions.find((s) => s.paneId === pick) : undefined;
        if (session) {
          judging.current = true;
          void judgeAndMaybeQuarantine(session, cfg, inFlight).finally(() => { judging.current = false; });
        }
      }
    }
  }, []);
}

// Auto-end a finished fleet worker (#920 / #1379). Two triggers drop a worker pane into a resting
// state (done / needs-attention / blocked) instead of leaving a dead console in the grid:
//   - `pty_exit_{paneId}` — the shell exited (legacy; rarely fires for the long-lived REPL).
//   - `bsc-done` (#1379) — a finished worker self-reports via `done.log`; we poll `read_done_panes`
//     and reap, additionally `pty_kill`-ing the still-live session.
// Either way the TRIGGER is only the prompt to evaluate; the verdict comes from plan.db
// (`bsc plan list`) with coord.log as a tiebreaker (`classifyWorkerEnd`) — NOT the worker's
// say-so. The ended state is persisted + recovery-gated, so a restart never re-opens a finished
// worker. Mounted once at the app root.
//
// THIS MODULE WRITES TO NO SESSION'S STDIN. It ends and reaps panes; it never types at one. Two raw
// `pty_write` calls into the DIRECTOR's pane lived here until
// #the-fleet-went-pull-but-nobody-told-the-director-to-pull — a raw invoke, so the injector ratchet
// (which matches `injectPrompt` imports) could not see them, and `pty_kill` reads as the same kind of
// call at a glance. If you are about to add a message for a director, it belongs in a queue the
// director PULLS (`bsc logs waiting`, `bsc fleet list`), not in its input.

import { useEffect, useRef } from "react";
import { listen } from "@tauri-apps/api/event";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { bscJson } from "@/shared/lib/core/bsc";
import { logsDonePanes, logsPaneActivity } from "@/shared/lib/core/logsBridge";
import { usePoll } from "@/shared/hooks/usePoll";
import { useLogStream } from "@/shared/hooks/useLogStream";
import { useAppStore } from "@/store";
import { emptyCoordState } from "@/shared/lib/fleet/coordination";
import { readCoordState } from "@/shared/lib/fleet/useCoordLog";
import { classifyWorkerEnd, type OwnedIssue } from "@/shared/lib/fleet/workerEnd";
import { decideWorkerAutoEnd, DEFAULT_AUTO_END_THRESHOLDS } from "@/shared/lib/fleet/workerAutoEnd";
import { log } from "@/shared/lib/core/log";

/** One pane's latest turn-boundary state, as `bsc logs pane-activity` (`logs::PaneActivity`)
 *  returns it — typed locally so this shared module doesn't import the app layer. */
interface ActivityRow { pane: string; state: string; at: number }

// The close-NUDGE is gone (#session-stop-is-honoured). It used to `pty_write` a "run bsc-done" prompt
// into an idle, question-free, work-complete worker — i.e. the app typing at a session that had just
// finished. That never fired in practice, because `bsc-defer` refused a worker's Stop and it could not
// reach "idle with work complete" in the first place. Removing the hook would have SWITCHED IT ON, so
// a finished worker would have stopped and immediately been re-prompted: the exact behaviour this item
// exists to end, arriving through a different door.
//
// The pane still reaches its resting state — `evaluateExit` is called directly instead. That is the
// same verdict from the same source (plan.db via `classifyWorkerEnd`, never the worker's say-so); the
// nudge only ever existed to make the worker call `bsc-done` so this ran. Cutting out the round trip
// through the agent is strictly better: no injection, no token spend, and no dependence on the session
// still being alive to answer. The app updating its OWN UI is not the app driving a session.

/** How idle-poll ticks: every 15s. The close-nudge threshold is 60s, so this is responsive enough. */
// #3643: the idle close-nudge is event-driven — it re-checks when a worker's turn state changes
// (`activity`), coord changes, or a worker self-reports done, + a slow backstop; not a 15s clock.

/**
 * Evaluate a worker's owned issues and mark the pane ended accordingly. `opts.kill` also kills the
 * PTY — used by the `bsc-done` path, where the worker is still live (the `pty_exit` path leaves it
 * false, since the shell already exited).
 */
async function evaluateExit(paneId: string, opts: { kill?: boolean } = {}): Promise<void> {
  const s = useAppStore.getState();
  if (s.endedPanes[paneId]) return; // already ended
  if ((s.paneRoles[paneId] ?? "worker") !== "worker") return; // only auto-end workers
  const stream = s.fleetPaneStreams[paneId];
  if (!stream) return;

  // The owning project key, from the tab that minted this pane id. The old positional
  // `t{tab}p{pane}` parse broke for fleet workers (#1379): #1176 gave them stable
  // `<projectKey>:<streamId>` ids, so look the pane up in its tab's `paneIds` instead.
  const projectKey = s.tabs.find((t) => t.paneIds?.includes(paneId))?.projectKey;
  if (!projectKey) return; // can't query the DB without the project

  // `bsc plan list --stream <id> --full --json` emits this stream's full issue rows (the same
  // `Vec<PlanIssue>` the old `plan_list_issues` command returned); bscJson degrades to `null` when the
  // project's plan.db isn't there yet, so an absent store bails exactly as the old catch did.
  const issues = await bscJson<OwnedIssue[] | null>(projectKey, ["plan", "list", "--stream", stream.id, "--full", "--json"], null);
  if (!issues) return;

  const coord = (await readCoordState(5000))?.state ?? emptyCoordState();

  const verdict = classifyWorkerEnd(issues.map((i) => ({ ref: i.ref, status: i.status })), coord);
  log.info(`auto-end: ${paneId} (${stream.id}) → ${verdict.state} — ${verdict.summary}`);
  useAppStore.getState().markPaneEnded(paneId, {
    state: verdict.state, streamId: stream.id, summary: verdict.summary, at: Date.now(),
  });
  // The director close-open-issues nudge (#1379) USED TO BE HERE and is gone
  // (#the-fleet-went-pull-but-nobody-told-the-director-to-pull). It typed a message into the
  // director's stdin with a trailing CR, which submits it — opening a Claude turn in a session
  // nobody clicked. That is the symptom the maintainer reported, arriving through the one path the
  // injector ratchet could not see (it matches `injectPrompt` imports; this was a raw `pty_write`).
  //
  // NOTHING REPLACES IT, deliberately. It told the director to run `gh issue close`, and the
  // GitHub-ownership clause was removed from director-protocol.md under local-first — the protocol
  // tests now assert its ABSENCE. So the nudge instructed work the director no longer claims.
  // bsc-done (#1379): the worker is still live and asked to close, so actually kill its PTY.
  if (opts.kill) {
    await safeInvoke("pty_kill", { paneId }, undefined, (e) => log.error(`auto-end: pty_kill failed for ${paneId}: ${e}`));
  }
}

export function useWorkerAutoEnd(): void {
  // Re-subscribe whenever the fleet pane set changes (panes come and go across launches).
  const fleetPaneStreams = useAppStore((s) => s.fleetPaneStreams);
  useEffect(() => {
    let cancelled = false;
    const unlistens: Array<() => void> = [];
    for (const paneId of Object.keys(fleetPaneStreams)) {
      if ((useAppStore.getState().paneRoles[paneId] ?? "worker") !== "worker") continue;
      void listen(`pty_exit_${paneId}`, () => { if (!cancelled) void evaluateExit(paneId); })
        .then((off) => { if (cancelled) off(); else unlistens.push(off); });
    }
    return () => { cancelled = true; for (const off of unlistens) off(); };
  }, [fleetPaneStreams]);

  // bsc-done self-close (#1379): poll the workers that self-reported done and reap each —
  // classify from plan.db (markPaneEnded) AND pty_kill the still-live shell. The endedPanes guard
  // in evaluateExit makes this idempotent across polls (a lingering done.log line won't re-kill).
  // Event-driven (#3638): reap self-reported-done workers only when the done log changes (plus mount +
  // a slow backstop), instead of polling every 2s. The `endedPanes` guard in `evaluateExit` keeps it
  // idempotent, so a lingering done.log line re-firing on a later event won't re-kill.
  useLogStream("done", async (isCancelled) => {
    const done = await logsDonePanes();
    if (isCancelled() || !Array.isArray(done)) return;
    const s = useAppStore.getState();
    for (const paneId of done) {
      if (s.endedPanes[paneId] || !s.fleetPaneStreams[paneId]) continue;
      await evaluateExit(paneId, { kill: true });
    }
  }, []);

  // Idle close-nudge (#1379 stage 3): for each at-rest worker, decide via the pure core whether to
  // nudge it to self-close. A worker that's question-free, idle past the short window, and whose
  // owned issues all read complete in plan.db gets ONE "wrap up / bsc-done" prompt; the nudge
  // re-arms when its turn reopens. A worker paused for the user (coord.waiting) is left alone, and
  // an outstanding director question routes to the resurface path (stage 4), never a close.
  const nudgedRef = useRef<Set<string>>(new Set());
  const resurfacedRef = useRef<Set<string>>(new Set()); // lost-ask resurfaces, one per stale ask
  useLogStream(["activity", "coord", "done"], async (isCancelled) => {
    const activity = await logsPaneActivity<ActivityRow>();
    const coordRes = await readCoordState(5000);
    if (isCancelled() || !Array.isArray(activity)) return;
    const coord = coordRes?.state ?? emptyCoordState();
    const s = useAppStore.getState();
    const now = Date.now();

    // #3944: decide the candidate set FIRST, then read each project's issues ONCE.
    //
    // This used to spawn `bsc plan list --stream <id>` inside the loop — one subprocess per pane, awaited
    // serially, on every change to any of THREE log streams (activity/coord/done). That was the bulk of
    // 37 `bsc plan list`/min and ~10% of all invoke time. `useWarden`, in the next file over, already
    // reads once per project and partitions in memory; this now matches it. `PlanIssue` carries `stream`,
    // so the per-stream query bought nothing a filter can't do.
    const candidates: Array<{ paneId: string; stream: { id: string }; projectKey: string; act: ActivityRow | undefined }> = [];
    for (const paneId of Object.keys(s.fleetPaneStreams)) {
      if (s.endedPanes[paneId] || (s.paneRoles[paneId] ?? "worker") !== "worker") continue;
      const act = activity.find((a) => a.pane === paneId);
      if (act?.state === "run") { nudgedRef.current.delete(paneId); resurfacedRef.current.delete(paneId); continue; } // working → re-arm
      if (coord.waiting.some((w) => w.session === paneId)) continue;             // paused for the user → leave it
      // `maintaining` NO LONGER PINS A PANE OPEN (#session-stop-is-honoured). Under #1957 a `maintain`
      // event meant "parked alive and ready", so skipping it was right. It now means the worker left a
      // standing note on its way OUT, so skipping it would hold a finished pane in the grid forever —
      // the resting-state problem (#920) coming back through the event that says the work is done.
      if (!coord.asking.some((a) => a.session === paneId)) resurfacedRef.current.delete(paneId); // ask answered → re-arm resurface
      const stream = s.fleetPaneStreams[paneId];
      const projectKey = s.tabs.find((t) => t.paneIds?.includes(paneId))?.projectKey;
      if (!projectKey || !stream) continue;
      candidates.push({ paneId, stream, projectKey, act });
    }
    if (candidates.length === 0) return;
    // One read per DISTINCT project, concurrently — not one per pane, serially.
    const byProject = new Map<string, OwnedIssue[] | null>();
    await Promise.all([...new Set(candidates.map((c) => c.projectKey))].map(async (key) => {
      byProject.set(key, await bscJson<OwnedIssue[] | null>(key, ["plan", "list", "--full", "--json"], null));
    }));
    if (isCancelled()) return;

    for (const { paneId, stream, projectKey, act } of candidates) {
      const all = byProject.get(projectKey);
      if (!all) continue;                                   // read failed / no plan.db — same bail as before
      const issues = all.filter((i) => i.stream === stream.id);
      const verdict = classifyWorkerEnd(issues.map((i) => ({ ref: i.ref, status: i.status })), coord);
      const action = decideWorkerAutoEnd({
        turnOpen: act?.state === "run",
        idleMs: act?.state === "idle" ? now - act.at : 0,
        hasOutstandingQuestion: coord.asking.some((a) => a.session === paneId),
        verdict,
      }, DEFAULT_AUTO_END_THRESHOLDS);
      if (action === "close-nudge" && !nudgedRef.current.has(paneId)) {
        // The decision is unchanged — this worker is at rest with its owned work complete. What we DO
        // with it changed: reap the pane ourselves rather than typing at the session (see the header).
        // `evaluateExit` re-reads plan.db and is idempotent via its own `endedPanes` guard, so the ref
        // is belt-and-braces against a burst of log events, not the thing that makes it safe.
        // No `kill` — the shell stays up so the user can resume this session with a click.
        nudgedRef.current.add(paneId); // once per idle period; cleared when the turn reopens
        log.info(`auto-end: reaping ${paneId} (${stream.id}) — idle + work complete`);
        await evaluateExit(paneId);
      } else if (action === "resurface-question" && !resurfacedRef.current.has(paneId)) {
        // Lost-question resurface (#1379 stage 4): the worker has waited too long on a director
        // answer. This used to TYPE the question into the director's pane; it now only records the
        // observation (#the-fleet-went-pull-but-nobody-told-the-director-to-pull).
        //
        // NOTHING IS LOST, because the push had a pull all along: `bsc logs waiting` lists every
        // unanswered ask oldest-first, and the director's protocol now tells it to sweep that queue.
        // The pull is strictly better than this was — it shows EVERY stale ask on every sweep, where
        // this fired once per pane per idle period and then went quiet.
        const ask = coord.asking.find((a) => a.session === paneId);
        if (ask) {
          resurfacedRef.current.add(paneId);
          const waited = Math.max(1, Math.round((now - ask.at) / 60_000));
          log.info(`auto-end: ${paneId} has waited ~${waited}m on an unanswered ask — it is in \`bsc logs waiting\` for its director to sweep`);
        }
      }
    }
  }, []);

  // Reclaim a finished worker's worktree once its branch is MERGED (#worktree-disk). Gated on the
  // pane already being ENDED (its work is pushed) AND the PR merged on GitHub — the authoritative
  // remote signal the boot-GC's local merge check can't see. Teardown runs once per pane; the
  // boot-GC remains the fallback for anything missed (and never removes a dirty/unmerged worktree).
  const tornDownRef = useRef<Set<string>>(new Set());
  usePoll(async (isCancelled) => {
    const s = useAppStore.getState();
    const token = s.githubToken;
    if (!token) return;
    for (const paneId of Object.keys(s.endedPanes)) {
      if (tornDownRef.current.has(paneId)) continue;
      if ((s.paneRoles[paneId] ?? "worker") !== "worker") continue;
      const ps = s.paneStream[paneId];               // { repo, branch }
      const stream = s.fleetPaneStreams[paneId];      // AgentStream (.id = the worktree slug source)
      const projectKey = s.tabs.find((t) => t.paneIds?.includes(paneId))?.projectKey;
      if (!ps || !stream || !projectKey) continue;
      const owner = ps.repo.split("/")[0];
      const prs = await safeInvoke<Array<{ merged_at: string | null }> | null>(
        "github_request",
        { token, path: `repos/${ps.repo}/pulls?state=all&head=${owner}:${ps.branch}&per_page=1` },
        null,
      );
      if (isCancelled()) return;
      if (!Array.isArray(prs) || prs[0]?.merged_at == null) continue; // not merged yet — keep it
      tornDownRef.current.add(paneId); // reclaim once
      log.info(`teardown: stream ${stream.id} merged → reclaiming its worktree`);
      await safeInvoke("teardown_worktree", { projectKey, repo: ps.repo, agentId: stream.id }, undefined,
        (e) => log.error(`teardown_worktree failed for ${stream.id}: ${e}`));
    }
  }, 60_000, []);
}

// Data-defined component variants (#2569 rung 3) — the RENDER path for variants an LLM authors with
// `bsc ui component <c> define-variant`. Each stored definition is a token bundle for a
// `<component>:<variant>`; this compiles them into ONE managed `<style>` of `.<component>.<variant>`
// rules that set the component's semantic tokens, so an authored variant restyles the real component
// with zero component changes (the primitive already adds the variant string as a class — a new variant
// is pure DATA). Applied globally on boot + re-applied on a `ui-touch` "variant" write (live, #2525).
//
// DEFENSE IN DEPTH: the CLI already sanitises the name + grammar-checks each value (crates/bsc-ui), but
// this compiles LLM-authored data into live CSS, so we re-validate here — a variant/component name must
// be a safe CSS identifier and a value must not contain a declaration-ending / injection sequence.
// Anything failing is skipped, never emitted.

/** One stored variant definition — the shape `bsc ui variants` returns. */
export interface VariantDef {
  /** `<component>:<variant>` (the store id). */
  id: string;
  component: string;
  variant: string;
  /** Short token key (e.g. `bg`) → value (a `var(--x)` / colour / dimension). */
  tokens: Record<string, string>;
}

const STYLE_ID = "bsc-ui-variants";
/** A safe CSS identifier for a class selector segment (mirrors the CLI's sanitize_variant_name). */
const SAFE_IDENT = /^[a-z][a-z0-9-]*$/;
/** A value that could END the declaration or INJECT CSS — refused even though the CLI already guards. */
const UNSAFE_VALUE = /[;{}<>\\]|url\(|expression\(|@import|\/\*/i;

/**
 * Compile variant definitions into CSS: one `.<component>.<variant> { --<component>-<key>: <value>; … }`
 * rule per definition. Pure + guarded — skips any definition whose component/variant name isn't a safe
 * identifier and any token whose value looks like an injection. Empty string when nothing is renderable.
 */
export function compileVariantsCss(defs: VariantDef[]): string {
  const rules: string[] = [];
  for (const d of defs) {
    if (!d || !SAFE_IDENT.test(d.component ?? "") || !SAFE_IDENT.test(d.variant ?? "")) continue;
    const decls = Object.entries(d.tokens ?? {})
      .filter(([key, value]) => SAFE_IDENT.test(key) && typeof value === "string" && !UNSAFE_VALUE.test(value))
      .map(([key, value]) => `  --${d.component}-${key}: ${value};`);
    if (decls.length) rules.push(`.${d.component}.${d.variant} {\n${decls.join("\n")}\n}`);
  }
  return rules.join("\n\n");
}

/**
 * Inject / update / clear the managed `<style id="bsc-ui-variants">` holding the compiled variant CSS.
 * Removing the last variant removes the element. `doc` is param'd for tests. Mirrors the accent/theme
 * root-apply — one global stylesheet the whole app follows.
 */
export function applyVariantsToRoot(defs: VariantDef[], doc: Document = document): void {
  const css = compileVariantsCss(defs);
  let el = doc.getElementById(STYLE_ID) as HTMLStyleElement | null;
  if (!css) {
    el?.remove();
    return;
  }
  if (!el) {
    el = doc.createElement("style");
    el.id = STYLE_ID;
    doc.head.appendChild(el);
  }
  el.textContent = css;
}

// The LINK VERIFIER for graph records (epic #3604) — "would this record actually load?", answered with
// the runtime's own mechanism instead of a guess.
//
// Two existing checks look like they cover this and do not:
//   - `componentScan` builds and RUNS each component, but through the PREVIEW bundler, which
//     deliberately ISOLATES — it stubs React and forbids `@/` first-party imports. It cannot see whether
//     a record's imports resolve against the APP.
//   - `platformBoundary.test.ts` does ask the right question, but with a REGEX over the source. A static
//     check more permissive than the runtime is exactly the defect #4188 and #4224 each removed:
//     `zustand/react/shallow` sailed past that guard and failed in the browser.
//
// The linker made the exact answer available. `scanRequires` over COMPILED output is what the runtime
// requires — type-only imports have already erased, re-exports have already become requires, and there
// is no second parser to drift.
//
// IT DOES NOT EVALUATE, deliberately. Evaluating runs a record's module-init side effects against the
// live app, and a verification pass must not have side effects — a Studio that verified on every
// keystroke would be re-running registries as you typed. The consequence is a stated limit: "exports a
// component" is only knowable by evaluating, so it stays the mounting host's job (`pickComponent`, and
// the last-good render gate behind it).

import { linkGraphModules, scanRequires, type CompileFn, type SourceResolver } from "@/shared/lib/runtime/graphModules";

/** One record's verdict. `ok` is the whole judgement; the arrays say why, so a caller can render a
 *  useful message rather than a boolean. */
export interface LinkVerdict {
  ok: boolean;
  /** A compile failure — the record does not parse. Mutually exclusive with `unresolved` having meaning:
   *  nothing can be resolved if nothing compiled. */
  compileError?: string;
  /** Specifiers that are neither a graph record nor a registered platform module. These are what throw
   *  the loader's named error at mount time. */
  unresolved: string[];
  /** Every runtime specifier reached, across the record and its transitively linked records — useful for
   *  a report, and the non-vacuity check for a sweep (zero imports usually means nothing was scanned). */
  imports: string[];
  /** How many records the entry linked, INCLUDING itself. */
  linkedCount: number;
}

/** Is this specifier backed by a live registered app module? Injected so the verifier is testable and
 *  usable from a harness that registers its own platform. */
export type RegistryProbe = (specifier: string) => boolean;

/**
 * Verify that `source` would LINK: it compiles, and every specifier it (transitively) requires resolves
 * to either another graph record or a registered platform module.
 *
 * `resolveSource` is the same resolver the loader uses, so graph-first `provides` overrides (#3660) and
 * `@/components/<id>` siblings both count as resolved — a record that provides a platform specifier is a
 * legitimate answer, not a miss.
 *
 * A BARE npm specifier is checked like any other (#4224). It used to feel like the import map's concern,
 * but the import map belongs to the preview; the loader's `require` demands every specifier be
 * registered, first-party or not.
 */
export async function verifyGraphRecord(
  source: string,
  opts: { resolveSource?: SourceResolver; isRegistered: RegistryProbe; compile: CompileFn },
): Promise<LinkVerdict> {
  const { resolveSource, isRegistered, compile } = opts;
  let linked;
  // Declared without an initializer: the try below assigns BOTH halves, and the catch returns, so an
  // initial value would only ever be dead.
  let linkFailures: { specifier: string; error: string }[];
  try {
    ({ linked, failures: linkFailures } = await linkGraphModules(source, resolveSource, compile));
  } catch (e) {
    // A record that does not parse is a compile failure, not a link failure. Reported rather than
    // thrown: a sweep over hundreds of records must not stop at the first bad one.
    return { ok: false, compileError: String(e instanceof Error ? e.message : e), unresolved: [], imports: [], linkedCount: 0 };
  }

  const imports = new Set<string>();
  for (const mod of linked.values()) for (const spec of scanRequires(mod.cjs)) imports.add(spec);

  // A specifier is resolved when the linker took it (it is a record) or the registry answers it. Order
  // does not matter here — this is a membership question, not the graph-first PRECEDENCE question the
  // require chain answers at mount.
  const unresolved = [...imports].filter((spec) => !linked.has(spec) && !isRegistered(spec)).sort();

  // A closure member that would not COMPILE is declined at RUNTIME (the registry answers instead), but for
  // VERIFICATION it is exactly the thing worth naming — the sweep exists to find records that are inert.
  const compileError =
    linkFailures.length > 0
      ? `override "${linkFailures[0].specifier}" does not compile: ${linkFailures[0].error}`
      : undefined;

  return {
    ok: unresolved.length === 0 && !compileError,
    compileError,
    unresolved,
    imports: [...imports].sort(),
    linkedCount: linked.size,
  };
}

/** A one-line human summary of a verdict — what a Studio would show, and what a sweep prints per row. */
export function describeVerdict(id: string, v: LinkVerdict): string {
  if (v.compileError) return `${id}: does not compile — ${v.compileError}`;
  if (!v.ok) return `${id}: ${v.unresolved.length} unresolved import(s) — ${v.unresolved.join(", ")}`;
  return `${id}: ok (${v.linkedCount} module(s), ${v.imports.length} import(s))`;
}

import { Terminal, FolderOpen, GitBranch, GitCompareArrows, History, ShieldCheck, Activity } from "lucide-react";
import type { LucideIcon } from "lucide-react";

// The canonical console-pane VIEW registry: the set of views a pane can show, their icon/label/
// hotkey, and their order. The view switcher itself lives in the PaneMenu dropdown (#1149/#1319) and
// the PaneShell trigger glyph; both read VIEW_DEFS, and useHotkeys maps Alt+digits through VIEW_ORDER.
// (Extracted out of the former ViewTabs tab-strip component — removed once switching moved into the
// menu; the icon-registry migration of these glyphs is tracked separately as the console+icons theme.)
export type ViewKey = "console" | "files" | "branches" | "changes" | "log" | "tools" | "telemetry";

// `group` (#1149) splits the view-switcher dropdown into the working SCREENs (terminal, files,
// git views) and the INSPECT panels (tools & permissions, …) — mirroring the Console-Shell design.
export const VIEW_DEFS: Record<ViewKey, { Icon: LucideIcon; label: string; hint: string; hotkey: string; group: "screen" | "inspect" }> = {
  console:  { Icon: Terminal,   label: "Console",  hint: "claude session",      hotkey: "Alt+1", group: "screen" },
  files:    { Icon: FolderOpen, label: "Files",    hint: "working tree",        hotkey: "Alt+2", group: "screen" },
  branches: { Icon: GitBranch,  label: "Branches", hint: "local + remote refs", hotkey: "Alt+3", group: "screen" },
  changes:  { Icon: GitCompareArrows, label: "Changes", hint: "diff vs HEAD",   hotkey: "Alt+4", group: "screen" },
  log:      { Icon: History,    label: "Log",      hint: "recent commits",      hotkey: "Alt+5", group: "screen" },
  tools:    { Icon: ShieldCheck, label: "Tools & permissions", hint: "mcp + role posture", hotkey: "Alt+6", group: "inspect" },
  telemetry:{ Icon: Activity,   label: "Telemetry · cost", hint: "tokens + spend", hotkey: "Alt+7", group: "inspect" },
};

/** Views in their canonical (hotkey) order — index i ⇒ Alt+(i+1) / Alt+Shift+(i+1). The single
 *  source the view hotkeys (useHotkeys) map digits through, so the keys never drift from VIEW_DEFS. */
export const VIEW_ORDER: ViewKey[] = ["console", "files", "branches", "changes", "log", "tools", "telemetry"];

// Viewport culling geometry (#components-graph-culls-offscreen-nodes) — which world-space boxes can the
// user actually see, given a pan/zoom view and the size of the viewport that clips it.
//
// PURE ON PURPOSE. The decision "is this node worth mounting" is arithmetic over a transform and two
// rectangles; making it a function of numbers (rather than something that reads the DOM) is what lets the
// rule be tested exhaustively without a browser — and jsdom, which every test here runs in, has no layout
// at all, so a DOM-reading version would be untestable by construction.
//
// The caller measures the viewport in an EFFECT and passes the numbers in.
import type { GraphBox, GraphView } from "@/shared/ui/layouts/useGraphViewport";

/**
 * How much MORE than the visible area to keep mounted, as a multiple of the viewport, on every side.
 *
 * This is not a comfort setting — it is what makes culling compatible with the imperative pan (#4140).
 * A drag writes the world transform straight to the DOM and commits to React state only on mouseup, so
 * NOTHING re-renders mid-drag: the mounted set is frozen from the moment the drag starts until it ends.
 * A margin of one full viewport per side means a drag has to travel a whole screen before it can reach
 * space that was culled, and the commit that lands on mouseup re-fills it.
 *
 * The cost of raising it is real (area grows as the square: 1 ⇒ 9× the visible area), which is why it is
 * one rather than two.
 */
export const CULL_MARGIN_VIEWPORTS = 1;

/**
 * The world-space rectangle currently visible through a viewport of `vpW`×`vpH` screen px, expanded by
 * `margin` viewports on every side.
 *
 * Inverts the world layer's transform (`translate(tx,ty) scale(scale)`): a world point `w` is drawn at
 * screen `w * scale + t`, so the visible world span is `(0 - t)/scale` to `(vp - t)/scale`.
 *
 * Returns `null` for a viewport that has not been measured yet or a degenerate scale — the caller MUST
 * read that as "cull nothing" rather than "show nothing". Guessing a rect before the element has a size
 * is what would flash an empty graph on first paint.
 */
export function visibleWorldRect(
  view: GraphView,
  vpW: number,
  vpH: number,
  margin: number = CULL_MARGIN_VIEWPORTS,
): GraphBox | null {
  if (!(vpW > 0) || !(vpH > 0) || !(view.scale > 0)) return null;
  const w = vpW / view.scale;
  const h = vpH / view.scale;
  // `(0 - tx)` rather than `-tx`: the latter yields NEGATIVE zero for an unpanned view, and `-0` is a
  // value that compares equal to 0 with `===` but not with `Object.is`/`toEqual` — a trap for any caller
  // that memoizes or asserts on this rect. Geometry should not carry a sign on nothing.
  return {
    x: (0 - view.tx) / view.scale - w * margin,
    y: (0 - view.ty) / view.scale - h * margin,
    w: w * (1 + margin * 2),
    h: h * (1 + margin * 2),
  };
}

/**
 * Do two world-space boxes overlap at all? Edge-inclusive, so a node flush against the rect's boundary
 * counts as visible — the whole point of the margin is to be generous, and a node that is half a pixel
 * outside is one the user is about to pan onto.
 */
export function boxesIntersect(a: GraphBox, b: GraphBox): boolean {
  return a.x <= b.x + b.w && b.x <= a.x + a.w && a.y <= b.y + b.h && b.y <= a.y + a.h;
}

/**
 * Is a node at (`x`,`y`) sized `w`×`h` worth mounting, given the visible rect?
 *
 * A `null` rect means UNMEASURED, and everything is visible — see {@link visibleWorldRect}. That default
 * is deliberate and load-bearing: every failure mode of this module should render too much, never too
 * little, because rendering too much is the state we are already in and rendering too little is a blank
 * graph the user cannot tell from a crash.
 */
export function isNodeVisible(rect: GraphBox | null, x: number, y: number, w: number, h: number): boolean {
  return rect === null || boxesIntersect(rect, { x, y, w, h });
}

// vizRunToDataset (#2940): extract a plain, component-consumable DATASET from a sandbox VizRun — the
// bridge that lets a librarian ALGORITHM feed a designer COMPONENT's preview (the studio-network payoff).
//
// A VizRun is `{ datatype, input, frames }` where each Frame carries a fresh snapshot of the structure's
// data. The algorithm's OUTPUT is the LAST snapshot frame — a sort's sorted array, a matrix op's
// transformed grid, a graph layout's positioned nodes — falling back to the seed `input` when a run has
// no snapshot frames. The result is normalized so a component preview can bind a data prop straight to it
// (e.g. a `graph` dataset → a ForceGraph's `{ nodes, edges }`), with no per-component adapter.
import type { VizRun } from "@/features/algorithms/viz/examples/vizProgram";
import type { GraphInput } from "@/features/algorithms/lib/tracer";

/** A nested tree node (#3790) — a `{ id, label, children? }` forest node, structurally the shared
 *  Tree/TreeExplorerPage `nodes` prop shape (`TreeNodeData`), so it binds directly. */
export interface TreeDatasetNode {
  id: string;
  label: string;
  children?: TreeDatasetNode[];
}

/** A normalized dataset extracted from a run — discriminated by the run's datatype, structurally-cloneable
 *  and directly bindable to a component prop. `graph` covers both the `graph` and `scene` datatypes; `tree`
 *  (#3790) is a NESTED forest (built from a BST's pure shape, not a run — see `datasetForStructure`). */
export type VizDataset =
  | { kind: "array"; data: number[] }
  | { kind: "matrix"; data: number[][] }
  | { kind: "graph"; nodes: GraphInput["nodes"]; edges: GraphInput["edges"] }
  | { kind: "tree"; roots: TreeDatasetNode[] };

// Frames are snapshots; we read the last one that carries the structure's data. Typed loosely here
// (the tracer's Frame union lives module-private) — we only touch the snapshot fields we extract.
type Snapshot = {
  structure?: string;
  data?: number[] | number[][];
  nodes?: GraphInput["nodes"];
  edges?: GraphInput["edges"];
};

/** A tree frame's parent-pointer node list — the shape `TracedTree` snapshots (#4162). Read separately
 *  from {@link Snapshot} because a graph node and a tree node share only the `id` field. */
type TreeSnapshotNode = { id: string; value: number | string; parent?: string };

/** The last frame that carries a structural snapshot (the algorithm's settled output), or undefined. */
function lastSnapshot(frames: readonly unknown[]): Snapshot | undefined {
  for (let i = frames.length - 1; i >= 0; i--) {
    const f = frames[i] as Snapshot;
    if (f && (f.data !== undefined || f.nodes !== undefined)) return f;
  }
  return undefined;
}

/** Nest a parent-pointer node list into a forest (#4162). Children keep their snapshot order, so a BST
 *  reads left-then-right. Orphans (a `parent` naming no node) are promoted to roots rather than dropped —
 *  a partial tree is still worth showing, and silently losing nodes would misrepresent the algorithm. */
function nestByParent(nodes: readonly TreeSnapshotNode[]): TreeDatasetNode[] {
  const byId = new Map<string, TreeDatasetNode>(
    nodes.map((n) => [n.id, { id: n.id, label: String(n.value) }]),
  );
  const roots: TreeDatasetNode[] = [];
  for (const n of nodes) {
    const node = byId.get(n.id);
    if (!node) continue;
    const parent = n.parent !== undefined ? byId.get(n.parent) : undefined;
    if (parent) (parent.children ??= []).push(node);
    else roots.push(node);
  }
  return roots;
}

/**
 * Normalize a {@link VizRun} into a {@link VizDataset} a component preview can bind to. Prefers the
 * algorithm's FINAL snapshot (its computed output); falls back to the run's seed `input` so a run that
 * recorded no snapshot frames still yields the shaped data.
 *
 * `undefined` for the `stack` and `scalar` datatypes (#4162): a stack's contents are a mixed
 * number/string sequence and a scalar run is a NAMED variable map — neither is any of the three dataset
 * shapes a component prop binds to. Returning a coerced `array` for them would hand a component a
 * plausible-looking dataset that means something else, which is worse than having none.
 */
export function vizRunToDataset(run: VizRun): VizDataset | undefined {
  const snap = lastSnapshot(run.frames);
  switch (run.datatype) {
    case "tree": {
      // The tracer's tree frames carry the parent pointers; nesting them is the whole conversion.
      const nodes = (snap?.nodes as TreeSnapshotNode[] | undefined) ?? [];
      return { kind: "tree", roots: nestByParent(nodes) };
    }
    case "stack":
    case "scalar":
      return undefined;
    case "array": {
      const data = (snap?.data as number[] | undefined) ?? (run.input as number[]);
      return { kind: "array", data: [...(data ?? [])] };
    }
    case "matrix": {
      const data = (snap?.data as number[][] | undefined) ?? (run.input as number[][]);
      return { kind: "matrix", data: (data ?? []).map((row) => [...row]) };
    }
    case "graph":
    case "scene": {
      const seed = run.input as GraphInput;
      const nodes = snap?.nodes ?? seed?.nodes ?? [];
      const edges = snap?.edges ?? seed?.edges ?? [];
      return { kind: "graph", nodes: nodes.map((n) => ({ ...n })), edges: edges.map((e) => ({ ...e })) };
    }
  }
}

// Source instrumentation for stored trace-programs (#3250, epic #3230/#3215) — the compile-time step that
// gives every emitted op a SOURCE LOCATION, so the animation can light up the line that is executing.
//
// WHY AST, NOT TEXT SEARCH. The viz philosophy is instrumented execution: real code runs and the frames
// ARE its ops. Per-op highlighting only holds up if each op knows which CALL produced it. A text search
// for `.swap(` cannot tell quicksort's two swap branches apart — it would find both and have to guess,
// and the highlight would jump to the wrong branch for half the trace. Parsing gives each call its exact,
// unambiguous range, so a repeated op always points at the call that actually ran.
//
// WHY NOT A RUNTIME STACK CAPTURE. The obvious no-dependency alternative is for the tracer to read
// `new Error().stack` on every emit. It was rejected: stack-string formats and the line offset that
// `new Function` introduces are ENGINE-SPECIFIC (V8 / JSC / SpiderMonkey all differ), so the feature would
// silently produce wrong ranges on some platforms and right ones on others — the worst failure mode for a
// teaching visualization. Parsing is deterministic on every engine.
//
// HOW. Each traced call `a.swap(i, j)` is rewritten to `__bscLoc(7, () => a.swap(i, j))`, where the hook
// pushes range #7 onto the tracer's ambient location stack for the duration of the call (`withSourceLoc`).
// Rewriting is pure INSERTION — no original character is moved or deleted — and the recorded ranges index
// the ORIGINAL source, which is also the string the code column renders. So the highlight and the code can
// never drift apart.

import { parse } from "acorn";
import type { SourceRange } from "@/features/algorithms/lib/trace";
import { TracedArray, TracedGraph, TracedMatrix, TracedScalar, TracedScene, TracedStack, TracedTree } from "@/features/algorithms/lib/tracer";

/** The identifier the instrumented program calls to announce its current source range. Deliberately
 *  unlikely to collide with anything a trace-program declares. */
export const LOC_HOOK = "__bscLoc";

/** Every method name the traced structures expose — DERIVED from the classes themselves rather than
 *  hand-listed, so a new tracer verb is instrumented the day it lands and this file never drifts.
 *
 *  Over-matching is harmless BY CONSTRUCTION: wrapping a call that emits no frame (`a.get(i)`, or an
 *  unrelated `list.push(x)` that merely shares a name with a tracer verb) just pushes and pops a range
 *  nobody reads. Under-matching would silently drop a highlight, so erring wide is the safe direction. */
const TRACER_METHODS: ReadonlySet<string> = new Set(
  [TracedArray, TracedMatrix, TracedGraph, TracedStack, TracedScalar, TracedTree, TracedScene]
    .flatMap((cls) => Object.getOwnPropertyNames(cls.prototype))
    .filter((name) => name !== "constructor"),
);

/** The shape of an acorn node this module reads. Acorn's own types are structural and loose; this is the
 *  minimal surface (`type` + offsets + the `loc` acorn adds under `locations: true`). */
interface AcornNode {
  type: string;
  start: number;
  end: number;
  loc?: { start: { line: number } };
  [key: string]: unknown;
}

/** One instrumented call site: its range in the ORIGINAL source, plus the nested calls inside it. */
interface Hit extends SourceRange {
  id: number;
  children: Hit[];
}

/** The result of instrumenting a trace-program. */
export interface InstrumentedProgram {
  /** The rewritten program — the ORIGINAL source with `__bscLoc(id, () => …)` wrappers inserted. */
  code: string;
  /** The source ranges, indexed by the id the wrappers pass. Empty when nothing was instrumented. */
  locs: SourceRange[];
}

/** Depth-first walk of an acorn AST, visiting every node. Generic over the node shape (acorn nodes are
 *  plain objects), so it needs no per-node-type knowledge and cannot fall behind new syntax. */
function walk(node: unknown, visit: (n: AcornNode) => void): void {
  if (node === null || typeof node !== "object") return;
  if (Array.isArray(node)) {
    for (const child of node) walk(child, visit);
    return;
  }
  const n = node as Record<string, unknown>;
  if (typeof n.type === "string") visit(n as unknown as AcornNode);
  for (const key of Object.keys(n)) {
    // `loc`/`range` are acorn's position metadata, not child nodes — skip (they carry no `type`, so
    // walking them is merely wasted work, but the tree is hot enough to be worth not doing).
    if (key === "type" || key === "start" || key === "end" || key === "loc" || key === "range") continue;
    walk(n[key], visit);
  }
}

/** Is this call a traced-structure operation — `<expr>.<tracerMethod>(…)` with a literal method name? */
function isTracerCall(n: AcornNode): boolean {
  if (n.type !== "CallExpression") return false;
  const callee = n.callee as AcornNode | undefined;
  if (!callee || callee.type !== "MemberExpression" || callee.computed === true) return false;
  const prop = callee.property as AcornNode | undefined;
  return prop?.type === "Identifier" && TRACER_METHODS.has(prop.name as string);
}

/**
 * Rewrite a trace-program so each traced call announces its source range (#3250).
 *
 * @param source the trace-program source — the exact string whose offsets the returned ranges index, and
 *   the string the code column must render.
 * @returns the instrumented {@link InstrumentedProgram}. Falls back to the source UNCHANGED with no ranges
 *   when the program cannot be safely instrumented — it does not parse (the caller's `new Function` will
 *   report the syntax error with a better message), or it contains `await`/`yield`, which the arrow-function
 *   wrappers would change the meaning of. Degrading to "animates, but no highlighting" is deliberate: a
 *   visualization must never be lost to a highlighting feature.
 */
export function instrumentVizCode(source: string): InstrumentedProgram {
  const plain: InstrumentedProgram = { code: source, locs: [] };

  let ast: unknown;
  try {
    ast = parse(source, { ecmaVersion: "latest", locations: true });
  } catch {
    return plain; // not parseable — let the caller's compile step surface the real syntax error
  }

  const flat: Hit[] = [];
  let unsafe = false;
  walk(ast, (n) => {
    // An arrow wrapper would sever `await`/`yield` from their function, so a program using either is left
    // alone entirely. Trace-programs are synchronous by contract (`runAlgorithm` calls `run` and reads the
    // log immediately), so this is a guard, not a supported path.
    if (n.type === "AwaitExpression" || n.type === "YieldExpression") unsafe = true;
    if (isTracerCall(n)) {
      flat.push({ id: 0, start: n.start, end: n.end, line: n.loc?.start.line ?? 1, children: [] });
    }
  });
  if (unsafe || flat.length === 0) return plain;

  // Outermost-first, then by position: the ordering that lets one linear pass rebuild the containment
  // tree. AST call ranges are always properly nested (never partially overlapping), so a stack suffices.
  flat.sort((a, b) => a.start - b.start || b.end - a.end);
  flat.forEach((h, i) => (h.id = i));

  const roots: Hit[] = [];
  const stack: Hit[] = [];
  for (const hit of flat) {
    while (stack.length > 0 && stack[stack.length - 1].end <= hit.start) stack.pop();
    (stack[stack.length - 1]?.children ?? roots).push(hit);
    stack.push(hit);
  }

  // Rebuild the source recursively rather than splicing offsets in place: nested calls make offset
  // bookkeeping error-prone (wrapping an inner call shifts the outer call's end), whereas rendering each
  // range from its children is correct by construction.
  const render = (from: number, to: number, children: Hit[]): string => {
    let out = "";
    let cursor = from;
    for (const child of children) {
      out += source.slice(cursor, child.start);
      out += `${LOC_HOOK}(${child.id},()=>${render(child.start, child.end, child.children)})`;
      cursor = child.end;
    }
    return out + source.slice(cursor, to);
  };

  return {
    code: render(0, source.length, roots),
    locs: flat.map(({ start, end, line }) => ({ start, end, line })),
  };
}

// The stored-`vizCode` executor (#3232, epic #3215 slice B / #3230 §1) — compile an implementation's
// PERSISTED trace-program (its `vizCode` facet, #3218) into a runnable program descriptor. This is the
// "visualization as DATA" path: instead of a hardcoded in-app module (sorts.ts / matrixTransforms.ts /
// graphAlgos.ts), the algorithm's visualization lives in the store and is compiled here on demand.
//
// CONTRACT — `vizCode` is a JS expression that evaluates to a self-describing descriptor:
//
//   ({
//     datatype: "array",         // the structure — picks the runner + renderer(s) + input seam
//     input: [5, 2, 9, 1, 6],    // the DEFAULT input, shaped per datatype (see below)
//     run(a) { … },              // the real algorithm, written against the Traced<Structure> API
//   })
//
// DATATYPES — one per shipped renderer, each with its own input shape:
//
//   array   number[]                        run(array)
//   matrix  number[][]                      run(matrix)
//   graph   { nodes, edges }                run(graph)
//   tree    number[] (the values)           run(tree, values)   + optional seed(values) => TreeNode[]
//   stack   string (the expression)         run(stack, input)   + optional mode: "stack" | "queue"
//   scalar  { name: number|string }         run(scalar)
//   scene   { nodes, edges } (seed graph)   run(scene, input)
//
// A `"scene"` (#3275) is the MULTI-STRUCTURE case: its `run(scene, input)` drives a `TracedScene`
// (`scene.graph("g", …)` / `scene.array("dist", …)` / …), and it renders as synchronized panels — the
// persisted-data twin of the in-app scene programs (`scenes.ts`). It seeds on a GraphInput (like the graph
// datatype) and every structure renderer is registered so any panel it declares resolves.
//
// `tree`, `stack` and `scalar` (#4162) close the gap where three of the six shipped renderers were
// reachable ONLY from an in-app program: `TracedTree`/`TracedStack`/`TracedScalar` and their views all
// ship, `treeAlgos.ts`/`stackAlgos.ts`/`scalarAlgos.ts` drive them, but a STORED program naming one threw
// at compile — so bst-insert, bst-inorder, balanced-parens and postfix-eval could not be authored as data
// at all. Their descriptors carry the two extra fields the in-app `TreeProgram`/`StackProgram` interfaces
// already prove are load-bearing: a tree's `seed` (build-from-empty vs walk-a-finished-tree — without it,
// an in-order traversal replays the whole build as part of the walk) and a stack's `mode` (LIFO vs FIFO).
// Both are OPTIONAL, so the simple case stays a three-field descriptor.
//
// It is self-contained (carries its own default input so the preview + "your input" field work) and does
// NOT depend on `kind` — the descriptor names its own datatype, so nothing is inferred or guessed.
//
// ISOLATION (#3233): this module is PURE (compile + run over the tracer, no DOM). It is imported by the
// dedicated Web Worker (`vizWorker.ts`) so `compileVizProgram`'s `new Function` and the algorithm's `run`
// execute in the WORKER's isolated global scope — never on the main thread, and never with DOM access. The
// main thread reaches it only through `vizSandbox.runInSandbox` (which posts to the worker); it also imports
// it directly as the inline fallback when `Worker` is unavailable (test / SSR), where trusted test code runs
// it on the main thread. A runaway program (e.g. `while(true)`) wedges only the worker, which the sandbox
// terminates on timeout — the main thread never freezes.

import {
  runAlgorithm,
  runMatrixAlgorithm,
  runGraphAlgorithm,
  runTreeAlgorithm,
  runStackAlgorithm,
  runScalarAlgorithm,
  runScene,
  withSourceLoc,
  type GraphInput,
  type StackMode,
  type TracedArray,
  type TracedMatrix,
  type TracedGraph,
  type TracedTree,
  type TracedStack,
  type TracedScalar,
  type TracedScene,
  type TreeNode,
} from "@/features/algorithms/lib/tracer";
import type { Frame } from "@/features/algorithms/lib/trace";
import { instrumentVizCode, LOC_HOOK } from "@/features/algorithms/viz/examples/vizInstrument";

/** The structure a stored trace-program drives — selects the runner, renderer(s), and input seam. One per
 *  shipped renderer (#4162): `scene` is the multi-structure case (`run(scene, input)` over a TracedScene →
 *  synchronized panels); the rest each drive their single `Traced<Structure>`. */
export type VizDatatype = "array" | "matrix" | "graph" | "tree" | "stack" | "scalar" | "scene";

/** Every datatype, as data — the single list `compileVizProgram`'s validation, the error message, and the
 *  tests all read, so adding a datatype cannot leave one of them behind. */
export const VIZ_DATATYPES: readonly VizDatatype[] = [
  "array",
  "matrix",
  "graph",
  "tree",
  "stack",
  "scalar",
  "scene",
] as const;

/** A stored program's default input, per datatype — see the DATATYPES table at the top of this file. */
export type VizInput = number[] | number[][] | GraphInput | string | Record<string, number | string>;

/** A compiled, validated stored trace-program. `run` is typed per {@link datatype} by the caller (a
 *  `(structure) => void` over the matching Traced class, or a scene's `(scene, input) => void`); `input`
 *  is the datatype's default. */
export interface VizProgramDescriptor {
  datatype: VizDatatype;
  input: VizInput;
  /** `tree` only — the nodes the tree holds BEFORE `run` (`seed(values)`). Omitted ⇒ the tree starts empty
   *  and `run` builds it. This is what separates bst-insert (builds) from bst-inorder (walks a finished
   *  tree); without it the traversal's trace would replay the whole build first. */
  seed?: (values: number[]) => TreeNode[];
  /** `stack` only — LIFO (default) or FIFO. */
  mode?: StackMode;
  /** The exact source the program's frame {@link Frame.loc} ranges index into (#3250) — the TRIMMED
   *  `vizCode`, i.e. what was parsed and instrumented. Carried on the descriptor (rather than recomputed
   *  by the caller) so the code column always renders the string the offsets were measured against. */
  source: string;
  // The compiled algorithm. Loosely typed here (never-typed params are assignable to any Traced signature,
  // and a rest tuple lets a scene's TWO-arg `run(scene, input)` fit too); `runVizProgram` narrows it to the
  // datatype's real signature (`TracedArray|TracedMatrix|TracedGraph`, or `(TracedScene, GraphInput)`).
  run: (...args: never[]) => void;
}

/** True when `v` is a finite-number array (the array-datatype default input). */
function isNumberArray(v: unknown): v is number[] {
  return Array.isArray(v) && v.every((n) => typeof n === "number" && Number.isFinite(n));
}

/** True when `v` is a rectangular-ish grid of finite numbers (the matrix-datatype default input). */
function isNumberGrid(v: unknown): v is number[][] {
  return Array.isArray(v) && v.length > 0 && v.every(isNumberArray);
}

/** True when `v` has the {@link GraphInput} shape — `nodes` + `edges` arrays (the graph-datatype input). */
function isGraphInput(v: unknown): v is GraphInput {
  if (typeof v !== "object" || v === null) return false;
  const g = v as Record<string, unknown>;
  return Array.isArray(g.nodes) && Array.isArray(g.edges);
}

/** True when `v` is a named-variable seed (the scalar-datatype input) — a plain object of numbers/strings.
 *  An EMPTY object is valid: an algorithm may set every variable it uses (`{}` is the "no parameters" seed). */
function isScalarSeed(v: unknown): v is Record<string, number | string> {
  if (typeof v !== "object" || v === null || Array.isArray(v)) return false;
  return Object.values(v as Record<string, unknown>).every(
    (x) => (typeof x === "number" && Number.isFinite(x)) || typeof x === "string",
  );
}

/** Does `input` match `datatype`'s declared shape? The gate that keeps a mismatched program from rendering
 *  an empty pane instead of failing. `tree` seeds on the VALUES (a `number[]`, like `array`) — the datatype
 *  names itself, so two structures sharing an input shape is not an ambiguity to resolve. */
function inputMatches(datatype: VizDatatype, input: unknown): boolean {
  switch (datatype) {
    case "array":
    case "tree":
      return isNumberArray(input);
    case "matrix":
      return isNumberGrid(input);
    case "graph":
    case "scene": // a scene seeds on a graph
      return isGraphInput(input);
    case "stack":
      return typeof input === "string";
    case "scalar":
      return isScalarSeed(input);
  }
}

/**
 * Compile a stored `vizCode` string into a validated {@link VizProgramDescriptor}.
 *
 * @param code the impl's `vizCode` — a JS expression evaluating to `{ datatype, input, run }`.
 * @returns the validated descriptor.
 * @throws Error with a human-readable reason when the code is empty, fails to evaluate, is not a
 *   descriptor object, names an unknown `datatype`, lacks a `run` function, or carries an `input` whose
 *   shape does not match `datatype`. Callers catch this and fall back to the in-app program.
 */
export function compileVizProgram(code: string): VizProgramDescriptor {
  const trimmed = code?.trim();
  if (!trimmed) throw new Error("vizCode is empty");

  // Tag each traced call with its source range (#3250) so the frames it emits know where they came from.
  // Pure insertion over `trimmed`, so the recorded ranges index `trimmed` — the string reported as
  // `source` and rendered by the code column. An un-instrumentable program comes back unchanged with no
  // ranges: it still compiles and animates, just without highlighting.
  const { code: instrumented, locs } = instrumentVizCode(trimmed);

  let raw: unknown;
  try {
    // Strict mode; the ONLY injected binding is the location hook, a closure we own that pushes a range
    // onto the tracer's ambient stack for the duration of one traced call. It grants the program no
    // capability it did not already have (it can neither read nor reach anything through it), so the
    // isolation note above (#3233) still holds: the program's only capability is the Traced structure.
    const hook = <T,>(id: number, call: () => T): T => withSourceLoc(locs[id], call);
    raw = new Function(LOC_HOOK, `"use strict"; return (${instrumented});`)(hook);
  } catch (e) {
    // Preserve the original SyntaxError as `cause` (assigned, not via the ES2022 constructor option —
    // the tsconfig lib target is ES2020).
    const err = new Error(`vizCode failed to compile: ${(e as Error).message}`);
    (err as Error & { cause?: unknown }).cause = e;
    throw err;
  }

  if (typeof raw !== "object" || raw === null) {
    throw new Error("vizCode must evaluate to a { datatype, input, run } object");
  }
  const d = raw as Record<string, unknown>;

  const datatype = d.datatype as VizDatatype;
  if (!VIZ_DATATYPES.includes(datatype)) {
    throw new Error(
      `vizCode.datatype must be ${VIZ_DATATYPES.map((t) => `"${t}"`).join(" | ")} (got ${JSON.stringify(d.datatype)})`,
    );
  }
  if (typeof d.run !== "function") {
    throw new Error("vizCode.run must be a function over the Traced structure");
  }

  const input = d.input;
  if (!inputMatches(datatype, input)) {
    throw new Error(`vizCode.input does not match datatype "${datatype}" (expected ${INPUT_SHAPE[datatype]})`);
  }
  // The two OPTIONAL per-datatype fields. A wrong TYPE is rejected rather than ignored: a `seed` that is
  // not a function, or a `mode` outside the two the tracer knows, is a program that does not do what its
  // author wrote — and silently dropping it would animate the wrong thing with no complaint.
  if (d.seed !== undefined && typeof d.seed !== "function") {
    throw new Error('vizCode.seed must be a function (values) => TreeNode[] — the tree\'s starting nodes');
  }
  if (d.mode !== undefined && d.mode !== "stack" && d.mode !== "queue") {
    throw new Error(`vizCode.mode must be "stack" | "queue" (got ${JSON.stringify(d.mode)})`);
  }

  return {
    datatype,
    input: input as VizInput,
    run: d.run as VizProgramDescriptor["run"],
    seed: d.seed as VizProgramDescriptor["seed"],
    mode: d.mode as StackMode | undefined,
    source: trimmed,
  };
}

/** Human-readable expected input shape per datatype, for the validation error message. */
const INPUT_SHAPE: Record<VizDatatype, string> = {
  array: "a number[]",
  matrix: "a number[][]",
  graph: "a { nodes, edges } object",
  tree: "a number[] (the values, in insertion order)",
  stack: "a string (the expression to trace)",
  scalar: "a { name: number | string } object (the initial variables)",
  scene: "a { nodes, edges } object (the scene's seed graph)",
};

/** The result of running a stored trace-program: its datatype, the input it ran on (the descriptor default
 *  or a caller override), and the recorded frame trace. Frames are plain, structured-cloneable data — so
 *  the Web Worker (#3233) posts them straight back to the main thread for replay. */
export interface VizRun {
  datatype: VizDatatype;
  input: VizInput;
  frames: Frame[];
  /** The trace-program source each frame's `loc` indexes into (#3250) — the trimmed `vizCode`. Travels
   *  back from the Worker alongside the frames so the code column and the highlights are always the same
   *  artifact; a caller must never substitute its own copy of the code. */
  source: string;
}

/**
 * Compile a stored `vizCode` and RUN it against the matching Traced structure, collecting the full frame
 * trace (#3233). Pure — this is the unit the Web Worker executes in isolation; the main thread calls it only
 * as the no-Worker fallback (tests / SSR).
 *
 * @param code the impl's `vizCode` — a `{ datatype, input, run }` descriptor expression.
 * @param inputOverride when set, runs the program on this input instead of the descriptor's default (the
 *   "your input" seam). Its shape is validated by the tracer for the descriptor's datatype.
 * @returns the datatype, the input used, and the recorded frames.
 * @throws whatever {@link compileVizProgram} throws (malformed code) or the algorithm throws at runtime.
 */
export function runVizProgram(code: string, inputOverride?: unknown): VizRun {
  const d = compileVizProgram(code);
  const input = (inputOverride ?? d.input) as VizRun["input"];
  // A caller-supplied override skipped `compileVizProgram`'s shape check, so it is validated here — the
  // "your input" seam parses text and could hand back a shape the descriptor's runner cannot accept.
  if (!inputMatches(d.datatype, input)) {
    throw new Error(`input does not match datatype "${d.datatype}" (expected ${INPUT_SHAPE[d.datatype]})`);
  }
  return { datatype: d.datatype, input, frames: [...framesFor(d, input)], source: d.source };
}

/** Run a compiled descriptor against its datatype's tracer. Split out of {@link runVizProgram} so the
 *  dispatch is one exhaustive `switch` (a new datatype fails to compile until it is handled) rather than a
 *  ternary chain whose final `else` silently absorbs anything unmatched. */
function framesFor(d: VizProgramDescriptor, input: VizRun["input"]): Generator<Frame> {
  switch (d.datatype) {
    case "array":
      return runAlgorithm(d.run as (a: TracedArray) => void, input as number[])();
    case "matrix":
      return runMatrixAlgorithm(d.run as (m: TracedMatrix) => void, input as number[][])();
    case "graph":
      return runGraphAlgorithm(d.run as (g: TracedGraph) => void, input as GraphInput)();
    case "tree": {
      // `run` takes the VALUES alongside the tree (matching the in-app `TreeProgram`): a build walks them,
      // and a traversal of a seeded tree simply ignores them.
      const values = input as number[];
      const run = d.run as unknown as (t: TracedTree, values: number[]) => void;
      return runTreeAlgorithm((t) => run(t, values), d.seed?.(values) ?? [])();
    }
    case "stack": {
      const text = input as string;
      const run = d.run as unknown as (s: TracedStack, input: string) => void;
      return runStackAlgorithm((s) => run(s, text), d.mode ?? "stack")();
    }
    case "scalar":
      return runScalarAlgorithm(
        d.run as (s: TracedScalar) => void,
        input as Record<string, number | string>,
      )();
    case "scene":
      return runScene(d.run as (scene: TracedScene, input: GraphInput) => void, input as GraphInput)();
  }
}

// The pluggable structure-renderer registry (#3176, epic #3171) — the injection point every per-structure
// renderer (#3178–#3185) plugs into WITHOUT editing the player. The player takes a `RendererRegistry`
// (a `Partial<Record<StructureName, StructureRenderer>>`) and dispatches each panel to its structure's
// renderer, or the `fallbackRenderer` when none is registered — so a missing renderer degrades, never
// crashes.
//
// A renderer for structure `S` is a React component over that structure's OWN frame type (`FrameOf<S>`),
// so a `StructureRenderer<"array">` receives an `ArrayFrame`. The registry map is typed per-key, so
// authoring is type-safe: `const registry: RendererRegistry = { array: ArrayView }`.

import type { ComponentType } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Stack } from "@/shared/ui/layout/Stack";
import { Eyebrow } from "@/shared/ui/typography/Eyebrow";
import type { FrameOf, StructureFrame, StructureName } from "@/features/algorithms/lib/trace";

/** A renderer for structure `S` — a React component over that structure's frame type (`FrameOf<S>`).
 *  Defaulting `S` to the whole union yields the erased shape the player dispatches through
 *  (a component over any `StructureFrame`), which the {@link fallbackRenderer} satisfies. */
export type StructureRenderer<S extends StructureName = StructureName> = ComponentType<{ frame: FrameOf<S> }>;

/** The injected map the player consumes — a per-structure renderer for zero or more structures. Each
 *  entry is typed to its own frame (`array` → a renderer over `ArrayFrame`). Equivalent to
 *  `Partial<Record<StructureName, StructureRenderer>>` but key-precise. The renderer issues add entries
 *  here; the player never changes. */
export type RendererRegistry = { [S in StructureName]?: StructureRenderer<S> };

/**
 * Resolve the renderer for a panel's structure — the registered one, else the {@link fallbackRenderer}.
 * The single, guarded cast site: the player looks a renderer up by the panel's OWN `structure`, so the
 * runtime frame always matches the resolved renderer's narrowed frame type even though the map's union
 * value type can't prove it statically.
 */
export function resolveRenderer(registry: RendererRegistry, structure: StructureName): StructureRenderer {
  return (registry[structure] as StructureRenderer | undefined) ?? fallbackRenderer;
}

/**
 * The default renderer for any structure with no registered renderer — prints the structure name + a
 * JSON dump of the frame. Keeps the player useful before the concrete renderers (#3178–#3185) land, and
 * makes an unregistered structure legible instead of a crash.
 */
export const fallbackRenderer: StructureRenderer = ({ frame }: { frame: StructureFrame }) => (
  <Stack gap={4} className="trace-fallback">
    <Eyebrow size={10}>{frame.structure}</Eyebrow>
    <Box as="pre" className="trace-fallback-json mono">
      {JSON.stringify(frame, null, 2)}
    </Box>
  </Stack>
);

// The vizCode SANDBOX worker (#3233) — a dedicated module Web Worker that compiles + runs a stored
// trace-program in an ISOLATED global scope (no DOM, no app state) and posts the recorded frames back.
// This is where untrusted stored `vizCode` executes, so `new Function` (in compileVizProgram) and the
// algorithm's `run` never touch the main thread. Spawned lazily by `vizSandbox.runInSandbox`.

import { runVizProgram } from "@/features/algorithms/viz/examples/vizProgram";
import type { VizWorkerRequest, VizWorkerResponse } from "@/features/algorithms/viz/examples/vizSandbox";

// `self` is the worker global. Typed loosely (a minimal shape) to avoid pulling in the TS "webworker" lib,
// which would clash with the app-wide "dom" lib (duplicate `self`/`postMessage` declarations). The message
// types are shared with the client via `import type` (erased — no runtime cycle with vizSandbox).
const ctx = self as unknown as {
  postMessage(message: VizWorkerResponse): void;
  onmessage: ((event: { data: VizWorkerRequest }) => void) | null;
};

ctx.onmessage = ({ data }) => {
  try {
    const { datatype, input, frames, source } = runVizProgram(data.code, data.input);
    ctx.postMessage({ id: data.id, ok: true, datatype, input, frames, source });
  } catch (err) {
    ctx.postMessage({ id: data.id, ok: false, error: err instanceof Error ? err.message : String(err) });
  }
};

// The warden's LLM-judge escalation (#1102, slice 3). The deterministic check (conformance.ts)
// is the hard gate — an out-of-lane edit or a gate-denied command hard-pauses immediately. But it
// can't see SEMANTIC drift: a worker that stays in its lane and runs only allowed commands yet is
// doing the wrong thing (e.g. following an injected instruction that touches nothing rule-visible).
// This module escalates a SAMPLED worker to an LLM judge — given only trusted telemetry (the plan
// anchor + the recent diff + the recent commands, never the worker-ingested prose) — for a fuzzy
// "on-task or drifted?" second opinion, off the deterministic hot path.
//
// Pure: prompt building + verdict parsing + sampling. The useWarden loop owns the llm_complete call and
// the quarantine actuation. Fail-OPEN by design — a parse failure or model wobble must NOT pause a
// legit worker (the deterministic check is the trustworthy gate); the judge only ADDS coverage.

import wardenJudgeEmbedded from "@data/fleet/warden-judge.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

export interface JudgeInput {
  streamId: string;
  /** File globs the stream owns — what it's SUPPOSED to be touching. */
  ownedGlobs: string[];
  /** Issue refs the stream owns (e.g. `#42`), for context on its assignment. */
  issues: string[];
  /** Files the worker changed (trusted: from git diff). */
  changedFiles: string[];
  /** Commands the worker ran (trusted: from the bsc-audit log). */
  commands: string[];
}

export interface JudgeVerdict {
  drifted: boolean;
  reason: string;
}

// The system prompt DATA is externalized to `@data/fleet/warden-judge.json` (#2145, epic #2027 tail) —
// editable without touching code + part of the exportable config bundle; the config-dir copy (#2047)
// overlays the embedded default via `overlayFile`. Only the literal text moved; the user-prompt BUILDER
// below stays in TS (it interpolates the runtime telemetry).
const JUDGE_SYSTEM = overlayFile("fleet/warden-judge.json", wardenJudgeEmbedded).system;

/** Build the judge prompt from trusted telemetry only. */
export function buildJudgePrompt(input: JudgeInput): { system: string; user: string } {
  const list = (xs: string[]) => (xs.length ? xs.map((x) => `  - ${x}`).join("\n") : "  (none)");
  const user =
    `Assignment\n` +
    `  stream: ${input.streamId}\n` +
    `  owns (file globs it should stay within):\n${list(input.ownedGlobs)}\n` +
    `  assigned issues:\n${list(input.issues)}\n\n` +
    `Observed activity\n` +
    `  files changed:\n${list(input.changedFiles)}\n` +
    `  commands run:\n${list(input.commands)}\n\n` +
    `Is this worker on-task for its assignment, or drifted/hijacked? Reply with the JSON object only.`;
  return { system: JUDGE_SYSTEM, user };
}

/** Parse the judge's reply. Tolerant + FAIL-OPEN: anything but a clear `"drifted": true` is
 *  treated as not-drifted, so a malformed reply never quarantines a legit worker. */
export function parseJudgeVerdict(text: string): JudgeVerdict {
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      const obj = JSON.parse(match[0]) as { drifted?: unknown; reason?: unknown };
      if (obj.drifted === true) {
        const reason = typeof obj.reason === "string" && obj.reason.trim() ? obj.reason.trim() : "off-task activity";
        return { drifted: true, reason };
      }
      return { drifted: false, reason: typeof obj.reason === "string" ? obj.reason.trim() : "" };
    } catch {
      // fall through to fail-open
    }
  }
  return { drifted: false, reason: "" };
}

/** Pick one worker to spot-check this round, round-robin, excluding already-quarantined panes.
 *  Returns null when there's nothing eligible. The loop controls HOW OFTEN this is called
 *  (judging every tick would be needlessly expensive); this only picks WHICH one. */
export function selectForJudging(
  paneIds: string[],
  cycle: number,
  skip: ReadonlySet<string>,
): string | null {
  const eligible = paneIds.filter((p) => !skip.has(p));
  if (eligible.length === 0) return null;
  return eligible[Math.abs(cycle) % eligible.length];
}

// The warden's pure decision layer (#1102). The always-on loop (useWarden) gathers each live
// worker's trusted activity (git diff + bsc-audit) and plan anchor, and this module decides who
// has drifted off-plan — by running the deterministic, non-injectable checkConformance. Kept
// pure (no IPC, no store) so the "who trips" logic is unit-tested; the loop owns the side effects
// (auto-pause + push).

import type { WorktreeChanges } from "@/shared/lib/fleet/worktreeChanges";
import { checkConformance, type StreamAnchor, type SessionActivity, type ConformanceTrip } from "@/shared/lib/fleet/conformance";

/** One live worker the warden evaluates: its pane, its trusted anchor, and what it did. */
export interface WardenSession {
  paneId: string;
  anchor: StreamAnchor;
  activity: SessionActivity;
}

/** A worker the warden decided to quarantine, with a one-line summary for the push + UI. */
export interface WardenTrip {
  paneId: string;
  streamId: string;
  trips: ConformanceTrip[];
  summary: string;
}

/** Condense trips into one human line for the quarantine banner + the mobile push body.
 *  Deterministic, derived only from trusted signals — safe to surface and to send. */
export function summarizeTrips(trips: ConformanceTrip[]): string {
  if (trips.length === 0) return "on plan";
  const part = (t: ConformanceTrip) =>
    t.kind === "out-of-glob" ? `edited out-of-lane ${t.detail}` : `ran denied \`${t.detail}\``;
  const head = part(trips[0]);
  return trips.length === 1 ? head : `${head} (+${trips.length - 1} more)`;
}

/** Decide which sessions to quarantine this pass. Skips panes already quarantined (a trip is a
 *  one-shot hard pause, not a repeating alert) and any that pass the deterministic check. */
export function planWarden(sessions: WardenSession[], alreadyQuarantined: ReadonlySet<string>): WardenTrip[] {
  const out: WardenTrip[] = [];
  for (const s of sessions) {
    if (alreadyQuarantined.has(s.paneId)) continue;
    const verdict = checkConformance(s.anchor, s.activity);
    if (!verdict.onTask) {
      out.push({
        paneId: s.paneId,
        streamId: s.anchor.streamId,
        trips: verdict.trips,
        summary: summarizeTrips(verdict.trips),
      });
    }
  }
  return out;
}

/** Extract the shell commands a pane attempted from `bsc-audit` lines (`ts \t pane \t tool \t
 *  target`). Only Bash-tool rows are commands; their `target` is the command string. `since` (epoch
 *  ms, 0 = no floor) drops rows logged BEFORE it, so a denied command from a PRIOR run can't
 *  re-quarantine a worker that triage just relaunched — `ts` is ISO-8601 (`bsc-audit` writes
 *  `date -u +%Y-%m-%dT%H:%M:%SZ`), so `Date.parse` compares cleanly; an unparseable ts is kept. Pure. */
export function parseAuditCommands(lines: string[], paneId: string, since = 0): string[] {
  const cmds: string[] = [];
  for (const line of lines) {
    const f = line.split("\t");
    if (f.length < 4) continue;
    const [ts, pane, tool, target] = f;
    if (pane !== paneId || tool.trim().toLowerCase() !== "bash" || !target.trim()) continue;
    if (since > 0) {
      const at = Date.parse(ts);
      if (Number.isFinite(at) && at < since) continue;
    }
    cmds.push(target.trim());
  }
  return cmds;
}

/**
 * Zip a batched `read_worktree_changes_batch` result back onto the panes it was requested for (#3908).
 *
 * The batch is INDEX-ALIGNED to the cwds sent, so this is the one place a fleet-wide perf fix could
 * silently corrupt the warden's evidence: a short, long, or misordered result must never attribute
 * one worker's changed files to another — that would quarantine the wrong session. A missing entry
 * degrades to "no file signal", exactly as a failed single-pane read did before batching.
 */
export function zipWorktreeChanges(
  panes: string[],
  changes: readonly (WorktreeChanges | undefined)[],
): Map<string, string[]> {
  const out = new Map<string, string[]>();
  // #3983: the LANE check reads TRACKED changes only. An untracked file has not entered the repo, is
  // not picked up by the lane's `git add`, and cannot collide at integration — which is the only harm
  // the lane exists to prevent. Merging the two lists made a `.agentscratch.txt` indistinguishable
  // from an out-of-lane source edit, and the warden killed four workers that had ZERO tracked changes
  // between them. Self-correcting rather than permissive: commit out-of-lane source and it becomes
  // tracked, and trips then — still before integration.
  panes.forEach((p, i) => out.set(p, changes[i]?.tracked ?? []));
  return out;
}

/**
 * The panes a warden sweep should actually probe (#3954): those with a RUNNING session.
 *
 * The sweep used to take the whole planned roster (`Object.keys(fleetPaneStreams)` minus completed
 * streams). That is the set of streams the PLAN defines, not the set that is running — so once the
 * resume rebuilt network-monitor's worktrees the sweep grew to 47 panes while only 3 terminals were
 * live, and each pane costs two git subprocesses. ~94 serial spawns inside one synchronous command
 * stalled the whole Tauri queue (`pty_write` measured at 3280ms, `pty_resize` at 8279ms).
 *
 * A pane with no session cannot be drifting: the warden watches what a RUNNING worker does to its
 * worktree, and there is nothing to watch when nothing is running. Liveness is the same definition
 * Glance and the launch pump use — present in a tab, and neither ended nor disabled — so all three
 * agree on "does this session exist?".
 *
 * Pure; the caller injects the store slices.
 */
export function wardenSweepTargets(
  panes: readonly string[],
  live: ReadonlySet<string>,
  completed: ReadonlySet<string>,
): string[] {
  return panes.filter((p) => live.has(p) && !completed.has(p));
}

/** The live pane set from the tab roster: in a tab, not ended, not disabled. Pure. */
export function livePaneIdsOf(
  tabs: readonly { paneIds?: string[] }[],
  ended: Record<string, unknown>,
  disabled: Record<string, unknown>,
): Set<string> {
  const out = new Set<string>();
  for (const t of tabs) for (const p of t.paneIds ?? []) {
    if (p && !ended[p] && !disabled[p]) out.add(p);
  }
  return out;
}

/**
 * Bucket K timestamp streams into per-day counts over a rolling N-day window, aligned to one label
 * axis — the shape every "activity over the last N days" chart needs.
 *
 * Two properties are the whole point, and both are easy to get wrong by hand:
 *
 * 1. **Empty days are present.** The window is built first and every stream is tallied INTO it, so a
 *    day with no events is a `0`, not a missing entry. Deriving labels from the data instead (the
 *    obvious shortcut) silently compresses quiet days out of the axis, which makes a gap look like a
 *    dip and misstates the trend.
 * 2. **The series are aligned.** Every returned series has exactly `days` entries in the same order as
 *    `labels`, so index `i` means the same day in all of them. A chart layering two series cannot check
 *    this and will happily plot them against each other misaligned.
 *
 * Days are UTC — a rolling window whose bucket boundaries move with the viewer's timezone would make
 * the same data tell two stories. Timestamps are ISO-8601; anything unparseable or outside the window
 * is dropped rather than clamped, because a bad timestamp landing on an edge day is a fabricated event.
 *
 * Harvested from the Fleet page's throughput panel (#3462/#3465).
 */

/** The day axis: display labels and the `YYYY-MM-DD` keys they bucket by, oldest → newest. */
export interface DayWindow {
  labels: string[];
  keys: string[];
}

/** The aligned result: one label axis and one equal-length numeric series per input stream. */
export interface WindowedTally<TName extends string> {
  labels: string[];
  series: Record<TName, number[]>;
}

/**
 * The last `days` UTC days ending at `now` (inclusive), oldest first.
 *
 * `days <= 0` yields an empty window rather than throwing — a caller asking for no window gets no
 * window, and every tally over it is correctly empty.
 */
export function dayWindow(days: number, now: Date): DayWindow {
  const labels: string[] = [];
  const keys: string[] = [];
  for (let i = Math.max(0, Math.floor(days)) - 1; i >= 0; i--) {
    const d = new Date(now.getTime() - i * 86_400_000);
    labels.push(`${d.getUTCMonth() + 1}/${d.getUTCDate()}`);
    keys.push(d.toISOString().slice(0, 10));
  }
  return { labels, keys };
}

/**
 * Count the timestamps falling on each day of `win`, in window order.
 *
 * Null/undefined/unparseable entries are skipped — these streams come from APIs where "not merged
 * yet" is a null timestamp, so filtering at the call site would be required of every caller.
 */
export function tallyByDay(win: DayWindow, timestamps: ReadonlyArray<string | null | undefined>): number[] {
  const index = new Map(win.keys.map((k, i) => [k, i]));
  const out = new Array<number>(win.keys.length).fill(0);
  for (const ts of timestamps) {
    if (!ts) continue;
    const at = index.get(ts.slice(0, 10));
    if (at !== undefined) out[at] += 1;
  }
  return out;
}

/**
 * Tally several named streams over ONE window, so the result is aligned by construction.
 *
 * Preferred over calling {@link tallyByDay} per stream: sharing the window is what guarantees the
 * series line up, and doing it here removes the caller's opportunity to build two windows a
 * millisecond apart and land the boundary event in different buckets.
 */
export function windowedTally<TName extends string>(
  streams: Record<TName, ReadonlyArray<string | null | undefined>>,
  days: number,
  now: Date,
): WindowedTally<TName> {
  const win = dayWindow(days, now);
  const series = {} as Record<TName, number[]>;
  for (const name of Object.keys(streams) as TName[]) {
    series[name] = tallyByDay(win, streams[name]);
  }
  return { labels: win.labels, series };
}

// Done-time per-worker audit (#920). Assembles the concrete output of a finished worker —
// what it changed (diff/commits), where it shipped (the PR), and the raw conversation
// (Claude's transcript) — by reading the worktree + GitHub at view time. Every piece is
// tolerant (the backend commands return empty/None on failure), so a partial worktree still
// renders what it can. The durable, structured record (tool/coord/decisions) is already shown
// on the worker page; this is the snapshot it was missing.

import { safeInvoke } from "@/shared/lib/core/safeInvoke";

export interface WorktreeCommit {
  hash: string;
  subject: string;
  author: string;
  date: string;
}

export interface BranchPr {
  number: number;
  url: string;
  /** OPEN | CLOSED | MERGED */
  state: string;
  merged: boolean;
}

export interface DoneAudit {
  /** Current branch of the worktree. */
  branch: string;
  /** Recent commits on the branch, newest first. */
  commits: WorktreeCommit[];
  /** Uncommitted changed files (vs HEAD + untracked). */
  changedFiles: string[];
  /** The PR opened from the branch, or null when there's none / gh is unavailable. */
  pr: BranchPr | null;
  /** Path to Claude's transcript `.jsonl`, or null when there's no history. */
  transcriptPath: string | null;
}

/**
 * Assemble the done-time audit for a worker's worktree `cwd` (and its `repo`, for the PR
 * lookup). Never rejects — each command failure degrades to an empty value.
 */
export async function loadDoneAudit(cwd: string, repo: string): Promise<DoneAudit> {
  if (!cwd) return { branch: "", commits: [], changedFiles: [], pr: null, transcriptPath: null };
  const [branch, commits, changedFiles, transcriptPath] = await Promise.all([
    safeInvoke<string>("read_worktree_branch", { cwd }, ""),
    safeInvoke<WorktreeCommit[]>("read_worktree_commits", { cwd, limit: 20 }, []),
    safeInvoke<string[]>("read_worktree_changes", { cwd }, []),
    safeInvoke<string | null>("claude_transcript_path", { cwd }, null),
  ]);
  const pr = branch && repo
    ? await safeInvoke<BranchPr | null>("find_branch_pr", { repo, branch }, null)
    : null;
  return { branch, commits, changedFiles, pr, transcriptPath };
}

// Heuristic worker auto-end decision (#1379). The authoritative `pty_exit` trigger (#920) is dead
// for stable-identity workers (#1176) and likely never fires anyway (claude returns to the bash
// prompt without the SHELL exiting). So drive auto-end heuristically off IDLE TIME, branched on
// whether the worker has an outstanding question — Claude-driven, not foolproof, by design.
//
// This is the pure brain: (idle state + outstanding-ask? + owned-issue completeness + thresholds)
// → one action. The side effects (inject the close-nudge, resurface the question, end the pane)
// live in the hook/store; keeping the decision pure makes every branch unit-testable.

import type { WorkerEndVerdict } from "@/shared/lib/fleet/workerEnd";

/** What to do for an at-rest worker this tick. */
export type AutoEndAction =
  | "none"               // still working, or not idle long enough — do nothing
  | "close-nudge"        // idle + no question + work complete → nudge it to close itself
  | "resurface-question"; // idle past the lost-question wait with an unanswered ask → resurface it

export interface AutoEndSignals {
  /** Turn still open per the #1184 activity signal — the worker is actively working (never act). */
  turnOpen: boolean;
  /** How long the worker has been at rest, ms (now − last activity). */
  idleMs: number;
  /** An unanswered `bsc-ask` is outstanding for this worker (from the coordination log). */
  hasOutstandingQuestion: boolean;
  /** The owned-issue completeness verdict (classifyWorkerEnd) — only `done` warrants a close-nudge. */
  verdict: WorkerEndVerdict;
}

export interface AutoEndThresholds {
  /** Idle before nudging a question-free, complete worker to close — SHORTER. */
  closeNudgeMs: number;
  /** Idle before treating an unanswered question as lost and resurfacing it — LONGER. */
  lostQuestionMs: number;
}

/** Defaults: a question-free worker is nudged to close after 1 min idle; an unanswered question is
 *  given 5 min before it's treated as lost. Tunable; the longer window gives the director time. */
export const DEFAULT_AUTO_END_THRESHOLDS: AutoEndThresholds = {
  closeNudgeMs: 60_000,
  lostQuestionMs: 300_000,
};

/**
 * Decide what to do for an at-rest worker.
 *
 * - Turn still open → `none` (it's working, even if silent — never act).
 * - Outstanding question → only `resurface-question` once idle ≥ the LONGER `lostQuestionMs`
 *   (give the director time to answer); otherwise `none`. Never close a worker that's waiting.
 * - No question → `close-nudge` once idle ≥ the SHORTER `closeNudgeMs` AND the owned work is
 *   genuinely complete (`verdict.state === "done"`). A `needs-attention`/`blocked` worker is NOT
 *   nudged to close — that's the director's call.
 */
export function decideWorkerAutoEnd(s: AutoEndSignals, t: AutoEndThresholds): AutoEndAction {
  if (s.turnOpen) return "none";
  if (s.hasOutstandingQuestion) {
    return s.idleMs >= t.lostQuestionMs ? "resurface-question" : "none";
  }
  if (s.idleMs >= t.closeNudgeMs && s.verdict.state === "done") return "close-nudge";
  return "none";
}

// The modal shell used by the per-agent WorkerDetail page (#499) — a titled,
// dismissable card floated over a scrim with an optional footer action row.
import { ModalScrim } from "@/shared/ui/overlay/ModalScrim";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { IconButton } from "@/shared/ui/controls/IconButton";

export function Modal({ title, children, onClose, footer }: {
  title: string; children: React.ReactNode; onClose: () => void; footer?: React.ReactNode;
}) {
  return (
    <ModalScrim onDismiss={onClose}>
      {/* The CARD is the dialog, not the scrim behind it — `aria-modal` is what marks the covered page
          inert to a screen reader. Named by its own title, which is already on screen. */}
      <Box role="dialog" aria-modal="true" aria-label={title} bg="var(--bg-panel)" border radius="lg" style={{ width: 440, maxWidth: "90vw", boxShadow: "0 12px 40px rgba(0,0,0,0.5)" }}>
        <Row style={{ padding: "12px 16px", borderBottom: "1px solid var(--border-soft)" }}>
          <Text as="h3" style={{ margin: 0 }}>{title}</Text>
          <Spacer />
          <IconButton aria-label="close" onClick={onClose} />
        </Row>
        <Box pad={16}>{children}</Box>
        {footer && <Row justify="end" align="stretch" gap={8} style={{ padding: "12px 16px", borderTop: "1px solid var(--border-soft)" }}>{footer}</Row>}
      </Box>
    </ModalScrim>
  );
}

// Shared constants + types for the per-agent WorkerDetail page (#499).

/** Permission-tier → dot color for the WorkerDetail permissions grid. */
export const TIER_COLOR: Record<string, string> = {
  allow: "var(--success)", ask: "var(--accent)", deny: "var(--danger)",
};

/** The modal states the WorkerDetail page can open. */
export type WorkerModal = "steer" | "answer" | "stop" | "profile";

// Worker completeness classifier (#920). When a fleet worker's PTY exits, we decide its
// resting state from plan.db OWNED-ISSUE STATUS — the structured, per-issue, recovery-durable
// source of truth — NOT the worker's free-text "I'm done". coord.log landed/merged is a
// tiebreaker that surfaces the "marked complete but the PR never merged" gap, but does not
// block the card: a worker's card closes on worker-finished (`complete`), while `verified` /
// merged is the director's separate confirmation, surfaced in the summary.

import { isSatisfied, parseRef, type CoordState } from "@/shared/lib/fleet/coordination";
import type { WorkerEndState } from "@/store/types";

/** One owned issue's ref + plan.db lifecycle status. */
export interface OwnedIssue {
  ref: string;
  /** open | in_progress | blocked | complete | verified | failed */
  status: string;
  /** Owning fleet stream id (#3944). Present on `bsc plan list --full` rows; lets a caller read a
   *  project's issues ONCE and partition by stream in memory instead of querying per stream. */
  stream?: string;
}

export interface WorkerEndVerdict {
  state: WorkerEndState;
  summary: string;
}

// plan.db issue lifecycle buckets (crates/plandb STATUSES).
/** The worker did its part. EXPORTED (#4050) so the progress bar counts "done" the same way the
 *  finished-verdict does — a second definition would eventually disagree with the card that says
 *  "finished", and the two would drift silently. */
export const TERMINAL_GOOD = new Set(["complete", "verified"]); // the worker did its part
const STILL_RUNNING = new Set(["open", "in_progress"]);   // stopped early
const TERMINAL_BAD = new Set(["blocked", "failed"]);      // needs attention

/**
 * Classify a finished worker from its owned issues + the coordination state.
 *
 * Precedence: any blocked/failed ⇒ `blocked`; else any still-open ⇒ `needs-attention`
 * (stopped early — never silently "done"); else all complete/verified ⇒ `done`. An empty
 * owned-issue set is `needs-attention` (we can't confirm completion from the DB).
 *
 * The `landed` count (coord.log merged/landed/closed for the owned refs) is reported in the
 * summary so "worker finished" reads distinctly from "work shipped".
 */
export function classifyWorkerEnd(issues: OwnedIssue[], coord: CoordState): WorkerEndVerdict {
  if (issues.length === 0) {
    return { state: "needs-attention", summary: "no owned issues in plan.db — can't confirm completion" };
  }

  let good = 0, running = 0, bad = 0;
  for (const i of issues) {
    if (TERMINAL_BAD.has(i.status)) bad++;
    else if (STILL_RUNNING.has(i.status)) running++;
    else if (TERMINAL_GOOD.has(i.status)) good++;
    else running++; // unknown status ⇒ treat as not-done (conservative)
  }

  const landed = issues.filter((i) => {
    const ref = parseRef(i.ref);
    return ref ? isSatisfied(coord, ref) : false;
  }).length;

  const n = issues.length;
  if (bad > 0) {
    return { state: "blocked", summary: `${bad}/${n} blocked or failed · ${good}/${n} complete` };
  }
  if (running > 0) {
    return { state: "needs-attention", summary: `stopped early — ${running}/${n} still open · ${good}/${n} complete` };
  }
  return { state: "done", summary: `${n}/${n} complete · ${landed}/${n} landed` };
}

// Build a fleet worker's scoped context markdown (#844) — the focused lane a worker
// loads as its `CLAUDE.local.md`, INSTEAD of the full planning spec. Workers used to
// inherit the hub's ~52KB planner `CLAUDE.md` (their worktrees sat under the hub, so
// Claude Code's cwd-and-ancestors `CLAUDE.md` walk picked it up); relocating worktrees
// out from under the hub removes that leak, and this gives each worker exactly the
// context it needs: the files and issues it owns, and the contracts it builds against. Pure +
// unit-tested; the Rust side (`write_worker_context`) writes it as the lead of the
// worktree's CLAUDE.local.md, ahead of the per-repo context, protocol, and skills.

import type { AgentStream } from "@/features/planner/fleet/planFleet";
import { buildWorkerDependencyBlock, type PlanDependency } from "@/features/planner/issues/dependencies";
import { COMMONS_STREAM_ID } from "@/features/planner/fleet/commonsGate";
import workerScopeEmbedded from "@data/fleet/worker-scope.json";
import { overlayFile } from "@/shared/lib/core/configOverrides";

// The fully-static prose blocks (maintenance-mode notice, the integration-interfaces paragraph, and the
// issue-lifecycle paragraph) are externalized to `@data/fleet/worker-scope.json` (#2145, epic #2027 tail)
// — editable without touching code + part of the exportable config bundle; the config-dir copy (#2047)
// overlays the embedded default via `overlayFile`. Only lines with NO interpolation moved; the heading,
// the owns/issues/deps bullets, and the repo-root-commons block stay inline (they interpolate runtime
// values / the `gatedOnCommons` flag), and the builder still assembles the whole markdown.
const SCOPE_PROSE = overlayFile("fleet/worker-scope.json", workerScopeEmbedded);

/** The project's {kit, theme} pairing (#2489) as the worker context needs it — the kit ref halves
 *  plus the chosen theme id. Sourced from plan.db's `ui` blob (`bsc plan ui get`, the planner's
 *  per-project record) falling back to the blueprint's pin. */
export interface WorkerUiPairing {
  kit?: { id: string; version: string };
  /** A `bsc ui theme` id. Absent ⇒ `"default"`. */
  themeId?: string;
}

/**
 * Fold the two pairing sources into the worker's {@link WorkerUiPairing} (#2489): plan.db's `ui`
 * blob (`bsc plan ui get` — the planner's per-project record) wins PER HALF, the project
 * blueprint's pin fills what it doesn't set (kit and/or themeId). Tolerant of the untyped blob
 * shape; `undefined` when neither source contributes anything (no block is inlined). Pure so the
 * fold is unit-testable; callers do the async reads.
 */
export function toWorkerUiPairing(
  planned: { kit?: { id?: unknown; version?: unknown } | null; themeId?: unknown } | null | undefined,
  pin?: { id: string; version: string; themeId?: string },
): WorkerUiPairing | undefined {
  const plannedKit =
    planned?.kit && typeof planned.kit.id === "string" && planned.kit.id && typeof planned.kit.version === "string" && planned.kit.version
      ? { id: planned.kit.id, version: planned.kit.version }
      : undefined;
  const kit = plannedKit ?? (pin ? { id: pin.id, version: pin.version } : undefined);
  const themeId =
    (typeof planned?.themeId === "string" && planned.themeId ? planned.themeId : undefined) ?? pin?.themeId;
  if (!kit && !themeId) return undefined;
  return { ...(kit ? { kit } : {}), ...(themeId ? { themeId } : {}) };
}

/**
 * Render the project's UI-palette pairing (#2489) as the worker-context block appended to the
 * scope — mirroring the dependencies-lock guardrail (#1111): the semantic token layer is
 * planner-owned and READ-ONLY for workers; the palette lives entirely in the swappable
 * `theme.css`. Returns "" when the project recorded no pairing (nothing to inline).
 */
export function buildWorkerUiThemeBlock(ui?: WorkerUiPairing): string {
  if (!ui || (!ui.kit && !ui.themeId)) return "";
  const theme = ui.themeId || "default";
  const kit = ui.kit ? `\`${ui.kit.id}@${ui.kit.version}\` component kit` : "component kit";
  return [
    "## UI palette (locked by the planner)",
    "",
    `This app is built on the ${kit} with the \`${theme}\` theme. Its stylesheet order is the`,
    "contract: `tokens.css` (the semantic token layer the kit components consume — `--card-*`/",
    "`--btn-*`/`--field-*`/`--chip-*`) → `theme.css` (the chosen theme's overrides — THE app's",
    "palette) → app styles. Both files are emitted into the app's styles dir by:",
    "",
    `    "$BSC_BIN" ui emit-css --theme ${theme} --out <styles dir>`,
    "",
    "**Do NOT edit `tokens.css`, and do NOT hand-roll palette values in component styles** — the",
    "token layer is read-only for you; the palette lives ENTIRELY in `theme.css`, so re-theming the",
    "app stays a one-file swap (re-run `emit-css` with another `--theme`). Components reference the",
    "semantic tokens, never raw colors. If a view genuinely needs a token the layer doesn't provide,",
    "request it from the director (`bsc-ask`) rather than adding it yourself.",
  ].join("\n");
}

/**
 * Render a stream's owned globs / issues / dependencies into the scope block that leads
 * a worker's `CLAUDE.local.md`. Kept deliberately small — the worker's job is to finish
 * its issues, not to hold the whole plan; cross-stream questions go to the director and
 * integration interfaces live in the contracts dir.
 *
 * `deps` is the LOCKED dependency manifest for this worker's repo (#1111): when present it's
 * appended as the planner-owned "Dependencies (locked)" block so the worker installs from a single
 * authority instead of adding its own (the source of parallel-worktree manifest collisions).
 *
 * `ui` is the project's recorded {kit, theme} pairing (#2489): when present it's appended as the
 * planner-owned "UI palette (locked)" block — token layer read-only, palette in theme.css.
 *
 * Returns a heading + bullet list. Empty fields are rendered as an explicit "none"/"all
 * within your owned paths" so the worker isn't left guessing whether the field was
 * omitted or genuinely empty.
 */
export function buildWorkerScope(stream: AgentStream, deps: PlanDependency[] = [], maintenance = false, ui?: WorkerUiPairing): string {
  const owns = stream.owns.length
    ? stream.owns.map((g) => `\`${g}\``).join(", ")
    : "(none assigned — confirm your lane with the director before writing)";
  const issues = stream.issues.length ? stream.issues.join(", ") : "(none yet — ask the director)";
  // The commons-landed sentinel (#851) is a Phase-0 gate, not a peer contract; surface it as the
  // commons note below rather than in the contracts line so it doesn't read as another stream's seam.
  const gatedOnCommons = stream.dependsOn.includes(COMMONS_STREAM_ID);
  const contractDeps = stream.dependsOn.filter((d) => d !== COMMONS_STREAM_ID);
  const streamDeps = contractDeps.length ? contractDeps.join(", ") : "none";

  const lines: string[] = [`# Your scope — ${stream.name}`, ""];
  if (maintenance) {
    lines.push(...SCOPE_PROSE.maintenance);
  }
  lines.push(
    "You are one of several Claude sessions building this project in parallel, working in your",
    `own git worktree on branch \`${stream.id}\`. This file is your lane — not the full plan.`,
    "",
    `- **You own:** ${owns}. Do not modify files outside your owned paths — another stream owns`,
    "  them; coordinate through the director instead of reaching in.",
    `- **Your issues:** ${issues}.`,
    `- **You build against the contracts of:** ${streamDeps}. Implement to their planned interface IN`,
    "  PARALLEL — do NOT wait for those streams to land; integration is verified at merge.",
    "",
    ...SCOPE_PROSE.integrationInterfaces,
    "**Repo-root commons belong to the `commons` lane, not to you** — `.gitignore`, `package.json`/lockfile,",
    "`tsconfig*`, `.github/workflows/**`, `.env.example`, formatter/linter config" + (gatedOnCommons ? " (already scaffolded and landed)" : "") + ". Do NOT",
    "edit them: for a new dependency, ignore entry, CI tweak, or env key, ask the director (`bsc-ask`)",
    "and pause (`bsc-wait`). The director does not apply it either — it routes the change to the commons",
    "lane, which lands it and wakes you. (The scope hook blocks the write anyway.)",
    "",
    ...SCOPE_PROSE.issueLifecycle,
  );

  const depBlock = buildWorkerDependencyBlock(deps);
  if (depBlock) lines.push("", depBlock);

  const uiBlock = buildWorkerUiThemeBlock(ui);
  if (uiBlock) lines.push("", uiBlock);

  return lines.join("\n");
}

// The wire shape of `read_worktree_changes_batch` (#3983) — kept SPLIT on purpose.
//
// `tracked` and `untracked` are not the same risk. The warden's lane check governs what enters the
// REPO, so it reads `tracked` only: an untracked scratch file cannot collide at integration, which is
// the harm the lane exists to prevent. The Fleet UI's "uncommitted changes" display wants the union.
// Returning both — rather than making the batch tracked-only — keeps one command with one meaning.
export interface WorktreeChanges {
  /** Paths git tracks that differ from HEAD (staged + unstaged). */
  tracked: string[];
  /** Paths git does not track and `.gitignore` does not cover — scratch, logs, temp output. */
  untracked: string[];
}

/** Every change, tracked or not — what a "does this worktree have uncommitted work?" view wants. */
export function allChanges(c: WorktreeChanges | undefined): string[] {
  return [...(c?.tracked ?? []), ...(c?.untracked ?? [])];
}

// worktreeReconcile (#3614) — heal the fleet split-brain at boot.
//
// The boot-GC (`fleet::teardown::gc_worktrees_impl`) reclaims a fleet worker's git worktree once its
// branch is merged + clean (the work landed) — a disk-hygiene feature. But it only deletes the DIRECTORY;
// the persisted `<project> · build` tab + its pane records survive. So on every boot the ghost tab
// mounts its panes and tries to relaunch workers into directories the app itself deleted → each spawns a
// doomed PTY → a burst of 8 jams the backend event loop → the whole app feels frozen. This module is the
// reconciliation: a worker whose worktree is gone has FINISHED (the GC only removes merged+clean), so it
// is marked ENDED (a resting card) rather than relaunched. `endedPanes` is persisted, so after one boot
// the tab renders resting workers and never thrashes again.
import type { EndedInfo } from "@/store/types/console";

/** A persisted fleet worker pane to check for a missing worktree at boot. */
export interface WorktreeCheck {
  paneId: string;
  cwd: string;
  streamId: string;
}

/** Which persisted fleet worker panes to worktree-check at boot: every pane with a fleet stream + a
 *  cwd that isn't already ended or disabled. (`paneRoles` is NOT persisted, so `fleetPaneStreams`
 *  membership is the worker filter — the same signal `useWorkerAutoEnd` uses.) Pure for testability. */
export function worktreeChecks(
  fleetPaneStreams: Record<string, { id: string } | undefined>,
  endedPanes: Record<string, unknown>,
  disabledPanes: Record<string, unknown>,
  paneCwds: Record<string, string>,
): WorktreeCheck[] {
  const checks: WorktreeCheck[] = [];
  for (const paneId of Object.keys(fleetPaneStreams)) {
    const stream = fleetPaneStreams[paneId];
    const cwd = paneCwds[paneId];
    if (!stream || !cwd || endedPanes[paneId] || disabledPanes[paneId]) continue;
    checks.push({ paneId, cwd, streamId: stream.id });
  }
  return checks;
}

/** The `EndedInfo` recorded for a worker whose worktree vanished. The boot-GC only reclaims a
 *  merged + clean worktree, so a gone worktree means the work landed → `done` (a resting card). */
export function reclaimedWorkerEnd(streamId: string, at: number): EndedInfo {
  return { state: "done", streamId, summary: "worktree reclaimed — work merged; session closed", at };
}

/**
 * For each candidate, check whether its worktree still exists; if gone (and not ended meanwhile), mark it
 * ended so it renders a resting card instead of relaunching into a deleted directory. Pure over its
 * injected deps (existence probe, ended-check, mark, clock) — the useAppBoot effect wires the real
 * `dir_exists` invoke + store. Returns the pane ids it ended (for logging/tests).
 */
export async function reconcileMissingWorktrees(
  checks: WorktreeCheck[],
  exists: (cwd: string) => Promise<boolean>,
  isEnded: (paneId: string) => boolean,
  markEnded: (paneId: string, info: EndedInfo) => void,
  now: () => number,
): Promise<string[]> {
  const ended: string[] = [];
  for (const c of checks) {
    if (await exists(c.cwd)) continue;   // worktree still there — leave the worker alone
    if (isEnded(c.paneId)) continue;      // #920 / a prior pass already ended it
    markEnded(c.paneId, reclaimedWorkerEnd(c.streamId, now()));
    ended.push(c.paneId);
  }
  return ended;
}

// Role gate (#219) — write-path scoping. Translates the role's `writeGlobs` into an anchored
// matcher and answers the two write-scope questions: may a role write a given PATH
// ({@link canWritePath}), and what is the effective write-scope boundary for a pane
// ({@link scopeWriteGlobs}, what the `bsc-scope` PreToolUse hook hard-limits to). Pure enforcement
// core, free of React / xterm / Tauri. Re-exported from `sessionRoles.ts`.

import type { RoleCapability, SessionRole } from "@/shared/lib/session/roleModel";
import { roleCapability, hasScopedWriteCarveOut } from "@/shared/lib/session/roleModel";

/**
 * The effective write-scope globs for a pane's role (#1297) — what the `bsc-scope` PreToolUse hook
 * hard-limits writes to. Uses the pane's assigned owned globs when it has them, else the role's
 * default boundary, so the planner falls back to {@link PLAN_WRITE_GLOBS} rather than being
 * overridden to `[]`. Empty ⇒ the role has no write boundary (a `code: "none"` role with no
 * carve-out, or a worker with no lane yet) and so gets no scope hook. A `code: "none"` role WITH an
 * explicit carve-out (the director's commons, #851) is scoped to exactly those globs — so the
 * scope hook hard-blocks any director write outside the commons.
 */
export function scopeWriteGlobs(role: SessionRole, ownGlobs: string[]): string[] {
  const cap = roleCapability(role, ownGlobs.length ? { writeGlobs: ownGlobs } : {});
  if (cap.code === "write") return cap.writeGlobs;
  return hasScopedWriteCarveOut(cap) ? cap.writeGlobs : [];
}

// ── Write-path scoping ──────────────────────────────────────────────────────────

/** Translate a path glob (`*` = non-slash run, `**` = any) into an anchored RegExp. */
function globToRegExp(glob: string): RegExp {
  let out = "";
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === "*") {
      if (glob[i + 1] === "*") {
        out += ".*";
        i += 1;
      } else {
        out += "[^/]*";
      }
    } else if (/[.+^${}()|[\]\\]/.test(c)) {
      out += `\\${c}`;
    } else {
      out += c;
    }
  }
  return new RegExp(`^${out}$`);
}

/** True when `path` matches `glob`. */
export function matchGlob(glob: string, path: string): boolean {
  return globToRegExp(glob).test(path);
}

/**
 * Whether a role may write `path`: it needs `code` access AND the path must fall
 * inside one of its `writeGlobs`. No globs ⇒ no boundary ⇒ no code writes (a worker
 * must be assigned its ownership boundary first).
 *
 * The one exception is the scoped carve-out (#851): a `code: "none"` role that carries explicit
 * `writeGlobs` (the director's commons) may write paths inside those globs and nothing else — the
 * carve-out grants exactly the listed paths while every other write stays denied.
 */
export function canWritePath(cap: RoleCapability, path: string): boolean {
  if (cap.code === "none" && !hasScopedWriteCarveOut(cap)) return false;
  return cap.writeGlobs.some((g) => matchGlob(g, path));
}
